// Trong môi trường thực tế, bạn sẽ import { createClient } from '@supabase/supabase-js'
// và sử dụng process.env.NEXT_PUBLIC_SUPABASE_URL và process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

// Vì đây là bản demo chạy client-side không có env thực, chúng ta tạo một Mock Client
// để mô phỏng hành vi đăng nhập và lấy dữ liệu.

import { User } from '../../types';

const MOCK_USER: User = {
  id: 'user-123',
  email: 'admin@manager.tool',
  role: 'manager',
  name: 'Nguyễn Văn Quản Lý'
};

export const supabase = {
  auth: {
    signInWithPassword: async ({ email, password }: any) => {
      // Giả lập delay mạng
      await new Promise(resolve => setTimeout(resolve, 1000));

      if (email === 'admin@manager.tool' && password === 'admin') {
        return { data: { user: MOCK_USER, session: { access_token: 'fake-token' } }, error: null };
      }
      return { data: null, error: { message: 'Thông tin đăng nhập không chính xác (Thử: admin@manager.tool / admin)' } };
    },
    signOut: async () => {
      await new Promise(resolve => setTimeout(resolve, 500));
      return { error: null };
    },
    getSession: async () => {
        const stored = localStorage.getItem('sb-session');
        return { data: { session: stored ? JSON.parse(stored) : null }, error: null };
    }
  },
  // Giả lập hàm query database
  from: (table: string) => {
    return {
      select: async () => {
        await new Promise(resolve => setTimeout(resolve, 500));
        // Trả về dữ liệu giả tùy theo bảng
        if (table === 'employees') {
          return {
            data: [
              { id: '1', fullName: 'Trần Văn A', department: 'Kỹ thuật', position: 'Kỹ sư', status: 'active', joinDate: '2023-01-15' },
              { id: '2', fullName: 'Lê Thị B', department: 'Nhân sự', position: 'Chuyên viên', status: 'active', joinDate: '2023-03-10' },
              { id: '3', fullName: 'Phạm Văn C', department: 'Kỹ thuật', position: 'Thợ máy', status: 'leave', joinDate: '2022-11-05' },
            ],
            error: null
          };
        }
        if (table === 'tools') {
            return {
                data: [
                    { id: 't1', name: 'Máy khoan Bosch', category: 'Điện', totalQuantity: 10, availableQuantity: 8, condition: 'good' },
                    { id: 't2', name: 'Bộ kìm đa năng', category: 'Cầm tay', totalQuantity: 20, availableQuantity: 15, condition: 'new' },
                    { id: 't3', name: 'Máy hàn TIG', category: 'Điện', totalQuantity: 5, availableQuantity: 1, condition: 'worn' },
                ],
                error: null
            }
        }
        if (table === 'requests') {
             return {
                data: [
                    { id: 'r1', employeeId: '1', employeeName: 'Trần Văn A', toolId: 't1', toolName: 'Máy khoan Bosch', requestDate: '2023-10-25', status: 'approved' },
                    { id: 'r2', employeeId: '3', employeeName: 'Phạm Văn C', toolId: 't2', toolName: 'Bộ kìm đa năng', requestDate: '2023-10-26', status: 'pending' },
                ], 
                error: null
             }
        }
        return { data: [], error: null };
      }
    };
  }
};

import { GoogleGenAI } from "@google/genai";

// Lấy API Key từ biến môi trường
const apiKey = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey });

export const generateManagerInsight = async (contextData: string, query: string) => {
  if (!apiKey) {
    return "Vui lòng cấu hình API_KEY để sử dụng tính năng Trợ lý AI.";
  }

  try {
    const model = "gemini-2.5-flash";
    const prompt = `
      Bạn là một trợ lý ảo chuyên nghiệp dành cho Quản lý (Manager).
      Dưới đây là dữ liệu hiện tại của hệ thống (định dạng JSON):
      ${contextData}

      Người dùng (Quản lý) hỏi: "${query}"

      Hãy phân tích dữ liệu và đưa ra câu trả lời ngắn gọn, súc tích, chuyên nghiệp bằng Tiếng Việt.
      Nếu là đề xuất hành động, hãy gạch đầu dòng rõ ràng.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Xin lỗi, hiện tại tôi không thể xử lý yêu cầu này. Vui lòng kiểm tra lại kết nối hoặc API Key.";
  }
};

