} from 'lucide-react';

interface SidebarProps {
  currentPath: string;
  onNavigate: (path: string) => void;
  onLogout: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ currentPath, onNavigate, onLogout }) => {
  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, path: '/dashboard' },
    { id: 'employees', label: 'Nhân viên', icon: Users, path: '/employees' },
    { id: 'tools', label: 'Công cụ', icon: Wrench, path: '/tools' },
    { id: 'requests', label: 'Yêu cầu mượn', icon: FileText, path: '/requests' },
    { id: 'overtime', label: 'Tăng ca', icon: Clock, path: '/overtime' },
    { id: 'orders', label: 'Đơn hàng', icon: ShoppingCart, path: '/orders' },
    { id: 'history', label: 'Lịch sử', icon: History, path: '/history' },
  ];

  return (
    <div className="w-64 bg-slate-900 text-white flex flex-col h-screen fixed left-0 top-0 overflow-y-auto">
      <div className="p-6 border-b border-slate-700 flex items-center gap-3">
        <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center font-bold">M</div>
        <span className="font-bold text-lg tracking-wide">Manager Tool</span>
      </div>

      <nav className="flex-1 p-4 space-y-1">
        {menuItems.map((item) => {
          const isActive = currentPath === item.path;
          return (
