};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        // Trong thực tế, gọi thêm getUser để lấy info chi tiết
        setUser({ name: 'Nguyễn Văn Quản Lý', role: 'manager', email: 'admin@manager.tool' });
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return <div className="h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div></div>;
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
        } />

        {/* Protected Routes */}
        <Route path="/dashboard" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/employees" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/tools" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory /></MainLayout> : <Navigate to="/login" />
        } />

        {/* Catch all / fallback */}
        <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
      </Routes>
    </HashRouter>
  );
};

