        };
      }
      return { data: null, error: { message: 'Mã nhân viên hoặc mật khẩu không đúng.' } };
    },
    signOut: async () => {
      return { error: null };
    },
    getSession: async () => {
        const stored = localStorage.getItem('sb-session');
        return { data: { session: stored ? JSON.parse(stored) : null }, error: null };
    },
    getUser: async () => {
        const stored = localStorage.getItem('sb-session');
        const session = stored ? JSON.parse(stored) : null;
        return { data: { user: session?.user || null }, error: null };
    }
  },
  from: (table: string) => {
    return {
      select: async () => {
        await new Promise(resolve => setTimeout(resolve, 300));
        if (table === 'employees') {
          return {
            data: [
              { id: '1', employeeCode: 'NV001', fullName: 'Nguyễn Văn Quản Lý', department: 'Ban Giám Đốc', position: 'Quản lý', status: 'active', joinDate: '2020-01-15' },
              { id: '3', employeeCode: 'NV003', fullName: 'Phạm Văn Kỹ Thuật', department: 'Kỹ thuật', position: 'Kỹ sư', status: 'active', joinDate: '2022-11-05' },
            ],
