                ],
                error: null
            }
        }
        if (table === 'requests') {
             return { data: [...mockRequests], error: null }
        }
        return { data: [], error: null };
      },
      insert: async (payload: any) => {
          // Giả lập insert
          await new Promise(resolve => setTimeout(resolve, 300));
          if (table === 'requests') {
              const newReq = { ...payload[0], id: `r${Date.now()}` };
              mockRequests = [newReq, ...mockRequests];
              return { data: [newReq], error: null };
          }
          return { error: 'Table not supported for mock insert' };
      },
      update: async (payload: any) => {
          // Giả lập update (thường đi kèm .eq nhưng ở đây mock đơn giản trả về object builder)
          return {
              eq: async (column: string, value: string) => {
                   if (table === 'requests' && column === 'id') {
                       mockRequests = mockRequests.map(r => r.id === value ? { ...r, ...payload } : r);
                       return { error: null };
                   }
              }
          }
      },
      delete: () => {
          return {
              eq: async (column: string, value: string) => {
                  if (table === 'requests' && column === 'id') {
                      mockRequests = mockRequests.filter(r => r.id !== value);
                      return { error: null };
                  }
              }
          }
      }
    };
  }
};

