export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [history, setHistory] = useState<BorrowRequest[]>([]);

  useEffect(() => {
    const fetchHistory = async () => {
      const { data } = await supabase.from('requests').select();
      if (data) {
        const allRequests = data as BorrowRequest[];
        // Filter: Chỉ lấy request của user hiện tại VÀ không phải pending
        // (Hoặc hiển thị tất cả status như một log lịch sử đầy đủ)
        const myHistory = allRequests.filter(req => 
            req.employeeId === user.id
        );
        // Sort theo ngày mới nhất
        myHistory.sort((a, b) => new Date(b.requestDate).getTime() - new Date(a.requestDate).getTime());
        setHistory(myHistory);
      }
    };
    fetchHistory();
  }, [user]);

  return (
    <div className="space-y-6">
