       <div className="space-y-4">
            {history.length === 0 ? (
                <p className="text-gray-500 italic">Bạn chưa có lịch sử mượn công cụ nào.</p>
            ) : (
                history.map(item => (
                    <Card key={item.id} className="flex flex-col sm:flex-row sm:items-center justify-between p-4 gap-4">
                        <div className="flex items-start gap-4">
                            <div className={`mt-1 w-2 h-12 rounded-full ${
                                item.status === 'approved' ? 'bg-green-500' :
                                item.status === 'rejected' ? 'bg-red-500' :
                                'bg-yellow-500'
                            }`}></div>
                            <div>
                                <h4 className="font-bold text-gray-800">{item.toolName}</h4>
                                <div className="flex items-center gap-2 text-sm text-gray-500 mt-1">
                                    <Calendar className="w-3.5 h-3.5" />
                                    <span>{item.requestDate}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-4">
                            <div className="text-right">
                                <span className="block text-xs text-gray-500 uppercase tracking-wider mb-1">Trạng thái</span>
                                <span className={`font-semibold text-sm ${
                                    item.status === 'approved' ? 'text-green-600' :
                                    item.status === 'rejected' ? 'text-red-600' :
                                    'text-yellow-600'
                                }`}>
                                    {item.status === 'approved' ? 'Đã được duyệt' : 
                                     item.status === 'rejected' ? 'Bị từ chối' : 'Đang chờ duyệt'}
                                </span>
                            </div>
                        </div>
                    </Card>
                ))
            )}
       </div>
    </div>
  );
};

