import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { Wrench, PlusCircle, CheckCircle, MapPin, AlertCircle } from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  useEffect(() => {
    const fetchTools = async () => {
      // Query bảng 'tools'
      const { data, error } = await supabase.from('tools').select('*');
      if (data) setTools(data as Tool[]);
      if (error) console.error(error);
    };
    fetchTools();
  }, []);

  const handleBorrow = async (tool: Tool) => {
    setProcessingId(tool.id);
    setMessage(null);

    // Insert vào bảng 'requests'
    const { error } = await supabase.from('requests').insert([{
      employee_id: user.employeeCode, // Mã nhân viên (text)
      user_id: user.id,               // UUID của user
      user_name: user.name,
      tool_id: tool.id,
      tool_name: tool.name,
      borrow_date: new Date().toISOString(), // Dùng borrow_date thay vì requestDate
      status: 'pending'
    }]);

    if (!error) {
       setMessage(`Đã gửi yêu cầu mượn: ${tool.name}`);
       setTimeout(() => setMessage(null), 3000);
    } else {
       console.error(error);
       alert('Có lỗi xảy ra khi gửi yêu cầu.');
    }
    setProcessingId(null);
  };

  return (
    <div className="space-y-6 relative">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Kho công cụ</h2>
        {message && (
          <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce">
            <CheckCircle className="w-4 h-4" />
            {message}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {tools.map((tool) => (
          <Card key={tool.id} className="hover:shadow-md transition-shadow relative overflow-hidden group flex flex-col">
            <div className="flex justify-between items-start mb-4">
              <div className="p-2 bg-blue-50 rounded-lg text-2xl">
                {tool.image || <Wrench className="w-6 h-6 text-blue-600" />}
              </div>
              <span className={`text-xs px-2 py-1 rounded font-medium ${
                tool.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'
              }`}>
                {tool.status === 'active' ? 'Hoạt động' : 'Ngưng dùng'}
              </span>
            </div>

            <h3 className="text-lg font-bold text-gray-900 mb-1">{tool.name}</h3>
            <p className="text-sm text-gray-500 mb-2">{tool.category}</p>

            {tool.description && (
                <p className="text-xs text-gray-400 mb-4 line-clamp-2 flex-grow">{tool.description}</p>
            )}

            {tool.location && (
                <div className="flex items-center gap-1 text-xs text-gray-500 mb-4 bg-gray-50 p-1.5 rounded w-fit">
                    <MapPin className="w-3 h-3" />
                    {tool.location}
                </div>
            )}

            <div className="flex justify-between items-center text-sm border-t pt-4 text-gray-600 mb-2 mt-auto">
              <span>Tổng: <strong>{tool.quantity}</strong></span>
              <span>Sẵn có: <strong className={`${tool.available > 0 ? 'text-blue-600' : 'text-red-500'}`}>{tool.available}</strong></span>
            </div>

            {/* Nút mượn */}
            {tool.status === 'active' && tool.available > 0 ? (
                <button 
                  onClick={() => handleBorrow(tool)}
                  disabled={processingId === tool.id}
                  className="w-full mt-2 bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white py-2 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                >
                  {processingId === tool.id ? 'Đang xử lý...' : (
                    <>
                      <PlusCircle className="w-4 h-4" />
                      Yêu cầu mượn
                    </>
                  )}
                </button>
            ) : (
                <button disabled className="w-full mt-2 bg-gray-100 text-gray-400 py-2 rounded-lg font-medium cursor-not-allowed flex items-center justify-center gap-2">
                    <AlertCircle className="w-4 h-4" />
                    {tool.status !== 'active' ? 'Ngưng hoạt động' : 'Hết hàng'}
                </button>
            )}
          </Card>
        ))}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchRequests = async () => {
    let query = supabase.from('requests').select('*').order('borrow_date', { ascending: false });

    // Nếu là user thường, chỉ thấy request của mình (dựa vào user_id UUID)
    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) {
      setRequests(data as BorrowRequest[]);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchRequests();
  }, [user]);

  const handleStatusChange = async (id: string, newStatus: 'approved' | 'rejected') => {
    const updateData: any = { 
        status: newStatus,
        // Cập nhật người duyệt/từ chối và thời gian
        [newStatus === 'approved' ? 'approved_at' : 'rejected_at']: new Date().toISOString(),
        [newStatus === 'approved' ? 'approved_by' : 'rejected_by']: user.employeeCode
    };

    await supabase.from('requests').update(updateData).eq('id', id);
    fetchRequests(); 
  };

  const handleCancel = async (id: string) => {
    if (window.confirm('Bạn có chắc chắn muốn hủy yêu cầu này?')) {
      await supabase.from('requests').delete().eq('id', id);
      fetchRequests();
    }
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu Mượn</h2>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs">
              <tr>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Ngày yêu cầu</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={5} className="p-6 text-center">Đang tải...</td></tr>
              ) : requests.length === 0 ? (
                <tr><td colSpan={5} className="p-6 text-center text-gray-500">Chưa có yêu cầu nào.</td></tr>
              ) : (
                requests.map((req) => (
                  <tr key={req.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                        <div className="font-medium text-gray-900">{req.user_name}</div>
                        <div className="text-xs text-gray-400">{req.employee_id}</div>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-800">{req.tool_name}</td>
                    <td className="px-6 py-4">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ${
                        req.status === 'approved' ? 'bg-green-100 text-green-800' :
                        req.status === 'rejected' ? 'bg-red-100 text-red-800' :
                        req.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' ? 'Đã duyệt' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      {/* Logic cho Admin: Duyệt / Từ chối */}
                      {user.role === 'admin' && req.status === 'pending' && (
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => handleStatusChange(req.id, 'approved')}
                            className="p-1.5 bg-green-100 text-green-600 rounded hover:bg-green-200" title="Duyệt">
                            <Check className="w-4 h-4" />
                          </button>
                          <button 
                             onClick={() => handleStatusChange(req.id, 'rejected')}
                             className="p-1.5 bg-red-100 text-red-600 rounded hover:bg-red-200" title="Từ chối">
                            <X className="w-4 h-4" />
                          </button>
                        </div>
                      )}

                      {/* Logic cho User: Hủy yêu cầu của chính mình nếu đang chờ */}
                      {user.role !== 'admin' && req.user_id === user.id && req.status === 'pending' && (
                        <button 
                          onClick={() => handleCancel(req.id)}
                          className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded-lg hover:bg-red-50 transition-colors"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                          Hủy yêu cầu
                        </button>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

