                      : 'bg-gray-100/90 text-gray-500'
                  }`}>
                    {tool.status === 'active' ? 'Hoạt động' : 'Ngưng dùng'}
                  </span>
                </div>
              </div>

              {/* Phần thông tin */}
              <div className="flex-1 flex flex-col">
                <h3 className="text-lg font-bold text-gray-900 mb-1 line-clamp-1" title={tool.name}>{tool.name}</h3>
                <p className="text-sm text-blue-600 font-medium mb-2">{tool.category}</p>

                {tool.description && (
                    <p className="text-xs text-gray-500 mb-3 line-clamp-2 flex-grow">{tool.description}</p>
                )}

                {tool.location && (
                    <div className="flex items-center gap-1 text-xs text-gray-500 mb-3 bg-gray-50 p-1.5 rounded w-fit border border-gray-100">
                        <MapPin className="w-3 h-3" />
                        {tool.location}
                    </div>
                )}

                <div className="flex justify-between items-center text-sm border-t border-gray-100 pt-3 text-gray-600 mt-auto">
                  <span>Tổng kho: <strong>{tool.quantity}</strong></span>
                  <span>Sẵn có: <strong className={`${tool.available > 0 ? 'text-blue-600' : 'text-red-500'}`}>{tool.available}</strong></span>
                </div>
              </div>

              {/* Nút thao tác */}
              {tool.status === 'active' && tool.available > 0 ? (
                  <button 
                    onClick={() => handleBorrow(tool)}
                    disabled={processingId === tool.id}
                    className="w-full mt-4 bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white py-2.5 rounded-lg font-medium transition-colors flex items-center justify-center gap-2"
                  >
                    {processingId === tool.id ? 'Đang xử lý...' : (
                      <>
                        <PlusCircle className="w-4 h-4" />
                        Yêu cầu mượn
                      </>
                    )}
                  </button>
              ) : (
                  <button disabled className="w-full mt-4 bg-gray-100 text-gray-400 py-2.5 rounded-lg font-medium cursor-not-allowed flex items-center justify-center gap-2">
                      <AlertCircle className="w-4 h-4" />
                      {tool.status !== 'active' ? 'Ngưng hoạt động' : 'Hết hàng'}
                  </button>
              )}
            </Card>
          );
        })}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Employee } from '../../../types';
import { Card } from '../ui/Card';
import { Search, Plus, User as UserIcon, X, Save, Edit2 } from 'lucide-react';

export const EmployeeList: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  // State cho chức năng sửa
  const [isEditing, setIsEditing] = useState(false);
  const [editingUser, setEditingUser] = useState<Employee | null>(null);
  const [formData, setFormData] = useState({ name: '', role: 'employee' });

  useEffect(() => {
    const fetchEmployees = async () => {
      const { data, error } = await supabase.from('users').select('*').order('created_at', { ascending: false });
      if (data) setEmployees(data as Employee[]);
      if (error) console.error(error);
      setLoading(false);
    };
    fetchEmployees();
  }, []);

  const handleEdit = (employee: Employee) => {
    setEditingUser(employee);
    setFormData({ name: employee.name, role: employee.role });
    setIsEditing(true);
  };

  const handleSave = async () => {
    if (!editingUser) return;

    try {
      const { error } = await supabase
        .from('users')
        .update({ name: formData.name, role: formData.role })
        .eq('id', editingUser.id);

      if (error) throw error;

      // Cập nhật state local
      setEmployees(employees.map(e => 
        e.id === editingUser.id ? { ...e, name: formData.name, role: formData.role } : e
      ));

      setIsEditing(false);
      setEditingUser(null);
    } catch (error: any) {
      alert('Lỗi cập nhật: ' + error.message);
    }
  };

  return (
    <div className="space-y-6 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Danh sách tài khoản</h2>
        <button className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors">
          <Plus className="w-4 h-4" />
          Thêm tài khoản
        </button>
      </div>

      <Card className="p-0 overflow-hidden">
        {/* Toolbar */}
        <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row gap-4 bg-gray-50">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
              type="text" 
              placeholder="Tìm kiếm..." 
              className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
            />
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs">
              <tr>
                <th className="px-6 py-4">Mã NV</th>
                <th className="px-6 py-4">Họ và tên</th>
                <th className="px-6 py-4">Vai trò</th>
                <th className="px-6 py-4">Ngày tạo</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-gray-500">Đang tải dữ liệu...</td>
                </tr>
              ) : (
                employees.map((emp) => (
                  <tr key={emp.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 font-mono font-medium text-blue-600">{emp.employee_id}</td>
                    <td className="px-6 py-4 font-medium text-gray-900 flex items-center gap-2">
                        <div className="w-6 h-6 bg-gray-200 rounded-full flex items-center justify-center">
                            <UserIcon className="w-3 h-3 text-gray-500"/>
                        </div>
                        {emp.name}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium uppercase ${
                        emp.role === 'admin' ? 'bg-purple-100 text-purple-800' : 'bg-gray-100 text-gray-800'
                      }`}>
                        {emp.role}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-gray-400 text-xs">
                        {new Date(emp.created_at).toLocaleDateString('vi-VN')}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => handleEdit(emp)}
                        className="text-blue-600 hover:text-blue-800 font-medium inline-flex items-center gap-1 hover:underline"
                      >
                        <Edit2 className="w-3 h-3" /> Sửa
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* Edit Modal */}
      {isEditing && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md animate-fade-in-up">
            <div className="flex justify-between items-center p-6 border-b">
              <h3 className="text-lg font-bold text-gray-900">Chỉnh sửa thông tin</h3>
              <button onClick={() => setIsEditing(false)} className="text-gray-400 hover:text-gray-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Mã nhân viên (Không thể sửa)</label>
                <input 
                  type="text" 
                  value={editingUser?.employee_id} 
                  disabled 
                  className="w-full px-3 py-2 bg-gray-100 border border-gray-300 rounded-lg text-gray-500 text-sm"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Họ và tên</label>
                <input 
                  type="text" 
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all text-sm"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Vai trò</label>
                <select 
                  value={formData.role}
                  onChange={(e) => setFormData({...formData, role: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm"
                >
                  <option value="admin">Admin (Quản trị viên)</option>
                  <option value="manager">Manager (Quản lý)</option>
                  <option value="employee">Employee (Nhân viên)</option>
                  <option value="user">User (Người dùng)</option>
                </select>
              </div>
            </div>

            <div className="p-6 border-t bg-gray-50 rounded-b-xl flex justify-end gap-3">
              <button 
                onClick={() => setIsEditing(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleSave}
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 flex items-center gap-2"
              >
                <Save className="w-4 h-4" />
                Lưu thay đổi
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { Wrench, PlusCircle, CheckCircle, MapPin, AlertCircle, Trash2, Edit, Plus, X, Save, Image as ImageIcon } from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  // State cho Admin CRUD
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
    if (error) console.error(error);
  };

  // --- Logic Mượn (Giữ nguyên) ---
  const handleBorrow = async (tool: Tool) => {
    setProcessingId(tool.id);
    setMessage(null);

    const { error } = await supabase.from('requests').insert([{
      employee_id: user.employeeCode,
      user_id: user.id,
      user_name: user.name,
      tool_id: tool.id,
      tool_name: tool.name,
      borrow_date: new Date().toISOString(),
      status: 'pending'
    }]);

    if (!error) {
       setMessage(`Đã gửi yêu cầu mượn: ${tool.name}`);
       setTimeout(() => setMessage(null), 3000);
    } else {
       console.error(error);
       alert('Có lỗi xảy ra khi gửi yêu cầu.');
    }
    setProcessingId(null);
  };

  // --- Logic Admin CRUD ---
  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleDeleteTool = async (id: string) => {
    if (!window.confirm('Bạn có chắc chắn muốn xóa công cụ này?')) return;

    try {
      const { error } = await supabase.from('tools').delete().eq('id', id);
      if (error) throw error;
      setTools(tools.filter(t => t.id !== id));
      setMessage('Đã xóa công cụ thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    }
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');

      // Logic cơ bản: Nếu tăng số lượng tổng, available cũng tăng tương ứng (đơn giản hóa)
      const payload = { ...formData };

      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }

      await fetchTools(); // Refresh list
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  return (
    <div className="space-y-6 relative">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Kho công cụ</h2>
        <div className="flex items-center gap-3">
            {message && (
            <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce">
                <CheckCircle className="w-4 h-4" />
                {message}
            </div>
            )}
            {isAdmin && (
                <button 
                    onClick={handleAddNew}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-md"
                >
                    <Plus className="w-4 h-4" />
                    Thêm công cụ
                </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {tools.map((tool) => {
          const isImageUrl = tool.image?.match(/^(http|https|data:)/);

          return (
            <Card key={tool.id} className="hover:shadow-lg transition-shadow relative overflow-hidden group flex flex-col h-full border-gray-200 p-0">

              {/* Phần hiển thị hình ảnh - Đã chỉnh lại kích thước */}
              <div className="h-40 bg-gray-50 flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                {isImageUrl ? (
                  <img 
                    src={tool.image} 
                    alt={tool.name} 
                    className="w-full h-full object-contain p-2 transition-transform duration-500 group-hover:scale-105"
                  />
                ) : (
                  <div className="flex flex-col items-center justify-center text-gray-300">
                    <Wrench className="w-12 h-12 mb-2" />
                    <span className="text-xs">No Image</span>
                  </div>
                )}

                {/* Badge trạng thái */}
                <div className="absolute top-2 right-2">
                  <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold shadow-sm backdrop-blur-md border ${
                    tool.status === 'active' 
                      ? 'bg-green-100/90 text-green-700 border-green-200' 
                      : 'bg-red-100/90 text-red-600 border-red-200'
                  }`}>
                    {tool.status === 'active' ? 'Sẵn sàng' : 'Ngưng dùng'}
                  </span>
                </div>

                {/* Nút Admin Edit/Delete nổi lên khi hover */}
                {isAdmin && (
                    <div className="absolute top-2 left-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                        <button onClick={() => handleEditTool(tool)} className="p-1.5 bg-white text-blue-600 rounded-md shadow-md hover:bg-blue-50" title="Sửa">
                            <Edit className="w-3.5 h-3.5" />
                        </button>
                        <button onClick={() => handleDeleteTool(tool.id)} className="p-1.5 bg-white text-red-600 rounded-md shadow-md hover:bg-red-50" title="Xóa">
                            <Trash2 className="w-3.5 h-3.5" />
                        </button>
                    </div>
                )}
              </div>

              {/* Phần thông tin */}
              <div className="flex-1 flex flex-col p-4">
                <div className="mb-2">
                    <h3 className="text-base font-bold text-gray-900 line-clamp-1" title={tool.name}>{tool.name}</h3>
                    <p className="text-xs text-blue-600 font-medium">{tool.category}</p>
                </div>

                {/* Thông tin phụ gọn hơn */}
                <div className="space-y-1 mb-3">
                    {tool.description && (
                        <p className="text-xs text-gray-500 line-clamp-2 min-h-[2.5em]">{tool.description}</p>
                    )}
                    {tool.location && (
                        <div className="flex items-center gap-1 text-xs text-gray-400">
                            <MapPin className="w-3 h-3" />
                            {tool.location}
                        </div>
                    )}
                </div>

                <div className="flex justify-between items-center text-xs border-t border-gray-100 pt-3 text-gray-600 mt-auto">
                  <span className="bg-gray-100 px-2 py-1 rounded">Kho: {tool.quantity}</span>
                  <span className={`font-bold px-2 py-1 rounded ${tool.available > 0 ? 'bg-blue-50 text-blue-700' : 'bg-red-50 text-red-600'}`}>
                    Sẵn: {tool.available}
                  </span>
                </div>

                {/* Nút thao tác */}
                <div className="mt-3">
                    {tool.status === 'active' && tool.available > 0 ? (
                        <button 
                            onClick={() => handleBorrow(tool)}
                            disabled={processingId === tool.id}
                            className="w-full bg-blue-600 text-white hover:bg-blue-700 py-2 rounded-md text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 shadow-sm"
                        >
                            {processingId === tool.id ? 'Đang xử lý...' : (
                            <>
                                <PlusCircle className="w-3.5 h-3.5" />
                                Mượn dụng cụ
                            </>
                            )}
                        </button>
                    ) : (
                        <button disabled className="w-full bg-gray-100 text-gray-400 py-2 rounded-md text-xs font-semibold cursor-not-allowed flex items-center justify-center gap-1.5">
                            <AlertCircle className="w-3.5 h-3.5" />
                            Hết hàng / Ngưng
                        </button>
                    )}
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      {/* MODAL THÊM / SỬA CÔNG CỤ */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="flex justify-between items-center p-5 border-b">
              <h3 className="text-lg font-bold text-gray-900">{isEditing ? 'Cập nhật công cụ' : 'Thêm công cụ mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
              {/* Tên & Danh mục */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tên công cụ <span className="text-red-500">*</span></label>
                    <input 
                      type="text" 
                      value={formData.name}
                      onChange={(e) => setFormData({...formData, name: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      placeholder="VD: Khoan Bosch"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Danh mục</label>
                    <input 
                      type="text" 
                      value={formData.category}
                      onChange={(e) => setFormData({...formData, category: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
              </div>

              {/* Số lượng */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tổng số lượng</label>
                    <input 
                      type="number" 
                      min="0"
                      value={formData.quantity}
                      onChange={(e) => setFormData({...formData, quantity: parseInt(e.target.value) || 0})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Sẵn có</label>
                    <input 
                      type="number"
                      min="0"
                      value={formData.available}
                      onChange={(e) => setFormData({...formData, available: parseInt(e.target.value) || 0})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
              </div>

              {/* Hình ảnh */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">URL Hình ảnh</label>
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <ImageIcon className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
                        <input 
                        type="text" 
                        value={formData.image}
                        onChange={(e) => setFormData({...formData, image: e.target.value})}
                        className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                        placeholder="https://example.com/image.jpg"
                        />
                    </div>
                </div>
                {formData.image && (
                    <div className="mt-2 h-20 w-20 border rounded-lg overflow-hidden bg-gray-50">
                        <img src={formData.image} alt="Preview" className="w-full h-full object-cover" />
                    </div>
                )}
              </div>

              {/* Vị trí & Trạng thái */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Vị trí kho</label>
                    <input 
                      type="text" 
                      value={formData.location}
                      onChange={(e) => setFormData({...formData, location: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      placeholder="Kệ A, Tầng 2"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Trạng thái</label>
                    <select 
                      value={formData.status}
