              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { Wrench, PlusCircle, CheckCircle, MapPin, AlertCircle, Trash2, Edit, Plus, X, Save, Image as ImageIcon, LayoutGrid, List, ChevronLeft, ChevronRight } from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ITEMS_PER_PAGE = 20;

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);

  // State cho Admin CRUD
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); // Reset về trang 1 khi load lại dữ liệu
    }
    if (error) console.error(error);
  };

  // --- Logic Phân trang ---
  const totalPages = Math.ceil(tools.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentTools = tools.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
    }
  };

  // --- Logic Mượn (Giữ nguyên) ---
  const handleBorrow = async (tool: Tool) => {
    setProcessingId(tool.id);
    setMessage(null);

    const { error } = await supabase.from('requests').insert([{
      employee_id: user.employeeCode,
      user_id: user.id,
      user_name: user.name,
      tool_id: tool.id,
      tool_name: tool.name,
      borrow_date: new Date().toISOString(),
      status: 'pending'
    }]);

    if (!error) {
       setMessage(`Đã gửi yêu cầu mượn: ${tool.name}`);
       setTimeout(() => setMessage(null), 3000);
    } else {
       console.error(error);
       alert('Có lỗi xảy ra khi gửi yêu cầu.');
    }
    setProcessingId(null);
  };

  // --- Logic Admin CRUD ---
  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleDeleteTool = async (id: string) => {
    if (!window.confirm('Bạn có chắc chắn muốn xóa công cụ này?')) return;

    try {
      const { error } = await supabase.from('tools').delete().eq('id', id);
      if (error) throw error;
      const newTools = tools.filter(t => t.id !== id);
      setTools(newTools);

      // Nếu xóa hết item ở trang hiện tại, lùi về trang trước
      if (currentPage > Math.ceil(newTools.length / ITEMS_PER_PAGE)) {
        setCurrentPage(Math.max(1, currentPage - 1));
      }

      setMessage('Đã xóa công cụ thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    }
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');

      // Logic cơ bản: Nếu tăng số lượng tổng, available cũng tăng tương ứng (đơn giản hóa)
      const payload = { ...formData };

      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }

      await fetchTools(); // Refresh list
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)]">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800">Kho công cụ</h2>
            <p className="text-sm text-gray-500 mt-1">Tổng cộng: {tools.length} thiết bị</p>
        </div>

        <div className="flex flex-col sm:flex-row items-center gap-3 w-full sm:w-auto">
            {message && (
            <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce text-sm">
                <CheckCircle className="w-4 h-4" />
                {message}
            </div>
            )}

            <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-gray-200 shadow-sm">
              <button 
                onClick={() => setViewMode('grid')}
                className={`p-2 rounded-md transition-all ${viewMode === 'grid' ? 'bg-blue-50 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                title="Dạng lưới"
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setViewMode('table')}
                className={`p-2 rounded-md transition-all ${viewMode === 'table' ? 'bg-blue-50 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                title="Dạng bảng"
              >
                <List className="w-4 h-4" />
              </button>
            </div>

            {isAdmin && (
                <button 
                    onClick={handleAddNew}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-md w-full sm:w-auto justify-center"
                >
                    <Plus className="w-4 h-4" />
                    Thêm công cụ
                </button>
            )}
        </div>
      </div>

      <div className="flex-1">
        {/* VIEW MODE: GRID */}
        {viewMode === 'grid' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const isImageUrl = tool.image?.match(/^(http|https|data:)/);

                return (
                <Card key={tool.id} className="hover:shadow-lg transition-shadow relative overflow-hidden group flex flex-col h-full border-gray-200 p-0">

                    {/* Phần hiển thị hình ảnh */}
                    <div className="h-40 bg-gray-50 flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                    {isImageUrl ? (
                        <img 
                        src={tool.image} 
                        alt={tool.name} 
                        className="w-full h-full object-contain p-2 transition-transform duration-500 group-hover:scale-105"
                        />
                    ) : (
                        <div className="flex flex-col items-center justify-center text-gray-300">
                        <Wrench className="w-12 h-12 mb-2" />
                        <span className="text-xs">No Image</span>
                        </div>
                    )}

                    {/* Badge trạng thái */}
                    <div className="absolute top-2 right-2">
                        <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold shadow-sm backdrop-blur-md border ${
                        tool.status === 'active' 
                            ? 'bg-green-100/90 text-green-700 border-green-200' 
                            : 'bg-red-100/90 text-red-600 border-red-200'
                        }`}>
                        {tool.status === 'active' ? 'Sẵn sàng' : 'Ngưng dùng'}
                        </span>
                    </div>

                    {/* Nút Admin Edit/Delete nổi lên khi hover */}
                    {isAdmin && (
                        <div className="absolute top-2 left-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                            <button onClick={() => handleEditTool(tool)} className="p-1.5 bg-white text-blue-600 rounded-md shadow-md hover:bg-blue-50" title="Sửa">
                                <Edit className="w-3.5 h-3.5" />
                            </button>
                            <button onClick={() => handleDeleteTool(tool.id)} className="p-1.5 bg-white text-red-600 rounded-md shadow-md hover:bg-red-50" title="Xóa">
                                <Trash2 className="w-3.5 h-3.5" />
                            </button>
                        </div>
                    )}
                    </div>

                    {/* Phần thông tin */}
                    <div className="flex-1 flex flex-col p-4">
                    <div className="mb-2">
                        <h3 className="text-base font-bold text-gray-900 line-clamp-1" title={tool.name}>{tool.name}</h3>
                        <p className="text-xs text-blue-600 font-medium">{tool.category}</p>
                    </div>

                    {/* Thông tin phụ gọn hơn */}
                    <div className="space-y-1 mb-3">
                        {tool.description && (
                            <p className="text-xs text-gray-500 line-clamp-2 min-h-[2.5em]">{tool.description}</p>
                        )}
                        {tool.location && (
                            <div className="flex items-center gap-1 text-xs text-gray-400">
                                <MapPin className="w-3 h-3" />
                                {tool.location}
                            </div>
                        )}
                    </div>

                    <div className="flex justify-between items-center text-xs border-t border-gray-100 pt-3 text-gray-600 mt-auto">
                        <span className="bg-gray-100 px-2 py-1 rounded">Kho: {tool.quantity}</span>
                        <span className={`font-bold px-2 py-1 rounded ${tool.available > 0 ? 'bg-blue-50 text-blue-700' : 'bg-red-50 text-red-600'}`}>
                        Sẵn: {tool.available}
                        </span>
                    </div>

                    {/* Nút thao tác */}
                    <div className="mt-3">
                        {tool.status === 'active' && tool.available > 0 ? (
                            <button 
                                onClick={() => handleBorrow(tool)}
                                disabled={processingId === tool.id}
                                className="w-full bg-blue-600 text-white hover:bg-blue-700 py-2 rounded-md text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 shadow-sm"
                            >
                                {processingId === tool.id ? 'Đang xử lý...' : (
                                <>
                                    <PlusCircle className="w-3.5 h-3.5" />
                                    Mượn dụng cụ
                                </>
                                )}
                            </button>
                        ) : (
                            <button disabled className="w-full bg-gray-100 text-gray-400 py-2 rounded-md text-xs font-semibold cursor-not-allowed flex items-center justify-center gap-1.5">
                                <AlertCircle className="w-3.5 h-3.5" />
                                Hết hàng / Ngưng
                            </button>
                        )}
                    </div>
                    </div>
                </Card>
                );
            })}
            </div>
        )}

        {/* VIEW MODE: TABLE */}
        {viewMode === 'table' && (
            <Card className="p-0 overflow-hidden">
            <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-gray-600">
                <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs">
                    <tr>
                    <th className="px-6 py-4 w-20">Hình ảnh</th>
                    <th className="px-6 py-4">Tên công cụ</th>
                    <th className="px-6 py-4">Danh mục</th>
                    <th className="px-6 py-4 text-center">Tồn kho / Sẵn có</th>
                    <th className="px-6 py-4">Vị trí</th>
                    <th className="px-6 py-4">Trạng thái</th>
                    <th className="px-6 py-4 text-right">Thao tác</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 bg-white">
                    {currentTools.map((tool) => {
                    const isImageUrl = tool.image?.match(/^(http|https|data:)/);
                    return (
                        <tr key={tool.id} className="hover:bg-gray-50 transition-colors group">
                        <td className="px-6 py-3">
                            <div className="w-12 h-12 rounded-lg bg-gray-50 border border-gray-200 flex items-center justify-center overflow-hidden">
                            {isImageUrl ? (
                                <img src={tool.image} alt={tool.name} className="w-full h-full object-contain" />
                            ) : (
                                <Wrench className="w-5 h-5 text-gray-300" />
                            )}
                            </div>
                        </td>
                        <td className="px-6 py-3">
                            <div className="font-medium text-gray-900">{tool.name}</div>
                            {tool.description && <div className="text-xs text-gray-400 line-clamp-1 max-w-[200px]">{tool.description}</div>}
                        </td>
                        <td className="px-6 py-3">
                            <span className="text-gray-500">{tool.category}</span>
                        </td>
                        <td className="px-6 py-3 text-center">
                            <div className="flex flex-col items-center">
                            <span className="text-xs text-gray-400">Tổng: {tool.quantity}</span>
                            <span className={`font-bold ${tool.available > 0 ? 'text-blue-600' : 'text-red-500'}`}>
                                Sẵn: {tool.available}
                            </span>
                            </div>
                        </td>
                        <td className="px-6 py-3">
                            <div className="flex items-center gap-1 text-gray-500">
                                {tool.location ? (
                                    <>
                                        <MapPin className="w-3.5 h-3.5" />
                                        {tool.location}
                                    </>
                                ) : '-'}
                            </div>
                        </td>
                        <td className="px-6 py-3">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                tool.status === 'active' 
                                ? 'bg-green-100 text-green-800' 
                                : 'bg-red-100 text-red-800'
                            }`}>
                                {tool.status === 'active' ? 'Hoạt động' : 'Ngưng dùng'}
                            </span>
                        </td>
                        <td className="px-6 py-3 text-right">
                            <div className="flex items-center justify-end gap-2">
                            {/* Action Buttons for User (Borrow) */}
                            {tool.status === 'active' && tool.available > 0 && (
                                <button
                                onClick={() => handleBorrow(tool)}
                                disabled={processingId === tool.id}
                                className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-md hover:bg-blue-100 text-xs font-medium flex items-center gap-1 transition-colors"
                                >
                                {processingId === tool.id ? '...' : <PlusCircle className="w-3.5 h-3.5" />}
                                Mượn
                                </button>
                            )}

                            {/* Action Buttons for Admin (Edit/Delete) */}
                            {isAdmin && (
                                <>
                                    <button 
                                        onClick={() => handleEditTool(tool)}
                                        className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors"
                                        title="Sửa"
                                    >
                                        <Edit className="w-4 h-4" />
                                    </button>
                                    <button 
                                        onClick={() => handleDeleteTool(tool.id)}
                                        className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors"
                                        title="Xóa"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </>
                            )}
                            </div>
                        </td>
                        </tr>
                    );
                    })}
                </tbody>
                </table>
            </div>
            </Card>
        )}
      </div>

      {/* PAGINATION CONTROLS */}
      {tools.length > 0 && (
        <div className="flex items-center justify-between border-t border-gray-200 pt-4 mt-auto">
            <div className="text-sm text-gray-500 hidden sm:block">
                Hiển thị <span className="font-medium">{Math.min(startIndex + 1, tools.length)}</span> đến <span className="font-medium">{Math.min(startIndex + ITEMS_PER_PAGE, tools.length)}</span> trong số <span className="font-medium">{tools.length}</span> công cụ
            </div>
            <div className="flex items-center gap-2 mx-auto sm:mx-0">
                <button
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 border border-gray-300 rounded-md bg-white text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                    <ChevronLeft className="w-4 h-4" />
                </button>

                {/* Page Numbers */}
                <div className="flex items-center gap-1">
                    {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                        <button
                            key={page}
                            onClick={() => handlePageChange(page)}
                            className={`w-8 h-8 flex items-center justify-center rounded-md text-sm font-medium transition-colors ${
                                currentPage === page
                                    ? 'bg-blue-600 text-white border border-blue-600'
                                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                            }`}
                        >
                            {page}
                        </button>
                    ))}
                </div>

                <button
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 border border-gray-300 rounded-md bg-white text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                    <ChevronRight className="w-4 h-4" />
                </button>
            </div>
        </div>
      )}

      {/* MODAL THÊM / SỬA CÔNG CỤ */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="flex justify-between items-center p-5 border-b">
              <h3 className="text-lg font-bold text-gray-900">{isEditing ? 'Cập nhật công cụ' : 'Thêm công cụ mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
              {/* Tên & Danh mục */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tên công cụ <span className="text-red-500">*</span></label>
                    <input 
                      type="text" 
                      value={formData.name}
                      onChange={(e) => setFormData({...formData, name: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      placeholder="VD: Khoan Bosch"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Danh mục</label>
                    <input 
                      type="text" 
                      value={formData.category}
                      onChange={(e) => setFormData({...formData, category: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
              </div>

              {/* Số lượng */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tổng số lượng</label>
                    <input 
                      type="number" 
                      min="0"
                      value={formData.quantity}
                      onChange={(e) => setFormData({...formData, quantity: parseInt(e.target.value) || 0})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Sẵn có</label>
                    <input 
                      type="number"
                      min="0"
                      value={formData.available}
                      onChange={(e) => setFormData({...formData, available: parseInt(e.target.value) || 0})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
              </div>

              {/* Hình ảnh */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">URL Hình ảnh</label>
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <ImageIcon className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
                        <input 
                        type="text" 
                        value={formData.image}
                        onChange={(e) => setFormData({...formData, image: e.target.value})}
                        className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                        placeholder="https://example.com/image.jpg"
                        />
                    </div>
                </div>
                {formData.image && (
                    <div className="mt-2 h-20 w-20 border rounded-lg overflow-hidden bg-gray-50">
                        <img src={formData.image} alt="Preview" className="w-full h-full object-cover" />
                    </div>
                )}
              </div>

              {/* Vị trí & Trạng thái */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Vị trí kho</label>
                    <input 
                      type="text" 
                      value={formData.location}
                      onChange={(e) => setFormData({...formData, location: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      placeholder="Kệ A, Tầng 2"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Trạng thái</label>
                    <select 
                      value={formData.status}
                      onChange={(e) => setFormData({...formData, status: e.target.value as 'active' | 'inactive'})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    >
                        <option value="active">Hoạt động</option>
                        <option value="inactive">Ngưng sử dụng</option>
                    </select>
                  </div>
              </div>

              {/* Mô tả */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Mô tả chi tiết</label>
                <textarea 
                  value={formData.description}
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                  placeholder="Thông số kỹ thuật, ghi chú..."
                />
              </div>
            </div>

            <div className="p-5 border-t bg-gray-50 rounded-b-xl flex justify-end gap-3">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleSaveTool}
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-sm transition-colors"
              >
                <Save className="w-4 h-4" />
                {isEditing ? 'Lưu thay đổi' : 'Tạo mới'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { Wrench, PlusCircle, CheckCircle, MapPin, AlertCircle, Trash2, Edit, Plus, X, Save, Image as ImageIcon, LayoutGrid, List, ChevronLeft, ChevronRight } from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ITEMS_PER_PAGE = 20;

// Sub-component để xử lý hiển thị ảnh tối ưu
const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  // Reset error state khi src thay đổi
  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-100 text-gray-300 w-full h-full ${className}`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2' : 'w-5 h-5'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && (
        <div className="absolute inset-0 bg-gray-50 animate-pulse" />
      )}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-all duration-500 ${loaded ? 'opacity-100 scale-100' : 'opacity-0 scale-95'} ${mode === 'grid' ? 'p-4 group-hover:scale-110' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);

  // State cho Admin CRUD
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); // Reset về trang 1 khi load lại dữ liệu
    }
    if (error) console.error(error);
  };

  // --- Logic Phân trang ---
  const totalPages = Math.ceil(tools.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentTools = tools.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
    }
  };

  // --- Logic Mượn (Giữ nguyên) ---
  const handleBorrow = async (tool: Tool) => {
    setProcessingId(tool.id);
    setMessage(null);

    const { error } = await supabase.from('requests').insert([{
      employee_id: user.employeeCode,
      user_id: user.id,
      user_name: user.name,
      tool_id: tool.id,
      tool_name: tool.name,
      borrow_date: new Date().toISOString(),
      status: 'pending'
    }]);

    if (!error) {
       setMessage(`Đã gửi yêu cầu mượn: ${tool.name}`);
       setTimeout(() => setMessage(null), 3000);
    } else {
       console.error(error);
       alert('Có lỗi xảy ra khi gửi yêu cầu.');
    }
    setProcessingId(null);
  };

  // --- Logic Admin CRUD ---
  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleDeleteTool = async (id: string) => {
    if (!window.confirm('Bạn có chắc chắn muốn xóa công cụ này?')) return;

    try {
      const { error } = await supabase.from('tools').delete().eq('id', id);
      if (error) throw error;
      const newTools = tools.filter(t => t.id !== id);
      setTools(newTools);

      // Nếu xóa hết item ở trang hiện tại, lùi về trang trước
      if (currentPage > Math.ceil(newTools.length / ITEMS_PER_PAGE)) {
        setCurrentPage(Math.max(1, currentPage - 1));
      }

      setMessage('Đã xóa công cụ thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    }
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');

      // Logic cơ bản: Nếu tăng số lượng tổng, available cũng tăng tương ứng (đơn giản hóa)
      const payload = { ...formData };

      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }

      await fetchTools(); // Refresh list
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)]">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800">Kho công cụ</h2>
            <p className="text-sm text-gray-500 mt-1">Tổng cộng: {tools.length} thiết bị</p>
        </div>

        <div className="flex flex-col sm:flex-row items-center gap-3 w-full sm:w-auto">
            {message && (
            <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce text-sm">
                <CheckCircle className="w-4 h-4" />
                {message}
            </div>
            )}

            <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-gray-200 shadow-sm">
              <button 
                onClick={() => setViewMode('grid')}
                className={`p-2 rounded-md transition-all ${viewMode === 'grid' ? 'bg-blue-50 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                title="Dạng lưới"
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setViewMode('table')}
                className={`p-2 rounded-md transition-all ${viewMode === 'table' ? 'bg-blue-50 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                title="Dạng bảng"
              >
                <List className="w-4 h-4" />
              </button>
            </div>

            {isAdmin && (
                <button 
                    onClick={handleAddNew}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-md w-full sm:w-auto justify-center"
                >
                    <Plus className="w-4 h-4" />
                    Thêm công cụ
                </button>
            )}
        </div>
      </div>

      <div className="flex-1">
        {/* VIEW MODE: GRID */}
        {viewMode === 'grid' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                return (
                <Card key={tool.id} className="hover:shadow-lg transition-shadow relative overflow-hidden group flex flex-col h-full border-gray-200 p-0">

                    {/* Phần hiển thị hình ảnh */}
                    <div className="h-48 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />

                      {/* Badge trạng thái */}
                      <div className="absolute top-2 right-2 z-10">
                          <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold shadow-sm backdrop-blur-md border ${
                          tool.status === 'active' 
                              ? 'bg-green-100/90 text-green-700 border-green-200' 
                              : 'bg-red-100/90 text-red-600 border-red-200'
                          }`}>
                          {tool.status === 'active' ? 'Sẵn sàng' : 'Ngưng dùng'}
                          </span>
                      </div>

                      {/* Nút Admin Edit/Delete nổi lên khi hover */}
                      {isAdmin && (
                          <div className="absolute top-2 left-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200 z-10">
                              <button onClick={() => handleEditTool(tool)} className="p-1.5 bg-white text-blue-600 rounded-md shadow-md hover:bg-blue-50 border border-gray-100" title="Sửa">
                                  <Edit className="w-3.5 h-3.5" />
                              </button>
                              <button onClick={() => handleDeleteTool(tool.id)} className="p-1.5 bg-white text-red-600 rounded-md shadow-md hover:bg-red-50 border border-gray-100" title="Xóa">
                                  <Trash2 className="w-3.5 h-3.5" />
                              </button>
                          </div>
                      )}
                    </div>

                    {/* Phần thông tin */}
                    <div className="flex-1 flex flex-col p-4">
                    <div className="mb-2">
                        <h3 className="text-base font-bold text-gray-900 line-clamp-1" title={tool.name}>{tool.name}</h3>
                        <p className="text-xs text-blue-600 font-medium">{tool.category}</p>
                    </div>

                    {/* Thông tin phụ gọn hơn */}
                    <div className="space-y-1 mb-3">
                        {tool.description && (
                            <p className="text-xs text-gray-500 line-clamp-2 min-h-[2.5em]">{tool.description}</p>
                        )}
                        {tool.location && (
                            <div className="flex items-center gap-1 text-xs text-gray-400">
                                <MapPin className="w-3 h-3" />
                                {tool.location}
                            </div>
                        )}
                    </div>

                    <div className="flex justify-between items-center text-xs border-t border-gray-100 pt-3 text-gray-600 mt-auto">
                        <span className="bg-gray-100 px-2 py-1 rounded">Kho: {tool.quantity}</span>
                        <span className={`font-bold px-2 py-1 rounded ${tool.available > 0 ? 'bg-blue-50 text-blue-700' : 'bg-red-50 text-red-600'}`}>
                        Sẵn: {tool.available}
                        </span>
                    </div>

                    {/* Nút thao tác */}
                    <div className="mt-3">
                        {tool.status === 'active' && tool.available > 0 ? (
                            <button 
                                onClick={() => handleBorrow(tool)}
                                disabled={processingId === tool.id}
                                className="w-full bg-blue-600 text-white hover:bg-blue-700 py-2 rounded-md text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 shadow-sm"
                            >
                                {processingId === tool.id ? 'Đang xử lý...' : (
                                <>
                                    <PlusCircle className="w-3.5 h-3.5" />
                                    Mượn dụng cụ
                                </>
                                )}
                            </button>
                        ) : (
                            <button disabled className="w-full bg-gray-100 text-gray-400 py-2 rounded-md text-xs font-semibold cursor-not-allowed flex items-center justify-center gap-1.5">
                                <AlertCircle className="w-3.5 h-3.5" />
                                Hết hàng / Ngưng
                            </button>
                        )}
                    </div>
                    </div>
                </Card>
                );
            })}
            </div>
        )}

        {/* VIEW MODE: TABLE */}
        {viewMode === 'table' && (
            <Card className="p-0 overflow-hidden">
            <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-gray-600">
                <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs">
                    <tr>
                    <th className="px-6 py-4 w-24">Hình ảnh</th>
                    <th className="px-6 py-4">Tên công cụ</th>
                    <th className="px-6 py-4">Danh mục</th>
                    <th className="px-6 py-4 text-center">Tồn kho / Sẵn có</th>
                    <th className="px-6 py-4">Vị trí</th>
                    <th className="px-6 py-4">Trạng thái</th>
                    <th className="px-6 py-4 text-right">Thao tác</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 bg-white">
                    {currentTools.map((tool) => {
                    return (
                        <tr key={tool.id} className="hover:bg-gray-50 transition-colors group">
                        <td className="px-6 py-3">
                            <div className="w-12 h-12 rounded-lg bg-white border border-gray-200 flex items-center justify-center overflow-hidden shadow-sm">
                              <ToolThumbnail src={tool.image} alt={tool.name} mode="table" />
                            </div>
                        </td>
                        <td className="px-6 py-3">
                            <div className="font-medium text-gray-900">{tool.name}</div>
                            {tool.description && <div className="text-xs text-gray-400 line-clamp-1 max-w-[200px]">{tool.description}</div>}
                        </td>
                        <td className="px-6 py-3">
                            <span className="text-gray-500">{tool.category}</span>
                        </td>
                        <td className="px-6 py-3 text-center">
                            <div className="flex flex-col items-center">
                            <span className="text-xs text-gray-400">Tổng: {tool.quantity}</span>
                            <span className={`font-bold ${tool.available > 0 ? 'text-blue-600' : 'text-red-500'}`}>
                                Sẵn: {tool.available}
                            </span>
                            </div>
                        </td>
                        <td className="px-6 py-3">
                            <div className="flex items-center gap-1 text-gray-500">
                                {tool.location ? (
                                    <>
                                        <MapPin className="w-3.5 h-3.5" />
                                        {tool.location}
                                    </>
                                ) : '-'}
                            </div>
                        </td>
                        <td className="px-6 py-3">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                tool.status === 'active' 
                                ? 'bg-green-100 text-green-800' 
                                : 'bg-red-100 text-red-800'
                            }`}>
                                {tool.status === 'active' ? 'Hoạt động' : 'Ngưng dùng'}
                            </span>
                        </td>
                        <td className="px-6 py-3 text-right">
                            <div className="flex items-center justify-end gap-2">
                            {/* Action Buttons for User (Borrow) */}
                            {tool.status === 'active' && tool.available > 0 && (
                                <button
                                onClick={() => handleBorrow(tool)}
                                disabled={processingId === tool.id}
                                className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-md hover:bg-blue-100 text-xs font-medium flex items-center gap-1 transition-colors"
                                >
                                {processingId === tool.id ? '...' : <PlusCircle className="w-3.5 h-3.5" />}
                                Mượn
                                </button>
                            )}

                            {/* Action Buttons for Admin (Edit/Delete) */}
                            {isAdmin && (
                                <>
                                    <button 
                                        onClick={() => handleEditTool(tool)}
                                        className="p-1.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors"
                                        title="Sửa"
                                    >
                                        <Edit className="w-4 h-4" />
                                    </button>
                                    <button 
                                        onClick={() => handleDeleteTool(tool.id)}
                                        className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors"
                                        title="Xóa"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </>
                            )}
                            </div>
                        </td>
                        </tr>
                    );
                    })}
                </tbody>
                </table>
            </div>
            </Card>
        )}
      </div>

      {/* PAGINATION CONTROLS */}
      {tools.length > 0 && (
        <div className="flex items-center justify-between border-t border-gray-200 pt-4 mt-auto">
            <div className="text-sm text-gray-500 hidden sm:block">
                Hiển thị <span className="font-medium">{Math.min(startIndex + 1, tools.length)}</span> đến <span className="font-medium">{Math.min(startIndex + ITEMS_PER_PAGE, tools.length)}</span> trong số <span className="font-medium">{tools.length}</span> công cụ
            </div>
            <div className="flex items-center gap-2 mx-auto sm:mx-0">
                <button
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 border border-gray-300 rounded-md bg-white text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                    <ChevronLeft className="w-4 h-4" />
                </button>

                {/* Page Numbers */}
                <div className="flex items-center gap-1">
                    {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                        <button
                            key={page}
                            onClick={() => handlePageChange(page)}
                            className={`w-8 h-8 flex items-center justify-center rounded-md text-sm font-medium transition-colors ${
                                currentPage === page
                                    ? 'bg-blue-600 text-white border border-blue-600'
                                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                            }`}
                        >
                            {page}
                        </button>
                    ))}
                </div>

                <button
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 border border-gray-300 rounded-md bg-white text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                    <ChevronRight className="w-4 h-4" />
                </button>
            </div>
        </div>
      )}

      {/* MODAL THÊM / SỬA CÔNG CỤ */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="flex justify-between items-center p-5 border-b">
              <h3 className="text-lg font-bold text-gray-900">{isEditing ? 'Cập nhật công cụ' : 'Thêm công cụ mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4 overflow-y-auto custom-scrollbar">
              {/* Tên & Danh mục */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tên công cụ <span className="text-red-500">*</span></label>
                    <input 
                      type="text" 
                      value={formData.name}
                      onChange={(e) => setFormData({...formData, name: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      placeholder="VD: Khoan Bosch"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Danh mục</label>
                    <input 
                      type="text" 
                      value={formData.category}
                      onChange={(e) => setFormData({...formData, category: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
              </div>

              {/* Số lượng */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tổng số lượng</label>
                    <input 
                      type="number" 
                      min="0"
                      value={formData.quantity}
                      onChange={(e) => setFormData({...formData, quantity: parseInt(e.target.value) || 0})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Sẵn có</label>
                    <input 
                      type="number"
                      min="0"
                      value={formData.available}
                      onChange={(e) => setFormData({...formData, available: parseInt(e.target.value) || 0})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                    />
                  </div>
              </div>

              {/* Hình ảnh */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">URL Hình ảnh</label>
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <ImageIcon className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
                        <input 
                        type="text" 
                        value={formData.image}
                        onChange={(e) => setFormData({...formData, image: e.target.value})}
                        className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                        placeholder="https://example.com/image.jpg"
                        />
                    </div>
                </div>
                {formData.image && (
                    <div className="mt-2 h-40 w-full border rounded-lg overflow-hidden bg-gray-50 flex items-center justify-center">
                        <ToolThumbnail src={formData.image} alt="Preview" mode="grid" />
                    </div>
                )}
              </div>

              {/* Vị trí & Trạng thái */}
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Vị trí kho</label>
                    <input 
                      type="text" 
                      value={formData.location}
                      onChange={(e) => setFormData({...formData, location: e.target.value})}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                      placeholder="Kệ A, Tầng 2"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Trạng thái</label>
                    <select 
                      value={formData.status}
                      onChange={(e) => setFormData({...formData, status: e.target.value as 'active' | 'inactive'})}
