// Component an toàn để bọc biểu đồ, đảm bảo kích thước luôn > 0 trước khi render
const SafeChartContainer = ({ children, height = 300 }: { children: React.ReactNode, height?: number }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [shouldRender, setShouldRender] = useState(false);

  useEffect(() => {
    // Hàm kiểm tra kích thước
    const checkDimensions = () => {
      if (containerRef.current) {
        const { offsetWidth, offsetHeight } = containerRef.current;
        // Chỉ render khi container thực sự có kích thước
        if (offsetWidth > 0 && offsetHeight > 0) {
          setShouldRender(true);
        }
      }
    };

    // Kiểm tra ngay lập tức
    checkDimensions();

    // Sử dụng ResizeObserver để theo dõi thay đổi kích thước container
    const observer = new ResizeObserver(() => {
      checkDimensions();
    });

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    // Fallback: Kiểm tra lại sau 100ms để đảm bảo layout đã ổn định
    const timer = setTimeout(checkDimensions, 100);

    return () => {
      observer.disconnect();
      clearTimeout(timer);
    };
  }, []);

  return (
    <div ref={containerRef} style={{ width: '100%', height: height, minWidth: 0, position: 'relative' }}>
      {shouldRender ? (
        // Sử dụng 99% width để tránh lỗi làm tròn pixel trong một số layout grid
        <ResponsiveContainer width="99%" height="100%" debounce={50}>
          {children as React.ReactElement}
        </ResponsiveContainer>
      ) : (
        <div className="w-full h-full flex items-center justify-center bg-gray-50 rounded animate-pulse">
          <span className="text-gray-400 text-sm">Đang tải dữ liệu biểu đồ...</span>
        </div>
      )}
    </div>
  );
};

