export const DashboardStats: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalEmployees: 0,
    totalToolsAvailable: 0,
    pendingRequests: 0,
    inactiveTools: 0
  });
  const [barData, setBarData] = useState<any[]>([]);
  const [pieData, setPieData] = useState<any[]>([]);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      // 1. Fetch Stats Counts
      const [usersRes, toolsRes, requestsRes] = await Promise.all([
        supabase.from('users').select('id', { count: 'exact' }),
        supabase.from('tools').select('id, available, status, quantity'),
        supabase.from('requests').select('id, status, borrow_date')
      ]);

      // Tính toán số liệu tổng quan
      const totalEmployees = usersRes.count || 0;

      const tools = toolsRes.data || [];
      // Tổng số lượng available (tính tổng các số, không phải đếm dòng)
      const totalToolsAvailable = tools.reduce((sum, tool) => sum + (tool.status === 'active' ? tool.available : 0), 0);
      const inactiveTools = tools.filter(t => t.status === 'inactive').length;

      const requests = requestsRes.data || [];
      const pendingRequests = requests.filter(r => r.status === 'pending').length;

      setStats({
        totalEmployees,
        totalToolsAvailable,
        pendingRequests,
        inactiveTools
      });

      // 2. Process Pie Chart Data (Tình trạng công cụ)
      const activeHasStock = tools.filter(t => t.status === 'active' && t.available > 0).length;
      const activeNoStock = tools.filter(t => t.status === 'active' && t.available === 0).length;

      setPieData([
        { name: 'Sẵn sàng', value: activeHasStock },
        { name: 'Hết hàng', value: activeNoStock },
        { name: 'Ngưng dùng', value: inactiveTools },
      ]);

      // 3. Process Bar Chart Data (Yêu cầu 7 ngày gần nhất)
      const last7Days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        return {
            dateStr: d.toLocaleDateString('vi-VN'), // 24/10/2023
            dayName: d.toLocaleDateString('vi-VN', { weekday: 'short' }), // T2, T3...
            fullDate: d.toISOString().split('T')[0] // 2023-10-24 used for matching
        };
      });

      const chartData = last7Days.map(day => {
        const count = requests.filter(r => r.borrow_date.startsWith(day.fullDate)).length;
        return {
            name: day.dayName,
            fullDate: day.dateStr,
            requests: count
        };
      });

      setBarData(chartData);

    } catch (error) {
      console.error("Error fetching dashboard data:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
        <div className="flex h-96 items-center justify-center">
            <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
        </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card className="flex items-center gap-4 border-l-4 border-l-blue-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-blue-100 rounded-full text-blue-600">
            <Users className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Tổng nhân viên</p>
            <p className="text-2xl font-bold text-gray-800">{stats.totalEmployees}</p>
          </div>
        </Card>

        <Card className="flex items-center gap-4 border-l-4 border-l-green-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-green-100 rounded-full text-green-600">
            <Wrench className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Công cụ sẵn có</p>
            <p className="text-2xl font-bold text-gray-800">{stats.totalToolsAvailable}</p>
          </div>
        </Card>

        <Card className="flex items-center gap-4 border-l-4 border-l-yellow-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-yellow-100 rounded-full text-yellow-600">
            <TrendingUp className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Yêu cầu chờ duyệt</p>
            <p className="text-2xl font-bold text-gray-800">{stats.pendingRequests}</p>
          </div>
        </Card>

        <Card className="flex items-center gap-4 border-l-4 border-l-red-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-red-100 rounded-full text-red-600">
            <AlertCircle className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Ngưng hoạt động</p>
            <p className="text-2xl font-bold text-gray-800">{stats.inactiveTools}</p>
          </div>
        </Card>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card title="Yêu cầu mượn (7 ngày qua)" className="min-w-0">
          <SafeChartContainer height={300}>
            <BarChart data={barData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="name" axisLine={false} tickLine={false} />
              <YAxis axisLine={false} tickLine={false} allowDecimals={false} />
              <Tooltip 
                cursor={{fill: '#f3f4f6'}}
                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                labelStyle={{ fontWeight: 'bold', color: '#374151' }}
              />
              <Bar dataKey="requests" name="Số yêu cầu" fill="#3b82f6" radius={[4, 4, 0, 0]} />
            </BarChart>
          </SafeChartContainer>
        </Card>

        <Card title="Tình trạng danh mục đầu công cụ" className="min-w-0">
          <SafeChartContainer height={300}>
            <PieChart>
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
                nameKey="name"
              >
                {pieData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
              <text x="50%" y="50%" textAnchor="middle" dominantBaseline="middle" className="text-gray-400 text-sm font-medium">
                Tổng: {stats.totalToolsAvailable + stats.inactiveTools}
              </text>
            </PieChart>
          </SafeChartContainer>
          <div className="flex justify-center gap-4 mt-4">
              {pieData.map((entry, index) => (
                  <div key={index} className="flex items-center gap-1.5 text-xs text-gray-600">
