        <Card title="Tình trạng phân bổ tài sản" className="min-w-0">
          <SafeChartContainer height={300}>
            <PieChart>
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
