                {stats.totalToolsQuantity} Item
              </text>
            </PieChart>
          </SafeChartContainer>
          <div className="flex justify-center gap-4 mt-4 flex-wrap">
              {pieData.map((entry, index) => (
                  <div key={index} className="flex items-center gap-1.5 text-xs text-gray-600">
                      <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                      {entry.name} ({entry.value})
                  </div>
              ))}
          </div>
        </Card>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2 } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchRequests = async () => {
    let query = supabase.from('requests').select('*').order('borrow_date', { ascending: false });

    // Nếu là user thường, chỉ thấy request của mình (dựa vào user_id UUID)
    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) {
      setRequests(data as BorrowRequest[]);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchRequests();
  }, [user]);

  // Xử lý Phê duyệt hoặc Từ chối
  const handleStatusChange = async (id: string, newStatus: 'approved' | 'rejected') => {
    const confirmMsg = newStatus === 'approved' ? 'Phê duyệt yêu cầu mượn này?' : 'Từ chối yêu cầu này?';
    if (!window.confirm(confirmMsg)) return;

    const updateData: any = { 
        status: newStatus,
        // Cập nhật người duyệt/từ chối và thời gian
        [newStatus === 'approved' ? 'approved_at' : 'rejected_at']: new Date().toISOString(),
        [newStatus === 'approved' ? 'approved_by' : 'rejected_by']: user.employeeCode
    };

    await supabase.from('requests').update(updateData).eq('id', id);
    fetchRequests(); 
  };

  // Xử lý Trả lại công cụ (Chỉ dành cho Admin khi status là approved)
  const handleReturnTool = async (id: string, toolName: string) => {
    if (!window.confirm(`Xác nhận nhân viên đã trả lại công cụ: ${toolName}?`)) return;

    const { error } = await supabase.from('requests').update({
        status: 'returned',
        returned_at: new Date().toISOString()
    }).eq('id', id);

    if (error) {
        alert('Có lỗi xảy ra: ' + error.message);
    } else {
        fetchRequests();
    }
  };

  // Xử lý Hủy yêu cầu (Dành cho User khi status là pending)
  const handleCancel = async (id: string) => {
    if (window.confirm('Bạn có chắc chắn muốn hủy yêu cầu này?')) {
      await supabase.from('requests').delete().eq('id', id);
      fetchRequests();
    }
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu Mượn</h2>

      <Card className="p-0 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs">
              <tr>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Ngày yêu cầu</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={5} className="p-6 text-center">Đang tải...</td></tr>
              ) : requests.length === 0 ? (
                <tr><td colSpan={5} className="p-6 text-center text-gray-500">Chưa có yêu cầu nào.</td></tr>
              ) : (
                requests.map((req) => (
                  <tr key={req.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                        <div className="font-medium text-gray-900">{req.user_name}</div>
                        <div className="text-xs text-gray-400">{req.employee_id}</div>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-800">{req.tool_name}</td>
                    <td className="px-6 py-4">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ${
                        req.status === 'approved' ? 'bg-green-100 text-green-800' :
                        req.status === 'rejected' ? 'bg-red-100 text-red-800' :
                        req.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-blue-100 text-blue-800'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <Clock className="w-3 h-3" />}
                         {req.status === 'returned' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      {/* --- KHU VỰC ADMIN --- */}
                      {user.role === 'admin' && (
                        <div className="flex justify-end gap-2">
                            {/* Nút cho trạng thái Chờ duyệt */}
                            {req.status === 'pending' && (
                                <>
                                    <button 
                                        onClick={() => handleStatusChange(req.id, 'approved')}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-green-50 text-green-600 rounded-md hover:bg-green-100 border border-green-200 transition-colors text-xs font-medium" 
                                        title="Phê duyệt"
                                    >
                                        <Check className="w-3.5 h-3.5" /> Duyệt
                                    </button>
                                    <button 
                                        onClick={() => handleStatusChange(req.id, 'rejected')}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-red-50 text-red-600 rounded-md hover:bg-red-100 border border-red-200 transition-colors text-xs font-medium" 
                                        title="Từ chối"
                                    >
                                        <X className="w-3.5 h-3.5" /> Huỷ
                                    </button>
                                </>
                            )}

                            {/* Nút cho trạng thái Đang mượn -> Trả lại */}
                            {req.status === 'approved' && (
                                <button
                                    onClick={() => handleReturnTool(req.id, req.tool_name)}
                                    className="flex items-center gap-1 px-3 py-1.5 bg-blue-50 text-blue-700 rounded-md hover:bg-blue-100 border border-blue-200 transition-colors text-xs font-medium"
                                    title="Xác nhận đã trả"
                                >
                                    <RotateCcw className="w-3.5 h-3.5" />
                                    Đã trả lại
                                </button>
                            )}

                            {/* Trạng thái đã kết thúc */}
                            {(req.status === 'returned' || req.status === 'rejected') && (
                                <span className="text-xs text-gray-400 italic">Hoàn tất</span>
                            )}
                        </div>
                      )}

                      {/* --- KHU VỰC USER THƯỜNG --- */}
                      {user.role !== 'admin' && (
                        <>
                            {req.user_id === user.id && req.status === 'pending' ? (
                                <button 
                                onClick={() => handleCancel(req.id)}
                                className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded-lg hover:bg-red-50 transition-colors"
                                >
                                <Trash2 className="w-3.5 h-3.5" />
                                Hủy yêu cầu
                                </button>
                            ) : (
                                <span className="text-xs text-gray-400 italic">
                                    {req.status === 'approved' ? 'Vui lòng bảo quản tốt' : 
                                     req.status === 'returned' ? 'Đã trả xong' : 'Không có thao tác'}
                                </span>
                            )}
                        </>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, Filter } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);

  // Tab cho Admin: 'all' (Quản lý chung) | 'personal' (Của tôi)
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // Load danh sách yêu cầu
  const fetchRequests = async () => {
    setLoading(true);
    let query = supabase
      .from('requests')
      .select('*')
      .order('borrow_date', { ascending: false });

    // Logic lọc:
    // 1. Nếu không phải admin -> Luôn chỉ xem của mình
    // 2. Nếu là admin nhưng đang chọn tab 'personal' -> Chỉ xem của mình
    if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) {
      setRequests(data as BorrowRequest[]);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]); // Reload khi đổi tab

  // 1. Xử lý PHÊ DUYỆT (Trừ kho)
  const handleApprove = async (req: BorrowRequest) => {
    if (!window.confirm('Phê duyệt yêu cầu này? Số lượng kho sẽ bị trừ 1.')) return;
    setProcessingId(req.id);

    try {
      // B1: Kiểm tra tồn kho hiện tại
      const { data: toolData, error: toolError } = await supabase
        .from('tools')
        .select('available, quantity')
        .eq('id', req.tool_id)
        .single();

      if (toolError || !toolData) throw new Error("Không tìm thấy thông tin công cụ.");
      if (toolData.available <= 0) throw new Error("Kho đã hết công cụ này, không thể duyệt!");

      // B2: Trừ tồn kho
      const { error: updateToolError } = await supabase
        .from('tools')
        .update({ available: toolData.available - 1 })
        .eq('id', req.tool_id);

      if (updateToolError) throw new Error("Lỗi cập nhật kho.");

      // B3: Cập nhật trạng thái Request
      const { error: updateReqError } = await supabase
        .from('requests')
        .update({
            status: 'approved',
            approved_at: new Date().toISOString(),
            approved_by: user.employeeCode
        })
        .eq('id', req.id);

      if (updateReqError) {
          // Rollback kho nếu lỗi (đơn giản hoá: cộng lại)
          await supabase.from('tools').update({ available: toolData.available }).eq('id', req.tool_id);
          throw updateReqError;
      }

      // Success
      await fetchRequests();

    } catch (error: any) {
      alert(`Lỗi: ${error.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  // 2. Xử lý TỪ CHỐI (Không trừ kho)
  const handleReject = async (req: BorrowRequest) => {
    if (!window.confirm('Từ chối yêu cầu này?')) return;
    setProcessingId(req.id);

    try {
        const { error } = await supabase
            .from('requests')
            .update({
                status: 'rejected',
                rejected_at: new Date().toISOString(),
                rejected_by: user.employeeCode
            })
            .eq('id', req.id);

        if (error) throw error;
        await fetchRequests();
    } catch (error: any) {
        alert("Lỗi: " + error.message);
    } finally {
        setProcessingId(null);
    }
  };

  // 3. Xử lý TRẢ LẠI (Cộng kho)
  const handleReturn = async (req: BorrowRequest) => {
    if (!window.confirm(`Xác nhận đã trả công cụ: ${req.tool_name}? Kho sẽ được cộng thêm 1.`)) return;
    setProcessingId(req.id);

    try {
        // B1: Lấy thông tin kho hiện tại để đảm bảo tính đúng đắn
        const { data: toolData } = await supabase
            .from('tools')
            .select('available')
            .eq('id', req.tool_id)
            .single();

        const currentAvailable = toolData ? toolData.available : 0;

        // B2: Cộng tồn kho
        await supabase
            .from('tools')
            .update({ available: currentAvailable + 1 })
            .eq('id', req.tool_id);

        // B3: Cập nhật Request thành 'returned'
        const { error } = await supabase
            .from('requests')
            .update({
                status: 'returned',
                returned_at: new Date().toISOString()
            })
            .eq('id', req.id);

        if (error) throw error;
        await fetchRequests();

    } catch (error: any) {
        alert("Lỗi khi trả đồ: " + error.message);
    } finally {
        setProcessingId(null);
    }
  };

  // 4. Xử lý HUỶ (User tự huỷ khi chưa duyệt)
  const handleCancel = async (id: string) => {
    if (!window.confirm('Hủy yêu cầu này?')) return;
    setProcessingId(id);
    await supabase.from('requests').delete().eq('id', id);
    await fetchRequests();
    setProcessingId(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu Mượn</h2>

        {/* TAB SWITCHER CHO ADMIN */}
        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' 
                        ? 'bg-white text-blue-700 shadow-sm' 
                        : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' 
                        ? 'bg-white text-blue-700 shadow-sm' 
                        : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200">
              <tr>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={5} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : requests.length === 0 ? (
                <tr><td colSpan={5} className="p-8 text-center text-gray-500 italic">Không có yêu cầu nào.</td></tr>
              ) : (
                requests.map((req) => (
                  <tr key={req.id} className="hover:bg-blue-50/50 transition-colors">
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name.charAt(0)}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-800">{req.tool_name}</td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                        req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                        req.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                        'bg-yellow-50 text-yellow-700 border-yellow-200'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'returned' && <RotateCcw className="w-3 h-3" />}
                         {req.status === 'rejected' && <X className="w-3 h-3" />}

                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        {/* 1. ADMIN ACTIONS (Chỉ hiển thị khi ở tab 'Quản lý chung' HOẶC user là admin xử lý đơn của người khác) */}
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {/* Duyệt / Huỷ */}
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => handleApprove(req)}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50" 
                                            title="Phê duyệt (Trừ kho)"
                                        >
                                            <Check className="w-3.5 h-3.5" /> Duyệt
                                        </button>
                                        <button 
                                            onClick={() => handleReject(req)}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50" 
                                            title="Từ chối"
                                        >
                                            <X className="w-3.5 h-3.5" /> Từ chối
                                        </button>
                                    </>
                                )}

                                {/* Trả lại */}
                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => handleReturn(req)}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm"
                                        title="Xác nhận đã trả (Cộng kho)"
                                    >
                                        <RotateCcw className="w-3.5 h-3.5" />
                                        Đã trả lại
                                    </button>
                                )}
                            </>
                        )}

                        {/* 2. USER ACTIONS (User thường HOẶC Admin ở tab 'Của tôi') */}
                        {(user.role !== 'admin' || activeTab === 'personal') && (
                            <>
                                {req.status === 'pending' ? (
                                    <button 
                                        onClick={() => handleCancel(req.id)}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors"
                                    >
                                        <Trash2 className="w-3.5 h-3.5" />
                                        Hủy yêu cầu
                                    </button>
                                ) : (
                                    <span className="text-xs text-gray-400 italic">
                                        {req.status === 'returned' ? 'Hoàn tất' : 'Liên hệ quản lý'}
                                    </span>
                                )}
                            </>
                        )}

                        {/* Fallback display for completed items in Admin View */}
                        {user.role === 'admin' && activeTab === 'all' && (req.status === 'returned' || req.status === 'rejected') && (
                            <span className="text-xs text-gray-400 italic">Lưu trữ</span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
