import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { History, Search, Calendar, Filter, X, User as UserIcon, ShieldCheck } from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

// Mở rộng interface local để hứng thêm field người xử lý từ DB
interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const fetchHistory = async () => {
    setLoading(true);
    let query = supabase
      .from('requests')
      .select('*')
      .order('borrow_date', { ascending: false });

    // Nếu không phải admin, chỉ xem lịch sử của chính mình
    if (user.role !== 'admin') {
      query = query.eq('user_id', user.id);
    }

    // Lọc theo ngày (Server-side filter)
    if (startDate) {
      query = query.gte('borrow_date', `${startDate}T00:00:00`);
    }
    if (endDate) {
      query = query.lte('borrow_date', `${endDate}T23:59:59`);
    }

    const { data, error } = await query;
    if (data) {
      setLogs(data as ExtendedBorrowRequest[]);
    }
    if (error) console.error(error);
    setLoading(false);
  };

  useEffect(() => {
    fetchHistory();
  }, [user, startDate, endDate]); // Reload khi user hoặc date thay đổi

  // Lọc Client-side cho Text Search (Tên, Mã NV, Công cụ)
  const filteredLogs = logs.filter(log => {
    const searchLower = searchText.toLowerCase();
    return (
      log.user_name.toLowerCase().includes(searchLower) ||
      log.employee_id.toLowerCase().includes(searchLower) ||
      log.tool_name.toLowerCase().includes(searchLower)
    );
  });

  const clearFilters = () => {
    setSearchText('');
    setStartDate('');
    setEndDate('');
  };

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Admin';
    if (req.status === 'rejected') return req.rejected_by || 'Admin';
    return '-';
  };

  return (
    <div className="space-y-6">
       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-purple-100 rounded-lg text-purple-600">
                    <History className="w-6 h-6" />
                </div>
                <div>
                    <h2 className="text-2xl font-bold text-gray-800">Lịch sử hoạt động</h2>
                    <p className="text-sm text-gray-500">
                        {user.role === 'admin' ? 'Theo dõi toàn bộ lịch sử mượn trả của hệ thống' : 'Theo dõi lịch sử mượn trả của bạn'}
                    </p>
                </div>
            </div>
       </div>

       <Card className="p-0 overflow-hidden">
            {/* Toolbar Bộ lọc */}
            <div className="p-4 bg-gray-50 border-b border-gray-200 grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
                {/* Search Text */}
                <div className="md:col-span-5 relative">
                    <label className="block text-xs font-medium text-gray-500 mb-1 ml-1">Tìm kiếm (Tên, Mã NV, Công cụ)</label>
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                            type="text" 
                            value={searchText}
                            onChange={(e) => setSearchText(e.target.value)}
                            placeholder="Nhập từ khóa..." 
                            className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                        />
                    </div>
                </div>

                {/* Date Filters */}
                <div className="md:col-span-3">
                    <label className="block text-xs font-medium text-gray-500 mb-1 ml-1">Từ ngày</label>
                    <div className="relative">
                        <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="w-full pl-10 pr-3 py-2 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                        />
                    </div>
                </div>

                <div className="md:col-span-3">
                    <label className="block text-xs font-medium text-gray-500 mb-1 ml-1">Đến ngày</label>
                    <div className="relative">
                        <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="w-full pl-10 pr-3 py-2 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                        />
                    </div>
                </div>

                {/* Clear Button */}
                <div className="md:col-span-1">
                    {(searchText || startDate || endDate) && (
                        <button 
                            onClick={clearFilters}
                            className="w-full flex items-center justify-center gap-1 py-2 text-red-600 bg-red-50 hover:bg-red-100 rounded-lg text-xs font-medium transition-colors border border-red-200"
                            title="Xóa bộ lọc"
                        >
                            <X className="w-4 h-4" /> Xóa
                        </button>
                    )}
                </div>
            </div>

            {/* Bảng Dữ liệu */}
            <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-gray-600">
                    <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200">
                        <tr>
                            <th className="px-6 py-4">Người mượn</th>
                            <th className="px-6 py-4">Công cụ</th>
                            <th className="px-6 py-4">Ngày mượn</th>
                            <th className="px-6 py-4">Ngày trả</th>
                            <th className="px-6 py-4">Người xử lý</th>
                            <th className="px-6 py-4 text-center">Trạng thái</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 bg-white">
                        {loading ? (
                            <tr><td colSpan={6} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
                        ) : filteredLogs.length === 0 ? (
                            <tr><td colSpan={6} className="p-8 text-center text-gray-500 italic">Không tìm thấy dữ liệu phù hợp.</td></tr>
                        ) : (
                            filteredLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-gray-50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-xs font-bold">
                                                {item.user_name.charAt(0)}
                                            </div>
                                            <div>
                                                <div className="font-medium text-gray-900">{item.user_name}</div>
                                                <div className="text-xs text-gray-400 font-mono">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="font-medium text-gray-800">{item.tool_name}</span>
                                    </td>
                                    <td className="px-6 py-4 text-xs">
                                        <div className="text-gray-900 font-medium">{new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        <div className="text-gray-400">{new Date(item.borrow_date).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                    </td>
                                    <td className="px-6 py-4 text-xs">
                                        {item.returned_at ? (
                                            <>
                                                <div className="text-blue-700 font-medium">{new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                                <div className="text-blue-400">{new Date(item.returned_at).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                            </>
                                        ) : (
                                            <span className="text-gray-400 italic">-</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        {item.status !== 'pending' ? (
                                            <div className="flex items-center gap-1.5 text-xs text-gray-700 bg-gray-100 px-2 py-1 rounded w-fit">
                                                <ShieldCheck className="w-3 h-3 text-gray-500" />
                                                {getHandlerName(item)}
                                            </div>
                                        ) : (
                                            <span className="text-gray-400 text-xs italic">Đang chờ...</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium border ${
                                            item.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                                            item.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                                            item.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                            'bg-yellow-50 text-yellow-700 border-yellow-200'
                                        }`}>
                                            {item.status === 'approved' ? 'Đang mượn' : 
                                            item.status === 'rejected' ? 'Đã từ chối' : 
                                            item.status === 'returned' ? 'Đã trả' : 'Chờ duyệt'}
                                        </span>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
       </Card>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);

  // Tab cho Admin: 'all' (Quản lý chung) | 'personal' (Của tôi)
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // Load danh sách yêu cầu
  const fetchRequests = async () => {
    setLoading(true);
    let query = supabase
      .from('requests')
      .select('*')
      .order('borrow_date', { ascending: false });

    // Logic lọc:
    // 1. Nếu không phải admin -> Luôn chỉ xem của mình
    // 2. Nếu là admin nhưng đang chọn tab 'personal' -> Chỉ xem của mình
    if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) {
      setRequests(data as BorrowRequest[]);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]); // Reload khi đổi tab

  // 1. Xử lý PHÊ DUYỆT (Trừ kho)
  const handleApprove = async (req: BorrowRequest) => {
    if (!window.confirm('Phê duyệt yêu cầu này? Số lượng kho sẽ bị trừ 1.')) return;
    setProcessingId(req.id);

    try {
      // B1: Kiểm tra tồn kho hiện tại
      const { data: toolData, error: toolError } = await supabase
        .from('tools')
        .select('available, quantity')
        .eq('id', req.tool_id)
        .single();

      if (toolError || !toolData) throw new Error("Không tìm thấy thông tin công cụ.");
      if (toolData.available <= 0) throw new Error("Kho đã hết công cụ này, không thể duyệt!");

      // B2: Trừ tồn kho
      const { error: updateToolError } = await supabase
        .from('tools')
        .update({ available: toolData.available - 1 })
        .eq('id', req.tool_id);

      if (updateToolError) throw new Error("Lỗi cập nhật kho: " + updateToolError.message);

      // B3: Cập nhật trạng thái Request
      // LƯU Ý: Chỉ update các trường có trong DB. Bỏ approved_by để tránh lỗi nếu column chưa tạo.
      const { error: updateReqError } = await supabase
        .from('requests')
        .update({
            status: 'approved'
        })
        .eq('id', req.id);

      if (updateReqError) {
          // Rollback kho nếu lỗi (đơn giản hoá: cộng lại)
          await supabase.from('tools').update({ available: toolData.available }).eq('id', req.tool_id);
          throw new Error("Lỗi cập nhật trạng thái: " + updateReqError.message);
      }

      // Success
      await fetchRequests();

    } catch (error: any) {
      console.error(error);
      alert(`Có lỗi xảy ra: ${error.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  // 2. Xử lý TỪ CHỐI (Không trừ kho)
  const handleReject = async (req: BorrowRequest) => {
    if (!window.confirm('Từ chối yêu cầu này?')) return;
    setProcessingId(req.id);

    try {
        const { error } = await supabase
            .from('requests')
            .update({
                status: 'rejected'
            })
            .eq('id', req.id);

        if (error) throw new Error(error.message);
        await fetchRequests();
    } catch (error: any) {
        alert("Lỗi: " + error.message);
    } finally {
        setProcessingId(null);
    }
  };

  // 3. Xử lý TRẢ LẠI (Cộng kho)
  const handleReturn = async (req: BorrowRequest) => {
    if (!window.confirm(`Xác nhận đã trả công cụ: ${req.tool_name}? Kho sẽ được cộng thêm 1.`)) return;
    setProcessingId(req.id);

    try {
        // B1: Lấy thông tin kho hiện tại để đảm bảo tính đúng đắn
        const { data: toolData } = await supabase
            .from('tools')
            .select('available')
            .eq('id', req.tool_id)
            .single();

        const currentAvailable = toolData ? toolData.available : 0;

        // B2: Cộng tồn kho
        await supabase
            .from('tools')
            .update({ available: currentAvailable + 1 })
            .eq('id', req.tool_id);

        // B3: Cập nhật Request thành 'returned'
        const { error } = await supabase
            .from('requests')
            .update({
                status: 'returned',
                returned_at: new Date().toISOString()
            })
            .eq('id', req.id);

        if (error) throw error;
        await fetchRequests();

    } catch (error: any) {
        alert("Lỗi khi trả đồ: " + error.message);
    } finally {
        setProcessingId(null);
    }
  };

  // 4. Xử lý HUỶ (User tự huỷ khi chưa duyệt)
  const handleCancel = async (id: string) => {
    if (!window.confirm('Hủy yêu cầu này?')) return;
    setProcessingId(id);
    await supabase.from('requests').delete().eq('id', id);
    await fetchRequests();
    setProcessingId(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu Mượn</h2>

