                                        {req.status === 'returned' ? 'Hoàn tất' : 'Liên hệ quản lý'}
                                    </span>
                                )}
                            </>
                        )}

                        {/* Fallback display for completed items in Admin View */}
                        {user.role === 'admin' && activeTab === 'all' && (req.status === 'returned' || req.status === 'rejected') && (
                            <span className="text-xs text-gray-400 italic">Lưu trữ</span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);

  // Tab cho Admin: 'all' (Quản lý chung) | 'personal' (Của tôi)
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      // Nếu là admin và đang xem tab 'all', lấy hết. Ngược lại chỉ lấy của mình.
      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  // 1. Xử lý PHÊ DUYỆT (Trừ kho)
  const handleApprove = async (req: BorrowRequest) => {
    if (!window.confirm('Xác nhận DUYỆT yêu cầu này?')) return;
    setProcessingId(req.id);

    try {
      // B1: Lấy thông tin kho
      const { data: tools, error: toolError } = await supabase
        .from('tools')
        .select('*')
        .eq('id', req.tool_id);

      if (toolError) throw new Error("Lỗi kết nối CSDL khi lấy thông tin kho.");
      if (!tools || tools.length === 0) throw new Error("Không tìm thấy công cụ này trong kho (có thể đã bị xóa).");

      const tool = tools[0];
      const currentAvailable = parseInt(tool.available || '0');

      if (currentAvailable <= 0) throw new Error(`Kho đã hết (Sẵn có: ${currentAvailable}). Không thể duyệt!`);

      // B2: Trừ tồn kho
      const { error: updateToolError } = await supabase
        .from('tools')
        .update({ available: currentAvailable - 1 })
        .eq('id', req.tool_id);

      if (updateToolError) throw new Error("Lỗi cập nhật số lượng kho: " + updateToolError.message);

      // B3: Cập nhật trạng thái Request
      const { error: updateReqError } = await supabase
        .from('requests')
        .update({ status: 'approved' })
        .eq('id', req.id);

      if (updateReqError) {
          // Rollback kho nếu lỗi
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error("Lỗi cập nhật trạng thái đơn: " + updateReqError.message);
      }

      await fetchRequests();
    } catch (error: any) {
      console.error(error);
      alert(`Thao tác thất bại: ${error.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  // 2. Xử lý TỪ CHỐI
  const handleReject = async (req: BorrowRequest) => {
    if (!window.confirm('Xác nhận TỪ CHỐI yêu cầu này?')) return;
    setProcessingId(req.id);

    try {
        const { error } = await supabase
            .from('requests')
            .update({ status: 'rejected' })
            .eq('id', req.id);

        if (error) throw error;
        await fetchRequests();
    } catch (error: any) {
        alert("Lỗi khi từ chối: " + error.message);
    } finally {
        setProcessingId(null);
    }
  };

  // 3. Xử lý TRẢ LẠI (Cộng kho)
  const handleReturn = async (req: BorrowRequest) => {
    if (!window.confirm(`Xác nhận ĐÃ TRẢ công cụ: ${req.tool_name}?`)) return;
    setProcessingId(req.id);

    try {
        // B1: Lấy thông tin kho
        const { data: tools } = await supabase
            .from('tools')
            .select('available')
            .eq('id', req.tool_id);

        const currentAvailable = tools && tools.length > 0 ? parseInt(tools[0].available || '0') : 0;

        // B2: Cộng tồn kho
        await supabase
            .from('tools')
            .update({ available: currentAvailable + 1 })
            .eq('id', req.tool_id);

        // B3: Cập nhật Request
        const { error } = await supabase
            .from('requests')
            .update({
                status: 'returned',
                returned_at: new Date().toISOString()
            })
            .eq('id', req.id);

        if (error) throw error;
        await fetchRequests();

    } catch (error: any) {
        alert("Lỗi khi trả đồ: " + error.message);
    } finally {
        setProcessingId(null);
    }
  };

  // 4. Xử lý HUỶ
  const handleCancel = async (id: string) => {
    if (!window.confirm('Hủy yêu cầu này?')) return;
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) alert("Lỗi hủy đơn: " + error.message);
    else await fetchRequests();
    setProcessingId(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu</h2>

        {/* TAB SWITCHER: Chỉ hiển thị nếu là Admin */}
        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' 
                        ? 'bg-white text-blue-700 shadow-sm' 
                        : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' 
                        ? 'bg-white text-blue-700 shadow-sm' 
                        : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200">
              <tr>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={5} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : requests.length === 0 ? (
                <tr><td colSpan={5} className="p-8 text-center text-gray-500 italic">Không có yêu cầu nào.</td></tr>
              ) : (
                requests.map((req) => (
                  <tr key={req.id} className="hover:bg-blue-50/50 transition-colors">
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-800">{req.tool_name}</td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                        req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                        req.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                        'bg-yellow-50 text-yellow-700 border-yellow-200'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'returned' && <RotateCcw className="w-3 h-3" />}
                         {req.status === 'rejected' && <X className="w-3 h-3" />}

                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">

                        {/* 1. ADMIN ACTIONS */}
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {/* Nút Duyệt / Từ chối cho đơn Pending */}
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => handleApprove(req)}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm" 
                                            title="Phê duyệt (Trừ kho)"
                                        >
                                            <Check className="w-3.5 h-3.5" /> Duyệt
                                        </button>
                                        <button 
                                            onClick={() => handleReject(req)}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50" 
                                            title="Từ chối"
                                        >
                                            <X className="w-3.5 h-3.5" /> Từ chối
                                        </button>
                                    </>
                                )}

                                {/* Nút Trả lại cho đơn Approved */}
                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => handleReturn(req)}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm"
                                        title="Xác nhận đã trả (Cộng kho)"
                                    >
                                        <RotateCcw className="w-3.5 h-3.5" />
                                        Đã trả lại
                                    </button>
                                )}
                            </>
                        )}

                        {/* 2. USER ACTIONS (Owner) */}
                        {(user.role !== 'admin' || activeTab === 'personal') && (
                            <>
                                {req.status === 'pending' ? (
                                    <button 
                                        onClick={() => handleCancel(req.id)}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors"
                                    >
                                        <Trash2 className="w-3.5 h-3.5" />
                                        Hủy
                                    </button>
                                ) : (
                                    <span className="text-xs text-gray-400 italic min-w-[60px] inline-block text-center">
                                        {req.status === 'returned' ? 'Hoàn tất' : '...'}
                                    </span>
                                )}
                            </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

