// Khởi tạo client thực
const client = createClient(supabaseUrl, supabaseKey);

// Wrapper để giữ tương thích với code cũ và xử lý Auth tùy chỉnh
export const supabase = {
  // Proxy các hàm query cơ bản sang client thực
  from: (table: string) => client.from(table),
  rpc: (fn: string, args: any) => client.rpc(fn, args),

  // Auth tùy chỉnh dùng bảng 'users'
  auth: {
    signInWithPassword: async ({ employeeCode, password }: { employeeCode: string, password: string }) => {
      try {
        // Query trực tiếp bảng users
        const { data, error } = await client
          .from('users')
          .select('*')
          .eq('employee_id', employeeCode)
          .eq('password', password)
          .single();

        if (error || !data) {
          return { data: null, error: { message: 'Mã nhân viên hoặc mật khẩu không chính xác.' } };
        }

        // Tạo object User compatible với App, đảm bảo trim whitespace cho role
        const user = {
          id: data.id,
          employeeCode: data.employee_id,
          name: data.name,
          role: data.role ? data.role.trim() : 'user', // Quan trọng: Trim role để logic so sánh chính xác
        };

        const session = {
          access_token: 'custom-session-token', // Token giả vì không dùng Auth của Supabase
          user: user
        };

        return { data: { user, session }, error: null };
      } catch (err) {
        return { data: null, error: { message: 'Lỗi kết nối server.' } };
      }
    },
    signOut: async () => {
      // Vì dùng local session, việc signout chỉ cần App xóa localStorage là đủ
      return { error: null };
    },
    getSession: async () => {
      // Lấy session từ localStorage (do Login form lưu)
      const stored = localStorage.getItem('sb-session');
      return { data: { session: stored ? JSON.parse(stored) : null }, error: null };
    },
    getUser: async () => {
        const stored = localStorage.getItem('sb-session');
        const session = stored ? JSON.parse(stored) : null;
        return { data: { user: session?.user || null }, error: null };
    }
  }
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, AlertTriangle, Loader2 } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

// Component thông báo nổi (Toast)
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${bgClass} text-white px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-fade-in-up max-w-sm`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-medium">{message}</p>
      <button onClick={onClose} className="ml-auto p-1 hover:bg-white/20 rounded">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);

  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const parseQuantity = (val: any) => {
    const num = parseInt(val);
    return isNaN(num) ? 0 : num;
  };

  // 1. Xử lý PHÊ DUYỆT (Trừ kho)
  const handleApprove = async (req: BorrowRequest) => {
    // Bỏ window.confirm để tránh bị chặn
    showToast(`Đang duyệt đơn mượn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);

    try {
      // B1: Lấy thông tin kho
      const { data: tools, error: toolError } = await supabase
        .from('tools')
        .select('*')
        .eq('id', req.tool_id);

      if (toolError) throw new Error(`Lỗi đọc kho: ${toolError.message}`);
      if (!tools || tools.length === 0) throw new Error("Không tìm thấy công cụ này trong kho.");

      const tool = tools[0];
      const currentAvailable = parseQuantity(tool.available);

      if (currentAvailable <= 0) throw new Error(`Kho đã hết (Sẵn có: ${currentAvailable}).`);

      // B2: Trừ tồn kho
      const { error: updateToolError } = await supabase
        .from('tools')
        .update({ available: currentAvailable - 1 })
        .eq('id', req.tool_id)
        .select(); // Quan trọng: select() để đảm bảo row trả về, kiểm tra quyền RLS

      if (updateToolError) throw new Error(`Không thể cập nhật kho. Kiểm tra Policy Supabase.`);

      // B3: Cập nhật trạng thái Request
      const { error: updateReqError, data: updatedReq } = await supabase
        .from('requests')
        .update({ status: 'approved' })
        .eq('id', req.id)
        .select();

      // Kiểm tra kỹ RLS: Nếu không lỗi nhưng data rỗng => RLS chặn update
      if (!updatedReq || updatedReq.length === 0) {
           // Rollback kho
           await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
           throw new Error("Quyền hạn bị từ chối (RLS). Vui lòng cấu hình Policy cho phép UPDATE trên Supabase.");
      }

      if (updateReqError) {
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error(`Lỗi duyệt đơn: ${updateReqError.message}`);
      }

      showToast(`Đã duyệt thành công: ${req.tool_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      console.error(error);
      showToast(`Thất bại: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  // 2. Xử lý TỪ CHỐI
  const handleReject = async (req: BorrowRequest) => {
    showToast('Đang từ chối yêu cầu...', 'info');
    setProcessingId(req.id);

    try {
        const { error, data } = await supabase
            .from('requests')
            .update({ status: 'rejected' })
            .eq('id', req.id)
            .select();

        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Quyền hạn bị từ chối (RLS).");

        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  // 3. Xử lý TRẢ LẠI
  const handleReturn = async (req: BorrowRequest) => {
    showToast('Đang xử lý trả đồ...', 'info');
    setProcessingId(req.id);

    try {
        const { data: tools } = await supabase
            .from('tools')
            .select('available')
            .eq('id', req.tool_id);

        const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;

        const { error: toolErr } = await supabase
            .from('tools')
            .update({ available: currentAvailable + 1 })
            .eq('id', req.tool_id);

        if (toolErr) throw new Error(`Lỗi kho: ${toolErr.message}`);

        const { error: reqErr, data } = await supabase
            .from('requests')
            .update({
                status: 'returned',
                returned_at: new Date().toISOString()
            })
            .eq('id', req.id)
            .select();

        if (reqErr) throw new Error(reqErr.message);
        if (!data || data.length === 0) throw new Error("Quyền hạn bị từ chối (RLS).");

        showToast('Đã xác nhận trả đồ.', 'success');
        await fetchRequests();

    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  // 4. Xử lý HUỶ
  const handleCancel = async (id: string) => {
    if (!window.confirm('Hủy yêu cầu này?')) return; // Giữ confirm cho user thường
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi hủy đơn: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  return (
    <div className="space-y-6 relative">
      {/* Toast Notification Container */}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

