      // 1. Tính Tổng số lượng công cụ (Tổng cột quantity)
      const totalToolsQuantity = tools.reduce((sum, tool) => sum + (tool.quantity || 0), 0);

      // 2. Tính Số lượng sẵn có (Tổng cột available của các tool active)
      const totalToolsAvailable = tools.reduce((sum, tool) => sum + (tool.status === 'active' ? (tool.available || 0) : 0), 0);

      // 3. Tính Số lượng đang mượn (Dựa vào request đã duyệt 'approved')
      const borrowedTools = requests.filter(r => r.status === 'approved').length;

      // 4. Tính Số lượng chờ duyệt
      const pendingRequests = requests.filter(r => r.status === 'pending').length;

      setStats({
        totalToolsQuantity,
        totalToolsAvailable,
        borrowedTools,
        pendingRequests
      });

      // --- Biểu đồ Tròn: Phân bố trạng thái tài sản ---
      // Logic: Tổng tài sản = Sẵn có + Đang mượn + (Hỏng/Khác)
      // Để biểu đồ chính xác với thực tế:
      const pieChartData = [
        { name: 'Sẵn có', value: totalToolsAvailable },
        { name: 'Đang mượn', value: borrowedTools },
        { name: 'Khác/Hỏng', value: Math.max(0, totalToolsQuantity - totalToolsAvailable - borrowedTools) },
      ];
      // Lọc bỏ các mục có giá trị 0 để biểu đồ đẹp hơn
      setPieData(pieChartData.filter(item => item.value > 0));

      // --- Biểu đồ Cột: Yêu cầu 7 ngày gần nhất ---
      const last7Days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        return {
            dateStr: d.toLocaleDateString('vi-VN'),
            dayName: d.toLocaleDateString('vi-VN', { weekday: 'short' }),
            fullDate: d.toISOString().split('T')[0]
        };
      });

      const chartData = last7Days.map(day => {
        const count = requests.filter(r => r.borrow_date.startsWith(day.fullDate)).length;
        return {
            name: day.dayName,
            fullDate: day.dateStr,
            requests: count
        };
      });

      setBarData(chartData);

    } catch (error) {
      console.error("Error fetching dashboard data:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
        <div className="flex h-96 items-center justify-center">
            <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
        </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">

        {/* Card 1: Tổng số công cụ */}
        <Card className="flex items-center gap-4 border-l-4 border-l-purple-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-purple-100 rounded-full text-purple-600">
            <Package className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Tổng số công cụ</p>
            <p className="text-2xl font-bold text-gray-800">{stats.totalToolsQuantity}</p>
          </div>
        </Card>

        {/* Card 2: Đang cho mượn */}
        <Card className="flex items-center gap-4 border-l-4 border-l-orange-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-orange-100 rounded-full text-orange-600">
            <ShoppingBag className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Đang cho mượn</p>
            <p className="text-2xl font-bold text-gray-800">{stats.borrowedTools}</p>
          </div>
        </Card>

        {/* Card 3: Sẵn có */}
        <Card className="flex items-center gap-4 border-l-4 border-l-green-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-green-100 rounded-full text-green-600">
            <Wrench className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Sẵn có tại kho</p>
            <p className="text-2xl font-bold text-gray-800">{stats.totalToolsAvailable}</p>
          </div>
        </Card>

        {/* Card 4: Chờ duyệt */}
        <Card className="flex items-center gap-4 border-l-4 border-l-yellow-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-yellow-100 rounded-full text-yellow-600">
            <TrendingUp className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500">Yêu cầu chờ duyệt</p>
            <p className="text-2xl font-bold text-gray-800">{stats.pendingRequests}</p>
          </div>
        </Card>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card title="Xu hướng mượn (7 ngày qua)" className="min-w-0">
          <SafeChartContainer height={300}>
            <BarChart data={barData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
              <XAxis 
                dataKey="name" 
                axisLine={false} 
                tickLine={false} 
                tick={{fill: '#6b7280', fontSize: 12}}
                dy={10}
              />
              <YAxis 
                axisLine={false} 
                tickLine={false} 
                allowDecimals={false} 
                tick={{fill: '#6b7280', fontSize: 12}}
              />
              <Tooltip 
                cursor={{fill: '#f9fafb'}}
                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                labelStyle={{ fontWeight: '600', color: '#374151', marginBottom: '0.25rem' }}
              />
              <Bar 
                dataKey="requests" 
                name="Số yêu cầu" 
                fill="#8b5cf6" 
                radius={[4, 4, 0, 0]} 
                barSize={40}
              />
            </BarChart>
          </SafeChartContainer>
        </Card>

        <Card title="Tình trạng phân bổ tài sản" className="min-w-0">
          <SafeChartContainer height={300}>
            <PieChart>
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
                nameKey="name"
              >
                {pieData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />
                ))}
              </Pie>
              <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
              <text x="50%" y="50%" textAnchor="middle" dominantBaseline="middle" className="text-gray-400 text-sm font-medium">
                {stats.totalToolsQuantity} Item
              </text>
            </PieChart>
          </SafeChartContainer>
          <div className="flex justify-center gap-4 mt-4 flex-wrap">
              {pieData.map((entry, index) => (
                  <div key={index} className="flex items-center gap-1.5 text-xs text-gray-600 font-medium bg-gray-50 px-2 py-1 rounded-full border border-gray-100">
                      <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                      {entry.name} <span className="text-gray-400">({entry.value})</span>
                  </div>
              ))}
          </div>
        </Card>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, AlertTriangle, Loader2 } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

// Component thông báo nổi (Toast)
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${bgClass} text-white px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-fade-in-up max-w-sm`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-medium">{message}</p>
      <button onClick={onClose} className="ml-auto p-1 hover:bg-white/20 rounded">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

// Loại hành động cần xác nhận
type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | { type: 'bulk_cancel' }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // State cho Bulk Actions
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // State cho Confirmation Dialog
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
      setSelectedIds(new Set()); // Reset selection khi reload
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const parseQuantity = (val: any) => {
    const num = parseInt(val);
    return isNaN(num) ? 0 : num;
  };

  // --- BULK ACTIONS ---
  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    // Chỉ select những đơn Pending (có thể huỷ)
    const pendingIds = requests.filter(r => r.status === 'pending').map(r => r.id);

    if (selectedIds.size === pendingIds.length && pendingIds.length > 0) {
        setSelectedIds(new Set());
    } else {
        setSelectedIds(new Set(pendingIds));
    }
  };

  const executeBulkCancel = async () => {
    if (selectedIds.size === 0) return;
    showToast(`Đang hủy ${selectedIds.size} yêu cầu...`, 'info');
    setIsBulkProcessing(true);

    try {
        const idsArray = Array.from(selectedIds);
        const { error } = await supabase
            .from('requests')
            .delete()
            .in('id', idsArray);

        if (error) throw new Error(error.message);

        showToast(`Đã hủy thành công ${selectedIds.size} yêu cầu.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi hủy hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  // --- SINGLE ACTIONS ---

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn mượn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);

    try {
      const { data: tools, error: toolError } = await supabase.from('tools').select('*').eq('id', req.tool_id);
      if (toolError || !tools || tools.length === 0) throw new Error("Lỗi đọc kho.");

      const tool = tools[0];
      const currentAvailable = parseQuantity(tool.available);

      if (currentAvailable <= 0) throw new Error(`Kho đã hết.`);

      const { error: updateToolError } = await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id).select();
      if (updateToolError) throw new Error(`Lỗi cập nhật kho.`);

      const { error: updateReqError, data: updatedReq } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id).select();

      if (!updatedReq || updatedReq.length === 0) {
           await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
           throw new Error("Lỗi quyền hạn (RLS).");
      }

      if (updateReqError) {
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error(`Lỗi duyệt đơn: ${updateReqError.message}`);
      }

      showToast(`Đã duyệt: ${req.tool_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Thất bại: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang từ chối yêu cầu...', 'info');
    setProcessingId(req.id);
    try {
        const { error, data } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn (RLS).");
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang xử lý trả đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
        const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const { error, data } = await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn.");
        showToast('Đã xác nhận trả đồ.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy yêu cầu...', 'info');
    setProcessingId(id);

    const { error } = await supabase.from('requests').delete().eq('id', id);

    if (error) {
        showToast("Lỗi hủy đơn: " + error.message, 'error');
    } else {
        showToast("Đã hủy yêu cầu.", 'success');
        if (selectedIds.has(id)) {
            const newSet = new Set(selectedIds);
            newSet.delete(id);
            setSelectedIds(newSet);
        }
        await fetchRequests();
    }
    setProcessingId(null);
  };

  // Hàm điều phối xác nhận
  const handleConfirmAction = async () => {
    if (!confirmAction) return;

    setConfirmAction(null); // Đóng modal trước khi thực hiện

    switch (confirmAction.type) {
      case 'approve':
        await executeApprove(confirmAction.req);
        break;
      case 'reject':
        await executeReject(confirmAction.req);
        break;
      case 'return':
        await executeReturn(confirmAction.req);
        break;
      case 'cancel':
        await executeCancel(confirmAction.id);
        break;
      case 'bulk_cancel':
        await executeBulkCancel();
        break;
    }
  };

  // Helper để lấy nội dung modal
  const getConfirmContent = () => {
    if (!confirmAction) return { title: '', message: '', btnClass: '' };

    switch (confirmAction.type) {
      case 'approve':
        return {
          title: 'Duyệt yêu cầu',
          message: `Bạn có chắc chắn muốn DUYỆT yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-green-600 hover:bg-green-700'
        };
      case 'reject':
        return {
          title: 'Từ chối yêu cầu',
          message: `Bạn có chắc chắn muốn TỪ CHỐI yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'return':
        return {
          title: 'Xác nhận trả đồ',
          message: `Xác nhận nhân viên ${confirmAction.req.user_name} đã trả lại "${confirmAction.req.tool_name}"?`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      case 'cancel':
        return {
          title: 'Hủy yêu cầu',
          message: 'Hành động này không thể hoàn tác. Bạn có chắc chắn muốn hủy yêu cầu này?',
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_cancel':
        return {
          title: 'Hủy hàng loạt',
          message: `Bạn đang chọn hủy ${selectedIds.size} yêu cầu. Hành động này không thể hoàn tác. Tiếp tục?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      default:
        return { title: '', message: '', btnClass: '' };
    }
  };

  const confirmContent = getConfirmContent();

  return (
    <div className="space-y-6 relative">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu</h2>

            {/* BULK ACTION BUTTON */}
            {selectedIds.size > 0 && (
                <button 
                    onClick={() => setConfirmAction({ type: 'bulk_cancel' })}
                    disabled={isBulkProcessing}
                    className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-all animate-fade-in-up shadow-md"
                >
                    {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4" />}
                    Hủy {selectedIds.size} mục
                </button>
            )}
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto shadow-inner">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200">
              <tr>
                <th className="px-6 py-4 w-10">
                    <input 
                        type="checkbox" 
                        onChange={toggleSelectAll}
                        checked={requests.length > 0 && requests.some(r => r.status === 'pending') && requests.filter(r => r.status === 'pending').every(r => selectedIds.has(r.id))}
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                        disabled={!requests.some(r => r.status === 'pending')}
                    />
                </th>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : requests.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500 italic">Không có yêu cầu nào.</td></tr>
              ) : (
                requests.map((req) => (
                  <tr key={req.id} className={`transition-colors ${selectedIds.has(req.id) ? 'bg-blue-50/70' : 'hover:bg-blue-50/30'}`}>
                    <td className="px-6 py-4">
                        {req.status === 'pending' ? (
                            <input 
                                type="checkbox" 
                                checked={selectedIds.has(req.id)}
                                onChange={() => toggleSelection(req.id)}
                                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                            />
                        ) : (
                             <span className="block w-4 h-4"></span>
                        )}
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-800">{req.tool_name}</td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                        req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                        req.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                        'bg-yellow-50 text-yellow-700 border-yellow-200'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'returned' && <RotateCcw className="w-3 h-3" />}
                         {req.status === 'rejected' && <X className="w-3 h-3" />}

                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap" 
                                            title="Phê duyệt"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />} 
                                            Duyệt
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50 whitespace-nowrap" 
                                            title="Từ chối"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5" />} 
                                            Từ chối
                                        </button>
                                    </>
                                )}

                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap"
                                        title="Xác nhận đã trả"
                                    >
                                        {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />} 
                                        Đã trả
                                    </button>
                                )}
                            </>
                        )}

                        {/* User Actions */}
                        {(user.role !== 'admin' || activeTab === 'personal') && (
                            <>
                                {req.status === 'pending' ? (
                                    <button 
                                        onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors whitespace-nowrap"
                                    >
                                        {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                                        Hủy
                                    </button>
                                ) : (
                                    <span className="text-xs text-gray-400 italic min-w-[60px] inline-block text-center">
                                        {req.status === 'returned' ? 'Hoàn tất' : '-'}
                                    </span>
                                )}
                            </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* CONFIRMATION MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">{confirmContent.title}</h3>
              <p className="text-sm text-center text-gray-500">{confirmContent.message}</p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setConfirmAction(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`px-4 py-2 text-white font-medium rounded-lg text-sm shadow-md transition-colors ${confirmContent.btnClass}`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { Wrench, PlusCircle, CheckCircle, MapPin, AlertCircle, Trash2, Edit, Plus, X, Save, Image as ImageIcon, LayoutGrid, List, ChevronLeft, ChevronRight, CheckSquare, Loader2, Minus, AlertTriangle } from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ITEMS_PER_PAGE = 20;

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-100 text-gray-300 w-full h-full ${className}`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2' : 'w-5 h-5'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && (
        <div className="absolute inset-0 bg-gray-50 animate-pulse" />
      )}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-all duration-500 ${loaded ? 'opacity-100 scale-100' : 'opacity-0 scale-95'} ${mode === 'grid' ? 'p-4 group-hover:scale-110' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);

  // Bulk Action State
  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({}); // Lưu số lượng chọn cho từng tool
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // State cho Admin CRUD
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);

  // State xóa
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
    if (error) console.error(error);
  };

  // --- Logic Phân trang ---
  const totalPages = Math.ceil(tools.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentTools = tools.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
    }
  };

  // --- Logic Select & Quantity ---
  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        // Xóa quantity khi bỏ chọn
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        // Mặc định quantity = 1 khi mới chọn
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const updateQuantity = (id: string, delta: number, max: number) => {
      setQuantities(prev => {
          const current = prev[id] || 1;
          const newVal = Math.max(1, Math.min(max, current + delta));
          return { ...prev, [id]: newVal };
      });
  };

  const toggleSelectAll = () => {
    const selectableTools = currentTools.filter(isSelectable);
    const selectableIds = selectableTools.map(t => t.id);
    const allSelected = selectableIds.every(id => selectedToolIds.has(id));

    const newSet = new Set(selectedToolIds);
    const newQties = {...quantities};

    if (allSelected) {
        selectableIds.forEach(id => {
            newSet.delete(id);
            delete newQties[id];
        });
    } else {
        selectableIds.forEach(id => {
            newSet.add(id);
            if (!newQties[id]) newQties[id] = 1;
        });
    }
    setSelectedToolIds(newSet);
    setQuantities(newQties);
  };

  // --- Logic Mượn ---
  const handleBorrow = async (tool: Tool) => {
    setProcessingId(tool.id);
    setMessage(null);

    const { error } = await supabase.from('requests').insert([{
      employee_id: user.employeeCode,
      user_id: user.id,
      user_name: user.name,
      tool_id: tool.id,
      tool_name: tool.name,
      borrow_date: new Date().toISOString(),
      status: 'pending'
    }]);

    if (!error) {
       setMessage(`Đã gửi yêu cầu mượn: ${tool.name}`);
       setTimeout(() => setMessage(null), 3000);
    } else {
       console.error(error);
       alert('Có lỗi xảy ra khi gửi yêu cầu.');
    }
    setProcessingId(null);
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));

    // Tạo mảng requests dựa trên số lượng đã chọn
    const requests: any[] = [];

    toolsToBorrow.forEach(tool => {
        const qty = quantities[tool.id] || 1;
        // Tạo N request cho số lượng N
        for(let i = 0; i < qty; i++) {
            requests.push({
                employee_id: user.employeeCode,
                user_id: user.id,
                user_name: user.name,
                tool_id: tool.id,
                tool_name: tool.name,
                borrow_date: new Date().toISOString(), // Dùng cùng timestamp
                status: 'pending'
            });
        }
    });

    const { error } = await supabase.from('requests').insert(requests);

    if (!error) {
        setMessage(`Đã gửi thành công ${requests.length} yêu cầu mượn (cho ${selectedToolIds.size} thiết bị).`);
        setSelectedToolIds(new Set()); // Reset
        setQuantities({});
        setTimeout(() => setMessage(null), 4000);
    } else {
        alert('Có lỗi xảy ra: ' + error.message);
    }
    setIsBulkProcessing(false);
  };

  // --- Logic Admin CRUD ---
  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const confirmDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete);
      if (error) throw error;
      const newTools = tools.filter(t => t.id !== toolToDelete);
      setTools(newTools);
      if (currentPage > Math.ceil(newTools.length / ITEMS_PER_PAGE)) {
        setCurrentPage(Math.max(1, currentPage - 1));
      }
      setMessage('Đã xóa công cụ thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    } finally {
        setToolToDelete(null);
    }
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  // Helper tính tổng số lượng đang chọn để hiển thị trên nút Mượn
  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)]">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800">Kho công cụ</h2>
            <div className="flex items-center gap-3">
                <p className="text-sm text-gray-500 mt-1">Tổng cộng: {tools.length} thiết bị</p>
                {selectedToolIds.size > 0 && (
                    <button 
                        onClick={handleBulkBorrow}
                        disabled={isBulkProcessing}
                        className="ml-2 flex items-center gap-1.5 px-3 py-1 bg-blue-600 text-white rounded-lg text-xs font-bold hover:bg-blue-700 transition-all shadow-md animate-fade-in-up"
                    >
                        {isBulkProcessing ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <CheckSquare className="w-3.5 h-3.5" />}
                        Mượn {totalItemsSelected} món
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col sm:flex-row items-center gap-3 w-full sm:w-auto">
            {message && (
            <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce text-sm">
                <CheckCircle className="w-4 h-4" />
                {message}
            </div>
            )}

            <div className="flex items-center gap-2 bg-white p-1 rounded-lg border border-gray-200 shadow-sm">
              <button 
                onClick={() => setViewMode('grid')}
                className={`p-2 rounded-md transition-all ${viewMode === 'grid' ? 'bg-blue-50 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                title="Dạng lưới"
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setViewMode('table')}
                className={`p-2 rounded-md transition-all ${viewMode === 'table' ? 'bg-blue-50 text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                title="Dạng bảng"
              >
                <List className="w-4 h-4" />
              </button>
            </div>

            {isAdmin && (
                <button 
                    onClick={handleAddNew}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-md w-full sm:w-auto justify-center"
                >
                    <Plus className="w-4 h-4" />
                    Thêm công cụ
                </button>
            )}
        </div>
      </div>

      <div className="flex-1">
        {/* VIEW MODE: GRID */}
        {viewMode === 'grid' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-lg transition-all relative overflow-hidden group flex flex-col h-full p-0 border ${isSelected ? 'border-blue-500 ring-2 ring-blue-100' : 'border-gray-200'}`}>

                    {/* Phần hiển thị hình ảnh */}
                    <div className="h-48 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />

                      {/* Checkbox Select */}
                      {selectable && (
                          <div className="absolute top-2 left-2 z-20" onClick={(e) => e.stopPropagation()}>
                               <input 
                                    type="checkbox"
                                    checked={isSelected}
                                    onChange={() => toggleSelection(tool.id)}
                                    className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer shadow-sm"
                               />
                          </div>
                      )}

                      {/* Badge trạng thái */}
                      <div className="absolute top-2 right-2">
                        {tool.status === 'inactive' ? (
                          <span className="bg-red-100 text-red-800 text-xs px-2 py-1 rounded-full font-medium">Bảo trì</span>
                        ) : tool.available > 0 ? (
                          <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded-full font-medium shadow-sm">
                            Sẵn: {tool.available}
                          </span>
                        ) : (
                          <span className="bg-gray-100 text-gray-800 text-xs px-2 py-1 rounded-full font-medium">Hết hàng</span>
                        )}
                      </div>

                      {/* Quantity Selector Overlay (Khi chọn) */}
                      {isSelected && (
                          <div className="absolute bottom-2 left-0 right-0 flex justify-center z-20 animate-fade-in-up">
                              <div className="bg-white/90 backdrop-blur shadow-md rounded-lg flex items-center border border-blue-200 overflow-hidden" onClick={(e) => e.stopPropagation()}>
                                  <button 
                                    onClick={() => updateQuantity(tool.id, -1, tool.available)}
                                    className="px-3 py-1 hover:bg-blue-50 text-blue-600 border-r border-gray-200"
                                    disabled={qty <= 1}
                                  >
                                      <Minus className="w-3 h-3" />
                                  </button>
                                  <span className="w-8 text-center text-sm font-bold text-blue-700">{qty}</span>
                                  <button 
                                    onClick={() => updateQuantity(tool.id, 1, tool.available)}
                                    className="px-3 py-1 hover:bg-blue-50 text-blue-600 border-l border-gray-200"
                                    disabled={qty >= tool.available}
                                  >
                                      <Plus className="w-3 h-3" />
                                  </button>
                              </div>
                          </div>
                      )}
                    </div>

                    <div className="p-4 flex-1 flex flex-col">
                      <div className="flex justify-between items-start mb-2">
                        <div>
                          <h3 className="font-bold text-gray-800 text-base line-clamp-1" title={tool.name}>{tool.name}</h3>
                          <p className="text-xs text-gray-500">{tool.category}</p>
                        </div>
                      </div>

                      {tool.location && (
                        <div className="flex items-center gap-1 text-xs text-gray-500 mb-3">
                          <MapPin className="w-3 h-3" />
                          {tool.location}
                        </div>
                      )}

                      <div className="mt-auto pt-4 flex gap-2">
                        {isAdmin ? (
                          <>
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-gray-100 hover:bg-gray-200 text-gray-700 py-2 rounded-lg text-xs font-medium transition-colors flex items-center justify-center gap-1">
                                <Edit className="w-3 h-3" /> Sửa
                             </button>
                             <button onClick={() => setToolToDelete(tool.id)} className="flex-1 bg-red-50 hover:bg-red-100 text-red-600 py-2 rounded-lg text-xs font-medium transition-colors flex items-center justify-center gap-1">
                                <Trash2 className="w-3 h-3" /> Xóa
                             </button>
                          </>
                        ) : (
                          // Nếu đã chọn thì ẩn nút Mượn lẻ để tránh rối, chỉ hiển thị trạng thái
                          isSelected ? (
                              <div className="w-full bg-blue-50 text-blue-600 py-2 rounded-lg text-sm font-medium flex items-center justify-center border border-blue-200">
                                  Đã chọn {qty}
                              </div>
                          ) : (
                              <button
                                onClick={() => handleBorrow(tool)}
                                disabled={processingId === tool.id || tool.available === 0 || tool.status === 'inactive'}
                                className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                              >
                                {processingId === tool.id ? <Loader2 className="w-4 h-4 animate-spin"/> : 'Mượn ngay'}
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            })}
            </div>
        )}

        {/* VIEW MODE: TABLE */}
        {viewMode === 'table' && (
          <Card className="p-0 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm text-gray-600">
                <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs">
                  <tr>
                    <th className="px-6 py-4 w-10">
                        {/* Select All Checkbox */}
                        <input 
                            type="checkbox"
                            checked={currentTools.some(isSelectable) && currentTools.filter(isSelectable).every(t => selectedToolIds.has(t.id))}
                            onChange={toggleSelectAll}
                            className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                            disabled={!currentTools.some(isSelectable)}
                        />
                    </th>
                    <th className="px-6 py-4 w-16">Hình</th>
                    <th className="px-6 py-4">Tên thiết bị</th>
                    <th className="px-6 py-4">Danh mục</th>
                    <th className="px-6 py-4 text-center">Tồn kho</th>
                    <th className="px-6 py-4 text-center">Sẵn có</th>
                    <th className="px-6 py-4">Vị trí</th>
                    <th className="px-6 py-4">Trạng thái</th>
