import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, AlertTriangle, Loader2 } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

// Component thông báo nổi (Toast)
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${bgClass} text-white px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-fade-in-up max-w-sm`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-medium">{message}</p>
      <button onClick={onClose} className="ml-auto p-1 hover:bg-white/20 rounded">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

// Loại hành động cần xác nhận
type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | { type: 'bulk_cancel' }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // State cho Bulk Actions
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // State cho Confirmation Dialog
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
      setSelectedIds(new Set()); // Reset selection khi reload
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const parseQuantity = (val: any) => {
    const num = parseInt(val);
    return isNaN(num) ? 0 : num;
  };

  // --- BULK ACTIONS ---
  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    // Chỉ select những đơn Pending (có thể huỷ)
    const pendingIds = requests.filter(r => r.status === 'pending').map(r => r.id);

    if (selectedIds.size === pendingIds.length && pendingIds.length > 0) {
        setSelectedIds(new Set());
    } else {
        setSelectedIds(new Set(pendingIds));
    }
  };

  const executeBulkCancel = async () => {
    if (selectedIds.size === 0) return;
    showToast(`Đang hủy ${selectedIds.size} yêu cầu...`, 'info');
    setIsBulkProcessing(true);

    try {
        const idsArray = Array.from(selectedIds);
        const { error } = await supabase
            .from('requests')
            .delete()
            .in('id', idsArray);

        if (error) throw new Error(error.message);

        showToast(`Đã hủy thành công ${selectedIds.size} yêu cầu.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi hủy hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  // --- SINGLE ACTIONS ---

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn mượn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);

    try {
      const { data: tools, error: toolError } = await supabase.from('tools').select('*').eq('id', req.tool_id);
      if (toolError || !tools || tools.length === 0) throw new Error("Lỗi đọc kho.");

      const tool = tools[0];
      const currentAvailable = parseQuantity(tool.available);

      if (currentAvailable <= 0) throw new Error(`Kho đã hết.`);

      const { error: updateToolError } = await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id).select();
      if (updateToolError) throw new Error(`Lỗi cập nhật kho.`);

      const { error: updateReqError, data: updatedReq } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id).select();

      if (!updatedReq || updatedReq.length === 0) {
           await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
           throw new Error("Lỗi quyền hạn (RLS).");
      }

      if (updateReqError) {
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error(`Lỗi duyệt đơn: ${updateReqError.message}`);
      }

      showToast(`Đã duyệt: ${req.tool_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Thất bại: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang từ chối yêu cầu...', 'info');
    setProcessingId(req.id);
    try {
        const { error, data } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn (RLS).");
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang xử lý trả đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
        const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const { error, data } = await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn.");
        showToast('Đã xác nhận trả đồ.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy yêu cầu...', 'info');
    setProcessingId(id);

    const { error } = await supabase.from('requests').delete().eq('id', id);

    if (error) {
        showToast("Lỗi hủy đơn: " + error.message, 'error');
    } else {
        showToast("Đã hủy yêu cầu.", 'success');
        if (selectedIds.has(id)) {
            const newSet = new Set(selectedIds);
            newSet.delete(id);
            setSelectedIds(newSet);
        }
        await fetchRequests();
    }
    setProcessingId(null);
  };

  // Hàm điều phối xác nhận
  const handleConfirmAction = async () => {
    if (!confirmAction) return;

    setConfirmAction(null); // Đóng modal trước khi thực hiện

    switch (confirmAction.type) {
      case 'approve':
        await executeApprove(confirmAction.req);
        break;
      case 'reject':
        await executeReject(confirmAction.req);
        break;
      case 'return':
        await executeReturn(confirmAction.req);
        break;
      case 'cancel':
        await executeCancel(confirmAction.id);
        break;
      case 'bulk_cancel':
        await executeBulkCancel();
        break;
    }
  };

  // Helper để lấy nội dung modal
  const getConfirmContent = () => {
    if (!confirmAction) return { title: '', message: '', btnClass: '' };

    switch (confirmAction.type) {
      case 'approve':
        return {
          title: 'Duyệt yêu cầu',
          message: `Bạn có chắc chắn muốn DUYỆT yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-green-600 hover:bg-green-700'
        };
      case 'reject':
        return {
          title: 'Từ chối yêu cầu',
          message: `Bạn có chắc chắn muốn TỪ CHỐI yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'return':
        return {
          title: 'Xác nhận trả đồ',
          message: `Xác nhận nhân viên ${confirmAction.req.user_name} đã trả lại "${confirmAction.req.tool_name}"?`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      case 'cancel':
        return {
          title: 'Hủy yêu cầu',
          message: 'Hành động này không thể hoàn tác. Bạn có chắc chắn muốn hủy yêu cầu này?',
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_cancel':
        return {
          title: 'Hủy hàng loạt',
          message: `Bạn đang chọn hủy ${selectedIds.size} yêu cầu. Hành động này không thể hoàn tác. Tiếp tục?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      default:
        return { title: '', message: '', btnClass: '' };
    }
  };

  const confirmContent = getConfirmContent();

  return (
    <div className="space-y-6 relative">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu</h2>

            {/* BULK ACTION BUTTON */}
            {selectedIds.size > 0 && (
                <button 
                    onClick={() => setConfirmAction({ type: 'bulk_cancel' })}
                    disabled={isBulkProcessing}
                    className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-all animate-fade-in-up shadow-md"
                >
                    {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4" />}
                    Hủy {selectedIds.size} mục
                </button>
            )}
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto shadow-inner">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="px-6 py-4 w-10">
                    <input 
                        type="checkbox" 
                        onChange={toggleSelectAll}
                        checked={requests.length > 0 && requests.some(r => r.status === 'pending') && requests.filter(r => r.status === 'pending').every(r => selectedIds.has(r.id))}
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                        disabled={!requests.some(r => r.status === 'pending')}
                    />
                </th>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : requests.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500 italic">Không có yêu cầu nào.</td></tr>
              ) : (
                requests.map((req) => (
                  <tr key={req.id} className={`transition-colors ${selectedIds.has(req.id) ? 'bg-blue-50/70' : 'hover:bg-blue-50/30'}`}>
                    <td className="px-6 py-4">
                        {req.status === 'pending' ? (
                            <input 
                                type="checkbox" 
                                checked={selectedIds.has(req.id)}
                                onChange={() => toggleSelection(req.id)}
                                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                            />
                        ) : (
                             <span className="block w-4 h-4"></span>
                        )}
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-800">{req.tool_name}</td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                        req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                        req.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                        'bg-yellow-50 text-yellow-700 border-yellow-200'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'returned' && <RotateCcw className="w-3 h-3" />}
                         {req.status === 'rejected' && <X className="w-3 h-3" />}

                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {/* Admin Action Group (Only in All Tab) */}
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap" 
                                            title="Phê duyệt"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />} 
                                            Duyệt
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50 whitespace-nowrap" 
                                            title="Từ chối"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5" />} 
                                            Từ chối
                                        </button>
                                    </>
                                )}

                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap"
                                        title="Xác nhận đã trả"
                                    >
                                        {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />} 
                                        Đã trả
                                    </button>
                                )}
                            </>
                        )}

                        {/* Nút Hủy cho chính chủ (kể cả admin khi mượn đồ) */}
                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                disabled={processingId === req.id}
                                className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors whitespace-nowrap"
                            >
                                {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                                Hủy yêu cầu
                            </button>
                        )}

                        {/* Status text if nothing else */}
                        {(user.role !== 'admin' || activeTab === 'personal') && req.status !== 'pending' && (
                            <span className="text-xs text-gray-400 italic min-w-[60px] inline-block text-center">
                                {req.status === 'returned' ? 'Hoàn tất' : '-'}
                            </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* CONFIRMATION MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">{confirmContent.title}</h3>
              <p className="text-sm text-center text-gray-500">{confirmContent.message}</p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setConfirmAction(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`px-4 py-2 text-white font-medium rounded-lg text-sm shadow-md transition-colors ${confirmContent.btnClass}`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { History, Search, Calendar, Filter, X, User as UserIcon, ShieldCheck, ChevronDown } from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

// Mở rộng interface local để hứng thêm field người xử lý từ DB
interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | '7days' | '30days' | 'thisMonth';

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  const fetchHistory = async () => {
    setLoading(true);
    let query = supabase
      .from('requests')
      .select('*')
      .order('borrow_date', { ascending: false });

    // Nếu không phải admin, chỉ xem lịch sử của chính mình
    if (user.role !== 'admin') {
      query = query.eq('user_id', user.id);
    }

    // Lọc theo trạng thái (Server-side)
    if (statusFilter !== 'all') {
      query = query.eq('status', statusFilter);
    }

    // Lọc theo ngày (Server-side filter)
    if (startDate) {
      query = query.gte('borrow_date', `${startDate}T00:00:00`);
    }
    if (endDate) {
      query = query.lte('borrow_date', `${endDate}T23:59:59`);
    }

    const { data, error } = await query;
    if (data) {
      setLogs(data as ExtendedBorrowRequest[]);
    }
    if (error) console.error(error);
    setLoading(false);
  };

  useEffect(() => {
    fetchHistory();
  }, [user, startDate, endDate, statusFilter]); // Reload khi các filter thay đổi

  // Lọc Client-side cho Text Search (Tên, Mã NV, Công cụ) - Vì Supabase text search cần cấu hình phức tạp hơn
  const filteredLogs = logs.filter(log => {
    const searchLower = searchText.toLowerCase();
    return (
      log.user_name.toLowerCase().includes(searchLower) ||
      log.employee_id.toLowerCase().includes(searchLower) ||
      log.tool_name.toLowerCase().includes(searchLower)
    );
  });

  // Logic chọn nhanh ngày
  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'today':
            // start = end = today
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'custom':
            return; // Giữ nguyên giá trị hiện tại hoặc reset nếu muốn
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
  };

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Admin';
    if (req.status === 'rejected') return req.rejected_by || 'Admin';
    return '-';
  };

  return (
    <div className="space-y-6">
       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-purple-100 rounded-lg text-purple-600">
                    <History className="w-6 h-6" />
                </div>
                <div>
                    <h2 className="text-2xl font-bold text-gray-800">Lịch sử hoạt động</h2>
                    <p className="text-sm text-gray-500">
                        {user.role === 'admin' ? 'Theo dõi toàn bộ lịch sử mượn trả của hệ thống' : 'Theo dõi lịch sử mượn trả của bạn'}
                    </p>
                </div>
            </div>
       </div>

       <Card className="p-0 overflow-hidden">
            {/* Toolbar Bộ lọc Nâng cao */}
            <div className="p-4 bg-gray-50 border-b border-gray-200 space-y-4">

                {/* Hàng 1: Quick Actions */}
                <div className="flex flex-wrap items-center gap-2">
                    <span className="text-xs font-semibold text-gray-500 uppercase mr-2">Thời gian:</span>
                    <button 
                        onClick={() => handleQuickDate('today')}
                        className={`px-3 py-1 text-xs font-medium rounded-full transition-colors border ${quickDate === 'today' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-100'}`}
                    >
                        Hôm nay
                    </button>
                    <button 
                        onClick={() => handleQuickDate('7days')}
                        className={`px-3 py-1 text-xs font-medium rounded-full transition-colors border ${quickDate === '7days' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-100'}`}
                    >
                        7 ngày qua
