                            <span className="inline-block text-xl font-bold text-blue-700 bg-blue-100 px-3 py-1 rounded-md min-w-[3rem] text-center shadow-sm border border-blue-200">
                                {tool.available}
                            </span>
                        </td>
                        <td className="px-6 py-4">{tool.location || '-'}</td>
                        <td className="px-6 py-4">
                          {tool.status === 'active' 
                            ? <span className="text-green-600 text-xs bg-green-100 px-2 py-1 rounded-full font-medium">Hoạt động</span> 
                            : <span className="text-red-600 text-xs bg-red-100 px-2 py-1 rounded-full font-medium">Bảo trì</span>}
                        </td>
                        <td className="px-6 py-4 text-right">
                            {isAdmin ? (
                                <div className="flex justify-end gap-2" onClick={(e) => e.stopPropagation()}>
                                    <button onClick={() => handleEditTool(tool)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded"><Edit className="w-4 h-4" /></button>
                                    <button onClick={() => setToolToDelete(tool.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            ) : (
                                isSelected ? (
                                    <div className="flex justify-end items-center" onClick={(e) => e.stopPropagation()}>
                                        <div className="flex items-center border border-blue-300 rounded-lg overflow-hidden bg-white shadow-sm z-10 relative">
                                            <button 
                                                type="button"
                                                onClick={(e) => {
                                                  e.preventDefault();
                                                  e.stopPropagation();
                                                  updateQuantity(tool.id, -1, tool.available);
                                                }}
                                                className="px-3 py-1.5 hover:bg-blue-100 text-blue-700 border-r border-blue-100 disabled:opacity-50 disabled:bg-gray-50 transition-colors"
                                                disabled={qty <= 1}
                                            >
                                                <Minus className="w-4 h-4" />
                                            </button>
                                            <span className="w-10 text-center text-sm font-bold text-blue-800 select-none">{qty}</span>
                                            <button 
                                                type="button"
                                                onClick={(e) => {
                                                  e.preventDefault();
                                                  e.stopPropagation();
                                                  updateQuantity(tool.id, 1, tool.available);
                                                }}
                                                className="px-3 py-1.5 hover:bg-blue-100 text-blue-700 border-l border-blue-100 disabled:opacity-50 disabled:bg-gray-50 transition-colors"
                                                disabled={qty >= Number(tool.available)}
                                            >
                                                <Plus className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button 
                                        onClick={(e) => {
                                          e.stopPropagation();
                                          handleBorrow(tool);
                                        }}
                                        disabled={processingId === tool.id || tool.available === 0 || tool.status === 'inactive'}
                                        className="text-blue-600 hover:text-blue-800 text-xs font-bold border border-blue-200 px-3 py-1.5 rounded hover:bg-blue-50 disabled:opacity-50 transition-colors whitespace-nowrap z-10 relative"
                                    >
                                        {processingId === tool.id ? '...' : 'Mượn'}
                                    </button>
                                )
                            )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
            <div className="mt-6 flex justify-center items-center gap-4">
                <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg border bg-white disabled:opacity-50 hover:bg-gray-50 text-gray-600"
                >
                    <ChevronLeft className="w-4 h-4" />
                </button>
                <span className="text-sm font-medium text-gray-600">Trang {currentPage} / {totalPages}</span>
                <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg border bg-white disabled:opacity-50 hover:bg-gray-50 text-gray-600"
                >
                    <ChevronRight className="w-4 h-4" />
                </button>
            </div>
        )}
      </div>

      {/* Modal Thêm/Sửa (Chỉ Admin) */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-fade-in-up">
