                              >
                                {processingId === tool.id ? <Loader2 className="w-4 h-4 animate-spin"/> : 'Mượn ngay'}
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            })}
            </div>
        )}

        {/* VIEW MODE: TABLE */}
        {viewMode === 'table' && (
          <Card className="p-0 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm text-gray-600">
