                </div>
                {formData.image && (
                    <div className="mt-2 w-full h-32 bg-gray-100 rounded border border-gray-200 flex items-center justify-center overflow-hidden">
                        <img src={formData.image} alt="Preview" className="h-full object-contain" onError={(e) => (e.currentTarget.style.display = 'none')} />
                    </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Mô tả chi tiết</label>
                <textarea 
                  value={formData.description}
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm h-24 resize-none"
                  placeholder="Thông tin thêm về thiết bị..."
