            </div>

            <div className="p-6 border-t bg-gray-50 flex justify-end gap-3 sticky bottom-0">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleSaveTool}
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 flex items-center gap-2"
              >
                <Save className="w-4 h-4" />
                {isEditing ? 'Lưu thay đổi' : 'Thêm mới'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Delete */}
      {toolToDelete && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">Xác nhận xóa</h3>
              <p className="text-sm text-center text-gray-500">
                Bạn có chắc chắn muốn xóa công cụ này? Hành động này không thể hoàn tác và sẽ xóa mọi dữ liệu liên quan.
              </p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setToolToDelete(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={confirmDeleteTool}
                className="px-4 py-2 bg-red-600 text-white font-medium rounded-lg hover:bg-red-700 text-sm shadow-md"
              >
                Xóa vĩnh viễn
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { History, Search, Calendar, Filter, X, User as UserIcon, ShieldCheck, ChevronDown, SlidersHorizontal } from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

// Mở rộng interface local để hứng thêm field người xử lý từ DB
interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | '7days' | '30days' | 'thisMonth';

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); // Lọc theo người xử lý
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  const fetchHistory = async () => {
    setLoading(true);
    let query = supabase
      .from('requests')
      .select('*')
      .order('borrow_date', { ascending: false });

    // Nếu không phải admin, chỉ xem lịch sử của chính mình
    if (user.role !== 'admin') {
      query = query.eq('user_id', user.id);
    }

    // Lọc theo trạng thái (Server-side)
    if (statusFilter !== 'all') {
      query = query.eq('status', statusFilter);
    }

    // Lọc theo ngày (Server-side filter)
    if (startDate) {
      query = query.gte('borrow_date', `${startDate}T00:00:00`);
    }
    if (endDate) {
      query = query.lte('borrow_date', `${endDate}T23:59:59`);
    }

    const { data, error } = await query;
    if (data) {
      setLogs(data as ExtendedBorrowRequest[]);
    }
    if (error) console.error(error);
    setLoading(false);
  };

  useEffect(() => {
    fetchHistory();
  }, [user, startDate, endDate, statusFilter]); // Reload khi các filter Server-side thay đổi

  // Helper lấy tên người xử lý
  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Admin';
    if (req.status === 'rejected') return req.rejected_by || 'Admin';
    return '-';
  };

  // Lọc Client-side kết hợp (Text Search + Handler)
  const filteredLogs = logs.filter(log => {
    const searchLower = searchText.toLowerCase();
    const handlerLower = handlerFilter.toLowerCase();

    // 1. Text Search: Tên người mượn, Mã NV, Tên công cụ
    const matchesText = 
      log.user_name.toLowerCase().includes(searchLower) ||
      log.employee_id.toLowerCase().includes(searchLower) ||
      log.tool_name.toLowerCase().includes(searchLower);

    // 2. Handler Filter: Tên người xử lý
    const currentHandler = getHandlerName(log).toLowerCase();
    const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);

    return matchesText && matchesHandler;
  });

  // Logic chọn nhanh ngày
  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'today':
            // start = end = today
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'custom':
            return; 
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setHandlerFilter('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
  };

  // Đếm số lượng filter đang active để hiển thị visual cue
  const activeFiltersCount = [
    searchText, 
    handlerFilter, 
    startDate, 
    endDate, 
    statusFilter !== 'all'
  ].filter(Boolean).length;

  return (
    <div className="space-y-6">
       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-purple-100 rounded-lg text-purple-600">
                    <History className="w-6 h-6" />
                </div>
                <div>
                    <h2 className="text-2xl font-bold text-gray-800">Lịch sử hoạt động</h2>
                    <p className="text-sm text-gray-500">
                        {user.role === 'admin' ? 'Theo dõi toàn bộ lịch sử mượn trả của hệ thống' : 'Theo dõi lịch sử mượn trả của bạn'}
                    </p>
                </div>
            </div>
       </div>

       <Card className="p-0 overflow-hidden border border-gray-200 shadow-md">
            <div className="p-5 space-y-5 bg-white">
                <div className="flex items-center justify-between">
                    <h3 className="text-sm font-bold text-gray-700 flex items-center gap-2 uppercase tracking-wide">
                        <SlidersHorizontal className="w-4 h-4" /> Bộ lọc tìm kiếm
                    </h3>
                    {activeFiltersCount > 0 && (
                        <button 
                            onClick={clearFilters}
                            className="text-xs text-red-600 hover:text-red-800 font-medium flex items-center gap-1 hover:underline"
                        >
                            <X className="w-3 h-3" /> Xóa {activeFiltersCount} bộ lọc
                        </button>
                    )}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                    {/* LEFT COLUMN: Date & Time */}
                    <div className="lg:col-span-5 space-y-3 border-r border-gray-100 pr-0 lg:pr-6">
                        <label className="block text-xs font-semibold text-gray-500">Khoảng thời gian</label>
                        <div className="flex flex-wrap gap-2 mb-3">
                             {/* Quick Actions Buttons */}
                             {[{id: 'today', l: 'Hôm nay'}, {id: '7days', l: '7 ngày'}, {id: '30days', l: '30 ngày'}, {id: 'thisMonth', l: 'Tháng này'}].map((btn) => (
                                <button
                                    key={btn.id}
                                    onClick={() => handleQuickDate(btn.id as QuickDateOption)}
                                    className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all border ${
                                        quickDate === btn.id 
                                        ? 'bg-blue-50 text-blue-700 border-blue-200 shadow-sm' 
                                        : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                                    }`}
                                >
                                    {btn.l}
                                </button>
                             ))}
                        </div>
                        <div className="flex items-center gap-3">
                            <div className="relative flex-1">
                                <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none">
                                    <Calendar className="w-3.5 h-3.5" />
                                </span>
                                <input 
                                    type="date" 
                                    value={startDate}
                                    onChange={(e) => handleManualDateChange('start', e.target.value)}
                                    className="w-full pl-8 pr-2 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                                />
                            </div>
                            <span className="text-gray-400">-</span>
                            <div className="relative flex-1">
                                <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none">
                                    <Calendar className="w-3.5 h-3.5" />
                                </span>
                                <input 
                                    type="date" 
                                    value={endDate}
                                    onChange={(e) => handleManualDateChange('end', e.target.value)}
                                    className="w-full pl-8 pr-2 py-2 text-sm border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                                />
                            </div>
                        </div>
                    </div>

                    {/* RIGHT COLUMN: Advanced Attributes */}
                    <div className="lg:col-span-7 space-y-3">
                         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-semibold text-gray-500 mb-1.5">Từ khóa chung</label>
                                <div className="relative">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                                    <input 
                                        type="text" 
                                        value={searchText}
                                        onChange={(e) => setSearchText(e.target.value)}
                                        placeholder="Tên người mượn, mã NV..." 
                                        className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-semibold text-gray-500 mb-1.5">Trạng thái đơn</label>
                                <div className="relative">
                                    <select
                                        value={statusFilter}
                                        onChange={(e) => setStatusFilter(e.target.value)}
                                        className="w-full pl-3 pr-8 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm appearance-none bg-white cursor-pointer"
                                    >
                                        <option value="all">Tất cả trạng thái</option>
                                        <option value="pending">⏳ Chờ duyệt</option>
                                        <option value="approved">✅ Đang mượn</option>
                                        <option value="returned">↩️ Đã trả</option>
                                        <option value="rejected">❌ Đã từ chối</option>
                                    </select>
                                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                                </div>
                            </div>
                         </div>

                         {/* Row 2: Handler Filter */}
                         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-semibold text-gray-500 mb-1.5">Người xử lý (Admin)</label>
                                <div className="relative">
                                    <ShieldCheck className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                                    <input 
                                        type="text" 
                                        value={handlerFilter}
                                        onChange={(e) => setHandlerFilter(e.target.value)}
                                        placeholder="Nhập tên người duyệt..." 
                                        className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
                                    />
                                </div>
                            </div>
                         </div>
                    </div>
                </div>
            </div>

            {/* Bảng Dữ liệu */}
            <div className="overflow-x-auto border-t border-gray-200">
                <table className="w-full text-left text-sm text-gray-600">
                    <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200">
                        <tr>
                            <th className="px-6 py-4">Người mượn</th>
                            <th className="px-6 py-4">Công cụ</th>
                            <th className="px-6 py-4">Ngày mượn</th>
                            <th className="px-6 py-4">Ngày trả</th>
                            <th className="px-6 py-4">Người xử lý</th>
                            <th className="px-6 py-4 text-center">Trạng thái</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 bg-white">
                        {loading ? (
                            <tr><td colSpan={6} className="p-10 text-center text-gray-500 flex flex-col items-center"><div className="w-6 h-6 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mb-2"></div>Đang tải dữ liệu...</td></tr>
                        ) : filteredLogs.length === 0 ? (
                            <tr><td colSpan={6} className="p-10 text-center text-gray-500 italic bg-gray-50/50">Không tìm thấy dữ liệu phù hợp với bộ lọc hiện tại.</td></tr>
                        ) : (
                            filteredLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-blue-50/30 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-blue-100 to-blue-200 text-blue-700 flex items-center justify-center text-sm font-bold shadow-sm border border-blue-200">
                                                {item.user_name ? item.user_name.charAt(0) : '?'}
                                            </div>
                                            <div>
                                                <div className="font-semibold text-gray-900">{item.user_name}</div>
                                                <div className="text-xs text-gray-500 font-mono bg-gray-100 px-1.5 py-0.5 rounded w-fit mt-0.5">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="font-medium text-gray-800">{item.tool_name}</span>
                                    </td>
                                    <td className="px-6 py-4 text-xs">
                                        <div className="text-gray-900 font-medium mb-0.5">{new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        <div className="text-gray-400 flex items-center gap-1"><History className="w-3 h-3"/> {new Date(item.borrow_date).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                    </td>
                                    <td className="px-6 py-4 text-xs">
                                        {item.returned_at ? (
                                            <>
                                                <div className="text-blue-700 font-medium mb-0.5">{new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                                <div className="text-blue-400">{new Date(item.returned_at).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                            </>
                                        ) : (
                                            <span className="text-gray-300 text-lg leading-none select-none">•</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        {item.status !== 'pending' ? (
                                            <div className="flex items-center gap-1.5 text-xs text-gray-700 bg-gray-100 border border-gray-200 px-2 py-1 rounded-md w-fit shadow-sm">
                                                <ShieldCheck className="w-3 h-3 text-gray-500" />
                                                <span className="font-medium">{getHandlerName(item)}</span>
                                            </div>
                                        ) : (
                                            <span className="text-gray-400 text-xs italic pl-1">Đang chờ...</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold border shadow-sm ${
                                            item.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                                            item.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                                            item.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                            'bg-yellow-50 text-yellow-700 border-yellow-200'
                                        }`}>
                                            {item.status === 'approved' ? 'Đang mượn' : 
                                            item.status === 'rejected' ? 'Đã từ chối' : 
                                            item.status === 'returned' ? 'Đã trả' : 'Chờ duyệt'}
                                        </span>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Footer Summary */}
            <div className="bg-gray-50 border-t border-gray-200 p-3 text-xs text-gray-500 flex justify-between px-6">
                <span>Hiển thị {filteredLogs.length} kết quả</span>
                <span>Cập nhật lúc: {new Date().toLocaleTimeString('vi-VN')}</span>
            </div>
       </Card>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, AlertTriangle, Loader2 } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

// Component thông báo nổi (Toast)
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${bgClass} text-white px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-fade-in-up max-w-sm`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-medium">{message}</p>
      <button onClick={onClose} className="ml-auto p-1 hover:bg-white/20 rounded">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

// Loại hành động cần xác nhận
type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | { type: 'bulk_cancel' }
  | { type: 'bulk_return' }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // State cho Bulk Actions
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // State cho Confirmation Dialog
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];

      // Sắp xếp Client-side: Approved lên đầu -> Pending -> Các trạng thái khác -> Sau đó theo ngày mới nhất
      fetchedData.sort((a, b) => {
          const getScore = (status: string) => {
              if (status === 'approved') return 3; // Ưu tiên cao nhất
              if (status === 'pending') return 2;
              return 1;
          };

          const scoreA = getScore(a.status);
          const scoreB = getScore(b.status);

          if (scoreA !== scoreB) {
              return scoreB - scoreA; // Descending score
          }

          // Nếu cùng status, sắp xếp theo ngày giảm dần
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(fetchedData);
      setSelectedIds(new Set()); // Reset selection khi reload
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const parseQuantity = (val: any) => {
    const num = parseInt(val);
    return isNaN(num) ? 0 : num;
  };

  // --- BULK ACTIONS ---
  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    // Select tất cả các item có thể tương tác (pending hoặc approved)
    const actionableIds = requests
        .filter(r => r.status === 'pending' || r.status === 'approved')
        .map(r => r.id);

    // Nếu đã chọn hết actionable items -> bỏ chọn tất cả
    // Ngược lại -> chọn tất cả actionable items
    const allSelected = actionableIds.every(id => selectedIds.has(id));

    if (allSelected && actionableIds.length > 0) {
        setSelectedIds(new Set());
    } else {
        setSelectedIds(new Set(actionableIds));
    }
  };

  const executeBulkCancel = async () => {
    // Chỉ lọc ra các item pending để hủy
    const idsToCancel = Array.from(selectedIds).filter(id => {
        const req = requests.find(r => r.id === id);
        return req?.status === 'pending';
    });

    if (idsToCancel.length === 0) return;

    showToast(`Đang hủy ${idsToCancel.length} yêu cầu...`, 'info');
    setIsBulkProcessing(true);

    try {
        const { error } = await supabase
            .from('requests')
            .delete()
            .in('id', idsToCancel);

        if (error) throw new Error(error.message);

        showToast(`Đã hủy thành công ${idsToCancel.length} yêu cầu.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi hủy hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const executeBulkReturn = async () => {
    // Chỉ lọc ra các item approved để trả
    const itemsToReturn = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved');

    if (itemsToReturn.length === 0) return;

    showToast(`Đang xử lý trả ${itemsToReturn.length} món...`, 'info');
    setIsBulkProcessing(true);

    try {
        // Thực hiện tuần tự để đảm bảo tính đúng đắn của tồn kho (có thể tối ưu bằng RPC nếu có)
        for (const req of itemsToReturn) {
            const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
            const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;

            // +1 Tồn kho
            await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);

            // Update status
            await supabase.from('requests')
                .update({ status: 'returned', returned_at: new Date().toISOString() })
                .eq('id', req.id);
        }

        showToast(`Đã trả thành công ${itemsToReturn.length} món đồ.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi trả hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  // --- SINGLE ACTIONS ---

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn mượn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);

    try {
      const { data: tools, error: toolError } = await supabase.from('tools').select('*').eq('id', req.tool_id);
      if (toolError || !tools || tools.length === 0) throw new Error("Lỗi đọc kho.");

      const tool = tools[0];
      const currentAvailable = parseQuantity(tool.available);

      if (currentAvailable <= 0) throw new Error(`Kho đã hết.`);

      const { error: updateToolError } = await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id).select();
      if (updateToolError) throw new Error(`Lỗi cập nhật kho.`);

      const { error: updateReqError, data: updatedReq } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id).select();

      if (!updatedReq || updatedReq.length === 0) {
           await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
           throw new Error("Lỗi quyền hạn (RLS).");
      }

      if (updateReqError) {
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error(`Lỗi duyệt đơn: ${updateReqError.message}`);
      }

      showToast(`Đã duyệt: ${req.tool_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Thất bại: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang từ chối yêu cầu...', 'info');
    setProcessingId(req.id);
    try {
        const { error, data } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn (RLS).");
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang xử lý trả đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
        const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const { error, data } = await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn.");
        showToast('Đã xác nhận trả đồ.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy yêu cầu...', 'info');
    setProcessingId(id);

    const { error } = await supabase.from('requests').delete().eq('id', id);

    if (error) {
        showToast("Lỗi hủy đơn: " + error.message, 'error');
    } else {
        showToast("Đã hủy yêu cầu.", 'success');
        if (selectedIds.has(id)) {
            const newSet = new Set(selectedIds);
            newSet.delete(id);
            setSelectedIds(newSet);
        }
        await fetchRequests();
    }
    setProcessingId(null);
  };

  // Hàm điều phối xác nhận
  const handleConfirmAction = async () => {
    if (!confirmAction) return;

    setConfirmAction(null); // Đóng modal trước khi thực hiện

    switch (confirmAction.type) {
      case 'approve':
        await executeApprove(confirmAction.req);
        break;
      case 'reject':
        await executeReject(confirmAction.req);
        break;
      case 'return':
        await executeReturn(confirmAction.req);
        break;
      case 'cancel':
        await executeCancel(confirmAction.id);
        break;
      case 'bulk_cancel':
        await executeBulkCancel();
        break;
      case 'bulk_return':
        await executeBulkReturn();
        break;
    }
  };

  // Helper để lấy nội dung modal
  const getConfirmContent = () => {
    if (!confirmAction) return { title: '', message: '', btnClass: '' };

    switch (confirmAction.type) {
      case 'approve':
        return {
          title: 'Duyệt yêu cầu',
          message: `Bạn có chắc chắn muốn DUYỆT yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-green-600 hover:bg-green-700'
        };
      case 'reject':
        return {
          title: 'Từ chối yêu cầu',
          message: `Bạn có chắc chắn muốn TỪ CHỐI yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'return':
        return {
          title: 'Xác nhận trả đồ',
          message: `Xác nhận nhân viên ${confirmAction.req.user_name} đã trả lại "${confirmAction.req.tool_name}"?`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      case 'cancel':
        return {
          title: 'Hủy yêu cầu',
          message: 'Hành động này không thể hoàn tác. Bạn có chắc chắn muốn hủy yêu cầu này?',
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_cancel':
        // Đếm số lượng pending được chọn
        const pendingCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'pending').length;
        return {
          title: 'Hủy hàng loạt',
          message: `Bạn đang chọn hủy ${pendingCount} yêu cầu đang chờ. Hành động này không thể hoàn tác. Tiếp tục?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_return':
        const approvedCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'approved').length;
        return {
          title: 'Trả đồ hàng loạt',
          message: `Xác nhận nhận lại ${approvedCount} món đồ đã chọn? Kho sẽ được cập nhật số lượng tương ứng.`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      default:
        return { title: '', message: '', btnClass: '' };
    }
  };

  const confirmContent = getConfirmContent();

  // Tính toán số lượng cho các nút Bulk Action
  const selectedPendingCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'pending').length;
  const selectedApprovedCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved').length;

  return (
    <div className="space-y-6 relative">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu</h2>

            {/* BULK ACTION BUTTONS */}
            <div className="flex gap-2">
                {selectedPendingCount > 0 && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_cancel' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4" />}
                        Hủy {selectedPendingCount} đơn
                    </button>
                )}

                {selectedApprovedCount > 0 && user.role === 'admin' && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_return' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RotateCcw className="w-4 h-4" />}
                        Trả {selectedApprovedCount} món
                    </button>
                )}
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto shadow-inner">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="px-6 py-4 w-10">
                    <input 
                        type="checkbox" 
                        onChange={toggleSelectAll}
                        // Check nếu có item actionable và tất cả actionable item đều đã được chọn
                        checked={
                            requests.some(r => r.status === 'pending' || r.status === 'approved') && 
                            requests.filter(r => r.status === 'pending' || r.status === 'approved').every(r => selectedIds.has(r.id))
                        }
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                        disabled={!requests.some(r => r.status === 'pending' || r.status === 'approved')}
                    />
                </th>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : requests.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500 italic">Không có yêu cầu nào.</td></tr>
              ) : (
                requests.map((req) => (
                  <tr key={req.id} className={`transition-colors ${selectedIds.has(req.id) ? 'bg-blue-50/70' : 'hover:bg-blue-50/30'}`}>
                    <td className="px-6 py-4">
                        {/* Chỉ hiện checkbox cho item có thể thao tác: Pending (để hủy) hoặc Approved (để trả) */}
                        {req.status === 'pending' || (req.status === 'approved' && user.role === 'admin') ? (
                            <input 
                                type="checkbox" 
                                checked={selectedIds.has(req.id)}
                                onChange={() => toggleSelection(req.id)}
                                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                            />
                        ) : (
                             <span className="block w-4 h-4"></span>
                        )}
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-800">{req.tool_name}</td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                        req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                        req.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                        'bg-yellow-50 text-yellow-700 border-yellow-200'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'returned' && <RotateCcw className="w-3 h-3" />}
                         {req.status === 'rejected' && <X className="w-3 h-3" />}

                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {/* Admin Action Group (Only in All Tab) */}
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap" 
                                            title="Phê duyệt"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />} 
                                            Duyệt
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50 whitespace-nowrap" 
                                            title="Từ chối"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5" />} 
                                            Từ chối
                                        </button>
                                    </>
                                )}

                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap"
                                        title="Xác nhận đã trả"
                                    >
                                        {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />} 
                                        Đã trả
                                    </button>
                                )}
                            </>
                        )}

                        {/* Nút Hủy cho chính chủ (kể cả admin khi mượn đồ) */}
                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                disabled={processingId === req.id}
                                className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors whitespace-nowrap"
                            >
                                {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                                Hủy yêu cầu
                            </button>
                        )}

                        {/* Status text if nothing else */}
                        {(user.role !== 'admin' || activeTab === 'personal') && req.status !== 'pending' && (
                            <span className="text-xs text-gray-400 italic min-w-[60px] inline-block text-center">
                                {req.status === 'returned' ? 'Hoàn tất' : '-'}
                            </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* CONFIRMATION MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">{confirmContent.title}</h3>
              <p className="text-sm text-center text-gray-500">{confirmContent.message}</p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setConfirmAction(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`px-4 py-2 text-white font-medium rounded-lg text-sm shadow-md transition-colors ${confirmContent.btnClass}`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { Wrench, PlusCircle, CheckCircle, MapPin, AlertCircle, Trash2, Edit, Plus, X, Save, Image as ImageIcon, LayoutGrid, List, ChevronLeft, ChevronRight, CheckSquare, Loader2, Minus, AlertTriangle, ShoppingCart, Send, PackagePlus, Settings2, Search, Filter } from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ITEMS_PER_PAGE = 20;

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full ${className} transition-colors`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2 text-gray-300' : 'w-5 h-5 text-gray-400'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-50 animate-pulse" />}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-all duration-500 ${loaded ? 'opacity-100 scale-100' : 'opacity-0 scale-95'} ${mode === 'grid' ? 'p-4 group-hover:scale-110' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);

  // --- FILTER STATES ---
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  // --- ADMIN & MODE STATE ---
  const isAdmin = user.role === 'admin';
  // Mặc định Admin vào là chế độ quản lý, User vào là chế độ mượn
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  // --- CART / SELECTION STATE ---
  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // --- CRUD STATE ---
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  // Reset trang về 1 khi thay đổi bộ lọc
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory, filterStatus]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
    if (error) console.error(error);
  };

  // --- FILTER LOGIC ---
  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      // 1. Search Text
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());

      // 2. Category
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;

      // 3. Status/Availability
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }

      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  // Lấy danh sách category duy nhất để tạo dropdown
  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  // --- PAGINATION ---
  const totalPages = Math.ceil(filteredTools.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentTools = filteredTools.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) setCurrentPage(newPage);
  };

  // --- SELECTION & QUANTITY LOGIC ---
  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); // Bỏ chọn nếu giảm về 0
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const toggleSelectAll = () => {
    const selectableTools = currentTools.filter(isSelectable);
    const selectableIds = selectableTools.map(t => t.id);
    const allSelected = selectableIds.every(id => selectedToolIds.has(id));

    const newSet = new Set(selectedToolIds);
    const newQties = {...quantities};

    if (allSelected) {
        selectableIds.forEach(id => {
            newSet.delete(id);
            delete newQties[id];
        });
    } else {
        selectableIds.forEach(id => {
            newSet.add(id);
            if (!newQties[id]) newQties[id] = 1;
        });
    }
    setSelectedToolIds(newSet);
    setQuantities(newQties);
  };

  const handleRowClick = (tool: Tool) => {
      if (isManageMode) return; // Chế độ quản lý không cho chọn nhanh bằng click row
      if (isSelectable(tool)) {
          toggleSelection(tool.id);
      }
  };

  // --- BORROW SUBMIT ---
  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
    const requests: any[] = [];

    toolsToBorrow.forEach(tool => {
        const qty = quantities[tool.id] || 1;
        for(let i = 0; i < qty; i++) {
            requests.push({
                employee_id: user.employeeCode,
                user_id: user.id,
                user_name: user.name,
                tool_id: tool.id,
                tool_name: tool.name,
                borrow_date: new Date().toISOString(),
                status: 'pending'
            });
        }
    });

    const { error } = await supabase.from('requests').insert(requests);

    if (!error) {
        setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
        setSelectedToolIds(new Set()); 
        setQuantities({});
        setTimeout(() => setMessage(null), 4000);
    } else {
        alert('Có lỗi xảy ra: ' + error.message);
    }
    setIsBulkProcessing(false);
  };

  // --- CRUD ACTIONS ---
  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const confirmDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete);
      if (error) throw error;
      const newTools = tools.filter(t => t.id !== toolToDelete);
      setTools(newTools);
      if (currentPage > Math.ceil(newTools.length / ITEMS_PER_PAGE)) {
        setCurrentPage(Math.max(1, currentPage - 1));
      }
      setMessage('Đã xóa công cụ thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    } finally {
        setToolToDelete(null);
    }
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32">
      {/* HEADER CONTROLS */}
      <div className="flex flex-col gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    Kho công cụ
                    {!isAdmin && <span className="text-xs font-normal text-gray-500 bg-gray-100 px-2 py-1 rounded-full">Chế độ Mượn</span>}
                </h2>
                <p className="text-sm text-gray-500 mt-1">Tổng cộng: {tools.length} thiết bị</p>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-3 w-full xl:w-auto">
                {message && (
                <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce text-sm shadow-sm whitespace-nowrap">
                    <CheckCircle className="w-4 h-4" />
                    {message}
                </div>
                )}

                {/* ADMIN MODE TOGGLE */}
                {isAdmin && (
                    <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-md text-xs font-bold transition-all ${isManageMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200'}`}
                        >
                            <Settings2 className="w-3.5 h-3.5" />
                            Quản lý
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-md text-xs font-bold transition-all ${!isManageMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200'}`}
                        >
                            <ShoppingCart className="w-3.5 h-3.5" />
                            Mượn đồ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-2 rounded-md transition-all ${viewMode === 'grid' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                    title="Dạng lưới"
                >
                    <LayoutGrid className="w-4 h-4" />
                </button>
                <button 
                    onClick={() => setViewMode('table')}
                    className={`p-2 rounded-md transition-all ${viewMode === 'table' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                    title="Dạng bảng"
                >
                    <List className="w-4 h-4" />
                </button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-md w-full sm:w-auto justify-center whitespace-nowrap"
                    >
                        <Plus className="w-4 h-4" />
                        Thêm mới
                    </button>
                )}
            </div>
        </div>

        {/* --- FILTER TOOLBAR --- */}
        <div className="flex flex-col md:flex-row gap-3 pt-4 border-t border-gray-100">
            {/* Search */}
            <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
                />
            </div>

            {/* Filter Group */}
            <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
                {/* Category Filter */}
                <div className="relative min-w-[150px]">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-3 pr-8 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                        ))}
                    </select>
                    <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 pointer-events-none" />
                </div>

                {/* Status Filter */}
                <div className="relative min-w-[150px]">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-3 pr-8 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Đang bảo trì</option>
                    </select>
                    <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 pointer-events-none" />
                </div>

                {/* Clear Filter */}
                {(searchTerm || filterCategory !== 'all' || filterStatus !== 'all') && (
                    <button 
                        onClick={() => { setSearchTerm(''); setFilterCategory('all'); setFilterStatus('all'); }}
                        className="px-3 py-2 text-red-500 hover:bg-red-50 rounded-lg text-sm font-medium transition-colors flex items-center gap-1 whitespace-nowrap"
                    >
                        <X className="w-4 h-4" /> Xóa lọc
                    </button>
                )}
            </div>
        </div>
      </div>

      <div className="flex-1">
        {/* === GRID VIEW === */}
        {viewMode === 'grid' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.length === 0 ? (
                <div className="col-span-full py-20 text-center text-gray-500 flex flex-col items-center">
                    <Search className="w-12 h-12 text-gray-200 mb-4" />
                    <p className="text-lg font-medium">Không tìm thấy công cụ nào</p>
                    <p className="text-sm">Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm</p>
                </div>
            ) : (
            currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-lg transition-all relative overflow-hidden group flex flex-col h-full p-0 border ${isSelected ? 'border-blue-500 ring-2 ring-blue-100' : 'border-gray-200'}`}>
                    {/* Image */}
                    <div className="h-48 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />

                      {/* Select Checkbox (Chỉ hiện khi không phải Manage Mode) */}
                      {!isManageMode && selectable && (
                          <div className="absolute top-2 left-2 z-20" onClick={(e) => e.stopPropagation()}>
                               <input 
                                    type="checkbox"
                                    checked={isSelected}
                                    onChange={() => toggleSelection(tool.id)}
                                    className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer shadow-md"
                               />
                          </div>
                      )}

                      <div className="absolute top-2 right-2">
                        {tool.status === 'inactive' ? (
                          <span className="bg-red-100 text-red-800 text-xs px-2 py-1 rounded-full font-medium shadow-sm">Bảo trì</span>
                        ) : tool.available > 0 ? (
                          <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded-full font-medium shadow-sm">
                            Sẵn: {tool.available}
                          </span>
                        ) : (
                          <span className="bg-gray-100 text-gray-800 text-xs px-2 py-1 rounded-full font-medium shadow-sm">Hết hàng</span>
                        )}
                      </div>
                    </div>

                    <div className="p-4 flex-1 flex flex-col">
                      <div className="flex justify-between items-start mb-2">
                        <div>
                          <h3 className="font-bold text-gray-800 text-base line-clamp-2 min-h-[3rem]" title={tool.name}>{tool.name}</h3>
                          <p className="text-xs text-gray-500 mt-1">{tool.category}</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-1 text-xs text-gray-500 mb-4">
                        <MapPin className="w-3 h-3" />
                        {tool.location || 'Chưa cập nhật vị trí'}
                      </div>

                      <div className="mt-auto">
                        {/* CONDITIONAL ACTIONS BASED ON MODE */}
                        {isManageMode ? (
                          <div className="flex gap-2">
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-gray-100 hover:bg-gray-200 text-gray-700 py-2 rounded-lg text-xs font-bold transition-colors flex items-center justify-center gap-1">
                                <Edit className="w-3.5 h-3.5" /> Sửa
                             </button>
                             <button onClick={() => setToolToDelete(tool.id)} className="flex-1 bg-red-50 hover:bg-red-100 text-red-600 py-2 rounded-lg text-xs font-bold transition-colors flex items-center justify-center gap-1">
                                <Trash2 className="w-3.5 h-3.5" /> Xóa
                             </button>
                          </div>
                        ) : (
                          // BORROW ACTIONS
                          isSelected ? (
                              <div className="flex items-center justify-between bg-blue-50 rounded-lg p-1 border border-blue-200 animate-in fade-in zoom-in duration-200">
                                  <button 
                                    onClick={(e) => { e.preventDefault(); changeQuantity(tool.id, -1, tool.available); }}
                                    className="w-8 h-8 flex items-center justify-center bg-white rounded shadow-sm text-blue-600 hover:text-blue-700 hover:bg-gray-50 transition-colors"
                                  >
                                      <Minus className="w-4 h-4" />
                                  </button>
                                  <span className="font-bold text-blue-700 text-lg">{qty}</span>
                                  <button 
                                    onClick={(e) => { e.preventDefault(); changeQuantity(tool.id, 1, tool.available); }}
                                    className="w-8 h-8 flex items-center justify-center bg-blue-600 rounded shadow-sm text-white hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:bg-gray-400"
                                    disabled={qty >= Number(tool.available)}
                                  >
                                      <Plus className="w-4 h-4" />
                                  </button>
                              </div>
                          ) : (
                              <button
                                onClick={() => toggleSelection(tool.id)}
