interface OvertimeRegistrationProps {
  user: User;
}

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState({ date: '', startTime: '17:30', endTime: '18:30', reason: '' });

  // Fetch dữ liệu từ Supabase khi component load
  useEffect(() => {
    fetchRequests();
  }, [user.id]);

  const fetchRequests = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('overtime_requests')
        .select('*')
        .eq('user_id', user.id)
        .order('date', { ascending: false });

      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (error) {
      console.error('Error fetching OT requests:', error);
    } finally {
      setLoading(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [startH, startM] = start.split(':').map(Number);
    const [endH, endM] = end.split(':').map(Number);
    const totalStart = startH * 60 + startM;
    const totalEnd = endH * 60 + endM;
    const diff = totalEnd - totalStart;
    return diff > 0 ? parseFloat((diff / 60).toFixed(2)) : 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const hours = calculateHours(formData.startTime, formData.endTime);
    if (hours <= 0) {
        alert("Thời gian kết thúc phải lớn hơn thời gian bắt đầu");
        return;
    }

    setIsSubmitting(true);
    try {
        const payload = {
            user_id: user.id,
            employee_id: user.employeeCode,
            date: formData.date,
            start_time: formData.startTime,
            end_time: formData.endTime,
            hours: hours,
            reason: formData.reason,
            status: 'pending'
        };

        const { error } = await supabase.from('overtime_requests').insert([payload]);

        if (error) throw error;

        // Reset form và reload lại danh sách
        setIsModalOpen(false);
        setFormData({ date: '', startTime: '17:30', endTime: '18:30', reason: '' });
        await fetchRequests();
        alert('Đăng ký tăng ca thành công!');

    } catch (error: any) {
        alert('Lỗi khi đăng ký: ' + error.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
      <div className="space-y-6">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                  <h2 className="text-2xl font-bold text-gray-800">Đăng ký Tăng ca</h2>
                  <p className="text-sm text-gray-500">Quản lý và đăng ký thời gian làm thêm giờ (OT)</p>
              </div>
              <button 
                  onClick={() => setIsModalOpen(true)}
                  className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-md"
              >
                  <Plus className="w-4 h-4" />
                  Đăng ký OT
              </button>
          </div>

          <Card className="p-0 overflow-hidden border border-gray-200 shadow-sm">
             <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-gray-600">
                    <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200">
                        <tr>
                            <th className="px-6 py-4">Ngày đăng ký</th>
                            <th className="px-6 py-4">Thời gian</th>
                            <th className="px-6 py-4 text-center">Tổng giờ</th>
                            <th className="px-6 py-4">Lý do</th>
                            <th className="px-6 py-4 text-center">Trạng thái</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 bg-white">
                        {loading ? (
                            <tr><td colSpan={5} className="p-8 text-center text-gray-500"><div className="flex justify-center items-center gap-2"><Loader2 className="w-4 h-4 animate-spin"/> Đang tải dữ liệu...</div></td></tr>
                        ) : requests.length === 0 ? (
                             <tr><td colSpan={5} className="p-8 text-center text-gray-500 italic">Chưa có dữ liệu đăng ký tăng ca.</td></tr>
                        ) : (
                            requests.map((req) => (
                                <tr key={req.id} className="hover:bg-gray-50 transition-colors">
                                    <td className="px-6 py-4 font-medium text-gray-900">
                                        <div className="flex items-center gap-2">
                                            <Calendar className="w-4 h-4 text-gray-400" />
                                            {new Date(req.date).toLocaleDateString('vi-VN')}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-1.5 text-xs bg-gray-100 w-fit px-2 py-1 rounded">
                                            <Clock className="w-3 h-3 text-gray-500" />
                                            {req.start_time} - {req.end_time}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className="font-bold text-blue-600">{req.hours}h</span>
                                    </td>
                                    <td className="px-6 py-4 max-w-xs truncate" title={req.reason}>{req.reason}</td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium border ${
                                            req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                                            req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                                            'bg-yellow-50 text-yellow-700 border-yellow-200'
                                        }`}>
                                            {req.status === 'approved' ? <CheckCircle2 className="w-3 h-3"/> : req.status === 'pending' ? <Timer className="w-3 h-3"/> : <AlertCircle className="w-3 h-3"/>}
                                            {req.status === 'approved' ? 'Đã duyệt' : req.status === 'rejected' ? 'Từ chối' : 'Chờ duyệt'}
                                        </span>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
             </div>
          </Card>

          {/* Register Modal */}
          {isModalOpen && (
              <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                  <div className="bg-white rounded-xl shadow-xl w-full max-w-md animate-fade-in-up">
                      <div className="flex justify-between items-center p-6 border-b">
                          <h3 className="text-lg font-bold text-gray-900">Đăng ký làm thêm giờ</h3>
                          <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                              <X className="w-5 h-5" />
                          </button>
                      </div>

                      <form onSubmit={handleSubmit}>
                        <div className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Ngày làm việc</label>
                                <input 
                                    type="date" 
                                    required
                                    value={formData.date}
                                    onChange={(e) => setFormData({...formData, date: e.target.value})}
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Bắt đầu</label>
                                    <input 
                                        type="time" 
                                        required
                                        value={formData.startTime}
                                        onChange={(e) => setFormData({...formData, startTime: e.target.value})}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1">Kết thúc</label>
                                    <input 
                                        type="time" 
                                        required
                                        value={formData.endTime}
                                        onChange={(e) => setFormData({...formData, endTime: e.target.value})}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-sm"
                                    />
                                </div>
                            </div>

                            <div className="bg-blue-50 p-3 rounded-lg flex justify-between items-center">
                                <span className="text-sm text-blue-800 font-medium">Tổng số giờ dự kiến:</span>
                                <span className="text-lg font-bold text-blue-700">
                                    {calculateHours(formData.startTime, formData.endTime)}h
                                </span>
                            </div>

                            <div>
