import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, AlertTriangle, Loader2, Search, Filter, Calendar, Wrench } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

// Mở rộng interface để chứa thông tin ảnh
interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

// Component thông báo nổi (Toast)
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${bgClass} text-white px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-fade-in-up max-w-sm`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-medium">{message}</p>
      <button onClick={onClose} className="ml-auto p-1 hover:bg-white/20 rounded">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

// Loại hành động cần xác nhận
type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | { type: 'bulk_cancel' }
  | { type: 'bulk_return' }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // --- FILTER STATES ---
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');

  // State cho Bulk Actions
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // State cho Confirmation Dialog
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];

      // Lấy danh sách tool_id duy nhất để fetch ảnh
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      // Fetch thông tin ảnh từ bảng tools
      const { data: toolsData } = await supabase
        .from('tools')
        .select('id, image')
        .in('id', toolIds);

      // Tạo map id -> image
      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      // Merge ảnh vào request
      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      // Sắp xếp Client-side: Approved lên đầu -> Pending -> Các trạng thái khác -> Sau đó theo ngày mới nhất
      enrichedData.sort((a, b) => {
          const getScore = (status: string) => {
              if (status === 'approved') return 3; // Ưu tiên cao nhất
              if (status === 'pending') return 2;
              return 1;
          };

          const scoreA = getScore(a.status);
          const scoreB = getScore(b.status);

          if (scoreA !== scoreB) {
              return scoreB - scoreA; // Descending score
          }

          // Nếu cùng status, sắp xếp theo ngày giảm dần
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
      setSelectedIds(new Set()); // Reset selection khi reload
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  // --- FILTER LOGIC ---
  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      // 1. Search Text (Name, ID, Tool Name)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      // 2. Status
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      // 3. Date Range
      let matchesDate = true;
      if (filterStartDate || filterEndDate) {
        const reqDate = new Date(req.borrow_date).setHours(0,0,0,0);
        if (filterStartDate) {
           matchesDate = matchesDate && reqDate >= new Date(filterStartDate).setHours(0,0,0,0);
        }
        if (filterEndDate) {
           matchesDate = matchesDate && reqDate <= new Date(filterEndDate).setHours(0,0,0,0);
        }
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate, filterEndDate]);

  const parseQuantity = (val: any) => {
    const num = parseInt(val);
    return isNaN(num) ? 0 : num;
  };

  // --- BULK ACTIONS ---
  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    // Chỉ select các item ĐANG HIỂN THỊ (filtered) có thể tương tác
    const actionableIds = filteredRequests
        .filter(r => r.status === 'pending' || r.status === 'approved')
        .map(r => r.id);

    const allSelected = actionableIds.length > 0 && actionableIds.every(id => selectedIds.has(id));

    if (allSelected) {
        // Bỏ chọn tất cả các item đang hiển thị
        const newSet = new Set(selectedIds);
        actionableIds.forEach(id => newSet.delete(id));
        setSelectedIds(newSet);
    } else {
        // Chọn tất cả các item đang hiển thị
        const newSet = new Set(selectedIds);
        actionableIds.forEach(id => newSet.add(id));
        setSelectedIds(newSet);
    }
  };

  const executeBulkCancel = async () => {
    // Chỉ lọc ra các item pending để hủy
    const idsToCancel = Array.from(selectedIds).filter(id => {
        const req = requests.find(r => r.id === id);
        return req?.status === 'pending';
    });

    if (idsToCancel.length === 0) return;

    showToast(`Đang hủy ${idsToCancel.length} yêu cầu...`, 'info');
    setIsBulkProcessing(true);

    try {
        const { error } = await supabase
            .from('requests')
            .delete()
            .in('id', idsToCancel);

        if (error) throw new Error(error.message);

        showToast(`Đã hủy thành công ${idsToCancel.length} yêu cầu.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi hủy hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const executeBulkReturn = async () => {
    // Chỉ lọc ra các item approved để trả
    const itemsToReturn = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved');

    if (itemsToReturn.length === 0) return;

    showToast(`Đang xử lý trả ${itemsToReturn.length} món...`, 'info');
    setIsBulkProcessing(true);

    try {
        // Thực hiện tuần tự để đảm bảo tính đúng đắn của tồn kho (có thể tối ưu bằng RPC nếu có)
        for (const req of itemsToReturn) {
            const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
            const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;

            // +1 Tồn kho
            await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);

            // Update status
            await supabase.from('requests')
                .update({ status: 'returned', returned_at: new Date().toISOString() })
                .eq('id', req.id);
        }

        showToast(`Đã trả thành công ${itemsToReturn.length} món đồ.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi trả hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  // --- SINGLE ACTIONS ---

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn mượn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);

    try {
      const { data: tools, error: toolError } = await supabase.from('tools').select('*').eq('id', req.tool_id);
      if (toolError || !tools || tools.length === 0) throw new Error("Lỗi đọc kho.");

      const tool = tools[0];
      const currentAvailable = parseQuantity(tool.available);

      if (currentAvailable <= 0) throw new Error(`Kho đã hết.`);

      const { error: updateToolError } = await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id).select();
      if (updateToolError) throw new Error(`Lỗi cập nhật kho.`);

      const { error: updateReqError, data: updatedReq } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id).select();

      if (!updatedReq || updatedReq.length === 0) {
           await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
           throw new Error("Lỗi quyền hạn (RLS).");
      }

      if (updateReqError) {
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error(`Lỗi duyệt đơn: ${updateReqError.message}`);
      }

      showToast(`Đã duyệt: ${req.tool_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Thất bại: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang từ chối yêu cầu...', 'info');
    setProcessingId(req.id);
    try {
        const { error, data } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn (RLS).");
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang xử lý trả đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
        const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const { error, data } = await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn.");
        showToast('Đã xác nhận trả đồ.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy yêu cầu...', 'info');
    setProcessingId(id);

    const { error } = await supabase.from('requests').delete().eq('id', id);

    if (error) {
        showToast("Lỗi hủy đơn: " + error.message, 'error');
    } else {
        showToast("Đã hủy yêu cầu.", 'success');
        if (selectedIds.has(id)) {
            const newSet = new Set(selectedIds);
            newSet.delete(id);
            setSelectedIds(newSet);
        }
        await fetchRequests();
    }
    setProcessingId(null);
  };

  // Hàm điều phối xác nhận
  const handleConfirmAction = async () => {
    if (!confirmAction) return;

    setConfirmAction(null); // Đóng modal trước khi thực hiện

    switch (confirmAction.type) {
      case 'approve':
        await executeApprove(confirmAction.req);
        break;
      case 'reject':
        await executeReject(confirmAction.req);
        break;
      case 'return':
        await executeReturn(confirmAction.req);
        break;
      case 'cancel':
        await executeCancel(confirmAction.id);
        break;
      case 'bulk_cancel':
        await executeBulkCancel();
        break;
      case 'bulk_return':
        await executeBulkReturn();
        break;
    }
  };

  // Helper để lấy nội dung modal
  const getConfirmContent = () => {
    if (!confirmAction) return { title: '', message: '', btnClass: '' };

    switch (confirmAction.type) {
      case 'approve':
        return {
          title: 'Duyệt yêu cầu',
          message: `Bạn có chắc chắn muốn DUYỆT yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-green-600 hover:bg-green-700'
        };
      case 'reject':
        return {
          title: 'Từ chối yêu cầu',
          message: `Bạn có chắc chắn muốn TỪ CHỐI yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'return':
        return {
          title: 'Xác nhận trả đồ',
          message: `Xác nhận nhân viên ${confirmAction.req.user_name} đã trả lại "${confirmAction.req.tool_name}"?`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      case 'cancel':
        return {
          title: 'Hủy yêu cầu',
          message: 'Hành động này không thể hoàn tác. Bạn có chắc chắn muốn hủy yêu cầu này?',
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_cancel':
        // Đếm số lượng pending được chọn
        const pendingCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'pending').length;
        return {
          title: 'Hủy hàng loạt',
          message: `Bạn đang chọn hủy ${pendingCount} yêu cầu đang chờ. Hành động này không thể hoàn tác. Tiếp tục?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_return':
        const approvedCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'approved').length;
        return {
          title: 'Trả đồ hàng loạt',
          message: `Xác nhận nhận lại ${approvedCount} món đồ đã chọn? Kho sẽ được cập nhật số lượng tương ứng.`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      default:
        return { title: '', message: '', btnClass: '' };
    }
  };

  const confirmContent = getConfirmContent();

  // Tính toán số lượng cho các nút Bulk Action
  const selectedPendingCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'pending').length;
  const selectedApprovedCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved').length;

  return (
    <div className="space-y-6 relative">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu</h2>

            {/* BULK ACTION BUTTONS */}
            <div className="flex gap-2">
                {selectedPendingCount > 0 && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_cancel' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4" />}
                        Hủy {selectedPendingCount} đơn
                    </button>
                )}

                {selectedApprovedCount > 0 && user.role === 'admin' && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_return' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RotateCcw className="w-4 h-4" />}
                        Trả {selectedApprovedCount} món
                    </button>
                )}
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto shadow-inner">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm space-y-4">
        <div className="flex items-center gap-2 text-sm font-semibold text-gray-700">
            <Filter className="w-4 h-4" /> Bộ lọc
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {/* Search */}
            <div className="relative col-span-1 md:col-span-1 lg:col-span-2">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên, mã NV, công cụ..."
                    className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
            </div>

            {/* Status Filter */}
            <div>
                 <div className="relative">
                    <select
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-3 pr-8 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none bg-white cursor-pointer"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="pending">⏳ Chờ duyệt</option>
                        <option value="approved">✅ Đang mượn</option>
                        <option value="returned">↩️ Đã trả</option>
                        <option value="rejected">❌ Từ chối</option>
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <Filter className="w-3.5 h-3.5" />
                    </div>
                 </div>
            </div>

            {/* Date Filter (Start) */}
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <input 
                        type="date"
                        value={filterStartDate}
                        onChange={(e) => setFilterStartDate(e.target.value)}
                        className="w-full pl-8 pr-2 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 pointer-events-none" />
                </div>
            </div>
        </div>
        {(searchTerm || filterStatus !== 'all' || filterStartDate) && (
             <div className="flex justify-end">
                <button 
                    onClick={() => { setSearchTerm(''); setFilterStatus('all'); setFilterStartDate(''); setFilterEndDate(''); }}
                    className="text-xs text-red-600 hover:text-red-800 font-medium flex items-center gap-1"
                >
                    <X className="w-3 h-3" /> Xóa bộ lọc
                </button>
             </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="px-6 py-4 w-10">
                    <input 
                        type="checkbox" 
                        onChange={toggleSelectAll}
                        // Check nếu có item actionable và tất cả actionable item đều đã được chọn
                        checked={
                            filteredRequests.some(r => r.status === 'pending' || r.status === 'approved') && 
                            filteredRequests.filter(r => r.status === 'pending' || r.status === 'approved').every(r => selectedIds.has(r.id))
                        }
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                        disabled={!filteredRequests.some(r => r.status === 'pending' || r.status === 'approved')}
                    />
                </th>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500 italic">Không tìm thấy yêu cầu nào phù hợp.</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr key={req.id} className={`transition-colors ${selectedIds.has(req.id) ? 'bg-blue-50/70' : 'hover:bg-blue-50/30'}`}>
                    <td className="px-6 py-4">
                        {/* Chỉ hiện checkbox cho item có thể thao tác: Pending (để hủy) hoặc Approved (để trả) */}
                        {req.status === 'pending' || (req.status === 'approved' && user.role === 'admin') ? (
                            <input 
                                type="checkbox" 
                                checked={selectedIds.has(req.id)}
                                onChange={() => toggleSelection(req.id)}
                                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                            />
                        ) : (
                             <span className="block w-4 h-4"></span>
                        )}
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-gray-100 rounded border border-gray-200 flex-shrink-0 flex items-center justify-center overflow-hidden">
                                {req.tool_image ? (
                                    <img src={req.tool_image} alt="" className="w-full h-full object-contain" />
                                ) : (
                                    <Wrench className="w-4 h-4 text-gray-400" />
                                )}
                            </div>
                            <span className="font-medium text-gray-800">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                        req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                        req.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                        'bg-yellow-50 text-yellow-700 border-yellow-200'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'returned' && <RotateCcw className="w-3 h-3" />}
                         {req.status === 'rejected' && <X className="w-3 h-3" />}

                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {/* Admin Action Group (Only in All Tab) */}
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap" 
                                            title="Phê duyệt"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />} 
                                            Duyệt
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50 whitespace-nowrap" 
                                            title="Từ chối"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5" />} 
                                            Từ chối
                                        </button>
                                    </>
                                )}

                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap"
                                        title="Xác nhận đã trả"
                                    >
                                        {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />} 
                                        Đã trả
                                    </button>
                                )}
                            </>
                        )}

                        {/* Nút Hủy cho chính chủ (kể cả admin khi mượn đồ) */}
                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                disabled={processingId === req.id}
                                className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors whitespace-nowrap"
                            >
                                {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                                Hủy yêu cầu
                            </button>
                        )}

                        {/* Status text if nothing else */}
                        {(user.role !== 'admin' || activeTab === 'personal') && req.status !== 'pending' && (
                            <span className="text-xs text-gray-400 italic min-w-[60px] inline-block text-center">
                                {req.status === 'returned' ? 'Hoàn tất' : '-'}
                            </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* CONFIRMATION MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">{confirmContent.title}</h3>
              <p className="text-sm text-center text-gray-500">{confirmContent.message}</p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setConfirmAction(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`px-4 py-2 text-white font-medium rounded-lg text-sm shadow-md transition-colors ${confirmContent.btnClass}`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, AlertTriangle, Loader2, Search, Filter, Calendar, Wrench } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

// Mở rộng interface để chứa thông tin ảnh
interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

// Component thông báo nổi (Toast)
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${bgClass} text-white px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-fade-in-up max-w-sm`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-medium">{message}</p>
      <button onClick={onClose} className="ml-auto p-1 hover:bg-white/20 rounded">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

// Loại hành động cần xác nhận
type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | { type: 'bulk_cancel' }
  | { type: 'bulk_return' }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // --- FILTER STATES ---
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');

  // State cho Bulk Actions
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // State cho Confirmation Dialog
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];

      // Lấy danh sách tool_id duy nhất để fetch ảnh
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      // Fetch thông tin ảnh từ bảng tools
      const { data: toolsData } = await supabase
        .from('tools')
        .select('id, image')
        .in('id', toolIds);

      // Tạo map id -> image
      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      // Merge ảnh vào request
      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      // Sắp xếp Client-side: Approved lên đầu -> Pending -> Các trạng thái khác -> Sau đó theo ngày mới nhất
      enrichedData.sort((a, b) => {
          const getScore = (status: string) => {
              if (status === 'approved') return 3; // Ưu tiên cao nhất
              if (status === 'pending') return 2;
              return 1;
          };

          const scoreA = getScore(a.status);
          const scoreB = getScore(b.status);

          if (scoreA !== scoreB) {
              return scoreB - scoreA; // Descending score
          }

          // Nếu cùng status, sắp xếp theo ngày giảm dần
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
      setSelectedIds(new Set()); // Reset selection khi reload
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  // --- FILTER LOGIC ---
  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      // 1. Search Text (Name, ID, Tool Name)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      // 2. Status
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      // 3. Date Range
      let matchesDate = true;
      if (filterStartDate || filterEndDate) {
        const reqDate = new Date(req.borrow_date).setHours(0,0,0,0);
        if (filterStartDate) {
           matchesDate = matchesDate && reqDate >= new Date(filterStartDate).setHours(0,0,0,0);
        }
        if (filterEndDate) {
           matchesDate = matchesDate && reqDate <= new Date(filterEndDate).setHours(0,0,0,0);
        }
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate, filterEndDate]);

  const parseQuantity = (val: any) => {
    const num = parseInt(val);
    return isNaN(num) ? 0 : num;
  };

  // --- BULK ACTIONS ---
  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    // Chỉ select các item ĐANG HIỂN THỊ (filtered) có thể tương tác
    const actionableIds = filteredRequests
        .filter(r => r.status === 'pending' || r.status === 'approved')
        .map(r => r.id);

    const allSelected = actionableIds.length > 0 && actionableIds.every(id => selectedIds.has(id));

    if (allSelected) {
        // Bỏ chọn tất cả các item đang hiển thị
        const newSet = new Set(selectedIds);
        actionableIds.forEach(id => newSet.delete(id));
        setSelectedIds(newSet);
    } else {
        // Chọn tất cả các item đang hiển thị
        const newSet = new Set(selectedIds);
        actionableIds.forEach(id => newSet.add(id));
        setSelectedIds(newSet);
    }
  };

  const executeBulkCancel = async () => {
    // Chỉ lọc ra các item pending để hủy
    const idsToCancel = Array.from(selectedIds).filter(id => {
        const req = requests.find(r => r.id === id);
        return req?.status === 'pending';
    });

    if (idsToCancel.length === 0) return;

    showToast(`Đang hủy ${idsToCancel.length} yêu cầu...`, 'info');
    setIsBulkProcessing(true);

    try {
        const { error } = await supabase
            .from('requests')
            .delete()
            .in('id', idsToCancel);

        if (error) throw new Error(error.message);

        showToast(`Đã hủy thành công ${idsToCancel.length} yêu cầu.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi hủy hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const executeBulkReturn = async () => {
    // Chỉ lọc ra các item approved để trả
    const itemsToReturn = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved');

    if (itemsToReturn.length === 0) return;

    showToast(`Đang xử lý trả ${itemsToReturn.length} món...`, 'info');
    setIsBulkProcessing(true);

    try {
        // Thực hiện tuần tự để đảm bảo tính đúng đắn của tồn kho (có thể tối ưu bằng RPC nếu có)
        for (const req of itemsToReturn) {
            const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
            const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;

            // +1 Tồn kho
            await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);

            // Update status
            await supabase.from('requests')
                .update({ status: 'returned', returned_at: new Date().toISOString() })
                .eq('id', req.id);
        }

        showToast(`Đã trả thành công ${itemsToReturn.length} món đồ.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi trả hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  // --- SINGLE ACTIONS ---

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn mượn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);

    try {
      const { data: tools, error: toolError } = await supabase.from('tools').select('*').eq('id', req.tool_id);
      if (toolError || !tools || tools.length === 0) throw new Error("Lỗi đọc kho.");

      const tool = tools[0];
      const currentAvailable = parseQuantity(tool.available);

      if (currentAvailable <= 0) throw new Error(`Kho đã hết.`);

      const { error: updateToolError } = await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id).select();
      if (updateToolError) throw new Error(`Lỗi cập nhật kho.`);

      const { error: updateReqError, data: updatedReq } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id).select();

      if (!updatedReq || updatedReq.length === 0) {
           await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
           throw new Error("Lỗi quyền hạn (RLS).");
      }

      if (updateReqError) {
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error(`Lỗi duyệt đơn: ${updateReqError.message}`);
      }

      showToast(`Đã duyệt: ${req.tool_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Thất bại: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang từ chối yêu cầu...', 'info');
    setProcessingId(req.id);
    try {
        const { error, data } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn (RLS).");
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang xử lý trả đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
        const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const { error, data } = await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn.");
        showToast('Đã xác nhận trả đồ.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy yêu cầu...', 'info');
    setProcessingId(id);

    const { error } = await supabase.from('requests').delete().eq('id', id);

    if (error) {
        showToast("Lỗi hủy đơn: " + error.message, 'error');
    } else {
        showToast("Đã hủy yêu cầu.", 'success');
        if (selectedIds.has(id)) {
            const newSet = new Set(selectedIds);
            newSet.delete(id);
            setSelectedIds(newSet);
        }
        await fetchRequests();
    }
    setProcessingId(null);
  };

  // Hàm điều phối xác nhận
  const handleConfirmAction = async () => {
    if (!confirmAction) return;

    setConfirmAction(null); // Đóng modal trước khi thực hiện

    switch (confirmAction.type) {
      case 'approve':
        await executeApprove(confirmAction.req);
        break;
      case 'reject':
        await executeReject(confirmAction.req);
        break;
      case 'return':
        await executeReturn(confirmAction.req);
        break;
      case 'cancel':
        await executeCancel(confirmAction.id);
        break;
      case 'bulk_cancel':
        await executeBulkCancel();
        break;
      case 'bulk_return':
        await executeBulkReturn();
        break;
    }
  };

  // Helper để lấy nội dung modal
  const getConfirmContent = () => {
    if (!confirmAction) return { title: '', message: '', btnClass: '' };

    switch (confirmAction.type) {
      case 'approve':
        return {
          title: 'Duyệt yêu cầu',
          message: `Bạn có chắc chắn muốn DUYỆT yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-green-600 hover:bg-green-700'
        };
      case 'reject':
        return {
          title: 'Từ chối yêu cầu',
          message: `Bạn có chắc chắn muốn TỪ CHỐI yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'return':
        return {
          title: 'Xác nhận trả đồ',
          message: `Xác nhận nhân viên ${confirmAction.req.user_name} đã trả lại "${confirmAction.req.tool_name}"?`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      case 'cancel':
        return {
          title: 'Hủy yêu cầu',
          message: 'Hành động này không thể hoàn tác. Bạn có chắc chắn muốn hủy yêu cầu này?',
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_cancel':
        // Đếm số lượng pending được chọn
        const pendingCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'pending').length;
        return {
          title: 'Hủy hàng loạt',
          message: `Bạn đang chọn hủy ${pendingCount} yêu cầu đang chờ. Hành động này không thể hoàn tác. Tiếp tục?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_return':
        const approvedCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'approved').length;
        return {
          title: 'Trả đồ hàng loạt',
          message: `Xác nhận nhận lại ${approvedCount} món đồ đã chọn? Kho sẽ được cập nhật số lượng tương ứng.`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      default:
        return { title: '', message: '', btnClass: '' };
    }
  };

  const confirmContent = getConfirmContent();

  // Tính toán số lượng cho các nút Bulk Action
  const selectedPendingCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'pending').length;
  const selectedApprovedCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved').length;

  return (
    <div className="space-y-6 relative">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu</h2>

            {/* BULK ACTION BUTTONS */}
            <div className="flex gap-2">
                {selectedPendingCount > 0 && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_cancel' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4" />}
                        Hủy {selectedPendingCount} đơn
                    </button>
                )}

                {selectedApprovedCount > 0 && user.role === 'admin' && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_return' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RotateCcw className="w-4 h-4" />}
                        Trả {selectedApprovedCount} món
                    </button>
                )}
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto shadow-inner">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm space-y-4">
        <div className="flex items-center gap-2 text-sm font-semibold text-gray-700">
            <Filter className="w-4 h-4" /> Bộ lọc
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {/* Search */}
            <div className="relative col-span-1 md:col-span-1 lg:col-span-2">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên, mã NV, công cụ..."
                    className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
            </div>

            {/* Status Filter */}
            <div>
                 <div className="relative">
                    <select
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-3 pr-8 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none bg-white cursor-pointer"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="pending">⏳ Chờ duyệt</option>
                        <option value="approved">✅ Đang mượn</option>
                        <option value="returned">↩️ Đã trả</option>
                        <option value="rejected">❌ Từ chối</option>
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <Filter className="w-3.5 h-3.5" />
                    </div>
                 </div>
            </div>

            {/* Date Filter (Start) */}
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <input 
                        type="date"
                        value={filterStartDate}
                        onChange={(e) => setFilterStartDate(e.target.value)}
                        className="w-full pl-8 pr-2 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 pointer-events-none" />
                </div>
            </div>
        </div>
        {(searchTerm || filterStatus !== 'all' || filterStartDate) && (
             <div className="flex justify-end">
                <button 
                    onClick={() => { setSearchTerm(''); setFilterStatus('all'); setFilterStartDate(''); setFilterEndDate(''); }}
                    className="text-xs text-red-600 hover:text-red-800 font-medium flex items-center gap-1"
                >
                    <X className="w-3 h-3" /> Xóa bộ lọc
                </button>
             </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="px-6 py-4 w-10">
                    <input 
                        type="checkbox" 
                        onChange={toggleSelectAll}
                        // Check nếu có item actionable và tất cả actionable item đều đã được chọn
                        checked={
                            filteredRequests.some(r => r.status === 'pending' || r.status === 'approved') && 
                            filteredRequests.filter(r => r.status === 'pending' || r.status === 'approved').every(r => selectedIds.has(r.id))
                        }
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                        disabled={!filteredRequests.some(r => r.status === 'pending' || r.status === 'approved')}
                    />
                </th>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500 italic">Không tìm thấy yêu cầu nào phù hợp.</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr key={req.id} className={`transition-colors ${selectedIds.has(req.id) ? 'bg-blue-50/70' : 'hover:bg-blue-50/30'}`}>
                    <td className="px-6 py-4">
                        {/* Chỉ hiện checkbox cho item có thể thao tác: Pending (để hủy) hoặc Approved (để trả) */}
                        {req.status === 'pending' || (req.status === 'approved' && user.role === 'admin') ? (
                            <input 
                                type="checkbox" 
                                checked={selectedIds.has(req.id)}
                                onChange={() => toggleSelection(req.id)}
                                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                            />
                        ) : (
                             <span className="block w-4 h-4"></span>
                        )}
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-gray-100 rounded border border-gray-200 flex-shrink-0 flex items-center justify-center overflow-hidden">
                                {req.tool_image ? (
                                    <img src={req.tool_image} alt="" className="w-full h-full object-contain" />
                                ) : (
                                    <Wrench className="w-4 h-4 text-gray-400" />
                                )}
                            </div>
                            <span className="font-medium text-gray-800">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${
                        req.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                        req.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                        req.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                        'bg-yellow-50 text-yellow-700 border-yellow-200'
                      }`}>
                         {req.status === 'pending' && <Clock className="w-3 h-3" />}
                         {req.status === 'approved' && <CheckCircle2 className="w-3 h-3" />}
                         {req.status === 'returned' && <RotateCcw className="w-3 h-3" />}
                         {req.status === 'rejected' && <X className="w-3 h-3" />}

                         {req.status === 'approved' ? 'Đang mượn' : 
                          req.status === 'rejected' ? 'Từ chối' : 
                          req.status === 'pending' ? 'Chờ duyệt' : 'Đã trả'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {/* Admin Action Group (Only in All Tab) */}
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap" 
                                            title="Phê duyệt"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />} 
                                            Duyệt
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50 whitespace-nowrap" 
                                            title="Từ chối"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5" />} 
                                            Từ chối
                                        </button>
                                    </>
                                )}

                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap"
                                        title="Xác nhận đã trả"
                                    >
                                        {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />} 
                                        Đã trả
                                    </button>
                                )}
                            </>
                        )}

                        {/* Nút Hủy cho chính chủ (kể cả admin khi mượn đồ) */}
                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                disabled={processingId === req.id}
                                className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors whitespace-nowrap"
                            >
                                {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                                Hủy yêu cầu
                            </button>
                        )}

                        {/* Status text if nothing else */}
                        {(user.role !== 'admin' || activeTab === 'personal') && req.status !== 'pending' && (
                            <span className="text-xs text-gray-400 italic min-w-[60px] inline-block text-center">
                                {req.status === 'returned' ? 'Hoàn tất' : '-'}
                            </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* CONFIRMATION MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">{confirmContent.title}</h3>
              <p className="text-sm text-center text-gray-500">{confirmContent.message}</p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setConfirmAction(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`px-4 py-2 text-white font-medium rounded-lg text-sm shadow-md transition-colors ${confirmContent.btnClass}`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { Check, X, Trash2, Clock, RotateCcw, CheckCircle2, User as UserIcon, ShieldCheck, AlertTriangle, Loader2, Search, Filter, Calendar, Wrench, Ban, CheckSquare } from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

// Mở rộng interface để chứa thông tin ảnh
interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

// Component thông báo nổi (Toast)
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-green-600' : type === 'error' ? 'bg-red-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-4 right-4 z-50 ${bgClass} text-white px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-fade-in-up max-w-sm`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-medium">{message}</p>
      <button onClick={onClose} className="ml-auto p-1 hover:bg-white/20 rounded">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

// Loại hành động cần xác nhận
type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | { type: 'bulk_cancel' }
  | { type: 'bulk_return' }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  // --- FILTER STATES ---
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');

  // State cho Bulk Actions
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // State cho Confirmation Dialog
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('requests')
        .select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];

      // Lấy danh sách tool_id duy nhất để fetch ảnh
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      // Fetch thông tin ảnh từ bảng tools
      const { data: toolsData } = await supabase
        .from('tools')
        .select('id, image')
        .in('id', toolIds);

      // Tạo map id -> image
      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      // Merge ảnh vào request
      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      // Sắp xếp Client-side: Pending lên đầu -> Approved -> Returned -> Rejected
      enrichedData.sort((a, b) => {
          const getScore = (status: string) => {
              if (status === 'pending') return 4; // Ưu tiên cao nhất để xử lý
              if (status === 'approved') return 3; // Đang mượn
              if (status === 'returned') return 2; // Lịch sử
              return 1; // Rejected
          };

          const scoreA = getScore(a.status);
          const scoreB = getScore(b.status);

          if (scoreA !== scoreB) {
              return scoreB - scoreA; // Descending score
          }

          // Nếu cùng status, sắp xếp theo ngày giảm dần (mới nhất lên trên)
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
      setSelectedIds(new Set()); // Reset selection khi reload
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  // --- FILTER LOGIC ---
  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      // 1. Search Text (Name, ID, Tool Name)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      // 2. Status
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      // 3. Date Range
      let matchesDate = true;
      if (filterStartDate || filterEndDate) {
        const reqDate = new Date(req.borrow_date).setHours(0,0,0,0);
        if (filterStartDate) {
           matchesDate = matchesDate && reqDate >= new Date(filterStartDate).setHours(0,0,0,0);
        }
        if (filterEndDate) {
           matchesDate = matchesDate && reqDate <= new Date(filterEndDate).setHours(0,0,0,0);
        }
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate, filterEndDate]);

  const parseQuantity = (val: any) => {
    const num = parseInt(val);
    return isNaN(num) ? 0 : num;
  };

  // --- BULK ACTIONS ---
  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const toggleSelectAll = () => {
    // Chỉ select các item ĐANG HIỂN THỊ (filtered) có thể tương tác
    const actionableIds = filteredRequests
        .filter(r => r.status === 'pending' || r.status === 'approved')
        .map(r => r.id);

    const allSelected = actionableIds.length > 0 && actionableIds.every(id => selectedIds.has(id));

    if (allSelected) {
        // Bỏ chọn tất cả các item đang hiển thị
        const newSet = new Set(selectedIds);
        actionableIds.forEach(id => newSet.delete(id));
        setSelectedIds(newSet);
    } else {
        // Chọn tất cả các item đang hiển thị
        const newSet = new Set(selectedIds);
        actionableIds.forEach(id => newSet.add(id));
        setSelectedIds(newSet);
    }
  };

  const executeBulkCancel = async () => {
    // Chỉ lọc ra các item pending để hủy
    const idsToCancel = Array.from(selectedIds).filter(id => {
        const req = requests.find(r => r.id === id);
        return req?.status === 'pending';
    });

    if (idsToCancel.length === 0) return;

    showToast(`Đang hủy ${idsToCancel.length} yêu cầu...`, 'info');
    setIsBulkProcessing(true);

    try {
        const { error } = await supabase
            .from('requests')
            .delete()
            .in('id', idsToCancel);

        if (error) throw new Error(error.message);

        showToast(`Đã hủy thành công ${idsToCancel.length} yêu cầu.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi hủy hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const executeBulkReturn = async () => {
    // Chỉ lọc ra các item approved để trả
    const itemsToReturn = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved');

    if (itemsToReturn.length === 0) return;

    showToast(`Đang xử lý trả ${itemsToReturn.length} món...`, 'info');
    setIsBulkProcessing(true);

    try {
        // Thực hiện tuần tự để đảm bảo tính đúng đắn của tồn kho (có thể tối ưu bằng RPC nếu có)
        for (const req of itemsToReturn) {
            const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
            const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;

            // +1 Tồn kho
            await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);

            // Update status
            await supabase.from('requests')
                .update({ status: 'returned', returned_at: new Date().toISOString() })
                .eq('id', req.id);
        }

        showToast(`Đã trả thành công ${itemsToReturn.length} món đồ.`, 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi trả hàng loạt: ${error.message}`, 'error');
    } finally {
        setIsBulkProcessing(false);
    }
  };

  // --- SINGLE ACTIONS ---

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn mượn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);

    try {
      const { data: tools, error: toolError } = await supabase.from('tools').select('*').eq('id', req.tool_id);
      if (toolError || !tools || tools.length === 0) throw new Error("Lỗi đọc kho.");

      const tool = tools[0];
      const currentAvailable = parseQuantity(tool.available);

      if (currentAvailable <= 0) throw new Error(`Kho đã hết.`);

      const { error: updateToolError } = await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id).select();
      if (updateToolError) throw new Error(`Lỗi cập nhật kho.`);

      const { error: updateReqError, data: updatedReq } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id).select();

      if (!updatedReq || updatedReq.length === 0) {
           await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
           throw new Error("Lỗi quyền hạn (RLS).");
      }

      if (updateReqError) {
          await supabase.from('tools').update({ available: currentAvailable }).eq('id', req.tool_id);
          throw new Error(`Lỗi duyệt đơn: ${updateReqError.message}`);
      }

      showToast(`Đã duyệt: ${req.tool_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Thất bại: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang từ chối yêu cầu...', 'info');
    setProcessingId(req.id);
    try {
        const { error, data } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn (RLS).");
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang xử lý trả đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id);
        const currentAvailable = tools && tools.length > 0 ? parseQuantity(tools[0].available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const { error, data } = await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id).select();
        if (error) throw new Error(error.message);
        if (!data || data.length === 0) throw new Error("Lỗi quyền hạn.");
        showToast('Đã xác nhận trả đồ.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy yêu cầu...', 'info');
    setProcessingId(id);

    const { error } = await supabase.from('requests').delete().eq('id', id);

    if (error) {
        showToast("Lỗi hủy đơn: " + error.message, 'error');
    } else {
        showToast("Đã hủy yêu cầu.", 'success');
        if (selectedIds.has(id)) {
            const newSet = new Set(selectedIds);
            newSet.delete(id);
            setSelectedIds(newSet);
        }
        await fetchRequests();
    }
    setProcessingId(null);
  };

  // Hàm điều phối xác nhận
  const handleConfirmAction = async () => {
    if (!confirmAction) return;

    setConfirmAction(null); // Đóng modal trước khi thực hiện

    switch (confirmAction.type) {
      case 'approve':
        await executeApprove(confirmAction.req);
        break;
      case 'reject':
        await executeReject(confirmAction.req);
        break;
      case 'return':
        await executeReturn(confirmAction.req);
        break;
      case 'cancel':
        await executeCancel(confirmAction.id);
        break;
      case 'bulk_cancel':
        await executeBulkCancel();
        break;
      case 'bulk_return':
        await executeBulkReturn();
        break;
    }
  };

  // Helper để lấy nội dung modal
  const getConfirmContent = () => {
    if (!confirmAction) return { title: '', message: '', btnClass: '' };

    switch (confirmAction.type) {
      case 'approve':
        return {
          title: 'Duyệt yêu cầu',
          message: `Bạn có chắc chắn muốn DUYỆT yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-green-600 hover:bg-green-700'
        };
      case 'reject':
        return {
          title: 'Từ chối yêu cầu',
          message: `Bạn có chắc chắn muốn TỪ CHỐI yêu cầu mượn "${confirmAction.req.tool_name}" của ${confirmAction.req.user_name}?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'return':
        return {
          title: 'Xác nhận trả đồ',
          message: `Xác nhận nhân viên ${confirmAction.req.user_name} đã trả lại "${confirmAction.req.tool_name}"?`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      case 'cancel':
        return {
          title: 'Hủy yêu cầu',
          message: 'Hành động này không thể hoàn tác. Bạn có chắc chắn muốn hủy yêu cầu này?',
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_cancel':
        // Đếm số lượng pending được chọn
        const pendingCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'pending').length;
        return {
          title: 'Hủy hàng loạt',
          message: `Bạn đang chọn hủy ${pendingCount} yêu cầu đang chờ. Hành động này không thể hoàn tác. Tiếp tục?`,
          btnClass: 'bg-red-600 hover:bg-red-700'
        };
      case 'bulk_return':
        const approvedCount = Array.from(selectedIds).filter(id => requests.find(r => r.id === id)?.status === 'approved').length;
        return {
          title: 'Trả đồ hàng loạt',
          message: `Xác nhận nhận lại ${approvedCount} món đồ đã chọn? Kho sẽ được cập nhật số lượng tương ứng.`,
          btnClass: 'bg-blue-600 hover:bg-blue-700'
        };
      default:
        return { title: '', message: '', btnClass: '' };
    }
  };

  const confirmContent = getConfirmContent();

  // Tính toán số lượng cho các nút Bulk Action
  const selectedPendingCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'pending').length;
  const selectedApprovedCount = requests.filter(r => selectedIds.has(r.id) && r.status === 'approved').length;

  return (
    <div className="space-y-6 relative">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold text-gray-800">Quản lý Yêu cầu</h2>

            {/* BULK ACTION BUTTONS */}
            <div className="flex gap-2">
                {selectedPendingCount > 0 && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_cancel' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4" />}
                        Hủy {selectedPendingCount} đơn
                    </button>
                )}

                {selectedApprovedCount > 0 && user.role === 'admin' && (
                    <button 
                        onClick={() => setConfirmAction({ type: 'bulk_return' })}
                        disabled={isBulkProcessing}
                        className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-all animate-fade-in-up shadow-md"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RotateCcw className="w-4 h-4" />}
                        Trả {selectedApprovedCount} món
                    </button>
                )}
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-200 p-1 rounded-lg self-start sm:self-auto shadow-inner">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-600 hover:text-gray-800'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm space-y-4">
        <div className="flex items-center gap-2 text-sm font-semibold text-gray-700">
            <Filter className="w-4 h-4" /> Bộ lọc
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {/* Search */}
            <div className="relative col-span-1 md:col-span-1 lg:col-span-2">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên, mã NV, công cụ..."
                    className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
            </div>

            {/* Status Filter */}
            <div>
                 <div className="relative">
                    <select
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-3 pr-8 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none bg-white cursor-pointer"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="pending">⏳ Chờ duyệt</option>
                        <option value="approved">✅ Đang mượn</option>
                        <option value="returned">↩️ Đã trả</option>
                        <option value="rejected">❌ Từ chối</option>
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <Filter className="w-3.5 h-3.5" />
                    </div>
                 </div>
            </div>

            {/* Date Filter (Start) */}
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <input 
                        type="date"
                        value={filterStartDate}
                        onChange={(e) => setFilterStartDate(e.target.value)}
                        className="w-full pl-8 pr-2 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                    <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 pointer-events-none" />
                </div>
            </div>
        </div>
        {(searchTerm || filterStatus !== 'all' || filterStartDate) && (
             <div className="flex justify-end">
                <button 
                    onClick={() => { setSearchTerm(''); setFilterStatus('all'); setFilterStartDate(''); setFilterEndDate(''); }}
                    className="text-xs text-red-600 hover:text-red-800 font-medium flex items-center gap-1"
                >
                    <X className="w-3 h-3" /> Xóa bộ lọc
                </button>
             </div>
        )}
      </div>

      <Card className="p-0 overflow-hidden border-t-4 border-t-blue-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="px-6 py-4 w-10">
                    <input 
                        type="checkbox" 
                        onChange={toggleSelectAll}
                        // Check nếu có item actionable và tất cả actionable item đều đã được chọn
                        checked={
                            filteredRequests.some(r => r.status === 'pending' || r.status === 'approved') && 
                            filteredRequests.filter(r => r.status === 'pending' || r.status === 'approved').every(r => selectedIds.has(r.id))
                        }
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                        disabled={!filteredRequests.some(r => r.status === 'pending' || r.status === 'approved')}
                    />
                </th>
                <th className="px-6 py-4">Nhân viên</th>
                <th className="px-6 py-4">Công cụ</th>
                <th className="px-6 py-4">Thời gian</th>
                <th className="px-6 py-4">Trạng thái</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500">Đang tải dữ liệu...</td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={6} className="p-8 text-center text-gray-500 italic">Không tìm thấy yêu cầu nào phù hợp.</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr key={req.id} className={`transition-colors ${selectedIds.has(req.id) ? 'bg-blue-50/70' : 'hover:bg-blue-50/30'}`}>
                    <td className="px-6 py-4">
                        {/* Chỉ hiện checkbox cho item có thể thao tác: Pending (để hủy) hoặc Approved (để trả) */}
                        {req.status === 'pending' || (req.status === 'approved' && user.role === 'admin') ? (
                            <input 
                                type="checkbox" 
                                checked={selectedIds.has(req.id)}
                                onChange={() => toggleSelection(req.id)}
                                className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"
                            />
                        ) : (
                             <span className="block w-4 h-4"></span>
                        )}
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${
                                req.user_id === user.id ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-medium text-gray-900 flex items-center gap-1">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1 rounded">Me</span>}
                                </div>
                                <div className="text-xs text-gray-400">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-gray-100 rounded border border-gray-200 flex-shrink-0 flex items-center justify-center overflow-hidden">
                                {req.tool_image ? (
                                    <img src={req.tool_image} alt="" className="w-full h-full object-contain" />
                                ) : (
                                    <Wrench className="w-4 h-4 text-gray-400" />
                                )}
                            </div>
                            <span className="font-medium text-gray-800">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                        <div className="flex flex-col text-xs">
                            <span className="text-gray-600">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-gray-400">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-6 py-4">
                      {req.status === 'pending' && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-amber-100 text-amber-800 border border-amber-200 shadow-sm">
                            <Clock className="w-3.5 h-3.5" />
                            Chờ duyệt
                        </span>
                      )}
                      {req.status === 'approved' && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-emerald-100 text-emerald-800 border border-emerald-200 shadow-sm">
                            <CheckCircle2 className="w-3.5 h-3.5" />
                            Đang mượn
                        </span>
                      )}
                      {req.status === 'returned' && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-slate-100 text-slate-700 border border-slate-200">
                            <CheckSquare className="w-3.5 h-3.5" />
                            Đã trả
                        </span>
                      )}
                      {req.status === 'rejected' && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-rose-100 text-rose-800 border border-rose-200">
                            <Ban className="w-3.5 h-3.5" />
                            Từ chối
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {/* Admin Action Group (Only in All Tab) */}
                        {user.role === 'admin' && activeTab === 'all' && (
                            <>
                                {req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap" 
                                            title="Phê duyệt"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />} 
                                            Duyệt
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            disabled={processingId === req.id}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-white text-red-600 border border-red-200 rounded hover:bg-red-50 transition-colors text-xs font-medium disabled:opacity-50 whitespace-nowrap" 
                                            title="Từ chối"
                                        >
                                            {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <X className="w-3.5 h-3.5" />} 
                                            Từ chối
                                        </button>
                                    </>
                                )}

                                {req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        disabled={processingId === req.id}
                                        className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-xs font-medium disabled:opacity-50 shadow-sm whitespace-nowrap"
                                        title="Xác nhận đã trả"
                                    >
                                        {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RotateCcw className="w-3.5 h-3.5" />} 
                                        Đã trả
                                    </button>
                                )}
                            </>
                        )}

                        {/* Nút Hủy cho chính chủ (kể cả admin khi mượn đồ) */}
                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                disabled={processingId === req.id}
                                className="flex items-center gap-1 text-red-600 hover:text-red-800 text-xs font-semibold ml-auto border border-red-200 px-3 py-1.5 rounded hover:bg-red-50 transition-colors whitespace-nowrap"
                            >
                                {processingId === req.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
                                Hủy yêu cầu
                            </button>
                        )}

                        {/* Status text if nothing else */}
                        {(user.role !== 'admin' || activeTab === 'personal') && req.status !== 'pending' && (
                            <span className="text-xs text-gray-400 italic min-w-[60px] inline-block text-center">
                                {req.status === 'returned' ? 'Hoàn tất' : '-'}
                            </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* CONFIRMATION MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">{confirmContent.title}</h3>
              <p className="text-sm text-center text-gray-500">{confirmContent.message}</p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setConfirmAction(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`px-4 py-2 text-white font-medium rounded-lg text-sm shadow-md transition-colors ${confirmContent.btnClass}`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Bell, User, CheckCircle2, XCircle, Clock, Info, ChevronRight, Loader2 } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, OvertimeRequest } from '../../../types';

interface HeaderProps {
  user: any;
}

interface NotificationItem {
  id: string;
  type: 'borrow' | 'overtime';
  title: string;
  message: string;
  time: string; // ISO string
  status: 'pending' | 'approved' | 'rejected' | 'returned';
  isRead: boolean;
}

export const Header: React.FC<HeaderProps> = ({ user }) => {
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Đóng dropdown khi click ra ngoài
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchNotifications = async () => {
    if (!user) return;
    setLoading(true);

    try {
      const isAdmin = user.role === 'admin';
      const notifs: NotificationItem[] = [];

      // 1. Fetch Borrow Requests
      let borrowQuery = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false })
        .limit(10);

      // Nếu không phải Admin, chỉ lấy của mình. Nếu Admin, ưu tiên lấy pending.
      if (!isAdmin) {
        borrowQuery = borrowQuery.eq('user_id', user.id);
      }

      const { data: borrowData } = await borrowQuery;

      if (borrowData) {
        (borrowData as BorrowRequest[]).forEach(req => {
          // Logic lọc thông báo:
          // Admin: Quan tâm pending
          // User: Quan tâm approved/rejected/returned
          let shouldNotify = false;
          let title = '';
          let message = '';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Yêu cầu mượn mới';
              message = `${req.user_name} muốn mượn ${req.tool_name}`;
            }
          } else {
            if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Cập nhật yêu cầu mượn';
              const statusText = req.status === 'approved' ? 'được duyệt' : req.status === 'rejected' ? 'bị từ chối' : 'đã trả';
              message = `Yêu cầu mượn "${req.tool_name}" đã ${statusText}`;
            }
          }

          if (shouldNotify) {
            notifs.push({
              id: `borrow-${req.id}`,
              type: 'borrow',
              title,
              message,
              time: req.borrow_date, // Sử dụng borrow_date làm mốc thời gian
              status: req.status,
              isRead: false // Mặc định chưa đọc (trong thực tế cần bảng notifications riêng)
            });
          }
        });
      }

      // 2. Fetch Overtime Requests
      let otQuery = supabase
        .from('overtime_requests')
        .select('*')
        .order('date', { ascending: false })
        .limit(5);

      if (!isAdmin) {
        otQuery = otQuery.eq('user_id', user.id);
      }

      const { data: otData } = await otQuery;

      if (otData) {
        (otData as OvertimeRequest[]).forEach(req => {
          let shouldNotify = false;
          let title = '';
          let message = '';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Đăng ký tăng ca mới';
              message = `${req.employee_id} đăng ký OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')}`;
            }
          } else {
             if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Kết quả đăng ký OT';
              const statusText = req.status === 'approved' ? 'được duyệt' : 'bị từ chối';
              message = `OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')} đã ${statusText}`;
             }
          }

          if (shouldNotify) {
            notifs.push({
              id: `ot-${req.id}`,
              type: 'overtime',
              title,
              message,
              time: req.created_at || new Date().toISOString(), // Fallback nếu không có created_at
              status: req.status,
              isRead: false
            });
          }
        });
      }

      // Sort by time desc
      notifs.sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());

      setNotifications(notifs);
      setUnreadCount(notifs.length);

    } catch (error) {
      console.error("Error fetching notifications", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNotifications();

    // Polling nhẹ mỗi 30s để update thông báo
    const interval = setInterval(fetchNotifications, 30000);
    return () => clearInterval(interval);
  }, [user]);

  const handleToggle = () => {
    setIsOpen(!isOpen);
    // Khi mở ra coi như đã xem (demo logic)
    if (!isOpen && unreadCount > 0) {
        setTimeout(() => setUnreadCount(0), 1000); 
    }
  };

  const getTimeAgo = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return 'Vừa xong';
    if (diffMins < 60) return `${diffMins} phút trước`;
    if (diffHours < 24) return `${diffHours} giờ trước`;
    return `${diffDays} ngày trước`;
  };

  const getIcon = (item: NotificationItem) => {
    if (item.status === 'approved') return <CheckCircle2 className="w-5 h-5 text-green-500" />;
    if (item.status === 'rejected') return <XCircle className="w-5 h-5 text-red-500" />;
    if (item.status === 'pending') return <Clock className="w-5 h-5 text-yellow-500" />;
    if (item.status === 'returned') return <Info className="w-5 h-5 text-blue-500" />;
    return <Info className="w-5 h-5 text-gray-500" />;
  };

  return (
    <header className="bg-white border-b border-gray-200 h-16 px-8 flex items-center justify-between sticky top-0 z-20 shadow-sm">
      <div className="flex items-center gap-2 text-gray-500">
        <span className="text-sm font-medium">Hôm nay, {new Date().toLocaleDateString('vi-VN', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' })}</span>
      </div>

      <div className="flex items-center gap-6">
        {/* Notification Bell */}
        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={handleToggle}
            className={`relative p-2 rounded-full transition-all duration-200 ${isOpen ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            <Bell className={`w-5 h-5 ${unreadCount > 0 ? 'animate-pulse-slow' : ''}`} />
            {unreadCount > 0 && (
              <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white flex items-center justify-center">
                 <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
              </span>
            )}
          </button>

          {/* Dropdown */}
          {isOpen && (
            <div className="absolute right-0 top-full mt-3 w-80 sm:w-96 bg-white rounded-xl shadow-2xl border border-gray-100 overflow-hidden animate-fade-in-up origin-top-right">
              <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-800">Thông báo</h3>
                <button onClick={fetchNotifications} title="Làm mới" className="text-gray-400 hover:text-blue-600">
                   {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <span className="text-xs font-medium">Làm mới</span>}
                </button>
              </div>

              <div className="max-h-[400px] overflow-y-auto">
                {notifications.length === 0 ? (
                  <div className="p-8 text-center text-gray-500 flex flex-col items-center">
                    <Bell className="w-10 h-10 text-gray-200 mb-2" />
                    <p className="text-sm">Không có thông báo mới</p>
                  </div>
                ) : (
                  <ul className="divide-y divide-gray-50">
                    {notifications.map((notif) => (
                      <li key={notif.id} className="p-4 hover:bg-blue-50/50 transition-colors group cursor-pointer">
                        <div className="flex gap-3">
                          <div className={`mt-1 flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center bg-white border shadow-sm`}>
                            {getIcon(notif)}
                          </div>
                          <div className="flex-1">
                            <div className="flex justify-between items-start">
                                <p className="text-sm font-semibold text-gray-800">{notif.title}</p>
                                <span className="text-[10px] text-gray-400 whitespace-nowrap ml-2">{getTimeAgo(notif.time)}</span>
                            </div>
                            <p className="text-sm text-gray-600 mt-0.5 line-clamp-2">{notif.message}</p>
                          </div>
                          {notif.status === 'pending' && user.role === 'admin' && (
                             <div className="self-center">
                                <ChevronRight className="w-4 h-4 text-gray-300 group-hover:text-blue-400" />
                             </div>
                          )}
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              {notifications.length > 0 && (
                 <div className="p-2 bg-gray-50 border-t border-gray-100 text-center">
                    <button className="text-xs font-medium text-blue-600 hover:text-blue-800 transition-colors">
                        Đánh dấu tất cả là đã đọc
                    </button>
                 </div>
              )}
            </div>
          )}
        </div>

        {/* User Profile */}
        <div className="flex items-center gap-3 pl-6 border-l border-gray-200">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-semibold text-gray-800">{user?.name || 'Admin User'}</p>
            <p className="text-xs text-gray-500 uppercase flex items-center justify-end gap-1">
                {user?.role === 'admin' ? <CheckCircle2 className="w-3 h-3 text-blue-500"/> : null}
                {user?.role || 'Manager'}
            </p>
          </div>
          <div className="w-10 h-10 bg-gradient-to-br from-blue-100 to-blue-200 rounded-full flex items-center justify-center text-blue-600 shadow-inner border border-white">
            <User className="w-5 h-5" />
          </div>
        </div>
      </div>
    </header>
  );
};

import { GoogleGenAI } from "@google/genai";

// Lấy API Key từ biến môi trường
const apiKey = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey });

export const generateManagerInsight = async (contextData: string, query: string) => {
  if (!apiKey) {
    return "Vui lòng cấu hình API_KEY để sử dụng tính năng Trợ lý AI.";
  }

  try {
    const model = "gemini-2.5-flash";
    const prompt = `
      Bạn là một trợ lý ảo chuyên nghiệp dành cho Quản lý (Manager).
      Dưới đây là dữ liệu hiện tại của hệ thống (định dạng JSON):
      ${contextData}

      Người dùng (Quản lý) hỏi: "${query}"

      Hãy phân tích dữ liệu và đưa ra câu trả lời ngắn gọn, súc tích, chuyên nghiệp bằng Tiếng Việt.
      Nếu là đề xuất hành động, hãy gạch đầu dòng rõ ràng.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Xin lỗi, hiện tại tôi không thể xử lý yêu cầu này. Vui lòng kiểm tra lại kết nối hoặc API Key.";
  }
};

export const rewriteOvertimeReason = async (originalReason: string) => {
  if (!apiKey) return originalReason;

  try {
    const prompt = `
      Hãy viết lại lý do tăng ca sau đây cho chuyên nghiệp, ngắn gọn, phù hợp với môi trường doanh nghiệp (Corporate style) bằng Tiếng Việt.
      Chỉ trả về nội dung lý do đã viết lại, không thêm lời dẫn.

      Lý do gốc: "${originalReason}"
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
    });

    return response.text.trim();
  } catch (error) {
    console.error("Gemini Rewrite Error:", error);
    return originalReason;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Plus, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, AlertTriangle, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

// Helper: Get days in month
const getDaysInMonth = (year: number, month: number) => {
  return new Date(year, month + 1, 0).getDate();
};

// Helper: Get first day of month (0-6, 0 is Sunday)
const getFirstDayOfMonth = (year: number, month: number) => {
  return new Date(year, month, 1).getDay();
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [loading, setLoading] = useState(true);

  // Calendar State
  const [currentDate, setCurrentDate] = useState(new Date());

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  // Form Data
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('18:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false); // Config cho T7

  useEffect(() => {
    fetchRequests();
  }, [user.id]);

  const fetchRequests = async () => {
    setLoading(true);
    let query = supabase.from('overtime_requests').select('*');

    // Nếu không phải admin, chỉ xem của mình
    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  // --- CALCULATION LOGIC ---
  const calculateHours = (dateStr: string, start: string, end: string, isSat: boolean) => {
    const date = new Date(dateStr);
    const day = date.getDay(); // 0: Sun, 6: Sat

    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);

    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    // Logic: Thứ 7 đi làm -> Tính OT từ 14:30 (14.5)
    if (day === 6 && isSat) {
        if (startVal < 14.5) startVal = 14.5;
    }

    let diff = endVal - startVal;
    if (diff <= 0) return 0;

    // Logic: Trừ giờ nghỉ
    if (day === 6 && isSat) {
        // T7: Nếu làm trên 4h, trừ 0.5h nghỉ
        if (diff > 4) diff -= 0.5;
    } else if (day === 0) {
        // CN: Max 11h (đã trừ nghỉ trưa 1h nếu làm cả ngày)
        // Giả sử logic: nếu làm > 5h thì trừ 1h nghỉ
        if (diff > 5) diff -= 1;
        if (diff > 11) diff = 11;
    }

    return parseFloat(diff.toFixed(2));
  };

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(selectedDateStr, startTime, endTime, isSaturdayWork);
  }, [selectedDateStr, startTime, endTime, isSaturdayWork]);

  // --- AI REWRITE ---
  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  // --- EXCEL EXPORT ---
  const handleExportExcel = () => {
    // 1. Prepare data
    const exportData = requests.map(req => ({
        "Mã NV": req.employee_id,
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.hours,
        "Lý do": req.reason,
        "Trạng thái": req.status === 'approved' ? 'Đã duyệt' : req.status === 'pending' ? 'Chờ duyệt' : 'Từ chối'
    }));

    // 2. Create Sheet
    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");

    // 3. Download
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  // --- SUBMIT ---
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        employee_id: user.employeeCode,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('overtime_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        // Reset
        setReason('');
    } else {
        alert("Lỗi: " + error.message);
    }
    setIsSubmitting(false);
  };

  // --- CALENDAR HELPERS ---
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()); // 0-6
  // Adjust so Monday is first (Vietnamese calendar usually starts Mon)
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    // Empty cells
    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-24 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    // Days
    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

        days.push(
            <div 
                key={d} 
                onClick={() => {
                    setSelectedDateStr(dateStr);
                    // Auto check Saturday config
                    if (dateObj.getDay() === 6) setIsSaturdayWork(true);
                    else setIsSaturdayWork(false);
                    setIsModalOpen(true);
                }}
                className={`h-24 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                    {d}
                </span>

                <div className="mt-1 flex flex-wrap gap-1">
                    {dayRequests.slice(0, 3).map((req, idx) => (
                        <div key={idx} className={`w-6 h-6 rounded-full flex items-center justify-center text-[10px] text-white font-bold border-2 border-white shadow-sm ${req.user_id === user.id ? 'bg-blue-600 z-10' : 'bg-gray-400'}`} title={req.employee_id}>
                            {req.employee_id.substring(2)}
                        </div>
                    ))}
                    {dayRequests.length > 3 && (
                        <div className="w-6 h-6 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 3}
                        </div>
                    )}
                </div>

                {myRequest && (
                    <div className="absolute top-2 right-2">
                        {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                        {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                        {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  // --- ADMIN STATS DATA ---
  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
