import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { Wrench, PlusCircle, CheckCircle, MapPin, AlertCircle, Trash2, Edit, Plus, X, Save, Image as ImageIcon, LayoutGrid, List, ChevronLeft, ChevronRight, CheckSquare, Loader2, Minus, AlertTriangle, ShoppingCart, Send, PackagePlus, Settings2, Search, Filter } from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ITEMS_PER_PAGE = 20;

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full ${className} transition-colors`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2 text-gray-300' : 'w-5 h-5 text-gray-400'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'} ${mode === 'grid' ? 'p-4 group-hover:scale-105 transition-transform duration-300' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);

  // --- FILTER STATES ---
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  // --- ADMIN & MODE STATE ---
  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  // --- CART / SELECTION STATE ---
  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // --- CRUD STATE ---
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory, filterStatus]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
    if (error) console.error(error);
  };

  // --- FILTER LOGIC ---
  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  // --- PAGINATION ---
  const totalPages = Math.ceil(filteredTools.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentTools = filteredTools.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) setCurrentPage(newPage);
  };

  // --- SELECTION & QUANTITY LOGIC ---
  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); 
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const toggleSelectAll = () => {
    const selectableTools = currentTools.filter(isSelectable);
    const selectableIds = selectableTools.map(t => t.id);
    const allSelected = selectableIds.every(id => selectedToolIds.has(id));

    const newSet = new Set(selectedToolIds);
    const newQties = {...quantities};

    if (allSelected) {
        selectableIds.forEach(id => {
            newSet.delete(id);
            delete newQties[id];
        });
    } else {
        selectableIds.forEach(id => {
            newSet.add(id);
            if (!newQties[id]) newQties[id] = 1;
        });
    }
    setSelectedToolIds(newSet);
    setQuantities(newQties);
  };

  const handleRowClick = (tool: Tool) => {
      if (isManageMode) return; 
      if (isSelectable(tool)) {
          toggleSelection(tool.id);
      }
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
    const requests: any[] = [];

    toolsToBorrow.forEach(tool => {
        const qty = quantities[tool.id] || 1;
        for(let i = 0; i < qty; i++) {
            requests.push({
                employee_id: user.employeeCode,
                user_id: user.id,
                user_name: user.name,
                tool_id: tool.id,
                tool_name: tool.name,
                borrow_date: new Date().toISOString(),
                status: 'pending'
            });
        }
    });

    const { error } = await supabase.from('requests').insert(requests);

    if (!error) {
        setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
        setSelectedToolIds(new Set()); 
        setQuantities({});
        setTimeout(() => setMessage(null), 4000);
    } else {
        alert('Có lỗi xảy ra: ' + error.message);
    }
    setIsBulkProcessing(false);
  };

  // --- CRUD ACTIONS ---
  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const confirmDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete);
      if (error) throw error;
      const newTools = tools.filter(t => t.id !== toolToDelete);
      setTools(newTools);
      if (currentPage > Math.ceil(newTools.length / ITEMS_PER_PAGE)) {
        setCurrentPage(Math.max(1, currentPage - 1));
      }
      setMessage('Đã xóa công cụ thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    } finally {
        setToolToDelete(null);
    }
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32">
      {/* HEADER CONTROLS */}
      <div className="flex flex-col gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    Kho công cụ
                    {!isAdmin && <span className="text-xs font-normal text-gray-500 bg-gray-100 px-2 py-1 rounded-full">Chế độ Mượn</span>}
                </h2>
                <p className="text-sm text-gray-500 mt-1">Tổng cộng: {tools.length} thiết bị</p>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-3 w-full xl:w-auto">
                {message && (
                <div className="bg-green-100 text-green-700 px-4 py-2 rounded-lg flex items-center gap-2 animate-bounce text-sm shadow-sm whitespace-nowrap">
                    <CheckCircle className="w-4 h-4" />
                    {message}
                </div>
                )}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-md text-xs font-bold transition-all ${isManageMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200'}`}
                        >
                            <Settings2 className="w-3.5 h-3.5" />
                            Quản lý
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-md text-xs font-bold transition-all ${!isManageMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200'}`}
                        >
                            <ShoppingCart className="w-3.5 h-3.5" />
                            Mượn đồ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-2 rounded-md transition-all ${viewMode === 'grid' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                    title="Dạng lưới"
                >
                    <LayoutGrid className="w-4 h-4" />
                </button>
                <button 
                    onClick={() => setViewMode('table')}
                    className={`p-2 rounded-md transition-all ${viewMode === 'table' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                    title="Dạng bảng"
                >
                    <List className="w-4 h-4" />
                </button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-md w-full sm:w-auto justify-center whitespace-nowrap"
                    >
                        <Plus className="w-4 h-4" />
                        Thêm mới
                    </button>
                )}
            </div>
        </div>

        {/* --- FILTER TOOLBAR --- */}
        <div className="flex flex-col md:flex-row gap-3 pt-4 border-t border-gray-100">
            {/* Search - WHITE BG */}
            <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-9 pr-3 py-2 bg-white border border-gray-300 rounded-lg text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all text-gray-900"
                />
            </div>

            {/* Filter Group */}
            <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
                {/* Category Filter - WHITE BG */}
                <div className="relative min-w-[150px]">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-3 pr-8 py-2 bg-white border border-gray-300 rounded-lg text-sm shadow-sm appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                        ))}
                    </select>
                    <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 pointer-events-none" />
                </div>

                {/* Status Filter - WHITE BG */}
                <div className="relative min-w-[150px]">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-3 pr-8 py-2 bg-white border border-gray-300 rounded-lg text-sm shadow-sm appearance-none cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Đang bảo trì</option>
                    </select>
                    <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 pointer-events-none" />
                </div>

                {/* Clear Filter */}
                {(searchTerm || filterCategory !== 'all' || filterStatus !== 'all') && (
                    <button 
                        onClick={() => { setSearchTerm(''); setFilterCategory('all'); setFilterStatus('all'); }}
                        className="px-3 py-2 text-red-500 hover:bg-red-50 rounded-lg text-sm font-medium transition-colors flex items-center gap-1 whitespace-nowrap border border-transparent hover:border-red-100"
                    >
                        <X className="w-4 h-4" /> Xóa lọc
                    </button>
                )}
            </div>
        </div>
      </div>

      <div className="flex-1">
        {/* === GRID VIEW === */}
        {viewMode === 'grid' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.length === 0 ? (
                <div className="col-span-full py-20 text-center text-gray-500 flex flex-col items-center">
                    <Search className="w-12 h-12 text-gray-200 mb-4" />
                    <p className="text-lg font-medium">Không tìm thấy công cụ nào</p>
                    <p className="text-sm">Thử thay đổi bộ lọc hoặc từ khóa tìm kiếm</p>
                </div>
            ) : (
            currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-lg transition-all relative overflow-hidden group flex flex-col h-full p-0 border ${isSelected ? 'border-blue-500 ring-2 ring-blue-100' : 'border-gray-200'}`}>
                    {/* Image */}
                    <div className="h-48 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />

                      {/* Select Checkbox */}
                      {!isManageMode && selectable && (
                          <div className="absolute top-3 left-3 z-20" onClick={(e) => e.stopPropagation()}>
                               <input 
                                    type="checkbox"
                                    checked={isSelected}
                                    onChange={() => toggleSelection(tool.id)}
                                    className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer shadow-md bg-white accent-blue-600"
                               />
                          </div>
                      )}

                      <div className="absolute top-2 right-2">
                        {tool.status === 'inactive' ? (
                          <span className="bg-red-100 text-red-800 text-xs px-2 py-1 rounded-full font-medium shadow-sm border border-red-200">Bảo trì</span>
                        ) : tool.available > 0 ? (
                          <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded-full font-medium shadow-sm border border-green-200">
                            Sẵn: {tool.available}
                          </span>
                        ) : (
                          <span className="bg-gray-100 text-gray-800 text-xs px-2 py-1 rounded-full font-medium shadow-sm border border-gray-200">Hết hàng</span>
                        )}
                      </div>
                    </div>

                    <div className="p-4 flex-1 flex flex-col bg-white">
                      <div className="flex justify-between items-start mb-2">
                        <div>
                          <h3 className="font-bold text-gray-900 text-base line-clamp-2 min-h-[3rem]" title={tool.name}>{tool.name}</h3>
                          <p className="text-xs text-gray-500 mt-1">{tool.category}</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-1 text-xs text-gray-500 mb-4">
                        <MapPin className="w-3 h-3" />
                        {tool.location || 'Chưa cập nhật vị trí'}
                      </div>

                      <div className="mt-auto">
                        {/* CONDITIONAL ACTIONS BASED ON MODE */}
                        {isManageMode ? (
                          <div className="flex gap-2">
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-gray-50 hover:bg-gray-100 text-gray-700 border border-gray-200 py-2 rounded-lg text-xs font-bold transition-colors flex items-center justify-center gap-1">
                                <Edit className="w-3.5 h-3.5" /> Sửa
                             </button>
                             <button onClick={() => setToolToDelete(tool.id)} className="flex-1 bg-white hover:bg-red-50 text-red-600 border border-red-200 py-2 rounded-lg text-xs font-bold transition-colors flex items-center justify-center gap-1">
                                <Trash2 className="w-3.5 h-3.5" /> Xóa
                             </button>
                          </div>
                        ) : (
                          // BORROW ACTIONS
                          isSelected ? (
                              <div className="flex items-center justify-between bg-blue-50 rounded-lg p-1 border border-blue-200 animate-in fade-in zoom-in duration-200">
                                  <button 
                                    onClick={(e) => { e.preventDefault(); changeQuantity(tool.id, -1, tool.available); }}
                                    className="w-8 h-8 flex items-center justify-center bg-white rounded shadow-sm text-blue-600 hover:text-blue-700 hover:bg-gray-50 transition-colors border border-blue-100"
                                  >
                                      <Minus className="w-4 h-4" />
                                  </button>
                                  <span className="font-bold text-blue-700 text-lg">{qty}</span>
                                  <button 
                                    onClick={(e) => { e.preventDefault(); changeQuantity(tool.id, 1, tool.available); }}
                                    className="w-8 h-8 flex items-center justify-center bg-blue-600 rounded shadow-sm text-white hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:bg-gray-400"
                                    disabled={qty >= Number(tool.available)}
                                  >
                                      <Plus className="w-4 h-4" />
                                  </button>
                              </div>
                          ) : (
                              <button
                                onClick={() => toggleSelection(tool.id)}
                                disabled={tool.available === 0 || tool.status === 'inactive'}
                                className="w-full bg-white border border-blue-600 text-blue-600 hover:bg-blue-50 py-2 rounded-lg text-sm font-bold transition-all disabled:opacity-50 disabled:border-gray-200 disabled:text-gray-400 disabled:bg-gray-100 flex items-center justify-center gap-2 shadow-sm hover:shadow-md"
                              >
                                <PackagePlus className="w-4 h-4" />
                                Chọn mượn
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            }))}
            </div>
        )}

        {/* === TABLE VIEW === */}
        {viewMode === 'table' && (
          <Card className="p-0 overflow-hidden border border-gray-200 shadow-sm">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm text-gray-600">
                <thead className="bg-gray-50 text-gray-700 font-semibold uppercase tracking-wider text-xs sticky top-0 z-10 shadow-sm border-b border-gray-200">
                  <tr>
                    <th className="px-6 py-4 w-10 bg-gray-50">
                        {!isManageMode && (
                            <input 
                                type="checkbox"
                                checked={currentTools.length > 0 && currentTools.some(isSelectable) && currentTools.filter(isSelectable).every(t => selectedToolIds.has(t.id))}
                                onChange={toggleSelectAll}
                                className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer bg-white accent-blue-600"
                                disabled={!currentTools.some(isSelectable)}
                            />
                        )}
                    </th>
                    <th className="px-6 py-4 w-16 bg-gray-50">Hình</th>
                    <th className="px-6 py-4 bg-gray-50">Tên thiết bị</th>
                    <th className="px-6 py-4 bg-gray-50">Danh mục</th>
                    <th className="px-6 py-4 text-center bg-gray-50">Tồn kho</th>
                    <th className="px-6 py-4 text-center bg-gray-50">Sẵn có</th>
                    <th className="px-6 py-4 bg-gray-50">Vị trí</th>
                    <th className="px-6 py-4 bg-gray-50">Trạng thái</th>
                    <th className="px-6 py-4 text-right min-w-[160px] bg-gray-50">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 bg-white">
                  {currentTools.length === 0 ? (
                      <tr>
                        <td colSpan={9} className="py-10 text-center text-gray-500">
                            Không tìm thấy công cụ phù hợp
                        </td>
                      </tr>
                  ) : (
                  currentTools.map((tool) => {
                      const selectable = isSelectable(tool);
                      const isSelected = selectedToolIds.has(tool.id);
                      const qty = quantities[tool.id] || 1;

                      return (
                      <tr 
                          key={tool.id} 
                          onClick={() => handleRowClick(tool)}
                          className={`transition-colors cursor-pointer ${isSelected ? 'bg-blue-50/60' : 'hover:bg-gray-50'}`}
                      >
                        <td className="px-6 py-4" onClick={(e) => e.stopPropagation()}>
                            {!isManageMode && selectable && (
                                <input 
                                    type="checkbox"
                                    checked={isSelected}
                                    onChange={() => toggleSelection(tool.id)}
                                    className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer bg-white accent-blue-600"
                                />
                            )}
                        </td>
                        <td className="px-6 py-4">
                            <div className="w-10 h-10 rounded bg-white border border-gray-200 overflow-hidden flex items-center justify-center p-1">
                                <ToolThumbnail src={tool.image} alt={tool.name} mode="table" />
                            </div>
                        </td>
                        <td className="px-6 py-4 font-medium text-gray-900">{tool.name}</td>
                        <td className="px-6 py-4">{tool.category}</td>
                        <td className="px-6 py-4 text-center">{tool.quantity}</td>
                        <td className="px-6 py-4 text-center">
                            <span className="inline-block text-lg font-bold text-blue-700 bg-blue-50 px-3 py-1 rounded-md min-w-[3rem] text-center shadow-sm border border-blue-200">
                                {tool.available}
                            </span>
                        </td>
                        <td className="px-6 py-4">{tool.location || '-'}</td>
                        <td className="px-6 py-4">
                          {tool.status === 'active' 
                            ? <span className="text-green-700 text-xs bg-green-50 border border-green-200 px-2 py-1 rounded-full font-medium">Hoạt động</span> 
                            : <span className="text-red-700 text-xs bg-red-50 border border-red-200 px-2 py-1 rounded-full font-medium">Bảo trì</span>}
                        </td>
                        <td className="px-6 py-4 text-right" onClick={(e) => e.stopPropagation()}>
                            {isManageMode ? (
                                <div className="flex justify-end gap-2">
                                    <button onClick={() => handleEditTool(tool)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors border border-gray-200 hover:border-blue-200 bg-white"><Edit className="w-4 h-4" /></button>
                                    <button onClick={() => setToolToDelete(tool.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors border border-gray-200 hover:border-red-200 bg-white"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            ) : (
                                <div className="flex justify-end">
                                    {isSelected ? (
                                        <div className="flex items-center gap-1 bg-white border border-blue-500 rounded-lg shadow-sm p-0.5 animate-in fade-in zoom-in duration-200 ring-2 ring-blue-100">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); changeQuantity(tool.id, -1, tool.available); }}
                                                className="w-7 h-7 flex items-center justify-center rounded bg-gray-50 hover:bg-gray-100 text-gray-700 transition-colors"
                                            >
                                                <Minus className="w-3.5 h-3.5" />
                                            </button>
                                            <span className="w-8 text-center font-bold text-blue-700 text-sm select-none">{qty}</span>
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); changeQuantity(tool.id, 1, tool.available); }}
                                                className="w-7 h-7 flex items-center justify-center rounded bg-blue-600 hover:bg-blue-700 text-white disabled:opacity-50 transition-colors"
                                                disabled={qty >= Number(tool.available)}
                                            >
                                                <Plus className="w-3.5 h-3.5" />
                                            </button>
                                        </div>
                                    ) : (
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); toggleSelection(tool.id); }}
                                            disabled={tool.available === 0 || tool.status === 'inactive'}
                                            className="bg-white border border-blue-600 text-blue-600 hover:bg-blue-50 px-3 py-1.5 rounded-lg text-xs font-bold transition-all shadow-sm flex items-center gap-1.5 disabled:opacity-50 disabled:border-gray-200 disabled:text-gray-400 disabled:bg-gray-50"
                                        >
                                            <PackagePlus className="w-3.5 h-3.5" />
                                            Chọn mượn
                                        </button>
                                    )}
                                </div>
                            )}
                        </td>
                      </tr>
                    );
                  }))}
                </tbody>
              </table>
            </div>
          </Card>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
            <div className="mt-6 flex justify-center items-center gap-4">
                <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-2 rounded-lg border border-gray-300 bg-white disabled:opacity-50 hover:bg-gray-50 text-gray-700 shadow-sm"><ChevronLeft className="w-4 h-4" /></button>
                <span className="text-sm font-medium text-gray-700 bg-white px-3 py-1.5 rounded-lg border border-gray-300 shadow-sm">Trang {currentPage} / {totalPages}</span>
                <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-2 rounded-lg border border-gray-300 bg-white disabled:opacity-50 hover:bg-gray-50 text-gray-700 shadow-sm"><ChevronRight className="w-4 h-4" /></button>
            </div>
        )}
      </div>

      {/* === FLOATING ACTION BAR === */}
      {selectedToolIds.size > 0 && (
          <div className="fixed bottom-6 left-0 right-0 z-[100] flex justify-center px-4 pointer-events-none">
             <div className="bg-gray-900 text-white p-2 pr-3 rounded-2xl shadow-2xl flex items-center gap-4 pointer-events-auto animate-fade-in-up border border-gray-700 w-full max-w-lg mx-auto backdrop-blur-md bg-opacity-95">
                <div className="flex items-center gap-3 pl-2">
                    <div className="bg-blue-600 rounded-xl w-10 h-10 flex items-center justify-center font-bold text-lg shadow-inner relative">
                        {totalItemsSelected}
                    </div>
                    <div className="flex flex-col">
                        <span className="text-[10px] text-gray-400 uppercase tracking-wide font-bold">Giỏ đồ</span>
                        <span className="font-bold text-sm text-white">{selectedToolIds.size} loại</span>
                    </div>
                </div>

                <div className="flex-1"></div>

                <div className="flex items-center gap-2">
                    <button 
                        onClick={() => { setSelectedToolIds(new Set()); setQuantities({}); }}
                        className="text-gray-400 hover:text-white text-xs font-bold px-3 py-2 rounded hover:bg-gray-800 transition-colors"
                    >
                        Hủy
                    </button>
                    <button 
                        onClick={handleBulkBorrow}
                        disabled={isBulkProcessing}
                        className="bg-blue-600 hover:bg-blue-500 text-white px-5 py-2.5 rounded-xl font-bold shadow-lg transition-all hover:scale-105 active:scale-95 flex items-center gap-2"
                    >
                        {isBulkProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : <Send className="w-4 h-4" />}
                        Gửi yêu cầu
                    </button>
                </div>
             </div>
          </div>
      )}

      {/* Admin Modals */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-fade-in-up">
            <div className="flex justify-between items-center p-6 border-b sticky top-0 bg-white z-10">
              <h3 className="text-lg font-bold text-gray-900">{isEditing ? 'Cập nhật công cụ' : 'Thêm công cụ mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Tên thiết bị <span className="text-red-500">*</span></label>
                <input 
                  type="text" 
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
                  placeholder="Ví dụ: Máy khoan Bosch..."
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Danh mục</label>
                    <select 
                    value={formData.category}
                    onChange={(e) => setFormData({...formData, category: e.target.value})}
                    className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
                    >
                    <option>Thiết bị cầm tay</option>
                    <option>Máy móc lớn</option>
                    <option>Dụng cụ đo lường</option>
                    <option>Đồ bảo hộ</option>
                    <option>Vật tư tiêu hao</option>
                    <option>Thiết bị văn phòng</option>
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Trạng thái</label>
                    <select 
                    value={formData.status}
                    onChange={(e) => setFormData({...formData, status: e.target.value as any})}
                    className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
                    >
                    <option value="active">Hoạt động</option>
                    <option value="inactive">Bảo trì / Hỏng</option>
                    </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tổng số lượng</label>
                    <input 
                    type="number" 
                    min="0"
                    value={formData.quantity}
                    onChange={(e) => setFormData({...formData, quantity: parseInt(e.target.value) || 0})}
                    className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Sẵn có</label>
                    <input 
                    type="number" 
                    min="0"
                    value={formData.available}
                    onChange={(e) => setFormData({...formData, available: parseInt(e.target.value) || 0})}
                    className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
                    />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Vị trí lưu kho</label>
                <input 
                  type="text" 
                  value={formData.location}
                  onChange={(e) => setFormData({...formData, location: e.target.value})}
                  className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
                  placeholder="Kệ A2, Kho 1..."
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Link Ảnh (URL)</label>
                <div className="flex gap-2">
                    <div className="flex-1 relative">
                        <ImageIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                        type="text" 
                        value={formData.image}
                        onChange={(e) => setFormData({...formData, image: e.target.value})}
                        className="w-full pl-9 pr-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm text-gray-900"
                        placeholder="https://..."
                        />
                    </div>
                </div>
                {formData.image && (
                    <div className="mt-2 w-full h-32 bg-white rounded border border-gray-200 flex items-center justify-center overflow-hidden p-2">
                        <img src={formData.image} alt="Preview" className="h-full object-contain" onError={(e) => (e.currentTarget.style.display = 'none')} />
                    </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Mô tả chi tiết</label>
                <textarea 
                  value={formData.description}
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm h-24 resize-none text-gray-900"
                  placeholder="Thông tin thêm về thiết bị..."
                />
              </div>
            </div>

            <div className="p-6 border-t bg-gray-50 flex justify-end gap-3 sticky bottom-0">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 shadow-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleSaveTool}
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-sm"
              >
                <Save className="w-4 h-4" />
                {isEditing ? 'Lưu thay đổi' : 'Thêm mới'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Delete */}
      {toolToDelete && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">Xác nhận xóa</h3>
              <p className="text-sm text-center text-gray-500">
                Bạn có chắc chắn muốn xóa công cụ này? Hành động này không thể hoàn tác và sẽ xóa mọi dữ liệu liên quan.
              </p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setToolToDelete(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm shadow-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={confirmDeleteTool}
                className="px-4 py-2 bg-red-600 text-white font-medium rounded-lg hover:bg-red-700 text-sm shadow-md"
              >
                Xóa vĩnh viễn
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
