tôi đã tạo bảng như này trên supabase bạn có thể sử dụng -- BẮT ĐẦU TRANSACTION
BEGIN;

-- 1. TẠO BẢNG PROFILES (Hồ sơ nhân viên)
CREATE TABLE IF NOT EXISTS public.profiles (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  employee_code text,
  full_name text,
  role text DEFAULT 'USER',
  department text,
  avatar_url text,
  default_reason text,
  password text
);

-- Bổ sung các cột nếu bảng đã tồn tại nhưng thiếu cột
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS employee_code text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role text DEFAULT 'USER';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS department text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS avatar_url text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS default_reason text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS password text;

-- 2. TẠO BẢNG DAY_CONFIGS (Cấu hình ngày làm việc/thứ 7)
CREATE TABLE IF NOT EXISTS public.day_configs (
  date text PRIMARY KEY,
  is_working_day boolean DEFAULT true
);

-- 3. TẠO BẢNG OT_REQUESTS (Yêu cầu OT)
CREATE TABLE IF NOT EXISTS public.ot_requests (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id uuid,
  date text,
  start_time text,
  end_time text,
  total_hours numeric,
  reason text,
  status text,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Bổ sung các cột nếu thiếu
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS user_id uuid;
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS date text;
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS start_time text;
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS end_time text;
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS total_hours numeric;
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS reason text;
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS status text;
ALTER TABLE public.ot_requests ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW();

-- 4. XỬ LÝ KHÓA NGOẠI (FOREIGN KEY) - QUAN TRỌNG
-- Xóa tất cả các liên kết cũ giữa ot_requests và profiles để tránh lỗi xung đột
DO $$ 
DECLARE 
    r RECORD;
BEGIN 
    FOR r IN 
        SELECT tc.constraint_name 
        FROM information_schema.table_constraints AS tc 
        JOIN information_schema.constraint_column_usage AS ccu 
          ON tc.constraint_name = ccu.constraint_name 
        WHERE tc.constraint_type = 'FOREIGN KEY' 
          AND tc.table_name = 'ot_requests' 
          AND ccu.table_name = 'profiles'
    LOOP 
        EXECUTE 'ALTER TABLE public.ot_requests DROP CONSTRAINT IF EXISTS "' || r.constraint_name || '" CASCADE';
    END LOOP;
END $$;

-- Tạo lại khóa ngoại chuẩn (ON DELETE CASCADE để khi xóa User sẽ xóa luôn OT của họ)
ALTER TABLE public.ot_requests 
ADD CONSTRAINT ot_requests_user_id_fkey 
FOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE CASCADE;

-- 5. CẤP QUYỀN TRUY CẬP (ROW LEVEL SECURITY)
-- Bật RLS
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ot_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.day_configs ENABLE ROW LEVEL SECURITY;

-- Tạo Policy cho phép mọi thao tác (Select, Insert, Update, Delete)
-- Lưu ý: Đây là cấu hình mở cho tiện sử dụng nội bộ.
DROP POLICY IF EXISTS "Public profiles access" ON public.profiles;
CREATE POLICY "Public profiles access" ON public.profiles FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public ot_requests access" ON public.ot_requests;
CREATE POLICY "Public ot_requests access" ON public.ot_requests FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public day_configs access" ON public.day_configs;
CREATE POLICY "Public day_configs access" ON public.day_configs FOR ALL USING (true) WITH CHECK (true);

-- 6. TẠO TÀI KHOẢN ADMIN MẶC ĐỊNH (Nếu chưa có)
INSERT INTO public.profiles (employee_code, full_name, password, role, department, default_reason)
VALUES ('ADMIN', 'Quản Trị Viên', 'admin123', 'ADMIN', 'Board', 'Họp quản trị')
ON CONFLICT DO NOTHING;

COMMIT;

