// Wrapper để giữ tương thích với code cũ và xử lý Auth tùy chỉnh
export const supabase = {
  // Proxy các hàm query cơ bản sang client thực
  from: (table: string) => client.from(table),
  rpc: (fn: string, args: any) => client.rpc(fn, args),

  // Auth tùy chỉnh dùng bảng 'users' (Database cũ)
  auth: {
    signInWithPassword: async ({ employeeCode, password }: { employeeCode: string, password: string }) => {
      try {
        // Query trực tiếp bảng users
        const { data, error } = await client
          .from('users')
          .select('*')
          .eq('employee_id', employeeCode)
          .eq('password', password)
          .single();

        if (error || !data) {
          return { data: null, error: { message: 'Mã nhân viên hoặc mật khẩu không chính xác.' } };
        }

        // Tạo object User compatible với App
        const user = {
          id: data.id,
          employeeCode: data.employee_id,
          name: data.name,
          role: data.role ? data.role.toLowerCase() : 'user',
        };

        const session = {
          access_token: 'custom-session-token', 
          user: user
        };

        return { data: { user, session }, error: null };
      } catch (err) {
        return { data: null, error: { message: 'Lỗi kết nối server.' } };
      }
    },
    signOut: async () => {
      return { error: null };
    },
    getSession: async () => {
      const stored = localStorage.getItem('sb-session');
      return { data: { session: stored ? JSON.parse(stored) : null }, error: null };
    },
    getUser: async () => {
        const stored = localStorage.getItem('sb-session');
        const session = stored ? JSON.parse(stored) : null;
        return { data: { user: session?.user || null }, error: null };
    }
  }
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Employee } from '../../../types';
import { Card } from '../ui/Card';
import { Search, Plus, User as UserIcon, X, Save, Edit2, Trash2, AlertTriangle, Shield, User } from 'lucide-react';

export const EmployeeList: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  // State cho chức năng sửa/thêm
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentId, setCurrentId] = useState<string | null>(null);

  const initialForm = { employee_id: '', name: '', role: 'user', password: '123' };
  const [formData, setFormData] = useState(initialForm);

  // State cho chức năng xóa
  const [userToDelete, setUserToDelete] = useState<Employee | null>(null);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    setLoading(true);
    const { data, error } = await supabase.from('users').select('*').order('employee_id', { ascending: true });
    if (data) setEmployees(data as Employee[]);
    if (error) console.error(error);
    setLoading(false);
  };

  const handleAddNew = () => {
    setFormData(initialForm);
    setIsEditing(false);
    setIsModalOpen(true);
  };

  const handleEdit = (employee: Employee) => {
    setCurrentId(employee.id);
    setFormData({
        employee_id: employee.employee_id,
        name: employee.name,
        role: employee.role,
        password: employee.password || '',
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  const handleDelete = async () => {
    if (!userToDelete) return;

    try {
      const { error } = await supabase.from('users').delete().eq('id', userToDelete.id);
      if (error) throw error;

      setEmployees(employees.filter(emp => emp.id !== userToDelete.id));
      setUserToDelete(null);
    } catch (error: any) {
      alert('Lỗi khi xóa tài khoản: ' + error.message);
    }
  };

  const handleSave = async () => {
    if (!formData.employee_id || !formData.name) return alert("Vui lòng nhập đủ thông tin");

    try {
      const payload = {
          employee_id: formData.employee_id,
          name: formData.name,
          role: formData.role,
          password: formData.password,
      };

      if (isEditing && currentId) {
        const { error } = await supabase.from('users').update(payload).eq('id', currentId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('users').insert([payload]);
        if (error) throw error;
      }

      await fetchEmployees();
      setIsModalOpen(false);
    } catch (error: any) {
      alert('Lỗi cập nhật: ' + error.message);
    }
  };

  return (
    <div className="space-y-6 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Danh sách nhân sự</h2>
        <button onClick={handleAddNew} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm font-medium transition-colors shadow-sm">
          <Plus className="w-4 h-4" />
          Thêm nhân sự
        </button>
      </div>

      <Card className="p-0 overflow-hidden">
        {/* Toolbar */}
        <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row gap-4 bg-gray-50">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
              type="text" 
              placeholder="Tìm tên, mã NV..." 
              className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-300 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm shadow-sm text-gray-900"
            />
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-gray-600">
            <thead className="bg-gray-100 text-gray-700 font-semibold uppercase tracking-wider text-xs sticky top-0 z-10 shadow-sm border-b border-gray-200">
              <tr>
                <th className="px-6 py-4">Mã NV</th>
                <th className="px-6 py-4">Họ và tên</th>
                <th className="px-6 py-4">Vai trò</th>
                <th className="px-6 py-4">Ngày tạo</th>
                <th className="px-6 py-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center text-gray-500">Đang tải dữ liệu...</td>
                </tr>
              ) : (
                employees.map((emp) => (
                  <tr key={emp.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 font-mono font-medium text-blue-600">{emp.employee_id}</td>
                    <td className="px-6 py-4 font-medium text-gray-900 flex items-center gap-2">
                        <div className="w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center overflow-hidden border border-gray-200">
                           <UserIcon className="w-4 h-4 text-gray-400"/>
                        </div>
                        {emp.name}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium uppercase ${
                        emp.role === 'admin' ? 'bg-purple-100 text-purple-800 border border-purple-200' : 'bg-gray-100 text-gray-800 border border-gray-200'
                      }`}>
                        {emp.role === 'admin' ? <Shield className="w-3 h-3"/> : <User className="w-3 h-3"/>}
                        {emp.role}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-xs text-gray-500">
                        {emp.created_at ? new Date(emp.created_at).toLocaleDateString('vi-VN') : '-'}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => handleEdit(emp)}
                          className="text-blue-600 hover:bg-blue-50 p-1.5 rounded transition-colors"
                          title="Sửa thông tin"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => setUserToDelete(emp)}
                          className="text-red-600 hover:bg-red-50 p-1.5 rounded transition-colors"
                          title="Xóa tài khoản"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* Edit/Add Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md animate-fade-in-up">
            <div className="flex justify-between items-center p-6 border-b">
              <h3 className="text-lg font-bold text-gray-900">{isEditing ? 'Sửa thông tin' : 'Thêm nhân sự mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Mã nhân viên</label>
                <input 
                  type="text" 
                  value={formData.employee_id} 
                  onChange={(e) => setFormData({...formData, employee_id: e.target.value.toUpperCase()})}
                  disabled={isEditing}
                  className="w-full px-3 py-2 bg-white border border-gray-300 rounded-lg text-gray-900 text-sm shadow-sm focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-gray-100 disabled:text-gray-500"
                  placeholder="VD: NV001"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Họ và tên</label>
                <input 
                  type="text" 
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white focus:ring-2 focus:ring-blue-500 text-sm shadow-sm text-gray-900 outline-none"
                />
              </div>

              <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Vai trò</label>
                  <select 
                  value={formData.role}
                  onChange={(e) => setFormData({...formData, role: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white focus:ring-2 focus:ring-blue-500 text-sm shadow-sm text-gray-900 outline-none"
                  >
                  <option value="admin">Admin</option>
                  <option value="user">User</option>
                  </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Mật khẩu</label>
                <input 
                  type="text" 
                  value={formData.password}
                  onChange={(e) => setFormData({...formData, password: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-white focus:ring-2 focus:ring-blue-500 text-sm shadow-sm text-gray-900 outline-none"
                />
              </div>
            </div>

            <div className="p-6 border-t bg-gray-50 rounded-b-xl flex justify-end gap-3">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 shadow-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleSave}
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-sm"
              >
                <Save className="w-4 h-4" />
                Lưu
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Delete */}
      {userToDelete && (
        <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm animate-fade-in-up overflow-hidden">
            <div className="p-6">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-center text-gray-900 mb-2">Xác nhận xóa</h3>
              <p className="text-sm text-center text-gray-500">
                Bạn có chắc chắn muốn xóa <strong>{userToDelete.name}</strong>? 
                <br/>Dữ liệu OT liên quan cũng sẽ bị xóa.
              </p>
            </div>
            <div className="bg-gray-50 px-6 py-4 flex gap-3 justify-center">
              <button 
                onClick={() => setUserToDelete(null)}
                className="px-4 py-2 bg-white text-gray-700 font-medium rounded-lg border border-gray-300 hover:bg-gray-50 text-sm shadow-sm"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleDelete}
                className="px-4 py-2 bg-red-600 text-white font-medium rounded-lg hover:bg-red-700 text-sm shadow-md"
              >
                Xóa vĩnh viễn
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('18:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
  }, [user.id, currentDate]);

  const fetchRequests = async () => {
    setLoading(true);
    // Join với bảng users (database cũ) thay vì profiles
    let query = supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const calculateHours = (dateStr: string, start: string, end: string, isSat: boolean) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    if (day === 6 && isSat) {
        if (startVal < 14.5) startVal = 14.5;
    }

    let diff = endVal - startVal;
    if (diff <= 0) return 0;

    if (day === 6 && isSat) {
        if (diff > 4) diff -= 0.5;
    } else if (day === 0) {
        if (diff > 5) diff -= 1;
        if (diff > 11) diff = 11;
    }

    return parseFloat(diff.toFixed(2));
  };

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(selectedDateStr, startTime, endTime, isSaturdayWork);
  }, [selectedDateStr, startTime, endTime, isSaturdayWork]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending' // Default as per DB default, but nice to be explicit
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        alert("Lỗi: " + error.message);
    }
    setIsSubmitting(false);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

        days.push(
            <div 
                key={d} 
                onClick={() => {
                    setSelectedDateStr(dateStr);
                    if (dateObj.getDay() === 6) setIsSaturdayWork(true);
                    else setIsSaturdayWork(false);
                    setIsModalOpen(true);
                }}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                        {d}
                    </span>
                    {myRequest && (
                        <div>
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                        </div>
                    )}
                </div>

                <div className="mt-2 flex flex-wrap gap-1 content-start h-16 overflow-hidden">
                    {dayRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className={`w-7 h-7 rounded-full flex items-center justify-center border-2 border-white shadow-sm overflow-hidden ${req.user_id === user.id ? 'ring-2 ring-blue-300 z-10' : ''}`} 
                            title={`${req.users?.name} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-100 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                            </div>
                        </div>
                    ))}
                    {dayRequests.length > 4 && (
                        <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 4}
                        </div>
                    )}
                </div>
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        <div className="flex items-center gap-3 p-3 bg-orange-50 rounded-lg border border-orange-100">
                             <input 
                                type="checkbox" 
                                id="sat_work" 
                                checked={isSaturdayWork} 
                                onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white"
                             />
                             <label htmlFor="sat_work" className="text-sm text-gray-700 select-none">
                                Áp dụng quy tắc <span className="font-bold">Ngày làm việc T7</span> <br/>
                                <span className="text-xs text-gray-500">(Bắt đầu tính từ 14:30, trừ nghỉ 0.5h nếu &gt;4h)</span>
                             </label>
                        </div>

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <span className="text-indigo-800 font-medium">Tổng giờ tính toán:</span>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Bell, User, CheckCircle2, XCircle, Clock, Info, ChevronRight, Loader2 } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, OvertimeRequest } from '../../../types';

interface HeaderProps {
  user: any;
}

interface NotificationItem {
  id: string;
  type: 'borrow' | 'overtime';
  title: string;
  message: string;
  time: string;
  status: 'pending' | 'approved' | 'rejected' | 'returned';
  isRead: boolean;
}

export const Header: React.FC<HeaderProps> = ({ user }) => {
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchNotifications = async () => {
    if (!user) return;
    setLoading(true);

    try {
      const isAdmin = user.role === 'admin';
      const notifs: NotificationItem[] = [];

      // 1. Fetch Borrow Requests
      let borrowQuery = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false })
        .limit(10);

      if (!isAdmin) {
        borrowQuery = borrowQuery.eq('user_id', user.id);
      }

      const { data: borrowData } = await borrowQuery;

      if (borrowData) {
        (borrowData as BorrowRequest[]).forEach(req => {
          let shouldNotify = false;
          let title = '';
          let message = '';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Yêu cầu mượn mới';
              message = `${req.user_name} muốn mượn ${req.tool_name}`;
            }
          } else {
            if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Cập nhật yêu cầu mượn';
              const statusText = req.status === 'approved' ? 'được duyệt' : req.status === 'rejected' ? 'bị từ chối' : 'đã trả';
              message = `Yêu cầu mượn "${req.tool_name}" đã ${statusText}`;
            }
          }

          if (shouldNotify) {
            notifs.push({
              id: `borrow-${req.id}`,
              type: 'borrow',
              title,
              message,
              time: req.borrow_date,
              status: req.status,
              isRead: false
            });
          }
        });
      }

      // 2. Fetch OT Requests (Join with users table)
      let otQuery = supabase
        .from('ot_requests')
        .select('*, users(employee_id)')
        .order('date', { ascending: false })
        .limit(5);

      if (!isAdmin) {
        otQuery = otQuery.eq('user_id', user.id);
      }

      const { data: otData } = await otQuery;

      if (otData) {
        (otData as OvertimeRequest[]).forEach(req => {
          let shouldNotify = false;
          let title = '';
          let message = '';

          const empCode = req.users?.employee_id || 'Nhân viên';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Đăng ký tăng ca mới';
              message = `${empCode} đăng ký OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')}`;
            }
          } else {
             if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Kết quả đăng ký OT';
              const statusText = req.status === 'approved' ? 'được duyệt' : 'bị từ chối';
              message = `OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')} đã ${statusText}`;
             }
          }

          if (shouldNotify) {
            notifs.push({
              id: `ot-${req.id}`,
              type: 'overtime',
              title,
              message,
              time: req.created_at || new Date().toISOString(),
              status: req.status,
              isRead: false
            });
          }
        });
      }

      notifs.sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());

      setNotifications(notifs);
      setUnreadCount(notifs.length);

    } catch (error) {
      console.error("Error fetching notifications", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 30000);
    return () => clearInterval(interval);
  }, [user]);

  const handleToggle = () => {
    setIsOpen(!isOpen);
    if (!isOpen && unreadCount > 0) {
        setTimeout(() => setUnreadCount(0), 1000); 
    }
  };

  const getTimeAgo = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return 'Vừa xong';
    if (diffMins < 60) return `${diffMins} phút trước`;
    if (diffHours < 24) return `${diffHours} giờ trước`;
    return `${diffDays} ngày trước`;
  };

  const getIcon = (item: NotificationItem) => {
    if (item.status === 'approved') return <CheckCircle2 className="w-5 h-5 text-green-500" />;
    if (item.status === 'rejected') return <XCircle className="w-5 h-5 text-red-500" />;
    if (item.status === 'pending') return <Clock className="w-5 h-5 text-yellow-500" />;
    if (item.status === 'returned') return <Info className="w-5 h-5 text-blue-500" />;
    return <Info className="w-5 h-5 text-gray-500" />;
  };

  return (
    <header className="bg-white border-b border-gray-200 h-16 px-8 flex items-center justify-between sticky top-0 z-20 shadow-sm">
      <div className="flex items-center gap-2 text-gray-500">
        <span className="text-sm font-medium">Hôm nay, {new Date().toLocaleDateString('vi-VN', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' })}</span>
      </div>

      <div className="flex items-center gap-6">
        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={handleToggle}
            className={`relative p-2 rounded-full transition-all duration-200 ${isOpen ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            <Bell className={`w-5 h-5 ${unreadCount > 0 ? 'animate-pulse-slow' : ''}`} />
            {unreadCount > 0 && (
              <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white flex items-center justify-center">
                 <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
              </span>
            )}
          </button>

          {isOpen && (
            <div className="absolute right-0 top-full mt-3 w-80 sm:w-96 bg-white rounded-xl shadow-2xl border border-gray-100 overflow-hidden animate-fade-in-up origin-top-right">
              <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-800">Thông báo</h3>
                <button onClick={fetchNotifications} title="Làm mới" className="text-gray-400 hover:text-blue-600">
                   {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <span className="text-xs font-medium">Làm mới</span>}
                </button>
              </div>

              <div className="max-h-[400px] overflow-y-auto">
                {notifications.length === 0 ? (
                  <div className="p-8 text-center text-gray-500 flex flex-col items-center">
                    <Bell className="w-10 h-10 text-gray-200 mb-2" />
                    <p className="text-sm">Không có thông báo mới</p>
                  </div>
                ) : (
                  <ul className="divide-y divide-gray-50">
                    {notifications.map((notif) => (
                      <li key={notif.id} className="p-4 hover:bg-blue-50/50 transition-colors group cursor-pointer">
                        <div className="flex gap-3">
                          <div className={`mt-1 flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center bg-white border shadow-sm`}>
                            {getIcon(notif)}
                          </div>
                          <div className="flex-1">
                            <div className="flex justify-between items-start">
                                <p className="text-sm font-semibold text-gray-800">{notif.title}</p>
                                <span className="text-[10px] text-gray-400 whitespace-nowrap ml-2">{getTimeAgo(notif.time)}</span>
                            </div>
                            <p className="text-sm text-gray-600 mt-0.5 line-clamp-2">{notif.message}</p>
                          </div>
                          {notif.status === 'pending' && user.role === 'admin' && (
                             <div className="self-center">
                                <ChevronRight className="w-4 h-4 text-gray-300 group-hover:text-blue-400" />
                             </div>
                          )}
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              {notifications.length > 0 && (
                 <div className="p-2 bg-gray-50 border-t border-gray-100 text-center">
                    <button className="text-xs font-medium text-blue-600 hover:text-blue-800 transition-colors">
                        Đánh dấu tất cả là đã đọc
                    </button>
                 </div>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 pl-6 border-l border-gray-200">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-semibold text-gray-800">{user?.name || 'Admin User'}</p>
            <p className="text-xs text-gray-500 uppercase flex items-center justify-end gap-1">
                {user?.role === 'admin' ? <CheckCircle2 className="w-3 h-3 text-blue-500"/> : null}
                {user?.role || 'Manager'}
            </p>
          </div>
          <div className="w-10 h-10 bg-gradient-to-br from-blue-100 to-blue-200 rounded-full flex items-center justify-center text-blue-600 shadow-inner border border-white overflow-hidden">
             {user?.avatarUrl ? (
                <img src={user.avatarUrl} alt="" className="w-full h-full object-cover" />
             ) : (
                <User className="w-5 h-5" />
             )}
          </div>
        </div>
      </div>
    </header>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('18:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
  }, [user.id, currentDate]);

  const fetchRequests = async () => {
    setLoading(true);
    // Join với bảng users (database cũ)
    // Lưu ý: Nếu Database chưa sửa FK thì query này có thể trả về users: null
    let query = supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const calculateHours = (dateStr: string, start: string, end: string, isSat: boolean) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    if (day === 6 && isSat) {
        if (startVal < 14.5) startVal = 14.5;
    }

    let diff = endVal - startVal;
    if (diff <= 0) return 0;

    if (day === 6 && isSat) {
        if (diff > 4) diff -= 0.5;
    } else if (day === 0) {
        if (diff > 5) diff -= 1;
        if (diff > 11) diff = 11;
    }

    return parseFloat(diff.toFixed(2));
  };

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(selectedDateStr, startTime, endTime, isSaturdayWork);
  }, [selectedDateStr, startTime, endTime, isSaturdayWork]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        // Handle Foreign Key Error specifically
        if (error.message.includes('foreign key constraint') || error.message.includes('ot_requests_user_id_fkey')) {
            alert("Lỗi cấu hình Database: Bảng 'ot_requests' đang liên kết sai bảng. Vui lòng chạy lệnh SQL để sửa khóa ngoại trỏ về bảng 'users'.");
        } else {
            alert("Lỗi: " + error.message);
        }
    }
    setIsSubmitting(false);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

        days.push(
            <div 
                key={d} 
                onClick={() => {
                    setSelectedDateStr(dateStr);
                    if (dateObj.getDay() === 6) setIsSaturdayWork(true);
                    else setIsSaturdayWork(false);
                    setIsModalOpen(true);
                }}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                        {d}
                    </span>
                    {myRequest && (
                        <div>
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                        </div>
                    )}
                </div>

                <div className="mt-2 flex flex-wrap gap-1 content-start h-16 overflow-hidden">
                    {dayRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className={`w-7 h-7 rounded-full flex items-center justify-center border-2 border-white shadow-sm overflow-hidden ${req.user_id === user.id ? 'ring-2 ring-blue-300 z-10' : ''}`} 
                            title={`${req.users?.name || 'N/A'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-100 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                            </div>
                        </div>
                    ))}
                    {dayRequests.length > 4 && (
                        <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 4}
                        </div>
                    )}
                </div>
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        <div className="flex items-center gap-3 p-3 bg-orange-50 rounded-lg border border-orange-100">
                             <input 
                                type="checkbox" 
                                id="sat_work" 
                                checked={isSaturdayWork} 
                                onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white"
                             />
                             <label htmlFor="sat_work" className="text-sm text-gray-700 select-none">
                                Áp dụng quy tắc <span className="font-bold">Ngày làm việc T7</span> <br/>
                                <span className="text-xs text-gray-500">(Bắt đầu tính từ 14:30, trừ nghỉ 0.5h nếu &gt;4h)</span>
                             </label>
                        </div>

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <span className="text-indigo-800 font-medium">Tổng giờ tính toán:</span>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  // Mặc định 20:30 để khi trừ 0.5h nghỉ sẽ còn 2.5h làm việc
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
  }, [user.id, currentDate]);

  const fetchRequests = async () => {
    setLoading(true);
    // Join với bảng users (database cũ)
    let query = supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const calculateHours = (dateStr: string, start: string, end: string, isSat: boolean) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    // Logic cho ngày làm việc thứ 7 (Chỉ áp dụng khi Admin tích chọn)
    if (day === 6 && isSat) {
        if (startVal < 14.5) startVal = 14.5; // Bắt đầu từ 14:30
    }

    let diff = endVal - startVal;

    // Quy tắc mới: Luôn trừ 0.5 tiếng nghỉ
    if (diff > 0) {
        diff = diff - 0.5;
    }

    if (diff <= 0) return 0;

    return parseFloat(diff.toFixed(2));
  };

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(selectedDateStr, startTime, endTime, isSaturdayWork);
  }, [selectedDateStr, startTime, endTime, isSaturdayWork]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        if (error.message.includes('foreign key constraint') || error.message.includes('ot_requests_user_id_fkey')) {
            alert("Lỗi cấu hình Database: Bảng 'ot_requests' đang liên kết sai bảng. Vui lòng chạy lệnh SQL để sửa khóa ngoại trỏ về bảng 'users'.");
        } else {
            alert("Lỗi: " + error.message);
        }
    }
    setIsSubmitting(false);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

        days.push(
            <div 
                key={d} 
                onClick={() => {
                    setSelectedDateStr(dateStr);
                    // Reset trạng thái T7 khi mở modal. Admin phải tự tích nếu muốn.
                    setIsSaturdayWork(false); 
                    setIsModalOpen(true);
                }}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                        {d}
                    </span>
                    {myRequest && (
                        <div>
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                        </div>
                    )}
                </div>

                <div className="mt-2 flex flex-wrap gap-1 content-start h-16 overflow-hidden">
                    {dayRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className={`w-7 h-7 rounded-full flex items-center justify-center border-2 border-white shadow-sm overflow-hidden ${req.user_id === user.id ? 'ring-2 ring-blue-300 z-10' : ''}`} 
                            title={`${req.users?.name || 'N/A'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-100 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                            </div>
                        </div>
                    ))}
                    {dayRequests.length > 4 && (
                        <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 4}
                        </div>
                    )}
                </div>
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        <div className={`flex items-center gap-3 p-3 rounded-lg border ${user.role === 'admin' ? 'bg-orange-50 border-orange-100' : 'bg-gray-50 border-gray-200 opacity-75'}`}>
                             <input 
                                type="checkbox" 
                                id="sat_work" 
                                checked={isSaturdayWork} 
                                onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                disabled={user.role !== 'admin'}
                                className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white disabled:cursor-not-allowed"
                             />
                             <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                Áp dụng quy tắc <span className="font-bold">Ngày làm việc T7</span> <br/>
                                <span className="text-xs text-gray-500">
                                    {user.role === 'admin' 
                                        ? "(Bắt đầu tính từ 14:30)" 
                                        : "(Chỉ Admin mới có quyền chọn)"}
                                </span>
                             </label>
                        </div>

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ 0.5h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

export interface User {
  id: string;
  employeeCode: string; // Map từ users.employee_id
  role: string; // 'admin' | 'user'
  name: string; // Map từ users.name
  email?: string;
  // Avatar removed if not in old schema
}

// Map bảng 'users' cũ
export interface Employee {
  id: string;
  employee_id: string;
  name: string;
  role: string;
  password?: string;
  created_at?: string;
}

export interface Tool {
  id: string;
  name: string;
  category: string;
  quantity: number;
  available: number;
  description?: string;
  location?: string;
  image?: string;
  status: 'active' | 'inactive';
}

export interface BorrowRequest {
  id: string;
  employee_id: string;
  user_id: string;
  user_name: string;
  tool_id: string;
  tool_name: string;
  borrow_date: string;
  status: 'pending' | 'approved' | 'rejected' | 'returned';
  returned_at?: string;
}

// Map bảng 'ot_requests', join với 'users'
export interface OvertimeRequest {
  id: string;
  user_id: string;
  date: string;
  start_time: string;
  end_time: string;
  total_hours: number;
  reason: string;
  status: 'pending' | 'approved' | 'rejected';
  created_at?: string;
  // Join fields from users
  users?: {
    employee_id: string;
    name: string;
  };
}

// Map bảng 'day_configs'
export interface DayConfig {
  date: string; // YYYY-MM-DD
  is_working_day: boolean; // true = Đi làm, false = Nghỉ
}

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  // Khi chọn ngày hoặc thay đổi loại ngày (T7), tự động cập nhật giờ
  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    // Nếu là Thứ 7
    if (day === 6) {
        if (isSaturdayWork) {
            // T7 Đi làm: OT từ 14:30 - 20:00
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            // T7 Nghỉ: OT từ 08:00 - 20:00
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        // Ngày thường: 17:30 - 20:00
        setStartTime('17:30');
        setEndTime('20:00');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    let query = supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    // Lấy config của tháng hiện tại
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        // Upsert vào bảng day_configs
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;

        // Cập nhật state local
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;

    // Quy tắc: Luôn trừ 0.5 tiếng nghỉ (ăn tối/trưa)
    if (diff > 0.5) {
        diff = diff - 0.5;
    } else {
        return 0; // Nếu làm < 0.5h thì coi như bằng 0 sau khi trừ
    }

    return parseFloat(diff.toFixed(2));
  };

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ 0.5h phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        if (error.message.includes('foreign key constraint') || error.message.includes('ot_requests_user_id_fkey')) {
            alert("Lỗi cấu hình Database: Bảng 'ot_requests' đang liên kết sai bảng. Vui lòng chạy lệnh SQL để sửa khóa ngoại trỏ về bảng 'users'.");
        } else {
            alert("Lỗi: " + error.message);
        }
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);

    // Kiểm tra cấu hình có sẵn
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        // Nếu đã có config trong DB thì dùng, không thì mặc định T7 là Đi làm (true)
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

        // Config marker
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr]; // true/false or undefined

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex flex-col">
                        <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {/* Hiển thị trạng thái cấu hình T7 trên lịch */}
                        {isSat && configWork !== undefined && (
                            <span className={`text-[10px] font-bold mt-1 px-1 rounded ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div>
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                        </div>
                    )}
                </div>

                <div className="mt-2 flex flex-wrap gap-1 content-start h-16 overflow-hidden">
                    {dayRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className={`w-7 h-7 rounded-full flex items-center justify-center border-2 border-white shadow-sm overflow-hidden ${req.user_id === user.id ? 'ring-2 ring-blue-300 z-10' : ''}`} 
                            title={`${req.users?.name || 'N/A'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-100 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                            </div>
                        </div>
                    ))}
                    {dayRequests.length > 4 && (
                        <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 4}
                        </div>
                    )}
                </div>
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {/* Config Section for Saturday */}
                        {new Date(selectedDateStr).getDay() === 6 && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    {user.role === 'admin' && (
                                        <button 
                                            type="button" 
                                            onClick={handleSaveDayConfig}
                                            disabled={isSavingConfig}
                                            className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                            title="Lưu cấu hình này cho mọi người"
                                        >
                                            {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                            Lưu cấu hình
                                        </button>
                                    )}
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            disabled={user.role !== 'admin'}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white disabled:cursor-not-allowed peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            {user.role === 'admin' ? "(Admin có thể thay đổi và Lưu)" : "(Theo cấu hình của Admin)"}
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ 0.5h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  // Khi chọn ngày hoặc thay đổi loại ngày (T7), tự động cập nhật giờ
  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    // Nếu là Thứ 7
    if (day === 6) {
        if (isSaturdayWork) {
            // T7 Đi làm: OT từ 14:30 - 20:00
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            // T7 Nghỉ: OT từ 08:00 - 20:00
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        // Ngày thường: 17:30 - 20:00
        setStartTime('17:30');
        setEndTime('20:00');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    let query = supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    // Lấy config của tháng hiện tại
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        // Upsert vào bảng day_configs
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;

        // Cập nhật state local
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;

    // Quy tắc: Luôn trừ 0.5 tiếng nghỉ (ăn tối/trưa)
    if (diff > 0.5) {
        diff = diff - 0.5;
    } else {
        return 0; // Nếu làm < 0.5h thì coi như bằng 0 sau khi trừ
    }

    return parseFloat(diff.toFixed(2));
  };

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ 0.5h phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        if (error.message.includes('foreign key constraint') || error.message.includes('ot_requests_user_id_fkey')) {
            alert("Lỗi cấu hình Database: Bảng 'ot_requests' đang liên kết sai bảng. Vui lòng chạy lệnh SQL để sửa khóa ngoại trỏ về bảng 'users'.");
        } else {
            alert("Lỗi: " + error.message);
        }
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);

    // Kiểm tra cấu hình có sẵn
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        // Nếu đã có config trong DB thì dùng, không thì mặc định T7 là Đi làm (true)
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

        // Config marker
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr]; // true/false or undefined

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex flex-col">
                        <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {/* Hiển thị trạng thái cấu hình T7 trên lịch */}
                        {isSat && configWork !== undefined && (
                            <span className={`text-[10px] font-bold mt-1 px-1 rounded ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div>
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                        </div>
                    )}
                </div>

                <div className="mt-2 flex flex-wrap gap-1 content-start h-16 overflow-hidden">
                    {dayRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className={`w-7 h-7 rounded-full flex items-center justify-center border-2 border-white shadow-sm overflow-hidden ${req.user_id === user.id ? 'ring-2 ring-blue-300 z-10' : ''}`} 
                            title={`${req.users?.name || 'N/A'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-100 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                            </div>
                        </div>
                    ))}
                    {dayRequests.length > 4 && (
                        <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 4}
                        </div>
                    )}
                </div>
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {/* Config Section for Saturday - Only visible to Admin */}
                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                        title="Lưu cấu hình này cho mọi người"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu cấu hình
                                    </button>
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white cursor-pointer peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            (Admin có thể thay đổi và Lưu)
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ 0.5h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  // Khi chọn ngày hoặc thay đổi loại ngày (T7), tự động cập nhật giờ
  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    // Nếu là Thứ 7
    if (day === 6) {
        if (isSaturdayWork) {
            // T7 Đi làm: OT từ 14:30 - 20:00 (5.5h - 0.5h = 5h)
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            // T7 Nghỉ: OT từ 08:00 - 20:00 (12h - 1h = 11h)
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        // Ngày thường: 17:30 - 20:30 (3h - 0.5h = 2.5h)
        setStartTime('17:30');
        setEndTime('20:30');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    let query = supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    // Lấy config của tháng hiện tại
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        // Upsert vào bảng day_configs
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;

        // Cập nhật state local
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;

    // Quy tắc: 
    // - Nếu tổng thời gian >= 8h (ví dụ làm full ngày T7 nghỉ): Trừ 1h nghỉ
    // - Nếu < 8h (ngày thường, T7 đi làm): Trừ 0.5h nghỉ
    const deduction = diff >= 8 ? 1.0 : 0.5;

    if (diff > deduction) {
        diff = diff - deduction;
    } else {
        return 0; // Nếu làm < thời gian nghỉ
    }

    return parseFloat(diff.toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime]);

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        if (error.message.includes('foreign key constraint') || error.message.includes('ot_requests_user_id_fkey')) {
            alert("Lỗi cấu hình Database: Bảng 'ot_requests' đang liên kết sai bảng. Vui lòng chạy lệnh SQL để sửa khóa ngoại trỏ về bảng 'users'.");
        } else {
            alert("Lỗi: " + error.message);
        }
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);

    // Kiểm tra cấu hình có sẵn
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        // Nếu đã có config trong DB thì dùng, không thì mặc định T7 là Đi làm (true)
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

        // Config marker
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr]; // true/false or undefined

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex flex-col">
                        <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {/* Hiển thị trạng thái cấu hình T7 trên lịch */}
                        {isSat && configWork !== undefined && (
                            <span className={`text-[10px] font-bold mt-1 px-1 rounded ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div>
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                        </div>
                    )}
                </div>

                <div className="mt-2 flex flex-wrap gap-1 content-start h-16 overflow-hidden">
                    {dayRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className={`w-7 h-7 rounded-full flex items-center justify-center border-2 border-white shadow-sm overflow-hidden ${req.user_id === user.id ? 'ring-2 ring-blue-300 z-10' : ''}`} 
                            title={`${req.users?.name || 'N/A'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-100 flex items-center justify-center text-[10px] font-bold text-indigo-700">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                            </div>
                        </div>
                    ))}
                    {dayRequests.length > 4 && (
                        <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 4}
                        </div>
                    )}
                </div>
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {/* Config Section for Saturday - Only visible to Admin */}
                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                        title="Lưu cấu hình này cho mọi người"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu cấu hình
                                    </button>
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white cursor-pointer peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            (Admin có thể thay đổi và Lưu)
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ {currentDeduction}h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  // Khi chọn ngày hoặc thay đổi loại ngày (T7), tự động cập nhật giờ
  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    // Nếu là Thứ 7
    if (day === 6) {
        if (isSaturdayWork) {
            // T7 Đi làm: OT từ 14:30 - 20:00 (5.5h - 0.5h = 5h)
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            // T7 Nghỉ: OT từ 08:00 - 20:00 (12h - 1h = 11h)
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        // Ngày thường: 17:30 - 20:30 (3h - 0.5h = 2.5h)
        setStartTime('17:30');
        setEndTime('20:30');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    let query = supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (user.role !== 'admin') {
        // Fetch tất cả để hiển thị trên lịch, nhưng highlight chính mình
        query = supabase.from('ot_requests').select('*, users(employee_id, name)');
    }

    const { data, error } = await query;
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    // Lấy config của tháng hiện tại
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;

        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;
    const deduction = diff >= 8 ? 1.0 : 0.5;

    if (diff > deduction) {
        diff = diff - deduction;
    } else {
        return 0;
    }

    return parseFloat(diff.toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime]);

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        alert("Lỗi: " + error.message);
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        // Tách riêng đăng ký của bản thân để highlight
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                {/* Góc trên: Ngày và Trạng thái Admin duyệt */}
                <div className="flex justify-between items-start">
                    <div className="flex flex-col">
                        <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center shadow-sm' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[10px] font-bold mt-1 px-1 rounded ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="animate-pulse-slow">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-red-500" />}
                        </div>
                    )}
                </div>

                {/* Giữa ô: Hiển thị Avatars (Highlight Bạn trước) */}
                <div className="mt-2 flex flex-wrap gap-1 content-start h-16 overflow-hidden">
                    {myRequest && (
                        <div 
                            className="w-8 h-8 rounded-full flex items-center justify-center border-2 border-blue-600 shadow-md bg-blue-50 z-10" 
                            title={`Bạn (${myRequest.total_hours}h)`}
                        >
                            <span className="text-[10px] font-bold text-blue-700">TÔI</span>
                        </div>
                    )}

                    {otherRequests.slice(0, 3).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-7 h-7 rounded-full flex items-center justify-center border border-white shadow-sm bg-indigo-100 overflow-hidden" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <span className="text-[10px] font-bold text-indigo-700 uppercase">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                            </span>
                        </div>
                    ))}

                    {dayRequests.length > 4 && (
                        <div className="w-7 h-7 rounded-full bg-gray-100 flex items-center justify-center text-[10px] text-gray-500 border border-dashed border-gray-300">
                            +{dayRequests.length - 4}
                        </div>
                    )}
                </div>

                {/* Góc dưới: Huy hiệu số lượng người */}
                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-slate-800/90 text-white text-[9px] px-1.5 py-0.5 rounded-md font-bold flex items-center gap-0.5 shadow-sm">
                        <Users className="w-2.5 h-2.5" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu cấu hình
                                    </button>
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white cursor-pointer peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            (Admin có thể thay đổi và Lưu)
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ {currentDeduction}h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    if (day === 6) {
        if (isSaturdayWork) {
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        setStartTime('17:30');
        setEndTime('20:30');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    // Fetch all requests to display everyone on the calendar
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;
    const deduction = diff >= 8 ? 1.0 : 0.5;

    if (diff > deduction) {
        diff = diff - deduction;
    } else {
        return 0;
    }

    return parseFloat(diff.toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime]);

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        alert("Lỗi: " + error.message);
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                {/* Header ô lịch */}
                <div className="flex justify-between items-start">
                    <div className="flex flex-col">
                        <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-full flex items-center justify-center shadow-sm' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[9px] font-bold mt-1 px-1 rounded ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-3.5 h-3.5 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-3.5 h-3.5 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-3.5 h-3.5 text-red-500" />}
                        </div>
                    )}
                </div>

                {/* Body ô lịch: Avatar Hiển thị */}
                <div className="flex-1 mt-1 flex flex-col items-center justify-center">
                    {/* Hàng 1: Bạn (To hơn, có tích xanh) */}
                    {myRequest && (
                        <div className="relative mb-1">
                            <div 
                                className="w-9 h-9 rounded-full flex items-center justify-center border-2 border-blue-600 shadow-md bg-blue-50 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[9px] font-bold text-blue-700">TÔI</span>
                            </div>
                            {/* Dấu tích xanh nhỏ trên avatar */}
                            <div className="absolute -top-1 -right-1 bg-white rounded-full p-0.5 shadow-sm">
                                <CheckCircle2 className="w-3 h-3 text-green-500 fill-white" />
                            </div>
                        </div>
                    )}

                    {/* Hàng 2: Đồng nghiệp (Nhỏ hơn) */}
                    <div className="flex flex-wrap gap-0.5 justify-center">
                        {otherRequests.slice(0, 4).map((req, idx) => (
                            <div 
                                key={idx} 
                                className="w-5 h-5 rounded-full flex items-center justify-center border border-white shadow-sm bg-indigo-50 overflow-hidden" 
                                title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                            >
                                <span className="text-[8px] font-bold text-indigo-700 uppercase">
                                    {req.users?.name?.charAt(0) || <UserIcon className="w-2 h-2"/>}
                                </span>
                            </div>
                        ))}
                        {otherRequests.length > 4 && (
                            <div className="w-5 h-5 rounded-full bg-gray-100 flex items-center justify-center text-[7px] text-gray-500 border border-dashed border-gray-300">
                                +{otherRequests.length - 4}
                            </div>
                        )}
                    </div>
                </div>

                {/* Huy hiệu tổng số người ở góc dưới */}
                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-slate-800/80 text-white text-[8px] px-1.5 py-0.5 rounded font-bold flex items-center gap-0.5 shadow-sm">
                        <Users className="w-2 h-2" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu cấu hình
                                    </button>
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white cursor-pointer peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            (Admin có thể thay đổi và Lưu)
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ {currentDeduction}h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    if (day === 6) {
        if (isSaturdayWork) {
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        setStartTime('17:30');
        setEndTime('20:30');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;
    const deduction = diff >= 8 ? 1.0 : 0.5;

    if (diff > deduction) {
        diff = diff - deduction;
    } else {
        return 0;
    }

    return parseFloat(diff.toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime]);

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        alert("Lỗi: " + error.message);
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                {/* Header: Ngày và trạng thái Duyệt */}
                <div className="flex justify-between items-start mb-1">
                    <div className="flex flex-col">
                        <span className={`text-sm font-medium ${isToday ? 'bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center shadow-sm' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[8px] font-bold mt-0.5 px-1 rounded w-fit ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-3 h-3 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-3 h-3 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-3 h-3 text-red-500" />}
                        </div>
                    )}
                </div>

                {/* Body: Danh sách Avatars sắp xếp Trái -> Phải */}
                <div className="flex flex-wrap gap-1 items-center mt-auto mb-auto">
                    {/* Ảnh của tôi (Highlight, có tích xanh) */}
                    {myRequest && (
                        <div className="relative">
                            <div 
                                className="w-7 h-7 rounded-full flex items-center justify-center border-2 border-blue-600 shadow-sm bg-blue-50 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[8px] font-bold text-blue-700 leading-none">TÔI</span>
                            </div>
                            <div className="absolute -top-1 -right-1 bg-white rounded-full p-0.5 shadow-xs border border-gray-100">
                                <CheckCircle2 className="w-2.5 h-2.5 text-green-500 fill-white" />
                            </div>
                        </div>
                    )}

                    {/* Ảnh đồng nghiệp (Nhỏ hơn) */}
                    {otherRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-5 h-5 rounded-full flex items-center justify-center border border-white shadow-xs bg-indigo-50 overflow-hidden" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <span className="text-[7px] font-bold text-indigo-700 uppercase">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-2 h-2"/>}
                            </span>
                        </div>
                    ))}

                    {otherRequests.length > 4 && (
                        <div className="w-5 h-5 rounded-full bg-gray-100 flex items-center justify-center text-[7px] text-gray-500 border border-dashed border-gray-300">
                            +{otherRequests.length - 4}
                        </div>
                    )}
                </div>

                {/* Footer: Huy hiệu tổng số người */}
                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-slate-800/80 text-white text-[8px] px-1 py-0.5 rounded font-bold flex items-center gap-0.5 shadow-sm">
                        <Users className="w-2 h-2" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500">
                <div className="flex items-center justify-between p-4 border-b border-gray-100">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-bold ${i >= 5 ? 'text-red-500' : 'text-gray-500'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu cấu hình
                                    </button>
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white cursor-pointer peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            (Admin có thể thay đổi và Lưu)
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ {currentDeduction}h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    if (day === 6) {
        if (isSaturdayWork) {
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        setStartTime('17:30');
        setEndTime('20:30');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;
    const deduction = diff >= 8 ? 1.0 : 0.5;

    if (diff > deduction) {
        diff = diff - deduction;
    } else {
        return 0;
    }

    return parseFloat(diff.toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime]);

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        alert("Lỗi: " + error.message);
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                {/* Header: Ngày và trạng thái Duyệt */}
                <div className="flex justify-between items-start mb-0.5">
                    <div className="flex flex-col">
                        <span className={`text-sm font-bold ${isToday ? 'bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center shadow-sm' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[8px] font-bold mt-0.5 px-1 rounded w-fit ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-3 h-3 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-3 h-3 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-3 h-3 text-red-500" />}
                        </div>
                    )}
                </div>

                {/* Dòng 1: Ảnh của tôi (Highlight riêng biệt ở dòng trên) */}
                <div className="h-8 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative">
                            <div 
                                className="w-7 h-7 rounded-full flex items-center justify-center border-2 border-blue-600 shadow-sm bg-blue-50 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[8px] font-bold text-blue-700 leading-none">TÔI</span>
                            </div>
                            <div className="absolute -top-1 -right-1 bg-white rounded-full p-0.5 shadow-xs border border-gray-100">
                                <CheckCircle2 className="w-2.5 h-2.5 text-green-500 fill-white" />
                            </div>
                        </div>
                    )}
                </div>

                {/* Dòng 2: Ảnh đồng nghiệp (Dòng dưới, nhỏ hơn) */}
                <div className="flex flex-wrap gap-0.5 items-center">
                    {otherRequests.slice(0, 5).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-4.5 h-4.5 rounded-full flex items-center justify-center border border-white shadow-xs bg-indigo-50 overflow-hidden" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <span className="text-[7px] font-bold text-indigo-700 uppercase">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-2 h-2"/>}
                            </span>
                        </div>
                    ))}
                    {otherRequests.length > 5 && (
                        <div className="w-4.5 h-4.5 rounded-full bg-gray-100 flex items-center justify-center text-[7px] text-gray-500 border border-dashed border-gray-300">
                            +{otherRequests.length - 5}
                        </div>
                    )}
                </div>

                {/* Huy hiệu số lượng người - Màu Cam rực rỡ */}
                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-orange-500 text-white text-[9px] px-1.5 py-0.5 rounded-md font-black flex items-center gap-0.5 shadow-md transform group-hover:scale-110 transition-transform">
                        <Users className="w-2.5 h-2.5" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500 shadow-xl">
                <div className="flex items-center justify-between p-4 border-b border-gray-100 bg-white">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-black tracking-widest ${i >= 5 ? 'text-red-500' : 'text-gray-400'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu cấu hình
                                    </button>
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white cursor-pointer peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            (Admin có thể thay đổi và Lưu)
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ {currentDeduction}h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    const date = new Date(selectedDateStr);
    const day = date.getDay();

    if (day === 6) {
        if (isSaturdayWork) {
            setStartTime('14:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
    } else {
        setStartTime('17:30');
        setEndTime('20:30');
    }
  }, [selectedDateStr, isSaturdayWork]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;
    const deduction = diff >= 8 ? 1.0 : 0.5;

    if (diff > deduction) {
        diff = diff - deduction;
    } else {
        return 0;
    }

    return parseFloat(diff.toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime]);

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    const { error } = await supabase.from('ot_requests').insert([payload]);

    if (!error) {
        await fetchRequests();
        setIsModalOpen(false);
        setReason('');
    } else {
        alert("Lỗi: " + error.message);
    }
    setIsSubmitting(false);
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-28 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-28 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30' : 'bg-white'}`}
            >
                {/* Header: Ngày và trạng thái Duyệt */}
                <div className="flex justify-between items-start mb-0.5">
                    <div className="flex flex-col">
                        <span className={`text-sm font-bold ${isToday ? 'bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center shadow-sm' : isWeekend ? 'text-red-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[8px] font-bold mt-0.5 px-1 rounded w-fit ${configWork ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-3 h-3 text-green-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-3 h-3 text-yellow-500" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-3 h-3 text-red-500" />}
                        </div>
                    )}
                </div>

                {/* Dòng 1: Ảnh của tôi (Highlight riêng biệt ở dòng trên) */}
                <div className="h-8 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative">
                            <div 
                                className="w-7 h-7 rounded-full flex items-center justify-center border-2 border-blue-600 shadow-sm bg-blue-50 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[8px] font-bold text-blue-700 leading-none">TÔI</span>
                            </div>
                            <div className="absolute -top-1.5 -right-1.5 bg-white rounded-full p-0.5 shadow-md border border-gray-100">
                                <CheckCircle2 className="w-3.5 h-3.5 text-green-500 fill-white" />
                            </div>
                        </div>
                    )}
                </div>

                {/* Dòng 2: Ảnh đồng nghiệp (Dòng dưới, nhỏ hơn) */}
                <div className="flex flex-wrap gap-0.5 items-center">
                    {otherRequests.slice(0, 5).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-4.5 h-4.5 rounded-full flex items-center justify-center border border-white shadow-xs bg-indigo-50 overflow-hidden" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <span className="text-[7px] font-bold text-indigo-700 uppercase">
                                {req.users?.name?.charAt(0) || <UserIcon className="w-2 h-2"/>}
                            </span>
                        </div>
                    ))}
                    {otherRequests.length > 5 && (
                        <div className="w-4.5 h-4.5 rounded-full bg-gray-100 flex items-center justify-center text-[7px] text-gray-500 border border-dashed border-gray-300">
                            +{otherRequests.length - 5}
                        </div>
                    )}
                </div>

                {/* Huy hiệu số lượng người - Màu Cam rực rỡ */}
                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-orange-500 text-white text-[9px] px-1.5 py-0.5 rounded-md font-black flex items-center gap-0.5 shadow-md transform group-hover:scale-110 transition-transform">
                        <Users className="w-2.5 h-2.5" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 border border-indigo-200">v2.0</span>
                </h2>
                <p className="text-sm text-gray-500">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1 rounded-lg border border-gray-200">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-4 border-t-indigo-500 shadow-xl">
                <div className="flex items-center justify-between p-4 border-b border-gray-100 bg-white">
                    <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft className="w-5 h-5 text-gray-600" /></button>
                    <h3 className="text-lg font-bold text-gray-800 uppercase tracking-wide">
                        Tháng {currentDate.getMonth() + 1}, {currentDate.getFullYear()}
                    </h3>
                    <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight className="w-5 h-5 text-gray-600" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-3 text-center text-xs font-black tracking-widest ${i >= 5 ? 'text-red-500' : 'text-gray-400'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-500 to-purple-600 text-white border-none">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-bold text-lg">Tổng giờ OT</h3>
                        </div>
                        <p className="text-3xl font-bold">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-sm opacity-80 mt-1">Tháng {currentDate.getMonth() + 1}</p>
                    </Card>

                    <Card className="bg-white border-l-4 border-green-500">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-6 h-6 text-green-600" />
                            <h3 className="font-bold">Nhân sự OT</h3>
                        </div>
                        <p className="text-3xl font-bold text-gray-800">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-sm text-gray-500 mt-1">Người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors border-dashed border-2 border-gray-300 shadow-none" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-8 h-8 text-green-600 mx-auto mb-2" />
                            <span className="font-bold text-green-700 block">Xuất Excel</span>
                            <span className="text-xs text-gray-500">Tải báo cáo tháng</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ tăng ca tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px]">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis dataKey="day" />
                            <YAxis />
                            <Tooltip cursor={{fill: '#f0f9ff'}} />
                            <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} name="Giờ làm" />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg animate-fade-in-up overflow-hidden">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white">
                        <div>
                            <h3 className="text-lg font-bold">Đăng ký OT</h3>
                            <p className="text-indigo-200 text-sm flex items-center gap-2">
                                <CalendarIcon className="w-3.5 h-3.5" /> 
                                {selectedDateStr.split('-').reverse().join('/')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-2 rounded-full transition-colors">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 space-y-5">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-3 bg-white border border-gray-300 rounded-lg text-lg font-semibold focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 shadow-sm" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-4 rounded-xl border transition-colors ${isSaturdayWork ? 'bg-blue-50 border-blue-200' : 'bg-orange-50 border-orange-200'}`}>
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-sm text-gray-800 flex items-center gap-2">
                                        <Settings className="w-4 h-4" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-xs bg-white border border-gray-300 px-2 py-1 rounded shadow-sm hover:bg-gray-50 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu cấu hình
                                    </button>
                                </div>

                                <div className="flex items-center gap-3">
                                     <div className="relative flex items-center">
                                        <input 
                                            type="checkbox" 
                                            id="sat_work" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500 accent-indigo-600 bg-white cursor-pointer peer"
                                        />
                                     </div>
                                     <label htmlFor="sat_work" className="text-sm text-gray-700 select-none flex-1">
                                        {isSaturdayWork ? (
                                            <span>Đang chọn: <span className="font-bold text-blue-700">Đi làm</span> (14:30 - 20:00)</span>
                                        ) : (
                                            <span>Đang chọn: <span className="font-bold text-orange-700">Ngày nghỉ</span> (08:00 - 20:00)</span>
                                        )}
                                        <span className="block text-xs text-gray-500 mt-0.5">
                                            (Admin có thể thay đổi và Lưu)
                                        </span>
                                     </label>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-4 bg-indigo-50 rounded-xl border border-indigo-100">
                            <div>
                                <span className="text-indigo-800 font-medium block">Tổng giờ tính toán:</span>
                                <span className="text-xs text-indigo-400 font-normal">(Đã trừ {currentDeduction}h nghỉ)</span>
                            </div>
                            <span className="text-2xl font-bold text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-xs font-bold text-gray-500 uppercase">Lý do / Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-xs flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-medium transition-colors disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-sm h-24 resize-none bg-white text-gray-900 shadow-sm"
                                placeholder="Nhập công việc cụ thể..."
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                            Gửi Đăng Ký
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, CheckSquare, 
  ChevronRight, ArrowUpCircle, Info
} from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | { type: 'bulk_cancel' }
  | { type: 'bulk_return' }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      // Enhanced Sorting: Pending > Approved > Returned > Rejected
      enrichedData.sort((a, b) => {
          const statusOrder: Record<string, number> = {
              'pending': 0,
              'approved': 1,
              'returned': 2,
              'rejected': 3
          };

          if (statusOrder[a.status] !== statusOrder[b.status]) {
              return statusOrder[a.status] - statusOrder[b.status];
          }
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
      setSelectedIds(new Set());
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDate = true;
      if (filterStartDate) {
        const reqDate = new Date(req.borrow_date).setHours(0,0,0,0);
        matchesDate = reqDate >= new Date(filterStartDate).setHours(0,0,0,0);
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      showToast(`Đã duyệt thành công cho ${req.user_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang xử lý...', 'info');
    setProcessingId(req.id);
    try {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang nhận lại đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id);
        showToast('Đã xác nhận trả thiết bị.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy đơn...', 'info');
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu thành công.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': return 'bg-amber-100 text-amber-700 border-amber-200 ring-amber-500/20';
      case 'approved': return 'bg-emerald-100 text-emerald-700 border-emerald-200 ring-emerald-500/20';
      case 'returned': return 'bg-sky-100 text-sky-700 border-sky-200 ring-sky-500/20';
      case 'rejected': return 'bg-rose-100 text-rose-700 border-rose-200 ring-rose-500/20';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-3.5 h-3.5 animate-pulse" />;
      case 'approved': return <CheckCircle2 className="w-3.5 h-3.5" />;
      case 'returned': return <RotateCcw className="w-3.5 h-3.5" />;
      case 'rejected': return <Ban className="w-3.5 h-3.5" />;
      default: return <Info className="w-3.5 h-3.5" />;
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-50 rounded-2xl">
                <Wrench className="w-6 h-6 text-blue-600" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Yêu cầu</h2>
                <p className="text-sm text-gray-500 font-medium">Theo dõi mượn trả tài sản</p>
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-100 p-1.5 rounded-xl shadow-inner self-start">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
        </div>

        <div className="relative">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer text-gray-900 font-medium"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang sử dụng</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <Filter className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative">
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
            <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-gray-50/80 text-gray-500 font-bold uppercase tracking-widest text-[10px] border-b border-gray-100">
              <tr>
                <th className="px-8 py-5">Nhân viên</th>
                <th className="px-8 py-5">Thiết bị</th>
                <th className="px-8 py-5">Thời gian</th>
                <th className="px-8 py-5">Trạng thái</th>
                <th className="px-8 py-5 text-right">Hành động</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={5} className="p-20 text-center text-gray-400 font-medium italic">Không có dữ liệu phù hợp</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr key={req.id} className="hover:bg-blue-50/40 transition-all duration-300">
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold shadow-sm ${
                                req.user_id === user.id ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[10px] bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded font-black">BẠN</span>}
                                </div>
                                <div className="text-[11px] text-gray-400 font-mono">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className="w-12 h-12 bg-gray-50 rounded-xl border border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-1.5 group-hover:scale-110 transition-transform">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-5 h-5 text-gray-300" />}
                            </div>
                            <span className="font-bold text-gray-800 text-sm">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex flex-col">
                            <span className="text-gray-900 font-bold">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-[11px] text-gray-400 font-medium">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <span className={`inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-[11px] font-black border uppercase tracking-wider ring-4 ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {req.status === 'pending' ? 'Chờ duyệt' : 
                             req.status === 'approved' ? 'Đang mượn' : 
                             req.status === 'returned' ? 'Đã trả' : 'Từ chối'}
                        </span>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                            <>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })}
                                    className="p-2 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 transition-all shadow-md shadow-emerald-200" 
                                    title="Duyệt"
                                >
                                    <Check className="w-4 h-4" />
                                </button>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })}
                                    className="p-2 bg-white text-rose-600 border border-rose-100 rounded-xl hover:bg-rose-50 transition-all" 
                                    title="Từ chối"
                                >
                                    <X className="w-4 h-4" />
                                </button>
                            </>
                        )}

                        {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                            <button
                                onClick={() => setConfirmAction({ type: 'return', req })}
                                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all text-xs font-bold shadow-lg shadow-blue-200"
                            >
                                <RotateCcw className="w-3.5 h-3.5" /> 
                                Thu hồi
                            </button>
                        )}

                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                className="flex items-center gap-1.5 text-rose-600 hover:text-white hover:bg-rose-600 border border-rose-100 px-4 py-2 rounded-xl text-xs font-black transition-all"
                            >
                                <Trash2 className="w-3.5 h-3.5" />
                                Hủy đơn
                            </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-8 text-center">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                <AlertTriangle className="w-8 h-8" />
              </div>
              <h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tight">Xác nhận thao tác</h3>
              <p className="text-sm text-gray-500 font-medium leading-relaxed">
                Bạn có chắc chắn muốn thực hiện hành động này? Dữ liệu hệ thống sẽ được cập nhật ngay lập tức.
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex gap-3">
              <button 
                onClick={() => setConfirmAction(null)}
                className="flex-1 py-3 bg-white text-gray-700 font-bold rounded-2xl border border-gray-200 hover:bg-gray-100 text-sm transition-all"
              >
                Đóng
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`flex-1 py-3 text-white font-bold rounded-2xl text-sm shadow-xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle
} from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      // Priority Sorting: Pending (0) > Approved (1) > Returned (2) > Rejected (3)
      enrichedData.sort((a, b) => {
          const statusOrder: Record<string, number> = {
              'pending': 0,
              'approved': 1,
              'returned': 2,
              'rejected': 3
          };

          if (statusOrder[a.status] !== statusOrder[b.status]) {
              return statusOrder[a.status] - statusOrder[b.status];
          }
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDate = true;
      if (filterStartDate) {
        const reqDate = new Date(req.borrow_date).setHours(0,0,0,0);
        matchesDate = reqDate >= new Date(filterStartDate).setHours(0,0,0,0);
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      showToast(`Đã duyệt thành công cho ${req.user_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang xử lý...', 'info');
    setProcessingId(req.id);
    try {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang nhận lại đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id);
        showToast('Đã xác nhận trả thiết bị.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy đơn...', 'info');
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu thành công.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  // VIBRANT STATUS STYLES
  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-50 text-amber-600 border-amber-200 ring-amber-500/10';
      case 'approved': 
        return 'bg-emerald-50 text-emerald-600 border-emerald-200 ring-emerald-500/10';
      case 'returned': 
        return 'bg-sky-50 text-sky-600 border-sky-200 ring-sky-500/10';
      case 'rejected': 
        return 'bg-rose-50 text-rose-600 border-rose-200 ring-rose-500/10';
      default: 
        return 'bg-gray-50 text-gray-600 border-gray-200';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4 animate-pulse" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'Chờ phê duyệt';
      case 'approved': return 'Đang sử dụng';
      case 'returned': return 'Đã hoàn trả';
      case 'rejected': return 'Đã từ chối';
      default: return 'Không xác định';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-50 rounded-2xl">
                <Wrench className="w-6 h-6 text-blue-600" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Yêu cầu</h2>
                <p className="text-sm text-gray-500 font-medium">Theo dõi mượn trả tài sản hệ thống</p>
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-100 p-1.5 rounded-xl shadow-inner self-start">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của tôi
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
        </div>

        <div className="relative">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer text-gray-900 font-medium"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang sử dụng</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <Filter className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative">
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
            <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-gray-50/80 text-gray-500 font-bold uppercase tracking-widest text-[10px] border-b border-gray-100">
              <tr>
                <th className="px-8 py-5">Nhân viên</th>
                <th className="px-8 py-5">Thiết bị</th>
                <th className="px-8 py-5">Thời gian</th>
                <th className="px-8 py-5">Trạng thái</th>
                <th className="px-8 py-5 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {loading ? (
                <tr><td colSpan={5} className="p-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={5} className="p-20 text-center text-gray-400 font-medium italic">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr key={req.id} className={`hover:bg-blue-50/20 transition-all duration-300 ${req.status === 'pending' ? 'bg-amber-50/10' : ''}`}>
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold shadow-sm ${
                                req.user_id === user.id ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[9px] bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded-md font-black">BẠN</span>}
                                </div>
                                <div className="text-[11px] text-gray-400 font-mono tracking-tight">{req.employee_id}</div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className="w-12 h-12 bg-gray-50 rounded-xl border border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-1.5 transition-transform hover:scale-110">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-5 h-5 text-gray-300" />}
                            </div>
                            <span className="font-bold text-gray-800 text-sm">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex flex-col">
                            <span className="text-gray-900 font-bold">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                            <span className="text-[11px] text-gray-400 font-medium">{new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-[11px] font-black border uppercase tracking-widest ring-4 transition-all ${getStatusStyle(req.status)} shadow-sm`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex justify-end gap-2 items-center">
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                            <>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })}
                                    className="p-2.5 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/20 active:scale-95" 
                                    title="Duyệt"
                                >
                                    <Check className="w-4 h-4" />
                                </button>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })}
                                    className="p-2.5 bg-white text-rose-600 border border-rose-100 rounded-xl hover:bg-rose-50 transition-all shadow-sm active:scale-95" 
                                    title="Từ chối"
                                >
                                    <X className="w-4 h-4" />
                                </button>
                            </>
                        )}

                        {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                            <button
                                onClick={() => setConfirmAction({ type: 'return', req })}
                                className="flex items-center gap-2 px-4 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all text-xs font-bold shadow-lg shadow-blue-600/20 active:scale-95"
                            >
                                <RotateCcw className="w-4 h-4" /> 
                                Nhận trả đồ
                            </button>
                        )}

                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                className="flex items-center gap-1.5 text-rose-600 hover:text-white hover:bg-rose-600 border border-rose-200 px-4 py-2 rounded-xl text-xs font-black transition-all shadow-sm active:scale-95"
                            >
                                <Trash2 className="w-4 h-4" />
                                Hủy đơn
                            </button>
                        )}

                        {req.status === 'returned' && (
                           <div className="p-2 text-gray-300" title="Đã hoàn thành">
                              <CheckCircle2 className="w-5 h-5 opacity-40" />
                           </div>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-8 text-center">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-8 h-8" /> : <AlertTriangle className="w-8 h-8" />}
              </div>
              <h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tight">Xác nhận thao tác</h3>
              <p className="text-sm text-gray-500 font-medium leading-relaxed">
                {confirmAction.type === 'approve' ? 'Bạn có chắc chắn muốn duyệt yêu cầu mượn thiết bị này không?' : 
                 confirmAction.type === 'return' ? 'Xác nhận nhân viên đã hoàn trả thiết bị nguyên vẹn?' :
                 confirmAction.type === 'reject' ? 'Bạn sẽ từ chối yêu cầu này, hành động này không thể hoàn tác.' :
                 'Bạn có chắc muốn hủy yêu cầu mượn đồ này không?'}
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex gap-3">
              <button 
                onClick={() => setConfirmAction(null)}
                className="flex-1 py-3 bg-white text-gray-700 font-bold rounded-2xl border border-gray-200 hover:bg-gray-100 text-sm transition-all active:scale-95"
              >
                Đóng
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`flex-1 py-3 text-white font-bold rounded-2xl text-sm shadow-xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History
} from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      // ENHANCED PRIORITY SORTING: Pending (0) > Approved (1) > Returned (2) > Rejected (3)
      enrichedData.sort((a, b) => {
          const statusOrder: Record<string, number> = {
              'pending': 0,
              'approved': 1,
              'returned': 2,
              'rejected': 3
          };

          if (statusOrder[a.status] !== statusOrder[b.status]) {
              return statusOrder[a.status] - statusOrder[b.status];
          }
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDate = true;
      if (filterStartDate) {
        const reqDate = new Date(req.borrow_date).setHours(0,0,0,0);
        matchesDate = reqDate >= new Date(filterStartDate).setHours(0,0,0,0);
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      showToast(`Đã duyệt thành công cho ${req.user_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang xử lý...', 'info');
    setProcessingId(req.id);
    try {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang nhận lại đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id);
        showToast('Đã xác nhận trả thiết bị.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy đơn...', 'info');
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu thành công.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  // VIBRANT STATUS STYLES WITH INDICATORS
  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-100 text-amber-700 border-amber-300 ring-amber-500/30';
      case 'approved': 
        return 'bg-emerald-100 text-emerald-700 border-emerald-300 ring-emerald-500/30';
      case 'returned': 
        return 'bg-blue-100 text-blue-700 border-blue-300 ring-blue-500/30';
      case 'rejected': 
        return 'bg-rose-100 text-rose-700 border-rose-300 ring-rose-500/30';
      default: 
        return 'bg-gray-100 text-gray-700 border-gray-300';
    }
  };

  const getRowIndicator = (status: string) => {
    switch(status) {
      case 'pending': return 'border-l-[6px] border-l-amber-500';
      case 'approved': return 'border-l-[6px] border-l-emerald-500';
      case 'returned': return 'border-l-[6px] border-l-blue-500';
      case 'rejected': return 'border-l-[6px] border-l-rose-500';
      default: return '';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4 animate-pulse" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'ĐANG CHỜ';
      case 'approved': return 'ĐANG MƯỢN';
      case 'returned': return 'ĐÃ TRẢ';
      case 'rejected': return 'TỪ CHỐI';
      default: return 'X';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-50 rounded-2xl">
                <Wrench className="w-6 h-6 text-blue-600" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Yêu cầu</h2>
                <p className="text-sm text-gray-500 font-medium">Theo dõi mượn trả tài sản hệ thống</p>
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-100 p-1.5 rounded-xl shadow-inner self-start">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Tất cả yêu cầu
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của cá nhân
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
        </div>

        <div className="relative">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer text-gray-900 font-medium"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang sử dụng</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <Filter className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative">
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
            <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-gray-50/80 text-gray-500 font-bold uppercase tracking-widest text-[10px] border-b border-gray-100">
              <tr>
                <th className="px-8 py-5">Người mượn</th>
                <th className="px-8 py-5">Thông tin thiết bị</th>
                <th className="px-8 py-5">Thời gian yêu cầu</th>
                <th className="px-8 py-5">Trạng thái xử lý</th>
                <th className="px-8 py-5 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 bg-white">
              {loading ? (
                <tr><td colSpan={5} className="p-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={5} className="p-20 text-center text-gray-400 font-medium italic">Không tìm thấy yêu cầu nào phù hợp.</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/20 transition-all duration-300 ${getRowIndicator(req.status)} ${req.status === 'pending' ? 'animate-pulse-slow' : ''}`}
                  >
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className={`w-11 h-11 rounded-xl flex items-center justify-center font-bold shadow-md transition-transform hover:scale-105 ${
                                req.user_id === user.id ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white' : 'bg-gray-100 text-gray-700 border border-gray-200'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[9px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-lg font-black border border-blue-200 shadow-sm">BẠN</span>}
                                </div>
                                <div className="text-[11px] text-gray-400 font-mono tracking-tight mt-0.5 flex items-center gap-1">
                                    <UserIcon className="w-2.5 h-2.5" />
                                    {req.employee_id}
                                </div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className="w-14 h-14 bg-gray-50 rounded-xl border border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-1.5 transition-all hover:shadow-inner">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-200" />}
                            </div>
                            <span className="font-black text-gray-800 text-sm tracking-tight">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex flex-col gap-1">
                            <div className="flex items-center gap-1.5 text-gray-900 font-bold text-sm">
                                <Calendar className="w-3.5 h-3.5 text-blue-500" />
                                {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                            </div>
                            <div className="flex items-center gap-1.5 text-[11px] text-gray-400 font-medium">
                                <Clock className="w-3.5 h-3.5" />
                                {new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className={`inline-flex items-center gap-2.5 px-4 py-2 rounded-xl text-[10px] font-black border uppercase tracking-widest ring-4 transition-all shadow-md ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex justify-end gap-3 items-center">
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                            <>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })}
                                    className="p-3 bg-emerald-600 text-white rounded-2xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/30 active:scale-90" 
                                    title="Phê duyệt mượn"
                                >
                                    <Check className="w-5 h-5" />
                                </button>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })}
                                    className="p-3 bg-white text-rose-600 border border-rose-100 rounded-2xl hover:bg-rose-50 transition-all shadow-sm active:scale-90" 
                                    title="Từ chối yêu cầu"
                                >
                                    <X className="w-5 h-5" />
                                </button>
                            </>
                        )}

                        {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                            <button
                                onClick={() => setConfirmAction({ type: 'return', req })}
                                className="flex items-center gap-2 px-5 py-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all text-xs font-black shadow-lg shadow-blue-600/30 active:scale-95"
                            >
                                <RotateCcw className="w-4 h-4" /> 
                                THU HỒI
                            </button>
                        )}

                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                className="flex items-center gap-2 text-rose-600 hover:text-white hover:bg-rose-600 border border-rose-200 px-5 py-2.5 rounded-2xl text-xs font-black transition-all shadow-sm active:scale-95"
                            >
                                <Trash2 className="w-4 h-4" />
                                HỦY ĐƠN
                            </button>
                        )}

                        {req.status === 'returned' && (
                           <div className="p-2 text-emerald-500 bg-emerald-50 rounded-full border border-emerald-100 shadow-sm" title="Hoàn tất trả đồ">
                              <CheckCircle2 className="w-5 h-5" />
                           </div>
                        )}

                        {req.status === 'rejected' && (
                           <div className="p-2 text-rose-500 bg-rose-50 rounded-full border border-rose-100 shadow-sm" title="Đã bị từ chối">
                              <Ban className="w-5 h-5" />
                           </div>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-10 text-center">
              <div className={`w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl transform rotate-3 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-10 h-10" /> : <AlertTriangle className="w-10 h-10" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-3 uppercase tracking-tight">Cần bạn xác nhận</h3>
              <p className="text-sm text-gray-500 font-medium leading-relaxed px-4">
                {confirmAction.type === 'approve' ? 'Hành động này sẽ xác nhận nhân viên đã nhận được thiết bị. Hệ thống sẽ trừ tồn kho.' : 
                 confirmAction.type === 'return' ? 'Xác nhận thiết bị đã được hoàn trả nguyên vẹn về kho lưu trữ.' :
                 confirmAction.type === 'reject' ? 'Từ chối yêu cầu này? Lý do sẽ được thông báo cho nhân viên.' :
                 'Bạn muốn rút lại yêu cầu mượn thiết bị này?'}
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex gap-4 border-t border-gray-100">
              <button 
                onClick={() => setConfirmAction(null)}
                className="flex-1 py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 hover:bg-gray-100 text-xs uppercase tracking-widest transition-all active:scale-95"
              >
                Đóng
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`flex-1 py-4 text-white font-black rounded-2xl text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                Xác nhận ngay
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History
} from 'lucide-react';

interface RequestManagerProps {
  user: User;
}

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  // Mặc định thiết lập ngày hôm nay (định dạng YYYY-MM-DD)
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      // ENHANCED PRIORITY SORTING: Pending (0) > Approved (1) > Returned (2) > Rejected (3)
      enrichedData.sort((a, b) => {
          const statusOrder: Record<string, number> = {
              'pending': 0,
              'approved': 1,
              'returned': 2,
              'rejected': 3
          };

          if (statusOrder[a.status] !== statusOrder[b.status]) {
              return statusOrder[a.status] - statusOrder[b.status];
          }
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      // Logic lọc theo ngày chính xác (chỉ hiển thị ngày đã chọn, mặc định là hôm nay)
      let matchesDate = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        matchesDate = reqDateStr === filterStartDate;
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      showToast(`Đã duyệt thành công cho ${req.user_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang xử lý...', 'info');
    setProcessingId(req.id);
    try {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang nhận lại đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id);
        showToast('Đã xác nhận trả thiết bị.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy đơn...', 'info');
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu thành công.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  // VIBRANT STATUS STYLES WITH INDICATORS
  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-100 text-amber-700 border-amber-300 ring-amber-500/30';
      case 'approved': 
        return 'bg-emerald-100 text-emerald-700 border-emerald-300 ring-emerald-500/30';
      case 'returned': 
        return 'bg-blue-100 text-blue-700 border-blue-300 ring-blue-500/30';
      case 'rejected': 
        return 'bg-rose-100 text-rose-700 border-rose-300 ring-rose-500/30';
      default: 
        return 'bg-gray-100 text-gray-700 border-gray-300';
    }
  };

  const getRowIndicator = (status: string) => {
    switch(status) {
      case 'pending': return 'border-l-[6px] border-l-amber-500';
      case 'approved': return 'border-l-[6px] border-l-emerald-500';
      case 'returned': return 'border-l-[6px] border-l-blue-500';
      case 'rejected': return 'border-l-[6px] border-l-rose-500';
      default: return '';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4 animate-pulse" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'ĐANG CHỜ';
      case 'approved': return 'ĐANG MƯỢN';
      case 'returned': return 'ĐÃ TRẢ';
      case 'rejected': return 'TỪ CHỐI';
      default: return 'X';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-50 rounded-2xl">
                <Wrench className="w-6 h-6 text-blue-600" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Yêu cầu</h2>
                <p className="text-sm text-gray-500 font-medium">Theo dõi mượn trả tài sản hôm nay</p>
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-100 p-1.5 rounded-xl shadow-inner self-start">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của cá nhân
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
        </div>

        <div className="relative">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer text-gray-900 font-medium"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang sử dụng</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <Filter className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative">
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
            <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-gray-50/80 text-gray-500 font-bold uppercase tracking-widest text-[10px] border-b border-gray-100">
              <tr>
                <th className="px-8 py-5">Người mượn</th>
                <th className="px-8 py-5">Thông tin thiết bị</th>
                <th className="px-8 py-5">Thời gian yêu cầu</th>
                <th className="px-8 py-5">Trạng thái xử lý</th>
                <th className="px-8 py-5 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 bg-white">
              {loading ? (
                <tr><td colSpan={5} className="p-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-20 text-center text-gray-400 font-medium italic">
                    {filterStartDate === new Date().toISOString().split('T')[0] 
                      ? "Hôm nay chưa có yêu cầu mượn nào." 
                      : `Không tìm thấy yêu cầu nào vào ngày ${filterStartDate.split('-').reverse().join('/')}.`}
                  </td>
                </tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/20 transition-all duration-300 ${getRowIndicator(req.status)} ${req.status === 'pending' ? 'animate-pulse-slow' : ''}`}
                  >
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className={`w-11 h-11 rounded-xl flex items-center justify-center font-bold shadow-md transition-transform hover:scale-105 ${
                                req.user_id === user.id ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white' : 'bg-gray-100 text-gray-700 border border-gray-200'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[9px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-lg font-black border border-blue-200 shadow-sm">BẠN</span>}
                                </div>
                                <div className="text-[11px] text-gray-400 font-mono tracking-tight mt-0.5 flex items-center gap-1">
                                    <UserIcon className="w-2.5 h-2.5" />
                                    {req.employee_id}
                                </div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className="w-14 h-14 bg-gray-50 rounded-xl border border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-1.5 transition-all hover:shadow-inner">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-200" />}
                            </div>
                            <span className="font-black text-gray-800 text-sm tracking-tight">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex flex-col gap-1">
                            <div className="flex items-center gap-1.5 text-gray-900 font-bold text-sm">
                                <Calendar className="w-3.5 h-3.5 text-blue-500" />
                                {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                            </div>
                            <div className="flex items-center gap-1.5 text-[11px] text-gray-400 font-medium">
                                <Clock className="w-3.5 h-3.5" />
                                {new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className={`inline-flex items-center gap-2.5 px-4 py-2 rounded-xl text-[10px] font-black border uppercase tracking-widest ring-4 transition-all shadow-md ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex justify-end gap-3 items-center">
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                            <>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })}
                                    className="p-3 bg-emerald-600 text-white rounded-2xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/30 active:scale-90" 
                                    title="Phê duyệt mượn"
                                >
                                    <Check className="w-5 h-5" />
                                </button>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })}
                                    className="p-3 bg-white text-rose-600 border border-rose-100 rounded-2xl hover:bg-rose-50 transition-all shadow-sm active:scale-90" 
                                    title="Từ chối yêu cầu"
                                >
                                    <X className="w-5 h-5" />
                                </button>
                            </>
                        )}

                        {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                            <button
                                onClick={() => setConfirmAction({ type: 'return', req })}
                                className="flex items-center gap-2 px-5 py-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all text-xs font-black shadow-lg shadow-blue-600/30 active:scale-95"
                            >
                                <RotateCcw className="w-4 h-4" /> 
                                THU HỒI
                            </button>
                        )}

                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                className="flex items-center gap-2 text-rose-600 hover:text-white hover:bg-rose-600 border border-rose-200 px-5 py-2.5 rounded-2xl text-xs font-black transition-all shadow-sm active:scale-95"
                            >
                                <Trash2 className="w-4 h-4" />
                                HỦY ĐƠN
                            </button>
                        )}

                        {req.status === 'returned' && (
                           <div className="p-2 text-emerald-500 bg-emerald-50 rounded-full border border-emerald-100 shadow-sm" title="Hoàn tất trả đồ">
                              <CheckCircle2 className="w-5 h-5" />
                           </div>
                        )}

                        {req.status === 'rejected' && (
                           <div className="p-2 text-rose-500 bg-rose-50 rounded-full border border-rose-100 shadow-sm" title="Đã bị từ chối">
                              <Ban className="w-5 h-5" />
                           </div>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-10 text-center">
              <div className={`w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl transform rotate-3 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-10 h-10" /> : <AlertTriangle className="w-10 h-10" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-3 uppercase tracking-tight">Cần bạn xác nhận</h3>
              <p className="text-sm text-gray-500 font-medium leading-relaxed px-4">
                {confirmAction.type === 'approve' ? 'Hành động này sẽ xác nhận nhân viên đã nhận được thiết bị. Hệ thống sẽ trừ tồn kho.' : 
                 confirmAction.type === 'return' ? 'Xác nhận thiết bị đã được hoàn trả nguyên vẹn về kho lưu trữ.' :
                 confirmAction.type === 'reject' ? 'Từ chối yêu cầu này? Lý do sẽ được thông báo cho nhân viên.' :
                 'Bạn muốn rút lại yêu cầu mượn thiết bị này?'}
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex gap-4 border-t border-gray-100">
              <button 
                onClick={() => setConfirmAction(null)}
                className="flex-1 py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 hover:bg-gray-100 text-xs uppercase tracking-widest transition-all active:scale-95"
              >
                Đóng
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`flex-1 py-4 text-white font-black rounded-2xl text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                Xác nhận ngay
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Wrench, TrendingUp, Loader2, Package, ShoppingBag, BarChart as BarChartIcon } from 'lucide-react';

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d'];

interface SafeChartContainerProps {
  children: React.ReactNode;
  height?: number;
  hasData?: boolean;
}

/**
 * Component an toàn để bọc biểu đồ Recharts.
 * Giải quyết lỗi "width/height is -1" bằng cách theo dõi chính xác kích thước container cha.
 */
const SafeChartContainer: React.FC<SafeChartContainerProps> = ({ children, height = 300, hasData = true }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    if (!containerRef.current) return;

    // Sử dụng ResizeObserver để lấy kích thước chính xác của container
    const observer = new ResizeObserver((entries) => {
      if (!entries.length) return;
      const { width, height: contentHeight } = entries[0].contentRect;

      // Chỉ cập nhật khi kích thước hợp lệ
      if (width > 0) {
        setDimensions({ width, height: contentHeight || height });
      }
    });

    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [height]);

  // Hiển thị trạng thái trống nếu không có dữ liệu
  if (!hasData) {
    return (
      <div style={{ height }} className="w-full flex flex-col items-center justify-center bg-gray-50 rounded-lg border border-dashed border-gray-200">
         <div className="p-3 bg-gray-100 rounded-full mb-2">
            <BarChartIcon className="w-6 h-6 text-gray-400" />
         </div>
         <span className="text-gray-400 text-sm font-medium">Chưa có dữ liệu thống kê</span>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef} 
      style={{ 
        height: `${height}px`, 
        width: '100%', 
        position: 'relative',
        minWidth: '0px' // Quan trọng: ngăn flex container bị tràn
      }} 
      className="overflow-hidden" 
    >
      {/* Chỉ render ResponsiveContainer khi component đã mount và container có kích thước > 0 */}
      {isMounted && dimensions.width > 0 ? (
        <ResponsiveContainer width="100%" height="100%">
          {children as React.ReactElement}
        </ResponsiveContainer>
      ) : (
        <div className="w-full h-full flex flex-col items-center justify-center bg-gray-50/50 rounded-lg">
           <Loader2 className="w-5 h-5 text-blue-500 animate-spin mb-2" />
           <span className="text-gray-400 text-xs">Đang khởi tạo biểu đồ...</span>
        </div>
      )}
    </div>
  );
};

export const DashboardStats: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalToolsQuantity: 0,
    totalToolsAvailable: 0,
    borrowedTools: 0,
    pendingRequests: 0,
  });
  const [barData, setBarData] = useState<any[]>([]);
  const [pieData, setPieData] = useState<any[]>([]);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [toolsRes, requestsRes] = await Promise.all([
        supabase.from('tools').select('quantity, available, status'),
        supabase.from('requests').select('status, borrow_date')
      ]);

      const tools = toolsRes.data || [];
      const requests = requestsRes.data || [];

      // 1. Tính Tổng số lượng công cụ
      const totalToolsQuantity = tools.reduce((sum, tool) => sum + (tool.quantity || 0), 0);

      // 2. Tính Số lượng sẵn có
      const totalToolsAvailable = tools.reduce((sum, tool) => sum + (tool.status === 'active' ? (tool.available || 0) : 0), 0);

      // 3. Tính Số lượng đang mượn
      const borrowedTools = requests.filter(r => r.status === 'approved').length;

      // 4. Tính Số lượng chờ duyệt
      const pendingRequests = requests.filter(r => r.status === 'pending').length;

      setStats({
        totalToolsQuantity,
        totalToolsAvailable,
        borrowedTools,
        pendingRequests
      });

      // --- Biểu đồ Tròn: Phân bố trạng thái tài sản ---
      const pieChartData = [
        { name: 'Sẵn có', value: totalToolsAvailable },
        { name: 'Đang mượn', value: borrowedTools },
        { name: 'Khác/Bảo trì', value: Math.max(0, totalToolsQuantity - totalToolsAvailable - borrowedTools) },
      ];
      setPieData(pieChartData.filter(item => item.value > 0));

      // --- Biểu đồ Cột: Yêu cầu 7 ngày gần nhất ---
      const last7Days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        return {
            dateStr: d.toLocaleDateString('vi-VN'),
            dayName: d.toLocaleDateString('vi-VN', { weekday: 'short' }),
            fullDate: d.toISOString().split('T')[0]
        };
      });

      const chartData = last7Days.map(day => {
        const count = requests.filter(r => r.borrow_date.startsWith(day.fullDate)).length;
        return {
            name: day.dayName,
            fullDate: day.dateStr,
            requests: count
        };
      });

      setBarData(chartData);

    } catch (error) {
      console.error("Error fetching dashboard data:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
        <div className="flex h-96 items-center justify-center">
            <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
        </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card className="flex items-center gap-4 border-l-4 border-l-purple-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-purple-100 rounded-full text-purple-600">
            <Package className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500 font-medium">Tổng số công cụ</p>
            <p className="text-2xl font-bold text-gray-800">{stats.totalToolsQuantity}</p>
          </div>
        </Card>

        <Card className="flex items-center gap-4 border-l-4 border-l-orange-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-orange-100 rounded-full text-orange-600">
            <ShoppingBag className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500 font-medium">Đang cho mượn</p>
            <p className="text-2xl font-bold text-gray-800">{stats.borrowedTools}</p>
          </div>
        </Card>

        <Card className="flex items-center gap-4 border-l-4 border-l-green-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-green-100 rounded-full text-green-600">
            <Wrench className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500 font-medium">Sẵn có tại kho</p>
            <p className="text-2xl font-bold text-gray-800">{stats.totalToolsAvailable}</p>
          </div>
        </Card>

        <Card className="flex items-center gap-4 border-l-4 border-l-yellow-500 hover:shadow-md transition-shadow">
          <div className="p-3 bg-yellow-100 rounded-full text-yellow-600">
            <TrendingUp className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500 font-medium">Yêu cầu chờ duyệt</p>
            <p className="text-2xl font-bold text-gray-800">{stats.pendingRequests}</p>
          </div>
        </Card>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card title="Xu hướng mượn đồ (7 ngày qua)" className="min-w-0">
          <SafeChartContainer height={300} hasData={barData.some(d => d.requests > 0)}>
            <BarChart data={barData} margin={{ top: 10, right: 10, left: -25, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
              <XAxis 
