import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      enrichedData.sort((a, b) => {
          const statusOrder: Record<string, number> = {
              'pending': 0,
              'approved': 1,
              'returned': 2,
              'rejected': 3
          };
          if (statusOrder[a.status] !== statusOrder[b.status]) {
              return statusOrder[a.status] - statusOrder[b.status];
          }
          return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
      });

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      // Logic lọc theo ngày và trạng thái mượn chưa trả
      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        // Nếu đang lọc một trạng thái cụ thể (vd: Pending), chỉ hiện những cái matching date
        // Nếu đang để "Tất cả", hiện (Ngày được chọn) + (Tất cả những cái Đang mượn chưa trả)
        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      showToast(`Đã duyệt thành công cho ${req.user_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang xử lý...', 'info');
    setProcessingId(req.id);
    try {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang nhận lại đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id);
        showToast('Đã xác nhận trả thiết bị.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy đơn...', 'info');
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu thành công.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': return 'bg-amber-100 text-amber-700 border-amber-300 ring-amber-500/30';
      case 'approved': return 'bg-emerald-100 text-emerald-700 border-emerald-300 ring-emerald-500/30';
      case 'returned': return 'bg-blue-100 text-blue-700 border-blue-300 ring-blue-500/30';
      case 'rejected': return 'bg-rose-100 text-rose-700 border-rose-300 ring-rose-500/30';
      default: return 'bg-gray-100 text-gray-700 border-gray-300';
    }
  };

  const getRowIndicator = (status: string) => {
    switch(status) {
      case 'pending': return 'border-l-[6px] border-l-amber-500';
      case 'approved': return 'border-l-[6px] border-l-emerald-500';
      case 'returned': return 'border-l-[6px] border-l-blue-500';
      case 'rejected': return 'border-l-[6px] border-l-rose-500';
      default: return '';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4 animate-pulse" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'ĐANG CHỜ';
      case 'approved': return 'ĐANG MƯỢN';
      case 'returned': return 'ĐÃ TRẢ';
      case 'rejected': return 'TỪ CHỐI';
      default: return 'X';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-50 rounded-2xl">
                <Wrench className="w-6 h-6 text-blue-600" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Yêu cầu</h2>
                <p className="text-sm text-gray-500 font-medium">Lịch hôm nay & Thiết bị chưa trả</p>
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-100 p-1.5 rounded-xl shadow-inner self-start">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    Quản lý chung
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    Của cá nhân
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
        </div>

        <div className="relative">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer text-gray-900 font-medium"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang sử dụng</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <Filter className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative">
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            />
            <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-gray-50/80 text-gray-500 font-bold uppercase tracking-widest text-[10px] border-b border-gray-100">
              <tr>
                <th className="px-8 py-5">Người mượn</th>
                <th className="px-8 py-5">Thông tin thiết bị</th>
                <th className="px-8 py-5">Thời gian yêu cầu</th>
                <th className="px-8 py-5">Trạng thái xử lý</th>
                <th className="px-8 py-5 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 bg-white">
              {loading ? (
                <tr><td colSpan={5} className="p-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-20 text-center text-gray-400 font-medium italic">
                    {filterStartDate === new Date().toISOString().split('T')[0] 
                      ? "Hiện tại không có yêu cầu nào cần xử lý." 
                      : `Không tìm thấy yêu cầu nào vào ngày ${filterStartDate.split('-').reverse().join('/')}.`}
                  </td>
                </tr>
              ) : (
                filteredRequests.map((req) => {
                  const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
                  const isOldBorrowed = req.status === 'approved' && reqDateStr !== filterStartDate;

                  return (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/20 transition-all duration-300 ${getRowIndicator(req.status)} ${req.status === 'pending' ? 'animate-pulse-slow' : ''} ${isOldBorrowed ? 'bg-emerald-50/20' : ''}`}
                  >
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className={`w-11 h-11 rounded-xl flex items-center justify-center font-bold shadow-md transition-transform hover:scale-105 ${
                                req.user_id === user.id ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white' : 'bg-gray-100 text-gray-700 border border-gray-200'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[9px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-lg font-black border border-blue-200 shadow-sm">BẠN</span>}
                                </div>
                                <div className="text-[11px] text-gray-400 font-mono tracking-tight mt-0.5 flex items-center gap-1">
                                    <UserIcon className="w-2.5 h-2.5" />
                                    {req.employee_id}
                                </div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex items-center gap-3">
                            <div className="w-14 h-14 bg-gray-50 rounded-xl border border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-1.5 transition-all hover:shadow-inner">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-200" />}
                            </div>
                            <span className="font-black text-gray-800 text-sm tracking-tight">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className="flex flex-col gap-1">
                            <div className={`flex items-center gap-1.5 font-bold text-sm ${isOldBorrowed ? 'text-emerald-700' : 'text-gray-900'}`}>
                                <Calendar className="w-3.5 h-3.5 text-blue-500" />
                                {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                                {isOldBorrowed && (
                                    <span className="flex items-center gap-1 bg-emerald-100 text-emerald-800 text-[9px] px-1.5 py-0.5 rounded uppercase font-black ml-1">
                                        <AlertCircle className="w-2 h-2" /> Tồn
                                    </span>
                                )}
                            </div>
                            <div className="flex items-center gap-1.5 text-[11px] text-gray-400 font-medium">
                                <Clock className="w-3.5 h-3.5" />
                                {new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5">
                        <div className={`inline-flex items-center gap-2.5 px-4 py-2 rounded-xl text-[10px] font-black border uppercase tracking-widest ring-4 transition-all shadow-md ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex justify-end gap-3 items-center">
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                            <>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })}
                                    className="p-3 bg-emerald-600 text-white rounded-2xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/30 active:scale-90" 
                                    title="Phê duyệt mượn"
                                >
                                    <Check className="w-5 h-5" />
                                </button>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })}
                                    className="p-3 bg-white text-rose-600 border border-rose-100 rounded-2xl hover:bg-rose-50 transition-all shadow-sm active:scale-90" 
                                    title="Từ chối yêu cầu"
                                >
                                    <X className="w-5 h-5" />
                                </button>
                            </>
                        )}

                        {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                            <button
                                onClick={() => setConfirmAction({ type: 'return', req })}
                                className="flex items-center gap-2 px-5 py-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all text-xs font-black shadow-lg shadow-blue-600/30 active:scale-95"
                            >
                                <RotateCcw className="w-4 h-4" /> 
                                THU HỒI
                            </button>
                        )}

                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                className="flex items-center gap-2 text-rose-600 hover:text-white hover:bg-rose-600 border border-rose-200 px-5 py-2.5 rounded-2xl text-xs font-black transition-all shadow-sm active:scale-95"
                            >
                                <Trash2 className="w-4 h-4" />
                                HỦY ĐƠN
                            </button>
                        )}

                        {req.status === 'returned' && (
                           <div className="p-2 text-emerald-500 bg-emerald-50 rounded-full border border-emerald-100 shadow-sm" title="Hoàn tất trả đồ">
                              <CheckCircle2 className="w-5 h-5" />
                           </div>
                        )}

                        {req.status === 'rejected' && (
                           <div className="p-2 text-rose-500 bg-rose-50 rounded-full border border-rose-100 shadow-sm" title="Đã bị từ chối">
                              <Ban className="w-5 h-5" />
                           </div>
                        )}
                      </div>
                    </td>
                  </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-10 text-center">
              <div className={`w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-xl transform rotate-3 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-10 h-10" /> : <AlertTriangle className="w-10 h-10" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-3 uppercase tracking-tight">Cần bạn xác nhận</h3>
              <p className="text-sm text-gray-500 font-medium leading-relaxed px-4">
                {confirmAction.type === 'approve' ? 'Hành động này sẽ xác nhận nhân viên đã nhận được thiết bị. Hệ thống sẽ trừ tồn kho.' : 
                 confirmAction.type === 'return' ? 'Xác nhận thiết bị đã được hoàn trả nguyên vẹn về kho lưu trữ.' :
                 confirmAction.type === 'reject' ? 'Từ chối yêu cầu này? Lý do sẽ được thông báo cho nhân viên.' :
                 'Bạn muốn rút lại yêu cầu mượn thiết bị này?'}
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex gap-4 border-t border-gray-100">
              <button 
                onClick={() => setConfirmAction(null)}
                className="flex-1 py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 hover:bg-gray-100 text-xs uppercase tracking-widest transition-all active:scale-95"
              >
                Đóng
              </button>
              <button 
                onClick={handleConfirmAction}
                className={`flex-1 py-4 text-white font-black rounded-2xl text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                Xác nhận ngay
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  // Tìm yêu cầu của bản thân cho ngày đang chọn
  const myCurrentRequest = useMemo(() => {
    return requests.find(r => r.date === selectedDateStr && r.user_id === user.id);
  }, [requests, selectedDateStr, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    // Nếu đã có yêu cầu, điền thông tin cũ vào form
    if (myCurrentRequest) {
        setStartTime(myCurrentRequest.start_time);
        setEndTime(myCurrentRequest.end_time);
        setReason(myCurrentRequest.reason);
    } else {
        const date = new Date(selectedDateStr);
        const day = date.getDay();

        if (day === 6) {
            if (isSaturdayWork) {
                setStartTime('14:30');
                setEndTime('20:00');
            } else {
                setStartTime('08:00');
                setEndTime('20:00');
            }
        } else {
            setStartTime('17:30');
            setEndTime('20:30');
        }
        setReason('');
    }
  }, [selectedDateStr, isSaturdayWork, myCurrentRequest]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string) => {
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;
    if (diff <= 0) return 0;

    const deduction = diff >= 8 ? 1.0 : 0.5;

    if (diff > deduction) {
        diff = diff - deduction;
    } else {
        return 0;
    }

    return parseFloat(diff.toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime]);

  const calculatedHours = useMemo(() => {
     if (!selectedDateStr) return 0;
     return calculateHours(startTime, endTime);
  }, [startTime, endTime]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    let result;
    if (myCurrentRequest) {
        // Cập nhật nếu đã có
        result = await supabase.from('ot_requests').update(payload).eq('id', myCurrentRequest.id);
    } else {
        // Thêm mới nếu chưa có
        result = await supabase.from('ot_requests').insert([payload]);
    }

    if (!result.error) {
        await fetchRequests();
        setIsModalOpen(false);
    } else {
        alert("Lỗi: " + result.error.message);
    }
    setIsSubmitting(false);
  };

  const handleCancelRequest = async () => {
    if (!myCurrentRequest) return;
    if (!confirm("Bạn có chắc chắn muốn hủy yêu cầu tăng ca này không?")) return;

    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', myCurrentRequest.id);
        if (error) throw error;
        await fetchRequests();
        setIsModalOpen(false);
    } catch (error: any) {
        alert("Lỗi khi hủy: " + error.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                {/* Header: Ngày và trạng thái Duyệt */}
                <div className="flex justify-between items-start mb-1">
                    <div className="flex flex-col">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[9px] font-black mt-1 px-1.5 py-0.5 rounded shadow-sm w-fit ${configWork ? 'bg-blue-100 text-blue-700 border border-blue-200' : 'bg-orange-100 text-orange-700 border border-orange-200'}`}>
                                {configWork ? 'LÀM' : 'NGHỈ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1.5 p-1 bg-white rounded-lg shadow-sm border border-gray-100">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-emerald-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-amber-500 animate-pulse" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-rose-500" />}
                        </div>
                    )}
                </div>

                {/* Dòng 1: Ảnh của tôi - To rõ */}
                <div className="h-10 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div 
                                className="w-9 h-9 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[10px] font-black text-white leading-none">TÔI</span>
                            </div>
                            <div className="absolute -top-1.5 -right-1.5 bg-white rounded-full p-0.5 shadow-md border border-gray-100">
                                <CheckCircle2 className="w-4 h-4 text-emerald-500 fill-white" />
                            </div>
                        </div>
                    )}
                </div>

                {/* Dòng 2: Ảnh đồng nghiệp - To hơn chút để dễ nhìn */}
                <div className="flex flex-wrap gap-1 items-center">
                    {otherRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-6 h-6 rounded-lg flex items-center justify-center border border-white shadow-md bg-white overflow-hidden transform hover:scale-125 transition-transform" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-50 flex items-center justify-center">
                                <span className="text-[10px] font-black text-indigo-700 uppercase">
                                    {req.users?.name?.charAt(0) || <UserIcon className="w-3 h-3"/>}
                                </span>
                            </div>
                        </div>
                    ))}
                    {otherRequests.length > 4 && (
                        <div className="w-6 h-6 rounded-lg bg-gray-100 flex items-center justify-center text-[10px] font-black text-gray-500 border border-dashed border-gray-300 shadow-sm">
                            +{otherRequests.length - 4}
                        </div>
                    )}
                </div>

                {/* Huy hiệu số lượng người - Màu Cam rực rỡ */}
                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-orange-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black flex items-center gap-1 shadow-lg transform group-hover:scale-110 transition-transform border border-orange-400">
                        <Users className="w-3 h-3" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded-lg text-[10px] bg-indigo-100 text-indigo-700 border border-indigo-200 font-black uppercase">v2.1</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-8 border-t-indigo-600 shadow-2xl rounded-[2rem]">
                <div className="flex items-center justify-between p-6 border-b border-gray-100 bg-white">
                    <button onClick={prevMonth} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronLeft className="w-6 h-6 text-gray-700" /></button>
                    <div className="text-center">
                        <h3 className="text-xl font-black text-gray-900 uppercase tracking-widest">
                            Tháng {currentDate.getMonth() + 1}
                        </h3>
                        <p className="text-xs text-gray-400 font-bold tracking-widest mt-0.5">{currentDate.getFullYear()}</p>
                    </div>
                    <button onClick={nextMonth} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronRight className="w-6 h-6 text-gray-700" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50/80 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-4 text-center text-[10px] font-black tracking-[0.2em] ${i >= 5 ? 'text-rose-500' : 'text-gray-400'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-600 to-purple-700 text-white border-none shadow-xl shadow-indigo-200">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-black text-lg uppercase tracking-tight">Tổng giờ OT</h3>
                        </div>
                        <p className="text-4xl font-black tracking-tighter">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-xs opacity-70 mt-1 font-bold">Tháng {currentDate.getMonth() + 1} ({currentDate.getFullYear()})</p>
                    </Card>

                    <Card className="bg-white border-l-8 border-emerald-500 shadow-lg">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-7 h-7 text-emerald-600" />
                            <h3 className="font-black uppercase tracking-tight text-sm text-gray-500">Nhân sự tham gia</h3>
                        </div>
                        <p className="text-4xl font-black text-gray-900 tracking-tighter">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-xs text-gray-400 mt-1 font-bold">Tổng số người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-all border-dashed border-2 border-gray-300 shadow-none group active:scale-95" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-10 h-10 text-emerald-600 mx-auto mb-3 group-hover:bounce transition-all" />
                            <span className="font-black text-emerald-700 block text-sm uppercase tracking-widest">Xuất Báo Cáo</span>
                            <span className="text-[10px] text-gray-400 font-bold mt-1 block">XLSX • {new Date().toLocaleDateString('vi-VN')}</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ phân bổ giờ làm tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px] rounded-3xl shadow-xl">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                            <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} />
                            <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} />
                            <Tooltip cursor={{fill: '#f8fafc', radius: 8}} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                            <Bar dataKey="hours" fill="#4f46e5" radius={[6, 6, 0, 0]} name="Giờ làm" barSize={20} />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)] w-full max-w-lg animate-zoom-in overflow-hidden border border-gray-100">
                    <div className="bg-indigo-600 p-8 flex justify-between items-center text-white relative">
                        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
                            <Clock className="w-32 h-32 transform rotate-12" />
                        </div>
                        <div className="relative z-10">
                            <h3 className="text-2xl font-black uppercase tracking-tight">{myCurrentRequest ? 'Chi tiết đăng ký' : 'Đăng ký OT mới'}</h3>
                            <p className="text-indigo-100 text-sm font-bold flex items-center gap-2 mt-1">
                                <CalendarIcon className="w-4 h-4" /> 
                                {selectedDateStr.split('-').reverse().join(' / ')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all active:scale-90 relative z-10">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-8 space-y-6">
                        {myCurrentRequest && (
                             <div className={`p-4 rounded-2xl border-2 flex items-center gap-4 ${
                                 myCurrentRequest.status === 'approved' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' :
                                 myCurrentRequest.status === 'rejected' ? 'bg-rose-50 border-rose-100 text-rose-800' :
                                 'bg-amber-50 border-amber-100 text-amber-800'
                             }`}>
                                 <div className={`p-3 rounded-xl bg-white shadow-sm`}>
                                     {myCurrentRequest.status === 'approved' ? <CheckCircle2 className="w-6 h-6" /> :
                                      myCurrentRequest.status === 'rejected' ? <X className="w-6 h-6" /> :
                                      <Clock className="w-6 h-6 animate-pulse" />}
                                 </div>
                                 <div>
                                     <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Trạng thái hiện tại</p>
                                     <p className="text-sm font-black uppercase">
                                         {myCurrentRequest.status === 'approved' ? 'Đã được phê duyệt' :
                                          myCurrentRequest.status === 'rejected' ? 'Bị từ chối' :
                                          'Đang chờ phê duyệt'}
                                     </p>
                                 </div>
                             </div>
                        )}

                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-5 rounded-[1.5rem] border-2 transition-all ${isSaturdayWork ? 'bg-blue-50 border-blue-100' : 'bg-orange-50 border-orange-100'}`}>
                                <div className="flex items-center justify-between mb-3">
                                    <h4 className="font-black text-xs text-gray-800 uppercase tracking-widest flex items-center gap-2">
                                        <Settings className="w-4 h-4 text-indigo-500" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-[10px] bg-white border border-gray-200 px-3 py-1.5 rounded-xl shadow-sm hover:shadow-md font-black uppercase tracking-tighter transition-all active:scale-95 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu lại
                                    </button>
                                </div>

                                <div className="flex items-center gap-4">
                                     <label className="relative inline-flex items-center cursor-pointer">
                                        <input 
                                            type="checkbox" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                                     </label>
                                     <span className="text-sm text-gray-700 font-bold select-none">
                                        {isSaturdayWork ? (
                                            <span className="text-blue-700">Đi làm (OT x 1.5)</span>
                                        ) : (
                                            <span className="text-orange-700">Ngày nghỉ (OT x 2.0)</span>
                                        )}
                                     </span>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-5 bg-indigo-50/50 rounded-[1.5rem] border-2 border-indigo-100 shadow-sm transform hover:scale-[1.02] transition-transform">
                            <div>
                                <span className="text-indigo-900 font-black uppercase text-xs tracking-widest block">Tính toán giờ làm</span>
                                <span className="text-[10px] text-indigo-400 font-bold">(Nghỉ giải lao: -{currentDeduction}h)</span>
                            </div>
                            <span className="text-3xl font-black text-indigo-700 tabular-nums">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">Lý do & Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-[10px] flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-black uppercase tracking-tighter transition-all disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl focus:ring-0 outline-none text-sm h-24 resize-none text-gray-900 shadow-inner font-medium"
                                placeholder="Hãy mô tả công việc cần làm thêm..."
                            />
                        </div>

                        <div className="flex gap-4">
                            {myCurrentRequest && myCurrentRequest.status === 'pending' && (
                                <button 
                                    type="button" 
                                    onClick={handleCancelRequest}
                                    disabled={isDeleting}
                                    className="px-6 py-4 bg-white text-rose-600 font-black rounded-2xl border-2 border-rose-100 hover:bg-rose-50 transition-all active:scale-95 flex items-center justify-center gap-2 shadow-sm"
                                >
                                    {isDeleting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Trash2 className="w-5 h-5" />}
                                    HỦY
                                </button>
                            )}
                            <button 
                                type="submit" 
                                disabled={isSubmitting || calculatedHours <= 0}
                                className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-[1.2rem] shadow-xl shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
                            >
                                {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                                {myCurrentRequest ? 'Lưu cập nhật' : 'Gửi đăng ký'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); // Map: date -> is_working_day
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:30');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  // Tìm yêu cầu của bản thân cho ngày đang chọn
  const myCurrentRequest = useMemo(() => {
    return requests.find(r => r.date === selectedDateStr && r.user_id === user.id);
  }, [requests, selectedDateStr, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    // Nếu đã có yêu cầu, điền thông tin cũ vào form
    if (myCurrentRequest) {
        setStartTime(myCurrentRequest.start_time);
        setEndTime(myCurrentRequest.end_time);
        setReason(myCurrentRequest.reason);
    } else {
        const date = new Date(selectedDateStr);
        const day = date.getDay();

        if (day === 6) {
            if (isSaturdayWork) {
                setStartTime('14:30');
                setEndTime('20:00');
            } else {
                setStartTime('08:00');
                setEndTime('20:00');
            }
        } else {
            setStartTime('17:30');
            setEndTime('20:30');
        }
        setReason('');
    }
  }, [selectedDateStr, isSaturdayWork, myCurrentRequest]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr) return 0;
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    let diff = endVal - startVal;
    if (diff <= 0) return 0;

    const date = new Date(dateStr);
    const dayOfWeek = date.getDay(); // 0: CN, 1: T2... 6: T7
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

    // Quy tắc mới: 
    // - Ngày thường (T2-T6): Nếu làm ca tối ngắn (dưới 5h) thì không trừ giờ nghỉ (Vd: 17:30-20:00 = 2.5h)
    // - Cuối tuần hoặc ca làm việc dài (> 5h): Trừ 1h nếu >= 8h, trừ 0.5h nếu > 4h
    let deduction = 0;
    if (isWeekend || diff > 5) {
        deduction = diff >= 8 ? 1.0 : 0.5;
    }

    const final = diff - deduction;
    return parseFloat(Math.max(0, final).toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      if (!selectedDateStr) return 0.5;
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);
      let diff = (eH + eM / 60) - (sH + sM / 60);

      const date = new Date(selectedDateStr);
      const isWeekend = date.getDay() === 0 || date.getDay() === 6;

      if (!isWeekend && diff <= 5) return 0;
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime, selectedDateStr]);

  const calculatedHours = useMemo(() => {
     return calculateHours(startTime, endTime, selectedDateStr);
  }, [startTime, endTime, selectedDateStr]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0)");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    let result;
    if (myCurrentRequest) {
        result = await supabase.from('ot_requests').update(payload).eq('id', myCurrentRequest.id);
    } else {
        result = await supabase.from('ot_requests').insert([payload]);
    }

    if (!result.error) {
        await fetchRequests();
        setIsModalOpen(false);
    } else {
        alert("Lỗi: " + result.error.message);
    }
    setIsSubmitting(false);
  };

  const handleCancelRequest = async () => {
    if (!myCurrentRequest) return;
    if (!confirm("Bạn có chắc chắn muốn hủy yêu cầu tăng ca này không?")) return;

    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', myCurrentRequest.id);
        if (error) throw error;
        await fetchRequests();
        setIsModalOpen(false);
    } catch (error: any) {
        alert("Lỗi khi hủy: " + error.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <div className="flex flex-col">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[9px] font-black mt-1 px-1.5 py-0.5 rounded shadow-sm w-fit ${configWork ? 'bg-blue-100 text-blue-700 border border-blue-200' : 'bg-orange-100 text-orange-700 border border-orange-200'}`}>
                                {configWork ? 'LÀM' : 'NGHỈ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1.5 p-1 bg-white rounded-lg shadow-sm border border-gray-100">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-emerald-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-amber-500 animate-pulse" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-rose-500" />}
                        </div>
                    )}
                </div>

                <div className="h-12 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div 
                                className="w-10 h-10 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[11px] font-black text-white leading-none">TÔI</span>
                            </div>
                            <div className="absolute -top-1.5 -right-1.5 bg-white rounded-full p-0.5 shadow-md border border-gray-100 z-20">
                                <CheckCircle2 className="w-4 h-4 text-emerald-500 fill-white" />
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap gap-1 items-center">
                    {otherRequests.slice(0, 4).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-8 h-8 rounded-lg flex items-center justify-center border border-white shadow-md bg-white overflow-hidden transform hover:scale-125 transition-transform" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-50 flex items-center justify-center">
                                <span className="text-[11px] font-black text-indigo-700 uppercase">
                                    {req.users?.name?.charAt(0) || <UserIcon className="w-4 h-4"/>}
                                </span>
                            </div>
                        </div>
                    ))}
                    {otherRequests.length > 4 && (
                        <div className="w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center text-[11px] font-black text-gray-500 border border-dashed border-gray-300 shadow-sm">
                            +{otherRequests.length - 4}
                        </div>
                    )}
                </div>

                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-orange-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black flex items-center gap-1 shadow-lg transform group-hover:scale-110 transition-transform border border-orange-400">
                        <Users className="w-3 h-3" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded-lg text-[10px] bg-indigo-100 text-indigo-700 border border-indigo-200 font-black uppercase">v2.1</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium">Quản lý làm thêm giờ thông minh</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-8 border-t-indigo-600 shadow-2xl rounded-[2rem]">
                <div className="flex items-center justify-between p-6 border-b border-gray-100 bg-white">
                    <button onClick={prevMonth} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronLeft className="w-6 h-6 text-gray-700" /></button>
                    <div className="text-center">
                        <h3 className="text-xl font-black text-gray-900 uppercase tracking-widest">
                            Tháng {currentDate.getMonth() + 1}
                        </h3>
                        <p className="text-xs text-gray-400 font-bold tracking-widest mt-0.5">{currentDate.getFullYear()}</p>
                    </div>
                    <button onClick={nextMonth} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronRight className="w-6 h-6 text-gray-700" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50/80 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-4 text-center text-[10px] font-black tracking-[0.2em] ${i >= 5 ? 'text-rose-500' : 'text-gray-400'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-600 to-purple-700 text-white border-none shadow-xl shadow-indigo-200">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-black text-lg uppercase tracking-tight">Tổng giờ OT</h3>
                        </div>
                        <p className="text-4xl font-black tracking-tighter">{statsData.reduce((a, b) => a + b.hours, 0)}h</p>
                        <p className="text-xs opacity-70 mt-1 font-bold">Tháng {currentDate.getMonth() + 1} ({currentDate.getFullYear()})</p>
                    </Card>

                    <Card className="bg-white border-l-8 border-emerald-500 shadow-lg">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-7 h-7 text-emerald-600" />
                            <h3 className="font-black uppercase tracking-tight text-sm text-gray-500">Nhân sự tham gia</h3>
                        </div>
                        <p className="text-4xl font-black text-gray-900 tracking-tighter">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-xs text-gray-400 mt-1 font-bold">Tổng số người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-all border-dashed border-2 border-gray-300 shadow-none group active:scale-95" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-10 h-10 text-emerald-600 mx-auto mb-3 group-hover:bounce transition-all" />
                            <span className="font-black text-emerald-700 block text-sm uppercase tracking-widest">Xuất Báo Cáo</span>
                            <span className="text-[10px] text-gray-400 font-bold mt-1 block">XLSX • {new Date().toLocaleDateString('vi-VN')}</span>
                        </div>
                    </Card>
                </div>

                <Card title={`Biểu đồ phân bổ giờ làm tháng ${currentDate.getMonth() + 1}`} className="min-h-[400px] rounded-3xl shadow-xl">
                    <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={statsData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                            <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} />
                            <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} />
                            <Tooltip cursor={{fill: '#f8fafc', radius: 8}} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                            <Bar dataKey="hours" fill="#4f46e5" radius={[6, 6, 0, 0]} name="Giờ làm" barSize={20} />
                        </BarChart>
                    </ResponsiveContainer>
                </Card>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)] w-full max-w-lg animate-zoom-in overflow-hidden border border-gray-100">
                    <div className="bg-indigo-600 p-8 flex justify-between items-center text-white relative">
                        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
                            <Clock className="w-32 h-32 transform rotate-12" />
                        </div>
                        <div className="relative z-10">
                            <h3 className="text-2xl font-black uppercase tracking-tight">{myCurrentRequest ? 'Chi tiết đăng ký' : 'Đăng ký OT mới'}</h3>
                            <p className="text-indigo-100 text-sm font-bold flex items-center gap-2 mt-1">
                                <CalendarIcon className="w-4 h-4" /> 
                                {selectedDateStr.split('-').reverse().join(' / ')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all active:scale-90 relative z-10">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-8 space-y-6">
                        {myCurrentRequest && (
                             <div className={`p-4 rounded-2xl border-2 flex items-center gap-4 ${
                                 myCurrentRequest.status === 'approved' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' :
                                 myCurrentRequest.status === 'rejected' ? 'bg-rose-50 border-rose-100 text-rose-800' :
                                 'bg-amber-50 border-amber-100 text-amber-800'
                             }`}>
                                 <div className={`p-3 rounded-xl bg-white shadow-sm`}>
                                     {myCurrentRequest.status === 'approved' ? <CheckCircle2 className="w-6 h-6" /> :
                                      myCurrentRequest.status === 'rejected' ? <X className="w-6 h-6" /> :
                                      <Clock className="w-6 h-6 animate-pulse" />}
                                 </div>
                                 <div>
                                     <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Trạng thái hiện tại</p>
                                     <p className="text-sm font-black uppercase">
                                         {myCurrentRequest.status === 'approved' ? 'Đã được phê duyệt' :
                                          myCurrentRequest.status === 'rejected' ? 'Bị từ chối' :
                                          'Đang chờ phê duyệt'}
                                     </p>
                                 </div>
                             </div>
                        )}

                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-5 rounded-[1.5rem] border-2 transition-all ${isSaturdayWork ? 'bg-blue-50 border-blue-100' : 'bg-orange-50 border-orange-100'}`}>
                                <div className="flex items-center justify-between mb-3">
                                    <h4 className="font-black text-xs text-gray-800 uppercase tracking-widest flex items-center gap-2">
                                        <Settings className="w-4 h-4 text-indigo-500" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-[10px] bg-white border border-gray-200 px-3 py-1.5 rounded-xl shadow-sm hover:shadow-md font-black uppercase tracking-tighter transition-all active:scale-95 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu lại
                                    </button>
                                </div>

                                <div className="flex items-center gap-4">
                                     <label className="relative inline-flex items-center cursor-pointer">
                                        <input 
                                            type="checkbox" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                                     </label>
                                     <span className="text-sm text-gray-700 font-bold select-none">
                                        {isSaturdayWork ? (
                                            <span className="text-blue-700">Đi làm (OT x 1.5)</span>
                                        ) : (
                                            <span className="text-orange-700">Ngày nghỉ (OT x 2.0)</span>
                                        )}
                                     </span>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-between items-center p-5 bg-indigo-50/50 rounded-[1.5rem] border-2 border-indigo-100 shadow-sm transform hover:scale-[1.02] transition-transform">
                            <div>
                                <span className="text-indigo-900 font-black uppercase text-xs tracking-widest block">Tính toán giờ làm</span>
                                <span className="text-[10px] text-indigo-400 font-bold">
                                    {currentDeduction > 0 ? `(Nghỉ giải lao: -${currentDeduction}h)` : '(Không trừ giờ nghỉ)'}
                                </span>
                            </div>
                            <span className="text-3xl font-black text-indigo-700 tabular-nums">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">Lý do & Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-[10px] flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-black uppercase tracking-tighter transition-all disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl focus:ring-0 outline-none text-sm h-24 resize-none text-gray-900 shadow-inner font-medium"
                                placeholder="Hãy mô tả công việc cần làm thêm..."
                            />
                        </div>

                        <div className="flex gap-4">
                            {myCurrentRequest && myCurrentRequest.status === 'pending' && (
                                <button 
                                    type="button" 
                                    onClick={handleCancelRequest}
                                    disabled={isDeleting}
                                    className="px-6 py-4 bg-white text-rose-600 font-black rounded-2xl border-2 border-rose-100 hover:bg-rose-50 transition-all active:scale-95 flex items-center justify-center gap-2 shadow-sm"
                                >
                                    {isDeleting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Trash2 className="w-5 h-5" />}
                                    HỦY
                                </button>
                            )}
                            <button 
                                type="submit" 
                                disabled={isSubmitting || calculatedHours <= 0}
                                className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-[1.2rem] shadow-xl shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
                            >
                                {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                                {myCurrentRequest ? 'Lưu cập nhật' : 'Gửi đăng ký'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isAttendeesModalOpen, setIsAttendeesModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  const myCurrentRequest = useMemo(() => {
    return requests.find(r => r.date === selectedDateStr && r.user_id === user.id);
  }, [requests, selectedDateStr, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (myCurrentRequest) {
        setStartTime(myCurrentRequest.start_time);
        setEndTime(myCurrentRequest.end_time);
        setReason(myCurrentRequest.reason);
    } else {
        const date = new Date(selectedDateStr);
        const day = date.getDay();

        if (day === 6) {
            if (isSaturdayWork) {
                setStartTime('14:30');
                setEndTime('20:00');
            } else {
                setStartTime('08:00');
                setEndTime('20:00');
            }
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
    }
  }, [selectedDateStr, isSaturdayWork, myCurrentRequest]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr) return 0;
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    // GIỚI HẠN TỐI ĐA 20:00 (8:00 PM)
    const maxEndVal = 20.0;
    const effectiveEndVal = Math.min(endVal, maxEndVal);

    let diff = effectiveEndVal - startVal;
    if (diff <= 0) return 0;

    const date = new Date(dateStr);
    const dayOfWeek = date.getDay(); 
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

    let deduction = 0;
    if (isWeekend || diff > 5) {
        deduction = diff >= 8 ? 1.0 : 0.5;
    }

    const final = diff - deduction;
    return parseFloat(Math.max(0, final).toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      if (!selectedDateStr) return 0.5;
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);

      const maxEndVal = 20.0;
      const effectiveEndVal = Math.min(eH + eM / 60, maxEndVal);
      let diff = effectiveEndVal - (sH + sM / 60);

      const date = new Date(selectedDateStr);
      const isWeekend = date.getDay() === 0 || date.getDay() === 6;

      if (!isWeekend && diff <= 5) return 0;
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime, selectedDateStr]);

  const calculatedHours = useMemo(() => {
     return calculateHours(startTime, endTime, selectedDateStr);
  }, [startTime, endTime, selectedDateStr]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0). Lưu ý hệ thống chỉ tính OT đến 20:00.");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    let result;
    if (myCurrentRequest) {
        result = await supabase.from('ot_requests').update(payload).eq('id', myCurrentRequest.id);
    } else {
        result = await supabase.from('ot_requests').insert([payload]);
    }

    if (!result.error) {
        await fetchRequests();
        setIsModalOpen(false);
    } else {
        alert("Lỗi: " + result.error.message);
    }
    setIsSubmitting(false);
  };

  const handleCancelRequest = async () => {
    if (!myCurrentRequest) return;
    if (!confirm("Bạn có chắc chắn muốn hủy yêu cầu tăng ca này không?")) return;

    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', myCurrentRequest.id);
        if (error) throw error;
        await fetchRequests();
        setIsModalOpen(false);
    } catch (error: any) {
        alert("Lỗi khi hủy: " + error.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const handleViewAttendees = (e: React.MouseEvent, dateStr: string) => {
    e.stopPropagation();
    setSelectedDateStr(dateStr);
    setIsAttendeesModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
