                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-all border-dashed border-2 border-gray-300 shadow-none group active:scale-95" onClick={handleExportExcel}>
                        <div className="text-center">
                            <Download className="w-10 h-10 text-emerald-600 mx-auto mb-3 group-hover:bounce transition-all" />
                            <span className="font-black text-emerald-700 block text-sm uppercase tracking-widest">Xuất Báo Cáo</span>
                            <span className="text-[10px] text-gray-400 font-bold mt-1 block">XLSX • {new Date().toLocaleDateString('vi-VN')}</span>
                        </div>
                    </Card>
