                                    <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl border border-gray-100">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-indigo-100 text-indigo-700 flex items-center justify-center font-black text-xs">
                                                {req.users?.name?.charAt(0) || 'D'}
                                            </div>
                                            <div>
                                                <p className="font-bold text-gray-900 text-sm">{req.users?.name}</p>
                                                <p className="text-[10px] text-gray-400 font-mono">{req.users?.employee_id}</p>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-xs font-black text-indigo-600">{req.total_hours}h</p>
                                            <p className="text-[9px] text-gray-400">{req.start_time}-{req.end_time}</p>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)] w-full max-w-lg animate-zoom-in overflow-hidden border border-gray-100">
                    <div className="bg-indigo-600 p-8 flex justify-between items-center text-white relative">
                        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
                            <Clock className="w-32 h-32 transform rotate-12" />
                        </div>
                        <div className="relative z-10">
                            <h3 className="text-2xl font-black uppercase tracking-tight">{myCurrentRequest ? 'Chi tiết đăng ký' : 'Đăng ký OT mới'}</h3>
                            <p className="text-indigo-100 text-sm font-bold flex items-center gap-2 mt-1">
                                <CalendarIcon className="w-4 h-4" /> 
                                {selectedDateStr.split('-').reverse().join(' / ')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all active:scale-90 relative z-10">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-8 space-y-6">
                        {myCurrentRequest && (
                             <div className={`p-4 rounded-2xl border-2 flex items-center gap-4 ${
                                 myCurrentRequest.status === 'approved' ? 'bg-emerald-50 border-emerald-100 text-emerald-800' :
                                 myCurrentRequest.status === 'rejected' ? 'bg-rose-50 border-rose-100 text-rose-800' :
                                 'bg-amber-50 border-amber-100 text-amber-800'
                             }`}>
                                 <div className={`p-3 rounded-xl bg-white shadow-sm`}>
                                     {myCurrentRequest.status === 'approved' ? <CheckCircle2 className="w-6 h-6" /> :
                                      myCurrentRequest.status === 'rejected' ? <X className="w-6 h-6" /> :
                                      <Clock className="w-6 h-6 animate-pulse" />}
                                 </div>
                                 <div>
                                     <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Trạng thái hiện tại</p>
                                     <p className="text-sm font-black uppercase">
                                         {myCurrentRequest.status === 'approved' ? 'Đã được phê duyệt' :
                                          myCurrentRequest.status === 'rejected' ? 'Bị từ chối' :
                                          'Đang chờ phê duyệt'}
                                     </p>
                                 </div>
                             </div>
                        )}

                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
                        </div>

                        {new Date(selectedDateStr).getDay() === 6 && user.role === 'admin' && (
                            <div className={`p-5 rounded-[1.5rem] border-2 transition-all ${isSaturdayWork ? 'bg-blue-50 border-blue-100' : 'bg-orange-50 border-orange-100'}`}>
                                <div className="flex items-center justify-between mb-3">
                                    <h4 className="font-black text-xs text-gray-800 uppercase tracking-widest flex items-center gap-2">
                                        <Settings className="w-4 h-4 text-indigo-500" /> Cấu hình Thứ 7
                                    </h4>
                                    <button 
                                        type="button" 
                                        onClick={handleSaveDayConfig}
                                        disabled={isSavingConfig}
                                        className="text-[10px] bg-white border border-gray-200 px-3 py-1.5 rounded-xl shadow-sm hover:shadow-md font-black uppercase tracking-tighter transition-all active:scale-95 flex items-center gap-1"
                                    >
                                        {isSavingConfig ? <Loader2 className="w-3 h-3 animate-spin"/> : <Save className="w-3 h-3 text-blue-600"/>}
                                        Lưu lại
                                    </button>
                                </div>

                                <div className="flex items-center gap-4">
                                     <label className="relative inline-flex items-center cursor-pointer">
                                        <input 
                                            type="checkbox" 
                                            checked={isSaturdayWork} 
                                            onChange={(e) => setIsSaturdayWork(e.target.checked)}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                                     </label>
                                     <span className="text-sm text-gray-700 font-bold select-none">
                                        {isSaturdayWork ? (
                                            <span className="text-blue-700">Đi làm (OT x 1.5)</span>
                                        ) : (
                                            <span className="text-orange-700">Ngày nghỉ (OT x 2.0)</span>
                                        )}
                                     </span>
                                </div>
                            </div>
                        )}

                        <div className="flex flex-col gap-2 p-5 bg-indigo-50/50 rounded-[1.5rem] border-2 border-indigo-100 shadow-sm">
                            <div className="flex justify-between items-center">
                                <div>
                                    <span className="text-indigo-900 font-black uppercase text-xs tracking-widest block">Tính toán giờ làm</span>
                                    <span className="text-[10px] text-indigo-400 font-bold">
                                        {currentDeduction > 0 ? `(Nghỉ giải lao: -${currentDeduction}h)` : '(Không trừ giờ nghỉ)'}
                                    </span>
                                </div>
                                <span className="text-3xl font-black text-indigo-700 tabular-nums">{calculatedHours}h</span>
                            </div>
                            <div className="flex items-center gap-2 text-[10px] text-indigo-500 font-bold mt-1 bg-white/50 p-2 rounded-lg">
                                <Info className="w-3 h-3" />
                                Hệ thống chỉ tính công OT tối đa đến 20:00 (8:00 PM).
                            </div>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest">Lý do & Công việc</label>
                                <button type="button" onClick={handleRewrite} disabled={isRewriting || !reason} className="text-[10px] flex items-center gap-1 text-indigo-600 hover:text-indigo-800 font-black uppercase tracking-tighter transition-all disabled:opacity-50">
                                    {isRewriting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />}
                                    AI Viết lại
                                </button>
                            </div>
                            <textarea 
                                required 
                                value={reason} 
                                onChange={(e) => setReason(e.target.value)} 
                                className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl focus:ring-0 outline-none text-sm h-24 resize-none text-gray-900 shadow-inner font-medium"
                                placeholder="Hãy mô tả công việc cần làm thêm..."
                            />
                        </div>

                        <div className="flex gap-4">
                            {myCurrentRequest && myCurrentRequest.status === 'pending' && (
                                <button 
                                    type="button" 
                                    onClick={handleCancelRequest}
                                    disabled={isDeleting}
                                    className="px-6 py-4 bg-white text-rose-600 font-black rounded-2xl border-2 border-rose-100 hover:bg-rose-50 transition-all active:scale-95 flex items-center justify-center gap-2 shadow-sm"
                                >
                                    {isDeleting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Trash2 className="w-5 h-5" />}
                                    HỦY
                                </button>
                            )}
                            <button 
                                type="submit" 
                                disabled={isSubmitting || calculatedHours <= 0}
                                className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-[1.2rem] shadow-xl shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
                            >
                                {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5" />}
                                {myCurrentRequest ? 'Lưu cập nhật' : 'Gửi đăng ký'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isAttendeesModalOpen, setIsAttendeesModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  const myCurrentRequest = useMemo(() => {
    return requests.find(r => r.date === selectedDateStr && r.user_id === user.id);
  }, [requests, selectedDateStr, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (myCurrentRequest) {
        setStartTime(myCurrentRequest.start_time);
        setEndTime(myCurrentRequest.end_time);
        setReason(myCurrentRequest.reason);
    } else {
        const date = new Date(selectedDateStr);
        const day = date.getDay();

        if (day === 6) {
            if (isSaturdayWork) {
                setStartTime('14:30');
                setEndTime('20:00');
            } else {
                setStartTime('08:00');
                setEndTime('20:00');
            }
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
    }
  }, [selectedDateStr, isSaturdayWork, myCurrentRequest]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('ot_requests')
        .select('*, users(employee_id, name)');

    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr) return 0;
    const [sH, sM] = start.split(':').map(Number);
    const [eH, eM] = end.split(':').map(Number);
    let startVal = sH + sM / 60;
    let endVal = eH + eM / 60;

    // GIỚI HẠN TỐI ĐA 20:00 (8:00 PM)
    const maxEndVal = 20.0;
    const effectiveEndVal = Math.min(endVal, maxEndVal);

    let diff = effectiveEndVal - startVal;
    if (diff <= 0) return 0;

    const date = new Date(dateStr);
    const dayOfWeek = date.getDay(); 
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

    let deduction = 0;
    if (isWeekend || diff > 5) {
        deduction = diff >= 8 ? 1.0 : 0.5;
    }

    const final = diff - deduction;
    return parseFloat(Math.max(0, final).toFixed(2));
  };

  const currentDeduction = useMemo(() => {
      if (!selectedDateStr) return 0.5;
      const [sH, sM] = startTime.split(':').map(Number);
      const [eH, eM] = endTime.split(':').map(Number);

      const maxEndVal = 20.0;
      const effectiveEndVal = Math.min(eH + eM / 60, maxEndVal);
      let diff = effectiveEndVal - (sH + sM / 60);

      const date = new Date(selectedDateStr);
      const isWeekend = date.getDay() === 0 || date.getDay() === 6;

      if (!isWeekend && diff <= 5) return 0;
      return diff >= 8 ? 1.0 : 0.5;
  }, [startTime, endTime, selectedDateStr]);

  const calculatedHours = useMemo(() => {
     return calculateHours(startTime, endTime, selectedDateStr);
  }, [startTime, endTime, selectedDateStr]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    const exportData = requests.map(req => ({
        "Mã NV": req.users?.employee_id || 'N/A',
        "Tên NV": req.users?.name || 'N/A',
        "Ngày": req.date,
        "Bắt đầu": req.start_time,
        "Kết thúc": req.end_time,
        "Tổng giờ": req.total_hours,
        "Lý do": req.reason,
        "Trạng thái": req.status
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "OT_Report");
    XLSX.writeFile(wb, `OT_Report_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ (sau khi trừ nghỉ phải > 0). Lưu ý hệ thống chỉ tính OT đến 20:00.");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'pending'
    };

    let result;
    if (myCurrentRequest) {
        result = await supabase.from('ot_requests').update(payload).eq('id', myCurrentRequest.id);
    } else {
        result = await supabase.from('ot_requests').insert([payload]);
    }

    if (!result.error) {
        await fetchRequests();
        setIsModalOpen(false);
    } else {
        alert("Lỗi: " + result.error.message);
    }
    setIsSubmitting(false);
  };

  const handleCancelRequest = async () => {
    if (!myCurrentRequest) return;
    if (!confirm("Bạn có chắc chắn muốn hủy yêu cầu tăng ca này không?")) return;

    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', myCurrentRequest.id);
        if (error) throw error;
        await fetchRequests();
        setIsModalOpen(false);
    } catch (error: any) {
        alert("Lỗi khi hủy: " + error.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const handleViewAttendees = (e: React.MouseEvent, dateStr: string) => {
    e.stopPropagation();
    setSelectedDateStr(dateStr);
    setIsAttendeesModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const attendeesOnSelectedDay = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <div className="flex flex-col">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[9px] font-black mt-1 px-1.5 py-0.5 rounded shadow-sm w-fit ${configWork ? 'bg-blue-100 text-blue-700 border border-blue-200' : 'bg-orange-100 text-orange-700 border border-orange-200'}`}>
                                {configWork ? 'LÀM' : 'NGHỈ'}
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1.5 p-1 bg-white rounded-lg shadow-sm border border-gray-100">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-emerald-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-amber-500 animate-pulse" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-rose-500" />}
                        </div>
                    )}
                </div>

                <div className="h-12 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div 
                                className="w-10 h-10 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[11px] font-black text-white leading-none">TÔI</span>
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap gap-1 items-center">
                    {otherRequests.slice(0, 3).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-8 h-8 rounded-lg flex items-center justify-center border border-white shadow-md bg-white overflow-hidden transform hover:scale-125 transition-transform" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-50 flex items-center justify-center">
                                <span className="text-[11px] font-black text-indigo-700 uppercase">
                                    {req.users?.name?.charAt(0) || 'D'}
                                </span>
                            </div>
                        </div>
                    ))}
                    {otherRequests.length > 3 && (
                        <div className="w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center text-[10px] font-black text-gray-500 border border-dashed border-gray-300 shadow-sm">
                            +{otherRequests.length - 3}
                        </div>
                    )}
                </div>

                {dayRequests.length > 0 && (
                    <div 
                        onClick={(e) => handleViewAttendees(e, dateStr)}
                        className="absolute bottom-1 right-1 bg-orange-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black flex items-center gap-1 shadow-lg transform group-hover:scale-110 transition-transform border border-orange-400 hover:bg-orange-600 active:scale-95"
                    >
                        <Users className="w-3 h-3" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const totalHours = requests
            .filter(r => r.date === dateStr && r.status === 'approved')
            .reduce((sum, r) => sum + (r.total_hours || 0), 0);
         data.push({ day: d, hours: totalHours });
     }
     return data;
  }, [requests, currentDate]);

  const top5Employees = useMemo(() => {
    const monthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string }> = {};

    requests
        .filter(r => r.date.startsWith(monthStr) && r.status === 'approved')
        .forEach(req => {
            const userId = req.user_id;
            if (!employeeMap[userId]) {
                employeeMap[userId] = { 
                    name: req.users?.name || 'Ẩn danh', 
                    hours: 0, 
                    employee_id: req.users?.employee_id || 'N/A' 
                };
            }
            employeeMap[userId].hours += req.total_hours;
        });

    return Object.values(employeeMap)
        .sort((a, b) => b.hours - a.hours)
        .slice(0, 5);
  }, [requests, currentDate]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded-lg text-[10px] bg-indigo-100 text-indigo-700 border border-indigo-200 font-black uppercase">v2.1</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium">Quản lý làm thêm giờ thông minh (OT giới hạn tới 20:00)</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-8 border-t-indigo-600 shadow-2xl rounded-[2rem]">
