                        <p className="text-4xl font-black tracking-tighter">{requests.filter(r => r.status === 'approved' && r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).reduce((a, b) => a + b.total_hours, 0).toFixed(1)}h</p>
                        <p className="text-xs opacity-70 mt-1 font-bold">Tháng {currentDate.getMonth() + 1} ({currentDate.getFullYear()})</p>
