                    </Card>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <Card title={`Top 5 Chiến thần OT - Tháng ${currentDate.getMonth() + 1}`} className="lg:col-span-1 rounded-3xl shadow-xl border-t-8 border-t-orange-500 overflow-hidden">
                        <div className="space-y-4">
                            {top5Employees.length === 0 ? (
                                <div className="text-center py-10">
                                    <Star className="w-10 h-10 text-gray-200 mx-auto mb-3" />
                                    <p className="text-sm text-gray-400 italic">Chưa có dữ liệu tháng này.</p>
                                </div>
                            ) : (
                                top5Employees.map((emp, idx) => (
                                    <div key={idx} className="flex items-center justify-between p-3.5 bg-gray-50 rounded-2xl border border-gray-100 hover:shadow-md transition-all group">
                                        <div className="flex items-center gap-3">
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black relative ${
                                                idx === 0 ? 'bg-yellow-100 text-yellow-700' :
                                                idx === 1 ? 'bg-gray-200 text-gray-600' :
                                                idx === 2 ? 'bg-orange-100 text-orange-700' :
                                                'bg-indigo-50 text-indigo-700'
                                            }`}>
                                                {idx === 0 ? <Trophy className="w-5 h-5" /> : idx + 1}
                                                {idx === 0 && <Star className="absolute -top-1 -right-1 w-3.5 h-3.5 text-yellow-500 fill-yellow-500 animate-pulse" />}
                                            </div>
                                            <div>
                                                <p className="font-black text-sm text-gray-900 leading-tight group-hover:text-orange-600 transition-colors">{emp.name}</p>
                                                <p className="text-[10px] text-gray-400 font-mono tracking-tighter uppercase">{emp.employee_id}</p>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            <span className="text-base font-black text-indigo-600 tabular-nums">{emp.hours.toFixed(1)}</span>
                                            <span className="text-[10px] font-black text-gray-400 uppercase ml-1">h</span>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </Card>

                    <Card title={`Số lượng người đăng ký theo ngày (Tháng ${currentDate.getMonth() + 1})`} className="lg:col-span-2 rounded-3xl shadow-xl border-t-8 border-t-indigo-600">
                        <ResponsiveContainer width="100%" height={320}>
                            <BarChart data={statsData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} />
                                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 'bold'}} allowDecimals={false} />
                                <Tooltip 
                                    cursor={{fill: '#f8fafc', radius: 8}} 
                                    contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold', fontSize: '12px' }}
                                    formatter={(value: any) => [value, "Số người"]}
                                />
                                <Bar dataKey="count" fill="#4f46e5" radius={[6, 6, 0, 0]} name="Số người" barSize={16} />
                            </BarChart>
                        </ResponsiveContainer>
                    </Card>
                </div>
            </div>
        )}

        {/* MODAL XUẤT EXCEL */}
        {isExportModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-zoom-in overflow-hidden border border-gray-100">
                    <div className="bg-emerald-600 p-8 flex justify-between items-center text-white relative">
                        <div>
                            <h3 className="text-2xl font-black uppercase tracking-tight">Xuất Báo Cáo Excel</h3>
                            <p className="text-emerald-100 text-sm font-bold flex items-center gap-2 mt-1">
                                <FileSpreadsheet className="w-4 h-4" /> 
                                Lựa chọn khoảng thời gian
                            </p>
                        </div>
                        <button onClick={() => setIsExportModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all active:scale-90">
                            <X className="w-6 h-6" />
                        </button>
                    </div>

                    <div className="p-8 space-y-6">
                        <div className="grid grid-cols-1 gap-4">
                            <button 
                                onClick={() => handleExportExcel('today')}
                                className="w-full py-4 bg-emerald-50 text-emerald-700 border-2 border-emerald-100 rounded-2xl font-black flex items-center justify-center gap-3 hover:bg-emerald-100 transition-all active:scale-95"
                            >
                                <CalendarIcon className="w-5 h-5" />
                                XUẤT DỮ LIỆU HÔM NAY
                            </button>

                            <div className="relative flex items-center py-4">
                                <div className="flex-grow border-t border-gray-200"></div>
                                <span className="flex-shrink mx-4 text-gray-400 text-xs font-black uppercase tracking-widest">Hoặc chọn khoảng ngày</span>
                                <div className="flex-grow border-t border-gray-200"></div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Từ ngày</label>
                                    <input 
                                        type="date" 
                                        value={exportStartDate}
                                        onChange={(e) => setExportStartDate(e.target.value)}
                                        className="w-full p-3 bg-gray-50 border-2 border-transparent focus:border-emerald-500 rounded-xl text-sm font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner"
                                    />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Đến ngày</label>
                                    <input 
                                        type="date" 
                                        value={exportEndDate}
                                        onChange={(e) => setExportEndDate(e.target.value)}
                                        className="w-full p-3 bg-gray-50 border-2 border-transparent focus:border-emerald-500 rounded-xl text-sm font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner"
                                    />
                                </div>
                            </div>
                        </div>

                        <button 
                            onClick={() => handleExportExcel('range')}
                            className="w-full py-5 bg-gray-900 hover:bg-black text-white font-black rounded-2xl shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
                        >
                            <Download className="w-5 h-5" />
                            XUẤT THEO KHOẢNG NGÀY
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* MODAL DANH SÁCH NGƯỜI ĐĂNG KÝ */}
        {isAttendeesModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-[60] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-sm animate-zoom-in overflow-hidden border border-gray-100">
                    <div className="bg-orange-500 p-6 flex justify-between items-center text-white">
                        <div className="flex items-center gap-3">
                            <Users className="w-6 h-6" />
                            <div>
                                <h3 className="text-lg font-black uppercase tracking-tight">Người đăng ký OT</h3>
                                <p className="text-xs opacity-90 font-bold">{selectedDateStr.split('-').reverse().join('/')}</p>
                            </div>
                        </div>
                        <button onClick={() => setIsAttendeesModalOpen(false)} className="hover:bg-black/10 p-2 rounded-xl transition-all">
                            <X className="w-5 h-5" />
                        </button>
                    </div>
                    <div className="p-6 max-h-[60vh] overflow-y-auto">
                        <div className="space-y-3">
                            {attendeesOnSelectedDay.length === 0 ? (
                                <p className="text-center text-gray-400 italic py-4">Chưa có ai đăng ký.</p>
                            ) : (
                                attendeesOnSelectedDay.map((req, idx) => (
                                    <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl border border-gray-100">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-indigo-100 text-indigo-700 flex items-center justify-center font-black text-xs">
                                                {req.users?.name?.charAt(0) || 'D'}
                                            </div>
                                            <div>
                                                <p className="font-bold text-gray-900 text-sm">{req.users?.name}</p>
                                                <p className="text-[10px] text-gray-400 font-mono">{req.users?.employee_id}</p>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-xs font-black text-indigo-600">{req.total_hours}h</p>
                                            <p className="text-[9px] text-gray-400">{req.start_time}-{req.end_time}</p>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
