  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  // States cho xuất Excel
  const [exportStartDate, setExportStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  // Xác định đơn đăng ký của chính người dùng trong ngày đang chọn
  const myCurrentRequest = useMemo(() => {
    if (!selectedDateStr || !user.id) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === user.id) || null;
  }, [requests, selectedDateStr, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (myCurrentRequest) {
        setStartTime(myCurrentRequest.start_time);
        setEndTime(myCurrentRequest.end_time);
        setReason(myCurrentRequest.reason || '');
    } else {
        const date = new Date(selectedDateStr);
        const day = date.getDay();

        if (day === 6) {
            if (isSaturdayWork) {
                setStartTime('14:30');
                setEndTime('20:00');
            } else {
                setStartTime('08:00');
                setEndTime('20:00');
            }
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
    }
  }, [selectedDateStr, isSaturdayWork, myCurrentRequest]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');

      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error("Fetch requests error:", err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const handleSaveDayConfig = async () => {
    if (!selectedDateStr || user.role !== 'admin') return;

    setIsSavingConfig(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({
            date: selectedDateStr,
            is_working_day: isSaturdayWork
        }, { onConflict: 'date' });

        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: isSaturdayWork }));
        alert("Đã lưu cấu hình ngày thành công!");
    } catch (error: any) {
        alert("Lỗi lưu cấu hình: " + error.message);
    } finally {
        setIsSavingConfig(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;

    const startVal = timeToNumber(start);
    const rawEndVal = timeToNumber(end);
    const maxEndVal = 20.0;
    const endVal = Math.min(rawEndVal, maxEndVal);

    const diff = endVal - startVal;
    if (diff <= 0) return 0;

    const date = new Date(dateStr);
    const dayOfWeek = date.getDay(); 
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

    let deduction = 0;
    if (diff >= 8) {
      deduction = 1.0;
    } else if (diff > 4) {
      if (isWeekend || diff > 5) {
        deduction = 0.5;
      }
    }

    const finalResult = diff - deduction;
    return parseFloat(Math.max(0, finalResult).toFixed(2));
  };

  const isOverlapping = useMemo(() => {
    if (!selectedDateStr) return false;
    const startVal = timeToNumber(startTime);
    const endVal = timeToNumber(endTime);

    return requests.some(req => {
      if (req.user_id !== user.id || req.date !== selectedDateStr || req.id === myCurrentRequest?.id) return false;
      const rStart = timeToNumber(req.start_time);
      const rEnd = timeToNumber(req.end_time);
      return Math.max(startVal, rStart) < Math.min(endVal, rEnd);
    });
  }, [startTime, endTime, selectedDateStr, requests, user.id, myCurrentRequest]);

  const currentDeduction = useMemo(() => {
    if (!selectedDateStr) return 0;
    const startVal = timeToNumber(startTime);
    const endVal = Math.min(timeToNumber(endTime), 20.0);
    const diff = endVal - startVal;
    if (diff <= 0) return 0;
    const date = new Date(selectedDateStr);
    const isWeekend = date.getDay() === 0 || date.getDay() === 6;
    if (diff >= 8) return 1.0;
    if (diff > 4 && (isWeekend || diff > 5)) return 0.5;
    return 0;
  }, [startTime, endTime, selectedDateStr]);

  const calculatedHours = useMemo(() => {
     return calculateHours(startTime, endTime, selectedDateStr);
  }, [startTime, endTime, selectedDateStr]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = (mode: 'today' | 'range') => {
    let dataToExport = requests;
    let fileName = `OT_Report_${new Date().toISOString().split('T')[0]}`;

    if (mode === 'today') {
        const todayStr = new Date().toISOString().split('T')[0];
        dataToExport = requests.filter(r => r.date === todayStr);
        fileName = `OT_Report_Today_${todayStr}`;
    } else {
        dataToExport = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
        fileName = `OT_Report_${exportStartDate}_to_${exportEndDate}`;
    }

    if (dataToExport.length === 0) {
        alert("Không có dữ liệu trong khoảng thời gian đã chọn.");
        return;
    }

    const groupedData: Record<string, any[]> = {};
    dataToExport.forEach(req => {
        const dateKey = req.date;
        if (!groupedData[dateKey]) groupedData[dateKey] = [];
        groupedData[dateKey].push({
            "Mã NV": req.users?.employee_id || 'N/A',
            "Tên NV": req.users?.name || 'N/A',
            "Bắt đầu": req.start_time,
            "Kết thúc": req.end_time,
            "Tổng giờ": req.total_hours,
            "Lý do": req.reason,
            "Trạng thái": req.status
        });
    });

    const wb = XLSX.utils.book_new();
    const sortedDates = Object.keys(groupedData).sort();

    sortedDates.forEach(date => {
        const ws = XLSX.utils.json_to_sheet(groupedData[date]);
        const sheetName = date.split('-').reverse().join('-');
        XLSX.utils.book_append_sheet(wb, ws, sheetName);
    });

    XLSX.writeFile(wb, `${fileName}.xlsx`);
    setIsExportModalOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ hoặc vượt quá giới hạn 20:00.");
    if (isOverlapping) return alert("Thời gian này trùng lặp với một đăng ký khác của bạn trong ngày.");

    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'approved' // Tự động phê duyệt ngay khi gửi
    };

    try {
      let response;
      if (myCurrentRequest) {
          response = await supabase.from('ot_requests').update(payload).eq('id', myCurrentRequest.id);
      } else {
          response = await supabase.from('ot_requests').insert([payload]);
      }

      if (response.error) throw response.error;

      await fetchRequests();
      setIsModalOpen(false);
    } catch (error: any) {
        alert("Lỗi khi lưu đăng ký: " + error.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    // 1. Capture record to be deleted immediately
    const recordToDelete = myCurrentRequest;
    if (!recordToDelete || !recordToDelete.id) {
        alert("Lỗi: Không tìm thấy ID đăng ký để thực hiện hủy.");
        return;
    }

    setIsDeleting(true);
    try {
        console.log("Attempting to delete OT Request ID:", recordToDelete.id);

        // 2. Perform the deletion in Supabase
        const { error, status } = await supabase
            .from('ot_requests')
            .delete()
            .eq('id', recordToDelete.id);

        if (error) {
            console.error("Supabase deletion error:", error);
            throw new Error(error.message);
        }

        console.log("Delete status:", status);

        // 3. Update local state immediately for instant feedback
        const targetId = recordToDelete.id;
        setRequests(prev => prev.filter(r => r.id !== targetId));

        // 4. Close modals and notify success
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
        alert("Đã hủy đăng ký thành công!");

        // 5. Hard sync with server in the background
        fetchRequests();
    } catch (error: any) {
        console.error("Critical handleCancelRequest error:", error);
        alert("Lỗi khi hủy: " + (error.message || "Lỗi không xác định khi kết nối với máy chủ."));
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    const isSat = dateObj.getDay() === 6;

    if (isSat) {
        const isWork = configIsWork !== undefined ? configIsWork : true;
        setIsSaturdayWork(isWork);
    } else {
        setIsSaturdayWork(false);
    }

    setIsModalOpen(true);
  };

  const handleViewAttendees = (e: React.MouseEvent, dateStr: string) => {
    e.stopPropagation();
    setSelectedDateStr(dateStr);
    setIsAttendeesModalOpen(true);
  };

  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
  const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

  const attendeesOnSelectedDay = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  const statsData = useMemo(() => {
     const data: any[] = [];
     for(let d = 1; d <= daysInMonth; d++) {
         const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
         const uniquePeopleCount = new Set(requests
            .filter(r => r.date === dateStr && r.status !== 'rejected')
            .map(r => r.user_id)).size;

         data.push({ day: d, count: uniquePeopleCount });
     }
     return data;
  }, [requests, currentDate]);

  const myTotalHoursInMonth = useMemo(() => {
    const monthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
    return requests
        .filter(r => r.user_id === user.id && r.status === 'approved' && r.date.startsWith(monthStr))
        .reduce((sum, r) => sum + (r.total_hours || 0), 0);
  }, [requests, currentDate, user.id]);

  const top5Employees = useMemo(() => {
    const monthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string }> = {};

    requests
        .filter(r => r.date.startsWith(monthStr) && r.status === 'approved')
        .forEach(req => {
            const userId = req.user_id;
            if (!employeeMap[userId]) {
                employeeMap[userId] = { 
                    name: req.users?.name || 'Ẩn danh', 
                    hours: 0, 
                    employee_id: req.users?.employee_id || 'N/A' 
                };
            }
            employeeMap[userId].hours += req.total_hours;
        });

    return Object.values(employeeMap)
        .sort((a, b) => b.hours - a.hours)
        .slice(0, 5);
  }, [requests, currentDate]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);

        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);

        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSun = dateObj.getDay() === 0;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-1.5">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>

                        {isSat && configWork !== undefined && (
                            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm whitespace-nowrap uppercase tracking-tighter border ${configWork ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-orange-50 text-orange-600 border-orange-200'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                        {isSun && (
                            <span className="text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm bg-rose-50 text-rose-600 border border-rose-200 uppercase tracking-tighter whitespace-nowrap">
                                Nghỉ
                            </span>
                        )}
                    </div>

                    {myRequest && (
                        <div className="flex items-center gap-1.5 p-1 bg-white rounded-lg shadow-sm border border-gray-100">
                            {myRequest.status === 'approved' && <CheckCircle2 className="w-4 h-4 text-emerald-500" />}
                            {myRequest.status === 'pending' && <Timer className="w-4 h-4 text-amber-500 animate-pulse" />}
                            {myRequest.status === 'rejected' && <AlertCircle className="w-4 h-4 text-rose-500" />}
                        </div>
                    )}
                </div>

                <div className="h-12 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div 
                                className="w-10 h-10 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[11px] font-black text-white leading-none">TÔI</span>
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap gap-1 items-center">
                    {otherRequests.slice(0, 3).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-8 h-8 rounded-lg flex items-center justify-center border border-white shadow-md bg-white overflow-hidden transform hover:scale-125 transition-transform" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <div className="w-full h-full bg-indigo-50 flex items-center justify-center">
                                <span className="text-[11px] font-black text-indigo-700 uppercase">
                                    {req.users?.name?.charAt(0) || 'D'}
                                </span>
                            </div>
                        </div>
                    ))}
                    {otherRequests.length > 3 && (
                        <div className="w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center text-[10px] font-black text-gray-500 border border-dashed border-gray-300 shadow-sm">
                            +{otherRequests.length - 3}
                        </div>
                    )}
                </div>

                {dayRequests.length > 0 && (
                    <div 
                        onClick={(e) => handleViewAttendees(e, dateStr)}
                        className="absolute bottom-1 right-1 bg-orange-500 text-white text-[10px] px-2 py-0.5 rounded-lg font-black flex items-center gap-1 shadow-lg transform group-hover:scale-110 transition-transform border border-orange-400 hover:bg-orange-600 active:scale-95"
                    >
                        <Users className="w-3 h-3" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded-lg text-[10px] bg-indigo-100 text-indigo-700 border border-indigo-200 font-black uppercase">v2.1</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium">Quản lý làm thêm giờ thông minh (OT giới hạn tới 20:00)</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('stats')}
                        className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Báo cáo
                    </button>
                )}
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="flex-1 flex flex-col p-0 overflow-hidden border-t-8 border-t-indigo-600 shadow-2xl rounded-[2rem]">
                <div className="flex items-center justify-between p-6 border-b border-gray-100 bg-white">
                    <button onClick={prevMonth} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronLeft className="w-6 h-6 text-gray-700" /></button>
                    <div className="text-center">
                        <h3 className="text-xl font-black text-gray-900 uppercase tracking-widest">
                            Tháng {currentDate.getMonth() + 1}
                        </h3>
                        <p className="text-xs text-gray-400 font-bold tracking-widest mt-0.5">{currentDate.getFullYear()}</p>
                    </div>
                    <button onClick={nextMonth} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronRight className="w-6 h-6 text-gray-700" /></button>
                </div>

                <div className="grid grid-cols-7 bg-gray-50/80 border-b border-gray-200">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                        <div key={d} className={`py-4 text-center text-[10px] font-black tracking-[0.2em] ${i >= 5 ? 'text-rose-500' : 'text-gray-400'}`}>{d}</div>
                    ))}
                </div>

                <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px] border-l border-gray-200">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && user.role === 'admin' && (
            <div className="space-y-6 animate-fade-in-up">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <Card className="bg-gradient-to-br from-indigo-600 to-purple-700 text-white border-none shadow-xl shadow-indigo-200">
                        <div className="flex items-center gap-3 mb-2">
                            <Clock className="w-8 h-8 opacity-80" />
                            <h3 className="font-black text-lg uppercase tracking-tight">Giờ OT của Tôi</h3>
                        </div>
                        <p className="text-4xl font-black tracking-tighter">{myTotalHoursInMonth.toFixed(1)}h</p>
                        <p className="text-xs opacity-70 mt-1 font-bold">Tháng {currentDate.getMonth() + 1} ({currentDate.getFullYear()})</p>
                    </Card>

                    <Card className="bg-white border-l-8 border-emerald-500 shadow-lg">
                        <div className="flex items-center gap-3 mb-2 text-gray-800">
                            <Users className="w-7 h-7 text-emerald-600" />
                            <h3 className="font-black uppercase tracking-tight text-sm text-gray-500">Nhân sự tham gia</h3>
                        </div>
                        <p className="text-4xl font-black text-gray-900 tracking-tighter">{new Set(requests.filter(r => r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`)).map(r => r.user_id)).size}</p>
                        <p className="text-xs text-gray-400 mt-1 font-bold">Tổng số người trong tháng</p>
                    </Card>

                     <Card className="flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-all border-dashed border-2 border-gray-300 shadow-none group active:scale-95" onClick={() => setIsExportModalOpen(true)}>
                        <div className="text-center">
                            <FileSpreadsheet className="w-10 h-10 text-emerald-600 mx-auto mb-3 group-hover:bounce transition-all" />
                            <span className="font-black text-emerald-700 block text-sm uppercase tracking-widest">Xuất Báo Cáo</span>
                            <span className="text-[10px] text-gray-400 font-bold mt-1 block">XLSX • Tuỳ chọn thời gian</span>
                        </div>
                    </Card>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <Card title={`Top 5 Chiến thần OT - Tháng ${currentDate.getMonth() + 1}`} className="lg:col-span-1 rounded-3xl shadow-xl border-t-8 border-t-orange-500 overflow-hidden">
                        <div className="space-y-4">
                            {top5Employees.length === 0 ? (
                                <div className="text-center py-10">
                                    <Star className="w-10 h-10 text-gray-200 mx-auto mb-3" />
                                    <p className="text-sm text-gray-400 italic">Chưa có dữ liệu tháng này.</p>
                                </div>
                            ) : (
                                top5Employees.map((emp, idx) => (
                                    <div key={idx} className="flex items-center justify-between p-3.5 bg-gray-50 rounded-2xl border border-gray-100 hover:shadow-md transition-all group">
                                        <div className="flex items-center gap-3">
