import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import * as XLSX from 'xlsx';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const PIE_COLORS = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444'];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'admin'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isAttendeesModalOpen, setIsAttendeesModalOpen] = useState(false);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  const [exportStartDate, setExportStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const myCurrentRequest = useMemo(() => {
    if (!selectedDateStr || !user.id) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === user.id) || null;
  }, [requests, selectedDateStr, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (myCurrentRequest) {
        setStartTime(myCurrentRequest.start_time);
        setEndTime(myCurrentRequest.end_time);
        setReason(myCurrentRequest.reason || '');
    } else {
        const date = new Date(selectedDateStr);
        const day = date.getDay();

        if (day === 6) {
            if (isSaturdayWork) {
                setStartTime('14:30');
                setEndTime('20:00');
            } else {
                setStartTime('08:00');
                setEndTime('20:00');
            }
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
    }
  }, [selectedDateStr, isSaturdayWork, myCurrentRequest]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');

      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error("Fetch requests error:", err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;

    const { data } = await supabase
        .from('day_configs')
        .select('*')
        .gte('date', startOfMonth)
        .lte('date', endOfMonth);

    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => {
            configMap[cfg.date] = cfg.is_working_day;
        });
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const startVal = timeToNumber(start);
    const endVal = Math.min(timeToNumber(end), 20.0);
    const diff = endVal - startVal;
    if (diff <= 0) return 0;
    const date = new Date(dateStr);
    const isWeekend = date.getDay() === 0 || date.getDay() === 6;
    let deduction = 0;
    if (diff >= 8) deduction = 1.0;
    else if (diff > 4 && (isWeekend || diff > 5)) deduction = 0.5;
    return parseFloat(Math.max(0, diff - deduction).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr]);

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: user.id,
        date: selectedDateStr,
        start_time: startTime,
        end_time: endTime,
        total_hours: calculatedHours,
        reason,
        status: 'approved' 
    };
    try {
      const response = myCurrentRequest 
        ? await supabase.from('ot_requests').update(payload).eq('id', myCurrentRequest.id)
        : await supabase.from('ot_requests').insert([payload]);
      if (response.error) throw response.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (error: any) {
        alert("Lỗi khi lưu: " + error.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    const recordToDelete = myCurrentRequest;
    if (!recordToDelete) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', recordToDelete.id);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== recordToDelete.id));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
        alert("Đã hủy thành công!");
    } catch (error: any) {
        alert("Lỗi: " + error.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const configIsWork = dayConfigs[dateStr];
    setIsSaturdayWork(dateObj.getDay() === 6 ? (configIsWork !== undefined ? configIsWork : true) : false);
    setIsModalOpen(true);
  };

  // --- STATS LOGIC ---
  const currentMonthStr = useMemo(() => `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`, [currentDate]);

  const myMonthlyStats = useMemo(() => {
    const myReqs = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const totalHours = myReqs.filter(r => r.status === 'approved').reduce((sum, r) => sum + r.total_hours, 0);
    const count = myReqs.length;
    const pending = myReqs.filter(r => r.status === 'pending').length;

    // Monthly trend for user
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const day = i + 1;
        const dStr = `${currentMonthStr}-${String(day).padStart(2, '0')}`;
        const dayReq = myReqs.find(r => r.date === dStr);
        return { day, hours: dayReq ? dayReq.total_hours : 0 };
    });

    const statusData = [
        { name: 'Đã duyệt', value: myReqs.filter(r => r.status === 'approved').length },
        { name: 'Chờ duyệt', value: pending },
        { name: 'Từ chối', value: myReqs.filter(r => r.status === 'rejected').length }
    ].filter(v => v.value > 0);

    return { totalHours, count, pending, trend, statusData };
  }, [requests, user.id, currentMonthStr]);

  const top5Employees = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved').forEach(req => {
        const userId = req.user_id;
        if (!employeeMap[userId]) {
            employeeMap[userId] = { 
                name: req.users?.name || 'Ẩn danh', 
                hours: 0, 
                employee_id: req.users?.employee_id || 'N/A',
                count: 0
            };
        }
        employeeMap[userId].hours += req.total_hours;
        employeeMap[userId].count += 1;
    });

    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const adminDailyStats = useMemo(() => {
    return Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const day = i + 1;
        const dStr = `${currentMonthStr}-${String(day).padStart(2, '0')}`;
        const count = new Set(requests.filter(r => r.date === dStr && r.status !== 'rejected').map(r => r.user_id)).size;
        return { day, count };
    });
  }, [requests, currentMonthStr]);

  return (
    <div className="space-y-6 h-full flex flex-col">
        {/* TOP NAVIGATION BAR */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight flex items-center gap-2">
                    OT Manager Pro
                    <span className="px-2 py-0.5 rounded-lg text-[10px] bg-indigo-100 text-indigo-700 border border-indigo-200 font-black uppercase">v2.5</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium italic">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button 
                    onClick={() => setActiveTab('calendar')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                <button 
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <UserIcon className="w-4 h-4" /> Cá nhân
                </button>
                {user.role === 'admin' && (
                    <button 
                        onClick={() => setActiveTab('admin')}
                        className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'admin' ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        <BarChart3 className="w-4 h-4" /> Quản trị
                    </button>
                )}
            </div>
        </div>

        {/* --- MAIN CONTENT AREAS --- */}
        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-t-8 border-t-indigo-600 shadow-2xl rounded-[2rem]">
                    <div className="flex items-center justify-between p-6 border-b border-gray-100 bg-white">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronLeft className="w-6 h-6 text-gray-700" /></button>
                        <div className="text-center">
                            <h3 className="text-xl font-black text-gray-900 uppercase tracking-widest">Tháng {currentDate.getMonth() + 1}</h3>
                        </div>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronRight className="w-6 h-6 text-gray-700" /></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                            <div key={d} className={`py-4 text-center text-[10px] font-black tracking-[0.2em] ${i >= 5 ? 'text-rose-500' : 'text-gray-400'}`}>{d}</div>
