                        {Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}).map((_, i) => {
                            const d = i + 1;
                            const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
                            const dayReqs = requests.filter(r => r.date === dStr);
                            const isToday = new Date().toISOString().split('T')[0] === dStr;
                            const myReq = dayReqs.find(r => r.user_id === user.id);

                            return (
                                <div key={d} onClick={() => handleDateClick(dStr, new Date(currentDate.getFullYear(), currentDate.getMonth(), d))} className={`h-32 border-gray-100 p-2 relative transition-all hover:bg-indigo-50 cursor-pointer group flex flex-col ${isToday ? 'bg-indigo-50/50 ring-inset ring-2 ring-indigo-500/20' : 'bg-white'}`}>
                                    <span className={`text-base font-black ${isToday ? 'bg-indigo-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-lg' : 'text-gray-700'}`}>{d}</span>
                                    <div className="flex-1 flex flex-col justify-center">
                                        {myReq && <div className="bg-indigo-600 text-white text-[10px] p-1 rounded-lg font-black text-center shadow-lg transform scale-110 mb-1">TÔI ({myReq.total_hours}h)</div>}
                                        <div className="flex flex-wrap gap-1">
                                            {dayReqs.filter(r => r.user_id !== user.id).slice(0, 3).map((r, idx) => (
                                                <div key={idx} className="w-5 h-5 bg-gray-100 rounded-lg flex items-center justify-center text-[9px] font-bold text-gray-500 border border-gray-200">{r.users?.name?.charAt(0)}</div>
                                            ))}
                                        </div>
                                    </div>
                                    {dayReqs.length > 0 && <div className="absolute bottom-1 right-1 text-[9px] font-black text-indigo-400 bg-white px-1.5 rounded-full shadow-sm">{dayReqs.length} OT</div>}
                                </div>
                            );
                        })}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-6 animate-fade-in-up">
