                            <h3 className="text-xs font-black uppercase tracking-widest opacity-80 mb-1">Tổng giờ OT</h3>
                            <div className="flex items-end gap-2">
                                <span className="text-4xl font-black">{myMonthlyStats.totalHours.toFixed(1)}</span>
                                <span className="text-lg font-bold mb-1">h</span>
                            </div>
                            <div className="mt-4 bg-white/20 p-2 rounded-xl flex items-center gap-2">
                                <Target className="w-4 h-4" />
                                <span className="text-[10px] font-bold">Mục tiêu: 40h/tháng</span>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-indigo-500">
                            <div className="p-3 bg-indigo-50 rounded-2xl text-indigo-600"><Activity className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Số lần đăng ký</p>
                                <p className="text-2xl font-black text-gray-900">{myMonthlyStats.count}</p>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-amber-500">
                            <div className="p-3 bg-amber-50 rounded-2xl text-amber-600"><Timer className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Đang chờ duyệt</p>
                                <p className="text-2xl font-black text-gray-900">{myMonthlyStats.pending}</p>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-blue-500">
                            <div className="p-3 bg-blue-50 rounded-2xl text-blue-600"><TrendingUp className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Tỉ lệ duyệt</p>
                                <p className="text-2xl font-black text-gray-900">{myMonthlyStats.count ? ((myMonthlyStats.count - myMonthlyStats.pending) / myMonthlyStats.count * 100).toFixed(0) : 0}%</p>
                            </div>
                        </Card>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        <Card title="Phân bổ trạng thái" className="lg:col-span-1 rounded-3xl shadow-lg border-t-8 border-indigo-500">
                            {myMonthlyStats.statusData.length > 0 ? (
                                <div className="h-64 relative">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <PieChart>
                                            <Pie data={myMonthlyStats.statusData} innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                                                {myMonthlyStats.statusData.map((_, index) => <Cell key={index} fill={PIE_COLORS[index % PIE_COLORS.length]} />)}
                                            </Pie>
                                            <Tooltip />
                                        </PieChart>
                                    </ResponsiveContainer>
                                    <div className="absolute inset-0 flex items-center justify-center flex-col pointer-events-none">
                                        <PieChartIcon className="w-5 h-5 text-indigo-500 mb-1" />
                                        <span className="text-xs font-black text-gray-400">STATUS</span>
                                    </div>
                                </div>
                            ) : <div className="h-64 flex items-center justify-center text-gray-400 italic text-sm">Chưa có dữ liệu</div>}
                        </Card>
                        <Card title="Biểu đồ làm việc trong tháng" className="lg:col-span-2 rounded-3xl shadow-lg border-t-8 border-emerald-500">
                            <div className="h-64">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={myMonthlyStats.trend} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <Tooltip cursor={{fill: '#f8fafc'}} />
                                        <Bar dataKey="hours" fill="#10b981" radius={[4, 4, 0, 0]} barSize={12} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </div>
                </div>
            )}

            {activeTab === 'admin' && user.role === 'admin' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* UPGRADED TOP 5 SECTION */}
                        <Card title="BẢNG VÀNG CHIẾN THẦN OT" className="lg:col-span-1 rounded-[2rem] shadow-2xl border-none bg-white relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-4 opacity-5"><Trophy className="w-32 h-32 rotate-12" /></div>
                            <div className="space-y-4 relative z-10">
                                {top5Employees.length === 0 ? (
                                    <div className="text-center py-20 text-gray-400 italic">Chưa có dữ liệu tháng này</div>
                                ) : (
                                    top5Employees.map((emp, idx) => {
                                        const isTop1 = idx === 0;
                                        const maxHours = top5Employees[0].hours;
                                        const progress = (emp.hours / maxHours) * 100;

                                        return (
                                            <div key={idx} className={`p-4 rounded-[1.5rem] border-2 transition-all group hover:scale-[1.02] ${
                                                idx === 0 ? 'bg-amber-50 border-amber-200' :
                                                idx === 1 ? 'bg-slate-50 border-slate-200' :
                                                idx === 2 ? 'bg-orange-50 border-orange-200' :
                                                'bg-gray-50 border-transparent'
                                            }`}>
                                                <div className="flex items-center gap-4">
                                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg relative shadow-inner ${
                                                        idx === 0 ? 'bg-gradient-to-br from-yellow-400 to-amber-600 text-white' :
                                                        idx === 1 ? 'bg-gradient-to-br from-slate-300 to-slate-500 text-white' :
                                                        idx === 2 ? 'bg-gradient-to-br from-orange-300 to-orange-500 text-white' :
                                                        'bg-white text-gray-400'
                                                    }`}>
                                                        {idx < 3 ? <Trophy className="w-6 h-6" /> : idx + 1}
                                                        {isTop1 && <Star className="absolute -top-2 -right-2 w-6 h-6 text-yellow-500 fill-yellow-500 animate-bounce" />}
                                                    </div>
                                                    <div className="flex-1">
                                                        <div className="flex justify-between items-start">
                                                            <div>
                                                                <h4 className="font-black text-gray-900 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{emp.name}</h4>
                                                                <p className="text-[10px] font-black text-gray-400 tracking-tighter uppercase">{emp.employee_id} • {emp.count} lượt</p>
                                                            </div>
                                                            <div className="text-right">
                                                                <span className="text-xl font-black text-indigo-600 tabular-nums">{emp.hours.toFixed(1)}</span>
                                                                <span className="text-[10px] font-black text-gray-400 ml-0.5 uppercase">h</span>
                                                            </div>
                                                        </div>
                                                        {/* Progress bar */}
                                                        <div className="mt-2 h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
                                                            <div 
                                                                className={`h-full rounded-full transition-all duration-1000 ${
                                                                    idx === 0 ? 'bg-amber-500' : 'bg-indigo-500'
                                                                }`} 
                                                                style={{ width: `${progress}%` }}
                                                            ></div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </Card>

                        <Card title="Tương tác hệ thống (Tháng này)" className="lg:col-span-2 rounded-[2rem] shadow-2xl border-none">
                            <div className="h-[400px]">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={adminDailyStats}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <Tooltip cursor={{fill: '#f8fafc', radius: 10}} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                                        <Bar dataKey="count" fill="#4f46e5" radius={[6, 6, 0, 0]} name="Số người" barSize={16} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </div>
                </div>
            )}
        </div>

        {/* --- MODALS (REUSED) --- */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-zoom-in overflow-hidden border border-gray-100">
                    <div className="bg-indigo-600 p-8 flex justify-between items-center text-white relative">
                        <div className="relative z-10">
                            <h3 className="text-2xl font-black uppercase tracking-tight">{myCurrentRequest ? 'Chi tiết đăng ký' : 'Đăng ký OT mới'}</h3>
                            <p className="text-indigo-100 text-sm font-bold flex items-center gap-2 mt-1">
                                <CalendarIcon className="w-4 h-4" /> {selectedDateStr.split('-').reverse().join(' / ')}
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all"><X className="w-6 h-6" /></button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-8 space-y-6">
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl text-xl font-black focus:ring-0 outline-none text-gray-900 transition-all shadow-inner" />
                            </div>
