                        <div className="flex flex-col gap-2 p-5 rounded-[1.5rem] border-2 bg-indigo-50/50 border-indigo-100 shadow-sm">
                            <div className="flex justify-between items-center">
                                <div>
                                    <span className="font-black uppercase text-xs tracking-widest block text-indigo-900">Tính toán giờ làm</span>
                                    <span className="text-[10px] font-bold text-indigo-400">(Tự động khấu trừ giờ nghỉ)</span>
                                </div>
                                <span className="text-3xl font-black text-indigo-700 tabular-nums">{calculatedHours}h</span>
