                            <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-[1.2rem] shadow-xl shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest text-sm flex items-center justify-center gap-2">
