import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'admin'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isAttendeesModalOpen, setIsAttendeesModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  const myCurrentRequest = useMemo(() => {
    if (!selectedDateStr || !user.id) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === user.id) || null;
  }, [requests, selectedDateStr, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (myCurrentRequest) {
        setStartTime(myCurrentRequest.start_time);
        setEndTime(myCurrentRequest.end_time);
        setReason(myCurrentRequest.reason || '');
    } else {
        const date = new Date(selectedDateStr);
        const isSat = date.getDay() === 6;
        if (isSat) {
            setStartTime(isSaturdayWork ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
    }
  }, [selectedDateStr, isSaturdayWork, myCurrentRequest]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const isWeekend = new Date(dateStr).getDay() === 0 || new Date(dateStr).getDay() === 6;
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (isWeekend || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: user.id, date: selectedDateStr, start_time: startTime,
        end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' 
    };
    try {
      const res = myCurrentRequest 
        ? await supabase.from('ot_requests').update(payload).eq('id', myCurrentRequest.id)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!myCurrentRequest) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', myCurrentRequest.id);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== myCurrentRequest.id));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    const cfg = dayConfigs[dateStr];
    setIsSaturdayWork(dateObj.getDay() === 6 ? (cfg !== undefined ? cfg : true) : false);
    setIsModalOpen(true);
  };

  const handleViewAttendees = (e: React.MouseEvent, dateStr: string) => {
    e.stopPropagation();
    setSelectedDateStr(dateStr);
    setIsAttendeesModalOpen(true);
  };

  // --- LOGIC THỐNG KÊ CHI TIẾT ---
  const currentMonthStr = useMemo(() => `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`, [currentDate]);

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  // FIX LOGIC TOP 5: Đảm bảo tính toán chính xác và gộp nhóm theo User ID
  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};

    // 1. Lấy tất cả các đơn trong tháng đang xem (không phân biệt trạng thái để kiểm tra nếu cần, 
    // nhưng thường chỉ tính 'approved' cho bảng xếp hạng thực tế)
    const monthlyData = requests.filter(r => r.date.startsWith(currentMonthStr));

    monthlyData.forEach(req => {
        // CHỈ TÍNH CÁC ĐƠN ĐÃ ĐƯỢC DUYỆT (approved)
        if (req.status !== 'approved') return;

        const id = req.user_id;
        if (!employeeMap[id]) {
            employeeMap[id] = { 
                name: req.users?.name || 'Thành viên mới', 
                hours: 0, 
                employee_id: req.users?.employee_id || '...',
                count: 0 
            };
        }

        // Cộng dồn giờ (đảm bảo là kiểu số) và tăng số lượt đăng ký
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });

    // 2. Chuyển Map thành Array và sắp xếp
    // Có thể sắp xếp theo 'hours' hoặc 'count' tùy yêu cầu. Ở đây giữ 'hours' làm chính.
    return Object.values(employeeMap)
        .sort((a, b) => b.hours - a.hours)
        .slice(0, 5);
  }, [requests, currentMonthStr]);

  const adminTrend = useMemo(() => {
    return Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i+1).padStart(2, '0')}`;
        return { day: i+1, count: new Set(requests.filter(r => r.date === dStr).map(r => r.user_id)).size };
    });
  }, [requests, currentMonthStr]);

  const attendeesOnSelectedDay = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSun = dateObj.getDay() === 0;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-1.5">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>

                        {isSat && configWork !== undefined && (
                            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm uppercase tracking-tighter border ${configWork ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-orange-50 text-orange-600 border-orange-200'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                        {isSun && (
                            <span className="text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm bg-rose-50 text-rose-600 border border-rose-200 uppercase tracking-tighter whitespace-nowrap">
                                Nghỉ
                            </span>
                        )}
                    </div>
                </div>

                <div className="h-12 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div 
                                className="w-10 h-10 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[11px] font-black text-white leading-none">TÔI</span>
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap gap-1 items-center">
                    {otherRequests.slice(0, 3).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-7 h-7 rounded-lg flex items-center justify-center border border-white shadow-sm bg-indigo-50 overflow-hidden transform hover:scale-110 transition-transform" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <span className="text-[10px] font-black text-indigo-700 uppercase">
                                {req.users?.name?.charAt(0) || 'D'}
                            </span>
                        </div>
                    ))}
                </div>

                {dayRequests.length > 0 && (
                    <div 
                        onClick={(e) => handleViewAttendees(e, dateStr)}
                        className="absolute bottom-1 right-1 bg-orange-500 text-white text-[9px] px-1.5 py-0.5 rounded-lg font-black flex items-center gap-1 shadow-lg transform group-hover:scale-110 transition-transform hover:bg-orange-600 active:scale-95"
                    >
                        <Users className="w-3 h-3" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
        {/* HEADER & NAV */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
            <div>
                <h2 className="text-2xl font-black text-gray-900 flex items-center gap-2 tracking-tight">
                    Tăng ca (OT)
                    <span className="text-xs font-bold bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full uppercase tracking-tighter">Manager Tool V2</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium italic">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button onClick={() => setActiveTab('calendar')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                <button onClick={() => setActiveTab('personal')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                    <UserIcon className="w-4 h-4" /> Cá nhân
                </button>
                {user.role === 'admin' && (
                    <button onClick={() => setActiveTab('admin')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'admin' ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                        <BarChart3 className="w-4 h-4" /> Quản trị
                    </button>
                )}
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-200 shadow-xl rounded-[2rem]">
                    <div className="flex items-center justify-between p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronLeft/></button>
                        <h3 className="text-lg font-black uppercase tracking-widest text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronRight/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-4 text-center ${i >= 5 ? 'text-rose-500' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                        <Card className="bg-gradient-to-br from-emerald-600 to-teal-700 text-white border-none shadow-xl">
                            <h3 className="text-xs font-black uppercase tracking-widest opacity-80 mb-1">Tổng giờ OT</h3>
                            <div className="flex items-end gap-2">
                                <span className="text-4xl font-black">{myStats.total.toFixed(1)}</span>
                                <span className="text-lg font-bold mb-1">h</span>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-indigo-500">
                            <div className="p-3 bg-indigo-50 rounded-2xl text-indigo-600"><Activity className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Số ngày đã làm</p>
                                <p className="text-2xl font-black text-gray-900">{myStats.count}</p>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-amber-500">
                            <div className="p-3 bg-amber-50 rounded-2xl text-amber-600"><Timer className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Đang chờ duyệt</p>
                                <p className="text-2xl font-black text-gray-900">{myStats.pending}</p>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-blue-500">
                            <div className="p-3 bg-blue-50 rounded-2xl text-blue-600"><TrendingUp className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Chu kỳ hiện tại</p>
                                <p className="text-xl font-black text-gray-900">T{currentDate.getMonth()+1}/{currentDate.getFullYear()}</p>
                            </div>
                        </Card>
                    </div>

                    <Card title="Biểu đồ làm việc cá nhân" className="rounded-3xl shadow-lg border-t-8 border-emerald-500">
                        <div className="h-64">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc'}} />
                                    <Bar dataKey="hours" fill="#10b981" radius={[4, 4, 0, 0]} barSize={12} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'admin' && user.role === 'admin' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* BẢNG VÀNG: CHIẾN THẦN OT (Ranked by Hours, but showing Days) */}
                        <Card title="🏆 BẢNG VÀNG CHIẾN THẦN OT" className="lg:col-span-1 rounded-[2.5rem] shadow-2xl border-none bg-white overflow-hidden flex flex-col">
                            <div className="p-6 bg-gradient-to-r from-indigo-600 to-blue-700 text-white">
                                <p className="text-[10px] font-black uppercase tracking-widest opacity-80">Bảng xếp hạng tháng {currentDate.getMonth()+1}</p>
                                <h4 className="text-xl font-black italic">TOP 5 STARS</h4>
                            </div>
                            <div className="flex-1 space-y-4 p-5">
                                {top5.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-full py-20 text-gray-400 italic">
                                        <Trophy className="w-12 h-12 mb-2 opacity-20" />
                                        Chưa có đơn duyệt tháng này
                                    </div>
                                ) : (
                                    top5.map((emp, idx) => {
                                        const isTop1 = idx === 0;
                                        const maxHours = top5[0].hours;
                                        const progress = (emp.hours / maxHours) * 100;

                                        return (
                                            <div key={idx} className={`p-4 rounded-[1.5rem] border-2 transition-all hover:scale-[1.02] ${
                                                idx === 0 ? 'bg-amber-50 border-amber-200' :
                                                idx === 1 ? 'bg-slate-50 border-slate-200' :
                                                idx === 2 ? 'bg-orange-50 border-orange-200' :
                                                'bg-white border-gray-100 shadow-sm'
                                            }`}>
                                                <div className="flex items-center gap-4">
                                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg relative shadow-inner ${
                                                        idx === 0 ? 'bg-gradient-to-br from-yellow-400 to-amber-600 text-white' :
                                                        idx === 1 ? 'bg-gradient-to-br from-slate-300 to-slate-500 text-white' :
                                                        idx === 2 ? 'bg-gradient-to-br from-orange-300 to-orange-500 text-white' :
                                                        'bg-indigo-50 text-indigo-400'
                                                    }`}>
                                                        {idx < 3 ? (
                                                            idx === 0 ? <Medal className="w-7 h-7" /> : <Trophy className="w-6 h-6" />
                                                        ) : (idx + 1)}
                                                        {isTop1 && <Star className="absolute -top-2 -right-2 w-6 h-6 text-yellow-500 fill-yellow-500 animate-bounce" />}
                                                    </div>
                                                    <div className="flex-1">
                                                        <div className="flex justify-between items-start">
                                                            <div>
                                                                <h4 className="font-black text-gray-900 text-sm leading-tight">{emp.name}</h4>
                                                                <p className="text-[10px] font-black text-indigo-500 tracking-tighter uppercase">{emp.employee_id} • {emp.count} ngày làm</p>
                                                            </div>
                                                            <div className="text-right">
                                                                <span className="text-xl font-black text-indigo-600 tabular-nums">{emp.hours.toFixed(1)}</span>
                                                                <span className="text-[10px] font-black text-gray-400 ml-0.5 uppercase">h</span>
                                                            </div>
                                                        </div>
                                                        <div className="mt-2 h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
                                                            <div 
                                                                className={`h-full rounded-full transition-all duration-1000 ${
                                                                    idx === 0 ? 'bg-amber-500' : 'bg-indigo-500'
                                                                }`} 
                                                                style={{ width: `${progress}%` }}
                                                            ></div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </Card>

                        <Card title="📈 Mật độ OT toàn nhân viên" className="lg:col-span-2 rounded-[2rem] shadow-2xl border-none">
                            <div className="h-[400px]">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={adminTrend}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <Tooltip cursor={{fill: '#f8fafc', radius: 10}} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                                        <Bar dataKey="count" fill="#4f46e5" radius={[6, 6, 0, 0]} name="Số người" barSize={16} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </div>
                </div>
            )}
        </div>

        {/* MODAL ĐĂNG KÝ */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-zoom-in overflow-hidden">
                    <div className="bg-indigo-600 p-8 flex justify-between items-center text-white relative">
                        <div className="relative z-10">
                            <h3 className="text-2xl font-black uppercase tracking-tight">{myCurrentRequest ? 'Chi tiết đơn' : 'Đăng ký OT'}</h3>
                            <p className="text-indigo-100 text-sm font-bold flex items-center gap-1.5 mt-1"><CalendarIcon className="w-4 h-4"/> {selectedDateStr.split('-').reverse().join('/')}</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X/></button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-8 space-y-6">
                        <div className="grid grid-cols-2 gap-6">
                            <div><label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Bắt đầu</label><input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-xl font-black focus:ring-2 focus:ring-indigo-500 text-gray-900"/></div>
                            <div><label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-xl font-black focus:ring-2 focus:ring-indigo-500 text-gray-900"/></div>
                        </div>

                        <div className="p-5 bg-indigo-50 rounded-3xl border border-indigo-100 flex justify-between items-center">
                            <div><p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Tổng thời gian</p><p className="text-[9px] text-indigo-300 font-bold">(Đã trừ giờ nghỉ tự động)</p></div>
                            <span className="text-3xl font-black text-indigo-700">{calculatedHours}h</span>
                        </div>

                        <div>
                            <div className="flex justify-between items-center mb-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung công việc</label><button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="text-[10px] font-black text-indigo-600 uppercase flex items-center gap-1 hover:text-indigo-800 disabled:opacity-50">{isRewriting ? <Loader2 className="w-3 h-3 animate-spin"/> : <Wand2 className="w-3 h-3"/>} AI Rewrite</button></div>
                            <textarea required value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 text-sm h-28 resize-none text-gray-900" placeholder="Hãy mô tả chi tiết công việc..."/>
                        </div>

                        <div className="flex gap-4">
                            {myCurrentRequest && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} disabled={isDeleting} className="p-4 bg-white text-rose-500 border border-rose-100 rounded-2xl hover:bg-rose-50 transition-all active:scale-95"><Trash2 className="w-6 h-6"/></button>}
                            <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 p-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-200 transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest text-sm flex items-center justify-center gap-2">
                                {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5"/>} {myCurrentRequest ? 'Cập nhật' : 'Gửi đăng ký'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* MODAL DANH SÁCH NGƯỜI ĐĂNG KÝ */}
        {isAttendeesModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-[60] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-sm animate-zoom-in overflow-hidden border border-gray-100">
                    <div className="bg-orange-500 p-6 flex justify-between items-center text-white">
                        <div className="flex items-center gap-3">
                            <Users className="w-6 h-6" />
                            <div>
                                <h3 className="text-lg font-black uppercase tracking-tight">Người đăng ký OT</h3>
                                <p className="text-xs opacity-90 font-bold">{selectedDateStr.split('-').reverse().join('/')}</p>
                            </div>
                        </div>
                        <button onClick={() => setIsAttendeesModalOpen(false)} className="hover:bg-black/10 p-2 rounded-xl transition-all">
                            <X className="w-5 h-5" />
                        </button>
                    </div>
                    <div className="p-6 max-h-[60vh] overflow-y-auto bg-gray-50">
                        <div className="space-y-3">
                            {attendeesOnSelectedDay.length === 0 ? (
                                <p className="text-center text-gray-400 italic py-4">Chưa có ai đăng ký.</p>
                            ) : (
                                attendeesOnSelectedDay.map((req, idx) => (
                                    <div key={idx} className="flex items-center justify-between p-3 bg-white rounded-xl border border-gray-100 shadow-sm">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-indigo-100 text-indigo-700 flex items-center justify-center font-black text-xs">
                                                {req.users?.name?.charAt(0) || 'D'}
                                            </div>
                                            <div>
                                                <p className="font-bold text-gray-900 text-sm">{req.users?.name}</p>
                                                <p className="text-[10px] text-gray-400 font-mono">{req.users?.employee_id}</p>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-xs font-black text-indigo-600">{req.total_hours}h</p>
                                            <p className="text-[9px] text-gray-400">{req.start_time}-{req.end_time}</p>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* MODAL XÁC NHẬN HỦY */}
        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-gray-100">
                    <div className="p-10 text-center">
                        <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl"><AlertTriangle className="w-8 h-8"/></div>
                        <h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đăng ký?</h3>
                        <p className="text-sm text-gray-500 font-medium leading-relaxed">Dữ liệu tăng ca sẽ bị xóa hoàn toàn khỏi hệ thống.</p>
                    </div>
                    <div className="p-6 bg-gray-50 flex gap-4 border-t border-gray-100">
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="flex-1 py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 text-xs uppercase transition-all">Đóng</button>
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="flex-1 py-4 bg-rose-600 text-white font-black rounded-2xl text-xs uppercase shadow-xl active:scale-95 flex items-center justify-center gap-2">
                            {isDeleting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4"/>} Hủy đơn
                        </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'admin'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  // State quản lý việc Admin đang sửa đơn của ai
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  // Lấy đơn của user đang được chọn (Admin có thể chọn user khác)
  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  // Đồng bộ form khi thay đổi user được chọn hoặc ngày được chọn
  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const date = new Date(selectedDateStr);
        const isSat = date.getDay() === 6;
        if (isSat) {
            setStartTime(isSaturdayWork ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, isSaturdayWork, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const isWeekend = new Date(dateStr).getDay() === 0 || new Date(dateStr).getDay() === 6;
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (isWeekend || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);

    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };

    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id); // Reset về chính mình khi mở lịch mới
    const cfg = dayConfigs[dateStr];
    setIsSaturdayWork(dateObj.getDay() === 6 ? (cfg !== undefined ? cfg : true) : false);
    setIsModalOpen(true);
  };

  // --- LOGIC THỐNG KÊ ---
  const currentMonthStr = useMemo(() => `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`, [currentDate]);

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) {
            employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        }
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const adminTrend = useMemo(() => {
    return Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i+1).padStart(2, '0')}`;
        return { day: i+1, count: new Set(requests.filter(r => r.date === dStr).map(r => r.user_id)).size };
    });
  }, [requests, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSun = dateObj.getDay() === 0;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-1.5">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>

                        {isSat && configWork !== undefined && (
                            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm uppercase tracking-tighter border ${configWork ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-orange-50 text-orange-600 border-orange-200'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                        {isSun && (
                            <span className="text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm bg-rose-50 text-rose-600 border border-rose-200 uppercase tracking-tighter whitespace-nowrap">
                                Nghỉ
                            </span>
                        )}
                    </div>
                </div>

                <div className="h-12 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div 
                                className="w-10 h-10 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
                            >
                                <span className="text-[11px] font-black text-white leading-none">TÔI</span>
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap gap-1 items-center">
                    {otherRequests.slice(0, 3).map((req, idx) => (
                        <div 
                            key={idx} 
                            className="w-7 h-7 rounded-lg flex items-center justify-center border border-white shadow-sm bg-indigo-50 overflow-hidden transform hover:scale-110 transition-transform" 
                            title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}
                        >
                            <span className="text-[10px] font-black text-indigo-700 uppercase">
                                {req.users?.name?.charAt(0) || 'D'}
                            </span>
                        </div>
                    ))}
                </div>

                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-orange-500 text-white text-[9px] px-1.5 py-0.5 rounded-lg font-black flex items-center gap-1 shadow-lg">
                        <Users className="w-3 h-3" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
        {/* HEADER & NAV */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
            <div>
                <h2 className="text-2xl font-black text-gray-900 flex items-center gap-2 tracking-tight">
                    Tăng ca (OT)
                    <span className="text-xs font-bold bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full uppercase tracking-tighter">Manager Tool V2</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium italic">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button onClick={() => setActiveTab('calendar')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                <button onClick={() => setActiveTab('personal')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                    <UserIcon className="w-4 h-4" /> Cá nhân
                </button>
                {isAdmin && (
                    <button onClick={() => setActiveTab('admin')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'admin' ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                        <BarChart3 className="w-4 h-4" /> Quản trị
                    </button>
                )}
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-200 shadow-xl rounded-[2rem]">
                    <div className="flex items-center justify-between p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronLeft/></button>
                        <h3 className="text-lg font-black uppercase tracking-widest text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronRight/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-4 text-center ${i >= 5 ? 'text-rose-500' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                        <Card className="bg-gradient-to-br from-emerald-600 to-teal-700 text-white border-none shadow-xl">
                            <h3 className="text-xs font-black uppercase tracking-widest opacity-80 mb-1">Tổng giờ OT</h3>
                            <div className="flex items-end gap-2">
                                <span className="text-4xl font-black">{myStats.total.toFixed(1)}</span>
                                <span className="text-lg font-bold mb-1">h</span>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-indigo-500">
                            <div className="p-3 bg-indigo-50 rounded-2xl text-indigo-600"><Activity className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Số ngày đã làm</p>
                                <p className="text-2xl font-black text-gray-900">{myStats.count}</p>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-amber-500">
                            <div className="p-3 bg-amber-50 rounded-2xl text-amber-600"><Timer className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Đang chờ duyệt</p>
                                <p className="text-2xl font-black text-gray-900">{myStats.pending}</p>
                            </div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-blue-500">
                            <div className="p-3 bg-blue-50 rounded-2xl text-blue-600"><TrendingUp className="w-6 h-6" /></div>
                            <div>
                                <p className="text-[10px] font-black text-gray-400 uppercase">Chu kỳ hiện tại</p>
                                <p className="text-xl font-black text-gray-900">T{currentDate.getMonth()+1}/{currentDate.getFullYear()}</p>
                            </div>
                        </Card>
                    </div>
                    <Card title="Biểu đồ làm việc cá nhân" className="rounded-3xl shadow-lg border-t-8 border-emerald-500">
                        <div className="h-64">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc'}} />
                                    <Bar dataKey="hours" fill="#10b981" radius={[4, 4, 0, 0]} barSize={12} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'admin' && isAdmin && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        <Card title="🏆 BẢNG VÀNG CHIẾN THẦN OT" className="lg:col-span-1 rounded-[2.5rem] shadow-2xl border-none bg-white overflow-hidden flex flex-col">
                            <div className="p-6 bg-gradient-to-r from-indigo-600 to-blue-700 text-white">
                                <p className="text-[10px] font-black uppercase tracking-widest opacity-80">Bảng xếp hạng tháng {currentDate.getMonth()+1}</p>
                                <h4 className="text-xl font-black italic">TOP 5 STARS</h4>
                            </div>
                            <div className="flex-1 space-y-4 p-5">
                                {top5.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-full py-20 text-gray-400 italic">
                                        <Trophy className="w-12 h-12 mb-2 opacity-20" />
                                        Chưa có đơn duyệt tháng này
                                    </div>
                                ) : (
                                    top5.map((emp, idx) => (
                                        <div key={idx} className={`p-4 rounded-[1.5rem] border-2 transition-all hover:scale-[1.02] ${idx === 0 ? 'bg-amber-50 border-amber-200' : idx === 1 ? 'bg-slate-50 border-slate-200' : idx === 2 ? 'bg-orange-50 border-orange-200' : 'bg-white border-gray-100 shadow-sm'}`}>
                                            <div className="flex items-center gap-4">
                                                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg shadow-inner ${idx === 0 ? 'bg-gradient-to-br from-yellow-400 to-amber-600 text-white' : idx === 1 ? 'bg-gradient-to-br from-slate-300 to-slate-500 text-white' : idx === 2 ? 'bg-gradient-to-br from-orange-300 to-orange-500 text-white' : 'bg-indigo-50 text-indigo-400'}`}>
                                                    {idx < 3 ? (idx === 0 ? <Medal className="w-7 h-7" /> : <Trophy className="w-6 h-6" />) : (idx + 1)}
                                                </div>
                                                <div className="flex-1">
                                                    <div className="flex justify-between items-start">
                                                        <div><h4 className="font-black text-gray-900 text-sm leading-tight">{emp.name}</h4><p className="text-[10px] font-black text-indigo-500 tracking-tighter uppercase">{emp.employee_id} • {emp.count} ngày làm</p></div>
                                                        <div className="text-right"><span className="text-xl font-black text-indigo-600 tabular-nums">{emp.hours.toFixed(1)}</span><span className="text-[10px] font-black text-gray-400 ml-0.5 uppercase">h</span></div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </Card>
                        <Card title="📈 Mật độ OT toàn nhân viên" className="lg:col-span-2 rounded-[2rem] shadow-2xl border-none">
                            <div className="h-[400px]">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={adminTrend}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <Tooltip cursor={{fill: '#f8fafc', radius: 10}} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                                        <Bar dataKey="count" fill="#4f46e5" radius={[6, 6, 0, 0]} name="Số người" barSize={16} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </div>
                </div>
            )}
        </div>

        {/* MODAL ĐĂNG KÝ (NÂNG CẤP CHO ADMIN) */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in overflow-y-auto">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-3xl animate-zoom-in overflow-hidden my-8">
                    <div className="bg-indigo-600 p-8 flex justify-between items-start text-white relative">
                        <div className="relative z-10">
                            <h3 className="text-2xl font-black uppercase tracking-tight">Quản lý OT - {selectedDateStr.split('-').reverse().join('/')}</h3>
                            <p className="text-indigo-100 text-sm font-bold flex items-center gap-1.5 mt-1">
                                <Users className="w-4 h-4"/> {requests.filter(r => r.date === selectedDateStr).length} người đăng ký
                            </p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X/></button>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2">
                        {/* CỘT TRÁI: DANH SÁCH NGƯỜI ĐĂNG KÝ (CHỈ CHO ADMIN) */}
                        <div className={`p-8 border-r border-gray-100 bg-gray-50/50 ${!isAdmin && 'hidden'}`}>
                            <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <Users className="w-3 h-3"/> Đã đăng ký
                            </h4>
                            <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2">
                                {requests.filter(r => r.date === selectedDateStr).length === 0 ? (
                                    <p className="text-sm italic text-gray-400">Chưa có ai đăng ký ngày này.</p>
                                ) : (
                                    requests.filter(r => r.date === selectedDateStr).map(req => (
                                        <div 
                                            key={req.id} 
                                            onClick={() => setTargetUserId(req.user_id)}
                                            className={`p-3 rounded-2xl border-2 transition-all cursor-pointer flex justify-between items-center ${targetUserId === req.user_id ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-transparent hover:border-gray-200'}`}
                                        >
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-lg bg-indigo-100 text-indigo-700 flex items-center justify-center font-black text-[10px]">
                                                    {req.users?.name?.charAt(0)}
                                                </div>
                                                <div>
                                                    <p className="text-xs font-bold text-gray-900">{req.users?.name}</p>
                                                    <p className="text-[10px] text-gray-400">{req.users?.employee_id}</p>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-xs font-black text-indigo-600">{req.total_hours}h</p>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>

                            <button 
                                onClick={() => { setTargetUserId(''); setEditingRequestId(null); setReason(''); }}
                                className="mt-6 w-full py-3 bg-white border-2 border-dashed border-gray-300 rounded-2xl text-xs font-black text-gray-400 hover:text-indigo-600 hover:border-indigo-400 transition-all flex items-center justify-center gap-2"
                            >
                                <UserPlus className="w-4 h-4"/> Thêm đăng ký hộ
                            </button>
                        </div>

                        {/* CỘT PHẢI: FORM ĐĂNG KÝ */}
                        <form onSubmit={handleSubmit} className="p-8 space-y-5">
                            {isAdmin && (
                                <div>
                                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Nhân viên thực hiện</label>
                                    <div className="relative">
                                        <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4"/>
                                        <select 
                                            required
                                            value={targetUserId}
                                            onChange={(e) => setTargetUserId(e.target.value)}
                                            className="w-full pl-11 pr-4 py-3 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-2 focus:ring-indigo-500 text-gray-900 appearance-none cursor-pointer"
                                        >
                                            <option value="" disabled>-- Chọn nhân viên --</option>
                                            {allEmployees.map(emp => (
                                                <option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>
                                            ))}
                                        </select>
                                    </div>
                                    {targetUserId && targetUserId !== user.id && (
                                        <p className="mt-2 text-[10px] text-orange-600 font-bold bg-orange-50 px-3 py-1 rounded-lg inline-block border border-orange-100">
                                            ⚠️ Bạn đang đăng ký hộ nhân viên
                                        </p>
                                    )}
                                </div>
                            )}

                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Bắt đầu</label><input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-lg font-black focus:ring-2 focus:ring-indigo-500 text-gray-900"/></div>
                                <div><label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-lg font-black focus:ring-2 focus:ring-indigo-500 text-gray-900"/></div>
                            </div>

                            <div className="p-4 bg-indigo-50 rounded-2xl border border-indigo-100 flex justify-between items-center">
                                <div><p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest leading-none">Tổng thời gian</p></div>
                                <span className="text-2xl font-black text-indigo-700">{calculatedHours}h</span>
                            </div>

                            <div>
                                <div className="flex justify-between items-center mb-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung</label><button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="text-[10px] font-black text-indigo-600 flex items-center gap-1">{isRewriting ? <Loader2 className="w-3 h-3 animate-spin"/> : <Wand2 className="w-3 h-3"/>} AI</button></div>
                                <textarea required value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl focus:ring-2 focus:ring-indigo-500 text-sm h-24 resize-none text-gray-900" placeholder="Mô tả công việc..."/>
                            </div>

                            <div className="flex gap-4 pt-2">
                                {(editingRequestId && (isAdmin || targetUserId === user.id)) && (
                                    <button type="button" onClick={() => setIsConfirmCancelOpen(true)} disabled={isDeleting} className="p-4 bg-white text-rose-500 border-2 border-rose-50 rounded-2xl hover:bg-rose-50 transition-all"><Trash2 className="w-5 h-5"/></button>
                                )}
                                <button type="submit" disabled={isSubmitting || calculatedHours <= 0 || !targetUserId} className="flex-1 p-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 transition-all disabled:opacity-50 flex items-center justify-center gap-2 uppercase tracking-widest text-xs">
                                    {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Save className="w-4 h-4"/>} 
                                    {editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* MODAL XÁC NHẬN HỦY */}
        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-gray-100">
                    <div className="p-10 text-center">
                        <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl"><AlertTriangle className="w-8 h-8"/></div>
                        <h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn OT?</h3>
                        <p className="text-sm text-gray-500 font-medium">Bạn có chắc chắn muốn xóa đơn của {allEmployees.find(e => e.id === targetUserId)?.name || 'nhân viên này'}?</p>
                    </div>
                    <div className="p-6 bg-gray-50 flex gap-4 border-t border-gray-100">
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="flex-1 py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 text-xs uppercase transition-all">Đóng</button>
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="flex-1 py-4 bg-rose-600 text-white font-black rounded-2xl text-xs uppercase shadow-xl active:scale-95 flex items-center justify-center gap-2">
                            {isDeleting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4"/>} Hủy ngay
                        </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus, Share2
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [isSaturdayWork, setIsSaturdayWork] = useState(false);

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const date = new Date(selectedDateStr);
        const isSat = date.getDay() === 6;
        if (isSat) {
            setStartTime(isSaturdayWork ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, isSaturdayWork, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const isWeekend = new Date(dateStr).getDay() === 0 || new Date(dateStr).getDay() === 6;
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (isWeekend || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr]);

  const handleExportExcel = () => {
    const currentMonthData = requests.filter(r => r.date.startsWith(currentMonthStr));
    const formattedData = currentMonthData.map(req => ({
        'Mã nhân viên': req.users?.employee_id || 'N/A',
        'Họ và tên': req.users?.name || 'Ẩn danh',
        'Ngày': req.date,
        'Bắt đầu': req.start_time,
        'Kết thúc': req.end_time,
        'Tổng giờ': req.total_hours,
        'Trạng thái': req.status === 'approved' ? 'Đã duyệt' : 'Chờ duyệt',
        'Lý do': req.reason
    }));

    const worksheet = XLSX.utils.json_to_sheet(formattedData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, `OT_T${currentDate.getMonth() + 1}`);
    XLSX.writeFile(workbook, `Bao_cao_OT_Thang_${currentDate.getMonth() + 1}_${currentDate.getFullYear()}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);

    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };

    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    const cfg = dayConfigs[dateStr];
    setIsSaturdayWork(dateObj.getDay() === 6 ? (cfg !== undefined ? cfg : true) : false);
    setIsModalOpen(true);
  };

  const currentMonthStr = useMemo(() => `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`, [currentDate]);

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) {
            employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        }
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const adminTrend = useMemo(() => {
    return Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i+1).padStart(2, '0')}`;
        return { day: i+1, count: new Set(requests.filter(r => r.date === dStr).map(r => r.user_id)).size };
    });
  }, [requests, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSun = dateObj.getDay() === 0;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-1.5">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && configWork !== undefined && (
                            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm uppercase tracking-tighter border ${configWork ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-orange-50 text-orange-600 border-orange-200'}`}>
                                {configWork ? 'Làm' : 'Nghỉ'}
                            </span>
                        )}
                        {isSun && (
                            <span className="text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm bg-rose-50 text-rose-600 border border-rose-200 uppercase tracking-tighter whitespace-nowrap">
                                Nghỉ
                            </span>
                        )}
                    </div>
                </div>

                <div className="h-12 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div 
                                className="w-10 h-10 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" 
                                title={`Bạn (${myRequest.total_hours}h)`}
