                    </div>
                </div>
            )}
        </div>

        {/* MODAL ĐĂNG KÝ SIÊU GỌN - NỔI BẬT THỜI GIAN */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md animate-zoom-in overflow-hidden my-auto border border-white/20">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white relative">
                        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none"><Clock className="w-32 h-32" /></div>
                        <div className="relative z-10">
                            <div className="flex items-center gap-2"><CalendarDays className="w-4 h-4 text-indigo-200" /><h3 className="text-xl font-black uppercase tracking-tighter leading-none">OT: {selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <div className="flex items-center gap-2 mt-2">
                                {isAdmin && new Date(selectedDateStr).getDay() === 6 && (
                                    <button onClick={toggleSaturdayStatus} disabled={isConfigUpdating} className="flex items-center gap-1.5 px-2 py-0.5 bg-white/20 rounded-lg text-[9px] font-black uppercase hover:bg-white/30 transition-all border border-white/10 shadow-sm">
                                        {isConfigUpdating ? <Loader2 className="w-3 h-3 animate-spin"/> : (dayConfigs[selectedDateStr] ?? true) ? <ToggleRight className="w-3.5 h-3.5"/> : <ToggleLeft className="w-3.5 h-3.5"/>}
                                        {(dayConfigs[selectedDateStr] ?? true) ? 'T7 Làm việc' : 'T7 Nghỉ'}
                                    </button>
                                )}
                                {new Date(selectedDateStr).getDay() === 0 && <span className="text-[9px] font-black uppercase bg-rose-500/40 px-2.5 py-1 rounded-lg border border-white/10 flex items-center gap-1"><AlertCircle className="w-3 h-3"/> Chủ Nhật Nghỉ</span>}
                            </div>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2.5 hover:bg-white/20 rounded-2xl transition-all shadow-lg backdrop-blur-md border border-white/10"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-6 space-y-6 bg-gray-50/50">
                        {/* DANH SÁCH ĐỒNG NGHIỆP: NHỎ GỌN & TINH TẾ */}
                        {dayRequests.length > 0 && (
                            <div className="space-y-3">
                                <div className="flex justify-between items-center px-1">
                                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-1.5"><Users className="w-3 h-3"/> Đồng nghiệp ({dayRequests.length})</h4>
                                    {isAdmin && <span className="text-[9px] font-bold text-indigo-500 bg-indigo-50 px-2 py-0.5 rounded-full border border-indigo-100">Click để sửa hộ</span>}
                                </div>
                                <div className="flex flex-wrap gap-2 max-h-24 overflow-y-auto p-1 custom-scrollbar">
                                    {dayRequests.map(req => (
                                        <button key={req.id} onClick={() => setTargetUserId(req.user_id)} className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-2xl border-2 transition-all group relative ${targetUserId === req.user_id ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg scale-105' : 'bg-white border-gray-100 text-gray-600 hover:border-indigo-200 hover:shadow-sm'}`}>
                                            <div className={`w-6 h-6 rounded-xl flex items-center justify-center font-black text-[10px] shadow-inner ${targetUserId === req.user_id ? 'bg-white text-indigo-600' : 'bg-indigo-50 text-indigo-700 ring-2 ring-indigo-100/50'}`}>{req.users?.name?.charAt(0)}</div>
                                            <span className="text-[10px] font-black tracking-tighter truncate max-w-[80px]">{req.users?.name}</span>
                                            {targetUserId === req.user_id && <div className="absolute -top-1 -right-1 w-3 h-3 bg-white text-indigo-600 rounded-full flex items-center justify-center border border-indigo-600 shadow-sm"><Check className="w-2 h-2" /></div>}
                                        </button>
                                    ))}
                                    {isAdmin && <button onClick={() => { setTargetUserId(''); setEditingRequestId(null); setReason(''); }} className="flex items-center gap-1.5 px-3 py-1.5 rounded-2xl border-2 border-dashed border-gray-300 text-gray-400 hover:text-indigo-600 hover:border-indigo-400 transition-all text-[10px] font-black group bg-white/50"><PlusCircle className="w-4 h-4 text-gray-300 group-hover:text-indigo-400"/> Thêm người</button>}
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border border-amber-100 p-6 rounded-[2rem] text-center space-y-4 shadow-xl shadow-amber-900/5 animate-fade-in relative overflow-hidden">
                                    <div className="absolute top-0 left-0 w-full h-1 bg-amber-400/30"></div>
                                    <Eye className="w-10 h-10 text-amber-500 mx-auto" />
                                    <div><h4 className="font-black text-amber-900 uppercase text-sm tracking-tight">Chi tiết đơn đồng nghiệp</h4><div className="mt-4 grid grid-cols-2 gap-2"><div className="bg-white/80 p-3 rounded-2xl border border-amber-200"><p className="text-[9px] font-black text-amber-400 uppercase">Khung giờ</p><p className="text-xs font-black text-amber-800">{startTime} - {endTime}</p></div><div className="bg-white/80 p-3 rounded-2xl border border-amber-200"><p className="text-[9px] font-black text-amber-400 uppercase">Tổng cộng</p><p className="text-xs font-black text-amber-800">{calculatedHours}h</p></div></div><div className="mt-3 p-3 bg-white/50 rounded-2xl text-left border border-amber-200/50 italic text-[11px] text-amber-700">"{reason || 'Chưa cập nhật mô tả'}"</div></div>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3.5 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center gap-2 tracking-widest"><MousePointer2 className="w-4 h-4" /> Đăng ký của tôi</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="relative group"><label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1 tracking-widest">Đang chỉnh sửa cho:</label><div className="relative"><UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-400 w-4 h-4" /><select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full pl-11 pr-4 py-3.5 bg-white border-2 border-gray-100 rounded-[1.25rem] text-xs font-black focus:ring-2 focus:ring-indigo-500 text-gray-900 shadow-sm appearance-none transition-all group-hover:border-indigo-100"><option value="" disabled>-- Chọn nhân viên --</option>{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}</select><Settings className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 w-3 h-3 pointer-events-none" /></div></div>
                                    )}

                                    {/* DASHBOARD THỜI GIAN NỔI BẬT */}
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="bg-white p-4 rounded-3xl border-2 border-gray-100 shadow-sm transition-all focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-500/10 group">
                                            <label className="block text-[9px] font-black text-gray-400 uppercase mb-2 tracking-widest group-focus-within:text-indigo-500">Giờ Bắt đầu</label>
                                            <div className="flex items-center gap-2">
                                                <Clock className="w-4 h-4 text-indigo-500" />
                                                <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 cursor-pointer"/>
                                            </div>
                                        </div>
                                        <div className="bg-white p-4 rounded-3xl border-2 border-gray-100 shadow-sm transition-all focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-500/10 group">
                                            <label className="block text-[9px] font-black text-gray-400 uppercase mb-2 tracking-widest group-focus-within:text-indigo-500">Giờ Kết thúc</label>
                                            <div className="flex items-center gap-2">
                                                <Clock className="w-4 h-4 text-rose-500" />
                                                <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 cursor-pointer"/>
                                            </div>
                                        </div>
                                    </div>

                                    {/* TỔNG GIỜ: CỰC KỲ NỔI BẬT */}
                                    <div className="relative group">
                                        <div className="absolute inset-0 bg-gradient-to-r from-indigo-600 to-blue-600 rounded-[2rem] blur-lg opacity-10 group-hover:opacity-20 transition-opacity"></div>
                                        <div className="relative flex justify-between items-center p-6 bg-gradient-to-r from-indigo-600 to-blue-700 rounded-[2rem] shadow-xl text-white">
                                            <div>
                                                <p className="text-[10px] font-black text-indigo-100 uppercase tracking-[0.2em] leading-none mb-1">Thời gian OT thực tế</p>
                                                <p className="text-[9px] text-indigo-200/60 font-medium italic">*Đã bao gồm khấu trừ giờ nghỉ</p>
                                            </div>
                                            <div className="text-right">
                                                <span className="text-4xl font-black tracking-tighter drop-shadow-md">{calculatedHours}</span>
                                                <span className="text-lg font-black ml-1 text-indigo-200">h</span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="space-y-2"><div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung công việc</label><button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="text-[10px] font-black text-indigo-600 flex items-center gap-1.5 hover:bg-indigo-50 px-2.5 py-1 rounded-full border border-indigo-100 transition-all">{isRewriting ? <Loader2 className="w-3 h-3 animate-spin"/> : <Wand2 className="w-3 h-3"/>}AI Smart Write</button></div><textarea required value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-5 bg-white border-2 border-gray-100 rounded-[1.5rem] focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm h-28 resize-none text-gray-900 shadow-sm transition-all placeholder:text-gray-300 font-medium" placeholder="Bạn đã làm gì trong khoảng thời gian này?"/></div>

                                    <div className="flex gap-4 pt-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} disabled={isDeleting} className="p-4 bg-white text-rose-500 border-2 border-rose-50 rounded-2xl hover:bg-rose-50 transition-all active:scale-90 shadow-sm group"><Trash2 className="w-6 h-6 group-hover:animate-bounce"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0 || !targetUserId} className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-3xl shadow-2xl shadow-indigo-200 transition-all disabled:opacity-50 flex items-center justify-center gap-3 uppercase tracking-widest text-xs active:scale-95">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5"/>} {editingRequestId ? 'Lưu đơn' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in"><div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in border border-gray-100"><div className="p-8 text-center"><div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-4 rounded-3xl shadow-xl shadow-rose-100 rotate-12"><AlertTriangle className="w-8 h-8"/></div><h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn OT?</h3><p className="text-xs text-gray-500 font-medium italic px-4">Đơn sẽ bị xóa vĩnh viễn khỏi hệ thống.</p></div><div className="p-5 bg-gray-50 flex gap-3 border-t border-gray-100"><button onClick={() => setIsConfirmCancelOpen(false)} className="flex-1 py-3.5 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 text-[10px] uppercase active:scale-95 transition-all">Đóng</button><button onClick={handleCancelRequest} disabled={isDeleting} className="flex-1 py-3.5 bg-rose-600 text-white font-black rounded-2xl text-[10px] uppercase shadow-xl shadow-rose-200 active:scale-95 flex items-center justify-center gap-2">{isDeleting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Trash2 className="w-3.5 h-3.5"/>} Hủy</button></div></div></div>
        )}
    </div>
  );
};
const PlusCircle = ({className}: {className?: string}) => <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus, Share2, ToggleLeft, ToggleRight, Eye, MousePointer2, CalendarRange, FileDown, ArrowRight, Zap
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  // States cho xuất Excel theo khoảng ngày
  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('20:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            if (isWorkDay) {
                setStartTime('14:30');
            } else {
                setStartTime('08:00');
            }
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const toggleSaturdayStatus = async () => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    const currentStatus = dayConfigs[selectedDateStr] ?? true;
    const newStatus = !currentStatus;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: newStatus });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: newStatus }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    let filtered = requests.filter(r => r.date >= start && r.date <= end);

    if (mode === 'personal') {
        filtered = filtered.filter(r => r.user_id === user.id);
    }

    if (filtered.length === 0) {
        return alert("Không có dữ liệu trong khoảng thời gian này.");
    }

    // Sắp xếp theo ngày tăng dần để các tab xuất hiện theo thứ tự thời gian
    filtered.sort((a, b) => a.date.localeCompare(b.date));

    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    // Nhóm dữ liệu theo ngày
    const groupedByDate: Record<string, OvertimeRequest[]> = {};
    filtered.forEach(req => {
        if (!groupedByDate[req.date]) {
            groupedByDate[req.date] = [];
        }
        groupedByDate[req.date].push(req);
    });

    // Tạo sheet TỔNG HỢP ở đầu
    const summaryData = filtered.map(req => {
        const d = new Date(req.date);
        return {
            'Ngày': req.date,
            'Thứ': dayNames[d.getDay()],
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        };
    });
    const summarySheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'BẢNG TỔNG HỢP');

    // Tạo từng tab cho mỗi ngày
    Object.keys(groupedByDate).forEach(dateKey => {
        const dayRequests = groupedByDate[dateKey];
        const dateObj = new Date(dateKey);
        const dayLabel = dayNames[dateObj.getDay()];

        const sheetData = dayRequests.map(req => ({
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        }));

        const worksheet = XLSX.utils.json_to_sheet(sheetData);

        // Định dạng tên tab: dd-mm (ví dụ: 25-10)
        const tabName = dateKey.split('-').reverse().slice(0, 2).join('-');
        XLSX.utils.book_append_sheet(workbook, worksheet, `${tabName} (${dayLabel})`);
    });

    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'personal' ? 'Ca_nhan' : 'Toan_bo'}_${start}_den_${end}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => {
      const today = new Date().toISOString().split('T')[0];
      handleExportExcel(mode, { start: today, end: today });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
  };

  const currentMonthStr = useMemo(() => `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`, [currentDate]);

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const adminTrend = useMemo(() => {
    return Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i+1).padStart(2, '0')}`;
        return { day: i+1, count: new Set(requests.filter(r => r.date === dStr).map(r => r.user_id)).size };
    });
  }, [requests, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-32 bg-gray-50 border border-gray-100 opacity-50"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSun = dateObj.getDay() === 0;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-32 border border-gray-100 p-2 relative transition-all hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50/30 ring-inset ring-2 ring-blue-500/20' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-1.5">
                        <span className={`text-base font-black ${isToday ? 'bg-blue-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-md' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {isSat && (
                            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm uppercase tracking-tighter border ${configWork === false ? 'bg-orange-50 text-orange-600 border-orange-200' : 'bg-blue-50 text-blue-600 border-blue-200'}`}>
                                {configWork === false ? 'Nghỉ' : 'Làm'}
                            </span>
                        )}
                        {isSun && <span className="text-[8px] font-black px-1.5 py-0.5 rounded shadow-sm bg-rose-50 text-rose-600 border border-rose-200 uppercase tracking-tighter whitespace-nowrap">Nghỉ</span>}
                    </div>
                </div>

                <div className="h-12 flex items-center justify-start mb-1">
                    {myRequest && (
                        <div className="relative transform hover:scale-110 transition-transform">
                            <div className="w-10 h-10 rounded-xl flex items-center justify-center border-2 border-blue-600 shadow-lg bg-gradient-to-br from-blue-500 to-blue-700 z-10" title={`Bạn (${myRequest.total_hours}h)`}>
                                <span className="text-[11px] font-black text-white leading-none">TÔI</span>
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex flex-wrap gap-1 items-center">
                    {otherRequests.slice(0, 3).map((req, idx) => (
                        <div key={idx} className="w-7 h-7 rounded-lg flex items-center justify-center border border-white shadow-sm bg-indigo-50 overflow-hidden transform hover:scale-110 transition-transform" title={`${req.users?.name || 'Đồng nghiệp'} (${req.total_hours}h)`}>
                            <span className="text-[10px] font-black text-indigo-700 uppercase">{req.users?.name?.charAt(0) || 'D'}</span>
                        </div>
                    ))}
                </div>

                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-orange-500 text-white text-[9px] px-1.5 py-0.5 rounded-lg font-black flex items-center gap-1 shadow-lg group-hover:bg-orange-600">
                        <Users className="w-3 h-3" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const isViewOnly = targetUserId !== user.id && !isAdmin;
  const dayRequests = requests.filter(r => r.date === selectedDateStr);

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
            <div>
                <h2 className="text-2xl font-black text-gray-900 flex items-center gap-2 tracking-tight">
                    Tăng ca (OT)
                    <span className="text-xs font-bold bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full uppercase tracking-tighter">Manager Tool V2</span>
                </h2>
                <p className="text-sm text-gray-500 font-medium italic">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-xl border border-gray-200 shadow-inner">
                <button onClick={() => setActiveTab('calendar')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                    <CalendarIcon className="w-4 h-4" /> Lịch biểu
                </button>
                <button onClick={() => setActiveTab('personal')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                    <UserIcon className="w-4 h-4" /> Cá nhân
                </button>
                <button onClick={() => setActiveTab('stats')} className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}>
                    <BarChart3 className="w-4 h-4" /> {isAdmin ? 'Quản trị' : 'Thống kê'}
                </button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-200 shadow-xl rounded-[2rem]">
                    <div className="flex items-center justify-between p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronLeft/></button>
                        <h3 className="text-lg font-black uppercase tracking-widest text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronRight/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-4 text-center ${i >= 5 ? 'text-rose-500' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
