                        <Card className="flex items-center gap-4 bg-white border-l-8 border-amber-500">
                            <div className="p-3 bg-amber-50 rounded-2xl text-amber-600"><Timer className="w-6 h-6" /></div>
                            <div><p className="text-[10px] font-black text-gray-400 uppercase">Đang chờ duyệt</p><p className="text-2xl font-black text-gray-900">{myStats.pending}</p></div>
                        </Card>
                        <Card className="flex items-center gap-4 bg-white border-l-8 border-blue-500">
                            <div className="p-3 bg-blue-50 rounded-2xl text-blue-600"><TrendingUp className="w-6 h-6" /></div>
                            <div><p className="text-[10px] font-black text-gray-400 uppercase">Chu kỳ hiện tại</p><p className="text-xl font-black text-gray-900">T{currentDate.getMonth()+1}/{currentDate.getFullYear()}</p></div>
                        </Card>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        <Card title="Biểu đồ làm việc cá nhân" className="lg:col-span-2 rounded-3xl shadow-lg border-t-8 border-emerald-500">
                            <div className="h-64">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={myStats.trend} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <Tooltip cursor={{fill: '#f8fafc'}} />
                                        <Bar dataKey="hours" fill="#10b981" radius={[4, 4, 0, 0]} barSize={12} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>

                        {/* BỘ CÔNG CỤ XUẤT EXCEL CÁ NHÂN */}
                        <Card className="lg:col-span-1 rounded-[2.5rem] shadow-2xl border-none bg-white flex flex-col overflow-hidden">
                            <div className="p-6 bg-gradient-to-br from-blue-600 to-indigo-800 text-white">
                                <div className="flex items-center gap-3">
                                    <div className="p-3 bg-white/20 rounded-2xl backdrop-blur-md"><FileSpreadsheet className="w-6 h-6" /></div>
                                    <h3 className="font-black uppercase text-sm tracking-widest leading-tight">Xuất báo cáo OT<br/><span className="text-[10px] opacity-70">Excel Smart Export</span></h3>
                                </div>
                            </div>

                            <div className="p-6 space-y-6 flex-1 bg-gray-50/30">
                                {/* Quick Export Buttons */}
                                <div className="grid grid-cols-1 gap-2">
                                    <button 
                                        onClick={() => handleExportToday('personal')}
                                        className="w-full py-3 bg-white hover:bg-emerald-50 text-emerald-600 border-2 border-emerald-100 font-black rounded-2xl transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-[10px] group shadow-sm"
                                    >
                                        <Zap className="w-4 h-4 fill-emerald-600 group-hover:animate-pulse" />
                                        Xuất hôm nay
                                    </button>
                                </div>

                                <div className="relative flex items-center py-2">
                                    <div className="flex-grow border-t border-gray-200"></div>
                                    <span className="flex-shrink mx-4 text-[9px] font-black text-gray-400 uppercase tracking-widest">Hoặc theo khoảng ngày</span>
                                    <div className="flex-grow border-t border-gray-200"></div>
                                </div>

                                <div className="space-y-4">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-1">Mốc bắt đầu</label>
                                        <div className="relative group">
                                            <CalendarRange className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-blue-500 transition-transform" />
                                            <input type="date" value={exportStartDate} onChange={(e) => setExportStartDate(e.target.value)} className="w-full pl-11 pr-4 py-3.5 bg-white border-2 border-gray-100 rounded-2xl text-xs font-black focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 text-gray-900 shadow-sm transition-all"/>
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-1">Mốc kết thúc</label>
                                        <div className="relative group">
                                            <CalendarRange className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-indigo-500 transition-transform" />
                                            <input type="date" value={exportEndDate} onChange={(e) => setExportEndDate(e.target.value)} className="w-full pl-11 pr-4 py-3.5 bg-white border-2 border-gray-100 rounded-2xl text-xs font-black focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 text-gray-900 shadow-sm transition-all"/>
                                        </div>
                                    </div>
                                </div>

                                <button 
                                    onClick={() => handleExportExcel('personal')}
                                    className="w-full py-4 bg-gradient-to-r from-blue-600 to-indigo-700 hover:from-blue-700 hover:to-indigo-800 text-white font-black rounded-3xl shadow-xl shadow-blue-200 transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-xs active:scale-95 group"
                                >
                                    <FileDown className="w-5 h-5 group-hover:animate-bounce" />
                                    Tải báo cáo Excel
                                </button>

                                <p className="text-[9px] text-gray-400 font-medium italic text-center px-4">
                                    * File Excel tự động chia Tab theo từng ngày làm việc.
                                </p>
                            </div>
                        </Card>
                    </div>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-5 rounded-2xl border border-gray-100 shadow-sm gap-4">
                        <h3 className="text-lg font-black text-gray-800 flex items-center gap-2"><PieChartIcon className="w-5 h-5 text-indigo-600" /> {isAdmin ? 'Quản trị & Điều phối' : 'Bảng xếp hạng'}</h3>

                        {isAdmin && (
                            <div className="flex flex-wrap items-center gap-3">
                                <button onClick={() => handleExportToday('all')} className="bg-white hover:bg-emerald-50 text-emerald-600 border-2 border-emerald-100 px-4 py-2 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 transition-all shadow-sm">
                                    <Zap className="w-4 h-4" /> Xuất Hôm Nay
                                </button>
                                <div className="flex items-center gap-2 bg-gray-50 p-2 rounded-xl border border-gray-100">
                                    <input type="date" value={exportStartDate} onChange={(e) => setExportStartDate(e.target.value)} className="bg-transparent border-none text-[10px] font-bold focus:ring-0 p-0"/>
                                    <span className="text-gray-400 text-[10px] font-black">→</span>
                                    <input type="date" value={exportEndDate} onChange={(e) => setExportEndDate(e.target.value)} className="bg-transparent border-none text-[10px] font-bold focus:ring-0 p-0"/>
                                </div>
                                <button onClick={() => handleExportExcel('all')} className="bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg shadow-emerald-100 transition-all active:scale-95">
                                    <FileSpreadsheet className="w-4 h-4" /> Xuất Theo Khoảng Ngày
                                </button>
                            </div>
                        )}
                    </div>
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        <Card title="🏆 BẢNG VÀNG CHIẾN THẦN OT" className="lg:col-span-1 rounded-[2.5rem] shadow-2xl border-none bg-white overflow-hidden flex flex-col">
                            <div className="p-6 bg-gradient-to-r from-indigo-600 to-blue-700 text-white">
                                <p className="text-[10px] font-black uppercase tracking-widest opacity-80">Bảng xếp hạng tháng {currentDate.getMonth()+1}</p>
                                <h4 className="text-xl font-black italic">TOP 5 STARS</h4>
                            </div>
                            <div className="flex-1 space-y-4 p-5">
                                {top5.length === 0 ? <div className="flex flex-col items-center justify-center h-full py-20 text-gray-400 italic"><Trophy className="w-12 h-12 mb-2 opacity-20" /> Chưa có đơn duyệt tháng này</div> : 
                                top5.map((emp, idx) => (
                                    <div key={idx} className={`p-4 rounded-[1.5rem] border-2 transition-all hover:scale-[1.02] ${idx === 0 ? 'bg-amber-50 border-amber-200' : idx === 1 ? 'bg-slate-50 border-slate-200' : idx === 2 ? 'bg-orange-50 border-orange-200' : 'bg-white border-gray-100 shadow-sm'}`}>
                                        <div className="flex items-center gap-4">
                                            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg shadow-inner ${idx === 0 ? 'bg-gradient-to-br from-yellow-400 to-amber-600 text-white' : idx === 1 ? 'bg-gradient-to-br from-slate-300 to-slate-500 text-white' : idx === 2 ? 'bg-gradient-to-br from-orange-300 to-orange-500 text-white' : 'bg-indigo-50 text-indigo-400'}`}>
                                                {idx < 3 ? (idx === 0 ? <Medal className="w-7 h-7" /> : <Trophy className="w-6 h-6" />) : (idx + 1)}
                                            </div>
                                            <div className="flex-1">
                                                <div className="flex justify-between items-start">
                                                    <div><h4 className="font-black text-gray-900 text-sm leading-tight">{emp.name}</h4><p className="text-[10px] font-black text-indigo-500 tracking-tighter uppercase">{emp.employee_id} • {emp.count} ngày làm</p></div>
                                                    <div className="text-right"><span className="text-xl font-black text-indigo-600 tabular-nums">{emp.hours.toFixed(1)}</span><span className="text-[10px] font-black text-gray-400 ml-0.5 uppercase">h</span></div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </Card>
                        <Card title="📈 Mật độ OT toàn nhân viên" className="lg:col-span-2 rounded-[2rem] shadow-2xl border-none">
                            <div className="h-[400px]">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={adminTrend}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <Tooltip cursor={{fill: '#f8fafc', radius: 10}} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                                        <Bar dataKey="count" fill="#4f46e5" radius={[6, 6, 0, 0]} name="Số người" barSize={16} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
