                                <>
                                    {isAdmin && (
                                        <div className="space-y-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1 tracking-widest">Nhân viên thực hiện:</label><div className="relative"><UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-400 w-5 h-5" /><select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full pl-12 pr-4 py-4 bg-white border-2 border-gray-100 rounded-3xl text-sm font-black focus:ring-4 focus:ring-indigo-500/10 text-gray-900 shadow-sm appearance-none transition-all outline-none"><option value="" disabled>-- Chọn nhân viên --</option>{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}</select><ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 w-4 h-4 pointer-events-none" /></div></div>
                                    )}

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="bg-white p-5 rounded-[2rem] border-2 border-gray-100 shadow-sm group focus-within:border-indigo-500 transition-all">
                                            <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 tracking-widest">Bắt đầu</label>
                                            <div className="flex items-center gap-3"><Clock className="w-5 h-5 text-indigo-500" /><input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 cursor-pointer"/></div>
                                        </div>
                                        <div className="bg-white p-5 rounded-[2rem] border-2 border-gray-100 shadow-sm group focus-within:border-rose-500 transition-all">
                                            <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 tracking-widest">Kết thúc</label>
                                            <div className="flex items-center gap-3"><Clock className="w-5 h-5 text-rose-500" /><input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 cursor-pointer"/></div>
                                        </div>
                                    </div>

                                    <div className="relative p-6 bg-gradient-to-r from-indigo-600 to-indigo-800 rounded-[2.5rem] shadow-xl text-white flex justify-between items-center group overflow-hidden">
                                        <div className="absolute top-0 right-0 p-10 opacity-5 rotate-45 translate-x-1/2 -translate-y-1/2"><Star className="w-24 h-24" /></div>
                                        <div className="relative z-10">
                                            <p className="text-[10px] font-black text-indigo-100 uppercase tracking-widest leading-none mb-1">Tổng giờ thực nhận</p>
                                            <p className="text-[9px] text-indigo-200/50 font-medium italic">*Tự động trừ 0.5-1h nghỉ</p>
                                        </div>
                                        <div className="text-right relative z-10">
                                            <span className="text-5xl font-black tracking-tighter tabular-nums drop-shadow-lg">{calculatedHours}</span>
                                            <span className="text-lg font-black ml-1 text-indigo-300">h</span>
                                        </div>
                                    </div>

                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center px-1">
                                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung</label>
                                            <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="text-[10px] font-black text-indigo-600 flex items-center gap-1.5 active:scale-95 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
                                                {isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>}
                                                AI Smart
                                            </button>
                                        </div>
                                        <textarea required value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-5 bg-white border-2 border-gray-100 rounded-[2rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 text-sm h-32 resize-none text-gray-900 shadow-sm transition-all placeholder:text-gray-300 font-medium outline-none" placeholder="Ví dụ: Hoàn thiện báo cáo quý 4, xử lý công cụ tồn kho..."/>
                                    </div>

                                    <div className="flex gap-4 pt-4 sticky bottom-0 bg-gray-50/50 -mx-6 px-6 pb-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} disabled={isDeleting} className="p-5 bg-white text-rose-500 border-2 border-rose-100 rounded-3xl hover:bg-rose-50 active:scale-90 shadow-sm transition-all"><Trash2 className="w-6 h-6"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0 || !targetUserId} className="flex-1 py-5 bg-gradient-to-r from-indigo-600 to-indigo-800 hover:from-indigo-700 hover:to-indigo-900 text-white font-black rounded-3xl shadow-xl shadow-indigo-100 transition-all disabled:opacity-50 flex items-center justify-center gap-3 uppercase tracking-[0.2em] text-[11px] active:scale-95">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5"/>} 
                                            {editingRequestId ? 'LƯU THAY ĐỔI' : 'GỬI ĐĂNG KÝ'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in"><div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in border border-gray-200"><div className="p-10 text-center"><div className="w-20 h-20 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-[2.5rem] shadow-xl shadow-rose-100 rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-10 h-10"/></div><h3 className="text-2xl font-black text-gray-900 mb-3 uppercase tracking-tight leading-none">HỦY ĐƠN?</h3><p className="text-[11px] text-gray-500 font-bold italic px-4 leading-relaxed uppercase opacity-70">Thao tác này sẽ xóa dữ liệu OT vĩnh viễn.</p></div><div className="p-6 bg-gray-50 flex flex-col gap-3 border-t border-gray-100"><button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl text-[11px] uppercase shadow-xl shadow-rose-100 active:scale-95 flex items-center justify-center gap-2">{isDeleting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4"/>} XÁC NHẬN HỦY</button><button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 text-[11px] uppercase active:scale-95 transition-all">ĐÓNG</button></div></div></div>
        )}
    </div>
  );
};
const PlusCircle = ({className}: {className?: string}) => <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const currentMonthStr = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const sortedAndFilteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    // Sắp xếp ưu tiên: Chờ duyệt (0) -> Đang mượn (1) -> Đã trả (2) -> Từ chối (3)
    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = {
            'pending': 0,
            'approved': 1,
            'returned': 2,
            'rejected': 3
        };
        if (statusOrder[a.status] !== statusOrder[b.status]) {
            return statusOrder[a.status] - statusOrder[b.status];
        }
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      showToast(`Đã duyệt thành công cho ${req.user_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang xử lý...', 'info');
    setProcessingId(req.id);
    try {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang nhận lại đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id);
        showToast('Đã xác nhận trả thiết bị.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy đơn...', 'info');
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu thành công.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-100 text-amber-700 border-amber-200 ring-amber-400/30';
      case 'approved': 
        return 'bg-emerald-100 text-emerald-700 border-emerald-200 ring-emerald-400/30';
      case 'returned': 
        return 'bg-blue-100 text-blue-700 border-blue-200 ring-blue-400/30';
      case 'rejected': 
        return 'bg-rose-100 text-rose-700 border-rose-200 ring-rose-400/30';
      default: 
        return 'bg-gray-100 text-gray-700 border-gray-200 ring-gray-400/30';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-3.5 h-3.5" />;
      case 'approved': return <Bookmark className="w-3.5 h-3.5" />;
      case 'returned': return <RotateCcw className="w-3.5 h-3.5" />;
      case 'rejected': return <Ban className="w-3.5 h-3.5" />;
      default: return <Info className="w-3.5 h-3.5" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'Đang Chờ';
      case 'approved': return 'Đang Mượn';
      case 'returned': return 'Đã Trả';
      case 'rejected': return 'Từ Chối';
      default: return 'Không xác định';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in max-w-[1400px] mx-auto px-4 md:px-0">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-3xl shadow-lg shadow-blue-200">
                <Wrench className="w-7 h-7 text-white" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Đơn Mượn</h2>
                <p className="text-sm text-gray-500 font-bold uppercase tracking-wider opacity-70">Theo dõi & Phê duyệt thiết bị</p>
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-100 p-1.5 rounded-2xl shadow-inner self-start">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-black transition-all ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    HỆ THỐNG
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-black transition-all ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    CỦA TÔI
                </button>
            </div>
        )}
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500 transition-colors" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-12 pr-4 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-0 text-gray-900 font-bold transition-all"
            />
        </div>

        <div className="relative group">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-5 pr-10 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-0 appearance-none cursor-pointer text-gray-900 font-bold transition-all"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang mượn</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <Filter className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500" />
        </div>

        <div className="relative group">
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-12 pr-4 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-0 text-gray-900 font-bold transition-all"
            />
            <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500" />
        </div>
      </div>

      <Card className="p-0 rounded-[2.5rem] shadow-xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-8 py-6 text-gray-400 font-black uppercase tracking-widest text-[10px]">Người mượn</th>
                <th className="px-8 py-6 text-gray-400 font-black uppercase tracking-widest text-[10px]">Thông tin thiết bị</th>
                <th className="px-8 py-6 text-gray-400 font-black uppercase tracking-widest text-[10px]">Thời gian</th>
                <th className="px-8 py-6 text-gray-400 font-black uppercase tracking-widest text-[10px]">Trạng thái</th>
                <th className="px-8 py-6 text-gray-400 font-black uppercase tracking-widest text-[10px] text-right">Hành động</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-10 h-10 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : sortedAndFilteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-32 text-center text-gray-400 font-bold italic opacity-60">
                    <History className="w-16 h-16 mx-auto mb-4 opacity-10" />
                    Không tìm thấy dữ liệu yêu cầu nào.
                  </td>
                </tr>
              ) : (
                sortedAndFilteredRequests.map((req) => {
                  const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
                  const isOldBorrowed = req.status === 'approved' && reqDateStr !== filterStartDate;

                  return (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/30 transition-all duration-300 group ${req.status === 'pending' ? 'bg-amber-50/10' : ''}`}
                  >
                    <td className="px-8 py-6 align-middle">
                        <div className="flex items-center gap-4">
                            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black shadow-sm transition-transform group-hover:scale-110 ${
                                req.user_id === user.id ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white' : 'bg-white text-gray-500 border-2 border-gray-100'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-black text-gray-900 text-sm flex items-center gap-2">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[9px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-lg font-black border border-blue-200">TÔI</span>}
                                </div>
                                <div className="text-[11px] text-gray-400 font-black tracking-tighter mt-1 flex items-center gap-1.5 uppercase opacity-70">
                                    <UserIcon className="w-3 h-3" />
                                    {req.employee_id}
                                </div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle">
                        <div className="flex items-center gap-4">
                            <div className="w-16 h-16 bg-white rounded-2xl border-2 border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-200 transition-colors shadow-sm">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-7 h-7 text-gray-100" />}
                            </div>
                            <span className="font-black text-gray-800 text-sm leading-tight max-w-[150px]">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle">
                        <div className="flex flex-col gap-1.5">
                            <div className={`flex items-center gap-2 font-black text-xs ${isOldBorrowed ? 'text-emerald-600' : 'text-gray-900'}`}>
                                <Calendar className="w-3.5 h-3.5 opacity-40" />
                                {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                                {isOldBorrowed && (
                                    <span className="bg-emerald-100 text-emerald-700 text-[8px] px-1.5 py-0.5 rounded uppercase font-black ml-1 border border-emerald-200">
                                        TỒN
                                    </span>
                                )}
                            </div>
                            <div className="flex items-center gap-2 text-[11px] text-gray-400 font-bold uppercase tracking-tighter">
                                <Clock className="w-3.5 h-3.5 opacity-40" />
                                {new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle">
                        <div className={`inline-flex items-center gap-2.5 px-4 py-2 rounded-2xl text-[10px] font-black border uppercase tracking-[0.1em] ring-4 transition-all shadow-sm ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle text-right">
                      <div className="flex justify-end gap-3 items-center">
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                            <>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })}
                                    className="w-11 h-11 flex items-center justify-center bg-emerald-600 text-white rounded-2xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-200 active:scale-90" 
                                    title="Phê duyệt"
                                >
                                    <Check className="w-5 h-5" />
                                </button>
                                <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })}
                                    className="w-11 h-11 flex items-center justify-center bg-white text-rose-600 border-2 border-rose-50 rounded-2xl hover:bg-rose-50 transition-all shadow-sm active:scale-90" 
                                    title="Từ chối"
                                >
                                    <X className="w-5 h-5" />
                                </button>
                            </>
                        )}

                        {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                            <button
                                onClick={() => setConfirmAction({ type: 'return', req })}
                                className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all text-[11px] font-black shadow-xl shadow-blue-200 active:scale-95 uppercase tracking-widest"
                            >
                                <RotateCcw className="w-4 h-4" /> 
                                THU HỒI
                            </button>
                        )}

                        {req.user_id === user.id && req.status === 'pending' && (
                            <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                className="flex items-center gap-2 text-rose-600 hover:text-white hover:bg-rose-600 border-2 border-rose-100 px-6 py-3 rounded-2xl text-[11px] font-black transition-all shadow-sm active:scale-95 uppercase tracking-widest"
                            >
                                <Trash2 className="w-4 h-4" />
                                HỦY ĐƠN
                            </button>
                        )}

                        {req.status === 'returned' && (
                           <div className="w-11 h-11 flex items-center justify-center text-emerald-500 bg-emerald-50 rounded-full border-2 border-emerald-100 shadow-inner" title="Hoàn tất">
                              <CheckCircle2 className="w-6 h-6" />
                           </div>
                        )}

                        {req.status === 'rejected' && (
                           <div className="w-11 h-11 flex items-center justify-center text-rose-500 bg-rose-50 rounded-full border-2 border-rose-100 shadow-inner" title="Đã từ chối">
                              <Ban className="w-6 h-6" />
                           </div>
                        )}
                      </div>
                    </td>
                  </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/70 z-[100] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className={`w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl transform rotate-6 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-12 h-12" /> : <AlertTriangle className="w-12 h-12" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-tight">Xác nhận thao tác?</h3>
              <p className="text-[13px] text-gray-500 font-bold leading-relaxed px-2 uppercase opacity-60">
                {confirmAction.type === 'approve' ? 'Duyệt mượn thiết bị và trừ tồn kho thực tế.' : 
                 confirmAction.type === 'return' ? 'Xác nhận thiết bị đã về kho an toàn.' :
                 confirmAction.type === 'reject' ? 'Từ chối yêu cầu và đóng đơn này.' :
                 'Xóa bỏ vĩnh viễn yêu cầu này khỏi hệ thống.'}
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex flex-col gap-3 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction}
                className={`w-full py-4.5 text-white font-black rounded-2xl text-[11px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)}
                className="w-full py-4.5 bg-white text-gray-400 font-black rounded-2xl border-2 border-gray-100 hover:bg-gray-100 text-[11px] uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                ĐÓNG LẠI
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const sortedAndFilteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    // Ưu tiên: pending (0) -> approved (1) -> returned (2) -> rejected (3)
    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = {
            'pending': 0,
            'approved': 1,
            'returned': 2,
            'rejected': 3
        };
        if (statusOrder[a.status] !== statusOrder[b.status]) {
            return statusOrder[a.status] - statusOrder[b.status];
        }
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const executeApprove = async (req: BorrowRequest) => {
    showToast(`Đang duyệt đơn: ${req.tool_name}...`, 'info');
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      showToast(`Đã duyệt thành công cho ${req.user_name}`, 'success');
      await fetchRequests();
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    showToast('Đang xử lý...', 'info');
    setProcessingId(req.id);
    try {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        showToast('Đã từ chối yêu cầu.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    showToast('Đang nhận lại đồ...', 'info');
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;
        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', req.id);
        showToast('Đã xác nhận trả thiết bị.', 'success');
        await fetchRequests();
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    showToast('Đang hủy đơn...', 'info');
    setProcessingId(id);
    const { error } = await supabase.from('requests').delete().eq('id', id);
    if (error) showToast("Lỗi: " + error.message, 'error');
    else {
        showToast("Đã hủy yêu cầu thành công.", 'success');
        await fetchRequests();
    }
    setProcessingId(null);
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50';
      case 'approved': 
        return 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50';
      case 'returned': 
        return 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50';
      case 'rejected': 
        return 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50';
      default: 
        return 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'Đang Chờ Duyệt';
      case 'approved': return 'Đang Mượn';
      case 'returned': return 'Đã Trả';
      case 'rejected': return 'Đã Từ Chối';
      default: return 'Không xác định';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in w-full">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {/* Header Section */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-3xl shadow-lg shadow-blue-100">
                <Wrench className="w-7 h-7 text-white" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Đơn Mượn</h2>
                <p className="text-sm text-gray-400 font-black uppercase tracking-[0.15em] opacity-80">Theo dõi & Phê duyệt thiết bị</p>
            </div>
        </div>

        {user.role === 'admin' && (
            <div className="flex bg-gray-100 p-1.5 rounded-2xl shadow-inner border border-gray-200">
                <button
                    onClick={() => setActiveTab('all')}
                    className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${
                        activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <ShieldCheck className="w-4 h-4" />
                    HỆ THỐNG
                </button>
                <button
                    onClick={() => setActiveTab('personal')}
                    className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${
                        activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <UserIcon className="w-4 h-4" />
                    CỦA TÔI
                </button>
            </div>
        )}
      </div>

      {/* Filter Section */}
      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500 transition-colors" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-12 pr-4 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all placeholder:text-gray-400"
            />
        </div>

        <div className="relative group">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-5 pr-10 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 appearance-none cursor-pointer text-gray-900 font-bold transition-all"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang mượn</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500" />
        </div>

        <div className="relative group">
            <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500 transition-colors" />
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-12 pr-4 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all"
            />
        </div>
      </div>

      {/* Table Section */}
      <Card className="p-0 rounded-[2.5rem] shadow-xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/80 border-b border-gray-100">
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[250px]">Người mượn</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[200px]">Thiết bị</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[150px]">Thời gian</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[180px] text-center">Trạng thái</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] text-right min-w-[200px]">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-30" /></td></tr>
              ) : sortedAndFilteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-32 text-center text-gray-400 font-bold italic opacity-60">
                    <div className="flex flex-col items-center">
                        <History className="w-16 h-16 mb-4 opacity-10" />
                        Không tìm thấy dữ liệu yêu cầu nào.
                    </div>
                  </td>
                </tr>
              ) : (
                sortedAndFilteredRequests.map((req) => {
                  const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
                  const isOldBorrowed = req.status === 'approved' && reqDateStr !== filterStartDate;

                  return (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/20 transition-all duration-300 group ${req.status === 'pending' ? 'bg-amber-50/10' : ''}`}
                  >
                    <td className="px-8 py-6 align-middle">
                        <div className="flex items-center gap-4">
