                                <h3 className="font-black text-gray-800 uppercase text-xs tracking-widest flex items-center gap-2"><Activity className="w-4 h-4 text-blue-600" /> Xu hướng tháng {currentDate.getMonth()+1}</h3>
                            </div>
                            <div className="h-64 md:h-80 w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={myStats.trend} margin={{ top: 0, right: 0, left: -30, bottom: 0 }}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                        <Tooltip 
                                            cursor={{fill: '#f8fafc', radius: 8}} 
                                            contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}}
                                        />
                                        <Bar dataKey="hours" fill="#4f46e5" radius={[6, 6, 0, 0]} barSize={12} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>

                        <Card className="lg:col-span-1 rounded-[2.5rem] shadow-xl border-none bg-white flex flex-col overflow-hidden">
                            <div className="p-6 bg-gradient-to-br from-indigo-600 to-blue-800 text-white">
                                <div className="flex items-center gap-3">
                                    <div className="p-3 bg-white/20 rounded-2xl backdrop-blur-md shadow-inner"><FileSpreadsheet className="w-6 h-6" /></div>
                                    <h3 className="font-black uppercase text-sm tracking-widest leading-tight">Xuất báo cáo<br/><span className="text-[10px] opacity-70">Cá nhân</span></h3>
                                </div>
