                                    >
                                        <FileDown className="w-5 h-5 group-hover:animate-bounce" />
                                        Tải Báo Cáo Khoảng Ngày
                                    </button>
                                </div>
                                <p className="text-[9px] text-gray-400 font-medium italic text-center px-4 leading-relaxed">
                                    * File Excel tự động phân chia Tab chi tiết cho từng ngày.
                                </p>
                            </div>
                        </Card>
                    </div>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm gap-4">
                        <h3 className="text-sm font-black text-gray-800 flex items-center gap-2 uppercase tracking-widest"><PieChartIcon className="w-5 h-5 text-indigo-600" /> {isAdmin ? 'Quản trị hệ thống' : 'Bảng vàng vinh danh'}</h3>

                        {isAdmin && (
                            <div className="flex flex-wrap items-center gap-2 w-full md:w-auto">
                                <button onClick={() => handleExportToday('all')} className="flex-1 md:flex-none bg-white hover:bg-emerald-50 text-emerald-600 border-2 border-emerald-100 px-4 py-2.5 rounded-xl text-[10px] font-black uppercase flex items-center justify-center gap-2 transition-all">
                                    <Zap className="w-4 h-4" /> Xuất Hôm Nay
                                </button>
                                <button onClick={() => handleExportExcel('all')} className="flex-1 md:flex-none bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-indigo-100 transition-all active:scale-95">
                                    <FileSpreadsheet className="w-4 h-4" /> Xuất Theo Kỳ
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        <Card className="lg:col-span-1 rounded-[2.5rem] shadow-2xl border-none bg-white overflow-hidden flex flex-col">
                            <div className="p-6 bg-gradient-to-r from-blue-700 to-indigo-800 text-white">
                                <p className="text-[9px] font-black uppercase tracking-widest opacity-80 mb-1">Xếp hạng tháng {currentDate.getMonth()+1}</p>
                                <h4 className="text-xl font-black italic tracking-tighter">TOP CHIẾN THẦN OT</h4>
                            </div>
                            <div className="flex-1 space-y-4 p-5 overflow-y-auto max-h-[500px] custom-scrollbar">
                                {top5.length === 0 ? (
