            <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md animate-zoom-in overflow-hidden my-auto border border-white/20">
                    {/* MODAL HEADER */}
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white relative">
                        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none"><Clock className="w-32 h-32" /></div>
                        <div className="relative z-10">
                            <div className="flex items-center gap-2"><CalendarDays className="w-4 h-4 text-indigo-200" /><h3 className="text-xl font-black uppercase tracking-tighter leading-none">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <div className="flex flex-wrap items-center gap-2 mt-2">
                                {isAdmin && new Date(selectedDateStr).getDay() === 6 && (
                                    <button onClick={toggleSaturdayStatus} disabled={isConfigUpdating} className="flex items-center gap-1.5 px-3 py-1 bg-white/20 rounded-full text-[9px] font-black uppercase hover:bg-white/30 transition-all border border-white/10">
                                        {isConfigUpdating ? <Loader2 className="w-3 h-3 animate-spin"/> : (dayConfigs[selectedDateStr] ?? true) ? <ToggleRight className="w-4 h-4"/> : <ToggleLeft className="w-4 h-4"/>}
                                        {(dayConfigs[selectedDateStr] ?? true) ? 'T7 Làm' : 'T7 Nghỉ'}
                                    </button>
                                )}
                                {new Date(selectedDateStr).getDay() === 0 && <span className="text-[9px] font-black uppercase bg-rose-500/40 px-3 py-1 rounded-full border border-white/10 flex items-center gap-1"><AlertCircle className="w-3.5 h-3.5"/> Chủ Nhật</span>}
                            </div>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-white/20 rounded-2xl transition-all shadow-lg backdrop-blur-md border border-white/10 active:scale-90"><X className="w-6 h-6"/></button>
                    </div>

                    <div className="p-6 space-y-6 bg-gray-50/50 max-h-[70vh] overflow-y-auto no-scrollbar">
                        {/* OPTIMIZED COLLEAGUE LIST */}
                        {dayRequests.length > 0 && (
                            <div className="space-y-3 bg-white/40 p-4 rounded-[2rem] border border-gray-100 shadow-sm">
                                <div className="flex justify-between items-center">
                                    <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                        <Users className="w-3.5 h-3.5"/> 
                                        Đồng nghiệp ({dayRequests.length})
                                    </div>
                                    <button 
                                        onClick={() => setShowColleagueDetails(!showColleagueDetails)}
                                        className="text-[10px] font-black text-blue-600 flex items-center gap-1 hover:underline transition-all"
                                    >
                                        {showColleagueDetails ? <><ChevronUp className="w-3 h-3"/> Thu gọn</> : <><ChevronDown className="w-3 h-3"/> Xem chi tiết</>}
                                    </button>
                                </div>

                                {showColleagueDetails ? (
                                    <div className="flex flex-wrap gap-2 animate-fade-in-up">
                                        {dayRequests.map(req => (
                                            <button key={req.id} onClick={() => setTargetUserId(req.user_id)} className={`flex items-center gap-2 px-3 py-2 rounded-2xl border-2 transition-all relative ${targetUserId === req.user_id ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg scale-105' : 'bg-white border-gray-100 text-gray-600 active:scale-95'}`}>
                                                <div className={`w-7 h-7 rounded-xl flex items-center justify-center font-black text-[11px] shadow-inner ${targetUserId === req.user_id ? 'bg-white text-indigo-600' : 'bg-indigo-50 text-indigo-700'}`}>{req.users?.name?.charAt(0)}</div>
                                                <span className="text-[10px] font-black tracking-tighter truncate max-w-[80px]">{req.users?.name}</span>
                                                {targetUserId === req.user_id && <Check className="w-3 h-3 absolute -top-1 -right-1 bg-white text-indigo-600 rounded-full border border-indigo-600" />}
                                            </button>
                                        ))}
                                        {isAdmin && <button onClick={() => { setTargetUserId(''); setEditingRequestId(null); setReason(''); }} className="flex items-center gap-2 px-3 py-2 rounded-2xl border-2 border-dashed border-gray-300 text-gray-400 active:scale-95 font-black text-[10px] bg-white/50">Thêm người</button>}
                                    </div>
                                ) : (
                                    <div className="flex items-center gap-3">
                                        <div className="flex -space-x-2 overflow-hidden">
                                            {dayRequests.slice(0, 5).map((req, idx) => (
                                                <div key={idx} className="w-8 h-8 rounded-xl bg-indigo-50 border-2 border-white flex items-center justify-center font-black text-[10px] text-indigo-600 shadow-sm">
                                                    {req.users?.name?.charAt(0)}
                                                </div>
                                            ))}
                                            {dayRequests.length > 5 && (
                                                <div className="w-8 h-8 rounded-xl bg-gray-100 border-2 border-white flex items-center justify-center font-black text-[10px] text-gray-400">
                                                    +{dayRequests.length - 5}
                                                </div>
                                            )}
                                        </div>
                                        {isAdmin && (
                                            <button 
                                                onClick={() => { setTargetUserId(''); setEditingRequestId(null); setReason(''); setShowColleagueDetails(true); }} 
                                                className="w-8 h-8 rounded-xl border-2 border-dashed border-gray-200 flex items-center justify-center text-gray-300 hover:text-indigo-500 hover:border-indigo-300 transition-colors"
                                            >
                                                <PlusCircle className="w-4 h-4"/>
                                            </button>
                                        )}
                                    </div>
                                )}
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border border-amber-200 p-6 rounded-[2.5rem] text-center space-y-4 shadow-xl shadow-amber-900/5 animate-fade-in relative overflow-hidden">
                                    <div className="absolute top-0 left-0 w-full h-1 bg-amber-400/40"></div>
                                    <Eye className="w-12 h-12 text-amber-500 mx-auto" />
                                    <div><h4 className="font-black text-amber-900 uppercase text-xs tracking-widest">Đơn của đồng nghiệp</h4><div className="mt-4 grid grid-cols-2 gap-3"><div className="bg-white/80 p-4 rounded-3xl border border-amber-200 shadow-sm text-center"><p className="text-[9px] font-black text-amber-400 uppercase mb-1">Thời gian</p><p className="text-xs font-black text-amber-800">{startTime} - {endTime}</p></div><div className="bg-white/80 p-4 rounded-3xl border border-amber-200 shadow-sm text-center"><p className="text-[9px] font-black text-amber-400 uppercase mb-1">Tổng cộng</p><p className="text-sm font-black text-amber-800">{calculatedHours}h</p></div></div><div className="mt-4 p-4 bg-white/60 rounded-3xl text-left border border-amber-200/50 italic text-[12px] text-amber-700 leading-relaxed shadow-inner">"{reason || 'Nội dung đang để trống'}"</div></div>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-4 bg-indigo-600 text-white text-[11px] font-black uppercase rounded-3xl shadow-xl shadow-indigo-200 active:scale-95 transition-all flex items-center justify-center gap-2 tracking-widest"><MousePointer2 className="w-4 h-4" /> Đăng ký của tôi</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1 tracking-widest">Nhân viên thực hiện:</label><div className="relative"><UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-400 w-5 h-5" /><select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full pl-12 pr-4 py-4 bg-white border-2 border-gray-100 rounded-3xl text-sm font-black focus:ring-4 focus:ring-indigo-500/10 text-gray-900 shadow-sm appearance-none transition-all outline-none"><option value="" disabled>-- Chọn nhân viên --</option>{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}</select><ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 w-4 h-4 pointer-events-none" /></div></div>
                                    )}

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="bg-white p-5 rounded-[2rem] border-2 border-gray-100 shadow-sm group focus-within:border-indigo-500 transition-all">
                                            <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 tracking-widest">Bắt đầu</label>
                                            <div className="flex items-center gap-3"><Clock className="w-5 h-5 text-indigo-500" /><input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 cursor-pointer"/></div>
                                        </div>
                                        <div className="bg-white p-5 rounded-[2rem] border-2 border-gray-100 shadow-sm group focus-within:border-rose-500 transition-all">
                                            <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 tracking-widest">Kết thúc</label>
                                            <div className="flex items-center gap-3"><Clock className="w-5 h-5 text-rose-500" /><input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 cursor-pointer"/></div>
                                        </div>
                                    </div>

                                    <div className="relative p-6 bg-gradient-to-r from-indigo-600 to-indigo-800 rounded-[2.5rem] shadow-xl text-white flex justify-between items-center group overflow-hidden">
                                        <div className="absolute top-0 right-0 p-10 opacity-5 rotate-45 translate-x-1/2 -translate-y-1/2"><Star className="w-24 h-24" /></div>
                                        <div className="relative z-10">
                                            <p className="text-[10px] font-black text-indigo-100 uppercase tracking-widest leading-none mb-1">Tổng giờ thực nhận</p>
                                            <p className="text-[9px] text-indigo-200/50 font-medium italic">*Tự động trừ 0.5-1h nghỉ</p>
                                        </div>
                                        <div className="text-right relative z-10">
                                            <span className="text-5xl font-black tracking-tighter tabular-nums drop-shadow-lg">{calculatedHours}</span>
                                            <span className="text-lg font-black ml-1 text-indigo-300">h</span>
                                        </div>
                                    </div>

                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center px-1">
                                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung</label>
                                            <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="text-[10px] font-black text-indigo-600 flex items-center gap-1.5 active:scale-95 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
                                                {isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>}
                                                AI Smart
                                            </button>
                                        </div>
                                        <textarea required value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-5 bg-white border-2 border-gray-100 rounded-[2rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 text-sm h-32 resize-none text-gray-900 shadow-sm transition-all placeholder:text-gray-300 font-medium outline-none" placeholder="Ví dụ: Hoàn thiện báo cáo quý 4, xử lý công cụ tồn kho..."/>
                                    </div>

                                    <div className="flex gap-4 pt-4 sticky bottom-0 bg-gray-50/50 -mx-6 px-6 pb-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} disabled={isDeleting} className="p-5 bg-white text-rose-500 border-2 border-rose-100 rounded-3xl hover:bg-rose-50 active:scale-90 shadow-sm transition-all"><Trash2 className="w-6 h-6"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0 || !targetUserId} className="flex-1 py-5 bg-gradient-to-r from-indigo-600 to-indigo-800 hover:from-indigo-700 hover:to-indigo-900 text-white font-black rounded-3xl shadow-xl shadow-indigo-100 transition-all disabled:opacity-50 flex items-center justify-center gap-3 uppercase tracking-[0.2em] text-[11px] active:scale-95">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5"/>} 
                                            {editingRequestId ? 'LƯU THAY ĐỔI' : 'GỬI ĐĂNG KÝ'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in"><div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in border border-gray-200"><div className="p-10 text-center"><div className="w-20 h-20 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-[2.5rem] shadow-xl shadow-rose-100 rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-10 h-10"/></div><h3 className="text-2xl font-black text-gray-900 mb-3 uppercase tracking-tight leading-none">HỦY ĐƠN?</h3><p className="text-[11px] text-gray-500 font-bold italic px-4 leading-relaxed uppercase opacity-70">Thao tác này sẽ xóa dữ liệu OT vĩnh viễn.</p></div><div className="p-6 bg-gray-50 flex flex-col gap-3 border-t border-gray-100"><button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl text-[11px] uppercase shadow-xl shadow-rose-100 active:scale-95 flex items-center justify-center gap-2">{isDeleting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4"/>} XÁC NHẬN HỦY</button><button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 text-[11px] uppercase active:scale-95 transition-all">ĐÓNG</button></div></div></div>
        )}
    </div>
  );
};
const PlusCircle = ({className}: {className?: string}) => <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const currentMonthStr = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus, Share2, ToggleLeft, ToggleRight, Eye, MousePointer2, CalendarRange, FileDown, ArrowRight, Zap, List, ChevronDown, ChevronUp
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('20:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            if (isWorkDay) {
                setStartTime('14:30');
            } else {
                setStartTime('08:00');
            }
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const toggleSaturdayStatus = async () => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    const currentStatus = dayConfigs[selectedDateStr] ?? true;
    const newStatus = !currentStatus;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: newStatus });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: newStatus }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng thời gian này.");

    filtered.sort((a, b) => a.date.localeCompare(b.date));
    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    const summaryData = filtered.map(req => {
        const d = new Date(req.date);
        return {
            'Ngày': req.date,
            'Thứ': dayNames[d.getDay()],
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        };
    });
    const summarySheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'TỔNG HỢP');

    const groupedByDate: Record<string, OvertimeRequest[]> = {};
    filtered.forEach(req => {
        if (!groupedByDate[req.date]) groupedByDate[req.date] = [];
        groupedByDate[req.date].push(req);
    });

    Object.keys(groupedByDate).forEach(dateKey => {
        const dayRequests = groupedByDate[dateKey];
        const dateObj = new Date(dateKey);
        const dayLabel = dayNames[dateObj.getDay()];
        const sheetData = dayRequests.map(req => ({
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        }));
        const worksheet = XLSX.utils.json_to_sheet(sheetData);
        const tabName = dateKey.split('-').reverse().slice(0, 2).join('-');
        XLSX.utils.book_append_sheet(workbook, worksheet, `${tabName} (${dayLabel})`);
    });

    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'personal' ? 'Ca_nhan' : 'Toan_bo'}_${start}_den_${end}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => {
      const today = new Date().toISOString().split('T')[0];
      handleExportExcel(mode, { start: today, end: today });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
