                            <div className="w-2.5 h-2.5 md:w-6 md:h-6 rounded-full md:rounded-lg bg-emerald-500 shadow-sm border border-white flex items-center justify-center flex-shrink-0 ring-1 ring-emerald-200">
                                <UserIcon className="w-1.5 h-1.5 md:w-3.5 md:h-3.5 text-white" />
                            </div>
