            <div className="w-full md:w-auto">
                <div className="flex items-center gap-2">
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight">Tăng ca</h2>
                    <span className="text-[10px] font-bold bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full uppercase">Tool V2</span>
                </div>
                <p className="text-xs md:text-sm text-gray-500 font-medium italic mt-0.5">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
            </div>

            <div className="flex w-full md:w-auto bg-gray-100/80 p-1 rounded-2xl border border-gray-200 overflow-x-auto no-scrollbar">
                <button onClick={() => setActiveTab('calendar')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-6 py-2 rounded-xl text-xs md:text-sm font-black transition-all whitespace-nowrap ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md transform scale-105' : 'text-gray-500'}`}>
                    <CalendarIcon className="w-3.5 h-3.5" /> Lịch
                </button>
                <button onClick={() => setActiveTab('personal')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-6 py-2 rounded-xl text-xs md:text-sm font-black transition-all whitespace-nowrap ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md transform scale-105' : 'text-gray-500'}`}>
                    <UserIcon className="w-3.5 h-3.5" /> Cá nhân
                </button>
                <button onClick={() => setActiveTab('stats')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-6 py-2 rounded-xl text-xs md:text-sm font-black transition-all whitespace-nowrap ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500'}`}>
                    <BarChart3 className="w-3.5 h-3.5" /> {isAdmin ? 'Quản trị' : 'Bảng điểm'}
                </button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-200 shadow-2xl rounded-[2.5rem] bg-white">
                    <div className="flex items-center justify-between p-4 md:p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2.5 md:p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronLeft className="w-5 h-5"/></button>
                        <h3 className="text-sm md:text-lg font-black uppercase tracking-[0.2em] text-gray-800">T{currentDate.getMonth()+1} - {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2.5 md:p-3 hover:bg-gray-100 rounded-2xl transition-all"><ChevronRight className="w-5 h-5"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-3 md:py-4 text-center ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>)}
