                <span className="text-xs text-gray-500 font-medium">
                    Hiển thị {currentLogs.length} trên tổng {filteredLogs.length} kết quả
                </span>

                {totalPages > 1 && (
                    <div className="flex items-center gap-2">
                        <button 
                            onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                            disabled={currentPage === 1}
                            className="p-2 rounded-lg border border-gray-300 bg-white disabled:opacity-30 hover:bg-gray-50 text-gray-600 transition-all shadow-sm"
                        >
                            <ChevronLeft className="w-4 h-4" />
                        </button>

                        <div className="flex items-center gap-1">
                            {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                                // Logic đơn giản hiển thị tối đa 5 trang đầu
                                const pageNum = i + 1;
                                return (
                                    <button
                                        key={pageNum}
                                        onClick={() => setCurrentPage(pageNum)}
                                        className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                            currentPage === pageNum 
                                            ? 'bg-blue-600 text-white shadow-md' 
                                            : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
                                        }`}
                                    >
                                        {pageNum}
                                    </button>
                                );
                            })}
                            {totalPages > 5 && <span className="text-gray-400 px-1">...</span>}
                        </div>

                        <button 
                            onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
                            disabled={currentPage === totalPages}
                            className="p-2 rounded-lg border border-gray-300 bg-white disabled:opacity-30 hover:bg-gray-50 text-gray-600 transition-all shadow-sm"
                        >
                            <ChevronRight className="w-4 h-4" />
                        </button>
                    </div>
                )}

                <span className="text-[10px] text-gray-400 font-medium">
                    Cập nhật: {new Date().toLocaleTimeString('vi-VN')}
                </span>
            </div>
       </Card>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
