interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ITEMS_PER_PAGE = 20;

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full ${className} transition-colors`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2 text-gray-300' : 'w-5 h-5 text-gray-400'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'} ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);

  // --- FILTER STATES ---
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  // --- ADMIN & MODE STATE ---
  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  // --- CART / SELECTION STATE ---
  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // --- CRUD STATE ---
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory, filterStatus]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
    if (error) console.error(error);
  };

  // --- FILTER LOGIC ---
  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  // --- PAGINATION ---
  const totalPages = Math.ceil(filteredTools.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentTools = filteredTools.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) setCurrentPage(newPage);
  };

  // --- SELECTION & QUANTITY LOGIC ---
  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); 
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const toggleSelectAll = () => {
    const selectableTools = currentTools.filter(isSelectable);
    const selectableIds = selectableTools.map(t => t.id);
    const allSelected = selectableIds.every(id => selectedToolIds.has(id));

    const newSet = new Set(selectedToolIds);
    const newQties = {...quantities};

    if (allSelected) {
        selectableIds.forEach(id => {
            newSet.delete(id);
            delete newQties[id];
        });
    } else {
        selectableIds.forEach(id => {
            newSet.add(id);
            if (!newQties[id]) newQties[id] = 1;
        });
    }
    setSelectedToolIds(newSet);
    setQuantities(newQties);
  };

  const handleRowClick = (tool: Tool) => {
      if (isManageMode) return; 
      if (isSelectable(tool)) {
          toggleSelection(tool.id);
      }
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
    const requests: any[] = [];

    toolsToBorrow.forEach(tool => {
        const qty = quantities[tool.id] || 1;
        for(let i = 0; i < qty; i++) {
            requests.push({
                employee_id: user.employeeCode,
                user_id: user.id,
                user_name: user.name,
                tool_id: tool.id,
                tool_name: tool.name,
                borrow_date: new Date().toISOString(),
                status: 'pending'
            });
        }
    });

    const { error } = await supabase.from('requests').insert(requests);

    if (!error) {
        setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
        setSelectedToolIds(new Set()); 
        setQuantities({});
        setTimeout(() => setMessage(null), 4000);
    } else {
        alert('Có lỗi xảy ra: ' + error.message);
    }
    setIsBulkProcessing(false);
  };

  // --- CRUD ACTIONS ---
  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const confirmDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete);
      if (error) throw error;
      const newTools = tools.filter(t => t.id !== toolToDelete);
      setTools(newTools);
      if (currentPage > Math.ceil(newTools.length / ITEMS_PER_PAGE)) {
        setCurrentPage(Math.max(1, currentPage - 1));
      }
      setMessage('Đã xóa công cụ thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    } finally {
        setToolToDelete(null);
    }
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32">
      {/* HEADER CONTROLS */}
      <div className="flex flex-col gap-4 bg-white p-5 rounded-3xl shadow-sm border border-gray-100 transition-all">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div>
                <h2 className="text-2xl font-black text-gray-900 flex items-center gap-3 tracking-tight">
                    Kho công cụ
                    {!isAdmin && <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-widest border border-indigo-100">Chế độ Mượn</span>}
                </h2>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1 opacity-70">Quản lý & Theo dõi tài sản</p>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && (
                <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100 whitespace-nowrap">
                    <CheckCircle className="w-5 h-5" />
                    {message}
                </div>
                )}

                {isAdmin && (
                    <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <Settings2 className="w-4 h-4" />
                            QUẢN LÝ
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <ShoppingBag className="w-4 h-4" />
                            MƯỢN ĐỒ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
                >
                    <LayoutGrid className="w-5 h-5" />
                </button>
                <button 
                    onClick={() => setViewMode('table')}
                    className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
                >
                    <List className="w-5 h-5" />
                </button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-2xl flex items-center gap-2 text-sm font-black transition-all shadow-xl shadow-indigo-100 w-full sm:w-auto justify-center whitespace-nowrap active:scale-95 uppercase tracking-widest"
                    >
                        <Plus className="w-5 h-5" />
                        THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        {/* --- FILTER TOOLBAR --- */}
        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500 transition-colors" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-12 pr-4 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 transition-all text-gray-900 placeholder:text-gray-400"
                />
            </div>

            <div className="flex gap-3 w-full md:w-auto">
                <div className="relative flex-1 sm:min-w-[180px] group">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-5 pr-10 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-gray-900 transition-all"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                        ))}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>

                <div className="relative flex-1 sm:min-w-[180px] group">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-5 pr-10 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-gray-900 transition-all"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Bảo trì</option>
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>

                {(searchTerm || filterCategory !== 'all' || filterStatus !== 'all') && (
                    <button 
                        onClick={() => { setSearchTerm(''); setFilterCategory('all'); setFilterStatus('all'); }}
                        className="px-4 py-3.5 text-rose-500 hover:bg-rose-50 rounded-2xl text-xs font-black transition-all flex items-center gap-2 whitespace-nowrap uppercase tracking-widest active:scale-95"
                    >
                        <X className="w-4 h-4" /> Xóa lọc
                    </button>
                )}
            </div>
        </div>
      </div>

      <div className="flex-1">
        {/* === GRID VIEW === */}
        {viewMode === 'grid' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.length === 0 ? (
                <div className="col-span-full py-32 text-center text-gray-300 flex flex-col items-center">
                    <div className="p-8 bg-gray-50 rounded-[3rem] mb-6">
                        <Wrench className="w-16 h-16 opacity-20" />
                    </div>
                    <p className="text-xl font-black uppercase tracking-widest opacity-40 italic">Không tìm thấy công cụ nào</p>
                </div>
            ) : (
            currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all relative overflow-hidden group flex flex-col h-full p-0 border-2 ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-500/5 transform scale-[1.02]' : 'border-transparent bg-white shadow-lg'}`}>
                    {/* Image */}
                    <div className="h-56 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />

                      {/* Select Checkbox */}
                      {!isManageMode && selectable && (
                          <div className="absolute top-4 left-4 z-20" onClick={(e) => e.stopPropagation()}>
                               <input 
                                    type="checkbox"
                                    checked={isSelected}
                                    onChange={() => toggleSelection(tool.id)}
                                    className="w-6 h-6 rounded-lg border-gray-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer shadow-xl bg-white accent-indigo-600"
                               />
                          </div>
                      )}

                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        {tool.status === 'inactive' ? (
                          <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg shadow-rose-200 tracking-widest">Bảo trì</span>
                        ) : tool.available > 0 ? (
                          <span className="bg-emerald-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg shadow-emerald-200 tracking-widest">
                            Sẵn có: {tool.available}
                          </span>
                        ) : (
                          <span className="bg-gray-400 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg shadow-gray-200 tracking-widest">Hết hàng</span>
                        )}
                      </div>
                    </div>

                    <div className="p-6 flex-1 flex flex-col bg-white">
                      <div className="mb-4">
                        <h3 className="font-black text-gray-900 text-lg line-clamp-2 min-h-[3.5rem] leading-tight tracking-tight" title={tool.name}>{tool.name}</h3>
                        <div className="flex items-center gap-2 mt-2">
                            <span className="text-[10px] font-black uppercase tracking-tighter text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md">{tool.category}</span>
                            <div className="flex items-center gap-1 text-[10px] text-gray-400 font-bold uppercase tracking-tighter">
                                <MapPin className="w-3 h-3 opacity-50" />
                                {tool.location || 'N/A'}
                            </div>
                        </div>
                      </div>

                      <div className="mt-auto">
                        {isManageMode ? (
                          <div className="flex gap-3 pt-4 border-t border-gray-50">
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-white hover:bg-indigo-50 text-indigo-700 border-2 border-indigo-100 py-3 rounded-2xl text-xs font-black transition-all flex items-center justify-center gap-2 uppercase tracking-widest active:scale-95">
                                <Edit className="w-4 h-4" /> Sửa
                             </button>
                             <button onClick={() => setToolToDelete(tool.id)} className="p-3 bg-white hover:bg-rose-50 text-rose-600 border-2 border-rose-100 rounded-2xl transition-all active:scale-90">
                                <Trash2 className="w-5 h-5" />
                             </button>
                          </div>
                        ) : (
                          // BORROW ACTIONS - HIGH PROMINENCE
                          isSelected ? (
                              <div className="flex items-center justify-between bg-indigo-600 rounded-2xl p-1.5 shadow-xl shadow-indigo-200 animate-fade-in-up border-2 border-indigo-500">
                                  <button 
                                    onClick={(e) => { e.preventDefault(); changeQuantity(tool.id, -1, tool.available); }}
                                    className="w-11 h-11 flex items-center justify-center bg-indigo-500/50 hover:bg-white/20 rounded-xl text-white transition-all active:scale-90"
                                  >
                                      <Minus className="w-5 h-5" />
                                  </button>
                                  <div className="flex flex-col items-center">
                                      <span className="text-[10px] font-black uppercase text-indigo-200 tracking-widest leading-none mb-1">Số lượng</span>
                                      <span className="font-black text-white text-xl tabular-nums leading-none">{qty}</span>
                                  </div>
                                  <button 
                                    onClick={(e) => { e.preventDefault(); changeQuantity(tool.id, 1, tool.available); }}
                                    className="w-11 h-11 flex items-center justify-center bg-white text-indigo-600 rounded-xl shadow-lg hover:bg-gray-50 transition-all active:scale-90 disabled:opacity-50 disabled:bg-gray-200"
                                    disabled={qty >= Number(tool.available)}
                                  >
                                      <Plus className="w-5 h-5" />
                                  </button>
                              </div>
                          ) : (
                              <button
                                onClick={() => toggleSelection(tool.id)}
                                disabled={tool.available === 0 || tool.status === 'inactive'}
                                className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-4 rounded-2xl text-sm font-black transition-all disabled:opacity-50 disabled:bg-gray-100 disabled:text-gray-400 flex items-center justify-center gap-3 shadow-xl shadow-indigo-100 active:scale-95 uppercase tracking-[0.15em] group"
                              >
                                <PackagePlus className="w-5 h-5 group-hover:animate-bounce" />
                                CHỌN MƯỢN
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            }))}
            </div>
        )}

        {/* === TABLE VIEW === */}
        {viewMode === 'table' && (
          <Card className="p-0 rounded-[2rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="px-8 py-6 w-10">
                        {!isManageMode && (
                            <input 
                                type="checkbox"
                                checked={currentTools.length > 0 && currentTools.some(isSelectable) && currentTools.filter(isSelectable).every(t => selectedToolIds.has(t.id))}
                                onChange={toggleSelectAll}
                                className="w-5 h-5 rounded-md border-gray-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer bg-white accent-indigo-600"
                                disabled={!currentTools.some(isSelectable)}
                            />
                        )}
                    </th>
                    <th className="px-8 py-6 w-24 text-[10px] font-black uppercase tracking-widest text-gray-400 bg-gray-50">Hình</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400 bg-gray-50">Tên thiết bị</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400 bg-gray-50">Danh mục</th>
                    <th className="px-8 py-6 text-center text-[10px] font-black uppercase tracking-widest text-gray-400 bg-gray-50">Kho/Sẵn</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400 bg-gray-50">Vị trí</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400 bg-gray-50">Trạng thái</th>
                    <th className="px-8 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400 bg-gray-50 min-w-[200px]">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.length === 0 ? (
                      <tr>
                        <td colSpan={8} className="py-24 text-center text-gray-400 italic font-bold">
                            Không tìm thấy công cụ phù hợp
                        </td>
                      </tr>
                  ) : (
                  currentTools.map((tool) => {
                      const selectable = isSelectable(tool);
                      const isSelected = selectedToolIds.has(tool.id);
                      const qty = quantities[tool.id] || 1;

                      return (
                      <tr 
                          key={tool.id} 
                          onClick={() => handleRowClick(tool)}
                          className={`transition-all duration-300 cursor-pointer group ${isSelected ? 'bg-indigo-50/50' : 'hover:bg-blue-50/30'}`}
                      >
                        <td className="px-8 py-6" onClick={(e) => e.stopPropagation()}>
                            {!isManageMode && selectable && (
                                <input 
                                    type="checkbox"
                                    checked={isSelected}
                                    onChange={() => toggleSelection(tool.id)}
                                    className="w-5 h-5 rounded-md border-gray-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer bg-white accent-indigo-600 shadow-sm"
                                />
                            )}
                        </td>
                        <td className="px-8 py-6">
                            <div className="w-14 h-14 rounded-2xl bg-white border-2 border-gray-100 overflow-hidden flex items-center justify-center p-2 shadow-sm group-hover:border-indigo-200 transition-colors">
                                <ToolThumbnail src={tool.image} alt={tool.name} mode="table" />
                            </div>
                        </td>
                        <td className="px-8 py-6">
                            <div className="font-black text-gray-900 leading-tight group-hover:text-indigo-700 transition-colors">{tool.name}</div>
                        </td>
                        <td className="px-8 py-6 text-xs font-bold text-gray-500">{tool.category}</td>
                        <td className="px-8 py-6 text-center">
                            <div className="flex flex-col items-center">
                                <span className="text-[10px] font-black text-gray-400 mb-1 leading-none uppercase">{tool.quantity}</span>
                                <span className={`text-sm font-black px-3 py-1 rounded-xl shadow-inner ${tool.available > 0 ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 'bg-gray-100 text-gray-400 border border-gray-200'}`}>
                                    {tool.available}
                                </span>
                            </div>
                        </td>
                        <td className="px-8 py-6 text-xs font-bold text-gray-500">{tool.location || '-'}</td>
                        <td className="px-8 py-6">
                          {tool.status === 'active' 
                            ? <span className="text-emerald-700 text-[9px] font-black uppercase bg-emerald-50 border border-emerald-100 px-3 py-1 rounded-full tracking-widest shadow-sm">Hoạt động</span> 
                            : <span className="text-rose-700 text-[9px] font-black uppercase bg-rose-50 border border-rose-100 px-3 py-1 rounded-full tracking-widest shadow-sm">Bảo trì</span>}
                        </td>
                        <td className="px-8 py-6 text-right" onClick={(e) => e.stopPropagation()}>
                            {isManageMode ? (
                                <div className="flex justify-end gap-3">
