                        </td>
                        <td className="px-8 py-6 text-right" onClick={(e) => e.stopPropagation()}>
                            {isManageMode ? (
                                <div className="flex justify-end gap-3">
                                    <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-white bg-gray-50 border-2 border-transparent hover:border-indigo-100 rounded-2xl transition-all"><Edit className="w-5 h-5" /></button>
                                    <button onClick={() => setToolToDelete(tool.id)} className="p-3 text-rose-600 hover:bg-white bg-gray-50 border-2 border-transparent hover:border-rose-100 rounded-2xl transition-all"><Trash2 className="w-5 h-5" /></button>
                                </div>
