                                <div className="flex justify-end">
                                    {isSelected ? (
                                        <div className="flex items-center gap-2 bg-indigo-600 border-2 border-indigo-500 rounded-2xl shadow-xl shadow-indigo-100 p-1 animate-fade-in-up">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); changeQuantity(tool.id, -1, tool.available); }}
                                                className="w-10 h-10 flex items-center justify-center rounded-xl bg-white/10 hover:bg-white/20 text-white transition-all active:scale-90"
                                            >
                                                <Minus className="w-4 h-4" />
                                            </button>
                                            <span className="w-8 text-center font-black text-white text-lg tabular-nums select-none leading-none">{qty}</span>
