import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
      showToast("Lỗi tải dữ liệu", "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const sortedAndFilteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = {
            'pending': 0,
            'approved': 1,
            'returned': 2,
            'rejected': 3
        };
        if (statusOrder[a.status] !== statusOrder[b.status]) {
            return statusOrder[a.status] - statusOrder[b.status];
        }
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  // Cập nhật state cục bộ để giao diện phản hồi nhanh
  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => 
      req.id === id ? { ...req, status: newStatus as any, ...extraData } : req
    ));
  };

  const executeApprove = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      // Thực thi các lệnh DB
      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      const { error } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      if (error) throw error;

      // Cập nhật giao diện ngay lập tức mà không fetch lại
      updateLocalRequestStatus(req.id, 'approved');
      showToast(`Đã duyệt cho ${req.user_name}`, 'success');
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
        const { error } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        if (error) throw error;

        updateLocalRequestStatus(req.id, 'rejected');
        showToast('Đã từ chối yêu cầu.', 'success');
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;

        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const now = new Date().toISOString();
        const { error } = await supabase.from('requests').update({ 
            status: 'returned', 
            returned_at: now 
        }).eq('id', req.id);

        if (error) throw error;

        updateLocalRequestStatus(req.id, 'returned', { returned_at: now });
        showToast('Đã xác nhận trả thiết bị.', 'success');
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    setProcessingId(id);
    try {
        const { error } = await supabase.from('requests').delete().eq('id', id);
        if (error) throw error;

        // Xóa khỏi danh sách hiện tại ngay lập tức
        setRequests(prev => prev.filter(r => r.id !== id));
        showToast("Đã hủy yêu cầu thành công.", 'success');
    } catch (error: any) {
        showToast("Lỗi: " + error.message, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50';
      case 'approved': 
        return 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50';
      case 'returned': 
        return 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50';
      case 'rejected': 
        return 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50';
      default: 
        return 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'Đang Chờ Duyệt';
      case 'approved': return 'Đang Mượn';
      case 'returned': return 'Đã Trả';
      case 'rejected': return 'Đã Từ Chối';
      default: return 'Không xác định';
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in w-full pb-10">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {/* Header Section */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-3xl shadow-lg shadow-blue-100">
                <Wrench className="w-7 h-7 text-white" />
            </div>
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Đơn Mượn</h2>
                <p className="text-sm text-gray-400 font-black uppercase tracking-[0.15em] opacity-80">Theo dõi & Phê duyệt thiết bị</p>
            </div>
        </div>

        <div className="flex flex-wrap items-center gap-4">
            <button 
                onClick={() => fetchRequests(true)}
                disabled={isRefreshing}
                className="p-3 bg-gray-50 hover:bg-gray-100 text-gray-500 rounded-2xl border border-gray-200 transition-all active:scale-95"
                title="Làm mới dữ liệu"
            >
                <RefreshCw className={`w-5 h-5 ${isRefreshing ? 'animate-spin text-blue-600' : ''}`} />
            </button>

            {user.role === 'admin' && (
                <div className="flex bg-gray-100 p-1.5 rounded-2xl shadow-inner border border-gray-200">
                    <button
                        onClick={() => setActiveTab('all')}
                        className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${
                            activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                        }`}
                    >
                        <ShieldCheck className="w-4 h-4" />
                        HỆ THỐNG
                    </button>
                    <button
                        onClick={() => setActiveTab('personal')}
                        className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${
                            activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                        }`}
                    >
                        <UserIcon className="w-4 h-4" />
                        CỦA TÔI
                    </button>
                </div>
            )}
        </div>
      </div>

      {/* Filter Section */}
      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="relative group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500 transition-colors" />
            <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm nhân viên, thiết bị..."
                className="w-full pl-12 pr-4 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all placeholder:text-gray-400 outline-none"
            />
        </div>

        <div className="relative group">
            <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full pl-5 pr-10 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 appearance-none cursor-pointer text-gray-900 font-bold transition-all outline-none"
            >
                <option value="all">Tất cả trạng thái</option>
                <option value="pending">⏳ Chờ phê duyệt</option>
                <option value="approved">✅ Đang mượn</option>
                <option value="returned">↩️ Đã hoàn trả</option>
                <option value="rejected">❌ Đã từ chối</option>
            </select>
            <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500" />
        </div>

        <div className="relative group">
            <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500 transition-colors" />
            <input 
                type="date"
                value={filterStartDate}
                onChange={(e) => setFilterStartDate(e.target.value)}
                className="w-full pl-12 pr-4 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all outline-none"
            />
        </div>
      </div>

      {/* Table Section */}
      <Card className="p-0 rounded-[2.5rem] shadow-xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead className="sticky top-0 z-10 bg-white">
              <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[250px] bg-gray-50">Người mượn</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[200px] bg-gray-50">Thiết bị</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[150px] bg-gray-50">Thời gian</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[180px] text-center bg-gray-50">Trạng thái</th>
                <th className="px-8 py-6 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] text-right min-w-[200px] bg-gray-50">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-30" /></td></tr>
              ) : sortedAndFilteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-32 text-center text-gray-400 font-bold italic opacity-60">
                    <div className="flex flex-col items-center">
                        <History className="w-16 h-16 mb-4 opacity-10" />
                        Không tìm thấy dữ liệu yêu cầu nào.
                    </div>
                  </td>
                </tr>
              ) : (
                sortedAndFilteredRequests.map((req) => {
                  const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
                  const isOldBorrowed = req.status === 'approved' && reqDateStr !== filterStartDate;
                  const isProcessing = processingId === req.id;

                  return (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/20 transition-all duration-300 group ${req.status === 'pending' ? 'bg-amber-50/10' : ''} ${isProcessing ? 'opacity-50 pointer-events-none' : ''}`}
                  >
                    <td className="px-8 py-6 align-middle">
                        <div className="flex items-center gap-4">
                            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black shadow-sm border-2 transition-transform group-hover:scale-110 ${
                                req.user_id === user.id ? 'bg-gradient-to-br from-blue-500 to-indigo-700 text-white border-blue-400' : 'bg-white text-gray-400 border-gray-100'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-black text-gray-900 text-sm flex items-center gap-2">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[9px] bg-blue-600 text-white px-2 py-0.5 rounded-lg font-black uppercase tracking-tighter">TÔI</span>}
                                </div>
                                <div className="text-[11px] text-gray-400 font-bold tracking-tighter mt-1 flex items-center gap-1.5 uppercase">
                                    <UserIcon className="w-3 h-3" />
                                    {req.employee_id}
                                </div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle">
                        <div className="flex items-center gap-4">
                            <div className="w-16 h-16 bg-white rounded-2xl border-2 border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-300 transition-colors shadow-sm">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-7 h-7 text-gray-100" />}
                            </div>
                            <span className="font-black text-gray-800 text-sm leading-tight max-w-[150px]">{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle">
                        <div className="flex flex-col gap-1.5">
                            <div className={`flex items-center gap-2 font-black text-xs ${isOldBorrowed ? 'text-emerald-600' : 'text-gray-900'}`}>
                                <Calendar className="w-3.5 h-3.5 opacity-40" />
                                {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                                {isOldBorrowed && (
                                    <span className="bg-emerald-100 text-emerald-700 text-[8px] px-1.5 py-0.5 rounded uppercase font-black ml-1 border border-emerald-200">
                                        TỒN
                                    </span>
                                )}
                            </div>
                            <div className="flex items-center gap-2 text-[10px] text-gray-400 font-black uppercase tracking-tighter">
                                <Clock className="w-3.5 h-3.5 opacity-40" />
                                {new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle text-center">
                        <div className={`inline-flex items-center gap-2.5 px-5 py-2.5 rounded-2xl text-[10px] font-black border-2 uppercase tracking-widest shadow-lg transform group-hover:scale-105 transition-all ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-6 align-middle text-right">
                      <div className="flex justify-end gap-3 items-center">
                        {isProcessing ? (
                            <div className="w-12 h-12 flex items-center justify-center">
                                <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                            </div>
                        ) : (
                            <>
                                {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            className="w-12 h-12 flex items-center justify-center bg-emerald-600 text-white rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-200 active:scale-90" 
                                            title="Phê duyệt"
                                        >
                                            <Check className="w-6 h-6" />
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            className="w-12 h-12 flex items-center justify-center bg-white text-rose-600 border-2 border-rose-100 rounded-2xl hover:bg-rose-50 transition-all shadow-sm active:scale-90" 
                                            title="Từ chối"
                                        >
                                            <X className="w-6 h-6" />
                                        </button>
                                    </>
                                )}

                                {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all text-[11px] font-black shadow-2xl shadow-blue-200 active:scale-95 uppercase tracking-[0.15em]"
                                    >
                                        <RotateCcw className="w-4 h-4" /> 
                                        THU HỒI
                                    </button>
                                )}

                                {req.user_id === user.id && req.status === 'pending' && (
                                    <button 
                                        onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                        className="flex items-center gap-2 text-rose-600 hover:text-white hover:bg-rose-600 border-2 border-rose-100 px-6 py-3.5 rounded-2xl text-[11px] font-black transition-all shadow-sm active:scale-95 uppercase tracking-[0.15em]"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                        HỦY ĐƠN
                                    </button>
                                )}

                                {req.status === 'returned' && (
                                <div className="w-12 h-12 flex items-center justify-center text-emerald-500 bg-emerald-50 rounded-full border-2 border-emerald-100 shadow-inner" title="Hoàn tất">
                                    <CheckCircle2 className="w-7 h-7" />
                                </div>
                                )}

                                {req.status === 'rejected' && (
                                <div className="w-12 h-12 flex items-center justify-center text-rose-500 bg-rose-50 rounded-full border-2 border-rose-100 shadow-inner" title="Đã từ chối">
                                    <Ban className="w-7 h-7" />
                                </div>
                                )}
                            </>
                        )}
                      </div>
                    </td>
                  </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/80 z-[100] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl transform rotate-6 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-12 h-12" /> : <AlertTriangle className="w-12 h-12" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-tight">Xác nhận?</h3>
              <p className="text-[12px] text-gray-400 font-bold leading-relaxed px-4 uppercase tracking-widest opacity-80">
                {confirmAction.type === 'approve' ? 'Duyệt mượn thiết bị và trừ tồn kho thực tế.' : 
                 confirmAction.type === 'return' ? 'Xác nhận thiết bị đã về kho an toàn.' :
                 confirmAction.type === 'reject' ? 'Từ chối yêu cầu và đóng đơn này.' :
                 'Xóa bỏ vĩnh viễn yêu cầu này khỏi hệ thống.'}
              </p>
            </div>
            <div className="bg-gray-50 p-8 flex flex-col gap-3 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction}
                className={`w-full py-5 text-white font-black rounded-[1.5rem] text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)}
                className="w-full py-5 bg-white text-gray-400 font-black rounded-[1.5rem] border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>('all');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
      showToast("Lỗi tải dữ liệu", "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const sortedAndFilteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = {
            'pending': 0,
            'approved': 1,
            'returned': 2,
            'rejected': 3
        };
        if (statusOrder[a.status] !== statusOrder[b.status]) {
            return statusOrder[a.status] - statusOrder[b.status];
        }
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => 
      req.id === id ? { ...req, status: newStatus as any, ...extraData } : req
    ));
  };

  const executeApprove = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      const { error } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      if (error) throw error;

      updateLocalRequestStatus(req.id, 'approved');
      showToast(`Đã duyệt cho ${req.user_name}`, 'success');
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
        const { error } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        if (error) throw error;

        updateLocalRequestStatus(req.id, 'rejected');
        showToast('Đã từ chối yêu cầu.', 'success');
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;

        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const now = new Date().toISOString();
        const { error } = await supabase.from('requests').update({ 
            status: 'returned', 
            returned_at: now 
        }).eq('id', req.id);

        if (error) throw error;

        updateLocalRequestStatus(req.id, 'returned', { returned_at: now });
        showToast('Đã xác nhận trả thiết bị.', 'success');
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    setProcessingId(id);
    try {
        const { error } = await supabase.from('requests').delete().eq('id', id);
        if (error) throw error;

        setRequests(prev => prev.filter(r => r.id !== id));
        showToast("Đã hủy yêu cầu thành công.", 'success');
    } catch (error: any) {
        showToast("Lỗi: " + error.message, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50';
      case 'approved': 
        return 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50';
      case 'returned': 
        return 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50';
      case 'rejected': 
        return 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50';
      default: 
        return 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'Đang Chờ Duyệt';
      case 'approved': return 'Đang Mượn';
      case 'returned': return 'Đã Trả';
      case 'rejected': return 'Đã Từ Chối';
      default: return 'Không xác định';
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 lg:px-0 space-y-6 animate-fade-in w-full pb-10">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {/* Header & Tabs Section - Sticky on desktop */}
      <div className="sticky top-0 lg:top-[64px] z-30 space-y-4 pt-4 pb-2 bg-gray-50/95 backdrop-blur-sm">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-5 rounded-[2rem] shadow-sm border border-gray-100">
          <div className="flex items-center gap-4">
              <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-100 flex-shrink-0">
                  <Wrench className="w-6 h-6 text-white" />
              </div>
              <div>
                  <h2 className="text-xl font-black text-gray-900 tracking-tight leading-none">Quản lý Đơn Mượn</h2>
                  <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.15em] opacity-80 mt-1">Phê duyệt & Theo dõi kho</p>
              </div>
          </div>

          <div className="flex flex-wrap items-center gap-3">
              <button 
                  onClick={() => fetchRequests(true)}
                  disabled={isRefreshing}
                  className="p-3 bg-gray-50 hover:bg-gray-100 text-gray-500 rounded-2xl border border-gray-200 transition-all active:scale-95"
                  title="Làm mới dữ liệu"
              >
                  <RefreshCw className={`w-5 h-5 ${isRefreshing ? 'animate-spin text-blue-600' : ''}`} />
              </button>

              {user.role === 'admin' && (
                  <div className="flex bg-gray-100 p-1 rounded-2xl shadow-inner border border-gray-200">
                      <button
                          onClick={() => setActiveTab('all')}
                          className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${
                              activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                          }`}
                      >
                          <ShieldCheck className="w-3.5 h-3.5" />
                          HỆ THỐNG
                      </button>
                      <button
                          onClick={() => setActiveTab('personal')}
                          className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${
                              activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                          }`}
                      >
                          <UserIcon className="w-3.5 h-3.5" />
                          CỦA TÔI
                      </button>
                  </div>
              )}
          </div>
        </div>

        {/* Filter Bar - Sticky with Header */}
        <div className="bg-white p-4 rounded-[2rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="relative group">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500 transition-colors" />
              <input 
                  type="text" 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Tìm nhân viên, thiết bị..."
                  className="w-full pl-11 pr-4 py-3 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all placeholder:text-gray-400 outline-none"
              />
          </div>

          <div className="relative group">
              <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="w-full pl-5 pr-10 py-3 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 appearance-none cursor-pointer text-gray-900 font-bold transition-all outline-none"
              >
                  <option value="all">Tất cả trạng thái</option>
                  <option value="pending">⏳ Chờ phê duyệt</option>
                  <option value="approved">✅ Đang mượn</option>
                  <option value="returned">↩️ Đã hoàn trả</option>
                  <option value="rejected">❌ Đã từ chối</option>
