              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500" />
          </div>

          <div className="relative group">
              <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500 transition-colors" />
              <input 
                  type="date"
                  value={filterStartDate}
                  onChange={(e) => setFilterStartDate(e.target.value)}
                  className="w-full pl-11 pr-4 py-3 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all outline-none"
              />
          </div>
        </div>
      </div>

      {/* Table Section */}
      <Card className="p-0 rounded-[2.5rem] shadow-xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead className="sticky top-0 z-10 bg-white">
              <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[220px] bg-gray-50">Người mượn</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[180px] bg-gray-50">Thiết bị</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[140px] bg-gray-50">Thời gian</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[160px] text-center bg-gray-50">Trạng thái</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] text-right min-w-[180px] bg-gray-50">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-30" /></td></tr>
              ) : sortedAndFilteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-32 text-center text-gray-400 font-bold italic opacity-60">
                    <div className="flex flex-col items-center">
                        <History className="w-16 h-16 mb-4 opacity-10" />
                        Không tìm thấy dữ liệu yêu cầu nào.
                    </div>
                  </td>
                </tr>
              ) : (
                sortedAndFilteredRequests.map((req) => {
                  const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
                  const isOldBorrowed = req.status === 'approved' && reqDateStr !== filterStartDate;
                  const isProcessing = processingId === req.id;

                  return (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/20 transition-all duration-300 group ${req.status === 'pending' ? 'bg-amber-50/10' : ''} ${isProcessing ? 'opacity-50 pointer-events-none' : ''}`}
                  >
                    <td className="px-8 py-5 align-middle">
                        <div className="flex items-center gap-3">
                            <div className={`w-11 h-11 rounded-2xl flex items-center justify-center font-black shadow-sm border-2 transition-transform group-hover:scale-110 ${
                                req.user_id === user.id ? 'bg-gradient-to-br from-blue-500 to-indigo-700 text-white border-blue-400' : 'bg-white text-gray-400 border-gray-100'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-black text-gray-900 text-sm flex items-center gap-2">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[8px] bg-blue-600 text-white px-2 py-0.5 rounded-lg font-black uppercase tracking-tighter">TÔI</span>}
                                </div>
                                <div className="text-[10px] text-gray-400 font-bold tracking-tighter mt-0.5 flex items-center gap-1 uppercase">
                                    <UserIcon className="w-3 h-3" />
                                    {req.employee_id}
                                </div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle">
                        <div className="flex items-center gap-3">
                            <div className="w-14 h-14 bg-white rounded-2xl border-2 border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-300 transition-colors shadow-sm">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-100" />}
                            </div>
                            <span className="font-black text-gray-800 text-sm leading-tight max-w-[140px] truncate" title={req.tool_name}>{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle">
                        <div className="flex flex-col gap-1">
                            <div className={`flex items-center gap-1.5 font-black text-xs ${isOldBorrowed ? 'text-emerald-600' : 'text-gray-900'}`}>
                                <Calendar className="w-3 h-3 opacity-40" />
                                {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                                {isOldBorrowed && (
                                    <span className="bg-emerald-100 text-emerald-700 text-[8px] px-1.5 py-0.5 rounded uppercase font-black ml-1 border border-emerald-200">
                                        TỒN
                                    </span>
                                )}
                            </div>
                            <div className="flex items-center gap-1.5 text-[10px] text-gray-400 font-black uppercase tracking-tighter">
                                <Clock className="w-3 h-3 opacity-40" />
                                {new Date(req.borrow_date).toLocaleTimeString('vi-VN', { hour: '2-digit', minute:'2-digit'})}
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle text-center">
                        <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black border-2 uppercase tracking-widest shadow-lg transform group-hover:scale-105 transition-all ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle text-right">
                      <div className="flex justify-end gap-2.5 items-center">
                        {isProcessing ? (
                            <div className="w-10 h-10 flex items-center justify-center">
                                <Loader2 className="w-5 h-5 animate-spin text-blue-600" />
                            </div>
                        ) : (
                            <>
                                {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            className="w-11 h-11 flex items-center justify-center bg-emerald-600 text-white rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-200 active:scale-90" 
                                            title="Phê duyệt"
                                        >
                                            <Check className="w-5 h-5" />
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            className="w-11 h-11 flex items-center justify-center bg-white text-rose-600 border-2 border-rose-100 rounded-2xl hover:bg-rose-50 transition-all shadow-sm active:scale-90" 
                                            title="Từ chối"
                                        >
                                            <X className="w-5 h-5" />
                                        </button>
                                    </>
                                )}

                                {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        className="flex items-center gap-2 px-5 py-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all text-[10px] font-black shadow-2xl shadow-blue-200 active:scale-95 uppercase tracking-[0.15em]"
                                    >
                                        <RotateCcw className="w-3.5 h-3.5" /> 
                                        THU HỒI
                                    </button>
                                )}

                                {req.user_id === user.id && req.status === 'pending' && (
                                    <button 
                                        onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                        className="flex items-center gap-2 text-rose-600 hover:text-white hover:bg-rose-600 border-2 border-rose-100 px-5 py-3 rounded-2xl text-[10px] font-black transition-all shadow-sm active:scale-95 uppercase tracking-[0.15em]"
                                    >
                                        <Trash2 className="w-3.5 h-3.5" />
                                        HỦY ĐƠN
                                    </button>
                                )}

                                {req.status === 'returned' && (
                                <div className="w-10 h-10 flex items-center justify-center text-emerald-500 bg-emerald-50 rounded-full border-2 border-emerald-100 shadow-inner" title="Hoàn tất">
                                    <CheckCircle2 className="w-6 h-6" />
                                </div>
                                )}

                                {req.status === 'rejected' && (
                                <div className="w-10 h-10 flex items-center justify-center text-rose-500 bg-rose-50 rounded-full border-2 border-rose-100 shadow-inner" title="Đã từ chối">
                                    <Ban className="w-6 h-6" />
                                </div>
                                )}
                            </>
                        )}
                      </div>
                    </td>
                  </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/80 z-[100] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-10 text-center">
              <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-2xl transform rotate-6 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-10 h-10" /> : <AlertTriangle className="w-10 h-10" />}
              </div>
              <h3 className="text-xl font-black text-gray-900 mb-3 uppercase tracking-tighter leading-tight">Xác nhận?</h3>
              <p className="text-[10px] text-gray-400 font-bold leading-relaxed px-4 uppercase tracking-widest opacity-80">
                {confirmAction.type === 'approve' ? 'Duyệt mượn thiết bị và trừ tồn kho thực tế.' : 
                 confirmAction.type === 'return' ? 'Xác nhận thiết bị đã về kho an toàn.' :
                 confirmAction.type === 'reject' ? 'Từ chối yêu cầu và đóng đơn này.' :
                 'Xóa bỏ vĩnh viễn yêu cầu này khỏi hệ thống.'}
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex flex-col gap-3 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction}
                className={`w-full py-4 text-white font-black rounded-[1.2rem] text-[10px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)}
                className="w-full py-4 bg-white text-gray-400 font-black rounded-[1.2rem] border-2 border-gray-100 hover:bg-gray-100 text-[10px] uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

