                    className="w-full px-5 py-4 bg-gray-50 border-2 border-transparent rounded-2xl shadow-sm focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-sm font-bold text-gray-900 transition-all outline-none"
                    />
                </div>
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Vị trí lưu kho</label>
                <div className="relative group">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500" />
                    <input 
                    type="text" 
                    value={formData.location}
                    onChange={(e) => setFormData({...formData, location: e.target.value})}
                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-2 border-transparent rounded-2xl shadow-sm focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-sm font-bold text-gray-900 transition-all outline-none"
                    placeholder="Kệ A2, Kho 1..."
                    />
                </div>
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Link Ảnh (URL)</label>
                <div className="relative group">
                    <ImageIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500" />
                    <input 
                    type="text" 
                    value={formData.image}
                    onChange={(e) => setFormData({...formData, image: e.target.value})}
                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-2 border-transparent rounded-2xl shadow-sm focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-sm font-bold text-gray-900 transition-all outline-none"
                    placeholder="https://..."
                    />
                </div>
                {formData.image && (
                    <div className="mt-4 w-full h-40 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-200 flex items-center justify-center overflow-hidden p-4 group">
                        <img src={formData.image} alt="Preview" className="h-full object-contain transition-transform group-hover:scale-110 duration-500" onError={(e) => (e.currentTarget.style.display = 'none')} />
                    </div>
                )}
              </div>

              <div className="space-y-2">
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mô tả chi tiết</label>
                <textarea 
                  value={formData.description}
                  onChange={(e) => setFormData({...formData, description: e.target.value})}
                  className="w-full px-5 py-4 bg-gray-50 border-2 border-transparent rounded-2xl shadow-sm focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-sm font-bold h-32 resize-none text-gray-900 outline-none transition-all placeholder:text-gray-300"
                  placeholder="Thông tin thêm về thiết bị..."
                />
              </div>
            </div>

            <div className="p-8 border-t border-gray-100 bg-gray-50 flex justify-end gap-4 sticky bottom-0 rounded-b-[2.5rem]">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-6 py-4 text-xs font-black text-gray-400 uppercase tracking-widest bg-white border-2 border-gray-100 rounded-2xl hover:bg-gray-100 transition-all active:scale-95"
              >
                Hủy bỏ
              </button>
              <button 
                onClick={handleSaveTool}
                className="px-8 py-4 text-xs font-black text-white uppercase tracking-widest bg-indigo-600 rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all flex items-center gap-2 active:scale-95"
              >
                <Save className="w-5 h-5" />
                {isEditing ? 'LƯU THAY ĐỔI' : 'THÊM MỚI'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Delete */}
      {toolToDelete && (
        <div className="fixed inset-0 bg-black/80 z-[60] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-sm overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2.5rem] shadow-2xl shadow-rose-100 rotate-12 transition-transform hover:rotate-0">
                <AlertTriangle className="w-12 h-12" />
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xác nhận xóa?</h3>
              <p className="text-[12px] text-gray-400 font-bold italic px-4 leading-relaxed uppercase tracking-widest opacity-80">
                Hành động này sẽ xóa vĩnh viễn thiết bị khỏi hệ thống và không thể hoàn tác.
              </p>
            </div>
            <div className="bg-gray-50 p-8 flex flex-col gap-3 border-t border-gray-100">
              <button 
                onClick={confirmDeleteTool}
                className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl text-[11px] uppercase shadow-2xl shadow-rose-100 active:scale-95 flex items-center justify-center gap-3 tracking-widest"
              >
                <Trash2 className="w-5 h-5" />
                XÁC NHẬN XÓA
              </button>
              <button 
                onClick={() => setToolToDelete(null)}
                className="w-full py-5 bg-white text-gray-400 font-black rounded-2xl border-2 border-gray-100 hover:bg-gray-100 text-[11px] uppercase tracking-widest active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { History, Search, Calendar, Filter, X, User as UserIcon, ShieldCheck, ChevronDown, SlidersHorizontal, ChevronLeft, ChevronRight } from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | '7days' | '30days' | 'thisMonth';

const ITEMS_PER_PAGE = 20;

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  // State phân trang
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async () => {
    setLoading(true);
    let query = supabase
      .from('requests')
      .select('*')
      .order('borrow_date', { ascending: false });

    if (user.role !== 'admin') {
      query = query.eq('user_id', user.id);
    }

    if (statusFilter !== 'all') {
      query = query.eq('status', statusFilter);
    }

    if (startDate) {
      query = query.gte('borrow_date', `${startDate}T00:00:00`);
    }
    if (endDate) {
      query = query.lte('borrow_date', `${endDate}T23:59:59`);
    }

    const { data, error } = await query;
    if (data) {
      setLogs(data as ExtendedBorrowRequest[]);
    }
    if (error) console.error(error);
    setLoading(false);
  };

  useEffect(() => {
    fetchHistory();
  }, [user, startDate, endDate, statusFilter]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Admin';
    if (req.status === 'rejected') return req.rejected_by || 'Admin';
    return '-';
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.toLowerCase();
      const handlerLower = handlerFilter.toLowerCase();

      const matchesText = 
        log.user_name.toLowerCase().includes(searchLower) ||
        log.employee_id.toLowerCase().includes(searchLower) ||
        log.tool_name.toLowerCase().includes(searchLower);

      const currentHandler = getHandlerName(log).toLowerCase();
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);

      return matchesText && matchesHandler;
    });
  }, [logs, searchText, handlerFilter]);

  const totalPages = Math.ceil(filteredLogs.length / ITEMS_PER_PAGE);
  const currentLogs = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [filteredLogs, currentPage]);

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'today':
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'custom':
            return; 
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setHandlerFilter('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
  };

  const activeFiltersCount = [
    searchText, 
    handlerFilter, 
    startDate, 
    endDate, 
    statusFilter !== 'all'
  ].filter(Boolean).length;

  return (
    <div className="space-y-6">
       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-purple-100 rounded-lg text-purple-600">
                    <History className="w-6 h-6" />
                </div>
                <div>
                    <h2 className="text-2xl font-bold text-gray-800">Lịch sử hoạt động</h2>
                    <p className="text-sm text-gray-500">
                        {user.role === 'admin' ? 'Theo dõi toàn bộ lịch sử mượn trả của hệ thống' : 'Theo dõi lịch sử mượn trả của bạn'}
                    </p>
                </div>
            </div>
       </div>

       {/* STICKY FILTERS SECTION */}
       <div className="sticky top-[64px] z-30 pt-2 pb-4 bg-gray-50/95 backdrop-blur-sm -mx-4 px-4 md:-mx-8 md:px-8">
         <Card className="p-0 overflow-hidden border border-gray-200 shadow-md bg-white">
              <div className="p-5 space-y-5">
                  <div className="flex items-center justify-between">
                      <h3 className="text-sm font-bold text-gray-700 flex items-center gap-2 uppercase tracking-wide">
                          <SlidersHorizontal className="w-4 h-4" /> Bộ lọc tìm kiếm
                      </h3>
                      {activeFiltersCount > 0 && (
                          <button 
                              onClick={clearFilters}
                              className="text-xs text-red-600 hover:text-red-800 font-medium flex items-center gap-1 hover:underline"
                          >
                              <X className="w-3 h-3" /> Xóa {activeFiltersCount} bộ lọc
                          </button>
                      )}
                  </div>

                  <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                      <div className="lg:col-span-5 space-y-3 lg:border-r lg:border-gray-100 lg:pr-6">
                          <label className="block text-xs font-semibold text-gray-500">Khoảng thời gian</label>
                          <div className="flex flex-wrap gap-2 mb-3">
                               {[{id: 'today', l: 'Hôm nay'}, {id: '7days', l: '7 ngày'}, {id: '30days', l: '30 ngày'}, {id: 'thisMonth', l: 'Tháng này'}].map((btn) => (
                                  <button
                                      key={btn.id}
                                      onClick={() => handleQuickDate(btn.id as QuickDateOption)}
                                      className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all border ${
                                          quickDate === btn.id 
                                          ? 'bg-blue-50 text-blue-700 border-blue-200 shadow-sm' 
                                          : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                                      }`}
                                  >
                                      {btn.l}
                                  </button>
                               ))}
                          </div>
                          <div className="flex items-center gap-3">
                              <div className="relative flex-1">
                                  <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none">
                                      <Calendar className="w-3.5 h-3.5" />
                                  </span>
                                  <input 
                                      type="date" 
                                      value={startDate}
                                      onChange={(e) => handleManualDateChange('start', e.target.value)}
                                      className="w-full pl-8 pr-2 py-2 text-sm bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 shadow-sm text-gray-900"
                                  />
                              </div>
                              <span className="text-gray-400">-</span>
                              <div className="relative flex-1">
                                  <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none">
                                      <Calendar className="w-3.5 h-3.5" />
                                  </span>
                                  <input 
                                      type="date" 
                                      value={endDate}
                                      onChange={(e) => handleManualDateChange('end', e.target.value)}
                                      className="w-full pl-8 pr-2 py-2 text-sm bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 shadow-sm text-gray-900"
                                  />
                              </div>
                          </div>
                      </div>

                      <div className="lg:col-span-7 space-y-3">
                           <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                              <div>
                                  <label className="block text-xs font-semibold text-gray-500 mb-1.5">Từ khóa chung</label>
                                  <div className="relative">
                                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                                      <input 
                                          type="text" 
                                          value={searchText}
                                          onChange={(e) => setSearchText(e.target.value)}
                                          placeholder="Tên người mượn, mã NV..." 
                                          className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm shadow-sm text-gray-900"
                                      />
                                  </div>
                              </div>

                              <div>
                                  <label className="block text-xs font-semibold text-gray-500 mb-1.5">Trạng thái đơn</label>
                                  <div className="relative">
                                      <select
                                          value={statusFilter}
                                          onChange={(e) => setStatusFilter(e.target.value)}
                                          className="w-full pl-3 pr-8 py-2 bg-gray-50 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm appearance-none cursor-pointer shadow-sm text-gray-900"
                                      >
                                          <option value="all">Tất cả trạng thái</option>
                                          <option value="pending">⏳ Chờ duyệt</option>
                                          <option value="approved">✅ Đang mượn</option>
                                          <option value="returned">↩️ Đã trả</option>
                                          <option value="rejected">❌ Đã từ chối</option>
                                      </select>
                                      <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                                  </div>
                              </div>
                           </div>

                           <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                              <div>
                                  <label className="block text-xs font-semibold text-gray-500 mb-1.5">Người xử lý (Admin)</label>
                                  <div className="relative">
                                      <ShieldCheck className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                                      <input 
                                          type="text" 
                                          value={handlerFilter}
                                          onChange={(e) => setHandlerFilter(e.target.value)}
                                          placeholder="Nhập tên người duyệt..." 
                                          className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm shadow-sm text-gray-900"
                                      />
                                  </div>
                              </div>
                           </div>
                      </div>
                  </div>
              </div>
         </Card>
       </div>

       <Card className="p-0 overflow-hidden border border-gray-200 shadow-md bg-white">
            <div className="overflow-x-auto w-full">
                <table className="w-full text-left text-sm text-gray-600">
                    <thead className="sticky top-0 z-10 bg-gray-50">
                        <tr className="text-gray-700 font-semibold uppercase tracking-wider text-xs border-b border-gray-200 shadow-sm">
                            <th className="px-6 py-4">Người mượn</th>
                            <th className="px-6 py-4">Công cụ</th>
                            <th className="px-6 py-4">Ngày mượn</th>
                            <th className="px-6 py-4">Ngày trả</th>
                            <th className="px-6 py-4">Người xử lý</th>
                            <th className="px-6 py-4 text-center">Trạng thái</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 bg-white">
                        {loading ? (
                            <tr><td colSpan={6} className="p-10 text-center text-gray-500 flex flex-col items-center"><div className="w-6 h-6 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mb-2"></div>Đang tải dữ liệu...</td></tr>
                        ) : currentLogs.length === 0 ? (
                            <tr><td colSpan={6} className="p-10 text-center text-gray-500 italic bg-gray-50/50">Không tìm thấy dữ liệu phù hợp với bộ lọc hiện tại.</td></tr>
                        ) : (
                            currentLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-blue-50/30 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-blue-100 to-blue-200 text-blue-700 flex items-center justify-center text-sm font-bold shadow-sm border border-blue-200">
                                                {item.user_name ? item.user_name.charAt(0) : '?'}
                                            </div>
                                            <div>
                                                <div className="font-semibold text-gray-900">{item.user_name}</div>
                                                <div className="text-xs text-gray-500 font-mono bg-gray-100 px-1.5 py-0.5 rounded w-fit mt-0.5">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="font-medium text-gray-800">{item.tool_name}</span>
                                    </td>
                                    <td className="px-6 py-4 text-xs">
                                        <div className="text-gray-900 font-medium mb-0.5">{new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        <div className="text-gray-400 flex items-center gap-1"><History className="w-3 h-3"/> {new Date(item.borrow_date).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                    </td>
                                    <td className="px-6 py-4 text-xs">
                                        {item.returned_at ? (
                                            <>
                                                <div className="text-blue-700 font-medium mb-0.5">{new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                                <div className="text-blue-400">{new Date(item.returned_at).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                            </>
                                        ) : (
                                            <span className="text-gray-300 text-lg leading-none select-none">•</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        {item.status !== 'pending' ? (
                                            <div className="flex items-center gap-1.5 text-xs text-gray-700 bg-gray-100 border border-gray-200 px-2 py-1 rounded-md w-fit shadow-sm">
                                                <ShieldCheck className="w-3 h-3 text-gray-500" />
                                                <span className="font-medium">{getHandlerName(item)}</span>
                                            </div>
                                        ) : (
                                            <span className="text-gray-400 text-xs italic pl-1">Đang chờ...</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold border shadow-sm ${
                                            item.status === 'approved' ? 'bg-green-50 text-green-700 border-green-200' :
                                            item.status === 'rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                                            item.status === 'returned' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                            'bg-yellow-50 text-yellow-700 border-yellow-200'
                                        }`}>
                                            {item.status === 'approved' ? 'Đang mượn' : 
                                            item.status === 'rejected' ? 'Đã từ chối' : 
                                            item.status === 'returned' ? 'Đã trả' : 'Chờ duyệt'}
                                        </span>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            <div className="bg-gray-50 border-t border-gray-200 p-4 flex flex-col sm:flex-row items-center justify-between gap-4 px-6">
                <span className="text-xs text-gray-500 font-medium">
                    Hiển thị {currentLogs.length} trên tổng {filteredLogs.length} kết quả
                </span>

                {totalPages > 1 && (
                    <div className="flex items-center gap-2">
                        <button 
                            onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                            disabled={currentPage === 1}
                            className="p-2 rounded-lg border border-gray-300 bg-white disabled:opacity-30 hover:bg-gray-50 text-gray-600 transition-all shadow-sm"
                        >
                            <ChevronLeft className="w-4 h-4" />
                        </button>

                        <div className="flex items-center gap-1">
                            {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                                const pageNum = i + 1;
                                return (
                                    <button
                                        key={pageNum}
                                        onClick={() => setCurrentPage(pageNum)}
                                        className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                            currentPage === pageNum 
                                            ? 'bg-blue-600 text-white shadow-md' 
                                            : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
                                        }`}
                                    >
                                        {pageNum}
                                    </button>
                                );
                            })}
                            {totalPages > 5 && <span className="text-gray-400 px-1">...</span>}
                        </div>

                        <button 
                            onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
                            disabled={currentPage === totalPages}
                            className="p-2 rounded-lg border border-gray-300 bg-white disabled:opacity-30 hover:bg-gray-50 text-gray-600 transition-all shadow-sm"
                        >
                            <ChevronRight className="w-4 h-4" />
                        </button>
                    </div>
                )}

                <span className="text-[10px] text-gray-400 font-medium">
                    Cập nhật: {new Date().toLocaleTimeString('vi-VN')}
                </span>
            </div>
       </Card>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Sidebar } from './src/components/layout/Sidebar';
import { Header } from './src/components/layout/Header';
import { LoginForm } from './src/components/auth/LoginForm';
import { DashboardStats } from './src/components/dashboard/DashboardStats';
import { EmployeeList } from './src/components/employees/EmployeeList';
import { ToolInventory } from './src/components/tools/ToolInventory';
import { RequestManager } from './src/components/requests/RequestManager';
import { HistoryLog } from './src/components/history/HistoryLog';
import { OvertimeRegistration } from './src/components/overtime/OvertimeRegistration';
import { generateManagerInsight } from './src/services/geminiService';
import { Bot, X, Send, Menu } from 'lucide-react';
import { supabase } from './src/lib/supabase';
import { User } from './types';

const MainLayout: React.FC<{ children: React.ReactNode; user: User; onLogout: () => void }> = ({ children, user, onLogout }) => {
  const location = useLocation();
  const [currentPath, setCurrentPath] = useState(location.pathname);
  const [showAiChat, setShowAiChat] = useState(false);
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    setCurrentPath(location.pathname);
    setIsSidebarOpen(false); 
  }, [location]);

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!aiQuery.trim()) return;

    setAiLoading(true);
    const context = `User Role: ${user.role}. Tổng nhân viên: 124. Công cụ: 856.`;
    const result = await generateManagerInsight(context, aiQuery);
    setAiResponse(result || "Không có phản hồi.");
    setAiLoading(false);
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      {/* Sidebar - Cố định bên trái */}
      <Sidebar 
        currentPath={currentPath} 
        onNavigate={(path) => window.location.hash = path} 
        onLogout={onLogout}
        userRole={user.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Backdrop cho mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-30 lg:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Vùng nội dung bên phải: Header cố định, Main cuộn */}
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden">
        <Header user={user} onMenuClick={() => setIsSidebarOpen(true)} />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth custom-scrollbar">
          {children}
        </main>
      </div>

      {/* AI Assistant - Luôn nổi ở góc dưới */}
      <div className="fixed bottom-6 right-6 z-50">
        {!showAiChat ? (
          <button 
            onClick={() => setShowAiChat(true)}
            className="w-14 h-14 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white hover:shadow-xl transition-all transform hover:scale-110 active:scale-95 border-4 border-white"
          >
            <Bot className="w-7 h-7" />
          </button>
        ) : (
          <div className="bg-white rounded-2xl shadow-2xl w-[calc(100vw-2rem)] sm:w-96 flex flex-col border border-gray-200 overflow-hidden animate-fade-in-up origin-bottom-right">
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-4 flex justify-between items-center text-white">
              <div className="flex items-center gap-2">
                <Bot className="w-5 h-5" />
                <span className="font-semibold">Trợ lý Quản lý</span>
              </div>
              <button onClick={() => setShowAiChat(false)} className="hover:bg-white/20 p-1 rounded transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 h-64 overflow-y-auto bg-gray-50 text-sm">
              {!aiResponse && !aiLoading && (
                <p className="text-gray-500 text-center mt-20">Hãy hỏi tôi về dữ liệu nhân sự, công cụ hoặc xu hướng...</p>
              )}
              {aiLoading && (
                <div className="flex items-center justify-center h-full">
                   <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                </div>
              )}
              {aiResponse && (
                <div className="prose prose-sm max-w-none text-gray-800 whitespace-pre-line">
                  {aiResponse}
                </div>
              )}
            </div>

            <form onSubmit={handleAiAsk} className="p-3 border-t bg-white flex gap-2">
              <input 
                type="text" 
                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Hỏi trợ lý..."
                className="flex-1 px-3 py-2 border rounded-xl focus:outline-none focus:border-blue-500 text-sm shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 disabled:opacity-50 transition-colors shadow-md"
              >
                <Send className="w-4 h-4" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return <div className="h-screen flex items-center justify-center"><div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div></div>;
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
        } />

        <Route path="/dashboard" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/employees" element={
          user ? (
             user.role === 'admin' ? (
                <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
             ) : <Navigate to="/dashboard" />
          ) : <Navigate to="/login" />
        } />

        <Route path="/tools" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/requests" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/history" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/overtime" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

