import React, { useState, useEffect, useRef } from 'react';
import { Bell, User, CheckCircle2, XCircle, Clock, Info, ChevronRight, Loader2, Menu } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, OvertimeRequest } from '../../../types';

interface HeaderProps {
  user: any;
  onMenuClick?: () => void;
}

interface NotificationItem {
  id: string;
  type: 'borrow' | 'overtime';
  title: string;
  message: string;
  time: string;
  status: 'pending' | 'approved' | 'rejected' | 'returned';
  isRead: boolean;
}

export const Header: React.FC<HeaderProps> = ({ user, onMenuClick }) => {
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchNotifications = async () => {
    if (!user) return;
    setLoading(true);

    try {
      const isAdmin = user.role === 'admin';
      const notifs: NotificationItem[] = [];

      let borrowQuery = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false })
        .limit(10);

      if (!isAdmin) {
        borrowQuery = borrowQuery.eq('user_id', user.id);
      }

      const { data: borrowData } = await borrowQuery;

      if (borrowData) {
        (borrowData as BorrowRequest[]).forEach(req => {
          let shouldNotify = false;
          let title = '';
          let message = '';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Yêu cầu mượn mới';
              message = `${req.user_name} muốn mượn ${req.tool_name}`;
            }
          } else {
            if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Cập nhật yêu cầu mượn';
              const statusText = req.status === 'approved' ? 'được duyệt' : req.status === 'rejected' ? 'bị từ chối' : 'đã trả';
              message = `Yêu cầu mượn "${req.tool_name}" đã ${statusText}`;
            }
          }

          if (shouldNotify) {
            notifs.push({
              id: `borrow-${req.id}`,
              type: 'borrow',
              title,
              message,
              time: req.borrow_date,
              status: req.status,
              isRead: false
            });
          }
        });
      }

      let otQuery = supabase
        .from('ot_requests')
        .select('*, users(employee_id)')
        .order('date', { ascending: false })
        .limit(5);

      if (!isAdmin) {
        otQuery = otQuery.eq('user_id', user.id);
      }

      const { data: otData } = await otQuery;

      if (otData) {
        (otData as OvertimeRequest[]).forEach(req => {
          let shouldNotify = false;
          let title = '';
          let message = '';

          const empCode = req.users?.employee_id || 'Nhân viên';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Đăng ký tăng ca mới';
              message = `${empCode} đăng ký OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')}`;
            }
          } else {
             if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Kết quả đăng ký OT';
              const statusText = req.status === 'approved' ? 'được duyệt' : 'bị từ chối';
              message = `OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')} đã ${statusText}`;
             }
          }

          if (shouldNotify) {
            notifs.push({
              id: `ot-${req.id}`,
              type: 'overtime',
              title,
              message,
              time: req.created_at || new Date().toISOString(),
              status: req.status,
              isRead: false
            });
          }
        });
      }

      notifs.sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());
      setNotifications(notifs);
      setUnreadCount(notifs.length);

    } catch (error) {
      console.error("Error fetching notifications", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 30000);
    return () => clearInterval(interval);
  }, [user]);

  const handleToggle = () => {
    setIsOpen(!isOpen);
    if (!isOpen && unreadCount > 0) {
        setTimeout(() => setUnreadCount(0), 1000); 
    }
  };

  const getTimeAgo = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return 'Vừa xong';
    if (diffMins < 60) return `${diffMins} phút trước`;
    if (diffHours < 24) return `${diffHours} giờ trước`;
    return `${diffDays} ngày trước`;
  };

  const getIcon = (item: NotificationItem) => {
    if (item.status === 'approved') return <CheckCircle2 className="w-5 h-5 text-green-500" />;
    if (item.status === 'rejected') return <XCircle className="w-5 h-5 text-red-500" />;
    if (item.status === 'pending') return <Clock className="w-5 h-5 text-yellow-500" />;
    if (item.status === 'returned') return <Info className="w-5 h-5 text-blue-500" />;
    return <Info className="w-5 h-5 text-gray-500" />;
  };

  return (
    <header className="bg-white border-b border-gray-200 h-16 px-4 md:px-8 flex items-center justify-between sticky top-0 z-20 shadow-sm flex-shrink-0">
      <div className="flex items-center gap-3">
        <button 
          onClick={onMenuClick}
          className="lg:hidden p-2 -ml-2 hover:bg-gray-100 rounded-xl transition-colors"
        >
          <Menu className="w-6 h-6 text-gray-600" />
        </button>
        <div className="hidden sm:flex items-center gap-2 text-gray-500">
          <span className="text-xs md:text-sm font-medium">Hôm nay, {new Date().toLocaleDateString('vi-VN', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' })}</span>
        </div>
      </div>

      <div className="flex items-center gap-3 md:gap-6">
        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={handleToggle}
            className={`relative p-2.5 rounded-xl transition-all duration-200 ${isOpen ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            <Bell className={`w-5 h-5 ${unreadCount > 0 ? 'animate-pulse-slow' : ''}`} />
            {unreadCount > 0 && (
              <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white flex items-center justify-center shadow-sm">
                 <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-rose-400 opacity-75"></span>
              </span>
            )}
          </button>

          {isOpen && (
            <div className="absolute right-0 top-full mt-3 w-[calc(100vw-2rem)] sm:w-96 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-fade-in-up origin-top-right">
              <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-800 tracking-tight">Thông báo</h3>
                <button onClick={fetchNotifications} title="Làm mới" className="text-gray-400 hover:text-blue-600 transition-colors">
                   {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <span className="text-xs font-bold uppercase tracking-tighter">Làm mới</span>}
                </button>
              </div>

              <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
                {notifications.length === 0 ? (
                  <div className="p-12 text-center text-gray-500 flex flex-col items-center">
                    <Bell className="w-12 h-12 text-gray-100 mb-2" />
                    <p className="text-sm font-medium">Không có thông báo mới</p>
                  </div>
                ) : (
                  <ul className="divide-y divide-gray-50">
                    {notifications.map((notif) => (
                      <li key={notif.id} className="p-4 hover:bg-blue-50/40 transition-colors group cursor-pointer border-l-4 border-l-transparent hover:border-l-blue-500">
                        <div className="flex gap-3">
                          <div className={`mt-1 flex-shrink-0 w-9 h-9 rounded-xl flex items-center justify-center bg-white border shadow-sm transition-transform group-hover:scale-105`}>
                            {getIcon(notif)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-start gap-2">
                                <p className="text-sm font-bold text-gray-900 truncate">{notif.title}</p>
                                <span className="text-[10px] text-gray-400 font-bold whitespace-nowrap">{getTimeAgo(notif.time)}</span>
                            </div>
                            <p className="text-sm text-gray-500 mt-0.5 line-clamp-2 leading-relaxed">{notif.message}</p>
                          </div>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              {notifications.length > 0 && (
                 <div className="p-3 bg-gray-50 border-t border-gray-100 text-center">
                    <button className="text-xs font-bold text-blue-600 hover:text-blue-800 transition-colors uppercase tracking-widest">
                        Xem tất cả
                    </button>
                 </div>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 md:gap-3 pl-4 md:pl-6 border-l border-gray-100">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-bold text-gray-900 tracking-tight">{user?.name || 'Admin User'}</p>
            <p className="text-[10px] text-blue-500 font-black uppercase tracking-widest">
                {user?.role || 'Staff'}
            </p>
          </div>
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20 border-2 border-white overflow-hidden transform hover:rotate-6 transition-transform">
             {user?.avatarUrl ? (
                <img src={user.avatarUrl} alt="" className="w-full h-full object-cover" />
             ) : (
                <User className="w-5 h-5" />
             )}
          </div>
        </div>
      </div>
    </header>
  );
};

