    if (statusFilter !== 'all') query = query.eq('status', statusFilter);
    if (startDate) query = query.gte('borrow_date', `${startDate}T00:00:00`);
    if (endDate) query = query.lte('borrow_date', `${endDate}T23:59:59`);
    const { data, error } = await query;
    if (data) setLogs(data);
    setLoading(false);
