                <p className="text-sm text-gray-500">{user.role === 'admin' ? 'Theo dõi toàn bộ hệ thống' : 'Theo dõi cá nhân'}</p>
            </div>
       </div>

       {/* STICKY FILTERS - Bám vào Main Container cuộn */}
       <div className="sticky top-[-1px] z-30 pt-2 pb-4 bg-gray-50/95 backdrop-blur-sm -mx-4 px-4 md:-mx-8 md:px-8">
         <Card className="p-5 border border-gray-200 shadow-md bg-white rounded-3xl">
             <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
                 <div className="relative group">
                     <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                     <input type="text" value={searchText} onChange={(e) => setSearchText(e.target.value)} placeholder="Tìm tên, mã NV..." className="w-full pl-10 pr-4 py-2 bg-gray-50 border-2 border-transparent rounded-xl text-sm font-bold focus:bg-white focus:border-blue-500 outline-none transition-all" />
