};

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { setError(false); setLoaded(false); }, [src]);
  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0;

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full ${className}`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2 text-gray-300' : 'w-5 h-5 text-gray-400'}`} />
      </div>
    );
  }
  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}
      <img src={src} alt={alt} onLoad={() => setLoaded(true)} onError={() => setError(true)} className={`max-w-full max-h-full object-contain ${loaded ? 'opacity-100' : 'opacity-0'}`} />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const isAdmin = user.role === 'admin';

  useEffect(() => { fetchTools(); }, []);

  const fetchTools = async () => {
    const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      return matchesSearch && matchesCategory;
    });
  }, [tools, searchTerm, filterCategory]);

  const handleRowClick = (tool: Tool) => {
    if (isAdmin) return;
    const newSet = new Set(selectedToolIds);
    if (newSet.has(tool.id)) newSet.delete(tool.id);
    else { newSet.add(tool.id); setQuantities(prev => ({...prev, [tool.id]: 1})); }
    setSelectedToolIds(newSet);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Kho công cụ</h2>
        <div className="flex gap-2">
          {isAdmin && <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 text-sm"><Plus className="w-4 h-4"/> Thêm mới</button>}
          <div className="flex bg-gray-100 p-1 rounded-lg">
            <button onClick={() => setViewMode('grid')} className={`p-2 rounded ${viewMode === 'grid' ? 'bg-white shadow-sm' : ''}`}><LayoutGrid className="w-4 h-4"/></button>
            <button onClick={() => setViewMode('table')} className={`p-2 rounded ${viewMode === 'table' ? 'bg-white shadow-sm' : ''}`}><List className="w-4 h-4"/></button>
          </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Tìm kiếm công cụ..." className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" />
        </div>
        <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} className="px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none">
          <option value="all">Tất cả danh mục</option>
          {Array.from(new Set(tools.map(t => t.category))).map(cat => <option key={cat} value={cat}>{cat}</option>)}
        </select>
      </div>

      {viewMode === 'grid' ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredTools.map(tool => (
            <Card key={tool.id} className={`p-0 overflow-hidden cursor-pointer border-2 ${selectedToolIds.has(tool.id) ? 'border-blue-500' : 'border-transparent'}`} onClick={() => handleRowClick(tool)}>
              <div className="h-48 bg-gray-50 border-b"><ToolThumbnail src={tool.image} alt={tool.name} mode="grid" /></div>
              <div className="p-4">
                <p className="text-xs text-blue-600 font-bold uppercase mb-1">{tool.category}</p>
                <h4 className="font-bold text-gray-900 truncate">{tool.name}</h4>
                <div className="mt-3 flex justify-between items-center text-sm">
                  <span className="text-gray-500">Sẵn: {tool.available} / {tool.quantity}</span>
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${tool.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{tool.status === 'active' ? 'HOẠT ĐỘNG' : 'BẢO TRÌ'}</span>
                </div>
              </div>
            </Card>
          ))}
        </div>
      ) : (
        <Card className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-gray-50 border-b">
