              </thead>
              <tbody className="divide-y">
                {filteredTools.map(tool => (
                  <tr key={tool.id} className={`hover:bg-gray-50 ${selectedToolIds.has(tool.id) ? 'bg-blue-50' : ''}`} onClick={() => handleRowClick(tool)}>
                    <td className="px-6 py-4 font-bold text-gray-900">{tool.name}</td>
                    <td className="px-6 py-4 text-sm text-gray-500">{tool.category}</td>
                    <td className="px-6 py-4 text-center font-bold">{tool.available} / {tool.quantity}</td>
