const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkUser = async () => {
      const stored = localStorage.getItem('sb-session');
      if (stored) {
        const session = JSON.parse(stored);
        setUser(session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => { setUser(userData); };
  const handleLogout = () => { localStorage.removeItem('sb-session'); setUser(null); };

  if (loading) return <div className="h-screen flex items-center justify-center">Đang tải...</div>;

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={!user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />} />
        <Route path="/dashboard" element={user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />} />
        <Route path="/employees" element={user && user.role === 'admin' ? <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout> : <Navigate to="/dashboard" />} />
        <Route path="/tools" element={user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />} />
        <Route path="/requests" element={user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />} />
        <Route path="/history" element={user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />} />
        <Route path="/overtime" element={user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />} />
        <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

