import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus, Share2, ToggleLeft, ToggleRight, Eye, MousePointer2, CalendarRange, FileDown, ArrowRight, Zap, List, ChevronDown, ChevronUp
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (data) setRequests(data as OvertimeRequest[]);
    } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const { data } = await supabase.from('day_configs').select('*');
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setReason('');
    setEditingRequestId(null);
    setIsModalOpen(true);

    // Mặc định giờ theo ngày
    const dateObj = new Date(dateStr);
    if (dateObj.getDay() === 0) {
        setStartTime('08:00'); setEndTime('20:00');
    } else {
        setStartTime('17:30'); setEndTime('20:00');
    }

    // Nếu tôi đã có đơn ngày này, chuyển sang chế độ sửa
    const myExisting = requests.find(r => r.date === dateStr && r.user_id === user.id);
    if (myExisting) {
        setEditingRequestId(myExisting.id);
        setStartTime(myExisting.start_time);
        setEndTime(myExisting.end_time);
        setReason(myExisting.reason);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm việc không hợp lệ.");
    setIsSubmitting(true);

    try {
        // Kiểm tra xem người này đã có đơn ngày này chưa
        if (!editingRequestId) {
            const { data: existing } = await supabase.from('ot_requests')
                .select('id, users(name)')
                .eq('date', selectedDateStr)
                .eq('user_id', targetUserId)
                .single();

            if (existing) {
                const confirmUpdate = window.confirm(
                    `LƯU Ý: ${existing.users?.name || 'Nhân viên này'} ĐÃ có đơn đăng ký vào ngày này. \nBạn có muốn ghi đè lên đơn hiện có không?`
                );
                if (!confirmUpdate) {
                    setIsSubmitting(false);
                    return;
                }
                setEditingRequestId(existing.id);
            }
        }

        const payload = {
            user_id: targetUserId,
            date: selectedDateStr,
            start_time: startTime,
            end_time: endTime,
            total_hours: calculatedHours,
            reason,
            status: 'approved'
        };

        const res = editingRequestId 
            ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
            : await supabase.from('ot_requests').insert([payload]);

        if (res.error) throw res.error;
        await fetchRequests();
        setIsModalOpen(false);
        alert("Cập nhật đăng ký thành công!");
    } catch (err: any) {
        alert("Lỗi: " + err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const totalDays = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);
    const offset = firstDay === 0 ? 6 : firstDay - 1;

    for (let i = 0; i < offset; i++) days.push(<div key={`empty-${i}`} className="h-20 bg-gray-50/30 border border-gray-100 opacity-50"></div>);

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayReqs = requests.filter(r => r.date === dateStr);
        const hasMine = dayReqs.some(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;

        days.push(
            <div key={d} onClick={() => handleDateClick(dateStr)} className={`h-20 border border-gray-100 p-2 relative cursor-pointer hover:bg-blue-50 transition-colors ${isToday ? 'bg-blue-50/50 ring-1 ring-blue-400' : 'bg-white'}`}>
                <span className={`text-sm font-bold ${isToday ? 'text-blue-600' : 'text-gray-600'}`}>{d}</span>
                <div className="mt-1 flex flex-wrap gap-1">
                    {hasMine && <div className="w-2 h-2 bg-emerald-500 rounded-full" title="Đơn của tôi"></div>}
                    {dayReqs.length > (hasMine ? 1 : 0) && <div className="w-2 h-2 bg-indigo-400 rounded-full" title="Đơn của đồng nghiệp"></div>}
                </div>
                {dayReqs.length > 0 && <span className="absolute bottom-1 right-2 text-[10px] font-black text-gray-300">{dayReqs.length} đơn</span>}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-[2rem] shadow-sm border">
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">Quản lý Tăng ca</h2>
                <p className="text-sm text-gray-500 font-medium">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
            </div>
            <div className="flex bg-gray-100 p-1 rounded-2xl border">
                <button onClick={() => setActiveTab('calendar')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500'}`}>Lịch</button>
                <button onClick={() => setActiveTab('personal')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md' : 'text-gray-500'}`}>Cá nhân</button>
                <button onClick={() => setActiveTab('stats')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-500'}`}>Thống kê</button>
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="p-0 overflow-hidden rounded-[2.5rem] bg-white shadow-xl">
                <div className="flex items-center justify-between p-6 border-b">
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-100 rounded-xl"><ChevronLeft/></button>
                    <h3 className="font-black uppercase tracking-widest">Tháng {currentDate.getMonth() + 1}</h3>
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-100 rounded-xl"><ChevronRight/></button>
                </div>
                <div className="grid grid-cols-7 text-center py-4 bg-gray-50 text-[10px] font-black uppercase text-gray-400">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d}>{d}</div>)}
                </div>
                <div className="grid grid-cols-7 gap-[1px] bg-gray-100">
                    {renderCalendarDays()}
                </div>
