const ToolThumbnail = ({ src, alt, className }: { src?: string | null, alt: string, className?: string }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { setError(false); setLoaded(false); }, [src]);
  if (error || !src) return <div className={`flex items-center justify-center bg-gray-50 ${className}`}><Wrench className="w-10 h-10 text-gray-300"/></div>;
  return <div className={`relative bg-white flex items-center justify-center ${className}`}>{!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}<img src={src} alt={alt} onLoad={() => setLoaded(true)} onError={() => setError(true)} className={`max-h-full transition-opacity ${loaded ? 'opacity-100' : 'opacity-0'}`} /></div>;
};

