import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Save, X, CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Users, User as UserIcon, Trash2, Info, Activity, PieChart as PieChartIcon, Search, Eye, MousePointer2, CalendarRange, FileDown, Zap
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => {
    const d = new Date(year, month, 1).getDay();
    return d === 0 ? 6 : d - 1; // 0=T2, 6=CN
};

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (data) setRequests(data as OvertimeRequest[]);
    } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const { data } = await supabase.from('day_configs').select('*');
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setEditingRequestId(null);
    setReason('');

    // Tìm đơn cũ nếu có (của chính mình)
    const existing = requests.find(r => r.date === dateStr && r.user_id === user.id);
    if (existing) {
        setEditingRequestId(existing.id);
        setStartTime(existing.start_time);
        setEndTime(existing.end_time);
        setReason(existing.reason);
    } else {
        const dateObj = new Date(dateStr);
        if (dateObj.getDay() === 0) { setStartTime('08:00'); setEndTime('20:00'); }
        else { setStartTime('17:30'); setEndTime('20:00'); }
    }
    setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm việc không hợp lệ.");
    setIsSubmitting(true);

    try {
        // Kiểm tra chặn ghi đè nếu Admin đang đăng ký hộ
        if (!editingRequestId) {
            const { data: existing } = await supabase.from('ot_requests')
                .select('id, users(name)')
                .eq('date', selectedDateStr)
                .eq('user_id', targetUserId)
                .single();

            if (existing) {
                const targetName = Array.isArray(existing.users) ? (existing.users[0] as any)?.name : (existing.users as any)?.name;
                const confirmUpdate = window.confirm(
                    `LƯU Ý: ${targetName || 'Nhân viên này'} ĐÃ có một đơn đăng ký vào ngày này. \nBạn có muốn ghi đè lên đơn hiện có không?`
                );
                if (!confirmUpdate) {
                    setIsSubmitting(false);
                    return;
                }
                setEditingRequestId(existing.id);
            }
        }

        const payload = {
            user_id: targetUserId,
            date: selectedDateStr,
            start_time: startTime,
            end_time: endTime,
            total_hours: calculatedHours,
            reason,
            status: 'approved'
        };

        const res = editingRequestId 
            ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
            : await supabase.from('ot_requests').insert([payload]);

        if (res.error) throw res.error;
        await fetchRequests();
        setIsModalOpen(false);
        alert("Đã cập nhật đơn đăng ký thành công!");
    } catch (err: any) {
        alert("Có lỗi xảy ra: " + err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const offset = getFirstDayOfMonth(year, month);
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < offset; i++) days.push(<div key={`empty-${i}`} className="h-20 bg-gray-50/50 border border-gray-100/50"></div>);

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayReqs = requests.filter(r => r.date === dateStr);
        const myReq = dayReqs.find(r => r.user_id === user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;

        days.push(
            <div key={d} onClick={() => handleDateClick(dateStr)} className={`h-20 border border-gray-100 p-2 relative cursor-pointer hover:bg-blue-50 transition-colors flex flex-col ${isToday ? 'bg-blue-50/70 ring-1 ring-blue-400' : 'bg-white'}`}>
                <span className={`text-sm font-bold ${isToday ? 'text-blue-600' : 'text-gray-700'}`}>{d}</span>
                <div className="mt-1 flex flex-wrap gap-1">
                    {myReq && <div className="w-2 h-2 bg-emerald-500 rounded-full" title="Đơn của bạn"></div>}
                    {dayReqs.length > (myReq ? 1 : 0) && <div className="w-2 h-2 bg-indigo-400 rounded-full" title="Đơn đồng nghiệp"></div>}
                </div>
                {dayReqs.length > 0 && <span className="absolute bottom-1 right-2 text-[10px] font-bold text-gray-300">{dayReqs.length} đơn</span>}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
            <div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">Lịch trình Tăng ca</h2>
                <p className="text-sm text-gray-400 font-medium mt-1">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
            </div>
            <div className="flex bg-gray-100 p-1 rounded-2xl border border-gray-200">
                <button onClick={() => setActiveTab('calendar')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Lịch</button>
                <button onClick={() => setActiveTab('personal')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Của tôi</button>
                <button onClick={() => setActiveTab('stats')} className={`px-6 py-2 rounded-xl text-sm font-black transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-500 hover:text-gray-700'}`}>Thống kê</button>
            </div>
        </div>

        {activeTab === 'calendar' && (
            <Card className="p-0 overflow-hidden rounded-[2.5rem] bg-white shadow-xl border-none">
                <div className="flex items-center justify-between p-6 border-b border-gray-50 bg-white">
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-50 rounded-xl transition-colors"><ChevronLeft className="w-5 h-5"/></button>
                    <h3 className="font-black uppercase tracking-widest text-gray-800">THÁNG {currentDate.getMonth() + 1}</h3>
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-50 rounded-xl transition-colors"><ChevronRight className="w-5 h-5"/></button>
                </div>
                <div className="grid grid-cols-7 text-center py-4 bg-gray-50 text-[10px] font-black uppercase text-gray-400 tracking-widest border-b border-gray-100">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d}>{d}</div>)}
                </div>
                <div className="grid grid-cols-7 gap-[1px] bg-gray-100">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-zoom-in">
                    <div className={`p-6 text-white flex justify-between items-center ${targetUserId === user.id ? 'bg-indigo-600' : 'bg-orange-600'}`}>
                        <div className="flex items-center gap-3">
                            <Clock className="w-6 h-6" />
                            <div>
                                <h3 className="text-xl font-black">{selectedDateStr.split('-').reverse().join('/')}</h3>
                                <p className="text-[10px] font-black uppercase tracking-widest opacity-80">
                                    {editingRequestId ? 'Cập nhật đơn' : 'Đăng ký mới'} 
                                    {targetUserId !== user.id && ` cho nhân viên`}
                                </p>
                            </div>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="hover:bg-white/20 p-2 rounded-xl transition-colors"><X className="w-6 h-6"/></button>
                    </div>

                    <form onSubmit={handleSubmit} className="p-8 space-y-6">
                        {isAdmin && (
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Người thực hiện:</label>
                                <select 
                                    value={targetUserId} 
                                    onChange={(e) => {
                                        const newUid = e.target.value;
                                        setTargetUserId(newUid);
                                        const existing = requests.find(r => r.date === selectedDateStr && r.user_id === newUid);
                                        if (existing) {
                                            setEditingRequestId(existing.id);
                                            setStartTime(existing.start_time);
                                            setEndTime(existing.end_time);
                                            setReason(existing.reason);
                                        } else {
                                            setEditingRequestId(null);
                                            setReason('');
                                        }
                                    }}
                                    className="w-full px-4 py-3 border-2 border-gray-100 rounded-2xl text-sm font-black focus:border-indigo-500 outline-none transition-all shadow-sm"
                                >
                                    {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>)}
                                </select>
                            </div>
                        )}

                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Bắt đầu</label>
                                <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-black text-lg border-none focus:ring-2 focus:ring-indigo-500/20" />
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Kết thúc</label>
                                <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full p-4 bg-gray-50 rounded-2xl font-black text-lg border-none focus:ring-2 focus:ring-indigo-500/20" />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <div className="flex justify-between items-center px-1">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung công việc</label>
                                <div className="flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-700 rounded-full">
                                    <span className="text-[11px] font-black">{calculatedHours}h</span>
                                    <span className="text-[8px] font-bold uppercase tracking-tighter">Tổng giờ</span>
                                </div>
                            </div>
                            <textarea 
                                value={reason} 
                                onChange={e => setReason(e.target.value)} 
                                required
                                placeholder="Nhập lý do hoặc chi tiết công việc..."
                                className="w-full p-4 bg-gray-50 rounded-3xl text-sm h-32 resize-none border-none outline-none focus:ring-2 focus:ring-indigo-500/20 shadow-inner"
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={isSubmitting || calculatedHours <= 0}
                            className={`w-full py-5 text-white font-black rounded-[2rem] shadow-xl transition-all active:scale-95 uppercase tracking-[0.2em] text-xs flex items-center justify-center gap-3 ${targetUserId === user.id ? 'bg-indigo-600 shadow-indigo-100' : 'bg-orange-600 shadow-orange-100'}`}
                        >
                            {isSubmitting ? <Loader2 className="animate-spin w-5 h-5" /> : <Save className="w-5 h-5" />}
                            {editingRequestId ? 'LƯU THAY ĐỔI' : 'XÁC NHẬN GỬI'}
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
