import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, ArrowRight, Loader2
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const ToolThumbnail = ({ src, alt, className }: { src?: string | null, alt: string, className?: string }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { setError(false); setLoaded(false); }, [src]);
  if (error || !src) return <div className={`flex items-center justify-center bg-gray-50 ${className}`}><Wrench className="w-10 h-10 text-gray-300"/></div>;
  return <div className={`relative bg-white flex items-center justify-center ${className}`}>{!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}<img src={src} alt={alt} onLoad={() => setLoaded(true)} onError={() => setError(true)} className={`max-h-full transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'}`} /></div>;
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const isAdmin = user.role === 'admin';

  useEffect(() => {
    const fetchTools = async () => {
      const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
      if (data) setTools(data as Tool[]);
    };
    fetchTools();
  }, []);

  const filtered = tools.filter(t => t.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleToolClick = (tool: Tool) => {
    if (isAdmin) return;
    if (tool.status === 'inactive' || tool.available === 0) return;

    const newSelected = new Set(selectedToolIds);
    if (newSelected.has(tool.id)) {
        newSelected.delete(tool.id);
    } else {
        newSelected.add(tool.id);
        setQuantities(prev => ({ ...prev, [tool.id]: 1 }));
    }
    setSelectedToolIds(newSelected);
  };

  const handleBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsSubmitting(true);
    // Logic gửi yêu cầu...
    alert("Đã gửi yêu cầu mượn đồ thành công!");
    setSelectedToolIds(new Set());
    setIsSubmitting(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
            <h2 className="text-2xl font-black text-gray-900 tracking-tight">Kho thiết bị</h2>
            <p className="text-sm text-gray-400 font-medium">Quản lý và theo dõi công cụ sản xuất</p>
        </div>
        <div className="flex gap-2">
            {isAdmin && <button className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-xl text-sm font-black flex items-center gap-2 transition-all shadow-lg shadow-blue-100 active:scale-95"><Plus className="w-4 h-4"/> Thêm mới</button>}
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
                <button onClick={() => setViewMode('grid')} className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}><LayoutGrid className="w-5 h-5"/></button>
                <button onClick={() => setViewMode('table')} className={`p-2 rounded-lg transition-all ${viewMode === 'table' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}><List className="w-5 h-5"/></button>
            </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-3xl border border-gray-100 shadow-sm flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1 group">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500 transition-colors" />
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Tìm tên công cụ hoặc mã thiết bị..." className="w-full pl-10 pr-4 py-3 bg-gray-50 border-none rounded-2xl focus:bg-white focus:ring-2 focus:ring-blue-500/10 outline-none text-sm font-medium transition-all" />
        </div>
      </div>

      {viewMode === 'grid' ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filtered.map(tool => {
            const isSelected = selectedToolIds.has(tool.id);
            return (
              <Card 
                key={tool.id} 
                className={`p-0 overflow-hidden flex flex-col h-full rounded-[2rem] border-2 transition-all duration-300 ${isSelected ? 'border-blue-600 ring-8 ring-blue-500/5' : 'border-transparent shadow-lg hover:shadow-xl'}`}
                onClick={() => handleToolClick(tool)}
              >
                <div className="relative">
                    <ToolThumbnail src={tool.image} alt={tool.name} className="h-48 border-b border-gray-50" />
                    <div className="absolute top-3 right-3 flex flex-col gap-1.5 items-end">
                        <span className={`px-2.5 py-1 rounded-full font-black text-[9px] uppercase tracking-widest shadow-sm border ${tool.status === 'active' ? (tool.available > 0 ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-gray-400 text-white border-gray-300') : 'bg-rose-500 text-white border-rose-400'}`}>
                            {tool.status === 'active' ? (tool.available > 0 ? 'Sẵn sàng' : 'Hết hàng') : 'Bảo trì'}
                        </span>
                    </div>
                </div>
                <div className="p-5 flex-1 flex flex-col">
                  <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1 opacity-70">{tool.category}</p>
                  <h4 className="font-bold text-gray-900 leading-tight mb-4 group-hover:text-blue-600">{tool.name}</h4>
                  <div className="mt-auto space-y-3">
                      <div className="flex justify-between items-center text-xs">
                        <span className="font-bold text-gray-400 flex items-center gap-1"><MapPin className="w-3 h-3"/> {tool.location || 'N/A'}</span>
                        <span className="font-black text-gray-900 bg-gray-50 px-2 py-1 rounded-lg">{tool.available} / {tool.quantity}</span>
                      </div>

                      {!isAdmin && isSelected && (
                        <div className="flex items-center justify-between bg-blue-50 p-1.5 rounded-xl border border-blue-100 animate-fade-in-up" onClick={e => e.stopPropagation()}>
                            <button onClick={() => setQuantities(prev => ({...prev, [tool.id]: Math.max(1, (prev[tool.id] || 1) - 1)}))} className="p-1 bg-white rounded-lg shadow-sm text-blue-600"><Minus className="w-4 h-4"/></button>
                            <span className="text-sm font-black text-blue-700">{quantities[tool.id] || 1}</span>
                            <button onClick={() => setQuantities(prev => ({...prev, [tool.id]: Math.min(tool.available, (prev[tool.id] || 1) + 1)}))} className="p-1 bg-white rounded-lg shadow-sm text-blue-600"><Plus className="w-4 h-4"/></button>
                        </div>
                      )}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      ) : (
        <Card className="p-0 overflow-hidden rounded-[2.5rem] border-none shadow-xl bg-white">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50 text-gray-400 uppercase text-[10px] font-black tracking-[0.2em]">
                <tr>
                  <th className="px-8 py-5">Tên thiết bị</th>
                  <th className="px-8 py-5">Phân loại</th>
                  <th className="px-8 py-5 text-center">Tồn kho</th>
                  <th className="px-8 py-5 text-right">Tình trạng</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filtered.map(tool => (
                  <tr key={tool.id} className="hover:bg-blue-50/20 transition-colors cursor-pointer group" onClick={() => handleToolClick(tool)}>
                    <td className="px-8 py-4">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-gray-100 flex items-center justify-center overflow-hidden border border-gray-200">
                                <ToolThumbnail src={tool.image} alt="" className="w-full h-full" />
                            </div>
                            <span className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors">{tool.name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-4 font-medium text-gray-500 uppercase text-[10px] tracking-widest">{tool.category}</td>
                    <td className="px-8 py-4 text-center font-black text-gray-900">{tool.available} / {tool.quantity}</td>
                    <td className="px-8 py-4 text-right">
                        <span className={`px-2.5 py-1 rounded-lg font-black text-[9px] uppercase tracking-tighter ${tool.status === 'active' ? 'text-emerald-600 bg-emerald-50' : 'text-rose-600 bg-rose-50'}`}>{tool.status === 'active' ? 'Làm việc' : 'Bảo trì'}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {!isAdmin && selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-40 w-full max-w-lg px-4">
              <div className="bg-gray-950/90 backdrop-blur-xl text-white p-4 pr-5 rounded-[2.5rem] shadow-2xl flex items-center justify-between border border-white/10 animate-fade-in-up">
                  <div className="flex items-center gap-4 pl-3">
                      <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg"><ShoppingBag className="w-6 h-6"/></div>
                      <div>
                          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Đang chọn</p>
                          <p className="text-sm font-black">{selectedToolIds.size} loại thiết bị</p>
                      </div>
                  </div>
                  <button 
                    onClick={handleBorrow} 
                    disabled={isSubmitting}
                    className="bg-white text-gray-950 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-2 hover:bg-blue-50 transition-all active:scale-95"
                  >
                      {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Send className="w-4 h-4" />}
                      Gửi yêu cầu
                  </button>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, ArrowRight, Loader2
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const ToolThumbnail = ({ src, alt, className }: { src?: string | null, alt: string, className?: string }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { setError(false); setLoaded(false); }, [src]);
  if (error || !src) return <div className={`flex items-center justify-center bg-gray-50 ${className}`}><Wrench className="w-10 h-10 text-gray-300"/></div>;
  return <div className={`relative bg-white flex items-center justify-center ${className}`}>{!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}<img src={src} alt={alt} onLoad={() => setLoaded(true)} onError={() => setError(true)} className={`max-h-full transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'}`} /></div>;
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const isAdmin = user.role === 'admin';

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const filtered = tools.filter(t => t.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleToolClick = (tool: Tool) => {
    // Không cho chọn nếu đang bảo trì hoặc hết hàng
    if (tool.status === 'inactive' || tool.available === 0) return;

    const newSelected = new Set(selectedToolIds);
    if (newSelected.has(tool.id)) {
        newSelected.delete(tool.id);
    } else {
        newSelected.add(tool.id);
        setQuantities(prev => ({ ...prev, [tool.id]: 1 }));
    }
    setSelectedToolIds(newSelected);
  };

  const handleBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsSubmitting(true);

    try {
      const selectedTools = tools.filter(t => selectedToolIds.has(t.id));

      // Chuẩn bị dữ liệu insert vào bảng 'requests'
      const requestsToInsert = selectedTools.map(tool => ({
        employee_id: user.employeeCode,
        user_id: user.id,
        user_name: user.name,
        tool_id: tool.id,
        tool_name: tool.name,
        borrow_date: new Date().toISOString(),
        status: 'pending'
      }));

      const { error } = await supabase.from('requests').insert(requestsToInsert);

      if (error) throw error;

      alert(`Đã gửi yêu cầu mượn ${selectedToolIds.size} thiết bị thành công! Vui lòng chờ quản lý duyệt tại mục "Yêu cầu mượn".`);

      // Reset state
      setSelectedToolIds(new Set());
      setQuantities({});
      await fetchTools(); // Cập nhật lại số lượng hiển thị (nếu cần)
    } catch (err: any) {
      alert("Có lỗi khi gửi yêu cầu: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
            <h2 className="text-2xl font-black text-gray-900 tracking-tight">Kho thiết bị</h2>
            <p className="text-sm text-gray-400 font-medium">Chọn thiết bị để gửi yêu cầu mượn</p>
        </div>
        <div className="flex gap-2">
            {isAdmin && <button className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-xl text-sm font-black flex items-center gap-2 transition-all shadow-lg shadow-blue-100 active:scale-95"><Plus className="w-4 h-4"/> Thêm mới</button>}
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
                <button onClick={() => setViewMode('grid')} className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}><LayoutGrid className="w-5 h-5"/></button>
                <button onClick={() => setViewMode('table')} className={`p-2 rounded-lg transition-all ${viewMode === 'table' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}><List className="w-5 h-5"/></button>
            </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-3xl border border-gray-100 shadow-sm flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1 group">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500 transition-colors" />
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Tìm tên công cụ hoặc mã thiết bị..." className="w-full pl-10 pr-4 py-3 bg-gray-50 border-none rounded-2xl focus:bg-white focus:ring-2 focus:ring-blue-500/10 outline-none text-sm font-medium transition-all" />
        </div>
      </div>

      {viewMode === 'grid' ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filtered.map(tool => {
            const isSelected = selectedToolIds.has(tool.id);
            const isDisable = tool.status === 'inactive' || tool.available === 0;

            return (
              <Card 
                key={tool.id} 
                className={`p-0 overflow-hidden flex flex-col h-full rounded-[2rem] border-2 transition-all duration-300 ${isDisable ? 'opacity-60 cursor-not-allowed bg-gray-50' : 'cursor-pointer'} ${isSelected ? 'border-blue-600 ring-8 ring-blue-500/5 bg-blue-50/10' : 'border-transparent shadow-lg hover:shadow-xl'}`}
                onClick={() => handleToolClick(tool)}
              >
                <div className="relative">
                    <ToolThumbnail src={tool.image} alt={tool.name} className="h-48 border-b border-gray-50" />
                    <div className="absolute top-3 right-3 flex flex-col gap-1.5 items-end">
                        <span className={`px-2.5 py-1 rounded-full font-black text-[9px] uppercase tracking-widest shadow-sm border ${tool.status === 'active' ? (tool.available > 0 ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-gray-400 text-white border-gray-300') : 'bg-rose-500 text-white border-rose-400'}`}>
                            {tool.status === 'active' ? (tool.available > 0 ? 'Sẵn sàng' : 'Hết hàng') : 'Bảo trì'}
                        </span>
                    </div>
                    {isSelected && (
                        <div className="absolute inset-0 bg-blue-600/10 flex items-center justify-center">
                            <div className="bg-blue-600 text-white p-2 rounded-full shadow-lg scale-110">
                                <ShoppingBag className="w-5 h-5" />
                            </div>
                        </div>
                    )}
                </div>
                <div className="p-5 flex-1 flex flex-col">
                  <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1 opacity-70">{tool.category}</p>
                  <h4 className="font-bold text-gray-900 leading-tight mb-4 group-hover:text-blue-600">{tool.name}</h4>
                  <div className="mt-auto space-y-3">
                      <div className="flex justify-between items-center text-xs">
                        <span className="font-bold text-gray-400 flex items-center gap-1"><MapPin className="w-3 h-3"/> {tool.location || 'N/A'}</span>
                        <span className={`font-black px-2 py-1 rounded-lg ${tool.available === 0 ? 'text-rose-600 bg-rose-50' : 'text-gray-900 bg-gray-50'}`}>{tool.available} / {tool.quantity}</span>
                      </div>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      ) : (
        <Card className="p-0 overflow-hidden rounded-[2.5rem] border-none shadow-xl bg-white">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50 text-gray-400 uppercase text-[10px] font-black tracking-[0.2em]">
                <tr>
                  <th className="px-8 py-5">Tên thiết bị</th>
                  <th className="px-8 py-5">Phân loại</th>
                  <th className="px-8 py-5 text-center">Tồn kho</th>
                  <th className="px-8 py-5 text-right">Tình trạng</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filtered.map(tool => {
                   const isSelected = selectedToolIds.has(tool.id);
                   const isDisable = tool.status === 'inactive' || tool.available === 0;
                   return (
                    <tr 
                        key={tool.id} 
                        className={`transition-colors group ${isDisable ? 'opacity-50 cursor-not-allowed bg-gray-50' : 'cursor-pointer hover:bg-blue-50/20'} ${isSelected ? 'bg-blue-50' : ''}`} 
                        onClick={() => handleToolClick(tool)}
                    >
                        <td className="px-8 py-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-gray-100 flex items-center justify-center overflow-hidden border border-gray-200">
                                    <ToolThumbnail src={tool.image} alt="" className="w-full h-full" />
                                </div>
                                <span className={`font-bold transition-colors ${isSelected ? 'text-blue-600' : 'text-gray-900 group-hover:text-blue-600'}`}>{tool.name}</span>
                            </div>
                        </td>
                        <td className="px-8 py-4 font-medium text-gray-500 uppercase text-[10px] tracking-widest">{tool.category}</td>
                        <td className="px-8 py-4 text-center font-black text-gray-900">{tool.available} / {tool.quantity}</td>
                        <td className="px-8 py-4 text-right">
                            <span className={`px-2.5 py-1 rounded-lg font-black text-[9px] uppercase tracking-tighter ${tool.status === 'active' ? 'text-emerald-600 bg-emerald-50' : 'text-rose-600 bg-rose-50'}`}>{tool.status === 'active' ? 'Làm việc' : 'Bảo trì'}</span>
                        </td>
                    </tr>
                   )
                })}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-40 w-full max-w-lg px-4">
              <div className="bg-gray-950/90 backdrop-blur-xl text-white p-4 pr-5 rounded-[2.5rem] shadow-2xl flex items-center justify-between border border-white/10 animate-fade-in-up">
                  <div className="flex items-center gap-4 pl-3">
                      <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg"><ShoppingBag className="w-6 h-6"/></div>
                      <div>
                          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Đang chọn</p>
                          <p className="text-sm font-black">{selectedToolIds.size} thiết bị</p>
                      </div>
                  </div>
                  <button 
                    onClick={handleBorrow} 
                    disabled={isSubmitting}
                    className="bg-white text-gray-950 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-2 hover:bg-blue-50 transition-all active:scale-95"
                  >
                      {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Send className="w-4 h-4" />}
                      Gửi yêu cầu
                  </button>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);

  // Mặc định tab 'personal' cho user, 'all' cho admin
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (error: any) {
      console.error("Fetch error:", error);
      showToast("Lỗi tải dữ liệu", "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const sortedAndFilteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = {
            'pending': 0,
            'approved': 1,
            'returned': 2,
            'rejected': 3
        };
        if (statusOrder[a.status] !== statusOrder[b.status]) {
            return statusOrder[a.status] - statusOrder[b.status];
        }
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => 
      req.id === id ? { ...req, status: newStatus as any, ...extraData } : req
    ));
  };

  const executeApprove = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
      const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
      const currentAvailable = tools ? Number(tools.available) : 0;
      if (currentAvailable <= 0) throw new Error("Kho đã hết thiết bị này.");

      await supabase.from('tools').update({ available: currentAvailable - 1 }).eq('id', req.tool_id);
      const { error } = await supabase.from('requests').update({ status: 'approved' }).eq('id', req.id);

      if (error) throw error;

      updateLocalRequestStatus(req.id, 'approved');
      showToast(`Đã duyệt cho ${req.user_name}`, 'success');
    } catch (error: any) {
      showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
      setProcessingId(null);
    }
  };

  const executeReject = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
        const { error } = await supabase.from('requests').update({ status: 'rejected' }).eq('id', req.id);
        if (error) throw error;

        updateLocalRequestStatus(req.id, 'rejected');
        showToast('Đã từ chối yêu cầu.', 'success');
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeReturn = async (req: BorrowRequest) => {
    setProcessingId(req.id);
    try {
        const { data: tools } = await supabase.from('tools').select('available').eq('id', req.tool_id).single();
        const currentAvailable = tools ? Number(tools.available) : 0;

        await supabase.from('tools').update({ available: currentAvailable + 1 }).eq('id', req.tool_id);
        const now = new Date().toISOString();
        const { error } = await supabase.from('requests').update({ 
            status: 'returned', 
            returned_at: now 
        }).eq('id', req.id);

        if (error) throw error;

        updateLocalRequestStatus(req.id, 'returned', { returned_at: now });
        showToast('Đã xác nhận trả thiết bị.', 'success');
    } catch (error: any) {
        showToast(`Lỗi: ${error.message}`, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const executeCancel = async (id: string) => {
    setProcessingId(id);
    try {
        const { error } = await supabase.from('requests').delete().eq('id', id);
        if (error) throw error;

        setRequests(prev => prev.filter(r => r.id !== id));
        showToast("Đã hủy yêu cầu thành công.", 'success');
    } catch (error: any) {
        showToast("Lỗi: " + error.message, 'error');
    } finally {
        setProcessingId(null);
    }
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    if (action.type === 'approve') await executeApprove(action.req);
    if (action.type === 'reject') await executeReject(action.req);
    if (action.type === 'return') await executeReturn(action.req);
    if (action.type === 'cancel') await executeCancel(action.id);
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': 
        return 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50';
      case 'approved': 
        return 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50';
      case 'returned': 
        return 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50';
      case 'rejected': 
        return 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50';
      default: 
        return 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50';
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'pending': return <Clock className="w-4 h-4" />;
      case 'approved': return <CheckCircle2 className="w-4 h-4" />;
      case 'returned': return <RotateCcw className="w-4 h-4" />;
      case 'rejected': return <Ban className="w-4 h-4" />;
      default: return <Info className="w-4 h-4" />;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'pending': return 'Đang Chờ Duyệt';
      case 'approved': return 'Đang Mượn';
      case 'returned': return 'Đã Trả';
      case 'rejected': return 'Đã Từ Chối';
      default: return 'Không xác định';
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 lg:px-0 space-y-6 animate-fade-in w-full pb-10">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="sticky top-0 lg:top-[64px] z-30 space-y-4 pt-4 pb-2 bg-gray-50/95 backdrop-blur-sm">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-5 rounded-[2rem] shadow-sm border border-gray-100">
          <div className="flex items-center gap-4">
              <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-100 flex-shrink-0">
                  <Wrench className="w-6 h-6 text-white" />
              </div>
              <div>
                  <h2 className="text-xl font-black text-gray-900 tracking-tight leading-none">
                      {activeTab === 'personal' ? 'Đồ của tôi' : 'Quản lý Đơn Mượn'}
                  </h2>
                  <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.15em] opacity-80 mt-1">Theo dõi tình trạng thiết bị</p>
              </div>
          </div>

          <div className="flex flex-wrap items-center gap-3">
              <button 
                  onClick={() => fetchRequests(true)}
                  disabled={isRefreshing}
                  className="p-3 bg-gray-50 hover:bg-gray-100 text-gray-500 rounded-2xl border border-gray-200 transition-all active:scale-95"
                  title="Làm mới dữ liệu"
              >
                  <RefreshCw className={`w-5 h-5 ${isRefreshing ? 'animate-spin text-blue-600' : ''}`} />
              </button>

              {user.role === 'admin' && (
                  <div className="flex bg-gray-100 p-1 rounded-2xl shadow-inner border border-gray-200">
                      <button
                          onClick={() => setActiveTab('all')}
                          className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${
                              activeTab === 'all' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                          }`}
                      >
                          <ShieldCheck className="w-3.5 h-3.5" />
                          HỆ THỐNG
                      </button>
                      <button
                          onClick={() => setActiveTab('personal')}
                          className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${
                              activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'
                          }`}
                      >
                          <UserIcon className="w-3.5 h-3.5" />
                          CỦA TÔI
                      </button>
                  </div>
              )}
          </div>
        </div>

        <div className="bg-white p-4 rounded-[2rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="relative group">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500 transition-colors" />
              <input 
                  type="text" 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Tìm nhân viên, thiết bị..."
                  className="w-full pl-11 pr-4 py-3 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all placeholder:text-gray-400 outline-none"
              />
          </div>

          <div className="relative group">
              <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="w-full pl-5 pr-10 py-3 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 appearance-none cursor-pointer text-gray-900 font-bold transition-all outline-none"
              >
                  <option value="all">Tất cả trạng thái</option>
                  <option value="pending">⏳ Chờ phê duyệt</option>
                  <option value="approved">✅ Đang mượn</option>
                  <option value="returned">↩️ Đã hoàn trả</option>
                  <option value="rejected">❌ Đã từ chối</option>
              </select>
              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500" />
          </div>

          <div className="relative group">
              <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-blue-500 transition-colors" />
              <input 
                  type="date"
                  value={filterStartDate}
                  onChange={(e) => setFilterStartDate(e.target.value)}
                  className="w-full pl-11 pr-4 py-3 bg-gray-50 border-2 border-transparent rounded-2xl text-sm focus:bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 text-gray-900 font-bold transition-all outline-none"
              />
          </div>
        </div>
      </div>

      <Card className="p-0 rounded-[2.5rem] shadow-xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead className="sticky top-0 z-10 bg-white">
              <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[220px] bg-gray-50">Người mượn</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[180px] bg-gray-50">Thiết bị</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[140px] bg-gray-50">Thời gian</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] min-w-[160px] text-center bg-gray-50">Trạng thái</th>
                <th className="px-8 py-5 text-gray-500 font-black uppercase tracking-[0.2em] text-[10px] text-right min-w-[180px] bg-gray-50">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-30" /></td></tr>
              ) : sortedAndFilteredRequests.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-32 text-center text-gray-400 font-bold italic opacity-60">
                    <div className="flex flex-col items-center">
                        <History className="w-16 h-16 mb-4 opacity-10" />
                        {activeTab === 'personal' ? 'Bạn chưa có yêu cầu mượn nào.' : 'Không tìm thấy dữ liệu yêu cầu nào.'}
                    </div>
                  </td>
                </tr>
              ) : (
                sortedAndFilteredRequests.map((req) => {
                  const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
                  const isOldBorrowed = req.status === 'approved' && reqDateStr !== filterStartDate;
                  const isProcessing = processingId === req.id;

                  return (
                  <tr 
                    key={req.id} 
                    className={`hover:bg-blue-50/20 transition-all duration-300 group ${req.status === 'pending' ? 'bg-amber-50/10' : ''} ${isProcessing ? 'opacity-50 pointer-events-none' : ''}`}
                  >
                    <td className="px-8 py-5 align-middle">
                        <div className="flex items-center gap-3">
                            <div className={`w-11 h-11 rounded-2xl flex items-center justify-center font-black shadow-sm border-2 transition-transform group-hover:scale-110 ${
                                req.user_id === user.id ? 'bg-gradient-to-br from-blue-500 to-indigo-700 text-white border-blue-400' : 'bg-white text-gray-400 border-gray-100'
                            }`}>
                                {req.user_name ? req.user_name.charAt(0) : '?'}
                            </div>
                            <div>
                                <div className="font-black text-gray-900 text-sm flex items-center gap-2">
                                    {req.user_name}
                                    {req.user_id === user.id && <span className="text-[8px] bg-blue-600 text-white px-2 py-0.5 rounded-lg font-black uppercase tracking-tighter">TÔI</span>}
                                </div>
                                <div className="text-[10px] text-gray-400 font-bold tracking-tighter mt-0.5 flex items-center gap-1 uppercase">
                                    <UserIcon className="w-3 h-3" />
                                    {req.employee_id}
                                </div>
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle">
                        <div className="flex items-center gap-3">
                            <div className="w-14 h-14 bg-white rounded-2xl border-2 border-gray-100 flex-shrink-0 flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-300 transition-colors shadow-sm">
                                {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-100" />}
                            </div>
                            <span className="font-black text-gray-800 text-sm leading-tight max-w-[140px] truncate" title={req.tool_name}>{req.tool_name}</span>
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle">
                        <div className="flex flex-col gap-1">
                            <div className={`flex items-center gap-1.5 font-black text-xs ${isOldBorrowed ? 'text-emerald-600' : 'text-gray-900'}`}>
                                <Calendar className="w-3 h-3 opacity-40" />
                                {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                                {isOldBorrowed && (
                                    <span className="bg-emerald-100 text-emerald-700 text-[8px] px-1.5 py-0.5 rounded uppercase font-black ml-1 border border-emerald-200">
                                        ĐANG GIỮ
                                    </span>
                                )}
                            </div>
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle text-center">
                        <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black border-2 uppercase tracking-widest shadow-lg transform group-hover:scale-105 transition-all ${getStatusStyle(req.status)}`}>
                            {getStatusIcon(req.status)}
                            {getStatusLabel(req.status)}
                        </div>
                    </td>
                    <td className="px-8 py-5 align-middle text-right">
                      <div className="flex justify-end gap-2.5 items-center">
                        {isProcessing ? (
                            <div className="w-10 h-10 flex items-center justify-center">
                                <Loader2 className="w-5 h-5 animate-spin text-blue-600" />
                            </div>
                        ) : (
                            <>
                                {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                                    <>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'approve', req })}
                                            className="w-11 h-11 flex items-center justify-center bg-emerald-600 text-white rounded-2xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-200 active:scale-90" 
                                            title="Phê duyệt"
                                        >
                                            <Check className="w-5 h-5" />
                                        </button>
                                        <button 
                                            onClick={() => setConfirmAction({ type: 'reject', req })}
                                            className="w-11 h-11 flex items-center justify-center bg-white text-rose-600 border-2 border-rose-100 rounded-2xl hover:bg-rose-50 transition-all shadow-sm active:scale-90" 
                                            title="Từ chối"
                                        >
                                            <X className="w-5 h-5" />
                                        </button>
                                    </>
                                )}

                                {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                                    <button
                                        onClick={() => setConfirmAction({ type: 'return', req })}
                                        className="flex items-center gap-2 px-5 py-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all text-[10px] font-black shadow-2xl shadow-blue-200 active:scale-95 uppercase tracking-[0.15em]"
                                    >
                                        <RotateCcw className="w-3.5 h-3.5" /> 
                                        THU HỒI
                                    </button>
                                )}

                                {(req.user_id === user.id) && req.status === 'pending' && (
                                    <button 
                                        onClick={() => setConfirmAction({ type: 'cancel', id: req.id })}
                                        className="flex items-center gap-2 text-rose-600 hover:text-white hover:bg-rose-600 border-2 border-rose-100 px-5 py-3 rounded-2xl text-[10px] font-black transition-all shadow-sm active:scale-95 uppercase tracking-[0.15em]"
                                    >
                                        <Trash2 className="w-3.5 h-3.5" />
                                        HỦY ĐƠN
                                    </button>
                                )}

                                {req.status === 'returned' && (
                                <div className="w-10 h-10 flex items-center justify-center text-emerald-500 bg-emerald-50 rounded-full border-2 border-emerald-100 shadow-inner" title="Hoàn tất">
                                    <CheckCircle2 className="w-6 h-6" />
                                </div>
                                )}

                                {req.status === 'rejected' && (
                                <div className="w-10 h-10 flex items-center justify-center text-rose-500 bg-rose-50 rounded-full border-2 border-rose-100 shadow-inner" title="Đã từ chối">
                                    <Ban className="w-6 h-6" />
                                </div>
                                )}
                            </>
                        )}
                      </div>
                    </td>
                  </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {confirmAction && (
        <div className="fixed inset-0 bg-gray-900/80 z-[100] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-10 text-center">
              <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-2xl transform rotate-6 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'cancel' || confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-10 h-10" /> : <AlertTriangle className="w-10 h-10" />}
              </div>
              <h3 className="text-xl font-black text-gray-900 mb-3 uppercase tracking-tighter leading-tight">Xác nhận?</h3>
              <p className="text-[10px] text-gray-400 font-bold leading-relaxed px-4 uppercase tracking-widest opacity-80">
                {confirmAction.type === 'approve' ? 'Duyệt mượn thiết bị và trừ tồn kho thực tế.' : 
                 confirmAction.type === 'return' ? 'Xác nhận thiết bị đã về kho an toàn.' :
                 confirmAction.type === 'reject' ? 'Từ chối yêu cầu và đóng đơn này.' :
                 'Xóa bỏ vĩnh viễn yêu cầu này khỏi hệ thống.'}
              </p>
            </div>
            <div className="bg-gray-50 p-6 flex flex-col gap-3 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction}
                className={`w-full py-4 text-white font-black rounded-[1.2rem] text-[10px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                    confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                    confirmAction.type === 'return' ? 'bg-blue-600 shadow-blue-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)}
                className="w-full py-4 bg-white text-gray-400 font-black rounded-[1.2rem] border-2 border-gray-100 hover:bg-gray-100 text-[10px] uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

