                                                <div className="flex items-center gap-1.5 px-2.5 py-0.5 bg-indigo-600 rounded-full text-white shadow-sm border border-indigo-500 animate-fade-in">
                                                    <span className="text-[11px] font-black tabular-nums">{calculatedHours}</span>
                                                    <span className="text-[9px] font-bold opacity-80 uppercase">Giờ</span>
                                                </div>
                                            </div>
                                            <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="text-[10px] font-black text-indigo-600 flex items-center gap-1.5 active:scale-95 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
                                                {isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>}
                                                AI Smart
                                            </button>
                                        </div>
                                        <textarea required value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-5 bg-white border-2 border-gray-100 rounded-[2rem] focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 text-sm h-32 resize-none text-gray-900 shadow-sm transition-all placeholder:text-gray-300 font-medium outline-none" placeholder="Lý do tăng ca..."/>
                                    </div>

                                    <div className="flex gap-4 pt-4 sticky bottom-0 bg-gray-50/50 -mx-6 px-6 pb-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} disabled={isDeleting} className="p-5 bg-white text-rose-500 border-2 border-rose-100 rounded-3xl hover:bg-rose-50 active:scale-90 shadow-sm transition-all"><Trash2 className="w-6 h-6"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0 || !targetUserId} className="flex-1 py-5 bg-gradient-to-r from-indigo-600 to-indigo-800 hover:from-indigo-700 hover:to-indigo-900 text-white font-black rounded-3xl shadow-xl shadow-indigo-100 transition-all disabled:opacity-50 flex items-center justify-center gap-3 uppercase tracking-[0.2em] text-[11px] active:scale-95">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5"/>} 
                                            {editingRequestId ? 'LƯU THAY ĐỔI' : 'GỬI ĐĂNG KÝ'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in"><div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in border border-gray-200"><div className="p-10 text-center"><div className="w-20 h-20 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-[2.5rem] shadow-xl shadow-rose-100 rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-10 h-10"/></div><h3 className="text-2xl font-black text-gray-900 mb-3 uppercase tracking-tight leading-none">HỦY ĐƠN?</h3><p className="text-[11px] text-gray-500 font-bold italic px-4 leading-relaxed uppercase opacity-70">Thao tác này sẽ xóa dữ liệu OT vĩnh viễn.</p></div><div className="p-6 bg-gray-50 flex flex-col gap-3 border-t border-gray-100"><button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl text-[11px] uppercase shadow-xl shadow-rose-100 active:scale-95 flex items-center justify-center gap-2">{isDeleting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Trash2 className="w-4 h-4"/>} XÁC NHẬN HỦY</button><button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-700 font-black rounded-2xl border border-gray-200 text-[11px] uppercase active:scale-95 transition-all">ĐÓNG</button></div></div></div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, ArrowRight, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Package, Settings2, ChevronDown, ChevronsLeft, ChevronsRight
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full ${className} transition-colors`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2 text-gray-300' : 'w-5 h-5 text-gray-400'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'} ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');

  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory, filterStatus, pageSize]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) setCurrentPage(newPage);
  };

  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); 
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    try {
        const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
        const requests: any[] = [];

        toolsToBorrow.forEach(tool => {
            const qty = quantities[tool.id] || 1;
            for(let i = 0; i < qty; i++) {
                requests.push({
                    employee_id: user.employeeCode,
                    user_id: user.id,
                    user_name: user.name,
                    tool_id: tool.id,
                    tool_name: tool.name,
                    borrow_date: new Date().toISOString(),
                    status: 'pending'
                });
            }
        });

        const { error } = await supabase.from('requests').insert(requests);

        if (!error) {
            setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
            setSelectedToolIds(new Set()); 
            setQuantities({});
            setTimeout(() => setMessage(null), 4000);
            await fetchTools();
        } else {
            alert('Có lỗi xảy ra: ' + error.message);
        }
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32">
      <div className="flex flex-col gap-4 bg-white p-5 rounded-3xl shadow-sm border border-gray-100 transition-all">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div>
                <h2 className="text-2xl font-black text-gray-900 flex items-center gap-3 tracking-tight">
                    Kho công cụ
                    {!isAdmin && <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-widest border border-indigo-100">Chế độ Mượn</span>}
                </h2>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1 opacity-70">Quản lý & Theo dõi tài sản</p>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && (
                <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100 whitespace-nowrap">
                    <CheckCircle2 className="w-5 h-5" />
                    {message}
                </div>
                )}

                {isAdmin && (
                    <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <Settings2 className="w-4 h-4" />
                            QUẢN LÝ
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <ShoppingBag className="w-4 h-4" />
                            MƯỢN ĐỒ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><List className="w-5 h-5" /></button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-2xl flex items-center gap-2 text-sm font-black transition-all shadow-xl shadow-indigo-100 w-full sm:w-auto justify-center whitespace-nowrap active:scale-95 uppercase tracking-widest"
                    >
                        <Plus className="w-5 h-5" />
                        THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500 transition-colors" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-12 pr-4 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 transition-all text-gray-900 placeholder:text-gray-400 outline-none"
                />
            </div>

            <div className="flex gap-3 w-full md:w-auto">
                <div className="relative flex-1 sm:min-w-[180px] group">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-5 pr-10 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>

                <div className="relative flex-1 sm:min-w-[180px] group">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-5 pr-10 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Bảo trì</option>
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>
            </div>
        </div>
      </div>

      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all relative overflow-hidden group flex flex-col h-full p-0 border-2 ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-500/5 transform scale-[1.02]' : 'border-transparent bg-white shadow-lg'}`} onClick={() => !isManageMode && selectable && toggleSelection(tool.id)}>
                    <div className="h-56 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        {tool.status === 'inactive' ? <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Bảo trì</span> : tool.available > 0 ? <span className="bg-emerald-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Sẵn có: {tool.available}</span> : <span className="bg-gray-400 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Hết hàng</span>}
                      </div>
                    </div>

                    <div className="p-6 flex-1 flex flex-col bg-white">
                      <div className="mb-4">
                        <h3 className="font-black text-gray-900 text-lg line-clamp-2 min-h-[3.5rem] leading-tight tracking-tight">{tool.name}</h3>
                        <div className="flex items-center gap-2 mt-2">
                            <span className="text-[10px] font-black uppercase tracking-tighter text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md">{tool.category}</span>
                            <div className="flex items-center gap-1 text-[10px] text-gray-400 font-bold uppercase tracking-tighter">
                                <MapPin className="w-3 h-3 opacity-50" />
                                {tool.location || 'N/A'}
                            </div>
                        </div>
                      </div>

                      <div className="mt-auto">
                        {isManageMode ? (
                          <div className="flex gap-3 pt-4 border-t border-gray-50" onClick={e => e.stopPropagation()}>
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-white hover:bg-indigo-50 text-indigo-700 border-2 border-indigo-100 py-3 rounded-2xl text-xs font-black transition-all flex items-center justify-center gap-2 uppercase tracking-widest"><Edit className="w-4 h-4" /> Sửa</button>
                             <button onClick={() => setToolToDelete(tool.id)} className="p-3 bg-white hover:bg-rose-50 text-rose-600 border-2 border-rose-100 rounded-2xl transition-all"><Trash2 className="w-5 h-5" /></button>
                          </div>
                        ) : (
                          isSelected ? (
                              <div className="flex items-center justify-between bg-indigo-600 rounded-2xl p-1.5 shadow-xl animate-fade-in-up border-2 border-indigo-500" onClick={e => e.stopPropagation()}>
                                  <button onClick={() => changeQuantity(tool.id, -1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-indigo-500/50 hover:bg-white/20 rounded-xl text-white transition-all"><Minus className="w-5 h-5" /></button>
                                  <div className="flex flex-col items-center"><span className="text-[10px] font-black uppercase text-indigo-200 tracking-widest leading-none mb-1">Số lượng</span><span className="font-black text-white text-xl tabular-nums leading-none">{qty}</span></div>
                                  <button onClick={() => changeQuantity(tool.id, 1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-white text-indigo-600 rounded-xl shadow-lg transition-all disabled:opacity-50" disabled={qty >= Number(tool.available)}><Plus className="w-5 h-5" /></button>
                              </div>
                          ) : (
                              <button disabled={!selectable} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-4 rounded-2xl text-sm font-black transition-all disabled:opacity-50 disabled:bg-gray-100 flex items-center justify-center gap-3 uppercase tracking-[0.15em]">
                                <PackagePlus className="w-5 h-5" /> CHỌN MƯỢN
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[2.5rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="px-8 py-6 w-24 text-[10px] font-black uppercase tracking-widest text-gray-400">Hình</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Tên thiết bị</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Danh mục</th>
                    <th className="px-8 py-6 text-center text-[10px] font-black uppercase tracking-widest text-gray-400">Kho/Sẵn</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-8 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => {
                      const isSelected = selectedToolIds.has(tool.id);
                      return (
                      <tr key={tool.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-50/50' : 'hover:bg-blue-50/30'}`} onClick={() => !isManageMode && isSelectable(tool) && toggleSelection(tool.id)}>
                        <td className="px-8 py-6"><div className="w-14 h-14 rounded-2xl bg-white border-2 border-gray-100 overflow-hidden flex items-center justify-center p-2 shadow-sm"><ToolThumbnail src={tool.image} alt={tool.name} mode="table" /></div></td>
                        <td className="px-8 py-6 font-black text-gray-900">{tool.name}</td>
                        <td className="px-8 py-6 text-xs font-bold text-gray-500">{tool.category}</td>
                        <td className="px-8 py-6 text-center text-sm font-black">{tool.available} / {tool.quantity}</td>
                        <td className="px-8 py-6">{tool.status === 'active' ? <span className="text-emerald-700 text-[9px] font-black uppercase bg-emerald-50 px-3 py-1 rounded-full tracking-widest">Hoạt động</span> : <span className="text-rose-700 text-[9px] font-black uppercase bg-rose-50 px-3 py-1 rounded-full tracking-widest">Bảo trì</span>}</td>
                        <td className="px-8 py-6 text-right" onClick={e => e.stopPropagation()}>{isManageMode ? <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-gray-50 rounded-2xl"><Edit className="w-5 h-5"/></button> : <div className="flex justify-end">{isSelected ? <span className="text-indigo-600 font-black">Đã chọn</span> : <button disabled={!isSelectable(tool)} className="p-3 bg-indigo-600 text-white rounded-2xl disabled:opacity-50"><PackagePlus className="w-5 h-5"/></button>}</div>}</td>
                      </tr>
                      );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-0 right-0 z-[100] flex justify-center px-4 md:px-8 pointer-events-none">
             <div className="bg-gray-950/90 backdrop-blur-2xl text-white p-3 pr-4 rounded-[2.5rem] shadow-2xl flex items-center gap-6 pointer-events-auto animate-fade-in-up border border-white/10 w-full max-w-2xl mx-auto">
                <div className="flex items-center gap-4 pl-3">
                    <div className="bg-indigo-600 rounded-[1.5rem] w-14 h-14 flex items-center justify-center font-black text-2xl shadow-xl border-2 border-indigo-400">
                        {totalItemsSelected}
                    </div>
                    <div className="flex flex-col"><span className="text-[10px] text-gray-400 uppercase tracking-widest font-black opacity-80 mb-0.5">Xác nhận mượn</span><div className="flex items-center gap-2"><span className="font-black text-lg text-white tracking-tight">{selectedToolIds.size}</span><span className="text-xs font-bold text-gray-400 uppercase">loại thiết bị</span></div></div>
                </div>
                <div className="flex-1 flex items-center gap-4 justify-end">
                    <button onClick={() => { setSelectedToolIds(new Set()); setQuantities({}); }} className="text-gray-400 hover:text-white text-[10px] font-black uppercase tracking-widest px-4">HỦY BỎ</button>
                    <button onClick={handleBulkBorrow} disabled={isBulkProcessing} className="bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-4 rounded-[1.5rem] font-black shadow-2xl transition-all flex items-center gap-3 uppercase tracking-widest text-[11px]">
                        {isBulkProcessing ? <Loader2 className="w-5 h-5 animate-spin"/> : <Send className="w-5 h-5" />} GỬI YÊU CẦU
                    </button>
                </div>
             </div>
          </div>
      )}

      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-zoom-in">
            <div className="flex justify-between items-center p-8 border-b border-gray-100 sticky top-0 bg-white z-10">
              <h3 className="text-xl font-black text-gray-900 uppercase tracking-tight">{isEditing ? 'Cập nhật công cụ' : 'Thêm mới'}</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="w-6 h-6 text-gray-400"/></button>
            </div>
            <div className="p-8 space-y-6">
              <input type="text" placeholder="Tên thiết bị" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"><option>Thiết bị cầm tay</option><option>Máy móc lớn</option><option>Đồ bảo hộ</option></select>
              <div className="grid grid-cols-2 gap-4">
                  <input type="number" placeholder="Tổng số" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
                  <input type="number" placeholder="Sẵn có" value={formData.available} onChange={e => setFormData({...formData, available: parseInt(e.target.value) || 0})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
              </div>
              <input type="text" placeholder="URL Hình ảnh" value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
              <button onClick={handleSaveTool} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest text-xs flex items-center justify-center gap-2"><Save className="w-5 h-5"/> {isEditing ? 'LƯU THAY ĐỔI' : 'THÊM MỚI'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const sortedAndFilteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = { 'pending': 0, 'approved': 1, 'returned': 2, 'rejected': 3 };
        if (statusOrder[a.status] !== statusOrder[b.status]) return statusOrder[a.status] - statusOrder[b.status];
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus as any, ...extraData } : req));
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    setProcessingId(action.type === 'cancel' ? action.id : action.req.id);

    try {
        if (action.type === 'approve') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            if ((tool?.available || 0) <= 0) throw new Error("Hết hàng");
            await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'approved' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'approved');
        } else if (action.type === 'return') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'returned');
        } else if (action.type === 'cancel') {
            await supabase.from('requests').delete().eq('id', action.id);
            setRequests(prev => prev.filter(r => r.id !== action.id));
        } else if (action.type === 'reject') {
            await supabase.from('requests').update({ status: 'rejected' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'rejected');
        }
        showToast("Thành công", "success");
    } catch (e: any) {
        showToast(e.message, "error");
    } finally {
        setProcessingId(null);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in w-full pb-10">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-3xl shadow-lg shadow-blue-100"><Wrench className="w-7 h-7 text-white" /></div>
            <div><h2 className="text-2xl font-black text-gray-900 tracking-tight">{activeTab === 'personal' ? 'Đồ của tôi' : 'Quản lý Đơn Mượn'}</h2><p className="text-sm text-gray-400 font-black uppercase tracking-[0.15em] opacity-80">Theo dõi & Phê duyệt</p></div>
        </div>
        <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
            {user.role === 'admin' && <button onClick={() => setActiveTab('all')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all ${activeTab === 'all' ? 'bg-white text-blue-700 shadow-md' : 'text-gray-500'}`}>HỆ THỐNG</button>}
            <button onClick={() => setActiveTab('personal')} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all ${activeTab === 'personal' ? 'bg-white text-blue-700 shadow-md' : 'text-gray-500'}`}>CỦA TÔI</button>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
        <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Tìm nhân viên, thiết bị..." className="w-full px-5 py-4 bg-gray-50 rounded-2xl text-sm font-bold outline-none"/>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="w-full px-5 py-4 bg-gray-50 rounded-2xl text-sm font-bold outline-none"><option value="all">Tất cả</option><option value="pending">⏳ Chờ duyệt</option><option value="approved">✅ Đang mượn</option><option value="returned">↩️ Đã trả</option></select>
        <input type="date" value={filterStartDate} onChange={e => setFilterStartDate(e.target.value)} className="w-full px-5 py-4 bg-gray-50 rounded-2xl text-sm font-bold outline-none"/>
      </div>

      <Card className="p-0 rounded-[2.5rem] shadow-xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100"><th className="px-8 py-6 text-gray-500 font-black uppercase text-[10px]">Người mượn</th><th className="px-8 py-6 text-gray-500 font-black uppercase text-[10px]">Thiết bị</th><th className="px-8 py-6 text-gray-500 font-black uppercase text-[10px]">Thời gian</th><th className="px-8 py-6 text-gray-500 font-black uppercase text-[10px] text-center">Trạng thái</th><th className="px-8 py-6 text-gray-500 font-black uppercase text-[10px] text-right">Thao tác</th></tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {sortedAndFilteredRequests.map((req) => (
                <tr key={req.id} className="hover:bg-blue-50/20 transition-all group">
                    <td className="px-8 py-6"><div className="flex items-center gap-4"><div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black">{req.user_name?.charAt(0)}</div><div><p className="font-black text-gray-900 text-sm">{req.user_name}</p><p className="text-[10px] text-gray-400 font-bold">{req.employee_id}</p></div></div></td>
                    <td className="px-8 py-6"><p className="font-black text-gray-800 text-sm">{req.tool_name}</p></td>
                    <td className="px-8 py-6 text-xs font-black text-gray-500">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</td>
                    <td className="px-8 py-6 text-center"><span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-[10px] font-black uppercase tracking-widest">{req.status}</span></td>
                    <td className="px-8 py-6 text-right">
                        <div className="flex justify-end gap-2">
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                            <button onClick={() => setConfirmAction({ type: 'approve', req })} className="p-3 bg-emerald-600 text-white rounded-xl shadow-lg"><Check className="w-4 h-4"/></button>
                        )}
                        {req.user_id === user.id && req.status === 'pending' && (
                            <button onClick={() => setConfirmAction({ type: 'cancel', id: req.id })} className="p-3 bg-rose-50 text-rose-600 border-2 border-rose-100 rounded-xl"><Trash2 className="w-4 h-4"/></button>
                        )}
                        {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                            <button onClick={() => setConfirmAction({ type: 'return', req })} className="px-4 py-2 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase">THU HỒI</button>
                        )}
                        </div>
                    </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      {confirmAction && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter">Xác nhận?</h3>
              <p className="text-[12px] text-gray-400 font-bold leading-relaxed px-4 uppercase tracking-widest opacity-80">Thực hiện thay đổi trạng thái yêu cầu.</p>
            </div>
            <div className="bg-gray-50 p-8 flex flex-col gap-3 border-t border-gray-100">
              <button onClick={handleConfirmAction} className="w-full py-5 bg-blue-600 text-white font-black rounded-[1.5rem] text-xs uppercase shadow-2xl">XÁC NHẬN</button>
              <button onClick={() => setConfirmAction(null)} className="w-full py-5 bg-white text-gray-400 font-black rounded-[1.5rem] border-2 border-gray-100 text-xs uppercase">HỦY BỎ</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, ArrowRight, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Package, Settings2, ChevronDown, ChevronsLeft, ChevronsRight,
  CheckCircle2, Trash2
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full ${className} transition-colors`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2 text-gray-300' : 'w-5 h-5 text-gray-400'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'} ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');

  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory, filterStatus, pageSize]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) setCurrentPage(newPage);
  };

  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); 
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    try {
        const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
        const requests: any[] = [];

        toolsToBorrow.forEach(tool => {
            const qty = quantities[tool.id] || 1;
            for(let i = 0; i < qty; i++) {
                requests.push({
                    employee_id: user.employeeCode,
                    user_id: user.id,
                    user_name: user.name,
                    tool_id: tool.id,
                    tool_name: tool.name,
                    borrow_date: new Date().toISOString(),
                    status: 'pending'
                });
            }
        });

        const { error } = await supabase.from('requests').insert(requests);

        if (!error) {
            setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
            setSelectedToolIds(new Set()); 
            setQuantities({});
            setTimeout(() => setMessage(null), 4000);
            await fetchTools();
        } else {
            alert('Có lỗi xảy ra: ' + error.message);
        }
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32">
      <div className="flex flex-col gap-4 bg-white p-5 rounded-3xl shadow-sm border border-gray-100 transition-all">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div>
                <h2 className="text-2xl font-black text-gray-900 flex items-center gap-3 tracking-tight">
                    Kho công cụ
                    {!isAdmin && <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-widest border border-indigo-100">Chế độ Mượn</span>}
                </h2>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1 opacity-70">Quản lý & Theo dõi tài sản</p>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && (
                <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100 whitespace-nowrap">
                    <CheckCircle2 className="w-5 h-5" />
                    {message}
                </div>
                )}

                {isAdmin && (
                    <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <Settings2 className="w-4 h-4" />
                            QUẢN LÝ
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-md transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <ShoppingBag className="w-4 h-4" />
                            MƯỢN ĐỒ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><List className="w-5 h-5" /></button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-2xl flex items-center gap-2 text-sm font-black transition-all shadow-xl shadow-indigo-100 w-full sm:w-auto justify-center whitespace-nowrap active:scale-95 uppercase tracking-widest"
                    >
                        <Plus className="w-5 h-5" />
                        THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500 transition-colors" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-12 pr-4 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 transition-all text-gray-900 placeholder:text-gray-400 outline-none"
                />
            </div>

            <div className="flex gap-3 w-full md:w-auto">
                <div className="relative flex-1 sm:min-w-[180px] group">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-5 pr-10 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>

                <div className="relative flex-1 sm:min-w-[180px] group">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-5 pr-10 py-3.5 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Bảo trì</option>
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>
            </div>
        </div>
      </div>

      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all relative overflow-hidden group flex flex-col h-full p-0 border-2 ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-500/5 transform scale-[1.02]' : 'border-transparent bg-white shadow-lg'}`} onClick={() => !isManageMode && selectable && toggleSelection(tool.id)}>
                    <div className="h-56 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        {tool.status === 'inactive' ? <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Bảo trì</span> : tool.available > 0 ? <span className="bg-emerald-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Sẵn có: {tool.available}</span> : <span className="bg-gray-400 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Hết hàng</span>}
                      </div>
                    </div>

                    <div className="p-6 flex-1 flex flex-col bg-white">
                      <div className="mb-4">
                        <h3 className="font-black text-gray-900 text-lg line-clamp-2 min-h-[3.5rem] leading-tight tracking-tight">{tool.name}</h3>
                        <div className="flex items-center gap-2 mt-2">
                            <span className="text-[10px] font-black uppercase tracking-tighter text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md">{tool.category}</span>
                            <div className="flex items-center gap-1 text-[10px] text-gray-400 font-bold uppercase tracking-tighter">
                                <MapPin className="w-3 h-3 opacity-50" />
                                {tool.location || 'N/A'}
                            </div>
                        </div>
                      </div>

                      <div className="mt-auto">
                        {isManageMode ? (
                          <div className="flex gap-3 pt-4 border-t border-gray-50" onClick={e => e.stopPropagation()}>
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-white hover:bg-indigo-50 text-indigo-700 border-2 border-indigo-100 py-3 rounded-2xl text-xs font-black transition-all flex items-center justify-center gap-2 uppercase tracking-widest"><Edit className="w-4 h-4" /> Sửa</button>
                             <button onClick={() => setToolToDelete(tool.id)} className="p-3 bg-white hover:bg-rose-50 text-rose-600 border-2 border-rose-100 rounded-2xl transition-all"><Trash2 className="w-5 h-5" /></button>
                          </div>
                        ) : (
                          isSelected ? (
                              <div className="flex items-center justify-between bg-indigo-600 rounded-2xl p-1.5 shadow-xl animate-fade-in-up border-2 border-indigo-500" onClick={e => e.stopPropagation()}>
                                  <button onClick={() => changeQuantity(tool.id, -1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-indigo-500/50 hover:bg-white/20 rounded-xl text-white transition-all"><Minus className="w-5 h-5" /></button>
                                  <div className="flex flex-col items-center"><span className="text-[10px] font-black uppercase text-indigo-200 tracking-widest leading-none mb-1">Số lượng</span><span className="font-black text-white text-xl tabular-nums leading-none">{qty}</span></div>
                                  <button onClick={() => changeQuantity(tool.id, 1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-white text-indigo-600 rounded-xl shadow-lg transition-all disabled:opacity-50" disabled={qty >= Number(tool.available)}><Plus className="w-5 h-5" /></button>
                              </div>
                          ) : (
                              <button disabled={!selectable} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-4 rounded-2xl text-sm font-black transition-all disabled:opacity-50 disabled:bg-gray-100 flex items-center justify-center gap-3 uppercase tracking-[0.15em]">
                                <PackagePlus className="w-5 h-5" /> CHỌN MƯỢN
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[2.5rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="px-8 py-6 w-24 text-[10px] font-black uppercase tracking-widest text-gray-400">Hình</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Tên thiết bị</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Danh mục</th>
                    <th className="px-8 py-6 text-center text-[10px] font-black uppercase tracking-widest text-gray-400">Kho/Sẵn</th>
                    <th className="px-8 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-8 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => {
                      const isSelected = selectedToolIds.has(tool.id);
                      return (
                      <tr key={tool.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-50/50' : 'hover:bg-blue-50/30'}`} onClick={() => !isManageMode && isSelectable(tool) && toggleSelection(tool.id)}>
                        <td className="px-8 py-6"><div className="w-14 h-14 rounded-2xl bg-white border-2 border-gray-100 overflow-hidden flex items-center justify-center p-2 shadow-sm"><ToolThumbnail src={tool.image} alt={tool.name} mode="table" /></div></td>
                        <td className="px-8 py-6 font-black text-gray-900">{tool.name}</td>
                        <td className="px-8 py-6 text-xs font-bold text-gray-500">{tool.category}</td>
                        <td className="px-8 py-6 text-center text-sm font-black">{tool.available} / {tool.quantity}</td>
                        <td className="px-8 py-6">{tool.status === 'active' ? <span className="text-emerald-700 text-[9px] font-black uppercase bg-emerald-50 px-3 py-1 rounded-full tracking-widest">Hoạt động</span> : <span className="text-rose-700 text-[9px] font-black uppercase bg-rose-50 px-3 py-1 rounded-full tracking-widest">Bảo trì</span>}</td>
                        <td className="px-8 py-6 text-right" onClick={e => e.stopPropagation()}>{isManageMode ? <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-gray-50 rounded-2xl"><Edit className="w-5 h-5"/></button> : <div className="flex justify-end">{isSelected ? <span className="text-indigo-600 font-black">Đã chọn</span> : <button disabled={!isSelectable(tool)} className="p-3 bg-indigo-600 text-white rounded-2xl disabled:opacity-50"><PackagePlus className="w-5 h-5"/></button>}</div>}</td>
                      </tr>
                      );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-0 right-0 z-[100] flex justify-center px-4 md:px-8 pointer-events-none">
             <div className="bg-gray-950/90 backdrop-blur-2xl text-white p-3 pr-4 rounded-[2.5rem] shadow-2xl flex items-center gap-6 pointer-events-auto animate-fade-in-up border border-white/10 w-full max-w-2xl mx-auto">
                <div className="flex items-center gap-4 pl-3">
                    <div className="bg-indigo-600 rounded-[1.5rem] w-14 h-14 flex items-center justify-center font-black text-2xl shadow-xl border-2 border-indigo-400">
                        {totalItemsSelected}
                    </div>
                    <div className="flex flex-col"><span className="text-[10px] text-gray-400 uppercase tracking-widest font-black opacity-80 mb-0.5">Xác nhận mượn</span><div className="flex items-center gap-2"><span className="font-black text-lg text-white tracking-tight">{selectedToolIds.size}</span><span className="text-xs font-bold text-gray-400 uppercase">loại thiết bị</span></div></div>
                </div>
                <div className="flex-1 flex items-center gap-4 justify-end">
                    <button onClick={() => { setSelectedToolIds(new Set()); setQuantities({}); }} className="text-gray-400 hover:text-white text-[10px] font-black uppercase tracking-widest px-4">HỦY BỎ</button>
                    <button onClick={handleBulkBorrow} disabled={isBulkProcessing} className="bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-4 rounded-[1.5rem] font-black shadow-2xl transition-all flex items-center gap-3 uppercase tracking-widest text-[11px]">
                        {isBulkProcessing ? <Loader2 className="w-5 h-5 animate-spin"/> : <Send className="w-5 h-5" />} GỬI YÊU CẦU
                    </button>
                </div>
             </div>
          </div>
      )}

      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-zoom-in">
            <div className="flex justify-between items-center p-8 border-b border-gray-100 sticky top-0 bg-white z-10">
              <h3 className="text-xl font-black text-gray-900 uppercase tracking-tight">{isEditing ? 'Cập nhật công cụ' : 'Thêm mới'}</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="w-6 h-6 text-gray-400"/></button>
            </div>
            <div className="p-8 space-y-6">
              <input type="text" placeholder="Tên thiết bị" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
              <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"><option>Thiết bị cầm tay</option><option>Máy móc lớn</option><option>Đồ bảo hộ</option></select>
              <div className="grid grid-cols-2 gap-4">
                  <input type="number" placeholder="Tổng số" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
                  <input type="number" placeholder="Sẵn có" value={formData.available} onChange={e => setFormData({...formData, available: parseInt(e.target.value) || 0})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
              </div>
              <input type="text" placeholder="URL Hình ảnh" value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none"/>
              <button onClick={handleSaveTool} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest text-xs flex items-center justify-center gap-2"><Save className="w-5 h-5"/> {isEditing ? 'LƯU THAY ĐỔI' : 'THÊM MỚI'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (err: any) {
        showToast("Không thể tải dữ liệu: " + err.message, "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const sortedAndFilteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = { 'pending': 0, 'approved': 1, 'returned': 2, 'rejected': 3 };
        if (statusOrder[a.status] !== statusOrder[b.status]) return statusOrder[a.status] - statusOrder[b.status];
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus as any, ...extraData } : req));
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    setProcessingId(action.type === 'cancel' ? action.id : action.req.id);

    try {
        if (action.type === 'approve') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
            await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'approved' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'approved');
        } else if (action.type === 'return') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'returned');
        } else if (action.type === 'cancel') {
            await supabase.from('requests').delete().eq('id', action.id);
            setRequests(prev => prev.filter(r => r.id !== action.id));
        } else if (action.type === 'reject') {
            await supabase.from('requests').update({ status: 'rejected' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'rejected');
        }
        showToast("Thao tác thành công!", "success");
    } catch (e: any) {
        showToast(e.message, "error");
    } finally {
        setProcessingId(null);
    }
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': return 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50';
      case 'approved': return 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50';
      case 'returned': return 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50';
      case 'rejected': return 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50';
      default: return 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50';
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in w-full pb-20">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100"><Wrench className="w-8 h-8 text-white" /></div>
            <div>
              <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">
                {activeTab === 'personal' ? 'Yêu cầu của tôi' : 'Quản lý Đơn Mượn'}
              </h2>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                {activeTab === 'personal' ? 'Theo dõi lịch sử cá nhân' : 'Quản lý toàn bộ hệ thống'}
              </p>
            </div>
        </div>

        <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
            {user.role === 'admin' && (
              <button 
                onClick={() => setActiveTab('all')} 
                className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
              >
                HỆ THỐNG
              </button>
            )}
            <button 
              onClick={() => setActiveTab('personal')} 
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
            >
              CỦA TÔI
            </button>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative group flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm nhân viên, thiết bị..." 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none transition-all"
          />
        </div>

        <div className="relative group">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ phê duyệt</option>
            <option value="approved">✅ Đang mượn</option>
            <option value="returned">↩️ Đã hoàn trả</option>
          </select>
          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative group">
          <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input 
            type="date" 
            value={filterStartDate} 
            onChange={e => setFilterStartDate(e.target.value)} 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          />
        </div>
      </div>

      <Card className="p-0 rounded-[3rem] shadow-2xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Người mượn</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thiết bị</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thời gian</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-center bg-gray-50/50">Trạng thái</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-right bg-gray-50/50">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : sortedAndFilteredRequests.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                sortedAndFilteredRequests.map((req) => (
                  <tr key={req.id} className="hover:bg-blue-50/20 transition-all duration-300 group">
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-[1rem] bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-lg border-2 border-indigo-400 transition-transform group-hover:scale-110 group-hover:rotate-3">
                          {req.user_name?.charAt(0)}
                        </div>
                        <div>
                          <p className="font-black text-gray-900 text-sm tracking-tight">{req.user_name}</p>
                          <p className="text-[10px] text-gray-400 font-black tracking-widest uppercase opacity-70 mt-0.5">{req.employee_id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                         <div className="w-14 h-14 bg-white border-2 border-gray-50 rounded-2xl flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-200 transition-colors shadow-sm">
                           {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-200" />}
                         </div>
                         <p className="font-black text-gray-800 text-sm leading-tight max-w-[200px]">{req.tool_name}</p>
                      </div>
                    </td>
                    <td className="px-10 py-6 text-[11px] font-black text-gray-500 uppercase tracking-tighter">
                      <div className="flex items-center gap-2">
                        <Calendar className="w-3.5 h-3.5 opacity-30" />
                        {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                      </div>
                    </td>
                    <td className="px-10 py-6 text-center">
                      <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 shadow-lg transition-all group-hover:scale-105 ${getStatusStyle(req.status)}`}>
                        {req.status === 'pending' ? <Clock className="w-3.5 h-3.5" /> : req.status === 'approved' ? <CheckCircle2 className="w-3.5 h-3.5" /> : <Info className="w-3.5 h-3.5" />}
                        {req.status === 'pending' ? 'Chờ Duyệt' : req.status === 'approved' ? 'Đang Mượn' : req.status === 'returned' ? 'Đã Trả' : 'Từ Chối'}
                      </div>
                    </td>
                    <td className="px-10 py-6 text-right">
                      <div className="flex justify-end gap-3 items-center">
                        {processingId === req.id ? (
                          <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                        ) : (
                          <>
                            {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                              <>
                                <button 
                                  onClick={() => setConfirmAction({ type: 'approve', req })} 
                                  className="w-11 h-11 bg-emerald-600 text-white rounded-[1rem] flex items-center justify-center shadow-lg shadow-emerald-100 hover:bg-emerald-700 transition-all active:scale-90"
                                  title="Duyệt yêu cầu"
                                >
                                  <Check className="w-6 h-6" />
                                </button>
                                <button 
                                  onClick={() => setConfirmAction({ type: 'reject', req })} 
                                  className="w-11 h-11 bg-white text-rose-600 border-2 border-rose-50 rounded-[1rem] flex items-center justify-center hover:bg-rose-50 transition-all active:scale-90"
                                  title="Từ chối"
                                >
                                  <X className="w-6 h-6" />
                                </button>
                              </>
                            )}

                            {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                              <button 
                                onClick={() => setConfirmAction({ type: 'return', req })} 
                                className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
                              >
                                <RotateCcw className="w-4 h-4" /> THU HỒI
                              </button>
                            )}

                            {req.user_id === user.id && req.status === 'pending' && (
                              <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })} 
                                className="flex items-center gap-2 px-6 py-3 bg-white text-rose-600 border-2 border-rose-100 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all active:scale-95"
                              >
                                <Trash2 className="w-4 h-4" /> HỦY ĐƠN
                              </button>
                            )}
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* CONFIRM MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl rotate-12 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-12 h-12" /> : <AlertTriangle className="w-12 h-12" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xác nhận?</h3>
              <p className="text-[11px] text-gray-400 font-bold leading-relaxed px-6 uppercase tracking-[0.15em] opacity-80 italic">
                {confirmAction.type === 'approve' ? 'Duyệt yêu cầu này và cập nhật tồn kho.' : 'Bạn có chắc chắn muốn thực hiện thao tác này?'}
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction} 
                className={`w-full py-5 text-white font-black rounded-3xl text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                  confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)} 
                className="w-full py-5 bg-white text-gray-400 font-black rounded-3xl border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Sidebar } from './src/components/layout/Sidebar';
import { Header } from './src/components/layout/Header';
import { LoginForm } from './src/components/auth/LoginForm';
import { DashboardStats } from './src/components/dashboard/DashboardStats';
import { EmployeeList } from './src/components/employees/EmployeeList';
import { ToolInventory } from './src/components/tools/ToolInventory';
import { RequestManager } from './src/components/requests/RequestManager';
import { HistoryLog } from './src/components/history/HistoryLog';
import { OvertimeRegistration } from './src/components/overtime/OvertimeRegistration';
import { generateManagerInsight } from './src/services/geminiService';
import { Bot, X, Send, Menu } from 'lucide-react';
import { supabase } from './src/lib/supabase';
import { User } from './types';

const MainLayout: React.FC<{ children: React.ReactNode; user: User; onLogout: () => void }> = ({ children, user, onLogout }) => {
  const location = useLocation();
  const [currentPath, setCurrentPath] = useState(location.pathname);
  const [showAiChat, setShowAiChat] = useState(false);
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    setCurrentPath(location.pathname);
    setIsSidebarOpen(false);
  }, [location]);

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!aiQuery.trim()) return;

    setAiLoading(true);
    const context = `User Role: ${user.role}. Tổng nhân viên: 124. Công cụ: 856.`;
    const result = await generateManagerInsight(context, aiQuery);
    setAiResponse(result || "Không có phản hồi.");
    setAiLoading(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      {/* Sidebar - Dính ở bên trái trên Desktop */}
      <Sidebar 
        currentPath={currentPath} 
        onNavigate={(path) => window.location.hash = path} 
        onLogout={onLogout}
        userRole={user.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Backdrop cho mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">
        <Header user={user} onMenuClick={() => setIsSidebarOpen(true)} />
        <main className="flex-1 p-4 md:p-8">
          {children}
        </main>
      </div>

      {/* AI Assistant Button */}
      <div className="fixed bottom-6 right-6 z-50">
        {!showAiChat ? (
          <button 
            onClick={() => setShowAiChat(true)}
            className="w-14 h-14 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white hover:shadow-xl transition-all transform hover:scale-110 active:scale-95 border-4 border-white"
          >
            <Bot className="w-7 h-7" />
          </button>
        ) : (
          <div className="bg-white rounded-2xl shadow-2xl w-[calc(100vw-2rem)] sm:w-96 flex flex-col border border-gray-200 overflow-hidden animate-fade-in-up origin-bottom-right">
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-4 flex justify-between items-center text-white">
              <div className="flex items-center gap-2">
                <Bot className="w-5 h-5" />
                <span className="font-semibold">Trợ lý Quản lý</span>
              </div>
              <button onClick={() => setShowAiChat(false)} className="hover:bg-white/20 p-1 rounded transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 h-64 overflow-y-auto bg-gray-50 text-sm">
              {!aiResponse && !aiLoading && (
                <p className="text-gray-500 text-center mt-20">Hãy hỏi tôi về dữ liệu nhân sự, công cụ hoặc xu hướng...</p>
              )}
              {aiLoading && (
                <div className="flex items-center justify-center h-full">
                   <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                </div>
              )}
              {aiResponse && (
                <div className="prose prose-sm max-w-none text-gray-800 whitespace-pre-line">
                  {aiResponse}
                </div>
              )}
            </div>

            <form onSubmit={handleAiAsk} className="p-3 border-t bg-white flex gap-2">
              <input 
                type="text" 
                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Hỏi trợ lý..."
                className="flex-1 px-3 py-2 border rounded-xl focus:outline-none focus:border-blue-500 text-sm shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 disabled:opacity-50 transition-colors shadow-md"
              >
                <Send className="w-4 h-4" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return <div className="h-screen flex items-center justify-center"><div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div></div>;
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
        } />

        {/* Protected Routes */}
        <Route path="/dashboard" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/employees" element={
          user ? (
             user.role === 'admin' ? (
                <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
             ) : <Navigate to="/dashboard" />
          ) : <Navigate to="/login" />
        } />

        <Route path="/tools" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/requests" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/history" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/overtime" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Bell, User, CheckCircle2, XCircle, Clock, Info, ChevronRight, Loader2, Menu } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, OvertimeRequest } from '../../../types';

interface HeaderProps {
  user: any;
  onMenuClick?: () => void;
}

interface NotificationItem {
  id: string;
  type: 'borrow' | 'overtime';
  title: string;
  message: string;
  time: string;
  status: 'pending' | 'approved' | 'rejected' | 'returned';
  isRead: boolean;
}

export const Header: React.FC<HeaderProps> = ({ user, onMenuClick }) => {
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchNotifications = async () => {
    if (!user) return;
    setLoading(true);

    try {
      const isAdmin = user.role === 'admin';
      const notifs: NotificationItem[] = [];

      let borrowQuery = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false })
        .limit(10);

      if (!isAdmin) {
        borrowQuery = borrowQuery.eq('user_id', user.id);
      }

      const { data: borrowData } = await borrowQuery;

      if (borrowData) {
        (borrowData as BorrowRequest[]).forEach(req => {
          let shouldNotify = false;
          let title = '';
          let message = '';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Yêu cầu mượn mới';
              message = `${req.user_name} muốn mượn ${req.tool_name}`;
            }
          } else {
            if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Cập nhật yêu cầu mượn';
              const statusText = req.status === 'approved' ? 'được duyệt' : req.status === 'rejected' ? 'bị từ chối' : 'đã trả';
              message = `Yêu cầu mượn "${req.tool_name}" đã ${statusText}`;
            }
          }

          if (shouldNotify) {
            notifs.push({
              id: `borrow-${req.id}`,
              type: 'borrow',
              title,
              message,
              time: req.borrow_date,
              status: req.status,
              isRead: false
            });
          }
        });
      }

      let otQuery = supabase
        .from('ot_requests')
        .select('*, users(employee_id)')
        .order('date', { ascending: false })
        .limit(5);

      if (!isAdmin) {
        otQuery = otQuery.eq('user_id', user.id);
      }

      const { data: otData } = await otQuery;

      if (otData) {
        (otData as OvertimeRequest[]).forEach(req => {
          let shouldNotify = false;
          let title = '';
          let message = '';

          const empCode = req.users?.employee_id || 'Nhân viên';

          if (isAdmin) {
            if (req.status === 'pending') {
              shouldNotify = true;
              title = 'Đăng ký tăng ca mới';
              message = `${empCode} đăng ký OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')}`;
            }
          } else {
             if (req.status !== 'pending') {
              shouldNotify = true;
              title = 'Kết quả đăng ký OT';
              const statusText = req.status === 'approved' ? 'được duyệt' : 'bị từ chối';
              message = `OT ngày ${new Date(req.date).toLocaleDateString('vi-VN')} đã ${statusText}`;
             }
          }

          if (shouldNotify) {
            notifs.push({
              id: `ot-${req.id}`,
              type: 'overtime',
              title,
              message,
              time: req.created_at || new Date().toISOString(),
              status: req.status,
              isRead: false
            });
          }
        });
      }

      notifs.sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());
      setNotifications(notifs);
      setUnreadCount(notifs.length);

    } catch (error) {
      console.error("Error fetching notifications", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 30000);
    return () => clearInterval(interval);
  }, [user]);

  const handleToggle = () => {
    setIsOpen(!isOpen);
    if (!isOpen && unreadCount > 0) {
        setTimeout(() => setUnreadCount(0), 1000); 
    }
  };

  const getTimeAgo = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return 'Vừa xong';
    if (diffMins < 60) return `${diffMins} phút trước`;
    if (diffHours < 24) return `${diffHours} giờ trước`;
    return `${diffDays} ngày trước`;
  };

  const getIcon = (item: NotificationItem) => {
    if (item.status === 'approved') return <CheckCircle2 className="w-5 h-5 text-green-500" />;
    if (item.status === 'rejected') return <XCircle className="w-5 h-5 text-red-500" />;
    if (item.status === 'pending') return <Clock className="w-5 h-5 text-yellow-500" />;
    if (item.status === 'returned') return <Info className="w-5 h-5 text-blue-500" />;
    return <Info className="w-5 h-5 text-gray-500" />;
  };

  return (
    <header className="bg-white/80 backdrop-blur-md border-b border-gray-200 h-16 px-4 md:px-8 flex items-center justify-between sticky top-0 z-30 shadow-sm transition-all">
      <div className="flex items-center gap-3">
        <button 
          onClick={onMenuClick}
          className="lg:hidden p-2 -ml-2 hover:bg-gray-100 rounded-xl transition-colors"
        >
          <Menu className="w-6 h-6 text-gray-600" />
        </button>
        <div className="hidden sm:flex items-center gap-2 text-gray-500">
          <span className="text-xs md:text-sm font-medium">Hôm nay, {new Date().toLocaleDateString('vi-VN', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' })}</span>
        </div>
      </div>

      <div className="flex items-center gap-3 md:gap-6">
        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={handleToggle}
            className={`relative p-2.5 rounded-xl transition-all duration-200 ${isOpen ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            <Bell className={`w-5 h-5 ${unreadCount > 0 ? 'animate-pulse-slow' : ''}`} />
            {unreadCount > 0 && (
              <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white flex items-center justify-center shadow-sm">
                 <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-rose-400 opacity-75"></span>
              </span>
            )}
          </button>

          {isOpen && (
            <div className="absolute right-0 top-full mt-3 w-[calc(100vw-2rem)] sm:w-96 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-fade-in-up origin-top-right">
              <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-800 tracking-tight">Thông báo</h3>
                <button onClick={fetchNotifications} title="Làm mới" className="text-gray-400 hover:text-blue-600 transition-colors">
                   {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <span className="text-xs font-bold uppercase tracking-tighter">Làm mới</span>}
                </button>
              </div>

              <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
                {notifications.length === 0 ? (
                  <div className="p-12 text-center text-gray-500 flex flex-col items-center">
                    <Bell className="w-12 h-12 text-gray-100 mb-2" />
                    <p className="text-sm font-medium">Không có thông báo mới</p>
                  </div>
                ) : (
                  <ul className="divide-y divide-gray-50">
                    {notifications.map((notif) => (
                      <li key={notif.id} className="p-4 hover:bg-blue-50/40 transition-colors group cursor-pointer border-l-4 border-l-transparent hover:border-l-blue-500">
                        <div className="flex gap-3">
                          <div className={`mt-1 flex-shrink-0 w-9 h-9 rounded-xl flex items-center justify-center bg-white border shadow-sm transition-transform group-hover:scale-105`}>
                            {getIcon(notif)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-start gap-2">
                                <p className="text-sm font-bold text-gray-900 truncate">{notif.title}</p>
                                <span className="text-[10px] text-gray-400 font-bold whitespace-nowrap">{getTimeAgo(notif.time)}</span>
                            </div>
                            <p className="text-sm text-gray-500 mt-0.5 line-clamp-2 leading-relaxed">{notif.message}</p>
                          </div>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 md:gap-3 pl-4 md:pl-6 border-l border-gray-100">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-bold text-gray-900 tracking-tight">{user?.name || 'Admin User'}</p>
            <p className="text-[10px] text-blue-500 font-black uppercase tracking-widest">
                {user?.role || 'Staff'}
            </p>
          </div>
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20 border-2 border-white overflow-hidden transform hover:rotate-6 transition-transform">
             {user?.avatarUrl ? (
                <img src={user.avatarUrl} alt="" className="w-full h-full object-cover" />
             ) : (
                <User className="w-5 h-5" />
             )}
          </div>
        </div>
      </div>
    </header>
  );
};

