import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, ArrowRight, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Package, Settings2, ChevronDown, ChevronsLeft, ChevronsRight,
  CheckCircle2, Trash2, Check
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full ${className} transition-colors`}>
        <Wrench className={`${mode === 'grid' ? 'w-12 h-12 mb-2 text-gray-300' : 'w-5 h-5 text-gray-400'}`} />
        {mode === 'grid' && <span className="text-[10px] font-medium uppercase tracking-wider text-gray-400">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse" />}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'} ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');

  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(12); // Đặt 12 để hiển thị đẹp trên lưới 4 cột

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory, filterStatus, pageSize]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); 
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    try {
        const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
        const requests: any[] = [];

        toolsToBorrow.forEach(tool => {
            const qty = quantities[tool.id] || 1;
            for(let i = 0; i < qty; i++) {
                requests.push({
                    employee_id: user.employeeCode,
                    user_id: user.id,
                    user_name: user.name,
                    tool_id: tool.id,
                    tool_name: tool.name,
                    borrow_date: new Date().toISOString(),
                    status: 'pending'
                });
            }
        });

        const { error } = await supabase.from('requests').insert(requests);

        if (!error) {
            setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
            setSelectedToolIds(new Set()); 
            setQuantities({});
            setTimeout(() => setMessage(null), 4000);
            await fetchTools();
        } else {
            alert('Có lỗi xảy ra: ' + error.message);
        }
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete);
      if (error) throw error;
      await fetchTools();
      setToolToDelete(null);
      setMessage('Đã xóa thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* HEADER SECTION */}
      <div className="flex flex-col gap-4 bg-white p-5 rounded-[2.5rem] shadow-sm border border-gray-100 transition-all">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100">
                    <Wrench className="w-8 h-8 text-white" />
                </div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">
                        Kho công cụ
                    </h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        Quản lý & Theo dõi tài sản hệ thống
                    </p>
                </div>
                {!isAdmin && <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-widest border border-indigo-100 ml-2">Chế độ Mượn</span>}
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && (
                <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100 whitespace-nowrap">
                    <CheckCircle2 className="w-5 h-5" />
                    {message}
                </div>
                )}

                {isAdmin && (
                    <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <Settings2 className="w-4 h-4" />
                            QUẢN LÝ
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <ShoppingBag className="w-4 h-4" />
                            MƯỢN ĐỒ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><List className="w-5 h-5" /></button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-4 rounded-2xl flex items-center gap-2 text-xs font-black transition-all shadow-xl shadow-indigo-100 w-full sm:w-auto justify-center whitespace-nowrap active:scale-95 uppercase tracking-widest"
                    >
                        <Plus className="w-5 h-5" />
                        THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500 transition-colors" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-indigo-500/10 transition-all text-gray-900 placeholder:text-gray-400 outline-none"
                />
            </div>

            <div className="flex gap-3 w-full md:w-auto">
                <div className="relative flex-1 sm:min-w-[200px] group">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-indigo-500/10 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>

                <div className="relative flex-1 sm:min-w-[200px] group">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-indigo-500/10 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Bảo trì</option>
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>
            </div>
        </div>
      </div>

      {/* CONTENT LIST */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all relative overflow-hidden group flex flex-col h-full p-0 border-2 ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-500/5 transform scale-[1.02]' : 'border-transparent bg-white shadow-lg rounded-[2.5rem]'}`} onClick={() => !isManageMode && selectable && toggleSelection(tool.id)}>
                    <div className="h-56 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        {tool.status === 'inactive' ? (
                          <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Bảo trì</span>
                        ) : tool.available > 0 ? (
                          <span className="bg-emerald-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Sẵn có: {tool.available}</span>
                        ) : (
                          <span className="bg-gray-400 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Hết hàng</span>
                        )}
                      </div>
                    </div>

                    <div className="p-6 flex-1 flex flex-col bg-white">
                      <div className="mb-4">
                        <h3 className="font-black text-gray-900 text-lg line-clamp-2 min-h-[3.5rem] leading-tight tracking-tight">{tool.name}</h3>
                        <div className="flex items-center gap-2 mt-2">
                            <span className="text-[10px] font-black uppercase tracking-tighter text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md">{tool.category}</span>
                            <div className="flex items-center gap-1 text-[10px] text-gray-400 font-bold uppercase tracking-tighter">
                                <MapPin className="w-3 h-3 opacity-50" />
                                {tool.location || 'N/A'}
                            </div>
                        </div>
                      </div>

                      <div className="mt-auto">
                        {isManageMode ? (
                          <div className="flex gap-3 pt-4 border-t border-gray-50" onClick={e => e.stopPropagation()}>
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-white hover:bg-indigo-50 text-indigo-700 border-2 border-indigo-100 py-3 rounded-2xl text-[10px] font-black transition-all flex items-center justify-center gap-2 uppercase tracking-widest"><Edit className="w-4 h-4" /> Sửa</button>
                             <button onClick={() => setToolToDelete(tool.id)} className="p-3 bg-white hover:bg-rose-50 text-rose-600 border-2 border-rose-100 rounded-2xl transition-all"><Trash2 className="w-5 h-5" /></button>
                          </div>
                        ) : (
                          isSelected ? (
                              <div className="flex items-center justify-between bg-indigo-600 rounded-2xl p-1.5 shadow-xl animate-fade-in-up border-2 border-indigo-500" onClick={e => e.stopPropagation()}>
                                  <button onClick={() => changeQuantity(tool.id, -1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-indigo-500/50 hover:bg-white/20 rounded-xl text-white transition-all"><Minus className="w-5 h-5" /></button>
                                  <div className="flex flex-col items-center"><span className="text-[10px] font-black uppercase text-indigo-200 tracking-widest leading-none mb-1">Số lượng</span><span className="font-black text-white text-xl tabular-nums leading-none">{qty}</span></div>
                                  <button onClick={() => changeQuantity(tool.id, 1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-white text-indigo-600 rounded-xl shadow-lg transition-all disabled:opacity-50" disabled={qty >= Number(tool.available)}><Plus className="w-5 h-5" /></button>
                              </div>
                          ) : (
                              <button disabled={!selectable} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl text-[10px] font-black transition-all disabled:opacity-50 disabled:bg-gray-100 flex items-center justify-center gap-3 uppercase tracking-[0.15em] shadow-lg shadow-indigo-100">
                                <PackagePlus className="w-5 h-5" /> CHỌN MƯỢN
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[3rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                    <th className="px-10 py-6 w-24 text-[10px] font-black uppercase tracking-widest text-gray-400">Hình</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Tên thiết bị</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Danh mục</th>
                    <th className="px-10 py-6 text-center text-[10px] font-black uppercase tracking-widest text-gray-400">Kho/Sẵn</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-10 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => {
                      const isSelected = selectedToolIds.has(tool.id);
                      return (
                      <tr key={tool.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-50/50' : 'hover:bg-blue-50/30'}`} onClick={() => !isManageMode && isSelectable(tool) && toggleSelection(tool.id)}>
                        <td className="px-10 py-6"><div className="w-16 h-16 rounded-2xl bg-white border-2 border-gray-100 overflow-hidden flex items-center justify-center p-2 shadow-sm"><ToolThumbnail src={tool.image} alt={tool.name} mode="table" /></div></td>
                        <td className="px-10 py-6 font-black text-gray-900">{tool.name}</td>
                        <td className="px-10 py-6 text-[11px] font-bold text-gray-500 uppercase tracking-tight">{tool.category}</td>
                        <td className="px-10 py-6 text-center text-sm font-black tabular-nums">{tool.available} / {tool.quantity}</td>
                        <td className="px-10 py-6">{tool.status === 'active' ? <span className="text-emerald-700 text-[9px] font-black uppercase bg-emerald-50 px-3 py-1 rounded-full tracking-widest border border-emerald-100">Hoạt động</span> : <span className="text-rose-700 text-[9px] font-black uppercase bg-rose-50 px-3 py-1 rounded-full tracking-widest border border-rose-100">Bảo trì</span>}</td>
                        <td className="px-10 py-6 text-right" onClick={e => e.stopPropagation()}>
                          {isManageMode ? (
                            <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-gray-100 rounded-2xl transition-colors"><Edit className="w-5 h-5"/></button>
                          ) : (
                            <div className="flex justify-end">
                              {isSelected ? (
                                <span className="text-indigo-600 font-black text-[10px] uppercase tracking-widest flex items-center gap-2"><Check className="w-4 h-4" /> Đã chọn</span>
                              ) : (
                                <button disabled={!isSelectable(tool)} className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg disabled:opacity-50 active:scale-90 transition-all"><PackagePlus className="w-5 h-5"/></button>
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                      );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {/* PAGINATION FOOTER */}
      <Card className="p-6 rounded-[3rem] shadow-xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
          <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                  Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredTools.length, startIndex + 1)}-{Math.min(filteredTools.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums">{filteredTools.length}</span> thiết bị
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                 <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                 <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-indigo-100">{currentPage} / {totalPages}</span>
              </div>
          </div>

          <div className="flex items-center gap-3">
              <button 
                  onClick={() => handlePageChange(1)}
                  disabled={currentPage === 1}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
                  title="Trang đầu"
              >
                  <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                  onClick={() => handlePageChange(currentPage - 1)}
                  disabled={currentPage === 1}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
              >
                  <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                  {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                      let pageNum = 1;
                      if (totalPages <= 5) pageNum = i + 1;
                      else if (currentPage <= 3) pageNum = i + 1;
                      else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                      else pageNum = currentPage - 2 + i;

                      return (
                          <button
                              key={pageNum}
                              onClick={() => handlePageChange(pageNum)}
                              className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                                  currentPage === pageNum 
                                  ? 'bg-indigo-600 text-white border-indigo-600 shadow-xl scale-110 z-10' 
                                  : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                              }`}
                          >
                              {pageNum}
                          </button>
                      );
                  })}
              </div>

              <button 
                  onClick={() => handlePageChange(currentPage + 1)}
                  disabled={currentPage === totalPages}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
              >
                  <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                  onClick={() => handlePageChange(totalPages)}
                  disabled={currentPage === totalPages}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
                  title="Trang cuối"
              >
                  <ChevronsRight className="w-5 h-5" />
              </button>
          </div>
      </Card>

      {/* FLOATING ACTION BAR FOR BORROWING */}
      {selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-0 right-0 z-[100] flex justify-center px-4 md:px-8 pointer-events-none">
             <div className="bg-gray-950/90 backdrop-blur-2xl text-white p-3 pr-4 rounded-[2.5rem] shadow-2xl flex items-center gap-6 pointer-events-auto animate-fade-in-up border border-white/10 w-full max-w-2xl mx-auto">
                <div className="flex items-center gap-4 pl-3">
                    <div className="bg-indigo-600 rounded-[1.5rem] w-14 h-14 flex items-center justify-center font-black text-2xl shadow-xl border-2 border-indigo-400">
                        {totalItemsSelected}
                    </div>
                    <div className="flex flex-col">
                      <span className="text-[10px] text-gray-400 uppercase tracking-widest font-black opacity-80 mb-0.5">Xác nhận mượn</span>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-lg text-white tracking-tight">{selectedToolIds.size}</span>
                        <span className="text-[10px] font-bold text-gray-400 uppercase">loại thiết bị</span>
                      </div>
                    </div>
                </div>
                <div className="flex-1 flex items-center gap-4 justify-end">
                    <button onClick={() => { setSelectedToolIds(new Set()); setQuantities({}); }} className="text-gray-400 hover:text-white text-[10px] font-black uppercase tracking-widest px-4 hover:underline transition-all">HỦY BỎ</button>
                    <button onClick={handleBulkBorrow} disabled={isBulkProcessing} className="bg-indigo-600 hover:bg-indigo-500 text-white px-10 py-5 rounded-[1.5rem] font-black shadow-2xl transition-all flex items-center gap-3 uppercase tracking-[0.15em] text-[11px] active:scale-95">
                        {isBulkProcessing ? <Loader2 className="w-5 h-5 animate-spin"/> : <Send className="w-5 h-5" />} GỬI YÊU CẦU
                    </button>
                </div>
             </div>
          </div>
      )}

      {/* MANAGE MODAL */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-zoom-in border border-white/20 my-auto no-scrollbar">
            <div className="flex justify-between items-center p-10 border-b border-gray-100 sticky top-0 bg-white z-10">
              <div>
                <h3 className="text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none">{isEditing ? 'Cập nhật' : 'Thêm mới'}</h3>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-2">Dữ liệu tài sản công ty</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-gray-100 rounded-3xl transition-all active:scale-90"><X className="w-6 h-6 text-gray-400"/></button>
            </div>

            <div className="p-10 space-y-8 bg-gray-50/50">
              <div className="space-y-6 bg-white p-8 rounded-[3rem] border border-gray-100 shadow-sm">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Tên thiết bị</label>
                  <input type="text" placeholder="Nhập tên..." value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Danh mục</label>
                  <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 appearance-none cursor-pointer transition-all">
                    <option>Thiết bị cầm tay</option>
                    <option>Máy móc lớn</option>
                    <option>Đồ bảo hộ</option>
                    <option>Vật tư tiêu hao</option>
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Tổng số</label>
                    <input type="number" placeholder="0" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Sẵn có</label>
                    <input type="number" placeholder="0" value={formData.available} onChange={e => setFormData({...formData, available: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Vị trí lưu kho</label>
                  <input type="text" placeholder="VD: Kệ A1, Tầng 2..." value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Link hình ảnh</label>
                  <div className="relative">
                    <ImageIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 w-5 h-5" />
                    <input type="text" placeholder="http://..." value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full pl-12 pr-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                  </div>
                </div>
              </div>

              <button onClick={handleSaveTool} className="w-full py-6 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-[2rem] shadow-2xl shadow-indigo-100 uppercase tracking-[0.2em] text-xs flex items-center justify-center gap-3 transition-all active:scale-95">
                <Save className="w-6 h-6"/> 
                {isEditing ? 'LƯU THAY ĐỔI' : 'XÁC NHẬN THÊM'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* DELETE CONFIRMATION */}
      {toolToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2.5rem] shadow-2xl shadow-rose-100 rotate-12 transition-transform hover:rotate-0">
                <AlertTriangle className="w-12 h-12"/>
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xóa tài sản?</h3>
              <p className="text-[11px] text-gray-400 font-bold italic px-8 leading-relaxed uppercase tracking-widest opacity-80">
                Dữ liệu sẽ bị xóa vĩnh viễn và không thể khôi phục.
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button onClick={handleDeleteTool} className="w-full py-5 bg-rose-600 text-white font-black rounded-[2rem] text-xs uppercase tracking-[0.2em] shadow-2xl shadow-rose-200 transition-all active:scale-95">XÁC NHẬN XÓA</button>
              <button onClick={() => setToolToDelete(null)} className="w-full py-5 bg-white text-gray-400 font-black rounded-[2rem] border-2 border-gray-100 text-xs uppercase tracking-[0.2em] active:scale-95 transition-all">HỦY BỎ</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, 
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw, ChevronLeft, ChevronsLeft, ChevronsRight
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  // Phân trang
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 20;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (err: any) {
        showToast("Không thể tải dữ liệu: " + err.message, "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = { 'pending': 0, 'approved': 1, 'returned': 2, 'rejected': 3 };
        if (statusOrder[a.status] !== statusOrder[b.status]) return statusOrder[a.status] - statusOrder[b.status];
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  // Tính toán phân trang
  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentRequests = filteredRequests.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterStatus, filterStartDate, activeTab]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus as any, ...extraData } : req));
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    setProcessingId(action.type === 'cancel' ? action.id : action.req.id);

    try {
        if (action.type === 'approve') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
            await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'approved' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'approved');
        } else if (action.type === 'return') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'returned');
        } else if (action.type === 'cancel') {
            await supabase.from('requests').delete().eq('id', action.id);
            setRequests(prev => prev.filter(r => r.id !== action.id));
        } else if (action.type === 'reject') {
            await supabase.from('requests').update({ status: 'rejected' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'rejected');
        }
        showToast("Thao tác thành công!", "success");
    } catch (e: any) {
        showToast(e.message, "error");
    } finally {
        setProcessingId(null);
    }
  };

  const getStatusStyle = (status: string) => {
    switch(status) {
      case 'pending': return 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50';
      case 'approved': return 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50';
      case 'returned': return 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50';
      case 'rejected': return 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50';
      default: return 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50';
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in w-full pb-20">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100"><Wrench className="w-8 h-8 text-white" /></div>
            <div>
              <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">
                {activeTab === 'personal' ? 'Yêu cầu của tôi' : 'Quản lý Đơn Mượn'}
              </h2>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                {activeTab === 'personal' ? 'Theo dõi lịch sử cá nhân' : 'Quản lý toàn bộ hệ thống'}
              </p>
            </div>
        </div>

        <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
            {user.role === 'admin' && (
              <button 
                onClick={() => setActiveTab('all')} 
                className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
              >
                HỆ THỐNG
              </button>
            )}
            <button 
              onClick={() => setActiveTab('personal')} 
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
            >
              CỦA TÔI
            </button>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative group flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm nhân viên, thiết bị..." 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none transition-all"
          />
        </div>

        <div className="relative group">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ phê duyệt</option>
            <option value="approved">✅ Đang mượn</option>
            <option value="returned">↩️ Đã hoàn trả</option>
          </select>
          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative group">
          <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input 
            type="date" 
            value={filterStartDate} 
            onChange={e => setFilterStartDate(e.target.value)} 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          />
        </div>
      </div>

      <Card className="p-0 rounded-[3rem] shadow-2xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Người mượn</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thiết bị</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thời gian</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-center bg-gray-50/50">Trạng thái</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-right bg-gray-50/50">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : currentRequests.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                currentRequests.map((req) => (
                  <tr key={req.id} className="hover:bg-blue-50/20 transition-all duration-300 group">
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-[1rem] bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-lg border-2 border-indigo-400 transition-transform group-hover:scale-110 group-hover:rotate-3">
                          {req.user_name?.charAt(0)}
                        </div>
                        <div>
                          <p className="font-black text-gray-900 text-sm tracking-tight">{req.user_name}</p>
                          <p className="text-[10px] text-gray-400 font-black tracking-widest uppercase opacity-70 mt-0.5">{req.employee_id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                         <div className="w-14 h-14 bg-white border-2 border-gray-50 rounded-2xl flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-200 transition-colors shadow-sm">
                           {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-200" />}
                         </div>
                         <p className="font-black text-gray-800 text-sm leading-tight max-w-[200px]">{req.tool_name}</p>
                      </div>
                    </td>
                    <td className="px-10 py-6 text-[11px] font-black text-gray-500 uppercase tracking-tighter">
                      <div className="flex items-center gap-2">
                        <Calendar className="w-3.5 h-3.5 opacity-30" />
                        {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                      </div>
                    </td>
                    <td className="px-10 py-6 text-center">
                      <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 shadow-lg transition-all group-hover:scale-105 ${getStatusStyle(req.status)}`}>
                        {req.status === 'pending' ? <Clock className="w-3.5 h-3.5" /> : req.status === 'approved' ? <CheckCircle2 className="w-3.5 h-3.5" /> : <Info className="w-3.5 h-3.5" />}
                        {req.status === 'pending' ? 'Chờ Duyệt' : req.status === 'approved' ? 'Đang Mượn' : req.status === 'returned' ? 'Đã Trả' : 'Từ Chối'}
                      </div>
                    </td>
                    <td className="px-10 py-6 text-right">
                      <div className="flex justify-end gap-3 items-center">
                        {processingId === req.id ? (
                          <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                        ) : (
                          <>
                            {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                              <>
                                <button 
                                  onClick={() => setConfirmAction({ type: 'approve', req })} 
                                  className="w-11 h-11 bg-emerald-600 text-white rounded-[1rem] flex items-center justify-center shadow-lg shadow-emerald-100 hover:bg-emerald-700 transition-all active:scale-90"
                                  title="Duyệt yêu cầu"
                                >
                                  <Check className="w-6 h-6" />
                                </button>
                                <button 
                                  onClick={() => setConfirmAction({ type: 'reject', req })} 
                                  className="w-11 h-11 bg-white text-rose-600 border-2 border-rose-50 rounded-[1rem] flex items-center justify-center hover:bg-rose-50 transition-all active:scale-90"
                                  title="Từ chối"
                                >
                                  <X className="w-6 h-6" />
                                </button>
                              </>
                            )}

                            {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                              <button 
                                onClick={() => setConfirmAction({ type: 'return', req })} 
                                className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
                              >
                                <RotateCcw className="w-4 h-4" /> THU HỒI
                              </button>
                            )}

                            {req.user_id === user.id && req.status === 'pending' && (
                              <button 
                                onClick={() => setConfirmAction({ type: 'cancel', id: req.id })} 
                                className="flex items-center gap-2 px-6 py-3 bg-white text-rose-600 border-2 border-rose-100 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all active:scale-95"
                              >
                                <Trash2 className="w-4 h-4" /> HỦY ĐƠN
                              </button>
                            )}
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* PAGINATION FOOTER */}
        {filteredRequests.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-6 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredRequests.length, startIndex + 1)}-{Math.min(filteredRequests.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums">{filteredRequests.length}</span> yêu cầu
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-blue-100">{currentPage} / {totalPages}</span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => handlePageChange(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang đầu"
              >
                <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum = 1;
                  if (totalPages <= 5) pageNum = i + 1;
                  else if (currentPage <= 3) pageNum = i + 1;
                  else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                  else pageNum = currentPage - 2 + i;

                  return (
                    <button
                      key={pageNum}
                      onClick={() => handlePageChange(pageNum)}
                      className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                        currentPage === pageNum 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xl scale-110 z-10' 
                        : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang cuối"
              >
                <ChevronsRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}
      </Card>

      {/* CONFIRM MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl rotate-12 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-12 h-12" /> : <AlertTriangle className="w-12 h-12" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xác nhận?</h3>
              <p className="text-[11px] text-gray-400 font-bold leading-relaxed px-6 uppercase tracking-[0.15em] opacity-80 italic">
                {confirmAction.type === 'approve' ? 'Duyệt yêu cầu này và cập nhật tồn kho.' : 'Bạn có chắc chắn muốn thực hiện thao tác này?'}
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction} 
                className={`w-full py-5 text-white font-black rounded-3xl text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                  confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)} 
                className="w-full py-5 bg-white text-gray-400 font-black rounded-3xl border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  History, Search, Calendar, Filter, X, 
  User as UserIcon, ShieldCheck, ChevronDown, 
  SlidersHorizontal, ChevronLeft, ChevronRight, 
  Loader2, RefreshCw, AlertCircle, ChevronsLeft, ChevronsRight 
} from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

// Mở rộng interface local để hứng thêm field người xử lý từ DB
interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | '7days' | '30days' | 'thisMonth';

const ITEMS_PER_PAGE = 20;

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  // State phân trang
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async (silent = false) => {
    if (!user) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    setError(null);

    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
      }

      if (statusFilter !== 'all') {
        query = query.eq('status', statusFilter);
      }

      if (startDate) {
        query = query.gte('borrow_date', `${startDate}T00:00:00`);
      }
      if (endDate) {
        query = query.lte('borrow_date', `${endDate}T23:59:59`);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      if (data) {
        setLogs(data as ExtendedBorrowRequest[]);
      }
    } catch (err: any) {
      console.error("Fetch history error:", err);
      setError("Không thể tải dữ liệu lịch sử. Vui lòng thử lại.");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, [user.id, startDate, endDate, statusFilter, user.role]);

  // Reset trang về 1 khi bất kỳ bộ lọc nào thay đổi
  useEffect(() => {
    setCurrentPage(1);
  }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Admin';
    if (req.status === 'rejected') return req.rejected_by || 'Admin';
    return '-';
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.trim().toLowerCase();
      const handlerLower = handlerFilter.trim().toLowerCase();

      const matchesText = !searchLower || (
        log.user_name?.toLowerCase().includes(searchLower) ||
        log.employee_id?.toLowerCase().includes(searchLower) ||
        log.tool_name?.toLowerCase().includes(searchLower)
      );

      const currentHandler = getHandlerName(log).toLowerCase();
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);

      return matchesText && matchesHandler;
    });
  }, [logs, searchText, handlerFilter]);

  // Logic phân trang cho Client-side
  const totalPages = Math.max(1, Math.ceil(filteredLogs.length / ITEMS_PER_PAGE));

  const currentLogs = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [filteredLogs, currentPage]);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'today':
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'custom':
            return; 
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setHandlerFilter('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
    setCurrentPage(1);
  };

  const activeFiltersCount = [
    searchText.trim(), 
    handlerFilter.trim(), 
    startDate, 
    endDate, 
    statusFilter !== 'all'
  ].filter(Boolean).length;

  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;

  return (
    <div className="space-y-6 animate-fade-in pb-10">
       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-purple-600 rounded-[1.5rem] shadow-xl shadow-purple-100 text-white">
                    <History className="w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">Lịch sử hoạt động</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        {user.role === 'admin' ? 'Theo dõi toàn bộ lịch sử mượn trả hệ thống' : 'Theo dõi lịch sử mượn trả cá nhân'}
                    </p>
                </div>
            </div>
            <button 
              onClick={() => fetchHistory(true)} 
              className="flex items-center gap-2 px-6 py-3 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border border-gray-200"
            >
              {isRefreshing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RefreshCw className="w-4 h-4"/>}
              Làm mới
            </button>
       </div>

       <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[3rem] bg-white">
            <div className="p-8 space-y-6 bg-white">
                <div className="flex items-center justify-between">
                    <h3 className="text-[10px] font-black text-gray-400 flex items-center gap-2 uppercase tracking-[0.2em]">
                        <SlidersHorizontal className="w-4 h-4 text-purple-600" /> Bộ lọc tìm kiếm
                    </h3>
                    {activeFiltersCount > 0 && (
                        <button 
                            onClick={clearFilters}
                            className="text-[10px] text-rose-600 hover:text-rose-800 font-black uppercase tracking-widest flex items-center gap-1 hover:underline"
                        >
                            <X className="w-3.5 h-3.5" /> Xóa {activeFiltersCount} bộ lọc
                        </button>
                    )}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    <div className="lg:col-span-5 space-y-4 border-r border-gray-100 pr-0 lg:pr-8">
                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Khoảng thời gian</label>
                        <div className="flex flex-wrap gap-2 mb-3">
                             {[{id: 'today', l: 'Hôm nay'}, {id: '7days', l: '7 ngày'}, {id: '30days', l: '30 ngày'}, {id: 'thisMonth', l: 'Tháng này'}].map((btn) => (
                                <button
                                    key={btn.id}
                                    onClick={() => handleQuickDate(btn.id as QuickDateOption)}
                                    className={`px-4 py-2 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all border-2 ${
                                        quickDate === btn.id 
                                        ? 'bg-purple-50 text-purple-700 border-purple-200 shadow-md transform scale-105' 
                                        : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'
                                    }`}
                                >
                                    {btn.l}
                                </button>
                             ))}
                        </div>
                        <div className="flex items-center gap-3">
                            <div className="relative flex-1 group">
                                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                <input 
                                    type="date" 
                                    value={startDate}
                                    onChange={(e) => handleManualDateChange('start', e.target.value)}
                                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                />
                            </div>
                            <span className="text-gray-300 font-black">-</span>
                            <div className="relative flex-1 group">
                                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                <input 
                                    type="date" 
                                    value={endDate}
                                    onChange={(e) => handleManualDateChange('end', e.target.value)}
                                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="lg:col-span-7 space-y-4">
                         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Từ khóa chung</label>
                                <div className="relative group">
                                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                    <input 
                                        type="text" 
                                        value={searchText}
                                        onChange={(e) => setSearchText(e.target.value)}
                                        placeholder="Tên, mã NV, thiết bị..." 
                                        className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                    />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Trạng thái đơn</label>
                                <div className="relative group">
                                    <select
                                        value={statusFilter}
                                        onChange={(e) => setStatusFilter(e.target.value)}
                                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900 appearance-none cursor-pointer"
                                    >
                                        <option value="all">Tất cả trạng thái</option>
                                        <option value="pending">⏳ Chờ duyệt</option>
                                        <option value="approved">✅ Đang mượn</option>
                                        <option value="returned">↩️ Đã trả</option>
                                        <option value="rejected">❌ Đã từ chối</option>
                                    </select>
                                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-purple-600" />
                                </div>
                            </div>
                         </div>

                         <div className="space-y-2">
                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Người xử lý (Admin)</label>
                            <div className="relative group">
                                <ShieldCheck className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                <input 
                                    type="text" 
                                    value={handlerFilter}
                                    onChange={(e) => setHandlerFilter(e.target.value)}
                                    placeholder="Tìm người duyệt yêu cầu..." 
                                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                />
                            </div>
                         </div>
                    </div>
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Người mượn</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Thiết bị</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Ngày mượn</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Ngày trả</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Người xử lý</th>
                            <th className="px-10 py-6 text-center text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 bg-white">
                        {loading ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center"><div className="flex flex-col items-center gap-4"><Loader2 className="w-12 h-12 animate-spin text-purple-600 opacity-20" /><p className="text-sm font-black uppercase tracking-widest text-gray-300">Đang tải lịch sử...</p></div></td></tr>
                        ) : error ? (
                             <tr><td colSpan={6} className="px-10 py-32 text-center"><div className="flex flex-col items-center gap-4 text-rose-500"><AlertCircle className="w-12 h-12" /><p className="text-sm font-black uppercase tracking-widest">{error}</p><button onClick={() => fetchHistory()} className="px-6 py-2 bg-rose-50 rounded-xl text-xs font-black uppercase tracking-widest border border-rose-100">Thử lại</button></div></td></tr>
                        ) : currentLogs.length === 0 ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không có dữ liệu phù hợp</td></tr>
                        ) : (
                            currentLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-purple-50/20 transition-all duration-300 group">
                                    <td className="px-10 py-6">
                                        <div className="flex items-center gap-4">
                                            <div className="w-12 h-12 rounded-[1rem] bg-purple-600 text-white flex items-center justify-center font-black text-lg shadow-lg border-2 border-purple-400 transition-transform group-hover:scale-110 group-hover:rotate-3">
                                                {item.user_name ? item.user_name.charAt(0) : '?'}
                                            </div>
                                            <div>
                                                <div className="font-black text-gray-900 text-sm tracking-tight">{item.user_name}</div>
                                                <div className="text-[10px] text-gray-400 font-black tracking-widest uppercase opacity-70 mt-0.5">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-10 py-6">
                                        <span className="font-black text-gray-800 text-sm leading-tight group-hover:text-purple-700 transition-colors">{item.tool_name}</span>
                                    </td>
                                    <td className="px-10 py-6">
                                        <div className="text-gray-900 font-black text-xs">{new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        <div className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter mt-0.5 flex items-center gap-1 opacity-60">
                                            <History className="w-3 h-3"/> 
                                            {new Date(item.borrow_date).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}
                                        </div>
                                    </td>
                                    <td className="px-10 py-6">
                                        {item.returned_at ? (
                                            <>
                                                <div className="text-purple-700 font-black text-xs">{new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                                <div className="text-[10px] text-purple-400 font-bold uppercase tracking-tighter mt-0.5">{new Date(item.returned_at).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                            </>
                                        ) : (
                                            <span className="text-gray-200 font-black text-lg select-none">—</span>
                                        )}
                                    </td>
                                    <td className="px-10 py-6">
                                        {item.status !== 'pending' ? (
                                            <div className="flex items-center gap-2 px-3 py-1.5 bg-gray-50 border border-gray-100 rounded-xl w-fit shadow-sm">
                                                <ShieldCheck className="w-3.5 h-3.5 text-gray-400" />
                                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-tight">{getHandlerName(item)}</span>
                                            </div>
                                        ) : (
                                            <span className="text-gray-300 text-[10px] font-black uppercase tracking-widest italic pl-1">Chờ xử lý</span>
                                        )}
                                    </td>
                                    <td className="px-10 py-6 text-center">
                                        <span className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 shadow-lg transition-all group-hover:scale-105 ${
                                            item.status === 'approved' ? 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50' :
                                            item.status === 'rejected' ? 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50' :
                                            item.status === 'returned' ? 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50' :
                                            'bg-amber-500 text-white border-amber-600 shadow-amber-200/50'
                                        }`}>
                                            {item.status === 'approved' ? 'Đang mượn' : 
                                            item.status === 'rejected' ? 'Từ chối' : 
                                            item.status === 'returned' ? 'Đã trả' : 'Chờ duyệt'}
                                        </span>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Phân trang Footer */}
            <div className="bg-gray-50 border-t border-gray-100 p-8 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
                <div className="flex flex-col sm:flex-row items-center gap-4">
                  <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                    Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredLogs.length, startIndex + 1)}-{Math.min(filteredLogs.length, startIndex + ITEMS_PER_PAGE)}</span> trong <span className="text-gray-900 tabular-nums">{filteredLogs.length}</span> kết quả
                  </span>
                  <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                    <span className="bg-purple-50 text-purple-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-purple-100">{currentPage} / {totalPages}</span>
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <button 
                    onClick={() => handlePageChange(1)}
                    disabled={currentPage === 1}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                    title="Trang đầu"
                  >
                    <ChevronsLeft className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </button>

                  <div className="flex items-center gap-1 mx-2">
                    {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                      let pageNum = 1;
                      if (totalPages <= 5) pageNum = i + 1;
                      else if (currentPage <= 3) pageNum = i + 1;
                      else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                      else pageNum = currentPage - 2 + i;

                      return (
                        <button
                          key={pageNum}
                          onClick={() => handlePageChange(pageNum)}
                          className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                            currentPage === pageNum 
                            ? 'bg-purple-600 text-white border-purple-600 shadow-xl scale-110 z-10' 
                            : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                  >
                    <ChevronRight className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => handlePageChange(totalPages)}
                    disabled={currentPage === totalPages}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                    title="Trang cuối"
                  >
                    <ChevronsRight className="w-5 h-5" />
                  </button>
                </div>
            </div>
       </Card>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, ArrowRight, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Package, Settings2, ChevronDown, ChevronsLeft, ChevronsRight,
  CheckCircle2, Trash2, Check
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, className, mode = 'grid' }: { src?: string | null, alt: string, className?: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setError(false);
    setLoaded(false);
  }, [src]);

  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-100/50 w-full h-full ${className || ''} transition-colors rounded-xl`}>
        <div className={`flex items-center justify-center ${mode === 'grid' ? 'p-6 bg-white/50 rounded-full shadow-inner' : ''}`}>
           <Wrench className={`${mode === 'grid' ? 'w-10 h-10 text-gray-300' : 'w-6 h-6 text-gray-400 opacity-60'}`} />
        </div>
        {mode === 'grid' && <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-400 mt-2 opacity-60">No Image</span>}
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white ${className || ''}`}>
      {!loaded && <div className="absolute inset-0 bg-gray-100 animate-pulse rounded-xl" />}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain transition-opacity duration-300 ${loaded ? 'opacity-100' : 'opacity-0'} ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');

  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(12); // Đặt 12 để hiển thị đẹp trên lưới 4 cột

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterCategory, filterStatus, pageSize]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); 
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    try {
        const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
        const requests: any[] = [];

        toolsToBorrow.forEach(tool => {
            const qty = quantities[tool.id] || 1;
            for(let i = 0; i < qty; i++) {
                requests.push({
                    employee_id: user.employeeCode,
                    user_id: user.id,
                    user_name: user.name,
                    tool_id: tool.id,
                    tool_name: tool.name,
                    borrow_date: new Date().toISOString(),
                    status: 'pending'
                });
            }
        });

        const { error } = await supabase.from('requests').insert(requests);

        if (!error) {
            setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
            setSelectedToolIds(new Set()); 
            setQuantities({});
            setTimeout(() => setMessage(null), 4000);
            await fetchTools();
        } else {
            alert('Có lỗi xảy ra: ' + error.message);
        }
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete);
      if (error) throw error;
      await fetchTools();
      setToolToDelete(null);
      setMessage('Đã xóa thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* HEADER SECTION */}
      <div className="flex flex-col gap-4 bg-white p-5 rounded-[2.5rem] shadow-sm border border-gray-100 transition-all">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100">
                    <Wrench className="w-8 h-8 text-white" />
                </div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">
                        Kho công cụ
                    </h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        Quản lý & Theo dõi tài sản hệ thống
                    </p>
                </div>
                {!isAdmin && <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-widest border border-indigo-100 ml-2">Chế độ Mượn</span>}
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && (
                <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100 whitespace-nowrap">
                    <CheckCircle2 className="w-5 h-5" />
                    {message}
                </div>
                )}

                {isAdmin && (
                    <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <Settings2 className="w-4 h-4" />
                            QUẢN LÝ
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <ShoppingBag className="w-4 h-4" />
                            MƯỢN ĐỒ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><List className="w-5 h-5" /></button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-4 rounded-2xl flex items-center gap-2 text-xs font-black transition-all shadow-xl shadow-indigo-100 w-full sm:w-auto justify-center whitespace-nowrap active:scale-95 uppercase tracking-widest"
                    >
                        <Plus className="w-5 h-5" />
                        THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500 transition-colors" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-indigo-500/10 transition-all text-gray-900 placeholder:text-gray-400 outline-none"
                />
            </div>

            <div className="flex gap-3 w-full md:w-auto">
                <div className="relative flex-1 sm:min-w-[200px] group">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-indigo-500/10 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>

                <div className="relative flex-1 sm:min-w-[200px] group">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-indigo-500/10 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Bảo trì</option>
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>
            </div>
        </div>
      </div>

      {/* CONTENT LIST */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
