import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, XCircle,
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw, ChevronLeft, ChevronsLeft, ChevronsRight
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  // Phân trang
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 20;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (err: any) {
        showToast("Không thể tải dữ liệu: " + err.message, "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        // Ưu tiên: Pending (0) -> Approved (1) -> Returned (2) -> Rejected (3)
        const statusOrder: Record<string, number> = { 'pending': 0, 'approved': 1, 'returned': 2, 'rejected': 3 };
        if (statusOrder[a.status] !== statusOrder[b.status]) return statusOrder[a.status] - statusOrder[b.status];
        // Cùng trạng thái thì sắp xếp theo ngày mới nhất lên đầu
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  // Tính toán phân trang
  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentRequests = filteredRequests.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterStatus, filterStartDate, activeTab]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus as any, ...extraData } : req));
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    setProcessingId(action.type === 'cancel' ? action.id : action.req.id);

    try {
        if (action.type === 'approve') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
            await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'approved' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'approved');
        } else if (action.type === 'return') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'returned');
        } else if (action.type === 'cancel') {
            await supabase.from('requests').delete().eq('id', action.id);
            setRequests(prev => prev.filter(r => r.id !== action.id));
        } else if (action.type === 'reject') {
            await supabase.from('requests').update({ status: 'rejected' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'rejected');
        }
        showToast("Thao tác thành công!", "success");
    } catch (e: any) {
        showToast(e.message, "error");
    } finally {
        setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'pending': 
        return {
            className: 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50',
            icon: <Clock className="w-3.5 h-3.5" />,
            label: 'Chờ Duyệt'
        };
      case 'approved': 
        return {
            className: 'bg-emerald-600 text-white border-emerald-700 shadow-emerald-200/50',
            icon: <CheckCircle2 className="w-3.5 h-3.5" />,
            label: 'Đang Mượn'
        };
      case 'returned': 
        return {
            className: 'bg-blue-600 text-white border-blue-700 shadow-blue-200/50',
            icon: <RotateCcw className="w-3.5 h-3.5" />,
            label: 'Đã Trả'
        };
      case 'rejected': 
        return {
            className: 'bg-rose-600 text-white border-rose-700 shadow-rose-200/50',
            icon: <XCircle className="w-3.5 h-3.5" />,
            label: 'Từ Chối'
        };
      default: 
        return {
            className: 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50',
            icon: <Info className="w-3.5 h-3.5" />,
            label: 'Không Xác Định'
        };
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in w-full pb-20">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100"><Wrench className="w-8 h-8 text-white" /></div>
            <div>
              <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">
                {activeTab === 'personal' ? 'Yêu cầu của tôi' : 'Quản lý Đơn Mượn'}
              </h2>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                {activeTab === 'personal' ? 'Theo dõi lịch sử cá nhân' : 'Quản lý toàn bộ hệ thống'}
              </p>
            </div>
        </div>

        <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
            {user.role === 'admin' && (
              <button 
                onClick={() => setActiveTab('all')} 
                className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
              >
                HỆ THỐNG
              </button>
            )}
            <button 
              onClick={() => setActiveTab('personal')} 
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
            >
              CỦA TÔI
            </button>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative group flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm nhân viên, thiết bị..." 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none transition-all"
          />
        </div>

        <div className="relative group">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ phê duyệt</option>
            <option value="approved">✅ Đang mượn</option>
            <option value="returned">↩️ Đã hoàn trả</option>
            <option value="rejected">❌ Từ chối</option>
          </select>
          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative group">
          <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input 
            type="date" 
            value={filterStartDate} 
            onChange={e => setFilterStartDate(e.target.value)} 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          />
        </div>
      </div>

      <Card className="p-0 rounded-[3rem] shadow-2xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Người mượn</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thiết bị</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thời gian</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-center bg-gray-50/50">Trạng thái</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-right bg-gray-50/50">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : currentRequests.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                currentRequests.map((req) => {
                  const badge = getStatusBadge(req.status);
                  return (
                    <tr key={req.id} className="hover:bg-blue-50/20 transition-all duration-300 group">
                      <td className="px-10 py-6">
                        <div className="flex items-center gap-4">
                          <div className="w-12 h-12 rounded-[1rem] bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-lg border-2 border-indigo-400 transition-transform group-hover:scale-110 group-hover:rotate-3">
                            {req.user_name?.charAt(0)}
                          </div>
                          <div>
                            <p className="font-black text-gray-900 text-sm tracking-tight">{req.user_name}</p>
                            <p className="text-[10px] text-gray-400 font-black tracking-widest uppercase opacity-70 mt-0.5">{req.employee_id}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-10 py-6">
                        <div className="flex items-center gap-4">
                           <div className="w-14 h-14 bg-white border-2 border-gray-50 rounded-2xl flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-200 transition-colors shadow-sm">
                             {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-200" />}
                           </div>
                           <p className="font-black text-gray-800 text-sm leading-tight max-w-[200px]">{req.tool_name}</p>
                        </div>
                      </td>
                      <td className="px-10 py-6 text-[11px] font-black text-gray-500 uppercase tracking-tighter">
                        <div className="flex items-center gap-2">
                          <Calendar className="w-3.5 h-3.5 opacity-30" />
                          {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                        </div>
                      </td>
                      <td className="px-10 py-6 text-center">
                        <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 shadow-lg transition-all group-hover:scale-105 ${badge.className}`}>
                          {badge.icon}
                          {badge.label}
                        </div>
                      </td>
                      <td className="px-10 py-6 text-right">
                        <div className="flex justify-end gap-3 items-center">
                          {processingId === req.id ? (
                            <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                          ) : (
                            <>
                              {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                                <>
                                  <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })} 
                                    className="w-11 h-11 bg-emerald-600 text-white rounded-[1rem] flex items-center justify-center shadow-lg shadow-emerald-100 hover:bg-emerald-700 transition-all active:scale-90"
                                    title="Duyệt yêu cầu"
                                  >
                                    <Check className="w-6 h-6" />
                                  </button>
                                  <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })} 
                                    className="w-11 h-11 bg-white text-rose-600 border-2 border-rose-50 rounded-[1rem] flex items-center justify-center hover:bg-rose-50 transition-all active:scale-90"
                                    title="Từ chối"
                                  >
                                    <X className="w-6 h-6" />
                                  </button>
                                </>
                              )}

                              {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                                <button 
                                  onClick={() => setConfirmAction({ type: 'return', req })} 
                                  className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
                                >
                                  <RotateCcw className="w-4 h-4" /> THU HỒI
                                </button>
                              )}

                              {req.user_id === user.id && req.status === 'pending' && (
                                <button 
                                  onClick={() => setConfirmAction({ type: 'cancel', id: req.id })} 
                                  className="flex items-center gap-2 px-6 py-3 bg-white text-rose-600 border-2 border-rose-100 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all active:scale-95"
                                >
                                  <Trash2 className="w-4 h-4" /> HỦY ĐƠN
                                </button>
                              )}
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {/* PAGINATION FOOTER */}
        {filteredRequests.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-6 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredRequests.length, startIndex + 1)}-{Math.min(filteredRequests.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums">{filteredRequests.length}</span> yêu cầu
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-blue-100">{currentPage} / {totalPages}</span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => handlePageChange(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang đầu"
              >
                <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum = 1;
                  if (totalPages <= 5) pageNum = i + 1;
                  else if (currentPage <= 3) pageNum = i + 1;
                  else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                  else pageNum = currentPage - 2 + i;

                  return (
                    <button
                      key={pageNum}
                      onClick={() => handlePageChange(pageNum)}
                      className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                        currentPage === pageNum 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xl scale-110 z-10' 
                        : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang cuối"
              >
                <ChevronsRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}
      </Card>

      {/* CONFIRM MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl rotate-12 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'
              }`}>
                {confirmAction.type === 'approve' ? <CheckCircle2 className="w-12 h-12" /> : <AlertTriangle className="w-12 h-12" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xác nhận?</h3>
              <p className="text-[11px] text-gray-400 font-bold leading-relaxed px-6 uppercase tracking-[0.15em] opacity-80 italic">
                {confirmAction.type === 'approve' ? 'Duyệt yêu cầu này và cập nhật tồn kho.' : 'Bạn có chắc chắn muốn thực hiện thao tác này?'}
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction} 
                className={`w-full py-5 text-white font-black rounded-3xl text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                  confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 'bg-rose-600 shadow-rose-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)} 
                className="w-full py-5 bg-white text-gray-400 font-black rounded-3xl border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLayoutDashboard, LucideLoader2, UserCircle } from 'lucide-react';

interface LoginFormProps {
  onLoginSuccess: (user: any) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onLoginSuccess }) => {
  const [employeeCode, setEmployeeCode] = useState('NV001');
  const [password, setPassword] = useState('123');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      // Gọi hàm mock signInWithPassword nhưng truyền employeeCode
      const { data, error } = await supabase.auth.signInWithPassword({
        employeeCode,
        password,
      });

      if (error) {
        setError(error.message);
      } else if (data?.user) {
        // Lưu session giả
        localStorage.setItem('sb-session', JSON.stringify(data.session));
        onLoginSuccess(data.user);
      }
    } catch (err) {
      setError('Đã xảy ra lỗi không mong muốn.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden">
        <div className="bg-blue-800 p-8 text-center relative overflow-hidden">
            {/* Decoration */}
            <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
                <div className="absolute top-[-50px] left-[-50px] w-32 h-32 bg-white rounded-full"></div>
                <div className="absolute bottom-[-30px] right-[-30px] w-24 h-24 bg-white rounded-full"></div>
            </div>

          <div className="mx-auto bg-white/20 w-20 h-20 rounded-full flex items-center justify-center mb-4 backdrop-blur-sm border border-white/30 shadow-lg relative z-10">
            <LucideLayoutDashboard className="text-white w-10 h-10" />
          </div>
          <h2 className="text-3xl font-bold text-white mb-1 relative z-10">Manager Tool</h2>
          <p className="text-blue-200 text-sm relative z-10">Hệ thống quản lý nội bộ</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Mã nhân viên</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <UserCircle className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
                  className="w-full pl-10 pr-4 py-3 rounded-lg border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all uppercase placeholder:normal-case text-gray-900 shadow-sm"
                  placeholder="Ví dụ: NV001"
                  required
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Mật khẩu</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 rounded-lg border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all text-gray-900 shadow-sm"
                placeholder="••••••••"
                required
              />
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 flex items-center gap-2">
                <span className="w-1.5 h-1.5 bg-red-600 rounded-full"></span>
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-700 hover:bg-blue-800 text-white font-semibold py-3.5 px-4 rounded-lg transition-colors flex items-center justify-center disabled:opacity-70 disabled:cursor-not-allowed shadow-lg shadow-blue-700/30"
            >
              {loading ? (
                <>
                  <LucideLoader2 className="w-5 h-5 animate-spin mr-2" />
                  Đang xác thực...
                </>
              ) : (
                'Đăng nhập hệ thống'
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus, Share2, ToggleLeft, ToggleRight, Eye, MousePointer2, CalendarRange, FileDown, ArrowRight, Zap, List, ChevronDown, ChevronUp, Edit
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const currentMonthStr = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;

// Fixed: The component was missing its return statement and closing logic, causing a 'void' return error.
export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('20:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const toggleSaturdayStatus = async () => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    const currentStatus = dayConfigs[selectedDateStr] ?? true;
    const newStatus = !currentStatus;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: newStatus });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: newStatus }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng thời gian này.");

    filtered.sort((a, b) => a.date.localeCompare(b.date));
    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    const summaryData = filtered.map(req => {
      const d = new Date(req.date);
      return {
        'Ngày': req.date,
        'Thứ': dayNames[d.getDay()],
        'Nhân viên': req.users?.name || req.user_id,
        'Mã NV': req.users?.employee_id || '-',
        'Bắt đầu': req.start_time,
        'Kết thúc': req.end_time,
        'Tổng giờ': req.total_hours,
        'Lý do': req.reason,
        'Trạng thái': req.status === 'approved' ? 'Đã duyệt' : req.status === 'pending' ? 'Chờ duyệt' : 'Từ chối'
      };
    });

    const worksheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, worksheet, "Overtime");
    XLSX.writeFile(workbook, `OT_Report_${start}_to_${end}.xlsx`);
  };

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");
    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'pending'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  // Fixed: Added the missing return statement and UI structure to fix the 'void' return error.
  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-100 rounded-2xl text-indigo-600">
            <Clock className="w-8 h-8" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Đăng ký Tăng ca</h2>
            <p className="text-sm text-gray-500">Quản lý và theo dõi lịch trình OT</p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1.5 rounded-2xl">
          <button onClick={() => setActiveTab('calendar')} className={`px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-500'}`}>Lịch</button>
          <button onClick={() => setActiveTab('personal')} className={`px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-500'}`}>Danh sách</button>
          <button onClick={() => setActiveTab('stats')} className={`px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-500'}`}>Thống kê</button>
        </div>
      </div>

      {activeTab === 'calendar' && (
        <Card className="p-8">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
              <CalendarIcon className="w-5 h-5 text-indigo-500" />
              Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}
            </h3>
            <div className="flex gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-100 rounded-xl transition-colors"><ChevronLeft className="w-5 h-5"/></button>
              <button onClick={() => setCurrentDate(new Date())} className="px-4 py-2 text-sm font-bold text-indigo-600 hover:bg-indigo-50 rounded-xl">Hôm nay</button>
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-100 rounded-xl transition-colors"><ChevronRight className="w-5 h-5"/></button>
            </div>
          </div>
          <div className="grid grid-cols-7 gap-4">
            {['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'].map(d => (
              <div key={d} className="text-center text-xs font-black text-gray-400 uppercase tracking-widest py-2">{d}</div>
            ))}
            {Array.from({ length: getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => (
              <div key={`empty-${i}`} className="h-32 bg-gray-50/50 rounded-2xl border border-dashed border-gray-100"></div>
            ))}
            {Array.from({ length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const dayReqs = requests.filter(r => r.date === dateStr);
              return (
                <button 
                  key={day} 
                  onClick={() => { setSelectedDateStr(dateStr); setIsModalOpen(true); }}
                  className="h-32 p-3 bg-white border border-gray-100 rounded-2xl hover:border-indigo-300 hover:shadow-xl hover:shadow-indigo-500/5 transition-all group relative overflow-hidden text-left"
                >
                  <span className={`text-lg font-bold ${new Date().toISOString().split('T')[0] === dateStr ? 'text-indigo-600' : 'text-gray-900'}`}>{day}</span>
                  <div className="mt-2 space-y-1">
                    {dayReqs.slice(0, 2).map(r => (
                      <div key={r.id} className="text-[10px] bg-indigo-50 text-indigo-700 px-2 py-1 rounded-lg font-bold truncate">
                        {r.users?.name || 'User'} - {r.total_hours}h
                      </div>
                    ))}
                    {dayReqs.length > 2 && <div className="text-[9px] text-gray-400 font-bold ml-1">+{dayReqs.length - 2} người khác</div>}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'personal' && (
        <Card title="Danh sách yêu cầu" className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Ngày</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Nhân viên</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Thời gian</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest text-center">Tổng giờ</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Trạng thái</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {requests.length === 0 ? (
                  <tr><td colSpan={5} className="px-6 py-12 text-center text-gray-400">Không có dữ liệu</td></tr>
                ) : (
                  requests.map(r => (
                    <tr key={r.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm font-bold">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                      <td className="px-6 py-4 text-sm font-bold text-gray-900">{r.users?.name || '-'}</td>
                      <td className="px-6 py-4 text-xs text-gray-500 font-medium">{r.start_time} - {r.end_time}</td>
                      <td className="px-6 py-4 text-center text-sm font-black text-indigo-600">{r.total_hours}h</td>
                      <td className="px-6 py-4">
                        <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${r.status === 'approved' ? 'bg-green-100 text-green-700' : r.status === 'pending' ? 'bg-amber-100 text-amber-700' : 'bg-rose-100 text-rose-700'}`}>
                          {r.status === 'approved' ? 'Đã duyệt' : r.status === 'pending' ? 'Chờ' : 'Từ chối'}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center">
              <h3 className="text-lg font-bold text-gray-900">Đăng ký OT: {selectedDateStr}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-gray-100 rounded-xl transition-colors"><X className="w-5 h-5 text-gray-400"/></button>
            </div>
            <div className="p-6 space-y-4">
              {isAdmin && (
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Nhân viên</label>
                  <select value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-gray-50 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 border-none">
                    {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>)}
                  </select>
                </div>
              )}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Bắt đầu</label>
                  <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 border-none"/>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Kết thúc</label>
                  <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 border-none"/>
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1 ml-1">Lý do</label>
                <div className="relative">
                  <textarea value={reason} onChange={e => setReason(e.target.value)} placeholder="Nhập lý do chi tiết..." className="w-full px-4 py-3 bg-gray-50 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 border-none min-h-[100px] resize-none pr-12"></textarea>
                  <button onClick={handleRewrite} disabled={isRewriting || !reason.trim()} className="absolute right-3 bottom-3 p-2 bg-white text-indigo-600 rounded-lg shadow-sm hover:shadow-md transition-all disabled:opacity-50">
                    {isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>}
                  </button>
                </div>
              </div>
              <div className="p-4 bg-indigo-50 rounded-2xl flex items-center justify-between">
                <span className="text-xs font-bold text-indigo-600 uppercase tracking-widest">Tổng thời gian</span>
                <span className="text-xl font-black text-indigo-700">{calculatedHours}h</span>
              </div>
            </div>
            <div className="p-6 bg-gray-50 flex gap-3">
              <button onClick={() => setIsModalOpen(false)} className="flex-1 px-6 py-3 bg-white text-gray-500 font-bold rounded-xl border border-gray-200 hover:bg-gray-100 transition-all text-sm">Hủy</button>
              <button onClick={handleSaveRequest} disabled={isSubmitting} className="flex-2 px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-all disabled:opacity-50 text-sm flex items-center justify-center gap-2">
                {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Save className="w-4 h-4"/>}
                {editingRequestId ? 'Cập nhật' : 'Đăng ký'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

