  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('20:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");
    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'pending'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  const handleDayClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-4 md:space-y-6 max-w-5xl mx-auto">
      {/* Header section optimized for mobile */}
      <div className="flex flex-col gap-4 bg-white p-4 md:p-6 rounded-2xl md:rounded-3xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-3 md:gap-4">
          <div className="p-2 md:p-3 bg-indigo-100 rounded-xl md:rounded-2xl text-indigo-600">
            <Clock className="w-6 h-6 md:w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-bold text-gray-900 leading-tight">Đăng ký Tăng ca</h2>
            <p className="text-xs md:text-sm text-gray-500">Quản lý lịch trình OT</p>
          </div>
        </div>

        {/* Responsive Tabs */}
        <div className="flex bg-gray-100 p-1 rounded-xl md:rounded-2xl w-full">
          <button 
            onClick={() => setActiveTab('calendar')} 
            className={`flex-1 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}
          >
            Lịch
          </button>
          <button 
            onClick={() => setActiveTab('personal')} 
            className={`flex-1 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}
          >
            Danh sách
          </button>
          <button 
            onClick={() => setActiveTab('stats')} 
            className={`flex-1 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}
          >
            Thống kê
          </button>
        </div>
      </div>

      {activeTab === 'calendar' && (
        <Card className="p-3 md:p-8">
          <div className="flex items-center justify-between mb-4 md:mb-8">
            <h3 className="text-base md:text-xl font-bold text-gray-900 flex items-center gap-2">
              <CalendarIcon className="w-4 h-4 md:w-5 h-5 text-indigo-500" />
              T{currentDate.getMonth() + 1}/{currentDate.getFullYear()}
            </h3>
            <div className="flex gap-1 md:gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-1.5 md:p-2 hover:bg-gray-100 rounded-lg transition-colors"><ChevronLeft className="w-4 h-4 md:w-5 h-5"/></button>
              <button onClick={() => setCurrentDate(new Date())} className="px-2 md:px-4 py-1.5 md:py-2 text-[10px] md:text-sm font-bold text-indigo-600 hover:bg-indigo-50 rounded-lg">Hiện tại</button>
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-1.5 md:p-2 hover:bg-gray-100 rounded-lg transition-colors"><ChevronRight className="w-4 h-4 md:w-5 h-5"/></button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-1 md:gap-4">
            {['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'].map(d => (
              <div key={d} className="text-center text-[8px] md:text-xs font-black text-gray-400 uppercase tracking-widest py-1 md:py-2">{d}</div>
            ))}
            {Array.from({ length: getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => (
              <div key={`empty-${i}`} className="h-14 md:h-32 bg-gray-50/50 rounded-lg md:rounded-2xl border border-dashed border-gray-100"></div>
            ))}
            {Array.from({ length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const dayReqs = requests.filter(r => r.date === dateStr);
              const isToday = new Date().toISOString().split('T')[0] === dateStr;

              return (
                <button 
                  key={day} 
                  onClick={() => handleDayClick(dateStr)}
                  className={`h-14 md:h-32 p-1 md:p-3 bg-white border border-gray-100 rounded-lg md:rounded-2xl hover:border-indigo-300 transition-all text-left relative overflow-hidden ${isToday ? 'ring-2 ring-indigo-500/20' : ''}`}
                >
                  <span className={`text-xs md:text-lg font-bold ${isToday ? 'text-indigo-600' : 'text-gray-900'}`}>{day}</span>
                  <div className="mt-0.5 md:mt-2 space-y-0.5">
                    {dayReqs.slice(0, 1).map(r => (
                      <div key={r.id} className="text-[7px] md:text-[10px] bg-indigo-50 text-indigo-700 px-1 md:px-2 py-0.5 rounded font-bold truncate">
                        {r.users?.name?.split(' ').pop()} - {r.total_hours}h
                      </div>
                    ))}
                    {dayReqs.length > 1 && (
                      <div className="text-[6px] md:text-[9px] text-gray-400 font-bold ml-0.5">
                        +{dayReqs.length - 1} <span className="hidden md:inline">khác</span>
                      </div>
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'personal' && (
        <Card title="Danh sách yêu cầu" className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left min-w-[500px] md:min-w-full">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-3 md:px-6 py-3 md:py-4 text-[9px] md:text-xs font-bold text-gray-400 uppercase tracking-widest">Ngày</th>
                  <th className="px-3 md:px-6 py-3 md:py-4 text-[9px] md:text-xs font-bold text-gray-400 uppercase tracking-widest">Nhân viên</th>
                  <th className="px-3 md:px-6 py-3 md:py-4 text-[9px] md:text-xs font-bold text-gray-400 uppercase tracking-widest">Thời gian</th>
                  <th className="px-3 md:px-6 py-3 md:py-4 text-[9px] md:text-xs font-bold text-gray-400 uppercase tracking-widest text-center">Tổng giờ</th>
                  <th className="px-3 md:px-6 py-3 md:py-4 text-[9px] md:text-xs font-bold text-gray-400 uppercase tracking-widest">Trạng thái</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {requests.length === 0 ? (
                  <tr><td colSpan={5} className="px-6 py-12 text-center text-gray-400">Không có dữ liệu</td></tr>
                ) : (
                  requests.map(r => (
                    <tr key={r.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-3 md:px-6 py-3 md:py-4 text-xs md:text-sm font-bold">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                      <td className="px-3 md:px-6 py-3 md:py-4 text-xs md:text-sm font-bold text-gray-900">{r.users?.name || '-'}</td>
                      <td className="px-3 md:px-6 py-3 md:py-4 text-[10px] md:text-xs text-gray-500 font-medium">{r.start_time} - {r.end_time}</td>
                      <td className="px-3 md:px-6 py-3 md:py-4 text-center text-xs md:text-sm font-black text-indigo-600">{r.total_hours}h</td>
                      <td className="px-3 md:px-6 py-3 md:py-4">
                        <span className={`px-2 md:px-3 py-0.5 md:py-1 rounded-full text-[8px] md:text-[10px] font-black uppercase ${r.status === 'approved' ? 'bg-green-100 text-green-700' : r.status === 'pending' ? 'bg-amber-100 text-amber-700' : 'bg-rose-100 text-rose-700'}`}>
                          {r.status === 'approved' ? 'Duyệt' : r.status === 'pending' ? 'Chờ' : 'Hủy'}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-3 md:p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl md:rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in">
            <div className="p-4 md:p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50/30">
              <div>
                <h3 className="text-sm md:text-lg font-bold text-gray-900">
                  {editingRequestId ? 'Sửa OT' : 'Đăng ký OT'}
                </h3>
                <p className="text-[10px] md:text-xs text-gray-500 font-medium">{selectedDateStr}</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-1.5 md:p-2 hover:bg-gray-100 rounded-xl transition-colors"><X className="w-5 h-5 text-gray-400"/></button>
            </div>

            <div className="p-4 md:p-6 space-y-3 md:space-y-4">
              {isAdmin && (
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 ml-1">Nhân viên</label>
                  <div className="relative">
                    <select 
                      value={targetUserId} 
                      onChange={e => setTargetUserId(e.target.value)} 
                      className="w-full pl-3 pr-8 py-2 md:py-3 bg-gray-50 rounded-xl text-xs md:text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 border-none appearance-none"
                    >
                      {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name}</option>)}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 ml-1">Bắt đầu</label>
                  <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-3 py-2 md:py-3 bg-gray-50 rounded-xl text-xs md:text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 border-none"/>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 ml-1">Kết thúc</label>
                  <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-3 py-2 md:py-3 bg-gray-50 rounded-xl text-xs md:text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500 border-none"/>
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 ml-1">Lý do</label>
                <div className="relative">
                  <textarea 
                    value={reason} 
                    onChange={e => setReason(e.target.value)} 
                    placeholder="Công việc cụ thể..." 
                    className="w-full px-3 py-2 md:py-3 bg-gray-50 rounded-xl text-xs md:text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 border-none min-h-[80px] md:min-h-[100px] resize-none pr-10"
                  ></textarea>
                  <button onClick={handleRewrite} disabled={isRewriting || !reason.trim()} className="absolute right-2 bottom-2 p-1.5 bg-white text-indigo-600 rounded-lg shadow-sm hover:shadow-md transition-all disabled:opacity-50 border border-gray-100">
                    {isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>}
                  </button>
                </div>
              </div>

              <div className="p-3 md:p-4 bg-indigo-50 rounded-xl md:rounded-2xl flex items-center justify-between border border-indigo-100">
                <div className="flex items-center gap-2">
                  <div className="w-6 h-6 md:w-8 h-8 bg-white rounded-lg flex items-center justify-center text-indigo-600 shadow-sm">
                    <Timer className="w-4 h-4 md:w-5 h-5" />
                  </div>
                  <span className="text-[10px] md:text-xs font-bold text-indigo-600 uppercase tracking-widest">Dự kiến OT</span>
                </div>
                <span className="text-lg md:text-xl font-black text-indigo-700">{calculatedHours}h</span>
              </div>
            </div>

            <div className="p-4 md:p-6 bg-gray-50/50 flex gap-2 md:gap-3">
              <button 
                onClick={() => setIsModalOpen(false)} 
                className="flex-1 py-2 md:py-3 bg-white text-gray-500 font-bold rounded-xl border border-gray-200 hover:bg-gray-100 transition-all text-xs md:text-sm active:scale-95"
              >
                Hủy
              </button>
              <button 
                onClick={handleSaveRequest} 
                disabled={isSubmitting} 
                className="flex-[1.5] py-2 md:py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all disabled:opacity-50 text-xs md:text-sm flex items-center justify-center gap-2 active:scale-95"
              >
                {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Save className="w-4 h-4"/>}
                {editingRequestId ? 'Lưu thay đổi' : 'Gửi đăng ký'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, User as UserIcon, Check, Trash2, Info,
  AlertTriangle, Search, ToggleLeft, ToggleRight, List, ChevronDown, Edit
} from 'lucide-react';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  // Logic kiểm tra xem nhân viên đang chọn đã có đơn OT trong ngày đang chọn chưa
  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  // Cập nhật form khi thay đổi ngày hoặc nhân viên (cho Admin)
  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        // Nếu đã có đơn, chuyển sang chế độ Sửa
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        // Nếu chưa có đơn, set default theo cấu hình ngày
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('17:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0); // Giới hạn max 22h đêm
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");

    // Yêu cầu xác nhận nếu Admin đang ghi đè lên đơn cũ
    if (editingRequestId && isAdmin && targetUserId !== user.id) {
        const confirmed = window.confirm("Nhân viên này đã có đơn OT trong ngày này. Bạn có chắc chắn muốn CẬP NHẬT đơn hiện tại không?");
        if (!confirmed) return;
    }

    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'pending'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  const handleDayClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    // Khi mở modal, mặc định chọn chính mình nếu không phải là admin đang xem đơn cụ thể
    if (!isAdmin) setTargetUserId(user.id);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-4 md:space-y-6 max-w-5xl mx-auto pb-10">
      {/* Header section optimized for mobile */}
      <div className="flex flex-col gap-4 bg-white p-4 md:p-6 rounded-2xl md:rounded-3xl shadow-sm border border-gray-100">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="p-2 md:p-3 bg-indigo-600 rounded-xl md:rounded-2xl text-white shadow-lg shadow-indigo-100">
              <Clock className="w-6 h-6 md:w-8 h-8" />
            </div>
            <div>
              <h2 className="text-xl md:text-2xl font-bold text-gray-900 leading-tight">Đăng ký Tăng ca</h2>
              <p className="text-[10px] md:text-sm text-gray-400 font-bold uppercase tracking-widest">Lịch trình OT hệ thống</p>
            </div>
          </div>
        </div>

        {/* Responsive Tabs */}
        <div className="flex bg-gray-100 p-1 rounded-xl md:rounded-2xl w-full">
          <button 
            onClick={() => setActiveTab('calendar')} 
            className={`flex-1 py-2.5 rounded-lg md:rounded-xl text-xs md:text-sm font-black uppercase tracking-widest transition-all ${activeTab === 'calendar' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}
          >
            Lịch
          </button>
          <button 
            onClick={() => setActiveTab('personal')} 
            className={`flex-1 py-2.5 rounded-lg md:rounded-xl text-xs md:text-sm font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}
          >
            Danh sách
          </button>
        </div>
      </div>

      {activeTab === 'calendar' && (
        <Card className="p-3 md:p-8 rounded-[2rem] md:rounded-[3rem] border-none shadow-xl overflow-hidden">
          <div className="flex items-center justify-between mb-4 md:mb-8 px-1">
            <h3 className="text-base md:text-xl font-black text-gray-900 flex items-center gap-2 uppercase tracking-tight">
              <CalendarIcon className="w-5 h-5 text-indigo-500 hidden md:block" />
              Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}
            </h3>
            <div className="flex gap-1 md:gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-100 rounded-xl transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
              <button onClick={() => setCurrentDate(new Date())} className="px-3 md:px-5 py-2 text-[10px] md:text-xs font-black uppercase tracking-widest text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors">Hiện tại</button>
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-100 rounded-xl transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-1 md:gap-3">
            {['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'].map(d => (
              <div key={d} className="text-center text-[9px] md:text-xs font-black text-gray-400 uppercase tracking-widest py-1 md:py-3">{d}</div>
            ))}
            {Array.from({ length: getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => (
              <div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 rounded-xl md:rounded-2xl border border-dashed border-gray-100"></div>
            ))}
            {Array.from({ length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const dayReqs = requests.filter(r => r.date === dateStr);
              const isToday = new Date().toISOString().split('T')[0] === dateStr;

              return (
                <button 
                  key={day} 
                  onClick={() => handleDayClick(dateStr)}
                  className={`h-16 md:h-32 p-1.5 md:p-4 bg-white border border-gray-100 rounded-xl md:rounded-2xl hover:border-indigo-300 transition-all text-left relative overflow-hidden group shadow-sm hover:shadow-lg ${isToday ? 'ring-2 ring-indigo-500' : ''}`}
                >
                  <span className={`text-xs md:text-xl font-black ${isToday ? 'text-indigo-600' : 'text-gray-900'}`}>{day}</span>
                  <div className="mt-1 md:mt-3 space-y-0.5 md:space-y-1.5">
                    {dayReqs.slice(0, 1).map(r => (
                      <div key={r.id} className="text-[7px] md:text-[10px] bg-indigo-50 text-indigo-700 px-1 md:px-2 py-0.5 md:py-1 rounded-md font-black truncate border border-indigo-100">
                        {r.users?.name?.split(' ').pop()} {r.total_hours}h
                      </div>
                    ))}
                    {dayReqs.length > 1 && (
                      <div className="text-[6px] md:text-[9px] text-gray-400 font-bold ml-1">
                        +{dayReqs.length - 1} <span className="hidden md:inline">người nữa</span>
                      </div>
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'personal' && (
        <Card className="p-0 rounded-[2rem] md:rounded-[3rem] border-none shadow-xl overflow-hidden bg-white">
          <div className="overflow-x-auto">
            <table className="w-full text-left min-w-[600px] md:min-w-full">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100">
                  <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Ngày</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Nhân viên</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Thời gian</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">Tổng giờ</th>
                  <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Trạng thái</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {requests.length === 0 ? (
                  <tr><td colSpan={5} className="px-6 py-20 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Chưa có đăng ký nào</td></tr>
                ) : (
                  requests.map(r => (
                    <tr key={r.id} className="hover:bg-indigo-50/20 transition-all duration-300 group">
                      <td className="px-6 py-5 text-xs md:text-sm font-black text-gray-900">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                      <td className="px-6 py-5">
                         <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center font-black text-[10px] text-gray-500">{r.users?.name?.charAt(0)}</div>
                            <span className="text-xs md:text-sm font-bold text-gray-700">{r.users?.name || '-'}</span>
                         </div>
                      </td>
                      <td className="px-6 py-5 text-[10px] md:text-xs text-gray-400 font-black uppercase tracking-tighter">{r.start_time} - {r.end_time}</td>
                      <td className="px-6 py-5 text-center text-xs md:text-sm font-black text-indigo-600 tabular-nums">{r.total_hours}h</td>
                      <td className="px-6 py-5">
                        <span className={`px-3 py-1.5 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-widest shadow-sm ${r.status === 'approved' ? 'bg-emerald-500 text-white' : r.status === 'pending' ? 'bg-amber-500 text-white' : 'bg-rose-500 text-white'}`}>
                          {r.status === 'approved' ? 'Đã duyệt' : r.status === 'pending' ? 'Chờ duyệt' : 'Từ chối'}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-3 md:p-4 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[2.5rem] md:rounded-[4rem] shadow-2xl w-full max-w-md overflow-hidden animate-zoom-in border border-white/20">
            <div className={`p-6 md:p-10 border-b border-gray-100 flex justify-between items-center ${editingRequestId ? 'bg-indigo-50/50' : 'bg-white'}`}>
              <div>
                <h3 className="text-xl md:text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none flex items-center gap-2">
                  {editingRequestId ? <Edit className="w-5 h-5 text-indigo-600" /> : <Clock className="w-5 h-5 text-indigo-600" />}
                  {editingRequestId ? 'Cập nhật OT' : 'Đăng ký OT'}
                </h3>
                <p className="text-[10px] md:text-xs text-gray-400 font-black uppercase tracking-[0.2em] mt-2">{selectedDateStr}</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-gray-100 rounded-3xl transition-all active:scale-90"><X className="w-6 h-6 text-gray-400"/></button>
            </div>

            <div className="p-6 md:p-10 space-y-6 bg-white">
              {isAdmin && (
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nhân viên đăng ký</label>
                  <div className="relative group">
                    <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 w-4 h-4 group-focus-within:text-indigo-500" />
                    <select 
                      value={targetUserId} 
                      onChange={e => setTargetUserId(e.target.value)} 
                      className="w-full pl-12 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 appearance-none cursor-pointer transition-all"
                    >
                      {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                  </div>
                  {/* Cảnh báo ghi đè nếu Admin đang sửa đơn cũ */}
                  {editingRequestId && targetUserId !== user.id && (
                    <div className="flex items-center gap-2 mt-2 px-3 py-2 bg-amber-50 text-amber-700 rounded-xl border border-amber-100 animate-pulse">
                      <AlertTriangle className="w-4 h-4" />
                      <span className="text-[9px] font-black uppercase tracking-tight">Nhân viên đã có đơn OT - Chế độ CẬP NHẬT</span>
                    </div>
                  )}
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Bắt đầu</label>
                  <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Kết thúc</label>
                  <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nội dung công việc</label>
                <div className="relative group">
                  <textarea 
                    value={reason} 
                    onChange={e => setReason(e.target.value)} 
                    placeholder="Ghi chú chi tiết công việc..." 
                    className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-medium outline-none focus:ring-4 focus:ring-indigo-500/10 min-h-[100px] resize-none pr-12 transition-all"
                  ></textarea>
                  <button onClick={handleRewrite} disabled={isRewriting || !reason.trim()} className="absolute right-3 bottom-3 p-2 bg-white text-indigo-600 rounded-xl shadow-lg hover:shadow-indigo-100 transition-all disabled:opacity-50 border border-gray-100">
                    {isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>}
                  </button>
                </div>
              </div>

              <div className="p-5 md:p-6 bg-indigo-600 rounded-[2rem] flex items-center justify-between shadow-xl shadow-indigo-100 border-2 border-indigo-400">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 md:w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white">
                    <Timer className="w-5 h-5 md:w-6 h-6" />
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-white/70 uppercase tracking-widest leading-none mb-1">Dự kiến OT</span>
                    <span className="text-white text-[10px] font-bold opacity-60">Thanh toán sau duyệt</span>
                  </div>
                </div>
                <span className="text-2xl md:text-3xl font-black text-white tracking-tighter tabular-nums">{calculatedHours}h</span>
              </div>
            </div>

            <div className="p-8 md:p-10 bg-gray-50/50 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleSaveRequest} 
                disabled={isSubmitting} 
                className={`w-full py-5 md:py-6 text-white font-black rounded-[2rem] shadow-2xl transition-all flex items-center justify-center gap-3 uppercase tracking-[0.2em] text-xs active:scale-95 ${editingRequestId ? 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                {isSubmitting ? <Loader2 className="w-6 h-6 animate-spin"/> : <Save className="w-6 h-6"/>}
                {editingRequestId ? 'LƯU THAY ĐỔI' : 'XÁC NHẬN ĐĂNG KÝ'}
              </button>
              <button 
                onClick={() => setIsModalOpen(false)} 
                className="w-full py-5 md:py-6 bg-white text-gray-400 font-black rounded-[2rem] border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-[0.2em] transition-all active:scale-95 shadow-sm"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, User as UserIcon, Check, Trash2, Info,
  AlertTriangle, Search, ToggleLeft, ToggleRight, List, ChevronDown, Edit
} from 'lucide-react';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';

  // Kiểm tra xem tổ hợp (Ngày + Nhân viên) đã tồn tại đơn OT chưa
  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  // Cập nhật form tự động khi đổi ngày hoặc đổi nhân viên (dành cho Admin)
  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        // Chế độ Cập nhật: Load dữ liệu cũ
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        // Chế độ Đăng ký mới: Set giờ mặc định
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('17:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");

    // Yêu cầu xác nhận nếu Admin đang chuẩn bị ghi đè/sửa đơn của người khác
    if (editingRequestId && isAdmin && targetUserId !== user.id) {
        const confirmed = window.confirm(`Nhân viên này đã có đơn đăng ký vào ngày ${selectedDateStr}. Bạn có chắc chắn muốn CẬP NHẬT đơn hiện tại này không?`);
        if (!confirmed) return;
    }

    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'pending'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  const handleDayClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    if (!isAdmin) setTargetUserId(user.id);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-4 md:space-y-6 max-w-5xl mx-auto pb-10">
      {/* Header section optimized for mobile */}
      <div className="flex flex-col gap-4 bg-white p-4 md:p-6 rounded-2xl md:rounded-3xl shadow-sm border border-gray-100">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="p-2 md:p-3 bg-indigo-600 rounded-xl md:rounded-2xl text-white shadow-lg shadow-indigo-100">
              <Clock className="w-6 h-6 md:w-8 h-8" />
            </div>
            <div>
              <h2 className="text-xl md:text-2xl font-bold text-gray-900 leading-tight">Đăng ký Tăng ca</h2>
