import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLayoutDashboard, LucideLoader2, UserCircle } from 'lucide-react';

interface LoginFormProps {
  onLoginSuccess: (user: any) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onLoginSuccess }) => {
  const [employeeCode, setEmployeeCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        employeeCode,
        password,
      });

      if (error) {
        setError(error.message);
      } else if (data?.user) {
        localStorage.setItem('sb-session', JSON.stringify(data.session));
        onLoginSuccess(data.user);
      }
    } catch (err) {
      setError('Đã xảy ra lỗi không mong muốn.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden">
        <div className="bg-blue-800 p-8 text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
                <div className="absolute top-[-50px] left-[-50px] w-32 h-32 bg-white rounded-full"></div>
                <div className="absolute bottom-[-30px] right-[-30px] w-24 h-24 bg-white rounded-full"></div>
            </div>

          <div className="mx-auto bg-white/20 w-20 h-20 rounded-full flex items-center justify-center mb-4 backdrop-blur-sm border border-white/30 shadow-lg relative z-10">
            <LucideLayoutDashboard className="text-white w-10 h-10" />
          </div>
          <h2 className="text-3xl font-bold text-white mb-1 relative z-10">Manager Tool</h2>
          <p className="text-blue-200 text-sm relative z-10">Hệ thống quản lý nội bộ</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Mã nhân viên</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <UserCircle className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
                  className="w-full pl-10 pr-4 py-3 rounded-lg border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all uppercase placeholder:normal-case text-gray-900 shadow-sm outline-none"
                  placeholder="Nhập mã NV..."
                  required
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Mật khẩu</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 rounded-lg border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all text-gray-900 shadow-sm outline-none"
                placeholder="••••••••"
                required
              />
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 flex items-center gap-2">
                <span className="w-1.5 h-1.5 bg-red-600 rounded-full"></span>
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-700 hover:bg-blue-800 text-white font-semibold py-3.5 px-4 rounded-lg transition-colors flex items-center justify-center disabled:opacity-70 disabled:cursor-not-allowed shadow-lg shadow-blue-700/30"
            >
              {loading ? (
                <>
                  <LucideLoader2 className="w-5 h-5 animate-spin mr-2" />
                  Đang xác thực...
                </>
              ) : (
                'Đăng nhập hệ thống'
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus, Share2, ToggleLeft, ToggleRight, Eye, MousePointer2, CalendarRange, FileDown, ArrowRight, Zap, List, ChevronDown, ChevronUp, Edit
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const currentMonthStr = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';

  // Check if target user has a request for the selected date
  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('20:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");

    // Safety check for Admins
    if (editingRequestId && isAdmin && targetUserId !== user.id) {
        const confirmed = window.confirm(`Nhân viên này đã có đơn OT vào ngày ${selectedDateStr}. Bạn có chắc chắn muốn CẬP NHẬT đè lên đơn cũ không?`);
        if (!confirmed) return;
    }

    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'approved'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng thời gian này.");

    filtered.sort((a, b) => a.date.localeCompare(b.date));
    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    const summaryData = filtered.map(req => {
      const d = new Date(req.date);
      return {
        'Ngày': req.date,
        'Thứ': dayNames[d.getDay()],
        'Nhân viên': req.users?.name || req.user_id,
        'Bắt đầu': req.start_time,
        'Kết thúc': req.end_time,
        'Tổng giờ': req.total_hours,
        'Lý do': req.reason
      };
    });

    const worksheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, worksheet, "Overtime");
    XLSX.writeFile(workbook, `OT_Report_${start}_to_${end}.xlsx`);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  return (
    <div className="space-y-4 md:space-y-6 max-w-7xl mx-auto pb-10">
      {/* Header Optimized for Mobile */}
      <div className="flex flex-col gap-4 bg-white p-4 md:p-6 rounded-2xl md:rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-3 md:gap-4">
          <div className="p-3 bg-indigo-600 rounded-xl md:rounded-2xl text-white shadow-lg shadow-indigo-100">
            <Clock className="w-6 h-6 md:w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 leading-tight">Đăng ký Tăng ca</h2>
            <p className="text-[10px] md:text-sm text-gray-400 font-bold uppercase tracking-widest">Manager Tool V2</p>
          </div>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-xl md:rounded-2xl w-full">
          <button onClick={() => setActiveTab('calendar')} className={`flex-1 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-black transition-all ${activeTab === 'calendar' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>Lịch</button>
          <button onClick={() => setActiveTab('personal')} className={`flex-1 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-black transition-all ${activeTab === 'personal' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>Cá nhân</button>
          <button onClick={() => setActiveTab('stats')} className={`flex-1 py-2 rounded-lg md:rounded-xl text-xs md:text-sm font-black transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>Thống kê</button>
        </div>
      </div>

      {activeTab === 'calendar' && (
        <Card className="p-3 md:p-8 rounded-2xl md:rounded-[3rem] border-none shadow-xl overflow-hidden">
          <div className="flex items-center justify-between mb-4 md:mb-8 px-1">
            <h3 className="text-base md:text-xl font-black text-gray-900 flex items-center gap-2 uppercase">
              Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}
            </h3>
            <div className="flex gap-1 md:gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-1.5 md:p-2 hover:bg-gray-100 rounded-lg"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
              <button onClick={() => setCurrentDate(new Date())} className="px-3 md:px-5 py-2 text-[10px] md:text-xs font-black uppercase tracking-widest text-indigo-600">Hiện tại</button>
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-1.5 md:p-2 hover:bg-gray-100 rounded-lg"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
            </div>
          </div>
          <div className="grid grid-cols-7 gap-1 md:gap-3">
            {['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'].map(d => (
              <div key={d} className="text-center text-[9px] md:text-xs font-black text-gray-400 uppercase tracking-widest py-1 md:py-3">{d}</div>
            ))}
            {Array.from({ length: getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => (
              <div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 rounded-xl md:rounded-2xl border border-dashed border-gray-100"></div>
            ))}
            {Array.from({ length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const dayReqs = requests.filter(r => r.date === dateStr);
              const isToday = new Date().toISOString().split('T')[0] === dateStr;
              return (
                <button 
                  key={day} 
                  onClick={() => { setSelectedDateStr(dateStr); setIsModalOpen(true); }}
                  className={`h-16 md:h-32 p-1.5 md:p-4 bg-white border border-gray-100 rounded-xl md:rounded-2xl hover:border-indigo-300 transition-all text-left relative overflow-hidden group shadow-sm hover:shadow-lg ${isToday ? 'ring-2 ring-indigo-500' : ''}`}
                >
                  <span className={`text-xs md:text-xl font-black ${isToday ? 'text-indigo-600' : 'text-gray-900'}`}>{day}</span>
                  <div className="mt-1 md:mt-3 space-y-0.5">
                    {dayReqs.slice(0, 1).map(r => (
                      <div key={r.id} className="text-[7px] md:text-[10px] bg-indigo-50 text-indigo-700 px-1 md:px-2 py-0.5 rounded font-black truncate">
                        {r.users?.name?.split(' ').pop()} {r.total_hours}h
                      </div>
                    ))}
                    {dayReqs.length > 1 && <div className="text-[6px] md:text-[9px] text-gray-400 font-bold">+{dayReqs.length - 1}</div>}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'personal' && (
        <div className="space-y-6 animate-fade-in">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Card className="bg-indigo-600 text-white p-6 rounded-[2rem] border-none shadow-xl">
               <h3 className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-2">Tổng giờ tháng này</h3>
               <p className="text-4xl md:text-5xl font-black">{myStats.total.toFixed(1)}h</p>
            </Card>
            <Card className="p-6 rounded-[2rem] border-none shadow-xl flex items-center justify-between">
               <div>
                  <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Xuất dữ liệu cá nhân</h3>
                  <button onClick={() => handleExportExcel('personal')} className="flex items-center gap-2 bg-emerald-600 text-white px-6 py-3 rounded-xl text-xs font-black uppercase shadow-lg shadow-emerald-100 active:scale-95 transition-all">
                    <Download className="w-4 h-4"/> Tải Excel
                  </button>
               </div>
               <FileSpreadsheet className="w-16 h-16 text-gray-100"/>
            </Card>
          </div>
          <Card className="p-0 rounded-[2rem] shadow-xl overflow-hidden border-none bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b border-gray-100">
                  <tr>
                    <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Ngày</th>
                    <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Tổng giờ</th>
                    <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">Lý do</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {requests.filter(r => r.user_id === user.id).length === 0 ? (
                    <tr><td colSpan={3} className="px-6 py-20 text-center text-gray-300 font-black italic uppercase">Chưa có dữ liệu</td></tr>
                  ) : (
                    requests.filter(r => r.user_id === user.id).map(r => (
                      <tr key={r.id} className="hover:bg-indigo-50/20 transition-all">
                        <td className="px-6 py-4 text-xs md:text-sm font-black">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                        <td className="px-6 py-4 text-center text-xs md:text-sm font-black text-indigo-600">{r.total_hours}h</td>
                        <td className="px-6 py-4 text-xs text-gray-500 font-medium">{r.reason}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </Card>
        </div>
      )}

      {activeTab === 'stats' && (
        <div className="space-y-6 animate-fade-in">
           <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <Card className="lg:col-span-1 rounded-[2rem] shadow-xl p-6 bg-white flex flex-col">
                 <h4 className="font-black text-gray-800 text-sm uppercase tracking-widest mb-6">TOP CHIẾN THẦN OT</h4>
                 <div className="space-y-4 flex-1">
                    {top5.map((emp, idx) => (
                      <div key={idx} className="flex items-center gap-4 p-3 rounded-2xl border border-gray-100">
                         <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-white ${idx === 0 ? 'bg-amber-500' : idx === 1 ? 'bg-slate-400' : idx === 2 ? 'bg-orange-400' : 'bg-indigo-500'}`}>
                            {idx + 1}
                         </div>
                         <div className="flex-1">
                            <p className="font-black text-xs text-gray-900 truncate">{emp.name}</p>
                            <p className="text-[9px] font-bold text-gray-400 uppercase">{emp.employee_id}</p>
                         </div>
                         <p className="text-sm font-black text-indigo-600">{emp.hours.toFixed(1)}h</p>
                      </div>
                    ))}
                 </div>
              </Card>
              <Card className="lg:col-span-2 rounded-[2rem] shadow-xl p-6 bg-white">
                 <h4 className="font-black text-gray-800 text-sm uppercase tracking-widest mb-6">XU HƯỚNG TĂNG CA</h4>
                 <div className="h-64">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={myStats.trend}>
                         <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                         <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                         <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                         <Tooltip />
                         <Bar dataKey="hours" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                 </div>
              </Card>
           </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-3 md:p-4 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[2rem] md:rounded-[4rem] shadow-2xl w-full max-w-md overflow-hidden animate-zoom-in">
            <div className="p-6 md:p-10 border-b border-gray-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl md:text-2xl font-black text-gray-900 uppercase tracking-tighter">
                  {editingRequestId ? 'Cập nhật OT' : 'Đăng ký OT'}
                </h3>
                <p className="text-[10px] md:text-xs text-gray-400 font-black uppercase tracking-widest mt-2">{selectedDateStr}</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-gray-100 rounded-3xl transition-all"><X className="w-6 h-6 text-gray-400"/></button>
            </div>

            <div className="p-6 md:p-10 space-y-6">
              {isAdmin && (
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nhân viên đăng ký</label>
                  <div className="relative">
                    <select value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 appearance-none transition-all">
                      {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                  </div>
                  {editingRequestId && (
                    <div className="flex items-center gap-2 mt-2 px-3 py-2 bg-amber-50 text-amber-700 rounded-xl border border-amber-100">
                      <AlertTriangle className="w-4 h-4" />
                      <span className="text-[9px] font-black uppercase">Chế độ CẬP NHẬT đè lên đơn cũ</span>
                    </div>
                  )}
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Bắt đầu</label>
                  <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Kết thúc</label>
                  <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Lý do công việc</label>
                <div className="relative">
                  <textarea value={reason} onChange={e => setReason(e.target.value)} placeholder="Mô tả công việc chi tiết..." className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-medium outline-none focus:ring-4 focus:ring-indigo-500/10 min-h-[100px] resize-none pr-12 transition-all"></textarea>
                  <button onClick={handleRewrite} disabled={isRewriting || !reason.trim()} className="absolute right-3 bottom-3 p-2 bg-white text-indigo-600 rounded-xl shadow-lg hover:shadow-indigo-100 transition-all disabled:opacity-50">
                    {isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>}
                  </button>
                </div>
              </div>

              <div className="p-5 md:p-6 bg-indigo-600 rounded-[2rem] flex items-center justify-between shadow-xl shadow-indigo-100">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white"><Timer className="w-5 h-5" /></div>
                  <span className="text-[10px] font-black text-white/70 uppercase tracking-widest">Dự kiến OT</span>
                </div>
                <span className="text-2xl md:text-3xl font-black text-white">{calculatedHours}h</span>
              </div>
            </div>

            <div className="p-8 md:p-10 bg-gray-50 flex flex-col gap-4 border-t border-gray-100">
              <button onClick={handleSaveRequest} disabled={isSubmitting} className="w-full py-5 md:py-6 bg-indigo-600 text-white font-black rounded-[2rem] shadow-2xl shadow-indigo-100 uppercase tracking-widest text-xs active:scale-95 transition-all">
                {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5 mr-2 inline"/>} 
                XÁC NHẬN ĐĂNG KÝ
              </button>
              <button onClick={() => setIsModalOpen(false)} className="w-full py-5 md:py-6 bg-white text-gray-400 font-black rounded-[2rem] border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-widest active:scale-95 transition-all">HỦY BỎ</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLayoutDashboard, LucideLoader2, UserCircle } from 'lucide-react';

interface LoginFormProps {
  onLoginSuccess: (user: any) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onLoginSuccess }) => {
  const [employeeCode, setEmployeeCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        employeeCode,
        password,
      });

      if (error) {
        setError(error.message);
      } else if (data?.user) {
        localStorage.setItem('sb-session', JSON.stringify(data.session));
        onLoginSuccess(data.user);
      }
    } catch (err) {
      setError('Đã xảy ra lỗi không mong muốn.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden">
        <div className="bg-blue-800 p-8 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
            <div className="absolute top-[-50px] left-[-50px] w-32 h-32 bg-white rounded-full"></div>
            <div className="absolute bottom-[-30px] right-[-30px] w-24 h-24 bg-white rounded-full"></div>
          </div>

          <div className="mx-auto bg-white/20 w-20 h-20 rounded-full flex items-center justify-center mb-4 backdrop-blur-sm border border-white/30 shadow-lg relative z-10">
            <LucideLayoutDashboard className="text-white w-10 h-10" />
          </div>
          <h2 className="text-3xl font-bold text-white mb-1 relative z-10">Manager Tool</h2>
          <p className="text-blue-200 text-sm relative z-10">Hệ thống quản lý nội bộ</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Mã nhân viên</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <UserCircle className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
                  className="w-full pl-10 pr-4 py-3 rounded-lg border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all uppercase placeholder:normal-case text-gray-900 shadow-sm outline-none"
                  placeholder="Nhập mã NV..."
                  required
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Mật khẩu</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 rounded-lg border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all text-gray-900 shadow-sm outline-none"
                placeholder="••••••••"
                required
              />
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 flex items-center gap-2">
                <span className="w-1.5 h-1.5 bg-red-600 rounded-full"></span>
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-700 hover:bg-blue-800 text-white font-semibold py-3.5 px-4 rounded-lg transition-colors flex items-center justify-center disabled:opacity-70 disabled:cursor-not-allowed shadow-lg shadow-blue-700/30"
            >
              {loading ? (
                <>
                  <LucideLoader2 className="w-5 h-5 animate-spin mr-2" />
                  Đang xác thực...
                </>
              ) : (
                'Đăng nhập hệ thống'
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, 
  Wand2, Download, BarChart3, Users, User as UserIcon, 
  Check, Edit, Trash2, Info, FileSpreadsheet, AlertTriangle, TrendingUp
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('17:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, currentSelectedRequest, dayConfigs]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");

    if (editingRequestId && isAdmin && targetUserId !== user.id) {
        const confirmed = window.confirm("Nhân viên này đã có đơn đăng ký. Bạn có chắc chắn muốn CẬP NHẬT không?");
        if (!confirmed) return;
    }

    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'approved'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string }> = {};
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthly.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A' };
        employeeMap[id].hours += Number(req.total_hours || 0);
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-10">
      <div className="flex flex-col gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-600 rounded-xl text-white shadow-lg shadow-indigo-100">
            <Clock className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Đăng ký Tăng ca</h2>
            <p className="text-sm text-gray-500">Quản lý lịch trình làm việc thêm giờ</p>
          </div>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-xl w-full">
          <button onClick={() => setActiveTab('calendar')} className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === 'calendar' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>Lịch</button>
          <button onClick={() => setActiveTab('personal')} className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === 'personal' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>Danh sách</button>
          <button onClick={() => setActiveTab('stats')} className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>Thống kê</button>
        </div>
      </div>

      {activeTab === 'calendar' && (
        <Card className="p-4 md:p-8">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}
            </h3>
            <div className="flex gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-100 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
              <button onClick={() => setCurrentDate(new Date())} className="px-3 py-1 text-xs font-bold text-indigo-600 hover:bg-indigo-50 rounded-lg">Hiện tại</button>
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-100 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-1 md:gap-3">
            {['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'].map(d => (
              <div key={d} className="text-center text-xs font-bold text-gray-400 uppercase py-2">{d}</div>
            ))}
            {Array.from({ length: getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => (
              <div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50 rounded-xl"></div>
            ))}
            {Array.from({ length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const dayReqs = requests.filter(r => r.date === dateStr);
              const isToday = new Date().toISOString().split('T')[0] === dateStr;

              return (
                <button 
                  key={day} 
                  onClick={() => { setSelectedDateStr(dateStr); setIsModalOpen(true); }}
                  className={`h-16 md:h-32 p-2 bg-white border border-gray-100 rounded-xl hover:border-indigo-300 transition-all text-left relative overflow-hidden shadow-sm ${isToday ? 'ring-2 ring-indigo-500' : ''}`}
                >
                  <span className={`text-sm md:text-lg font-bold ${isToday ? 'text-indigo-600' : 'text-gray-900'}`}>{day}</span>
                  <div className="mt-1 space-y-1">
                    {dayReqs.slice(0, 1).map(r => (
                      <div key={r.id} className="text-[8px] md:text-[10px] bg-indigo-50 text-indigo-700 px-1 rounded font-bold truncate">
                        {r.users?.name?.split(' ').pop()} {r.total_hours}h
                      </div>
                    ))}
                    {dayReqs.length > 1 && <div className="text-[7px] md:text-[9px] text-gray-400 ml-1">+{dayReqs.length - 1}</div>}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'personal' && (
        <Card className="p-0 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Ngày</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Nhân viên</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Thời gian</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase text-center">Tổng giờ</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase">Trạng thái</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {requests.length === 0 ? (
                  <tr><td colSpan={5} className="px-6 py-12 text-center text-gray-400">Không có dữ liệu</td></tr>
                ) : (
                  requests.map(r => (
                    <tr key={r.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm font-semibold">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                      <td className="px-6 py-4 text-sm font-medium text-gray-700">{r.users?.name || '-'}</td>
                      <td className="px-6 py-4 text-xs text-gray-500 font-medium">{r.start_time} - {r.end_time}</td>
                      <td className="px-6 py-4 text-center text-sm font-bold text-indigo-600">{r.total_hours}h</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase ${r.status === 'approved' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                          {r.status === 'approved' ? 'Đã duyệt' : 'Chờ duyệt'}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {activeTab === 'stats' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
           <Card title="Top tăng ca" className="md:col-span-1">
              <div className="space-y-4">
                 {top5.map((emp, idx) => (
                    <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                       <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-lg bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold text-xs">{idx + 1}</div>
                          <span className="text-sm font-semibold truncate max-w-[120px]">{emp.name}</span>
                       </div>
                       <span className="text-sm font-bold text-indigo-600">{emp.hours.toFixed(1)}h</span>
                    </div>
                 ))}
              </div>
           </Card>
           <Card title="Biểu đồ xu hướng" className="md:col-span-2">
              <div className="h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={myStats.trend}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10}} />
                    <Tooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                    <Bar dataKey="hours" fill="#4f46e5" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
           </Card>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-zoom-in">
            <div className="p-6 border-b flex justify-between items-center">
              <h3 className="text-lg font-bold text-gray-900">{editingRequestId ? 'Cập nhật OT' : 'Đăng ký OT'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600 transition-colors"><X className="w-6 h-6"/></button>
            </div>

            <div className="p-6 space-y-4">
              <div className="flex items-center gap-2 text-sm text-gray-500 font-medium">
                <CalendarIcon className="w-4 h-4" />
                Ngày: {selectedDateStr}
              </div>

              {isAdmin && (
                <div className="space-y-1">
                  <label className="text-xs font-bold text-gray-400 uppercase">Nhân viên</label>
                  <select value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500">
                    {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name}</option>)}
                  </select>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-gray-400 uppercase">Bắt đầu</label>
                  <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500"/>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-gray-400 uppercase">Kết thúc</label>
                  <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500"/>
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-400 uppercase">Lý do công việc</label>
                <div className="relative">
                  <textarea value={reason} onChange={e => setReason(e.target.value)} placeholder="Nhập lý do..." className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 min-h-[100px] resize-none pr-10"></textarea>
                  <button onClick={handleRewrite} disabled={isRewriting || !reason.trim()} className="absolute right-2 bottom-2 p-1.5 bg-white text-indigo-600 rounded-lg shadow hover:bg-indigo-50 transition-all disabled:opacity-50 border border-gray-100">
                    {isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>}
                  </button>
                </div>
              </div>

              <div className="p-4 bg-indigo-50 rounded-xl flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Timer className="w-5 h-5 text-indigo-600" />
                  <span className="text-sm font-bold text-indigo-600 uppercase">Dự kiến:</span>
                </div>
                <span className="text-xl font-bold text-indigo-700">{calculatedHours}h</span>
              </div>
            </div>

            <div className="p-6 bg-gray-50 flex gap-3">
              <button onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-white text-gray-500 font-bold rounded-xl border hover:bg-gray-100 transition-all">Hủy</button>
              <button onClick={handleSaveRequest} disabled={isSubmitting} className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg hover:bg-indigo-700 transition-all flex items-center justify-center gap-2 disabled:opacity-50">
                {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Save className="w-4 h-4"/>}
                Xác nhận
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLayoutDashboard, LucideLoader2, UserCircle } from 'lucide-react';

interface LoginFormProps {
  onLoginSuccess: (user: any) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onLoginSuccess }) => {
  const [employeeCode, setEmployeeCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        employeeCode,
        password,
      });

      if (error) {
        setError(error.message);
      } else if (data?.user) {
        localStorage.setItem('sb-session', JSON.stringify(data.session));
        onLoginSuccess(data.user);
      }
    } catch (err) {
      setError('Đã xảy ra lỗi không mong muốn.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-200">
        <div className="bg-slate-900 p-8 text-center relative overflow-hidden">
          <div className="mx-auto bg-blue-600 w-16 h-16 rounded-2xl flex items-center justify-center mb-4 shadow-lg shadow-blue-500/20">
            <LucideLayoutDashboard className="text-white w-8 h-8" />
          </div>
          <h2 className="text-2xl font-bold text-white mb-1">Manager Tool</h2>
          <p className="text-slate-400 text-xs uppercase tracking-widest font-semibold">Đăng nhập hệ thống</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-5">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Mã nhân viên</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <UserCircle className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500 transition-all uppercase outline-none font-medium"
                  placeholder="VD: NV001"
                  required
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Mật khẩu</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 rounded-xl border border-gray-200 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-blue-500 transition-all outline-none font-medium"
                placeholder="••••••••"
                required
              />
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-xs rounded-xl border border-red-100 font-medium">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-4 rounded-xl transition-all flex items-center justify-center disabled:opacity-70 shadow-lg shadow-blue-500/20 active:scale-[0.98]"
            >
              {loading ? <LucideLoader2 className="w-5 h-5 animate-spin mr-2" /> : 'Đăng nhập'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, 
  Wand2, Download, BarChart3, Users, User as UserIcon, 
  Check, Edit, Trash2, Info, FileSpreadsheet, AlertTriangle, TrendingUp, Search
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'list' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  // Kiểm tra xem nhân viên đang được chọn (targetUserId) đã có đơn vào ngày này chưa
  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  // Cập nhật form khi đổi ngày hoặc đổi nhân viên (dành cho Admin khi đăng ký thay)
  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('17:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, currentSelectedRequest, dayConfigs]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");

    // Cảnh báo xác nhận quan trọng cho Admin khi đăng ký hộ mà đã có đơn
    if (editingRequestId && isAdmin) {
        const empName = allEmployees.find(e => e.id === targetUserId)?.name || "nhân viên này";
        const confirmed = window.confirm(`CẢNH BÁO: ${empName} đã có đơn đăng ký vào ngày ${selectedDateStr}.\n\nBạn có chắc chắn muốn CẬP NHẬT đè lên đơn hiện tại của họ không?`);
        if (!confirmed) return;
    }

    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'approved'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    let filtered = requests;
    if (!isAdmin) filtered = filtered.filter(r => r.user_id === user.id);

    if (filtered.length === 0) return alert("Không có dữ liệu để xuất.");

    const workbook = XLSX.utils.book_new();
    const data = filtered.map(r => ({
      'Mã NV': r.users?.employee_id,
      'Nhân viên': r.users?.name,
      'Ngày': r.date,
      'Giờ bắt đầu': r.start_time,
      'Giờ kết thúc': r.end_time,
      'Tổng giờ': r.total_hours,
      'Lý do': r.reason,
      'Trạng thái': r.status === 'approved' ? 'Đã duyệt' : 'Chờ duyệt'
    }));

    const worksheet = XLSX.utils.json_to_sheet(data);
    XLSX.utils.book_append_sheet(workbook, worksheet, "Overtime");
    XLSX.writeFile(workbook, `OT_Report_${currentMonthStr}.xlsx`);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string }> = {};
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthly.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A' };
        employeeMap[id].hours += Number(req.total_hours || 0);
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  // Phân quyền dữ liệu cho tab Danh sách
  const displayRequests = useMemo(() => {
    if (isAdmin) return requests;
    return requests.filter(r => r.user_id === user.id);
  }, [requests, isAdmin, user.id]);

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-10">
      <div className="flex flex-col gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-600 rounded-xl text-white shadow-lg shadow-blue-100">
              <Clock className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-gray-900">Đăng ký Tăng ca</h2>
              <p className="text-sm text-gray-500">{isAdmin ? 'Quản lý toàn bộ danh sách tăng ca' : 'Quản lý lịch trình làm việc cá nhân'}</p>
            </div>
          </div>
          <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2.5 rounded-xl text-sm font-bold transition-all shadow-md">
            <FileSpreadsheet className="w-4 h-4" /> Xuất Excel
          </button>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-xl w-full">
          <button onClick={() => setActiveTab('calendar')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Lịch</button>
          <button onClick={() => setActiveTab('list')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'list' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>{isAdmin ? 'Tất cả đơn' : 'Danh sách của tôi'}</button>
          <button onClick={() => setActiveTab('stats')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Thống kê</button>
        </div>
      </div>

      {activeTab === 'calendar' && (
        <Card className="p-4 md:p-8">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}
            </h3>
            <div className="flex gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
              <button onClick={() => setCurrentDate(new Date())} className="px-3 py-1 text-xs font-bold text-blue-600 hover:bg-blue-50 rounded-lg">Hiện tại</button>
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-1 md:gap-3">
            {['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'].map(d => (
              <div key={d} className="text-center text-xs font-bold text-gray-400 uppercase py-2 tracking-wider">{d}</div>
            ))}
            {Array.from({ length: getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => (
              <div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50 rounded-xl"></div>
            ))}
            {Array.from({ length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const dayReqs = requests.filter(r => r.date === dateStr);
              const isToday = new Date().toISOString().split('T')[0] === dateStr;

              return (
                <button 
                  key={day} 
                  onClick={() => { setSelectedDateStr(dateStr); setTargetUserId(user.id); setIsModalOpen(true); }}
                  className={`h-16 md:h-32 p-2 bg-white border border-gray-100 rounded-xl hover:border-blue-300 transition-all text-left relative overflow-hidden shadow-sm ${isToday ? 'ring-2 ring-blue-500' : ''}`}
                >
                  <span className={`text-sm md:text-lg font-bold ${isToday ? 'text-blue-600' : 'text-gray-900'}`}>{day}</span>
                  <div className="mt-1 space-y-1">
                    {dayReqs.slice(0, 1).map(r => (
                      <div key={r.id} className="text-[8px] md:text-[10px] bg-blue-50 text-blue-700 px-1 rounded font-bold truncate">
                        {r.users?.name?.split(' ').pop()} {r.total_hours}h
                      </div>
                    ))}
                    {dayReqs.length > 1 && <div className="text-[7px] md:text-[9px] text-gray-400 ml-1">+{dayReqs.length - 1}</div>}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'list' && (
        <Card className="p-0 overflow-hidden border-none shadow-xl">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Ngày</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Nhân viên</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Thời gian</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Tổng giờ</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Trạng thái</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {displayRequests.length === 0 ? (
                  <tr><td colSpan={5} className="px-6 py-20 text-center text-gray-400 italic">Không có đăng ký nào được tìm thấy</td></tr>
                ) : (
                  displayRequests.map(r => (
                    <tr key={r.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm font-bold text-gray-900">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <div className="w-7 h-7 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-[10px] font-bold uppercase">{r.users?.name?.charAt(0)}</div>
                          <span className="text-sm font-semibold text-gray-700">{r.users?.name || '-'}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-xs text-gray-500 font-medium">{r.start_time} - {r.end_time}</td>
                      <td className="px-6 py-4 text-center text-sm font-bold text-blue-600">{r.total_hours}h</td>
                      <td className="px-6 py-4">
                        <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase ${r.status === 'approved' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                          {r.status === 'approved' ? 'Đã duyệt' : 'Chờ duyệt'}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {activeTab === 'stats' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
           <Card title="Xếp hạng tăng ca" className="md:col-span-1 border-none shadow-xl">
              <div className="space-y-4">
                 {top5.map((emp, idx) => (
                    <div key={idx} className="flex items-center justify-between p-3.5 bg-gray-50 rounded-2xl border border-gray-100">
                       <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${idx === 0 ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>{idx + 1}</div>
                          <span className="text-sm font-bold text-gray-800 truncate max-w-[120px]">{emp.name}</span>
                       </div>
                       <span className="text-sm font-black text-blue-600">{emp.hours.toFixed(1)}h</span>
                    </div>
                 ))}
              </div>
           </Card>
           <Card title="Biểu đồ giờ làm thêm" className="md:col-span-2 border-none shadow-xl">
              <div className="h-72">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={myStats.trend}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                    <Tooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                    <Bar dataKey="hours" fill="#2563eb" radius={[6, 6, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
           </Card>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50/50">
              <div>
                <h3 className="text-xl font-bold text-gray-900 leading-tight">
                    {editingRequestId ? 'Cập nhật đăng ký' : 'Đăng ký tăng ca mới'}
                </h3>
                <p className="text-xs text-gray-400 font-semibold mt-1">Ngày: {selectedDateStr}</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600 p-2 rounded-full hover:bg-gray-100 transition-all"><X className="w-6 h-6"/></button>
            </div>

            <div className="p-8 space-y-6">
              {isAdmin && (
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Nhân viên thực hiện</label>
                  <div className="relative">
                    <select 
                        value={targetUserId} 
                        onChange={e => setTargetUserId(e.target.value)} 
                        className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500 appearance-none transition-all"
                    >
                        {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                  </div>
                  {editingRequestId && (
                    <div className="flex items-center gap-2 mt-2 px-3 py-2 bg-amber-50 text-amber-700 rounded-xl border border-amber-100 text-[10px] font-bold uppercase animate-pulse">
                      <AlertTriangle className="w-3.5 h-3.5" /> Chế độ CẬP NHẬT đè đơn hiện tại
                    </div>
                  )}
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Bắt đầu</label>
                  <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500 transition-all"/>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Kết thúc</label>
                  <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500 transition-all"/>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Nội dung / Lý do</label>
                <div className="relative group">
                  <textarea 
                    value={reason} 
                    onChange={e => setReason(e.target.value)} 
                    placeholder="Mô tả công việc cần xử lý..." 
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 min-h-[100px] resize-none pr-12 transition-all"
                  ></textarea>
                  <button onClick={handleRewrite} disabled={isRewriting || !reason.trim()} className="absolute right-3 bottom-3 p-2 bg-white text-blue-600 rounded-lg shadow-md border border-gray-100 hover:bg-blue-50 transition-all active:scale-90 disabled:opacity-50">
                    {isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>}
                  </button>
                </div>
              </div>

              <div className="p-5 bg-blue-600 rounded-2xl flex items-center justify-between shadow-xl shadow-blue-500/20">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-white"><Timer className="w-5 h-5" /></div>
                  <span className="text-xs font-bold text-white uppercase tracking-widest opacity-90">Tổng cộng OT:</span>
                </div>
                <span className="text-3xl font-black text-white tabular-nums tracking-tighter">{calculatedHours}h</span>
              </div>
            </div>

            <div className="p-8 bg-gray-50 flex flex-col sm:flex-row gap-3">
              <button onClick={() => setIsModalOpen(false)} className="flex-1 py-4 bg-white text-gray-500 font-bold rounded-2xl border border-gray-200 hover:bg-gray-100 transition-all active:scale-[0.98]">Hủy bỏ</button>
              <button 
                onClick={handleSaveRequest} 
                disabled={isSubmitting} 
                className="flex-[2] py-4 bg-blue-600 text-white font-bold rounded-2xl shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center gap-2 active:scale-[0.98] disabled:opacity-50"
              >
                {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5"/>}
                Xác nhận đăng ký
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, 
  Wand2, Download, BarChart3, Users, User as UserIcon, 
  Check, Edit, Trash2, Info, FileSpreadsheet, AlertTriangle, TrendingUp, Search,
  ChevronDown
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'list' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  // Kiểm tra xem nhân viên đang được chọn (targetUserId) đã có đơn vào ngày này chưa
  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  // Cập nhật form khi đổi ngày hoặc đổi nhân viên (dành cho Admin khi đăng ký thay)
  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('17:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            setStartTime(isWorkDay ? '14:30' : '08:00');
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, currentSelectedRequest, dayConfigs]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSaveRequest = async () => {
    if (!reason.trim()) return alert("Vui lòng nhập lý do tăng ca");

    // Cảnh báo xác nhận quan trọng cho Admin khi đăng ký hộ mà đã có đơn
    if (editingRequestId && isAdmin) {
        const empName = allEmployees.find(e => e.id === targetUserId)?.name || "nhân viên này";
        const confirmed = window.confirm(`CẢNH BÁO: ${empName} đã có đơn đăng ký vào ngày ${selectedDateStr}.\n\nBạn có chắc chắn muốn CẬP NHẬT đè lên đơn hiện tại của họ không?`);
        if (!confirmed) return;
    }

    setIsSubmitting(true);
    const payload = {
      user_id: targetUserId,
      date: selectedDateStr,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      status: 'approved'
    };
    try {
      if (editingRequestId) {
        const { error } = await supabase.from('ot_requests').update(payload).eq('id', editingRequestId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('ot_requests').insert([payload]);
        if (error) throw error;
      }
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
      alert("Lỗi: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRewrite = async () => {
    if (!reason.trim()) return;
    setIsRewriting(true);
    const res = await rewriteOvertimeReason(reason);
    setReason(res);
    setIsRewriting(false);
  };

  const handleExportExcel = () => {
    let filtered = requests;
    if (!isAdmin) filtered = filtered.filter(r => r.user_id === user.id);

    if (filtered.length === 0) return alert("Không có dữ liệu để xuất.");

    const workbook = XLSX.utils.book_new();
    const data = filtered.map(r => ({
      'Mã NV': r.users?.employee_id,
      'Nhân viên': r.users?.name,
      'Ngày': r.date,
      'Giờ bắt đầu': r.start_time,
      'Giờ kết thúc': r.end_time,
      'Tổng giờ': r.total_hours,
      'Lý do': r.reason,
      'Trạng thái': r.status === 'approved' ? 'Đã duyệt' : 'Chờ duyệt'
    }));

    const worksheet = XLSX.utils.json_to_sheet(data);
    XLSX.utils.book_append_sheet(workbook, worksheet, "Overtime");
    XLSX.writeFile(workbook, `OT_Report_${currentMonthStr}.xlsx`);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string }> = {};
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthly.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A' };
        employeeMap[id].hours += Number(req.total_hours || 0);
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  // Phân quyền dữ liệu cho tab Danh sách
  const displayRequests = useMemo(() => {
    if (isAdmin) return requests;
    return requests.filter(r => r.user_id === user.id);
  }, [requests, isAdmin, user.id]);

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-10">
      <div className="flex flex-col gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-blue-600 rounded-xl text-white shadow-lg shadow-blue-100">
              <Clock className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-gray-900">Đăng ký Tăng ca</h2>
              <p className="text-sm text-gray-500">{isAdmin ? 'Quản lý toàn bộ danh sách tăng ca' : 'Quản lý lịch trình làm việc cá nhân'}</p>
            </div>
          </div>
          <button onClick={handleExportExcel} className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2.5 rounded-xl text-sm font-bold transition-all shadow-md">
            <FileSpreadsheet className="w-4 h-4" /> Xuất Excel
          </button>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-xl w-full">
          <button onClick={() => setActiveTab('calendar')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Lịch</button>
          <button onClick={() => setActiveTab('list')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'list' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>{isAdmin ? 'Tất cả đơn' : 'Danh sách của tôi'}</button>
          <button onClick={() => setActiveTab('stats')} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Thống kê</button>
        </div>
      </div>

      {activeTab === 'calendar' && (
        <Card className="p-4 md:p-8">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}
            </h3>
            <div className="flex gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
              <button onClick={() => setCurrentDate(new Date())} className="px-3 py-1 text-xs font-bold text-blue-600 hover:bg-blue-50 rounded-lg">Hiện tại</button>
              <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-1 md:gap-3">
            {['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'].map(d => (
              <div key={d} className="text-center text-xs font-bold text-gray-400 uppercase py-2 tracking-wider">{d}</div>
            ))}
            {Array.from({ length: getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => (
              <div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50 rounded-xl"></div>
            ))}
            {Array.from({ length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()) }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const dayReqs = requests.filter(r => r.date === dateStr);
              const isToday = new Date().toISOString().split('T')[0] === dateStr;

              return (
                <button 
                  key={day} 
                  onClick={() => { setSelectedDateStr(dateStr); setTargetUserId(user.id); setIsModalOpen(true); }}
                  className={`h-16 md:h-32 p-2 bg-white border border-gray-100 rounded-xl hover:border-blue-300 transition-all text-left relative overflow-hidden shadow-sm ${isToday ? 'ring-2 ring-blue-500' : ''}`}
                >
                  <span className={`text-sm md:text-lg font-bold ${isToday ? 'text-blue-600' : 'text-gray-900'}`}>{day}</span>
                  <div className="mt-1 space-y-1">
                    {dayReqs.slice(0, 1).map(r => (
                      <div key={r.id} className="text-[8px] md:text-[10px] bg-blue-50 text-blue-700 px-1 rounded font-bold truncate">
                        {r.users?.name?.split(' ').pop()} {r.total_hours}h
                      </div>
                    ))}
                    {dayReqs.length > 1 && <div className="text-[7px] md:text-[9px] text-gray-400 ml-1">+{dayReqs.length - 1}</div>}
                  </div>
                </button>
              );
            })}
          </div>
        </Card>
      )}

      {activeTab === 'list' && (
        <Card className="p-0 overflow-hidden border-none shadow-xl">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Ngày</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Nhân viên</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Thời gian</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Tổng giờ</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Trạng thái</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {displayRequests.length === 0 ? (
                  <tr><td colSpan={5} className="px-6 py-20 text-center text-gray-400 italic">Không có đăng ký nào được tìm thấy</td></tr>
                ) : (
                  displayRequests.map(r => (
                    <tr key={r.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-6 py-4 text-sm font-bold text-gray-900">{new Date(r.date).toLocaleDateString('vi-VN')}</td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <div className="w-7 h-7 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-[10px] font-bold uppercase">{r.users?.name?.charAt(0)}</div>
                          <span className="text-sm font-semibold text-gray-700">{r.users?.name || '-'}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-xs text-gray-500 font-medium">{r.start_time} - {r.end_time}</td>
                      <td className="px-6 py-4 text-center text-sm font-bold text-blue-600">{r.total_hours}h</td>
                      <td className="px-6 py-4">
                        <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase ${r.status === 'approved' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                          {r.status === 'approved' ? 'Đã duyệt' : 'Chờ duyệt'}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </Card>
      )}

      {activeTab === 'stats' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
           <Card title="Xếp hạng tăng ca" className="md:col-span-1 border-none shadow-xl">
              <div className="space-y-4">
                 {top5.map((emp, idx) => (
                    <div key={idx} className="flex items-center justify-between p-3.5 bg-gray-50 rounded-2xl border border-gray-100">
                       <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${idx === 0 ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>{idx + 1}</div>
                          <span className="text-sm font-bold text-gray-800 truncate max-w-[120px]">{emp.name}</span>
                       </div>
                       <span className="text-sm font-black text-blue-600">{emp.hours.toFixed(1)}h</span>
                    </div>
                 ))}
              </div>
           </Card>
           <Card title="Biểu đồ giờ làm thêm" className="md:col-span-2 border-none shadow-xl">
              <div className="h-72">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={myStats.trend}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                    <Tooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                    <Bar dataKey="hours" fill="#2563eb" radius={[6, 6, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
           </Card>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-zoom-in border border-gray-100">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50/50">
              <div>
                <h3 className="text-xl font-bold text-gray-900 leading-tight">
                    {editingRequestId ? 'Cập nhật đăng ký' : 'Đăng ký tăng ca mới'}
                </h3>
                <p className="text-xs text-gray-400 font-semibold mt-1">Ngày: {selectedDateStr}</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-400 hover:text-gray-600 p-2 rounded-full hover:bg-gray-100 transition-all"><X className="w-6 h-6"/></button>
            </div>

            <div className="p-8 space-y-6">
              {isAdmin && (
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Nhân viên thực hiện</label>
                  <div className="relative">
                    <select 
                        value={targetUserId} 
                        onChange={e => setTargetUserId(e.target.value)} 
                        className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500 appearance-none transition-all"
                    >
                        {allEmployees.map(emp => <option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                  </div>
                  {editingRequestId && (
                    <div className="flex items-center gap-2 mt-2 px-3 py-2 bg-amber-50 text-amber-700 rounded-xl border border-amber-100 text-[10px] font-bold uppercase animate-pulse">
                      <AlertTriangle className="w-3.5 h-3.5" /> Chế độ CẬP NHẬT đè đơn hiện tại
                    </div>
                  )}
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Bắt đầu</label>
                  <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500 transition-all"/>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Kết thúc</label>
                  <input type="time" value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500 transition-all"/>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-gray-400 uppercase tracking-widest ml-1">Nội dung / Lý do</label>
                <div className="relative group">
                  <textarea 
                    value={reason} 
                    onChange={e => setReason(e.target.value)} 
                    placeholder="Mô tả công việc cần xử lý..." 
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 min-h-[100px] resize-none pr-12 transition-all"
                  ></textarea>
                  <button onClick={handleRewrite} disabled={isRewriting || !reason.trim()} className="absolute right-3 bottom-3 p-2 bg-white text-blue-600 rounded-lg shadow-md border border-gray-100 hover:bg-blue-50 transition-all active:scale-90 disabled:opacity-50">
                    {isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>}
                  </button>
                </div>
              </div>

              <div className="p-5 bg-blue-600 rounded-2xl flex items-center justify-between shadow-xl shadow-blue-500/20">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center text-white"><Timer className="w-5 h-5" /></div>
                  <span className="text-xs font-bold text-white uppercase tracking-widest opacity-90">Tổng cộng OT:</span>
                </div>
                <span className="text-3xl font-black text-white tabular-nums tracking-tighter">{calculatedHours}h</span>
              </div>
            </div>

            <div className="p-8 bg-gray-50 flex flex-col sm:flex-row gap-3">
              <button onClick={() => setIsModalOpen(false)} className="flex-1 py-4 bg-white text-gray-500 font-bold rounded-2xl border border-gray-200 hover:bg-gray-100 transition-all active:scale-[0.98]">Hủy bỏ</button>
              <button 
                onClick={handleSaveRequest} 
                disabled={isSubmitting} 
                className="flex-[2] py-4 bg-blue-600 text-white font-bold rounded-2xl shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center gap-2 active:scale-[0.98] disabled:opacity-50"
              >
                {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Save className="w-5 h-5"/>}
                Xác nhận đăng ký
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
