  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('20:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            if (isWorkDay) {
                setStartTime('14:30');
            } else {
                setStartTime('08:00');
            }
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const toggleSaturdayStatus = async () => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    const currentStatus = dayConfigs[selectedDateStr] ?? true;
    const newStatus = !currentStatus;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: newStatus });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: newStatus }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng thời gian này.");

    filtered.sort((a, b) => a.date.localeCompare(b.date));
    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    const summaryData = filtered.map(req => {
        const d = new Date(req.date);
        return {
            'Ngày': req.date,
            'Thứ': dayNames[d.getDay()],
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        };
    });
    const summarySheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'TỔNG HỢP');

    const groupedByDate: Record<string, OvertimeRequest[]> = {};
    filtered.forEach(req => {
        if (!groupedByDate[req.date]) groupedByDate[req.date] = [];
        groupedByDate[req.date].push(req);
    });

    Object.keys(groupedByDate).forEach(dateKey => {
        const dayRequests = groupedByDate[dateKey];
        const dateObj = new Date(dateKey);
        const dayLabel = dayNames[dateObj.getDay()];
        const sheetData = dayRequests.map(req => ({
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        }));
        const worksheet = XLSX.utils.json_to_sheet(sheetData);
        const tabName = dateKey.split('-').reverse().slice(0, 2).join('-');
        XLSX.utils.book_append_sheet(workbook, worksheet, `${tabName} (${dayLabel})`);
    });

    const fileNameDate = start === end ? `Ngay_${start}` : `${start}_den_${end}`;
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'personal' ? 'Ca_nhan' : 'Toan_bo'}_${fileNameDate}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => {
      const today = new Date().toISOString().split('T')[0];
      handleExportExcel(mode, { start: today, end: today });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setShowColleagueDetails(false);
    setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const adminTrend = useMemo(() => {
    return Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i+1).padStart(2, '0')}`;
        return { day: i+1, count: new Set(requests.filter(r => r.date === dStr).map(r => r.user_id)).size };
    });
  }, [requests, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSun = dateObj.getDay() === 0;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-16 md:h-32 border border-gray-100 p-1 md:p-2 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-0.5 md:gap-1.5">
                        <span className={`text-[10px] md:text-base font-black ${isToday ? 'bg-blue-600 text-white w-4 h-4 md:w-6 md:h-6 rounded-md md:rounded-lg flex items-center justify-center shadow-lg' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {/* Nhãn Thứ 7: Hiển thị trên mọi thiết bị nhưng nhỏ gọn trên mobile */}
                        <div className="flex items-center gap-0.5 md:gap-1">
                            {isSat && (
                                <span className={`text-[6px] md:text-[8px] font-black px-0.5 md:px-1 py-0.5 rounded shadow-sm uppercase border ${configWork === false ? 'bg-orange-50 text-orange-600 border-orange-200' : 'bg-blue-50 text-blue-600 border-blue-200'}`}>
                                    {configWork === false ? 'Nghỉ' : 'Làm'}
                                </span>
                            )}
                            {isSun && <span className="text-[6px] md:text-[8px] font-black px-0.5 md:px-1 py-0.5 rounded shadow-sm bg-rose-50 text-rose-600 border border-rose-200 uppercase tracking-tighter">Nghỉ</span>}
                        </div>
                    </div>
                </div>

                <div className="flex-1 flex flex-col justify-start gap-1 mt-0.5 overflow-hidden">
                    {myRequest && (
                        <div className="flex items-center gap-1">
                            <div className="w-1.5 h-1.5 md:w-6 md:h-6 rounded-full md:rounded-lg bg-emerald-500 shadow-sm flex items-center justify-center flex-shrink-0">
                                <UserIcon className="hidden md:block w-3.5 h-3.5 text-white" />
                            </div>
                        </div>
                    )}

                    {otherRequests.length > 0 && (
                        <div className="flex items-center gap-0.5">
                             <div className="flex -space-x-1 overflow-hidden">
                                {otherRequests.slice(0, 2).map((req, idx) => (
                                    <div key={idx} className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-indigo-200 md:bg-indigo-100 border border-white shadow-sm flex items-center justify-center flex-shrink-0">
                                        <span className="hidden md:block text-[7px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-100 text-gray-500 text-[6px] md:text-[8px] px-0.5 md:px-1.5 py-0.5 rounded md:rounded-lg font-black flex items-center gap-0.5 md:gap-1 border border-gray-200 shadow-sm">
                        <Users className="w-2 md:w-2.5 h-2 md:h-2.5" />
                        {dayRequests.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const isViewOnly = targetUserId !== user.id && !isAdmin;
  const dayRequests = requests.filter(r => r.date === selectedDateStr);

  return (
    <div className="space-y-4 md:space-y-6 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-0">
        {/* HEADER RESPONSIVE */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-3 md:gap-4 bg-white p-3 md:p-6 rounded-[1.5rem] md:rounded-[2rem] shadow-sm border border-gray-100 transition-all">
            <div className="w-full md:w-auto flex items-center justify-between md:block">
                <div>
                    <div className="flex items-center gap-2">
                        <h2 className="text-lg md:text-2xl font-black text-gray-900 tracking-tight">Tăng ca</h2>
                        <span className="text-[8px] md:text-[10px] font-bold bg-indigo-100 text-indigo-700 px-1.5 md:py-0.5 rounded-full uppercase">Tool V2</span>
                    </div>
                    <p className="text-[10px] md:text-sm text-gray-500 font-medium italic mt-0.5">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
                </div>

                <button 
                  onClick={() => handleExportToday(isAdmin ? 'all' : 'personal')}
                  className="md:hidden flex items-center gap-1.5 bg-emerald-600 text-white px-3 py-1.5 rounded-lg text-[9px] font-black uppercase shadow-lg shadow-emerald-100 active:scale-95"
                >
                  <Zap className="w-3 h-3" /> Xuất Ngày
                </button>
            </div>

            <div className="flex flex-col md:flex-row items-center gap-3 w-full md:w-auto">
                <div className="flex w-full md:w-auto bg-gray-100/80 p-1 rounded-xl md:rounded-2xl border border-gray-200 overflow-x-auto no-scrollbar">
                    <button onClick={() => setActiveTab('calendar')} className={`flex-1 md:flex-none flex items-center justify-center gap-1.5 px-3 md:px-6 py-2 rounded-lg md:rounded-xl text-[10px] md:text-sm font-black transition-all whitespace-nowrap ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>
                        <CalendarIcon className="w-3 h-3 md:w-3.5 md:h-3.5" /> Lịch
                    </button>
                    <button onClick={() => setActiveTab('personal')} className={`flex-1 md:flex-none flex items-center justify-center gap-1.5 px-3 md:px-6 py-2 rounded-lg md:rounded-xl text-[10px] md:text-sm font-black transition-all whitespace-nowrap ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-sm' : 'text-gray-500'}`}>
                        <UserIcon className="w-3 h-3 md:w-3.5 md:h-3.5" /> Cá nhân
                    </button>
                    <button onClick={() => setActiveTab('stats')} className={`flex-1 md:flex-none flex items-center justify-center gap-1.5 px-3 md:px-6 py-2 rounded-lg md:rounded-xl text-[10px] md:text-sm font-black transition-all whitespace-nowrap ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>
                        <BarChart3 className="w-3 h-3 md:w-3.5 md:h-3.5" /> Thống kê
                    </button>
                </div>

                <button 
                  onClick={() => handleExportToday(isAdmin ? 'all' : 'personal')}
                  className="hidden md:flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2.5 rounded-xl text-xs font-black uppercase shadow-lg shadow-emerald-100 transition-all transform hover:scale-105 active:scale-95"
                >
                  <Zap className="w-4 h-4" /> Xuất Excel Hôm Nay
                </button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-200 shadow-lg md:shadow-2xl rounded-[1.5rem] md:rounded-[2.5rem] bg-white">
                    <div className="flex items-center justify-between p-3 md:p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 md:p-3 hover:bg-gray-100 rounded-xl transition-all"><ChevronLeft className="w-4 h-4 md:w-5 md:h-5"/></button>
                        <h3 className="text-[10px] md:text-lg font-black uppercase tracking-[0.1em] md:tracking-[0.2em] text-gray-800">T{currentDate.getMonth()+1} - {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 md:p-3 hover:bg-gray-100 rounded-xl transition-all"><ChevronRight className="w-4 h-4 md:w-5 md:h-5"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[8px] md:text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-2 md:py-4 text-center ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-100 gap-[0.5px] md:gap-[1px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-700 text-white border-none shadow-lg rounded-[1.2rem] md:rounded-[2rem] p-4 md:p-6 relative overflow-hidden">
                            <h3 className="text-[8px] md:text-[10px] font-black uppercase tracking-widest opacity-80 mb-1 md:mb-2">Tháng {currentDate.getMonth()+1}</h3>
                            <div className="flex items-end gap-1"><span className="text-2xl md:text-5xl font-black tabular-nums tracking-tighter">{myStats.total.toFixed(1)}</span><span className="text-[10px] md:text-lg font-bold mb-0.5 md:mb-1 opacity-70">h</span></div>
                        </Card>
                        <Card className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 bg-white border-l-4 md:border-l-8 border-emerald-500 rounded-[1.2rem] p-3 md:p-5 shadow-sm">
                            <div className="hidden md:flex p-3 bg-emerald-50 rounded-2xl text-emerald-600"><Timer className="w-6 h-6" /></div>
                            <div><p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest">Đã đăng ký</p><p className="text-sm md:text-2xl font-black text-gray-900">{myStats.count} <span className="text-[8px] md:text-[10px] font-medium text-gray-400 uppercase">Ngày</span></p></div>
                        </Card>
                        <Card className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 bg-white border-l-4 md:border-l-8 border-amber-500 rounded-[1.2rem] p-3 md:p-5 shadow-sm">
                            <div className="hidden md:flex p-3 bg-amber-50 rounded-2xl text-amber-600"><Clock className="w-6 h-6" /></div>
                            <div><p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest">Chờ duyệt</p><p className="text-sm md:text-2xl font-black text-gray-900">{myStats.pending}</p></div>
                        </Card>
                        <Card className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 bg-white border-l-4 md:border-l-8 border-indigo-500 rounded-[1.2rem] p-3 md:p-5 shadow-sm">
                            <div className="hidden md:flex p-3 bg-indigo-50 rounded-2xl text-indigo-600"><TrendingUp className="w-6 h-6" /></div>
                            <div><p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest">Trung bình</p><p className="text-sm md:text-2xl font-black text-gray-900">{(myStats.total / (myStats.count || 1)).toFixed(1)}</p></div>
                        </Card>
                    </div>

                    <Card className="rounded-[1.5rem] md:rounded-[2.5rem] shadow-lg border-none p-4 md:p-6">
                        <h3 className="font-black text-gray-800 uppercase text-[10px] md:text-xs tracking-widest flex items-center gap-2 mb-4 md:mb-6"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ xu hướng</h3>
                        <div className="h-48 md:h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{ top: 0, right: 0, left: -30, bottom: 0 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 8, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 8, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc', radius: 4}} contentStyle={{borderRadius: '8px', border: 'none', fontSize: '10px'}} />
                                    <Bar dataKey="hours" fill="#4f46e5" radius={[2, 2, 0, 0]} barSize={8} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <Card className="rounded-[1.5rem] md:rounded-[2.5rem] shadow-lg border-none bg-white overflow-hidden flex flex-col p-0">
                        <div className="p-4 md:p-6 bg-gradient-to-r from-blue-700 to-indigo-800 text-white">
                            <h4 className="text-sm md:text-xl font-black italic tracking-tighter uppercase">Xếp hạng tăng ca T{currentDate.getMonth()+1}</h4>
                        </div>
                        <div className="space-y-2 p-3 md:p-5 overflow-y-auto max-h-[400px]">
                            {top5.map((emp, idx) => (
                                <div key={idx} className={`p-3 rounded-xl md:rounded-[1.5rem] border transition-all flex items-center gap-3 ${idx === 0 ? 'bg-amber-50 border-amber-200' : 'bg-white border-gray-100'}`}>
                                    <div className={`w-8 h-8 md:w-12 md:h-12 rounded-lg md:rounded-2xl flex items-center justify-center font-black text-xs md:text-lg ${idx === 0 ? 'bg-amber-500 text-white' : 'bg-indigo-50 text-indigo-400'}`}>
                                        {idx + 1}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-center gap-2">
                                            <div className="truncate"><h4 className="font-black text-gray-900 text-[11px] md:text-sm truncate">{emp.name}</h4><p className="text-[8px] md:text-[10px] font-bold text-indigo-500">{emp.employee_id}</p></div>
                                            <div className="text-right"><span className="text-sm md:text-xl font-black text-indigo-600">{emp.hours.toFixed(1)}</span><span className="text-[8px] md:text-[10px] font-bold text-gray-400 ml-0.5">h</span></div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </Card>
                </div>
            )}
        </div>

        {/* MODAL ĐĂNG KÝ CẢI TIẾN CHO MOBILE */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/70 z-50 flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-t-[2rem] md:rounded-[3rem] shadow-2xl w-full max-w-md animate-slide-up md:animate-zoom-in overflow-hidden max-h-[95vh] flex flex-col">
                    <div className="bg-indigo-600 p-4 md:p-6 flex justify-between items-center text-white shrink-0">
                        <div>
                            <div className="flex items-center gap-2"><CalendarDays className="w-3.5 h-3.5 text-indigo-200" /><h3 className="text-base md:text-xl font-black uppercase tracking-tighter">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[9px] md:text-xs text-indigo-200 font-bold opacity-80 uppercase mt-0.5">Đăng ký tăng ca</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all active:scale-90"><X className="w-5 h-5 md:w-6 md:h-6"/></button>
                    </div>

                    <div className="p-4 md:p-8 space-y-4 md:space-y-6 overflow-y-auto no-scrollbar pb-10">
                        {/* PHẦN CẤU HÌNH THỨ 7 DÀNH CHO ADMIN */}
                        {isAdmin && new Date(selectedDateStr).getDay() === 6 && (
                            <div className="bg-indigo-50/50 p-4 rounded-2xl border-2 border-indigo-100 shadow-sm animate-fade-in flex items-center justify-between">
                                <div>
                                    <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest leading-none">Cấu hình Thứ 7</h4>
                                    <p className="text-[8px] text-indigo-400 font-bold mt-1 uppercase tracking-tighter">Làm việc toàn hệ thống</p>
                                </div>
                                <button 
                                    type="button"
                                    onClick={toggleSaturdayStatus} 
                                    disabled={isConfigUpdating} 
                                    className={`relative inline-flex h-7 w-14 items-center rounded-full transition-colors focus:outline-none shadow-inner ${ (dayConfigs[selectedDateStr] ?? true) ? 'bg-indigo-600' : 'bg-gray-300' }`}
                                >
                                    <span className={`${ (dayConfigs[selectedDateStr] ?? true) ? 'translate-x-7' : 'translate-x-1' } inline-block h-5 w-5 transform rounded-full bg-white transition-transform shadow-md flex items-center justify-center`}>
                                        {isConfigUpdating ? <Loader2 className="w-2.5 h-2.5 animate-spin text-indigo-600" /> : (dayConfigs[selectedDateStr] ?? true) ? <Check className="w-2.5 h-2.5 text-indigo-600" /> : <X className="w-2.5 h-2.5 text-gray-400" />}
                                    </span>
                                </button>
                            </div>
                        )}

                        {dayRequests.length > 0 && (
                            <div className="p-3 md:p-4 bg-gray-50 rounded-2xl border border-gray-100">
                                <button onClick={() => setShowColleagueDetails(!showColleagueDetails)} className="w-full flex justify-between items-center text-[9px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                    <span className="flex items-center gap-1.5"><Users className="w-3 h-3 md:w-3.5 md:h-3.5"/> Đồng nghiệp ({dayRequests.length})</span>
                                    {showColleagueDetails ? <ChevronUp className="w-3 h-3"/> : <ChevronDown className="w-3 h-3"/>}
                                </button>
                                {showColleagueDetails && (
                                    <div className="mt-3 flex flex-wrap gap-2 animate-fade-in">
                                        {dayRequests.map(req => (
                                            <div key={req.id} className="flex items-center gap-1.5 px-2 py-1 bg-white rounded-lg border border-gray-200 text-[8px] md:text-[10px] font-bold">
                                                <div className="w-4 h-4 rounded bg-indigo-50 flex items-center justify-center text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</div>
                                                <span className="truncate max-w-[60px]">{req.users?.name}</span>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4 md:space-y-6">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border border-amber-100 p-5 rounded-[1.5rem] text-center space-y-4">
                                    <Eye className="w-8 h-8 text-amber-500 mx-auto" />
                                    <p className="text-xs font-bold text-amber-900 uppercase">Đơn của {dayRequests.find(r => r.user_id === targetUserId)?.users?.name}</p>
                                    <div className="grid grid-cols-2 gap-2 text-[10px]">
                                        <div className="bg-white p-2 rounded-xl"><p className="text-gray-400 font-black uppercase">Giờ</p><p className="font-black text-gray-800">{startTime} - {endTime}</p></div>
                                        <div className="bg-white p-2 rounded-xl"><p className="text-gray-400 font-black uppercase">Tổng</p><p className="font-black text-gray-800">{calculatedHours}h</p></div>
                                    </div>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl">Đăng ký mới cho tôi</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-1">
                                            <label className="text-[9px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nhân viên:</label>
                                            <select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-xs md:text-sm font-black focus:ring-2 focus:ring-indigo-500 outline-none appearance-none">
                                                {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name}</option>))}
                                            </select>
                                        </div>
                                    )}

                                    <div className="grid grid-cols-2 gap-3 md:gap-4">
                                        <div className="bg-gray-50 p-3 md:p-4 rounded-xl md:rounded-2xl border border-gray-200">
                                            <label className="block text-[8px] md:text-[10px] font-black text-gray-400 uppercase mb-1 tracking-widest">Bắt đầu</label>
                                            <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-base md:text-xl font-black text-gray-900 focus:ring-0 outline-none"/>
                                        </div>
                                        <div className="bg-gray-50 p-3 md:p-4 rounded-xl md:rounded-2xl border border-gray-200">
                                            <label className="block text-[8px] md:text-[10px] font-black text-gray-400 uppercase mb-1 tracking-widest">Kết thúc</label>
                                            <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-base md:text-xl font-black text-gray-900 focus:ring-0 outline-none"/>
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1">
                                            <label className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest">Lý do & Tổng giờ</label>
                                            <span className="text-[10px] md:text-sm font-black text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full">{calculatedHours}h OT</span>
                                        </div>
                                        <textarea required value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-3 md:p-5 bg-gray-50 border border-gray-200 rounded-xl md:rounded-[2rem] text-xs md:text-sm h-24 md:h-32 resize-none text-gray-900 font-medium outline-none" placeholder="Nội dung công việc..."/>
                                        <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="w-full mt-1 flex items-center justify-center gap-1.5 py-2 text-[8px] md:text-[10px] font-black text-indigo-600 bg-indigo-50 rounded-xl border border-indigo-100">
                                            {isRewriting ? <Loader2 className="w-3 h-3 animate-spin"/> : <Wand2 className="w-3 h-3"/>}
                                            Tối ưu lý do bằng AI
                                        </button>
                                    </div>

                                    <div className="flex gap-3 pt-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3 md:p-5 bg-rose-50 text-rose-600 rounded-xl md:rounded-3xl border border-rose-100 transition-all active:scale-95"><Trash2 className="w-5 h-5"/></button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-3 md:py-5 bg-indigo-600 text-white font-black rounded-xl md:rounded-3xl shadow-xl shadow-indigo-100 text-[10px] md:text-xs tracking-widest uppercase transition-all active:scale-95 disabled:opacity-50">
                                            {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật đăng ký' : 'Xác nhận đăng ký'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/80 z-[60] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in"><div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-gray-200"><div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-4 rounded-2xl"><AlertTriangle className="w-8 h-8"/></div><h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tight">Xóa đơn này?</h3><p className="text-[10px] text-gray-500 font-bold uppercase opacity-70 mb-6">Thao tác không thể khôi phục</p><div className="space-y-2"><button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-3 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase shadow-lg shadow-rose-100 active:scale-95">Xác nhận xóa</button><button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-3 bg-white text-gray-500 font-black rounded-xl border border-gray-200 text-[10px] uppercase active:scale-95">Hủy bỏ</button></div></div></div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, Save, X, 
  CheckCircle2, AlertCircle, Timer, Loader2, 
  ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, Info, Trophy, Medal, Star, CalendarDays, FileSpreadsheet,
  AlertTriangle, TrendingUp, Target, Activity, PieChart as PieChartIcon, Search, UserPlus, Share2, ToggleLeft, ToggleRight, Eye, MousePointer2, CalendarRange, FileDown, ArrowRight, Zap, List, ChevronDown, ChevronUp,
  Home, HardHat, Briefcase
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const currentMonthStr = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        if (dayOfWeek === 0) {
            setStartTime('08:00');
            setEndTime('20:00');
        } else if (dayOfWeek === 6) {
            const isWorkDay = dayConfigs[selectedDateStr] ?? true;
            if (isWorkDay) {
                setStartTime('14:30');
            } else {
                setStartTime('08:00');
            }
            setEndTime('20:00');
        } else {
            setStartTime('17:30');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const setSaturdayStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng thời gian này.");

    filtered.sort((a, b) => a.date.localeCompare(b.date));
    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    const summaryData = filtered.map(req => {
        const d = new Date(req.date);
        return {
            'Ngày': req.date,
            'Thứ': dayNames[d.getDay()],
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        };
    });
    const summarySheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'TỔNG HỢP');

    const groupedByDate: Record<string, OvertimeRequest[]> = {};
    filtered.forEach(req => {
        if (!groupedByDate[req.date]) groupedByDate[req.date] = [];
        groupedByDate[req.date].push(req);
    });

    Object.keys(groupedByDate).forEach(dateKey => {
        const dayRequests = groupedByDate[dateKey];
        const dateObj = new Date(dateKey);
        const dayLabel = dayNames[dateObj.getDay()];
        const sheetData = dayRequests.map(req => ({
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        }));
        const worksheet = XLSX.utils.json_to_sheet(sheetData);
        const tabName = dateKey.split('-').reverse().slice(0, 2).join('-');
        XLSX.utils.book_append_sheet(workbook, worksheet, `${tabName} (${dayLabel})`);
    });

    const fileNameDate = start === end ? `Ngay_${start}` : `${start}_den_${end}`;
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'personal' ? 'Ca_nhan' : 'Toan_bo'}_${fileNameDate}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => {
      const today = new Date().toISOString().split('T')[0];
      handleExportExcel(mode, { start: today, end: today });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setShowColleagueDetails(false);
    setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const top5 = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const adminTrend = useMemo(() => {
    return Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i+1).padStart(2, '0')}`;
        return { day: i+1, count: new Set(requests.filter(r => r.date === dStr).map(r => r.user_id)).size };
    });
  }, [requests, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequests.find(r => r.user_id === user.id);
        const otherRequests = dayRequests.filter(r => r.user_id !== user.id);
        const isToday = new Date().toISOString().split('T')[0] === dateStr;
        const dateObj = new Date(year, month, d);
        const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
        const isSun = dateObj.getDay() === 0;
        const isSat = dateObj.getDay() === 6;
        const configWork = dayConfigs[dateStr];

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-16 md:h-32 border border-gray-100 p-1 md:p-2 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-0.5 md:gap-1.5">
                        <span className={`text-[10px] md:text-base font-black ${isToday ? 'bg-blue-600 text-white w-4 h-4 md:w-6 md:h-6 rounded-md md:rounded-lg flex items-center justify-center shadow-lg' : isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        {/* Nhãn Ngày Nghỉ/Làm - Tăng độ nổi bật */}
                        <div className="flex items-center gap-0.5 md:gap-1">
                            {isSat && (
                                <span className={`text-[6px] md:text-[8px] font-black px-1.5 md:px-2 py-0.5 md:py-1 rounded-full shadow-md uppercase border-2 ${configWork === false ? 'bg-rose-500 text-white border-rose-400' : 'bg-indigo-600 text-white border-indigo-500'}`}>
                                    {configWork === false ? 'Nghỉ' : 'Làm'}
                                </span>
                            )}
                            {isSun && <span className="text-[6px] md:text-[8px] font-black px-1.5 md:px-2 py-0.5 md:py-1 rounded-full shadow-md bg-rose-500 text-white border-2 border-rose-400 uppercase tracking-tighter">Nghỉ</span>}
                        </div>
                    </div>
                </div>

                <div className="flex-1 flex flex-col justify-start gap-1 mt-0.5 overflow-hidden">
                    {myRequest && (
                        <div className="flex items-center gap-1">
                            <div className="w-1.5 h-1.5 md:w-6 md:h-6 rounded-full md:rounded-lg bg-emerald-500 shadow-sm flex items-center justify-center flex-shrink-0">
                                <UserIcon className="hidden md:block w-3.5 h-3.5 text-white" />
                            </div>
                        </div>
                    )}

                    {otherRequests.length > 0 && (
                        <div className="flex items-center gap-0.5">
                             <div className="flex -space-x-1 overflow-hidden">
                                {otherRequests.slice(0, 2).map((req, idx) => (
                                    <div key={idx} className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-indigo-200 md:bg-indigo-100 border border-white shadow-sm flex items-center justify-center flex-shrink-0">
                                        <span className="hidden md:block text-[7px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                {dayRequests.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-100 text-gray-500 text-[6px] md:text-[8px] px-0.5 md:px-1.5 py-0.5 rounded md:rounded-lg font-black flex items-center gap-0.5 md:gap-1 border border-gray-200 shadow-sm">
                        <Users className="w-2 md:w-2.5 h-2 md:h-2.5" />
