  }, [searchTerm, filterCategory, filterStatus, pageSize]);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) {
        setTools(data as Tool[]);
        setCurrentPage(1); 
        setSelectedToolIds(new Set()); 
        setQuantities({});
    }
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') {
        matchesStatus = tool.status === 'active' && tool.available > 0;
      } else if (filterStatus === 'out_of_stock') {
        matchesStatus = tool.status === 'active' && tool.available === 0;
      } else if (filterStatus === 'inactive') {
        matchesStatus = tool.status === 'inactive';
      }
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => {
    const cats = new Set(tools.map(t => t.category).filter(Boolean));
    return Array.from(cats);
  }, [tools]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const isSelectable = (tool: Tool) => tool.status === 'active' && tool.available > 0;

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities};
        delete newQties[id];
        setQuantities(newQties);
    } else {
        newSet.add(id);
        setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  const changeQuantity = (id: string, delta: number, max: number) => {
      const currentQty = quantities[id] || 1;
      const newQty = currentQty + delta;

      if (newQty < 1) {
          toggleSelection(id); 
      } else if (newQty <= max) {
          setQuantities(prev => ({ ...prev, [id]: newQty }));
      }
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBulkProcessing(true);

    try {
        const toolsToBorrow = tools.filter(t => selectedToolIds.has(t.id));
        const requests: any[] = [];

        toolsToBorrow.forEach(tool => {
            const qty = quantities[tool.id] || 1;
            for(let i = 0; i < qty; i++) {
                requests.push({
                    employee_id: user.employeeCode,
                    user_id: user.id,
                    user_name: user.name,
                    tool_id: tool.id,
                    tool_name: tool.name,
                    borrow_date: new Date().toISOString(),
                    status: 'pending'
                });
            }
        });

        const { error } = await supabase.from('requests').insert(requests);

        if (!error) {
            setMessage(`Đã gửi thành công ${requests.length} yêu cầu!`);
            setSelectedToolIds(new Set()); 
            setQuantities({});
            setTimeout(() => setMessage(null), 4000);
            await fetchTools();
        } else {
            alert('Có lỗi xảy ra: ' + error.message);
        }
    } finally {
        setIsBulkProcessing(false);
    }
  };

  const handleAddNew = () => {
    setFormData(INITIAL_FORM_DATA);
    setIsEditing(false);
    setCurrentToolId(null);
    setIsModalOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setCurrentToolId(tool.id);
    setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    try {
      if (!formData.name) return alert('Vui lòng nhập tên công cụ');
      const payload = { ...formData };
      if (isEditing && currentToolId) {
        const { error } = await supabase.from('tools').update(payload).eq('id', currentToolId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('tools').insert([payload]);
        if (error) throw error;
      }
      await fetchTools();
      setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi lưu dữ liệu: ' + error.message);
    }
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete);
      if (error) throw error;
      await fetchTools();
      setToolToDelete(null);
      setMessage('Đã xóa thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) {
      alert('Lỗi khi xóa: ' + error.message);
    }
  };

  const totalItemsSelected = Array.from(selectedToolIds).reduce((sum, id) => sum + (quantities[id] || 1), 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* HEADER SECTION */}
      <div className="flex flex-col gap-4 bg-white p-5 rounded-[2.5rem] shadow-sm border border-gray-100 transition-all">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100">
                    <Wrench className="w-8 h-8 text-white" />
                </div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">
                        Kho công cụ
                    </h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        Quản lý & Theo dõi tài sản hệ thống
                    </p>
                </div>
                {!isAdmin && <span className="text-[10px] font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-full uppercase tracking-widest border border-indigo-100 ml-2">Chế độ Mượn</span>}
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && (
                <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100 whitespace-nowrap">
                    <CheckCircle2 className="w-5 h-5" />
                    {message}
                </div>
                )}

                {isAdmin && (
                    <div className="flex bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button 
                            onClick={() => setIsManageMode(true)}
                            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <Settings2 className="w-4 h-4" />
                            QUẢN LÝ
                        </button>
                        <button 
                            onClick={() => setIsManageMode(false)}
                            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <ShoppingBag className="w-4 h-4" />
                            MƯỢN ĐỒ
                        </button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100/80 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}><List className="w-5 h-5" /></button>
                </div>

                {isAdmin && (
                    <button 
                        onClick={handleAddNew}
                        className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-4 rounded-2xl flex items-center gap-2 text-xs font-black transition-all shadow-xl shadow-indigo-100 w-full sm:w-auto justify-center whitespace-nowrap active:scale-95 uppercase tracking-widest"
                    >
                        <Plus className="w-5 h-5" />
                        THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-indigo-500 transition-colors" />
                <input 
                    type="text" 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Tìm tên thiết bị, vị trí..."
                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-indigo-500/10 transition-all text-gray-900 placeholder:text-gray-400 outline-none"
                />
            </div>

            <div className="flex gap-3 w-full md:w-auto">
                <div className="relative flex-1 sm:min-w-[200px] group">
                    <select 
                        value={filterCategory}
                        onChange={(e) => setFilterCategory(e.target.value)}
                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-indigo-500/10 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả danh mục</option>
                        {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>

                <div className="relative flex-1 sm:min-w-[200px] group">
                    <select 
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value)}
                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-indigo-500/10 text-gray-900 transition-all outline-none"
                    >
                        <option value="all">Tất cả trạng thái</option>
                        <option value="available">✅ Sẵn có</option>
                        <option value="out_of_stock">⚠️ Hết hàng</option>
                        <option value="inactive">🚫 Bảo trì</option>
                    </select>
                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-indigo-500" />
                </div>
            </div>
        </div>
      </div>

      {/* CONTENT LIST */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const selectable = isSelectable(tool);
                const isSelected = selectedToolIds.has(tool.id);
                const qty = quantities[tool.id] || 1;

                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all relative overflow-hidden group flex flex-col h-full p-0 border-2 ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-500/5 transform scale-[1.02]' : 'border-transparent bg-white shadow-lg rounded-[2.5rem]'}`} onClick={() => !isManageMode && selectable && toggleSelection(tool.id)}>
                    <div className="h-56 bg-white flex items-center justify-center overflow-hidden relative border-b border-gray-100">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        {tool.status === 'inactive' ? (
                          <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Bảo trì</span>
                        ) : tool.available > 0 ? (
                          <span className="bg-emerald-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Sẵn có: {tool.available}</span>
                        ) : (
                          <span className="bg-gray-400 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg tracking-widest">Hết hàng</span>
                        )}
                      </div>
                    </div>

                    <div className="p-6 flex-1 flex flex-col bg-white">
                      <div className="mb-4">
                        <h3 className="font-black text-gray-900 text-lg line-clamp-2 min-h-[3.5rem] leading-tight tracking-tight">{tool.name}</h3>
                        <div className="flex items-center gap-2 mt-2">
                            <span className="text-[10px] font-black uppercase tracking-tighter text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md">{tool.category}</span>
                            <div className="flex items-center gap-1 text-[10px] text-gray-400 font-bold uppercase tracking-tighter">
                                <MapPin className="w-3 h-3 opacity-50" />
                                {tool.location || 'N/A'}
                            </div>
                        </div>
                      </div>

                      <div className="mt-auto">
                        {isManageMode ? (
                          <div className="flex gap-3 pt-4 border-t border-gray-50" onClick={e => e.stopPropagation()}>
                             <button onClick={() => handleEditTool(tool)} className="flex-1 bg-white hover:bg-indigo-50 text-indigo-700 border-2 border-indigo-100 py-3 rounded-2xl text-[10px] font-black transition-all flex items-center justify-center gap-2 uppercase tracking-widest"><Edit className="w-4 h-4" /> Sửa</button>
                             <button onClick={() => setToolToDelete(tool.id)} className="p-3 bg-white hover:bg-rose-50 text-rose-600 border-2 border-rose-100 rounded-2xl transition-all"><Trash2 className="w-5 h-5" /></button>
                          </div>
                        ) : (
                          isSelected ? (
                              <div className="flex items-center justify-between bg-indigo-600 rounded-2xl p-1.5 shadow-xl animate-fade-in-up border-2 border-indigo-500" onClick={e => e.stopPropagation()}>
                                  <button onClick={() => changeQuantity(tool.id, -1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-indigo-500/50 hover:bg-white/20 rounded-xl text-white transition-all"><Minus className="w-5 h-5" /></button>
                                  <div className="flex flex-col items-center"><span className="text-[10px] font-black uppercase text-indigo-200 tracking-widest leading-none mb-1">Số lượng</span><span className="font-black text-white text-xl tabular-nums leading-none">{qty}</span></div>
                                  <button onClick={() => changeQuantity(tool.id, 1, tool.available)} className="w-11 h-11 flex items-center justify-center bg-white text-indigo-600 rounded-xl shadow-lg transition-all disabled:opacity-50" disabled={qty >= Number(tool.available)}><Plus className="w-5 h-5" /></button>
                              </div>
                          ) : (
                              <button disabled={!selectable} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl text-[10px] font-black transition-all disabled:opacity-50 disabled:bg-gray-100 flex items-center justify-center gap-3 uppercase tracking-[0.15em] shadow-lg shadow-indigo-100">
                                <PackagePlus className="w-5 h-5" /> CHỌN MƯỢN
                              </button>
                          )
                        )}
                      </div>
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[3rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                    <th className="px-10 py-6 w-24 text-[10px] font-black uppercase tracking-widest text-gray-400">Hình</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Tên thiết bị</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Danh mục</th>
                    <th className="px-10 py-6 text-center text-[10px] font-black uppercase tracking-widest text-gray-400">Kho/Sẵn</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-10 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => {
                      const isSelected = selectedToolIds.has(tool.id);
                      return (
                      <tr key={tool.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-50/50' : 'hover:bg-blue-50/30'}`} onClick={() => !isManageMode && isSelectable(tool) && toggleSelection(tool.id)}>
                        <td className="px-10 py-6">
                            <div className="w-16 h-16 rounded-2xl bg-white border-2 border-gray-100 overflow-hidden flex items-center justify-center p-1 shadow-sm group-hover:border-indigo-200 transition-colors">
                                <ToolThumbnail src={tool.image} alt={tool.name} mode="table" />
                            </div>
                        </td>
                        <td className="px-10 py-6 font-black text-gray-900">{tool.name}</td>
                        <td className="px-10 py-6 text-[11px] font-bold text-gray-500 uppercase tracking-tight">{tool.category}</td>
                        <td className="px-10 py-6 text-center text-sm font-black tabular-nums">{tool.available} / {tool.quantity}</td>
                        <td className="px-10 py-6">{tool.status === 'active' ? <span className="text-emerald-700 text-[9px] font-black uppercase bg-emerald-50 px-3 py-1 rounded-full tracking-widest border border-emerald-100">Hoạt động</span> : <span className="text-rose-700 text-[9px] font-black uppercase bg-rose-50 px-3 py-1 rounded-full tracking-widest border border-rose-100">Bảo trì</span>}</td>
                        <td className="px-10 py-6 text-right" onClick={e => e.stopPropagation()}>
                          {isManageMode ? (
                            <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-gray-100 rounded-2xl transition-colors"><Edit className="w-5 h-5"/></button>
                          ) : (
                            <div className="flex justify-end">
                              {isSelected ? (
                                <span className="text-indigo-600 font-black text-[10px] uppercase tracking-widest flex items-center gap-2"><Check className="w-4 h-4" /> Đã chọn</span>
                              ) : (
                                <button disabled={!isSelectable(tool)} className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg disabled:opacity-50 active:scale-90 transition-all"><PackagePlus className="w-5 h-5"/></button>
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                      );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {/* PAGINATION FOOTER */}
      <Card className="p-6 rounded-[3rem] shadow-xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
          <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                  Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredTools.length, startIndex + 1)}-{Math.min(filteredTools.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums">{filteredTools.length}</span> thiết bị
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                 <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                 <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-indigo-100">{currentPage} / {totalPages}</span>
              </div>
          </div>

          <div className="flex items-center gap-3">
              <button 
                  onClick={() => handlePageChange(1)}
                  disabled={currentPage === 1}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
                  title="Trang đầu"
              >
                  <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                  onClick={() => handlePageChange(currentPage - 1)}
                  disabled={currentPage === 1}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
              >
                  <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                  {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                      let pageNum = 1;
                      if (totalPages <= 5) pageNum = i + 1;
                      else if (currentPage <= 3) pageNum = i + 1;
                      else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                      else pageNum = currentPage - 2 + i;

                      return (
                          <button
                              key={pageNum}
                              onClick={() => handlePageChange(pageNum)}
                              className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                                  currentPage === pageNum 
                                  ? 'bg-indigo-600 text-white border-indigo-600 shadow-xl scale-110 z-10' 
                                  : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                              }`}
                          >
                              {pageNum}
                          </button>
                      );
                  })}
              </div>

              <button 
                  onClick={() => handlePageChange(currentPage + 1)}
                  disabled={currentPage === totalPages}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
              >
                  <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                  onClick={() => handlePageChange(totalPages)}
                  disabled={currentPage === totalPages}
                  className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 transition-all shadow-sm active:scale-90"
                  title="Trang cuối"
              >
                  <ChevronsRight className="w-5 h-5" />
              </button>
          </div>
      </Card>

      {/* FLOATING ACTION BAR FOR BORROWING */}
      {selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-0 right-0 z-[100] flex justify-center px-4 md:px-8 pointer-events-none">
             <div className="bg-gray-950/90 backdrop-blur-2xl text-white p-3 pr-4 rounded-[2.5rem] shadow-2xl flex items-center gap-6 pointer-events-auto animate-fade-in-up border border-white/10 w-full max-w-2xl mx-auto">
                <div className="flex items-center gap-4 pl-3">
                    <div className="bg-indigo-600 rounded-[1.5rem] w-14 h-14 flex items-center justify-center font-black text-2xl shadow-xl border-2 border-indigo-400">
                        {totalItemsSelected}
                    </div>
                    <div className="flex flex-col">
                      <span className="text-[10px] text-gray-400 uppercase tracking-widest font-black opacity-80 mb-0.5">Xác nhận mượn</span>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-lg text-white tracking-tight">{selectedToolIds.size}</span>
                        <span className="text-[10px] font-bold text-gray-400 uppercase">loại thiết bị</span>
                      </div>
