  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [currentDate]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const { data } = await supabase.from('day_configs').select('*');
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const handleExportExcel = (mode: 'personal' | 'all') => {
    let filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng này.");

    const workbook = XLSX.utils.book_new();
    const data = filtered.map(req => ({
        'Ngày': req.date,
        'Họ tên': req.users?.name || 'Ẩn danh',
        'Mã NV': req.users?.employee_id || 'N/A',
        'Bắt đầu': req.start_time,
        'Kết thúc': req.end_time,
        'Tổng giờ': req.total_hours,
        'Nội dung': req.reason
    }));
    const worksheet = XLSX.utils.json_to_sheet(data);
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Bao_cao_OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}_${exportStartDate}_den_${exportEndDate}.xlsx`);
  };

  const teamStats = useMemo(() => {
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr));
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        const dayHours = monthly.filter(r => r.date === dStr).reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
        return { day: d, hours: dayHours };
    });
    const ranking = Array.from(new Set(monthly.map(r => r.user_id))).map(id => {
        const userReqs = monthly.filter(r => r.user_id === id);
        return { 
            name: userReqs[0].users?.name || 'Ẩn danh', 
            id: userReqs[0].users?.employee_id || 'N/A', 
            total: userReqs.reduce((sum, r) => sum + Number(r.total_hours || 0), 0),
            count: userReqs.length
        };
    }).sort((a, b) => b.total - a.total).slice(0, 10);
    return { trend, ranking, today: requests.filter(r => r.date === todayStr) };
  }, [requests, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const totalDays = getDaysInMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1;

    for (let i = 0; i < startOffset; i++) days.push(<div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 opacity-40 border border-gray-100"></div>);

    for (let d = 1; d <= totalDays; d++) {
        const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dStr);
        const hasMe = dayRequests.some(r => r.user_id === user.id);

        days.push(
            <div key={d} onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
                 className={`h-16 md:h-32 border border-gray-100 p-2 relative cursor-pointer hover:bg-indigo-50 transition-all ${todayStr === dStr ? 'bg-indigo-50 ring-2 ring-indigo-500' : 'bg-white'}`}>
                <span className={`text-[10px] md:text-sm font-black ${todayStr === dStr ? 'text-indigo-600' : 'text-gray-700'}`}>{d}</span>
                <div className="mt-1 flex flex-wrap gap-1">
                    {hasMe && <div className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-emerald-500 shadow-sm flex items-center justify-center text-[8px] text-white font-bold">{user.name.charAt(0)}</div>}
                    {dayRequests.filter(r => r.user_id !== user.id).length > 0 && <div className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[8px] font-black">{dayRequests.length}</div>}
                </div>
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto pb-24">
      {/* HEADER TABS */}
      <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
        <h2 className="text-xl font-black text-gray-900 flex items-center gap-3"><Clock className="w-6 h-6 text-indigo-600" /> Quản lý Tăng ca</h2>
        <div className="flex bg-gray-100 p-1 rounded-2xl border border-gray-200">
            {['calendar', 'personal', 'stats'].map(tab => (
                <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}>
                    {tab === 'calendar' ? 'Lịch' : tab === 'personal' ? 'Cá nhân' : 'Thống kê'}
                </button>
            ))}
        </div>
      </div>

      <div className="flex-1">
        {activeTab === 'calendar' && (
            <Card className="p-0 overflow-hidden border-none shadow-xl rounded-[2.5rem] bg-white">
                <div className="flex justify-between items-center p-6 border-b">
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronLeft /></button>
                    <h3 className="font-black uppercase tracking-widest text-gray-800">Tháng {currentDate.getMonth()+1} - {currentDate.getFullYear()}</h3>
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronRight /></button>
                </div>
                <div className="grid grid-cols-7 bg-gray-50 border-b">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="py-3 text-center text-[10px] font-black text-gray-400 uppercase">{d}</div>)}
                </div>
                <div className="grid grid-cols-7 bg-gray-100 gap-px">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && (
            <div className="space-y-8 animate-fade-in">
                {/* TỔNG QUAN ADMIN */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <Card className="bg-indigo-600 text-white p-6 shadow-xl shadow-indigo-100">
                        <p className="text-[10px] font-black uppercase tracking-widest opacity-80 flex items-center gap-2"><Trophy className="w-4 h-4"/> Đăng ký hôm nay</p>
                        <p className="text-4xl font-black mt-2">{teamStats.today.length} <span className="text-sm opacity-60">Nhân sự</span></p>
                    </Card>
                    <Card className="bg-white border-l-4 border-emerald-500 p-6 shadow-md">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><Activity className="w-4 h-4 text-emerald-500"/> Tổng giờ tháng này</p>
                        <p className="text-4xl font-black mt-2 text-gray-900">{teamStats.ranking.reduce((s, r) => s + r.total, 0).toFixed(1)} <span className="text-sm text-gray-400">h</span></p>
                    </Card>
                    <Card className="bg-white border-l-4 border-amber-500 p-6 shadow-md">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><Users className="w-4 h-4 text-amber-500"/> Nhân sự hoạt động</p>
                        <p className="text-4xl font-black mt-2 text-gray-900">{teamStats.ranking.length}</p>
                    </Card>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* DANH SÁCH HÔM NAY */}
                    <Card className="rounded-[2rem] p-0 overflow-hidden bg-white shadow-xl">
                        <div className="p-6 bg-gray-50 border-b flex justify-between items-center">
                            <h4 className="text-sm font-black uppercase text-gray-800 tracking-tighter">Nhân sự OT Hôm nay</h4>
                            <span className="text-[10px] font-bold bg-indigo-100 text-indigo-700 px-3 py-1 rounded-lg">{todayStr}</span>
                        </div>
                        <div className="p-4 max-h-[400px] overflow-y-auto space-y-3">
                            {teamStats.today.map((req, i) => (
                                <div key={i} className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 bg-indigo-600 rounded-xl text-white flex items-center justify-center font-black">{req.users?.name.charAt(0)}</div>
                                        <div><p className="font-black text-sm text-gray-900">{req.users?.name}</p><p className="text-[10px] text-gray-400 font-bold uppercase">{req.users?.employee_id}</p></div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-black text-indigo-600">{req.total_hours}h</p>
                                        <p className="text-[9px] text-gray-400 font-bold uppercase">{req.start_time}-{req.end_time}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </Card>

                    {/* BIỂU ĐỒ XU HƯỚNG */}
                    <Card className="rounded-[2rem] p-8 bg-white shadow-xl">
                        <h4 className="text-sm font-black uppercase text-gray-800 mb-8">Xu hướng OT toàn hệ thống (Tháng {currentDate.getMonth()+1})</h4>
                        <div className="h-64">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={teamStats.trend}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 9, fontBold: true, fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fontBold: true, fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc', radius: 8}} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                                    <Bar dataKey="hours" fill="#4f46e5" radius={[4, 4, 0, 0]} barSize={12} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>

                {/* XẾP HẠNG & XUẤT EXCEL */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    <Card className="lg:col-span-5 rounded-[2rem] p-0 overflow-hidden bg-white shadow-xl">
                         <div className="p-6 bg-indigo-700 text-white flex items-center justify-between">
                            <h4 className="text-sm font-black uppercase italic flex items-center gap-2"><Award className="w-5 h-5 text-amber-400" /> BXH Tăng ca Top 10</h4>
                         </div>
                         <div className="p-4 space-y-2">
                            {teamStats.ranking.map((r, i) => (
                                <div key={i} className={`flex items-center gap-4 p-4 rounded-2xl ${i === 0 ? 'bg-amber-50 border border-amber-200' : 'bg-white'}`}>
                                    <span className={`w-6 text-sm font-black ${i < 3 ? 'text-amber-500' : 'text-gray-300'}`}>{i + 1}</span>
                                    <div className="flex-1"><p className="text-sm font-black text-gray-900 uppercase">{r.name}</p><p className="text-[10px] text-gray-400 font-bold">{r.id}</p></div>
                                    <span className="text-lg font-black text-indigo-600">{r.total.toFixed(1)}h</span>
                                </div>
                            ))}
                         </div>
                    </Card>

                    <Card className="lg:col-span-7 rounded-[2rem] p-10 bg-white shadow-xl border-4 border-emerald-50 h-fit">
                        <div className="space-y-6">
                            <h4 className="text-2xl font-black text-gray-900 uppercase tracking-tighter flex items-center gap-3"><FileSpreadsheet className="w-8 h-8 text-emerald-600" /> Kết xuất báo cáo Excel</h4>
                            <p className="text-xs text-gray-400 font-bold uppercase tracking-widest leading-relaxed">Chọn khoảng thời gian để tải dữ liệu tăng ca toàn bộ hệ thống.</p>

                            <div className="grid grid-cols-2 gap-4 pt-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-gray-400 uppercase ml-1">Từ ngày</label>
                                    <input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-xs font-black outline-none focus:ring-4 focus:ring-emerald-500/10 transition-all" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-gray-400 uppercase ml-1">Đến ngày</label>
                                    <input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-xs font-black outline-none focus:ring-4 focus:ring-emerald-500/10 transition-all" />
                                </div>
                            </div>

                            <div className="flex flex-col gap-4 pt-8">
                                <button onClick={() => handleExportExcel('all')} className="w-full py-5 bg-emerald-600 text-white font-black rounded-3xl shadow-xl shadow-emerald-100 flex items-center justify-center gap-3 uppercase tracking-widest text-xs"><FileDown className="w-5 h-5" /> Tải báo cáo Hệ thống</button>
                                <button onClick={() => handleExportExcel('personal')} className="w-full py-5 bg-white text-emerald-600 font-black rounded-3xl border-2 border-emerald-100 flex items-center justify-center gap-3 uppercase tracking-widest text-xs">Báo cáo Cá nhân tôi</button>
                            </div>
                        </div>
                    </Card>
                </div>
            </div>
        )}
      </div>

      {/* MODAL ĐĂNG KÝ (GIỮ NGUYÊN LOGIC CŨ) */}
      {isModalOpen && (
          <div className="fixed inset-0 bg-black/70 z-50 flex items-end md:items-center justify-center backdrop-blur-sm">
             <div className="bg-white rounded-t-[2rem] md:rounded-[3rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col">
                <div className="bg-indigo-600 p-6 flex justify-between items-center text-white shrink-0">
                    <div>
                        <h3 className="text-xl font-black uppercase tracking-tighter">{selectedDateStr}</h3>
                        <p className="text-[10px] text-indigo-200 font-bold uppercase">Đăng ký tăng ca vtrang</p>
                    </div>
                    <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-6 h-6"/></button>
                </div>
                <div className="p-8 space-y-6 overflow-y-auto no-scrollbar">
                    <form onSubmit={async (e) => {
                        e.preventDefault();
                        setIsSubmitting(true);
                        const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: timeToNumber(endTime) - timeToNumber(startTime), reason, status: 'approved' };
                        await supabase.from('ot_requests').insert([payload]);
                        await fetchRequests();
                        setIsSubmitting(false);
                        setIsModalOpen(false);
                    }} className="space-y-6">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="bg-gray-50 p-4 rounded-2xl">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none text-xl font-black outline-none"/>
                            </div>
                            <div className="bg-gray-50 p-4 rounded-2xl">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none text-xl font-black outline-none"/>
                            </div>
                        </div>
                        <div className="space-y-2">
                            <textarea required value={reason} onChange={e => setReason(e.target.value)} className="w-full p-5 bg-gray-50 border border-gray-200 rounded-[2rem] text-sm h-32 resize-none font-medium" placeholder="Mô tả công việc tăng ca..."/>
                            <button type="button" onClick={async () => setReason(await rewriteOvertimeReason(reason))} className="w-full py-2 text-[10px] font-black text-indigo-600 bg-indigo-50 rounded-xl border border-indigo-100 flex items-center justify-center gap-2"><Wand2 className="w-4 h-4" /> AI Tối ưu lý do</button>
                        </div>
                        <button type="submit" disabled={isSubmitting} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl shadow-indigo-100 text-xs tracking-widest uppercase active:scale-95 disabled:opacity-50">
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : 'Xác nhận đăng ký'}
                        </button>
                    </form>
                </div>
             </div>
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, ChevronDown, ChevronsLeft, ChevronsRight,
  CheckCircle2, Trash2, Check
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className="flex flex-col items-center justify-center bg-gray-100 w-full h-full rounded-xl">
        <Wrench className={`${mode === 'grid' ? 'w-10 h-10 text-gray-300' : 'w-6 h-6 text-gray-400'}`} />
      </div>
    );
  }

  return (
    <img
      src={src}
      alt={alt}
      onError={() => setError(true)}
      className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
    />
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [quantities, setQuantities] = useState<{[key: string]: number}>({});
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);

  // State quan trọng: Xác nhận xóa
  const [toolToDelete, setToolToDelete] = useState<Tool | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);
  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const currentTools = filteredTools.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
        const newQties = {...quantities}; delete newQties[id]; setQuantities(newQties);
    } else {
        newSet.add(id); setQuantities(prev => ({...prev, [id]: 1}));
    }
    setSelectedToolIds(newSet);
  };

  // Fix: Added missing handleEditTool function
  const handleEditTool = (tool: Tool) => {
    setCurrentToolId(tool.id);
    setFormData({
      name: tool.name,
      category: tool.category,
      quantity: tool.quantity,
      available: tool.available,
      description: tool.description || '',
      location: tool.location || '',
      image: tool.image || '',
      status: tool.status
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      const { error } = await supabase.from('tools').delete().eq('id', toolToDelete.id);
      if (error) throw error;
      setTools(prev => prev.filter(t => t.id !== toolToDelete.id));
      setToolToDelete(null);
      setMessage('Đã xóa thiết bị khỏi kho');
      setTimeout(() => setMessage(null), 3000);
    } catch (err: any) {
      alert('Lỗi: ' + err.message);
    }
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools();
      setIsModalOpen(false);
    } catch (err: any) { alert(err.message); }
  };

  return (
    <div className="space-y-6 relative pb-24 animate-fade-in">
      {/* HEADER */}
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-4">
          <div className="p-4 bg-indigo-600 rounded-2xl shadow-lg text-white"><Wrench className="w-6 h-6" /></div>
          <div>
            <h2 className="text-xl font-black text-gray-900">Kho công cụ</h2>
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Quản lý tài sản vtrang</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {isAdmin && (
            <button onClick={() => setIsManageMode(!isManageMode)} className={`px-5 py-2.5 rounded-xl text-xs font-bold uppercase border-2 transition-all ${isManageMode ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-100'}`}>
              {isManageMode ? 'Chế độ: Quản lý' : 'Chế độ: Mượn đồ'}
            </button>
          )}
          {isManageMode && (
            <button onClick={() => { setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true); }} className="bg-emerald-600 text-white px-5 py-2.5 rounded-xl text-xs font-bold uppercase shadow-lg">Thêm mới</button>
          )}
        </div>
      </div>

      {/* FILTER BAR */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input type="text" placeholder="Tìm kiếm thiết bị..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-gray-50 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500/20" />
        </div>
        <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} className="bg-gray-50 p-3 rounded-xl text-sm outline-none">
          <option value="all">Tất cả danh mục</option>
          {uniqueCategories.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="bg-gray-50 p-3 rounded-xl text-sm outline-none">
          <option value="all">Tất cả trạng thái</option>
          <option value="available">Sẵn có</option>
          <option value="inactive">Đang bảo trì</option>
        </select>
      </div>

      {/* TOOL LIST */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {currentTools.map(tool => (
          <Card key={tool.id} className={`group relative overflow-hidden p-0 border-2 transition-all rounded-[1.5rem] ${selectedToolIds.has(tool.id) ? 'border-indigo-600 ring-4 ring-indigo-50' : 'border-transparent bg-white shadow-md'}`} onClick={() => !isManageMode && tool.available > 0 && toggleSelection(tool.id)}>
            <div className="h-48 bg-white flex items-center justify-center relative border-b border-gray-50">
              <ToolThumbnail src={tool.image} alt={tool.name} />
              <div className="absolute top-3 right-3">
                {tool.status === 'inactive' ? <span className="bg-rose-500 text-white text-[8px] font-black px-2 py-1 rounded-lg uppercase">Bảo trì</span> : <span className="bg-emerald-500 text-white text-[8px] font-black px-2 py-1 rounded-lg uppercase">Sẵn có: {tool.available}</span>}
              </div>
            </div>
            <div className="p-5 space-y-3">
              <h3 className="font-bold text-gray-900 text-sm line-clamp-2 h-10">{tool.name}</h3>
              <div className="flex items-center justify-between text-[10px] text-gray-400 font-bold">
                <span className="bg-gray-100 px-2 py-0.5 rounded-md uppercase">{tool.category}</span>
                <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {tool.location || 'Kho'}</span>
              </div>

              {isManageMode ? (
                <div className="flex gap-2 pt-2 border-t border-gray-50">
                  <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="flex-1 bg-indigo-50 text-indigo-600 py-2 rounded-lg text-[10px] font-black uppercase">Sửa</button>
                  <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool); }} className="px-3 bg-rose-50 text-rose-600 py-2 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                </div>
              ) : (
                selectedToolIds.has(tool.id) && (
                  <div className="bg-indigo-600 text-white py-2 rounded-lg text-center text-[10px] font-black uppercase flex items-center justify-center gap-2">
                    <Check className="w-3 h-3" /> Đã chọn
                  </div>
                )
              )}
            </div>
          </Card>
        ))}
      </div>

      {/* PHÂN TRANG */}
      <div className="flex justify-center items-center gap-4 mt-8">
        <button disabled={currentPage === 1} onClick={() => setCurrentPage(prev => prev - 1)} className="p-2 bg-white rounded-xl shadow disabled:opacity-30"><ChevronLeft className="w-5 h-5"/></button>
        <span className="text-xs font-black text-gray-500 uppercase tracking-widest">Trang {currentPage} / {totalPages}</span>
        <button disabled={currentPage === totalPages} onClick={() => setCurrentPage(prev => prev + 1)} className="p-2 bg-white rounded-xl shadow disabled:opacity-30"><ChevronRight className="w-5 h-5"/></button>
      </div>

      {/* CONFIRM DELETE MODAL */}
      {toolToDelete && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in">
            <div className="p-8 text-center">
              <div className="w-16 h-16 bg-rose-100 text-rose-600 rounded-2xl flex items-center justify-center mx-auto mb-4"><AlertTriangle className="w-8 h-8" /></div>
              <h3 className="text-xl font-black text-gray-900 mb-2 uppercase">Xác nhận xóa?</h3>
              <p className="text-xs text-gray-400 font-medium px-4">Bạn có chắc muốn xóa <b>{toolToDelete.name}</b>? Hành động này không thể hoàn tác.</p>
            </div>
            <div className="p-6 bg-gray-50 flex gap-3">
              <button onClick={() => setToolToDelete(null)} className="flex-1 py-3 bg-white text-gray-500 font-black rounded-xl text-[10px] uppercase border border-gray-200">Hủy bỏ</button>
              <button onClick={handleDeleteTool} className="flex-1 py-3 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase shadow-lg shadow-rose-100">Xóa vĩnh viễn</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, Wand2, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  TrendingUp, Activity, Zap, ChevronDown, ChevronUp, Home, Briefcase, CalendarRange, UserCheck, Search,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, Info
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();
const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};
const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [currentDate]);

  const fetchRequests = async () => {
    setLoading(true);
    const { data } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
    if (data) setRequests(data as OvertimeRequest[]);
    setLoading(false);
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const { data } = await supabase.from('day_configs').select('*');
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const handleExportExcel = (mode: 'personal' | 'all') => {
    let filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng này.");

    const workbook = XLSX.utils.book_new();
    const data = filtered.map(req => ({
        'Ngày': req.date,
        'Họ tên': req.users?.name || 'Ẩn danh',
        'Mã NV': req.users?.employee_id || 'N/A',
        'Bắt đầu': req.start_time,
        'Kết thúc': req.end_time,
        'Tổng giờ': req.total_hours,
        'Nội dung': req.reason
    }));
    const worksheet = XLSX.utils.json_to_sheet(data);
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Bao_cao_OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}_${exportStartDate}_den_${exportEndDate}.xlsx`);
  };

  const teamStats = useMemo(() => {
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr));
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        const dayHours = monthly.filter(r => r.date === dStr).reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
        return { day: d, hours: dayHours };
    });
    const ranking = Array.from(new Set(monthly.map(r => r.user_id))).map(id => {
        const userReqs = monthly.filter(r => r.user_id === id);
        return { 
            name: userReqs[0].users?.name || 'Ẩn danh', 
            id: userReqs[0].users?.employee_id || 'N/A', 
            total: userReqs.reduce((sum, r) => sum + Number(r.total_hours || 0), 0),
            count: userReqs.length
        };
    }).sort((a, b) => b.total - a.total).slice(0, 10);
    return { trend, ranking, today: requests.filter(r => r.date === todayStr) };
  }, [requests, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const totalDays = getDaysInMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1;

    for (let i = 0; i < startOffset; i++) days.push(<div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 opacity-40 border border-gray-100"></div>);

    for (let d = 1; d <= totalDays; d++) {
        const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequests = requests.filter(r => r.date === dStr);
        const hasMe = dayRequests.some(r => r.user_id === user.id);

        days.push(
            <div key={d} onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
                 className={`h-16 md:h-32 border border-gray-100 p-2 relative cursor-pointer hover:bg-indigo-50 transition-all ${todayStr === dStr ? 'bg-indigo-50 ring-2 ring-indigo-500' : 'bg-white'}`}>
                <span className={`text-[10px] md:text-sm font-black ${todayStr === dStr ? 'text-indigo-600' : 'text-gray-700'}`}>{d}</span>
                <div className="mt-1 flex flex-wrap gap-1">
                    {hasMe && <div className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-emerald-500 shadow-sm flex items-center justify-center text-[8px] text-white font-bold">{user.name.charAt(0)}</div>}
                    {dayRequests.filter(r => r.user_id !== user.id).length > 0 && <div className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center text-[8px] font-black">{dayRequests.length}</div>}
                </div>
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto pb-24">
      {/* HEADER TABS */}
      <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
        <h2 className="text-xl font-black text-gray-900 flex items-center gap-3"><Clock className="w-6 h-6 text-indigo-600" /> Quản lý Tăng ca</h2>
        <div className="flex bg-gray-100 p-1 rounded-2xl border border-gray-200">
            {['calendar', 'personal', 'stats'].map(tab => (
                <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}>
                    {tab === 'calendar' ? 'Lịch' : tab === 'personal' ? 'Cá nhân' : 'Thống kê'}
                </button>
            ))}
        </div>
      </div>

      <div className="flex-1">
        {activeTab === 'calendar' && (
            <Card className="p-0 overflow-hidden border-none shadow-xl rounded-[2.5rem] bg-white">
                <div className="flex justify-between items-center p-6 border-b">
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronLeft /></button>
                    <h3 className="font-black uppercase tracking-widest text-gray-800">Tháng {currentDate.getMonth()+1} - {currentDate.getFullYear()}</h3>
                    <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronRight /></button>
                </div>
                <div className="grid grid-cols-7 bg-gray-50 border-b">
                    {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="py-3 text-center text-[10px] font-black text-gray-400 uppercase">{d}</div>)}
                </div>
                <div className="grid grid-cols-7 bg-gray-100 gap-px">
                    {renderCalendarDays()}
                </div>
            </Card>
        )}

        {activeTab === 'stats' && (
            <div className="space-y-8 animate-fade-in">
                {/* TỔNG QUAN ADMIN */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <Card className="bg-indigo-600 text-white p-6 shadow-xl shadow-indigo-100">
                        <p className="text-[10px] font-black uppercase tracking-widest opacity-80 flex items-center gap-2"><Trophy className="w-4 h-4"/> Đăng ký hôm nay</p>
                        <p className="text-4xl font-black mt-2">{teamStats.today.length} <span className="text-sm opacity-60">Nhân sự</span></p>
                    </Card>
                    <Card className="bg-white border-l-4 border-emerald-500 p-6 shadow-md">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><Activity className="w-4 h-4 text-emerald-500"/> Tổng giờ tháng này</p>
                        <p className="text-4xl font-black mt-2 text-gray-900">{teamStats.ranking.reduce((s, r) => s + r.total, 0).toFixed(1)} <span className="text-sm text-gray-400">h</span></p>
                    </Card>
                    <Card className="bg-white border-l-4 border-amber-500 p-6 shadow-md">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><Users className="w-4 h-4 text-amber-500"/> Nhân sự hoạt động</p>
                        <p className="text-4xl font-black mt-2 text-gray-900">{teamStats.ranking.length}</p>
                    </Card>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* DANH SÁCH HÔM NAY */}
                    <Card className="rounded-[2rem] p-0 overflow-hidden bg-white shadow-xl">
                        <div className="p-6 bg-gray-50 border-b flex justify-between items-center">
                            <h4 className="text-sm font-black uppercase text-gray-800 tracking-tighter">Nhân sự OT Hôm nay</h4>
                            <span className="text-[10px] font-bold bg-indigo-100 text-indigo-700 px-3 py-1 rounded-lg">{todayStr}</span>
                        </div>
                        <div className="p-4 max-h-[400px] overflow-y-auto space-y-3">
                            {teamStats.today.map((req, i) => (
                                <div key={i} className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 bg-indigo-600 rounded-xl text-white flex items-center justify-center font-black">{req.users?.name.charAt(0)}</div>
                                        <div><p className="font-black text-sm text-gray-900">{req.users?.name}</p><p className="text-[10px] text-gray-400 font-bold uppercase">{req.users?.employee_id}</p></div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-black text-indigo-600">{req.total_hours}h</p>
                                        <p className="text-[9px] text-gray-400 font-bold uppercase">{req.start_time}-{req.end_time}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </Card>

                    {/* BIỂU ĐỒ XU HƯỚNG */}
                    <Card className="rounded-[2rem] p-8 bg-white shadow-xl">
                        <h4 className="text-sm font-black uppercase text-gray-800 mb-8">Xu hướng OT toàn hệ thống (Tháng {currentDate.getMonth()+1})</h4>
                        <div className="h-64">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={teamStats.trend}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    {/* Fix: Changed fontBold to fontWeight */}
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    {/* Fix: Changed fontBold to fontWeight */}
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc', radius: 8}} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                                    <Bar dataKey="hours" fill="#4f46e5" radius={[4, 4, 0, 0]} barSize={12} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>

                {/* XẾP HẠNG & XUẤT EXCEL */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    <Card className="lg:col-span-5 rounded-[2rem] p-0 overflow-hidden bg-white shadow-xl">
                         <div className="p-6 bg-indigo-700 text-white flex items-center justify-between">
                            <h4 className="text-sm font-black uppercase italic flex items-center gap-2"><Award className="w-5 h-5 text-amber-400" /> BXH Tăng ca Top 10</h4>
                         </div>
                         <div className="p-4 space-y-2">
                            {teamStats.ranking.map((r, i) => (
                                <div key={i} className={`flex items-center gap-4 p-4 rounded-2xl ${i === 0 ? 'bg-amber-50 border border-amber-200' : 'bg-white'}`}>
                                    <span className={`w-6 text-sm font-black ${i < 3 ? 'text-amber-500' : 'text-gray-300'}`}>{i + 1}</span>
                                    <div className="flex-1"><p className="text-sm font-black text-gray-900 uppercase">{r.name}</p><p className="text-[10px] text-gray-400 font-bold">{r.id}</p></div>
                                    <span className="text-lg font-black text-indigo-600">{r.total.toFixed(1)}h</span>
                                </div>
                            ))}
                         </div>
                    </Card>

                    <Card className="lg:col-span-7 rounded-[2rem] p-10 bg-white shadow-xl border-4 border-emerald-50 h-fit">
                        <div className="space-y-6">
                            <h4 className="text-2xl font-black text-gray-900 uppercase tracking-tighter flex items-center gap-3"><FileSpreadsheet className="w-8 h-8 text-emerald-600" /> Kết xuất báo cáo Excel</h4>
                            <p className="text-xs text-gray-400 font-bold uppercase tracking-widest leading-relaxed">Chọn khoảng thời gian để tải dữ liệu tăng ca toàn bộ hệ thống.</p>

                            <div className="grid grid-cols-2 gap-4 pt-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-gray-400 uppercase ml-1">Từ ngày</label>
                                    <input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-xs font-black outline-none focus:ring-4 focus:ring-emerald-500/10 transition-all" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-gray-400 uppercase ml-1">Đến ngày</label>
                                    <input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full p-4 bg-gray-50 border-none rounded-2xl text-xs font-black outline-none focus:ring-4 focus:ring-emerald-500/10 transition-all" />
                                </div>
                            </div>

                            <div className="flex flex-col gap-4 pt-8">
                                <button onClick={() => handleExportExcel('all')} className="w-full py-5 bg-emerald-600 text-white font-black rounded-3xl shadow-xl shadow-emerald-100 flex items-center justify-center gap-3 uppercase tracking-widest text-xs"><FileDown className="w-5 h-5" /> Tải báo cáo Hệ thống</button>
                                <button onClick={() => handleExportExcel('personal')} className="w-full py-5 bg-white text-emerald-600 font-black rounded-3xl border-2 border-emerald-100 flex items-center justify-center gap-3 uppercase tracking-widest text-xs">Báo cáo Cá nhân tôi</button>
                            </div>
                        </div>
                    </Card>
                </div>
            </div>
        )}
      </div>

      {/* MODAL ĐĂNG KÝ (GIỮ NGUYÊN LOGIC CŨ) */}
      {isModalOpen && (
          <div className="fixed inset-0 bg-black/70 z-50 flex items-end md:items-center justify-center backdrop-blur-sm">
             <div className="bg-white rounded-t-[2rem] md:rounded-[3rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col">
                <div className="bg-indigo-600 p-6 flex justify-between items-center text-white shrink-0">
                    <div>
                        <h3 className="text-xl font-black uppercase tracking-tighter">{selectedDateStr}</h3>
                        <p className="text-[10px] text-indigo-200 font-bold uppercase">Đăng ký tăng ca vtrang</p>
                    </div>
                    <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-6 h-6"/></button>
                </div>
                <div className="p-8 space-y-6 overflow-y-auto no-scrollbar">
                    <form onSubmit={async (e) => {
                        e.preventDefault();
                        setIsSubmitting(true);
                        const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: timeToNumber(endTime) - timeToNumber(startTime), reason, status: 'approved' };
                        await supabase.from('ot_requests').insert([payload]);
                        await fetchRequests();
                        setIsSubmitting(false);
                        setIsModalOpen(false);
                    }} className="space-y-6">
                        <div className="grid grid-cols-2 gap-4">
                            <div className="bg-gray-50 p-4 rounded-2xl">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Bắt đầu</label>
                                <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none text-xl font-black outline-none"/>
                            </div>
                            <div className="bg-gray-50 p-4 rounded-2xl">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Kết thúc</label>
                                <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none text-xl font-black outline-none"/>
                            </div>
                        </div>
                        <div className="space-y-2">
                            <textarea required value={reason} onChange={e => setReason(e.target.value)} className="w-full p-5 bg-gray-50 border border-gray-200 rounded-[2rem] text-sm h-32 resize-none font-medium" placeholder="Mô tả công việc tăng ca..."/>
                            <button type="button" onClick={async () => setReason(await rewriteOvertimeReason(reason))} className="w-full py-2 text-[10px] font-black text-indigo-600 bg-indigo-50 rounded-xl border border-indigo-100 flex items-center justify-center gap-2"><Wand2 className="w-4 h-4" /> AI Tối ưu lý do</button>
                        </div>
                        <button type="submit" disabled={isSubmitting} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl shadow-indigo-100 text-xs tracking-widest uppercase active:scale-95 disabled:opacity-50">
                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : 'Xác nhận đăng ký'}
                        </button>
                    </form>
                </div>
             </div>
          </div>
      )}
    </div>
  );
};

