                      <td className="px-10 py-6 text-[11px] font-black text-gray-500 uppercase tracking-tighter">
                        <div className="flex items-center gap-2">
                          <Calendar className="w-3.5 h-3.5 opacity-30" />
                          {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                        </div>
                      </td>
                      <td className="px-10 py-6 text-center">
                        <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 shadow-lg transition-all group-hover:scale-105 ${badge.className}`}>
                          {badge.icon}
                          {badge.label}
                        </div>
                      </td>
                      <td className="px-10 py-6 text-right">
                        <div className="flex justify-end gap-3 items-center">
                          {processingId === req.id ? (
                            <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                          ) : (
                            <>
                              {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                                <div className="flex items-center gap-2">
                                  <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })} 
                                    className="flex items-center gap-2 px-5 py-3 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all active:scale-90"
                                    title="Duyệt yêu cầu"
                                  >
                                    <Check className="w-4 h-4" /> DUYỆT
                                  </button>
                                  <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })} 
                                    className="flex items-center gap-2 px-5 py-3 bg-white text-rose-600 border-2 border-rose-100 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all active:scale-90"
                                    title="Từ chối"
                                  >
                                    <X className="w-4 h-4" /> TỪ CHỐI
                                  </button>
                                </div>
                              )}

                              {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                                <button 
                                  onClick={() => setConfirmAction({ type: 'return', req })} 
                                  className="flex items-center gap-2 px-6 py-4 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
                                >
                                  <RotateCcw className="w-5 h-5" /> THU HỒI TÀI SẢN
                                </button>
                              )}

                              {req.user_id === user.id && req.status === 'pending' && (
                                <button 
                                  onClick={() => setConfirmAction({ type: 'cancel', id: req.id })} 
                                  className="flex items-center gap-2 px-6 py-4 bg-white text-rose-600 border-2 border-rose-100 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all active:scale-95 shadow-sm"
                                >
                                  <Trash2 className="w-5 h-5" /> HỦY YÊU CẦU
                                </button>
                              )}
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {filteredRequests.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-6 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredRequests.length, startIndex + 1)}-{Math.min(filteredRequests.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums">{filteredRequests.length}</span> yêu cầu
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-blue-100">{currentPage} / {totalPages}</span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => handlePageChange(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang đầu"
              >
                <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum = 1;
                  if (totalPages <= 5) pageNum = i + 1;
                  else if (currentPage <= 3) pageNum = i + 1;
                  else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                  else pageNum = currentPage - 2 + i;

                  return (
                    <button
                      key={pageNum}
                      onClick={() => handlePageChange(pageNum)}
                      className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                        currentPage === pageNum 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xl scale-110 z-10' 
                        : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang cuối"
              >
                <ChevronsRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}
      </Card>

      {/* CONFIRM MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl rotate-12 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' :
                'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <ThumbsUp className="w-12 h-12" /> : 
                 confirmAction.type === 'reject' ? <ThumbsDown className="w-12 h-12" /> :
                 <RotateCcw className="w-12 h-12" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">
                {confirmAction.type === 'approve' ? 'Duyệt yêu cầu?' : 
                 confirmAction.type === 'reject' ? 'Từ chối đơn?' : 
                 confirmAction.type === 'return' ? 'Thu hồi đồ?' : 'Xác nhận xóa?'}
              </h3>
              <p className="text-[11px] text-gray-400 font-bold leading-relaxed px-6 uppercase tracking-[0.15em] opacity-80 italic">
                {confirmAction.type === 'approve' ? 'Hành động này sẽ cập nhật tồn kho thiết bị.' : 
                 confirmAction.type === 'reject' ? 'Đơn này sẽ được chuyển sang trạng thái Từ chối.' :
                 confirmAction.type === 'return' ? 'Xác nhận người mượn đã hoàn trả thiết bị.' : 'Hành động này không thể hoàn tác.'}
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction} 
                className={`w-full py-5 text-white font-black rounded-3xl text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                  confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                  confirmAction.type === 'reject' ? 'bg-rose-600 shadow-rose-200' :
                  'bg-blue-600 shadow-blue-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)} 
                className="w-full py-5 bg-white text-gray-400 font-black rounded-3xl border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { 
  LayoutDashboard, 
  Users, 
  Wrench, 
  Clock, 
  History, 
  FileText, 
  LogOut,
  X
} from 'lucide-react';

interface SidebarProps {
  currentPath: string;
  onNavigate: (path: string) => void;
  onLogout: () => void;
  userRole: string;
  isOpen?: boolean;
  onClose?: () => void;
  pendingBorrowCount?: number;
  pendingOTCount?: number;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentPath, 
  onNavigate, 
  onLogout, 
  userRole, 
  isOpen, 
  onClose,
  pendingBorrowCount = 0,
  pendingOTCount = 0
}) => {
  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, path: '/dashboard', roles: ['admin', 'manager', 'employee', 'user'] },
    { id: 'employees', label: 'Nhân viên', icon: Users, path: '/employees', roles: ['admin', 'manager'] },
    { id: 'tools', label: 'Công cụ', icon: Wrench, path: '/tools', roles: ['admin', 'manager', 'employee', 'user'] },
    { id: 'requests', label: 'Yêu cầu mượn', icon: FileText, path: '/requests', roles: ['admin', 'manager', 'employee', 'user'], badge: pendingBorrowCount },
    { id: 'history', label: 'Lịch sử', icon: History, path: '/history', roles: ['admin', 'manager', 'employee', 'user'] },
    { id: 'overtime', label: 'Tăng ca', icon: Clock, path: '/overtime', roles: ['admin', 'manager', 'employee', 'user'], badge: pendingOTCount }, 
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(userRole));

  return (
    <div className={`
      fixed lg:sticky top-0 z-50 w-64 bg-slate-900 text-white flex flex-col h-screen overflow-y-auto transition-transform duration-300 ease-in-out
      ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
    `}>
      <div className="p-6 border-b border-slate-700 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center font-bold shadow-lg shadow-blue-500/20">M</div>
          <span className="font-bold text-lg tracking-wide">Manager Tool</span>
        </div>
        <button onClick={onClose} className="lg:hidden p-1 hover:bg-slate-800 rounded transition-colors">
          <X className="w-5 h-5 text-slate-400" />
        </button>
      </div>

      <nav className="flex-1 p-4 space-y-1">
        {filteredItems.map((item) => {
          const isActive = currentPath === item.path;
          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.path)}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-200 group ${
                isActive 
                  ? 'bg-blue-600 text-white shadow-xl shadow-blue-600/20 transform scale-[1.02]' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <div className="flex items-center gap-3">
                <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-white'}`} />
                <span className="font-medium text-sm tracking-tight">{item.label}</span>
              </div>

              {item.badge > 0 && (
                <span className={`flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full text-[10px] font-black animate-pulse ${
                  isActive ? 'bg-white text-blue-600' : 'bg-rose-500 text-white'
                }`}>
                  {item.badge}
                </span>
              )}
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-700">
        <button 
          onClick={onLogout}
          className="w-full flex items-center gap-3 px-4 py-3 text-rose-400 hover:bg-rose-900/20 hover:text-rose-300 rounded-xl transition-all"
        >
          <LogOut className="w-5 h-5" />
          <span className="font-medium text-sm tracking-tight">Đăng xuất</span>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Sidebar } from './src/components/layout/Sidebar';
import { Header } from './src/components/layout/Header';
import { LoginForm } from './src/components/auth/LoginForm';
import { DashboardStats } from './src/components/dashboard/DashboardStats';
import { EmployeeList } from './src/components/employees/EmployeeList';
import { ToolInventory } from './src/components/tools/ToolInventory';
import { RequestManager } from './src/components/requests/RequestManager';
import { HistoryLog } from './src/components/history/HistoryLog';
import { OvertimeRegistration } from './src/components/overtime/OvertimeRegistration';
import { generateManagerInsight } from './src/services/geminiService';
import { Bot, X, Send, Menu } from 'lucide-react';
import { supabase } from './src/lib/supabase';
import { User } from './types';

const MainLayout: React.FC<{ children: React.ReactNode; user: User; onLogout: () => void }> = ({ children, user, onLogout }) => {
  const location = useLocation();
  const [currentPath, setCurrentPath] = useState(location.pathname);
  const [showAiChat, setShowAiChat] = useState(false);
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // States for badges
  const [pendingBorrowCount, setPendingBorrowCount] = useState(0);
  const [pendingOTCount, setPendingOTCount] = useState(0);

  useEffect(() => {
    setCurrentPath(location.pathname);
    setIsSidebarOpen(false);
  }, [location]);

  // Fetch pending counts for badges
  useEffect(() => {
    const fetchCounts = async () => {
      if (!user) return;

      const isAdmin = user.role === 'admin';

      // Count Borrow Requests
      let borrowQuery = supabase.from('requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) borrowQuery = borrowQuery.eq('user_id', user.id);
      const { count: bCount } = await borrowQuery;
      setPendingBorrowCount(bCount || 0);

      // Count Overtime Requests (Only if relevant, normally approved by admin)
      // Note: In your current schema, OT requests might go straight to approved in some views, 
      // but let's check for 'pending' if it exists.
      let otQuery = supabase.from('ot_requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) otQuery = otQuery.eq('user_id', user.id);
      const { count: oCount } = await otQuery;
      setPendingOTCount(oCount || 0);
    };

    fetchCounts();
    // Poll every 30 seconds for new requests
    const interval = setInterval(fetchCounts, 30000);
    return () => clearInterval(interval);
  }, [user]);

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!aiQuery.trim()) return;

    setAiLoading(true);
    const context = `User Role: ${user.role}. Tổng nhân viên: 124. Công cụ: 856.`;
    const result = await generateManagerInsight(context, aiQuery);
    setAiResponse(result || "Không có phản hồi.");
    setAiLoading(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <Sidebar 
        currentPath={currentPath} 
        onNavigate={(path) => window.location.hash = path} 
        onLogout={onLogout}
        userRole={user.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        pendingBorrowCount={pendingBorrowCount}
        pendingOTCount={pendingOTCount}
      />

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      <div className="flex-1 flex flex-col min-w-0">
        <Header user={user} onMenuClick={() => setIsSidebarOpen(true)} />
        <main className="flex-1 p-4 md:p-8">
          {children}
        </main>
      </div>

      <div className="fixed bottom-6 right-6 z-50">
        {!showAiChat ? (
          <button 
            onClick={() => setShowAiChat(true)}
            className="w-14 h-14 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white hover:shadow-xl transition-all transform hover:scale-110 active:scale-95 border-4 border-white"
          >
            <Bot className="w-7 h-7" />
          </button>
        ) : (
          <div className="bg-white rounded-2xl shadow-2xl w-[calc(100vw-2rem)] sm:w-96 flex flex-col border border-gray-200 overflow-hidden animate-fade-in-up origin-bottom-right">
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-4 flex justify-between items-center text-white">
              <div className="flex items-center gap-2">
                <Bot className="w-5 h-5" />
                <span className="font-semibold">Trợ lý Quản lý</span>
              </div>
              <button onClick={() => setShowAiChat(false)} className="hover:bg-white/20 p-1 rounded transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 h-64 overflow-y-auto bg-gray-50 text-sm">
              {!aiResponse && !aiLoading && (
                <p className="text-gray-500 text-center mt-20">Hãy hỏi tôi về dữ liệu nhân sự, công cụ hoặc xu hướng...</p>
              )}
              {aiLoading && (
                <div className="flex items-center justify-center h-full">
                   <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                </div>
              )}
              {aiResponse && (
                <div className="prose prose-sm max-w-none text-gray-800 whitespace-pre-line">
                  {aiResponse}
                </div>
              )}
            </div>

            <form onSubmit={handleAiAsk} className="p-3 border-t bg-white flex gap-2">
              <input 
                type="text" 
                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Hỏi trợ lý..."
                className="flex-1 px-3 py-2 border rounded-xl focus:outline-none focus:border-blue-500 text-sm shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 disabled:opacity-50 transition-colors shadow-md"
              >
                <Send className="w-4 h-4" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return <div className="h-screen flex items-center justify-center"><div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div></div>;
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
        } />

        <Route path="/dashboard" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/employees" element={
          user ? (
             user.role === 'admin' ? (
                <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
             ) : <Navigate to="/dashboard" />
          ) : <Navigate to="/login" />
        } />

        <Route path="/tools" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/requests" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/history" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/overtime" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, ChevronDown, ChevronsLeft, ChevronsRight,
  CheckCircle2, Trash2, Check, ArrowRight
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className="flex flex-col items-center justify-center bg-gray-100 w-full h-full rounded-xl">
        <Wrench className={`${mode === 'grid' ? 'w-10 h-10 text-gray-300' : 'w-6 h-6 text-gray-400'}`} />
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white rounded-xl`}>
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);
  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
    } else {
        newSet.add(id);
    }
    setSelectedToolIds(newSet);
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBorrowing(true);
    try {
      const selectedTools = tools.filter(t => selectedToolIds.has(t.id));

      for (const tool of selectedTools) {
        if (tool.available <= 0) continue;

        const requestPayload = {
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        };

        const { error } = await supabase.from('requests').insert([requestPayload]);
        if (error) throw error;
      }

      setMessage(`Đã gửi ${selectedToolIds.size} yêu cầu mượn đồ!`);
      setSelectedToolIds(new Set());
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi khi gửi yêu cầu: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      await supabase.from('tools').delete().eq('id', toolToDelete);
      await fetchTools(); setToolToDelete(null);
      setMessage('Đã xóa thành công'); setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* Header & Filters */}
      <div className="flex flex-col gap-4 bg-white p-5 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100 text-white"><Wrench className="w-8 h-8" /></div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight">Kho công cụ</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">Hệ thống quản lý tài sản</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button onClick={() => {setIsManageMode(true); setSelectedToolIds(new Set());}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500'}`}><Settings2 className="w-4 h-4 mr-2 inline" />QUẢN LÝ</button>
                        <button onClick={() => {setIsManageMode(false); setSelectedToolIds(new Set());}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500'}`}><ShoppingBag className="w-4 h-4 mr-2 inline" />MƯỢN ĐỒ</button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}><List className="w-5 h-5" /></button>
                </div>

                {isManageMode && <button onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-xs font-black uppercase shadow-xl">THÊM MỚI</button>}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Tìm tên thiết bị, vị trí..." className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none" />
            </div>

            <div className="flex gap-3">
                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none">
                    <option value="all">Tất cả danh mục</option>
                    {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                </select>
                <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className="px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none">
                    <option value="all">Tất cả trạng thái</option>
                    <option value="available">Sẵn có</option>
                    <option value="inactive">Bảo trì</option>
                </select>
            </div>
        </div>
      </div>

      {/* Tools Display */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const isSelected = selectedToolIds.has(tool.id);
                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all p-0 border-2 overflow-hidden rounded-[2.5rem] ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-50' : 'border-transparent bg-white shadow-lg'}`} onClick={() => !isManageMode && tool.available > 0 && toggleSelection(tool.id)}>
                    <div className="h-56 bg-white flex items-center justify-center relative border-b">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4">
                        {tool.status === 'inactive' ? <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg">Bảo trì</span> : <span className="bg-emerald-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg">Sẵn có: {tool.available}</span>}
                      </div>
                    </div>
                    <div className="p-6 space-y-4">
                      <h3 className="font-black text-gray-900 text-lg line-clamp-2 h-14 leading-tight">{tool.name}</h3>
                      <div className="flex items-center justify-between text-[10px] text-gray-400 font-bold uppercase">
                          <span className="bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded">{tool.category}</span>
                          <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {tool.location || 'N/A'}</span>
                      </div>
                      {isManageMode ? (
                        <div className="flex gap-3 pt-4 border-t">
                           <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="flex-1 bg-white border-2 border-indigo-100 text-indigo-700 py-3 rounded-2xl text-[10px] font-black uppercase">Sửa</button>
                           <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-3 bg-white border-2 border-rose-100 text-rose-600 rounded-2xl"><Trash2 className="w-5 h-5" /></button>
                        </div>
                      ) : isSelected && (
                        <div className="bg-indigo-600 text-white py-3 rounded-2xl text-center text-[10px] font-black uppercase shadow-lg shadow-indigo-100 flex items-center justify-center gap-2"><Check className="w-4 h-4" /> Đã chọn</div>
                      )}
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[3rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Hình</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Tên thiết bị</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Kho/Sẵn</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-10 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => (
                    <tr key={tool.id} className="hover:bg-blue-50/30 transition-all cursor-pointer" onClick={() => !isManageMode && tool.available > 0 && toggleSelection(tool.id)}>
                      <td className="px-10 py-6"><div className="w-16 h-16 rounded-2xl bg-white border-2 overflow-hidden flex items-center justify-center p-1"><ToolThumbnail src={tool.image} alt={tool.name} mode="table" /></div></td>
                      <td className="px-10 py-6 font-black text-gray-900">{tool.name}</td>
                      <td className="px-10 py-6 text-center text-sm font-black tabular-nums">{tool.available} / {tool.quantity}</td>
                      <td className="px-10 py-6">{tool.status === 'active' ? <span className="text-emerald-700 bg-emerald-50 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-emerald-100">Hoạt động</span> : <span className="text-rose-700 bg-rose-50 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-rose-100">Bảo trì</span>}</td>
                      <td className="px-10 py-6 text-right" onClick={e => e.stopPropagation()}>{isManageMode ? <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-gray-100 rounded-2xl transition-colors"><Edit className="w-5 h-5"/></button> : selectedToolIds.has(tool.id) ? <span className="text-indigo-600 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 justify-end"><Check className="w-4 h-4" /> Đã chọn</span> : <button disabled={tool.available === 0} className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><PackagePlus className="w-5 h-5"/></button>}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {/* Pagination */}
      <Card className="p-6 rounded-[3rem] shadow-xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
          <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">Hiển thị {Math.min(filteredTools.length, startIndex + 1)}-{Math.min(filteredTools.length, startIndex + pageSize)} trong {filteredTools.length} thiết bị</span>
          <div className="flex items-center gap-3">
              <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50"><ChevronLeft className="w-5 h-5" /></button>
              <span className="bg-indigo-50 text-indigo-600 px-4 py-2 rounded-lg text-sm font-black border border-indigo-100">{currentPage} / {totalPages}</span>
              <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50"><ChevronRight className="w-5 h-5" /></button>
          </div>
      </Card>

      {/* Floating Borrow Action Bar */}
      {!isManageMode && selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[80] w-[calc(100%-2rem)] max-w-2xl animate-fade-in-up">
            <div className="bg-slate-900/90 backdrop-blur-xl border border-white/20 p-4 md:p-6 rounded-[2.5rem] shadow-2xl flex items-center justify-between gap-4">
                <div className="flex items-center gap-4 pl-2">
                    <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">
                        {selectedToolIds.size}
                    </div>
                    <div>
                        <p className="text-white font-black text-sm md:text-base leading-none">Thiết bị được chọn</p>
                        <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mt-1">Sẽ gửi yêu cầu mượn ngay</p>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button 
                        onClick={() => setSelectedToolIds(new Set())}
                        className="px-4 py-3 text-gray-400 hover:text-white text-[10px] font-black uppercase tracking-widest transition-colors"
                    >
                        Hủy
                    </button>
                    <button 
                        onClick={handleBulkBorrow}
                        disabled={isBorrowing}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-[0.2em] shadow-xl shadow-blue-600/20 flex items-center gap-2 transition-all active:scale-95 disabled:opacity-50"
                    >
                        {isBorrowing ? <Loader2 className="w-4 h-4 animate-spin" /> : <><Send className="w-4 h-4" /> XÁC NHẬN MƯỢN</>}
                    </button>
                </div>
            </div>
          </div>
      )}

      {/* Admin Modals */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-zoom-in my-auto no-scrollbar">
            <div className="flex justify-between items-center p-10 border-b sticky top-0 bg-white z-10">
              <h3 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">{isEditing ? 'Cập nhật' : 'Thêm mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-gray-100 rounded-3xl"><X className="w-6 h-6 text-gray-400"/></button>
            </div>
            <div className="p-10 space-y-8 bg-gray-50/50">
              <div className="space-y-6 bg-white p-8 rounded-[3rem] border shadow-sm">
                <input type="text" placeholder="Tên thiết bị..." value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10">
                  <option>Thiết bị cầm tay</option><option>Máy móc lớn</option><option>Đồ bảo hộ</option><option>Vật tư tiêu hao</option>
                </select>
                <div className="grid grid-cols-2 gap-6">
                  <input type="number" placeholder="Tổng số" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                  <input type="number" placeholder="Sẵn có" value={formData.available} onChange={e => setFormData({...formData, available: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                </div>
                <input type="text" placeholder="Link hình ảnh..." value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
              </div>
              <button onClick={handleSaveTool} className="w-full py-6 bg-indigo-600 text-white font-black rounded-[2rem] shadow-2xl uppercase text-xs flex items-center justify-center gap-3 transition-all active:scale-95"><Save className="w-6 h-6"/> {isEditing ? 'LƯU THAY ĐỔI' : 'XÁC NHẬN THÊM'}</button>
            </div>
          </div>
        </div>
      )}

      {toolToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2.5rem] shadow-2xl rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-12 h-12"/></div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter">Xóa tài sản?</h3>
              <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80">Dữ liệu sẽ bị xóa vĩnh viễn.</p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t">
              <button onClick={handleDeleteTool} className="w-full py-5 bg-rose-600 text-white font-black rounded-[2rem] text-xs uppercase shadow-2xl transition-all active:scale-95">XÁC NHẬN XÓA</button>
              <button onClick={() => setToolToDelete(null)} className="w-full py-5 bg-white text-gray-400 font-black rounded-[2rem] border-2 text-xs uppercase active:scale-95">HỦY BỎ</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Sidebar } from './src/components/layout/Sidebar';
import { Header } from './src/components/layout/Header';
import { LoginForm } from './src/components/auth/LoginForm';
import { DashboardStats } from './src/components/dashboard/DashboardStats';
import { EmployeeList } from './src/components/employees/EmployeeList';
import { ToolInventory } from './src/components/tools/ToolInventory';
import { RequestManager } from './src/components/requests/RequestManager';
import { HistoryLog } from './src/components/history/HistoryLog';
import { OvertimeRegistration } from './src/components/overtime/OvertimeRegistration';
import { generateManagerInsight } from './src/services/geminiService';
import { Bot, X, Send, Menu } from 'lucide-react';
import { supabase } from './src/lib/supabase';
import { User } from './types';

const MainLayout: React.FC<{ children: React.ReactNode; user: User; onLogout: () => void }> = ({ children, user, onLogout }) => {
  const location = useLocation();
  const [currentPath, setCurrentPath] = useState(location.pathname);
  const [showAiChat, setShowAiChat] = useState(false);
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [pendingBorrowCount, setPendingBorrowCount] = useState(0);
  const [pendingOTCount, setPendingOTCount] = useState(0);

  useEffect(() => {
    setCurrentPath(location.pathname);
    setIsSidebarOpen(false);
  }, [location]);

  const fetchCounts = useCallback(async () => {
    if (!user) return;

    const isAdmin = user.role === 'admin';

    try {
      // Truy vấn số lượng đơn mượn đồ đang chờ (pending)
      let borrowQuery = supabase.from('requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) {
        borrowQuery = borrowQuery.eq('user_id', user.id);
      }
      const { count: bCount } = await borrowQuery;
      setPendingBorrowCount(bCount || 0);

      // Truy vấn số lượng đơn tăng ca đang chờ (nếu có logic pending)
      let otQuery = supabase.from('ot_requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) {
        otQuery = otQuery.eq('user_id', user.id);
      }
      const { count: oCount } = await otQuery;
      setPendingOTCount(oCount || 0);
    } catch (error) {
      console.error("Error fetching badge counts:", error);
    }
  }, [user]);

  useEffect(() => {
    fetchCounts();

    // Lắng nghe sự kiện tùy chỉnh để cập nhật badge ngay lập tức
    const handleRefresh = () => fetchCounts();
    window.addEventListener('refresh-counts', handleRefresh);

    // Polling định kỳ mỗi 15 giây để đảm bảo dữ liệu mới nhất
    const interval = setInterval(fetchCounts, 15000);

    return () => {
      window.removeEventListener('refresh-counts', handleRefresh);
      clearInterval(interval);
    };
  }, [fetchCounts]);

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!aiQuery.trim()) return;

    setAiLoading(true);
    const context = `User Role: ${user.role}.`;
    const result = await generateManagerInsight(context, aiQuery);
    setAiResponse(result || "Không có phản hồi.");
    setAiLoading(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <Sidebar 
        currentPath={currentPath} 
        onNavigate={(path) => window.location.hash = path} 
        onLogout={onLogout}
        userRole={user.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        pendingBorrowCount={pendingBorrowCount}
        pendingOTCount={pendingOTCount}
      />

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      <div className="flex-1 flex flex-col min-w-0">
        <Header user={user} onMenuClick={() => setIsSidebarOpen(true)} />
        <main className="flex-1 p-4 md:p-8">
          {children}
        </main>
      </div>

      <div className="fixed bottom-6 right-6 z-50">
        {!showAiChat ? (
          <button 
            onClick={() => setShowAiChat(true)}
            className="w-14 h-14 bg-gradient-to-r from-blue-600 to-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white hover:shadow-xl transition-all transform hover:scale-110 active:scale-95 border-4 border-white"
          >
            <Bot className="w-7 h-7" />
          </button>
        ) : (
          <div className="bg-white rounded-2xl shadow-2xl w-[calc(100vw-2rem)] sm:w-96 flex flex-col border border-gray-200 overflow-hidden animate-fade-in-up origin-bottom-right">
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-4 flex justify-between items-center text-white">
              <div className="flex items-center gap-2">
                <Bot className="w-5 h-5" />
                <span className="font-semibold text-sm">Trợ lý Quản lý</span>
              </div>
              <button onClick={() => setShowAiChat(false)} className="hover:bg-white/20 p-1 rounded transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 h-64 overflow-y-auto bg-gray-50 text-sm">
              {!aiResponse && !aiLoading && (
                <p className="text-gray-500 text-center mt-20 italic">Hãy hỏi tôi về dữ liệu hệ thống...</p>
              )}
              {aiLoading && (
                <div className="flex items-center justify-center h-full">
                   <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                </div>
              )}
              {aiResponse && (
                <div className="prose prose-sm max-w-none text-gray-800 whitespace-pre-line">
                  {aiResponse}
                </div>
              )}
            </div>

            <form onSubmit={handleAiAsk} className="p-3 border-t bg-white flex gap-2">
              <input 
                type="text" 
                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Hỏi trợ lý AI..."
                className="flex-1 px-3 py-2 border rounded-xl focus:outline-none focus:border-blue-500 text-sm shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 disabled:opacity-50 transition-colors shadow-md"
              >
                <Send className="w-4 h-4" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-gray-400 font-bold text-xs uppercase tracking-widest">Đang tải hệ thống...</p>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={
          !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
        } />

        <Route path="/dashboard" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/employees" element={
          user ? (
             user.role === 'admin' ? (
                <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
             ) : <Navigate to="/dashboard" />
          ) : <Navigate to="/login" />
        } />

        <Route path="/tools" element={
          user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/requests" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/history" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="/overtime" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
        } />

        <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, ChevronDown, ChevronsLeft, ChevronsRight,
  CheckCircle2, Trash2, Check, ArrowRight
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className="flex flex-col items-center justify-center bg-gray-100 w-full h-full rounded-xl">
        <Wrench className={`${mode === 'grid' ? 'w-10 h-10 text-gray-300' : 'w-6 h-6 text-gray-400'}`} />
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white rounded-xl`}>
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedToolIds, setSelectedToolIds] = useState<Set<string>>(new Set());
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);
  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedToolIds);
    if (newSet.has(id)) {
        newSet.delete(id);
    } else {
        newSet.add(id);
    }
    setSelectedToolIds(newSet);
  };

  const handleBulkBorrow = async () => {
    if (selectedToolIds.size === 0) return;
    setIsBorrowing(true);
    try {
      const selectedTools = tools.filter(t => selectedToolIds.has(t.id));

      for (const tool of selectedTools) {
        if (tool.available <= 0) continue;

        const requestPayload = {
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        };

        const { error } = await supabase.from('requests').insert([requestPayload]);
        if (error) throw error;
      }

      setMessage(`Đã gửi ${selectedToolIds.size} yêu cầu mượn đồ!`);
      setSelectedToolIds(new Set());

      // Kích hoạt cập nhật badge ngay lập tức
      window.dispatchEvent(new CustomEvent('refresh-counts'));

      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi khi gửi yêu cầu: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      await supabase.from('tools').delete().eq('id', toolToDelete);
      await fetchTools(); setToolToDelete(null);
      setMessage('Đã xóa thành công'); setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* Header & Filters */}
      <div className="flex flex-col gap-4 bg-white p-5 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100 text-white"><Wrench className="w-8 h-8" /></div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">Kho công cụ</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2 opacity-70">Quản lý & Điều phối tài sản</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button onClick={() => {setIsManageMode(true); setSelectedToolIds(new Set());}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500'}`}><Settings2 className="w-4 h-4 mr-2 inline" />QUẢN LÝ</button>
                        <button onClick={() => {setIsManageMode(false); setSelectedToolIds(new Set());}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500'}`}><ShoppingBag className="w-4 h-4 mr-2 inline" />MƯỢN ĐỒ</button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}><List className="w-5 h-5" /></button>
                </div>

                {isManageMode && <button onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-4 rounded-2xl text-xs font-black uppercase shadow-xl transition-all active:scale-95">THÊM MỚI</button>}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Tìm tên thiết bị, vị trí..." className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none" />
            </div>

            <div className="flex gap-3">
                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none">
                    <option value="all">Tất cả danh mục</option>
                    {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                </select>
                <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className="px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none">
                    <option value="all">Tất cả trạng thái</option>
                    <option value="available">Sẵn có</option>
                    <option value="inactive">Bảo trì</option>
                </select>
            </div>
        </div>
      </div>

      {/* Tools Display */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const isSelected = selectedToolIds.has(tool.id);
                const isAvailable = tool.status === 'active' && tool.available > 0;
                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all p-0 border-2 overflow-hidden rounded-[2.5rem] ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-50' : 'border-transparent bg-white shadow-lg'} ${!isManageMode && !isAvailable ? 'opacity-60 grayscale-[0.5]' : ''}`} onClick={() => !isManageMode && isAvailable && toggleSelection(tool.id)}>
                    <div className="h-56 bg-white flex items-center justify-center relative border-b">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4">
                        {tool.status === 'inactive' ? <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg">Bảo trì</span> : <span className={`text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg ${tool.available > 0 ? 'bg-emerald-500' : 'bg-gray-400'}`}>Sẵn có: {tool.available}</span>}
                      </div>
                    </div>
                    <div className="p-6 space-y-4">
                      <h3 className="font-black text-gray-900 text-lg line-clamp-2 h-14 leading-tight">{tool.name}</h3>
                      <div className="flex items-center justify-between text-[10px] text-gray-400 font-bold uppercase">
                          <span className="bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded">{tool.category}</span>
                          <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {tool.location || 'N/A'}</span>
                      </div>
                      {isManageMode ? (
                        <div className="flex gap-3 pt-4 border-t">
                           <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="flex-1 bg-white border-2 border-indigo-100 text-indigo-700 py-3 rounded-2xl text-[10px] font-black uppercase">Sửa</button>
                           <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-3 bg-white border-2 border-rose-100 text-rose-600 rounded-2xl"><Trash2 className="w-5 h-5" /></button>
                        </div>
                      ) : isSelected && (
                        <div className="bg-indigo-600 text-white py-3 rounded-2xl text-center text-[10px] font-black uppercase shadow-lg shadow-indigo-100 flex items-center justify-center gap-2"><Check className="w-4 h-4" /> Đã chọn</div>
                      )}
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[3rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Hình</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Tên thiết bị</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Kho/Sẵn</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-10 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => (
                    <tr key={tool.id} className="hover:bg-blue-50/30 transition-all cursor-pointer" onClick={() => !isManageMode && tool.available > 0 && toggleSelection(tool.id)}>
                      <td className="px-10 py-6"><div className="w-16 h-16 rounded-2xl bg-white border-2 overflow-hidden flex items-center justify-center p-1"><ToolThumbnail src={tool.image} alt={tool.name} mode="table" /></div></td>
                      <td className="px-10 py-6 font-black text-gray-900">{tool.name}</td>
                      <td className="px-10 py-6 text-center text-sm font-black tabular-nums">{tool.available} / {tool.quantity}</td>
                      <td className="px-10 py-6">{tool.status === 'active' ? <span className="text-emerald-700 bg-emerald-50 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-emerald-100">Hoạt động</span> : <span className="text-rose-700 bg-rose-50 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-rose-100">Bảo trì</span>}</td>
                      <td className="px-10 py-6 text-right" onClick={e => e.stopPropagation()}>{isManageMode ? <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-gray-100 rounded-2xl transition-colors"><Edit className="w-5 h-5"/></button> : selectedToolIds.has(tool.id) ? <span className="text-indigo-600 font-black text-[10px] uppercase tracking-widest flex items-center gap-2 justify-end"><Check className="w-4 h-4" /> Đã chọn</span> : <button disabled={tool.available === 0} className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><PackagePlus className="w-5 h-5"/></button>}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {/* Pagination */}
      <Card className="p-6 rounded-[3rem] shadow-xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
          <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">Hiển thị {Math.min(filteredTools.length, startIndex + 1)}-{Math.min(filteredTools.length, startIndex + pageSize)} trong {filteredTools.length} thiết bị</span>
          <div className="flex items-center gap-3">
              <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50"><ChevronLeft className="w-5 h-5" /></button>
              <span className="bg-indigo-50 text-indigo-600 px-4 py-2 rounded-lg text-sm font-black border border-indigo-100">{currentPage} / {totalPages}</span>
              <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50"><ChevronRight className="w-5 h-5" /></button>
          </div>
      </Card>

      {/* Floating Borrow Action Bar */}
      {!isManageMode && selectedToolIds.size > 0 && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[80] w-[calc(100%-2rem)] max-w-2xl animate-fade-in-up">
            <div className="bg-slate-900/90 backdrop-blur-xl border border-white/20 p-4 md:p-6 rounded-[2.5rem] shadow-2xl flex items-center justify-between gap-4">
                <div className="flex items-center gap-4 pl-2">
                    <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20">
                        {selectedToolIds.size}
                    </div>
                    <div>
                        <p className="text-white font-black text-sm md:text-base leading-none">Thiết bị được chọn</p>
                        <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mt-2">Sẽ gửi yêu cầu mượn ngay</p>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button 
                        onClick={() => setSelectedToolIds(new Set())}
                        className="px-4 py-3 text-gray-400 hover:text-white text-[10px] font-black uppercase tracking-widest transition-colors"
                    >
                        Hủy
                    </button>
                    <button 
                        onClick={handleBulkBorrow}
                        disabled={isBorrowing}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-[0.2em] shadow-xl shadow-blue-600/20 flex items-center gap-2 transition-all active:scale-95 disabled:opacity-50"
                    >
                        {isBorrowing ? <Loader2 className="w-4 h-4 animate-spin" /> : <><Send className="w-4 h-4" /> XÁC NHẬN MƯỢN</>}
                    </button>
                </div>
            </div>
          </div>
      )}

      {/* Admin Modals */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-zoom-in my-auto no-scrollbar">
            <div className="flex justify-between items-center p-10 border-b sticky top-0 bg-white z-10">
              <h3 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">{isEditing ? 'Cập nhật' : 'Thêm mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-gray-100 rounded-3xl"><X className="w-6 h-6 text-gray-400"/></button>
            </div>
            <div className="p-10 space-y-8 bg-gray-50/50">
              <div className="space-y-6 bg-white p-8 rounded-[3rem] border shadow-sm">
                <input type="text" placeholder="Tên thiết bị..." value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10">
                  <option>Thiết bị cầm tay</option><option>Máy móc lớn</option><option>Đồ bảo hộ</option><option>Vật tư tiêu hao</option>
                </select>
                <div className="grid grid-cols-2 gap-6">
                  <input type="number" placeholder="Tổng số" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                  <input type="number" placeholder="Sẵn có" value={formData.available} onChange={e => setFormData({...formData, available: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                </div>
                <input type="text" placeholder="Link hình ảnh..." value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
              </div>
              <button onClick={handleSaveTool} className="w-full py-6 bg-indigo-600 text-white font-black rounded-[2rem] shadow-2xl uppercase text-xs flex items-center justify-center gap-3 transition-all active:scale-95"><Save className="w-6 h-6"/> {isEditing ? 'LƯU THAY ĐỔI' : 'XÁC NHẬN THÊM'}</button>
            </div>
          </div>
        </div>
      )}

      {toolToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2.5rem] shadow-2xl rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-12 h-12"/></div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter">Xóa tài sản?</h3>
              <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80">Dữ liệu sẽ bị xóa vĩnh viễn.</p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t">
              <button onClick={handleDeleteTool} className="w-full py-5 bg-rose-600 text-white font-black rounded-[2rem] text-xs uppercase shadow-2xl transition-all active:scale-95">XÁC NHẬN XÓA</button>
              <button onClick={() => setToolToDelete(null)} className="w-full py-5 bg-white text-gray-400 font-black rounded-[2rem] border-2 text-xs uppercase active:scale-95">HỦY BỎ</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, XCircle,
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw, ChevronLeft, ChevronsLeft, ChevronsRight,
  ThumbsUp, ThumbsDown
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-sm border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin" />}
      <p className="text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  // Phân trang
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 20;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (err: any) {
        showToast("Không thể tải dữ liệu: " + err.message, "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = { 'pending': 0, 'approved': 1, 'returned': 2, 'rejected': 3 };
        if (statusOrder[a.status] !== statusOrder[b.status]) return statusOrder[a.status] - statusOrder[b.status];
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentRequests = filteredRequests.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterStatus, filterStartDate, activeTab]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus as any, ...extraData } : req));
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    setProcessingId(action.type === 'cancel' ? action.id : action.req.id);

    try {
        if (action.type === 'approve') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
            await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'approved' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'approved');
        } else if (action.type === 'return') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'returned');
        } else if (action.type === 'cancel') {
            await supabase.from('requests').delete().eq('id', action.id);
            setRequests(prev => prev.filter(r => r.id !== action.id));
        } else if (action.type === 'reject') {
            await supabase.from('requests').update({ status: 'rejected' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'rejected');
        }

        // Kích hoạt cập nhật badge ở Sidebar ngay lập tức
        window.dispatchEvent(new CustomEvent('refresh-counts'));

        showToast("Thao tác thành công!", "success");
    } catch (e: any) {
        showToast(e.message, "error");
    } finally {
        setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'pending': 
        return {
            className: 'bg-amber-500 text-white border-amber-600 shadow-amber-200/50',
            icon: <Clock className="w-3.5 h-3.5" />,
            label: 'Chờ Duyệt'
        };
      case 'approved': 
        return {
            className: 'bg-emerald-600 text-white border-emerald-700 shadow-emerald-200/50',
            icon: <CheckCircle2 className="w-3.5 h-3.5" />,
            label: 'Đang Mượn'
        };
      case 'returned': 
        return {
            className: 'bg-blue-600 text-white border-blue-700 shadow-blue-200/50',
            icon: <RotateCcw className="w-3.5 h-3.5" />,
            label: 'Đã Trả'
        };
      case 'rejected': 
        return {
            className: 'bg-rose-600 text-white border-rose-700 shadow-rose-200/50',
            icon: <XCircle className="w-3.5 h-3.5" />,
            label: 'Từ Chối'
        };
      default: 
        return {
            className: 'bg-gray-500 text-white border-gray-600 shadow-gray-200/50',
            icon: <Info className="w-3.5 h-3.5" />,
            label: 'Không Xác Định'
        };
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in w-full pb-20">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-5">
            <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100"><Wrench className="w-8 h-8 text-white" /></div>
            <div>
              <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">
                {activeTab === 'personal' ? 'Yêu cầu của tôi' : 'Quản lý Đơn Mượn'}
              </h2>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2 opacity-70">
                {activeTab === 'personal' ? 'Theo dõi lịch sử cá nhân' : 'Quản lý & phê duyệt hệ thống'}
              </p>
            </div>
        </div>

        <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
            {user.role === 'admin' && (
              <button 
                onClick={() => setActiveTab('all')} 
                className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
              >
                HỆ THỐNG
              </button>
            )}
            <button 
              onClick={() => setActiveTab('personal')} 
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-blue-700 shadow-lg transform scale-105' : 'text-gray-500'}`}
            >
              CỦA TÔI
            </button>
        </div>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative group flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-500" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm nhân viên, thiết bị..." 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none transition-all"
          />
        </div>

        <div className="relative group">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className="w-full px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold appearance-none outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ phê duyệt</option>
            <option value="approved">✅ Đang mượn</option>
            <option value="returned">↩️ Đã hoàn trả</option>
            <option value="rejected">❌ Từ chối</option>
          </select>
          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
        </div>

        <div className="relative group">
          <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input 
            type="date" 
            value={filterStartDate} 
            onChange={e => setFilterStartDate(e.target.value)} 
            className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
          />
        </div>
      </div>

      <Card className="p-0 rounded-[3rem] shadow-2xl overflow-hidden border-none bg-white">
        <div className="overflow-x-auto w-full">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Người mượn</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thiết bị</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] bg-gray-50/50">Thời gian</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-center bg-gray-50/50">Trạng thái</th>
                <th className="px-10 py-6 text-gray-500 font-black uppercase text-[10px] tracking-[0.2em] text-right bg-gray-50/50">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="p-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : currentRequests.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                currentRequests.map((req) => {
                  const badge = getStatusBadge(req.status);
                  return (
                    <tr key={req.id} className="hover:bg-blue-50/20 transition-all duration-300 group">
                      <td className="px-10 py-6">
                        <div className="flex items-center gap-4">
                          <div className="w-12 h-12 rounded-[1rem] bg-indigo-600 text-white flex items-center justify-center font-black text-lg shadow-lg border-2 border-indigo-400 transition-transform group-hover:scale-110 group-hover:rotate-3">
                            {req.user_name?.charAt(0)}
                          </div>
                          <div>
                            <p className="font-black text-gray-900 text-sm tracking-tight">{req.user_name}</p>
                            <p className="text-[10px] text-gray-400 font-black tracking-widest uppercase opacity-70 mt-0.5">{req.employee_id}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-10 py-6">
                        <div className="flex items-center gap-4">
                           <div className="w-14 h-14 bg-white border-2 border-gray-50 rounded-2xl flex items-center justify-center overflow-hidden p-2 group-hover:border-blue-200 transition-colors shadow-sm">
                             {req.tool_image ? <img src={req.tool_image} alt="" className="w-full h-full object-contain" /> : <Wrench className="w-6 h-6 text-gray-200" />}
                           </div>
                           <p className="font-black text-gray-800 text-sm leading-tight max-w-[200px]">{req.tool_name}</p>
                        </div>
                      </td>
                      <td className="px-10 py-6 text-[11px] font-black text-gray-500 uppercase tracking-tighter">
                        <div className="flex items-center gap-2">
                          <Calendar className="w-3.5 h-3.5 opacity-30" />
                          {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                        </div>
                      </td>
                      <td className="px-10 py-6 text-center">
                        <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 shadow-lg transition-all group-hover:scale-105 ${badge.className}`}>
                          {badge.icon}
                          {badge.label}
                        </div>
                      </td>
                      <td className="px-10 py-6 text-right">
                        <div className="flex justify-end gap-3 items-center">
                          {processingId === req.id ? (
                            <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                          ) : (
                            <>
                              {user.role === 'admin' && activeTab === 'all' && req.status === 'pending' && (
                                <div className="flex items-center gap-2">
                                  <button 
                                    onClick={() => setConfirmAction({ type: 'approve', req })} 
                                    className="flex items-center gap-2 px-5 py-3 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all active:scale-90"
                                    title="Duyệt yêu cầu"
                                  >
                                    <Check className="w-4 h-4" /> DUYỆT
                                  </button>
                                  <button 
                                    onClick={() => setConfirmAction({ type: 'reject', req })} 
                                    className="flex items-center gap-2 px-5 py-3 bg-white text-rose-600 border-2 border-rose-100 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all active:scale-90"
                                    title="Từ chối"
                                  >
                                    <X className="w-4 h-4" /> TỪ CHỐI
                                  </button>
                                </div>
                              )}

                              {user.role === 'admin' && activeTab === 'all' && req.status === 'approved' && (
                                <button 
                                  onClick={() => setConfirmAction({ type: 'return', req })} 
                                  className="flex items-center gap-2 px-6 py-4 bg-blue-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
                                >
                                  <RotateCcw className="w-5 h-5" /> THU HỒI TÀI SẢN
                                </button>
                              )}

                              {req.user_id === user.id && req.status === 'pending' && (
                                <button 
                                  onClick={() => setConfirmAction({ type: 'cancel', id: req.id })} 
                                  className="flex items-center gap-2 px-6 py-4 bg-white text-rose-600 border-2 border-rose-100 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all active:scale-95 shadow-sm"
                                >
                                  <Trash2 className="w-5 h-5" /> HỦY YÊU CẦU
                                </button>
                              )}
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {filteredRequests.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-6 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredRequests.length, startIndex + 1)}-{Math.min(filteredRequests.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums">{filteredRequests.length}</span> yêu cầu
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-blue-100">{currentPage} / {totalPages}</span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => handlePageChange(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang đầu"
              >
                <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum = 1;
                  if (totalPages <= 5) pageNum = i + 1;
                  else if (currentPage <= 3) pageNum = i + 1;
                  else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                  else pageNum = currentPage - 2 + i;

                  return (
                    <button
                      key={pageNum}
                      onClick={() => handlePageChange(pageNum)}
                      className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                        currentPage === pageNum 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xl scale-110 z-10' 
                        : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                title="Trang cuối"
              >
                <ChevronsRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}
      </Card>

      {/* CONFIRM MODAL */}
      {confirmAction && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl rotate-12 transition-transform hover:rotate-0 ${
                confirmAction.type === 'approve' ? 'bg-emerald-100 text-emerald-600' : 
                confirmAction.type === 'reject' ? 'bg-rose-100 text-rose-600' :
                'bg-blue-100 text-blue-600'
              }`}>
                {confirmAction.type === 'approve' ? <ThumbsUp className="w-12 h-12" /> : 
                 confirmAction.type === 'reject' ? <ThumbsDown className="w-12 h-12" /> :
                 <RotateCcw className="w-12 h-12" />}
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">
                {confirmAction.type === 'approve' ? 'Duyệt yêu cầu?' : 
                 confirmAction.type === 'reject' ? 'Từ chối đơn?' : 
                 confirmAction.type === 'return' ? 'Thu hồi đồ?' : 'Xác nhận xóa?'}
              </h3>
              <p className="text-[11px] text-gray-400 font-bold leading-relaxed px-6 uppercase tracking-[0.15em] opacity-80 italic">
                {confirmAction.type === 'approve' ? 'Hành động này sẽ cập nhật tồn kho thiết bị.' : 
                 confirmAction.type === 'reject' ? 'Đơn này sẽ được chuyển sang trạng thái Từ chối.' :
                 confirmAction.type === 'return' ? 'Xác nhận người mượn đã hoàn trả thiết bị.' : 'Hành động này không thể hoàn tác.'}
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleConfirmAction} 
                className={`w-full py-5 text-white font-black rounded-3xl text-xs uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${
                  confirmAction.type === 'approve' ? 'bg-emerald-600 shadow-emerald-200' : 
                  confirmAction.type === 'reject' ? 'bg-rose-600 shadow-rose-200' :
                  'bg-blue-600 shadow-blue-200'
                }`}
              >
                XÁC NHẬN THỰC HIỆN
              </button>
              <button 
                onClick={() => setConfirmAction(null)} 
                className="w-full py-5 bg-white text-gray-400 font-black rounded-3xl border-2 border-gray-100 hover:bg-gray-100 text-xs uppercase tracking-[0.2em] transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { 
  LayoutDashboard, 
  Users, 
  Wrench, 
  Clock, 
  History, 
  FileText, 
  LogOut,
  X
} from 'lucide-react';

interface SidebarProps {
  currentPath: string;
  onNavigate: (path: string) => void;
  onLogout: () => void;
  userRole: string;
  isOpen?: boolean;
  onClose?: () => void;
  pendingBorrowCount?: number;
  pendingOTCount?: number;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentPath, 
  onNavigate, 
  onLogout, 
  userRole, 
  isOpen, 
  onClose,
  pendingBorrowCount = 0,
  pendingOTCount = 0
}) => {
  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, path: '/dashboard', roles: ['admin', 'manager', 'employee', 'user'] },
    { id: 'employees', label: 'Nhân viên', icon: Users, path: '/employees', roles: ['admin', 'manager'] },
    { id: 'tools', label: 'Công cụ', icon: Wrench, path: '/tools', roles: ['admin', 'manager', 'employee', 'user'] },
    { id: 'requests', label: 'Yêu cầu mượn', icon: FileText, path: '/requests', roles: ['admin', 'manager', 'employee', 'user'], badge: pendingBorrowCount },
    { id: 'history', label: 'Lịch sử', icon: History, path: '/history', roles: ['admin', 'manager', 'employee', 'user'] },
    { id: 'overtime', label: 'Tăng ca', icon: Clock, path: '/overtime', roles: ['admin', 'manager', 'employee', 'user'], badge: pendingOTCount }, 
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(userRole));

  return (
    <div className={`
      fixed lg:sticky top-0 z-50 w-64 bg-slate-900 text-white flex flex-col h-screen overflow-y-auto transition-transform duration-300 ease-in-out
      ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
    `}>
      <div className="p-6 border-b border-slate-700 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center font-bold shadow-lg shadow-blue-500/20">M</div>
          <span className="font-bold text-lg tracking-wide">Manager Tool</span>
        </div>
        <button onClick={onClose} className="lg:hidden p-1 hover:bg-slate-800 rounded transition-colors">
          <X className="w-5 h-5 text-slate-400" />
        </button>
      </div>

      <nav className="flex-1 p-4 space-y-1">
        {filteredItems.map((item) => {
          const isActive = currentPath === item.path;
          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.path)}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-200 group ${
                isActive 
                  ? 'bg-blue-600 text-white shadow-xl shadow-blue-600/20 transform scale-[1.02]' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <div className="flex items-center gap-3">
                <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-white'}`} />
                <span className="font-medium text-sm tracking-tight">{item.label}</span>
              </div>

              {item.badge !== undefined && item.badge > 0 && (
                <span className={`flex items-center justify-center min-w-[22px] h-5 px-1.5 rounded-full text-[10px] font-black border-2 animate-pulse ${
                  isActive ? 'bg-white text-blue-600 border-blue-400' : 'bg-red-600 text-white border-red-500'
                }`}>
                  {item.badge}
                </span>
              )}
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-700">
        <button 
          onClick={onLogout}
          className="w-full flex items-center gap-3 px-4 py-3 text-rose-400 hover:bg-rose-900/20 hover:text-rose-300 rounded-xl transition-all"
        >
          <LogOut className="w-5 h-5" />
          <span className="font-medium text-sm tracking-tight">Đăng xuất</span>
        </button>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Employee } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Search, Plus, User as UserIcon, X, Save, Edit2, Trash2, 
  AlertTriangle, Shield, User, ChevronLeft, ChevronRight, 
  ChevronsLeft, ChevronsRight, Loader2 
} from 'lucide-react';

export const EmployeeList: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // Phân trang
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 20;

  // State cho chức năng sửa/thêm
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentId, setCurrentId] = useState<string | null>(null);

  const initialForm = { employee_id: '', name: '', role: 'user', password: '123' };
  const [formData, setFormData] = useState(initialForm);

  // State cho chức năng xóa
  const [userToDelete, setUserToDelete] = useState<Employee | null>(null);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('users').select('*').order('employee_id', { ascending: true });
      if (data) setEmployees(data as Employee[]);
      if (error) throw error;
    } catch (error) {
      console.error("Error fetching employees:", error);
    } finally {
      setLoading(false);
    }
  };

  // Logic lọc và phân trang
  const filteredEmployees = useMemo(() => {
    return employees.filter(emp => 
      emp.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      emp.employee_id.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [employees, searchTerm]);

  const totalPages = Math.max(1, Math.ceil(filteredEmployees.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentEmployees = filteredEmployees.slice(startIndex, startIndex + pageSize);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm]);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleAddNew = () => {
    setFormData(initialForm);
    setIsEditing(false);
    setIsModalOpen(true);
  };

  const handleEdit = (employee: Employee) => {
    setCurrentId(employee.id);
    setFormData({
        employee_id: employee.employee_id,
        name: employee.name,
        role: employee.role,
        password: employee.password || '',
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  const handleDelete = async () => {
    if (!userToDelete) return;

    try {
      const { error } = await supabase.from('users').delete().eq('id', userToDelete.id);
      if (error) throw error;

      setEmployees(employees.filter(emp => emp.id !== userToDelete.id));
      setUserToDelete(null);
    } catch (error: any) {
      alert('Lỗi khi xóa tài khoản: ' + error.message);
    }
  };

  const handleSave = async () => {
    if (!formData.employee_id || !formData.name) return alert("Vui lòng nhập đủ thông tin");

    try {
      const payload = {
          employee_id: formData.employee_id,
          name: formData.name,
          role: formData.role,
          password: formData.password,
      };

      if (isEditing && currentId) {
        const { error } = await supabase.from('users').update(payload).eq('id', currentId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('users').insert([payload]);
        if (error) throw error;
      }

      await fetchEmployees();
      setIsModalOpen(false);
    } catch (error: any) {
      alert('Lỗi cập nhật: ' + error.message);
    }
  };

  return (
    <div className="space-y-6 relative animate-fade-in pb-10">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className="p-4 bg-blue-600 rounded-[1.2rem] shadow-xl shadow-blue-100 text-white">
            <UserIcon className="w-8 h-8" />
          </div>
          <div>
            <h2 className="text-2xl font-black text-gray-900 tracking-tight">Danh sách nhân sự</h2>
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">Quản lý tài khoản hệ thống</p>
          </div>
        </div>
        <button onClick={handleAddNew} className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl flex items-center gap-2 text-xs font-black uppercase tracking-widest transition-all shadow-xl shadow-blue-100 active:scale-95">
          <Plus className="w-4 h-4" />
          Thêm nhân sự
        </button>
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[2.5rem] bg-white">
        {/* Toolbar */}
        <div className="p-6 border-b border-gray-100 bg-gray-50/50">
          <div className="relative group max-w-md">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600 transition-colors" />
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Tìm tên, mã NV..." 
              className="w-full pl-12 pr-4 py-4 rounded-2xl border-none bg-white shadow-sm focus:outline-none focus:ring-4 focus:ring-blue-500/10 text-sm font-bold text-gray-900 transition-all"
            />
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100">
                <th className="px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Mã NV</th>
                <th className="px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Họ và tên</th>
                <th className="px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Vai trò</th>
                <th className="px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Ngày tạo</th>
                <th className="px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em] text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-10 py-32 text-center">
                    <div className="flex flex-col items-center gap-4">
                      <Loader2 className="w-12 h-12 animate-spin text-blue-600 opacity-20" />
                      <p className="text-xs font-black uppercase tracking-widest text-gray-300">Đang tải dữ liệu...</p>
                    </div>
                  </td>
                </tr>
              ) : currentEmployees.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-10 py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">
                    Không tìm thấy nhân sự nào
                  </td>
                </tr>
              ) : (
                currentEmployees.map((emp) => (
                  <tr key={emp.id} className="hover:bg-blue-50/20 transition-all duration-300 group">
                    <td className="px-10 py-6 font-black text-blue-600 text-sm tracking-tight">{emp.employee_id}</td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center border border-indigo-100 shadow-sm transition-transform group-hover:scale-110">
                           <UserIcon className="w-5 h-5 text-indigo-400"/>
                        </div>
                        <span className="font-black text-gray-900 text-sm">{emp.name}</span>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border-2 shadow-sm ${
                        emp.role === 'admin' 
                          ? 'bg-purple-50 text-purple-700 border-purple-200' 
                          : 'bg-blue-50 text-blue-700 border-blue-200'
                      }`}>
                        {emp.role === 'admin' ? <Shield className="w-3.5 h-3.5"/> : <User className="w-3.5 h-3.5"/>}
                        {emp.role}
                      </span>
                    </td>
                    <td className="px-10 py-6 text-[11px] font-black text-gray-400 uppercase tabular-nums">
                        {emp.created_at ? new Date(emp.created_at).toLocaleDateString('vi-VN') : '—'}
                    </td>
                    <td className="px-10 py-6 text-right">
                      <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => handleEdit(emp)}
                          className="bg-white p-3 border-2 border-blue-100 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all active:scale-90"
                          title="Sửa thông tin"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => setUserToDelete(emp)}
                          className="bg-white p-3 border-2 border-rose-100 text-rose-600 rounded-xl hover:bg-rose-600 hover:text-white hover:border-rose-600 transition-all active:scale-90"
                          title="Xóa tài khoản"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination Footer */}
        {filteredEmployees.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-8 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredEmployees.length, startIndex + 1)}-{Math.min(filteredEmployees.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums">{filteredEmployees.length}</span> nhân sự
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-blue-100">{currentPage} / {totalPages}</span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => handlePageChange(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum = 1;
                  if (totalPages <= 5) pageNum = i + 1;
                  else if (currentPage <= 3) pageNum = i + 1;
                  else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                  else pageNum = currentPage - 2 + i;

                  return (
                    <button
                      key={pageNum}
                      onClick={() => handlePageChange(pageNum)}
                      className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                        currentPage === pageNum 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xl scale-110 z-10' 
                        : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
              >
                <ChevronsRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}
      </Card>

      {/* Edit/Add Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-lg animate-zoom-in overflow-hidden">
            <div className="flex justify-between items-center p-10 border-b border-gray-100 sticky top-0 bg-white">
              <h3 className="text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none">
                {isEditing ? 'Sửa thông tin' : 'Thêm nhân sự mới'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-gray-100 rounded-[1.5rem] transition-colors">
                <X className="w-6 h-6 text-gray-400" />
              </button>
            </div>

            <div className="p-10 space-y-6 bg-gray-50/50">
              <div className="space-y-4 bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm">
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Mã nhân viên</label>
                  <input 
                    type="text" 
                    value={formData.employee_id} 
                    onChange={(e) => setFormData({...formData, employee_id: e.target.value.toUpperCase()})}
                    disabled={isEditing}
                    className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all disabled:opacity-50"
                    placeholder="VD: NV001"
                  />
                </div>

                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Họ và tên</label>
                  <input 
                    type="text" 
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                    placeholder="Nguyễn Văn A..."
                    className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                      <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Vai trò</label>
                      <select 
                        value={formData.role}
                        onChange={(e) => setFormData({...formData, role: e.target.value})}
                        className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all appearance-none cursor-pointer"
                      >
                        <option value="admin">Admin</option>
                        <option value="user">User</option>
                      </select>
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Mật khẩu</label>
                    <input 
                      type="text" 
                      value={formData.password}
                      onChange={(e) => setFormData({...formData, password: e.target.value})}
                      className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all"
                    />
                  </div>
                </div>
              </div>

              <button 
                onClick={handleSave}
                className="w-full py-6 bg-blue-600 text-white font-black rounded-[2rem] shadow-2xl shadow-blue-100 uppercase text-xs tracking-[0.2em] flex items-center justify-center gap-3 transition-all active:scale-95"
              >
                <Save className="w-5 h-5" />
                Lưu thay đổi
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Delete */}
      {userToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2rem] shadow-2xl rotate-12 transition-transform hover:rotate-0">
                <AlertTriangle className="w-12 h-12" />
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xóa nhân sự?</h3>
              <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80 leading-relaxed px-4">
                Xác nhận xóa tài khoản <strong>{userToDelete.name}</strong>. Dữ liệu liên quan cũng sẽ bị gỡ bỏ.
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleDelete}
                className="w-full py-5 bg-rose-600 text-white font-black rounded-[2rem] text-xs uppercase tracking-widest shadow-2xl shadow-rose-200 transition-all active:scale-95"
              >
                XÓA VĨNH VIỄN
              </button>
              <button 
                onClick={() => setUserToDelete(null)}
                className="w-full py-5 bg-white text-gray-400 font-black rounded-[2rem] border-2 border-gray-100 text-xs uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  TrendingUp, Activity, Zap, ChevronDown, ChevronUp, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const dayRequests = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            if (dayOfWeek === 6) {
                setStartTime('14:30');
            } else {
                setStartTime('17:30');
            }
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu trong khoảng thời gian này.");

    filtered.sort((a, b) => a.date.localeCompare(b.date));
    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    const summaryData = filtered.map(req => {
        const d = new Date(req.date);
        return {
            'Ngày': req.date,
            'Thứ': dayNames[d.getDay()],
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        };
    });
    const summarySheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'TỔNG HỢP');

    const groupedByDate: Record<string, OvertimeRequest[]> = {};
    filtered.forEach(req => {
        if (!groupedByDate[req.date]) groupedByDate[req.date] = [];
        groupedByDate[req.date].push(req);
    });

    Object.keys(groupedByDate).forEach(dateKey => {
        const dayReqs = groupedByDate[dateKey];
        const dateObj = new Date(dateKey);
        const dayLabel = dayNames[dateObj.getDay()];
        const sheetData = dayReqs.map(req => ({
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        }));
        const worksheet = XLSX.utils.json_to_sheet(sheetData);
        const tabName = dateKey.split('-').reverse().slice(0, 2).join('-');
        XLSX.utils.book_append_sheet(workbook, worksheet, `${tabName} (${dayLabel})`);
    });

    const fileNameDate = start === end ? `Ngay_${start}` : `${start}_den_${end}`;
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'personal' ? 'Ca_nhan' : 'Toan_bo'}_${fileNameDate}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => {
      const today = new Date().toISOString().split('T')[0];
      handleExportExcel(mode, { start: today, end: today });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setShowColleagueDetails(false);
    setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        const dayHours = monthlyApproved.filter(r => r.date === dStr).reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
        return { day: d, hours: dayHours };
    });
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { trend, totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRegistrations = useMemo(() => {
    return requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const dateObj = new Date(year, month, d);

        const dayOfWeek = dateObj.getDay();
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const configWork = dayConfigs[dateStr];
        const isActuallyWorking = configWork ?? defaultIsWorking;

        const isWeekendDefault = dayOfWeek === 0 || dayOfWeek === 6;

        const shouldShowBadge = !isActuallyWorking || (isActuallyWorking && isWeekendDefault);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-16 md:h-32 border border-gray-100 p-1 md:p-2 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30' : 'bg-white'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-0.5 md:gap-1.5">
                        <span className={`text-[10px] md:text-base font-black ${isToday ? 'bg-blue-600 text-white w-4 h-4 md:w-6 md:h-6 rounded-md md:rounded-lg flex items-center justify-center shadow-lg' : !isActuallyWorking ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                        <div className="flex items-center gap-0.5 md:gap-1">
                            {shouldShowBadge && (
                                <span className={`text-[6px] md:text-[8px] font-black px-1.5 md:px-2 py-0.5 md:py-1 rounded-full shadow-md uppercase border-2 ${!isActuallyWorking ? 'bg-rose-500 text-white border-rose-400' : 'bg-indigo-600 text-white border-indigo-500'}`}>
                                    {!isActuallyWorking ? 'Nghỉ' : 'Làm'}
                                </span>
                            )}
                        </div>
                    </div>
                </div>

                <div className="flex-1 flex flex-col justify-start gap-1 mt-0.5 overflow-hidden">
                    {myRequest && (
                        <div className="flex items-center gap-1">
                            <div className="w-1.5 h-1.5 md:w-6 md:h-6 rounded-full md:rounded-lg bg-emerald-500 shadow-sm flex items-center justify-center flex-shrink-0">
                                <UserIcon className="hidden md:block w-3.5 h-3.5 text-white" />
                            </div>
                        </div>
                    )}
                    {otherRequests.length > 0 && (
                        <div className="flex items-center gap-0.5">
                             <div className="flex -space-x-1 md:-space-x-2 overflow-hidden">
                                {otherRequests.slice(0, 5).map((req, idx) => (
                                    <div key={idx} className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-indigo-200 md:bg-indigo-100 border border-white shadow-sm flex items-center justify-center flex-shrink-0">
