      <div className="flex flex-col items-center justify-center bg-gray-100 w-full h-full rounded-xl">
        <Wrench className={`${mode === 'grid' ? 'w-10 h-10 text-gray-300' : 'w-6 h-6 text-gray-400'}`} />
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white rounded-xl`}>
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  // Lưu trữ số lượng mượn cho từng toolId: { [toolId]: quantity }
  const [selectedQuantities, setSelectedQuantities] = useState<Record<string, number>>({});
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);
  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const updateQuantity = (id: string, delta: number, max: number) => {
    setSelectedQuantities(prev => {
        const current = prev[id] || 0;
        const next = Math.max(0, Math.min(max, current + delta));
        const newQuantities = { ...prev };
        if (next === 0) {
            delete newQuantities[id];
        } else {
            newQuantities[id] = next;
        }
        return newQuantities;
    });
  };

  const handleBulkBorrow = async () => {
    const selectedToolIds = Object.keys(selectedQuantities);
    if (selectedToolIds.length === 0) return;
    setIsBorrowing(true);
    try {
      for (const toolId of selectedToolIds) {
        const tool = tools.find(t => t.id === toolId);
        const qty = selectedQuantities[toolId];

        if (!tool || tool.available < qty) continue;

        // Vì schema requests không có cột quantity, ta tạo nhiều record cho mỗi item
        const requestsToInsert = Array.from({ length: qty }).map(() => ({
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        }));

        const { error } = await supabase.from('requests').insert(requestsToInsert);
        if (error) throw error;
      }

      setMessage(`Đã gửi yêu cầu mượn ${Object.values(selectedQuantities).reduce((a, b) => a + b, 0)} thiết bị!`);
      setSelectedQuantities({});

      window.dispatchEvent(new CustomEvent('refresh-counts'));
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi khi gửi yêu cầu: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Cập nhật thành công' : 'Thêm mới thành công');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      await supabase.from('tools').delete().eq('id', toolToDelete);
      await fetchTools(); setToolToDelete(null);
      setMessage('Đã xóa thành công'); setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const totalSelectedCount = Object.values(selectedQuantities).reduce((sum, q) => sum + q, 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* Header & Filters */}
      <div className="flex flex-col gap-4 bg-white p-5 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.5rem] shadow-xl shadow-blue-100 text-white"><Wrench className="w-8 h-8" /></div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">Kho công cụ</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2 opacity-70">Quản lý & Điều phối tài sản</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div className="bg-emerald-600 text-white px-5 py-2.5 rounded-2xl flex items-center gap-2 animate-fade-in-up text-sm font-bold shadow-xl shadow-emerald-100">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button onClick={() => {setIsManageMode(true); setSelectedQuantities({});}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500'}`}><Settings2 className="w-4 h-4 mr-2 inline" />QUẢN LÝ</button>
                        <button onClick={() => {setIsManageMode(false); setSelectedQuantities({});}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-indigo-600 shadow-lg transform scale-105' : 'text-gray-500'}`}><ShoppingBag className="w-4 h-4 mr-2 inline" />MƯỢN ĐỒ</button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl ${viewMode === 'grid' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl ${viewMode === 'table' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400'}`}><List className="w-5 h-5" /></button>
                </div>

                {isManageMode && <button onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-4 rounded-2xl text-xs font-black uppercase shadow-xl transition-all active:scale-95">THÊM MỚI</button>}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Tìm tên thiết bị, vị trí..." className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none" />
            </div>

            <div className="flex gap-3">
                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none">
                    <option value="all">Tất cả danh mục</option>
                    {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                </select>
                <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className="px-5 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none">
                    <option value="all">Tất cả trạng thái</option>
                    <option value="available">Sẵn có</option>
                    <option value="inactive">Bảo trì</option>
                </select>
            </div>
        </div>
      </div>

      {/* Tools Display */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const qty = selectedQuantities[tool.id] || 0;
                const isSelected = qty > 0;
                const isAvailable = tool.status === 'active' && tool.available > 0;
                return (
                <Card key={tool.id} className={`hover:shadow-2xl transition-all p-0 border-2 overflow-hidden rounded-[2.5rem] ${isSelected ? 'border-indigo-500 ring-8 ring-indigo-50' : 'border-transparent bg-white shadow-lg'} ${!isManageMode && !isAvailable ? 'opacity-60 grayscale-[0.5]' : ''}`}>
                    <div className="h-56 bg-white flex items-center justify-center relative border-b">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4">
                        {tool.status === 'inactive' ? <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg">Bảo trì</span> : <span className={`text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg ${tool.available > 0 ? 'bg-emerald-500' : 'bg-gray-400'}`}>Sẵn có: {tool.available}</span>}
                      </div>
                    </div>
                    <div className="p-6 space-y-4">
                      <h3 className="font-black text-gray-900 text-lg line-clamp-2 h-14 leading-tight">{tool.name}</h3>
                      <div className="flex items-center justify-between text-[10px] text-gray-400 font-bold uppercase">
                          <span className="bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded">{tool.category}</span>
                          <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {tool.location || 'N/A'}</span>
                      </div>
                      {isManageMode ? (
                        <div className="flex gap-3 pt-4 border-t">
                           <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="flex-1 bg-white border-2 border-indigo-100 text-indigo-700 py-3 rounded-2xl text-[10px] font-black uppercase">Sửa</button>
                           <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-3 bg-white border-2 border-rose-100 text-rose-600 rounded-2xl"><Trash2 className="w-5 h-5" /></button>
                        </div>
                      ) : (
                        <div className="pt-2">
                           {!isSelected ? (
                             <button 
                                onClick={() => isAvailable && updateQuantity(tool.id, 1, tool.available)}
                                disabled={!isAvailable}
                                className="w-full py-3 bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all disabled:opacity-30 flex items-center justify-center gap-2"
                             >
                               <Plus className="w-4 h-4" /> CHỌN MƯỢN
                             </button>
                           ) : (
                             <div className="flex items-center justify-between bg-indigo-600 p-1.5 rounded-2xl text-white shadow-lg animate-zoom-in">
                                <button onClick={() => updateQuantity(tool.id, -1, tool.available)} className="p-2 hover:bg-white/20 rounded-xl transition-colors"><Minus className="w-4 h-4" /></button>
                                <div className="flex flex-col items-center">
                                    <span className="text-[10px] font-black uppercase tracking-tighter opacity-70 leading-none">Số lượng</span>
                                    <span className="text-sm font-black tabular-nums">{qty}</span>
                                </div>
                                <button onClick={() => updateQuantity(tool.id, 1, tool.available)} className="p-2 hover:bg-white/20 rounded-xl transition-colors"><Plus className="w-4 h-4" /></button>
                             </div>
                           )}
                        </div>
                      )}
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[3rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Hình</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Tên thiết bị</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400 text-center">Kho/Sẵn</th>
                    <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-10 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => {
                    const qty = selectedQuantities[tool.id] || 0;
                    return (
                        <tr key={tool.id} className="hover:bg-blue-50/30 transition-all">
                        <td className="px-10 py-6"><div className="w-16 h-16 rounded-2xl bg-white border-2 overflow-hidden flex items-center justify-center p-1"><ToolThumbnail src={tool.image} alt={tool.name} mode="table" /></div></td>
                        <td className="px-10 py-6 font-black text-gray-900">{tool.name}</td>
                        <td className="px-10 py-6 text-center text-sm font-black tabular-nums">{tool.available} / {tool.quantity}</td>
                        <td className="px-10 py-6">{tool.status === 'active' ? <span className="text-emerald-700 bg-emerald-50 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-emerald-100">Hoạt động</span> : <span className="text-rose-700 bg-rose-50 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-rose-100">Bảo trì</span>}</td>
                        <td className="px-10 py-6 text-right">
                            {isManageMode ? (
                                <div className="flex justify-end gap-2">
                                    <button onClick={() => handleEditTool(tool)} className="p-3 text-indigo-600 hover:bg-gray-100 rounded-2xl transition-colors"><Edit className="w-5 h-5"/></button>
                                    <button onClick={() => setToolToDelete(tool.id)} className="p-3 text-rose-600 hover:bg-gray-100 rounded-2xl transition-colors"><Trash2 className="w-5 h-5"/></button>
                                </div>
                            ) : (
                                <div className="flex justify-end items-center gap-3">
                                    {qty > 0 && (
                                        <div className="flex items-center bg-gray-100 rounded-xl p-1 border">
                                            <button onClick={() => updateQuantity(tool.id, -1, tool.available)} className="p-2 hover:bg-white rounded-lg text-gray-500"><Minus className="w-3.5 h-3.5"/></button>
                                            <span className="px-3 font-black text-xs tabular-nums">{qty}</span>
                                            <button onClick={() => updateQuantity(tool.id, 1, tool.available)} className="p-2 hover:bg-white rounded-lg text-gray-500"><Plus className="w-3.5 h-3.5"/></button>
                                        </div>
                                    )}
                                    <button 
                                        onClick={() => qty === 0 ? updateQuantity(tool.id, 1, tool.available) : null}
                                        disabled={tool.available === 0} 
                                        className={`p-4 rounded-2xl shadow-lg transition-all active:scale-90 ${qty > 0 ? 'bg-indigo-600 text-white' : 'bg-gray-50 text-indigo-600 border border-indigo-100 hover:bg-indigo-50'}`}
                                    >
                                        {qty > 0 ? <Check className="w-5 h-5"/> : <PackagePlus className="w-5 h-5"/>}
                                    </button>
                                </div>
                            )}
                        </td>
                        </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {/* Pagination */}
      <Card className="p-6 rounded-[3rem] shadow-xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
          <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">Hiển thị {Math.min(filteredTools.length, startIndex + 1)}-{Math.min(filteredTools.length, startIndex + pageSize)} trong {filteredTools.length} thiết bị</span>
          <div className="flex items-center gap-3">
              <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50"><ChevronLeft className="w-5 h-5" /></button>
              <span className="bg-indigo-50 text-indigo-600 px-4 py-2 rounded-lg text-sm font-black border border-indigo-100">{currentPage} / {totalPages}</span>
              <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50"><ChevronRight className="w-5 h-5" /></button>
          </div>
      </Card>

      {/* Floating Borrow Action Bar */}
      {!isManageMode && totalSelectedCount > 0 && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[80] w-[calc(100%-2rem)] max-w-2xl animate-fade-in-up">
            <div className="bg-slate-900/90 backdrop-blur-xl border border-white/20 p-4 md:p-6 rounded-[2.5rem] shadow-2xl flex items-center justify-between gap-4">
                <div className="flex items-center gap-4 pl-2">
                    <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white font-black shadow-lg shadow-blue-500/20 tabular-nums">
                        {totalSelectedCount}
                    </div>
                    <div>
                        <p className="text-white font-black text-sm md:text-base leading-none">Thiết bị được chọn</p>
                        <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest mt-2">Sẽ gửi yêu cầu mượn ngay</p>
                    </div>
                </div>

                <div className="flex items-center gap-2">
                    <button 
                        onClick={() => setSelectedQuantities({})}
                        className="px-4 py-3 text-gray-400 hover:text-white text-[10px] font-black uppercase tracking-widest transition-colors"
                    >
                        Hủy
                    </button>
                    <button 
                        onClick={handleBulkBorrow}
                        disabled={isBorrowing}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-[0.2em] shadow-xl shadow-blue-600/20 flex items-center gap-2 transition-all active:scale-95 disabled:opacity-50"
                    >
                        {isBorrowing ? <Loader2 className="w-4 h-4 animate-spin" /> : <><Send className="w-4 h-4" /> XÁC NHẬN MƯỢN</>}
                    </button>
                </div>
            </div>
          </div>
      )}

      {/* Admin Modals */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto animate-zoom-in my-auto no-scrollbar">
            <div className="flex justify-between items-center p-10 border-b sticky top-0 bg-white z-10">
              <h3 className="text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none">{isEditing ? 'Cập nhật' : 'Thêm mới'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-gray-100 rounded-3xl transition-colors"><X className="w-6 h-6 text-gray-400"/></button>
            </div>
            <div className="p-10 space-y-8 bg-gray-50/50">
              <div className="space-y-6 bg-white p-8 rounded-[3rem] border shadow-sm">
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Tên thiết bị</label>
                  <input type="text" placeholder="Tên thiết bị..." value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"/>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Danh mục</label>
                  <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 appearance-none cursor-pointer">
                    <option>Thiết bị cầm tay</option><option>Máy móc lớn</option><option>Đồ bảo hộ</option><option>Vật tư tiêu hao</option>
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Tổng số lượng</label>
                    <input type="number" placeholder="Tổng số" value={formData.quantity} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Số lượng sẵn có</label>
                    <input type="number" placeholder="Sẵn có" value={formData.available} onChange={e => setFormData({...formData, available: parseInt(e.target.value) || 0})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Đường dẫn hình ảnh</label>
                  <input type="text" placeholder="Link hình ảnh..." value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-500/10"/>
                </div>
              </div>
              <button onClick={handleSaveTool} className="w-full py-6 bg-indigo-600 text-white font-black rounded-[2rem] shadow-2xl uppercase text-xs flex items-center justify-center gap-3 transition-all active:scale-95 shadow-indigo-200"><Save className="w-6 h-6"/> {isEditing ? 'LƯU THAY ĐỔI' : 'XÁC NHẬN THÊM'}</button>
            </div>
          </div>
        </div>
      )}

      {toolToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2.5rem] shadow-2xl rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-12 h-12"/></div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xóa tài sản?</h3>
              <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80 leading-relaxed px-4">Dữ liệu sẽ bị xóa vĩnh viễn khỏi hệ thống.</p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t">
              <button onClick={handleDeleteTool} className="w-full py-5 bg-rose-600 text-white font-black rounded-[2rem] text-xs uppercase shadow-2xl shadow-rose-200 transition-all active:scale-95">XÁC NHẬN XÓA</button>
              <button onClick={() => setToolToDelete(null)} className="w-full py-5 bg-white text-gray-400 font-black rounded-[2rem] border-2 text-xs uppercase active:scale-95">HỦY BỎ</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, Loader2, PackagePlus, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, ChevronDown, ChevronsLeft, ChevronsRight,
  CheckCircle2, Trash2, Check, ArrowRight, Layers, Boxes, Info
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: 'Thiết bị cầm tay',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className="flex flex-col items-center justify-center bg-gray-100 w-full h-full rounded-xl">
        <Wrench className={`${mode === 'grid' ? 'w-10 h-10 text-gray-300' : 'w-6 h-6 text-gray-400'}`} />
      </div>
    );
  }

  return (
    <div className={`relative w-full h-full flex items-center justify-center bg-white rounded-xl`}>
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedQuantities, setSelectedQuantities] = useState<Record<string, number>>({});
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data, error } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (tool: Tool) => {
    if (isManageMode) return;
    const isAvailable = tool.status === 'active' && tool.available > 0;
    if (!isAvailable && !selectedQuantities[tool.id]) return;

    setSelectedQuantities(prev => {
        const current = prev[tool.id] || 0;
        if (current > 0) {
            const next = { ...prev };
            delete next[tool.id];
            return next;
        } else {
            return { ...prev, [tool.id]: 1 };
        }
    });
  };

  const updateQuantity = (id: string, delta: number, max: number, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedQuantities(prev => {
        const current = prev[id] || 0;
        const next = Math.max(0, Math.min(max, current + delta));
        const newQuantities = { ...prev };
        if (next === 0) {
            delete newQuantities[id];
        } else {
            newQuantities[id] = next;
        }
        return newQuantities;
    });
  };

  const handleBulkBorrow = async () => {
    const selectedToolIds = Object.keys(selectedQuantities);
    if (selectedToolIds.length === 0) return;
    setIsBorrowing(true);
    try {
      for (const toolId of selectedToolIds) {
        const tool = tools.find(t => t.id === toolId);
        const qty = selectedQuantities[toolId];

        if (!tool || tool.available < qty) continue;

        const requestsToInsert = Array.from({ length: qty }).map(() => ({
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        }));

        const { error } = await supabase.from('requests').insert(requestsToInsert);
        if (error) throw error;
      }

      setMessage(`Gửi thành công yêu cầu mượn ${Object.values(selectedQuantities).reduce((a, b) => a + b, 0)} thiết bị!`);
      setSelectedQuantities({});
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Đã cập nhật' : 'Đã thêm mới');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const handleDeleteTool = async () => {
    if (!toolToDelete) return;
    try {
      await supabase.from('tools').delete().eq('id', toolToDelete);
      await fetchTools(); setToolToDelete(null);
      setMessage('Đã xóa'); setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const totalSelectedCount = Object.values(selectedQuantities).reduce((sum, q) => sum + q, 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* Header & Filters */}
      <div className="flex flex-col gap-4 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.8rem] shadow-xl shadow-blue-100 text-white"><Wrench className="w-8 h-8" /></div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none uppercase">Kho thiết bị</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2 opacity-70">Quản lý & mượn đồ tập trung</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div className="bg-emerald-600 text-white px-5 py-3 rounded-2xl flex items-center gap-2 animate-fade-in-up text-[11px] font-black uppercase shadow-xl shadow-emerald-100 tracking-widest">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
                        <button onClick={() => {setIsManageMode(true); setSelectedQuantities({});}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-blue-600 shadow-lg' : 'text-gray-500'}`}>QUẢN LÝ</button>
                        <button onClick={() => {setIsManageMode(false); setSelectedQuantities({});}} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-blue-600 shadow-lg' : 'text-gray-500'}`}>MƯỢN ĐỒ</button>
                    </div>
                )}

                <div className="flex items-center gap-2 bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl ${viewMode === 'grid' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}><LayoutGrid className="w-5 h-5" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl ${viewMode === 'table' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}><List className="w-5 h-5" /></button>
                </div>

                {isManageMode && (
                    <button 
                        onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} 
                        className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 transition-all active:scale-95 flex items-center gap-2"
                    >
                        <Plus className="w-4 h-4" /> THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-6 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600 transition-colors" />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Tìm tên thiết bị, vị trí..." className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all" />
            </div>

            <div className="flex gap-3">
                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="px-6 py-4 bg-gray-50 border-none rounded-2xl text-[11px] font-black uppercase tracking-widest outline-none cursor-pointer">
                    <option value="all">Tất cả danh mục</option>
                    {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                </select>
                <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className="px-6 py-4 bg-gray-50 border-none rounded-2xl text-[11px] font-black uppercase tracking-widest outline-none cursor-pointer">
                    <option value="all">Trạng thái</option>
                    <option value="available">Sẵn mượn</option>
                    <option value="inactive">Đang sửa</option>
                </select>
            </div>
        </div>
      </div>

      {/* Tools Display */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool) => {
                const qty = selectedQuantities[tool.id] || 0;
                const isSelected = qty > 0;
                const isAvailable = tool.status === 'active' && tool.available > 0;
                return (
                <Card 
                    key={tool.id} 
                    onClick={() => toggleSelection(tool)}
                    className={`cursor-pointer group hover:shadow-2xl transition-all p-0 border-4 overflow-hidden rounded-[2.8rem] ${isSelected ? 'border-blue-600 ring-8 ring-blue-50 bg-blue-50/20' : 'border-transparent bg-white shadow-xl'} ${!isManageMode && !isAvailable && !isSelected ? 'opacity-50 grayscale pointer-events-none' : ''}`}
                >
                    <div className="h-60 bg-white flex items-center justify-center relative border-b border-gray-50">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-5 right-5 flex flex-col gap-2 items-end">
                        {tool.status === 'inactive' ? (
                            <span className="bg-rose-500 text-white text-[9px] font-black uppercase px-4 py-2 rounded-xl shadow-lg">Đang sửa</span>
                        ) : (
                            <span className={`text-white text-[9px] font-black uppercase px-4 py-2 rounded-xl shadow-lg border-2 border-white ${tool.available > 0 ? 'bg-emerald-500' : 'bg-gray-400'}`}>
                                {tool.available > 0 ? `Sẵn có: ${tool.available}` : 'Hết đồ'}
                            </span>
                        )}
                        {isSelected && <div className="bg-blue-600 text-white p-2 rounded-full shadow-xl animate-bounce"><Check className="w-4 h-4" /></div>}
                      </div>
                    </div>
                    <div className="p-8 space-y-5">
                      <div className="space-y-1">
                        <span className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{tool.category}</span>
                        <h3 className="font-black text-gray-900 text-lg line-clamp-2 h-14 leading-tight group-hover:text-blue-700 transition-colors uppercase tracking-tight">{tool.name}</h3>
                      </div>

                      <div className="flex items-center justify-between text-[10px] text-gray-400 font-bold uppercase tracking-widest bg-gray-50 p-3 rounded-2xl border border-gray-100">
                          <span className="flex items-center gap-1.5"><MapPin className="w-3.5 h-3.5 text-blue-400" /> {tool.location || 'KHO CHUNG'}</span>
                          <span className="font-black text-gray-900">ID: {tool.id.slice(0, 5)}</span>
                      </div>

                      {isManageMode ? (
                        <div className="flex gap-3 pt-2">
                           <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="flex-1 bg-gray-900 hover:bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] shadow-lg transition-all active:scale-95">CHỈNH SỬA</button>
                           <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-4 bg-rose-50 border border-rose-100 text-rose-600 rounded-2xl hover:bg-rose-600 hover:text-white transition-all"><Trash2 className="w-5 h-5" /></button>
                        </div>
                      ) : (
                        <div className="pt-2">
                           {isSelected && (
                             <div className="flex items-center justify-between bg-blue-600 p-2 rounded-[1.5rem] text-white shadow-xl animate-zoom-in border-4 border-white">
                                <button onClick={(e) => updateQuantity(tool.id, -1, tool.available, e)} className="p-3 hover:bg-white/20 rounded-xl transition-colors"><Minus className="w-4 h-4" /></button>
                                <div className="flex flex-col items-center">
                                    <span className="text-[9px] font-black uppercase tracking-widest opacity-70">Số lượng mượn</span>
                                    <span className="text-xl font-black tabular-nums">{qty}</span>
                                </div>
                                <button onClick={(e) => updateQuantity(tool.id, 1, tool.available, e)} className="p-3 hover:bg-white/20 rounded-xl transition-colors"><Plus className="w-4 h-4" /></button>
                             </div>
                           )}
                        </div>
                      )}
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[3rem] overflow-hidden border-none shadow-2xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-10 py-8 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Hình</th>
                    <th className="px-10 py-8 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Tên thiết bị</th>
                    <th className="px-10 py-8 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Danh mục</th>
                    <th className="px-10 py-8 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400 text-center">Sẵn / Tổng</th>
                    <th className="px-10 py-8 text-center text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Trạng thái</th>
                    <th className="px-10 py-8 text-right text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool) => {
                    const qty = selectedQuantities[tool.id] || 0;
                    const isSelected = qty > 0;
                    return (
                        <tr 
                            key={tool.id} 
                            onClick={() => toggleSelection(tool)}
                            className={`cursor-pointer transition-all ${isSelected ? 'bg-blue-50/50' : 'hover:bg-gray-50'}`}
                        >
                            <td className="px-10 py-6">
                                <div className={`w-16 h-16 rounded-2xl bg-white border-2 overflow-hidden flex items-center justify-center p-1 shadow-sm transition-all ${isSelected ? 'border-blue-600' : 'border-gray-100'}`}>
                                    <ToolThumbnail src={tool.image} alt={tool.name} mode="table" />
                                </div>
                            </td>
                            <td className="px-10 py-6">
                                <div className={`font-black uppercase text-sm tracking-tight ${isSelected ? 'text-blue-700' : 'text-gray-900'}`}>{tool.name}</div>
                                <div className="text-[10px] text-gray-400 font-bold uppercase mt-1 flex items-center gap-1"><MapPin className="w-3 h-3" /> {tool.location || 'KHO'}</div>
                            </td>
                            <td className="px-10 py-6">
                                <span className="bg-gray-100 text-gray-500 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest">{tool.category}</span>
                            </td>
                            <td className="px-10 py-6 text-center text-sm font-black tabular-nums">
                                <span className={tool.available > 0 ? 'text-emerald-600' : 'text-rose-500'}>{tool.available}</span>
                                <span className="text-gray-200 mx-2">/</span>
                                <span className="text-gray-400">{tool.quantity}</span>
                            </td>
                            <td className="px-10 py-6 text-center">
                                {tool.status === 'active' ? (
                                    <span className="text-emerald-700 bg-emerald-50 px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border-2 border-emerald-100">Sẵn sàng</span>
                                ) : (
                                    <span className="text-rose-700 bg-rose-50 px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border-2 border-rose-100">Bảo trì</span>
                                )}
                            </td>
                            <td className="px-10 py-6 text-right">
                                <div className="flex justify-end items-center gap-4">
                                    {isManageMode ? (
                                        <div className="flex gap-2">
                                            <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="p-3 bg-white text-gray-900 border border-gray-200 hover:bg-gray-900 hover:text-white rounded-2xl transition-all"><Edit className="w-5 h-5"/></button>
                                            <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-3 bg-white text-rose-600 border border-rose-100 hover:bg-rose-600 hover:text-white rounded-2xl transition-all"><Trash2 className="w-5 h-5"/></button>
                                        </div>
                                    ) : (
                                        <>
                                            {isSelected && (
                                                <div className="flex items-center bg-blue-600 rounded-2xl p-1 shadow-lg border-2 border-white">
                                                    <button onClick={(e) => updateQuantity(tool.id, -1, tool.available, e)} className="p-2 hover:bg-white/20 rounded-xl text-white"><Minus className="w-4 h-4"/></button>
                                                    <span className="px-4 font-black text-sm tabular-nums text-white">{qty}</span>
                                                    <button onClick={(e) => updateQuantity(tool.id, 1, tool.available, e)} className="p-2 hover:bg-white/20 rounded-xl text-white"><Plus className="w-4 h-4"/></button>
                                                </div>
                                            )}
                                            <div className={`p-4 rounded-2xl transition-all ${isSelected ? 'bg-emerald-500 text-white' : 'bg-gray-100 text-gray-400 group-hover:bg-blue-600 group-hover:text-white'}`}>
                                                {isSelected ? <Check className="w-5 h-5" /> : <Plus className="w-5 h-5" />}
                                            </div>
                                        </>
                                    )}
                                </div>
                            </td>
                        </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {/* Pagination */}
      <Card className="p-8 rounded-[3rem] shadow-xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-6 px-12">
          <div className="flex items-center gap-4">
            <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.2em]">Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredTools.length, startIndex + 1)}-{Math.min(filteredTools.length, startIndex + pageSize)}</span> của {filteredTools.length}</span>
