          <div className="flex items-center gap-4">
              <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-4 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"><ChevronLeft className="w-6 h-6" /></button>
              <div className="flex items-center gap-2">
                 {Array.from({length: totalPages}, (_, i) => i + 1).filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1).map((p, idx, arr) => (
                    <React.Fragment key={p}>
                        {idx > 0 && arr[idx-1] !== p - 1 && <span className="text-gray-300 font-black">...</span>}
                        <button 
                            onClick={() => handlePageChange(p)}
                            className={`w-12 h-12 rounded-2xl font-black text-sm transition-all border-2 ${currentPage === p ? 'bg-blue-600 text-white border-blue-600 shadow-lg scale-110' : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'}`}
                        >
                            {p}
                        </button>
                    </React.Fragment>
                 ))}
              </div>
              <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-4 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"><ChevronRight className="w-6 h-6" /></button>
          </div>
      </Card>

      {/* Floating Borrow Action Bar */}
      {!isManageMode && totalSelectedCount > 0 && (
          <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[80] w-[calc(100%-3rem)] max-w-2xl animate-fade-in-up">
            <div className="bg-gray-900/95 backdrop-blur-xl border border-white/10 p-5 md:p-8 rounded-[3.5rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.5)] flex flex-col sm:flex-row items-center justify-between gap-6">
                <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-blue-600 rounded-[2rem] flex items-center justify-center text-white font-black text-xl shadow-2xl shadow-blue-500/40 border-4 border-white/20 tabular-nums">
                        {totalSelectedCount}
                    </div>
                    <div>
                        <p className="text-white font-black text-lg leading-none uppercase tracking-tight">Thiết bị đang mượn</p>
                        <p className="text-blue-400 text-[10px] font-black uppercase tracking-[0.2em] mt-2 opacity-80">Sẵn sàng gửi yêu cầu phê duyệt</p>
                    </div>
                </div>

                <div className="flex items-center gap-4 w-full sm:w-auto">
                    <button 
                        onClick={() => setSelectedQuantities({})}
                        className="flex-1 sm:flex-none px-6 py-4 text-gray-400 hover:text-white text-[11px] font-black uppercase tracking-widest transition-colors"
                    >
                        HỦY BỎ
                    </button>
                    <button 
                        onClick={handleBulkBorrow}
                        disabled={isBorrowing}
                        className="flex-1 sm:flex-none bg-blue-600 hover:bg-blue-700 text-white px-10 py-5 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-blue-600/30 flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50"
                    >
                        {isBorrowing ? <Loader2 className="w-5 h-5 animate-spin" /> : <><Send className="w-5 h-5" /> GỬI YÊU CẦU</>}
                    </button>
                </div>
            </div>
          </div>
      )}

      {/* Admin Modals - IMPROVED UI */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-2xl max-h-[95vh] overflow-y-auto animate-zoom-in my-auto no-scrollbar border border-white/20">
            <div className="flex justify-between items-center px-12 py-10 border-b sticky top-0 bg-white z-20">
              <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl">
                      {isEditing ? <Edit className="w-6 h-6"/> : <Plus className="w-6 h-6"/>}
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none">
                    {isEditing ? 'Cập nhật thiết bị' : 'Thêm thiết bị mới'}
                  </h3>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-gray-100 rounded-[1.5rem] transition-colors group">
                <X className="w-8 h-8 text-gray-400 group-hover:text-gray-900"/>
              </button>
            </div>

            <div className="p-12 space-y-10 bg-gray-50/30">
              {/* Form Content */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-6 flex flex-col">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-2">Thông tin cơ bản</label>
                    <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-6">
                        <div>
                            <input 
                                type="text" 
                                placeholder="Tên thiết bị (VD: Máy khoan bê tông)" 
                                value={formData.name} 
                                onChange={e => setFormData({...formData, name: e.target.value})} 
                                className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all"
                            />
                        </div>
                        <div>
                            <input 
                                list="category-suggestions"
                                type="text" 
                                placeholder="Danh mục (Tự nhập hoặc chọn bên dưới)" 
                                value={formData.category} 
                                onChange={e => setFormData({...formData, category: e.target.value})} 
                                className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all"
                            />
                            <datalist id="category-suggestions">
