                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-2">Mô tả thiết bị</label>
                    <textarea 
                        placeholder="Thông tin chi tiết, tình trạng máy, lưu ý khi sử dụng..." 
                        value={formData.description} 
                        onChange={e => setFormData({...formData, description: e.target.value})} 
                        className="w-full px-6 py-4 bg-white border border-gray-100 rounded-[2.5rem] text-sm font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all h-32 resize-none shadow-sm"
                    />
                  </div>
                </div>

                <div className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-2">Quản lý kho số lượng</label>
                    <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
                        <div className="space-y-3">
                            <div className="flex justify-between items-center px-2">
                                <span className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Tổng nhập kho</span>
                                <span className="text-xl font-black text-blue-600 tabular-nums">{formData.quantity}</span>
                            </div>
                            <div className="flex items-center gap-3">
                                <button onClick={() => setFormData({...formData, quantity: Math.max(0, formData.quantity - 1)})} className="p-4 bg-gray-50 rounded-2xl text-gray-400 hover:bg-gray-100 hover:text-gray-900 transition-colors"><Minus className="w-5 h-5"/></button>
                                <input 
                                    type="number" 
                                    value={formData.quantity} 
                                    onChange={e => setFormData({...formData, quantity: parseInt(e.target.value) || 0})} 
                                    className="flex-1 px-4 py-4 bg-gray-50 border-none rounded-2xl text-center text-lg font-black focus:ring-4 focus:ring-blue-600/10 outline-none"
                                />
                                <button onClick={() => setFormData({...formData, quantity: formData.quantity + 1})} className="p-4 bg-gray-50 rounded-2xl text-gray-400 hover:bg-gray-100 hover:text-gray-900 transition-colors"><Plus className="w-5 h-5"/></button>
                            </div>
                        </div>

                        <div className="space-y-3">
                            <div className="flex justify-between items-center px-2">
                                <span className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Đang sẵn mượn</span>
                                <span className="text-xl font-black text-emerald-600 tabular-nums">{formData.available}</span>
                            </div>
                            <div className="flex items-center gap-3">
                                <button onClick={() => setFormData({...formData, available: Math.max(0, formData.available - 1)})} className="p-4 bg-gray-50 rounded-2xl text-gray-400 hover:bg-gray-100 hover:text-gray-900 transition-colors"><Minus className="w-5 h-5"/></button>
                                <input 
                                    type="number" 
                                    value={formData.available} 
                                    onChange={e => setFormData({...formData, available: parseInt(e.target.value) || 0})} 
                                    className="flex-1 px-4 py-4 bg-gray-50 border-none rounded-2xl text-center text-lg font-black focus:ring-4 focus:ring-blue-600/10 outline-none"
                                />
                                <button onClick={() => setFormData({...formData, available: formData.available + 1})} className="p-4 bg-gray-50 rounded-2xl text-gray-400 hover:bg-gray-100 hover:text-gray-900 transition-colors"><Plus className="w-5 h-5"/></button>
                            </div>
                            <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest px-2 italic text-center">* Đảm bảo 'Sẵn mượn' không vượt quá 'Tổng nhập'</p>
                        </div>
                    </div>
                  </div>

                  <div>
                     <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-2">Hình ảnh thiết bị</label>
                     <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-4">
                        <input 
                            type="text" 
                            placeholder="Dán link ảnh tại đây (URL)..." 
                            value={formData.image} 
                            onChange={e => setFormData({...formData, image: e.target.value})} 
                            className="w-full px-6 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all"
                        />
                        <div className="h-40 rounded-3xl bg-gray-50 border-2 border-dashed border-gray-100 flex items-center justify-center overflow-hidden">
                            {formData.image ? (
                                <img src={formData.image} alt="Preview" className="h-full w-full object-contain p-4" onError={(e) => (e.currentTarget.src = 'https://via.placeholder.com/200?text=Loi+Anh')} />
                            ) : (
                                <div className="text-center">
                                    <ImageIcon className="w-10 h-10 text-gray-200 mx-auto mb-2" />
                                    <p className="text-[9px] font-black text-gray-300 uppercase">Xem trước hình ảnh</p>
                                </div>
                            )}
                        </div>
                     </div>
                  </div>
                </div>
              </div>

              <div className="bg-blue-50 p-6 rounded-[2.5rem] border border-blue-100 flex items-center gap-4">
                 <div className="p-3 bg-blue-600 rounded-2xl text-white shadow-lg"><Boxes className="w-6 h-6"/></div>
                 <div className="flex-1">
                    <label className="block text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1 ml-1">Trạng thái vận hành</label>
                    <select 
                        value={formData.status} 
                        onChange={e => setFormData({...formData, status: e.target.value as any})} 
                        className="w-full bg-transparent border-none text-sm font-black text-gray-900 outline-none p-0 cursor-pointer"
                    >
                        <option value="active">🟢 ĐANG HOẠT ĐỘNG (Sẵn sàng cấp phát)</option>
                        <option value="inactive">🔴 ĐANG BẢO TRÌ (Tạm dừng mượn)</option>
                    </select>
                 </div>
              </div>

              <button 
                onClick={handleSaveTool} 
                className="w-full py-7 bg-gray-900 hover:bg-black text-white font-black rounded-[2.5rem] shadow-2xl uppercase text-[11px] flex items-center justify-center gap-4 transition-all active:scale-95 shadow-gray-200 tracking-[0.3em]"
              >
                <Save className="w-6 h-6"/> 
                {isEditing ? 'LƯU CẬP NHẬT TÀI SẢN' : 'HOÀN TẤT THÊM TÀI SẢN'}
              </button>
            </div>
          </div>
        </div>
      )}

      {toolToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2.5rem] shadow-2xl rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-12 h-12"/></div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xóa tài sản?</h3>
              <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80 leading-relaxed px-4">Dữ liệu thiết bị này sẽ bị gỡ bỏ vĩnh viễn khỏi hệ thống.</p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button onClick={handleDeleteTool} className="w-full py-5 bg-rose-600 text-white font-black rounded-[2rem] text-[10px] uppercase tracking-widest shadow-2xl shadow-rose-200 transition-all active:scale-95">XÁC NHẬN XÓA</button>
              <button onClick={() => setToolToDelete(null)} className="w-full py-5 bg-white text-gray-400 font-black rounded-[2rem] border-2 border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">HỦY BỎ</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, ShoppingBag, Send, Loader2, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, Trash2, Check, Boxes, Info, Tag, Hash, Archive
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: '',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const isValidUrl = src && typeof src === 'string' && src.trim().length > 0 && (src.startsWith('http') || src.startsWith('data:'));

  if (error || !isValidUrl) {
    return (
      <div className="flex flex-col items-center justify-center bg-gray-50 w-full h-full rounded-2xl border-2 border-dashed border-gray-100">
        <Wrench className={`${mode === 'grid' ? 'w-10 h-10 text-gray-200' : 'w-5 h-5 text-gray-300'}`} />
      </div>
    );
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-white rounded-xl">
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedQuantities, setSelectedQuantities] = useState<Record<string, number>>({});
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (tool: Tool) => {
    if (isManageMode) return;
    const isAvailable = tool.status === 'active' && tool.available > 0;
    if (!isAvailable && !selectedQuantities[tool.id]) return;

    setSelectedQuantities(prev => {
        const current = prev[tool.id] || 0;
        if (current > 0) {
            const next = { ...prev };
            delete next[tool.id];
            return next;
        } else {
            return { ...prev, [tool.id]: 1 };
        }
    });
  };

  const updateQuantity = (id: string, delta: number, max: number, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedQuantities(prev => {
        const current = prev[id] || 0;
        const next = Math.max(0, Math.min(max, current + delta));
        const newQuantities = { ...prev };
        if (next === 0) delete newQuantities[id];
        else newQuantities[id] = next;
        return newQuantities;
    });
  };

  const handleBulkBorrow = async () => {
    const selectedToolIds = Object.keys(selectedQuantities);
    if (selectedToolIds.length === 0) return;
    setIsBorrowing(true);
    try {
      for (const toolId of selectedToolIds) {
        const tool = tools.find(t => t.id === toolId);
        const qty = selectedQuantities[toolId];
        if (!tool || tool.available < qty) continue;

        const requestsToInsert = Array.from({ length: qty }).map(() => ({
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        }));

        const { error } = await supabase.from('requests').insert(requestsToInsert);
        if (error) throw error;
      }
      setMessage(`Gửi thành công yêu cầu mượn đồ!`);
      setSelectedQuantities({});
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Đã cập nhật' : 'Đã thêm mới');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const totalSelectedCount = Object.values(selectedQuantities).reduce((sum, q) => sum + q, 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* Search & Header */}
      <div className="flex flex-col gap-5 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-[1.8rem] shadow-xl shadow-blue-100 text-white"><Wrench className="w-8 h-8" /></div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none uppercase">Kho thiết bị</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2 opacity-70">Quản lý & mượn đồ tập trung</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div className="bg-emerald-600 text-white px-5 py-3 rounded-2xl flex items-center gap-2 animate-fade-in-up text-[10px] font-black uppercase shadow-lg shadow-emerald-100 tracking-widest">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
