import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  History, Search, Calendar, Filter, X, 
  User as UserIcon, ShieldCheck, ChevronDown, 
  SlidersHorizontal, ChevronLeft, ChevronRight, 
  Loader2, RefreshCw, AlertCircle, ChevronsLeft, ChevronsRight,
  Undo2, CheckCircle2, AlertTriangle
} from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

// Mở rộng interface local để hứng thêm field người xử lý từ DB
interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | '7days' | '30days' | 'thisMonth';

const ITEMS_PER_PAGE = 20;

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`fixed bottom-10 right-10 z-[100] ${type === 'success' ? 'bg-emerald-600' : 'bg-rose-600'} text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up border border-white/20 backdrop-blur-md`}>
      {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
      <p className="text-xs font-black uppercase tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-2 hover:bg-white/20 p-1 rounded-full"><X className="w-4 h-4"/></button>
    </div>
  );
};

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reBorrowingId, setReBorrowingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  // State phân trang
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async (silent = false) => {
    if (!user) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    setError(null);

    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
      }

      if (statusFilter !== 'all') {
        query = query.eq('status', statusFilter);
      }

      if (startDate) {
        query = query.gte('borrow_date', `${startDate}T00:00:00`);
      }
      if (endDate) {
        query = query.lte('borrow_date', `${endDate}T23:59:59`);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      if (data) {
        setLogs(data as ExtendedBorrowRequest[]);
      }
    } catch (err: any) {
      console.error("Fetch history error:", err);
      setError("Không thể tải dữ liệu lịch sử. Vui lòng thử lại.");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, [user.id, startDate, endDate, statusFilter, user.role]);

  // Reset trang về 1 khi bất kỳ bộ lọc nào thay đổi
  useEffect(() => {
    setCurrentPage(1);
  }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Admin';
    if (req.status === 'rejected') return req.rejected_by || 'Admin';
    return '-';
  };

  const handleReBorrow = async (log: ExtendedBorrowRequest) => {
    setReBorrowingId(log.id);
    try {
      const { error } = await supabase.from('requests').insert([{
        user_id: user.id,
        user_name: user.name,
        employee_id: user.employeeCode,
        tool_id: log.tool_id,
        tool_name: log.tool_name,
        borrow_date: new Date().toISOString(),
        status: 'pending'
      }]);

      if (error) throw error;

      setToast({ message: "Đã gửi yêu cầu mượn lại thành công!", type: 'success' });
      // Gửi event để cập nhật badge ở Header/Sidebar
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      // Reload history if needed, though the new record will appear at the top
      fetchHistory(true);
    } catch (err: any) {
      setToast({ message: "Lỗi: " + err.message, type: 'error' });
    } finally {
      setReBorrowingId(null);
    }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.trim().toLowerCase();
      const handlerLower = handlerFilter.trim().toLowerCase();

      const matchesText = !searchLower || (
        log.user_name?.toLowerCase().includes(searchLower) ||
        log.employee_id?.toLowerCase().includes(searchLower) ||
        log.tool_name?.toLowerCase().includes(searchLower)
      );

      const currentHandler = getHandlerName(log).toLowerCase();
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);

      return matchesText && matchesHandler;
    });
  }, [logs, searchText, handlerFilter]);

  // Logic phân trang cho Client-side
  const totalPages = Math.max(1, Math.ceil(filteredLogs.length / ITEMS_PER_PAGE));

  const currentLogs = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [filteredLogs, currentPage]);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'today':
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'custom':
            return; 
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setHandlerFilter('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
    setCurrentPage(1);
  };

  const activeFiltersCount = [
    searchText.trim(), 
    handlerFilter.trim(), 
    startDate, 
    endDate, 
    statusFilter !== 'all'
  ].filter(Boolean).length;

  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;

  return (
    <div className="space-y-6 animate-fade-in pb-10">
       {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

       <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-purple-600 rounded-[1.5rem] shadow-xl shadow-purple-100 text-white">
                    <History className="w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none">Lịch sử hoạt động</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        {user.role === 'admin' ? 'Theo dõi toàn bộ lịch sử mượn trả hệ thống' : 'Theo dõi lịch sử mượn trả cá nhân'}
                    </p>
                </div>
            </div>
            <button 
              onClick={() => fetchHistory(true)} 
              className="flex items-center gap-2 px-6 py-3 bg-gray-50 hover:bg-gray-100 text-gray-600 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border border-gray-200"
            >
              {isRefreshing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RefreshCw className="w-4 h-4"/>}
              Làm mới
            </button>
       </div>

       <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[3rem] bg-white">
            <div className="p-8 space-y-6 bg-white">
                <div className="flex items-center justify-between">
                    <h3 className="text-[10px] font-black text-gray-400 flex items-center gap-2 uppercase tracking-[0.2em]">
                        <SlidersHorizontal className="w-4 h-4 text-purple-600" /> Bộ lọc tìm kiếm
                    </h3>
                    {activeFiltersCount > 0 && (
                        <button 
                            onClick={clearFilters}
                            className="text-[10px] text-rose-600 hover:text-rose-800 font-black uppercase tracking-widest flex items-center gap-1 hover:underline"
                        >
                            <X className="w-3.5 h-3.5" /> Xóa {activeFiltersCount} bộ lọc
                        </button>
                    )}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    <div className="lg:col-span-5 space-y-4 border-r border-gray-100 pr-0 lg:pr-8">
                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Khoảng thời gian</label>
                        <div className="flex flex-wrap gap-2 mb-3">
                             {[{id: 'today', l: 'Hôm nay'}, {id: '7days', l: '7 ngày'}, {id: '30days', l: '30 ngày'}, {id: 'thisMonth', l: 'Tháng này'}].map((btn) => (
                                <button
                                    key={btn.id}
                                    onClick={() => handleQuickDate(btn.id as QuickDateOption)}
                                    className={`px-4 py-2 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all border-2 ${
                                        quickDate === btn.id 
                                        ? 'bg-purple-50 text-purple-700 border-purple-200 shadow-md transform scale-105' 
                                        : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'
                                    }`}
                                >
                                    {btn.l}
                                </button>
                             ))}
                        </div>
                        <div className="flex items-center gap-3">
                            <div className="relative flex-1 group">
                                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                <input 
                                    type="date" 
                                    value={startDate}
                                    onChange={(e) => handleManualDateChange('start', e.target.value)}
                                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                />
                            </div>
                            <span className="text-gray-300 font-black">-</span>
                            <div className="relative flex-1 group">
                                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                <input 
                                    type="date" 
                                    value={endDate}
                                    onChange={(e) => handleManualDateChange('end', e.target.value)}
                                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="lg:col-span-7 space-y-4">
                         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Từ khóa chung</label>
                                <div className="relative group">
                                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                    <input 
                                        type="text" 
                                        value={searchText}
                                        onChange={(e) => setSearchText(e.target.value)}
                                        placeholder="Tên, mã NV, thiết bị..." 
                                        className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                    />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Trạng thái đơn</label>
                                <div className="relative group">
                                    <select
                                        value={statusFilter}
                                        onChange={(e) => setStatusFilter(e.target.value)}
                                        className="w-full pl-5 pr-10 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900 appearance-none cursor-pointer"
                                    >
                                        <option value="all">Tất cả trạng thái</option>
                                        <option value="pending">⏳ Chờ duyệt</option>
                                        <option value="approved">✅ Đang mượn</option>
                                        <option value="returned">↩️ Đã trả</option>
                                        <option value="rejected">❌ Đã từ chối</option>
                                    </select>
                                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none group-focus-within:text-purple-600" />
                                </div>
                            </div>
                         </div>

                         <div className="space-y-2">
                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Người xử lý (Admin)</label>
                            <div className="relative group">
                                <ShieldCheck className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-purple-600" />
                                <input 
                                    type="text" 
                                    value={handlerFilter}
                                    onChange={(e) => setHandlerFilter(e.target.value)}
                                    placeholder="Tìm người duyệt yêu cầu..." 
                                    className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-sm font-bold focus:ring-4 focus:ring-purple-500/10 outline-none transition-all text-gray-900"
                                />
                            </div>
                         </div>
                    </div>
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 border-b border-gray-100 shadow-sm">
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Người mượn</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Thiết bị</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Ngày mượn</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Ngày trả</th>
                            <th className="px-10 py-6 text-[10px] font-black uppercase tracking-widest text-gray-400">Người xử lý</th>
                            <th className="px-10 py-6 text-center text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                            <th className="px-10 py-6 text-right text-[10px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 bg-white">
                        {loading ? (
                            <tr><td colSpan={7} className="px-10 py-32 text-center"><div className="flex flex-col items-center gap-4"><Loader2 className="w-12 h-12 animate-spin text-purple-600 opacity-20" /><p className="text-sm font-black uppercase tracking-widest text-gray-300">Đang tải lịch sử...</p></div></td></tr>
                        ) : error ? (
                             <tr><td colSpan={7} className="px-10 py-32 text-center"><div className="flex flex-col items-center gap-4 text-rose-500"><AlertCircle className="w-12 h-12" /><p className="text-sm font-black uppercase tracking-widest">{error}</p><button onClick={() => fetchHistory()} className="px-6 py-2 bg-rose-50 rounded-xl text-xs font-black uppercase tracking-widest border border-rose-100">Thử lại</button></div></td></tr>
                        ) : currentLogs.length === 0 ? (
                            <tr><td colSpan={7} className="px-10 py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không có dữ liệu phù hợp</td></tr>
                        ) : (
                            currentLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-purple-50/20 transition-all duration-300 group">
                                    <td className="px-10 py-6">
                                        <div className="flex items-center gap-4">
                                            <div className="w-12 h-12 rounded-[1rem] bg-purple-600 text-white flex items-center justify-center font-black text-lg shadow-lg border-2 border-purple-400 transition-transform group-hover:scale-110 group-hover:rotate-3">
                                                {item.user_name ? item.user_name.charAt(0) : '?'}
                                            </div>
                                            <div>
                                                <div className="font-black text-gray-900 text-sm tracking-tight">{item.user_name}</div>
                                                <div className="text-[10px] text-gray-400 font-black tracking-widest uppercase opacity-70 mt-0.5">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-10 py-6">
                                        <span className="font-black text-gray-800 text-sm leading-tight group-hover:text-purple-700 transition-colors">{item.tool_name}</span>
                                    </td>
                                    <td className="px-10 py-6">
                                        <div className="text-gray-900 font-black text-xs">{new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        <div className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter mt-0.5 flex items-center gap-1 opacity-60">
                                            <History className="w-3 h-3"/> 
                                            {new Date(item.borrow_date).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}
                                        </div>
                                    </td>
                                    <td className="px-10 py-6">
                                        {item.returned_at ? (
                                            <>
                                                <div className="text-purple-700 font-black text-xs">{new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                                <div className="text-[10px] text-purple-400 font-bold uppercase tracking-tighter mt-0.5">{new Date(item.returned_at).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</div>
                                            </>
                                        ) : (
                                            <span className="text-gray-200 font-black text-lg select-none">—</span>
                                        )}
                                    </td>
                                    <td className="px-10 py-6">
                                        {item.status !== 'pending' ? (
                                            <div className="flex items-center gap-2 px-3 py-1.5 bg-gray-50 border border-gray-100 rounded-xl w-fit shadow-sm">
                                                <ShieldCheck className="w-3.5 h-3.5 text-gray-400" />
                                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-tight">{getHandlerName(item)}</span>
                                            </div>
                                        ) : (
                                            <span className="text-gray-300 text-[10px] font-black uppercase tracking-widest italic pl-1">Chờ xử lý</span>
                                        )}
                                    </td>
                                    <td className="px-10 py-6 text-center">
                                        <span className={`inline-flex items-center gap-2 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 shadow-lg transition-all group-hover:scale-105 ${
                                            item.status === 'approved' ? 'bg-emerald-500 text-white border-emerald-600 shadow-emerald-200/50' :
                                            item.status === 'rejected' ? 'bg-rose-500 text-white border-rose-600 shadow-rose-200/50' :
                                            item.status === 'returned' ? 'bg-blue-500 text-white border-blue-600 shadow-blue-200/50' :
                                            'bg-amber-500 text-white border-amber-600 shadow-amber-200/50'
                                        }`}>
                                            {item.status === 'approved' ? 'Đang mượn' : 
                                            item.status === 'rejected' ? 'Từ chối' : 
                                            item.status === 'returned' ? 'Đã trả' : 'Chờ duyệt'}
                                        </span>
                                    </td>
                                    <td className="px-10 py-6 text-right">
                                        {item.status === 'returned' || item.status === 'rejected' ? (
                                            <button 
                                                onClick={() => handleReBorrow(item)}
                                                disabled={reBorrowingId === item.id}
                                                className="inline-flex items-center gap-2 px-4 py-2.5 bg-white text-blue-600 border-2 border-blue-100 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all active:scale-95 disabled:opacity-50"
                                            >
                                                {reBorrowingId === item.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Undo2 className="w-3.5 h-3.5" />}
                                                Mượn lại
                                            </button>
                                        ) : (
                                            <span className="text-gray-100 font-black text-xs select-none">N/A</span>
                                        )}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Phân trang Footer */}
            <div className="bg-gray-50 border-t border-gray-100 p-8 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
                <div className="flex flex-col sm:flex-row items-center gap-4">
                  <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                    Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredLogs.length, startIndex + 1)}-{Math.min(filteredLogs.length, startIndex + ITEMS_PER_PAGE)}</span> trong <span className="text-gray-900 tabular-nums">{filteredLogs.length}</span> kết quả
                  </span>
                  <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                    <span className="bg-purple-50 text-purple-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-purple-100">{currentPage} / {totalPages}</span>
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <button 
                    onClick={() => handlePageChange(1)}
                    disabled={currentPage === 1}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                    title="Trang đầu"
                  >
                    <ChevronsLeft className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </button>

                  <div className="flex items-center gap-1 mx-2">
                    {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                      let pageNum = 1;
                      if (totalPages <= 5) pageNum = i + 1;
                      else if (currentPage <= 3) pageNum = i + 1;
                      else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                      else pageNum = currentPage - 2 + i;

                      return (
                        <button
                          key={pageNum}
                          onClick={() => handlePageChange(pageNum)}
                          className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                            currentPage === pageNum 
                            ? 'bg-purple-600 text-white border-purple-600 shadow-xl scale-110 z-10' 
                            : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                  >
                    <ChevronRight className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => handlePageChange(totalPages)}
                    disabled={currentPage === totalPages}
                    className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-purple-50 text-gray-600 hover:text-purple-600 transition-all shadow-sm active:scale-90"
                    title="Trang cuối"
                  >
                    <ChevronsRight className="w-5 h-5" />
                  </button>
                </div>
            </div>
       </Card>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, Send, Loader2, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, Trash2, Check, Boxes, Info, Tag, Hash, Archive
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: '',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);

  // Kiểm tra URL hợp lệ
  const isValidUrl = useMemo(() => {
    if (!src || typeof src !== 'string' || src.trim().length === 0) return false;
    return src.startsWith('http') || src.startsWith('data:');
  }, [src]);

  // Nếu lỗi hoặc URL không hợp lệ, hiển thị placeholder chuyên nghiệp
  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full rounded-xl border-2 border-dashed border-gray-200 transition-colors group-hover:bg-gray-100`}>
        <div className={`p-2 bg-white rounded-full shadow-sm border border-gray-100`}>
          <Wrench className={`${mode === 'grid' ? 'w-8 h-8 text-gray-400' : 'w-4 h-4 text-gray-500'}`} />
        </div>
        {mode === 'grid' && (
          <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">No Image</span>
        )}
      </div>
    );
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-white rounded-xl overflow-hidden">
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
      {/* Overlay hiệu ứng khi hover ở grid */}
      {mode === 'grid' && (
        <div className="absolute inset-0 bg-blue-600/0 group-hover:bg-blue-600/5 transition-colors pointer-events-none" />
      )}
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedQuantities, setSelectedQuantities] = useState<Record<string, number>>({});
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (tool: Tool) => {
    if (isManageMode) return;
    const isAvailable = tool.status === 'active' && tool.available > 0;
    if (!isAvailable && !selectedQuantities[tool.id]) return;

    setSelectedQuantities(prev => {
        const current = prev[tool.id] || 0;
        if (current > 0) {
            const next = { ...prev };
            delete next[tool.id];
            return next;
        } else {
            return { ...prev, [tool.id]: 1 };
        }
    });
  };

  const updateQuantity = (id: string, delta: number, max: number, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedQuantities(prev => {
        const current = prev[id] || 0;
        const next = Math.max(0, Math.min(max, current + delta));
        const newQuantities = { ...prev };
        if (next === 0) delete newQuantities[id];
        else newQuantities[id] = next;
        return newQuantities;
    });
  };

  const handleBulkBorrow = async () => {
    const selectedToolIds = Object.keys(selectedQuantities);
    if (selectedToolIds.length === 0) return;
    setIsBorrowing(true);
    try {
      for (const toolId of selectedToolIds) {
        const tool = tools.find(t => t.id === toolId);
        const qty = selectedQuantities[toolId];
        if (!tool || tool.available < qty) continue;

        const requestsToInsert = Array.from({ length: qty }).map(() => ({
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        }));

        const { error } = await supabase.from('requests').insert(requestsToInsert);
        if (error) throw error;
      }
      setMessage(`Gửi thành công yêu cầu mượn đồ!`);
      setSelectedQuantities({});
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Đã cập nhật' : 'Đã thêm mới');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const totalSelectedCount = (Object.values(selectedQuantities) as number[]).reduce((sum: number, q: number) => sum + q, 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* Header & Filter */}
      <div className="flex flex-col gap-5 bg-white p-6 rounded-[2rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-blue-600 rounded-2xl md:rounded-[1.8rem] shadow-xl shadow-blue-100 text-white"><Wrench className="w-6 h-6 md:w-8 md:h-8" /></div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none uppercase">Kho thiết bị</h2>
                    <p className="text-[9px] md:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1.5 opacity-70">Quản lý & mượn đồ tập trung</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div className="bg-emerald-600 text-white px-4 py-2.5 rounded-2xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 tracking-widest">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1 rounded-2xl border border-gray-200">
                        <button onClick={() => {setIsManageMode(true); setSelectedQuantities({});}} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-white text-blue-600 shadow-lg' : 'text-gray-500'}`}>QUẢN LÝ</button>
                        <button onClick={() => {setIsManageMode(false); setSelectedQuantities({});}} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-white text-blue-600 shadow-lg' : 'text-gray-500'}`}>MƯỢN ĐỒ</button>
                    </div>
                )}

                {isManageMode && (
                    <button 
                        onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} 
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-xl shadow-blue-100 transition-all active:scale-95 flex items-center gap-2"
                    >
                        <Plus className="w-4 h-4" /> THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600 transition-colors" />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Tìm tên thiết bị, vị trí..." className="w-full pl-12 pr-4 py-3.5 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all" />
            </div>

            <div className="flex gap-3">
                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="px-5 py-3.5 bg-gray-50 border-none rounded-2xl text-[9px] font-black uppercase tracking-widest outline-none cursor-pointer">
                    <option value="all">Danh mục</option>
                    {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                </select>
                <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-2xl border border-gray-200">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl ${viewMode === 'grid' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}><LayoutGrid className="w-4 h-4" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl ${viewMode === 'table' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}><List className="w-4 h-4" /></button>
                </div>
            </div>
        </div>
      </div>

      {/* Main List */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool: Tool) => {
                const qty = selectedQuantities[tool.id] || 0;
                const isSelected = qty > 0;
                const isAvailable = tool.status === 'active' && tool.available > 0;
                return (
                <Card 
                    key={tool.id} 
                    onClick={() => toggleSelection(tool)}
                    className={`cursor-pointer group hover:shadow-2xl transition-all p-0 border-4 overflow-hidden rounded-[2.8rem] ${isSelected ? 'border-blue-600 ring-8 ring-blue-50 bg-blue-50/20' : 'border-transparent bg-white shadow-xl'} ${!isManageMode && !isAvailable && !isSelected ? 'opacity-50 grayscale pointer-events-none' : ''}`}
                >
                    <div className="h-56 bg-white flex items-center justify-center relative border-b border-gray-50">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        <span className={`text-white text-[8px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg border-2 border-white ${tool.status === 'inactive' ? 'bg-rose-500' : tool.available > 0 ? 'bg-emerald-500' : 'bg-gray-400'}`}>
                            {tool.status === 'inactive' ? 'Sửa chữa' : tool.available > 0 ? `Sẵn: ${tool.available}` : 'Hết đồ'}
                        </span>
                        {isSelected && <div className="bg-blue-600 text-white p-2 rounded-full shadow-xl animate-bounce"><Check className="w-3.5 h-3.5" /></div>}
                      </div>
                    </div>
                    <div className="p-6 space-y-4">
                      <div className="space-y-1">
                        <span className="text-[8px] font-black text-blue-600 uppercase tracking-[0.2em]">{tool.category}</span>
                        <h3 className="font-black text-gray-900 text-sm line-clamp-2 h-10 leading-tight uppercase tracking-tight">{tool.name}</h3>
                      </div>
                      <div className="flex items-center justify-between text-[8px] text-gray-400 font-bold uppercase bg-gray-50 p-2.5 rounded-xl border border-gray-100">
                          <span className="flex items-center gap-1.5"><MapPin className="w-3 h-3 text-blue-400" /> {tool.location || 'KHO CHUNG'}</span>
                          <span className="font-black text-gray-900">ID: {tool.id.slice(0, 5)}</span>
                      </div>
                      {isManageMode && (
                        <div className="flex gap-2 pt-1">
                           <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="flex-1 bg-gray-900 hover:bg-black text-white py-3 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg transition-all active:scale-95">Chỉnh sửa</button>
                           <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-3 bg-rose-50 text-rose-600 rounded-xl hover:bg-rose-600 hover:text-white transition-all"><Trash2 className="w-4 h-4" /></button>
                        </div>
                      )}
                      {!isManageMode && isSelected && (
                        <div className="flex items-center justify-between bg-blue-600 p-1.5 rounded-2xl text-white shadow-xl animate-zoom-in border-4 border-white">
                            <button onClick={(e) => updateQuantity(tool.id, -1, tool.available, e)} className="p-2.5 hover:bg-white/20 rounded-xl transition-colors"><Minus className="w-4 h-4" /></button>
                            <span className="text-lg font-black tabular-nums">{qty}</span>
                            <button onClick={(e) => updateQuantity(tool.id, 1, tool.available, e)} className="p-2.5 hover:bg-white/20 rounded-xl transition-colors"><Plus className="w-4 h-4" /></button>
                        </div>
                      )}
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[2.5rem] overflow-hidden border-none shadow-xl bg-white">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-8 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Thiết bị</th>
                    <th className="px-8 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Danh mục</th>
                    <th className="px-8 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400 text-center">Sẵn / Tổng</th>
                    <th className="px-8 py-6 text-center text-[9px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-8 py-6 text-right text-[9px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool: Tool) => {
                    const qty = selectedQuantities[tool.id] || 0;
                    const isSelected = qty > 0;
                    return (
                        <tr key={tool.id} onClick={() => toggleSelection(tool)} className={`cursor-pointer transition-all ${isSelected ? 'bg-blue-50/50' : 'hover:bg-gray-50'} group`}>
                            <td className="px-8 py-4">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-xl bg-white border-2 overflow-hidden flex items-center justify-center p-1 shadow-sm"><ToolThumbnail src={tool.image} alt={tool.name} mode="table" /></div>
                                    <div>
                                        <div className={`font-black uppercase text-xs ${isSelected ? 'text-blue-700' : 'text-gray-900'}`}>{tool.name}</div>
                                        <div className="text-[9px] text-gray-400 font-bold uppercase mt-0.5 flex items-center gap-1"><MapPin className="w-3 h-3" /> {tool.location || 'KHO'}</div>
                                    </div>
                                </div>
                            </td>
                            <td className="px-8 py-4"><span className="bg-gray-100 text-gray-500 px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest">{tool.category}</span></td>
                            <td className="px-8 py-4 text-center text-xs font-black tabular-nums">
                                <span className={tool.available > 0 ? 'text-emerald-600' : 'text-rose-500'}>{tool.available}</span>
                                <span className="text-gray-200 mx-1.5">/</span>
                                <span className="text-gray-400">{tool.quantity}</span>
                            </td>
                            <td className="px-8 py-4 text-center">
                                {tool.status === 'active' ? (
                                    <span className="text-emerald-700 bg-emerald-50 px-3 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest border border-emerald-100">Sẵn sàng</span>
                                ) : (
                                    <span className="text-rose-700 bg-rose-50 px-3 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest border border-rose-100">Bảo trì</span>
                                )}
                            </td>
                            <td className="px-8 py-4 text-right">
                                <div className="flex justify-end items-center gap-3">
                                    {isManageMode ? (
                                        <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className="p-3 bg-gray-900 text-white rounded-xl shadow-lg transition-all active:scale-90"><Edit className="w-4 h-4"/></button>
                                    ) : (
                                        isSelected && (
                                            <div className="flex items-center bg-blue-600 rounded-xl p-1 shadow-lg border-2 border-white">
                                                <button onClick={(e) => updateQuantity(tool.id, -1, tool.available, e)} className="p-2 hover:bg-white/20 rounded-lg text-white"><Minus className="w-3.5 h-3.5"/></button>
                                                <span className="px-3 font-black text-xs text-white">{qty}</span>
                                                <button onClick={(e) => updateQuantity(tool.id, 1, tool.available, e)} className="p-2 hover:bg-white/20 rounded-lg text-white"><Plus className="w-3.5 h-3.5"/></button>
                                            </div>
                                        )
                                    )}
                                </div>
                            </td>
                        </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        )}
      </div>

      {/* Pagination Bar */}
      <Card className="p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] shadow-xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-6 px-8 md:px-12">
          <div className="flex items-center gap-4">
            <span className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Hiển thị <span className="text-gray-900 tabular-nums">{Math.min(filteredTools.length, startIndex + 1)}-{Math.min(filteredTools.length, startIndex + pageSize)}</span> trong {filteredTools.length}</span>
          </div>
          <div className="flex items-center gap-3">
              <button 
                onClick={() => handlePageChange(currentPage - 1)} 
                disabled={currentPage === 1} 
                className="p-3.5 rounded-xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all active:scale-90"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <div className="flex items-center gap-1.5">
                 {Array.from({length: totalPages}, (_, i) => i + 1).filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1).map((p, idx, arr) => (
                    <React.Fragment key={p}>
                        {idx > 0 && arr[idx-1] !== p - 1 && <span className="text-gray-300 font-black">...</span>}
                        <button 
                            onClick={() => handlePageChange(p)}
                            className={`w-10 h-10 rounded-xl font-black text-xs transition-all border-2 ${currentPage === p ? 'bg-blue-600 text-white border-blue-600 shadow-lg scale-110' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'}`}
                        >
                            {p}
                        </button>
                    </React.Fragment>
                 ))}
              </div>
              <button 
                onClick={() => handlePageChange(currentPage + 1)} 
                disabled={currentPage === totalPages} 
                className="p-3.5 rounded-xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all active:scale-90"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
          </div>
      </Card>

      {/* Action Bar */}
      {!isManageMode && totalSelectedCount > 0 && (
          <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[80] w-[calc(100%-2rem)] max-w-xl animate-fade-in-up">
            <div className="bg-gray-900/95 backdrop-blur-xl border border-white/10 p-5 md:p-6 rounded-[3rem] shadow-2xl flex items-center justify-between gap-6">
                <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-blue-600 rounded-2xl flex items-center justify-center text-white font-black text-xl border-2 border-white/20">{totalSelectedCount}</div>
                    <div className="hidden sm:block">
                        <p className="text-white font-black text-sm uppercase tracking-tight">Thiết bị đang mượn</p>
                        <p className="text-blue-400 text-[8px] font-black uppercase tracking-widest mt-1 opacity-80">Gửi yêu cầu phê duyệt</p>
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setSelectedQuantities({})} className="px-4 py-2 text-gray-400 hover:text-white text-[9px] font-black uppercase tracking-widest">HỦY</button>
                    <button onClick={handleBulkBorrow} disabled={isBorrowing} className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50">
                        {isBorrowing ? <Loader2 className="w-4 h-4 animate-spin" /> : <><Send className="w-4 h-4" /> GỬI YÊU CẦU</>}
                    </button>
                </div>
            </div>
          </div>
      )}

      {/* Admin Edit Modal */}
      {isAdmin && isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in overflow-y-auto">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-xl max-h-[90vh] overflow-hidden animate-zoom-in my-auto border border-white/20 flex flex-col">
            <div className="flex justify-between items-center px-8 py-6 border-b sticky top-0 bg-white z-20">
              <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100"><Edit className="w-5 h-5"/></div>
                  <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">{isEditing ? 'Cập nhật tài sản' : 'Thêm tài sản mới'}</h3>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2.5 hover:bg-gray-100 rounded-xl transition-colors"><X className="w-6 h-6 text-gray-400"/></button>
            </div>

            <div className="p-8 space-y-6 bg-gray-50/20 overflow-y-auto no-scrollbar flex-1">
              {/* Fields Group */}
              <div className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Tên tài sản</label>
                        <input type="text" placeholder="Tên thiết bị..." value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-4 py-3.5 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all"/>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Vị trí kho</label>
                        <input type="text" placeholder="Kệ A, Tầng 1..." value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} className="w-full px-4 py-3.5 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all"/>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Danh mục</label>
                        <input list="cat-suggestions" type="text" placeholder="Nhập hoặc chọn..." value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-4 py-3.5 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all"/>
                        <datalist id="cat-suggestions">{uniqueCategories.map(c => <option key={c} value={c} />)}</datalist>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Trạng thái</label>
                        <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})} className="w-full px-4 py-3.5 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none cursor-pointer">
                            <option value="active">ĐANG HOẠT ĐỘNG</option>
                            <option value="inactive">ĐANG BẢO TRÌ</option>
                        </select>
                    </div>
                  </div>
              </div>

              {/* Stock Management */}
              <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest px-1">Tổng kho</p>
                        <div className="flex items-center bg-gray-50 rounded-xl p-1.5 border border-gray-100">
                            <button onClick={() => setFormData({...formData, quantity: Math.max(0, formData.quantity - 1)})} className="p-2.5 bg-white rounded-lg shadow-sm hover:bg-gray-900 hover:text-white transition-all"><Minus className="w-3.5 h-3.5"/></button>
                            <span className="flex-1 text-center font-black text-sm tabular-nums">{formData.quantity}</span>
                            <button onClick={() => setFormData({...formData, quantity: formData.quantity + 1})} className="p-2.5 bg-white rounded-lg shadow-sm hover:bg-gray-900 hover:text-white transition-all"><Plus className="w-3.5 h-3.5"/></button>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest px-1">Sẵn mượn</p>
                        <div className="flex items-center bg-gray-50 rounded-xl p-1.5 border border-gray-100">
                            <button onClick={() => setFormData({...formData, available: Math.max(0, formData.available - 1)})} className="p-2.5 bg-white rounded-lg shadow-sm hover:bg-gray-900 hover:text-white transition-all"><Minus className="w-3.5 h-3.5"/></button>
                            <span className="flex-1 text-center font-black text-sm tabular-nums">{formData.available}</span>
                            <button onClick={() => setFormData({...formData, available: Math.min(formData.quantity, formData.available + 1)})} className="p-2.5 bg-white rounded-lg shadow-sm hover:bg-gray-900 hover:text-white transition-all"><Plus className="w-3.5 h-3.5"/></button>
                        </div>
                    </div>
              </div>

              {/* Media & Desc */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-4">
                    <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Đường dẫn ảnh</label>
                        <input type="text" placeholder="Dán link ảnh (URL)..." value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-4 py-3.5 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none focus:ring-4 focus:ring-blue-600/10 transition-all"/>
                    </div>
                    <div className="h-32 rounded-2xl bg-white border-2 border-dashed border-gray-100 flex items-center justify-center overflow-hidden">
                        {formData.image ? <img src={formData.image} alt="" className="h-full w-full object-contain p-2" onError={(e) => (e.currentTarget.src = 'https://via.placeholder.com/200?text=Loi+Anh')} /> : <ImageIcon className="w-8 h-8 text-gray-100" />}
                    </div>
                 </div>
                 <div className="flex flex-col space-y-1.5">
                    <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Mô tả / Ghi chú</label>
                    <textarea placeholder="Thông tin kỹ thuật..." value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="flex-1 w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-xs font-bold outline-none resize-none shadow-inner"/>
                 </div>
              </div>

              <button onClick={handleSaveTool} className="w-full py-5 bg-gray-900 hover:bg-black text-white font-black rounded-2xl shadow-xl uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 transition-all active:scale-95">
                <Save className="w-5 h-5"/> LƯU THAY ĐỔI
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation */}
      {toolToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-sm overflow-hidden animate-zoom-in border border-white/10">
            <div className="p-10 text-center">
              <div className="w-20 h-20 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-3xl shadow-lg"><AlertTriangle className="w-10 h-10"/></div>
              <h3 className="text-xl font-black text-gray-900 mb-3 uppercase tracking-tighter">Xác nhận xóa?</h3>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest opacity-80 leading-relaxed px-4">Hành động này sẽ gỡ bỏ thiết bị khỏi kho vĩnh viễn.</p>
            </div>
            <div className="bg-gray-50/50 p-6 flex flex-col gap-3 border-t">
              <button onClick={async () => { await supabase.from('tools').delete().eq('id', toolToDelete); await fetchTools(); setToolToDelete(null); setMessage('Đã xóa'); setTimeout(() => setMessage(null), 3000); }} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl text-[9px] uppercase tracking-widest shadow-xl shadow-rose-200 transition-all active:scale-95">XÓA TÀI SẢN</button>
              <button onClick={() => setToolToDelete(null)} className="w-full py-4 bg-white text-gray-400 font-black rounded-2xl border-2 border-gray-100 text-[9px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  History, Search, Calendar, Filter, X, 
  User as UserIcon, ShieldCheck, ChevronDown, 
  SlidersHorizontal, ChevronLeft, ChevronRight, 
  Loader2, RefreshCw, AlertCircle, ChevronsLeft, ChevronsRight,
  Undo2, CheckCircle2, AlertTriangle, FileSpreadsheet,
  Download, ListFilter, CalendarDays, Activity, 
  ArrowUpRight, Clock, Box, LayoutPanelLeft
} from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | 'yesterday' | 'thisWeek' | '7days' | '30days' | '90days' | 'thisMonth';

const ITEMS_PER_PAGE = 20;

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`fixed bottom-10 right-10 z-[100] ${type === 'success' ? 'bg-emerald-600' : 'bg-rose-600'} text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up border border-white/20 backdrop-blur-md`}>
      {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
      <p className="text-xs font-black uppercase tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-2 hover:bg-white/20 p-1 rounded-full"><X className="w-4 h-4"/></button>
    </div>
  );
};

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reBorrowingId, setReBorrowingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  // State phân trang
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async (silent = false) => {
    if (!user) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    setError(null);

    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
      }

      if (statusFilter !== 'all') {
        query = query.eq('status', statusFilter);
      }

      if (startDate) {
        query = query.gte('borrow_date', `${startDate}T00:00:00`);
      }
      if (endDate) {
        query = query.lte('borrow_date', `${endDate}T23:59:59`);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      if (data) {
        setLogs(data as ExtendedBorrowRequest[]);
      }
    } catch (err: any) {
      console.error("Fetch history error:", err);
      setError("Không thể tải dữ liệu lịch sử.");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, [user.id, startDate, endDate, statusFilter, user.role]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Admin';
    if (req.status === 'rejected') return req.rejected_by || 'Admin';
    return '-';
  };

  const handleReBorrow = async (log: ExtendedBorrowRequest) => {
    setReBorrowingId(log.id);
    try {
      const { error } = await supabase.from('requests').insert([{
        user_id: user.id,
        user_name: user.name,
        employee_id: user.employeeCode,
        tool_id: log.tool_id,
        tool_name: log.tool_name,
        borrow_date: new Date().toISOString(),
        status: 'pending'
      }]);

      if (error) throw error;

      setToast({ message: "Đã gửi yêu cầu mượn lại thành công!", type: 'success' });
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchHistory(true);
    } catch (err: any) {
      setToast({ message: "Lỗi: " + err.message, type: 'error' });
    } finally {
      setReBorrowingId(null);
    }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.trim().toLowerCase();
      const handlerLower = handlerFilter.trim().toLowerCase();

      const matchesText = !searchLower || (
        log.user_name?.toLowerCase().includes(searchLower) ||
        log.employee_id?.toLowerCase().includes(searchLower) ||
        log.tool_name?.toLowerCase().includes(searchLower)
      );

      const currentHandler = getHandlerName(log).toLowerCase();
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);

      return matchesText && matchesHandler;
    });
  }, [logs, searchText, handlerFilter]);

  // Thống kê tóm tắt dựa trên logs đã fetch (không phụ thuộc searchText)
  const summaryStats = useMemo(() => {
    return {
      total: logs.length,
      pending: logs.filter(l => l.status === 'pending').length,
      borrowing: logs.filter(l => l.status === 'approved').length,
      completed: logs.filter(l => l.status === 'returned' || l.status === 'rejected').length
    };
  }, [logs]);

  const handleExportExcel = () => {
    if (filteredLogs.length === 0) return alert("Không có dữ liệu để xuất.");

    const exportData = filteredLogs.map(log => ({
      'Người mượn': log.user_name,
      'Mã nhân viên': log.employee_id,
      'Thiết bị': log.tool_name,
      'Ngày mượn': new Date(log.borrow_date).toLocaleString('vi-VN'),
      'Ngày trả': log.returned_at ? new Date(log.returned_at).toLocaleString('vi-VN') : 'Chưa trả',
      'Người xử lý': getHandlerName(log),
      'Trạng thái': log.status === 'approved' ? 'Đang mượn' : 
                    log.status === 'returned' ? 'Đã trả' : 
                    log.status === 'rejected' ? 'Từ chối' : 'Chờ duyệt'
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "LichSuMuonTra");
    XLSX.writeFile(workbook, `Lich_su_muon_tra_${new Date().getTime()}.xlsx`);
  };

  const totalPages = Math.max(1, Math.ceil(filteredLogs.length / ITEMS_PER_PAGE));

  const currentLogs = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [filteredLogs, currentPage]);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'yesterday':
            start.setDate(today.getDate() - 1);
            end.setDate(today.getDate() - 1);
            break;
        case 'thisWeek':
            const day = today.getDay();
            const diff = today.getDate() - day + (day === 0 ? -6 : 1); // Thứ 2
            start = new Date(today.setDate(diff));
            end = new Date();
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case '90days':
            start.setDate(today.getDate() - 90);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'today':
        default:
            break; 
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setHandlerFilter('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
    setCurrentPage(1);
  };

  const activeFiltersCount = [
    searchText.trim(), 
    handlerFilter.trim(), 
    startDate, 
    endDate, 
    statusFilter !== 'all'
  ].filter(Boolean).length;

  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;

  return (
    <div className="space-y-4 md:space-y-6 animate-fade-in pb-10">
       {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

       {/* Top Header & Export */}
       <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-3 md:p-4 bg-indigo-600 rounded-[1.2rem] shadow-xl shadow-indigo-100 text-white">
                    <History className="w-6 h-6 md:w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none">Lịch sử hoạt động</h2>
                    <p className="text-[8px] md:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        Quản lý & Tra cứu mượn trả
                    </p>
                </div>
            </div>
            <div className="flex items-center gap-2">
                <button 
                  onClick={handleExportExcel}
                  className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-emerald-50 text-emerald-600 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all border border-emerald-100 hover:bg-emerald-600 hover:text-white"
                >
                  <FileSpreadsheet className="w-4 h-4"/> Xuất Excel
                </button>
                <button 
                  onClick={() => fetchHistory(true)} 
                  className="p-2.5 bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-xl transition-all border border-gray-100"
                >
                  {isRefreshing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RefreshCw className="w-4 h-4"/>}
                </button>
            </div>
       </div>

       {/* Summary Stats */}
       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4">
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2 bg-purple-100 text-purple-600 rounded-lg"><LayoutPanelLeft className="w-4 h-4"/></div>
              <span className="text-[7px] md:text-[9px] font-black text-purple-400 uppercase tracking-widest">Tổng lượt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900">{summaryStats.total}</p>
          </Card>
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><Clock className="w-4 h-4"/></div>
              <span className="text-[7px] md:text-[9px] font-black text-amber-400 uppercase tracking-widest">Chờ duyệt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900">{summaryStats.pending}</p>
          </Card>
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg"><Box className="w-4 h-4"/></div>
              <span className="text-[7px] md:text-[9px] font-black text-indigo-400 uppercase tracking-widest">Đang mượn</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900">{summaryStats.borrowing}</p>
          </Card>
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><CheckCircle2 className="w-4 h-4"/></div>
              <span className="text-[7px] md:text-[9px] font-black text-emerald-400 uppercase tracking-widest">Hoàn thành</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900">{summaryStats.completed}</p>
          </Card>
       </div>

       {/* Filters Section */}
       <Card className="p-4 md:p-8 overflow-visible border-none shadow-sm rounded-[1.5rem] md:rounded-[3rem] bg-white">
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h3 className="text-[9px] md:text-[11px] font-black text-gray-400 flex items-center gap-2 uppercase tracking-[0.15em]">
                        <SlidersHorizontal className="w-3.5 h-3.5 text-indigo-600" /> Công cụ lọc linh hoạt
                    </h3>
                    {activeFiltersCount > 0 && (
                        <button onClick={clearFilters} className="text-[9px] text-rose-600 font-black uppercase tracking-widest flex items-center gap-1 hover:underline">
                            <X className="w-3 h-3" /> Xóa lọc
                        </button>
                    )}
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
                    <div className="xl:col-span-4 space-y-4">
                        <label className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Khoảng thời gian nhanh</label>
                        <div className="grid grid-cols-3 md:grid-cols-4 gap-1.5">
                             {[
                               {id: 'today', l: 'H.Nay'}, 
                               {id: 'yesterday', l: 'H.Qua'}, 
                               {id: 'thisWeek', l: 'Tuần này'}, 
                               {id: '7days', l: '7 ngày'}, 
                               {id: '30days', l: '30 ngày'}, 
                               {id: '90days', l: '90 ngày'}, 
                               {id: 'thisMonth', l: 'Tháng này'}
                             ].map((btn) => (
                                <button
                                    key={btn.id}
                                    onClick={() => handleQuickDate(btn.id as QuickDateOption)}
                                    className={`px-2 py-2 text-[8px] font-black uppercase tracking-widest rounded-lg border-2 transition-all ${
                                        quickDate === btn.id 
                                        ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
                                        : 'bg-white text-gray-400 border-gray-100 hover:border-indigo-200'
                                    }`}
                                >
                                    {btn.l}
                                </button>
                             ))}
                        </div>
                    </div>

                    <div className="xl:col-span-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div className="space-y-2">
                            <label className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Tùy chỉnh ngày</label>
                            <div className="flex items-center gap-2">
                                <input type="date" value={startDate} onChange={e => handleManualDateChange('start', e.target.value)} className="w-full px-3 py-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-bold focus:ring-2 focus:ring-indigo-600/10 outline-none"/>
                                <span className="text-gray-300">-</span>
                                <input type="date" value={endDate} onChange={e => handleManualDateChange('end', e.target.value)} className="w-full px-3 py-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-bold focus:ring-2 focus:ring-indigo-600/10 outline-none"/>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Trạng thái & Phê duyệt</label>
                            <div className="flex flex-col gap-2">
                                <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-black uppercase outline-none cursor-pointer">
                                    <option value="all">TẤT CẢ TRẠNG THÁI</option>
                                    <option value="pending">CHỜ DUYỆT</option>
                                    <option value="approved">ĐANG MƯỢN</option>
                                    <option value="returned">ĐÃ TRẢ</option>
                                    <option value="rejected">TỪ CHỐI</option>
                                </select>
                                <div className="relative group">
                                    <ShieldCheck className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5" />
                                    <input type="text" value={handlerFilter} onChange={e => setHandlerFilter(e.target.value)} placeholder="Người xử lý..." className="w-full pl-9 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-bold outline-none"/>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Tìm kiếm văn bản</label>
                            <div className="relative group h-[calc(100%-24px)]">
                                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                                <input 
                                    type="text" 
                                    value={searchText}
                                    onChange={e => setSearchText(e.target.value)}
                                    placeholder="Tên, mã NV, thiết bị..." 
                                    className="w-full h-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-[11px] font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all"
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
       </Card>

       {/* Logs Table Section */}
       <Card className="p-0 overflow-hidden border-none shadow-xl rounded-[1.5rem] md:rounded-[3rem] bg-white">
            <div className="overflow-x-auto w-full no-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50/80 border-b border-gray-100">
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Thành viên</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Thiết bị</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Thời gian</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Admin xử lý</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-center text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-right text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Hành động</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {loading ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center"><Loader2 className="w-10 h-10 animate-spin text-indigo-600 mx-auto opacity-20" /></td></tr>
                        ) : currentLogs.length === 0 ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không có kết quả phù hợp</td></tr>
                        ) : (
                            currentLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-indigo-50/20 transition-all duration-300 group">
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 md:w-10 md:h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-xs md:text-sm border-2 border-indigo-400">
                                                {item.user_name?.charAt(0)}
                                            </div>
                                            <div>
                                                <div className="font-black text-gray-900 text-[11px] md:text-[13px]">{item.user_name}</div>
                                                <div className="text-[7px] md:text-[9px] text-gray-400 font-black uppercase tracking-widest mt-0.5">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <span className="font-black text-gray-800 text-[11px] md:text-[13px] uppercase tracking-tight">{item.tool_name}</span>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="text-gray-900 font-black text-[10px] md:text-xs">M: {new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        {item.returned_at && (
                                            <div className="text-indigo-500 font-black text-[10px] md:text-xs mt-1">T: {new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                        )}
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="flex items-center gap-1.5 text-[8px] md:text-[10px] font-black text-gray-600 uppercase">
                                            <ShieldCheck className="w-3 h-3 text-gray-300" /> {getHandlerName(item)}
                                        </div>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6 text-center">
                                        <span className={`inline-flex px-3 py-1.5 rounded-xl text-[7px] md:text-[8px] font-black uppercase tracking-widest border shadow-sm ${
                                            item.status === 'approved' ? 'bg-indigo-600 text-white border-indigo-500' :
                                            item.status === 'rejected' ? 'bg-rose-500 text-white border-rose-400' :
                                            item.status === 'returned' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                            'bg-amber-50 text-amber-600 border-amber-100'
                                        }`}>
                                            {item.status === 'approved' ? 'Đang mượn' : 
                                             item.status === 'rejected' ? 'Từ chối' : 
                                             item.status === 'returned' ? 'Đã trả' : 'Chờ duyệt'}
                                        </span>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6 text-right">
                                        {(item.status === 'returned' || item.status === 'rejected') ? (
                                            <button 
                                                onClick={() => handleReBorrow(item)}
                                                disabled={reBorrowingId === item.id}
                                                className="inline-flex items-center gap-1.5 px-3 py-2 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-lg text-[9px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50"
                                            >
                                                {reBorrowingId === item.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Undo2 className="w-3.5 h-3.5" />}
                                                Mượn lại
                                            </button>
                                        ) : (
                                            <span className="text-gray-100 font-black text-[9px]">N/A</span>
                                        )}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Pagination */}
            <div className="bg-gray-50 border-t border-gray-100 p-6 md:p-10 flex flex-col sm:flex-row items-center justify-between gap-6">
                <div className="text-[9px] md:text-[11px] text-gray-400 font-black uppercase tracking-widest">
                  Hiển thị <span className="text-gray-900">{startIndex + 1}-{Math.min(filteredLogs.length, startIndex + ITEMS_PER_PAGE)}</span> trên {filteredLogs.length}
                </div>

                <div className="flex items-center gap-2">
                  <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-2.5 rounded-xl border border-gray-200 bg-white disabled:opacity-30 hover:bg-indigo-50 transition-all"><ChevronLeft className="w-5 h-5" /></button>
                  <div className="flex items-center gap-1">
                    {Array.from({ length: totalPages }, (_, i) => i + 1).filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1).map((p, idx, arr) => (
                         <React.Fragment key={p}>
                            {idx > 0 && arr[idx-1] !== p - 1 && <span className="text-gray-300">...</span>}
                            <button 
                                onClick={() => handlePageChange(p)}
                                className={`w-9 h-9 md:w-11 md:h-11 rounded-xl text-[10px] font-black transition-all border-2 ${currentPage === p ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'}`}
                            >
                                {p}
                            </button>
                         </React.Fragment>
                    ))}
                  </div>
                  <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-2.5 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 transition-all"><ChevronRight className="w-5 h-5" /></button>
                </div>
            </div>
       </Card>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, Clock, RotateCcw, 
  CheckCircle2, User as UserIcon, ShieldCheck, 
  AlertTriangle, Loader2, Search, Filter, 
  Calendar, Wrench, Ban, Info, XCircle,
  ChevronRight, ArrowUpCircle, History, AlertCircle, Bookmark,
  ChevronDown, RefreshCw, ChevronLeft, ChevronsLeft, ChevronsRight,
  ThumbsUp, ThumbsDown, PackageCheck, Timer, MapPin, Undo2
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 5000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3.5 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up max-w-[calc(100vw-3rem)] border border-white/20 backdrop-blur-md`}>
      {type === 'success' && <CheckCircle2 className="w-5 h-5 flex-shrink-0" />}
      {type === 'error' && <AlertTriangle className="w-5 h-5 flex-shrink-0" />}
      {type === 'info' && <Loader2 className="w-5 h-5 animate-spin flex-shrink-0" />}
      <p className="text-xs md:text-sm font-bold tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-auto p-1.5 hover:bg-white/20 rounded-full transition-colors">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

type ConfirmActionType = 
  | { type: 'approve'; req: BorrowRequest }
  | { type: 'reject'; req: BorrowRequest }
  | { type: 'return'; req: BorrowRequest }
  | { type: 'cancel'; id: string }
  | null;

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  // Phân trang
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 15;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [confirmAction, setConfirmAction] = useState<ConfirmActionType>(null);

  const showToast = (message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  };

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    try {
      let query = supabase.from('requests').select('*');

      const isAdminView = user.role === 'admin' && activeTab === 'all';
      if (!isAdminView) {
          query = query.eq('user_id', user.id);
      }

      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];

      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) {
        toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));
      }

      const enrichedData: RequestWithImage[] = fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      }));

      setRequests(enrichedData);
    } catch (err: any) {
        showToast("Không thể tải dữ liệu: " + err.message, "error");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    let result = requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);

      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;

      let matchesDateOrBorrowed = true;
      if (filterStartDate) {
        const reqDateStr = new Date(req.borrow_date).toISOString().split('T')[0];
        const isSelectedDate = reqDateStr === filterStartDate;
        const isCurrentlyBorrowed = req.status === 'approved';

        if (filterStatus === 'all') {
            matchesDateOrBorrowed = isSelectedDate || isCurrentlyBorrowed;
        } else {
            matchesDateOrBorrowed = isSelectedDate;
        }
      }

      return matchesSearch && matchesStatus && matchesDateOrBorrowed;
    });

    return result.sort((a, b) => {
        const statusOrder: Record<string, number> = { 'pending': 0, 'approved': 1, 'returned': 2, 'rejected': 3 };
        const orderA = statusOrder[a.status] ?? 99;
        const orderB = statusOrder[b.status] ?? 99;

        if (orderA !== orderB) return orderA - orderB;
        return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentRequests = filteredRequests.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, filterStatus, filterStartDate, activeTab]);

  const updateLocalRequestStatus = (id: string, newStatus: string, extraData = {}) => {
    setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus as any, ...extraData } : req));
  };

  const handleConfirmAction = async () => {
    if (!confirmAction) return;
    const action = confirmAction;
    setConfirmAction(null);
    setProcessingId(action.type === 'cancel' ? action.id : action.req.id);

    try {
        if (action.type === 'approve') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
            await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'approved' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'approved');
        } else if (action.type === 'return') {
            const { data: tool } = await supabase.from('tools').select('available').eq('id', action.req.tool_id).single();
            await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', action.req.tool_id);
            await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'returned');
        } else if (action.type === 'cancel') {
            await supabase.from('requests').delete().eq('id', action.id);
            setRequests(prev => prev.filter(r => r.id !== action.id));
        } else if (action.type === 'reject') {
            await supabase.from('requests').update({ status: 'rejected' }).eq('id', action.req.id);
            updateLocalRequestStatus(action.req.id, 'rejected');
        }

        window.dispatchEvent(new CustomEvent('refresh-counts'));
        showToast("Thao tác thành công!", "success");
    } catch (e: any) {
        showToast(e.message, "error");
    } finally {
        setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'pending': 
        return {
            className: 'bg-amber-50 text-amber-700 border-amber-200 ring-2 ring-amber-500/10 shadow-sm shadow-amber-100/50 font-black',
            icon: <Timer className="w-3.5 h-3.5 animate-pulse" />,
            label: 'Chờ duyệt'
        };
      case 'approved': 
        return {
            className: 'bg-emerald-600 text-white border-emerald-500 shadow-md shadow-emerald-200/50 ring-2 ring-emerald-500/20 font-black',
            icon: <PackageCheck className="w-3.5 h-3.5" />,
            label: 'Đang mượn'
        };
      case 'returned': 
        return {
            className: 'bg-blue-50 text-blue-700 border-blue-200 font-bold',
            icon: <RotateCcw className="w-3.5 h-3.5" />,
            label: 'Đã trả'
        };
      case 'rejected': 
        return {
            className: 'bg-rose-50 text-rose-700 border-rose-200 font-bold',
            icon: <XCircle className="w-3.5 h-3.5" />,
            label: 'Từ chối'
        };
      default: 
        return {
            className: 'bg-gray-100 text-gray-700 border-gray-200',
            icon: <Info className="w-3.5 h-3.5" />,
            label: '—'
        };
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-3 md:space-y-6 animate-fade-in w-full pb-20 px-1 md:px-0">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {/* Header Section */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-3 md:gap-6 bg-white p-3 md:p-6 rounded-[1.2rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-3 md:gap-5">
            <div className="p-2.5 md:p-4 bg-blue-600 rounded-xl md:rounded-[1.5rem] shadow-lg shadow-blue-100">
              <Wrench className="w-5 h-5 md:w-8 md:h-8 text-white" />
            </div>
            <div>
              <h2 className="text-base md:text-2xl font-black text-gray-900 tracking-tight leading-none">
                {activeTab === 'personal' ? 'Đơn của tôi' : 'Quản lý mượn'}
              </h2>
              <p className="text-[8px] md:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 md:mt-2 opacity-70">
                {activeTab === 'personal' ? 'Theo dõi mượn trả' : 'Phê duyệt hệ thống'}
              </p>
            </div>
        </div>

        <div className="flex bg-gray-100 p-1 rounded-xl md:rounded-2xl border border-gray-200 shadow-inner w-full lg:w-auto overflow-hidden">
            {user.role === 'admin' && (
              <button 
                onClick={() => setActiveTab('all')} 
                className={`flex-1 lg:flex-none px-3 md:px-8 py-2 md:py-2.5 rounded-lg md:rounded-xl text-[8px] md:text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-500'}`}
              >
                HỆ THỐNG
              </button>
            )}
            <button 
              onClick={() => setActiveTab('personal')} 
              className={`flex-1 lg:flex-none px-3 md:px-8 py-2 md:py-2.5 rounded-lg md:rounded-xl text-[8px] md:text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-500'}`}
            >
              CỦA TÔI
            </button>
        </div>
      </div>

      {/* Search & Filter Section */}
      <div className="bg-white p-2.5 md:p-6 rounded-[1.2rem] md:rounded-[2.5rem] border border-gray-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-2 md:gap-4">
        <div className="relative group">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5 group-focus-within:text-blue-500" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm nhân viên, đồ..." 
            className="w-full pl-10 pr-4 py-2.5 md:py-4 bg-gray-50 border-none rounded-xl md:rounded-2xl text-[11px] md:text-sm font-bold focus:ring-2 focus:ring-blue-500/10 outline-none transition-all"
          />
        </div>

