        <div className="flex items-center gap-5">
            <div className="p-4 bg-indigo-600 rounded-[1.5rem] shadow-xl shadow-indigo-100">
              <History className="w-8 h-8 text-white" />
            </div>
            <div>
              <h2 className="text-2xl font-black text-gray-900 tracking-tight leading-none uppercase italic">Quản lý mượn đồ</h2>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.3em] mt-2 opacity-70">Manager Tool V1 • Approval System</p>
            </div>
        </div>

        <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner overflow-hidden">
            {user.role === 'admin' && (
