        }
      `}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLayoutDashboard, LucideLoader2, UserCircle, ShieldCheck } from 'lucide-react';

interface LoginFormProps {
  onLoginSuccess: (user: any) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onLoginSuccess }) => {
  const [employeeCode, setEmployeeCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        employeeCode,
        password,
      });

      if (error) {
        setError(error.message);
      } else if (data?.user) {
        localStorage.setItem('sb-session', JSON.stringify(data.session));
        onLoginSuccess(data.user);
      }
    } catch (err) {
      setError('Đã xảy ra lỗi kết nối server.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4 selection:bg-indigo-100 selection:text-indigo-900">
      <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-gray-100 animate-zoom-in">
        <div className="bg-indigo-700 p-10 text-center relative overflow-hidden">
            {/* Decoration */}
            <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
                <div className="absolute top-[-50px] left-[-50px] w-40 h-40 bg-white rounded-full"></div>
                <div className="absolute bottom-[-30px] right-[-30px] w-32 h-32 bg-white rounded-full"></div>
