            <ShieldCheck className="text-white w-12 h-12" />
          </div>
          <h2 className="text-4xl font-black text-white mb-2 relative z-10 tracking-tighter italic">MANAGER TOOL V1</h2>
          <p className="text-indigo-200 text-[10px] font-black uppercase tracking-[0.3em] relative z-10 opacity-80">Security Personnel Management</p>
        </div>

        <div className="p-10">
          <form onSubmit={handleLogin} className="space-y-8">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mã nhân viên (ID)</label>
              <div className="relative group">
                <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none transition-colors group-focus-within:text-indigo-600">
                  <UserCircle className="h-6 w-6 text-gray-300" />
                </div>
                <input
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
                  className="w-full pl-14 pr-6 py-5 rounded-2xl border-none bg-gray-50 text-sm font-bold text-gray-900 focus:ring-4 focus:ring-indigo-600/10 transition-all uppercase placeholder:normal-case shadow-inner"
                  placeholder="VD: NV001"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mật mã truy cập</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-6 py-5 rounded-2xl border-none bg-gray-50 text-sm font-bold text-gray-900 focus:ring-4 focus:ring-indigo-600/10 transition-all shadow-inner"
                placeholder="••••••••"
                required
              />
            </div>

            {error && (
              <div className="p-4 bg-rose-50 text-rose-600 text-[11px] font-black uppercase tracking-tight rounded-2xl border-2 border-rose-100 flex items-center gap-3 animate-shake">
                <AlertTriangle className="w-5 h-5 flex-shrink-0" />
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-5 px-6 rounded-[2rem] transition-all flex items-center justify-center disabled:opacity-70 disabled:cursor-not-allowed shadow-2xl shadow-indigo-100 uppercase text-xs tracking-[0.2em] active:scale-95"
            >
              {loading ? (
                <>
                  <LucideLoader2 className="w-5 h-5 animate-spin mr-3" />
                  Đang xác thực...
                </>
              ) : (
                'Đăng nhập hệ thống'
              )}
            </button>
          </form>

          <div className="mt-10 text-center">
             <p className="text-[9px] text-gray-300 font-bold uppercase tracking-widest">© 2025 Manager Tool Group • V1.0.4</p>
          </div>
        </div>
      </div>
    </div>
  );
};

