import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  CheckCircle2, AlertTriangle, Loader2, Search, 
  Calendar, Wrench, Info, XCircle,
  ChevronDown, ChevronLeft, ChevronRight,
  PackageCheck, Timer
} from 'lucide-react';

interface RequestManagerProps { user: User; }

interface RequestWithImage extends BorrowRequest {
  tool_image?: string;
}

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgClass = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : 'bg-blue-600';

  return (
    <div className={`fixed bottom-6 right-6 z-50 ${bgClass} text-white px-5 py-3 rounded-xl shadow-lg flex items-center gap-3 animate-fade-in-up border border-white/10 backdrop-blur-md`}>
      {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
      <p className="text-xs font-bold uppercase tracking-wide">{message}</p>
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<RequestWithImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterStartDate, setFilterStartDate] = useState('');

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;

      const fetchedData = data as BorrowRequest[] || [];
      const toolIds = [...new Set(fetchedData.map(r => r.tool_id))];
      const { data: toolsData } = await supabase.from('tools').select('id, image').in('id', toolIds);

      const toolImageMap = new Map();
      if (toolsData) toolsData.forEach((t: any) => toolImageMap.set(t.id, t.image));

      setRequests(fetchedData.map(req => ({
        ...req,
        tool_image: toolImageMap.get(req.tool_id)
      })));
    } catch (err: any) {
        setToast({ message: "Lỗi tải dữ liệu", type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      const matchesDate = !filterStartDate || req.borrow_date.startsWith(filterStartDate);
      return matchesSearch && matchesStatus && matchesDate;
    }).sort((a, b) => new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime());
  }, [requests, searchTerm, filterStatus, filterStartDate]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }

      setToast({ message: "Thao tác thành công", type: 'success' });
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchRequests();
    } catch (e: any) {
      setToast({ message: e.message, type: 'error' });
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-50 text-amber-700 border-amber-200', icon: <Timer className="w-3 h-3" />, label: 'Chờ duyệt' },
      approved: { color: 'bg-emerald-50 text-emerald-700 border-emerald-200', icon: <PackageCheck className="w-3 h-3" />, label: 'Đang mượn' },
      returned: { color: 'bg-blue-50 text-blue-700 border-blue-200', icon: <RotateCcw className="w-3 h-3" />, label: 'Đã trả' },
      rejected: { color: 'bg-rose-50 text-rose-700 border-rose-200', icon: <XCircle className="w-3 h-3" />, label: 'Từ chối' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wide border ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Yêu cầu mượn đồ</h2>
          <p className="text-sm text-gray-500 font-medium">Quản lý và phê duyệt thiết bị</p>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'all' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>TẤT CẢ</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>CỦA TÔI</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Tìm tên, thiết bị..." className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/10 outline-none" />
        </div>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="px-4 py-3 bg-white border border-gray-200 rounded-xl text-sm outline-none">
          <option value="all">Tất cả trạng thái</option>
          <option value="pending">Đang chờ</option>
          <option value="approved">Đang mượn</option>
          <option value="returned">Đã trả</option>
          <option value="rejected">Từ chối</option>
        </select>
        <input type="date" value={filterStartDate} onChange={e => setFilterStartDate(e.target.value)} className="px-4 py-3 bg-white border border-gray-200 rounded-xl text-sm outline-none" />
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-sm rounded-2xl bg-white">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400">Thành viên</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400">Thiết bị</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 text-center">Trạng thái</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={4} className="p-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={4} className="p-20 text-center text-gray-400 italic">Không có yêu cầu</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr key={req.id} className="hover:bg-gray-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg bg-blue-600 text-white flex items-center justify-center font-bold text-xs uppercase">{req.user_name.charAt(0)}</div>
                        <div>
                          <p className="font-bold text-gray-900 text-sm">{req.user_name}</p>
                          <p className="text-[10px] text-gray-400 font-medium uppercase">{req.employee_id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="font-bold text-gray-800 text-sm">{req.tool_name}</p>
                      <p className="text-[10px] text-gray-400 font-medium uppercase">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</p>
                    </td>
                    <td className="px-6 py-4 text-center">{getStatusBadge(req.status)}</td>
                    <td className="px-6 py-4 text-right">
                      {processingId === req.id ? (
                        <Loader2 className="w-5 h-5 animate-spin text-blue-600 ml-auto" />
                      ) : (
                        <div className="flex justify-end gap-2">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="p-2 text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"><Check className="w-4 h-4" /></button>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><X className="w-4 h-4" /></button>
                            </>
                          )}
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-black uppercase tracking-wide">Thu hồi</button>
                          )}
                          {req.user_id === user.id && req.status === 'pending' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="p-2 text-gray-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><Trash2 className="w-4 h-4" /></button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLoader2, UserCircle, ShieldCheck, AlertTriangle } from 'lucide-react';

interface LoginFormProps {
  onLoginSuccess: (user: any) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onLoginSuccess }) => {
  const [employeeCode, setEmployeeCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        employeeCode,
        password,
      });

      if (error) {
        setError(error.message);
      } else if (data?.user) {
        localStorage.setItem('sb-session', JSON.stringify(data.session));
        onLoginSuccess(data.user);
      }
    } catch (err) {
      setError('Lỗi kết nối server.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden animate-zoom-in">
        <div className="p-8 text-center bg-white border-b border-gray-100">
          <div className="mx-auto bg-blue-600 w-16 h-16 rounded-2xl flex items-center justify-center mb-4 shadow-lg shadow-blue-100">
            <ShieldCheck className="text-white w-8 h-8" />
          </div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight uppercase">Manager Tool V1</h2>
          <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1">Hệ thống quản lý nội bộ</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mã nhân viên</label>
              <div className="relative">
                <UserCircle className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 w-5 h-5" />
                <input
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
                  className="w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-xl text-sm font-bold focus:ring-2 focus:ring-blue-600/10 outline-none"
                  placeholder="ID nhân viên"
                  required
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mật khẩu</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-4 bg-gray-50 border-none rounded-xl text-sm font-bold focus:ring-2 focus:ring-blue-600/10 outline-none"
                placeholder="••••••••"
                required
              />
            </div>

            {error && (
              <div className="p-3 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-xl border border-rose-100 flex items-center gap-2">
                <AlertTriangle className="w-4 h-4 flex-shrink-0" />
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-xl shadow-lg shadow-blue-100 uppercase text-xs tracking-widest transition-all active:scale-95 disabled:opacity-50"
            >
              {loading ? <LucideLoader2 className="w-5 h-5 animate-spin mx-auto" /> : 'Đăng nhập'}
            </button>
          </form>

          <div className="mt-8 text-center text-[9px] text-gray-300 font-bold uppercase tracking-widest">
            © 2025 Manager Tool Group
          </div>
        </div>
      </div>
    </div>
  );
};

