        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }

      setToast({ message: "Thao tác thành công", type: 'success' });
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchRequests();
    } catch (e: any) {
      setToast({ message: e.message, type: 'error' });
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-50 text-amber-700 border-amber-200', icon: <Timer className="w-3 h-3" />, label: 'Chờ duyệt' },
      approved: { color: 'bg-emerald-50 text-emerald-700 border-emerald-200', icon: <PackageCheck className="w-3 h-3" />, label: 'Đang mượn' },
      returned: { color: 'bg-blue-50 text-blue-700 border-blue-200', icon: <RotateCcw className="w-3 h-3" />, label: 'Đã trả' },
      rejected: { color: 'bg-rose-50 text-rose-700 border-rose-200', icon: <XCircle className="w-3 h-3" />, label: 'Từ chối' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wide border ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-gray-900 tracking-tight">Yêu cầu mượn đồ</h2>
          <p className="text-sm text-gray-500 font-medium">Quản lý và phê duyệt thiết bị</p>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'all' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>TẤT CẢ</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>CỦA TÔI</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Tìm tên, thiết bị..." className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/10 outline-none" />
        </div>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="px-4 py-3 bg-white border border-gray-200 rounded-xl text-sm outline-none">
          <option value="all">Tất cả trạng thái</option>
          <option value="pending">Đang chờ</option>
          <option value="approved">Đang mượn</option>
          <option value="returned">Đã trả</option>
          <option value="rejected">Từ chối</option>
        </select>
        <input type="date" value={filterStartDate} onChange={e => setFilterStartDate(e.target.value)} className="px-4 py-3 bg-white border border-gray-200 rounded-xl text-sm outline-none" />
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-sm rounded-2xl bg-white">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400">Thành viên</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400">Thiết bị</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 text-center">Trạng thái</th>
                <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={4} className="p-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={4} className="p-20 text-center text-gray-400 italic">Không có yêu cầu</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr key={req.id} className="hover:bg-gray-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg bg-blue-600 text-white flex items-center justify-center font-bold text-xs uppercase">{req.user_name.charAt(0)}</div>
                        <div>
                          <p className="font-bold text-gray-900 text-sm">{req.user_name}</p>
                          <p className="text-[10px] text-gray-400 font-medium uppercase">{req.employee_id}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="font-bold text-gray-800 text-sm">{req.tool_name}</p>
                      <p className="text-[10px] text-gray-400 font-medium uppercase">{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</p>
                    </td>
                    <td className="px-6 py-4 text-center">{getStatusBadge(req.status)}</td>
                    <td className="px-6 py-4 text-right">
                      {processingId === req.id ? (
                        <Loader2 className="w-5 h-5 animate-spin text-blue-600 ml-auto" />
                      ) : (
                        <div className="flex justify-end gap-2">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="p-2 text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"><Check className="w-4 h-4" /></button>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><X className="w-4 h-4" /></button>
                            </>
                          )}
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-black uppercase tracking-wide">Thu hồi</button>
                          )}
                          {req.user_id === user.id && req.status === 'pending' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="p-2 text-gray-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><Trash2 className="w-4 h-4" /></button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useState } from 'react';
