              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={4} className="py-24 text-center text-gray-300 font-medium italic">Không có dữ liệu yêu cầu</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className="group relative transition-all duration-200 ease-out hover:bg-blue-50/60 hover:shadow-[0_8px_30px_rgb(0,0,0,0.04)] border-l-4 border-l-transparent hover:border-l-blue-600"
