      returned: { color: 'bg-blue-500 text-white', icon: <RotateCcw className="w-4 h-4" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-red-500 text-white', icon: <XCircle className="w-4 h-4" />, label: 'TỪ CHỐI' }
    };
