                            )}
                            {shouldShowBadge && (
                                <span className={`text-[6px] md:text-[9px] font-black px-1.5 md:px-2.5 py-0.5 md:py-1 rounded-full shadow-lg uppercase border transition-all ${isPast ? 'opacity-30' : 'opacity-100'} ${!isActuallyWorking ? 'bg-rose-500 text-white border-rose-400' : 'bg-indigo-600 text-white border-indigo-500 ring-2 ring-indigo-50'}`}>
