import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  TrendingUp, Activity, Zap, ChevronDown, ChevronUp, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

// Lấy ngày hiện tại theo giờ địa phương
const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const dayRequests = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 

        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            if (dayOfWeek === 6) {
                setStartTime('14:30');
            } else {
                setStartTime('17:30');
            }
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', specificRange?: { start: string, end: string }) => {
    const start = specificRange ? specificRange.start : exportStartDate;
    const end = specificRange ? specificRange.end : exportEndDate;

    if (!start || !end) return alert("Vui lòng chọn đầy đủ khoảng thời gian.");

    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);

    if (filtered.length === 0) return alert("Không tìm thấy dữ liệu đăng ký trong khoảng thời gian này.");

    filtered.sort((a, b) => a.date.localeCompare(b.date));
    const workbook = XLSX.utils.book_new();
    const dayNames = ['Chủ Nhật', 'Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7'];

    const summaryData = filtered.map(req => {
        const d = new Date(req.date);
        return {
            'Ngày': req.date,
            'Thứ': dayNames[d.getDay()],
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        };
    });
    const summarySheet = XLSX.utils.json_to_sheet(summaryData);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'TỔNG HỢP');

    const groupedByDate: Record<string, OvertimeRequest[]> = {};
    filtered.forEach(req => {
        if (!groupedByDate[req.date]) groupedByDate[req.date] = [];
        groupedByDate[req.date].push(req);
    });

    Object.keys(groupedByDate).forEach(dateKey => {
        const dayReqs = groupedByDate[dateKey];
        const dateObj = new Date(dateKey);
        const dayLabel = dayNames[dateObj.getDay()];
        const sheetData = dayReqs.map(req => ({
            'Họ và tên': req.users?.name || 'Ẩn danh',
            'Mã nhân viên': req.users?.employee_id || 'N/A',
            'Bắt đầu': req.start_time,
            'Kết thúc': req.end_time,
            'Tổng giờ': req.total_hours,
            'Nội dung công việc': req.reason
        }));
        const worksheet = XLSX.utils.json_to_sheet(sheetData);
        const tabName = dateKey.split('-').reverse().slice(0, 2).join('-');
        XLSX.utils.book_append_sheet(workbook, worksheet, `${tabName} (${dayLabel})`);
    });

    const fileNameDate = start === end ? `Ngay_${start}` : `${start}_den_${end}`;
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'personal' ? 'Ca_nhan' : 'Toan_bo'}_${fileNameDate}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => {
      handleExportExcel(mode, { start: todayStr, end: todayStr });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string, dateObj: Date) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setShowColleagueDetails(false);
    setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        const dayHours = monthlyApproved.filter(r => r.date === dStr).reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
        return { day: d, hours: dayHours };
    });
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { trend, totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRegistrations = useMemo(() => {
    return requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/20"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateObj = new Date(year, month, d);
        dateObj.setHours(0, 0, 0, 0);
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);

        const isToday = todayStr === dateStr;
        const isPast = dateObj.getTime() < todayTime;

        const dayOfWeek = dateObj.getDay();
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const configWork = dayConfigs[dateStr];
        const isActuallyWorking = configWork ?? defaultIsWorking;

        const isWeekendDefault = dayOfWeek === 0 || dayOfWeek === 6;
        const shouldShowBadge = !isActuallyWorking || (isActuallyWorking && isWeekendDefault);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr, dateObj)}
                className={`h-16 md:h-32 relative transition-all duration-300 cursor-pointer group flex flex-col p-1.5 md:p-2.5
                  ${isToday 
                    ? 'bg-blue-600/5 ring-inset ring-2 md:ring-4 ring-blue-600/80 z-20 scale-[1.01] shadow-xl shadow-blue-500/10' 
                    : isPast 
                      ? 'bg-gray-50/30 opacity-60 grayscale-[40%]' 
                      : 'bg-white hover:bg-indigo-50/50 hover:z-10'} 
                  border-b border-r border-gray-100/60
                `}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-1.5">
                        <span className={`text-xs md:text-lg font-black transition-all ${
                          isToday 
                            ? 'bg-gradient-to-br from-blue-600 to-blue-700 text-white w-6 h-6 md:w-9 md:h-9 rounded-full flex items-center justify-center shadow-lg shadow-blue-400/40 ring-4 ring-blue-50' 
                            : !isActuallyWorking 
                              ? 'text-rose-500' 
                              : isPast 
                                ? 'text-gray-400' 
                                : 'text-gray-900 group-hover:text-blue-600'
                        }`}>
                            {d}
                        </span>

                        {shouldShowBadge && (
                            <span className={`text-[6px] md:text-[8px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter transition-opacity ${isPast ? 'opacity-30' : 'opacity-100'} ${!isActuallyWorking ? 'bg-rose-100 text-rose-600' : 'bg-indigo-100 text-indigo-600'}`}>
                                {!isActuallyWorking ? 'Nghỉ' : 'Làm'}
                            </span>
                        )}
                    </div>
                </div>

                <div className="flex-1 flex flex-col justify-center gap-1 mt-1.5 overflow-hidden">
                    {myRequest && (
                        <div className={`flex items-center gap-1 bg-emerald-50 px-1.5 py-0.5 rounded-lg border border-emerald-100/50 transition-all ${isPast ? 'opacity-30' : 'opacity-100 shadow-sm'}`}>
                            <div className="w-1 h-1 md:w-3.5 md:h-3.5 rounded-full bg-emerald-500 flex items-center justify-center flex-shrink-0">
                                <Check className="hidden md:block w-2.5 h-2.5 text-white" />
                            </div>
                            <span className="text-[7px] md:text-[10px] font-black text-emerald-700 uppercase tabular-nums tracking-tight">Tôi: {myRequest.total_hours}h</span>
                        </div>
                    )}

                    {otherRequests.length > 0 && (
                        <div className={`flex items-center gap-1 transition-all ${isPast ? 'opacity-30' : 'opacity-100'}`}>
                             <div className="flex -space-x-1.5 md:-space-x-2 overflow-hidden">
                                {otherRequests.slice(0, 4).map((req, idx) => (
                                    <div key={idx} className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-gray-50 border border-gray-200 shadow-sm flex items-center justify-center flex-shrink-0">
                                        <span className="text-[7px] md:text-[9px] font-black text-gray-400 uppercase">{req.users?.name?.charAt(0)}</span>
                                    </div>
                                ))}
                                {otherRequests.length > 4 && (
                                    <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-gray-900 border border-white flex items-center justify-center flex-shrink-0">
                                        <span className="text-[7px] md:text-[9px] font-black text-white">+{otherRequests.length - 4}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>

                {dayRequestsLocal.length > 0 && !myRequest && (
                    <div className={`absolute bottom-1.5 right-1.5 px-1.5 py-0.5 rounded-md font-black flex items-center gap-0.5 transition-all ${isPast ? 'text-gray-300' : 'text-indigo-400'} text-[6px] md:text-[9px] uppercase tracking-tighter`}>
                        {dayRequestsLocal.length} Đơn
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-4 md:space-y-6 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-2 md:px-0 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 transition-all">
            <div className="w-full md:w-auto flex items-center justify-between md:block">
                <div className="space-y-0.5">
                    <div className="flex items-center gap-2.5">
                        <div className="p-2 bg-blue-600 rounded-xl shadow-lg shadow-blue-100 text-white">
                            <Clock className="w-4 h-4 md:w-6 md:h-6" />
                        </div>
                        <h2 className="text-base md:text-2xl font-black text-gray-900 tracking-tight uppercase">Tăng ca hệ thống</h2>
                    </div>
                    <p className="text-[8px] md:text-xs text-gray-400 font-black uppercase tracking-[0.2em] ml-0 md:ml-10 opacity-60">Tháng {currentDate.getMonth() + 1} • Năm {currentDate.getFullYear()}</p>
                </div>
                <button 
                  onClick={() => handleExportToday(isAdmin ? 'all' : 'personal')}
                  className="md:hidden flex items-center gap-1.5 bg-emerald-600 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase shadow-xl active:scale-95"
                >
                  <Zap className="w-3.5 h-3.5" /> Xuất hnay
                </button>
            </div>

            <div className="flex flex-col md:flex-row items-center gap-3 w-full md:w-auto">
                <div className="flex w-full md:w-auto bg-gray-100 p-1 rounded-2xl border border-gray-200 shadow-inner">
                    <button onClick={() => setActiveTab('calendar')} className={`flex-1 md:flex-none px-4 md:px-8 py-2 md:py-3 rounded-xl text-[9px] md:text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                        Lịch biểu
                    </button>
                    <button onClick={() => setActiveTab('personal')} className={`flex-1 md:flex-none px-4 md:px-8 py-2 md:py-3 rounded-xl text-[9px] md:text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-white text-emerald-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                        Cá nhân
                    </button>
                    <button onClick={() => setActiveTab('stats')} className={`flex-1 md:flex-none px-4 md:px-8 py-2 md:py-3 rounded-xl text-[9px] md:text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'stats' ? 'bg-white text-indigo-600 shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
                        Phân tích
                    </button>
                </div>
                <button 
                  onClick={() => handleExportToday(isAdmin ? 'all' : 'personal')}
                  className="hidden md:flex items-center gap-2.5 bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 transition-all transform hover:-translate-y-0.5 active:scale-95 border border-white/10"
                >
                  <FileSpreadsheet className="w-4 h-4" /> Xuất Excel
                </button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-[0_20px_60px_-15px_rgba(0,0,0,0.08)] rounded-[1.5rem] md:rounded-[3rem] bg-white">
                    <div className="flex items-center justify-between p-4 md:p-10 bg-white">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 md:p-4 hover:bg-blue-50 text-blue-600 rounded-2xl transition-all shadow-sm border border-gray-100 active:scale-90"><ChevronLeft className="w-5 h-5 md:w-7 md:h-7"/></button>
                        <div className="text-center">
                            <h3 className="text-xs md:text-3xl font-black uppercase tracking-[0.2em] md:tracking-[0.4em] text-gray-900 leading-none">THÁNG {currentDate.getMonth()+1}</h3>
                        </div>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 md:p-4 hover:bg-blue-50 text-blue-600 rounded-2xl transition-all shadow-sm border border-gray-100 active:scale-90"><ChevronRight className="w-5 h-5 md:w-7 md:h-7"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] md:text-[10px] font-black uppercase text-gray-400 tracking-[0.25em] border-y border-gray-100">
                        {['Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7', 'CN'].map((d, i) => <div key={d} className={`py-3 md:py-6 text-center ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 md:space-y-8 animate-fade-in-up">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-6">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none shadow-xl rounded-[1.2rem] md:rounded-[2.5rem] p-5 md:p-10 transform hover:scale-[1.02] transition-transform">
                            <h3 className="text-[8px] md:text-[10px] font-black uppercase tracking-widest opacity-70 mb-2">Quỹ giờ cá nhân</h3>
                            <div className="flex items-end gap-1.5"><span className="text-3xl md:text-7xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-xs md:text-xl font-bold opacity-60 pb-1 md:pb-3 uppercase">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center bg-white border-l-4 md:border-l-8 border-emerald-500 rounded-[1.2rem] md:rounded-[2.5rem] p-5 md:p-10 shadow-sm hover:shadow-md transition-all">
                            <p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Số ngày OT</p>
                            <p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                        <Card className="flex flex-col justify-center bg-white border-l-4 md:border-l-8 border-amber-500 rounded-[1.2rem] md:rounded-[2.5rem] p-5 md:p-10 shadow-sm hover:shadow-md transition-all">
                            <p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Đang duyệt</p>
                            <p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{myStats.pending}</p>
                        </Card>
                        <Card className="flex flex-col justify-center bg-white border-l-4 md:border-l-8 border-indigo-500 rounded-[1.2rem] md:rounded-[2.5rem] p-5 md:p-10 shadow-sm hover:shadow-md transition-all">
                            <p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Trung bình</p>
                            <p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{(myStats.total / (myStats.count || 1)).toFixed(1)} <span className="text-[10px] text-gray-300">H/Ngày</span></p>
                        </Card>
                    </div>

                    <Card className="rounded-[2rem] md:rounded-[4rem] p-6 md:p-12 shadow-xl border-none bg-white">
                        <div className="flex items-center gap-4 mb-8">
                            <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl shadow-lg shadow-emerald-50">
                                <FileSpreadsheet className="w-7 h-7 md:w-9 md:h-9" />
                            </div>
                            <div>
                                <h3 className="text-lg md:text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none">Kết xuất báo cáo cá nhân</h3>
                                <p className="text-[10px] md:text-sm text-gray-400 font-black uppercase tracking-widest mt-1.5 opacity-60">Chọn mốc thời gian để tải file Excel</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-12 items-end gap-4 md:gap-6 bg-gray-50/50 p-6 md:p-10 rounded-[2.5rem] border border-gray-100">
                            <div className="md:col-span-4 space-y-2">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 flex items-center gap-2"><CalendarRange className="w-4 h-4 text-emerald-500"/> Từ ngày</label>
                                <input type="date" value={exportStartDate} onChange={(e) => setExportStartDate(e.target.value)} className="w-full px-6 py-4 bg-white border-2 border-gray-100 rounded-2xl text-xs md:text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all"/>
                            </div>
                            <div className="md:col-span-1 flex items-center justify-center pb-4">
                                <ArrowRight className="w-6 h-6 text-gray-300 hidden md:block" />
                                <div className="h-[2px] w-12 bg-gray-200 md:hidden my-2"></div>
                            </div>
                            <div className="md:col-span-4 space-y-2">
                                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 flex items-center gap-2"><CalendarRange className="w-4 h-4 text-emerald-500"/> Đến ngày</label>
                                <input type="date" value={exportEndDate} onChange={(e) => setExportEndDate(e.target.value)} className="w-full px-6 py-4 bg-white border-2 border-gray-100 rounded-2xl text-xs md:text-base font-black outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all"/>
                            </div>
                            <div className="md:col-span-3">
                                <button onClick={() => handleExportExcel('personal')} className="w-full flex items-center justify-center gap-3 py-4 md:py-5 bg-emerald-600 text-white rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 transition-all active:scale-95">
                                    <FileDown className="w-5 h-5" /> TẢI BÁO CÁO
                                </button>
                            </div>
                        </div>
                    </Card>

