import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  TrendingUp, Activity, Zap, ChevronDown, ChevronUp, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const dayRequests = useMemo(() => requests.filter(r => r.date === selectedDateStr), [requests, selectedDateStr]);
  const currentSelectedRequest = useMemo(() => requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null, [requests, selectedDateStr, targetUserId]);
  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;
    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0 && dayOfWeek !== 6);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); } finally { setIsConfigUpdating(false); }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0 && dateObj.getDay() !== 6);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', range?: { start: string, end: string }) => {
    const start = range?.start || exportStartDate;
    const end = range?.end || exportEndDate;
    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => handleExportExcel(mode, { start: todayStr, end: todayStr });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr); setTargetUserId(user.id); setShowColleagueDetails(false); setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamStats = useMemo(() => {
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr));
    const totalHours = monthly.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthly.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRequests = useMemo(() => requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time)), [requests]);

  const renderCalendar = () => {
    const days = [];
    const first = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()); d++) {
        const dStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const isT = todayStr === dStr;
        const isP = new Date(dStr).getTime() < todayTime;
        const dayReqs = requests.filter(r => r.date === dStr);
        const myReq = dayReqs.find(r => r.user_id === user.id);
        const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
        const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0 && new Date(dStr).getDay() !== 6);

        days.push(
            <div key={d} onClick={() => handleDateClick(dStr)} className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-1.5 md:p-2.5 border-b border-r border-gray-100/60 ${isT ? 'bg-blue-600/5 ring-inset ring-2 ring-blue-600/80 z-20 shadow-xl' : isP ? 'bg-gray-50/30 opacity-60' : 'bg-white hover:bg-indigo-50/50'}`}>
                <div className="flex items-center gap-1.5">
                    <span className={`text-xs md:text-lg font-black ${isT ? 'bg-blue-600 text-white w-6 h-6 md:w-8 md:h-8 rounded-full flex items-center justify-center shadow-lg' : !config ? 'text-rose-500' : isP ? 'text-gray-400' : 'text-gray-900'}`}>{d}</span>
                    {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
                </div>
                <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
                    {myReq && <div className="flex items-center gap-1 bg-emerald-50 px-1 py-0.5 rounded border border-emerald-100/50"><span className="text-[7px] md:text-[9px] font-black text-emerald-700">Tôi: {myReq.total_hours}h</span></div>}
                    {otherReqs.length > 0 && <div className="flex -space-x-1.5">{otherReqs.slice(0, 3).map((r, i) => <div key={i} className="w-4 h-4 md:w-5 md:h-5 rounded-lg bg-gray-100 border border-gray-200 flex items-center justify-center text-[7px] md:text-[8px] font-black text-gray-400 uppercase">{r.users?.name?.charAt(0)}</div>)}</div>}
                </div>
                {dayReqs.length > 0 && !myReq && <div className="absolute bottom-1.5 right-1.5 text-[6px] md:text-[9px] font-black text-indigo-400 uppercase">{dayReqs.length} Đơn</div>}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 md:p-5 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase">Tăng ca</h2>
            </div>
            <div className="flex gap-2">
                <div className="flex bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`px-4 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
                <button onClick={() => handleExportToday()} className="hidden md:flex items-center gap-2 bg-emerald-600 text-white px-5 py-2 rounded-xl text-[9px] font-black uppercase"><FileSpreadsheet className="w-4 h-4" /> Xuất</button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-3xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg"><ChevronLeft className="w-5 h-5"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-widest">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg"><ChevronRight className="w-5 h-5"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{renderCalendar()}</div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-5 rounded-3xl">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1">Tổng giờ</h3>
                            <div className="flex items-end gap-1"><span className="text-3xl md:text-5xl font-black">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-5 rounded-3xl border-l-4 border-emerald-500 shadow-sm">
                            <p className="text-[8px] font-black text-gray-400 uppercase">Số ngày</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900">{myStats.count}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-5 rounded-3xl border-l-4 border-amber-500 shadow-sm">
                            <p className="text-[8px] font-black text-gray-400 uppercase">Chờ duyệt</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900">{myStats.pending}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-5 rounded-3xl border-l-4 border-indigo-500 shadow-sm">
                            <p className="text-[8px] font-black text-gray-400 uppercase">Trung bình</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900">{(myStats.total / (myStats.count || 1)).toFixed(1)}H</p>
                        </Card>
                    </div>

                    <Card className="p-6 rounded-3xl border-none shadow-sm bg-white">
                        <div className="flex items-center gap-4 mb-5">
                            <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-xl"><FileSpreadsheet className="w-5 h-5" /></div>
                            <h3 className="text-sm md:text-lg font-black uppercase">Xuất báo cáo cá nhân</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-11 items-end gap-3 bg-gray-50 p-4 rounded-2xl">
                            <div className="md:col-span-4"><input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full px-4 py-2.5 rounded-xl border border-gray-200 text-xs font-bold"/></div>
                            <div className="md:col-span-1 text-center"><ArrowRight className="w-4 h-4 text-gray-300 mx-auto" /></div>
                            <div className="md:col-span-4"><input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full px-4 py-2.5 rounded-xl border border-gray-200 text-xs font-bold"/></div>
                            <div className="md:col-span-2"><button onClick={() => handleExportExcel('personal')} className="w-full py-3 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest"><FileDown className="w-4 h-4 mx-auto" /></button></div>
                        </div>
                    </Card>

                    <Card className="p-6 rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất</h3>
                        <div className="h-48 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -30}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} /><YAxis tick={{fontSize: 8}} /><Tooltip contentStyle={{fontSize: '10px', borderRadius: '10px'}} /><Bar dataKey="hours" fill="#3b82f6" radius={[3, 3, 0, 0]} barSize={8} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    {isAdmin && (
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                            <Card className="bg-white border-l-8 border-indigo-600 p-5 rounded-3xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase">Nhân sự OT</p><p className="text-2xl md:text-4xl font-black text-gray-900">{teamStats.activeMembers}</p></Card>
                            <Card className="bg-white border-l-8 border-emerald-600 p-5 rounded-3xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase">Tổng giờ</p><p className="text-2xl md:text-4xl font-black text-gray-900">{teamStats.totalHours.toFixed(1)}</p></Card>
                            <Card className="col-span-2 md:col-span-1 bg-gradient-to-br from-indigo-600 to-indigo-800 text-white p-5 rounded-3xl"><p className="text-[8px] font-black uppercase opacity-70">Hôm nay</p><p className="text-2xl md:text-4xl font-black">{todayRequests.length} Đơn</p></Card>
                        </div>
                    )}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                        <Card className="rounded-3xl p-0 flex flex-col overflow-hidden bg-white shadow-sm border-none">
                            <div className="p-4 bg-gray-50 border-b flex justify-between items-center"><h4 className="text-[9px] font-black uppercase flex items-center gap-2"><Trophy className="w-4 h-4 text-amber-500" /> Hôm nay</h4><span className="text-[7px] font-black bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full uppercase">Live</span></div>
                            <div className="max-h-[300px] overflow-y-auto p-4 space-y-3 no-scrollbar">
                                {todayRequests.length === 0 ? <p className="text-center text-gray-300 italic text-[9px] py-10">Trống</p> : todayRequests.map((r, i) => (
                                    <div key={i} className="p-3 rounded-2xl bg-gray-50 flex items-center gap-3 border-l-4 border-blue-600">
                                        <div className="w-8 h-8 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-[10px] uppercase">{r.users?.name?.charAt(0)}</div>
                                        <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[10px] truncate uppercase">{r.users?.name}</h5><p className="text-[7px] text-gray-400 font-bold">{r.users?.employee_id}</p></div>
                                        <div className="text-right"><div className="text-[7px] font-black text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded mb-0.5">{r.start_time}-{r.end_time}</div><span className="text-sm font-black text-gray-900">{r.total_hours.toFixed(1)}h</span></div>
                                    </div>
                                ))}
                            </div>
                        </Card>
                        <Card className="rounded-3xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                             <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[9px] font-black uppercase flex items-center gap-2"><Award className="w-4 h-4 text-amber-400" /> Vinh danh T{currentDate.getMonth()+1}</h4></div>
                             <div className="p-4 space-y-2 max-h-[300px] overflow-y-auto no-scrollbar">
                                {topRankings.map((e, i) => (
                                    <div key={i} className={`p-3 rounded-2xl border flex items-center gap-3 ${i === 0 ? 'bg-amber-50 border-amber-100' : 'bg-white border-gray-50'}`}>
                                        <div className={`w-7 h-7 rounded-lg flex items-center justify-center font-black text-[10px] ${i === 0 ? 'bg-amber-500 text-white' : 'bg-gray-100 text-gray-400'}`}>{i+1}</div>
                                        <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[10px] truncate uppercase">{e.name}</h5><p className="text-[7px] text-gray-400 font-bold">{e.count} Ngày</p></div>
                                        <div className="text-right"><span className="text-sm font-black text-indigo-700">{e.hours.toFixed(1)}</span><span className="text-[7px] font-black text-gray-400 ml-0.5 uppercase">H</span></div>
                                    </div>
                                ))}
                             </div>
                        </Card>
                    </div>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-indigo-600 p-5 flex justify-between items-center text-white shrink-0">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-lg font-black uppercase leading-none">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[8px] text-indigo-200 font-bold uppercase mt-1 opacity-70">Đăng ký tăng ca</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 space-y-5 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border-2 border-indigo-50 space-y-4">
                                <h4 className="text-[9px] font-black text-indigo-900 uppercase">Loại ngày</h4>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[9px] font-black uppercase transition-all ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0 || new Date(selectedDateStr).getDay() === 6))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100' }`}><Home className="w-3.5 h-3.5" /> Nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[9px] font-black uppercase transition-all ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0 && new Date(selectedDateStr).getDay() !== 6)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100' }`}><Briefcase className="w-3.5 h-3.5" /> Làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-5">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border-2 border-amber-100 p-6 rounded-2xl text-center space-y-4 shadow-sm">
                                    <Eye className="w-8 h-8 text-amber-500 mx-auto" /><p className="text-[9px] font-black text-amber-900 uppercase leading-relaxed">Đang xem đơn đồng nghiệp.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3 bg-indigo-600 text-white text-[9px] font-black uppercase rounded-xl transition-all">ĐĂNG KÝ CHO TÔI</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && <div className="space-y-1.5"><label className="text-[9px] font-black text-gray-400 uppercase ml-1">Nhân sự:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2.5 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none appearance-none">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}
                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[7px] font-black text-gray-400 uppercase mb-1">Bắt đầu</label><input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-lg font-black text-gray-900 focus:ring-0 outline-none"/></div>
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[7px] font-black text-gray-400 uppercase mb-1">Kết thúc</label><input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-lg font-black text-gray-900 focus:ring-0 outline-none"/></div>
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1"><label className="text-[9px] font-black text-gray-400 uppercase">Nội dung</label><div className="flex items-center gap-1 bg-blue-600 text-white px-2 py-0.5 rounded-lg text-[8px] font-black animate-pulse"><Zap className="w-2.5 h-2.5" />{calculatedHours}h OT</div></div>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl text-xs h-24 resize-none outline-none font-bold text-gray-800" placeholder="Công việc bạn thực hiện..."/>
                                        <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-2 text-[8px] font-black text-blue-600 bg-white rounded-xl border border-blue-100 active:scale-95 disabled:opacity-50 uppercase tracking-widest">{isRewriting ? <Loader2 className="w-3 h-3 animate-spin"/> : <Wand2 className="w-3 h-3"/>} Tối ưu AI</button>
                                    </div>
                                    <div className="flex gap-2 pt-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 active:scale-90 shadow-sm"><Trash2 className="w-5 h-5"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl text-[9px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-5 rounded-2xl"><Trash2 className="w-8 h-8"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase">Xóa đơn?</h3>
                    <p className="text-[9px] text-gray-400 font-bold uppercase opacity-60 mb-8">Thao tác này sẽ gỡ bỏ dữ liệu vĩnh viễn.</p>
                    <div className="flex flex-col gap-2">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[9px] uppercase shadow-lg">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[9px] uppercase">HỦY BỎ</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, Wand2, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  TrendingUp, Activity, Zap, ChevronDown, ChevronUp, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const dayRequests = useMemo(() => requests.filter(r => r.date === selectedDateStr), [requests, selectedDateStr]);
  const currentSelectedRequest = useMemo(() => requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null, [requests, selectedDateStr, targetUserId]);
  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;
    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0 && dayOfWeek !== 6);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); } finally { setIsConfigUpdating(false); }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0 && dateObj.getDay() !== 6);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', range?: { start: string, end: string }) => {
    const start = range?.start || exportStartDate;
    const end = range?.end || exportEndDate;
    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => handleExportExcel(mode, { start: todayStr, end: todayStr });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr); setTargetUserId(user.id); setShowColleagueDetails(false); setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamStats = useMemo(() => {
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr));
    const totalHours = monthly.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthly.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRequests = useMemo(() => requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time)), [requests]);

  const renderCalendar = () => {
    const days = [];
    const first = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()); d++) {
        const dStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const isT = todayStr === dStr;
        const isP = new Date(dStr).getTime() < todayTime;
        const isF = new Date(dStr).getTime() > todayTime;
        const dayReqs = requests.filter(r => r.date === dStr);
        const myReq = dayReqs.find(r => r.user_id === user.id);
        const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
        const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0 && new Date(dStr).getDay() !== 6);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dStr)} 
                className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-1.5 md:p-2.5 border-b border-r border-gray-100/60 
                  ${isT ? 'bg-blue-600/[0.07] ring-inset ring-2 ring-blue-600/60 z-20 shadow-lg' : 
                    isF ? 'bg-white hover:bg-indigo-50/50' : 
                    'bg-gray-50/40 opacity-50 grayscale-[20%]'
                  }`}
            >
                <div className="flex items-center gap-1.5">
                    <span className={`text-xs md:text-lg font-black transition-transform group-hover:scale-110 
                      ${isT ? 'bg-blue-600 text-white w-6 h-6 md:w-8 md:h-8 rounded-full flex items-center justify-center shadow-lg shadow-blue-400/40' : 
                        !config ? 'text-rose-500' : isP ? 'text-gray-400' : 'text-gray-900'}`}
                    >
                        {d}
                    </span>
                    {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
                </div>
                <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
                    {myReq && <div className="flex items-center gap-1 bg-emerald-50 px-1 py-0.5 rounded border border-emerald-100/50"><span className="text-[7px] md:text-[9px] font-black text-emerald-700">Tôi: {myReq.total_hours}h</span></div>}
                    {otherReqs.length > 0 && (
                      <div className="flex -space-x-1.5">
                        {otherReqs.slice(0, 3).map((r, i) => (
                          <div key={i} className="w-4 h-4 md:w-5 md:h-5 rounded-lg bg-gray-100 border border-gray-200 flex items-center justify-center text-[7px] md:text-[8px] font-black text-gray-400 uppercase shadow-sm">
                            {r.users?.name?.charAt(0)}
                          </div>
                        ))}
                      </div>
                    )}
                </div>
                {dayReqs.length > 0 && !myReq && <div className="absolute bottom-1.5 right-1.5 text-[6px] md:text-[9px] font-black text-indigo-400 uppercase">{dayReqs.length} Đơn</div>}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-5 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
                <button onClick={() => handleExportToday()} className="hidden md:flex items-center gap-2 bg-emerald-600 text-white px-5 py-2 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 active:scale-95"><FileSpreadsheet className="w-4 h-4" /> Xuất</button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{renderCalendar()}</div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 md:p-5 rounded-2xl md:rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-3xl md:text-5xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-amber-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Đang chờ duyệt</p>
                            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{myStats.pending}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-indigo-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Trung bình/ngày</p>
                            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{(myStats.total / (myStats.count || 1)).toFixed(1)}<span className="text-[10px] ml-1 text-gray-300">H</span></p>
                        </Card>
                    </div>

                    <Card className="p-5 md:p-6 rounded-2xl md:rounded-3xl border-none shadow-sm bg-white">
                        <div className="flex items-center gap-3 mb-5">
                            <div className="p-2 bg-emerald-50 text-emerald-600 rounded-xl"><FileSpreadsheet className="w-5 h-5" /></div>
                            <h3 className="text-sm md:text-lg font-black uppercase tracking-tight">Xuất báo cáo cá nhân</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-11 items-end gap-3 bg-gray-50/50 p-4 rounded-xl md:rounded-2xl border border-gray-100">
                            <div className="md:col-span-4"><input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full px-4 py-2.5 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
                            <div className="md:col-span-1 text-center hidden md:block"><ArrowRight className="w-4 h-4 text-gray-300 mx-auto" /></div>
                            <div className="md:col-span-4"><input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full px-4 py-2.5 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
                            <div className="md:col-span-2"><button onClick={() => handleExportExcel('personal')} className="w-full py-3 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-md shadow-emerald-50 active:scale-95"><FileDown className="w-4 h-4 mx-auto" /></button></div>
                        </div>
                    </Card>

                    <Card className="p-5 md:p-6 rounded-2xl md:rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất tháng</h3>
                        <div className="h-44 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(59, 130, 246, 0.05)'}}/><Bar dataKey="hours" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={window.innerWidth < 640 ? 6 : 12} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    {isAdmin && (
                        <div className="grid grid-cols-2 lg:grid-cols-3 gap-3 md:gap-4">
                            <Card className="bg-white border-l-4 md:border-l-8 border-indigo-600 p-4 md:p-5 rounded-2xl md:rounded-3xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase tracking-wider mb-1">Nhân sự OT</p><p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{teamStats.activeMembers}</p></Card>
                            <Card className="bg-white border-l-4 md:border-l-8 border-emerald-600 p-4 md:p-5 rounded-2xl md:rounded-3xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase tracking-wider mb-1">Tổng quỹ giờ</p><p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{teamStats.totalHours.toFixed(1)}</p></Card>
                            <Card className="col-span-2 md:col-span-1 bg-gradient-to-br from-indigo-600 to-indigo-800 text-white p-4 md:p-5 rounded-2xl md:rounded-3xl shadow-lg"><p className="text-[8px] font-black uppercase opacity-70 tracking-wider mb-1">Đăng ký hôm nay</p><p className="text-xl md:text-4xl font-black tabular-nums">{todayRequests.length} Đơn</p></Card>
                        </div>
                    )}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                        <Card className="rounded-2xl md:rounded-3xl p-0 flex flex-col overflow-hidden bg-white shadow-sm border-none">
                            <div className="p-4 bg-gray-50/50 border-b flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Trophy className="w-4 h-4 text-amber-500" /> Hoạt động hôm nay</h4><span className="text-[7px] font-black bg-blue-100 text-blue-700 px-2.5 py-1 rounded-full uppercase ring-1 ring-blue-200">Live</span></div>
                            <div className="max-h-[300px] md:max-h-[400px] overflow-y-auto p-3 md:p-4 space-y-2 md:space-y-3 no-scrollbar">
                                {todayRequests.length === 0 ? <div className="py-16 text-center"><p className="text-gray-300 italic text-[10px] uppercase tracking-widest">Danh sách trống</p></div> : todayRequests.map((r, i) => (
                                    <div key={i} className="p-3 md:p-3.5 rounded-xl md:rounded-2xl bg-gray-50/50 hover:bg-white transition-all border border-gray-100 flex items-center gap-3 md:gap-4 border-l-4 border-l-blue-600 group">
                                        <div className="w-9 h-9 md:w-12 md:h-12 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-[11px] md:text-lg uppercase shadow-lg shadow-indigo-100 group-hover:scale-105 transition-transform">{r.users?.name?.charAt(0)}</div>
                                        <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] md:text-sm truncate uppercase tracking-tight leading-tight">{r.users?.name}</h5><p className="text-[8px] md:text-[9px] text-gray-400 font-bold tracking-widest mt-0.5">{r.users?.employee_id}</p></div>
                                        <div className="text-right flex flex-col items-end"><div className="text-[8px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-md mb-1 border border-blue-100">{r.start_time}-{r.end_time}</div><span className="text-sm md:text-xl font-black text-gray-900 tabular-nums">{r.total_hours.toFixed(1)}h</span></div>
                                    </div>
                                ))}
                            </div>
                        </Card>
                        <Card className="rounded-2xl md:rounded-3xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                             <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Award className="w-4 h-4 text-amber-400 drop-shadow-sm" /> Top Chăm chỉ T{currentDate.getMonth()+1}</h4></div>
                             <div className="p-3 md:p-4 space-y-2 max-h-[300px] md:max-h-[400px] overflow-y-auto no-scrollbar">
                                {topRankings.map((e, i) => (
                                    <div key={i} className={`p-3 md:p-4 rounded-xl md:rounded-2xl border flex items-center gap-3 md:gap-4 transition-all ${i === 0 ? 'bg-amber-50/30 border-amber-200 shadow-sm' : 'bg-white border-gray-100'}`}>
                                        <div className={`w-8 h-8 md:w-11 md:h-11 rounded-xl flex items-center justify-center font-black text-[10px] md:text-base ${i === 0 ? 'bg-amber-500 text-white shadow-md' : 'bg-gray-100 text-gray-400'}`}>{i+1}</div>
                                        <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] md:text-sm truncate uppercase tracking-tight">{e.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày</p></div>
                                        <div className="text-right"><span className="text-sm md:text-2xl font-black text-indigo-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[8px] md:text-[10px] font-black text-gray-300 ml-1 uppercase">H</span></div>
                                    </div>
                                ))}
                             </div>
                        </Card>
                    </div>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-indigo-600 p-4 md:p-6 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2.5"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-lg md:text-xl font-black uppercase leading-none tracking-tight">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[8px] md:text-[10px] text-indigo-200 font-bold uppercase mt-1.5 opacity-70 tracking-widest">Chi tiết đăng ký</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2.5 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5 md:w-6 md:h-6"/></button>
                    </div>

                    <div className="p-5 md:p-6 space-y-5 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest">Loại hình ngày</h4>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-3 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0 || new Date(selectedDateStr).getDay() === 6))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Home className="w-4 h-4" /> Nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-3 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0 && new Date(selectedDateStr).getDay() !== 6)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Briefcase className="w-4 h-4" /> Làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-5">
                            {isViewOnly ? (
                                <div className="bg-amber-50/50 border-2 border-amber-100 p-6 rounded-2xl text-center space-y-4 shadow-sm">
                                    <Eye className="w-8 h-8 text-amber-500 mx-auto" /><p className="text-[10px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Thông tin đăng ký của đồng nghiệp.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3.5 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl transition-all shadow-lg shadow-indigo-100 active:scale-95">ĐĂNG KÝ CHO TÔI</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && <div className="space-y-2"><label className="text-[10px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}
                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="bg-white p-3 md:p-4 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Bắt đầu</label><input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl md:text-2xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                        <div className="bg-white p-3 md:p-4 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl md:text-2xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                    </div>
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung thực hiện</label><div className="flex items-center gap-1.5 bg-blue-600 text-white px-3 py-1 rounded-lg text-[9px] font-black shadow-md"><Zap className="w-3.5 h-3.5" />{calculatedHours}h OT</div></div>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 md:p-5 bg-white border border-gray-100 rounded-2xl text-xs md:text-sm h-28 md:h-36 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-600 transition-all" placeholder="Nhập tóm tắt công việc..."/>
                                        <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-3 text-[9px] font-black text-blue-600 bg-white rounded-xl border-2 border-blue-50 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} Tối ưu nội dung AI</button>
                                    </div>
                                    <div className="flex gap-3 pt-3">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 md:p-5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-5 h-5 md:w-6 md:h-6"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 md:py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-50 text-[10px] md:text-xs uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-6 h-6 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl shadow-lg shadow-rose-50"><Trash2 className="w-9 h-9"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-8 leading-relaxed">Dữ liệu sẽ được xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg shadow-rose-100 active:scale-95">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, ChevronDown, ChevronUp, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeToNumberParts(timeStr);
  return h + m / 60;
};

const timeToNumberParts = (timeStr: string) => {
  return timeStr.split(':').map(Number);
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showColleagueDetails, setShowColleagueDetails] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const dayRequests = useMemo(() => requests.filter(r => r.date === selectedDateStr), [requests, selectedDateStr]);
  const currentSelectedRequest = useMemo(() => requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null, [requests, selectedDateStr, targetUserId]);
  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;
    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0 && dayOfWeek !== 6);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0 && dateObj.getDay() !== 6);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', range?: { start: string, end: string }) => {
    const start = range?.start || exportStartDate;
    const end = range?.end || exportEndDate;
    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => handleExportExcel(mode, { start: todayStr, end: todayStr });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr); setTargetUserId(user.id); setShowColleagueDetails(false); setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamStats = useMemo(() => {
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr));
    const totalHours = monthly.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthly.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRequestsSummary = useMemo(() => requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time)), [requests]);

  const renderCalendar = () => {
    const days = [];
    const first = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()); d++) {
        const dStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const isT = todayStr === dStr;
        const isP = new Date(dStr).getTime() < todayTime;
        const isF = new Date(dStr).getTime() > todayTime;
        const dayReqs = requests.filter(r => r.date === dStr);
        const myReq = dayReqs.find(r => r.user_id === user.id);
        const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
        const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0 && new Date(dStr).getDay() !== 6);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dStr)} 
                className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-1.5 md:p-2.5 border-b border-r border-gray-100/60 
                  ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-20 shadow-[0_0_15px_rgba(244,63,94,0.15)]' : 
                    isF ? 'bg-white ring-inset ring-1 ring-sky-400/60 hover:bg-sky-50/30' : 
                    'bg-gray-50/40 opacity-50 grayscale-[20%]'
                  }`}
            >
                <div className="flex items-center gap-1.5">
                    <span className={`text-xs md:text-lg font-black transition-transform group-hover:scale-110 
                      ${isT ? 'bg-rose-500 text-white w-6 h-6 md:w-8 md:h-8 rounded-full flex items-center justify-center shadow-lg' : 
                        isF ? 'text-sky-600' :
                        !config ? 'text-rose-500' : isP ? 'text-gray-400' : 'text-gray-900'}`}
                    >
                        {d}
                    </span>
                    {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
                </div>
                <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
                    {myReq && <div className="flex items-center gap-1 bg-emerald-50 px-1 py-0.5 rounded border border-emerald-100/50"><span className="text-[7px] md:text-[9px] font-black text-emerald-700">Tôi: {myReq.total_hours}h</span></div>}
                    {otherReqs.length > 0 && (
                      <div className="flex -space-x-1.5">
                        {otherReqs.slice(0, 3).map((r, i) => (
                          <div key={i} className="w-4 h-4 md:w-5 md:h-5 rounded-lg bg-gray-100 border border-gray-200 flex items-center justify-center text-[7px] md:text-[8px] font-black text-gray-400 uppercase shadow-sm">
                            {r.users?.name?.charAt(0)}
                          </div>
                        ))}
                      </div>
                    )}
                </div>
                {dayReqs.length > 0 && !myReq && <div className={`absolute bottom-1.5 right-1.5 text-[6px] md:text-[9px] font-black uppercase ${isF ? 'text-sky-500' : 'text-indigo-400'}`}>{dayReqs.length} Đơn</div>}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-4 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
                <button onClick={() => handleExportToday()} className="hidden md:flex items-center gap-2 bg-emerald-600 text-white px-5 py-2 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 active:scale-95"><FileSpreadsheet className="w-4 h-4" /> Xuất</button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{renderCalendar()}</div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 md:p-5 rounded-2xl md:rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-2xl md:text-4xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-amber-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Đang chờ duyệt</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.pending}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-indigo-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Trung bình/ngày</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{(myStats.total / (myStats.count || 1)).toFixed(1)}<span className="text-[10px] ml-1 text-gray-300">H</span></p>
                        </Card>
                    </div>

                    <Card className="p-4 md:p-6 rounded-2xl md:rounded-3xl border-none shadow-sm bg-white">
                        <div className="flex items-center gap-3 mb-5">
                            <div className="p-2 bg-emerald-50 text-emerald-600 rounded-xl"><FileSpreadsheet className="w-5 h-5" /></div>
                            <h3 className="text-sm md:text-lg font-black uppercase tracking-tight">Xuất báo cáo cá nhân</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-11 items-end gap-3 bg-gray-50/50 p-3 rounded-xl md:rounded-2xl border border-gray-100">
                            <div className="md:col-span-4"><input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
                            <div className="md:col-span-1 text-center hidden md:block"><ArrowRight className="w-4 h-4 text-gray-300 mx-auto" /></div>
                            <div className="md:col-span-4"><input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
                            <div className="md:col-span-2"><button onClick={() => handleExportExcel('personal')} className="w-full py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-md active:scale-95"><FileDown className="w-4 h-4 mx-auto" /></button></div>
                        </div>
                    </Card>

                    <Card className="p-4 md:p-6 rounded-2xl md:rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất tháng</h3>
                        <div className="h-44 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(59, 130, 246, 0.05)'}}/><Bar dataKey="hours" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={window.innerWidth < 640 ? 6 : 12} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    {isAdmin && (
                        <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
                            <Card className="bg-white border-l-4 border-indigo-600 p-4 rounded-2xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase tracking-wider mb-1">Nhân sự OT</p><p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{teamStats.activeMembers}</p></Card>
                            <Card className="bg-white border-l-4 border-emerald-600 p-4 rounded-2xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase tracking-wider mb-1">Tổng quỹ giờ</p><p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{teamStats.totalHours.toFixed(1)}</p></Card>
                            <Card className="col-span-2 md:col-span-1 bg-gradient-to-br from-indigo-600 to-indigo-800 text-white p-4 rounded-2xl shadow-lg"><p className="text-[8px] font-black uppercase opacity-70 tracking-wider mb-1">Hôm nay</p><p className="text-xl md:text-3xl font-black tabular-nums">{todayRequestsSummary.length} Đơn</p></Card>
                        </div>
                    )}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                        <Card className="rounded-2xl p-0 flex flex-col overflow-hidden bg-white shadow-sm border-none">
                            <div className="p-4 bg-gray-50/50 border-b flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Trophy className="w-4 h-4 text-amber-500" /> Hoạt động hôm nay</h4><span className="text-[7px] font-black bg-blue-100 text-blue-700 px-2.5 py-1 rounded-full uppercase ring-1 ring-blue-200">Live</span></div>
                            <div className="max-h-[300px] md:max-h-[400px] overflow-y-auto p-3 space-y-2 no-scrollbar">
                                {todayRequestsSummary.length === 0 ? <div className="py-16 text-center"><p className="text-gray-300 italic text-[10px] uppercase tracking-widest">Danh sách trống</p></div> : todayRequestsSummary.map((r, i) => (
                                    <div key={i} className="p-3 rounded-xl bg-gray-50/50 hover:bg-white transition-all border border-gray-100 flex items-center gap-3 border-l-4 border-l-blue-600 group">
                                        <div className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-[11px] uppercase group-hover:scale-105 transition-transform">{r.users?.name?.charAt(0)}</div>
                                        <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight leading-tight">{r.users?.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{r.users?.employee_id}</p></div>
                                        <div className="text-right flex flex-col items-end"><div className="text-[8px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-md mb-1 border border-blue-100">{r.start_time}-{r.end_time}</div><span className="text-sm font-black text-gray-900 tabular-nums">{r.total_hours.toFixed(1)}h</span></div>
                                    </div>
                                ))}
                            </div>
                        </Card>
                        <Card className="rounded-2xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                             <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Award className="w-4 h-4 text-amber-400 drop-shadow-sm" /> Top Chăm chỉ T{currentDate.getMonth()+1}</h4></div>
                             <div className="p-3 space-y-2 max-h-[300px] md:max-h-[400px] overflow-y-auto no-scrollbar">
                                {topRankings.map((e, i) => (
                                    <div key={i} className={`p-3 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/30 border-amber-200 shadow-sm' : 'bg-white border-gray-100'}`}>
                                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-[10px] ${i === 0 ? 'bg-amber-500 text-white shadow-md' : 'bg-gray-100 text-gray-400'}`}>{i+1}</div>
                                        <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight">{e.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày</p></div>
                                        <div className="text-right"><span className="text-sm font-black text-indigo-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[8px] font-black text-gray-300 ml-1 uppercase">H</span></div>
                                    </div>
                                ))}
                             </div>
                        </Card>
                    </div>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-indigo-600 p-4 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2.5"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-lg font-black uppercase leading-none tracking-tight">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[8px] text-indigo-200 font-bold uppercase mt-1 opacity-70 tracking-widest">Chi tiết đăng ký</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 space-y-4 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[9px] font-black text-indigo-900 uppercase tracking-widest">Loại hình ngày</h4>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0 || new Date(selectedDateStr).getDay() === 6))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Home className="w-4 h-4" /> Nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0 && new Date(selectedDateStr).getDay() !== 6)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Briefcase className="w-4 h-4" /> Làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border-2 border-amber-100 p-6 rounded-2xl text-center space-y-4 shadow-sm">
                                    <Eye className="w-8 h-8 text-amber-500 mx-auto" /><p className="text-[10px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Thông tin đăng ký của đồng nghiệp.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl transition-all shadow-lg active:scale-95">ĐĂNG KÝ CHO TÔI</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && <div className="space-y-1.5"><label className="text-[9px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}
                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Bắt đầu</label><input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung thực hiện</label><div className="flex items-center gap-1.5 bg-blue-600 text-white px-2 py-0.5 rounded-lg text-[8px] font-black shadow-md"><Zap className="w-3 h-3" />{calculatedHours}h OT</div></div>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl text-xs h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-600 transition-all" placeholder="Nhập tóm tắt công việc..."/>
                                        <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-2 text-[9px] font-black text-blue-600 bg-white rounded-xl border-2 border-blue-50 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} Tối ưu nội dung AI</button>
                                    </div>
                                    <div className="flex gap-2 pt-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-5 h-5"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl text-[10px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl shadow-lg shadow-rose-50"><Trash2 className="w-9 h-9"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-8 leading-relaxed">Dữ liệu sẽ được xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg active:scale-95">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

// Hàm tạo màu sắc nét dựa trên tên
const getAvatarColor = (name: string) => {
  const colors = [
    'bg-blue-600', 'bg-indigo-600', 'bg-violet-600', 
    'bg-emerald-600', 'bg-rose-600', 'bg-amber-600', 'bg-sky-600'
  ];
  let hash = 0;
  for (let i = 0; i < name.length; i++) {
    hash = name.charCodeAt(i) + ((hash << 5) - hash);
  }
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);
  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const currentSelectedRequest = useMemo(() => requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null, [requests, selectedDateStr, targetUserId]);
  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  useEffect(() => {
    if (!selectedDateStr) return;
    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0 && dayOfWeek !== 6);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(dateStr);
    const isWorkDay = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0 && dateObj.getDay() !== 6);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', range?: { start: string, end: string }) => {
    const start = range?.start || exportStartDate;
    const end = range?.end || exportEndDate;
    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}.xlsx`);
  };

  const handleExportToday = (mode: 'personal' | 'all' = 'personal') => handleExportExcel(mode, { start: todayStr, end: todayStr });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr); setTargetUserId(user.id); setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamStats = useMemo(() => {
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr));
    const totalHours = monthly.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthly.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRequestsSummary = useMemo(() => requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time)), [requests]);

  const renderCalendar = () => {
    const days = [];
    const first = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth()); d++) {
        const dStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const isT = todayStr === dStr;
        const isP = new Date(dStr).getTime() < todayTime;
        const isF = new Date(dStr).getTime() > todayTime;
        const dayReqs = requests.filter(r => r.date === dStr);
        const myReq = dayReqs.find(r => r.user_id === user.id);
        const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
        const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0 && new Date(dStr).getDay() !== 6);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dStr)} 
                className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-1.5 md:p-2.5 border-b border-r border-gray-100/60 
                  ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-20 shadow-[0_0_15px_rgba(244,63,94,0.15)]' : 
                    isF ? 'bg-white ring-inset ring-1 ring-sky-400/60 hover:bg-sky-50/30' : 
                    'bg-gray-50/40 opacity-50 grayscale-[20%]'
                  }`}
            >
                <div className="flex items-center gap-1.5">
                    <span className={`text-xs md:text-lg font-black transition-transform group-hover:scale-110 
                      ${isT ? 'bg-rose-500 text-white w-6 h-6 md:w-8 md:h-8 rounded-full flex items-center justify-center shadow-lg' : 
                        isF ? 'text-sky-600' :
                        !config ? 'text-rose-500' : isP ? 'text-gray-400' : 'text-gray-900'}`}
                    >
                        {d}
                    </span>
                    {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
                </div>
                <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
                    {myReq && <div className="flex items-center gap-1 bg-emerald-50 px-1 py-0.5 rounded border border-emerald-100/50"><span className="text-[7px] md:text-[9px] font-black text-emerald-700">Tôi: {myReq.total_hours}h</span></div>}
                    {otherReqs.length > 0 && (
                      <div className="flex -space-x-1.5">
                        {otherReqs.slice(0, 3).map((r, i) => (
                          <div key={i} className={`w-4 h-4 md:w-5 md:h-5 rounded-lg ${getAvatarColor(r.users?.name || '')} border-2 border-white flex items-center justify-center text-[7px] md:text-[8px] font-black text-white uppercase shadow-sm antialiased`}>
                            {r.users?.name?.charAt(0)}
                          </div>
                        ))}
                      </div>
                    )}
                </div>
                {dayReqs.length > 0 && !myReq && <div className={`absolute bottom-1.5 right-1.5 text-[6px] md:text-[9px] font-black uppercase ${isF ? 'text-sky-500' : 'text-indigo-400'}`}>{dayReqs.length} Đơn</div>}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-4 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
                <button onClick={() => handleExportToday()} className="hidden md:flex items-center gap-2 bg-emerald-600 text-white px-5 py-2 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 active:scale-95"><FileSpreadsheet className="w-4 h-4" /> Xuất</button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{renderCalendar()}</div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 md:p-5 rounded-2xl md:rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-2xl md:text-4xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-amber-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Đang chờ duyệt</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.pending}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-indigo-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Trung bình/ngày</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{(myStats.total / (myStats.count || 1)).toFixed(1)}<span className="text-[10px] ml-1 text-gray-300">H</span></p>
                        </Card>
                    </div>

                    <Card className="p-4 md:p-6 rounded-2xl md:rounded-3xl border-none shadow-sm bg-white">
                        <div className="flex items-center gap-3 mb-5">
                            <div className="p-2 bg-emerald-50 text-emerald-600 rounded-xl"><FileSpreadsheet className="w-5 h-5" /></div>
                            <h3 className="text-sm md:text-lg font-black uppercase tracking-tight">Xuất báo cáo cá nhân</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-11 items-end gap-3 bg-gray-50/50 p-3 rounded-xl md:rounded-2xl border border-gray-100">
                            <div className="md:col-span-4"><input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
                            <div className="md:col-span-1 text-center hidden md:block"><ArrowRight className="w-4 h-4 text-gray-300 mx-auto" /></div>
                            <div className="md:col-span-4"><input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
