                                <>
                                    {isAdmin && <div className="space-y-1.5"><label className="text-[9px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}
                                    <div className="grid grid-cols-2 gap-3">
