                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung thực hiện</label><div className="flex items-center gap-1.5 bg-blue-600 text-white px-2 py-0.5 rounded-lg text-[8px] font-black shadow-md"><Zap className="w-3 h-3" />{calculatedHours}h OT</div></div>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl text-xs h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-600 transition-all" placeholder="Nhập tóm tắt công việc..."/>
                                        <button type="button" onClick={async () => { if(!reason) return; setIsRewriting(true); setReason(await rewriteOvertimeReason(reason)); setIsRewriting(false); }} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-2 text-[9px] font-black text-blue-600 bg-white rounded-xl border-2 border-blue-50 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} Tối ưu nội dung AI</button>
                                    </div>
                                    <div className="flex gap-2 pt-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-5 h-5"/></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl text-[10px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl shadow-lg shadow-rose-50"><Trash2 className="w-9 h-9"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-8 leading-relaxed">Dữ liệu sẽ được xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg active:scale-95">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
