import React, { useState, useEffect, useMemo, useCallback, memo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

const getColleagueColor = (name: string) => {
  const colors = ['bg-blue-600', 'bg-indigo-600', 'bg-violet-600', 'bg-purple-600', 'bg-sky-600', 'bg-blue-500'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

// Component Avatar tối ưu
const RegisteredAvatar = memo(({ name, isMe, size = 'sm' }: { name: string, isMe: boolean, size?: 'xs' | 'sm' | 'md' }) => {
  const sizeClasses = {
    xs: 'w-4 h-4 md:w-5 md:h-5 text-[7px] md:text-[8px]',
    sm: 'w-8 h-8 md:w-9 md:h-9 text-[10px] md:text-xs',
    md: 'w-10 h-10 md:w-12 md:h-12 text-xs md:text-sm'
  };
  const bgColor = isMe ? 'bg-emerald-500' : getColleagueColor(name);
  return (
    <div className="relative group/avatar inline-block">
      <div className={`${sizeClasses[size]} rounded-xl ${bgColor} text-white flex items-center justify-center font-black uppercase shadow-lg border-2 border-white antialiased transition-transform group-hover/avatar:scale-110`}>
        {name.charAt(0)}
      </div>
      {isMe && (
        <div className={`absolute -bottom-0.5 -right-0.5 bg-blue-500 text-white rounded-full border-2 border-white shadow-sm flex items-center justify-center ${size === 'xs' ? 'w-2 h-2 md:w-2.5 md:h-2.5' : 'w-4 h-4 md:w-4.5 md:h-4.5'}`}>
          <Check className={`${size === 'xs' ? 'w-1 h-1 md:w-1.5 md:h-1.5' : 'w-2.5 h-2.5 md:w-3 md:h-3'} stroke-[4]`} />
        </div>
      )}
    </div>
  );
});

// Component Lịch được tối ưu để không re-render khi gõ phím
const CalendarGrid = memo(({ 
  currentDate, 
  requests, 
  dayConfigs, 
  userId, 
  userName, 
  onDateClick 
}: { 
  currentDate: Date, 
  requests: OvertimeRequest[], 
  dayConfigs: Record<string, boolean>, 
  userId: string,
  userName: string,
  onDateClick: (d: string) => void 
}) => {
  const days = [];
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const first = getFirstDayOfMonth(year, month);
  const offset = first === 0 ? 6 : first - 1;

  for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);

  for (let d = 1; d <= getDaysInMonth(year, month); d++) {
    const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const isT = todayStr === dStr;
    const isP = new Date(dStr).getTime() < todayTime;
    const isF = new Date(dStr).getTime() > todayTime;
    const dayReqs = requests.filter(r => r.date === dStr);
    const myReq = dayReqs.find(r => r.user_id === userId);
    const otherReqs = dayReqs.filter(r => r.user_id !== userId);
    const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

    days.push(
      <div 
        key={d} 
        onClick={() => onDateClick(dStr)} 
        className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-1.5 md:p-2.5 border-b border-r border-gray-100/60 
          ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-20 shadow-[0_0_15px_rgba(244,63,94,0.15)]' : 
            isF ? 'bg-white ring-inset ring-1 ring-sky-400/60 hover:bg-sky-50/30' : 
            'bg-gray-50/40 opacity-50 grayscale-[20%]'
          }`}
      >
        <div className="flex items-center justify-between">
          <span className={`text-xs md:text-lg font-black transition-transform group-hover:scale-110 
            ${isT ? 'bg-rose-500 text-white w-6 h-6 md:w-8 md:h-8 rounded-full flex items-center justify-center shadow-lg' : 
              isF ? 'text-sky-600' :
              !config ? 'text-rose-500' : isP ? 'text-gray-400' : 'text-gray-900'}`}
          >
            {d}
          </span>
          {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
        </div>
        <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
          {(myReq || otherReqs.length > 0) && (
            <div className="flex -space-x-1.5 items-center">
              {myReq && <RegisteredAvatar name={userName} isMe={true} size="xs" />}
              {otherReqs.slice(0, myReq ? 2 : 3).map((r, i) => (
                <RegisteredAvatar key={i} name={r.users?.name || '?'} isMe={false} size="xs" />
              ))}
              {(dayReqs.length > 3) && (
                <div className="w-4 h-4 md:w-5 md:h-5 rounded-lg bg-gray-100 border border-white flex items-center justify-center text-[6px] md:text-[8px] font-black text-gray-400 shadow-sm z-10">
                  +{dayReqs.length - 3}
                </div>
              )}
            </div>
          )}
        </div>
        {dayReqs.length > 0 && !myReq && <div className={`absolute bottom-1.5 right-1.5 text-[6px] md:text-[9px] font-black uppercase ${isF ? 'text-sky-500' : 'text-indigo-400'}`}>{dayReqs.length} Đơn</div>}
      </div>
    );
  }
  return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{days}</div>;
});

