export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  const fetchRequests = useCallback(async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [user.id, user.role, activeTab]);

  useEffect(() => {
    fetchRequests();
  }, [fetchRequests]);

  const filteredRequests = useMemo(() => {
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      returned: 2,
      rejected: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      return matchesSearch && matchesStatus;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    // Lưu lại trạng thái cũ để rollback nếu lỗi
    const previousRequests = [...requests];
    setProcessingId(id);

    // Optimistic Update: Cập nhật UI ngay lập tức
    if (action !== 'cancel') {
        setRequests(prev => prev.map(req => {
            if (req.id === id) {
                const newStatus = action === 'approve' ? 'approved' : action === 'return' ? 'returned' : 'rejected';
                return { ...req, status: newStatus as any };
            }
            return req;
        }));
    } else {
        setRequests(prev => prev.filter(req => req.id !== id));
    }

    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
        await Promise.all([
          supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId),
          supabase.from('requests').update({ status: 'approved' }).eq('id', id)
        ]);
      } else if (action === 'return') {
        // Thu hồi: Chạy song song để nhanh hơn
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await Promise.all([
          supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId),
          supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id)
        ]);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }

      // Phát sự kiện làm mới badge mà không cần fetch lại toàn bộ bảng
      window.dispatchEvent(new CustomEvent('refresh-counts'));
    } catch (e: any) {
      alert(e.message);
      setRequests(previousRequests); // Rollback nếu lỗi
    } finally {
      setProcessingId(null);
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white p-6 md:p-8 rounded-3xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className="p-3 md:p-4 bg-blue-600 rounded-2xl shadow-lg shadow-blue-100 text-white">
            <RefreshCw className="w-6 h-6 md:w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-bold text-gray-900 tracking-tight">Quản lý mượn trả</h2>
            <p className="text-xs text-gray-500 mt-1">Phê duyệt và giám sát yêu cầu thiết bị</p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'all' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Tất cả đơn</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Đơn của tôi</button>
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 group">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm nhân viên, đồ..." 
            className="w-full pl-11 pr-4 py-3.5 bg-white border border-gray-100 rounded-2xl text-sm font-medium outline-none focus:ring-4 focus:ring-blue-500/5 focus:border-blue-500 transition-all shadow-sm" 
          />
        </div>
        <select 
          value={filterStatus} 
          onChange={e => setFilterStatus(e.target.value)} 
          className="px-5 py-3.5 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none cursor-pointer shadow-sm focus:border-blue-500 transition-all"
        >
          <option value="all">Trạng thái</option>
          <option value="pending">Đang chờ duyệt</option>
          <option value="approved">Đang mượn</option>
          <option value="returned">Đã trả đồ</option>
          <option value="rejected">Đã từ chối</option>
        </select>
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-xl rounded-3xl bg-white">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-gray-100">
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Người mượn</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Thiết bị</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Thời gian</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-center">Trạng thái</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading && requests.length === 0 ? (
                <tr><td colSpan={5} className="py-24 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={5} className="py-24 text-center text-gray-300 font-medium italic">Không có dữ liệu yêu cầu</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <RequestRow 
                    key={req.id} 
                    req={req} 
                    isAdmin={user.role === 'admin'} 
                    activeTab={activeTab} 
                    processingId={processingId} 
                    onAction={handleAction} 
                  />
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

