// Component Lịch riêng biệt để tránh render khi gõ phím
const CalendarGrid = memo(({ 
  currentDate, 
  requests, 
  dayConfigs, 
  userId, 
  userName, 
  onDateClick 
}: { 
  currentDate: Date, 
  requests: OvertimeRequest[], 
  dayConfigs: Record<string, boolean>, 
  userId: string,
  userName: string,
  onDateClick: (d: string) => void 
}) => {
  const days = [];
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const first = getFirstDayOfMonth(year, month);
  const offset = first === 0 ? 6 : first - 1;

  for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);

  for (let d = 1; d <= getDaysInMonth(year, month); d++) {
    const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const isT = todayStr === dStr;
    const isP = new Date(dStr).getTime() < todayTime;
    const isF = new Date(dStr).getTime() > todayTime;
    const dayReqs = requests.filter(r => r.date === dStr);
    const myReq = dayReqs.find(r => r.user_id === userId);
    const otherReqs = dayReqs.filter(r => r.user_id !== userId);
    const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

    days.push(
      <div 
        key={d} 
        onClick={() => onDateClick(dStr)} 
        className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-1.5 md:p-2.5 border-b border-r border-gray-100/60 
          ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-20 shadow-[0_0_15px_rgba(244,63,94,0.15)]' : 
            isF ? 'bg-white ring-inset ring-1 ring-sky-400/60 hover:bg-sky-50/30' : 
            'bg-gray-50/40 opacity-50 grayscale-[20%]'
          }`}
      >
        <div className="flex items-center justify-between">
          <span className={`text-xs md:text-lg font-black transition-transform group-hover:scale-110 
            ${isT ? 'bg-rose-500 text-white w-6 h-6 md:w-8 md:h-8 rounded-full flex items-center justify-center shadow-lg' : 
              isF ? 'text-sky-600' :
              !config ? 'text-rose-500' : isP ? 'text-gray-400' : 'text-gray-900'}`}
          >
            {d}
          </span>
          {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
        </div>
        <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
          {(myReq || otherReqs.length > 0) && (
            <div className="flex -space-x-1.5 items-center">
              {myReq && <RegisteredAvatar name={userName} isMe={true} size="xs" />}
              {otherReqs.slice(0, myReq ? 2 : 3).map((r, i) => (
                <RegisteredAvatar key={i} name={r.users?.name || '?'} isMe={false} size="xs" />
              ))}
              {(dayReqs.length > 3) && (
                <div className="w-4 h-4 md:w-5 md:h-5 rounded-lg bg-gray-100 border border-white flex items-center justify-center text-[6px] md:text-[8px] font-black text-gray-400 shadow-sm z-10">
                  +{dayReqs.length - 3}
                </div>
              )}
            </div>
          )}
        </div>
        {dayReqs.length > 0 && !myReq && <div className={`absolute bottom-1.5 right-1.5 text-[6px] md:text-[9px] font-black uppercase ${isF ? 'text-sky-500' : 'text-indigo-400'}`}>{dayReqs.length} Đơn</div>}
      </div>
    );
  }
  return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{days}</div>;
});

// Component Form đăng ký - Trái tim của giải pháp mượt mà
const OvertimeRegistrationForm = ({ 
  user, 
  initialData, 
  selectedDateStr, 
  dayConfigs, 
  allEmployees, 
  isAdmin, 
  onClose, 
  onSubmit, 
  onCancel,
  onUpdateDayStatus
}: any) => {
  const [targetUserId, setTargetUserId] = useState(initialData?.user_id || user.id);
  const [startTime, setStartTime] = useState(initialData?.start_time || '17:30');
  const [endTime, setEndTime] = useState(initialData?.end_time || '20:00');
  const [reason, setReason] = useState(initialData?.reason || '');
  const [isRewriting, setIsRewriting] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  // Tính giờ mượt mà ngay trong component con
  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    await onSubmit({
      user_id: targetUserId,
      start_time: startTime,
      end_time: endTime,
      total_hours: calculatedHours,
      reason,
      date: selectedDateStr
    });
    setIsSubmitting(false);
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
      <div className="bg-indigo-600 p-4 flex justify-between items-center text-white shrink-0 shadow-lg">
        <div className="flex flex-col">
          <div className="flex items-center gap-2.5"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-lg font-black uppercase leading-none tracking-tight">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
          <p className="text-[8px] text-indigo-200 font-bold uppercase mt-1 opacity-70 tracking-widest">Chi tiết đăng ký</p>
        </div>
        <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5"/></button>
      </div>

      <div className="p-5 space-y-4 overflow-y-auto no-scrollbar bg-gray-50/50">
        {isAdmin && (
          <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
            <h4 className="text-[9px] font-black text-indigo-900 uppercase tracking-widest">Loại hình ngày</h4>
            <div className="grid grid-cols-2 gap-2">
              <button onClick={() => onUpdateDayStatus(false)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Home className="w-4 h-4" /> Nghỉ</button>
              <button onClick={() => onUpdateDayStatus(true)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Briefcase className="w-4 h-4" /> Làm</button>
            </div>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {isViewOnly ? (
            <div className="bg-amber-50 border-2 border-amber-100 p-6 rounded-2xl text-center space-y-4 shadow-sm">
              <Eye className="w-8 h-8 text-amber-500 mx-auto" /><p className="text-[10px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Thông tin đăng ký của đồng nghiệp.</p>
              <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl transition-all shadow-lg active:scale-95">ĐĂNG KÝ CHO TÔI</button>
            </div>
          ) : (
            <>
              {isAdmin && <div className="space-y-1.5"><label className="text-[9px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">{allEmployees.map((emp: any) => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}
              <div className="grid grid-cols-2 gap-3">
                <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Bắt đầu</label><input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
              </div>
              <div className="space-y-2">
                <div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung thực hiện</label><div className="flex items-center gap-1.5 bg-blue-600 text-white px-2 py-0.5 rounded-lg text-[8px] font-black shadow-md"><Zap className="w-3 h-3" />{calculatedHours}h OT</div></div>
                <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl text-xs h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-600 transition-all" placeholder="Nhập tóm tắt công việc..."/>
                <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-2 text-[9px] font-black text-blue-600 bg-white rounded-xl border-2 border-blue-50 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} Tối ưu nội dung AI</button>
              </div>
              <div className="flex gap-2 pt-2">
                {initialData && (isAdmin || targetUserId === user.id) && <button type="button" onClick={onCancel} className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-4 h-4" /></button>}
                <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl text-[10px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : initialData ? 'Cập nhật' : 'Gửi đăng ký'}</button>
              </div>
            </>
          )}
        </form>
      </div>
    </div>
  );
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', range?: { start: string, end: string }) => {
    const start = range?.start || exportStartDate;
    const end = range?.end || exportEndDate;
    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}.xlsx`);
  };

  const handleExportToday = () => handleExportExcel(isAdmin ? 'all' : 'personal', { start: todayStr, end: todayStr });

  // Xử lý nộp form từ component con
  const handleFormSubmit = async (formData: any) => {
    const currentReq = requests.find(r => r.date === formData.date && r.user_id === formData.user_id);
    const payload = { ...formData, status: 'approved' };

    try {
      const res = currentReq 
        ? await supabase.from('ot_requests').update(payload).eq('id', currentReq.id) 
        : await supabase.from('ot_requests').insert([payload]);

      if (res.error) throw res.error;
      fetchRequests(); 
      setIsModalOpen(false);
    } catch (err: any) { alert(err.message); }
  };

  const handleCancelRequest = async () => {
    const currentReq = requests.find(r => r.date === selectedDateStr && (isAdmin || r.user_id === user.id));
    if (!currentReq) return;
    try {
        await supabase.from('ot_requests').delete().eq('id', currentReq.id);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); }
  };

  const handleDateClick = useCallback((dateStr: string) => {
    setSelectedDateStr(dateStr); 
    setIsModalOpen(true);
  }, []);

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const teamStats = useMemo(() => {
    const monthly = requests.filter(r => r.date.startsWith(currentMonthStr));
    const totalHours = monthly.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthly.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRequestsSummary = useMemo(() => requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time)), [requests]);

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-4 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
                <button onClick={handleExportToday} className="hidden md:flex items-center gap-2 bg-emerald-600 text-white px-5 py-2 rounded-xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 active:scale-95"><FileSpreadsheet className="w-4 h-4" /> Xuất</button>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    <CalendarGrid 
                      currentDate={currentDate} 
                      requests={requests} 
                      dayConfigs={dayConfigs} 
                      userId={user.id} 
                      userName={user.name} 
                      onDateClick={handleDateClick} 
                    />
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 md:p-5 rounded-2xl md:rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-2xl md:text-4xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-amber-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Đang chờ duyệt</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.pending}</p>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-5 rounded-2xl md:rounded-3xl border-l-4 border-indigo-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Trung bình/ngày</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{(myStats.total / (myStats.count || 1)).toFixed(1)}<span className="text-[10px] ml-1 text-gray-300">H</span></p>
                        </Card>
                    </div>

                    <Card className="p-4 md:p-6 rounded-2xl md:rounded-3xl border-none shadow-sm bg-white">
                        <div className="flex items-center gap-3 mb-5">
                            <div className="p-2 bg-emerald-50 text-emerald-600 rounded-xl"><FileSpreadsheet className="w-5 h-5" /></div>
                            <h3 className="text-sm md:text-lg font-black uppercase tracking-tight">Xuất báo cáo cá nhân</h3>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-11 items-end gap-3 bg-gray-50/50 p-3 rounded-xl md:rounded-2xl border border-gray-100">
                            <div className="md:col-span-4"><input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
                            <div className="md:col-span-1 text-center hidden md:block"><ArrowRight className="w-4 h-4 text-gray-300 mx-auto" /></div>
                            <div className="md:col-span-4"><input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-gray-100 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600/10 transition-all"/></div>
                            <div className="md:col-span-2"><button onClick={() => handleExportExcel('personal')} className="w-full py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-md active:scale-95"><FileDown className="w-4 h-4 mx-auto" /></button></div>
                        </div>
                    </Card>

                    <Card className="p-4 md:p-6 rounded-2xl md:rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất tháng</h3>
                        <div className="h-44 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(59, 130, 246, 0.05)'}}/><Bar dataKey="hours" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={window.innerWidth < 640 ? 6 : 12} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    {isAdmin && (
                        <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
                            <Card className="bg-white border-l-4 border-indigo-600 p-4 rounded-2xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase tracking-wider mb-1">Nhân sự OT</p><p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{teamStats.activeMembers}</p></Card>
                            <Card className="bg-white border-l-4 border-emerald-600 p-4 rounded-2xl shadow-sm"><p className="text-[8px] font-black text-gray-400 uppercase tracking-wider mb-1">Tổng quỹ giờ</p><p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{teamStats.totalHours.toFixed(1)}</p></Card>
                            <Card className="col-span-2 md:col-span-1 bg-gradient-to-br from-indigo-600 to-indigo-800 text-white p-4 rounded-2xl shadow-lg"><p className="text-[8px] font-black uppercase opacity-70 tracking-wider mb-1">Hôm nay</p><p className="text-xl md:text-3xl font-black tabular-nums">{todayRequestsSummary.length} Đơn</p></Card>
                        </div>
                    )}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                        <Card className="rounded-2xl p-0 flex flex-col overflow-hidden bg-white shadow-sm border-none">
                            <div className="p-4 bg-gray-50/50 border-b flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Trophy className="w-4 h-4 text-amber-500" /> Hoạt động hôm nay</h4><span className="text-[7px] font-black bg-blue-100 text-blue-700 px-2.5 py-1 rounded-full uppercase ring-1 ring-blue-200">Live</span></div>
                            <div className="max-h-[300px] md:max-h-[400px] overflow-y-auto p-3 space-y-2 no-scrollbar">
                                {todayRequestsSummary.length === 0 ? <div className="py-16 text-center"><p className="text-gray-300 italic text-[10px] uppercase tracking-widest">Danh sách trống</p></div> : todayRequestsSummary.map((r, i) => (
                                    <div key={i} className="p-3 rounded-xl bg-gray-50/50 hover:bg-white transition-all border border-gray-100 flex items-center gap-3 border-l-4 border-l-blue-600 group">
                                        <RegisteredAvatar name={r.users?.name || '?'} isMe={r.user_id === user.id} size="sm" />
                                        <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight leading-tight">{r.users?.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{r.users?.employee_id}</p></div>
                                        <div className="text-right flex flex-col items-end"><div className="text-[8px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-md mb-1 border border-blue-100">{r.start_time}-{r.end_time}</div><span className="text-sm font-black text-gray-900 tabular-nums">{r.total_hours.toFixed(1)}h</span></div>
                                    </div>
                                ))}
                            </div>
                        </Card>
                        <Card className="rounded-2xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                             <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Award className="w-4 h-4 text-amber-400 drop-shadow-sm" /> Top Chăm chỉ T{currentDate.getMonth()+1}</h4></div>
                             <div className="p-3 space-y-2 max-h-[300px] md:max-h-[400px] overflow-y-auto no-scrollbar">
                                {topRankings.map((e, i) => {
                                    const isMe = allEmployees.find(emp => emp.name === e.name)?.id === user.id;
                                    return (
                                        <div key={i} className={`p-3 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/30 border-amber-200 shadow-sm' : 'bg-white border-gray-100'}`}>
                                            <div className="w-9 h-9 md:w-11 md:h-11 flex items-center justify-center">
                                              {i === 0 ? <Trophy className="w-8 h-8 text-amber-500" /> : <RegisteredAvatar name={e.name} isMe={!!isMe} size="sm" />}
                                            </div>
                                            <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight">{e.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày</p></div>
                                            <div className="text-right"><span className="text-sm font-black text-indigo-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[8px] font-black text-gray-300 ml-1 uppercase">H</span></div>
                                        </div>
                                    );
                                })}
                             </div>
                        </Card>
                    </div>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <OvertimeRegistrationForm 
                  user={user}
                  selectedDateStr={selectedDateStr}
                  dayConfigs={dayConfigs}
                  allEmployees={allEmployees}
                  isAdmin={isAdmin}
                  initialData={requests.find(r => r.date === selectedDateStr && (isAdmin || r.user_id === user.id))}
                  onClose={() => setIsModalOpen(false)}
                  onSubmit={handleFormSubmit}
                  onCancel={() => setIsConfirmCancelOpen(true)}
                  onUpdateDayStatus={updateDayWorkingStatus}
                />
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl shadow-lg shadow-rose-50"><Trash2 className="w-9 h-9"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-8 leading-relaxed">Dữ liệu sẽ được xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg active:scale-95">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

const getColleagueColor = (name: string) => {
  const colors = ['bg-blue-600', 'bg-indigo-600', 'bg-violet-600', 'bg-purple-600', 'bg-sky-600', 'bg-blue-500'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Form states
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', range?: { start: string, end: string }) => {
    const start = range?.start || exportStartDate;
    const end = range?.end || exportEndDate;
    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}.xlsx`);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isT = todayStr === dStr;
      const isP = new Date(dStr).getTime() < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div key={d} onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-2 border-b border-r border-gray-100 ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-10' : 'bg-white hover:bg-gray-50'}`}>
          <div className="flex items-center justify-between">
            <span className={`text-xs md:text-lg font-black ${isT ? 'text-rose-600' : !config ? 'text-rose-400' : isP ? 'text-gray-300' : 'text-gray-900'}`}>{d}</span>
            {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
          </div>
          <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
            {(myReq || otherReqs.length > 0) && (
              <div className="flex -space-x-1.5 items-center">
                {myReq && (
                   <div className="relative group/avatar">
                     <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-emerald-500 text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased">{user.name.charAt(0)}</div>
                     <div className="absolute -bottom-0.5 -right-0.5 bg-blue-500 text-white rounded-full border border-white w-2 h-2 md:w-3 md:h-3 flex items-center justify-center"><Check className="w-1.5 h-1.5 md:w-2 md:h-2 stroke-[4]" /></div>
                   </div>
                )}
                {otherReqs.slice(0, myReq ? 2 : 3).map((r, i) => (
                  <div key={i} className={`w-4 h-4 md:w-6 md:h-6 rounded-lg ${getColleagueColor(r.users?.name || '')} text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased`}>{r.users?.name?.charAt(0)}</div>
                ))}
                {dayReqs.length > 3 && <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-gray-100 border border-white flex items-center justify-center text-[6px] md:text-[8px] font-black text-gray-400">+{dayReqs.length-3}</div>}
              </div>
            )}
          </div>
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{days}</div>;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-4 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    {renderCalendar()}
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-2xl md:text-4xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                    </div>
                    <Card className="p-4 rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất tháng</h3>
                        <div className="h-44 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(59, 130, 246, 0.05)'}}/><Bar dataKey="hours" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={window.innerWidth < 640 ? 6 : 12} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    <Card className="rounded-2xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                         <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Award className="w-4 h-4 text-amber-400 drop-shadow-sm" /> Top Chăm chỉ T{currentDate.getMonth()+1}</h4></div>
                         <div className="p-3 space-y-2 max-h-[400px] overflow-y-auto no-scrollbar">
                            {topRankings.map((e, i) => (
                                <div key={i} className={`p-3 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/30 border-amber-200 shadow-sm' : 'bg-white border-gray-100'}`}>
                                    <div className="w-9 h-9 md:w-11 md:h-11 flex items-center justify-center font-black text-sm uppercase">
                                      {i === 0 ? <Trophy className="w-8 h-8 text-amber-500" /> : <div className={`w-10 h-10 rounded-xl ${getColleagueColor(e.name)} text-white flex items-center justify-center`}>{e.name.charAt(0)}</div>}
                                    </div>
                                    <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight">{e.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày</p></div>
                                    <div className="text-right"><span className="text-sm font-black text-indigo-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[8px] font-black text-gray-300 ml-1 uppercase">H</span></div>
                                </div>
                            ))}
                         </div>
                    </Card>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-indigo-600 p-4 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2.5"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-lg font-black uppercase leading-none tracking-tight">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[8px] text-indigo-200 font-bold uppercase mt-1 opacity-70 tracking-widest">Chi tiết đăng ký</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 space-y-4 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[9px] font-black text-indigo-900 uppercase tracking-widest">Loại hình ngày</h4>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Home className="w-4 h-4" /> Nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Briefcase className="w-4 h-4" /> Làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border-2 border-amber-100 p-6 rounded-2xl text-center space-y-4 shadow-sm">
                                    <Eye className="w-8 h-8 text-amber-500 mx-auto" /><p className="text-[10px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Thông tin đăng ký của đồng nghiệp.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl transition-all shadow-lg active:scale-95">ĐĂNG KÝ CHO TÔI</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && <div className="space-y-1.5"><label className="text-[9px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}
                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Bắt đầu</label><input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung thực hiện</label><div className="flex items-center gap-1.5 bg-blue-600 text-white px-2 py-0.5 rounded-lg text-[8px] font-black shadow-md"><Zap className="w-3 h-3" />{calculatedHours}h OT</div></div>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl text-xs h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-600 transition-all" placeholder="Nhập tóm tắt công việc..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-2 text-[9px] font-black text-blue-600 bg-white rounded-xl border-2 border-blue-50 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} Tối ưu nội dung AI</button>
                                    </div>
                                    <div className="flex gap-2 pt-2">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-4 h-4" /></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl text-[10px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl shadow-lg shadow-rose-50"><Trash2 className="w-9 h-9"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-8 leading-relaxed">Dữ liệu sẽ được xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg active:scale-95">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon
} from 'lucide-react';

interface RequestManagerProps { user: User; }

const ToolTableImage = ({ toolId, toolName }: { toolId: string, toolName: string }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  return (
    <div className="w-12 h-12 bg-white border border-gray-100 rounded-xl overflow-hidden flex items-center justify-center p-1 shadow-sm">
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-5 h-5 text-gray-300" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      returned: 2,
      rejected: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      return matchesSearch && matchesStatus;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchRequests();
    } catch (e: any) {
      alert(e.message);
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-500 text-white border-amber-600', icon: <Timer className="w-4 h-4" />, label: 'CHỜ DUYỆT' },
      approved: { color: 'bg-emerald-600 text-white border-emerald-700', icon: <PackageCheck className="w-4 h-4" />, label: 'ĐANG MƯỢN' },
      returned: { color: 'bg-blue-500 text-white border-blue-600', icon: <RotateCcw className="w-4 h-4" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-red-500 text-white border-red-600', icon: <XCircle className="w-4 h-4" />, label: 'TỪ CHỐI' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-bold shadow-sm ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white p-6 md:p-8 rounded-3xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className="p-3 md:p-4 bg-blue-600 rounded-2xl shadow-lg shadow-blue-100 text-white">
            <RefreshCw className="w-6 h-6 md:w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-bold text-gray-900 tracking-tight">Quản lý mượn trả</h2>
            <p className="text-xs text-gray-500 mt-1">Phê duyệt và giám sát yêu cầu thiết bị</p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'all' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Tất cả đơn</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>Đơn của tôi</button>
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 group">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm nhân viên, đồ..." 
            className="w-full pl-11 pr-4 py-3.5 bg-white border border-gray-100 rounded-2xl text-sm font-medium outline-none focus:ring-4 focus:ring-blue-500/5 focus:border-blue-500 transition-all shadow-sm" 
          />
        </div>
        <select 
          value={filterStatus} 
          onChange={e => setFilterStatus(e.target.value)} 
          className="px-5 py-3.5 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none cursor-pointer shadow-sm focus:border-blue-500 transition-all"
        >
          <option value="all">Trạng thái</option>
          <option value="pending">Đang chờ duyệt</option>
          <option value="approved">Đang mượn</option>
          <option value="returned">Đã trả đồ</option>
          <option value="rejected">Đã từ chối</option>
        </select>
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-xl rounded-3xl bg-white">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-gray-100">
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Người mượn</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Thiết bị</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Thời gian</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-center">Trạng thái</th>
                <th className="px-8 py-6 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="py-24 text-center"><Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto opacity-20" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={5} className="py-24 text-center text-gray-300 font-medium italic">Không có dữ liệu yêu cầu</td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className="group transition-all duration-200 hover:bg-blue-50/50 border-l-4 border-l-transparent hover:border-l-blue-600 hover:shadow-sm"
                  >
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-indigo-600 text-white rounded-xl flex items-center justify-center font-bold text-sm shadow-md">
                          {req.user_name.charAt(0)}
                        </div>
                        <div>
                          <div className="font-bold text-gray-900 text-sm">{req.user_name}</div>
                          <div className="text-[10px] text-gray-400 font-medium">{req.employee_id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                        <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                        <div className="font-bold text-gray-800 text-sm uppercase">{req.tool_name}</div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-2 text-gray-400 font-medium text-xs">
                        <Calendar className="w-3.5 h-3.5" />
                        {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                      </div>
                    </td>
                    <td className="px-8 py-6 text-center">
                      {getStatusBadge(req.status)}
                    </td>
                    <td className="px-8 py-6 text-right">
                      {processingId === req.id ? (
                        <Loader2 className="w-5 h-5 animate-spin ml-auto text-blue-600" />
                      ) : (
                        <div className="flex justify-end gap-2">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-xl text-[10px] font-bold shadow-md hover:bg-emerald-700 active:scale-95 transition-all">DUYỆT</button>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-2 bg-red-50 text-red-600 rounded-xl hover:bg-red-600 hover:text-white transition-all shadow-sm" title="Từ chối"><X className="w-4 h-4" /></button>
                            </>
                          )}
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="flex items-center gap-2 px-5 py-2.5 bg-blue-600 text-white rounded-xl text-[10px] font-bold shadow-md shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all">
                              <RotateCcw className="w-3.5 h-3.5" /> THU HỒI
                            </button>
                          )}
                          {req.user_id === user.id && req.status === 'pending' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"><Trash2 className="w-4 h-4" /></button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

const getColleagueColor = (name: string) => {
  const colors = ['bg-blue-600', 'bg-indigo-600', 'bg-violet-600', 'bg-purple-600', 'bg-sky-600', 'bg-blue-500'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Form states
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  // Fix: Define isViewOnly to check if the current user can edit the registration
  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 20.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const handleExportExcel = (mode: 'personal' | 'all' = 'personal', range?: { start: string, end: string }) => {
    const start = range?.start || exportStartDate;
    const end = range?.end || exportEndDate;
    let filtered = requests.filter(r => r.date >= start && r.date <= end);
    if (mode === 'personal') filtered = filtered.filter(r => r.user_id === user.id);
    if (filtered.length === 0) return alert("Không có dữ liệu.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT');
    XLSX.writeFile(workbook, `Bao_cao_OT_${mode}.xlsx`);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isT = todayStr === dStr;
      const isP = new Date(dStr).getTime() < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div key={d} onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-2 border-b border-r border-gray-100 ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-10' : 'bg-white hover:bg-gray-50'}`}>
          <div className="flex items-center justify-between">
            <span className={`text-xs md:text-lg font-black ${isT ? 'text-rose-600' : !config ? 'text-rose-400' : isP ? 'text-gray-300' : 'text-gray-900'}`}>{d}</span>
            {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
          </div>
          <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
            {(myReq || otherReqs.length > 0) && (
              <div className="flex -space-x-1.5 items-center">
                {myReq && (
                   <div className="relative group/avatar">
                     <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-emerald-500 text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased">{user.name.charAt(0)}</div>
                     <div className="absolute -bottom-0.5 -right-0.5 bg-blue-500 text-white rounded-full border border-white w-2 h-2 md:w-3 md:h-3 flex items-center justify-center"><Check className="w-1.5 h-1.5 md:w-2 md:h-2 stroke-[4]" /></div>
                   </div>
                )}
                {otherReqs.slice(0, myReq ? 2 : 3).map((r, i) => (
                  <div key={i} className={`w-4 h-4 md:w-6 md:h-6 rounded-lg ${getColleagueColor(r.users?.name || '')} text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased`}>{r.users?.name?.charAt(0)}</div>
                ))}
                {dayReqs.length > 3 && <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-gray-100 border border-white flex items-center justify-center text-[6px] md:text-[8px] font-black text-gray-400">+{dayReqs.length-3}</div>}
              </div>
            )}
          </div>
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{days}</div>;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-4 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    {renderCalendar()}
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-2xl md:text-4xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                    </div>
                    <Card className="p-4 rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất tháng</h3>
                        <div className="h-44 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(59, 130, 246, 0.05)'}}/><Bar dataKey="hours" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={window.innerWidth < 640 ? 6 : 12} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    <Card className="rounded-2xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                         <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Award className="w-4 h-4 text-amber-400 drop-shadow-sm" /> Top Chăm chỉ T{currentDate.getMonth()+1}</h4></div>
                         <div className="p-3 space-y-2 max-h-[400px] overflow-y-auto no-scrollbar">
                            {topRankings.map((e, i) => (
                                <div key={i} className={`p-3 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/30 border-amber-200 shadow-sm' : 'bg-white border-gray-100'}`}>
                                    <div className="w-9 h-9 md:w-11 md:h-11 flex items-center justify-center font-black text-sm uppercase">
                                      {i === 0 ? <Trophy className="w-8 h-8 text-amber-500" /> : <div className={`w-10 h-10 rounded-xl ${getColleagueColor(e.name)} text-white flex items-center justify-center`}>{e.name.charAt(0)}</div>}
                                    </div>
                                    <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight">{e.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày</p></div>
                                    <div className="text-right"><span className="text-sm font-black text-indigo-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[8px] font-black text-gray-300 ml-1 uppercase">H</span></div>
                                </div>
                            ))}
                         </div>
                    </Card>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-indigo-600 p-4 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2.5"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-lg font-black uppercase leading-none tracking-tight">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[8px] text-indigo-200 font-bold uppercase mt-1 opacity-70 tracking-widest">Chi tiết đăng ký</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 space-y-4 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[9px] font-black text-indigo-900 uppercase tracking-widest">Loại hình ngày</h4>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Home className="w-4 h-4" /> Nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Briefcase className="w-4 h-4" /> Làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border-2 border-amber-100 p-6 rounded-2xl text-center space-y-4 shadow-sm">
                                    <Eye className="w-8 h-8 text-amber-500 mx-auto" /><p className="text-[10px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Thông tin đăng ký của đồng nghiệp.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl transition-all shadow-lg active:scale-95">ĐĂNG KÝ CHO TÔI</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && <div className="space-y-1.5"><label className="text-[9px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}
                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Bắt đầu</label><input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                        <div className="bg-white p-3 rounded-xl border border-gray-100 shadow-sm"><label className="block text-[8px] font-black text-gray-400 uppercase mb-2">Kết thúc</label><input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 focus:ring-0 outline-none tabular-nums"/></div>
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung thực hiện</label><div className="flex items-center gap-1.5 bg-blue-600 text-white px-2 py-0.5 rounded-lg text-[8px] font-black shadow-md"><Zap className="w-3 h-3" />{calculatedHours}h OT</div></div>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl text-xs h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-600 transition-all" placeholder="Nhập tóm tắt công việc..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-2 text-[9px] font-black text-blue-600 bg-white rounded-xl border-2 border-blue-50 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} Tối ưu nội dung AI</button>
                                    </div>
                                    <div className="flex gap-2 pt-2">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-4 h-4" /></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl text-[10px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl shadow-lg shadow-rose-50"><Trash2 className="w-9 h-9"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-8 leading-relaxed">Dữ liệu sẽ được xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg active:scale-95">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight, Check, Plus, Minus
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const numberToTime = (n: number) => {
  const h = Math.floor(n);
  const m = Math.round((n - h) * 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

const getColleagueColor = (name: string) => {
  const colors = ['bg-blue-600', 'bg-indigo-600', 'bg-violet-600', 'bg-purple-600', 'bg-sky-600', 'bg-blue-500'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Form states
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0); // Giới hạn tối đa 22:00
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const adjustTime = (type: 'start' | 'end', delta: number) => {
    if (isViewOnly) return;
    const currentVal = type === 'start' ? startTime : endTime;
    const num = timeToNumber(currentVal);
    let next = num + delta;
    if (next < 0) next = 0;
    if (next > 23.75) next = 23.75;
    const nextTime = numberToTime(next);
    if (type === 'start') setStartTime(nextTime);
    else setEndTime(nextTime);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isT = todayStr === dStr;
      const isP = new Date(dStr).getTime() < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div key={d} onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-2 border-b border-r border-gray-100 ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-10' : 'bg-white hover:bg-gray-50'}`}>
          <div className="flex items-center justify-between">
            <span className={`text-xs md:text-lg font-black ${isT ? 'text-rose-600' : !config ? 'text-rose-400' : isP ? 'text-gray-300' : 'text-gray-900'}`}>{d}</span>
            {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
          </div>
          <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
            {(myReq || otherReqs.length > 0) && (
              <div className="flex -space-x-1.5 items-center">
                {myReq && (
                   <div className="relative group/avatar">
                     <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-emerald-500 text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased">{user.name.charAt(0)}</div>
                     <div className="absolute -bottom-0.5 -right-0.5 bg-blue-500 text-white rounded-full border border-white w-2 h-2 md:w-3 md:h-3 flex items-center justify-center"><Check className="w-1.5 h-1.5 md:w-2 md:h-2 stroke-[4]" /></div>
                   </div>
                )}
                {otherReqs.slice(0, myReq ? 2 : 3).map((r, i) => (
                  <div key={i} className={`w-4 h-4 md:w-6 md:h-6 rounded-lg ${getColleagueColor(r.users?.name || '')} text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased`}>{r.users?.name?.charAt(0)}</div>
                ))}
                {dayReqs.length > 3 && <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-gray-100 border border-white flex items-center justify-center text-[6px] md:text-[8px] font-black text-gray-400">+{dayReqs.length-3}</div>}
              </div>
            )}
          </div>
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{days}</div>;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-4 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    {renderCalendar()}
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-2xl md:text-4xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                    </div>
                    <Card className="p-4 rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất tháng</h3>
                        <div className="h-44 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(59, 130, 246, 0.05)'}}/><Bar dataKey="hours" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={window.innerWidth < 640 ? 6 : 12} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    <Card className="rounded-2xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                         <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Award className="w-4 h-4 text-amber-400 drop-shadow-sm" /> Top Chăm chỉ T{currentDate.getMonth()+1}</h4></div>
                         <div className="p-3 space-y-2 max-h-[400px] overflow-y-auto no-scrollbar">
                            {topRankings.map((e, i) => (
                                <div key={i} className={`p-3 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/30 border-amber-200 shadow-sm' : 'bg-white border-gray-100'}`}>
                                    <div className="w-9 h-9 md:w-11 md:h-11 flex items-center justify-center font-black text-sm uppercase">
                                      {i === 0 ? <Trophy className="w-8 h-8 text-amber-500" /> : <div className={`w-10 h-10 rounded-xl ${getColleagueColor(e.name)} text-white flex items-center justify-center`}>{e.name.charAt(0)}</div>}
                                    </div>
                                    <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight">{e.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày</p></div>
                                    <div className="text-right"><span className="text-sm font-black text-indigo-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[8px] font-black text-gray-300 ml-1 uppercase">H</span></div>
                                </div>
                            ))}
                         </div>
                    </Card>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-indigo-600 p-4 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2.5"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-lg font-black uppercase leading-none tracking-tight">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[8px] text-indigo-200 font-bold uppercase mt-1 opacity-70 tracking-widest">Chi tiết đăng ký</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 space-y-4 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[9px] font-black text-indigo-900 uppercase tracking-widest">Loại hình ngày</h4>
                                <div className="grid grid-cols-2 gap-2">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Home className="w-4 h-4" /> Nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Briefcase className="w-4 h-4" /> Làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border-2 border-amber-100 p-6 rounded-2xl text-center space-y-4 shadow-sm">
                                    <Eye className="w-8 h-8 text-amber-500 mx-auto" /><p className="text-[10px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Thông tin đăng ký của đồng nghiệp.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-3 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl transition-all shadow-lg active:scale-95">ĐĂNG KÝ CHO TÔI</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && <div className="space-y-1.5"><label className="text-[9px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-2.5 bg-white border border-gray-200 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}

                                    {/* Refactored Time Inputs */}
                                    <div className="bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm space-y-5">
                                      <div className="flex items-center justify-between px-2">
                                        <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest">Thời gian mượn</h4>
                                        <div className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black shadow-lg shadow-indigo-100 ring-2 ring-white">
                                          <Zap className="w-3 h-3 text-amber-300 animate-pulse" /> {calculatedHours}h TÍNH TOÁN
                                        </div>
                                      </div>

                                      <div className="flex items-center gap-4">
                                        <div className="flex-1 space-y-2">
                                          <div className="flex items-center justify-between px-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Bắt đầu</label>
                                            <div className="flex gap-1">
                                              <button type="button" onClick={() => adjustTime('start', -0.25)} className="p-1 hover:bg-gray-100 rounded-md text-gray-300"><Minus className="w-3 h-3"/></button>
                                              <button type="button" onClick={() => adjustTime('start', 0.25)} className="p-1 hover:bg-gray-100 rounded-md text-gray-300"><Plus className="w-3 h-3"/></button>
                                            </div>
                                          </div>
                                          <div className="bg-gray-50/80 p-3 rounded-2xl border border-gray-100 focus-within:border-indigo-500 transition-all flex items-center gap-2">
                                            <input 
                                              type="time" 
                                              value={startTime} 
                                              onChange={e => setStartTime(e.target.value)} 
                                              className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 outline-none tabular-nums cursor-pointer"
                                            />
                                          </div>
                                        </div>

                                        <div className="flex items-center justify-center pt-6">
                                           <ArrowRight className="w-4 h-4 text-gray-200" />
                                        </div>

                                        <div className="flex-1 space-y-2">
                                          <div className="flex items-center justify-between px-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Kết thúc</label>
                                            <div className="flex gap-1">
                                              <button type="button" onClick={() => adjustTime('end', -0.25)} className="p-1 hover:bg-gray-100 rounded-md text-gray-300"><Minus className="w-3 h-3"/></button>
                                              <button type="button" onClick={() => adjustTime('end', 0.25)} className="p-1 hover:bg-gray-100 rounded-md text-gray-300"><Plus className="w-3 h-3"/></button>
                                            </div>
                                          </div>
                                          <div className="bg-gray-50/80 p-3 rounded-2xl border border-gray-100 focus-within:border-indigo-500 transition-all flex items-center gap-2">
                                            <input 
                                              type="time" 
                                              value={endTime} 
                                              onChange={e => setEndTime(e.target.value)} 
                                              className="w-full bg-transparent border-none p-0 text-xl font-black text-gray-900 outline-none tabular-nums cursor-pointer"
                                            />
                                          </div>
                                        </div>
                                      </div>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nội dung thực hiện</label>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-2xl text-xs h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-600 transition-all" placeholder="Nhập tóm tắt công việc..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-2 text-[9px] font-black text-blue-600 bg-white rounded-xl border-2 border-blue-50 hover:bg-blue-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} Tối ưu nội dung AI</button>
                                    </div>
                                    <div className="flex gap-2 pt-2">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-4 h-4" /></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl text-[10px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-2xl shadow-lg shadow-rose-50"><Trash2 className="w-9 h-9"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-8 leading-relaxed">Dữ liệu sẽ được xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg active:scale-95">XÓA VĨNH VIỄN</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight, Check, Plus, Minus,
  TrendingUp, Users, Download
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const numberToTime = (n: number) => {
  const h = Math.floor(n);
  const m = Math.round((n - h) * 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

const getColleagueColor = (name: string) => {
  const colors = ['bg-blue-600', 'bg-indigo-600', 'bg-violet-600', 'bg-purple-600', 'bg-sky-600', 'bg-blue-500'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  // Form states
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const adjustTime = (type: 'start' | 'end', delta: number) => {
    if (isViewOnly) return;
    const currentVal = type === 'start' ? startTime : endTime;
    const num = timeToNumber(currentVal);
    let next = num + delta;
    if (next < 0) next = 0;
    if (next > 23.75) next = 23.75;
    const nextTime = numberToTime(next);
    if (type === 'start') setStartTime(nextTime);
    else setEndTime(nextTime);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleExportToday = () => {
    const todayReqs = requests.filter(r => r.date === todayStr);
    if (todayReqs.length === 0) return alert("Không có dữ liệu hôm nay.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(todayReqs.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Tổng giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT-Today');
    XLSX.writeFile(workbook, `OT_Report_${todayStr}.xlsx`);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    return { total, count: my.length };
  }, [requests, user.id, currentMonthStr]);

  const top5Rankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const todayCount = useMemo(() => requests.filter(r => r.date === todayStr).length, [requests]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 border-b border-r border-gray-100 bg-gray-50/10"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isT = todayStr === dStr;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);

      const dateObj = new Date(dStr);
      const dayOfWeek = dateObj.getDay();
      const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
      const config = dayConfigs[dStr] ?? (dayOfWeek !== 0);

      days.push(
        <div 
          key={d} 
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-3 border-b border-r border-gray-100 ${isT ? 'bg-blue-50/40 ring-inset ring-2 ring-blue-500 z-10' : 'bg-white hover:bg-gray-50'}`}
        >
          <div className="flex items-center justify-between">
            <span className={`text-xs md:text-sm font-black ${isWeekend ? 'text-rose-500' : 'text-gray-900'} flex items-center gap-1`}>
              {d}
              {isWeekend && <span className="w-4 h-4 rounded-full bg-rose-500 text-white text-[8px] flex items-center justify-center">N</span>}
            </span>
            {!config && <span className="text-[7px] font-black px-1.5 py-0.5 rounded-full bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
          </div>

          <div className="flex-1 flex flex-col justify-end gap-1.5 mt-2 overflow-hidden">
            {dayReqs.length > 0 && (
                <div className="flex -space-x-2 items-center">
                    {myReq && (
                        <div className="w-5 h-5 md:w-8 md:h-8 rounded-full bg-emerald-500 text-white flex items-center justify-center font-black text-[10px] uppercase border-2 border-white shadow-sm ring-2 ring-blue-500/20">
                            {user.name.charAt(0)}
                        </div>
                    )}
                    {otherReqs.slice(0, myReq ? 2 : 3).map((r, i) => (
                        <div key={i} className={`w-5 h-5 md:w-8 md:h-8 rounded-full ${getColleagueColor(r.users?.name || '')} text-white flex items-center justify-center font-black text-[10px] uppercase border-2 border-white shadow-sm`}>
                            {r.users?.name?.charAt(0)}
                        </div>
                    ))}
                    {dayReqs.length > (myReq ? 3 : 3) && (
                        <div className="w-5 h-5 md:w-8 md:h-8 rounded-full bg-gray-100 border-2 border-white flex items-center justify-center text-[8px] font-black text-gray-500 shadow-sm">
                            +{dayReqs.length - 3}
                        </div>
                    )}
                </div>
            )}
            {dayReqs.length > 0 && <div className="text-[7px] md:text-[9px] font-black text-gray-400 uppercase tracking-tighter text-right">{dayReqs.length} Nhân sự</div>}
          </div>
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white border-l border-t border-gray-100 rounded-b-3xl overflow-hidden">{days}</div>;
  };

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in max-w-screen-2xl mx-auto px-4 pb-12">
        {/* Top Bar Header */}
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-3 bg-blue-600 rounded-2xl text-white shadow-lg shadow-blue-100">
                    <Clock className="w-6 h-6" />
                </div>
                <div>
                    <div className="flex items-center gap-2">
                        <h2 className="text-2xl font-black text-gray-900 tracking-tight uppercase">Tăng ca</h2>
                        <span className="bg-indigo-100 text-indigo-600 text-[8px] font-black px-2 py-0.5 rounded-full uppercase">Tool V2</span>
                    </div>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1 italic">Tháng {currentDate.getMonth() + 1} / {currentDate.getFullYear()}</p>
                </div>
            </div>
            <div className="flex items-center gap-3">
                <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200">
