                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-[1.8rem] shadow-2xl shadow-indigo-200 text-xs uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50 flex items-center justify-center gap-3">
