                    <button onClick={() => setActiveTab('personal')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>Tôi</button>
                    <button onClick={() => setActiveTab('stats')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>Thống kê</button>
                </div>
                <button 
                  onClick={handleExportToday} 
                  className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-3.5 rounded-2xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 transition-all active:scale-95"
                >
                    <Zap className="w-4 h-4 fill-white" /> Xuất Excel hôm nay
                </button>
            </div>
        </div>

        {/* Content Area */}
        <div className="flex flex-col xl:flex-row gap-6">
            {/* Main Calendar Card */}
            <div className="flex-1 order-2 xl:order-1">
                <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[2.5rem] bg-white h-full flex flex-col">
                    <div className="flex items-center justify-between p-8 bg-white">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-gray-50 rounded-2xl transition-all border border-gray-100 shadow-sm"><ChevronLeft className="w-6 h-6 text-gray-400"/></button>
                        <h3 className="text-xl md:text-2xl font-black uppercase tracking-[0.3em] text-gray-800">T{currentDate.getMonth()+1} - {currentDate.getFullYear()}</h3>
