                        <span className="text-[8px] font-black uppercase tracking-widest bg-white/20 px-2 py-1 rounded-lg">Realtime</span>
                    </div>
                    <p className="text-[10px] font-bold uppercase opacity-70 tracking-widest">Hôm nay ({todayStr.split('-').reverse().join('/')})</p>
                    <div className="flex items-end gap-2 mt-1">
                        <h4 className="text-4xl font-black">{todayCount}</h4>
                        <span className="text-xs font-bold uppercase pb-1.5 opacity-60">Nhân sự OT</span>
                    </div>
                </Card>

                <Card className="p-6 rounded-[2rem] border-none shadow-lg bg-white">
                    <div className="flex items-center gap-3 mb-6">
                        <div className="p-2 bg-amber-50 rounded-xl text-amber-500">
                            <Trophy className="w-5 h-5" />
                        </div>
                        <h4 className="text-[11px] font-black uppercase text-gray-800 tracking-widest">Top 5 chăm chỉ T{currentDate.getMonth()+1}</h4>
                    </div>

                    <div className="space-y-3">
                        {top5Rankings.length === 0 ? (
                            <p className="text-[10px] text-gray-300 italic text-center py-4 uppercase font-bold">Chưa có dữ liệu tháng này</p>
                        ) : (
                            top5Rankings.map((e, i) => (
                                <div key={i} className={`flex items-center gap-3 p-2.5 rounded-2xl transition-all border ${i === 0 ? 'bg-amber-50 border-amber-200 shadow-sm' : 'border-gray-50 bg-white hover:border-blue-100'}`}>
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-sm uppercase border-2 shadow-sm ${i === 0 ? 'bg-amber-500 text-white border-white' : 'bg-gray-100 text-gray-400 border-white'}`}>
                                        {i === 0 ? <Award className="w-5 h-5" /> : e.name.charAt(0)}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-[11px] font-black text-gray-900 uppercase truncate tracking-tight">{e.name}</p>
                                        <p className="text-[8px] font-bold text-gray-400 uppercase tracking-widest">{e.count} ngày OT</p>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-xs font-black text-indigo-600 tabular-nums">{e.hours.toFixed(1)}</span>
                                        <span className="text-[8px] font-black text-gray-300 ml-1 uppercase">H</span>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </Card>

                <Card className="p-6 rounded-[2rem] border-none shadow-lg bg-white overflow-hidden relative group">
                    <div className="relative z-10">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Cá nhân tích lũy</p>
                        <h4 className="text-2xl font-black text-gray-900 tabular-nums">{myStats.total.toFixed(1)}<span className="text-xs ml-1 text-gray-300">giờ</span></h4>
                        <div className="mt-4 flex items-center gap-2 text-[9px] font-black text-emerald-600 uppercase">
                            <Activity className="w-3.5 h-3.5" /> 
                            <span>Đã đăng ký {myStats.count} ngày</span>
                        </div>
                    </div>
                    <div className="absolute top-0 right-0 p-8 transform translate-x-1/2 -translate-y-1/2">
                        <div className="w-32 h-32 rounded-full bg-blue-50 group-hover:scale-110 transition-transform duration-700"></div>
                    </div>
                </Card>
            </div>
        </div>

        {/* OT Registration Modal */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[95vh] flex flex-col border border-white/20">
                    <div className="bg-indigo-600 p-6 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-3">
                                <CalendarDays className="w-6 h-6 text-indigo-200" />
                                <h3 className="text-xl font-black uppercase leading-none tracking-tighter">Ngày {selectedDateStr.split('-').reverse().join('/')}</h3>
                            </div>
                            <p className="text-[9px] text-indigo-200 font-black uppercase mt-1.5 opacity-70 tracking-widest">Đăng ký ca làm thêm</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-white/20 rounded-2xl transition-all shadow-inner"><X className="w-6 h-6"/></button>
                    </div>

                    <div className="p-6 space-y-6 overflow-y-auto no-scrollbar bg-gray-50/50 flex-1">
                        {isAdmin && (
                            <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest flex items-center gap-2"><Settings2 className="w-4 h-4"/> Cấu hình loại ngày</h4>
                                <div className="grid grid-cols-2 gap-3">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Home className="w-4 h-4" /> Ngày nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100 hover:border-indigo-100' }`}><Briefcase className="w-4 h-4" /> Đi làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border-2 border-amber-200 p-8 rounded-[2.5rem] text-center space-y-4 shadow-sm animate-pulse">
                                    <Eye className="w-12 h-12 text-amber-500 mx-auto" />
                                    <div className="space-y-2">
                                        <p className="text-[11px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Chế độ xem thông tin</p>
                                        <p className="text-[9px] text-amber-600 font-bold uppercase italic">Bạn đang xem lịch của đồng nghiệp</p>
                                    </div>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-4 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-2xl transition-all shadow-xl shadow-indigo-100 active:scale-95">Đăng ký cho chính mình</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label>
                                            <select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-6 py-4 bg-white border border-gray-200 rounded-2xl text-sm font-bold outline-none shadow-sm focus:border-indigo-600">
                                                {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}
                                            </select>
                                        </div>
                                    )}

                                    <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-6">
                                      <div className="flex items-center justify-between px-2">
                                        <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest">Khung giờ mượn thêm</h4>
                                        <div className="flex items-center gap-1.5 bg-indigo-600 text-white px-4 py-2 rounded-2xl text-[10px] font-black shadow-lg shadow-indigo-100 ring-4 ring-white">
                                          <Zap className="w-4 h-4 text-amber-300 animate-pulse" /> {calculatedHours}H TỔNG
                                        </div>
                                      </div>

                                      <div className="flex items-center gap-4">
                                        <div className="flex-1 space-y-2">
                                          <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Bắt đầu</label>
                                          <div className="flex items-center bg-gray-50 rounded-2xl p-2 border border-gray-100 group-focus-within:border-blue-500 transition-all">
                                            <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-1 text-xl font-black text-gray-900 outline-none tabular-nums cursor-pointer" />
                                          </div>
                                          <div className="flex justify-center gap-1.5 pt-1">
                                              <button type="button" onClick={() => adjustTime('start', -0.25)} className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400"><Minus className="w-3 h-3"/></button>
                                              <button type="button" onClick={() => adjustTime('start', 0.25)} className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400"><Plus className="w-3 h-3"/></button>
                                          </div>
                                        </div>

                                        <div className="flex items-center justify-center pt-8">
                                           <div className="w-8 h-[2px] bg-gray-100"></div>
                                        </div>

                                        <div className="flex-1 space-y-2">
                                          <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Kết thúc</label>
                                          <div className="flex items-center bg-gray-50 rounded-2xl p-2 border border-gray-100 group-focus-within:border-blue-500 transition-all">
                                            <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-1 text-xl font-black text-gray-900 outline-none tabular-nums cursor-pointer" />
                                          </div>
                                          <div className="flex justify-center gap-1.5 pt-1">
                                              <button type="button" onClick={() => adjustTime('end', -0.25)} className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400"><Minus className="w-3 h-3"/></button>
                                              <button type="button" onClick={() => adjustTime('end', 0.25)} className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400"><Plus className="w-3 h-3"/></button>
                                          </div>
