                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-3.5 text-[10px] font-black text-indigo-600 bg-white rounded-2xl border-2 border-indigo-50 hover:bg-indigo-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-[0.15em] shadow-sm">
