                    <div className="w-20 h-20 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-3xl shadow-lg shadow-rose-50 border-4 border-white"><Trash2 className="w-10 h-10"/></div>
                    <h3 className="text-xl font-black text-gray-900 mb-3 uppercase tracking-tighter">Hủy đăng ký?</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase opacity-60 mb-10 leading-relaxed px-4 tracking-widest">Hành động này không thể hoàn tác.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={() => { handleCancelRequest(); setIsConfirmCancelOpen(false); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-xl shadow-rose-200 transition-all active:scale-95">XÓA DỮ LIỆU</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-5 bg-white text-gray-400 font-black rounded-2xl border-2 border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  CalendarDays, Eye, Trophy, Award, ArrowRight, Check, Plus, Minus,
  Users, Download, Settings2, Sparkles
} from 'lucide-react';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const numberToTime = (n: number) => {
  const h = Math.floor(n);
  const m = Math.round((n - h) * 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

const getColleagueColor = (name: string) => {
  const colors = ['bg-blue-100 text-blue-600', 'bg-indigo-100 text-indigo-600', 'bg-violet-100 text-violet-600', 'bg-purple-100 text-purple-600', 'bg-sky-100 text-sky-600'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => !isAdmin && targetUserId !== user.id, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const adjustTime = (type: 'start' | 'end', delta: number) => {
    if (isViewOnly) return;
    const currentVal = type === 'start' ? startTime : endTime;
    const num = timeToNumber(currentVal);
    let next = num + delta;
    if (next < 0) next = 0;
    if (next > 23.75) next = 23.75;
    const nextTime = numberToTime(next);
    if (type === 'start') setStartTime(nextTime);
    else setEndTime(nextTime);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    try {
      const rewritten = await rewriteOvertimeReason(reason);
      if (rewritten) setReason(rewritten);
    } catch (err) { console.error(err); } finally { setIsRewriting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    try {
      const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
      if (error) throw error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) { alert(err.message); }
  };

  const handleExportToday = () => {
    const todayReqs = requests.filter(r => r.date === todayStr);
    if (todayReqs.length === 0) return alert("Không có dữ liệu hôm nay.");
    const workbook = XLSX.utils.book_new();
    const worksheet = XLSX.utils.json_to_sheet(todayReqs.map(req => ({
        'Ngày': req.date, 'Họ tên': req.users?.name, 'Bắt đầu': req.start_time, 'Kết thúc': req.end_time, 'Tổng giờ': req.total_hours, 'Lý do': req.reason
    })));
    XLSX.utils.book_append_sheet(workbook, worksheet, 'OT-Today');
    XLSX.writeFile(workbook, `OT_Report_${todayStr}.xlsx`);
  };

  const top5Rankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 5);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;

    for (let i = 0; i < offset; i++) {
        days.push(<div key={`e-${i}`} className="h-20 md:h-36 border-b border-r border-gray-100 bg-gray-50/20"></div>);
    }

    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isToday = todayStr === dStr;
      const dayReqs = requests.filter(r => r.date === dStr);

      const dateObj = new Date(dStr);
      const dayOfWeek = dateObj.getDay();
      const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
      const config = dayConfigs[dStr] ?? (dayOfWeek !== 0);

      days.push(
        <div 
          key={d} 
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-20 md:h-36 relative transition-all cursor-pointer flex flex-col p-3 border-b border-r border-gray-100 ${isToday ? 'bg-blue-50/60 ring-inset ring-1 ring-blue-500 z-10' : 'bg-white hover:bg-gray-50'}`}
        >
          <div className="flex items-start justify-between">
            <span className={`text-sm md:text-base font-bold ${isWeekend ? 'text-rose-500' : 'text-gray-700'}`}>{d}</span>
            <div className="flex flex-col items-end gap-1">
                {isWeekend && (
                   <span className="w-5 h-5 rounded-full bg-rose-500 text-white text-[9px] font-black flex items-center justify-center shadow-sm">N</span>
                )}
                {!config && !isWeekend && (
                   <span className="w-5 h-5 rounded-full bg-rose-100 text-rose-500 text-[9px] font-black flex items-center justify-center border border-rose-200">N</span>
                )}
                {config && isWeekend && (
                   <span className="w-5 h-5 rounded-full bg-blue-600 text-white text-[9px] font-black flex items-center justify-center shadow-sm">L</span>
                )}
            </div>
          </div>

          <div className="flex-1 flex flex-col justify-center gap-1 mt-2">
            {dayReqs.length > 0 && (
                <div className="flex flex-wrap gap-1">
                    {dayReqs.slice(0, 4).map((r, i) => (
                        <div key={i} className={`w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[8px] font-black uppercase border border-white shadow-sm ${getColleagueColor(r.users?.name || '')}`}>
                            {r.users?.name?.charAt(0)}
                        </div>
                    ))}
                    {dayReqs.length > 4 && (
                        <div className="w-5 h-5 md:w-6 md:h-6 rounded-full bg-gray-100 flex items-center justify-center text-[7px] font-bold text-gray-500 border border-gray-200">
                            +{dayReqs.length - 4}
                        </div>
                    )}
                </div>
            )}
          </div>

          {dayReqs.length > 0 && (
            <div className="absolute bottom-1 right-2">
                <span className="text-[9px] font-black text-gray-400 bg-gray-50 px-1.5 py-0.5 rounded border border-gray-100">{dayReqs.length}</span>
            </div>
          )}
        </div>
      );
    }

    // Fill remaining cells
    const remaining = 42 - days.length;
    for (let i = 0; i < remaining; i++) {
        days.push(<div key={`f-${i}`} className="h-20 md:h-36 border-b border-r border-gray-100 bg-gray-50/10"></div>);
    }

    return <div className="grid grid-cols-7 border-l border-t border-gray-100 rounded-b-3xl overflow-hidden">{days}</div>;
  };

  return (
    <div className="space-y-6 h-full flex flex-col animate-fade-in max-w-screen-2xl mx-auto px-4 pb-12">
        {/* Top Header Section */}
        <div className="flex flex-col md:flex-row justify-between items-center gap-6 bg-white p-6 md:p-8 rounded-[2rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-5">
                <div className="flex flex-col">
                    <div className="flex items-center gap-3">
                        <h2 className="text-2xl md:text-3xl font-black text-gray-900 tracking-tight">Tăng ca</h2>
                        <span className="bg-indigo-600 text-white text-[9px] font-black px-2 py-0.5 rounded-md uppercase">TOOL V2</span>
                    </div>
                    <p className="text-[11px] text-gray-400 font-bold mt-1 tracking-wide italic">Tháng 12 / 2025</p>
                </div>
            </div>

            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto justify-center">
                <div className="flex bg-gray-50 p-1.5 rounded-2xl border border-gray-100 shadow-inner">
                    <button onClick={() => setActiveTab('calendar')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all ${activeTab === 'calendar' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}>Lịch</button>
                    <button onClick={() => setActiveTab('personal')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all ${activeTab === 'personal' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}>Tôi</button>
                    <button onClick={() => setActiveTab('stats')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-md' : 'text-gray-400'}`}>Thống kê</button>
                </div>

                <button 
                  onClick={handleExportToday} 
                  className="flex items-center gap-2 bg-[#10b981] hover:bg-[#059669] text-white px-6 py-3.5 rounded-2xl text-[10px] font-black uppercase shadow-lg shadow-emerald-100 transition-all active:scale-95 group"
                >
                    <Sparkles className="w-4 h-4 fill-white animate-pulse" /> Xuất Excel hôm nay
                </button>
            </div>
        </div>

        {/* Content Area */}
        <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[3rem] bg-white flex flex-col">
            {/* Calendar Controls */}
            <div className="flex items-center justify-between p-8 bg-white">
                <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-gray-100 rounded-full transition-all text-gray-400"><ChevronLeft className="w-6 h-6"/></button>
                <h3 className="text-xl md:text-2xl font-black uppercase tracking-[0.4em] text-gray-900">T12 - 2025</h3>
                <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-3 hover:bg-gray-100 rounded-full transition-all text-gray-400"><ChevronRight className="w-6 h-6"/></button>
            </div>

            {/* Weekday Names */}
            <div className="grid grid-cols-7 bg-white text-[10px] font-black uppercase text-gray-400 text-center py-5 border-t border-b border-gray-50">
                {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => (
                    <div key={d} className={`tracking-widest ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>
                ))}
            </div>

            {activeTab === 'calendar' ? renderCalendar() : (
                <div className="p-12 text-center text-gray-300 font-bold uppercase tracking-widest italic h-96 flex items-center justify-center">
                   Nội dung đang được cập nhật...
                </div>
            )}
        </Card>

        {/* Stats Section Overlay (Optional but good for UX) */}
        {activeTab === 'calendar' && (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6">
                <Card className="p-8 rounded-[2.5rem] bg-white shadow-lg border-none">
                    <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                        <Activity className="w-4 h-4 text-blue-500" /> Hoạt động gần đây
                    </h4>
                    <div className="space-y-4">
                        {requests.slice(0, 3).map((r, i) => (
                            <div key={i} className="flex items-center justify-between p-3 rounded-2xl bg-gray-50 border border-gray-100">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold text-xs uppercase">{r.users?.name?.charAt(0)}</div>
                                    <div className="text-[11px] font-bold text-gray-700">{r.users?.name} - {r.date}</div>
                                </div>
                                <div className="text-[10px] font-black text-blue-600">+{r.total_hours}H</div>
                            </div>
                        ))}
                    </div>
                </Card>
                <Card className="p-8 rounded-[2.5rem] bg-white shadow-lg border-none">
                    <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                        <Trophy className="w-4 h-4 text-amber-500" /> Bảng xếp hạng tháng 12
                    </h4>
                    <div className="space-y-3">
                        {top5Rankings.map((e, i) => (
                            <div key={i} className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <span className={`text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-full ${i === 0 ? 'bg-amber-100 text-amber-600' : 'bg-gray-100 text-gray-400'}`}>{i + 1}</span>
                                    <span className="text-xs font-black text-gray-800 uppercase tracking-tighter">{e.name}</span>
                                </div>
                                <span className="text-xs font-black text-indigo-600 tabular-nums">{e.hours.toFixed(1)}H</span>
                            </div>
                        ))}
                    </div>
                </Card>
             </div>
        )}

        {/* Form Modal */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-blue-600 p-6 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <h3 className="text-xl font-black uppercase leading-none tracking-tighter">Ngày {selectedDateStr.split('-').reverse().join('/')}</h3>
                            <p className="text-[10px] text-blue-200 font-bold uppercase mt-1.5 tracking-widest">Đăng ký ca làm thêm</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2.5 hover:bg-white/20 rounded-xl transition-all"><X className="w-6 h-6"/></button>
                    </div>

                    <div className="p-8 space-y-6 overflow-y-auto no-scrollbar bg-gray-50/50 flex-1">
                        {isAdmin && (
                            <div className="bg-white p-5 rounded-3xl border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest flex items-center gap-2"><Settings2 className="w-4 h-4"/> Cấu hình ngày</h4>
                                <div className="grid grid-cols-2 gap-3">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 text-[10px] font-black uppercase transition-all ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-rose-600 text-white border-rose-400' : 'bg-white text-gray-300 border-gray-100' }`}><Home className="w-4 h-4" /> Nghỉ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 text-[10px] font-black uppercase transition-all ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-white text-gray-300 border-gray-100' }`}><Briefcase className="w-4 h-4" /> Làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {isViewOnly ? (
                                <div className="bg-amber-50 border-2 border-amber-200 p-8 rounded-[2rem] text-center space-y-4 shadow-sm">
                                    <Eye className="w-10 h-10 text-amber-500 mx-auto" />
                                    <p className="text-[11px] font-black text-amber-900 uppercase leading-relaxed tracking-tight">Đang xem lịch đăng ký của người khác</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-4 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-2xl transition-all shadow-xl active:scale-95">Đăng ký cho chính mình</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-gray-400 uppercase ml-1 tracking-widest">Cán bộ OT:</label>
                                            <select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-5 py-4 bg-white border border-gray-200 rounded-2xl text-xs font-bold outline-none shadow-sm focus:border-indigo-600">
                                                {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}
                                            </select>
                                        </div>
                                    )}

                                    <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
                                      <div className="flex items-center justify-between px-2">
                                        <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest">Khung giờ làm thêm</h4>
                                        <div className="bg-indigo-600 text-white px-4 py-1.5 rounded-full text-[10px] font-black shadow-lg">
                                          {calculatedHours}H TỔNG
                                        </div>
                                      </div>

                                      <div className="flex items-center gap-4">
                                        <div className="flex-1 space-y-2">
                                          <div className="flex items-center bg-gray-50 rounded-2xl p-2 border border-gray-100">
                                            <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-transparent border-none p-1 text-xl font-black text-gray-900 outline-none tabular-nums" />
                                          </div>
                                          <div className="flex justify-center gap-2">
                                              <button type="button" onClick={() => adjustTime('start', -0.25)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><Minus className="w-3 h-3"/></button>
                                              <button type="button" onClick={() => adjustTime('start', 0.25)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><Plus className="w-3 h-3"/></button>
                                          </div>
                                        </div>
                                        <ArrowRight className="w-4 h-4 text-gray-200 shrink-0" />
                                        <div className="flex-1 space-y-2">
                                          <div className="flex items-center bg-gray-50 rounded-2xl p-2 border border-gray-100">
                                            <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full bg-transparent border-none p-1 text-xl font-black text-gray-900 outline-none tabular-nums" />
                                          </div>
                                          <div className="flex justify-center gap-2">
                                              <button type="button" onClick={() => adjustTime('end', -0.25)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><Minus className="w-3 h-3"/></button>
                                              <button type="button" onClick={() => adjustTime('end', 0.25)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><Plus className="w-3 h-3"/></button>
                                          </div>
                                        </div>
                                      </div>
                                    </div>

                                    <div className="space-y-3">
                                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nội dung công việc</label>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-5 bg-white border border-gray-100 rounded-[1.5rem] text-xs h-28 resize-none outline-none font-bold text-gray-800 shadow-inner" placeholder="Tóm tắt công việc bạn sẽ xử lý..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-3 text-[10px] font-black text-indigo-600 bg-white rounded-xl border-2 border-indigo-50 hover:bg-indigo-600 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest">
                                            {isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>} Tối ưu nội dung AI
                                        </button>
                                    </div>

                                    <div className="flex gap-3 pt-4">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all">
                                                <Trash2 className="w-6 h-6" />
                                            </button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-5 bg-blue-600 text-white font-black rounded-[1.5rem] shadow-xl text-[10px] uppercase tracking-[0.2em] transition-all active:scale-[0.98] disabled:opacity-50">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật đăng ký' : 'Gửi đăng ký'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import * as XLSX from 'xlsx';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Zap, Home, Briefcase, 
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Award, ArrowRight, Check, Plus, Minus
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const numberToTime = (n: number) => {
  const h = Math.floor(n);
  const m = Math.round((n - h) * 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

const getColleagueColor = (name: string) => {
  const colors = ['bg-blue-600', 'bg-indigo-600', 'bg-violet-600', 'bg-purple-600', 'bg-sky-600', 'bg-blue-500'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Form states
  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-32 bg-gray-50/20 opacity-30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isT = todayStr === dStr;
      const isP = new Date(dStr).getTime() < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div key={d} onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} className={`h-16 md:h-32 relative transition-all cursor-pointer group flex flex-col p-2 border-b border-r border-gray-100 ${isT ? 'bg-rose-50/50 ring-inset ring-2 ring-rose-500 z-10' : 'bg-white hover:bg-gray-50'}`}>
          <div className="flex items-center justify-between">
            <span className={`text-xs md:text-lg font-black ${isT ? 'text-rose-600' : !config ? 'text-rose-400' : isP ? 'text-gray-300' : 'text-gray-900'}`}>{d}</span>
            {!config && <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>}
          </div>
          <div className="flex-1 flex flex-col justify-center gap-1 mt-1 overflow-hidden">
            {(myReq || otherReqs.length > 0) && (
              <div className="flex -space-x-1.5 items-center">
                {myReq && (
                   <div className="relative group/avatar">
                     <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-emerald-500 text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased">{user.name.charAt(0)}</div>
                     <div className="absolute -bottom-0.5 -right-0.5 bg-blue-500 text-white rounded-full border border-white w-2 h-2 md:w-3 md:h-3 flex items-center justify-center"><Check className="w-1.5 h-1.5 md:w-2 md:h-2 stroke-[4]" /></div>
                   </div>
                )}
                {otherReqs.slice(0, myReq ? 2 : 3).map((r, i) => (
                  <div key={i} className={`w-4 h-4 md:w-6 md:h-6 rounded-lg ${getColleagueColor(r.users?.name || '')} text-white flex items-center justify-center font-black text-[7px] md:text-[10px] uppercase shadow-sm border border-white antialiased`}>{r.users?.name?.charAt(0)}</div>
                ))}
                {dayReqs.length > 3 && <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-gray-100 border border-white flex items-center justify-center text-[6px] md:text-[8px] font-black text-gray-400">+{dayReqs.length-3}</div>}
              </div>
            )}
          </div>
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white">{days}</div>;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 md:p-4 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-600 rounded-xl text-white shadow-md shadow-blue-100"><Clock className="w-5 h-5" /></div>
                <h2 className="text-lg md:text-xl font-black text-gray-900 uppercase tracking-tight">Đăng ký tăng ca</h2>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100 p-1 rounded-xl">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-6 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-xl rounded-2xl bg-white">
                    <div className="flex items-center justify-between p-4 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5 text-gray-400"/></button>
                        <h3 className="text-sm md:text-xl font-black uppercase tracking-[0.2em] text-gray-800">Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-50 rounded-lg transition-colors"><ChevronRight className="w-5 h-5 text-gray-400"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[8px] font-black uppercase text-gray-400 text-center py-2.5 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map(d => <div key={d} className="tracking-widest">{d}</div>)}
                    </div>
                    {renderCalendar()}
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-blue-600 to-indigo-800 text-white border-none p-4 rounded-3xl shadow-lg">
                            <h3 className="text-[8px] font-black uppercase opacity-70 mb-1 tracking-wider">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-1.5"><span className="text-2xl md:text-4xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-60 pb-1">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 rounded-3xl border-l-4 border-emerald-500 shadow-sm bg-white">
                            <p className="text-[8px] font-black text-gray-400 uppercase tracking-wider">Số ngày OT</p>
                            <p className="text-xl md:text-2xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                    </div>
                    <Card className="p-4 rounded-3xl shadow-sm border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[9px] mb-6 flex items-center gap-2 tracking-widest"><Activity className="w-4 h-4 text-blue-600" /> Biểu đồ hiệu suất tháng</h3>
                        <div className="h-44 md:h-64 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(59, 130, 246, 0.05)'}}/><Bar dataKey="hours" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={window.innerWidth < 640 ? 6 : 12} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 animate-fade-in-up">
                    <Card className="rounded-2xl p-0 flex flex-col bg-white shadow-sm overflow-hidden border-none">
                         <div className="p-4 bg-indigo-700 text-white flex justify-between items-center"><h4 className="text-[10px] font-black uppercase flex items-center gap-2 tracking-tight"><Award className="w-4 h-4 text-amber-400 drop-shadow-sm" /> Top Chăm chỉ T{currentDate.getMonth()+1}</h4></div>
                         <div className="p-3 space-y-2 max-h-[400px] overflow-y-auto no-scrollbar">
                            {topRankings.map((e, i) => (
                                <div key={i} className={`p-3 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/30 border-amber-200 shadow-sm' : 'bg-white border-gray-100'}`}>
                                    <div className="w-9 h-9 md:w-11 md:h-11 flex items-center justify-center font-black text-sm uppercase">
                                      {i === 0 ? <Trophy className="w-8 h-8 text-amber-500" /> : <div className={`w-10 h-10 rounded-xl ${getColleagueColor(e.name)} text-white flex items-center justify-center`}>{e.name.charAt(0)}</div>}
                                    </div>
                                    <div className="flex-1 min-w-0"><h5 className="font-black text-gray-900 text-[11px] truncate uppercase tracking-tight">{e.name}</h5><p className="text-[8px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày</p></div>
                                    <div className="text-right"><span className="text-sm font-black text-indigo-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[8px] font-black text-gray-300 ml-1 uppercase">H</span></div>
                                </div>
                            ))}
                         </div>
                    </Card>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-sm animate-fade-in px-4">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-blue-600 p-4 flex justify-between items-center text-white shrink-0 shadow-lg">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2.5"><CalendarDays className="w-5 h-5 text-blue-200" /><h3 className="text-lg font-black uppercase leading-none tracking-tight">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[8px] text-blue-200 font-bold uppercase mt-1 opacity-70 tracking-widest">Chi tiết đăng ký</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-xl transition-all"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 space-y-4 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm space-y-4">
