import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Bell, User, Clock, Loader2, Menu, RefreshCw, Trash2, X, CheckCircle2, AlertTriangle, Snowflake } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest } from '../../../types';

interface HeaderProps {
  user: any;
  onMenuClick?: () => void;
}

interface NotificationItem {
  id: string;
  type: 'borrow' | 'overtime';
  title: string;
  message: string;
  time: string;
  status: 'pending' | 'approved' | 'rejected' | 'returned';
  isRead: boolean;
}

export const Header: React.FC<HeaderProps> = ({ user, onMenuClick }) => {
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const getDismissedIds = (): string[] => {
    const stored = localStorage.getItem(`dismissed_notifs_${user?.id}`);
    return stored ? JSON.parse(stored) : [];
  };

  const getSeenIds = (): string[] => {
    const stored = localStorage.getItem(`seen_notifs_${user?.id}`);
    return stored ? JSON.parse(stored) : [];
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchNotifications = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    try {
      const isAdmin = user.role === 'admin';
      const dismissedIds = getDismissedIds();
      const seenIds = getSeenIds();
      const notifs: NotificationItem[] = [];

      let borrowQuery = supabase.from('requests').select('*').order('borrow_date', { ascending: false }).limit(30);
      if (!isAdmin) borrowQuery = borrowQuery.eq('user_id', user.id);
      const { data: borrowData } = await borrowQuery;

      if (borrowData) {
        (borrowData as BorrowRequest[]).forEach(req => {
          let shouldNotify = false; 
          let title = ''; 
          let message = '';
          const uniqueId = `borrow-${req.id}-${req.status}`;
          if (dismissedIds.includes(uniqueId)) return;

          if (isAdmin) {
            if (req.status === 'pending') { 
              shouldNotify = true; 
              title = 'Món quà mượn mới'; 
              message = `${req.user_name} chờ bạn duyệt ${req.tool_name}`; 
            }
          } else {
            if (req.user_id === user.id && req.status !== 'pending') { 
              shouldNotify = true; 
              title = 'Tin nhắn từ tuần lộc'; 
              const statusText = req.status === 'approved' ? 'đã được DUYỆT' : req.status === 'rejected' ? 'bị TỪ CHỐI' : 'đã HOÀN TRẢ';
              message = `Món quà "${req.tool_name}" ${statusText}`; 
            }
          }

          if (shouldNotify) {
            notifs.push({ 
              id: uniqueId, 
              type: 'borrow', 
              title, 
              message, 
              time: req.status === 'returned' ? (req.returned_at || req.borrow_date) : req.borrow_date, 
              status: req.status, 
              isRead: seenIds.includes(uniqueId)
            });
          }
        });
      }

      const sortedNotifs = notifs.sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());
      setNotifications(sortedNotifs);
      const unread = sortedNotifs.filter(n => !seenIds.includes(n.id)).length;
      setUnreadCount(unread);
    } catch (error) { 
      console.error("Lỗi thông báo:", error); 
    } finally { 
      setLoading(false); 
    }
  }, [user]);

  useEffect(() => { 
    fetchNotifications(); 
    const handleRefresh = () => fetchNotifications();
    window.addEventListener('refresh-counts', handleRefresh);
    const interval = setInterval(fetchNotifications, 20000);
    return () => {
      window.removeEventListener('refresh-counts', handleRefresh);
      clearInterval(interval);
    };
  }, [fetchNotifications]);

  const handleBellClick = () => {
    setIsOpen(!isOpen);
    if (!isOpen) {
      const currentIds = notifications.map(n => n.id);
      const seenIds = Array.from(new Set([...getSeenIds(), ...currentIds]));
      localStorage.setItem(`seen_notifs_${user?.id}`, JSON.stringify(seenIds));
      setUnreadCount(0);
    }
  };

  const deleteNotification = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const dismissedIds = [...getDismissedIds(), id];
    localStorage.setItem(`dismissed_notifs_${user?.id}`, JSON.stringify(dismissedIds));
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  return (
    <header className="bg-white/80 backdrop-blur-md border-b border-gray-200 h-16 px-4 md:px-8 flex items-center justify-between sticky top-0 z-30 shadow-sm transition-all">
      <div className="flex items-center gap-3">
        <button onClick={onMenuClick} className="lg:hidden p-2 -ml-2 hover:bg-red-50 rounded-xl transition-colors">
          <Menu className="w-6 h-6 text-red-700" />
        </button>
        <span className="hidden sm:block text-xs md:text-sm font-medium text-red-800/60 italic flex items-center gap-2">
          <Snowflake className="w-4 h-4 text-blue-200" />
          {new Date().toLocaleDateString('vi-VN', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' })}
        </span>
      </div>

      <div className="flex items-center gap-3 md:gap-6">
        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={handleBellClick} 
            className={`relative p-2.5 rounded-xl transition-all ${isOpen ? 'bg-red-50 text-red-600 shadow-inner' : 'text-gray-500 hover:bg-gray-100'}`}
          >
            <Bell className="w-5 h-5" />
            {unreadCount > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[9px] font-black min-w-[18px] h-[18px] px-1 flex items-center justify-center rounded-full border-2 border-white shadow-lg animate-bounce-short">
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>

          {isOpen && (
            <div className="absolute right-0 top-full mt-3 w-80 sm:w-96 bg-white rounded-[2rem] shadow-2xl border border-red-100 overflow-hidden animate-fade-in-up origin-top-right ring-1 ring-black/5">
              <div className="p-5 border-b bg-red-50 flex justify-between items-center">
                <div className="flex items-center gap-2">
                  <h3 className="font-black text-red-800 text-xs uppercase tracking-widest">Tin nhắn Noel</h3>
                  <span className="bg-red-200 text-red-700 text-[9px] font-black px-2 py-0.5 rounded-full uppercase">Santa News</span>
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); fetchNotifications(); }} 
                  className={`p-2 hover:bg-white rounded-xl transition-all ${loading ? 'animate-spin' : ''}`}
                >
                  <RefreshCw className="w-3.5 h-3.5 text-red-600" />
                </button>
              </div>

              <div className="max-h-[400px] overflow-y-auto no-scrollbar bg-white">
                {notifications.length === 0 ? (
                  <div className="p-16 text-center flex flex-col items-center gap-3">
                    <div className="p-4 bg-gray-50 rounded-full">
                       <Bell className="w-8 h-8 text-gray-200" />
                    </div>
                    <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest italic">Santa chưa có tin gì mới</p>
                  </div>
                ) : (
                  <ul className="divide-y divide-gray-50">
                    {notifications.map((n) => (
                      <li key={n.id} className="relative p-5 hover:bg-red-50/30 transition-all border-l-4 border-l-transparent hover:border-l-red-600 group">
                        <div className="flex justify-between items-start gap-3">
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-1">
                              <span className={`w-1.5 h-1.5 rounded-full ${n.status === 'pending' ? 'bg-amber-500' : n.status === 'approved' ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
                              <p className="text-xs font-black text-gray-900 leading-tight uppercase tracking-tight">{n.title}</p>
                            </div>
                            <p className="text-[11px] text-gray-600 font-medium leading-relaxed pr-6">{n.message}</p>
                            <div className="flex items-center gap-2 mt-3 text-[9px] font-black text-gray-300 uppercase">
                                <Clock className="w-3 h-3" />
                                {new Date(n.time).toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })} • {new Date(n.time).toLocaleDateString('vi-VN')}
                            </div>
                          </div>
                          <button 
                            onClick={(e) => deleteNotification(e, n.id)}
                            className="absolute top-5 right-5 p-1.5 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3 pl-4 md:pl-6 border-l border-gray-100">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-black text-gray-900 tracking-tight leading-none">{user?.name || 'Thành viên'}</p>
            <p className="text-[10px] text-red-700 font-black uppercase tracking-[0.15em] mt-1.5">Noel Staff ❄</p>
          </div>
          <div className="relative group">
            <div className="w-10 h-10 bg-gradient-to-br from-red-600 to-red-900 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-red-200 border-2 border-white transform hover:rotate-6 transition-transform cursor-pointer">
               <User className="w-5 h-5" />
            </div>
            {/* Santa Hat Emoji Overlay */}
            <span className="absolute -top-3 -right-2 text-lg drop-shadow-md group-hover:scale-125 transition-transform">🎅</span>
          </div>
        </div>
      </div>
    </header>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Home, Briefcase, CalendarDays, Eye, Trophy, Award, 
  Check, Snowflake, Star, User as UserIcon, Users as UsersIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

const getColleagueColor = (name: string) => {
  const colors = ['bg-rose-500', 'bg-emerald-600', 'bg-amber-500', 'bg-blue-600', 'bg-indigo-600', 'bg-slate-700'];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-20 md:h-36 bg-gray-50/20"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isT = todayStr === dStr;
      const isP = new Date(dStr).getTime() < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div 
          key={d} 
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-20 md:h-36 relative transition-all cursor-pointer group flex flex-col p-2 border-b border-r border-gray-100 ${isT ? 'bg-red-50/50 ring-inset ring-2 ring-red-600 z-10' : 'bg-white hover:bg-gray-50'}`}
        >
          {/* Day Header */}
          <div className="flex items-center justify-between z-10">
            <span className={`text-xs md:text-xl font-black tabular-nums ${isT ? 'text-red-700' : !config ? 'text-rose-400' : isP ? 'text-gray-300' : 'text-gray-900'}`}>{d}</span>
            {!config && <span className="text-[6px] md:text-[8px] font-black px-1.5 py-0.5 rounded-full bg-rose-100 text-rose-600 uppercase">Lễ</span>}
          </div>

          {/* Content Area */}
          <div className="flex-1 flex flex-col mt-1 space-y-2 overflow-hidden">
            {/* My Presence (Prominent - Top) */}
            {myReq && (
              <div className="animate-fade-in-up">
                <div className="relative inline-flex">
                  <div className="w-6 h-6 md:w-9 md:h-9 rounded-xl bg-gradient-to-br from-red-600 to-red-800 text-white flex items-center justify-center font-black text-[9px] md:text-xs shadow-lg border-2 border-white ring-2 ring-red-100 antialiased transform -rotate-3 transition-transform group-hover:rotate-0">
                    {user.name.charAt(0)}
                  </div>
                  <div className="absolute -top-1 -right-1 bg-amber-400 text-red-900 rounded-full w-2.5 h-2.5 md:w-4 md:h-4 flex items-center justify-center shadow-sm border border-white">
                    <Star className="w-1.5 h-1.5 md:w-2.5 md:h-2.5 fill-current" />
                  </div>
                </div>
              </div>
            )}

            {/* Others Presence (Secondary - Bottom) */}
            {otherReqs.length > 0 && (
              <div className={`flex flex-wrap items-center gap-1 ${!myReq ? 'mt-auto' : ''}`}>
                <div className="flex -space-x-2">
                  {otherReqs.slice(0, 3).map((r, i) => (
                    <div 
                      key={i} 
                      className={`w-4 h-4 md:w-6 md:h-6 rounded-lg ${getColleagueColor(r.users?.name || '')} text-white flex items-center justify-center font-black text-[6px] md:text-[8px] uppercase shadow-sm border border-white antialiased transition-transform group-hover:translate-x-0.5`}
                      title={r.users?.name}
                    >
                      {r.users?.name?.charAt(0)}
                    </div>
                  ))}
                  {otherReqs.length > 3 && (
                    <div className="w-4 h-4 md:w-6 md:h-6 rounded-lg bg-white border border-gray-200 flex items-center justify-center text-[5px] md:text-[7px] font-black text-gray-400 shadow-sm">
                      +{otherReqs.length - 3}
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Subtle Background Icon for Holidays */}
          {!config && (
            <div className="absolute bottom-1 right-1 opacity-[0.03] pointer-events-none">
              <Snowflake className="w-8 h-8 md:w-16 md:h-16 text-red-900" />
            </div>
          )}
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white rounded-b-3xl overflow-hidden border-l border-t border-gray-100">{days}</div>;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-2 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white/80 backdrop-blur-md p-4 md:p-6 rounded-[2rem] shadow-xl border border-white/50">
            <div className="flex items-center gap-4">
                <div className="p-3 bg-red-700 rounded-2xl text-white shadow-lg shadow-red-200"><Clock className="w-6 h-6" /></div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 uppercase tracking-tighter italic">Quản lý tăng ca</h2>
                    <p className="text-[9px] font-black text-red-700 uppercase tracking-[0.2em] mt-1 opacity-60">Christmas Edition ❄</p>
                </div>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
                <div className="flex flex-1 md:flex-none bg-gray-100/50 p-1 rounded-2xl border border-gray-200/50">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:px-8 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === t ? 'bg-red-700 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <div className="h-full flex flex-col shadow-2xl rounded-[2.5rem] bg-white overflow-hidden border border-gray-100">
                    <div className="flex items-center justify-between p-6 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-red-50 rounded-2xl transition-all text-red-700"><ChevronLeft className="w-6 h-6"/></button>
                        <div className="text-center">
                            <h3 className="text-lg md:text-2xl font-black uppercase tracking-[0.3em] text-gray-900">Tháng {currentDate.getMonth()+1}</h3>
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-1">Year {currentDate.getFullYear()}</p>
                        </div>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-3 hover:bg-red-50 rounded-2xl transition-all text-red-700"><ChevronRight className="w-6 h-6"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[9px] font-black uppercase text-gray-400 text-center py-4 border-b border-gray-100 tracking-[0.2em]">
                        {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <div key={d}>{d}</div>)}
                    </div>
                    {renderCalendar()}
                </div>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        <Card className="bg-gradient-to-br from-red-700 to-red-900 text-white border-none p-6 rounded-[2.5rem] shadow-2xl shadow-red-200">
                            <h3 className="text-[10px] font-black uppercase opacity-60 mb-2 tracking-widest">Tổng giờ tích lũy</h3>
                            <div className="flex items-end gap-2"><span className="text-4xl md:text-5xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-xs font-bold opacity-50 pb-2 uppercase tracking-tighter">Hours</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-6 rounded-[2.5rem] border-2 border-emerald-50 shadow-sm bg-white relative overflow-hidden group">
                            <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform"><Check className="w-12 h-12 text-emerald-600" /></div>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Số ngày OT</p>
                            <p className="text-3xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                    </div>
                    <Card className="p-6 md:p-10 rounded-[3rem] shadow-xl border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[11px] mb-10 flex items-center gap-3 tracking-[0.2em]"><Activity className="w-5 h-5 text-red-600" /> Hiệu suất làm việc tháng {currentDate.getMonth()+1}</h3>
                        <div className="h-64 md:h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -30}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 9, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 9}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '11px', borderRadius: '15px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(185, 28, 28, 0.05)'}}/><Bar dataKey="hours" fill="#b91c1c" radius={[6, 6, 0, 0]} barSize={window.innerWidth < 640 ? 8 : 16} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-6 animate-fade-in-up">
                    <Card className="rounded-[3rem] p-0 flex flex-col bg-white shadow-2xl overflow-hidden border-none">
                         <div className="p-6 md:p-8 bg-gradient-to-r from-red-800 to-red-950 text-white flex justify-between items-center">
                            <div>
                                <h4 className="text-[12px] font-black uppercase flex items-center gap-3 tracking-widest"><Award className="w-6 h-6 text-amber-400" /> Bảng vàng cống hiến</h4>
                                <p className="text-[9px] font-bold opacity-40 uppercase mt-1 tracking-tight">Tháng {currentDate.getMonth()+1} • Season of Giving</p>
                            </div>
                         </div>
                         <div className="p-4 md:p-8 space-y-3 max-h-[500px] overflow-y-auto no-scrollbar">
                            {topRankings.map((e, i) => (
                                <div key={i} className={`p-4 rounded-2xl border flex items-center gap-4 transition-all hover:translate-x-1 ${i === 0 ? 'bg-amber-50/50 border-amber-200' : 'bg-white border-gray-100'}`}>
                                    <div className="w-10 h-10 md:w-14 md:h-14 flex items-center justify-center font-black text-sm md:text-xl uppercase shrink-0">
                                      {i === 0 ? <Trophy className="w-8 h-8 md:w-12 md:h-12 text-amber-500" /> : <div className={`w-10 h-10 md:w-12 md:h-12 rounded-xl ${getColleagueColor(e.name)} text-white flex items-center justify-center shadow-md`}>{e.name.charAt(0)}</div>}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h5 className="font-black text-gray-900 text-sm md:text-lg truncate uppercase tracking-tight">{e.name}</h5>
                                        <p className="text-[8px] md:text-[10px] text-gray-400 font-bold tracking-widest mt-0.5">{e.count} Ngày đăng ký</p>
                                    </div>
                                    <div className="text-right">
                                        <div className="flex items-end gap-1"><span className="text-xl md:text-3xl font-black text-red-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[10px] font-black text-gray-300 uppercase pb-1 tracking-widest">H</span></div>
                                    </div>
                                </div>
                            ))}
                         </div>
                    </Card>
                </div>
            )}
        </div>

        {/* Modal Registration */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-red-950/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-md animate-fade-in px-4">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-slide-up overflow-hidden max-h-[90vh] flex flex-col border border-white/20">
                    <div className="bg-red-700 p-6 flex justify-between items-center text-white shrink-0 shadow-lg relative overflow-hidden">
                        <Snowflake className="absolute -top-4 -right-4 w-24 h-24 opacity-10 animate-spin-slow" />
                        <div className="flex flex-col relative z-10">
                            <div className="flex items-center gap-3"><CalendarDays className="w-6 h-6 text-red-200" /><h3 className="text-xl font-black uppercase leading-none tracking-tighter italic">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[9px] text-red-200 font-black uppercase mt-2 opacity-70 tracking-[0.2em]">Hồ sơ đăng ký tăng ca ❄</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-white/20 rounded-2xl transition-all relative z-10"><X className="w-6 h-6"/></button>
                    </div>

                    <div className="p-6 md:p-8 space-y-6 overflow-y-auto no-scrollbar bg-gray-50/50">
                        {isAdmin && (
                            <div className="bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm space-y-4">
                                <h4 className="text-[10px] font-black text-red-800 uppercase tracking-widest">Thiết lập loại hình ngày</h4>
                                <div className="grid grid-cols-2 gap-3">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-3 py-3.5 rounded-2xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-red-700 text-white border-red-500' : 'bg-white text-gray-300 border-gray-100 hover:border-red-100' }`}><Home className="w-4 h-4" /> Nghỉ lễ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-3 py-3.5 rounded-2xl border-2 text-[10px] font-black uppercase transition-all shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-white text-gray-300 border-gray-100 hover:border-emerald-100' }`}><Briefcase className="w-4 h-4" /> Đi làm</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {isViewOnly ? (
                                <div className="bg-white border-2 border-red-100 p-8 rounded-[2.5rem] text-center space-y-5 shadow-sm">
                                    <Eye className="w-10 h-10 text-red-500 mx-auto opacity-50" /><p className="text-[11px] font-black text-gray-500 uppercase leading-relaxed tracking-tight px-6">Bạn đang xem lịch trình của đồng nghiệp. Không thể chỉnh sửa.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-4 bg-red-700 text-white text-[11px] font-black uppercase rounded-2xl transition-all shadow-xl active:scale-95 tracking-widest">ĐĂNG KÝ CHO CÁ NHÂN</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && <div className="space-y-2"><label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Cán bộ OT:</label><select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-xs font-bold outline-none shadow-sm focus:border-red-600 appearance-none">{allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}</select></div>}

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Bắt đầu:</label>
                                            <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Kết thúc:</label>
                                            <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                    </div>

                                    <div className="bg-red-50/50 p-4 rounded-2xl border border-red-100 flex items-center justify-between">
                                        <span className="text-[10px] font-black text-red-700 uppercase tracking-widest">Tổng thời gian:</span>
                                        <span className="text-lg font-black text-red-800 tabular-nums">{calculatedHours} Giờ</span>
                                    </div>

                                    <div className="space-y-3">
                                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Nội dung thực hiện</label>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-5 bg-white border border-gray-100 rounded-[2rem] text-xs h-28 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-red-600 transition-all" placeholder="Tóm tắt công việc chi tiết..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-2 py-3 text-[10px] font-black text-red-700 bg-white rounded-2xl border-2 border-red-50 hover:bg-red-700 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">{isRewriting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Wand2 className="w-4 h-4"/>} Tối ưu nội dung AI</button>
                                    </div>
                                    <div className="flex gap-3 pt-4">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-5 h-5" /></button>}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-5 bg-red-700 text-white font-black rounded-2xl shadow-2xl text-[11px] uppercase tracking-[0.3em] transition-all active:scale-[0.98] disabled:opacity-50">{isSubmitting ? <Loader2 className="w-6 h-6 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật hồ sơ' : 'Gửi đăng ký'}</button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* Cancel Confirm */}
        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-red-950/95 z-[120] flex items-center justify-center p-6 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-10 text-center border border-white/20">
                    <div className="w-20 h-20 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-[2rem] shadow-lg shadow-rose-100"><Trash2 className="w-10 h-10"/></div>
                    <h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tight">Hủy đơn đăng ký?</h3>
                    <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-60 mb-10 leading-relaxed px-6">Dữ liệu này sẽ được xóa vĩnh viễn khỏi hệ thống quản lý.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-xl active:scale-95">XÁC NHẬN XÓA</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-5 bg-white text-gray-400 font-black rounded-2xl border-2 border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Home, Briefcase, CalendarDays, Eye, Trophy, Award, 
  Check, Snowflake, Star, Sparkles, AlertCircle
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-24 md:h-44 bg-gray-50/20 border-b border-r border-gray-100/30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isT = todayStr === dStr;
      const isF = new Date(dStr).getTime() > todayTime;
      const isP = new Date(dStr).getTime() < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div 
          key={d} 
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-24 md:h-44 relative transition-all cursor-pointer group flex flex-col p-2 md:p-3 border-b border-r border-gray-100 
            ${isT ? 'bg-red-50/60 z-10 shadow-[inset_0_0_20px_rgba(185,28,28,0.05)] ring-inset ring-4 ring-red-600' : 'bg-white hover:bg-gray-50'}
            ${isF && !isT ? 'border-dashed border-2 border-indigo-200' : ''}
          `}
        >
          {/* Day Header */}
          <div className="flex items-center justify-between z-10">
            <div className="relative">
              <span className={`text-xs md:text-2xl font-black tabular-nums tracking-tighter transition-all ${isT ? 'text-red-700' : !config ? 'text-rose-400' : isP ? 'text-gray-200' : 'text-gray-700'}`}>
                {d}
              </span>
              {isT && <Sparkles className="absolute -top-3 -right-3 w-3 md:w-5 h-3 md:h-5 text-amber-500 animate-pulse" />}
            </div>
            {!config && <span className="text-[6px] md:text-[9px] font-black px-2 py-0.5 rounded-full bg-rose-50 text-rose-500 uppercase border border-rose-100 shadow-sm">Nghỉ</span>}
          </div>

          {/* Hierarchical Content Area */}
          <div className="flex-1 flex flex-col mt-2 md:mt-4 space-y-4 overflow-hidden">
            {/* 1. MY AVATAR (Prominent / Top) */}
            {myReq && (
              <div className="flex items-start">
                <div className="relative">
