import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon, AlertCircle, ChevronRight, ArrowUpRight, Snowflake
} from 'lucide-react';

interface RequestManagerProps { user: User; }

const ToolTableImage = ({ toolId, toolName }: { toolId: string, toolName: string }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  return (
    <div className="w-12 h-12 bg-white border border-gray-100 rounded-2xl overflow-hidden flex items-center justify-center p-1 shadow-sm group-hover:scale-110 transition-transform">
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-5 h-5 text-gray-300" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    // Ưu tiên trạng thái: Pending -> Approved -> Returned -> Rejected
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      returned: 2,
      rejected: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      return matchesSearch && matchesStatus;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      // Nếu cùng trạng thái thì đơn mới nhất lên đầu
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchRequests();
    } catch (e: any) {
      alert(e.message);
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { 
        color: 'bg-amber-500 text-white shadow-amber-200/50', 
        icon: <Timer className="w-3.5 h-3.5 animate-pulse" />, 
        label: 'ĐANG CHỜ DUYỆT' 
      },
      approved: { 
        color: 'bg-emerald-600 text-white shadow-emerald-200/50', 
        icon: <PackageCheck className="w-3.5 h-3.5" />, 
        label: 'ĐANG CHO MƯỢN' 
      },
      returned: { 
        color: 'bg-slate-500 text-white shadow-slate-200/50', 
        icon: <RotateCcw className="w-3.5 h-3.5" />, 
        label: 'ĐÃ TRẢ THÀNH CÔNG' 
      },
      rejected: { 
        color: 'bg-rose-600 text-white shadow-rose-200/50', 
        icon: <XCircle className="w-3.5 h-3.5" />, 
        label: 'ĐÃ BỊ TỪ CHỐI' 
      }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2.5 px-5 py-2.5 rounded-2xl text-[9px] font-black tracking-widest border-4 border-white shadow-xl transform group-hover:scale-105 transition-transform ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white p-6 md:p-10 rounded-[2.5rem] shadow-xl border border-white/50 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-10 opacity-[0.03] pointer-events-none">
            <RefreshCw className="w-32 h-32 rotate-12" />
        </div>

        <div className="flex items-center gap-6 relative z-10">
          <div className="p-4 bg-red-700 rounded-3xl shadow-2xl shadow-red-100 text-white transform -rotate-3">
            <RefreshCw className="w-7 h-7" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tighter uppercase italic">Trung tâm mượn trả</h2>
            <p className="text-[10px] text-red-700 font-black uppercase tracking-[0.25em] mt-1 opacity-50 flex items-center gap-2">
                <Snowflake className="w-3 h-3" /> Xmas Approval Center ❄
            </p>
          </div>
        </div>

        <div className="flex bg-gray-100 p-1.5 rounded-[1.8rem] border border-gray-200 shadow-inner relative z-10">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}>TẤT CẢ ĐƠN</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}>ĐƠN CỦA TÔI</button>
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-1 group w-full">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 w-5 h-5 group-focus-within:text-red-700 transition-colors" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm theo nhân viên, thiết bị, mã NV..." 
            className="w-full pl-14 pr-6 py-5 bg-white border-none rounded-[1.8rem] text-sm font-bold outline-none ring-4 ring-transparent focus:ring-red-700/5 transition-all shadow-xl shadow-gray-200/50" 
          />
        </div>

        <div className="relative w-full md:w-auto">
            <select 
              value={filterStatus} 
              onChange={e => setFilterStatus(e.target.value)} 
              className="w-full md:w-auto px-8 py-5 bg-white border-none rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-xl shadow-gray-200/50 hover:bg-gray-50 transition-colors appearance-none pr-14"
            >
              <option value="all">TẤT CẢ TRẠNG THÁI</option>
              <option value="pending">⏳ ĐANG CHỜ DUYỆT</option>
              <option value="approved">📦 ĐANG CHO MƯỢN</option>
              <option value="returned">✅ ĐÃ TRẢ THÀNH CÔNG</option>
              <option value="rejected">❌ ĐÃ TỪ CHỐI</option>
            </select>
            <ChevronRight className="absolute right-5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none rotate-90" />
        </div>
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[3rem] bg-white">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-[0.25em]">Thành viên</th>
                <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-[0.25em]">Món quà / Thiết bị</th>
                <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-[0.25em]">Thời gian</th>
                <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-[0.25em] text-center">Tiến độ đơn</th>
                <th className="px-10 py-8 text-[10px] font-black text-gray-400 uppercase tracking-[0.25em] text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="py-32 text-center"><Loader2 className="w-12 h-12 animate-spin text-red-700 mx-auto opacity-10" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={5} className="py-32 text-center">
                    <div className="flex flex-col items-center gap-4 opacity-30">
                        <AlertCircle className="w-12 h-12 text-gray-400" />
                        <p className="text-xs font-black uppercase tracking-widest italic">Không tìm thấy yêu cầu nào</p>
                    </div>
                </td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className="group transition-all duration-300 hover:bg-red-50/20 border-l-[6px] border-l-transparent hover:border-l-red-700"
                  >
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-gray-900 text-white rounded-2xl flex items-center justify-center font-black text-base shadow-lg border-2 border-white group-hover:rotate-6 transition-transform">
                          {req.user_name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <div className="font-black text-gray-900 text-[14px] uppercase tracking-tighter leading-none">{req.user_name}</div>
                          <div className="text-[9px] text-red-700 font-black tracking-widest mt-2 opacity-40 uppercase">{req.employee_id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                        <div className="font-black text-gray-800 text-[13px] uppercase tracking-tight">{req.tool_name}</div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex flex-col gap-1 text-gray-400 font-black text-[10px] uppercase">
                        <span className="flex items-center gap-2"><Calendar className="w-3.5 h-3.5 text-red-400" /> {new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                        <span className="text-[8px] opacity-40 italic">Lúc: {new Date(req.borrow_date).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'})}</span>
                      </div>
                    </td>
                    <td className="px-10 py-6 text-center">
                      {getStatusBadge(req.status)}
                    </td>
                    <td className="px-10 py-6 text-right">
                      {processingId === req.id ? (
                        <div className="flex justify-end"><Loader2 className="w-7 h-7 animate-spin text-red-700" /></div>
                      ) : (
                        <div className="flex justify-end gap-3">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="flex items-center gap-2 px-6 py-3 bg-red-700 text-white rounded-xl text-[9px] font-black tracking-widest shadow-xl hover:bg-black active:scale-95 transition-all">DUYỆT ĐƠN</button>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-3 bg-white text-gray-300 border border-gray-100 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm" title="Từ chối"><X className="w-5 h-5" /></button>
                            </>
                          )}
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="flex items-center gap-2 px-6 py-3 bg-black text-white rounded-xl text-[9px] font-black tracking-widest shadow-xl hover:bg-red-700 active:scale-95 transition-all uppercase">
                              <RotateCcw className="w-3.5 h-3.5" /> THU HỒI QUÀ
                            </button>
                          )}
                          {(req.user_id === user.id && req.status === 'pending') && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="flex items-center gap-2 px-5 py-3 bg-rose-50 text-rose-600 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-600 hover:text-white transition-all"><Trash2 className="w-4 h-4" /> HỦY ĐƠN</button>
                          )}

                          {/* Trạng thái xem thông tin đơn (View Details) */}
                          <button className="p-3 bg-gray-50 text-gray-300 rounded-xl hover:bg-gray-900 hover:text-white transition-all opacity-0 group-hover:opacity-100"><ArrowUpRight className="w-5 h-5"/></button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  History, Search, Calendar, Filter, X, 
  User as UserIcon, ShieldCheck, ChevronDown, 
  SlidersHorizontal, ChevronLeft, ChevronRight, 
  Loader2, RefreshCw, AlertCircle, ChevronsLeft, ChevronsRight,
  Undo2, CheckCircle2, AlertTriangle, FileSpreadsheet,
  Download, ListFilter, CalendarDays, Activity, 
  ArrowUpRight, Clock, Box, LayoutPanelLeft, Timer, PackageCheck, XCircle, RotateCcw
} from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | 'yesterday' | 'thisWeek' | '7days' | '30days' | '90days' | 'thisMonth';

const ITEMS_PER_PAGE = 20;

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`fixed bottom-10 right-10 z-[100] ${type === 'success' ? 'bg-emerald-600' : 'bg-rose-600'} text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up border border-white/20 backdrop-blur-md`}>
      {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
      <p className="text-xs font-black uppercase tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-2 hover:bg-white/20 p-1 rounded-full"><X className="w-4 h-4"/></button>
    </div>
  );
};

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reBorrowingId, setReBorrowingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  // State phân trang
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async (silent = false) => {
    if (!user) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    setError(null);

    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
      }

      if (statusFilter !== 'all') {
        query = query.eq('status', statusFilter);
      }

      if (startDate) {
        query = query.gte('borrow_date', `${startDate}T00:00:00`);
      }
      if (endDate) {
        query = query.lte('borrow_date', `${endDate}T23:59:59`);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      if (data) {
        setLogs(data as ExtendedBorrowRequest[]);
      }
    } catch (err: any) {
      console.error("Fetch history error:", err);
      setError("Không thể tải dữ liệu lịch sử.");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, [user.id, startDate, endDate, statusFilter, user.role]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Quản lý';
    if (req.status === 'rejected') return req.rejected_by || 'Quản lý';
    return '-';
  };

  const handleReBorrow = async (log: ExtendedBorrowRequest) => {
    setReBorrowingId(log.id);
    try {
      const { error } = await supabase.from('requests').insert([{
        user_id: user.id,
        user_name: user.name,
        employee_id: user.employeeCode,
        tool_id: log.tool_id,
        tool_name: log.tool_name,
        borrow_date: new Date().toISOString(),
        status: 'pending'
      }]);

      if (error) throw error;

      setToast({ message: "Đã gửi yêu cầu mượn lại thành công!", type: 'success' });
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchHistory(true);
    } catch (err: any) {
      setToast({ message: "Lỗi: " + err.message, type: 'error' });
    } finally {
      setReBorrowingId(null);
    }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.trim().toLowerCase();
      const handlerLower = handlerFilter.trim().toLowerCase();

      const matchesText = !searchLower || (
        log.user_name?.toLowerCase().includes(searchLower) ||
        log.employee_id?.toLowerCase().includes(searchLower) ||
        log.tool_name?.toLowerCase().includes(searchLower)
      );

      const currentHandler = getHandlerName(log).toLowerCase();
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);

      return matchesText && matchesHandler;
    });
  }, [logs, searchText, handlerFilter]);

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-500 text-white shadow-amber-200/50', icon: <Timer className="w-3 h-3 animate-pulse" />, label: 'CHỜ DUYỆT' },
      approved: { color: 'bg-emerald-600 text-white shadow-emerald-200/50', icon: <PackageCheck className="w-3 h-3" />, label: 'ĐANG MƯỢN' },
      returned: { color: 'bg-slate-500 text-white shadow-slate-200/50', icon: <RotateCcw className="w-3 h-3" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-rose-600 text-white shadow-rose-200/50', icon: <XCircle className="w-3 h-3" />, label: 'TỪ CHỐI' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl text-[8px] font-black tracking-widest border-2 border-white shadow-md ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  const summaryStats = useMemo(() => {
    return {
      total: logs.length,
      pending: logs.filter(l => l.status === 'pending').length,
      borrowing: logs.filter(l => l.status === 'approved').length,
      completed: logs.filter(l => l.status === 'returned' || l.status === 'rejected').length
    };
  }, [logs]);

  const handleExportExcel = () => {
    if (filteredLogs.length === 0) return alert("Không có dữ liệu để xuất.");

    const exportData = filteredLogs.map(log => ({
      'Người mượn': log.user_name,
      'Mã nhân viên': log.employee_id,
      'Thiết bị': log.tool_name,
      'Ngày mượn': new Date(log.borrow_date).toLocaleString('vi-VN'),
      'Ngày trả': log.returned_at ? new Date(log.returned_at).toLocaleString('vi-VN') : 'Chưa trả',
      'Người xử lý': getHandlerName(log),
      'Trạng thái': log.status === 'approved' ? 'Đang mượn' : 
                    log.status === 'returned' ? 'Đã trả' : 
                    log.status === 'rejected' ? 'Từ chối' : 'Chờ duyệt'
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "LichSuMuonTra");
    XLSX.writeFile(workbook, `Lich_su_muon_tra_${new Date().getTime()}.xlsx`);
  };

  const totalPages = Math.max(1, Math.ceil(filteredLogs.length / ITEMS_PER_PAGE));
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentLogs = filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'yesterday':
            start.setDate(today.getDate() - 1);
            end.setDate(today.getDate() - 1);
            break;
        case 'thisWeek':
            const day = today.getDay();
            const diff = today.getDate() - day + (day === 0 ? -6 : 1);
            start = new Date(today.setDate(diff));
            end = new Date();
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case '90days':
            start.setDate(today.getDate() - 90);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'today':
        default:
            break; 
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setHandlerFilter('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
    setCurrentPage(1);
  };

  const activeFiltersCount = [
    searchText.trim(), 
    handlerFilter.trim(), 
    startDate, 
    endDate, 
    statusFilter !== 'all'
  ].filter(Boolean).length;

  return (
    <div className="space-y-4 md:space-y-6 animate-fade-in pb-10">
       {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

       <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-3 md:p-4 bg-indigo-600 rounded-[1.2rem] shadow-xl shadow-indigo-100 text-white">
                    <History className="w-6 h-6 md:w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none italic uppercase">Lịch sử hoạt động</h2>
                    <p className="text-[8px] md:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        Hồ sơ tra cứu mượn trả thiết bị
                    </p>
                </div>
            </div>
            <div className="flex items-center gap-2">
                <button 
                  onClick={handleExportExcel}
                  className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-emerald-50 text-emerald-600 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all border border-emerald-100 hover:bg-emerald-600 hover:text-white shadow-sm"
                >
                  <FileSpreadsheet className="w-4 h-4"/> Xuất Excel
                </button>
                <button 
                  onClick={() => fetchHistory(true)} 
                  className="p-2.5 bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-xl transition-all border border-gray-100"
                >
                  {isRefreshing ? <Loader2 className="w-4 h-4 animate-spin"/> : <RefreshCw className="w-4 h-4"/>}
                </button>
            </div>
       </div>

       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4">
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2 bg-purple-100 text-purple-600 rounded-lg"><LayoutPanelLeft className="w-4 h-4"/></div>
              <span className="text-[7px] md:text-[9px] font-black text-purple-400 uppercase tracking-widest">Tổng lượt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.total}</p>
          </Card>
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><Clock className="w-4 h-4"/></div>
              <span className="text-[7px] md:text-[9px] font-black text-amber-400 uppercase tracking-widest">Chờ duyệt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.pending}</p>
          </Card>
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg"><Box className="w-4 h-4"/></div>
              <span className="text-[7px] md:text-[9px] font-black text-indigo-400 uppercase tracking-widest">Đang mượn</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.borrowing}</p>
          </Card>
          <Card className="p-4 md:p-6 border-none bg-white shadow-sm rounded-[1.2rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
