                  Hiển thị <span className="text-gray-900">{startIndex + 1}-{Math.min(filteredLogs.length, startIndex + ITEMS_PER_PAGE)}</span> trên {filteredLogs.length}
                </div>

                <div className="flex items-center gap-2">
