      returned: { color: 'bg-slate-50 text-slate-500 border-slate-200', icon: <History className="w-3 h-3" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-rose-50 text-rose-600 border-rose-200', icon: <Ban className="w-3 h-3" />, label: 'TỪ CHỐI' }
    };
