            </p>
          </div>
        </div>

        <div className="flex bg-gray-50 p-1.5 rounded-[1.8rem] border border-gray-200 shadow-inner relative z-10">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-6 md:px-10 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}>TẤT CẢ ĐƠN</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-6 md:px-10 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}>CỦA TÔI</button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 group">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5 group-focus-within:text-red-700 transition-colors" />
          <input 
