                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">Tài sản</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">Trạng thái</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] text-right">Thao tác xử lý</th>
              </tr>
