interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeToNumberArray(timeStr);
  return h + m / 60;
};

const timeToNumberArray = (timeStr: string) => {
    return timeStr.split(':').map(Number);
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).setHours(0,0,0,0);

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
        setIsModalOpen(false);
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-36 bg-gray-50/10 border-b border-r border-gray-100/30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const cellDate = new Date(dStr).setHours(0,0,0,0);
      const isT = todayStr === dStr;
      const isF = cellDate > todayTime;
      const isP = cellDate < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div 
          key={d} 
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-16 md:h-36 relative transition-all cursor-pointer group flex flex-col p-1 md:p-2 border-b border-r 
            ${isT ? 'bg-red-50/80 z-20 border-red-500 ring-1 md:ring-2 ring-inset ring-red-600 shadow-md md:shadow-2xl' : 'bg-white hover:bg-gray-50 border-gray-100'}
            ${isF && !isT ? 'border-1 md:border-2 border-emerald-100/50 bg-emerald-50/5' : ''}
          `}
        >
          {/* Day Header */}
          <div className="flex items-center justify-between z-10">
            <div className="relative">
              <span className={`text-[11px] md:text-lg font-black tabular-nums transition-all ${isT ? 'text-red-700 scale-110 block' : !config ? 'text-rose-400' : isP ? 'text-gray-200' : 'text-gray-500'}`}>
                {d}
              </span>
              {isT && <Sparkles className="absolute -top-1 -right-1 w-2 md:w-5 h-2 md:h-5 text-amber-500 animate-pulse" />}
            </div>
            {!config && <span className="text-[5px] md:text-[8px] font-black px-1 py-0.5 rounded-full bg-rose-50 text-rose-500 uppercase border border-rose-100 scale-90 md:scale-100">Nghỉ</span>}
          </div>

          {/* Optimized Avatar Space for Mobile */}
          <div className="flex-1 flex flex-col mt-0.5 md:mt-2 space-y-0.5 md:space-y-3 overflow-hidden">
            {myReq && (
              <div className="flex items-start">
                <div className="w-4 h-4 md:w-9 md:h-9 rounded-md md:rounded-xl bg-gradient-to-br from-red-600 to-red-800 text-white flex items-center justify-center font-black text-[7px] md:text-sm shadow-sm border-white border-[1px] md:border-[2px] ring-red-50/30">
                  {user.name.charAt(0)}
                </div>
              </div>
            )}

            {otherReqs.length > 0 && (
              <div className="mt-auto flex flex-col gap-0.5 md:gap-1">
                <div className="flex -space-x-1 md:-space-x-2.5">
                    {otherReqs.slice(0, 3).map((r, i) => (
                      <div 
                        key={i} 
                        className="w-3.5 h-3.5 md:w-7 md:h-7 rounded-sm md:rounded-lg bg-white border-[1px] md:border-2 border-gray-50 text-gray-500 flex items-center justify-center font-black text-[5px] md:text-[10px] uppercase shadow-sm"
                        title={r.users?.name}
                      >
                        {r.users?.name?.charAt(0)}
                      </div>
                    ))}
                    {otherReqs.length > 3 && (
                      <div className="w-3.5 h-3.5 md:w-7 md:h-7 rounded-sm md:rounded-lg bg-gray-900 text-white border-[1px] md:border-2 border-white flex items-center justify-center text-[4px] md:text-[9px] font-black shadow-sm">
                        +{otherReqs.length - 3}
                      </div>
                    )}
                  </div>
              </div>
            )}
          </div>
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white rounded-b-[1.5rem] md:rounded-b-[2.5rem] overflow-hidden border-l border-t border-gray-100">{days}</div>;
  };

  return (
    <div className="space-y-3 md:space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-2 pb-24">
        {/* Header - Fixed Height for Mobile */}
        <div className="flex flex-col sm:flex-row justify-between items-center gap-3 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-xl border border-white/50">
            <div className="flex items-center gap-3 w-full sm:w-auto">
                <div className="p-2 md:p-3 bg-red-700 rounded-xl md:rounded-2xl text-white shadow-lg"><Clock className="w-5 h-5 md:w-7 md:h-7" /></div>
                <div>
                    <h2 className="text-sm md:text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none italic">Lịch tăng ca</h2>
                    <p className="text-[7px] md:text-[9px] font-black text-red-700 uppercase tracking-[0.2em] mt-0.5 opacity-50 flex items-center gap-1.5">
                      <Snowflake className="w-2 h-2 md:w-3 h-3" /> Xmas Staff ❄
                    </p>
                </div>
            </div>
            <div className="w-full sm:w-auto">
                <div className="flex bg-gray-100/50 p-1 rounded-xl border border-gray-200/50">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 sm:px-6 md:px-8 py-1.5 md:py-2.5 rounded-lg text-[8px] md:text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-red-700 text-white shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Của tôi' : 'BXH'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col">
            {activeTab === 'calendar' && (
                <div className="flex-1 flex flex-col shadow-xl rounded-[1.5rem] md:rounded-[2.5rem] bg-white overflow-hidden border border-gray-100/50 min-h-[450px]">
                    <div className="flex items-center justify-between p-3 md:p-6 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-1.5 md:p-3 hover:bg-red-50 rounded-lg text-red-700 active:scale-90"><ChevronLeft className="w-5 h-5 md:w-6 md:h-6"/></button>
                        <div className="text-center">
                            <h3 className="text-sm md:text-2xl font-black uppercase tracking-[0.2em] text-gray-900 italic">Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        </div>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-1.5 md:p-3 hover:bg-red-50 rounded-lg text-red-700 active:scale-90"><ChevronRight className="w-5 h-5 md:w-6 md:h-6"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/30 text-[7px] md:text-[10px] font-black uppercase text-gray-400 text-center py-2 md:py-4 border-b border-gray-100 tracking-[0.1em] md:tracking-[0.2em]">
                        {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <div key={d} className={d === 'Sun' ? 'text-red-300' : ''}>{d}</div>)}
                    </div>
                    {renderCalendar()}
                </div>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
                        <Card className="bg-gradient-to-br from-red-700 to-red-950 text-white border-none p-4 md:p-6 rounded-[1.2rem] md:rounded-[2rem] shadow-xl">
                            <h3 className="text-[7px] md:text-[10px] font-black uppercase opacity-60 mb-1 tracking-widest">Tích lũy giờ</h3>
                            <div className="flex items-end gap-1"><span className="text-2xl md:text-5xl font-black tabular-nums tracking-tighter">{myStats.total.toFixed(1)}</span><span className="text-[8px] font-bold opacity-40 pb-1.5 uppercase">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-6 rounded-[1.2rem] md:rounded-[2rem] border-2 border-emerald-50 shadow-sm bg-white">
                            <p className="text-[7px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest mb-0.5 flex items-center gap-1.5">
                                <Check className="w-3 h-3 text-emerald-500" /> Ngày công
                            </p>
                            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                    </div>
                    <Card className="p-4 md:p-10 rounded-[1.5rem] md:rounded-[2.5rem] shadow-lg border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[8px] md:text-[11px] mb-6 md:mb-10 flex items-center gap-2.5 tracking-[0.1em] md:tracking-[0.2em]"><Activity className="w-4 h-4 md:w-5 md:h-5 text-red-600" /> Hoạt động cá nhân</h3>
                        <div className="h-40 md:h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '9px', borderRadius: '10px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(185, 28, 28, 0.05)'}}/><Bar dataKey="hours" fill="#b91c1c" radius={[3, 3, 0, 0]} barSize={8} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <Card className="rounded-[1.5rem] md:rounded-[2.5rem] p-0 flex flex-col bg-white shadow-xl overflow-hidden border-none">
                         <div className="p-4 md:p-8 bg-gradient-to-r from-red-800 to-black text-white flex justify-between items-center">
                            <div>
                                <h4 className="text-[9px] md:text-[12px] font-black uppercase flex items-center gap-2 tracking-widest"><Award className="w-5 h-5 text-amber-400" /> Bảng vàng cống hiến</h4>
                                <p className="text-[7px] md:text-[9px] font-bold opacity-40 uppercase mt-0.5">Dữ liệu tháng {currentDate.getMonth()+1}</p>
                            </div>
                            <Trophy className="w-7 h-7 md:w-10 md:h-10 opacity-20" />
                         </div>
                         <div className="p-2 md:p-8 space-y-1.5 md:space-y-3 max-h-[400px] md:max-h-[500px] overflow-y-auto no-scrollbar">
                            {topRankings.map((e, i) => (
                                <div key={i} className={`p-3 md:p-4 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/20 border-amber-100 shadow-sm' : 'bg-white border-gray-50'}`}>
                                    <div className="w-7 h-7 md:w-12 md:h-12 flex items-center justify-center font-black text-[10px] md:text-lg uppercase shrink-0">
                                      {i === 0 ? <Trophy className="w-5 h-5 md:w-8 md:h-8 text-amber-500" /> : <div className={`w-7 h-7 md:w-10 md:h-10 rounded-lg bg-gray-100 text-gray-400 flex items-center justify-center text-[9px] md:text-sm`}>{e.name.charAt(0)}</div>}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h5 className="font-black text-gray-900 text-[10px] md:text-lg truncate uppercase tracking-tight leading-none">{e.name}</h5>
                                        <p className="text-[6px] md:text-[10px] text-gray-400 font-bold tracking-widest mt-0.5 md:mt-1.5 uppercase">{e.count} Ngày</p>
                                    </div>
                                    <div className="text-right">
                                        <div className="flex items-end gap-0.5"><span className="text-sm md:text-3xl font-black text-red-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[6px] md:text-[10px] font-black text-gray-300 uppercase pb-0.5">H</span></div>
                                    </div>
                                </div>
                            ))}
                         </div>
                    </Card>
                </div>
            )}
        </div>

        {/* Modal Registration - Full Width Bottom on Mobile */}
        {isModalOpen && (
            <div 
              className="fixed inset-0 bg-red-950/80 z-[100] flex items-end sm:items-center justify-center backdrop-blur-md animate-fade-in px-0 sm:px-4"
              onClick={() => setIsModalOpen(false)} 
            >
                <div 
                  className="bg-white rounded-t-[2rem] sm:rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-slide-up overflow-hidden max-h-[92vh] flex flex-col border border-white/20"
                  onClick={(e) => e.stopPropagation()} 
                >
                    <div className="bg-red-700 p-4 md:p-6 flex justify-between items-center text-white shrink-0 relative overflow-hidden shadow-lg">
                        <Snowflake className="absolute -top-4 -right-4 w-16 h-16 opacity-10 animate-spin-slow" />
                        <div className="flex flex-col relative z-10">
                            <div className="flex items-center gap-2.5">
                                <div className="p-1.5 bg-white/20 rounded-lg"><CalendarDays className="w-4.5 h-4.5 text-white" /></div>
                                <h3 className="text-base font-black uppercase leading-none tracking-tighter italic">{selectedDateStr.split('-').reverse().join('/')}</h3>
                            </div>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-lg transition-all active:scale-90"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 md:p-10 space-y-5 md:space-y-6 overflow-y-auto no-scrollbar bg-gray-50/30 flex-1">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-red-50 shadow-sm space-y-3">
                                <div className="flex items-center justify-between px-1">
                                    <h4 className="text-[8px] font-black text-red-800 uppercase tracking-widest flex items-center gap-1.5 italic">
                                        <AlertCircle className="w-3 h-3" /> Chế độ Admin
                                    </h4>
                                    <div className={`px-2 py-0.5 rounded-full text-[7px] font-black uppercase ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600' }`}>
                                        {(dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'Ngày nghỉ' : 'Ngày làm'}
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <button 
                                        onClick={() => updateDayWorkingStatus(false)} 
                                        className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 transition-all ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-red-700 text-white border-red-500' : 'bg-white text-gray-300 border-gray-100 hover:border-red-200' }`}
                                    >
                                        <Home className="w-3.5 h-3.5" />
                                        <span className="text-[8px] font-black uppercase tracking-widest">Nghỉ</span>
                                    </button>
                                    <button 
                                        onClick={() => updateDayWorkingStatus(true)} 
                                        className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 transition-all ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-white text-gray-300 border-gray-100 hover:border-emerald-200' }`}
                                    >
                                        <Briefcase className="w-3.5 h-3.5" />
                                        <span className="text-[8px] font-black uppercase tracking-widest">Làm</span>
                                    </button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            {isViewOnly ? (
                                <div className="bg-white border-2 border-red-50 p-6 md:p-8 rounded-[1.5rem] md:rounded-[2rem] text-center space-y-4 shadow-lg">
                                    <div className="w-12 h-12 bg-red-100 rounded-xl flex items-center justify-center mx-auto shadow-sm">
                                        <Eye className="w-6 h-6 text-red-500" />
                                    </div>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-tight leading-relaxed italic">Xem lịch trình đồng nghiệp.</p>
                                    <div className="flex gap-2">
                                      <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 text-[8px] font-black uppercase rounded-xl tracking-widest">ĐÓNG</button>
                                      <button type="button" onClick={() => setTargetUserId(user.id)} className="flex-[2] py-3 bg-red-700 text-white text-[8px] font-black uppercase rounded-xl shadow-md active:scale-95 tracking-widest">ĐĂNG KÝ CHO BẠN</button>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Nhân sự:</label>
                                            <div className="relative">
                                                <select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-[10px] font-black outline-none shadow-sm focus:border-red-600 appearance-none">
                                                    {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}
                                                </select>
                                                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none" />
                                            </div>
                                        </div>
                                    )}

                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Giờ bắt đầu:</label>
                                            <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Giờ kết thúc:</label>
                                            <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                    </div>

                                    <div className="bg-red-50/50 p-3 rounded-xl border border-red-100 flex items-center justify-between shadow-sm">
                                        <span className="text-[8px] font-black text-red-800 uppercase tracking-widest opacity-60">Ước tính thời gian:</span>
                                        <span className="text-base font-black text-red-800 tabular-nums">{calculatedHours} <span className="text-[8px]">Giờ</span></span>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Nội dung công việc</label>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-xl text-[10px] h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-red-600 transition-all" placeholder="Ghi chú tóm tắt..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-1.5 py-2.5 text-[8px] font-black text-red-700 bg-white rounded-xl border-2 border-red-50 hover:bg-red-700 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">
                                            {isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} AI Tối Ưu Nội Dung
                                        </button>
                                    </div>

                                    <div className="flex gap-2 pt-2">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all">
                                                <Trash2 className="w-5 h-5" />
                                            </button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-red-700 text-white font-black rounded-xl shadow-lg text-[9px] uppercase tracking-[0.15em] transition-all active:scale-95 disabled:opacity-50 border-2 border-red-500">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật đăng ký' : 'Xác nhận đăng ký'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* Delete Confirmation Modal - Extra Safety */}
        {isConfirmCancelOpen && (
            <div 
              className="fixed inset-0 bg-red-950/95 z-[120] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in"
              onClick={() => setIsConfirmCancelOpen(false)}
            >
                <div 
                  className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center"
                  onClick={(e) => e.stopPropagation()}
                >
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-5 rounded-xl"><Trash2 className="w-8 h-8"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-1 uppercase tracking-tighter italic">Hủy đăng ký?</h3>
                    <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest opacity-60 mb-8">Dữ liệu sẽ bị xóa khỏi lịch công tác.</p>
                    <div className="flex flex-col gap-2.5">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[9px] uppercase tracking-widest shadow-md">XÁC NHẬN XÓA</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border-2 border-gray-100 text-[9px] uppercase tracking-widest">HỦY BỎ</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Home, Briefcase, CalendarDays, Eye, Trophy, Award, 
  Check, Snowflake, Star, Sparkles, AlertCircle, ChevronDown
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeToNumberArray(timeStr);
  return h + m / 60;
};

const timeToNumberArray = (timeStr: string) => {
    return timeStr.split(':').map(Number);
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).setHours(0,0,0,0);

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
        setIsModalOpen(false);
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-36 bg-gray-50/10 border-b border-r border-gray-100/30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const cellDate = new Date(dStr).setHours(0,0,0,0);
      const isT = todayStr === dStr;
      const isF = cellDate > todayTime;
      const isP = cellDate < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div 
          key={d} 
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-16 md:h-36 relative transition-all cursor-pointer group flex flex-col p-1 md:p-2 border-b border-r 
            ${isT ? 'bg-red-50/80 z-20 border-red-500 ring-1 md:ring-2 ring-inset ring-red-600 shadow-md md:shadow-2xl' : 'bg-white hover:bg-gray-50 border-gray-100'}
            ${isF && !isT ? 'border-1 md:border-2 border-emerald-100/50 bg-emerald-50/5' : ''}
          `}
        >
          {/* Day Header */}
          <div className="flex items-center justify-between z-10">
            <div className="relative">
              <span className={`text-[11px] md:text-lg font-black tabular-nums transition-all ${isT ? 'text-red-700 scale-110 block' : !config ? 'text-rose-400' : isP ? 'text-gray-200' : 'text-gray-500'}`}>
                {d}
              </span>
              {isT && <Sparkles className="absolute -top-1 -right-1 w-2 md:w-5 h-2 md:h-5 text-amber-500 animate-pulse" />}
            </div>
            {!config && <span className="text-[5px] md:text-[8px] font-black px-1 py-0.5 rounded-full bg-rose-50 text-rose-500 uppercase border border-rose-100 scale-90 md:scale-100">Nghỉ</span>}
          </div>

          {/* Optimized Avatar Space for Mobile */}
          <div className="flex-1 flex flex-col mt-0.5 md:mt-2 space-y-0.5 md:space-y-3 overflow-hidden">
            {myReq && (
              <div className="flex items-start">
                <div className="w-4 h-4 md:w-9 md:h-9 rounded-md md:rounded-xl bg-gradient-to-br from-red-600 to-red-800 text-white flex items-center justify-center font-black text-[7px] md:text-sm shadow-sm border-white border-[1px] md:border-[2px] ring-red-50/30">
                  {user.name.charAt(0)}
                </div>
              </div>
            )}

            {otherReqs.length > 0 && (
              <div className="mt-auto flex flex-col gap-0.5 md:gap-1">
                <div className="flex -space-x-1 md:-space-x-2.5">
                    {otherReqs.slice(0, 3).map((r, i) => (
                      <div 
                        key={i} 
                        className="w-3.5 h-3.5 md:w-7 md:h-7 rounded-sm md:rounded-lg bg-white border-[1px] md:border-2 border-gray-50 text-gray-500 flex items-center justify-center font-black text-[5px] md:text-[10px] uppercase shadow-sm"
                        title={r.users?.name}
                      >
                        {r.users?.name?.charAt(0)}
                      </div>
                    ))}
                    {otherReqs.length > 3 && (
                      <div className="w-3.5 h-3.5 md:w-7 md:h-7 rounded-sm md:rounded-lg bg-gray-900 text-white border-[1px] md:border-2 border-white flex items-center justify-center text-[4px] md:text-[9px] font-black shadow-sm">
                        +{otherReqs.length - 3}
                      </div>
                    )}
                  </div>
              </div>
            )}
          </div>
          {/* Total people count */}
          {dayReqs.length > 0 && (
            <div className="absolute bottom-1 right-1 md:bottom-2 md:right-2 z-30">
              <span className="inline-flex items-center justify-center h-4 md:h-5 px-1.5 md:px-2 bg-gray-900 text-white text-[7px] md:text-[9px] font-black rounded-full shadow-lg border border-white/50 animate-fade-in uppercase tracking-tight">
                {dayReqs.length} <UserIcon className="w-2.5 h-2.5 ml-1 opacity-60" />
              </span>
            </div>
          )}
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white rounded-b-[1.5rem] md:rounded-b-[2.5rem] overflow-hidden border-l border-t border-gray-100">{days}</div>;
  };

  return (
    <div className="space-y-3 md:space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-2 pb-24">
        {/* Header - Fixed Height for Mobile */}
        <div className="flex flex-col sm:flex-row justify-between items-center gap-3 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-xl border border-white/50">
            <div className="flex items-center gap-3 w-full sm:w-auto">
                <div className="p-2 md:p-3 bg-red-700 rounded-xl md:rounded-2xl text-white shadow-lg"><Clock className="w-5 h-5 md:w-7 md:h-7" /></div>
                <div>
                    <h2 className="text-sm md:text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none italic">Lịch tăng ca</h2>
                    <p className="text-[7px] md:text-[9px] font-black text-red-700 uppercase tracking-[0.2em] mt-0.5 opacity-50 flex items-center gap-1.5">
                      <Snowflake className="w-2 h-2 md:w-3 h-3" /> Xmas Staff ❄
                    </p>
                </div>
            </div>
            <div className="w-full sm:w-auto">
                <div className="flex bg-gray-100/50 p-1 rounded-xl border border-gray-200/50">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 sm:px-6 md:px-8 py-1.5 md:py-2.5 rounded-lg text-[8px] md:text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-red-700 text-white shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Của tôi' : 'BXH'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col">
            {activeTab === 'calendar' && (
                <div className="flex-1 flex flex-col shadow-xl rounded-[1.5rem] md:rounded-[2.5rem] bg-white overflow-hidden border border-gray-100/50 min-h-[450px]">
                    <div className="flex items-center justify-between p-3 md:p-6 bg-white border-b border-gray-50">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-1.5 md:p-3 hover:bg-red-50 rounded-lg text-red-700 active:scale-90"><ChevronLeft className="w-5 h-5 md:w-6 md:h-6"/></button>
                        <div className="text-center">
                            <h3 className="text-sm md:text-2xl font-black uppercase tracking-[0.2em] text-gray-900 italic">Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        </div>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-1.5 md:p-3 hover:bg-red-50 rounded-lg text-red-700 active:scale-90"><ChevronRight className="w-5 h-5 md:w-6 md:h-6"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/30 text-[7px] md:text-[10px] font-black uppercase text-gray-400 text-center py-2 md:py-4 border-b border-gray-100 tracking-[0.1em] md:tracking-[0.2em]">
                        {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <div key={d} className={d === 'Sun' ? 'text-red-300' : ''}>{d}</div>)}
                    </div>
                    {renderCalendar()}
                </div>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
                        <Card className="bg-gradient-to-br from-red-700 to-red-950 text-white border-none p-4 md:p-6 rounded-[1.2rem] md:rounded-[2rem] shadow-xl">
                            <h3 className="text-[7px] md:text-[10px] font-black uppercase opacity-60 mb-1 tracking-widest">Tích lũy giờ</h3>
                            <div className="flex items-end gap-1"><span className="text-2xl md:text-5xl font-black tabular-nums tracking-tighter">{myStats.total.toFixed(1)}</span><span className="text-[8px] font-bold opacity-40 pb-1.5 uppercase">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-6 rounded-[1.2rem] md:rounded-[2rem] border-2 border-emerald-50 shadow-sm bg-white">
                            <p className="text-[7px] md:text-[10px] font-black text-gray-400 uppercase tracking-widest mb-0.5 flex items-center gap-1.5">
                                <Check className="w-3 h-3 text-emerald-500" /> Ngày công
                            </p>
                            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{myStats.count}</p>
                        </Card>
                    </div>
                    <Card className="p-4 md:p-10 rounded-[1.5rem] md:rounded-[2.5rem] shadow-lg border-none bg-white">
                        <h3 className="font-black text-gray-900 uppercase text-[8px] md:text-[11px] mb-6 md:mb-10 flex items-center gap-2.5 tracking-[0.1em] md:tracking-[0.2em]"><Activity className="w-4 h-4 md:w-5 md:h-5 text-red-600" /> Hoạt động cá nhân</h3>
                        <div className="h-40 md:h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{left: -35}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="day" tick={{fontSize: 8, fontWeight: 'bold'}} axisLine={false} tickLine={false}/><YAxis tick={{fontSize: 8}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{fontSize: '9px', borderRadius: '10px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} cursor={{fill: 'rgba(185, 28, 28, 0.05)'}}/><Bar dataKey="hours" fill="#b91c1c" radius={[3, 3, 0, 0]} barSize={8} /></BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <Card className="rounded-[1.5rem] md:rounded-[2.5rem] p-0 flex flex-col bg-white shadow-xl overflow-hidden border-none">
                         <div className="p-4 md:p-8 bg-gradient-to-r from-red-800 to-black text-white flex justify-between items-center">
                            <div>
                                <h4 className="text-[9px] md:text-[12px] font-black uppercase flex items-center gap-2 tracking-widest"><Award className="w-5 h-5 text-amber-400" /> Bảng vàng cống hiến</h4>
                                <p className="text-[7px] md:text-[9px] font-bold opacity-40 uppercase mt-0.5">Dữ liệu tháng {currentDate.getMonth()+1}</p>
                            </div>
                            <Trophy className="w-7 h-7 md:w-10 md:h-10 opacity-20" />
                         </div>
                         <div className="p-2 md:p-8 space-y-1.5 md:space-y-3 max-h-[400px] md:max-h-[500px] overflow-y-auto no-scrollbar">
                            {topRankings.map((e, i) => (
                                <div key={i} className={`p-3 md:p-4 rounded-xl border flex items-center gap-3 transition-all ${i === 0 ? 'bg-amber-50/20 border-amber-100 shadow-sm' : 'bg-white border-gray-50'}`}>
                                    <div className="w-7 h-7 md:w-12 md:h-12 flex items-center justify-center font-black text-[10px] md:text-lg uppercase shrink-0">
                                      {i === 0 ? <Trophy className="w-5 h-5 md:w-8 md:h-8 text-amber-500" /> : <div className={`w-7 h-7 md:w-10 md:h-10 rounded-lg bg-gray-100 text-gray-400 flex items-center justify-center text-[9px] md:text-sm`}>{e.name.charAt(0)}</div>}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h5 className="font-black text-gray-900 text-[10px] md:text-lg truncate uppercase tracking-tight leading-none">{e.name}</h5>
                                        <p className="text-[6px] md:text-[10px] text-gray-400 font-bold tracking-widest mt-0.5 md:mt-1.5 uppercase">{e.count} Ngày</p>
                                    </div>
                                    <div className="text-right">
                                        <div className="flex items-end gap-0.5"><span className="text-sm md:text-3xl font-black text-red-700 tabular-nums">{e.hours.toFixed(1)}</span><span className="text-[6px] md:text-[10px] font-black text-gray-300 uppercase pb-0.5">H</span></div>
                                    </div>
                                </div>
                            ))}
                         </div>
                    </Card>
                </div>
            )}
        </div>

        {/* Modal Registration - Full Width Bottom on Mobile */}
        {isModalOpen && (
            <div 
              className="fixed inset-0 bg-red-950/80 z-[100] flex items-end sm:items-center justify-center backdrop-blur-md animate-fade-in px-0 sm:px-4"
              onClick={() => setIsModalOpen(false)} 
            >
                <div 
                  className="bg-white rounded-t-[2rem] sm:rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-slide-up overflow-hidden max-h-[92vh] flex flex-col border border-white/20"
                  onClick={(e) => e.stopPropagation()} 
                >
                    <div className="bg-red-700 p-4 md:p-6 flex justify-between items-center text-white shrink-0 relative overflow-hidden shadow-lg">
                        <Snowflake className="absolute -top-4 -right-4 w-16 h-16 opacity-10 animate-spin-slow" />
                        <div className="flex flex-col relative z-10">
                            <div className="flex items-center gap-2.5">
                                <div className="p-1.5 bg-white/20 rounded-lg"><CalendarDays className="w-4.5 h-4.5 text-white" /></div>
                                <h3 className="text-base font-black uppercase leading-none tracking-tighter italic">{selectedDateStr.split('-').reverse().join('/')}</h3>
                            </div>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-lg transition-all active:scale-90"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 md:p-10 space-y-5 md:space-y-6 overflow-y-auto no-scrollbar bg-gray-50/30 flex-1">
                        {isAdmin && (
                            <div className="bg-white p-4 rounded-2xl border border-red-50 shadow-sm space-y-3">
                                <div className="flex items-center justify-between px-1">
                                    <h4 className="text-[8px] font-black text-red-800 uppercase tracking-widest flex items-center gap-1.5 italic">
                                        <AlertCircle className="w-3 h-3" /> Chế độ Admin
                                    </h4>
                                    <div className={`px-2 py-0.5 rounded-full text-[7px] font-black uppercase ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-red-50 text-red-600' : 'bg-emerald-50 text-emerald-600' }`}>
                                        {(dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'Ngày nghỉ' : 'Ngày làm'}
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <button 
                                        onClick={() => updateDayWorkingStatus(false)} 
                                        className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 transition-all ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0))) ? 'bg-red-700 text-white border-red-500' : 'bg-white text-gray-300 border-gray-100 hover:border-red-200' }`}
                                    >
                                        <Home className="w-3.5 h-3.5" />
                                        <span className="text-[8px] font-black uppercase tracking-widest">Nghỉ</span>
                                    </button>
                                    <button 
                                        onClick={() => updateDayWorkingStatus(true)} 
                                        className={`flex items-center justify-center gap-2 py-2.5 rounded-xl border-2 transition-all ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0)) ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-white text-gray-300 border-gray-100 hover:border-emerald-200' }`}
                                    >
                                        <Briefcase className="w-3.5 h-3.5" />
                                        <span className="text-[8px] font-black uppercase tracking-widest">Làm</span>
                                    </button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            {isViewOnly ? (
                                <div className="bg-white border-2 border-red-50 p-6 md:p-8 rounded-[1.5rem] md:rounded-[2rem] text-center space-y-4 shadow-lg">
                                    <div className="w-12 h-12 bg-red-100 rounded-xl flex items-center justify-center mx-auto shadow-sm">
                                        <Eye className="w-6 h-6 text-red-500" />
                                    </div>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-tight leading-relaxed italic">Xem lịch trình đồng nghiệp.</p>
                                    <div className="flex gap-2">
                                      <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 text-[8px] font-black uppercase rounded-xl tracking-widest">ĐÓNG</button>
                                      <button type="button" onClick={() => setTargetUserId(user.id)} className="flex-[2] py-3 bg-red-700 text-white text-[8px] font-black uppercase rounded-xl shadow-md active:scale-95 tracking-widest">ĐĂNG KÝ CHO BẠN</button>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Nhân sự:</label>
                                            <div className="relative">
                                                <select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-[10px] font-black outline-none shadow-sm focus:border-red-600 appearance-none">
                                                    {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}
                                                </select>
                                                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none" />
                                            </div>
                                        </div>
                                    )}

                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Giờ bắt đầu:</label>
                                            <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Giờ kết thúc:</label>
                                            <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                    </div>

                                    <div className="bg-red-50/50 p-3 rounded-xl border border-red-100 flex items-center justify-between shadow-sm">
                                        <span className="text-[8px] font-black text-red-800 uppercase tracking-widest opacity-60">Ước tính thời gian:</span>
                                        <span className="text-base font-black text-red-800 tabular-nums">{calculatedHours} <span className="text-[8px]">Giờ</span></span>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Nội dung công việc</label>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-xl text-[10px] h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-red-600 transition-all" placeholder="Ghi chú tóm tắt..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-1.5 py-2.5 text-[8px] font-black text-red-700 bg-white rounded-xl border-2 border-red-50 hover:bg-red-700 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">
                                            {isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} AI Tối Ưu Nội Dung
                                        </button>
                                    </div>

                                    <div className="flex gap-2 pt-2">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all">
                                                <Trash2 className="w-5 h-5" />
                                            </button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-red-700 text-white font-black rounded-xl shadow-lg text-[9px] uppercase tracking-[0.15em] transition-all active:scale-95 disabled:opacity-50 border-2 border-red-500">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật đăng ký' : 'Xác nhận đăng ký'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* Delete Confirmation Modal - Extra Safety */}
        {isConfirmCancelOpen && (
            <div 
              className="fixed inset-0 bg-red-950/95 z-[120] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in"
              onClick={() => setIsConfirmCancelOpen(false)}
            >
                <div 
                  className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center"
                  onClick={(e) => e.stopPropagation()}
                >
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-5 rounded-xl"><Trash2 className="w-8 h-8"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-1 uppercase tracking-tighter italic">Hủy đăng ký?</h3>
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest opacity-60 mb-8">Dữ liệu sẽ bị xóa khỏi lịch công tác.</p>
                    <div className="flex flex-col gap-2.5">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[9px] uppercase tracking-widest shadow-md">XÁC NHẬN XÓA</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border-2 border-gray-100 text-[9px] uppercase tracking-widest">HỦY BỎ</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { rewriteOvertimeReason } from '../../services/geminiService';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Home, Briefcase, CalendarDays, Eye, Trophy, Award, 
  Check, Snowflake, Star, Sparkles, AlertCircle, ChevronDown,
  // Add UserIcon to the import list
  User as UserIcon
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeToNumberArray(timeStr);
  return h + m / 60;
};

const timeToNumberArray = (timeStr: string) => {
    return timeStr.split(':').map(Number);
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).setHours(0,0,0,0);

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
        setIsModalOpen(false);
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const handleAiRewrite = async () => {
    if (!reason) return;
    setIsRewriting(true);
    const newReason = await rewriteOvertimeReason(reason);
    setReason(newReason);
    setIsRewriting(false);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-36 bg-gray-50/10 border-b border-r border-gray-100/30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const cellDate = new Date(dStr).setHours(0,0,0,0);
      const isT = todayStr === dStr;
      const isF = cellDate > todayTime;
      const isP = cellDate < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div 
          key={d} 
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-16 md:h-36 relative transition-all cursor-pointer group flex flex-col p-1 md:p-2 border-b border-r 
            ${isT ? 'bg-red-50/80 z-20 border-red-500 ring-1 md:ring-2 ring-inset ring-red-600 shadow-md md:shadow-2xl' : 'bg-white hover:bg-gray-50 border-gray-100'}
            ${isF && !isT ? 'border-1 md:border-2 border-emerald-100/50 bg-emerald-50/5' : ''}
          `}
        >
          {/* Day Header */}
          <div className="flex items-center justify-between z-10">
            <div className="relative">
              <span className={`text-[11px] md:text-lg font-black tabular-nums transition-all ${isT ? 'text-red-700 scale-110 block' : !config ? 'text-rose-400' : isP ? 'text-gray-200' : 'text-gray-500'}`}>
                {d}
              </span>
              {isT && <Sparkles className="absolute -top-1 -right-1 w-2 md:w-5 h-2 md:h-5 text-amber-500 animate-pulse" />}
            </div>
            {!config && <span className="text-[5px] md:text-[8px] font-black px-1 py-0.5 rounded-full bg-rose-50 text-rose-500 uppercase border border-rose-100 scale-90 md:scale-100">Nghỉ</span>}
          </div>

          {/* Optimized Avatar Space for Mobile */}
          <div className="flex-1 flex flex-col mt-0.5 md:mt-2 space-y-0.5 md:space-y-3 overflow-hidden">
            {myReq && (
              <div className="flex items-start">
                <div className="w-4 h-4 md:w-9 md:h-9 rounded-md md:rounded-xl bg-gradient-to-br from-red-600 to-red-800 text-white flex items-center justify-center font-black text-[7px] md:text-sm shadow-sm border-white border-[1px] md:border-[2px] ring-red-50/30">
                  {user.name.charAt(0)}
                </div>
              </div>
            )}

            {otherReqs.length > 0 && (
              <div className="mt-auto flex flex-col gap-0.5 md:gap-1">
                <div className="flex -space-x-1 md:-space-x-2.5">
                    {otherReqs.slice(0, 3).map((r, i) => (
                      <div 
                        key={i} 
                        className="w-3.5 h-3.5 md:w-7 md:h-7 rounded-sm md:rounded-lg bg-white border-[1px] md:border-2 border-gray-50 text-gray-500 flex items-center justify-center font-black text-[5px] md:text-[10px] uppercase shadow-sm"
