                                        <Eye className="w-6 h-6 text-red-500" />
                                    </div>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-tight leading-relaxed italic">Xem lịch trình đồng nghiệp.</p>
                                    <div className="flex gap-2">
                                      <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-gray-100 text-gray-500 text-[8px] font-black uppercase rounded-xl tracking-widest">ĐÓNG</button>
                                      <button type="button" onClick={() => setTargetUserId(user.id)} className="flex-[2] py-3 bg-red-700 text-white text-[8px] font-black uppercase rounded-xl shadow-md active:scale-95 tracking-widest">ĐĂNG KÝ CHO BẠN</button>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Nhân sự:</label>
                                            <div className="relative">
                                                <select required value={targetUserId} onChange={e => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-[10px] font-black outline-none shadow-sm focus:border-red-600 appearance-none">
                                                    {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name.toUpperCase()}</option>))}
                                                </select>
                                                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none" />
                                            </div>
                                        </div>
                                    )}

                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Giờ bắt đầu:</label>
                                            <input type="time" required value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                        <div className="space-y-1">
                                            <label className="text-[8px] font-black text-gray-400 uppercase ml-1 tracking-widest">Giờ kết thúc:</label>
                                            <input type="time" required value={endTime} onChange={e => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-white border border-gray-100 rounded-xl text-xs font-bold outline-none shadow-sm focus:border-red-600" />
                                        </div>
                                    </div>

                                    <div className="bg-red-50/50 p-3 rounded-xl border border-red-100 flex items-center justify-between shadow-sm">
                                        <span className="text-[8px] font-black text-red-800 uppercase tracking-widest opacity-60">Ước tính thời gian:</span>
                                        <span className="text-base font-black text-red-800 tabular-nums">{calculatedHours} <span className="text-[8px]">Giờ</span></span>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Nội dung công việc</label>
                                        <textarea value={reason} onChange={e => setReason(e.target.value)} className="w-full p-4 bg-white border border-gray-100 rounded-xl text-[10px] h-24 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-red-600 transition-all" placeholder="Ghi chú tóm tắt..."/>
                                        <button type="button" onClick={handleAiRewrite} disabled={isRewriting || !reason} className="w-full flex items-center justify-center gap-1.5 py-2.5 text-[8px] font-black text-red-700 bg-white rounded-xl border-2 border-red-50 hover:bg-red-700 hover:text-white transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest shadow-sm">
                                            {isRewriting ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <Wand2 className="w-3.5 h-3.5"/>} AI Tối Ưu Nội Dung
                                        </button>
                                    </div>

                                    <div className="flex gap-2 pt-2">
                                        {editingRequestId && (isAdmin || targetUserId === user.id) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all">
                                                <Trash2 className="w-5 h-5" />
                                            </button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-red-700 text-white font-black rounded-xl shadow-lg text-[9px] uppercase tracking-[0.15em] transition-all active:scale-95 disabled:opacity-50 border-2 border-red-500">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật đăng ký' : 'Xác nhận đăng ký'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* Day Details Modal */}
        {isDayDetailsModalOpen && (
            <div 
              className="fixed inset-0 bg-red-950/80 z-[100] flex items-end sm:items-center justify-center backdrop-blur-md animate-fade-in px-0 sm:px-4"
              onClick={() => setIsDayDetailsModalOpen(false)} 
            >
                <div 
                  className="bg-white rounded-t-[2rem] sm:rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-slide-up overflow-hidden max-h-[92vh] flex flex-col border border-white/20"
                  onClick={(e) => e.stopPropagation()} 
                >
                    <div className="bg-red-700 p-4 md:p-6 flex justify-between items-center text-white shrink-0 relative overflow-hidden shadow-lg">
                        <Star className="absolute -top-4 -right-4 w-16 h-16 opacity-10 animate-spin-slow" />
                        <div className="flex flex-col relative z-10">
                            <div className="flex items-center gap-2.5">
                                <div className="p-1.5 bg-white/20 rounded-lg"><CalendarDays className="w-4.5 h-4.5 text-white" /></div>
                                <h3 className="text-base font-black uppercase leading-none tracking-tighter italic">
                                    {new Date(selectedDateStr).toLocaleDateString('vi-VN', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' })} - Tăng ca
                                </h3>
                            </div>
                        </div>
                        <button onClick={() => setIsDayDetailsModalOpen(false)} className="p-2 hover:bg-white/20 rounded-lg transition-all active:scale-90"><X className="w-5 h-5"/></button>
                    </div>

                    <div className="p-5 md:p-10 space-y-4 overflow-y-auto no-scrollbar bg-gray-50/30 flex-1">
                        {selectedDayRequests.length === 0 ? (
                            <div className="p-16 text-center flex flex-col items-center gap-3">
                                <div className="p-4 bg-gray-50 rounded-full">
                                    <AlertCircle className="w-8 h-8 text-gray-200" />
                                </div>
                                <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest italic">Chưa có ai đăng ký tăng ca ngày này.</p>
                            </div>
                        ) : (
                            selectedDayRequests.map((req) => (
                                <button
                                    key={req.id}
                                    onClick={() => {
                                        setIsDayDetailsModalOpen(false);
                                        setSelectedDateStr(req.date);
                                        setTargetUserId(req.user_id);
                                        setIsModalOpen(true);
                                    }}
                                    className="w-full flex items-center gap-4 p-4 bg-white rounded-2xl border border-gray-100 shadow-sm hover:border-red-200 hover:shadow-md transition-all group active:scale-[0.98]"
                                >
                                    <div className="w-12 h-12 bg-red-100 text-red-700 rounded-xl flex items-center justify-center font-black text-lg uppercase flex-shrink-0 border-2 border-white group-hover:bg-red-700 group-hover:text-white transition-colors">
                                        {req.users?.name?.charAt(0) || '?'}{' '}
                                    </div>
                                    <div className="flex-1 text-left">
                                        <p className="font-black text-gray-900 text-sm uppercase tracking-tight leading-none">{req.users?.name || 'Người dùng ẩn danh'}</p>
                                        <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest mt-1">{req.users?.employee_id || 'N/A'}</p>
                                    </div>
                                    <div className="text-right flex flex-col items-end">
                                        <p className="text-red-700 font-black text-sm tabular-nums">{req.start_time} - {req.end_time}</p>
                                        <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest mt-1">{req.total_hours} giờ</p>
                                    </div>
                                </button>
                            ))
                        )}
                    </div>
                </div>
            </div>
        )}

        {/* Delete Confirmation Modal - Extra Safety */}
        {isConfirmCancelOpen && (
            <div 
              className="fixed inset-0 bg-red-950/95 z-[120] flex items-center justify-center p-6 backdrop-blur-md animate-fade-in"
              onClick={() => setIsConfirmCancelOpen(false)}
            >
                <div 
                  className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center"
                  onClick={(e) => e.stopPropagation()}
                >
                    <div className="w-16 h-16 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-5 rounded-xl"><Trash2 className="w-8 h-8"/></div>
                    <h3 className="text-lg font-black text-gray-900 mb-1 uppercase tracking-tighter italic">Hủy đăng ký?</h3>
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest opacity-60 mb-8">Dữ liệu sẽ bị xóa khỏi lịch công tác.</p>
                    <div className="flex flex-col gap-2.5">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-xl text-[9px] uppercase tracking-widest shadow-md">XÁC NHẬN XÓA</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-xl border-2 border-gray-100 text-[9px] uppercase tracking-widest">HỦY BỎ</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon, AlertCircle, ChevronRight, ArrowUpRight, Snowflake,
  CheckCircle2, Ban, History, Clock
} from 'lucide-react';

interface RequestManagerProps { user: User; }

const ToolTableImage = ({ toolId, toolName }: { toolId: string, toolName: string }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  return (
    <div className="w-12 h-12 md:w-16 md:h-16 bg-white border border-gray-100 rounded-2xl overflow-hidden flex items-center justify-center p-1.5 shadow-sm group-hover:scale-110 transition-transform duration-500">
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-6 h-6 text-gray-200" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    // Thứ tự ưu tiên hiển thị: Pending (0) -> Approved (1) -> Returned (2) -> Rejected (3)
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      returned: 2,
      rejected: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      return matchesSearch && matchesStatus;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;

      // Sắp xếp theo mức độ ưu tiên trạng thái trước
      if (priorityA !== priorityB) return priorityA - priorityB;

      // Nếu cùng trạng thái, đưa những đơn mới nhất (theo ngày mượn) lên đầu
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchRequests();
    } catch (e: any) {
      alert(e.message);
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { 
        color: 'bg-amber-100 text-amber-700 border-amber-300 ring-4 ring-amber-500/10', 
        icon: <Clock className="w-3.5 h-3.5 animate-pulse" />, 
        label: 'ĐANG CHỜ DUYỆT' 
      },
      approved: { 
        color: 'bg-emerald-100 text-emerald-700 border-emerald-300 ring-4 ring-emerald-500/10', 
        icon: <PackageCheck className="w-3.5 h-3.5" />, 
        label: 'ĐANG CHO MƯỢN' 
      },
      returned: { 
        color: 'bg-slate-100 text-slate-600 border-slate-300 ring-4 ring-slate-500/10', 
        icon: <History className="w-3.5 h-3.5" />, 
        label: 'ĐÃ TRẢ THÀNH CÔNG' 
      },
      rejected: { 
        color: 'bg-rose-100 text-rose-700 border-rose-300 ring-4 ring-rose-500/10', 
        icon: <Ban className="w-3.5 h-3.5" />, 
        label: 'YÊU CẦU TỪ CHỐI' 
      }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2.5 px-4 py-2 rounded-full text-[10px] font-black tracking-widest border-2 shadow-sm ${c.color} uppercase transition-all group-hover:scale-105`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in pb-20">
      {/* Header Panel */}
      <div className="bg-white p-6 md:p-10 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
        <div className="absolute -top-10 -right-10 opacity-[0.03] pointer-events-none rotate-12">
            <RefreshCw className="w-48 h-48" />
        </div>

        <div className="flex items-center gap-6 relative z-10">
          <div className="p-4 bg-red-700 rounded-3xl shadow-xl shadow-red-100 text-white transform -rotate-3 transition-transform hover:rotate-0">
            <RefreshCw className="w-7 h-7" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Phê duyệt mượn trả</h2>
            <p className="text-[10px] text-red-700 font-black uppercase tracking-[0.25em] mt-2 opacity-50 flex items-center gap-2">
                <Snowflake className="w-3 h-3 text-blue-300" /> Hệ thống xét duyệt ưu tiên ❄
            </p>
          </div>
        </div>

        <div className="flex bg-gray-50 p-1.5 rounded-[1.8rem] border border-gray-200 shadow-inner relative z-10">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-8 md:px-12 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}>TẤT CẢ ĐƠN</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-8 md:px-12 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}>CỦA TÔI</button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 group">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5 group-focus-within:text-red-700 transition-colors" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm theo nhân viên, thiết bị, mã NV..." 
            className="w-full pl-14 pr-6 py-4.5 bg-white border-none rounded-[1.8rem] text-sm font-bold outline-none focus:ring-4 focus:ring-red-700/5 transition-all shadow-lg shadow-gray-200/30" 
          />
        </div>

        <div className="relative">
            <select 
              value={filterStatus} 
              onChange={e => setFilterStatus(e.target.value)} 
              className="w-full md:w-64 px-8 py-4.5 bg-white border-none rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-lg shadow-gray-200/30 hover:bg-gray-50 transition-colors appearance-none pr-14"
            >
              <option value="all">TẤT CẢ TRẠNG THÁI</option>
              <option value="pending">⏳ ĐANG CHỜ DUYỆT</option>
              <option value="approved">📦 ĐANG CHO MƯỢN</option>
              <option value="returned">✅ ĐÃ TRẢ THÀNH CÔNG</option>
              <option value="rejected">❌ ĐÃ TỪ CHỐI</option>
            </select>
            <ChevronRight className="absolute right-5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none rotate-90" />
        </div>
      </div>

      {/* Request Table Card */}
      <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[3rem] bg-white">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">Thành viên</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">Tài sản / Thiết bị</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">Trạng thái hiện tại</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] text-right">Thao tác xử lý</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={4} className="py-40 text-center"><Loader2 className="w-12 h-12 animate-spin text-red-700 mx-auto opacity-10" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={4} className="py-40 text-center">
                    <div className="flex flex-col items-center gap-4 opacity-20">
                        <AlertCircle className="w-16 h-16 text-gray-400" />
                        <p className="text-sm font-black uppercase tracking-widest italic text-gray-400">Chưa có yêu cầu nào cần phê duyệt ❄</p>
                    </div>
                </td></tr>
