                        : 'hover:bg-red-50/10 hover:border-l-red-700'
                    }`}
                  >
                    <td className="px-8 md:px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-gray-900 text-white rounded-2xl flex items-center justify-center font-black text-lg shadow-lg border-2 border-white group-hover:bg-red-700 transition-colors duration-500">
                          {req.user_name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <div className="font-black text-gray-900 text-[14px] uppercase tracking-tighter leading-none">{req.user_name}</div>
                          <div className="text-[9px] text-gray-400 font-black tracking-widest mt-2 uppercase opacity-60 italic">{req.employee_id} • {new Date(req.borrow_date).toLocaleDateString('vi-VN')}</div>
