        <div className="px-10 md:px-12 pb-10 md:pb-12 pt-8 md:pt-10 bg-gray-50/50">
          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-2">
              <label htmlFor="employeeCode" className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mã nhân viên</label>
              <div className="relative">
                <UserCircle className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input
                  id="employeeCode"
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
