            </div>

            <div className="space-y-2">
              <label htmlFor="password" className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mật khẩu</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input
                  id="password"
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full pl-11 pr-4 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold text-gray-900 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all shadow-sm"
                  placeholder="••••••••"
                  required
                  aria-label="Mật khẩu"
                />
              </div>
            </div>

            {error && (
              <div role="alert" className="p-4 bg-red-50 text-red-600 text-xs font-semibold rounded-xl border border-red-100 flex items-center gap-2 shadow-sm">
                <AlertCircle className="w-4 h-4 flex-shrink-0" />
