const COLORS = ['#ef4444', '#f97316', '#22c55e', '#3b82f6', '#8884d8', '#82ca9d']; // Adjusted colors for festive theme

interface SafeChartContainerProps {
  children: React.ReactNode;
  height?: number;
  hasData?: boolean;
}

/**
 * Component an toàn để bọc biểu đồ Recharts.
 * Giải quyết lỗi "width/height is -1" bằng cách theo dõi chính xác kích thước container cha.
 */
const SafeChartContainer: React.FC<SafeChartContainerProps> = ({ children, height = 300, hasData = true }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    if (!containerRef.current) return;

    // Sử dụng ResizeObserver để lấy kích thước chính xác của container
    const observer = new ResizeObserver((entries) => {
      if (!entries.length) return;
      const { width, height: contentHeight } = entries[0].contentRect;

      // Chỉ cập nhật khi kích thước hợp lệ
      if (width > 0) {
        setDimensions({ width, height: contentHeight || height });
      }
    });

    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [height]);

  // Hiển thị trạng thái trống nếu không có dữ liệu
  if (!hasData) {
    return (
      <div style={{ height }} className="w-full flex flex-col items-center justify-center bg-gray-50 rounded-xl md:rounded-2xl border-2 border-dashed border-gray-200 p-6">
         <div className="p-3 bg-gray-100 rounded-full mb-3">
            <BarChartIcon className="w-6 h-6 text-gray-400" />
         </div>
         <span className="text-gray-400 text-sm font-semibold italic">Chưa có dữ liệu thống kê</span>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef} 
      style={{ 
        height: `${height}px`, 
        width: '100%', 
        position: 'relative',
        minWidth: '0px' // Quan trọng: ngăn flex container bị tràn
      }} 
      className="overflow-hidden" 
    >
      {/* Chỉ render ResponsiveContainer khi component đã mount và container có kích thước > 0 */}
      {isMounted && dimensions.width > 0 ? (
        <ResponsiveContainer width="100%" height="100%">
          {children as React.ReactElement}
        </ResponsiveContainer>
      ) : (
        <div className="w-full h-full flex flex-col items-center justify-center bg-gray-50/50 rounded-xl md:rounded-2xl">
           <Loader2 className="w-6 h-6 text-red-600 animate-spin mb-3" />
           <span className="text-gray-400 text-xs font-semibold">Đang khởi tạo biểu đồ...</span>
        </div>
      )}
    </div>
  );
};

export const DashboardStats: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalToolsQuantity: 0,
    totalToolsAvailable: 0,
    borrowedTools: 0,
    pendingRequests: 0,
  });
  const [barData, setBarData] = useState<any[]>([]);
  const [pieData, setPieData] = useState<any[]>([]);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [toolsRes, requestsRes] = await Promise.all([
        supabase.from('tools').select('quantity, available, status'),
        supabase.from('requests').select('status, borrow_date')
      ]);

      const tools = toolsRes.data || [];
      const requests = requestsRes.data || [];

      // 1. Tính Tổng số lượng công cụ
      const totalToolsQuantity = tools.reduce((sum, tool) => sum + (tool.quantity || 0), 0);

      // 2. Tính Số lượng sẵn có
      const totalToolsAvailable = tools.reduce((sum, tool) => sum + (tool.status === 'active' ? (tool.available || 0) : 0), 0);

      // 3. Tính Số lượng đang mượn
      const borrowedTools = requests.filter(r => r.status === 'approved').length;

      // 4. Tính Số lượng chờ duyệt
      const pendingRequests = requests.filter(r => r.status === 'pending').length;

      setStats({
        totalToolsQuantity,
        totalToolsAvailable,
        borrowedTools,
        pendingRequests
      });

      // --- Biểu đồ Tròn: Phân bố trạng thái tài sản ---
      const pieChartData = [
        { name: 'Sẵn có', value: totalToolsAvailable },
        { name: 'Đang mượn', value: borrowedTools },
        { name: 'Khác/Bảo trì', value: Math.max(0, totalToolsQuantity - totalToolsAvailable - borrowedTools) },
      ];
      setPieData(pieChartData.filter(item => item.value > 0));

      // --- Biểu đồ Cột: Yêu cầu 7 ngày gần nhất ---
      const last7Days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        return {
            dateStr: d.toLocaleDateString('vi-VN'),
            dayName: d.toLocaleDateString('vi-VN', { weekday: 'short' }),
            fullDate: d.toISOString().split('T')[0]
        };
      });

      const chartData = last7Days.map(day => {
        const count = requests.filter(r => r.borrow_date.startsWith(day.fullDate)).length;
        return {
            name: day.dayName,
            fullDate: day.dateStr,
            requests: count
        };
      });

      setBarData(chartData);

    } catch (error) {
      console.error("Error fetching dashboard data:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
        <div className="flex h-96 items-center justify-center animate-fade-in">
            <Loader2 className="w-8 h-8 animate-spin text-red-600" />
            <p className="ml-3 text-red-700 font-bold text-sm uppercase tracking-widest">Đang tải dữ liệu...</p>
        </div>
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header Panel */}
      <div className="bg-white p-6 md:p-10 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
        <div className="absolute -top-10 -right-10 opacity-[0.03] pointer-events-none rotate-12">
            <Star className="w-48 h-48" />
        </div>

        <div className="flex items-center gap-6 relative z-10">
          <div className="p-4 bg-red-700 rounded-3xl shadow-xl shadow-red-100 text-white transform -rotate-3 transition-transform hover:rotate-0">
            <Info className="w-7 h-7" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Tổng quan hoạt động</h2>
            <p className="text-[10px] text-red-700 font-black uppercase tracking-[0.25em] mt-2 opacity-50 flex items-center gap-2">
                <Handshake className="w-3 h-3 text-blue-300" /> Thống kê và báo cáo tổng hợp
            </p>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card className="flex items-center gap-4 border-l-4 border-l-red-500 hover:shadow-md transition-shadow rounded-2xl md:rounded-[1.8rem] p-6">
          <div className="p-3 bg-red-100 rounded-full text-red-600">
            <Package className="w-6 h-6" />
          </div>
          <div>
            <p className="text-sm text-gray-500 font-semibold uppercase tracking-tight">Tổng số công cụ</p>
            <p className="text-2xl md:text-3xl font-black text-gray-800 tabular-nums">{stats.totalToolsQuantity}</p>
          </div>
        </Card>

        <Card className="flex items-center gap-4 border-l-4 border-l-orange-500 hover:shadow-md transition-shadow rounded-2xl md:rounded-[1.8rem] p-6">
