export const EmployeeList: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // Phân trang
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10; // Giảm pageSize để gọn gàng hơn

  // State cho chức năng sửa/thêm
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentId, setCurrentId] = useState<string | null>(null);

  const initialForm = { employee_id: '', name: '', role: 'user', password: '123' };
  const [formData, setFormData] = useState(initialForm);

  // State cho chức năng xóa
  const [userToDelete, setUserToDelete] = useState<Employee | null>(null);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('users').select('*').order('employee_id', { ascending: true });
      if (data) setEmployees(data as Employee[]);
      if (error) throw error;
    } catch (error) {
      console.error("Error fetching employees:", error);
    } finally {
      setLoading(false);
    }
  };

  // Logic lọc và phân trang
  const filteredEmployees = useMemo(() => {
    return employees.filter(emp => 
      emp.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      emp.employee_id.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [employees, searchTerm]);

  const totalPages = Math.max(1, Math.ceil(filteredEmployees.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentEmployees = filteredEmployees.slice(startIndex, startIndex + pageSize);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm]);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleAddNew = () => {
    setFormData(initialForm);
    setIsEditing(false);
    setIsModalOpen(true);
  };

  const handleEdit = (employee: Employee) => {
    setCurrentId(employee.id);
    setFormData({
        employee_id: employee.employee_id,
        name: employee.name,
        role: employee.role,
        password: employee.password || '',
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  const handleDelete = async () => {
    if (!userToDelete) return;

    try {
      const { error } = await supabase.from('users').delete().eq('id', userToDelete.id);
      if (error) throw error;

      setEmployees(employees.filter(emp => emp.id !== userToDelete.id));
      setUserToDelete(null);
    } catch (error: any) {
      alert('Lỗi khi xóa tài khoản: ' + error.message);
    }
  };

  const handleSave = async () => {
    if (!formData.employee_id || !formData.name) return alert("Vui lòng nhập đủ thông tin");

    try {
      const payload = {
          employee_id: formData.employee_id,
          name: formData.name,
          role: formData.role,
          password: formData.password,
      };

      if (isEditing && currentId) {
        const { error } = await supabase.from('users').update(payload).eq('id', currentId);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('users').insert([payload]);
        if (error) throw error;
      }

      await fetchEmployees();
      setIsModalOpen(false);
    } catch (error: any) {
      alert('Lỗi cập nhật: ' + error.message);
    }
  };

  return (
    <div className="space-y-6 relative animate-fade-in pb-10 max-w-7xl mx-auto">
      {/* Header Panel */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-gray-100">
        <div className="flex items-center gap-4">
          <div className="p-4 bg-blue-600 rounded-[1.8rem] shadow-xl shadow-blue-100 text-white">
            <Users className="w-8 h-8" />
          </div>
          <div>
            <h2 className="text-2xl md:text-3xl font-black text-gray-900 tracking-tight uppercase italic">Danh sách nhân sự</h2>
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">Quản lý tài khoản hệ thống</p>
          </div>
        </div>
        <button 
          onClick={handleAddNew} 
          className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4.5 rounded-2xl flex items-center gap-2 text-xs font-black uppercase tracking-widest transition-all shadow-xl shadow-blue-100 active:scale-95"
          aria-label="Thêm nhân sự mới"
        >
          <Plus className="w-4 h-4" />
          Thêm nhân sự
        </button>
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[3rem] bg-white">
        {/* Toolbar */}
        <div className="p-6 md:p-8 border-b border-gray-100 bg-gray-50/50">
          <div className="relative group max-w-lg">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5 group-focus-within:text-blue-600 transition-colors" />
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Tìm theo tên hoặc mã NV..." 
              className="w-full pl-14 pr-6 py-4 bg-white border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 text-gray-900 transition-all shadow-sm"
              aria-label="Tìm kiếm nhân sự"
            />
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/80 border-b border-gray-100">
                <th className="px-8 md:px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Mã NV</th>
                <th className="px-8 md:px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Họ và tên</th>
                <th className="px-8 md:px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Vai trò</th>
                <th className="px-8 md:px-10 py-6 text-gray-400 font-black uppercase text-[10px] tracking-[0.2em]">Ngày tạo</th>
