                      <span className={`inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border-2 shadow-sm ${
                        emp.role === 'admin' 
                          ? 'bg-purple-50 text-purple-700 border-purple-200' 
                          : 'bg-blue-50 text-blue-700 border-blue-200'
                      }`}>
                        {emp.role === 'admin' ? <Shield className="w-3.5 h-3.5"/> : <UserIcon className="w-3.5 h-3.5"/>}
                        {emp.role}
                      </span>
                    </td>
                    <td className="px-8 md:px-10 py-6 text-[11px] font-black text-gray-400 uppercase tabular-nums">
                        {emp.created_at ? new Date(emp.created_at).toLocaleDateString('vi-VN') : '—'}
                    </td>
                    <td className="px-8 md:px-10 py-6 text-right">
                      <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => handleEdit(emp)}
                          className="bg-white p-3.5 border-2 border-blue-100 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all active:scale-90"
                          title="Sửa thông tin"
                          aria-label={`Edit ${emp.name}`}
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => setUserToDelete(emp)}
                          className="bg-white p-3.5 border-2 border-rose-100 text-rose-600 rounded-xl hover:bg-rose-600 hover:text-white hover:border-rose-600 transition-all active:scale-90"
                          title="Xóa tài khoản"
                          aria-label={`Delete ${emp.name}`}
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination Footer */}
        {filteredEmployees.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-8 md:p-10 flex flex-col sm:flex-row items-center justify-between gap-6 px-10 md:px-14 rounded-b-[3rem]">
            <div className="flex flex-col sm:flex-row items-center gap-4">
              <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.15em]">
                Hiển thị <span className="text-gray-900 tabular-nums font-black">{Math.min(filteredEmployees.length, startIndex + 1)}-{Math.min(filteredEmployees.length, startIndex + pageSize)}</span> trong <span className="text-gray-900 tabular-nums font-black">{filteredEmployees.length}</span> nhân sự
              </span>
              <div className="h-4 w-[1px] bg-gray-200 hidden sm:block"></div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Trang</span>
                <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-lg text-sm font-black tabular-nums border border-blue-100">{currentPage} / {totalPages}</span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => handlePageChange(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                aria-label="First page"
              >
                <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                aria-label="Previous page"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum = 1;
                  if (totalPages <= 5) pageNum = i + 1;
                  else if (currentPage <= 3) pageNum = i + 1;
                  else if (currentPage >= totalPages - 2) pageNum = totalPages - 4 + i;
                  else pageNum = currentPage - 2 + i;

                  return (
                    <button
                      key={pageNum}
                      onClick={() => handlePageChange(pageNum)}
                      className={`w-10 h-10 rounded-xl text-xs font-black transition-all border-2 tabular-nums ${
                        currentPage === pageNum 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-xl scale-110 z-10' 
                        : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                      }`}
                      aria-label={`Go to page ${pageNum}`}
                      aria-current={currentPage === pageNum ? 'page' : undefined}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>

              <button 
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                aria-label="Next page"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handlePageChange(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 text-gray-600 hover:text-blue-600 transition-all shadow-sm active:scale-90"
                aria-label="Last page"
              >
                <ChevronsRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}
      </Card>

      {/* Edit/Add Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-md animate-fade-in">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-lg animate-zoom-in overflow-hidden">
            <div className="flex justify-between items-center p-8 md:p-10 border-b border-gray-100 sticky top-0 bg-white">
              <h3 className="text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none">
                {isEditing ? 'Sửa thông tin' : 'Thêm nhân sự mới'}
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-gray-100 rounded-[1.5rem] transition-colors active:scale-90" aria-label="Close modal">
                <X className="w-6 h-6 text-gray-400" />
              </button>
            </div>

            <div className="p-8 md:p-10 space-y-6 bg-gray-50/50">
              <div className="space-y-6 bg-white p-8 md:p-10 rounded-[2.5rem] border border-gray-100 shadow-sm">
                <div>
                  <label htmlFor="employee_id" className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Mã nhân viên</label>
                  <input 
                    id="employee_id"
                    type="text" 
                    value={formData.employee_id} 
                    onChange={(e) => setFormData({...formData, employee_id: e.target.value.toUpperCase()})}
                    disabled={isEditing}
                    className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all disabled:opacity-50 text-gray-900 shadow-inner"
                    placeholder="VD: NV001"
                  />
                </div>

                <div>
                  <label htmlFor="name" className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Họ và tên</label>
                  <input 
                    id="name"
                    type="text" 
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                    placeholder="Nguyễn Văn A..."
                    className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all text-gray-900 shadow-inner"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                      <label htmlFor="role" className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Vai trò</label>
                      <select 
                        id="role"
                        value={formData.role}
                        onChange={(e) => setFormData({...formData, role: e.target.value})}
                        className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all appearance-none cursor-pointer text-gray-900 shadow-inner"
                      >
                        <option value="admin">Admin</option>
                        <option value="user">User</option>
                      </select>
                  </div>

                  <div>
                    <label htmlFor="password" className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Mật khẩu</label>
                    <input 
                      id="password"
                      type="text" 
                      value={formData.password}
                      onChange={(e) => setFormData({...formData, password: e.target.value})}
                      className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all text-gray-900 shadow-inner"
                    />
                  </div>
                </div>
              </div>

              <button 
                onClick={handleSave}
                className="w-full py-5 bg-blue-600 text-white font-black rounded-[2rem] shadow-xl shadow-blue-100 uppercase text-xs tracking-[0.2em] flex items-center justify-center gap-3 transition-all active:scale-95"
                aria-label="Lưu thay đổi"
              >
                <Save className="w-5 h-5" />
                Lưu thay đổi
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Delete */}
      {userToDelete && (
        <div className="fixed inset-0 bg-black/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-white/20">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2rem] shadow-2xl rotate-12 transition-transform hover:rotate-0">
                <AlertTriangle className="w-12 h-12" />
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-4 uppercase tracking-tighter leading-none">Xóa nhân sự?</h3>
              <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80 leading-relaxed px-4">
                Xác nhận xóa tài khoản <strong>{userToDelete.name}</strong>. Dữ liệu liên quan cũng sẽ bị gỡ bỏ.
              </p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={handleDelete}
                className="w-full py-5 bg-rose-600 text-white font-black rounded-[2rem] text-xs uppercase tracking-widest shadow-2xl shadow-rose-200 transition-all active:scale-95"
                aria-label={`Confirm delete ${userToDelete.name}`}
              >
                XÓA VĨNH VIỄN
              </button>
              <button 
                onClick={() => setUserToDelete(null)}
                className="w-full py-5 bg-white text-gray-400 font-black rounded-[2rem] border-2 border-gray-100 text-xs uppercase tracking-widest hover:bg-gray-100 transition-all active:scale-95"
                aria-label="Cancel delete"
              >
                HỦY BỎ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, Send, Loader2, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Trash2, Check, ShoppingCart, Package, Info, ArrowRight, Gift, Snowflake, RefreshCw
} from 'lucide-react';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: '',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);

  const isValidUrl = useMemo(() => {
    if (!src || typeof src !== 'string' || src.trim().length === 0) return false;
    return src.startsWith('http') || src.startsWith('data:');
  }, [src]);

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full rounded-xl border-2 border-dashed border-gray-200 transition-colors group-hover:bg-gray-100`}>
        <div className={`p-2 bg-white rounded-full shadow-sm border border-gray-100`}>
          <Wrench className={`${mode === 'grid' ? 'w-8 h-8 text-gray-400' : 'w-4 h-4 text-gray-500'}`} />
        </div>
        {mode === 'grid' && (
          <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">No Image</span>
        )}
      </div>
    );
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-white rounded-xl overflow-hidden">
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
      {mode === 'grid' && (
        <div className="absolute inset-0 bg-red-700/0 group-hover:bg-red-700/5 transition-colors pointer-events-none" />
      )}
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedQuantities, setSelectedQuantities] = useState<Record<string, number>>({});
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);


  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async (silent = false) => {
    if (!silent) setIsRefreshing(true);
    const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
    if (!silent) setIsRefreshing(false);
  };

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (tool: Tool) => {
    if (isManageMode) return;
    const isAvailable = tool.status === 'active' && tool.available > 0;

    setSelectedQuantities(prev => {
        const current = prev[tool.id] || 0;
        if (current > 0) {
            const next = { ...prev };
            delete next[tool.id];
            return next;
        } else {
            if (!isAvailable) return prev;
            return { ...prev, [tool.id]: 1 };
        }
    });
  };

  const updateQuantity = (id: string, delta: number, max: number, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedQuantities(prev => {
        const current = prev[id] || 0;
        const next = Math.max(0, Math.min(max, current + delta));
        const newQuantities = { ...prev };
        if (next === 0) delete newQuantities[id];
        else newQuantities[id] = next;
        return newQuantities;
    });
  };

  const handleBulkBorrow = async () => {
    const selectedToolIds = Object.keys(selectedQuantities);
    if (selectedToolIds.length === 0) return;
    setIsBorrowing(true);
    try {
      for (const toolId of selectedToolIds) {
        const tool = tools.find(t => t.id === toolId);
        const qty = selectedQuantities[toolId];
        if (!tool || tool.available < qty) continue;

        const requestsToInsert = Array.from({ length: qty }).map(() => ({
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        }));

        const { error } = await supabase.from('requests').insert(requestsToInsert);
        if (error) throw error;
      }
      setMessage(`Gửi thành công ${selectedToolIds.length} yêu cầu mượn đồ!`);
      setSelectedQuantities({});
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Đã cập nhật' : 'Đã thêm mới');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const totalSelectedCount = useMemo(() => {
    return (Object.values(selectedQuantities) as number[]).reduce((sum: number, q: number) => sum + q, 0);
  }, [selectedQuantities]);

  const selectedToolsSummary = useMemo(() => {
    return Object.keys(selectedQuantities).map(id => {
        const tool = tools.find(t => t.id === id);
        return { name: tool?.name, qty: selectedQuantities[id] };
    }).filter(t => t.name);
  }, [selectedQuantities, tools]);

  const getInventoryBadge = (tool: Tool) => {
    if (tool.status === 'inactive') return { label: 'ĐANG BẢO TRÌ', color: 'bg-rose-500 shadow-rose-200' };
    if (tool.available <= 0) return { label: 'HẾT ĐỒ TRONG KHO', color: 'bg-slate-400 shadow-slate-200' };
    return { label: `SẴN CÓ: ${tool.available}`, color: 'bg-emerald-600 shadow-emerald-200' };
  };

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-40 animate-fade-in max-w-7xl mx-auto">
      {/* Header & Filter */}
      <div className="flex flex-col gap-5 bg-white p-6 rounded-[2rem] md:rounded-[2.5rem] shadow-xl border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-red-700 rounded-2xl md:rounded-[1.8rem] shadow-xl shadow-red-100 text-white"><Package className="w-6 h-6 md:w-8 md:h-8" /></div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none uppercase italic">Kho quà tặng Noel</h2>
                    <p className="text-[9px] md:text-[10px] text-red-700 font-black uppercase tracking-[0.2em] mt-1.5 opacity-50 flex items-center gap-2">
                        <Snowflake className="w-3 h-3" /> Xmas Tracking ❄
                    </p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div role="alert" className="bg-emerald-600 text-white px-5 py-3 rounded-2xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 tracking-widest animate-fade-in">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-50 p-1.5 rounded-2xl border border-gray-200 shadow-inner">
                        <button 
                          onClick={() => {setIsManageMode(true); setSelectedQuantities({});}} 
                          className={`px-6 py-3.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${isManageMode ? 'bg-red-700 text-white shadow-lg scale-105' : 'text-gray-400 hover:text-gray-600'}`}
                          aria-pressed={isManageMode}
                        >
                          QUẢN LÝ
                        </button>
                        <button 
                          onClick={() => {setIsManageMode(false); setSelectedQuantities({});}} 
                          className={`px-6 py-3.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${!isManageMode ? 'bg-red-700 text-white shadow-lg scale-105' : 'text-gray-400 hover:text-gray-600'}`}
                          aria-pressed={!isManageMode}
                        >
                          MƯỢN ĐỒ
                        </button>
                    </div>
                )}

                {isManageMode && (
                    <button 
                        onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} 
                        className="bg-gray-900 hover:bg-black text-white px-7 py-4.5 rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center gap-2"
                        aria-label="Thêm tài sản mới"
                    >
                        <Plus className="w-4 h-4" /> THÊM TÀI SẢN
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-red-700 transition-colors" />
                <input 
                  type="text" 
                  value={searchTerm} 
                  onChange={(e) => setSearchTerm(e.target.value)} 
                  placeholder="Tìm kiếm tên, vị trí thiết bị..." 
                  className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-red-700/5 transition-all shadow-sm text-gray-900"
                  aria-label="Search tools by name or location"
                />
            </div>

            <div className="flex gap-3">
                <div className="relative">
                  <select 
                    value={filterCategory} 
                    onChange={(e) => setFilterCategory(e.target.value)} 
