                            <button onClick={() => setFormData({...formData, available: Math.max(0, formData.available - 1)})} className="p-3 bg-white rounded-xl shadow-sm hover:bg-gray-900 hover:text-white transition-all active:scale-90" aria-label="Decrease available quantity"><Minus className="w-4 h-4"/></button>
                            <span className="flex-1 text-center font-black text-lg tabular-nums text-gray-900">{formData.available}</span>
                            <button onClick={() => setFormData({...formData, available: Math.min(formData.quantity, formData.available + 1)})} className="p-3 bg-white rounded-xl shadow-sm hover:bg-gray-900 hover:text-white transition-all active:scale-90" aria-label="Increase available quantity"><Plus className="w-4 h-4"/></button>
                        </div>
                    </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <div className="space-y-4">
                    <div className="space-y-2">
                        <label htmlFor="tool_image_url" className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Đường dẫn hình ảnh (URL)</label>
                        <input id="tool_image_url" type="text" placeholder="Dán link ảnh tại đây..." value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-6 py-4 bg-white border border-gray-100 rounded-2xl text-xs font-bold outline-none focus:ring-4 focus:ring-red-700/5 transition-all shadow-sm text-gray-900"/>
                    </div>
                    <div className="h-40 rounded-[2rem] bg-white border-4 border-dashed border-gray-100 flex items-center justify-center overflow-hidden shadow-inner group">
                        {formData.image ? <img src={formData.image} alt="Preview" className="h-full w-full object-contain p-4 group-hover:scale-105 transition-transform" onError={(e) => (e.currentTarget.src = 'https://via.placeholder.com/200?text=Loi+Anh')} /> : <ImageIcon className="w-10 h-10 text-gray-200" />}
                    </div>
                 </div>
                 <div className="flex flex-col space-y-2">
                    <label htmlFor="tool_description" className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Mô tả thông số kỹ thuật</label>
                    <textarea id="tool_description" placeholder="Thông tin chi tiết thiết bị..." value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="flex-1 w-full px-6 py-5 bg-white border border-gray-100 rounded-[2rem] text-xs font-bold outline-none resize-none shadow-inner focus:ring-4 focus:ring-red-700/5 transition-all text-gray-900"/>
                 </div>
              </div>

              <button 
                onClick={handleSaveTool} 
                className="w-full py-6 bg-red-700 hover:bg-black text-white font-black rounded-[2rem] shadow-2xl shadow-red-100 uppercase text-[11px] tracking-[0.25em] flex items-center justify-center gap-4 transition-all active:scale-95 border-4 border-white/20 italic"
                aria-label="Save tool changes"
              >
                <Save className="w-6 h-6"/> LƯU THAY ĐỔI NGAY
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation */}
      {toolToDelete && (
        <div className="fixed inset-0 bg-red-950/90 z-[110] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border-4 border-white">
            <div className="p-12 text-center">
              <div className="w-24 h-24 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-8 rounded-[2.5rem] shadow-xl shadow-rose-100 rotate-12 transition-transform hover:rotate-0"><AlertTriangle className="w-12 h-12"/></div>
              <h3 className="text-2xl font-black text-gray-900 mb-3 uppercase tracking-tighter italic">Gỡ bỏ tài sản?</h3>
              <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80 leading-relaxed px-6">Hành động này sẽ xóa vĩnh viễn thiết bị khỏi hệ thống quản lý.</p>
            </div>
            <div className="bg-gray-50/50 p-8 flex flex-col gap-4 border-t border-gray-100">
              <button 
                onClick={async () => { await supabase.from('tools').delete().eq('id', toolToDelete); await fetchTools(); setToolToDelete(null); setMessage('Đã xóa thành công'); setTimeout(() => setMessage(null), 3000); }} 
                className="w-full py-6 bg-rose-600 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-2xl shadow-rose-200 transition-all active:scale-95"
                aria-label="Confirm delete tool"
              >
                XÓA TÀI SẢN
              </button>
              <button 
                onClick={() => setToolToDelete(null)} 
                className="w-full py-6 bg-white text-gray-400 font-black rounded-2xl border-2 border-gray-100 text-[10px] uppercase tracking-widest active:scale-95"
                aria-label="Cancel delete"
              >
                QUAY LẠI
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon, AlertCircle, ChevronRight, ArrowUpRight, Snowflake,
  CheckCircle2, Ban, History, Clock
} from 'lucide-react';

interface RequestManagerProps { user: User; }

const ToolTableImage = ({ toolId, toolName }: { toolId: string, toolName: string }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  return (
    <div className="w-12 h-12 md:w-16 md:h-16 bg-white border border-gray-100 rounded-2xl overflow-hidden flex items-center justify-center p-1.5 shadow-sm group-hover:scale-110 transition-transform duration-500">
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-6 h-6 text-gray-200" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  const fetchRequests = async () => {
    setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    // Thứ tự ưu tiên hiển thị: Pending (0) -> Approved (1) -> Returned (2) -> Rejected (3)
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      returned: 2,
      rejected: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      return matchesSearch && matchesStatus;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;

      // Sắp xếp theo mức độ ưu tiên trạng thái trước
      if (priorityA !== priorityB) return priorityA - priorityB;

      // Nếu cùng trạng thái, đưa những đơn mới nhất (theo ngày mượn) lên đầu
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);

        // Optimistic UI Update for approve
        setRequests(prevRequests => prevRequests.map(req => 
          req.id === id ? { ...req, status: 'approved' } : req
        ));

      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);

        // Optimistic UI Update for return
        setRequests(prevRequests => prevRequests.map(req => 
          req.id === id ? { ...req, status: 'returned', returned_at: new Date().toISOString() } : req
        ));

      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);

        // Optimistic UI Update for reject
        setRequests(prevRequests => prevRequests.map(req => 
          req.id === id ? { ...req, status: 'rejected' } : req
        ));

      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);

        // Optimistic UI Update for cancel (remove from list)
        setRequests(prevRequests => prevRequests.filter(req => req.id !== id));
      }

      // Trigger a refresh for counts in sidebar/header
      window.dispatchEvent(new CustomEvent('refresh-counts'));

      // No need to call fetchRequests() here, UI is already updated optimistically
      // A full refetch might be triggered periodically by other effects or on tab switch if needed.

    } catch (e: any) {
      alert(e.message);
      // If optimistic update was done, revert it here if there was an error
      // For now, simple alert is sufficient, a full refetch on error could be another option.
      fetchRequests(); // Re-fetch on error to ensure data consistency
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { 
        color: 'bg-amber-100 text-amber-700 border-amber-300 ring-4 ring-amber-500/10', 
        icon: <Clock className="w-3.5 h-3.5 animate-pulse" />, 
        label: 'ĐANG CHỜ DUYỆT' 
      },
      approved: { 
        color: 'bg-emerald-100 text-emerald-700 border-emerald-300 ring-4 ring-emerald-500/10', 
        icon: <PackageCheck className="w-3.5 h-3.5" />, 
        label: 'ĐANG CHO MƯỢN' 
      },
      returned: { 
        color: 'bg-slate-100 text-slate-600 border-slate-300 ring-4 ring-slate-500/10', 
        icon: <History className="w-3.5 h-3.5" />, 
        label: 'ĐÃ TRẢ THÀNH CÔNG' 
      },
      rejected: { 
        color: 'bg-rose-100 text-rose-700 border-rose-300 ring-4 ring-rose-500/10', 
        icon: <Ban className="w-3.5 h-3.5" />, 
        label: 'YÊU CẦU TỪ CHỐI' 
      }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2.5 px-4 py-2 rounded-full text-[10px] font-black tracking-widest border-2 shadow-sm ${c.color} uppercase transition-all group-hover:scale-105`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in pb-20">
      {/* Header Panel */}
      <div className="bg-white p-6 md:p-10 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden">
        <div className="absolute -top-10 -right-10 opacity-[0.03] pointer-events-none rotate-12">
            <RefreshCw className="w-48 h-48" />
        </div>

        <div className="flex items-center gap-6 relative z-10">
          <div className="p-4 bg-red-700 rounded-3xl shadow-xl shadow-red-100 text-white transform -rotate-3 transition-transform hover:rotate-0">
            <RefreshCw className="w-7 h-7" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Phê duyệt mượn trả</h2>
            <p className="text-[10px] text-red-700 font-black uppercase tracking-[0.25em] mt-2 opacity-50 flex items-center gap-2">
                <Snowflake className="w-3 h-3 text-blue-300" /> Hệ thống xét duyệt ưu tiên ❄
            </p>
          </div>
        </div>

        <div className="flex bg-gray-50 p-1.5 rounded-[1.8rem] border border-gray-200 shadow-inner relative z-10">
            {user.role === 'admin' && (
              <button 
                onClick={() => setActiveTab('all')} 
                className={`px-8 md:px-12 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}
                aria-pressed={activeTab === 'all'}
              >
                TẤT CẢ ĐƠN
              </button>
            )}
            <button 
              onClick={() => setActiveTab('personal')} 
              className={`px-8 md:px-12 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? 'bg-red-700 text-white shadow-xl' : 'text-gray-400 hover:text-gray-600'}`}
              aria-pressed={activeTab === 'personal'}
            >
              CỦA TÔI
            </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 group">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5 group-focus-within:text-red-700 transition-colors" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm theo nhân viên, thiết bị, mã NV..." 
            className="w-full pl-14 pr-6 py-4.5 bg-white border border-gray-100 rounded-[1.8rem] text-sm font-bold outline-none focus:ring-4 focus:ring-red-700/5 transition-all shadow-lg shadow-gray-200/30 text-gray-900" 
            aria-label="Search requests"
          />
        </div>

        <div className="relative">
            <select 
              value={filterStatus} 
              onChange={e => setFilterStatus(e.target.value)} 
              className="w-full md:w-64 px-8 py-4.5 bg-white border border-gray-100 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-lg shadow-gray-200/30 hover:bg-gray-50 transition-colors appearance-none pr-14 text-gray-900"
              aria-label="Filter by status"
            >
              <option value="all">TẤT CẢ TRẠNG THÁI</option>
              <option value="pending">⏳ ĐANG CHỜ DUYỆT</option>
              <option value="approved">📦 ĐANG CHO MƯỢN</option>
              <option value="returned">✅ ĐÃ TRẢ THÀNH CÔNG</option>
              <option value="rejected">❌ ĐÃ TỪ CHỐI</option>
            </select>
            <ChevronRight className="absolute right-5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none rotate-90" />
        </div>
      </div>

      {/* Request Table Card */}
      <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[3rem] bg-white">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">Thành viên</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">Tài sản / Thiết bị</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">Trạng thái hiện tại</th>
                <th className="px-8 md:px-10 py-7 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] text-right">Thao tác xử lý</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={4} className="py-40 text-center animate-fade-in"><Loader2 className="w-12 h-12 animate-spin text-red-700 mx-auto opacity-10" /></td></tr>
              ) : filteredRequests.length === 0 ? (
                <tr><td colSpan={4} className="py-40 text-center animate-fade-in">
                    <div className="flex flex-col items-center gap-4 opacity-20">
                        <AlertCircle className="w-16 h-16 text-gray-400" />
                        <p className="text-sm font-black uppercase tracking-widest italic text-gray-400">Chưa có yêu cầu nào cần phê duyệt ❄</p>
                    </div>
                </td></tr>
              ) : (
                filteredRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className={`group transition-all duration-500 border-l-[6px] border-l-transparent ${
                      req.status === 'pending' 
                        ? 'bg-amber-50/5 hover:bg-amber-100/30 hover:border-l-amber-500' 
                        : 'hover:bg-red-50/10 hover:border-l-red-700'
                    }`}
                  >
                    <td className="px-8 md:px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-gray-900 text-white rounded-2xl flex items-center justify-center font-black text-lg shadow-lg border-2 border-white group-hover:bg-red-700 transition-colors duration-500">
                          {req.user_name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <div className="font-black text-gray-900 text-[14px] uppercase tracking-tighter leading-none">{req.user_name}</div>
                          <div className="text-[9px] text-gray-400 font-black tracking-widest mt-2 uppercase opacity-60 italic">{req.employee_id} • {new Date(req.borrow_date).toLocaleDateString('vi-VN')}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 md:px-10 py-6">
                      <div className="flex items-center gap-5">
                        <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                        <div className="font-black text-gray-800 text-[14px] uppercase tracking-tighter truncate max-w-[180px]">{req.tool_name}</div>
                      </div>
                    </td>
                    <td className="px-8 md:px-10 py-6 text-center">
                      {getStatusBadge(req.status)}
                    </td>
                    <td className="px-8 md:px-10 py-6 text-right">
                      {processingId === req.id ? (
                        <div className="flex justify-end animate-spin"><Loader2 className="w-8 h-8 text-red-700" /></div>
                      ) : (
                        <div className="flex justify-end gap-3 items-center">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <div className="flex gap-2 animate-fade-in-right">
                              <button 
                                onClick={() => handleAction(req.id, req.tool_id, 'approve')} 
                                className="flex items-center justify-center gap-2 px-8 py-4.5 bg-emerald-600 text-white rounded-[1.4rem] text-[11px] font-black tracking-[0.1em] shadow-xl shadow-emerald-200/50 hover:bg-emerald-700 active:scale-95 transition-all uppercase border-b-4 border-emerald-800"
                                aria-label={`Approve request for ${req.tool_name} by ${req.user_name}`}
                              >
                                <CheckCircle2 className="w-4 h-4" /> DUYỆT ĐƠN
                              </button>
                              <button 
                                onClick={() => handleAction(req.id, req.tool_id, 'reject')} 
                                className="flex items-center justify-center gap-2 px-6 py-4.5 bg-rose-50 text-rose-600 rounded-[1.4rem] text-[11px] font-black tracking-[0.1em] border-2 border-rose-100 hover:bg-rose-600 hover:text-white active:scale-95 transition-all uppercase"
                                aria-label={`Reject request for ${req.tool_name} by ${req.user_name}`}
                              >
                                <Ban className="w-4 h-4" /> TỪ CHỐI
                              </button>
                            </div>
                          )}

                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button 
                              onClick={() => handleAction(req.id, req.tool_id, 'return')} 
                              className="flex items-center justify-center gap-3 px-10 py-4.5 bg-gray-900 text-white rounded-[1.4rem] text-[11px] font-black tracking-[0.15em] shadow-2xl hover:bg-red-700 active:scale-95 transition-all uppercase border-b-4 border-black"
                              aria-label={`Confirm return of ${req.tool_name} by ${req.user_name}`}
                            >
                              <RotateCcw className="w-4 h-4" /> XÁC NHẬN THU HỒI
                            </button>
                          )}

                          {(req.user_id === user.id && req.status === 'pending') && (
                            <button 
                              onClick={() => handleAction(req.id, req.tool_id, 'cancel')} 
                              className="flex items-center gap-2 px-6 py-4 bg-rose-50 text-rose-600 rounded-[1.2rem] text-[10px] font-black uppercase tracking-widest hover:bg-rose-600 hover:text-white transition-all shadow-sm"
                              aria-label={`Cancel request for ${req.tool_name}`}
                            >
                              <Trash2 className="w-4 h-4" /> HỦY ĐƠN
                            </button>
                          )}

                          {/* Professional Details Icon */}
                          <div className="w-10 h-10 flex items-center justify-center text-gray-200 hover:text-red-700 hover:bg-red-50 rounded-full transition-all cursor-pointer ml-2 opacity-0 group-hover:opacity-100" title="Xem chi tiết đơn" aria-label="View request details">
                             <ArrowUpRight className="w-5 h-5" />
                          </div>
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </Card>

      {/* Visual Guide Legend */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 px-6">
          <div className="flex items-center gap-3 bg-amber-50/50 p-5 rounded-[1.5rem] border border-amber-100 shadow-sm">
             <div className="w-3 h-3 rounded-full bg-amber-500 animate-pulse shadow-[0_0_8px_rgba(245,158,11,0.5)]"></div>
             <p className="text-[10px] font-black text-amber-800 uppercase tracking-widest">Đang chờ (Ưu tiên nhất) ❄</p>
          </div>
          <div className="flex items-center gap-3 bg-emerald-50/50 p-5 rounded-[1.5rem] border border-emerald-100 shadow-sm">
             <div className="w-3 h-3 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
             <p className="text-[10px] font-black text-emerald-800 uppercase tracking-widest">Đang mượn (Theo dõi) 📦</p>
          </div>
          <div className="flex items-center gap-3 bg-slate-50/50 p-5 rounded-[1.5rem] border border-slate-100 shadow-sm">
             <div className="w-3 h-3 rounded-full bg-slate-500"></div>
             <p className="text-[10px] font-black text-slate-700 uppercase tracking-widest">Đã hoàn thành ✅</p>
          </div>
          <div className="flex items-center gap-3 bg-rose-50/50 p-5 rounded-[1.5rem] border border-rose-100 shadow-sm">
             <div className="w-3 h-3 rounded-full bg-rose-600"></div>
             <p className="text-[10px] font-black text-rose-700 uppercase tracking-widest">Đã từ chối ❌</p>
          </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  History, Search, Calendar, Filter, X, 
  User as UserIcon, ShieldCheck, ChevronDown, 
  SlidersHorizontal, ChevronLeft, ChevronRight, 
  Loader2, RefreshCw, AlertCircle, ChevronsLeft, ChevronsRight,
  Undo2, CheckCircle2, AlertTriangle, FileSpreadsheet,
  Download, ListFilter, CalendarDays, Activity, 
  ArrowUpRight, Clock, Box, LayoutPanelLeft, Timer, PackageCheck, XCircle, RotateCcw, TrendingUp // Added TrendingUp for summary stats
} from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | 'yesterday' | 'thisWeek' | '7days' | '30days' | '90days' | 'thisMonth';

const ITEMS_PER_PAGE = 10; // Giảm ITEMS_PER_PAGE để gọn gàng hơn

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div 
      role="status"
      aria-live="polite"
      className={`fixed bottom-10 right-10 z-[100] ${type === 'success' ? 'bg-emerald-600' : 'bg-rose-600'} text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up border border-white/20 backdrop-blur-md`}
    >
      {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
      <p className="text-xs font-black uppercase tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-2 hover:bg-white/20 p-1 rounded-full active:scale-90" aria-label="Close notification"><X className="w-4 h-4"/></button>
    </div>
  );
};

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reBorrowingId, setReBorrowingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // States cho bộ lọc
  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');

  // State phân trang
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async (silent = false) => {
    if (!user) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    setError(null);

    try {
      let query = supabase
        .from('requests')
        .select('*')
        .order('borrow_date', { ascending: false });

      if (user.role !== 'admin') {
        query = query.eq('user_id', user.id);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      if (data) {
        setLogs(data as ExtendedBorrowRequest[]);
      }
    } catch (err: any) {
      console.error("Fetch history error:", err);
      setError("Không thể tải dữ liệu lịch sử.");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    // Chỉ fetch lại dữ liệu khi user hoặc role thay đổi, không phải khi bộ lọc thay đổi
    fetchHistory();
  }, [user.id, user.role]);

  useEffect(() => {
    // Reset trang về 1 mỗi khi bất kỳ bộ lọc nào thay đổi
    setCurrentPage(1);
  }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Quản lý';
    if (req.status === 'rejected') return req.rejected_by || 'Quản lý';
    return '-';
  };

  const handleReBorrow = async (log: ExtendedBorrowRequest) => {
    setReBorrowingId(log.id);
    try {
      const { error } = await supabase.from('requests').insert([{
        user_id: user.id,
        user_name: user.name,
        employee_id: user.employeeCode,
        tool_id: log.tool_id,
        tool_name: log.tool_name,
        borrow_date: new Date().toISOString(),
        status: 'pending'
      }]);

      if (error) throw error;

      setToast({ message: "Đã gửi yêu cầu mượn lại thành công!", type: 'success' });
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchHistory(true); // Fetch lại dữ liệu sau khi gửi yêu cầu
    } catch (err: any) {
      setToast({ message: "Lỗi: " + err.message, type: 'error' });
    } finally {
      setReBorrowingId(null);
    }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.trim().toLowerCase();
      const handlerLower = handlerFilter.trim().toLowerCase();

      const matchesText = !searchLower || (
        log.user_name?.toLowerCase().includes(searchLower) ||
        log.employee_id?.toLowerCase().includes(searchLower) ||
        log.tool_name?.toLowerCase().includes(searchLower)
      );

      const currentHandler = (getHandlerName(log) || '').toLowerCase(); // Ensure getHandlerName returns string
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);

      const matchesStatus = statusFilter === 'all' || log.status === statusFilter;

      const logBorrowDate = new Date(log.borrow_date.split('T')[0]); // Lấy chỉ phần ngày
      const filterStartDate = startDate ? new Date(startDate) : null;
      const filterEndDate = endDate ? new Date(endDate) : null;

      const matchesDateRange = 
        (!filterStartDate || logBorrowDate >= filterStartDate) &&
        (!filterEndDate || logBorrowDate <= filterEndDate);

      return matchesText && matchesHandler && matchesStatus && matchesDateRange;
    });
  }, [logs, searchText, handlerFilter, statusFilter, startDate, endDate]); // Thêm các dependencies cho bộ lọc

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-500 text-white shadow-amber-200/50', icon: <Timer className="w-3 h-3 animate-pulse" />, label: 'CHỜ DUYỆT' },
      approved: { color: 'bg-emerald-600 text-white shadow-emerald-200/50', icon: <PackageCheck className="w-3 h-3" />, label: 'ĐANG MƯỢN' },
      returned: { color: 'bg-slate-500 text-white shadow-slate-200/50', icon: <RotateCcw className="w-3 h-3" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-rose-600 text-white shadow-rose-200/50', icon: <XCircle className="w-3 h-3" />, label: 'TỪ CHỐI' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl text-[8px] font-black tracking-widest border-2 border-white shadow-md ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  const summaryStats = useMemo(() => {
    return {
      total: filteredLogs.length, // Thống kê dựa trên filteredLogs
      pending: filteredLogs.filter(l => l.status === 'pending').length,
      borrowing: filteredLogs.filter(l => l.status === 'approved').length,
      completed: filteredLogs.filter(l => l.status === 'returned' || l.status === 'rejected').length
    };
  }, [filteredLogs]); // Dependency là filteredLogs

  const handleExportExcel = () => {
    if (filteredLogs.length === 0) return alert("Không có dữ liệu để xuất.");

    const exportData = filteredLogs.map(log => ({
      'Người mượn': log.user_name,
      'Mã nhân viên': log.employee_id,
      'Thiết bị': log.tool_name,
      'Ngày mượn': new Date(log.borrow_date).toLocaleString('vi-VN'),
      'Ngày trả': log.returned_at ? new Date(log.returned_at).toLocaleString('vi-VN') : 'Chưa trả',
      'Người xử lý': getHandlerName(log),
      'Trạng thái': log.status === 'approved' ? 'Đang mượn' : 
                    log.status === 'returned' ? 'Đã trả' : 
                    log.status === 'rejected' ? 'Từ chối' : 'Chờ duyệt'
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "LichSuMuonTra");
    XLSX.writeFile(workbook, `Lich_su_muon_tra_${new Date().getTime()}.xlsx`);
  };

  const totalPages = Math.max(1, Math.ceil(filteredLogs.length / ITEMS_PER_PAGE));
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentLogs = filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];

    let start = new Date();
    let end = new Date();

    switch (option) {
        case 'yesterday':
            start.setDate(today.getDate() - 1);
            end.setDate(today.getDate() - 1);
            break;
        case 'thisWeek':
            const day = today.getDay();
            const diff = today.getDate() - day + (day === 0 ? -6 : 1);
            start = new Date(today.setDate(diff));
            end = new Date();
            break;
        case '7days':
            start.setDate(today.getDate() - 7);
            break;
        case '30days':
            start.setDate(today.getDate() - 30);
            break;
        case '90days':
            start.setDate(today.getDate() - 90);
            break;
        case 'thisMonth':
            start = new Date(today.getFullYear(), today.getMonth(), 1);
            end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
            break;
        case 'today':
        default:
            break; 
    }

    setStartDate(formatDate(start));
    setEndDate(formatDate(end));
  };

  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
      setQuickDate('custom');
      if (type === 'start') setStartDate(value);
      else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText('');
    setHandlerFilter('');
    setStartDate('');
    setEndDate('');
    setStatusFilter('all');
    setQuickDate('custom');
    setCurrentPage(1);
  };

  const activeFiltersCount = [
    searchText.trim(), 
    handlerFilter.trim(), 
    startDate, 
    endDate, 
    statusFilter !== 'all'
  ].filter(Boolean).length;

  return (
    <div className="space-y-4 md:space-y-6 animate-fade-in pb-10 max-w-7xl mx-auto">
       {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

       {/* Header Panel */}
       <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-indigo-600 rounded-[1.8rem] shadow-xl shadow-indigo-100 text-white">
                    <History className="w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none italic uppercase">Lịch sử hoạt động</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">
                        Hồ sơ tra cứu mượn trả thiết bị
                    </p>
                </div>
            </div>
            <div className="flex items-center gap-2">
                <button 
                  onClick={handleExportExcel}
                  className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 bg-emerald-50 text-emerald-600 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all border border-emerald-100 hover:bg-emerald-600 hover:text-white shadow-sm active:scale-95"
                  aria-label="Export history to Excel"
                >
                  <FileSpreadsheet className="w-4 h-4"/> Xuất Excel
                </button>
                <button 
                  onClick={() => fetchHistory(true)} 
                  className="p-4 bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-2xl transition-all border border-gray-100 shadow-sm active:scale-95"
                  aria-label="Refresh history"
                >
                  {isRefreshing ? <Loader2 className="w-5 h-5 animate-spin"/> : <RefreshCw className="w-5 h-5"/>}
                </button>
            </div>
       </div>

       {/* Summary Stats Cards */}
       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-purple-100 text-purple-600 rounded-lg"><LayoutPanelLeft className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-purple-400 uppercase tracking-widest">Tổng lượt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.total}</p>
          </Card>
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-amber-100 text-amber-600 rounded-lg"><Clock className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-amber-400 uppercase tracking-widest">Chờ duyệt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.pending}</p>
          </Card>
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-indigo-100 text-indigo-600 rounded-lg"><Box className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-indigo-400 uppercase tracking-widest">Đang mượn</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.borrowing}</p>
          </Card>
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-emerald-100 text-emerald-600 rounded-lg"><CheckCircle2 className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-emerald-400 uppercase tracking-widest">Hoàn thành</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.completed}</p>
          </Card>
       </div>

       {/* Filter Card */}
       <Card className="p-6 md:p-8 overflow-visible border-none shadow-xl rounded-[2.5rem] md:rounded-[3rem] bg-white">
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h3 className="text-[9px] md:text-[11px] font-black text-gray-400 flex items-center gap-2 uppercase tracking-[0.15em]">
                        <SlidersHorizontal className="w-3.5 h-3.5 text-indigo-600" /> Công cụ lọc linh hoạt
                    </h3>
                    {activeFiltersCount > 0 && (
                        <button onClick={clearFilters} className="text-[9px] text-rose-600 font-black uppercase tracking-widest flex items-center gap-1 hover:underline" aria-label="Clear all filters">
                            <X className="w-3 h-3" /> Xóa lọc
                        </button>
                    )}
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
                    <div className="xl:col-span-4 space-y-4">
                        <label className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Khoảng thời gian nhanh</label>
                        <div className="grid grid-cols-3 md:grid-cols-4 gap-2">
                             {[
                               {id: 'today', l: 'H.Nay'}, 
                               {id: 'yesterday', l: 'H.Qua'}, 
                               {id: 'thisWeek', l: 'Tuần này'}, 
                               {id: '7days', l: '7 ngày'}, 
                               {id: '30days', l: '30 ngày'}, 
                               {id: '90days', l: '90 ngày'}, 
                               {id: 'thisMonth', l: 'Tháng này'}
                             ].map((btn) => (
                                <button
                                    key={btn.id}
                                    onClick={() => handleQuickDate(btn.id as QuickDateOption)}
                                    className={`px-2 py-2.5 text-[8px] font-black uppercase tracking-widest rounded-lg border-2 transition-all shadow-sm active:scale-95 ${
                                        quickDate === btn.id 
                                        ? 'bg-indigo-600 text-white border-indigo-600' 
                                        : 'bg-white text-gray-400 border-gray-100 hover:border-indigo-200'
                                    }`}
                                    aria-pressed={quickDate === btn.id}
                                >
                                    {btn.l}
                                </button>
                             ))}
                        </div>
                    </div>

                    <div className="xl:col-span-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div className="space-y-2">
                            <label htmlFor="startDate" className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Tùy chỉnh ngày</label>
                            <div className="flex items-center gap-2">
                                <input id="startDate" type="date" value={startDate} onChange={e => handleManualDateChange('start', e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-bold text-gray-900 focus:ring-2 focus:ring-indigo-600/10 outline-none shadow-inner" aria-label="Start date filter"/>
                                <span className="text-gray-300">-</span>
                                <input id="endDate" type="date" value={endDate} onChange={e => handleManualDateChange('end', e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-bold text-gray-900 focus:ring-2 focus:ring-indigo-600/10 outline-none shadow-inner" aria-label="End date filter"/>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label htmlFor="statusFilter" className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Trạng thái & Phê duyệt</label>
                            <div className="flex flex-col gap-2">
                                <div className="relative">
                                    <select id="statusFilter" value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-black uppercase text-gray-900 outline-none cursor-pointer appearance-none shadow-inner" aria-label="Filter by status">
                                        <option value="all">TẤT CẢ TRẠNG THÁI</option>
                                        <option value="pending">CHỜ DUYỆT</option>
                                        <option value="approved">ĐANG MƯỢN</option>
                                        <option value="returned">ĐÃ TRẢ</option>
                                        <option value="rejected">TỪ CHỐI</option>
                                    </select>
                                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none" />
                                </div>
                                <div className="relative group">
                                    <ShieldCheck className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5" />
                                    <input type="text" value={handlerFilter} onChange={e => setHandlerFilter(e.target.value)} placeholder="Người xử lý..." className="w-full pl-9 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-bold text-gray-900 outline-none shadow-inner" aria-label="Filter by handler name"/>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label htmlFor="searchText" className="block text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Tìm kiếm văn bản</label>
                            <div className="relative group h-[calc(100%-24px)]">
                                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                                <input 
                                    id="searchText"
                                    type="text" 
                                    value={searchText}
                                    onChange={e => setSearchText(e.target.value)}
                                    placeholder="Tên, mã NV, thiết bị..." 
                                    className="w-full h-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-[11px] font-bold text-gray-900 outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all shadow-inner"
                                    aria-label="Search by user name, employee ID, or tool name"
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
       </Card>

       {/* History Table */}
       <Card className="p-0 overflow-hidden border-none shadow-xl rounded-[2.5rem] md:rounded-[3rem] bg-white">
            <div className="overflow-x-auto w-full no-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50/80 border-b border-gray-100">
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Thành viên</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Thiết bị</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Thời gian</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Admin xử lý</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-center text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-right text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-400">Hành động</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {loading ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center animate-fade-in"><Loader2 className="w-10 h-10 animate-spin text-indigo-600 mx-auto opacity-20" /></td></tr>
                        ) : currentLogs.length === 0 ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50 animate-fade-in">Không có kết quả phù hợp</td></tr>
                        ) : (
                            currentLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-indigo-50/20 transition-all duration-300 group">
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 md:w-10 md:h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-xs md:text-sm border-2 border-indigo-400">
                                                {item.user_name?.charAt(0)}
                                            </div>
                                            <div>
                                                <div className="font-black text-gray-900 text-[11px] md:text-[13px] uppercase tracking-tighter">{item.user_name}</div>
                                                <div className="text-[7px] md:text-[9px] text-gray-400 font-black uppercase tracking-widest mt-0.5">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <span className="font-black text-gray-800 text-[11px] md:text-[13px] uppercase tracking-tight">{item.tool_name}</span>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="text-gray-900 font-black text-[10px] md:text-xs">M: {new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        {item.returned_at && (
                                            <div className="text-indigo-500 font-black text-[10px] md:text-xs mt-1">T: {new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                        )}
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="flex items-center gap-1.5 text-[8px] md:text-[10px] font-black text-gray-600 uppercase">
                                            <ShieldCheck className="w-3 h-3 text-gray-300" /> {getHandlerName(item)}
                                        </div>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6 text-center">
                                        {getStatusBadge(item.status)}
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6 text-right">
                                        {(item.status === 'returned' || item.status === 'rejected') ? (
                                            <button 
                                                onClick={() => handleReBorrow(item)}
                                                disabled={reBorrowingId === item.id}
                                                className="inline-flex items-center gap-1.5 px-3 py-2 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-lg text-[9px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50 active:scale-95"
                                                aria-label={`Re-borrow ${item.tool_name}`}
                                            >
                                                {reBorrowingId === item.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Undo2 className="w-3.5 h-3.5" />}
                                                Mượn lại
                                            </button>
                                        ) : (
                                            <span className="text-gray-100 font-black text-[9px]">N/A</span>
                                        )}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Pagination Footer */}
            {filteredLogs.length > 0 && (
                <div className="bg-gray-50 border-t border-gray-100 p-6 md:p-10 flex flex-col sm:flex-row items-center justify-between gap-6 rounded-b-[2.5rem] md:rounded-b-[3rem]">
                    <div className="text-[9px] md:text-[11px] text-gray-400 font-black uppercase tracking-widest">
                      Hiển thị <span className="text-gray-900 font-black">{startIndex + 1}-{Math.min(filteredLogs.length, startIndex + ITEMS_PER_PAGE)}</span> trên {filteredLogs.length}
                    </div>

                    <div className="flex items-center gap-2">
                      <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-2.5 rounded-xl border border-gray-200 bg-white disabled:opacity-30 hover:bg-indigo-50 transition-all active:scale-95" aria-label="Previous page"><ChevronLeft className="w-5 h-5" /></button>
                      <div className="flex items-center gap-1">
                        {Array.from({ length: totalPages }, (_, i) => i + 1).filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1).map((p, idx, arr) => (
                             <React.Fragment key={p}>
                                {idx > 0 && arr[idx-1] !== p - 1 && <span className="text-gray-300 px-1 font-bold">...</span>}
                                <button 
                                    onClick={() => handlePageChange(p)}
                                    className={`w-9 h-9 md:w-11 md:h-11 rounded-xl text-[10px] font-black transition-all border-2 ${currentPage === p ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white text-gray-400 border-gray-100 hover:bg-gray-50'}`}
                                    aria-label={`Go to page ${p}`}
                                    aria-current={currentPage === p ? 'page' : undefined}
                                >
                                    {p}
                                </button>
                             </React.Fragment>
                        ))}
                      </div>
                      <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-2.5 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-indigo-50 transition-all active:scale-95" aria-label="Next page"><ChevronRight className="w-5 h-5" /></button>
                    </div>
                </div>
            )}
       </Card>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { 
  Clock, X, Loader2, ChevronLeft, ChevronRight, Wand2, Trash2, 
  Activity, Home, Briefcase, CalendarDays, Eye, Trophy, Award, 
  Check, Snowflake, Star, Sparkles, AlertCircle, ChevronDown,
  User as UserIcon, CalendarSearch // Added CalendarSearch
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeToNumberArray(timeStr);
  return h + m / 60;
};

const timeToNumberArray = (timeStr: string) => {
    return timeStr.split(':').map(Number);
};

const now = new Date();
const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
const todayTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).setHours(0,0,0,0);

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');
  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  // New states for DayDetailsModal
  const [isDayDetailsModalOpen, setIsDayDetailsModalOpen] = useState(false);
  const [selectedDayRequests, setSelectedDayRequests] = useState<OvertimeRequest[]>([]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isViewOnly = useMemo(() => {
    return !isAdmin && targetUserId !== user.id;
  }, [isAdmin, targetUserId, user.id]);

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate, isAdmin]);

  useEffect(() => {
    if (!selectedDateStr) return;
    // This effect should trigger when selectedDateStr or targetUserId changes to fill the main modal
    const currentReq = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);

    if (currentReq) {
        setStartTime(currentReq.start_time);
        setEndTime(currentReq.end_time);
        setReason(currentReq.reason || '');
        setEditingRequestId(currentReq.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const isWorkingDay = dayConfigs[selectedDateStr] ?? (dayOfWeek !== 0);
        setStartTime(isWorkingDay ? (dayOfWeek === 6 ? '14:30' : '17:30') : '08:00');
        setEndTime('20:00');
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, requests, dayConfigs]);

  const fetchRequests = async () => {
    try {
      const { data, error } = await supabase.from('ot_requests').select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
        setIsModalOpen(false); // Close main modal if open
        setIsDayDetailsModalOpen(false); // Close day details modal if open
    } catch (err: any) { alert("Lỗi: " + err.message); }
  };

  const calculatedHours = useMemo(() => {
    if (!selectedDateStr || !startTime || !endTime) return 0;
    const s = timeToNumber(startTime);
    const e = Math.min(timeToNumber(endTime), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;
    const dateObj = new Date(selectedDateStr);
    const isWorkDay = dayConfigs[selectedDateStr] ?? (dateObj.getDay() !== 0);
    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  }, [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return;
    setIsSubmitting(true);
    const payload = { user_id: targetUserId, date: selectedDateStr, start_time: startTime, end_time: endTime, total_hours: calculatedHours, reason, status: 'approved' };
    try {
      const res = editingRequestId ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId) : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      fetchRequests(); setIsModalOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsSubmitting(false); }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        fetchRequests(); setIsModalOpen(false); setIsConfirmCancelOpen(false);
    } catch (err: any) { alert(err.message); } finally { setIsDeleting(false); }
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const dStr = `${currentMonthStr}-${String(i + 1).padStart(2, '0')}`;
        return { day: i + 1, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const topRankings = useMemo(() => {
    const map: Record<string, { name: string; hours: number; count: number }> = {};
    requests.filter(r => r.date.startsWith(currentMonthStr)).forEach(req => {
        if (!map[req.user_id]) map[req.user_id] = { name: req.users?.name || '?', hours: 0, count: 0 };
        map[req.user_id].hours += Number(req.total_hours || 0);
        map[req.user_id].count += 1;
    });
    return Object.values(map).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const renderCalendar = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const first = getFirstDayOfMonth(year, month);
    const offset = first === 0 ? 6 : first - 1;
    for (let i = 0; i < offset; i++) days.push(<div key={`e-${i}`} className="h-16 md:h-36 bg-gray-50/10 border-b border-r border-gray-100/30"></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const cellDate = new Date(dStr).setHours(0,0,0,0);
      const isT = todayStr === dStr;
      const isF = cellDate > todayTime;
      const isP = cellDate < todayTime;
      const dayReqs = requests.filter(r => r.date === dStr);
      const myReq = dayReqs.find(r => r.user_id === user.id);
      const otherReqs = dayReqs.filter(r => r.user_id !== user.id);
      const config = dayConfigs[dStr] ?? (new Date(dStr).getDay() !== 0);

      days.push(
        <div 
          key={d} 
          // This click handler opens the main registration modal for the CURRENT user
          onClick={() => { setSelectedDateStr(dStr); setTargetUserId(user.id); setIsModalOpen(true); }} 
          className={`h-16 md:h-36 relative transition-all cursor-pointer group flex flex-col p-1 md:p-2 border-b border-r 
            ${isT ? 'bg-red-50/80 z-20 border-red-500 ring-1 md:ring-2 ring-inset ring-red-600 shadow-md md:shadow-2xl' : 'bg-white hover:bg-gray-50 border-gray-100'}
            ${isF && !isT ? 'border-1 md:border-2 border-emerald-100/50 bg-emerald-50/5' : ''}
          `}
        >
          {/* Day Header */}
          <div className="flex items-center justify-between z-10">
            <div className="relative">
              <span className={`text-[11px] md:text-lg font-black tabular-nums transition-all ${isT ? 'text-red-700 scale-110 block' : !config ? 'text-rose-400' : isP ? 'text-gray-200' : 'text-gray-500'}`}>
                {d}
              </span>
              {isT && <Sparkles className="absolute -top-1 -right-1 w-2 md:w-5 h-2 md:h-5 text-amber-500 animate-pulse" />}
            </div>
            {!config && <span className="text-[5px] md:text-[8px] font-black px-1 py-0.5 rounded-full bg-rose-50 text-rose-500 uppercase border border-rose-100 scale-90 md:scale-100">Nghỉ</span>}
          </div>

          {/* Optimized Avatar Space for Mobile */}
          <div className="flex-1 flex flex-col mt-0.5 md:mt-2 space-y-0.5 md:space-y-3 overflow-hidden">
            {myReq && (
              <div className="flex items-start">
                <div className="w-4 h-4 md:w-9 md:h-9 rounded-md md:rounded-xl bg-gradient-to-br from-red-600 to-red-800 text-white flex items-center justify-center font-black text-[7px] md:text-sm shadow-sm border-white border-[1px] md:border-[2px] ring-red-50/30">
                  {user.name.charAt(0)}
                </div>
              </div>
            )}

            {otherReqs.length > 0 && (
              <div className="mt-auto flex flex-col gap-0.5 md:gap-1">
                <div className="flex -space-x-1 md:-space-x-2.5">
                    {otherReqs.slice(0, 3).map((r, i) => (
                      <div 
                        key={i} 
                        className="w-3.5 h-3.5 md:w-7 md:h-7 rounded-sm md:rounded-lg bg-white border-[1px] md:border-2 border-gray-50 text-gray-500 flex items-center justify-center font-black text-[5px] md:text-[10px] uppercase shadow-sm"
                        title={r.users?.name}
                      >
                        {r.users?.name?.charAt(0)}
                      </div>
                    ))}
                    {otherReqs.length > 3 && (
                      <div className="w-3.5 h-3.5 md:w-7 md:h-7 rounded-sm md:rounded-lg bg-gray-900 text-white border-[1px] md:border-2 border-white flex items-center justify-center text-[4px] md:text-[9px] font-black shadow-sm">
                        +{otherReqs.length - 3}
                      </div>
                    )}
                  </div>
              </div>
            )}
          </div>
          {/* Total people count - now clickable for DayDetailsModal */}
          {dayReqs.length > 0 && (
            <button 
                className="absolute bottom-1 right-1 md:bottom-2 md:right-2 z-30 inline-flex items-center justify-center h-4 md:h-5 px-1.5 md:px-2 bg-gray-900 text-white text-[7px] md:text-[9px] font-black rounded-full shadow-lg border border-white/50 animate-fade-in uppercase tracking-tight cursor-pointer group-hover:scale-110 transition-transform"
                onClick={(e) => { 
                    e.stopPropagation(); // Prevent opening the main modal when clicking the count
                    setSelectedDateStr(dStr);
                    setSelectedDayRequests(dayReqs);
                    setIsDayDetailsModalOpen(true);
                }}
                aria-label={`View ${dayReqs.length} overtime requests for ${dStr}`}
            >
                {dayReqs.length} <UserIcon className="w-2.5 h-2.5 ml-1 opacity-60" />
            </button>
          )}
        </div>
      );
    }
    return <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-white rounded-b-[1.5rem] md:rounded-b-[2.5rem] overflow-hidden border-l border-t border-gray-100">{days}</div>;
  };

  return (
    <div className="space-y-3 md:space-y-4 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-2 pb-24">
        {/* Header - Fixed Height for Mobile */}
        <div className="flex flex-col sm:flex-row justify-between items-center gap-3 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-xl border border-white/50">
            <div className="flex items-center gap-3 w-full sm:w-auto">
                <div className="p-2 md:p-3 bg-red-700 rounded-xl md:rounded-2xl text-white shadow-lg"><Clock className="w-5 h-5 md:w-7 md:h-7" /></div>
                <div>
                    <h2 className="text-sm md:text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none italic">Lịch tăng ca</h2>
                    <p className="text-[7px] md:text-[9px] font-black text-red-700 uppercase tracking-[0.2em] mt-0.5 opacity-50 flex items-center gap-1.5">
                      <Snowflake className="w-2 h-2 md:w-3 h-3" /> Xmas Staff ❄
                    </p>
                </div>
            </div>
            <div className="w-full sm:w-auto">
                <div className="flex bg-gray-100/50 p-1 rounded-xl border border-gray-200/50">
                    {['calendar', 'personal', 'stats'].map(t => (
                        <button 
                            key={t} 
                            onClick={() => setActiveTab(t as any)} 
                            className={`flex-1 sm:px-6 md:px-8 py-1.5 md:py-2.5 rounded-lg text-[8px] md:text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-red-700 text-white shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                            aria-pressed={activeTab === t}
                        >
                            {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Của tôi' : 'BXH'}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="flex-1 flex flex-col">
            {activeTab === 'calendar' && (
                <div className="flex-1 flex flex-col shadow-xl rounded-[1.5rem] md:rounded-[2.5rem] bg-white overflow-hidden border border-gray-100/50 min-h-[450px]">
                    <div className="flex items-center justify-between p-3 md:p-6 bg-white border-b border-gray-50">
                        <button 
                            onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} 
                            className="p-1.5 md:p-3 hover:bg-red-50 rounded-lg text-red-700 active:scale-90"
                            aria-label="Previous month"
                        >
                            <ChevronLeft className="w-5 h-5 md:w-6 md:h-6"/>
                        </button>
                        <div className="text-center">
                            <h3 className="text-sm md:text-2xl font-black uppercase tracking-[0.2em] text-gray-900 italic">Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        </div>
                        <button 
                            onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} 
                            className="p-1.5 md:p-3 hover:bg-red-50 rounded-lg text-red-700 active:scale-90"
                            aria-label="Next month"
                        >
                            <ChevronRight className="w-5 h-5 md:w-6 md:h-6"/>
                        </button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/30 text-[7px] md:text-[10px] font-black uppercase text-gray-400 text-center py-2 md:py-4 border-b border-gray-100 tracking-[0.1em] md:tracking-[0.2em]">
                        {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <div key={d} className={d === 'Sun' ? 'text-red-300' : ''}>{d}</div>)}
                    </div>
                    {renderCalendar()}
                </div>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
                        <Card className="bg-gradient-to-br from-red-700 to-red-950 text-white border-none p-4 md:p-6 rounded-[1.2rem] md:rounded-[2rem] shadow-xl">
                            <h3 className="text-[7px] md:text-[10px] font-black uppercase opacity-60 mb-1 tracking-widest">Tích lũy giờ</h3>
                            <div className="flex items-end gap-1"><span className="text-2xl md:text-5xl font-black tabular-nums tracking-tighter">{myStats.total.toFixed(1)}</span><span className="text-[8px] font-bold opacity-40 pb-1.5 uppercase">H</span></div>
                        </Card>
                        <Card className="flex flex-col justify-center p-4 md:p-6 rounded-[1.2rem] md:rounded-[2rem] border-2 border-emerald-50 shadow-sm bg-white">
