                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-[2.5rem] shadow-2xl shadow-indigo-200 text-[11px] md:text-xs tracking-[0.2em] uppercase transition-all active:scale-95 disabled:opacity-50 border-4 border-white/20">
