};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const month = new Date().getMonth();
  const isNoel = month === 11;
  const isTet = month === 0 || month === 1;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const getOTCategory = (dateStr: string) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    const isWorking = dayConfigs[dateStr] ?? (day !== 0 && day !== 6);
    return !isWorking ? '200%' : '150%';
  };

  const handleExportExcelPro = (mode: 'today' | 'range') => {
    let filtered = [];
    const department = "Automation";

    if (mode === 'today') {
        filtered = requests.filter(r => r.date === todayStr);
    } else {
        filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    }

    if (filtered.length === 0) return alert("Không tìm thấy dữ liệu đăng ký.");

    // Group by date
    const groupedByDate = filtered.reduce((acc, req) => {
        if (!acc[req.date]) acc[req.date] = [];
        acc[req.date].push(req);
        return acc;
    }, {} as Record<string, OvertimeRequest[]>);

    const workbook = XLSX.utils.book_new();
    const sortedDates = Object.keys(groupedByDate).sort();

    sortedDates.forEach((dateKey) => {
        const dayRequests = groupedByDate[dateKey];
        dayRequests.sort((a, b) => (a.users?.name || "").localeCompare(b.users?.name || ""));

        const displayDate = dateKey.split('-').reverse().join('/');
        const sheetName = dateKey.split('-').reverse().join('-'); // Excel sheet names can't have '/'

        const ws_data = [
            ["ĐĂNG KÝ LÀM THÊM TỰ NGUYỆN HÀNG NGÀY / APPLICATION FOR DAILY OVERTIME VOLUNTARY"],
            [],
            [`Bộ phận/Department: ${department}`, ``, ``, ``, ``, ``, ``, `Ngày/Date: ${displayDate}`],
            [`Tổng số người làm thêm/Total members OT: ${dayRequests.length}`, ``, ``, ``, ``, ``, ``, `Tổng số vé ăn chính/Total main ticket: `],
            [`Tổng số vé ăn phụ/Total sub-meal ticket: `],
            [],
            [
                "STT/No.", 
                "ID đầy đủ", 
                "Họ tên/ Full name", 
                "Bắt đầu (Giờ)", 
                "Kết thúc (Giờ)", 
                "OT 150%", 
                "OT 200%", 
                "OT 270%", 
                "OT 210%", 
                "OT 390%", 
                "Lý do Làm thêm/ Reason", 
                "Chữ ký người làm thêm", 
                "Ghi chú/Note"
            ]
        ];

        dayRequests.forEach((req, index) => {
            const otCat = getOTCategory(req.date);
            const row = [
                index + 1,
                req.users?.employee_id || "N/A",
                req.users?.name || "N/A",
                req.start_time,
                req.end_time,
                otCat === '150%' ? req.total_hours : "", 
                otCat === '200%' ? req.total_hours : "", 
                "", "", "", 
                req.reason || "",
                "", 
                req.date
            ];
            ws_data.push(row);
        });

        ws_data.push([]);
        ws_data.push(["Note/Ghi chú:"]);
        ws_data.push(["- Trước khi cnv làm thêm, bộ phận phải hoàn thành phiếu này (với đầy đủ chữ ký) và nộp lại cho HR lúc 15h cùng ngày."]);
        ws_data.push(["- Biểu đơn này sử dụng chung cho cả đăng ký làm thêm và xin cấp vé ăn."]);
        ws_data.push(["Before employees do OT, section must submit this form (fully signed) to HR 15 hours at the same working day."]);
        ws_data.push([]);
        ws_data.push([
            "Quản lý người việt (VN Manager)", "",
            "Quản lý người việt (VN Manager)", "",
            "Quản lý Người Hàn (Korea Manager)", "",
            "Quản lý Người Hàn Nhân Sự (HR Manager)"
        ]);
        ws_data.push(["", "", "", "", "", "", "", ""]);
        ws_data.push(["Date:", "", "Date:", "", "Date:", "", "Date:", ""]);

        const worksheet = XLSX.utils.aoa_to_sheet(ws_data);
        worksheet['!merges'] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: 12 } }];
        XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
    });

    XLSX.writeFile(workbook, `OT_Registration_${mode === 'today' ? todayStr : 'Range'}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRegistrations = useMemo(() => {
    return requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-14 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const dayOfWeek = dateObj.getDay();
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isActuallyWorking = dayConfigs[dateStr] ?? defaultIsWorking;

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-14 md:h-32 border border-gray-100 p-0.5 md:p-2 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30 z-10' : 'bg-white'} 
                  ${isPast ? 'opacity-40 grayscale-[0.2]' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-0.5 md:gap-1.5">
                        <span className={`text-[9px] md:text-base font-black ${isToday ? 'bg-blue-600 text-white w-3.5 h-3.5 md:w-6 md:h-6 rounded-md md:rounded-lg flex items-center justify-center shadow-lg' : !isActuallyWorking ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                    </div>
                </div>
                <div className="flex-1 flex flex-col justify-start gap-0.5 mt-0.5 overflow-hidden">
                    {myRequest && <div className="w-1.5 h-1.5 md:w-6 md:h-6 rounded-full md:rounded-lg bg-emerald-500 flex items-center justify-center shrink-0 shadow-sm"><UserIcon className="hidden md:block w-3 h-3 text-white" /></div>}
                    <div className="flex -space-x-1 md:-space-x-2 overflow-hidden">
                        {otherRequests.slice(0, 3).map((req, idx) => (
                            <div key={idx} className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-indigo-100 border border-white flex items-center justify-center shrink-0 shadow-sm">
                                <span className="hidden md:block text-[7px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                            </div>
                        ))}
                    </div>
                </div>
                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-0.5 right-0.5 bg-gray-100 text-gray-500 text-[5px] md:text-[8px] px-1 md:px-1.5 py-0.2 md:py-0.5 rounded md:rounded-lg font-black border border-gray-200">
                        {dayRequestsLocal.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-3 md:space-y-6 h-full flex flex-col animate-fade-in max-w-7xl mx-auto px-1 md:px-0 pb-20">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 md:p-6 rounded-[1.2rem] md:rounded-[2rem] shadow-sm border border-gray-100 transition-all">
            <div>
                <div className="flex items-center gap-2">
                    <h2 className="text-base md:text-2xl font-black text-gray-900 tracking-tight flex items-center gap-2">
                      Quản lý Tăng ca 
                      {isNoel && <Snowflake className="w-5 h-5 text-blue-300 animate-spin-slow" />}
                      {isTet && <Sparkles className="w-5 h-5 text-yellow-400" />}
                    </h2>
                    <span className="text-[7px] md:text-[10px] font-black bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded-full uppercase tracking-widest">MẪU PRO 2024</span>
                </div>
                <p className="text-[8px] md:text-sm text-gray-500 font-medium italic">Hệ thống ghi nhận công tác & Xuất biểu mẫu HR chuyên nghiệp</p>
            </div>
            <div className="flex bg-gray-100/80 p-0.5 rounded-xl md:rounded-2xl border border-gray-200 w-full md:w-auto">
                {['calendar', 'personal', 'stats'].map(t => (
                    <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 md:flex-none px-4 md:px-8 py-2 md:py-2.5 rounded-lg md:rounded-xl text-[9px] md:text-sm font-black transition-all ${activeTab === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>
                        {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                    </button>
                ))}
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-100 shadow-lg rounded-[1.2rem] md:rounded-[2.5rem] bg-white">
                    <div className="flex items-center justify-between p-3 md:p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-2 hover:bg-gray-100 rounded-xl transition-all"><ChevronLeft className="w-5 h-5"/></button>
                        <h3 className="text-sm md:text-lg font-black uppercase tracking-widest text-gray-800">Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-2 hover:bg-gray-100 rounded-xl transition-all"><ChevronRight className="w-5 h-5"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[7px] md:text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-2 md:py-4 text-center ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-100 gap-[0.5px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 md:space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        <Card className="bg-gradient-to-br from-indigo-600 to-blue-700 text-white border-none shadow-lg rounded-[1.2rem] p-4 md:p-6">
                            <h3 className="text-[8px] md:text-[10px] font-black uppercase tracking-widest opacity-80">Tổng giờ T{currentDate.getMonth()+1}</h3>
                            <div className="flex items-end gap-1"><span className="text-2xl md:text-5xl font-black">{myStats.total.toFixed(1)}</span><span className="text-[10px] md:text-lg font-bold opacity-70">h</span></div>
                        </Card>
                        <Card className="bg-white border-l-4 border-emerald-500 rounded-[1.2rem] p-4 shadow-sm flex items-center gap-3">
                            <div className="p-2.5 bg-emerald-50 rounded-xl text-emerald-600"><Check className="w-5 h-5"/></div>
                            <div><p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase">Đăng ký</p><p className="text-lg md:text-2xl font-black text-gray-900">{myStats.count} d</p></div>
                        </Card>
                         <Card className="bg-white border-l-4 border-amber-500 rounded-[1.2rem] p-4 shadow-sm flex items-center gap-3">
                            <div className="p-2.5 bg-amber-50 rounded-xl text-amber-600"><Timer className="w-5 h-5"/></div>
                            <div><p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase">Chờ duyệt</p><p className="text-lg md:text-2xl font-black text-gray-900">{myStats.pending}</p></div>
                        </Card>
                        <Card className="bg-white border-l-4 border-indigo-500 rounded-[1.2rem] p-4 shadow-sm flex items-center gap-3">
                            <div className="p-2.5 bg-indigo-50 rounded-xl text-indigo-600"><Activity className="w-5 h-5"/></div>
                            <div><p className="text-[8px] md:text-[10px] font-black text-gray-400 uppercase">Trung bình</p><p className="text-lg md:text-2xl font-black text-gray-900">{(myStats.total / (myStats.count || 1)).toFixed(1)}h</p></div>
                        </Card>
                    </div>

                    <Card className="rounded-[1.5rem] md:rounded-[2.5rem] p-5 md:p-8 shadow-md border-none bg-white">
                        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
                            <div>
                                <h3 className="text-lg font-black text-gray-900 uppercase tracking-tight">Biểu đồ xu hướng</h3>
                                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Lịch sử đăng ký OT của bạn</p>
                            </div>
                        </div>
                        <div className="h-48 md:h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{ top: 0, right: 0, left: -35, bottom: 0 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 8, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 8, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{fontSize: '10px', borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}} />
                                    <Bar dataKey="hours" fill="#4f46e5" radius={[2, 2, 0, 0]} barSize={8} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <Card className="bg-white border-none p-6 flex items-center gap-4 shadow-sm rounded-[1.5rem]">
                            <div className="p-4 bg-indigo-100 text-indigo-600 rounded-2xl"><Users className="w-6 h-6"/></div>
                            <div><p className="text-[10px] font-black text-gray-400 uppercase">Nhân sự OT</p><p className="text-3xl font-black text-gray-900">{teamMonthlyStats.activeMembers}</p></div>
                        </Card>
                        <Card className="bg-white border-none p-6 flex items-center gap-4 shadow-sm rounded-[1.5rem]">
                            <div className="p-4 bg-emerald-100 text-emerald-600 rounded-2xl"><Timer className="w-6 h-6"/></div>
                            <div><p className="text-[10px] font-black text-gray-400 uppercase">Tổng giờ tháng</p><p className="text-3xl font-black text-gray-900">{teamMonthlyStats.totalHours.toFixed(1)}h</p></div>
                        </Card>
                        <Card className="bg-indigo-600 text-white border-none p-6 flex items-center gap-4 shadow-lg rounded-[1.5rem]">
                            <div className="p-4 bg-white/20 rounded-2xl"><Target className="w-6 h-6"/></div>
                            <div><p className="text-[10px] font-black text-white/70 uppercase">Hôm nay</p><p className="text-3xl font-black">{todayRegistrations.length}</p></div>
                        </Card>
                    </div>

                    <Card className="rounded-[2rem] p-8 md:p-10 shadow-xl border-none bg-white">
                        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8 mb-10">
                            <div className="flex items-center gap-4">
                                <div className="p-4 bg-emerald-100 text-emerald-600 rounded-3xl"><FileSpreadsheet className="w-8 h-8"/></div>
                                <div>
                                    <h3 className="text-xl font-black text-gray-900 uppercase tracking-tighter">Xuất biểu mẫu nhân sự (HR)</h3>
                                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1 italic">Mẫu "Daily Overtime Voluntary" chuẩn quy định</p>
                                </div>
                            </div>
                            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                                <div className="flex items-center gap-3 px-4 py-2.5 bg-gray-50 border-2 border-gray-100 rounded-2xl w-full sm:w-auto">
                                  <input type="date" value={exportStartDate} onChange={(e) => setExportStartDate(e.target.value)} className="bg-transparent text-[11px] font-black outline-none focus:text-indigo-600 transition-all uppercase"/>
                                  <span className="text-gray-300 font-black">→</span>
                                  <input type="date" value={exportEndDate} onChange={(e) => setExportEndDate(e.target.value)} className="bg-transparent text-[11px] font-black outline-none focus:text-indigo-600 transition-all uppercase"/>
                                </div>
                                <div className="flex gap-2 w-full sm:w-auto">
                                    <button onClick={() => handleExportExcelPro('range')} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-8 py-4 bg-indigo-700 text-white rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest shadow-2xl shadow-indigo-100 active:scale-95 transition-all border-b-4 border-indigo-900"><FileDown className="w-4 h-4"/> Xuất khoảng ngày</button>
                                    <button onClick={() => handleExportExcelPro('today')} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-8 py-4 bg-emerald-600 text-white rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest shadow-2xl shadow-emerald-100 active:scale-95 transition-all border-b-4 border-emerald-800"><CalendarDays className="w-4 h-4"/> Hôm nay</button>
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                            <Card className="rounded-[1.5rem] p-0 flex flex-col overflow-hidden bg-gray-50/50 border-none">
                                <div className="p-6 bg-white border-b border-gray-100 flex justify-between items-center shadow-sm">
                                    <h4 className="text-xs font-black text-gray-900 uppercase tracking-widest flex items-center gap-2"><Clock className="w-4 h-4 text-indigo-600" /> Đăng ký hôm nay</h4>
                                    <span className="text-[10px] font-black bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full uppercase tabular-nums">{todayRegistrations.length}</span>
                                </div>
                                <div className="p-4 space-y-3 overflow-y-auto max-h-[300px] no-scrollbar">
                                    {todayRegistrations.length === 0 ? (
                                        <div className="h-40 flex flex-col items-center justify-center text-gray-300 italic text-[11px] gap-2">
                                            <Info className="w-5 h-5"/> Chưa có đăng ký nào
                                        </div>
                                    ) : (
                                        todayRegistrations.map((req, idx) => (
                                            <div key={idx} className="p-4 rounded-2xl bg-white border-2 border-transparent flex items-center gap-4 transition-all hover:border-indigo-100 hover:shadow-lg group">
                                                <div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-sm uppercase group-hover:rotate-6 transition-transform">{req.users?.name?.charAt(0)}</div>
                                                <div className="flex-1 min-w-0">
                                                    <h5 className="font-black text-gray-900 text-sm truncate uppercase tracking-tight italic">{req.users?.name}</h5>
                                                    <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">{req.users?.employee_id}</p>
                                                </div>
                                                <div className="text-right">
                                                    <div className="text-[10px] font-black text-indigo-600 mb-0.5">{req.start_time}-{req.end_time}</div>
                                                    <span className="text-sm font-black text-gray-900 tabular-nums">{req.total_hours.toFixed(1)}h</span>
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                            </Card>

                            <Card className="rounded-[1.5rem] p-0 flex flex-col bg-gray-50/50 overflow-hidden border-none">
                                 <div className="p-6 bg-indigo-700 text-white flex justify-between items-center shadow-lg">
                                     <h4 className="text-xs font-black uppercase tracking-widest flex items-center gap-2"><Award className="w-5 h-5 text-amber-400" /> Bảng vàng cống hiến</h4>
                                     <p className="text-[9px] font-bold opacity-60 uppercase">Tháng {currentDate.getMonth()+1}</p>
                                 </div>
                                 <div className="p-4 space-y-3 overflow-y-auto max-h-[300px] no-scrollbar">
                                    {topRankings.map((emp, idx) => (
                                        <div key={idx} className={`p-4 rounded-2xl border-2 flex items-center gap-4 transition-all ${idx === 0 ? 'bg-amber-50/50 border-amber-100' : 'bg-white border-transparent hover:border-indigo-100 hover:shadow-lg'}`}>
                                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs ${idx === 0 ? 'bg-amber-500 text-white' : idx === 1 ? 'bg-slate-300 text-white' : idx === 2 ? 'bg-orange-300 text-white' : 'bg-gray-100 text-gray-400'}`}>{idx + 1}</div>
                                            <div className="flex-1 min-w-0">
                                                <h5 className="font-black text-gray-900 text-sm truncate uppercase tracking-tight">{emp.name}</h5>
                                                <p className="text-[9px] font-bold text-gray-400 uppercase">{emp.count} ngày OT</p>
                                            </div>
                                            <div className="text-right">
                                                <span className="text-xl font-black text-indigo-600 tabular-nums">{emp.hours.toFixed(1)}</span>
                                                <span className="text-[10px] font-bold text-gray-400 ml-1 uppercase">h</span>
                                            </div>
                                        </div>
                                    ))}
                                 </div>
                            </Card>
                        </div>
                    </Card>
                </div>
            )}
        </div>

        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-md animate-fade-in px-0 md:px-4">
                <div className="bg-white rounded-t-[2.5rem] md:rounded-[3rem] shadow-2xl w-full max-w-lg animate-slide-up md:animate-zoom-in overflow-hidden max-h-[92vh] flex flex-col border border-white/10">
                    <div className="bg-indigo-600 p-5 md:p-8 flex justify-between items-center text-white shrink-0 shadow-xl">
                        <div className="flex flex-col">
                            <div className="flex items-center gap-2"><CalendarDays className="w-5 h-5 text-indigo-200" /><h3 className="text-xl font-black uppercase tracking-tighter italic">{selectedDateStr.split('-').reverse().join('/')}</h3></div>
                            <p className="text-[10px] text-indigo-200 font-bold uppercase tracking-widest mt-1">Ghi nhận tăng ca</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-white/20 rounded-2xl transition-all active:scale-90"><X className="w-6 h-6"/></button>
                    </div>

                    <div className="p-6 md:p-10 space-y-6 overflow-y-auto no-scrollbar pb-12 bg-gray-50/30 flex-1">
                        {isAdmin && (
                            <div className="bg-white p-5 rounded-3xl border border-indigo-50 shadow-sm space-y-4">
                                <div className="flex items-center gap-2 px-1">
                                    <Settings className="w-4 h-4 text-indigo-600" />
                                    <h4 className="text-[11px] font-black text-indigo-900 uppercase tracking-widest">Loại ngày hệ thống</h4>
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 transition-all font-black text-[10px] uppercase tracking-widest ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0 || new Date(selectedDateStr).getDay() === 6))) ? 'bg-rose-500 text-white border-rose-400 shadow-lg shadow-rose-100' : 'bg-white text-gray-400 border-gray-100 hover:border-rose-200' }`}>
                                        <Home className="w-4 h-4" /> Ngày nghỉ
                                    </button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 transition-all font-black text-[10px] uppercase tracking-widest ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0 && new Date(selectedDateStr).getDay() !== 6)) ? 'bg-indigo-600 text-white border-indigo-500 shadow-lg shadow-indigo-100' : 'bg-white text-gray-400 border-gray-100 hover:border-indigo-200' }`}>
                                        <Briefcase className="w-4 h-4" /> Đi làm
                                    </button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {isViewOnly ? (
                                <div className="bg-white border-2 border-indigo-50 p-8 rounded-[2.5rem] text-center space-y-4 shadow-lg">
                                    <Eye className="w-10 h-10 text-indigo-300 mx-auto" />
                                    <p className="text-xs font-black text-gray-400 uppercase tracking-widest italic leading-relaxed">Bạn đang xem đơn của đồng nghiệp.<br/>Hãy chọn đăng ký cho bạn nếu cần.</p>
                                    <button type="button" onClick={() => setTargetUserId(user.id)} className="w-full py-4 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-2xl tracking-[0.2em] shadow-xl shadow-indigo-100 active:scale-95 transition-all">Đăng ký mới cho tôi</button>
                                </div>
                            ) : (
                                <>
                                    {isAdmin && (
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nhân sự thực hiện:</label>
                                            <div className="relative">
                                                <select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-[11px] md:text-sm font-black outline-none focus:border-indigo-500 shadow-sm appearance-none cursor-pointer uppercase">
                                                    {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name}</option>))}
                                                </select>
                                                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
                                            </div>
                                        </div>
                                    )}
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Bắt đầu:</label>
                                            <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-base md:text-lg font-black text-gray-900 outline-none focus:border-indigo-500 shadow-sm"/>
                                        </div>
                                        <div className="space-y-2">
                                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Kết thúc:</label>
                                            {/* Fix: use setEndTime instead of non-existent setToolId */}
                                            <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-base md:text-lg font-black text-gray-900 outline-none focus:border-indigo-500 shadow-sm"/>
                                        </div>
                                    </div>
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center px-1">
                                            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nội dung công việc</label>
                                            <span className="text-xs font-black text-indigo-600 bg-white px-4 py-1 rounded-full border border-indigo-50 shadow-sm tabular-nums">{calculatedHours.toFixed(1)}h OT</span>
                                        </div>
                                        <textarea value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-5 bg-white border border-gray-100 rounded-[2rem] text-[11px] md:text-sm h-32 md:h-40 resize-none outline-none font-bold text-gray-800 shadow-inner focus:border-indigo-500 transition-all" placeholder="Ghi chú chi tiết công việc OT..."/>
                                    </div>
                                    <div className="flex gap-3 pt-4">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-5 bg-rose-50 text-rose-600 rounded-[2rem] border border-rose-100 hover:bg-rose-600 hover:text-white active:scale-90 transition-all shadow-sm"><Trash2 className="w-6 h-6"/></button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-[2.5rem] shadow-2xl shadow-indigo-200 text-[11px] md:text-xs tracking-[0.2em] uppercase transition-all active:scale-95 disabled:opacity-50 border-4 border-white/20">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'Cập nhật đăng ký' : 'Xác nhận đăng ký'}
                                        </button>
                                    </div>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/90 z-[120] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-sm overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-20 h-20 bg-rose-100 text-rose-600 flex items-center justify-center mx-auto mb-6 rounded-3xl shadow-xl shadow-rose-100 rotate-12"><Trash2 className="w-10 h-10"/></div>
                    <h3 className="text-xl font-black text-gray-900 mb-2 uppercase tracking-tighter">Hủy đăng ký?</h3>
                    <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest opacity-80 leading-relaxed mb-8 px-4">Dữ liệu sẽ bị xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-2xl shadow-rose-200 transition-all active:scale-95">XÁC NHẬN XÓA</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-2xl border-2 border-gray-100 text-[10px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon, Snowflake, Sparkles, Gift,
  ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, CalendarDays, Filter
} from 'lucide-react';

interface RequestManagerProps { user: User; }

const ITEMS_PER_PAGE = 10;
const todayStr = new Date().toISOString().split('T')[0];

const ToolTableImage = ({ toolId, toolName }: { toolId: string, toolName: string }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  return (
    <div className="w-12 h-12 bg-white border border-gray-100 rounded-xl overflow-hidden flex items-center justify-center p-1 shadow-sm transition-transform group-hover:scale-110 duration-300">
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-5 h-5 text-gray-300" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterDate, setFilterDate] = useState(todayStr); // Mặc định là ngày hôm nay
  const [currentPage, setCurrentPage] = useState(1);

  const month = new Date().getMonth();
  const isNoel = month === 11;
  const isTet = month === 0 || month === 1;

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      if (!silent) setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      returned: 2,
      rejected: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      // Lọc theo ngày (chỉ lấy phần YYYY-MM-DD từ borrow_date)
      const matchesDate = !filterDate || req.borrow_date.startsWith(filterDate);

      return matchesSearch && matchesStatus && matchesDate;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterDate]);

  // Logic phân trang
  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / ITEMS_PER_PAGE));
  const paginatedRequests = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredRequests.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredRequests, currentPage]);

  useEffect(() => {
    setCurrentPage(1); // Reset trang khi đổi bộ lọc
  }, [searchTerm, filterStatus, filterDate, activeTab]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    const oldRequests = [...requests];

    let newStatus: BorrowRequest['status'] = 'pending';
    if (action === 'approve') newStatus = 'approved';
    else if (action === 'reject') newStatus = 'rejected';
    else if (action === 'return') newStatus = 'returned';

    if (action === 'cancel') {
      setRequests(prev => prev.filter(r => r.id !== id));
    } else {
      setRequests(prev => prev.map(r => r.id === id ? { ...r, status: newStatus, returned_at: action === 'return' ? new Date().toISOString() : r.returned_at } : r));
    }

    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) {
           setRequests(oldRequests);
           throw new Error("Hết hàng trong kho");
        }
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
    } catch (e: any) {
      alert(e.message);
      setRequests(oldRequests);
    } finally {
      setProcessingId(null);
      fetchRequests(true);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-500 text-white', icon: <Timer className="w-4 h-4 animate-pulse" />, label: 'CHỜ DUYỆT' },
      approved: { color: 'bg-emerald-600 text-white', icon: <PackageCheck className="w-4 h-4" />, label: 'ĐANG MƯỢN' },
      returned: { color: 'bg-blue-500 text-white', icon: <RotateCcw className="w-4 h-4" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-red-500 text-white', icon: <XCircle className="w-4 h-4" />, label: 'TỪ CHỐI' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black shadow-sm transition-all duration-300 group-hover:scale-105 ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in max-w-7xl mx-auto pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white p-6 md:p-8 rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className={`p-3 md:p-4 rounded-2xl shadow-xl text-white transform hover:rotate-3 transition-transform ${isNoel ? 'bg-red-600' : (isTet ? 'bg-red-700' : 'bg-blue-600')}`}>
            <RefreshCw className="w-6 h-6 md:w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight uppercase flex items-center gap-2 italic">
               Duyệt mượn thiết bị
               {isNoel && <Snowflake className="w-5 h-5 text-blue-300 animate-spin-slow" />}
               {isTet && <Sparkles className="w-5 h-5 text-yellow-400" />}
            </h2>
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1 opacity-70">
              {filterDate === todayStr ? 'Đang hiển thị đơn hôm nay 📅' : `Đang hiển thị đơn ngày ${filterDate.split('-').reverse().join('/')}`}
            </p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-2xl border border-gray-200 shadow-inner">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? (isNoel || isTet ? 'bg-red-600 text-white' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500 hover:text-gray-700'}`}>Toàn bộ</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? (isNoel || isTet ? 'bg-red-600 text-white' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500 hover:text-gray-700'}`}>Của tôi</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
        <div className="md:col-span-5 relative group">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600 transition-colors" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm mã NV, tên, thiết bị..." 
            className="w-full pl-12 pr-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-red-500/5 focus:border-red-500 transition-all shadow-sm" 
          />
        </div>

        <div className="md:col-span-4 flex items-center gap-2 bg-white p-2 border border-gray-100 rounded-2xl shadow-sm">
           <CalendarDays className="w-5 h-5 text-gray-400 ml-2" />
           <input 
            type="date" 
            value={filterDate} 
            onChange={e => setFilterDate(e.target.value)}
            className="flex-1 bg-transparent border-none text-[11px] font-black uppercase outline-none focus:text-red-600 cursor-pointer"
           />
           {filterDate !== todayStr && (
             <button onClick={() => setFilterDate(todayStr)} className="px-3 py-1 bg-gray-100 text-[8px] font-black rounded-lg hover:bg-gray-200 transition-colors">HÔM NAY</button>
           )}
        </div>

        <div className="md:col-span-3">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className="w-full px-6 py-4 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-sm focus:border-red-500 transition-all"
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ duyệt</option>
            <option value="approved">📦 Đang mượn</option>
            <option value="returned">✅ Đã trả đồ</option>
            <option value="rejected">❌ Từ chối</option>
          </select>
        </div>
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[2.5rem] bg-white animate-zoom-in min-h-[400px]">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-separate border-spacing-0">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Người mượn</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Thiết bị</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Thời gian</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">Trạng thái</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50/50">
              {loading ? (
                <tr><td colSpan={5} className="py-32 text-center"><Loader2 className="w-10 h-10 animate-spin text-red-600 mx-auto opacity-20" /></td></tr>
              ) : paginatedRequests.length === 0 ? (
                <tr><td colSpan={5} className="py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                paginatedRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className="group relative transition-all duration-500 ease-out hover:bg-blue-50/50 hover:shadow-[0_8px_30px_rgb(0,0,0,0.04)] hover:translate-x-1 border-l-4 border-l-transparent hover:border-l-blue-600 cursor-default"
                  >
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className={`w-11 h-11 text-white rounded-2xl flex items-center justify-center font-black text-sm shadow-lg group-hover:scale-110 transition-transform ${isNoel ? 'bg-red-700' : (isTet ? 'bg-red-800' : 'bg-indigo-600')}`}>
                          {req.user_name.charAt(0)}
                        </div>
                        <div>
                          <div className="font-black text-gray-900 text-sm group-hover:text-blue-700 transition-colors uppercase italic">{req.user_name}</div>
                          <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-0.5">{req.employee_id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                        <div className="font-black text-gray-800 text-sm uppercase tracking-tighter line-clamp-1 group-hover:text-blue-600 transition-colors">{req.tool_name}</div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-2 text-gray-700 font-black text-[10px] uppercase tracking-widest">
                          <Calendar className="w-3.5 h-3.5 text-blue-500" />
                          {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                        </div>
                        {req.returned_at && (
                          <div className="text-[8px] font-black text-emerald-600 italic">Trả lúc: {new Date(req.returned_at).toLocaleTimeString('vi-VN')}</div>
                        )}
                      </div>
                    </td>
                    <td className="px-10 py-6 text-center">
                      {getStatusBadge(req.status)}
                    </td>
                    <td className="px-10 py-6 text-right">
                      {processingId === req.id ? (
                        <Loader2 className="w-6 h-6 animate-spin ml-auto text-red-600" />
                      ) : (
                        <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 hover:bg-emerald-700 active:scale-90 transition-all border-b-4 border-emerald-800">DUYỆT</button>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-2.5 bg-rose-50 text-rose-600 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm active:scale-90 border-b-4 border-rose-200" title="Từ chối"><X className="w-4 h-4" /></button>
                            </>
                          )}
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="flex items-center gap-2 px-6 py-3 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] shadow-xl shadow-red-200 hover:bg-red-700 active:scale-95 transition-all border-b-4 border-red-900">
                              <RotateCcw className="w-4 h-4" /> THU HỒI
                            </button>
                          )}
                          {req.user_id === user.id && req.status === 'pending' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="p-2.5 text-gray-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all active:scale-90"><Trash2 className="w-4 h-4" /></button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Phân trang Footer */}
        {filteredRequests.length > 0 && (
          <div className="bg-gray-50/50 border-t border-gray-100 p-8 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="text-[10px] text-gray-400 font-black uppercase tracking-[0.15em]">
              Hiển thị <span className="text-gray-900 tabular-nums">{(currentPage-1)*ITEMS_PER_PAGE + 1}-{Math.min(filteredRequests.length, currentPage*ITEMS_PER_PAGE)}</span> trong {filteredRequests.length} yêu cầu
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronsLeft className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>

              <div className="flex items-center gap-1.5 px-2">
                 {Array.from({length: totalPages}, (_, i) => i + 1).filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1).map((p, idx, arr) => (
                    <React.Fragment key={p}>
                        {idx > 0 && arr[idx-1] !== p - 1 && <span className="text-gray-300 font-black">...</span>}
                        <button 
                            onClick={() => setCurrentPage(p)}
                            className={`w-9 h-9 rounded-xl font-black text-[10px] transition-all border-2 tabular-nums ${currentPage === p ? 'bg-red-600 text-white border-red-600 shadow-lg scale-110' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'}`}
                        >
                            {p}
                        </button>
                    </React.Fragment>
                 ))}
              </div>

              <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronsRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </Card>

      <div className="flex justify-center gap-8 py-4 opacity-20">
         {isNoel && Array.from({length: 3}).map((_, i) => <Snowflake key={i} className="w-8 h-8 text-blue-400" />)}
         {isTet && Array.from({length: 3}).map((_, i) => <Gift key={i} className="w-8 h-8 text-yellow-500" />)}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const month = new Date().getMonth();
  const isNoel = month === 11;
  const isTet = month === 0 || month === 1;

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const getOTCategory = (dateStr: string) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    const isWorking = dayConfigs[dateStr] ?? (day !== 0 && day !== 6);
    return !isWorking ? '200%' : '150%';
  };

  const handleExportExcelPro = (mode: 'today' | 'range') => {
    let filtered = [];
    const department = "Automation";

    if (mode === 'today') {
        filtered = requests.filter(r => r.date === todayStr);
    } else {
        filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    }

    if (filtered.length === 0) return alert("Không tìm thấy dữ liệu đăng ký.");

    // Group by date to separate sheets
    const groupedByDate = filtered.reduce((acc, req) => {
        if (!acc[req.date]) acc[req.date] = [];
        acc[req.date].push(req);
        return acc;
    }, {} as Record<string, OvertimeRequest[]>);

    const workbook = XLSX.utils.book_new();
    const sortedDates = Object.keys(groupedByDate).sort();

    sortedDates.forEach((dateKey) => {
        const dayRequests = groupedByDate[dateKey];
        dayRequests.sort((a, b) => (a.users?.name || "").localeCompare(b.users?.name || ""));

        const displayDate = dateKey.split('-').reverse().join('/');
        const sheetName = dateKey.split('-').reverse().join('-'); // Excel sheet names can't have '/'

        const ws_data = [
            ["ĐĂNG KÝ LÀM THÊM TỰ NGUYỆN HÀNG NGÀY / APPLICATION FOR DAILY OVERTIME VOLUNTARY"],
            [],
            [`Bộ phận/Department: ${department}`, ``, ``, ``, ``, ``, ``, `Ngày/Date: ${displayDate}`],
            [`Tổng số người làm thêm/Total members OT: ${dayRequests.length}`, ``, ``, ``, ``, ``, ``, `Tổng số vé ăn chính/Total main ticket: `],
            [`Tổng số vé ăn phụ/Total sub-meal ticket: `],
            [],
            [
                "STT/No.", 
                "ID đầy đủ", 
                "Họ tên/ Full name", 
                "Bắt đầu (Giờ)", 
                "Kết thúc (Giờ)", 
                "OT 150%", 
                "OT 200%", 
                "OT 270%", 
                "OT 210%", 
                "OT 390%", 
                "Lý do Làm thêm/ Reason", 
                "Chữ ký người làm thêm", 
                "Ghi chú/Note"
            ]
        ];

        dayRequests.forEach((req, index) => {
            const otCat = getOTCategory(req.date);
            const row = [
                index + 1,
                req.users?.employee_id || "N/A",
                req.users?.name || "N/A",
                req.start_time,
                req.end_time,
                otCat === '150%' ? req.total_hours : "", 
                otCat === '200%' ? req.total_hours : "", 
                "", "", "", 
                req.reason || "",
                "", 
                req.date
            ];
            ws_data.push(row);
        });

        ws_data.push([]);
        ws_data.push(["Note/Ghi chú:"]);
        ws_data.push(["- Trước khi cnv làm thêm, bộ phận phải hoàn thành phiếu này (với đầy đủ chữ ký) và nộp lại cho HR lúc 15h cùng ngày."]);
        ws_data.push(["- Biểu đơn này sử dụng chung cho cả đăng ký làm thêm và xin cấp vé ăn."]);
        ws_data.push(["Before employees do OT, section must submit this form (fully signed) to HR 15 hours at the same working day."]);
        ws_data.push([]);
        ws_data.push([
            "Quản lý người việt (VN Manager)", "",
            "Quản lý người việt (VN Manager)", "",
            "Quản lý Người Hàn (Korea Manager)", "",
            "Quản lý Người Hàn Nhân Sự (HR Manager)"
        ]);
        ws_data.push(["", "", "", "", "", "", "", ""]);
        ws_data.push(["Date:", "", "Date:", "", "Date:", "", "Date:", ""]);

        const worksheet = XLSX.utils.aoa_to_sheet(ws_data);
        worksheet['!merges'] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: 12 } }];
        XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
    });

    XLSX.writeFile(workbook, `OT_Registration_${mode === 'today' ? todayStr : 'Range'}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");
    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason, 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRegistrations = useMemo(() => {
    return requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-14 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const dayOfWeek = dateObj.getDay();
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isActuallyWorking = dayConfigs[dateStr] ?? defaultIsWorking;

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-14 md:h-32 border border-gray-100 p-0.5 md:p-2 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30 z-10' : 'bg-white'} 
                  ${isPast ? 'opacity-40 grayscale-[0.2]' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-0.5 md:gap-1.5">
                        <span className={`text-[9px] md:text-base font-black ${isToday ? 'bg-blue-600 text-white w-3.5 h-3.5 md:w-6 md:h-6 rounded-md md:rounded-lg flex items-center justify-center shadow-lg' : !isActuallyWorking ? 'text-rose-500' : 'text-gray-700'}`}>
                            {d}
                        </span>
                    </div>
                </div>
                <div className="flex-1 flex flex-col justify-start gap-0.5 mt-0.5 overflow-hidden">
                    {myRequest && <div className="w-1.5 h-1.5 md:w-6 md:h-6 rounded-full md:rounded-lg bg-emerald-500 flex items-center justify-center shrink-0 shadow-sm"><UserIcon className="hidden md:block w-3 h-3 text-white" /></div>}
                    <div className="flex -space-x-1 md:-space-x-2 overflow-hidden">
                        {otherRequests.slice(0, 3).map((req, idx) => (
                            <div key={idx} className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-full bg-indigo-100 border border-white flex items-center justify-center shrink-0 shadow-sm">
                                <span className="hidden md:block text-[7px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                            </div>
                        ))}
                    </div>
                </div>
                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-0.5 right-0.5 bg-gray-100 text-gray-500 text-[5px] md:text-[8px] px-1 md:px-1.5 py-0.2 md:py-0.5 rounded md:rounded-lg font-black border border-gray-200">
