    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      if (!silent) setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      rejected: 2,
      returned: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      const matchesDate = !filterDate || req.borrow_date.startsWith(filterDate);

      return matchesSearch && matchesStatus && matchesDate;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterDate]);

  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / ITEMS_PER_PAGE));
  const paginatedRequests = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredRequests.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredRequests, currentPage]);

  useEffect(() => {
    setCurrentPage(1); 
  }, [searchTerm, filterStatus, filterDate, activeTab]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    const oldRequests = [...requests];

    let newStatus: BorrowRequest['status'] = 'pending';
    if (action === 'approve') newStatus = 'approved';
    else if (action === 'reject') newStatus = 'rejected';
    else if (action === 'return') newStatus = 'returned';

    if (action === 'cancel') {
      setRequests(prev => prev.filter(r => r.id !== id));
    } else {
      setRequests(prev => prev.map(r => r.id === id ? { ...r, status: newStatus, returned_at: action === 'return' ? new Date().toISOString() : r.returned_at } : r));
    }

    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) {
           setRequests(oldRequests);
           throw new Error("Hết hàng trong kho");
        }
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
    } catch (e: any) {
      alert(e.message);
      setRequests(oldRequests);
    } finally {
      setProcessingId(null);
      fetchRequests(true);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { 
        color: 'bg-amber-100 text-amber-700 border-amber-200 shadow-amber-100/50', 
        icon: <Timer className="w-3.5 h-3.5 animate-pulse" />, 
        label: 'CHỜ DUYỆT' 
      },
      approved: { 
        color: 'bg-emerald-100 text-emerald-700 border-emerald-200 shadow-emerald-100/50', 
        icon: <PackageCheck className="w-3.5 h-3.5" />, 
        label: 'ĐANG MƯỢN' 
      },
      returned: { 
        color: 'bg-indigo-100 text-indigo-700 border-indigo-200 shadow-indigo-100/50', 
        icon: <RotateCcw className="w-3.5 h-3.5" />, 
        label: 'ĐÃ TRẢ ĐỒ' 
      },
      rejected: { 
        color: 'bg-rose-100 text-rose-700 border-rose-200 shadow-rose-100/50', 
        icon: <AlertCircle className="w-3.5 h-3.5" />, 
        label: 'TỪ CHỐI' 
      }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black border shadow-lg transition-all duration-300 group-hover:scale-105 ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in max-w-7xl mx-auto pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 bg-white p-6 md:p-8 rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className={`p-3 md:p-4 rounded-2xl shadow-xl text-white transform hover:rotate-3 transition-transform ${isNoel ? 'bg-red-600' : (isTet ? 'bg-red-700' : 'bg-blue-600')}`}>
            <RefreshCw className="w-6 h-6 md:w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight uppercase flex items-center gap-2 italic">
               Duyệt mượn thiết bị
               {isNoel && <Snowflake className="w-5 h-5 text-blue-300 animate-spin-slow" />}
               {isTet && <Sparkles className="w-5 h-5 text-yellow-400" />}
            </h2>
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1 opacity-70">
              {filterDate === todayStr ? 'Đang hiển thị đơn hôm nay 📅' : `Đang hiển thị đơn ngày ${filterDate.split('-').reverse().join('/')}`}
            </p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-2xl border border-gray-200 shadow-inner">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? (isNoel || isTet ? 'bg-red-600 text-white' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500 hover:text-gray-700'}`}>Toàn bộ</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? (isNoel || isTet ? 'bg-red-600 text-white' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500 hover:text-gray-700'}`}>Của tôi</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
        <div className="md:col-span-5 relative group">
          <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600 transition-colors" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm mã NV, tên, thiết bị..." 
            className={`w-full pl-12 pr-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 transition-all shadow-sm ${isTet ? 'focus:ring-red-500/5 focus:border-red-500' : 'focus:ring-blue-500/5 focus:border-blue-500'}`} 
          />
        </div>

        <div className="md:col-span-4 flex items-center gap-2 bg-white p-2 border border-gray-100 rounded-2xl shadow-sm">
           <CalendarDays className="w-5 h-5 text-gray-400 ml-2" />
           <input 
            type="date" 
            value={filterDate} 
            onChange={e => setFilterDate(e.target.value)}
            className={`flex-1 bg-transparent border-none text-[11px] font-black uppercase outline-none cursor-pointer ${isTet ? 'focus:text-red-600' : 'focus:text-blue-600'}`}
           />
           {filterDate !== todayStr && (
             <button onClick={() => setFilterDate(todayStr)} className="px-3 py-1 bg-gray-100 text-[8px] font-black rounded-lg hover:bg-gray-200 transition-colors">HÔM NAY</button>
           )}
        </div>

        <div className="md:col-span-3">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className={`w-full px-6 py-4 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-sm transition-all ${isTet ? 'focus:border-red-500' : 'focus:border-blue-500'}`}
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ duyệt</option>
            <option value="approved">📦 Đang mượn</option>
            <option value="returned">✅ Đã trả đồ</option>
            <option value="rejected">❌ Từ chối</option>
          </select>
        </div>
      </div>

      <Card className="p-0 overflow-hidden border-none shadow-2xl rounded-[2.5rem] bg-white animate-zoom-in min-h-[400px]">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left border-separate border-spacing-0">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Người mượn</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Thiết bị</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Thời gian</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-center">Trạng thái</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50/50">
              {loading ? (
                <tr><td colSpan={5} className="py-32 text-center"><Loader2 className="w-10 h-10 animate-spin text-red-600 mx-auto opacity-20" /></td></tr>
              ) : paginatedRequests.length === 0 ? (
                <tr><td colSpan={5} className="py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                paginatedRequests.map((req) => (
                  <tr 
                    key={req.id} 
                    className={`group relative transition-all duration-500 ease-out hover:bg-blue-50/50 hover:shadow-[0_8px_30px_rgb(0,0,0,0.04)] hover:translate-x-1 border-l-4 border-l-transparent cursor-default ${isTet ? 'hover:border-l-red-600' : 'hover:border-l-blue-600'}`}
                  >
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className={`w-11 h-11 text-white rounded-2xl flex items-center justify-center font-black text-sm shadow-lg group-hover:scale-110 transition-transform ${isTet ? 'bg-red-800' : (isNoel ? 'bg-red-700' : 'bg-indigo-600')}`}>
                          {req.user_name.charAt(0)}
                        </div>
                        <div>
                          <div className={`font-black text-sm transition-colors uppercase italic ${isTet ? 'group-hover:text-red-700' : 'group-hover:text-blue-700'}`}>{req.user_name}</div>
                          <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-0.5">{req.employee_id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                        <div className={`font-black text-sm uppercase tracking-tighter line-clamp-1 transition-colors ${isTet ? 'group-hover:text-red-600' : 'group-hover:text-blue-600'}`}>{req.tool_name}</div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-2 text-gray-700 font-black text-[10px] uppercase tracking-widest">
                          <Calendar className={`w-3.5 h-3.5 ${isTet ? 'text-red-500' : 'text-blue-500'}`} />
                          {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                        </div>
                        {req.returned_at && (
                          <div className="text-[8px] font-black text-emerald-600 italic">Trả lúc: {new Date(req.returned_at).toLocaleTimeString('vi-VN')}</div>
                        )}
                      </div>
                    </td>
                    <td className="px-10 py-6 text-center">
                      {getStatusBadge(req.status)}
                    </td>
                    <td className="px-10 py-6 text-right">
                      {processingId === req.id ? (
                        <Loader2 className="w-6 h-6 animate-spin ml-auto text-red-600" />
                      ) : (
                        <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 hover:bg-emerald-700 active:scale-90 transition-all border-b-4 border-emerald-800">DUYỆT</button>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-2.5 bg-rose-50 text-rose-600 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm active:scale-90 border-b-4 border-rose-200" title="Từ chối"><X className="w-4 h-4" /></button>
                            </>
                          )}
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="flex items-center gap-2 px-6 py-3 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] shadow-xl shadow-red-200 hover:bg-red-700 active:scale-95 transition-all border-b-4 border-red-900">
                              <RotateCcw className="w-4 h-4" /> THU HỒI
                            </button>
                          )}
                          {req.user_id === user.id && req.status === 'pending' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="p-2.5 text-gray-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all active:scale-90"><Trash2 className="w-4 h-4" /></button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {filteredRequests.length > 0 && (
          <div className="bg-gray-50/50 border-t border-gray-100 p-8 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="text-[10px] text-gray-400 font-black uppercase tracking-[0.15em]">
              Hiển thị <span className="text-gray-900 tabular-nums">{(currentPage-1)*ITEMS_PER_PAGE + 1}-{Math.min(filteredRequests.length, currentPage*ITEMS_PER_PAGE)}</span> trong {filteredRequests.length} yêu cầu
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronsLeft className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>

              <div className="flex items-center gap-1.5 px-2">
                 {Array.from({length: totalPages}, (_, i) => i + 1).filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1).map((p, idx, arr) => (
                    <React.Fragment key={p}>
                        {idx > 0 && arr[idx-1] !== p - 1 && <span className="text-gray-300 font-black">...</span>}
                        <button 
                            onClick={() => setCurrentPage(p)}
                            className={`w-9 h-9 rounded-xl font-black text-[10px] transition-all border-2 tabular-nums ${currentPage === p ? (isTet || isNoel ? 'bg-red-600 text-white border-red-600' : 'bg-blue-600 text-white border-blue-600') : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'} shadow-lg scale-110`}
                        >
                            {p}
                        </button>
                    </React.Fragment>
                 ))}
              </div>

              <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-xl border border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all shadow-sm active:scale-90"
              >
                <ChevronsRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </Card>

      <div className="flex justify-center gap-8 py-4 opacity-20">
         {isNoel && Array.from({length: 3}).map((_, i) => <Snowflake key={i} className="w-8 h-8 text-blue-400" />)}
         {isTet && Array.from({length: 3}).map((_, i) => <Gift key={i} className="w-8 h-8 text-yellow-500" />)}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useContext } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLoader2, UserCircle, ShieldCheck, Lock, AlertCircle, Snowflake, Sparkles, TreePine, Gift } from 'lucide-react';
import { ThemeContext } from '../../../App';

interface LoginFormProps {
  onLoginSuccess: (user: any) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onLoginSuccess }) => {
  const { theme } = useContext(ThemeContext);
  const [employeeCode, setEmployeeCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  const festiveConfig = useMemo(() => {
    if (isNoel) return {
      bg: 'bg-red-50',
      accent: 'bg-red-600',
      shadow: 'shadow-red-200',
      button: 'bg-red-600 hover:bg-red-700 shadow-red-100',
      border: 'border-red-100',
      icon: <TreePine className="text-white w-8 h-8" />,
      tag: "Christmas Season ❄️"
    };
    if (isTet) return {
      bg: 'bg-orange-50',
      accent: 'bg-red-700',
      shadow: 'shadow-red-200',
      button: 'bg-red-700 hover:bg-red-800 shadow-red-100',
      border: 'border-orange-100',
      icon: <Sparkles className="text-white w-8 h-8" />,
      tag: "Lunar New Year 🧧"
    };
    return {
      bg: 'bg-gray-50',
      accent: 'bg-blue-600',
      shadow: 'shadow-blue-200',
      button: 'bg-blue-600 hover:bg-blue-700 shadow-blue-100',
      border: 'border-gray-100',
      icon: <ShieldCheck className="text-white w-8 h-8" />,
      tag: "Hệ thống quản lý công cụ & nhân sự"
    };
  }, [isNoel, isTet]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        employeeCode,
        password,
      });

      if (error) {
        setError(error.message);
      } else if (data?.user) {
        localStorage.setItem('sb-session', JSON.stringify(data.session));
        onLoginSuccess(data.user);
      }
    } catch (err) {
      setError('Lỗi kết nối server.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen ${festiveConfig.bg} flex items-center justify-center p-4 transition-colors duration-500 overflow-hidden relative`}>
      {/* Decorative Floating Icons */}
      {isNoel && <div className="absolute top-10 left-10 text-red-100"><Snowflake size={120} /></div>}
      {isTet && <div className="absolute top-10 left-10 text-orange-100"><Gift size={120} /></div>}

      <div className="max-w-md w-full bg-white rounded-[3rem] shadow-2xl border border-white/50 overflow-hidden relative z-10 animate-zoom-in">
        <div className="p-10 text-center">
          <div className={`mx-auto ${festiveConfig.accent} w-20 h-20 rounded-[2rem] flex items-center justify-center mb-6 shadow-2xl ${festiveConfig.shadow} rotate-6 hover:rotate-0 transition-transform`}>
            {festiveConfig.icon}
          </div>
          <h2 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic">Manager Tool</h2>
          <p className={`text-[10px] font-black uppercase tracking-[0.2em] mt-2 ${isNoel || isTet ? 'text-red-500' : 'text-gray-400'}`}>
            {festiveConfig.tag}
          </p>
        </div>

        <div className="px-10 pb-12">
          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mã nhân viên</label>
              <div className="relative group">
                <UserCircle className={`absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 w-5 h-5 transition-colors ${isTet ? 'group-focus-within:text-red-500' : 'group-focus-within:text-blue-500'}`} />
                <input
                  type="text"
                  value={employeeCode}
                  onChange={(e) => setEmployeeCode(e.target.value.toUpperCase())}
                  className={`w-full pl-14 pr-6 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold focus:bg-white focus:ring-4 outline-none transition-all shadow-inner ${isTet ? 'focus:border-red-500/20 focus:ring-red-500/5' : 'focus:border-blue-500/20 focus:ring-blue-500/5'}`}
                  placeholder="VD: VT008010"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mật khẩu bảo mật</label>
              <div className="relative group">
                <Lock className={`absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 w-5 h-5 transition-colors ${isTet ? 'group-focus-within:text-red-500' : 'group-focus-within:text-blue-500'}`} />
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className={`w-full pl-14 pr-6 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-sm font-bold focus:bg-white focus:ring-4 outline-none transition-all shadow-inner ${isTet ? 'focus:border-red-500/20 focus:ring-red-500/5' : 'focus:border-blue-500/20 focus:ring-blue-500/5'}`}
                  placeholder="••••••••"
                  required
                />
              </div>
            </div>

            {error && (
              <div className="p-4 bg-red-50 text-red-600 text-[10px] font-black uppercase tracking-widest rounded-2xl border border-red-100 flex items-center gap-3 animate-shake">
                <AlertCircle className="w-5 h-5 flex-shrink-0" />
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className={`w-full ${festiveConfig.button} text-white font-black py-5 rounded-[2rem] shadow-2xl transition-all active:scale-[0.95] disabled:opacity-50 flex items-center justify-center gap-3 uppercase text-xs tracking-[0.2em] border-b-4 border-black/20`}
            >
              {loading ? <LucideLoader2 className="w-5 h-5 animate-spin" /> : 'Xác nhận truy cập'}
            </button>
          </form>
          <p className="text-center text-[9px] text-gray-300 font-bold uppercase tracking-widest mt-8">Manager Tool Team v1.0 • 2024</p>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState, useMemo, useContext } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, Send, Loader2, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, Trash2, Check, Boxes, Info, Tag, Hash, Archive, Snowflake, Sparkles, Gift
} from 'lucide-react';
import { ThemeContext } from '../../../App';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: '',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const { theme } = useContext(ThemeContext);
  const isTet = theme === 'tet';
  const isNoel = theme === 'noel';

  // Kiểm tra URL hợp lệ
  const isValidUrl = useMemo(() => {
    if (!src || typeof src !== 'string' || src.trim().length === 0) return false;
    return src.startsWith('http') || src.startsWith('data:');
  }, [src]);

  // Nếu lỗi hoặc URL không hợp lệ, hiển thị placeholder chuyên nghiệp
  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full rounded-xl border-2 border-dashed border-gray-200 transition-colors group-hover:bg-gray-100`}>
        <div className={`p-2 bg-white rounded-full shadow-sm border border-gray-100 flex items-center justify-center`}>
          <Wrench className={`${mode === 'grid' ? 'w-8 h-8' : 'w-5 h-5'} ${isTet ? 'text-red-400' : isNoel ? 'text-blue-400' : 'text-gray-400'}`} />
        </div>
        {mode === 'grid' && (
          <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">No Image</span>
        )}
      </div>
    );
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-white rounded-xl overflow-hidden">
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
      {/* Overlay hiệu ứng khi hover ở grid */}
      {mode === 'grid' && (
        <div className="absolute inset-0 bg-blue-600/0 group-hover:bg-blue-600/5 transition-colors pointer-events-none" />
      )}
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedQuantities, setSelectedQuantities] = useState<Record<string, number>>({});
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  const isTet = theme === 'tet';
  const isNoel = theme === 'noel';

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const uniqueCategories = useMemo(() => Array.from(new Set(tools.map(t => t.category).filter(Boolean))), [tools]);

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (tool: Tool) => {
    if (isManageMode) return;
    const isAvailable = tool.status === 'active' && tool.available > 0;
    if (!isAvailable && !selectedQuantities[tool.id]) return;

    setSelectedQuantities(prev => {
        const current = prev[tool.id] || 0;
        if (current > 0) {
            const next = { ...prev };
            delete next[tool.id];
            return next;
        } else {
            return { ...prev, [tool.id]: 1 };
        }
    });
  };

  const updateQuantity = (id: string, delta: number, max: number, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedQuantities(prev => {
        const current = prev[id] || 0;
        const next = Math.max(0, Math.min(max, current + delta));
        const newQuantities = { ...prev };
        if (next === 0) delete newQuantities[id];
        else newQuantities[id] = next;
        return newQuantities;
    });
  };

  const handleBulkBorrow = async () => {
    const selectedToolIds = Object.keys(selectedQuantities);
    if (selectedToolIds.length === 0) return;
    setIsBorrowing(true);
    try {
      for (const toolId of selectedToolIds) {
        const tool = tools.find(t => t.id === toolId);
        const qty = selectedQuantities[toolId];
        if (!tool || tool.available < qty) continue;

        const requestsToInsert = Array.from({ length: qty }).map(() => ({
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        }));

        const { error } = await supabase.from('requests').insert(requestsToInsert);
        if (error) throw error;
      }
      setMessage(`Gửi thành công yêu cầu mượn đồ!`);
      setSelectedQuantities({});
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Đã cập nhật' : 'Đã thêm mới');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const totalSelectedCount = (Object.values(selectedQuantities) as number[]).reduce((sum: number, q: number) => sum + q, 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in">
      {/* Header & Filter */}
      <div className="flex flex-col gap-5 bg-white p-6 rounded-[2rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">
            <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl md:rounded-[1.8rem] shadow-xl text-white transform hover:rotate-3 transition-transform ${isTet ? 'bg-red-700 shadow-red-100' : isNoel ? 'bg-red-600 shadow-red-100' : 'bg-blue-600 shadow-blue-100'}`}>
                  <Wrench className="w-6 h-6 md:w-8 md:h-8" />
                </div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none uppercase italic">
                      Kho thiết bị
                      {isNoel && <Snowflake className="inline ml-2 w-5 h-5 text-blue-300 animate-spin-slow" />}
                      {isTet && <Sparkles className="inline ml-2 w-5 h-5 text-yellow-400" />}
                    </h2>
                    <p className="text-[9px] md:text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1.5 opacity-70">Quản lý & mượn đồ tập trung</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto">
                {message && <div className="bg-emerald-600 text-white px-4 py-2.5 rounded-2xl text-[9px] font-black uppercase shadow-lg shadow-emerald-100 tracking-widest">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1 rounded-2xl border border-gray-200">
                        <button onClick={() => {setIsManageMode(true); setSelectedQuantities({});}} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${isManageMode ? (isTet || isNoel ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-blue-600 shadow-lg') : 'text-gray-500'}`}>QUẢN LÝ</button>
                        <button onClick={() => {setIsManageMode(false); setSelectedQuantities({});}} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${!isManageMode ? (isTet || isNoel ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-blue-600 shadow-lg') : 'text-gray-500'}`}>MƯỢN ĐỒ</button>
                    </div>
                )}

                {isManageMode && (
                    <button 
                        onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} 
                        className={`text-white px-6 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center gap-2 border-b-4 ${isTet ? 'bg-red-700 border-red-900 shadow-red-100' : isNoel ? 'bg-red-600 border-red-800 shadow-red-100' : 'bg-blue-600 border-blue-800 shadow-blue-100'}`}
                    >
                        <Plus className="w-4 h-4" /> THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-4 pt-4 border-t border-gray-100">
            <div className="relative flex-1 group">
                <Search className={`absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 transition-colors ${isTet || isNoel ? 'group-focus-within:text-red-600' : 'group-focus-within:text-blue-600'}`} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Tìm tên thiết bị, vị trí..." className={`w-full pl-12 pr-4 py-3.5 bg-gray-50 border-none rounded-2xl text-sm font-bold outline-none focus:ring-4 transition-all ${isTet || isNoel ? 'focus:ring-red-600/10' : 'focus:ring-blue-600/10'}`} />
            </div>

            <div className="flex gap-3">
                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className={`px-5 py-3.5 bg-gray-50 border-none rounded-2xl text-[9px] font-black uppercase tracking-widest outline-none cursor-pointer transition-all ${isTet || isNoel ? 'focus:text-red-600' : 'focus:text-blue-600'}`}>
                    <option value="all">Danh mục</option>
                    {uniqueCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                </select>
                <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-2xl border border-gray-200">
                  <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? (isTet || isNoel ? 'bg-white text-red-600 shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-400'}`}><LayoutGrid className="w-4 h-4" /></button>
                  <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? (isTet || isNoel ? 'bg-white text-red-600 shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-400'}`}><List className="w-4 h-4" /></button>
                </div>
            </div>
        </div>
      </div>

      {/* Main List */}
      <div className="flex-1">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {currentTools.map((tool: Tool) => {
                const qty = selectedQuantities[tool.id] || 0;
                const isSelected = qty > 0;
                const isAvailable = tool.status === 'active' && tool.available > 0;
                return (
                <Card 
                    key={tool.id} 
                    onClick={() => toggleSelection(tool)}
                    className={`cursor-pointer group hover:shadow-2xl transition-all p-0 border-4 overflow-hidden rounded-[2.8rem] ${isSelected ? (isTet || isNoel ? 'border-red-600 ring-8 ring-red-50 bg-red-50/20' : 'border-blue-600 ring-8 ring-blue-50 bg-blue-50/20') : 'border-transparent bg-white shadow-xl'} ${!isManageMode && !isAvailable && !isSelected ? 'opacity-50 grayscale pointer-events-none' : ''}`}
                >
                    <div className="h-56 bg-white flex items-center justify-center relative border-b border-gray-50">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        <span className={`text-white text-[8px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg border-2 border-white ${tool.status === 'inactive' ? 'bg-rose-500' : tool.available > 0 ? 'bg-emerald-500' : 'bg-gray-400'}`}>
                            {tool.status === 'inactive' ? 'Sửa chữa' : tool.available > 0 ? `Sẵn: ${tool.available}` : 'Hết đồ'}
                        </span>
                        {isSelected && <div className={`${isTet || isNoel ? 'bg-red-600' : 'bg-blue-600'} text-white p-2 rounded-full shadow-xl animate-bounce`}><Check className="w-3.5 h-3.5" /></div>}
                      </div>
                    </div>
                    <div className="p-6 space-y-4">
                      <div className="space-y-1">
                        <span className={`text-[8px] font-black uppercase tracking-[0.2em] ${isTet || isNoel ? 'text-red-600' : 'text-blue-600'}`}>{tool.category}</span>
                        <h3 className="font-black text-gray-900 text-sm line-clamp-2 h-10 leading-tight uppercase tracking-tight">{tool.name}</h3>
                      </div>
                      <div className="flex items-center justify-between text-[8px] text-gray-400 font-bold uppercase bg-gray-50 p-2.5 rounded-xl border border-gray-100">
                          <span className="flex items-center gap-1.5"><MapPin className={`w-3 h-3 ${isTet || isNoel ? 'text-red-400' : 'text-blue-400'}`} /> {tool.location || 'KHO CHUNG'}</span>
                          <span className="font-black text-gray-900">ID: {tool.id.slice(0, 5)}</span>
                      </div>
                      {isManageMode && (
                        <div className="flex gap-2 pt-1">
                           <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg transition-all active:scale-95 ${isTet || isNoel ? 'bg-red-700 hover:bg-red-800' : 'bg-gray-900 hover:bg-black'} text-white`}>Chỉnh sửa</button>
                           <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-3 bg-rose-50 text-rose-600 rounded-xl hover:bg-rose-600 hover:text-white transition-all"><Trash2 className="w-4 h-4" /></button>
                        </div>
                      )}
                      {!isManageMode && isSelected && (
                        <div className={`flex items-center justify-between p-1.5 rounded-2xl text-white shadow-xl animate-zoom-in border-4 border-white ${isTet || isNoel ? 'bg-red-600' : 'bg-blue-600'}`}>
                            <button onClick={(e) => updateQuantity(tool.id, -1, tool.available, e)} className="p-2.5 hover:bg-white/20 rounded-xl transition-colors"><Minus className="w-4 h-4" /></button>
                            <span className="text-lg font-black tabular-nums">{qty}</span>
                            <button onClick={(e) => updateQuantity(tool.id, 1, tool.available, e)} className="p-2.5 hover:bg-white/20 rounded-xl transition-colors"><Plus className="w-4 h-4" /></button>
                        </div>
                      )}
                    </div>
                </Card>
                );
            })}
            </div>
        ) : (
          <Card className="p-0 rounded-[2.5rem] overflow-hidden border-none shadow-xl bg-white min-h-[400px]">
            <div className="overflow-x-auto no-scrollbar">
              <table className="w-full text-left border-separate border-spacing-0">
                <thead className="bg-gray-50/50 border-b border-gray-100">
                  <tr>
                    <th className="px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Thiết bị</th>
                    <th className="px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400">Danh mục</th>
                    <th className="px-10 py-6 text-[9px] font-black uppercase tracking-widest text-gray-400 text-center">Sẵn / Tổng</th>
                    <th className="px-10 py-6 text-center text-[9px] font-black uppercase tracking-widest text-gray-400">Trạng thái</th>
                    <th className="px-10 py-6 text-right text-[9px] font-black uppercase tracking-widest text-gray-400">Thao tác</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 bg-white">
                  {currentTools.map((tool: Tool) => {
                    const qty = selectedQuantities[tool.id] || 0;
                    const isSelected = qty > 0;
                    return (
                        <tr 
                            key={tool.id} 
                            onClick={() => toggleSelection(tool)} 
                            className={`cursor-pointer transition-all duration-300 group border-l-4 border-l-transparent ${isSelected ? (isTet || isNoel ? 'bg-red-50/30 border-l-red-600' : 'bg-blue-50/30 border-l-blue-600') : 'hover:bg-gray-50/50 hover:translate-x-1'}`}
                        >
                            <td className="px-10 py-5">
                                <div className="flex items-center gap-4">
                                    <div className={`w-14 h-14 rounded-xl bg-white border-2 overflow-hidden flex items-center justify-center p-1 shadow-sm transition-transform group-hover:scale-110 ${isSelected ? (isTet || isNoel ? 'border-red-200' : 'border-blue-200') : 'border-gray-100'}`}>
                                      <ToolThumbnail src={tool.image} alt={tool.name} mode="table" />
                                    </div>
                                    <div>
                                        <div className={`font-black uppercase text-xs italic tracking-tight transition-colors ${isSelected ? (isTet || isNoel ? 'text-red-700' : 'text-blue-700') : 'text-gray-900 group-hover:text-indigo-600'}`}>{tool.name}</div>
                                        <div className="text-[9px] text-gray-400 font-bold uppercase mt-1 flex items-center gap-1"><MapPin className={`w-3 h-3 ${isTet || isNoel ? 'text-red-400' : 'text-blue-400'}`} /> {tool.location || 'KHO'}</div>
                                    </div>
                                </div>
                            </td>
                            <td className="px-10 py-5"><span className="bg-gray-100 text-gray-500 px-3 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest border border-gray-200">{tool.category}</span></td>
                            <td className="px-10 py-5 text-center text-xs font-black tabular-nums">
                                <span className={tool.available > 0 ? 'text-emerald-600' : 'text-rose-500'}>{tool.available}</span>
                                <span className="text-gray-200 mx-1.5">/</span>
                                <span className="text-gray-400">{tool.quantity}</span>
                            </td>
                            <td className="px-10 py-5 text-center">
                                {tool.status === 'active' ? (
                                    <span className="text-emerald-700 bg-emerald-50 px-3 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest border border-emerald-100 shadow-sm">Sẵn sàng</span>
                                ) : (
                                    <span className="text-rose-700 bg-rose-50 px-3 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest border border-rose-100 shadow-sm">Bảo trì</span>
                                )}
                            </td>
                            <td className="px-10 py-5 text-right">
                                <div className="flex justify-end items-center gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                    {isManageMode ? (
                                        <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className={`p-3 rounded-xl shadow-lg transition-all active:scale-90 border-b-4 ${isTet || isNoel ? 'bg-red-700 border-red-900' : 'bg-gray-900 border-black'} text-white`}><Edit className="w-4 h-4"/></button>
                                    ) : (
                                        isSelected && (
                                            <div className={`flex items-center rounded-xl p-1 shadow-lg border-2 border-white animate-zoom-in ${isTet || isNoel ? 'bg-red-600' : 'bg-blue-600'}`}>
                                                <button onClick={(e) => updateQuantity(tool.id, -1, tool.available, e)} className="p-2 hover:bg-white/20 rounded-lg text-white"><Minus className="w-3.5 h-3.5"/></button>
                                                <span className="px-3 font-black text-xs text-white tabular-nums">{qty}</span>
                                                <button onClick={(e) => updateQuantity(tool.id, 1, tool.available, e)} className="p-2 hover:bg-white/20 rounded-lg text-white"><Plus className="w-3.5 h-3.5"/></button>
                                            </div>
                                        )
