            <div className={`p-4 flex justify-between items-center text-white ${theme === 'tet' ? 'bg-gradient-to-r from-red-700 to-yellow-600' : 'bg-gradient-to-r from-red-600 to-orange-600'}`}>
              <div className="flex items-center gap-2">
                <Bot className="w-5 h-5" />
                <span className="font-semibold text-sm">{theme === 'tet' ? 'Trợ lý Tết Đoàn Viên 🧧' : 'Trợ lý AI'}</span>
