  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0]);
  const [exportEndDate, setExportEndDate] = useState(new Date().toISOString().split('T')[0]);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcelPro = (mode: 'today' | 'range') => {
    let filtered = [];
    const department = "Automation";

    if (mode === 'today') {
        filtered = requests.filter(r => r.date === todayStr);
    } else {
        filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    }

    if (filtered.length === 0) return alert("Không tìm thấy dữ liệu đăng ký.");

    const workbook = XLSX.utils.book_new();
    const groupedByDate = filtered.reduce((acc, req) => {
        if (!acc[req.date]) acc[req.date] = [];
        acc[req.date].push(req);
        return acc;
    }, {} as Record<string, OvertimeRequest[]>);

    Object.keys(groupedByDate).sort().forEach((dateKey) => {
        const dayRequests = groupedByDate[dateKey];
        // Định dạng lại tên tab cho rõ ràng DD-MM-YYYY
        const sheetName = dateKey.split('-').reverse().join('-');
        const displayDate = dateKey.split('-').reverse().join('/');

        const ws_data = [
            ["ĐĂNG KÝ LÀM THÊM TỰ NGUYỆN HÀNG NGÀY / APPLICATION FOR DAILY OVERTIME VOLUNTARY"],
            [],
            [`Bộ phận: ${department}`, ``, ``, ``, ``, ``, ``, `Ngày: ${displayDate}`],
            [`Tổng số người OT: ${dayRequests.length}`],
            [],
            ["STT", "Mã NV", "Họ tên", "Bắt đầu", "Kết thúc", "OT 150%", "OT 200%", "Lý do", "Ký tên", "Ghi chú"]
        ];

        dayRequests.forEach((req, idx) => {
            const date = new Date(req.date);
            const isWorking = dayConfigs[req.date] ?? (date.getDay() !== 0 && date.getDay() !== 6);
            ws_data.push([
                idx + 1, req.users?.employee_id || "", req.users?.name || "", req.start_time, req.end_time,
                isWorking ? req.total_hours : "", !isWorking ? req.total_hours : "", req.reason || "", "", ""
            ]);
        });

        const worksheet = XLSX.utils.aoa_to_sheet(ws_data);

        // Thiết lập chiều rộng cột cơ bản
        worksheet['!cols'] = [
          { wch: 5 }, { wch: 15 }, { wch: 25 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 30 }, { wch: 15 }, { wch: 15 }
        ];

        XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
    });

    XLSX.writeFile(workbook, `OT_Registration_${mode}_${new Date().getTime()}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");

    // CHẶN TRÙNG LẶP: Kiểm tra xem người này đã có đơn trong ngày chưa (nếu không phải đang edit đơn hiện tại)
    const alreadyRegistered = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);
    if (alreadyRegistered && !editingRequestId) {
        alert(`Nhân viên này đã được đăng ký OT cho ngày ${selectedDateStr.split('-').reverse().join('/')}. Vui lòng kiểm tra lại hoặc chọn cập nhật đơn cũ.`);
        return;
    }

    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason: reason.trim(), 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      if (!isAdmin) setIsModalOpen(false);
      else alert("Đã lưu đăng ký thành công!");
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const todayRegistrations = useMemo(() => {
    return requests.filter(r => r.date === todayStr).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-16 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isActuallyWorking = dayConfigs[dateStr] ?? defaultIsWorking;

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-16 md:h-32 border border-gray-100 p-1 md:p-3 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30 z-10' : 'bg-white'} 
                  ${isPast ? 'opacity-40' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-1.5 flex-wrap">
                        <span className={`text-xs md:text-lg font-black ${isToday ? 'bg-blue-600 text-white w-5 h-5 md:w-8 md:h-8 rounded-lg flex items-center justify-center shadow-lg' : 'text-gray-700'}`}>
                            {d}
                        </span>

                        {(!isActuallyWorking || (isActuallyWorking && (dayOfWeek === 0 || dayOfWeek === 6))) && (
                            <span className={`text-[7px] md:text-[10px] font-black px-1.5 py-0.5 rounded uppercase tracking-tighter shadow-sm border ${isActuallyWorking ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                                {isActuallyWorking ? 'LÀM' : 'NGHỈ'}
                            </span>
                        )}
                    </div>
                </div>
                <div className="flex-1 flex flex-col justify-start gap-1 mt-1.5 overflow-hidden">
                    {myRequest && <div className="w-2 h-2 md:w-7 md:h-7 rounded-lg bg-emerald-500 flex items-center justify-center shrink-0 shadow-sm"><UserIcon className="hidden md:block w-4 h-4 text-white" /></div>}
                    <div className="flex -space-x-1.5 md:-space-x-3 overflow-hidden">
                        {otherRequests.slice(0, 4).map((req, idx) => (
                            <div key={idx} className="w-2 h-2 md:w-6 md:h-6 rounded-full bg-indigo-100 border-2 border-white flex items-center justify-center shrink-0 shadow-sm">
                                <span className="hidden md:block text-[8px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                            </div>
                        ))}
                    </div>
                </div>
                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-100 text-gray-600 text-[6px] md:text-[10px] px-1.5 py-0.5 rounded-lg font-black border border-gray-200">
                        {dayRequestsLocal.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const dayRequestsInModal = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  const displayedDayRequests = useMemo(() => {
    if (isListExpanded) return dayRequestsInModal;
    return dayRequestsInModal.slice(0, 4); 
  }, [dayRequestsInModal, isListExpanded]);

  return (
    <div className="space-y-4 md:space-y-8 h-full flex flex-col animate-fade-in max-w-[1400px] mx-auto w-full px-2 md:px-0 pb-20">
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-6 md:p-8 rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 transition-all">
            <div>
                <div className="flex items-center gap-3">
                    <h2 className="text-xl md:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-3 uppercase italic">
                      Quản lý Tăng ca 
                      {isNoel && <Snowflake className="w-6 h-6 text-blue-300 animate-spin-slow" />}
                      {isTet && <Sparkles className="w-6 h-6 text-yellow-400" />}
                    </h2>
                    <span className="hidden sm:inline-block text-[10px] md:text-xs font-black bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full uppercase tracking-widest">HỆ THỐNG V1</span>
                </div>
                <p className="text-[10px] md:text-base text-gray-500 font-medium italic mt-1">Giao diện đăng ký linh hoạt cho mọi thiết bị</p>
            </div>
            <div className="flex bg-gray-100/80 p-1 rounded-2xl border border-gray-200 w-full lg:w-auto overflow-x-auto no-scrollbar">
                {['calendar', 'personal', 'stats'].map(t => (
                    <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 lg:flex-none px-6 md:px-10 py-3 rounded-xl text-[10px] md:text-sm font-black transition-all uppercase tracking-widest ${activeTab === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>
                        {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                    </button>
                ))}
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-100 shadow-lg rounded-[1.5rem] md:rounded-[3rem] bg-white">
                    <div className="flex items-center justify-between p-4 md:p-8 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronLeft className="w-6 h-6"/></button>
                        <h3 className="text-base md:text-xl lg:text-2xl font-black uppercase tracking-[0.2em] text-gray-800 italic">Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-3 hover:bg-gray-100 rounded-2xl transition-all active:scale-90"><ChevronRight className="w-6 h-6"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[9px] md:text-xs font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-3 md:py-6 text-center ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-100 gap-[0.5px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-6 md:space-y-8 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
                        <Card className="bg-gradient-to-br from-indigo-600 to-blue-700 text-white border-none shadow-xl rounded-[2rem] p-6 md:p-8">
                            <h3 className="text-[10px] md:text-xs font-black uppercase tracking-widest opacity-80">Tổng giờ T{currentDate.getMonth()+1}</h3>
                            <div className="flex items-end gap-2 mt-2"><span className="text-3xl md:text-6xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-sm md:text-2xl font-bold opacity-70">h</span></div>
                        </Card>
                        <Card className="bg-white border-l-8 border-emerald-500 rounded-[2rem] p-6 shadow-sm flex items-center gap-4">
                            <div className="p-3 md:p-5 bg-emerald-50 rounded-2xl text-emerald-600"><Check className="w-6 h-6 md:w-8 md:h-8"/></div>
                            <div><p className="text-[10px] md:text-xs font-black text-gray-400 uppercase tracking-widest">Đăng ký</p><p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{myStats.count} d</p></div>
                        </Card>
                         <Card className="bg-white border-l-8 border-amber-500 rounded-[2rem] p-6 shadow-sm flex items-center gap-4">
                            <div className="p-3 md:p-5 bg-amber-50 rounded-2xl text-amber-600"><Timer className="w-6 h-6 md:w-8 md:h-8"/></div>
                            <div><p className="text-[10px] md:text-xs font-black text-gray-400 uppercase tracking-widest">Chờ duyệt</p><p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{myStats.pending}</p></div>
                        </Card>
                        <Card className="bg-white border-l-8 border-indigo-500 rounded-[2rem] p-6 shadow-sm flex items-center gap-4">
                            <div className="p-3 md:p-5 bg-indigo-50 rounded-2xl text-indigo-600"><Activity className="w-6 h-6 md:w-8 md:h-8"/></div>
                            <div><p className="text-[10px] md:text-xs font-black text-gray-400 uppercase tracking-widest">Trung bình</p><p className="text-xl md:text-4xl font-black text-gray-900 tabular-nums">{(myStats.total / (myStats.count || 1)).toFixed(1)}h</p></div>
                        </Card>
                    </div>

                    <Card className="rounded-[2rem] md:rounded-[4rem] p-6 md:p-12 shadow-md border-none bg-white">
                        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-10">
                            <div>
                                <h3 className="text-lg md:text-2xl font-black text-gray-900 uppercase tracking-tight italic">Biểu đồ xu hướng</h3>
                                <p className="text-[10px] md:text-sm text-gray-400 font-bold uppercase tracking-widest mt-1">Lịch sử đăng ký OT cá nhân</p>
                            </div>
                        </div>
                        <div className="h-64 md:h-96 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend} margin={{ top: 0, right: 0, left: -25, bottom: 0 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{fontSize: '11px', borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}} />
                                    <Bar dataKey="hours" fill="#4f46e5" radius={[4, 4, 0, 0]} barSize={12} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-6 md:space-y-10 animate-fade-in-up">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
                        <Card className="bg-white border-none p-8 flex items-center gap-6 shadow-sm rounded-[2rem]">
                            <div className="p-5 bg-indigo-100 text-indigo-600 rounded-3xl"><Users className="w-8 h-8"/></div>
                            <div><p className="text-[10px] md:text-xs font-black text-gray-400 uppercase tracking-widest">Nhân sự OT</p><p className="text-3xl md:text-5xl font-black text-gray-900 tabular-nums">{teamMonthlyStats.activeMembers}</p></div>
                        </Card>
                        <Card className="bg-white border-none p-8 flex items-center gap-6 shadow-sm rounded-[2rem]">
                            <div className="p-5 bg-emerald-100 text-emerald-600 rounded-3xl"><Timer className="w-8 h-8"/></div>
                            <div><p className="text-[10px] md:text-xs font-black text-gray-400 uppercase tracking-widest">Tổng giờ tháng</p><p className="text-3xl md:text-5xl font-black text-gray-900 tabular-nums">{teamMonthlyStats.totalHours.toFixed(1)}h</p></div>
