                                    <p className="text-[10px] font-semibold text-gray-400 uppercase tracking-widest italic leading-relaxed">Đang xem đăng ký của:<br/><span className="text-indigo-900 text-sm font-bold">{allEmployees.find(e => e.id === targetUserId)?.name}</span></p>
                                    <button type="button" onClick={() => {setTargetUserId(user.id); setEditingRequestId(null); setReason('');}} className="w-full py-3.5 bg-indigo-600 text-white text-[10px] font-bold uppercase rounded-xl tracking-widest shadow-lg hover:bg-indigo-700 transition-all border-b-4 border-indigo-900">QUAY LẠI ĐĂNG KÝ CHO BẠN</button>
                                </div>
                            ) : (
                                <div className="bg-white p-5 rounded-[1.5rem] border border-indigo-50 shadow-sm space-y-5 relative">
                                    {isAdmin && (
                                        <div className="space-y-1.5">
                                            <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-1.5"><UserCheck className="w-3 h-3" /> Chọn nhân sự thực hiện:</label>
                                            <div className="relative">
                                              <select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border-2 border-transparent rounded-xl text-[11px] font-bold outline-none focus:bg-white focus:border-indigo-500 appearance-none cursor-pointer uppercase shadow-inner transition-all">
                                                  {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}
                                              </select>
                                              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none" />
                                            </div>
                                        </div>
                                    )}
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-1.5">
                                            <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1 italic">Bắt đầu:</label>
                                            <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border-2 border-transparent rounded-xl text-xs md:text-sm font-bold text-gray-900 outline-none focus:bg-white focus:border-indigo-500 shadow-inner transition-all"/>
                                        </div>
                                        <div className="space-y-1.5">
                                            <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1 italic">Kết thúc:</label>
                                            <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border-2 border-transparent rounded-xl text-xs md:text-sm font-bold text-gray-900 outline-none focus:bg-white focus:border-indigo-500 shadow-inner transition-all"/>
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1">
                                            <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-1.5"><FileText className="w-3 h-3" /> Ghi chú công việc</label>
                                            <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2.5 py-0.5 rounded-lg border border-indigo-100 tabular-nums animate-pulse">{calculatedHours.toFixed(1)}h CÔNG</span>
                                        </div>
                                        <textarea value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-xl text-xs h-24 md:h-28 resize-none outline-none font-semibold text-gray-800 shadow-inner focus:bg-white focus:border-indigo-500 transition-all placeholder:text-gray-300" placeholder="Mô tả tóm tắt nội dung..."/>
                                    </div>
                                    <div className="flex gap-3 pt-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3.5 bg-rose-50 text-rose-600 rounded-xl border-2 border-rose-100 hover:bg-rose-600 hover:text-white transition-all shadow-sm active:scale-90"><Trash2 className="w-5 h-5"/></button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-bold rounded-xl shadow-xl text-[11px] tracking-[0.2em] uppercase transition-all active:scale-95 disabled:opacity-50 border-b-4 border-indigo-900">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'CẬP NHẬT ĐƠN' : 'XÁC NHẬN ĐĂNG KÝ'}
                                        </button>
                                    </div>
                                </div>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-20 h-20 bg-rose-50 text-rose-500 mx-auto mb-6 rounded-3xl flex items-center justify-center shadow-md"><Trash2 className="w-10 h-10" /></div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2 uppercase tracking-tighter italic">Hủy Đăng Ký?</h3>
                    <p className="text-[10px] md:text-xs text-gray-400 font-semibold uppercase mb-8 tracking-widest">Dữ liệu đăng ký sẽ bị xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-2.5">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-bold rounded-xl text-[10px] uppercase shadow-lg shadow-rose-200 border-b-4 border-rose-900">XÓA DỮ LIỆU</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-bold rounded-xl border-2 border-gray-100 text-[10px] uppercase active:scale-95 transition-all">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useContext } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles, UserPlus, UserRoundPen, ChevronUp, Gift
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { ThemeContext } from '../../../App';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);
  const [isListExpanded, setIsListExpanded] = useState(false); 
  const [isListHidden, setIsListHidden] = useState(false); 

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  // Mặc định ngày bắt đầu xuất Excel là ngày hôm nay
  const [exportStartDate, setExportStartDate] = useState(todayStr);
  const [exportEndDate, setExportEndDate] = useState(todayStr);

  // State cho việc xem danh sách theo ngày trong tab Thống kê
  const [statsViewDate, setStatsViewDate] = useState(todayStr);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcelPro = (mode: 'today' | 'range') => {
    let filtered: OvertimeRequest[] = [];
    const department = "Automation";

    if (mode === 'today') {
        filtered = requests.filter(r => r.date === todayStr);
    } else {
        filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    }

    if (filtered.length === 0) return alert("Không tìm thấy dữ liệu đăng ký trong khoảng ngày đã chọn.");

    const workbook = XLSX.utils.book_new();
    const groupedByDate = filtered.reduce((acc, req) => {
        if (!acc[req.date]) acc[req.date] = [];
        acc[req.date].push(req);
        return acc;
    }, {} as Record<string, OvertimeRequest[]>);

    Object.keys(groupedByDate).sort().forEach((dateKey) => {
        const dayRequests = groupedByDate[dateKey];
        const sheetName = dateKey.split('-').reverse().join('-');
        const displayDate = dateKey.split('-').reverse().join('/');

        const ws_data: any[][] = [
            ["ĐĂNG KÝ LÀM THÊM TỰ NGUYỆN HÀNG NGÀY / APPLICATION FOR DAILY OVERTIME VOLUNTARY"],
            [],
            [`Bộ phận: ${department}`, ``, ``, ``, ``, ``, ``, `Ngày: ${displayDate}`],
            [`Tổng số người OT: ${dayRequests.length}`],
            [],
            ["STT", "Mã NV", "Họ tên", "Bắt đầu", "Kết thúc", "OT 150%", "OT 200%", "Lý do", "Ký tên", "Ghi chú"]
        ];

        dayRequests.forEach((req, idx) => {
            const date = new Date(req.date);
            const isWorking = dayConfigs[req.date] ?? (date.getDay() !== 0 && date.getDay() !== 6);
            ws_data.push([
                idx + 1, req.users?.employee_id || "", req.users?.name || "", req.start_time, req.end_time,
                isWorking ? req.total_hours : "", !isWorking ? req.total_hours : "", req.reason || "", "", ""
            ]);
        });

        const worksheet = XLSX.utils.aoa_to_sheet(ws_data);
        worksheet['!cols'] = [
          { wch: 5 }, { wch: 15 }, { wch: 25 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 30 }, { wch: 15 }, { wch: 15 }
        ];
        XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
    });

    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'today' ? 'Today' : exportStartDate + '_to_' + exportEndDate}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");

    const alreadyRegistered = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);
    if (alreadyRegistered && !editingRequestId) {
        alert(`Nhân viên này đã được đăng ký OT cho ngày ${selectedDateStr.split('-').reverse().join('/')}. Vui lòng kiểm tra lại hoặc chọn cập nhật đơn cũ.`);
        return;
    }

    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason: reason.trim(), 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      if (!isAdmin) setIsModalOpen(false);
      else {
        alert("Đã lưu đăng ký thành công!");
        setIsListExpanded(true); 
      }
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
    setIsListExpanded(false); 
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  // Lọc danh sách đăng ký theo ngày được chọn trong tab Thống kê
  const targetedRegistrations = useMemo(() => {
    return requests.filter(r => r.date === statsViewDate).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests, statsViewDate]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-16 md:h-28 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isActuallyWorking = dayConfigs[dateStr] ?? defaultIsWorking;

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-16 md:h-28 border border-gray-100 p-1.5 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30 z-10' : 'bg-white'} 
                  ${isPast ? 'opacity-40' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-1 flex-wrap">
                        <span className={`text-[10px] md:text-sm font-black ${isToday ? 'bg-blue-600 text-white w-4 h-4 md:w-6 md:h-6 rounded-md flex items-center justify-center shadow-lg' : 'text-gray-700'}`}>
                            {d}
                        </span>

                        {(!isActuallyWorking || (isActuallyWorking && (dayOfWeek === 0 || dayOfWeek === 6))) && (
                            <span className={`text-[6px] md:text-[8px] font-black px-1 py-0.2 rounded uppercase tracking-tighter border ${isActuallyWorking ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                                {isActuallyWorking ? 'LÀM' : 'NGHỈ'}
                            </span>
                        )}
                    </div>
                </div>
                <div className="flex-1 flex flex-col justify-start gap-1 mt-1 overflow-hidden">
                    {myRequest && <div className="w-1.5 h-1.5 md:w-5 md:h-5 rounded-md bg-emerald-500 flex items-center justify-center shrink-0 shadow-sm"><UserIcon className="hidden md:block w-3 h-3 text-white" /></div>}
                    <div className="flex -space-x-1 md:-space-x-2 overflow-hidden">
                        {otherRequests.slice(0, 3).map((req, idx) => (
                            <div key={idx} className="w-1.5 h-1.5 md:w-4 md:h-4 rounded-full bg-indigo-100 border border-white flex items-center justify-center shrink-0 shadow-sm">
                                <span className="hidden md:block text-[6px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                            </div>
                        ))}
                    </div>
                </div>
                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-100 text-gray-500 text-[6px] md:text-[9px] px-1 py-0.2 rounded font-black border border-gray-200">
                        {dayRequestsLocal.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const dayRequestsInModal = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-[1300px] mx-auto w-full px-2 md:px-0 pb-20">
