                                            </button>
                                          )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {isViewOnly ? (
                                <div className="bg-white border-2 border-dashed border-indigo-100 p-8 rounded-[1.8rem] text-center space-y-3 shadow-sm">
                                    <Eye className="w-10 h-10 text-indigo-200 mx-auto" />
                                    <p className="text-[10px] font-semibold text-gray-400 uppercase tracking-widest italic leading-relaxed">Đang xem đăng ký của:<br/><span className="text-indigo-900 text-sm font-bold">{allEmployees.find(e => e.id === targetUserId)?.name}</span></p>
                                    <button type="button" onClick={() => {setTargetUserId(user.id); setEditingRequestId(null); setReason('');}} className="w-full py-3.5 bg-indigo-600 text-white text-[10px] font-bold uppercase rounded-xl tracking-widest shadow-lg hover:bg-indigo-700 transition-all border-b-4 border-indigo-900">QUAY LẠI ĐĂNG KÝ CHO BẠN</button>
                                </div>
                            ) : (
                                <div className="bg-white p-5 rounded-[1.5rem] border border-indigo-50 shadow-sm space-y-5 relative">
                                    {isAdmin && (
                                        <div className="space-y-1.5">
                                            <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-1.5"><UserCheck className="w-3 h-3" /> Chọn nhân sự thực hiện:</label>
                                            <div className="relative">
                                              <select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border-2 border-transparent rounded-xl text-[11px] font-bold outline-none focus:bg-white focus:border-indigo-500 appearance-none cursor-pointer uppercase shadow-inner transition-all">
                                                  {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}
                                              </select>
                                              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-300 pointer-events-none" />
                                            </div>
                                        </div>
                                    )}
                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-1.5">
                                            <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1 italic">Bắt đầu:</label>
                                            <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border-2 border-transparent rounded-xl text-xs md:text-sm font-bold text-gray-900 outline-none focus:bg-white focus:border-indigo-500 shadow-inner transition-all"/>
                                        </div>
                                        <div className="space-y-1.5">
                                            <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-widest ml-1 italic">Kết thúc:</label>
                                            <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border-2 border-transparent rounded-xl text-xs md:text-sm font-bold text-gray-900 outline-none focus:bg-white focus:border-indigo-500 shadow-inner transition-all"/>
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex justify-between items-center px-1">
                                            <label className="text-[9px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-1.5"><FileText className="w-3 h-3" /> Ghi chú công việc</label>
                                            <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2.5 py-0.5 rounded-lg border border-indigo-100 tabular-nums animate-pulse">{calculatedHours.toFixed(1)}h CÔNG</span>
                                        </div>
                                        <textarea value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-xl text-xs h-24 md:h-28 resize-none outline-none font-semibold text-gray-800 shadow-inner focus:bg-white focus:border-indigo-500 transition-all placeholder:text-gray-300" placeholder="Mô tả tóm tắt nội dung..."/>
                                    </div>
                                    <div className="flex gap-3 pt-2">
                                        {(editingRequestId && (isAdmin || targetUserId === user.id)) && (
                                            <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-3.5 bg-rose-50 text-rose-600 rounded-xl border-2 border-rose-100 hover:bg-rose-600 hover:text-white transition-all shadow-sm active:scale-90"><Trash2 className="w-5 h-5"/></button>
                                        )}
                                        <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className="flex-1 py-4 bg-indigo-600 text-white font-bold rounded-xl shadow-xl text-[11px] tracking-[0.2em] uppercase transition-all active:scale-95 disabled:opacity-50 border-b-4 border-indigo-900">
                                            {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin mx-auto"/> : editingRequestId ? 'CẬP NHẬT ĐƠN' : 'XÁC NHẬN ĐĂNG KÝ'}
                                        </button>
                                    </div>
                                </div>
                            )}
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
                <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xs overflow-hidden animate-zoom-in p-8 text-center border border-white/20">
                    <div className="w-20 h-20 bg-rose-50 text-rose-500 mx-auto mb-6 rounded-3xl flex items-center justify-center shadow-md"><Trash2 className="w-10 h-10" /></div>
                    <h3 className="text-xl font-bold text-gray-900 mb-2 uppercase tracking-tighter italic">Hủy Đăng Ký?</h3>
                    <p className="text-[10px] md:text-xs text-gray-400 font-semibold uppercase mb-8 tracking-widest">Dữ liệu đăng ký sẽ bị xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-2.5">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-bold rounded-xl text-[10px] uppercase shadow-lg shadow-rose-200 border-b-4 border-rose-900">XÓA DỮ LIỆU</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-bold rounded-xl border-2 border-gray-100 text-[10px] uppercase active:scale-95 transition-all">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo, useContext } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon, Snowflake, Sparkles, Gift,
  ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, CalendarDays, Filter,
  AlertCircle, ArrowRight
} from 'lucide-react';
import { ThemeContext } from '../../../App';

interface RequestManagerProps { user: User; }

const ITEMS_PER_PAGE = 10;
const todayStr = new Date().toISOString().split('T')[0];

const ToolTableImage = ({ toolId, toolName, size = "md" }: { toolId: string, toolName: string, size?: "sm" | "md" }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  const sizeClass = size === "sm" ? "w-10 h-10" : "w-12 h-12";

  return (
    <div className={`${sizeClass} bg-white border border-gray-100 rounded-xl overflow-hidden flex items-center justify-center p-1 shadow-sm shrink-0`}>
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-4 h-4 text-gray-300" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterDate, setFilterDate] = useState(todayStr); 
  const [currentPage, setCurrentPage] = useState(1);

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      if (!silent) setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      rejected: 2,
      returned: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      const matchesDate = !filterDate || req.borrow_date.startsWith(filterDate);

      return matchesSearch && matchesStatus && matchesDate;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterDate]);

  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / ITEMS_PER_PAGE));
  const paginatedRequests = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredRequests.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredRequests, currentPage]);

  useEffect(() => {
    setCurrentPage(1); 
  }, [searchTerm, filterStatus, filterDate, activeTab]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    const oldRequests = [...requests];

    let newStatus: BorrowRequest['status'] = 'pending';
    if (action === 'approve') newStatus = 'approved';
    else if (action === 'reject') newStatus = 'rejected';
    else if (action === 'return') newStatus = 'returned';

    if (action === 'cancel') {
      setRequests(prev => prev.filter(r => r.id !== id));
    } else {
      setRequests(prev => prev.map(r => r.id === id ? { ...r, status: newStatus, returned_at: action === 'return' ? new Date().toISOString() : r.returned_at } : r));
    }

    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) {
           setRequests(oldRequests);
           throw new Error("Hết hàng trong kho");
        }
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
    } catch (e: any) {
      alert(e.message);
      setRequests(oldRequests);
    } finally {
      setProcessingId(null);
      fetchRequests(true);
    }
  };

  const getStatusBadge = (status: string, size: "sm" | "md" = "md") => {
    const configs: any = {
      pending: { 
        color: 'bg-amber-100 text-amber-700 border-amber-200', 
        icon: <Timer className="w-3 h-3 animate-pulse" />, 
        label: 'CHỜ DUYỆT' 
      },
      approved: { 
        color: 'bg-emerald-100 text-emerald-700 border-emerald-200', 
        icon: <PackageCheck className="w-3 h-3" />, 
        label: 'ĐANG MƯỢN' 
      },
      returned: { 
        color: 'bg-indigo-100 text-indigo-700 border-indigo-200', 
        icon: <RotateCcw className="w-3 h-3" />, 
        label: 'ĐÃ TRẢ' 
      },
      rejected: { 
        color: 'bg-rose-100 text-rose-700 border-rose-200', 
        icon: <AlertCircle className="w-3 h-3" />, 
        label: 'TỪ CHỐI' 
      }
    };
    const c = configs[status] || configs.pending;
    const padding = size === "sm" ? "px-2 py-1" : "px-3 py-1.5";
    return (
      <div className={`inline-flex items-center gap-1.5 ${padding} rounded-lg text-[9px] font-black border shadow-sm ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-4 md:space-y-6 animate-fade-in max-w-7xl mx-auto pb-10">
      {/* HEADER SECTION */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white p-5 md:p-8 rounded-[1.5rem] md:rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className={`p-3 md:p-4 rounded-2xl shadow-xl text-white transform hover:rotate-3 transition-transform ${isNoel ? 'bg-red-600' : (isTet ? 'bg-red-700' : 'bg-blue-600')}`}>
            <RefreshCw className="w-6 h-6 md:w-8 h-8" />
          </div>
          <div>
            <h2 className="text-lg md:text-2xl font-black text-gray-900 tracking-tight uppercase flex items-center gap-2 italic">
               Phê duyệt mượn
               {isNoel && <Snowflake className="w-5 h-5 text-blue-300 animate-spin-slow hidden sm:block" />}
               {isTet && <Sparkles className="w-5 h-5 text-yellow-400 hidden sm:block" />}
            </h2>
            <p className="text-[9px] md:text-[10px] text-gray-400 font-black uppercase tracking-widest mt-0.5 opacity-70">
              {filterDate === todayStr ? 'Đơn hôm nay 📅' : `Ngày ${filterDate.split('-').reverse().join('/')}`}
            </p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200 shadow-inner w-full lg:w-auto">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`flex-1 lg:flex-none px-6 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? (isNoel || isTet ? 'bg-red-600 text-white shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500'}`}>Toàn bộ</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`flex-1 lg:flex-none px-6 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? (isNoel || isTet ? 'bg-red-600 text-white shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500'}`}>Của tôi</button>
        </div>
      </div>

      {/* FILTERS SECTION */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-3 md:gap-4">
        <div className="md:col-span-5 relative group">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600 transition-colors" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm mã NV, tên, thiết bị..." 
            className={`w-full pl-11 pr-4 py-3.5 bg-white border border-gray-100 rounded-2xl text-xs md:text-sm font-bold outline-none focus:ring-4 transition-all shadow-sm ${isTet ? 'focus:ring-red-500/5 focus:border-red-500' : 'focus:ring-blue-500/5 focus:border-blue-500'}`} 
          />
        </div>

        <div className="md:col-span-4 flex items-center gap-2 bg-white p-2 border border-gray-100 rounded-2xl shadow-sm">
           <CalendarDays className="w-5 h-5 text-gray-400 ml-2" />
           <input 
            type="date" 
            value={filterDate} 
            onChange={e => setFilterDate(e.target.value)}
            className={`flex-1 bg-transparent border-none text-[10px] md:text-[11px] font-black uppercase outline-none cursor-pointer ${isTet ? 'focus:text-red-600' : 'focus:text-blue-600'}`}
           />
           {filterDate !== todayStr && (
             <button onClick={() => setFilterDate(todayStr)} className="px-2 py-1 bg-gray-100 text-[8px] font-black rounded-lg hover:bg-gray-200">HÔM NAY</button>
           )}
        </div>

        <div className="md:col-span-3">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className={`w-full px-4 py-3.5 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-sm transition-all ${isTet ? 'focus:border-red-500' : 'focus:border-blue-500'}`}
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ duyệt</option>
            <option value="approved">📦 Đang mượn</option>
            <option value="returned">✅ Đã trả</option>
            <option value="rejected">❌ Từ chối</option>
          </select>
        </div>
      </div>

      {/* CONTENT AREA: RESPONSIVE TABLE/CARD */}
      <div className="bg-white rounded-[1.5rem] md:rounded-[2.5rem] shadow-xl overflow-hidden border border-gray-50 min-h-[400px]">
        {/* DESKTOP TABLE VIEW */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full text-left border-separate border-spacing-0">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Người mượn</th>
                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Thiết bị</th>
                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Thời gian</th>
                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Trạng thái</th>
                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="py-20 text-center"><Loader2 className="w-8 h-8 animate-spin text-gray-300 mx-auto" /></td></tr>
              ) : paginatedRequests.length === 0 ? (
                <tr><td colSpan={5} className="py-20 text-center text-gray-300 font-black uppercase text-xs">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                paginatedRequests.map((req) => (
                  <tr key={req.id} className="group hover:bg-blue-50/20 transition-all border-l-4 border-l-transparent hover:border-l-blue-600">
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-3">
                        <div className={`w-9 h-9 text-white rounded-xl flex items-center justify-center font-black text-xs shadow-md ${isTet ? 'bg-red-800' : 'bg-indigo-600'}`}>{req.user_name.charAt(0)}</div>
                        <div>
                          <div className="font-black text-xs uppercase italic text-gray-900">{req.user_name}</div>
                          <div className="text-[9px] text-gray-400 font-black tracking-widest">{req.employee_id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-3">
                        <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                        <div className="font-black text-xs uppercase tracking-tighter text-gray-700">{req.tool_name}</div>
                      </div>
                    </td>
                    <td className="px-8 py-5 text-[10px] font-black text-gray-500">
                        <Calendar className="w-3 h-3 inline mr-1 opacity-50" />
                        {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                    </td>
                    <td className="px-8 py-5 text-center">
                      {getStatusBadge(req.status)}
                    </td>
                    <td className="px-8 py-5 text-right">
                      {processingId === req.id ? (
                        <Loader2 className="w-5 h-5 animate-spin ml-auto text-blue-600" />
                      ) : (
                        <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                            <>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="p-2 bg-emerald-50 text-emerald-600 rounded-lg border border-emerald-100 hover:bg-emerald-600 hover:text-white transition-all"><Check className="w-4 h-4" /></button>
                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-2 bg-rose-50 text-rose-600 rounded-lg border border-rose-100 hover:bg-rose-600 hover:text-white transition-all"><X className="w-4 h-4" /></button>
                            </>
                          )}
                          {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="px-3 py-1.5 bg-red-50 text-red-600 rounded-lg border border-red-100 hover:bg-red-600 hover:text-white text-[9px] font-black uppercase">THU HỒI</button>
                          )}
                          {req.user_id === user.id && req.status === 'pending' && (
                            <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="p-2 text-gray-400 hover:text-rose-600 transition-all"><Trash2 className="w-4 h-4" /></button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* MOBILE CARD VIEW */}
        <div className="md:hidden divide-y divide-gray-100">
           {loading ? (
             <div className="py-20 text-center"><Loader2 className="w-10 h-10 animate-spin text-gray-200 mx-auto" /></div>
           ) : paginatedRequests.length === 0 ? (
             <div className="py-20 text-center text-gray-300 font-black uppercase text-[10px]">Trống rỗng...</div>
           ) : (
             paginatedRequests.map((req) => (
                <div key={req.id} className="p-5 space-y-4 active:bg-gray-50 transition-colors">
                    <div className="flex justify-between items-start">
                        <div className="flex items-center gap-3">
                            <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} size="sm" />
                            <div>
                                <h3 className="text-xs font-black uppercase tracking-tight text-gray-900 leading-tight">{req.tool_name}</h3>
                                <div className="flex items-center gap-1.5 mt-1 text-[9px] font-black text-gray-400 uppercase tracking-widest">
                                    <UserIcon className="w-2.5 h-2.5" />
                                    {req.user_name} • {req.employee_id}
                                </div>
                            </div>
                        </div>
                        {getStatusBadge(req.status, "sm")}
                    </div>

                    <div className="flex items-center justify-between bg-gray-50 p-3 rounded-xl border border-gray-100/50">
                        <div className="text-[9px] font-black text-gray-400 uppercase tracking-[0.15em] flex items-center gap-1.5">
                            <Calendar className="w-3 h-3" />
                            {new Date(req.borrow_date).toLocaleDateString('vi-VN')}
                        </div>
                        {req.returned_at && (
                            <div className="text-[8px] font-black text-emerald-600 italic">Trả: {new Date(req.returned_at).toLocaleTimeString('vi-VN')}</div>
                        )}
                    </div>

                    <div className="flex gap-2">
                        {processingId === req.id ? (
                            <div className="w-full flex justify-center py-2"><Loader2 className="w-5 h-5 animate-spin text-blue-600" /></div>
                        ) : (
                            <>
                                {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                                    <>
                                        <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="flex-1 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-emerald-100 flex items-center justify-center gap-2 border-b-4 border-emerald-800"><Check className="w-3.5 h-3.5" /> DUYỆT</button>
                                        <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="flex-1 py-3 bg-rose-50 text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest border border-rose-100 flex items-center justify-center gap-2"><X className="w-3.5 h-3.5" /> TỪ CHỐI</button>
                                    </>
                                )}
                                {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                                    <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="w-full py-3 bg-red-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-red-100 flex items-center justify-center gap-2 border-b-4 border-red-900"><RotateCcw className="w-3.5 h-3.5" /> THU HỒI THIẾT BỊ</button>
                                )}
                                {req.user_id === user.id && req.status === 'pending' && (
                                    <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="w-full py-3 bg-white text-rose-600 border-2 border-rose-100 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2"><Trash2 className="w-3.5 h-3.5" /> HỦY YÊU CẦU</button>
                                )}
                            </>
                        )}
                    </div>
                </div>
             ))
           )}
        </div>

        {/* PAGINATION FOOTER */}
        {filteredRequests.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-6 flex flex-col sm:flex-row items-center justify-between gap-6 px-6 md:px-10">
            <div className="text-[10px] text-gray-400 font-black uppercase tracking-widest">
              Trang <span className="text-gray-900 tabular-nums">{currentPage}/{totalPages}</span> ({filteredRequests.length})
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
                className="p-2 rounded-lg border border-gray-200 bg-white disabled:opacity-30 active:scale-90"
              >
                <ChevronsLeft className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-2 rounded-lg border border-gray-200 bg-white disabled:opacity-30 active:scale-90"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>

              <div className="flex items-center gap-1 mx-2">
                 {[currentPage].map(p => (
                    <div key={p} className={`w-8 h-8 rounded-lg font-black text-xs flex items-center justify-center ${isNoel || isTet ? 'bg-red-600 text-white' : 'bg-blue-600 text-white'}`}>
                        {p}
                    </div>
                 ))}
              </div>

              <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="p-2 rounded-lg border border-gray-200 bg-white disabled:opacity-30 active:scale-90"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
              <button 
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages}
                className="p-2 rounded-lg border border-gray-200 bg-white disabled:opacity-30 active:scale-90"
              >
                <ChevronsRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="flex justify-center gap-8 py-4 opacity-10 select-none">
         {isNoel && Array.from({length: 3}).map((_, i) => <Snowflake key={i} className="w-8 h-8 text-blue-400" />)}
         {isTet && Array.from({length: 3}).map((_, i) => <Gift key={i} className="w-8 h-8 text-yellow-500" />)}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useContext } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles, UserPlus, UserRoundPen, ChevronUp, Gift
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { ThemeContext } from '../../../App';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);
  const [isListExpanded, setIsListExpanded] = useState(false); 
  const [isListHidden, setIsListHidden] = useState(false); 

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(todayStr);
  const [exportEndDate, setExportEndDate] = useState(todayStr);
  const [statsViewDate, setStatsViewDate] = useState(todayStr);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcelPro = (mode: 'today' | 'range') => {
    let filtered: OvertimeRequest[] = [];
    const department = "Automation";

    if (mode === 'today') {
        filtered = requests.filter(r => r.date === todayStr);
    } else {
        filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    }

    if (filtered.length === 0) return alert("Không tìm thấy dữ liệu đăng ký trong khoảng ngày đã chọn.");

    const workbook = XLSX.utils.book_new();
    const groupedByDate = filtered.reduce((acc, req) => {
        if (!acc[req.date]) acc[req.date] = [];
        acc[req.date].push(req);
        return acc;
    }, {} as Record<string, OvertimeRequest[]>);

    Object.keys(groupedByDate).sort().forEach((dateKey) => {
        const dayRequests = groupedByDate[dateKey];
        const sheetName = dateKey.split('-').reverse().join('-');
        const displayDate = dateKey.split('-').reverse().join('/');

        const ws_data: any[][] = [
            ["ĐĂNG KÝ LÀM THÊM TỰ NGUYỆN HÀNG NGÀY / APPLICATION FOR DAILY OVERTIME VOLUNTARY"],
            [],
            [`Bộ phận: ${department}`, ``, ``, ``, ``, ``, ``, `Ngày: ${displayDate}`],
            [`Tổng số người OT: ${dayRequests.length}`],
            [],
            ["STT", "Mã NV", "Họ tên", "Bắt đầu", "Kết thúc", "OT 150%", "OT 200%", "Lý do", "Ký tên", "Ghi chú"]
        ];

        dayRequests.forEach((req, idx) => {
            const date = new Date(req.date);
            const isWorking = dayConfigs[req.date] ?? (date.getDay() !== 0 && date.getDay() !== 6);
            ws_data.push([
                idx + 1, req.users?.employee_id || "", req.users?.name || "", req.start_time, req.end_time,
                isWorking ? req.total_hours : "", !isWorking ? req.total_hours : "", req.reason || "", "", ""
            ]);
        });

        const worksheet = XLSX.utils.aoa_to_sheet(ws_data);
        worksheet['!cols'] = [
          { wch: 5 }, { wch: 15 }, { wch: 25 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 30 }, { wch: 15 }, { wch: 15 }
        ];
        XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
    });

    XLSX.writeFile(workbook, `Bao_cao_OT_${mode === 'today' ? 'Today' : exportStartDate + '_to_' + exportEndDate}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");

    const alreadyRegistered = requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId);
    if (alreadyRegistered && !editingRequestId) {
        alert(`Nhân viên này đã được đăng ký OT cho ngày ${selectedDateStr.split('-').reverse().join('/')}.`);
        return;
    }

    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason: reason.trim(), 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      if (!isAdmin) setIsModalOpen(false);
      else {
        alert("Đã lưu đăng ký thành công!");
        setIsListExpanded(true); 
      }
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
    setIsListExpanded(false); 
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; employee_id: string; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, employee_id: req.users?.employee_id || 'N/A', count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const targetedRegistrations = useMemo(() => {
    return requests.filter(r => r.date === statsViewDate).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests, statsViewDate]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-20 md:h-28 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isActuallyWorking = dayConfigs[dateStr] ?? defaultIsWorking;

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-20 md:h-28 border border-gray-100 p-1 md:p-1.5 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30 z-10' : 'bg-white'} 
                  ${isPast ? 'opacity-40' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-0.5 md:gap-1 flex-wrap">
                        <span className={`text-[10px] md:text-sm font-black ${isToday ? 'bg-blue-600 text-white w-4 h-4 md:w-6 md:h-6 rounded-md flex items-center justify-center' : 'text-gray-700'}`}>
                            {d}
                        </span>

                        {(!isActuallyWorking || (isActuallyWorking && (dayOfWeek === 0 || dayOfWeek === 6))) && (
                            <span className={`text-[6px] md:text-[8px] font-black px-0.5 md:px-1 py-0.2 rounded uppercase border ${isActuallyWorking ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                                {isActuallyWorking ? 'LÀM' : 'NGHỈ'}
                            </span>
                        )}
                    </div>
                </div>
                <div className="flex-1 flex flex-col justify-start gap-0.5 mt-0.5 md:mt-1 overflow-hidden">
                    {myRequest && <div className="w-1 md:w-5 h-1 md:h-5 rounded bg-emerald-500 flex items-center justify-center shrink-0 shadow-sm"><UserIcon className="hidden md:block w-3 h-3 text-white" /></div>}
                    <div className="flex -space-x-1 md:-space-x-2 overflow-hidden">
                        {otherRequests.slice(0, 3).map((req, idx) => (
                            <div key={idx} className="w-1 md:w-4 h-1 md:h-4 rounded-full bg-indigo-100 border border-white flex items-center justify-center shrink-0">
                                <span className="hidden md:block text-[6px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                            </div>
                        ))}
                    </div>
                </div>
                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-0.5 right-0.5 bg-gray-100 text-gray-500 text-[6px] md:text-[9px] px-1 py-0.2 rounded font-black border border-gray-200 scale-75 md:scale-100 origin-bottom-right">
                        {dayRequestsLocal.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const dayRequestsInModal = useMemo(() => {
    return requests.filter(r => r.date === selectedDateStr);
  }, [requests, selectedDateStr]);

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-[1300px] mx-auto w-full px-2 md:px-0 pb-20">
        {/* TAB NAVIGATION */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white p-4 md:p-6 rounded-[1.2rem] md:rounded-[1.8rem] shadow-sm border border-gray-100">
            <div>
                <h2 className="text-lg md:text-2xl font-black text-gray-900 tracking-tight uppercase italic flex items-center gap-2">
                    Tăng ca 
                    {isNoel && <Snowflake className="w-5 h-5 text-blue-300 animate-spin-slow" />}
                    {isTet && <Sparkles className="w-5 h-5 text-yellow-400" />}
                </h2>
