                              <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="p-3 bg-rose-50 text-rose-600 rounded-xl border border-rose-100 hover:bg-rose-600 hover:text-white transition-all shadow-sm active:scale-90"><X className="w-5 h-5" /></button>
