        {/* PAGINATION FOOTER */}
        {filteredRequests.length > 0 && (
          <div className="bg-gray-50 border-t border-gray-100 p-8 flex flex-col sm:flex-row items-center justify-between gap-6 px-10">
            <div className="text-[11px] text-gray-400 font-black uppercase tracking-widest">
              Trang <span className="text-gray-900 tabular-nums">{currentPage}/{totalPages}</span> ({filteredRequests.length} đơn)
