            <div className="flex items-center gap-3">
              <button 
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all active:scale-90"
              >
                <ChevronsLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all active:scale-90"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>

              <div className="flex items-center gap-1 mx-4">
                 <div className={`w-11 h-11 rounded-2xl font-black text-sm flex items-center justify-center shadow-lg ${isNoel || isTet ? 'bg-red-600 text-white' : 'bg-blue-600 text-white'}`}>
                    {currentPage}
                 </div>
              </div>

              <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all active:scale-90"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages}
                className="p-3 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-30 hover:bg-blue-50 transition-all active:scale-90"
              >
                <ChevronsRight className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="flex justify-center gap-12 py-8 opacity-10 select-none">
         {isNoel && Array.from({length: 4}).map((_, i) => <Snowflake key={i} className="w-10 h-10 text-blue-400" />)}
         {isTet && Array.from({length: 4}).map((_, i) => <Gift key={i} className="w-10 h-10 text-yellow-500" />)}
      </div>
    </div>
  );
};

