// Theme Context để quản lý giao diện toàn cục
type ThemeType = 'default' | 'noel' | 'tet';
interface ThemeContextType {
  theme: ThemeType;
  setTheme: (t: ThemeType) => void;
}
export const ThemeContext = createContext<ThemeContextType>({ theme: 'default', setTheme: () => {} });

const SeasonalEffects = () => {
  const { theme } = useContext(ThemeContext);

  useEffect(() => {
    if (theme === 'default') return;

    const container = document.createElement('div');
    container.className = theme === 'noel' ? 'snow-container' : 'blossom-container';
    document.body.appendChild(container);

    const createParticle = () => {
      const p = document.createElement('div');
      p.className = theme === 'noel' ? 'snowflake' : 'petal';
      if (theme === 'noel') p.innerText = '❄';

      const startLeft = Math.random() * 100;
      const duration = Math.random() * 5 + 5;
      const size = Math.random() * 10 + 10;

      p.style.left = startLeft + 'vw';
      p.style.animationDuration = duration + 's';
      p.style.fontSize = size + 'px';
      if (theme === 'tet') {
        p.style.width = size + 'px';
        p.style.height = size + 'px';
        p.style.backgroundColor = Math.random() > 0.5 ? '#ffb7c5' : '#ffd700'; // Hồng đào hoặc Vàng mai
      }

      container.appendChild(p);
      setTimeout(() => p.remove(), duration * 1000);
    };

    const interval = setInterval(createParticle, 300);
    return () => {
      clearInterval(interval);
      if (document.body.contains(container)) document.body.removeChild(container);
    };
  }, [theme]);

  return null;
};

const MainLayout: React.FC<{ children: React.ReactNode; user: User; onLogout: () => void }> = ({ children, user, onLogout }) => {
  const location = useLocation();
