  const [showAiChat, setShowAiChat] = useState(false);
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [pendingBorrowCount, setPendingBorrowCount] = useState(0);
  const [pendingOTCount, setPendingOTCount] = useState(0);

  const festiveClass = theme === 'noel' ? 'festive-christmas' : (theme === 'tet' ? 'festive-tet' : 'festive-default');

  useEffect(() => {
    setCurrentPath(location.pathname);
    setIsSidebarOpen(false);
    document.body.className = `bg-gray-50 text-gray-900 ${festiveClass}`;
  }, [location, festiveClass]);

  const fetchCounts = useCallback(async () => {
    if (!user) return;
    const isAdmin = user.role === 'admin';
    try {
      let borrowQuery = supabase.from('requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) borrowQuery = borrowQuery.eq('user_id', user.id);
      const { count: bCount } = await borrowQuery;
      setPendingBorrowCount(bCount || 0);

      let otQuery = supabase.from('ot_requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) otQuery = otQuery.eq('user_id', user.id);
      const { count: oCount } = await otQuery;
      setPendingOTCount(oCount || 0);
    } catch (error) {
      console.error("Error fetching badge counts:", error);
    }
  }, [user]);

  useEffect(() => {
    fetchCounts();
    const handleRefresh = () => fetchCounts();
    window.addEventListener('refresh-counts', handleRefresh);
    const interval = setInterval(fetchCounts, 15000);
    return () => {
      window.removeEventListener('refresh-counts', handleRefresh);
      clearInterval(interval);
    };
  }, [fetchCounts]);

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!aiQuery.trim()) return;
    setAiLoading(true);
    const context = `User Role: ${user.role}. Current Theme: ${theme}.`;
    const result = await generateManagerInsight(context, aiQuery);
    setAiResponse(result || "Không có phản hồi.");
    setAiLoading(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50 transition-colors text-[clamp(0.75rem,2vw,1rem)]">
      <SeasonalEffects />
      <Sidebar 
        currentPath={currentPath} 
        onNavigate={(path) => window.location.hash = path} 
        onLogout={onLogout}
        userRole={user.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        pendingBorrowCount={pendingBorrowCount}
        pendingOTCount={pendingOTCount}
      />

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      <div className="flex-1 flex flex-col min-w-0">
        <Header user={user} onMenuClick={() => setIsSidebarOpen(true)} />
        <main 
          key={location.pathname}
          className="flex-1 p-4 md:p-8 overflow-x-hidden page-transition"
        >
          {children}
        </main>
      </div>

      <div className="fixed bottom-6 right-6 z-50">
        {!showAiChat ? (
          <button 
            onClick={() => setShowAiChat(true)}
            className={`w-14 h-14 md:w-16 md:h-16 rounded-full shadow-2xl flex items-center justify-center text-white hover:shadow-xl transition-all transform hover:scale-110 active:scale-95 border-4 border-white ${theme === 'tet' ? 'bg-gradient-to-r from-red-600 to-yellow-600 shadow-red-200' : 'bg-gradient-to-r from-blue-600 to-indigo-600 shadow-blue-200'}`}
          >
            <Bot className="w-7 h-7 md:w-8 md:h-8" />
          </button>
        ) : (
          <div className="bg-white rounded-3xl shadow-2xl w-[calc(100vw-2rem)] sm:w-96 flex flex-col border border-gray-200 overflow-hidden animate-fade-in-up origin-bottom-right shadow-black/10">
            <div className={`p-4 md:p-5 flex justify-between items-center text-white ${theme === 'tet' ? 'bg-gradient-to-r from-red-700 to-yellow-600' : 'bg-gradient-to-r from-blue-700 to-indigo-700'}`}>
              <div className="flex items-center gap-3">
                <Bot className="w-5 h-5" />
                <span className="font-black text-sm uppercase tracking-widest">{theme === 'tet' ? 'Trợ lý Tết Đoàn Viên 🧧' : 'Trợ lý AI'}</span>
              </div>
              <button onClick={() => setShowAiChat(false)} className="hover:bg-white/20 p-2 rounded-xl transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-5 h-64 md:h-80 overflow-y-auto bg-gray-50 text-xs md:text-sm leading-relaxed">
              {!aiResponse && !aiLoading && (
                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4 opacity-50">
                   <Sparkles className="w-10 h-10" />
                   <p className="text-center italic font-bold">Tôi có thể giúp gì cho công việc của bạn hôm nay?</p>
                </div>
              )}
              {aiLoading && (
                <div className="flex flex-col items-center justify-center h-full gap-3">
                   <div className={`animate-spin rounded-full h-10 w-10 border-b-4 ${theme === 'tet' ? 'border-red-600' : 'border-blue-600'}`}></div>
                   <span className="text-[10px] font-black uppercase text-gray-400 animate-pulse tracking-widest">Đang suy nghĩ...</span>
                </div>
              )}
              {aiResponse && (
                <div className="prose prose-sm max-w-none text-gray-800 whitespace-pre-line font-medium">
                  {aiResponse}
                </div>
              )}
            </div>

            <form onSubmit={handleAiAsk} className="p-4 border-t bg-white flex gap-2">
              <input 
                type="text" 
                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Hỏi về kho, nhân sự, OT..."
                className="flex-1 px-4 py-3 bg-gray-50 border-none rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-500/10 text-xs md:text-sm font-bold shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className={`${theme === 'tet' ? 'bg-red-700' : 'bg-indigo-700'} text-white p-3 md:p-4 rounded-2xl hover:opacity-90 disabled:opacity-50 transition-colors shadow-lg shadow-black/5`}
              >
                <Send className="w-5 h-5" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState<ThemeType>('default');

  useEffect(() => {
    // Tự động nhận diện theme dựa trên ngày tháng thực tế
    const now = new Date();
    const month = now.getMonth(); // 0 = Tháng 1, 11 = Tháng 12

    if (month === 11) {
      setTheme('noel');
    } else if (month === 0 || month === 1) {
      setTheme('tet');
    } else {
      setTheme('default');
    }

    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-6">
          <div className="relative">
            <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center">
              <Sparkles className="w-6 h-6 text-red-600 animate-pulse" />
            </div>
          </div>
          <div className="text-center">
            <p className="text-red-700 font-black text-xs uppercase tracking-[0.3em] italic">Team V1 System</p>
            <p className="text-gray-400 text-[10px] font-bold uppercase mt-2 animate-pulse">Đang tải tài nguyên chuyên dụng...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      <HashRouter>
        <Routes>
          <Route path="/login" element={
            !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
          } />

          <Route path="/dashboard" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/employees" element={
            user ? (
               user.role === 'admin' ? (
                  <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
               ) : <Navigate to="/dashboard" />
            ) : <Navigate to="/login" />
          } />

          <Route path="/tools" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/requests" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/history" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/overtime" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
        </Routes>
      </HashRouter>
    </ThemeContext.Provider>
  );
};

export default App;

import React, { useEffect, useState, useMemo, useContext } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon, Snowflake, Sparkles, Gift,
  ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, CalendarDays, Filter,
  AlertCircle, ArrowRight
} from 'lucide-react';
import { ThemeContext } from '../../../App';

interface RequestManagerProps { user: User; }

const ITEMS_PER_PAGE = 10;
const todayStr = new Date().toISOString().split('T')[0];

const ToolTableImage = ({ toolId, toolName }: { toolId: string, toolName: string }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  return (
    <div className="w-10 h-10 md:w-12 md:h-12 bg-white border border-gray-100 rounded-xl overflow-hidden flex items-center justify-center p-1 shadow-sm shrink-0">
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-4 h-4 text-gray-300" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterDate, setFilterDate] = useState(todayStr); 
  const [currentPage, setCurrentPage] = useState(1);

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      if (!silent) setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      rejected: 2,
      returned: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      const matchesDate = !filterDate || req.borrow_date.startsWith(filterDate);

      return matchesSearch && matchesStatus && matchesDate;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterDate]);

  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / ITEMS_PER_PAGE));
  const paginatedRequests = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredRequests.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredRequests, currentPage]);

  useEffect(() => {
    setCurrentPage(1); 
  }, [searchTerm, filterStatus, filterDate, activeTab]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    const oldRequests = [...requests];

    let newStatus: BorrowRequest['status'] = 'pending';
    if (action === 'approve') newStatus = 'approved';
    else if (action === 'reject') newStatus = 'rejected';
    else if (action === 'return') newStatus = 'returned';

    if (action === 'cancel') {
      setRequests(prev => prev.filter(r => r.id !== id));
    } else {
      setRequests(prev => prev.map(r => r.id === id ? { ...r, status: newStatus, returned_at: action === 'return' ? new Date().toISOString() : r.returned_at } : r));
    }

    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) {
           setRequests(oldRequests);
           throw new Error("Hết hàng trong kho");
        }
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
    } catch (e: any) {
      alert(e.message);
      setRequests(oldRequests);
    } finally {
      setProcessingId(null);
      fetchRequests(true);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-100 text-amber-700 border-amber-200', icon: <Timer className="w-3 h-3 animate-pulse" />, label: 'CHỜ DUYỆT' },
      approved: { color: 'bg-emerald-100 text-emerald-700 border-emerald-200', icon: <PackageCheck className="w-3 h-3" />, label: 'ĐANG MƯỢN' },
      returned: { color: 'bg-indigo-100 text-indigo-700 border-indigo-200', icon: <RotateCcw className="w-3 h-3" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-rose-100 text-rose-700 border-rose-200', icon: <AlertCircle className="w-3 h-3" />, label: 'TỪ CHỐI' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-lg text-[10px] font-black border shadow-sm ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in max-w-7xl mx-auto pb-10">
      {/* HEADER SECTION */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white p-5 md:p-8 rounded-[1.5rem] md:rounded-[2rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className={`p-4 rounded-2xl shadow-xl text-white transform hover:rotate-3 transition-transform ${isNoel ? 'bg-red-600' : (isTet ? 'bg-red-700' : 'bg-blue-600')}`}>
            <RefreshCw className="w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight uppercase flex items-center gap-2 italic">
               Phê duyệt mượn
               {isNoel && <Snowflake className="w-5 h-5 text-blue-300 animate-spin-slow" />}
               {isTet && <Sparkles className="w-5 h-5 text-yellow-400" />}
            </h2>
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1 opacity-70">Quản lý & Giám sát tài sản</p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200 shadow-inner w-full lg:w-auto">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`flex-1 lg:flex-none px-8 py-2.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? (isNoel || isTet ? 'bg-red-600 text-white shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500'}`}>Toàn bộ</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`flex-1 lg:flex-none px-8 py-2.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? (isNoel || isTet ? 'bg-red-600 text-white shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500'}`}>Của tôi</button>
        </div>
      </div>

      {/* FILTERS SECTION */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
        <div className="md:col-span-5 relative group">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 group-focus-within:text-blue-600 transition-colors" />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm mã NV, tên, thiết bị..." 
            className={`w-full pl-12 pr-4 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 transition-all shadow-sm ${isTet ? 'focus:ring-red-500/5 focus:border-red-500' : 'focus:ring-blue-500/5 focus:border-blue-500'}`} 
          />
        </div>

        <div className="md:col-span-4 flex items-center gap-2 bg-white p-2 border border-gray-100 rounded-2xl shadow-sm">
           <CalendarDays className="w-5 h-5 text-gray-400 ml-2" />
           <input 
            type="date" 
            value={filterDate} 
            onChange={e => setFilterDate(e.target.value)}
            className={`flex-1 bg-transparent border-none text-[11px] font-black uppercase outline-none cursor-pointer ${isTet ? 'focus:text-red-600' : 'focus:text-blue-600'}`}
           />
           {filterDate !== todayStr && (
             <button onClick={() => setFilterDate(todayStr)} className="px-3 py-1 bg-gray-100 text-[10px] font-black rounded-lg hover:bg-gray-200">HÔM NAY</button>
           )}
        </div>

        <div className="md:col-span-3">
          <select 
            value={filterStatus} 
            onChange={e => setFilterStatus(e.target.value)} 
            className={`w-full px-4 py-4 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-sm transition-all ${isTet ? 'focus:border-red-500' : 'focus:border-blue-500'}`}
          >
            <option value="all">Tất cả trạng thái</option>
            <option value="pending">⏳ Chờ duyệt</option>
            <option value="approved">📦 Đang mượn</option>
            <option value="returned">✅ Đã trả</option>
            <option value="rejected">❌ Từ chối</option>
          </select>
        </div>
      </div>

      {/* TABLE AREA */}
      <div className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden border border-gray-50 min-h-[400px]">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left border-separate border-spacing-0">
            <thead>
              <tr className="bg-gray-50/50 border-b border-gray-100">
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Người mượn</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Thiết bị</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest">Thời gian</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Trạng thái</th>
                <th className="px-10 py-6 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {loading ? (
                <tr><td colSpan={5} className="py-20 text-center"><Loader2 className="w-10 h-10 animate-spin text-gray-200 mx-auto" /></td></tr>
              ) : paginatedRequests.length === 0 ? (
                <tr><td colSpan={5} className="py-20 text-center text-gray-300 font-black uppercase text-xs">Không tìm thấy yêu cầu nào</td></tr>
              ) : (
                paginatedRequests.map((req) => (
                  <tr key={req.id} className="group hover:bg-white hover:shadow-[0_8px_30px_rgb(0,0,0,0.06)] hover:-translate-y-0.5 transition-all duration-300 border-l-4 border-l-transparent hover:border-l-blue-600 relative z-0 hover:z-10">
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className={`w-10 h-10 text-white rounded-xl flex items-center justify-center font-black text-sm shadow-md transition-transform group-hover:scale-110 ${isTet ? 'bg-red-800' : 'bg-indigo-600'}`}>{req.user_name.charAt(0)}</div>
                        <div>
                          <div className="font-black text-xs md:text-sm uppercase italic text-gray-900">{req.user_name}</div>
                          <div className="text-[10px] text-gray-400 font-black tracking-widest">{req.employee_id}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                        <div className="font-black text-xs md:text-sm uppercase tracking-tighter text-gray-700 transition-colors group-hover:text-blue-600">{req.tool_name}</div>
                      </div>
                    </td>
                    <td className="px-10 py-6 text-xs font-black text-gray-500 tabular-nums">
