// Theme Context để quản lý giao diện toàn cục
type ThemeType = 'default' | 'noel' | 'tet';
interface ThemeContextType {
  theme: ThemeType;
  setTheme: (t: ThemeType) => void;
}
export const ThemeContext = createContext<ThemeContextType>({ theme: 'default', setTheme: () => {} });

const SeasonalEffects = () => {
  const { theme } = useContext(ThemeContext);
  const [particles, setParticles] = useState<{ id: number; left: number; duration: number; size: number; color?: string }[]>([]);

  useEffect(() => {
    if (theme === 'default') {
      setParticles([]);
      return;
    }

    const interval = setInterval(() => {
      setParticles(prev => {
        const newParticle = {
          id: Date.now(),
          left: Math.random() * 100,
          duration: Math.random() * 6 + 4,
          size: theme === 'noel' ? Math.random() * 10 + 10 : Math.random() * 8 + 6,
          color: theme === 'tet' ? (Math.random() > 0.3 ? '#ffb7c5' : '#ffc0cb') : undefined
        };
        const next = [...prev, newParticle];
        // Giới hạn số lượng hạt để không lag
        if (next.length > 30) next.shift();
        return next;
      });
    }, 400);

    return () => clearInterval(interval);
  }, [theme]);

  if (theme === 'default') return null;

  return (
    <>
      {theme === 'tet' && <div className="peach-branch-decoration" />}
      <div className={theme === 'noel' ? 'snow-container' : 'blossom-container'}>
        {particles.map(p => (
          <div
            key={p.id}
            className={theme === 'noel' ? 'snowflake' : 'petal'}
            style={{
              left: `${p.left}vw`,
              animationDuration: `${p.duration}s`,
              fontSize: theme === 'noel' ? `${p.size}px` : undefined,
              width: theme === 'tet' ? `${p.size}px` : undefined,
              height: theme === 'tet' ? `${p.size * 1.5}px` : undefined,
              backgroundColor: p.color,
              boxShadow: theme === 'tet' ? '0 0 5px rgba(255,183,197,0.5)' : undefined
            }}
          >
            {theme === 'noel' ? '❄' : null}
          </div>
        ))}
      </div>
    </>
  );
};

const MainLayout: React.FC<{ children: React.ReactNode; user: User; onLogout: () => void }> = ({ children, user, onLogout }) => {
  const location = useLocation();
  const { theme } = useContext(ThemeContext);
  const [currentPath, setCurrentPath] = useState(location.pathname);
  const [showAiChat, setShowAiChat] = useState(false);
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [pendingBorrowCount, setPendingBorrowCount] = useState(0);
  const [pendingOTCount, setPendingOTCount] = useState(0);

  const festiveClass = theme === 'noel' ? 'festive-christmas' : (theme === 'tet' ? 'festive-tet' : 'festive-default');

  useEffect(() => {
    setCurrentPath(location.pathname);
    setIsSidebarOpen(false);
    document.body.className = `bg-gray-50 text-gray-900 ${festiveClass}`;
  }, [location, festiveClass]);

  const fetchCounts = useCallback(async () => {
    if (!user) return;
    const isAdmin = user.role === 'admin';
    try {
      let borrowQuery = supabase.from('requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) borrowQuery = borrowQuery.eq('user_id', user.id);
      const { count: bCount } = await borrowQuery;
      setPendingBorrowCount(bCount || 0);

      let otQuery = supabase.from('ot_requests').select('*', { count: 'exact', head: true }).eq('status', 'pending');
      if (!isAdmin) otQuery = otQuery.eq('user_id', user.id);
      const { count: oCount } = await otQuery;
      setPendingOTCount(oCount || 0);
    } catch (error) {
      console.error("Error fetching badge counts:", error);
    }
  }, [user]);

  useEffect(() => {
    fetchCounts();
    const handleRefresh = () => fetchCounts();
    window.addEventListener('refresh-counts', handleRefresh);
    const interval = setInterval(fetchCounts, 15000);
    return () => {
      window.removeEventListener('refresh-counts', handleRefresh);
      clearInterval(interval);
    };
  }, [fetchCounts]);

  const handleAiAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!aiQuery.trim()) return;
    setAiLoading(true);
    const context = `User Role: ${user.role}. Current Theme: ${theme}.`;
    const result = await generateManagerInsight(context, aiQuery);
    setAiResponse(result || "Không có phản hồi.");
    setAiLoading(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50 transition-colors text-[clamp(0.75rem,2vw,1rem)] relative">
      <SeasonalEffects />
      <Sidebar 
        currentPath={currentPath} 
        onNavigate={(path) => window.location.hash = path} 
        onLogout={onLogout}
        userRole={user.role}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
        pendingBorrowCount={pendingBorrowCount}
        pendingOTCount={pendingOTCount}
      />

      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      <div className="flex-1 flex flex-col min-w-0">
        <Header user={user} onMenuClick={() => setIsSidebarOpen(true)} />
        <main 
          key={location.pathname}
          className="flex-1 p-4 md:p-8 overflow-x-hidden page-transition"
        >
          {children}
        </main>
      </div>

      <div className="fixed bottom-6 right-6 z-50">
        {!showAiChat ? (
          <button 
            onClick={() => setShowAiChat(true)}
            className={`w-14 h-14 md:w-16 md:h-16 rounded-full shadow-2xl flex items-center justify-center text-white hover:shadow-xl transition-all transform hover:scale-110 active:scale-95 border-4 border-white ${theme === 'tet' ? 'bg-gradient-to-r from-red-600 to-yellow-600 shadow-red-200' : 'bg-gradient-to-r from-blue-600 to-indigo-600 shadow-blue-200'}`}
          >
            <Bot className="w-7 h-7 md:w-8 md:h-8" />
          </button>
        ) : (
          <div className="bg-white rounded-3xl shadow-2xl w-[calc(100vw-2rem)] sm:w-96 flex flex-col border border-gray-200 overflow-hidden animate-fade-in-up origin-bottom-right shadow-black/10">
            <div className={`p-4 md:p-5 flex justify-between items-center text-white ${theme === 'tet' ? 'bg-gradient-to-r from-red-700 to-yellow-600' : 'bg-gradient-to-r from-blue-700 to-indigo-700'}`}>
              <div className="flex items-center gap-3">
                <Bot className="w-5 h-5" />
                <span className="font-black text-sm uppercase tracking-widest">{theme === 'tet' ? 'Trợ lý Tết Đoàn Viên 🧧' : 'Trợ lý AI'}</span>
              </div>
              <button onClick={() => setShowAiChat(false)} className="hover:bg-white/20 p-2 rounded-xl transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-5 h-64 md:h-80 overflow-y-auto bg-gray-50 text-xs md:text-sm leading-relaxed">
              {!aiResponse && !aiLoading && (
                <div className="flex flex-col items-center justify-center h-full text-gray-400 gap-4 opacity-50">
                   <Sparkles className="w-10 h-10" />
                   <p className="text-center italic font-bold">Tôi có thể giúp gì cho công việc của bạn hôm nay?</p>
                </div>
              )}
              {aiLoading && (
                <div className="flex flex-col items-center justify-center h-full gap-3">
                   <div className={`animate-spin rounded-full h-10 w-10 border-b-4 ${theme === 'tet' ? 'border-red-600' : 'border-blue-600'}`}></div>
                   <span className="text-[10px] font-black uppercase text-gray-400 animate-pulse tracking-widest">Đang suy nghĩ...</span>
                </div>
              )}
              {aiResponse && (
                <div className="prose prose-sm max-w-none text-gray-800 whitespace-pre-line font-medium">
                  {aiResponse}
                </div>
              )}
            </div>

            <form onSubmit={handleAiAsk} className="p-4 border-t bg-white flex gap-2">
              <input 
                type="text" 
                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Hỏi về kho, nhân sự, OT..."
                className="flex-1 px-4 py-3 bg-gray-50 border-none rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-500/10 text-xs md:text-sm font-bold shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className={`${theme === 'tet' ? 'bg-red-700' : 'bg-indigo-700'} text-white p-3 md:p-4 rounded-2xl hover:opacity-90 disabled:opacity-50 transition-colors shadow-lg shadow-black/5`}
              >
                <Send className="w-5 h-5" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState<ThemeType>('default');

  useEffect(() => {
    // Tự động nhận diện theme dựa trên ngày tháng thực tế
    const now = new Date();
    const month = now.getMonth(); 

    if (month === 11) {
      setTheme('noel');
    } else if (month === 0 || month === 1) {
      setTheme('tet');
    } else {
      setTheme('default');
    }

    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-6">
          <div className="relative">
            <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center">
              <Sparkles className="w-6 h-6 text-red-600 animate-pulse" />
            </div>
          </div>
          <div className="text-center">
            <p className="text-red-700 font-black text-xs uppercase tracking-[0.3em] italic">Team V1 System</p>
            <p className="text-gray-400 text-[10px] font-bold uppercase mt-2 animate-pulse">Đang tải tài nguyên chuyên dụng...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      <HashRouter>
        <Routes>
          <Route path="/login" element={
            !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
          } />

          <Route path="/dashboard" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/employees" element={
            user ? (
               user.role === 'admin' ? (
                  <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
               ) : <Navigate to="/dashboard" />
            ) : <Navigate to="/login" />
          } />

          <Route path="/tools" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/requests" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/history" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/overtime" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
        </Routes>
      </HashRouter>
    </ThemeContext.Provider>
  );
};

export default App;

import React, { useContext } from 'react';
