}
export const ThemeContext = createContext<ThemeContextType>({ theme: 'default', setTheme: () => {} });

const SeasonalEffects = () => {
  const { theme } = useContext(ThemeContext);
  const [particles, setParticles] = useState<{ id: number; left: number; duration: number; size: number; color?: string; delay: number }[]>([]);

  useEffect(() => {
    if (theme === 'default') {
      setParticles([]);
      return;
    }

    // Khởi tạo một số hạt ban đầu
    const initialParticles = Array.from({ length: 15 }).map((_, i) => ({
      id: Date.now() + i,
      left: Math.random() * 100,
      duration: Math.random() * 8 + 6,
      size: theme === 'noel' ? Math.random() * 10 + 10 : Math.random() * 6 + 4,
      color: theme === 'tet' ? (Math.random() > 0.5 ? '#ffb7c5' : '#ff9db0') : undefined,
      delay: Math.random() * -10 // Bắt đầu ở các vị trí khác nhau
    }));
    setParticles(initialParticles);

    const interval = setInterval(() => {
      setParticles(prev => {
        const newParticle = {
          id: Date.now(),
          left: Math.random() * 100,
          duration: Math.random() * 8 + 6,
          size: theme === 'noel' ? Math.random() * 10 + 10 : Math.random() * 6 + 4,
          color: theme === 'tet' ? (Math.random() > 0.5 ? '#ffb7c5' : '#ff9db0') : undefined,
          delay: 0
        };
        const next = [...prev, newParticle];
        if (next.length > 40) next.shift(); // Giới hạn số lượng hạt
        return next;
      });
    }, 600);

    return () => clearInterval(interval);
  }, [theme]);

  if (theme === 'default') return null;

  return (
    <>
      {theme === 'tet' && <div className="peach-branch-decoration" />}
      <div className={theme === 'noel' ? 'snow-container' : 'blossom-container'}>
        {particles.map(p => (
          <div
            key={p.id}
            className={theme === 'noel' ? 'snowflake' : 'petal'}
            style={{
              left: `${p.left}vw`,
              animationDuration: `${p.duration}s`,
              animationDelay: `${p.delay}s`,
              fontSize: theme === 'noel' ? `${p.size}px` : undefined,
              width: theme === 'tet' ? `${p.size}px` : undefined,
              height: theme === 'tet' ? `${p.size * 1.5}px` : undefined,
              backgroundColor: p.color,
              boxShadow: theme === 'tet' ? '0 0 8px rgba(255,183,197,0.4)' : undefined
            }}
          >
            {theme === 'noel' ? '❄' : null}
          </div>
        ))}
      </div>
    </>
  );
};

