                   <Sparkles className="w-10 h-10" />
                   <p className="text-center italic font-bold">Tôi có thể giúp gì cho công việc của bạn hôm nay?</p>
                </div>
              )}
              {aiLoading && (
                <div className="flex flex-col items-center justify-center h-full gap-3">
                   <div className={`animate-spin rounded-full h-10 w-10 border-b-4 ${theme === 'tet' ? 'border-red-600' : 'border-blue-600'}`}></div>
                   <span className="text-[10px] font-black uppercase text-gray-400 animate-pulse tracking-widest">Đang suy nghĩ...</span>
                </div>
              )}
              {aiResponse && (
                <div className="prose prose-sm max-w-none text-gray-800 whitespace-pre-line font-medium">
                  {aiResponse}
                </div>
              )}
            </div>

            <form onSubmit={handleAiAsk} className="p-4 border-t bg-white flex gap-2">
              <input 
                type="text" 
                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Hỏi về kho, nhân sự, OT..."
                className="flex-1 px-4 py-3 bg-gray-50 border-none rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-500/10 text-xs md:text-sm font-bold shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className={`${theme === 'tet' ? 'bg-red-700' : 'bg-indigo-700'} text-white p-3 md:p-4 rounded-2xl hover:opacity-90 disabled:opacity-50 transition-colors shadow-lg shadow-black/5`}
              >
                <Send className="w-5 h-5" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState<ThemeType>('default');

  useEffect(() => {
    // Tự động nhận diện theme dựa trên ngày tháng thực tế
    const now = new Date();
    const month = now.getMonth(); 

    if (month === 11) {
      setTheme('noel');
    } else if (month === 0 || month === 1) {
      setTheme('tet');
    } else {
      setTheme('default');
    }

    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-gray-50">
        <div className="flex flex-col items-center gap-6">
          <div className="relative">
            <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center">
              <Sparkles className="w-6 h-6 text-red-600 animate-pulse" />
            </div>
          </div>
          <div className="text-center">
            <p className="text-red-700 font-black text-xs uppercase tracking-[0.3em] italic">Team V1 System</p>
            <p className="text-gray-400 text-[10px] font-bold uppercase mt-2 animate-pulse">Đang tải tài nguyên chuyên dụng...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      <SeasonalEffects />
      <HashRouter>
        <Routes>
          <Route path="/login" element={
            !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
          } />

          <Route path="/dashboard" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/employees" element={
            user ? (
               user.role === 'admin' ? (
                  <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
               ) : <Navigate to="/dashboard" />
            ) : <Navigate to="/login" />
          } />

          <Route path="/tools" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/requests" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/history" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/overtime" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
        </Routes>
      </HashRouter>
    </ThemeContext.Provider>
  );
};

export default App;

import React, { useEffect, useState, useMemo, useContext } from 'react';
import { supabase } from '../../lib/supabase';
import { Tool, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Wrench, MapPin, Edit, Plus, X, LayoutGrid, List, Minus, Search, Send, Loader2, Save, Image as ImageIcon, ChevronLeft, ChevronRight, AlertTriangle, Settings2, Trash2, Check, Boxes, Info, Tag, Hash, Archive, Snowflake, Sparkles, Gift, Filter
} from 'lucide-react';
import { ThemeContext } from '../../../App';

interface ToolInventoryProps {
  user: User;
}

const INITIAL_FORM_DATA = {
  name: '',
  category: '',
  quantity: 1,
  available: 1,
  description: '',
  location: '',
  image: '',
  status: 'active' as 'active' | 'inactive'
};

const ToolThumbnail = ({ src, alt, mode = 'grid' }: { src?: string | null, alt: string, mode?: 'grid' | 'table' }) => {
  const [error, setError] = useState(false);
  const { theme } = useContext(ThemeContext);
  const isTet = theme === 'tet';
  const isNoel = theme === 'noel';

  const isValidUrl = useMemo(() => {
    if (!src || typeof src !== 'string' || src.trim().length === 0) return false;
    return src.startsWith('http') || src.startsWith('data:');
  }, [src]);

  if (error || !isValidUrl) {
    return (
      <div className={`flex flex-col items-center justify-center bg-gray-50 w-full h-full rounded-xl border-2 border-dashed border-gray-200 transition-colors group-hover:bg-gray-100`}>
        <div className={`p-2 bg-white rounded-full shadow-sm border border-gray-100 flex items-center justify-center`}>
          <Wrench className={`${mode === 'grid' ? 'w-8 h-8' : 'w-5 h-5'} ${isTet ? 'text-red-400' : isNoel ? 'text-blue-400' : 'text-gray-400'}`} />
        </div>
        {mode === 'grid' && (
          <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-2">No Image</span>
        )}
      </div>
    );
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center bg-white rounded-xl overflow-hidden">
      <img
        src={src}
        alt={alt}
        onError={() => setError(true)}
        className={`max-w-full max-h-full object-contain ${mode === 'grid' ? 'p-4 group-hover:scale-110 transition-transform duration-500' : 'p-1'}`}
      />
      {mode === 'grid' && (
        <div className="absolute inset-0 bg-blue-600/0 group-hover:bg-blue-600/5 transition-colors pointer-events-none" />
      )}
    </div>
  );
};

export const ToolInventory: React.FC<ToolInventoryProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [tools, setTools] = useState<Tool[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 12;

  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  const isAdmin = user.role === 'admin';
  const [isManageMode, setIsManageMode] = useState(isAdmin);

  const [selectedQuantities, setSelectedQuantities] = useState<Record<string, number>>({});
  const [isBorrowing, setIsBorrowing] = useState(false);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentToolId, setCurrentToolId] = useState<string | null>(null);
  const [formData, setFormData] = useState(INITIAL_FORM_DATA);
  const [toolToDelete, setToolToDelete] = useState<string | null>(null);

  const isTet = theme === 'tet';
  const isNoel = theme === 'noel';

  useEffect(() => {
    fetchTools();
  }, []);

  const fetchTools = async () => {
    const { data } = await supabase.from('tools').select('*').order('created_at', { ascending: false });
    if (data) setTools(data as Tool[]);
  };

  const uniqueCategories = useMemo(() => {
    const cats = Array.from(new Set(tools.map(t => t.category).filter(Boolean)));
    return ['all', ...cats];
  }, [tools]);

  const filteredTools = useMemo(() => {
    return tools.filter(tool => {
      const matchesSearch = tool.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            tool.location?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = filterCategory === 'all' || tool.category === filterCategory;
      let matchesStatus = true;
      if (filterStatus === 'available') matchesStatus = tool.status === 'active' && tool.available > 0;
      else if (filterStatus === 'inactive') matchesStatus = tool.status === 'inactive';
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [tools, searchTerm, filterCategory, filterStatus]);

  const totalPages = Math.max(1, Math.ceil(filteredTools.length / pageSize));
  const startIndex = (currentPage - 1) * pageSize;
  const currentTools = filteredTools.slice(startIndex, startIndex + pageSize);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleSelection = (tool: Tool) => {
    if (isManageMode) return;
    const isAvailable = tool.status === 'active' && tool.available > 0;
    if (!isAvailable && !selectedQuantities[tool.id]) return;

    setSelectedQuantities(prev => {
        const current = prev[tool.id] || 0;
        if (current > 0) {
            const next = { ...prev };
            delete next[tool.id];
            return next;
        } else {
            return { ...prev, [tool.id]: 1 };
        }
    });
  };

  const updateQuantity = (id: string, delta: number, max: number, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setSelectedQuantities(prev => {
        const current = prev[id] || 0;
        const next = Math.max(0, Math.min(max, current + delta));
        const newQuantities = { ...prev };
        if (next === 0) delete newQuantities[id];
        else newQuantities[id] = next;
        return newQuantities;
    });
  };

  const handleBulkBorrow = async () => {
    const selectedToolIds = Object.keys(selectedQuantities);
    if (selectedToolIds.length === 0) return;
    setIsBorrowing(true);
    try {
      for (const toolId of selectedToolIds) {
        const tool = tools.find(t => t.id === toolId);
        const qty = selectedQuantities[toolId];
        if (!tool || tool.available < qty) continue;

        const requestsToInsert = Array.from({ length: qty }).map(() => ({
          user_id: user.id,
          user_name: user.name,
          employee_id: user.employeeCode,
          tool_id: tool.id,
          tool_name: tool.name,
          borrow_date: new Date().toISOString(),
          status: 'pending'
        }));

        const { error } = await supabase.from('requests').insert(requestsToInsert);
        if (error) throw error;
      }
      setMessage(`Gửi thành công yêu cầu mượn đồ!`);
      setSelectedQuantities({});
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      setTimeout(() => setMessage(null), 3000);
      await fetchTools();
    } catch (error: any) {
      alert("Lỗi: " + error.message);
    } finally {
      setIsBorrowing(false);
    }
  };

  const handleEditTool = (tool: Tool) => {
    setFormData({
      name: tool.name, category: tool.category, quantity: tool.quantity, available: tool.available,
      description: tool.description || '', location: tool.location || '', image: tool.image || '', status: tool.status
    });
    setIsEditing(true); setCurrentToolId(tool.id); setIsModalOpen(true);
  };

  const handleSaveTool = async () => {
    if (!formData.name) return alert('Vui lòng nhập tên công cụ');
    try {
      if (isEditing && currentToolId) {
        await supabase.from('tools').update(formData).eq('id', currentToolId);
      } else {
        await supabase.from('tools').insert([formData]);
      }
      await fetchTools(); setIsModalOpen(false);
      setMessage(isEditing ? 'Đã cập nhật' : 'Đã thêm mới');
      setTimeout(() => setMessage(null), 3000);
    } catch (error: any) { alert('Lỗi: ' + error.message); }
  };

  const totalSelectedCount = (Object.values(selectedQuantities) as number[]).reduce((sum: number, q: number) => sum + q, 0);

  return (
    <div className="space-y-6 relative flex flex-col min-h-[calc(100vh-140px)] pb-32 animate-fade-in max-w-[1600px] mx-auto w-full">
      {/* Header & Filter */}
      <div className="flex flex-col gap-5 bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
            <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl md:rounded-[1.8rem] shadow-xl text-white transform hover:rotate-3 transition-transform ${isTet ? 'bg-red-700 shadow-red-100' : isNoel ? 'bg-red-600 shadow-red-100' : 'bg-blue-600 shadow-blue-100'}`}>
                  <Wrench className="w-6 h-6 md:w-8 md:h-8" />
                </div>
                <div>
                    <h2 className="text-lg md:text-2xl lg:text-3xl font-black text-gray-900 tracking-tight leading-none uppercase italic">
                      Kho thiết bị
                      {isNoel && <Snowflake className="inline ml-2 w-5 h-5 text-blue-300 animate-spin-slow" />}
                      {isTet && <Sparkles className="inline ml-2 w-5 h-5 text-yellow-400" />}
                    </h2>
                    <p className="text-[10px] md:text-xs text-gray-400 font-black uppercase tracking-[0.2em] mt-1.5 opacity-70">Quản lý & mượn đồ tập trung</p>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row items-center gap-4 w-full lg:w-auto">
                {message && <div className="bg-emerald-600 text-white px-4 py-2.5 rounded-2xl text-[10px] font-black uppercase shadow-lg shadow-emerald-100 tracking-widest animate-fade-in">{message}</div>}

                {isAdmin && (
                    <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 w-full sm:w-auto">
                        <button onClick={() => {setIsManageMode(true); setSelectedQuantities({});}} className={`flex-1 sm:flex-none px-6 py-2.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all ${isManageMode ? (isTet || isNoel ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-blue-600 shadow-lg') : 'text-gray-500'}`}>QUẢN LÝ</button>
                        <button onClick={() => {setIsManageMode(false); setSelectedQuantities({});}} className={`flex-1 sm:flex-none px-6 py-2.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all ${!isManageMode ? (isTet || isNoel ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-blue-600 shadow-lg') : 'text-gray-500'}`}>MƯỢN ĐỒ</button>
                    </div>
                )}

                {isManageMode && (
                    <button 
                        onClick={() => {setFormData(INITIAL_FORM_DATA); setIsEditing(false); setIsModalOpen(true);}} 
                        className={`w-full sm:w-auto text-white px-6 py-3.5 rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center justify-center gap-2 border-b-4 ${isTet ? 'bg-red-700 border-red-900 shadow-red-100' : isNoel ? 'bg-red-600 border-red-800 shadow-red-100' : 'bg-blue-600 border-blue-800 shadow-blue-100'}`}
                    >
                        <Plus className="w-4 h-4" /> THÊM MỚI
                    </button>
                )}
            </div>
        </div>

        {/* Lọc danh mục dạng Chips */}
        <div className="flex flex-col gap-4 pt-4 border-t border-gray-100">
            <div className="flex flex-col md:flex-row gap-4">
                <div className="relative flex-1 group">
                    <Search className={`absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 transition-colors ${isTet || isNoel ? 'group-focus-within:text-red-600' : 'group-focus-within:text-blue-600'}`} />
                    <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Tìm tên thiết bị, vị trí..." className={`w-full pl-12 pr-4 py-4 bg-gray-50 border-none rounded-2xl text-xs md:text-sm font-bold outline-none focus:ring-4 transition-all ${isTet || isNoel ? 'focus:ring-red-600/10' : 'focus:ring-blue-600/10'}`} />
                </div>
                <div className="flex items-center gap-2 bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shrink-0">
                    <button onClick={() => setViewMode('grid')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'grid' ? (isTet || isNoel ? 'bg-white text-red-600 shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-400'}`}><LayoutGrid className="w-5 h-5" /></button>
                    <button onClick={() => setViewMode('table')} className={`p-2.5 rounded-xl transition-all ${viewMode === 'table' ? (isTet || isNoel ? 'bg-white text-red-600 shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-400'}`}><List className="w-5 h-5" /></button>
                </div>
            </div>

            <div className="flex items-center gap-3 overflow-x-auto no-scrollbar py-1">
                <div className="flex items-center gap-2 pr-4 border-r border-gray-100 shrink-0">
                    <Filter className="w-4 h-4 text-gray-400" />
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Danh mục:</span>
                </div>
                {uniqueCategories.map(cat => (
                    <button 
                        key={cat} 
                        onClick={() => setFilterCategory(cat)}
                        className={`shrink-0 px-5 py-2.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all border-2 ${
                            filterCategory === cat 
                            ? (isTet || isNoel ? 'bg-red-600 text-white border-red-600 shadow-lg' : 'bg-blue-600 text-white border-blue-600 shadow-lg') 
                            : 'bg-white text-gray-500 border-gray-100 hover:border-gray-300'
                        }`}
                    >
                        {cat === 'all' ? 'TẤT CẢ' : cat}
                    </button>
                ))}
            </div>
        </div>
      </div>

      {/* Main List */}
      <div className="flex-1 px-2 md:px-0">
        {viewMode === 'grid' ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-6 md:gap-8">
            {currentTools.map((tool: Tool) => {
                const qty = selectedQuantities[tool.id] || 0;
                const isSelected = qty > 0;
                const isAvailable = tool.status === 'active' && tool.available > 0;
                return (
                <Card 
                    key={tool.id} 
                    onClick={() => toggleSelection(tool)}
                    className={`cursor-pointer group hover:shadow-2xl transition-all p-0 border-4 overflow-hidden rounded-[2.5rem] md:rounded-[3rem] ${isSelected ? (isTet || isNoel ? 'border-red-600 ring-8 ring-red-50 bg-red-50/20' : 'border-blue-600 ring-8 ring-blue-50 bg-blue-50/20') : 'border-transparent bg-white shadow-xl'} ${!isManageMode && !isAvailable && !isSelected ? 'opacity-50 grayscale pointer-events-none' : ''}`}
                >
                    <div className="h-52 md:h-64 bg-white flex items-center justify-center relative border-b border-gray-50">
                      <ToolThumbnail src={tool.image} alt={tool.name} mode="grid" />
                      <div className="absolute top-4 right-4 flex flex-col gap-2 items-end">
                        <span className={`text-white text-[9px] font-black uppercase px-3 py-1.5 rounded-xl shadow-lg border-2 border-white ${tool.status === 'inactive' ? 'bg-rose-500' : tool.available > 0 ? 'bg-emerald-500' : 'bg-gray-400'}`}>
                            {tool.status === 'inactive' ? 'Sửa chữa' : tool.available > 0 ? `Sẵn: ${tool.available}` : 'Hết đồ'}
                        </span>
                        {isSelected && <div className={`${isTet || isNoel ? 'bg-red-600' : 'bg-blue-600'} text-white p-2.5 rounded-full shadow-xl animate-bounce`}><Check className="w-4 h-4" /></div>}
                      </div>
                    </div>
                    <div className="p-6 md:p-8 space-y-4">
                      <div className="space-y-1">
                        <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${isTet || isNoel ? 'text-red-600' : 'text-blue-600'}`}>{tool.category}</span>
                        <h3 className="font-black text-gray-900 text-xs md:text-sm lg:text-base line-clamp-2 h-12 leading-tight uppercase tracking-tight italic">{tool.name}</h3>
                      </div>
                      <div className="flex items-center justify-between text-[10px] text-gray-400 font-bold uppercase bg-gray-50 p-3 rounded-xl border border-gray-100">
                          <span className="flex items-center gap-1.5 truncate pr-2"><MapPin className={`w-3.5 h-3.5 shrink-0 ${isTet || isNoel ? 'text-red-400' : 'text-blue-400'}`} /> {tool.location || 'KHO CHUNG'}</span>
                          <span className="font-black text-gray-900 shrink-0">ID: {tool.id.slice(0, 5)}</span>
                      </div>
                      {isManageMode && (
                        <div className="flex gap-2 pt-1">
                           <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className={`flex-1 py-3.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg transition-all active:scale-95 ${isTet || isNoel ? 'bg-red-700 hover:bg-red-800' : 'bg-gray-900 hover:bg-black'} text-white`}>Chỉnh sửa</button>
                           <button onClick={(e) => { e.stopPropagation(); setToolToDelete(tool.id); }} className="p-3.5 bg-rose-50 text-rose-600 rounded-xl hover:bg-rose-600 hover:text-white transition-all"><Trash2 className="w-5 h-5" /></button>
                        </div>
                      )}
                      {!isManageMode && isSelected && (
                        <div className={`flex items-center justify-between p-2 rounded-2xl text-white shadow-xl animate-zoom-in border-4 border-white ${isTet || isNoel ? 'bg-red-600' : 'bg-blue-600'}`}>
                            <button onClick={(e) => updateQuantity(tool.id, -1, tool.available, e)} className="p-3 hover:bg-white/20 rounded-xl transition-colors"><Minus className="w-5 h-5" /></button>
