                        >
                            <td className="px-10 py-6">
                                <div className="flex items-center gap-5">
                                    <div className={`w-16 h-16 rounded-2xl bg-white border-2 overflow-hidden flex items-center justify-center p-1 shadow-sm transition-transform group-hover:scale-110 ${isSelected ? (isTet || isNoel ? 'border-red-200' : 'border-blue-200') : 'border-gray-100'}`}>
                                      <ToolThumbnail src={tool.image} alt={tool.name} mode="table" />
                                    </div>
                                    <div>
                                        <div className={`font-black uppercase text-xs md:text-sm italic tracking-tight transition-colors ${isSelected ? (isTet || isNoel ? 'text-red-700' : 'text-blue-700') : 'text-gray-900 group-hover:text-indigo-600'}`}>{tool.name}</div>
                                        <div className="text-[10px] text-gray-400 font-bold uppercase mt-1.5 flex items-center gap-1.5"><MapPin className={`w-4 h-4 ${isTet || isNoel ? 'text-red-400' : 'text-blue-400'}`} /> {tool.location || 'KHO'}</div>
                                    </div>
                                </div>
                            </td>
                            <td className="px-10 py-6"><span className="bg-gray-100 text-gray-500 px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">{tool.category}</span></td>
                            <td className="px-10 py-6 text-center text-xs md:text-sm font-black tabular-nums">
                                <span className={tool.available > 0 ? 'text-emerald-600' : 'text-rose-500'}>{tool.available}</span>
                                <span className="text-gray-200 mx-2">/</span>
                                <span className="text-gray-400">{tool.quantity}</span>
                            </td>
                            <td className="px-10 py-6 text-center">
                                {tool.status === 'active' ? (
                                    <span className="text-emerald-700 bg-emerald-50 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-100 shadow-sm">Sẵn sàng</span>
                                ) : (
                                    <span className="text-rose-700 bg-rose-50 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border border-rose-100 shadow-sm">Bảo trì</span>
                                )}
                            </td>
                            <td className="px-10 py-6 text-right">
                                <div className="flex justify-end items-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                    {isManageMode ? (
                                        <button onClick={(e) => { e.stopPropagation(); handleEditTool(tool); }} className={`p-3.5 rounded-xl shadow-lg transition-all active:scale-90 border-b-4 ${isTet || isNoel ? 'bg-red-700 border-red-900' : 'bg-gray-900 border-black'} text-white`}><Edit className="w-5 h-5"/></button>
