                <div className="flex items-center gap-2 pr-2">
                    <button 
                      onClick={() => setSelectedQuantities({})} 
                      className="px-4 py-2 text-white/50 hover:text-white text-[9px] font-black uppercase tracking-widest transition-colors"
                    >
