                      className={`text-white px-6 md:px-10 py-4 md:py-5 rounded-full text-[10px] md:text-xs font-black uppercase tracking-widest shadow-2xl flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50 transition-all ${isTet || isNoel ? 'bg-red-600 hover:bg-red-500 shadow-red-900/50' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-900/50'}`}
