            <div className={`flex justify-between items-center px-10 py-8 text-white border-b sticky top-0 z-20 ${isTet ? 'bg-red-700' : isNoel ? 'bg-red-600' : 'bg-blue-600'}`}>
              <div className="flex items-center gap-4">
                  <div className="w-14 h-14 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center text-white shadow-xl border border-white/30"><Edit className="w-7 h-7"/></div>
                  <div>
                    <h3 className="text-2xl md:text-3xl font-black uppercase tracking-tighter leading-none">{isEditing ? 'Cập nhật tài sản' : 'Thêm tài sản mới'}</h3>
