                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Vị trí kho</label>
                        <input type="text" placeholder="Kệ A, Tầng 1..." value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} className={`w-full px-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 transition-all shadow-sm ${isTet || isNoel ? 'focus:ring-red-600/10' : 'focus:ring-blue-600/10'}`}/>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Danh mục</label>
                        <input list="cat-suggestions" type="text" placeholder="Nhập hoặc chọn..." value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className={`w-full px-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 transition-all shadow-sm ${isTet || isNoel ? 'focus:ring-red-600/10' : 'focus:ring-blue-600/10'}`}/>
                        <datalist id="cat-suggestions">{uniqueCategories.filter(c => c !== 'all').map(c => <option key={c} value={c} />)}</datalist>
