                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Trạng thái</label>
                        <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})} className="w-full px-6 py-4 bg-white border border-gray-100 rounded-2xl text-[10px] md:text-xs font-black uppercase outline-none cursor-pointer shadow-sm appearance-none">
                            <option value="active">ĐANG HOẠT ĐỘNG</option>
                            <option value="inactive">ĐANG BẢO TRÌ</option>
                        </select>
                    </div>
                  </div>
              </div>

              {/* Stock Management */}
              <div className="bg-white p-10 rounded-[2.5rem] border border-gray-100 shadow-xl grid grid-cols-2 gap-10 ring-1 ring-black/5">
                    <div className="space-y-3">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Tổng trong kho</p>
                        <div className="flex items-center bg-gray-50 rounded-2xl p-2.5 border border-gray-100 shadow-inner">
                            <button onClick={() => setFormData({...formData, quantity: Math.max(0, formData.quantity - 1)})} className="p-4 bg-white rounded-xl shadow-md hover:bg-gray-900 hover:text-white transition-all active:scale-90"><Minus className="w-5 h-5"/></button>
                            <span className="flex-1 text-center font-black text-2xl tabular-nums text-gray-900">{formData.quantity}</span>
                            <button onClick={() => setFormData({...formData, quantity: formData.quantity + 1})} className="p-4 bg-white rounded-xl shadow-md hover:bg-gray-900 hover:text-white transition-all active:scale-90"><Plus className="w-5 h-5"/></button>
                        </div>
                    </div>
                    <div className="space-y-3">
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Sẵn cho mượn</p>
                        <div className="flex items-center bg-gray-50 rounded-2xl p-2.5 border border-gray-100 shadow-inner">
                            <button onClick={() => setFormData({...formData, available: Math.max(0, formData.available - 1)})} className="p-4 bg-white rounded-xl shadow-md hover:bg-gray-900 hover:text-white transition-all active:scale-90"><Minus className="w-5 h-5"/></button>
                            <span className={`flex-1 text-center font-black text-2xl tabular-nums ${formData.available > 0 ? 'text-emerald-600' : 'text-rose-500'}`}>{formData.available}</span>
                            <button onClick={() => setFormData({...formData, available: Math.min(formData.quantity, formData.available + 1)})} className="p-4 bg-white rounded-xl shadow-md hover:bg-gray-900 hover:text-white transition-all active:scale-90"><Plus className="w-5 h-5"/></button>
                        </div>
                    </div>
              </div>

              {/* Media & Desc */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <div className="space-y-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Ảnh đại diện (URL)</label>
                        <input type="text" placeholder="Dán link ảnh..." value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className={`w-full px-5 py-4 bg-white border border-gray-100 rounded-2xl text-xs font-bold outline-none focus:ring-4 transition-all shadow-sm ${isTet || isNoel ? 'focus:ring-red-600/10' : 'focus:ring-blue-600/10'}`}/>
                    </div>
                    <div className="h-44 rounded-[2.5rem] bg-white border-4 border-dashed border-gray-100 flex items-center justify-center overflow-hidden p-2 shadow-inner group">
                        {formData.image ? <img src={formData.image} alt="" className="h-full w-full object-contain p-2 group-hover:scale-110 transition-transform duration-500" onError={(e) => (e.currentTarget.src = 'https://via.placeholder.com/200?text=Loi+Anh')} /> : <ImageIcon className="w-12 h-12 text-gray-100 animate-pulse" />}
                    </div>
                 </div>
                 <div className="flex flex-col space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Mô tả / Ghi chú kỹ thuật</label>
                    <textarea placeholder="Nhập thông tin chi tiết..." value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="flex-1 w-full px-6 py-5 bg-white border border-gray-100 rounded-[2.5rem] text-xs font-bold outline-none resize-none shadow-inner focus:border-indigo-500 transition-all"/>
