                        <input list="cat-suggestions" type="text" placeholder="Nhập hoặc chọn..." value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className={`w-full px-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 transition-all shadow-sm ${isTet || isNoel ? 'focus:ring-red-600/10' : 'focus:ring-blue-600/10'}`}/>
