type ThemeType = 'default' | 'noel' | 'tet';
interface ThemeContextType {
  theme: ThemeType;
  setTheme: (t: ThemeType) => void;
}
export const ThemeContext = createContext<ThemeContextType>({ theme: 'default', setTheme: () => {} });

const SeasonalEffects = () => {
  const { theme } = useContext(ThemeContext);
  const [particles, setParticles] = useState<{ id: number; left: number; duration: number; size: number; delay: number; sway: number }[]>([]);

  useEffect(() => {
    if (theme === 'default') {
      setParticles([]);
      return;
    }

    const initialParticles = Array.from({ length: 25 }).map((_, i) => ({
      id: Math.random(),
      left: Math.random() * 100,
      duration: Math.random() * 8 + 6,
      size: theme === 'noel' ? Math.random() * 8 + 8 : Math.random() * 10 + 10,
      delay: Math.random() * -15,
      sway: Math.random() * 200 - 100
    }));
    setParticles(initialParticles);

    const interval = setInterval(() => {
      setParticles(prev => {
        const newParticle = {
          id: Date.now() + Math.random(),
          left: Math.random() * 100,
          duration: Math.random() * 8 + 6,
          size: theme === 'noel' ? Math.random() * 8 + 8 : Math.random() * 10 + 10,
          delay: 0,
          sway: Math.random() * 200 - 100
        };
        const next = [...prev, newParticle];
        if (next.length > 45) next.shift(); 
        return next;
      });
    }, 600);

    return () => clearInterval(interval);
  }, [theme]);

  if (theme === 'default') return null;

  return (
    <div className={theme === 'noel' ? 'snow-container' : 'blossom-container'}>
      {particles.map(p => (
        <div
          key={p.id}
          className={theme === 'noel' ? 'snowflake' : 'petal'}
          style={{
            left: `${p.left}vw`,
            animationDuration: `${p.duration}s`,
            animationDelay: `${p.delay}s`,
            fontSize: theme === 'noel' ? `${p.size}px` : undefined,
            width: theme === 'tet' ? `${p.size}px` : undefined,
            height: theme === 'tet' ? `${p.size * 1.3}px` : undefined,
            '--sway-amount': `${p.sway}px`
          } as any}
        >
          {theme === 'noel' ? '❄' : null}
        </div>
      ))}
    </div>
  );
};

