                    <div className="flex -space-x-1 md:-space-x-2 overflow-hidden">
                        {otherRequests.slice(0, 3).map((req, idx) => (
                            <div key={idx} className="w-1 md:w-4 h-1 md:h-4 rounded-full bg-indigo-100 border border-white flex items-center justify-center shrink-0">
                                <span className="hidden md:block text-[6px] font-bold text-indigo-600 uppercase">{req.users?.name?.charAt(0)}</span>
                            </div>
