                            <div><p className="text-[9px] font-semibold text-gray-400 uppercase">Tổng giờ tháng</p><p className="text-lg md:text-2xl font-black text-gray-900 tabular-nums">{teamMonthlyStats.totalHours.toFixed(1)}h</p></div>
                        </Card>
                        <Card className={`${isTet ? 'bg-red-700 shadow-red-200' : 'bg-indigo-600 shadow-indigo-200'} text-white border-none p-4 flex items-center gap-4 shadow-lg rounded-[1.2rem]`}>
