                                        <input type="date" value={exportStartDate} onChange={(e) => setExportStartDate(e.target.value)} className={`bg-transparent text-[10px] font-black outline-none uppercase w-full ${isTet ? 'text-red-700' : ''}`}/>
                                        <span className="text-gray-300">→</span>
                                        <input type="date" value={exportEndDate} onChange={(e) => setExportEndDate(e.target.value)} className={`bg-transparent text-[10px] font-black outline-none uppercase w-full ${isTet ? 'text-red-700' : ''}`}/>
                                    </div>
                                    <div className="grid grid-cols-2 gap-2 w-full sm:w-auto">
                                        <button onClick={() => handleExportExcelPro('range')} className={`flex items-center justify-center gap-1 px-4 py-3 ${isTet ? 'bg-red-700 border-red-900' : 'bg-indigo-700 border-indigo-900'} text-white rounded-xl text-[9px] font-bold uppercase shadow-lg border-b-4`}><FileDown className="w-3.5 h-3.5"/> Dải ngày</button>
                                        <button onClick={() => handleExportExcelPro('today')} className="flex items-center justify-center gap-1 px-4 py-3 bg-emerald-600 text-white rounded-xl text-[9px] font-bold uppercase shadow-lg border-b-4 border-emerald-800"><CalendarDays className="w-3.5 h-3.5"/> Hôm nay</button>
                                    </div>
