                value={aiQuery}
                onChange={(e) => setAiQuery(e.target.value)}
                placeholder="Tra cứu kho, OT, nhân sự..."
                className="flex-1 px-5 py-3.5 bg-gray-50 border-none rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-500/10 text-xs md:text-sm font-bold shadow-inner"
              />
              <button 
                type="submit" 
                disabled={aiLoading}
                className={`${theme === 'tet' ? 'bg-red-700' : 'bg-indigo-700'} text-white p-3.5 md:p-4 rounded-2xl hover:opacity-90 disabled:opacity-50 transition-all shadow-lg shadow-black/5 active:scale-90`}
              >
                <Send className="w-5 h-5" />
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState<ThemeType>('tet'); // Mặc định theme Tết

  useEffect(() => {
    const checkUser = async () => {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setUser(data.session.user);
      }
      setLoading(false);
    };
    checkUser();
  }, []);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('sb-session');
    setUser(null);
  };

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-white">
        <div className="flex flex-col items-center gap-6">
          <div className="relative">
            <div className="w-20 h-20 border-[6px] border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center">
              <Sparkles className="w-8 h-8 text-indigo-600 animate-pulse" />
            </div>
          </div>
          <div className="text-center">
            <h1 className="text-indigo-900 font-black text-2xl uppercase tracking-[0.2em] italic">Team V1</h1>
            <p className="text-gray-400 text-[10px] font-bold uppercase mt-2 animate-pulse tracking-widest">Initializing Smart Infrastructure...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      <SeasonalEffects />
      <HashRouter>
        <Routes>
          <Route path="/login" element={
            !user ? <LoginForm onLoginSuccess={handleLoginSuccess} /> : <Navigate to="/dashboard" />
          } />

          <Route path="/dashboard" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><DashboardStats /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/employees" element={
            user ? (
               user.role === 'admin' ? (
                  <MainLayout user={user} onLogout={handleLogout}><EmployeeList /></MainLayout>
               ) : <Navigate to="/dashboard" />
            ) : <Navigate to="/login" />
          } />

          <Route path="/tools" element={
            user ? <MainLayout user={user} onLogout={handleLogout}><ToolInventory user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/requests" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><RequestManager user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/history" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><HistoryLog user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="/overtime" element={
              user ? <MainLayout user={user} onLogout={handleLogout}><OvertimeRegistration user={user} /></MainLayout> : <Navigate to="/login" />
          } />

          <Route path="*" element={<Navigate to={user ? "/dashboard" : "/login"} />} />
        </Routes>
      </HashRouter>
    </ThemeContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useContext } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles, UserPlus, UserRoundPen, ChevronUp, Gift, Send, Save
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { ThemeContext } from '../../../App';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);
  const [isListExpanded, setIsListExpanded] = useState(false); 

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(todayStr);
  const [exportEndDate, setExportEndDate] = useState(todayStr);
  const [statsViewDate, setStatsViewDate] = useState(todayStr);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");

    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason: reason.trim(), 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
      alert("Lưu thành công!");
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
    setIsListExpanded(false); 
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-20 md:h-28 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isActuallyWorking = dayConfigs[dateStr] ?? defaultIsWorking;

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-20 md:h-28 border border-gray-100 p-1 md:p-1.5 relative transition-all active:bg-blue-100 lg:hover:bg-blue-50 cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50 ring-inset ring-1 md:ring-2 ring-blue-500/30 z-10' : 'bg-white'} 
                  ${isPast ? 'opacity-40' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start">
                    <span className={`text-[10px] md:text-sm font-black ${isToday ? 'bg-blue-600 text-white w-5 h-5 md:w-6 md:h-6 rounded-md flex items-center justify-center' : 'text-gray-700'}`}>
                        {d}
                    </span>
                    {!isActuallyWorking && (
                      <span className="text-[6px] md:text-[8px] font-black px-1 py-0.2 rounded uppercase bg-rose-50 text-rose-600 border border-rose-100">NGHỈ</span>
                    )}
                </div>
                <div className="flex-1 flex flex-col justify-start gap-0.5 mt-0.5 md:mt-1 overflow-hidden">
                    {myRequest && <div className="w-1.5 md:w-5 h-1.5 md:h-5 rounded bg-emerald-500 flex items-center justify-center shrink-0 shadow-sm"><UserIcon className="hidden md:block w-3 h-3 text-white" /></div>}
                </div>
                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-100 text-gray-500 text-[6px] md:text-[9px] px-1 py-0.2 rounded font-black border border-gray-200">
                        {dayRequestsLocal.length}
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const dayRequestsInModal = useMemo(() => requests.filter(r => r.date === selectedDateStr), [requests, selectedDateStr]);

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-[1300px] mx-auto w-full px-2 md:px-0 pb-20">
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white p-5 md:p-6 rounded-[1.5rem] md:rounded-[2rem] shadow-sm border border-gray-100">
            <div>
                <h2 className={`text-lg md:text-2xl font-black ${isTet ? 'text-red-700' : 'text-gray-900'} tracking-tight uppercase italic flex items-center gap-2`}>
                    Tăng ca 
                    {isTet && <Sparkles className="w-5 h-5 text-yellow-400" />}
                </h2>
                <p className="text-[10px] md:text-sm text-gray-500 font-medium italic mt-0.5">Quản lý chuyên nghiệp Team V1</p>
            </div>
            <div className="flex bg-gray-100/80 p-1 rounded-xl border border-gray-200 shadow-inner w-full lg:w-auto">
                {['calendar', 'personal', 'stats'].map(t => (
                    <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 lg:flex-none px-4 md:px-8 py-2 md:py-2.5 rounded-lg text-[10px] md:text-sm font-black transition-all uppercase tracking-widest ${activeTab === t ? (isTet ? 'bg-red-600 text-white shadow-sm' : 'bg-white text-indigo-600 shadow-sm') : 'text-gray-500 hover:text-gray-700'}`}>
                        {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                    </button>
                ))}
            </div>
        </div>

        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-100 shadow-lg rounded-[1.5rem] md:rounded-[2rem] bg-white">
                    <div className="flex items-center justify-between p-4 md:p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className={`p-2 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : ''}`}><ChevronLeft className="w-5 h-5"/></button>
                        <h3 className={`text-xs md:text-lg font-black uppercase tracking-widest ${isTet ? 'text-red-800' : 'text-gray-800'} italic`}>Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className={`p-2 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : ''}`}><ChevronRight className="w-5 h-5"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[8px] md:text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-3 md:py-4 text-center ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-100 gap-[0.5px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4">
                        <Card className={`${isTet ? 'bg-gradient-to-br from-red-600 to-red-800' : 'bg-gradient-to-br from-indigo-600 to-blue-700'} text-white border-none shadow-md rounded-[1.2rem] p-4`}>
                            <h3 className="text-[9px] font-bold uppercase opacity-80">Tổng giờ T{currentDate.getMonth()+1}</h3>
                            <div className="flex items-end gap-1 mt-1"><span className="text-xl md:text-3xl font-black">{myStats.total.toFixed(1)}</span><span className="text-[10px] font-bold opacity-70">h</span></div>
                        </Card>
                        <Card className="bg-white border-l-4 border-emerald-500 rounded-[1.2rem] p-4 shadow-sm flex items-center gap-3">
                            <div className="p-2 bg-emerald-50 rounded-xl text-emerald-600 hidden sm:block"><Check className="w-5 h-5"/></div>
                            <div><p className="text-[9px] font-bold text-gray-400 uppercase">Ngày đăng ký</p><p className="text-base md:text-xl font-black text-gray-900">{myStats.count}</p></div>
                        </Card>
                    </div>
                    <Card className="rounded-[1.5rem] md:rounded-[2rem] p-5 md:p-8 shadow-md border-none bg-white">
                        <div className="h-48 md:h-72 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 8, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 8, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc'}} />
                                    <Bar dataKey="hours" fill={isTet ? "#dc2626" : "#4f46e5"} radius={[2, 2, 0, 0]} barSize={8} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}
        </div>

        {/* POPUP ĐĂNG KÝ OT - Nâng cấp hỗ trợ di động */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-md animate-fade-in px-0 md:px-4">
                <div className="bg-white rounded-t-[2.5rem] md:rounded-[3rem] shadow-2xl w-full max-w-xl animate-slide-up overflow-hidden max-h-[92vh] flex flex-col border border-white/20">
                    <div className={`${isTet ? 'bg-gradient-to-r from-red-700 to-red-600' : 'bg-gradient-to-r from-indigo-700 to-blue-600'} p-6 md:p-8 flex justify-between items-center text-white shrink-0 shadow-lg`}>
                        <div className="flex flex-col">
                            <h3 className="text-lg md:text-2xl font-black uppercase tracking-tighter italic">Đăng ký OT</h3>
                            <p className="text-[10px] md:text-xs font-black uppercase tracking-widest opacity-60">Ngày {selectedDateStr.split('-').reverse().join('/')}</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-white/20 rounded-2xl transition-all"><X className="w-8 h-8"/></button>
                    </div>

                    <div className="p-6 md:p-10 space-y-6 overflow-y-auto no-scrollbar pb-12 bg-gray-50/50 flex-1">
                        {isAdmin && (
                            <div className="bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm space-y-4">
                                <div className="flex items-center gap-2">
                                    <Settings className={`w-4 h-4 ${isTet ? 'text-red-600' : 'text-indigo-600'}`} />
                                    <h4 className={`text-[10px] font-black uppercase tracking-widest ${isTet ? 'text-red-900' : 'text-indigo-900'}`}>Loại ngày công</h4>
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`py-4 rounded-2xl border-2 transition-all font-black text-[10px] uppercase ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0 || new Date(selectedDateStr).getDay() === 6))) ? 'bg-rose-600 text-white border-rose-600 shadow-lg' : 'bg-white text-gray-400 border-gray-100' }`}>NGHỈ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`py-4 rounded-2xl border-2 transition-all font-black text-[10px] uppercase ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0 && new Date(selectedDateStr).getDay() !== 6)) ? (isTet ? 'bg-red-700 border-red-700 shadow-lg text-white' : 'bg-indigo-600 text-white border-indigo-600 shadow-lg') : 'bg-white text-gray-400 border-gray-100' }`}>LÀM VIỆC</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="bg-white p-6 md:p-8 rounded-[2rem] border border-gray-100 shadow-xl space-y-6 relative overflow-hidden">
                                <div className={`absolute top-0 left-0 w-2 h-full ${isTet ? 'bg-red-600' : 'bg-indigo-600'}`}></div>

                                {isAdmin && (
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nhân sự:</label>
                                        <select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-[11px] font-black outline-none uppercase appearance-none cursor-pointer focus:bg-white transition-all">
                                            {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}
                                        </select>
                                    </div>
                                )}

                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-2">
                                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Bắt đầu:</label>
                                        <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-xs md:text-sm font-black text-gray-900 outline-none focus:bg-white transition-all"/>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Kết thúc:</label>
                                        <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-xs md:text-sm font-black text-gray-900 outline-none focus:bg-white transition-all"/>
                                    </div>
                                </div>

                                <div className="space-y-3">
                                    <div className="flex justify-between items-center px-1">
                                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Lý do:</label>
                                        <span className={`text-[11px] font-black px-3 py-1 rounded-xl border-2 ${isTet ? 'bg-red-50 text-red-700 border-red-100' : 'bg-indigo-50 text-indigo-700 border-indigo-100'}`}>{calculatedHours.toFixed(1)}h OT</span>
                                    </div>
                                    <textarea value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-5 bg-gray-50 border-2 border-transparent rounded-[1.5rem] text-xs md:text-sm h-28 resize-none outline-none font-bold text-gray-800 focus:bg-white transition-all" placeholder="Nhập nội dung công việc..."/>
                                </div>

                                <div className="flex gap-3 pt-2">
                                    {editingRequestId && (isAdmin || targetUserId === user.id) && (
                                        <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-4 bg-rose-50 text-rose-600 rounded-[1.2rem] border-2 border-rose-100 hover:bg-rose-600 hover:text-white transition-all"><Trash2 className="w-6 h-6"/></button>
                                    )}
                                    <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className={`flex-1 py-5 text-white font-black rounded-[1.5rem] shadow-2xl text-[11px] md:text-sm tracking-[0.2em] uppercase active:scale-95 disabled:opacity-50 transition-all border-b-4 ${isTet ? 'bg-red-700 border-red-900 shadow-red-200' : 'bg-indigo-700 border-indigo-900 shadow-indigo-200'}`}>
                                        {isSubmitting ? <Loader2 className="w-6 h-6 animate-spin mx-auto"/> : (editingRequestId ? 'LƯU THAY ĐỔI' : 'ĐĂNG KÝ NGAY')}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-10 text-center border border-white/20">
                    <div className="w-20 h-20 bg-rose-100 text-rose-600 mx-auto mb-6 rounded-[1.5rem] flex items-center justify-center shadow-xl rotate-12"><Trash2 className="w-10 h-10" /></div>
                    <h3 className="text-xl font-black text-gray-900 mb-2 uppercase italic leading-none">Hủy Đăng Ký?</h3>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mb-8">Hành động này không thể hoàn tác.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-4 bg-rose-600 text-white font-black rounded-[1.2rem] text-[11px] uppercase tracking-widest shadow-lg active:scale-95">XÁC NHẬN XÓA</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-4 bg-white text-gray-400 font-black rounded-[1.2rem] border-2 border-gray-100 text-[11px] uppercase tracking-widest active:scale-95">QUAY LẠI</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useContext } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles, UserPlus, UserRoundPen, ChevronUp, Gift, Send, Save
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { ThemeContext } from '../../../App';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);
  const [isListExpanded, setIsListExpanded] = useState(false); 

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(todayStr);
  const [exportEndDate, setExportEndDate] = useState(todayStr);
  const [statsViewDate, setStatsViewDate] = useState(todayStr);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;

  const isTet = theme === 'tet';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleExportExcelPro = (mode: 'today' | 'range') => {
    let filtered: OvertimeRequest[] = [];
    if (mode === 'today') {
        filtered = requests.filter(r => r.date === todayStr);
    } else {
        filtered = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    }

    if (filtered.length === 0) return alert("Không tìm thấy dữ liệu.");

    const workbook = XLSX.utils.book_new();
    const grouped = filtered.reduce((acc, req) => {
        if (!acc[req.date]) acc[req.date] = [];
        acc[req.date].push(req);
        return acc;
    }, {} as Record<string, OvertimeRequest[]>);

    Object.keys(grouped).sort().forEach(date => {
        const data = grouped[date].map((r, i) => ({
            "STT": i + 1,
            "Mã NV": r.users?.employee_id,
            "Họ tên": r.users?.name,
            "Bắt đầu": r.start_time,
            "Kết thúc": r.end_time,
            "Tổng giờ": r.total_hours,
            "Lý do": r.reason
        }));
        const ws = XLSX.utils.json_to_sheet(data);
        XLSX.utils.book_append_sheet(workbook, ws, date.split('-').reverse().join('-'));
    });
    XLSX.writeFile(workbook, `OT_Report_${mode}.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");

    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason: reason.trim(), 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
      alert("Lưu thành công!");
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
    setIsListExpanded(false); 
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  // Logic Thống kê Nhóm
  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const targetedRegistrations = useMemo(() => {
    return requests.filter(r => r.date === statsViewDate).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests, statsViewDate]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-20 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const isActuallyWorking = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0 && dateObj.getDay() !== 6);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-20 md:h-32 border border-gray-100 p-1.5 md:p-2.5 relative transition-all cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50 ring-inset ring-2 ring-blue-500/30 z-10' : 'bg-white hover:bg-gray-50'} 
                  ${isPast ? 'opacity-60' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start">
                    <span className={`text-[10px] md:text-sm font-black ${isToday ? 'bg-blue-600 text-white w-5 h-5 md:w-7 md:h-7 rounded-lg flex items-center justify-center' : 'text-gray-700'}`}>
                        {d}
                    </span>
                    {!isActuallyWorking && (
                      <span className="text-[6px] md:text-[8px] font-black px-1 py-0.5 rounded uppercase bg-rose-50 text-rose-600 border border-rose-100">NGHỈ</span>
                    )}
                </div>

                {/* HIỂN THỊ NGƯỜI ĐĂNG KÝ TRÊN Ô LỊCH */}
                <div className="flex-1 flex flex-col justify-start gap-1 mt-1 md:mt-2 overflow-hidden">
                    {myRequest && (
                      <div className="flex items-center gap-1.5 bg-emerald-50 text-emerald-700 px-1.5 py-0.5 rounded border border-emerald-100 shrink-0">
                        <UserIcon className="w-2 h-2 md:w-3 md:h-3" />
                        <span className="text-[6px] md:text-[9px] font-black truncate uppercase">BẠN: {myRequest.total_hours}h</span>
                      </div>
                    )}
                    <div className="flex flex-wrap gap-1">
                      {otherRequests.slice(0, 4).map((req, idx) => (
                        <div key={idx} className="w-3 h-3 md:w-5 md:h-5 rounded-full bg-indigo-100 text-indigo-600 border border-white flex items-center justify-center shrink-0 shadow-sm">
                           <span className="text-[5px] md:text-[8px] font-bold uppercase">{req.users?.name?.charAt(0)}</span>
                        </div>
                      ))}
                      {otherRequests.length > 4 && (
                        <div className="w-3 h-3 md:w-5 md:h-5 rounded-full bg-gray-100 text-gray-400 border border-white flex items-center justify-center shrink-0">
                           <span className="text-[5px] md:text-[7px] font-black">+{otherRequests.length - 4}</span>
                        </div>
                      )}
                    </div>
                </div>

                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-800 text-white text-[6px] md:text-[9px] px-1.5 py-0.5 rounded-full font-black shadow-lg">
                        {dayRequestsLocal.length} NV
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const dayRequestsInModal = useMemo(() => requests.filter(r => r.date === selectedDateStr), [requests, selectedDateStr]);

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-[1300px] mx-auto w-full px-2 md:px-0 pb-20">
        {/* TAB HEADER */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white p-5 md:p-6 rounded-[1.5rem] md:rounded-[2rem] shadow-sm border border-gray-100">
            <div>
                <h2 className={`text-lg md:text-2xl font-black ${isTet ? 'text-red-700' : 'text-gray-900'} tracking-tight uppercase italic flex items-center gap-2`}>
                    Tăng ca 
                    {isTet && <Sparkles className="w-5 h-5 text-yellow-400" />}
                </h2>
                <p className="text-[10px] md:text-sm text-gray-500 font-medium italic mt-0.5">Hệ thống điều hành chuyên nghiệp</p>
            </div>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200 shadow-inner w-full lg:w-auto">
                {['calendar', 'personal', 'stats'].map(t => (
                    <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 lg:flex-none px-6 md:px-10 py-2.5 rounded-lg text-[10px] md:text-sm font-black transition-all uppercase tracking-widest ${activeTab === t ? (isTet ? 'bg-red-600 text-white shadow-md' : 'bg-white text-blue-600 shadow-md') : 'text-gray-500 hover:text-gray-700'}`}>
                        {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                    </button>
                ))}
            </div>
        </div>

        {/* TAB CONTENT */}
        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-100 shadow-lg rounded-[1.5rem] md:rounded-[2rem] bg-white">
                    <div className="flex items-center justify-between p-4 md:p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className={`p-2 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : ''}`}><ChevronLeft className="w-6 h-6"/></button>
                        <h3 className={`text-sm md:text-xl font-black uppercase tracking-widest ${isTet ? 'text-red-800' : 'text-gray-800'} italic`}>Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className={`p-2 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : ''}`}><ChevronRight className="w-6 h-6"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[8px] md:text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-4 text-center ${i >= 5 ? 'text-rose-400' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-100 gap-[0.5px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
