                </div>

                <div className="flex-1 flex flex-col justify-start gap-1 mt-1 md:mt-2 overflow-hidden">
                    {myRequest && (
                      <div className="flex items-center gap-1.5 bg-emerald-600 text-white px-2 py-0.5 rounded-full shrink-0 shadow-sm">
                        <UserIcon className="w-2 h-2 md:w-3 md:h-3" />
                        <span className="text-[6px] md:text-[9px] font-black truncate uppercase">BẠN: {myRequest.total_hours}h</span>
                      </div>
                    )}
                    <div className="flex flex-wrap gap-1">
                      {otherRequests.slice(0, 5).map((req, idx) => (
                        <div key={idx} className="w-4 h-4 md:w-6 md:h-6 rounded-full bg-indigo-600 text-white border-2 border-white flex items-center justify-center shrink-0 shadow-md">
                           <span className="text-[6px] md:text-[9px] font-bold uppercase">{req.users?.name?.charAt(0)}</span>
                        </div>
                      ))}
                      {otherRequests.length > 5 && (
                        <div className="w-4 h-4 md:w-6 md:h-6 rounded-full bg-gray-800 text-white border-2 border-white flex items-center justify-center shrink-0">
                           <span className="text-[6px] md:text-[8px] font-black">+{otherRequests.length - 5}</span>
                        </div>
                      )}
                    </div>
                </div>

                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-900 text-white text-[7px] md:text-[10px] px-2 py-0.5 rounded-full font-black shadow-lg border border-white/20">
                        {dayRequestsLocal.length} NV
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  const dayRequestsInModal = useMemo(() => requests.filter(r => r.date === selectedDateStr), [requests, selectedDateStr]);

  return (
