        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white transform hover:rotate-3 transition-transform ${isTet ? 'bg-red-700' : 'bg-blue-600'}`}>
                    <Clock className="w-6 h-6 md:w-8 md:h-8" />
                </div>
                <div>
                    <h2 className={`text-lg md:text-2xl font-black ${isTet ? 'text-red-800' : 'text-gray-900'} tracking-tight uppercase italic flex items-center gap-2`}>
                        Tăng ca 
                        {isTet && <Sparkles className="w-5 h-5 text-yellow-500" />}
                    </h2>
                    <p className="text-[10px] md:text-sm text-gray-500 font-black uppercase tracking-widest mt-0.5">Manager Tool V1</p>
                </div>
            </div>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200 shadow-inner w-full lg:w-auto">
                {['calendar', 'personal', 'stats'].map(t => (
                    <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 lg:flex-none px-4 md:px-8 py-2.5 rounded-lg text-[10px] md:text-sm font-black transition-all uppercase tracking-widest ${activeTab === t ? (isTet ? 'bg-red-700 text-white shadow-md' : 'bg-white text-blue-700 shadow-md') : 'text-gray-500 hover:text-gray-700'}`}>
                        {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                    </button>
                ))}
            </div>
        </div>

        {/* TAB CONTENT */}
        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border border-gray-100 shadow-lg rounded-[1.5rem] md:rounded-[2rem] bg-white">
                    <div className="flex items-center justify-between p-4 md:p-6 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className={`p-2 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : ''}`}><ChevronLeft className="w-6 h-6"/></button>
                        <h3 className={`text-sm md:text-xl font-black uppercase tracking-widest ${isTet ? 'text-red-900' : 'text-gray-900'} italic`}>Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className={`p-2 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : ''}`}><ChevronRight className="w-6 h-6"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50 text-[8px] md:text-[10px] font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-4 text-center ${i >= 5 ? 'text-rose-500' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-100 gap-[0.5px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-4 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                        <Card className={`${isTet ? 'bg-gradient-to-br from-red-700 to-red-900 shadow-red-200' : 'bg-gradient-to-br from-blue-700 to-indigo-900'} text-white border-none shadow-xl rounded-[1.5rem] p-5`}>
                            <h3 className="text-[10px] font-black uppercase opacity-80 tracking-widest">Tổng giờ mượn T{currentDate.getMonth()+1}</h3>
                            <div className="flex items-end gap-1 mt-2"><span className="text-3xl md:text-5xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-xs font-bold opacity-70">h</span></div>
                        </Card>
                        <Card className="bg-white border-l-4 border-emerald-600 rounded-[1.5rem] p-5 shadow-sm flex items-center gap-4">
                            <div className="p-3 bg-emerald-100 rounded-2xl text-emerald-700"><Check className="w-6 h-6"/></div>
                            <div><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Ngày đăng ký</p><p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{myStats.count}</p></div>
                        </Card>
                    </div>
                    <Card className="rounded-[2rem] p-6 md:p-10 shadow-md border-none bg-white">
                        <div className="h-64 md:h-96 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc'}} />
                                    <Bar dataKey="hours" fill={isTet ? "#dc2626" : "#2563eb"} radius={[4, 4, 0, 0]} barSize={12} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-6 animate-fade-in-up pb-10">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <Card className="bg-white p-6 border-none shadow-sm rounded-[1.5rem] flex items-center gap-5">
                            <div className={`p-4 ${isTet ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'} rounded-2xl`}><Users className="w-8 h-8"/></div>
                            <div><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Thành viên OT</p><p className="text-2xl md:text-4xl font-black text-gray-900">{teamMonthlyStats.activeMembers}</p></div>
                        </Card>
                        <Card className="bg-white p-6 border-none shadow-sm rounded-[1.5rem] flex items-center gap-5">
                            <div className="p-4 bg-emerald-100 text-emerald-700 rounded-2xl"><Timer className="w-8 h-8"/></div>
                            <div><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Tổng giờ nhóm</p><p className="text-2xl md:text-4xl font-black text-gray-900">{teamMonthlyStats.totalHours.toFixed(1)}h</p></div>
                        </Card>
                        <Card className={`${isTet ? 'bg-red-800 shadow-red-200' : 'bg-indigo-800 shadow-indigo-200'} text-white p-6 border-none shadow-xl rounded-[1.5rem] flex items-center gap-5`}>
                            <div className="p-4 bg-white/20 rounded-2xl"><Target className="w-8 h-8"/></div>
                            <div><p className="text-[10px] font-black text-white/70 uppercase tracking-widest">Hôm nay</p><p className="text-2xl md:text-4xl font-black">{requests.filter(r => r.date === todayStr).length} NV</p></div>
                        </Card>
                    </div>

                    <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
                        <div className="xl:col-span-8 space-y-6">
                            <Card className="rounded-[2.5rem] p-0 overflow-hidden shadow-xl border-none bg-white">
                                <div className="p-6 md:p-8 bg-gray-50/50 border-b border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                                    <div>
                                        <h4 className="text-lg font-black text-gray-900 uppercase flex items-center gap-3 italic"><Clock className="text-blue-700"/> Chi tiết đăng ký</h4>
                                        <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Dữ liệu ngày {statsViewDate.split('-').reverse().join('/')}</p>
                                    </div>
                                    <div className="flex items-center gap-2 bg-white px-4 py-2 rounded-xl border border-gray-200 shadow-sm w-full md:w-auto">
                                        <CalendarIcon className="w-4 h-4 text-gray-400" />
                                        <input type="date" value={statsViewDate} onChange={(e) => setStatsViewDate(e.target.value)} className="bg-transparent text-[11px] font-black outline-none uppercase cursor-pointer text-gray-900"/>
                                    </div>
                                </div>
                                <div className="p-6 space-y-3 overflow-y-auto max-h-[500px] no-scrollbar">
                                    {targetedRegistrations.length === 0 ? (
                                        <div className="py-20 text-center flex flex-col items-center gap-4 opacity-30 grayscale">
                                            <Info className="w-16 h-16 text-gray-900"/>
                                            <p className="font-black uppercase text-xs tracking-widest text-gray-900">Không có dữ liệu cho ngày này</p>
