                                            <div key={idx} className="p-4 md:p-6 rounded-[1.5rem] bg-gray-50 border-2 border-transparent hover:border-blue-200 hover:bg-white transition-all flex items-center justify-between group">
                                                <div className="flex items-center gap-5">
                                                    <div className={`w-12 h-12 md:w-16 md:h-16 text-white rounded-2xl flex items-center justify-center font-black text-lg md:text-2xl shadow-lg ${isTet ? 'bg-red-700' : 'bg-blue-700'}`}>{req.users?.name?.charAt(0)}</div>
                                                    <div>
                                                        <h5 className="font-black text-gray-900 text-sm md:text-lg uppercase italic leading-none">{req.users?.name}</h5>
                                                        <div className="flex items-center gap-3 mt-2">
                                                          <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{req.users?.employee_id}</span>
                                                          <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                                                          <span className="text-[10px] font-black text-blue-700 uppercase">{req.start_time} - {req.end_time}</span>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="text-right">
                                                    <p className="text-[10px] font-black text-gray-500 uppercase mb-1">Số giờ OT</p>
                                                    <span className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{req.total_hours.toFixed(1)}</span>
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                            </Card>
                        </div>

                        <div className="xl:col-span-4 space-y-6">
                            <Card className="rounded-[2.5rem] p-0 overflow-hidden shadow-xl border-none bg-white">
                                <div className={`p-6 md:p-8 ${isTet ? 'bg-red-800' : 'bg-blue-800'} text-white`}>
                                    <h4 className="text-sm md:text-lg font-black uppercase flex items-center gap-3 italic"><Award className="text-yellow-400 w-6 h-6" /> Bảng xếp hạng OT</h4>
                                    <p className="text-[10px] font-black opacity-60 uppercase tracking-widest mt-1">Tháng {currentDate.getMonth()+1}</p>
                                </div>
                                <div className="p-4 md:p-6 space-y-3">
                                    {topRankings.map((emp, idx) => (
                                        <div key={idx} className={`p-4 rounded-2xl border-2 flex items-center gap-4 transition-all ${idx === 0 ? 'bg-yellow-50 border-yellow-200' : 'bg-white border-gray-100'}`}>
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-sm shrink-0 ${idx === 0 ? 'bg-yellow-500 text-white' : idx === 1 ? 'bg-slate-300 text-white' : idx === 2 ? 'bg-orange-300 text-white' : 'bg-gray-100 text-gray-500'}`}>{idx + 1}</div>
                                            <div className="flex-1 min-w-0">
                                                <h5 className="font-black text-gray-900 text-xs md:text-sm truncate uppercase">{emp.name}</h5>
                                                <p className="text-[9px] font-black text-gray-500 uppercase mt-0.5">{emp.count} ngày OT</p>
                                            </div>
                                            <div className="text-right">
                                                <span className={`text-lg md:text-xl font-black ${idx === 0 ? 'text-yellow-700' : 'text-blue-800'} tabular-nums`}>{emp.hours.toFixed(1)}</span>
                                                <span className="text-[9px] font-black text-gray-400 ml-1 uppercase">h</span>
