                                    <div className="flex items-center gap-4">
                                        <div className="p-3 bg-white/10 rounded-xl"><FileSpreadsheet className="w-6 h-6 text-emerald-400"/></div>
                                        <div><h4 className="font-black uppercase italic text-sm">Xuất báo cáo</h4><p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-1">Excel Report Pro</p></div>
