import React, { useState, useEffect, useMemo, useContext } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles, UserPlus, UserRoundPen, ChevronUp, Gift, Send, Save
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { ThemeContext } from '../../../App';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);
  const [isListExpanded, setIsListExpanded] = useState(false); 

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(todayStr);
  const [exportEndDate, setExportEndDate] = useState(todayStr);
  const [statsViewDate, setStatsViewDate] = useState(todayStr);

  const isAdmin = user.role === 'admin';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
  const isTet = theme === 'tet';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const isViewOnly = !isAdmin && targetUserId !== user.id;

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, dayConfigs, currentSelectedRequest, targetUserId]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");

    setIsSubmitting(true);
    const payload = {
        user_id: targetUserId, 
        date: selectedDateStr, 
        start_time: startTime,
        end_time: endTime, 
        total_hours: calculatedHours, 
        reason: reason.trim(), 
        status: 'approved' 
    };
    try {
      const res = editingRequestId 
        ? await supabase.from('ot_requests').update(payload).eq('id', editingRequestId)
        : await supabase.from('ot_requests').insert([payload]);
      if (res.error) throw res.error;
      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
    setIsListExpanded(false); 
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const activeMembers = new Set(monthlyApproved.map(r => r.user_id)).size;
    return { totalHours, activeMembers };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, count: 0 };
        employeeMap[id].hours += Number(req.total_hours || 0);
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const targetedRegistrations = useMemo(() => {
    return requests.filter(r => r.date === statsViewDate).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests, statsViewDate]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-20 md:h-32 bg-gray-50/50 border border-gray-100/50 opacity-40"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const otherRequests = dayRequestsLocal.filter(r => r.user_id !== user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const isActuallyWorking = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0 && dateObj.getDay() !== 6);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-24 md:h-36 border border-gray-100 p-1 md:p-2 relative transition-all cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-blue-50/80 ring-inset ring-2 ring-blue-600/40 z-10' : 'bg-white hover:bg-gray-50'} 
                  ${isPast ? 'opacity-70' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start mb-1">
                    <span className={`text-[10px] md:text-sm font-black ${isToday ? 'bg-blue-600 text-white w-5 h-5 md:w-8 md:h-8 rounded-lg flex items-center justify-center shadow-lg' : 'text-gray-900'}`}>
                        {d}
                    </span>
                    {!isActuallyWorking && (
                      <span className="text-[6px] md:text-[8px] font-black px-1.5 py-0.5 rounded uppercase bg-rose-600 text-white shadow-sm">NGHỈ</span>
                    )}
                </div>

                <div className="flex-1 flex flex-col justify-start gap-1 md:gap-1.5 overflow-hidden">
                    {myRequest && (
                      <div className="flex items-center gap-1.5 bg-emerald-600 text-white px-2 py-0.5 rounded-full shrink-0 shadow-md border border-white/20">
                        <UserIcon className="w-2 h-2 md:w-3 md:h-3" />
                        <span className="text-[7px] md:text-[10px] font-black truncate uppercase">BẠN: {myRequest.total_hours}h</span>
                      </div>
                    )}
                    <div className="flex flex-wrap gap-1">
                      {otherRequests.slice(0, 4).map((req, idx) => (
                        <div key={idx} className="w-4 h-4 md:w-6 md:h-6 rounded-full bg-indigo-700 text-white border-2 border-white flex items-center justify-center shrink-0 shadow-lg" title={req.users?.name}>
                           <span className="text-[7px] md:text-[10px] font-black uppercase">{req.users?.name?.charAt(0)}</span>
                        </div>
                      ))}
                      {otherRequests.length > 4 && (
                        <div className="w-4 h-4 md:w-6 md:h-6 rounded-full bg-gray-800 text-white border-2 border-white flex items-center justify-center shrink-0">
                           <span className="text-[6px] md:text-[8px] font-black">+{otherRequests.length - 4}</span>
                        </div>
                      )}
                    </div>
                </div>

                {dayRequestsLocal.length > 0 && (
                    <div className="absolute bottom-1 right-1 bg-gray-900 text-white text-[7px] md:text-[10px] px-2 py-0.5 rounded-full font-black border border-white/10 shadow-xl">
                        {dayRequestsLocal.length} NV
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-fade-in max-w-[1400px] mx-auto w-full px-2 md:px-0 pb-24">
        {/* HEADER SECTION - Optimized for Mobile */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-white p-4 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
            <div className="flex items-center gap-3 md:gap-4">
                <div className={`p-4 rounded-2xl shadow-xl text-white transform hover:rotate-3 transition-transform ${isTet ? 'bg-red-700' : 'bg-indigo-600'}`}>
                    <Clock className="w-6 h-6 md:w-8 md:h-8" />
                </div>
                <div>
                    <h2 className={`text-lg md:text-2xl font-black ${isTet ? 'text-red-900' : 'text-gray-900'} tracking-tight uppercase italic flex items-center gap-2`}>
                        Tăng ca 
                        {isTet && <Sparkles className="w-5 h-5 text-yellow-500 animate-pulse" />}
                    </h2>
                    <p className="text-[9px] md:text-xs text-gray-500 font-black uppercase tracking-[0.15em] mt-0.5">Manager Tool V1</p>
                </div>
            </div>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200 shadow-inner w-full lg:w-auto">
                {['calendar', 'personal', 'stats'].map(t => (
                    <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 lg:flex-none px-4 md:px-10 py-2.5 rounded-lg text-[10px] md:text-xs font-black transition-all uppercase tracking-widest ${activeTab === t ? (isTet ? 'bg-red-700 text-white shadow-lg' : 'bg-white text-indigo-700 shadow-lg') : 'text-gray-500 hover:text-gray-700'}`}>
                        {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                    </button>
                ))}
            </div>
        </div>

        {/* MAIN CONTENT AREA */}
        <div className="flex-1">
            {activeTab === 'calendar' && (
                <Card className="h-full flex flex-col p-0 overflow-hidden border-none shadow-2xl rounded-[1.5rem] md:rounded-[3rem] bg-white">
                    <div className="flex items-center justify-between p-4 md:p-8 bg-white border-b border-gray-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className={`p-2.5 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : 'text-indigo-600'}`}><ChevronLeft className="w-6 h-6 md:w-8 md:h-8"/></button>
                        <h3 className={`text-sm md:text-2xl font-black uppercase tracking-[0.1em] ${isTet ? 'text-red-900' : 'text-gray-900'} italic`}>Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className={`p-2.5 hover:bg-gray-100 rounded-xl transition-all ${isTet ? 'text-red-600' : 'text-indigo-600'}`}><ChevronRight className="w-6 h-6 md:w-8 md:h-8"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-gray-50/50 text-[9px] md:text-xs font-black uppercase text-gray-400 border-b border-gray-100">
                        {['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'].map((d, i) => <div key={d} className={`py-4 md:py-6 text-center ${i >= 5 ? 'text-rose-600' : ''}`}>{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-gray-200 gap-[1px]">
                        {renderCalendarDays()}
                    </div>
                </Card>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-6 animate-fade-in-up">
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
                        <Card className={`${isTet ? 'bg-gradient-to-br from-red-700 to-red-900' : 'bg-gradient-to-br from-indigo-700 to-blue-900'} text-white border-none shadow-2xl rounded-[1.5rem] p-6`}>
                            <h3 className="text-[10px] font-black uppercase opacity-80 tracking-widest">Tổng giờ mượn T{currentDate.getMonth()+1}</h3>
                            <div className="flex items-end gap-1.5 mt-3"><span className="text-4xl md:text-6xl font-black tabular-nums">{myStats.total.toFixed(1)}</span><span className="text-sm font-bold opacity-70 mb-1.5">h</span></div>
                        </Card>
                        <Card className="bg-white border-l-[6px] border-emerald-600 rounded-[1.5rem] p-6 shadow-xl flex items-center gap-5">
                            <div className="p-4 bg-emerald-100 rounded-2xl text-emerald-700 hidden sm:block"><Check className="w-8 h-8"/></div>
                            <div><p className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Ngày đăng ký</p><p className="text-3xl md:text-4xl font-black text-gray-900 tabular-nums">{myStats.count}</p></div>
                        </Card>
                    </div>
                    <Card className="rounded-[2.5rem] md:rounded-[3rem] p-6 md:p-12 shadow-xl border-none bg-white">
                        <div className="mb-8">
                            <h4 className="text-xl font-black text-gray-900 uppercase tracking-tight flex items-center gap-3"><Activity className="text-indigo-600" /> Biểu đồ hoạt động</h4>
                        </div>
                        <div className="h-64 md:h-[450px] w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <Tooltip cursor={{fill: '#f8fafc'}} />
                                    <Bar dataKey="hours" fill={isTet ? "#dc2626" : "#4f46e5"} radius={[6, 6, 0, 0]} barSize={14} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-6 animate-fade-in-up pb-10">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6">
                        <Card className="bg-white p-6 border-none shadow-xl rounded-[2rem] flex items-center gap-6">
                            <div className={`p-5 ${isTet ? 'bg-red-100 text-red-700' : 'bg-indigo-100 text-indigo-700'} rounded-[1.5rem]`}><Users className="w-10 h-10"/></div>
                            <div><p className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Thành viên OT</p><p className="text-3xl md:text-5xl font-black text-gray-900">{teamMonthlyStats.activeMembers}</p></div>
                        </Card>
                        <Card className="bg-white p-6 border-none shadow-xl rounded-[2rem] flex items-center gap-6">
                            <div className="p-5 bg-emerald-100 text-emerald-700 rounded-[1.5rem]"><Timer className="w-10 h-10"/></div>
                            <div><p className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Tổng giờ nhóm</p><p className="text-3xl md:text-5xl font-black text-gray-900">{teamMonthlyStats.totalHours.toFixed(1)}h</p></div>
                        </Card>
                        <Card className={`${isTet ? 'bg-red-800 shadow-red-200' : 'bg-indigo-800 shadow-indigo-200'} text-white p-6 border-none shadow-2xl rounded-[2rem] flex items-center gap-6`}>
                            <div className="p-5 bg-white/20 rounded-[1.5rem]"><Target className="w-10 h-10"/></div>
                            <div><p className="text-[11px] font-black text-white/70 uppercase tracking-widest">Hôm nay</p><p className="text-3xl md:text-5xl font-black">{requests.filter(r => r.date === todayStr).length} NV</p></div>
                        </Card>
                    </div>

                    <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 md:gap-8">
                        {/* Chi tiết đăng ký theo ngày */}
                        <div className="xl:col-span-8 space-y-6">
                            <Card className="rounded-[2.5rem] md:rounded-[3rem] p-0 overflow-hidden shadow-2xl border-none bg-white">
                                <div className="p-6 md:p-10 bg-gray-50/80 border-b border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                                    <div>
                                        <h4 className="text-xl font-black text-gray-900 uppercase flex items-center gap-3 italic"><Clock className="text-indigo-700 w-6 h-6"/> Danh sách chi tiết</h4>
                                        <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1.5">Tra cứu ngày {statsViewDate.split('-').reverse().join('/')}</p>
                                    </div>
                                    <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-gray-200 shadow-sm w-full md:w-auto ring-1 ring-black/5">
                                        <CalendarIcon className="w-5 h-5 text-gray-400" />
                                        <input type="date" value={statsViewDate} onChange={(e) => setStatsViewDate(e.target.value)} className="bg-transparent text-[11px] md:text-xs font-black outline-none uppercase cursor-pointer text-gray-900 w-full"/>
                                    </div>
                                </div>
                                <div className="p-6 md:p-8 space-y-4 overflow-y-auto max-h-[600px] no-scrollbar">
                                    {targetedRegistrations.length === 0 ? (
                                        <div className="py-24 text-center flex flex-col items-center gap-6 opacity-30 grayscale">
                                            <Info className="w-20 h-20 text-gray-900"/>
                                            <p className="font-black uppercase text-xs md:text-sm tracking-[0.2em] text-gray-900">Không tìm thấy dữ liệu đăng ký</p>
                                        </div>
                                    ) : (
                                        targetedRegistrations.map((req, idx) => (
                                            <div key={idx} className="p-5 md:p-8 rounded-[2rem] bg-gray-50 border-2 border-transparent hover:border-indigo-200 hover:bg-white transition-all flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6 group shadow-sm">
                                                <div className="flex items-center gap-6">
                                                    <div className={`w-14 h-14 md:w-20 md:h-20 text-white rounded-[1.8rem] flex items-center justify-center font-black text-xl md:text-3xl shadow-xl transform group-hover:rotate-3 transition-transform ${isTet ? 'bg-red-700' : 'bg-indigo-700'}`}>{req.users?.name?.charAt(0)}</div>
                                                    <div>
                                                        <h5 className="font-black text-gray-900 text-base md:text-xl uppercase italic leading-none">{req.users?.name}</h5>
                                                        <div className="flex flex-wrap items-center gap-3 mt-3">
                                                          <span className="text-[10px] md:text-[11px] font-black text-gray-500 uppercase tracking-widest px-3 py-1 bg-gray-200 rounded-lg">{req.users?.employee_id}</span>
                                                          <span className="text-[10px] md:text-[11px] font-black text-indigo-700 uppercase px-3 py-1 bg-indigo-50 rounded-lg border border-indigo-100">{req.start_time} - {req.end_time}</span>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="text-left sm:text-right w-full sm:w-auto pt-4 sm:pt-0 border-t sm:border-t-0 border-gray-100 flex sm:flex-col justify-between sm:justify-center items-center sm:items-end">
                                                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5 hidden sm:block">Giờ làm thêm</p>
                                                    <div className="flex items-baseline gap-1">
                                                      <span className="text-3xl md:text-5xl font-black text-gray-900 tabular-nums">{req.total_hours.toFixed(1)}</span>
                                                      <span className="text-xs font-black text-gray-400 uppercase">H</span>
                                                    </div>
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                            </Card>
                        </div>

                        {/* BXH & Report Tools */}
                        <div className="xl:col-span-4 space-y-6 md:space-y-8">
                            <Card className="rounded-[2.5rem] md:rounded-[3rem] p-0 overflow-hidden shadow-2xl border-none bg-white">
                                <div className={`p-6 md:p-10 ${isTet ? 'bg-red-800' : 'bg-indigo-800'} text-white`}>
                                    <h4 className="text-base md:text-xl font-black uppercase flex items-center gap-4 italic"><Award className="text-yellow-400 w-8 h-8" /> Bảng vàng danh dự</h4>
                                    <p className="text-[10px] font-black opacity-60 uppercase tracking-widest mt-2">Tháng {currentDate.getMonth()+1}</p>
                                </div>
                                <div className="p-6 md:p-8 space-y-4">
                                    {topRankings.map((emp, idx) => (
                                        <div key={idx} className={`p-4 md:p-6 rounded-[1.5rem] border-2 flex items-center gap-5 transition-all ${idx === 0 ? 'bg-yellow-50 border-yellow-200 shadow-lg scale-[1.02]' : 'bg-white border-gray-100'}`}>
                                            <div className={`w-10 h-10 md:w-12 md:h-12 rounded-xl flex items-center justify-center font-black text-sm md:text-lg shrink-0 shadow-md ${idx === 0 ? 'bg-yellow-500 text-white' : idx === 1 ? 'bg-slate-300 text-white' : idx === 2 ? 'bg-orange-300 text-white' : 'bg-gray-100 text-gray-500'}`}>{idx + 1}</div>
                                            <div className="flex-1 min-w-0">
                                                <h5 className="font-black text-gray-900 text-xs md:text-sm truncate uppercase">{emp.name}</h5>
                                                <p className="text-[9px] font-black text-gray-400 uppercase mt-1">{emp.count} lượt tăng ca</p>
                                            </div>
                                            <div className="text-right">
                                                <span className={`text-xl md:text-2xl font-black ${idx === 0 ? 'text-yellow-700' : 'text-blue-800'} tabular-nums`}>{emp.hours.toFixed(1)}</span>
                                                <span className="text-[9px] font-black text-gray-400 ml-1 uppercase">h</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </Card>

                            {isAdmin && (
                                <Card className="rounded-[2.5rem] md:rounded-[3rem] p-8 md:p-10 shadow-2xl border-none bg-gray-900 text-white space-y-8">
                                    <div className="flex items-center gap-5">
                                        <div className="p-4 bg-white/10 rounded-[1.2rem] shadow-inner"><FileSpreadsheet className="w-8 h-8 text-emerald-400"/></div>
                                        <div><h4 className="font-black uppercase italic text-base">Báo cáo hệ thống</h4><p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Xuất dữ liệu chuẩn</p></div>
                                    </div>
                                    <div className="space-y-5">
                                        <button onClick={() => handleExportExcelPro('today')} className="w-full py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-xl transition-all active:scale-95 border-b-4 border-emerald-900">XUẤT HÔM NAY</button>
                                        <div className="grid grid-cols-2 gap-3">
                                            <input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="bg-white/5 border border-white/20 rounded-xl p-4 text-[11px] font-black text-white outline-none focus:ring-2 focus:ring-emerald-500/50"/>
                                            <input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="bg-white/5 border border-white/20 rounded-xl p-4 text-[11px] font-black text-white outline-none focus:ring-2 focus:ring-emerald-500/50"/>
                                        </div>
                                        <button onClick={() => handleExportExcelPro('range')} className="w-full py-5 bg-indigo-700 hover:bg-indigo-800 text-white rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-xl transition-all active:scale-95 border-b-4 border-indigo-950">XUẤT THEO DẢI NGÀY</button>
                                    </div>
                                </Card>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>

        {/* REGISTRATION MODAL - Optimized for Mobile */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-end md:items-center justify-center backdrop-blur-md animate-fade-in px-0 md:px-4">
                <div className="bg-white rounded-t-[2.5rem] md:rounded-[3.5rem] shadow-2xl w-full max-w-2xl animate-slide-up overflow-hidden max-h-[96vh] flex flex-col border border-white/20 shadow-[0_-20px_60px_rgba(0,0,0,0.4)]">
                    <div className={`${isTet ? 'bg-gradient-to-r from-red-700 to-red-900' : 'bg-gradient-to-r from-indigo-700 to-blue-900'} p-6 md:p-10 flex justify-between items-center text-white shrink-0 shadow-2xl relative`}>
                        <div className="flex flex-col relative z-10">
                            <h3 className="text-2xl md:text-3xl font-black uppercase tracking-tighter italic">Ghi nhận tăng ca</h3>
                            <p className="text-[11px] md:text-sm font-black uppercase tracking-[0.2em] opacity-80 mt-1">Ngày {selectedDateStr.split('-').reverse().join('/')}</p>
                        </div>
                        <button onClick={() => setIsModalOpen(false)} className="p-4 hover:bg-white/20 rounded-2xl transition-all active:scale-90"><X className="w-8 h-8"/></button>
                    </div>

                    <div className="p-6 md:p-12 space-y-8 overflow-y-auto no-scrollbar pb-20 bg-gray-50 flex-1">
                        {isAdmin && (
                            <div className="bg-white p-6 rounded-[2rem] border-2 border-gray-100 shadow-lg space-y-6">
                                <div className="flex items-center gap-3">
                                    <Settings className={`w-5 h-5 ${isTet ? 'text-red-700' : 'text-indigo-700'}`} />
                                    <h4 className="text-[11px] font-black uppercase tracking-widest text-gray-900">Cấu hình ngày công</h4>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`py-5 rounded-2xl border-2 transition-all font-black text-[12px] uppercase tracking-widest shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0 || new Date(selectedDateStr).getDay() === 6))) ? 'bg-rose-600 text-white border-rose-600 shadow-rose-200/50' : 'bg-white text-gray-400 border-gray-100 hover:border-rose-200' }`}>NGÀY NGHỈ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`py-5 rounded-2xl border-2 transition-all font-black text-[12px] uppercase tracking-widest shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0 && new Date(selectedDateStr).getDay() !== 6)) ? (isTet ? 'bg-red-700 border-red-700 text-white' : 'bg-blue-700 border-blue-700 text-white') : 'bg-white text-gray-400 border-gray-100 hover:border-blue-200' }`}>NGÀY ĐI LÀM</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-8">
                            <div className="bg-white p-6 md:p-10 rounded-[2.5rem] md:rounded-[3rem] border-2 border-gray-100 shadow-2xl space-y-8 relative overflow-hidden ring-1 ring-black/5">
                                {isAdmin && (
                                    <div className="space-y-3">
                                        <label className="text-[11px] font-black text-gray-500 uppercase tracking-widest ml-1">Nhân sự thực hiện:</label>
                                        <div className="relative group">
                                            <select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full px-6 py-5 bg-gray-50 border-2 border-transparent rounded-2xl text-[13px] font-black outline-none uppercase appearance-none cursor-pointer focus:bg-white focus:border-indigo-600 transition-all text-gray-900 shadow-inner">
                                                {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}
                                            </select>
                                            <ChevronDown className="absolute right-5 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 pointer-events-none group-focus-within:rotate-180 transition-transform" />
                                        </div>
                                    </div>
                                )}

                                <div className="grid grid-cols-2 gap-4 md:gap-6">
                                    <div className="space-y-3">
                                        <label className="block text-[11px] font-black text-gray-500 uppercase tracking-widest ml-1">Bắt đầu:</label>
                                        <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full px-5 py-5 bg-gray-50 border-2 border-transparent rounded-2xl text-base font-black text-gray-900 outline-none focus:bg-white focus:border-indigo-600 transition-all shadow-inner"/>
                                    </div>
                                    <div className="space-y-3">
                                        <label className="block text-[11px] font-black text-gray-500 uppercase tracking-widest ml-1">Kết thúc:</label>
                                        <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full px-5 py-5 bg-gray-50 border-2 border-transparent rounded-2xl text-base font-black text-gray-900 outline-none focus:bg-white focus:border-indigo-600 transition-all shadow-inner"/>
                                    </div>
                                </div>

                                <div className="space-y-4">
                                    <div className="flex justify-between items-center px-1">
                                        <label className="text-[11px] font-black text-gray-500 uppercase tracking-widest">Nội dung công việc:</label>
                                        <span className={`text-[12px] font-black px-5 py-1.5 rounded-xl border-2 shadow-sm ${isTet ? 'bg-red-50 text-red-900 border-red-200' : 'bg-indigo-50 text-indigo-900 border-indigo-200'}`}>{calculatedHours.toFixed(1)}h OT</span>
                                    </div>
                                    <textarea value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-6 bg-gray-50 border-2 border-transparent rounded-[2.2rem] text-sm md:text-base h-40 resize-none outline-none font-bold text-gray-900 focus:bg-white focus:border-indigo-600 transition-all shadow-inner placeholder:text-gray-300" placeholder="VD: Sửa chữa thiết bị KHO A, kiểm kê hàng hóa..."/>
                                </div>

                                <div className="flex gap-4 pt-4">
                                    {editingRequestId && (isAdmin || targetUserId === user.id) && (
                                        <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-6 bg-rose-50 text-rose-700 rounded-3xl border-2 border-rose-100 hover:bg-rose-600 hover:text-white transition-all shadow-lg active:scale-90"><Trash2 className="w-8 h-8"/></button>
                                    )}
                                    <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className={`flex-1 py-6 text-white font-black rounded-[2rem] shadow-2xl text-[12px] md:text-sm tracking-[0.25em] uppercase active:scale-95 disabled:opacity-50 transition-all border-b-4 ${isTet ? 'bg-red-700 border-red-900 shadow-red-200' : 'bg-indigo-700 border-indigo-950 shadow-indigo-200'}`}>
                                        {isSubmitting ? <Loader2 className="w-8 h-8 animate-spin mx-auto"/> : (editingRequestId ? 'CẬP NHẬT DỮ LIỆU' : 'XÁC NHẬN ĐĂNG KÝ')}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* CONFIRMATION MODAL */}
        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-2xl animate-fade-in">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-12 text-center border-2 border-gray-100">
                    <div className="w-24 h-24 bg-rose-100 text-rose-700 mx-auto mb-8 rounded-[2rem] flex items-center justify-center shadow-2xl rotate-12 transition-transform hover:rotate-0"><Trash2 className="w-12 h-12" /></div>
                    <h3 className="text-3xl font-black text-gray-900 mb-3 uppercase italic leading-none">Hủy bỏ?</h3>
                    <p className="text-[11px] text-gray-500 font-black uppercase tracking-widest mb-12 px-2">Dữ liệu đăng ký sẽ bị xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-4">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-6 bg-rose-600 text-white font-black rounded-2xl text-[11px] uppercase tracking-[0.3em] shadow-2xl active:scale-95 shadow-rose-200/50">XÓA DỮ LIỆU</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-6 bg-white text-gray-500 font-black rounded-2xl border-2 border-gray-200 text-[11px] uppercase tracking-[0.3em] active:scale-95">HỦY BỎ</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo, useContext } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import { 
  Check, X, Trash2, RotateCcw, 
  Loader2, Search, RefreshCw,
  PackageCheck, Timer, XCircle,
  Calendar, Wrench, User as UserIcon, Snowflake, Sparkles, Gift,
  ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, CalendarDays, Filter,
  AlertCircle, ArrowRight, Clock
} from 'lucide-react';
import { ThemeContext } from '../../../App';

interface RequestManagerProps { user: User; }

const ITEMS_PER_PAGE = 10;
const todayStr = new Date().toISOString().split('T')[0];

const ToolTableImage = ({ toolId, toolName }: { toolId: string, toolName: string }) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    const fetchToolImage = async () => {
      const { data } = await supabase.from('tools').select('image').eq('id', toolId).single();
      if (data?.image) setImageUrl(data.image);
    };
    fetchToolImage();
  }, [toolId]);

  return (
    <div className="w-12 h-12 md:w-16 md:h-16 bg-white border-2 border-gray-100 rounded-2xl overflow-hidden flex items-center justify-center p-1.5 shadow-sm shrink-0 group-hover:scale-105 transition-transform">
      {imageUrl ? (
        <img src={imageUrl} alt={toolName} className="w-full h-full object-contain" />
      ) : (
        <Wrench className="w-5 h-5 text-gray-300" />
      )}
    </div>
  );
};

export const RequestManager: React.FC<RequestManagerProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [requests, setRequests] = useState<BorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'all' | 'personal'>(user.role === 'admin' ? 'all' : 'personal');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterDate, setFilterDate] = useState(todayStr); 
  const [currentPage, setCurrentPage] = useState(1);

  const isTet = theme === 'tet';

  const fetchRequests = async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      let query = supabase.from('requests').select('*');
      if (user.role !== 'admin' || activeTab === 'personal') {
        query = query.eq('user_id', user.id);
      }
      const { data, error } = await query;
      if (error) throw error;
      setRequests(data as BorrowRequest[] || []);
    } catch (err) {
      console.error(err);
    } finally {
      if (!silent) setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [user, activeTab]);

  const filteredRequests = useMemo(() => {
    const statusPriority: Record<string, number> = {
      pending: 0,
      approved: 1,
      rejected: 2,
      returned: 3
    };

    return requests.filter(req => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        req.user_name.toLowerCase().includes(searchLower) ||
        req.tool_name.toLowerCase().includes(searchLower) ||
        req.employee_id.toLowerCase().includes(searchLower);
      const matchesStatus = filterStatus === 'all' || req.status === filterStatus;
      const matchesDate = !filterDate || req.borrow_date.startsWith(filterDate);

      return matchesSearch && matchesStatus && matchesDate;
    }).sort((a, b) => {
      const priorityA = statusPriority[a.status] ?? 99;
      const priorityB = statusPriority[b.status] ?? 99;
      if (priorityA !== priorityB) return priorityA - priorityB;
      return new Date(b.borrow_date).getTime() - new Date(a.borrow_date).getTime();
    });
  }, [requests, searchTerm, filterStatus, filterDate]);

  const totalPages = Math.max(1, Math.ceil(filteredRequests.length / ITEMS_PER_PAGE));
  const paginatedRequests = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredRequests.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredRequests, currentPage]);

  useEffect(() => {
    setCurrentPage(1); 
  }, [searchTerm, filterStatus, filterDate, activeTab]);

  const handleAction = async (id: string, toolId: string, action: 'approve' | 'reject' | 'return' | 'cancel') => {
    setProcessingId(id);
    const oldRequests = [...requests];

    try {
      if (action === 'approve') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        if ((tool?.available || 0) <= 0) throw new Error("Hết hàng trong kho");
        await supabase.from('tools').update({ available: (tool?.available || 1) - 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'approved' }).eq('id', id);
      } else if (action === 'return') {
        const { data: tool } = await supabase.from('tools').select('available').eq('id', toolId).single();
        await supabase.from('tools').update({ available: (tool?.available || 0) + 1 }).eq('id', toolId);
        await supabase.from('requests').update({ status: 'returned', returned_at: new Date().toISOString() }).eq('id', id);
      } else if (action === 'reject') {
        await supabase.from('requests').update({ status: 'rejected' }).eq('id', id);
      } else if (action === 'cancel') {
        await supabase.from('requests').delete().eq('id', id);
      }
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      await fetchRequests(true);
    } catch (e: any) {
      alert(e.message);
      setRequests(oldRequests);
    } finally {
      setProcessingId(null);
    }
  };

  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-600 text-white', icon: <Timer className="w-3 h-3 animate-pulse" />, label: 'CHỜ DUYỆT' },
      approved: { color: 'bg-indigo-600 text-white', icon: <PackageCheck className="w-3 h-3" />, label: 'ĐANG MƯỢN' },
      returned: { color: 'bg-emerald-600 text-white', icon: <RotateCcw className="w-3 h-3" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-rose-600 text-white', icon: <XCircle className="w-3 h-3" />, label: 'TỪ CHỐI' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl text-[9px] font-black border-2 border-white shadow-md ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in max-w-7xl mx-auto pb-24 px-2 md:px-0">
      {/* HEADER SECTION */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-white p-5 md:p-8 rounded-[2rem] md:rounded-[2.5rem] shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <div className={`p-4 rounded-2xl shadow-xl text-white transform hover:rotate-3 transition-transform ${isTet ? 'bg-red-700 shadow-red-100' : 'bg-indigo-600 shadow-indigo-100'}`}>
            <RefreshCw className="w-8 h-8" />
          </div>
          <div>
            <h2 className="text-xl md:text-3xl font-black text-gray-900 tracking-tight uppercase flex items-center gap-2 italic">
               Mượn tài sản
               {isTet && <Sparkles className="w-6 h-6 text-yellow-500 animate-pulse" />}
            </h2>
            <p className="text-[10px] md:text-xs text-gray-400 font-black uppercase tracking-widest mt-1 opacity-70">Điều hành xuất nhập kho Team V1</p>
          </div>
        </div>
        <div className="flex bg-gray-100 p-1.5 rounded-2xl border border-gray-200 shadow-inner w-full lg:w-auto">
            {user.role === 'admin' && (
              <button onClick={() => setActiveTab('all')} className={`flex-1 lg:flex-none px-8 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeTab === 'all' ? (isTet ? 'bg-red-700 text-white shadow-lg' : 'bg-white text-indigo-700 shadow-lg') : 'text-gray-500'}`}>Hệ thống</button>
            )}
            <button onClick={() => setActiveTab('personal')} className={`flex-1 lg:flex-none px-8 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${activeTab === 'personal' ? (isTet ? 'bg-red-700 text-white shadow-lg' : 'bg-white text-indigo-700 shadow-lg') : 'text-gray-500'}`}>Cá nhân</button>
        </div>
      </div>

      {/* FILTERS SECTION */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-12 gap-4">
        <div className="lg:col-span-5 relative group">
          <Search className={`absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5 transition-colors ${isTet ? 'group-focus-within:text-red-600' : 'group-focus-within:text-indigo-600'}`} />
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Tìm mã nhân viên, tên, hoặc thiết bị..." 
            className={`w-full pl-12 pr-4 py-5 bg-white border border-gray-100 rounded-[1.5rem] text-sm font-bold outline-none focus:ring-8 transition-all shadow-sm ${isTet ? 'focus:ring-red-500/5 focus:border-red-600/40' : 'focus:ring-indigo-500/5 focus:border-indigo-600/40'}`} 
          />
        </div>

        <div className="lg:col-span-4 flex items-center gap-3 bg-white p-3 border border-gray-100 rounded-[1.5rem] shadow-sm">
           <CalendarDays className="w-6 h-6 text-gray-400 ml-2" />
           <input 
            type="date" 
            value={filterDate} 
            onChange={e => setFilterDate(e.target.value)}
            className={`flex-1 bg-transparent border-none text-[12px] font-black uppercase outline-none cursor-pointer text-gray-900`}
           />
           {filterDate !== todayStr && (
             <button onClick={() => setFilterDate(todayStr)} className="px-3 py-1.5 bg-gray-100 text-[10px] font-black rounded-xl hover:bg-gray-200 transition-colors">HÔM NAY</button>
           )}
        </div>

        <div className="lg:col-span-3">
          <div className="relative group">
            <select 
              value={filterStatus} 
              onChange={e => setFilterStatus(e.target.value)} 
              className="w-full pl-6 pr-10 py-5 bg-white border border-gray-100 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest outline-none cursor-pointer shadow-sm appearance-none"
            >
              <option value="all">Tất cả trạng thái</option>
              <option value="pending">⏳ Đang chờ</option>
              <option value="approved">📦 Đang mượn</option>
              <option value="returned">✅ Đã trả</option>
              <option value="rejected">❌ Từ chối</option>
            </select>
            <ChevronDown className="absolute right-5 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 pointer-events-none group-focus-within:rotate-180 transition-transform" />
          </div>
        </div>
      </div>

      {/* REQUESTS LIST - Mobile Cards / Desktop Table */}
      <div className="space-y-4">
        {loading ? (
            <div className="py-32 text-center flex flex-col items-center gap-4">
              <Loader2 className="w-12 h-12 animate-spin text-indigo-600 opacity-20" />
              <p className="text-xs font-black uppercase tracking-widest text-gray-300">Đang tải yêu cầu...</p>
            </div>
        ) : paginatedRequests.length === 0 ? (
            <div className="py-32 text-center bg-white rounded-[3rem] border-2 border-dashed border-gray-100">
               <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6">
                 <AlertCircle className="w-10 h-10 text-gray-200" />
               </div>
               <p className="text-[11px] md:text-sm font-black text-gray-400 uppercase tracking-[0.2em] italic">Không tìm thấy dữ liệu phù hợp</p>
            </div>
        ) : (
          <div className="grid grid-cols-1 gap-4 lg:gap-0 lg:bg-white lg:rounded-[3rem] lg:shadow-2xl lg:overflow-hidden lg:border-none">
            {/* Desktop Table Header */}
            <div className="hidden lg:grid grid-cols-12 bg-gray-50/80 border-b border-gray-100 px-10 py-8">
               <div className="col-span-3 text-[11px] font-black text-gray-400 uppercase tracking-widest">Người mượn</div>
               <div className="col-span-3 text-[11px] font-black text-gray-400 uppercase tracking-widest">Thiết bị</div>
               <div className="col-span-2 text-[11px] font-black text-gray-400 uppercase tracking-widest">Thời gian</div>
               <div className="col-span-2 text-[11px] font-black text-gray-400 uppercase tracking-widest text-center">Trạng thái</div>
               <div className="col-span-2 text-[11px] font-black text-gray-400 uppercase tracking-widest text-right">Thao tác</div>
            </div>

            {paginatedRequests.map((req) => (
              <div 
                key={req.id} 
                className="bg-white rounded-[2.5rem] p-6 lg:p-0 lg:rounded-none lg:grid lg:grid-cols-12 lg:items-center lg:px-10 lg:py-7 lg:border-b lg:border-gray-50 lg:hover:bg-indigo-50/30 transition-all group relative border-4 border-transparent hover:border-indigo-600/10 lg:border-none shadow-xl lg:shadow-none"
              >
                {/* Mobile View: User Info Header */}
                <div className="lg:hidden flex items-center justify-between mb-6 pb-4 border-b border-gray-50">
                  <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 text-white rounded-2xl flex items-center justify-center font-black text-lg shadow-xl ${isTet ? 'bg-red-700' : 'bg-indigo-700'}`}>{req.user_name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-sm uppercase italic text-gray-900 leading-tight">{req.user_name}</p>
                      <p className="text-[10px] text-gray-400 font-bold tracking-widest mt-1 uppercase">{req.employee_id}</p>
                    </div>
                  </div>
                  {getStatusBadge(req.status)}
                </div>

                {/* Grid Item: User Info (Desktop only) */}
                <div className="hidden lg:col-span-3 lg:flex items-center gap-5">
                   <div className={`w-14 h-14 text-white rounded-[1.2rem] flex items-center justify-center font-black text-xl shadow-lg transition-transform group-hover:rotate-3 ${isTet ? 'bg-red-700' : 'bg-indigo-700'}`}>{req.user_name.charAt(0)}</div>
                   <div>
                     <p className="font-black text-sm md:text-base uppercase italic text-gray-900 truncate leading-none mb-1.5">{req.user_name}</p>
                     <p className="text-[10px] text-gray-400 font-black tracking-widest uppercase">{req.employee_id}</p>
                   </div>
                </div>

                {/* Grid Item: Tool Info */}
                <div className="lg:col-span-3 flex items-center gap-5 mb-6 lg:mb-0">
                  <ToolTableImage toolId={req.tool_id} toolName={req.tool_name} />
                  <div>
                    <p className="lg:hidden text-[10px] font-black text-gray-400 uppercase mb-1">Thiết bị mượn:</p>
                    <p className="font-black text-sm md:text-lg uppercase tracking-tighter text-gray-800 leading-tight italic group-hover:text-indigo-700 transition-colors">{req.tool_name}</p>
                  </div>
                </div>

                {/* Grid Item: Date Info */}
                <div className="lg:col-span-2 flex flex-col justify-center gap-1.5 mb-6 lg:mb-0">
                  <div className="flex items-center gap-2 text-xs font-black text-gray-600 tabular-nums">
                    <Calendar className="w-4 h-4 text-gray-300" />
                    <span>{new Date(req.borrow_date).toLocaleDateString('vi-VN')}</span>
                  </div>
                  {req.returned_at && (
                    <div className="flex items-center gap-2 text-[11px] font-black text-emerald-600 tabular-nums">
                       <RotateCcw className="w-3.5 h-3.5" />
                       <span>{new Date(req.returned_at).toLocaleDateString('vi-VN')}</span>
                    </div>
                  )}
                </div>

                {/* Grid Item: Status (Desktop only) */}
                <div className="hidden lg:col-span-2 lg:flex justify-center">
                  {getStatusBadge(req.status)}
                </div>

                {/* Grid Item: Actions */}
                <div className="lg:col-span-2 flex justify-end lg:pr-2">
                   {processingId === req.id ? (
                      <div className="p-4 bg-gray-50 rounded-2xl"><Loader2 className="w-6 h-6 animate-spin text-indigo-600" /></div>
                   ) : (
                      <div className="flex gap-3 w-full lg:w-auto">
                        {activeTab === 'all' && user.role === 'admin' && req.status === 'pending' && (
                          <>
                            <button onClick={() => handleAction(req.id, req.tool_id, 'approve')} className="flex-1 lg:flex-none p-5 lg:p-3.5 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-200/50 hover:bg-emerald-700 transition-all active:scale-90" title="Duyệt"><Check className="w-6 h-6 lg:w-5 lg:h-5" /></button>
                            <button onClick={() => handleAction(req.id, req.tool_id, 'reject')} className="flex-1 lg:flex-none p-5 lg:p-3.5 bg-rose-600 text-white rounded-2xl shadow-xl shadow-rose-200/50 hover:bg-rose-700 transition-all active:scale-90" title="Từ chối"><X className="w-6 h-6 lg:w-5 lg:h-5" /></button>
                          </>
                        )}
                        {activeTab === 'all' && user.role === 'admin' && req.status === 'approved' && (
                          <button onClick={() => handleAction(req.id, req.tool_id, 'return')} className="w-full lg:w-auto px-10 lg:px-6 py-5 lg:py-3.5 bg-gray-900 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-2xl hover:bg-black transition-all active:scale-95 border-b-4 border-white/10">THU HỒI</button>
                        )}
                        {req.user_id === user.id && req.status === 'pending' && (
                          <button onClick={() => handleAction(req.id, req.tool_id, 'cancel')} className="w-full lg:w-auto p-5 lg:p-3.5 bg-rose-50 text-rose-600 rounded-2xl border-2 border-rose-100 hover:bg-rose-600 hover:text-white transition-all active:scale-90 shadow-lg" title="Hủy yêu cầu"><Trash2 className="w-6 h-6 lg:w-5 lg:h-5" /></button>
                        )}
                      </div>
                   )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* PAGINATION FOOTER */}
      {filteredRequests.length > 0 && (
        <Card className="p-6 md:p-10 rounded-[2.5rem] md:rounded-[3.5rem] shadow-2xl border-none bg-white flex flex-col sm:flex-row items-center justify-between gap-8 px-12">
          <div className="text-[11px] md:text-sm text-gray-400 font-black uppercase tracking-[0.2em] flex items-center gap-3">
             <div className="w-2 h-2 rounded-full bg-indigo-600"></div>
             Trang <span className="text-gray-900 tabular-nums font-black">{currentPage} / {totalPages}</span>
             <span className="text-gray-300 font-medium ml-2">|</span>
             <span className="text-indigo-600 tabular-nums font-black ml-2">{filteredRequests.length} đơn mượn</span>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setCurrentPage(1)}
              disabled={currentPage === 1}
              className="p-4 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-indigo-50 transition-all active:scale-90 shadow-sm"
            >
              <ChevronsLeft className="w-6 h-6" />
            </button>
            <button 
              onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="p-4 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-indigo-50 transition-all active:scale-90 shadow-sm"
            >
              <ChevronLeft className="w-6 h-6" />
            </button>

            <div className={`w-14 h-14 rounded-2xl font-black text-xl flex items-center justify-center shadow-2xl transform transition-transform hover:scale-110 border-4 border-white ring-2 ring-indigo-600/10 mx-4 ${isTet ? 'bg-red-700 text-white' : 'bg-indigo-700 text-white'}`}>
                {currentPage}
            </div>

            <button 
              onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
              disabled={currentPage === totalPages}
              className="p-4 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-indigo-50 transition-all active:scale-90 shadow-sm"
            >
              <ChevronRight className="w-6 h-6" />
            </button>
            <button 
              onClick={() => setCurrentPage(totalPages)}
              disabled={currentPage === totalPages}
              className="p-4 rounded-2xl border-2 border-gray-100 bg-white disabled:opacity-20 hover:bg-indigo-50 transition-all active:scale-90 shadow-sm"
            >
              <ChevronsRight className="w-6 h-6" />
            </button>
          </div>
        </Card>
      )}

      <div className="flex justify-center gap-16 py-12 opacity-10 select-none pointer-events-none">
         {isTet ? Array.from({length: 4}).map((_, i) => <Gift key={i} className="w-12 h-12 text-yellow-600" />) : Array.from({length: 4}).map((_, i) => <Snowflake key={i} className="w-12 h-12 text-blue-600" />)}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useContext } from 'react';
