         {isTet ? Array.from({length: 4}).map((_, i) => <Gift key={i} className="w-12 h-12 text-yellow-600" />) : Array.from({length: 4}).map((_, i) => <Snowflake key={i} className="w-12 h-12 text-blue-600" />)}
