                    <div className={`${isTet ? 'bg-gradient-to-r from-red-700 to-red-900' : 'bg-gradient-to-r from-indigo-700 to-blue-900'} p-6 md:p-8 flex justify-between items-center text-white shrink-0 shadow-2xl relative`}>
