                        <div className="space-y-4">
                            <div className="flex items-center justify-between px-2">
                                <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-500">Nhân sự đã đăng ký ({dayRequestsInModal.length})</h4>
                                {dayRequestsInModal.length > 3 && (
                                    <button onClick={() => setIsListExpanded(!isListExpanded)} className="text-[10px] font-black text-indigo-700 uppercase tracking-widest hover:underline">
                                        {isListExpanded ? 'Thu gọn' : 'Xem tất cả'}
                                    </button>
                                )}
                            </div>
                            <div className={`grid grid-cols-1 sm:grid-cols-2 gap-3 transition-all duration-300 ${!isListExpanded && dayRequestsInModal.length > 4 ? 'max-h-48 overflow-hidden' : ''}`}>
                                {dayRequestsInModal.length === 0 ? (
                                    <div className="col-span-full py-6 text-center bg-white rounded-2xl border-2 border-dashed border-gray-100 italic text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                                        Chưa có nhân sự đăng ký trong ngày này
                                    </div>
                                ) : (
                                    dayRequestsInModal.map((r) => (
                                        <div key={r.id} className={`flex items-center justify-between p-3 bg-white rounded-2xl border shadow-sm transition-all ${r.user_id === user.id ? (isTet ? 'border-red-200 bg-red-50/50' : 'border-indigo-200 bg-indigo-50/50') : 'border-gray-100'}`}>
                                            <div className="flex items-center gap-3">
                                                <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs text-white shadow-md ${isTet ? 'bg-red-700' : 'bg-indigo-600'}`}>{r.users?.name?.charAt(0)}</div>
                                                <div className="min-w-0">
                                                    <p className="text-[11px] font-black uppercase text-gray-900 truncate leading-none mb-1">{r.users?.name}</p>
                                                    <p className="text-[9px] font-bold text-gray-500 uppercase tracking-tight">{r.start_time} - {r.end_time}</p>
                                                </div>
                                            </div>
                                            <div className={`text-[10px] font-black px-2 py-0.5 rounded-lg border-2 tabular-nums ${isTet ? 'text-red-700 border-red-200 bg-red-50' : 'text-indigo-700 border-indigo-200 bg-indigo-50'}`}>{r.total_hours}h</div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>

                        {isAdmin && (
                            <div className="bg-white p-5 rounded-[1.5rem] border-2 border-gray-100 shadow-lg space-y-4">
                                <div className="flex items-center gap-3">
                                    <Settings className={`w-4 h-4 ${isTet ? 'text-red-700' : 'text-indigo-700'}`} />
                                    <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-900">Loại ngày công</h4>
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <button onClick={() => updateDayWorkingStatus(false)} className={`py-4 rounded-xl border-2 transition-all font-black text-[11px] uppercase tracking-widest shadow-sm ${ (dayConfigs[selectedDateStr] === false || (dayConfigs[selectedDateStr] === undefined && (new Date(selectedDateStr).getDay() === 0 || new Date(selectedDateStr).getDay() === 6))) ? 'bg-rose-700 text-white border-rose-700 shadow-rose-200/50' : 'bg-white text-gray-600 border-gray-100 hover:border-rose-200' }`}>NGÀY NGHỈ</button>
                                    <button onClick={() => updateDayWorkingStatus(true)} className={`py-4 rounded-xl border-2 transition-all font-black text-[11px] uppercase tracking-widest shadow-sm ${ (dayConfigs[selectedDateStr] === true || (dayConfigs[selectedDateStr] === undefined && new Date(selectedDateStr).getDay() !== 0 && new Date(selectedDateStr).getDay() !== 6)) ? (isTet ? 'bg-red-700 border-red-700 text-white' : 'bg-indigo-700 border-indigo-700 text-white') : 'bg-white text-gray-600 border-gray-100 hover:border-indigo-200' }`}>NGÀY ĐI LÀM</button>
                                </div>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="bg-white p-6 md:p-8 rounded-[2rem] border-2 border-gray-100 shadow-2xl space-y-6 relative overflow-hidden ring-1 ring-black/5">
                                {isAdmin && (
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">Nhân sự thực hiện:</label>
                                        <div className="relative group">
                                            <select required value={targetUserId} onChange={(e) => setTargetUserId(e.target.value)} className="w-full px-5 py-4 bg-gray-50 border-2 border-transparent rounded-xl text-[12px] font-black outline-none uppercase appearance-none cursor-pointer focus:bg-white focus:border-indigo-600 transition-all text-gray-900 shadow-inner">
                                                {allEmployees.map(emp => (<option key={emp.id} value={emp.id}>{emp.name} ({emp.employee_id})</option>))}
                                            </select>
                                            <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                                        </div>
                                    </div>
                                )}

                                <div className="grid grid-cols-2 gap-4 md:gap-6">
                                    <div className="space-y-2">
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">Bắt đầu:</label>
                                        <input type="time" required value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full px-4 py-4 bg-gray-50 border-2 border-transparent rounded-xl text-sm font-black text-gray-900 outline-none focus:bg-white focus:border-indigo-600 transition-all shadow-inner"/>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="block text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">Kết thúc:</label>
                                        <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full px-4 py-4 bg-gray-50 border-2 border-transparent rounded-xl text-sm font-black text-gray-900 outline-none focus:bg-white focus:border-indigo-600 transition-all shadow-inner"/>
                                    </div>
                                </div>

                                <div className="space-y-3">
                                    <div className="flex justify-between items-center px-1">
                                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Nội dung công việc:</label>
                                        <span className={`text-[11px] font-black px-4 py-1 rounded-lg border-2 shadow-sm ${isTet ? 'bg-red-700 text-white border-red-700' : 'bg-indigo-700 text-white border-indigo-700'}`}>{calculatedHours.toFixed(1)}h OT</span>
                                    </div>
                                    <textarea value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-5 bg-gray-50 border-2 border-transparent rounded-[1.5rem] text-sm md:text-base h-32 resize-none outline-none font-bold text-gray-900 focus:bg-white focus:border-indigo-600 transition-all shadow-inner placeholder:text-gray-400" placeholder="VD: Sửa chữa thiết bị KHO A, kiểm kê hàng hóa..."/>
                                </div>

                                <div className="flex gap-4 pt-2">
                                    {editingRequestId && (isAdmin || targetUserId === user.id) && (
                                        <button type="button" onClick={() => setIsConfirmCancelOpen(true)} className="p-5 bg-rose-700 text-white rounded-2xl shadow-lg active:scale-90"><Trash2 className="w-6 h-6"/></button>
                                    )}
                                    <button type="submit" disabled={isSubmitting || calculatedHours <= 0} className={`flex-1 py-5 text-white font-black rounded-[1.5rem] shadow-2xl text-[11px] md:text-sm tracking-[0.2em] uppercase active:scale-95 disabled:opacity-50 transition-all border-b-4 ${isTet ? 'bg-red-700 border-red-900 shadow-red-200' : 'bg-indigo-700 border-indigo-950 shadow-indigo-200'}`}>
                                        {isSubmitting ? <Loader2 className="w-6 h-6 animate-spin mx-auto"/> : (editingRequestId ? 'CẬP NHẬT DỮ LIỆU' : 'XÁC NHẬN ĐĂNG KÝ')}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* CONFIRMATION MODAL */}
        {isConfirmCancelOpen && (
            <div className="fixed inset-0 bg-black/95 z-[120] flex items-center justify-center p-6 backdrop-blur-2xl animate-fade-in">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-10 text-center border-2 border-gray-100">
                    <div className="w-20 h-20 bg-rose-700 text-white mx-auto mb-6 rounded-[1.5rem] flex items-center justify-center shadow-2xl rotate-12 transition-transform hover:rotate-0"><Trash2 className="w-10 h-10" /></div>
                    <h3 className="text-2xl font-black text-gray-900 mb-2 uppercase italic leading-none">Hủy bỏ?</h3>
                    <p className="text-[10px] text-gray-600 font-black uppercase tracking-widest mb-10 px-2 leading-relaxed">Dữ liệu đăng ký sẽ bị xóa vĩnh viễn khỏi hệ thống.</p>
                    <div className="flex flex-col gap-3">
                        <button onClick={handleCancelRequest} disabled={isDeleting} className="w-full py-5 bg-rose-700 text-white font-black rounded-xl text-[11px] uppercase tracking-[0.2em] shadow-2xl active:scale-95">XÓA DỮ LIỆU</button>
                        <button onClick={() => setIsConfirmCancelOpen(false)} className="w-full py-5 bg-gray-100 text-gray-700 font-black rounded-xl border-2 border-gray-200 text-[11px] uppercase tracking-[0.2em] active:scale-95">HỦY BỎ</button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  History, Search, Calendar, Filter, X, 
  User as UserIcon, ShieldCheck, ChevronDown, 
  SlidersHorizontal, ChevronLeft, ChevronRight, 
  Loader2, RefreshCw, AlertCircle, ChevronsLeft, ChevronsRight,
  Undo2, CheckCircle2, AlertTriangle, FileSpreadsheet,
  Download, ListFilter, CalendarDays, Activity, 
  ArrowUpRight, Clock, Box, LayoutPanelLeft, Timer, PackageCheck, XCircle, RotateCcw, TrendingUp
} from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | 'yesterday' | 'thisWeek' | '7days' | '30days' | '90days' | 'thisMonth';

const ITEMS_PER_PAGE = 10;

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div 
      role="status"
      aria-live="polite"
      className={`fixed bottom-10 right-10 z-[100] ${type === 'success' ? 'bg-emerald-600' : 'bg-rose-600'} text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up border border-white/20 backdrop-blur-md`}
    >
      {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
      <p className="text-xs font-black uppercase tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-2 hover:bg-white/20 p-1 rounded-full active:scale-90" aria-label="Close notification"><X className="w-4 h-4"/></button>
    </div>
  );
};

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reBorrowingId, setReBorrowingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async (silent = false) => {
    if (!user) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    setError(null);
    try {
      let query = supabase.from('requests').select('*').order('borrow_date', { ascending: false });
      if (user.role !== 'admin') query = query.eq('user_id', user.id);
      const { data, error: fetchError } = await query;
      if (fetchError) throw fetchError;
      if (data) setLogs(data as ExtendedBorrowRequest[]);
    } catch (err: any) {
      console.error("Fetch history error:", err);
      setError("Không thể tải dữ liệu lịch sử.");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => { fetchHistory(); }, [user.id, user.role]);
  useEffect(() => { setCurrentPage(1); }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Quản lý';
    if (req.status === 'rejected') return req.rejected_by || 'Quản lý';
    return '-';
  };

  const handleReBorrow = async (log: ExtendedBorrowRequest) => {
    setReBorrowingId(log.id);
    try {
      const { error } = await supabase.from('requests').insert([{
        user_id: user.id, user_name: user.name, employee_id: user.employeeCode,
        tool_id: log.tool_id, tool_name: log.tool_name, borrow_date: new Date().toISOString(), status: 'pending'
      }]);
      if (error) throw error;
      setToast({ message: "Đã gửi yêu cầu mượn lại thành công!", type: 'success' });
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchHistory(true);
    } catch (err: any) {
      setToast({ message: "Lỗi: " + err.message, type: 'error' });
    } finally {
      setReBorrowingId(null);
    }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.trim().toLowerCase();
      const handlerLower = handlerFilter.trim().toLowerCase();
      const matchesText = !searchLower || (log.user_name?.toLowerCase().includes(searchLower) || log.employee_id?.toLowerCase().includes(searchLower) || log.tool_name?.toLowerCase().includes(searchLower));
      const currentHandler = (getHandlerName(log) || '').toLowerCase();
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);
      const matchesStatus = statusFilter === 'all' || log.status === statusFilter;
      const logBorrowDate = new Date(log.borrow_date.split('T')[0]);
      const filterStartDate = startDate ? new Date(startDate) : null;
      const filterEndDate = endDate ? new Date(endDate) : null;
      const matchesDateRange = (!filterStartDate || logBorrowDate >= filterStartDate) && (!filterEndDate || logBorrowDate <= filterEndDate);
      return matchesText && matchesHandler && matchesStatus && matchesDateRange;
    });
  }, [logs, searchText, handlerFilter, statusFilter, startDate, endDate]);

  const summaryStats = useMemo(() => ({
    total: filteredLogs.length,
    pending: filteredLogs.filter(l => l.status === 'pending').length,
    borrowing: filteredLogs.filter(l => l.status === 'approved').length,
    completed: filteredLogs.filter(l => l.status === 'returned' || l.status === 'rejected').length
  }), [filteredLogs]);

  const handleExportExcel = () => {
    if (filteredLogs.length === 0) return alert("Không có dữ liệu để xuất.");
    const exportData = filteredLogs.map(log => ({
      'Người mượn': log.user_name, 'Mã nhân viên': log.employee_id, 'Thiết bị': log.tool_name,
      'Ngày mượn': new Date(log.borrow_date).toLocaleString('vi-VN'),
      'Ngày trả': log.returned_at ? new Date(log.returned_at).toLocaleString('vi-VN') : 'Chưa trả',
      'Người xử lý': getHandlerName(log),
      'Trạng thái': log.status === 'approved' ? 'Đang mượn' : log.status === 'returned' ? 'Đã trả' : log.status === 'rejected' ? 'Từ chối' : 'Chờ duyệt'
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "LichSuMuonTra");
    XLSX.writeFile(workbook, `Lich_su_muon_tra_${new Date().getTime()}.xlsx`);
  };

  const totalPages = Math.max(1, Math.ceil(filteredLogs.length / ITEMS_PER_PAGE));
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentLogs = filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];
    let start = new Date(); let end = new Date();
    switch (option) {
        case 'yesterday': start.setDate(today.getDate() - 1); end.setDate(today.getDate() - 1); break;
        case 'thisWeek': const day = today.getDay(); const diff = today.getDate() - day + (day === 0 ? -6 : 1); start = new Date(today.setDate(diff)); end = new Date(); break;
        case '7days': start.setDate(today.getDate() - 7); break;
        case '30days': start.setDate(today.getDate() - 30); break;
        case '90days': start.setDate(today.getDate() - 90); break;
        case 'thisMonth': start = new Date(today.getFullYear(), today.getMonth(), 1); end = new Date(today.getFullYear(), today.getMonth() + 1, 0); break;
        case 'today': default: break; 
    }
    setStartDate(formatDate(start)); setEndDate(formatDate(end));
  };

  const clearFilters = () => {
    setSearchText(''); setHandlerFilter(''); setStartDate(''); setEndDate(''); setStatusFilter('all'); setQuickDate('custom'); setCurrentPage(1);
  };

  const activeFiltersCount = [searchText.trim(), handlerFilter.trim(), startDate, endDate, statusFilter !== 'all'].filter(Boolean).length;

  return (
    <div className="space-y-4 md:space-y-6 animate-fade-in pb-10 max-w-7xl mx-auto">
       {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

       {/* Header Panel */}
       <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-indigo-600 rounded-[1.8rem] shadow-xl shadow-indigo-100 text-white">
                    <History className="w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none italic uppercase">Lịch sử hoạt động</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">Hồ sơ tra cứu mượn trả thiết bị</p>
                </div>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={handleExportExcel} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 bg-emerald-50 text-emerald-600 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all border border-emerald-100 hover:bg-emerald-600 hover:text-white shadow-sm active:scale-95"><FileSpreadsheet className="w-4 h-4"/> Xuất Excel</button>
                <button onClick={() => fetchHistory(true)} className="p-4 bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-2xl transition-all border border-gray-100 shadow-sm active:scale-95">
                  {isRefreshing ? <Loader2 className="w-5 h-5 animate-spin"/> : <RefreshCw className="w-5 h-5"/>}
                </button>
            </div>
       </div>

       {/* Summary Stats Cards */}
       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-purple-100 text-purple-600 rounded-lg"><LayoutPanelLeft className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-purple-400 uppercase tracking-widest">Tổng lượt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.total}</p>
          </Card>
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-amber-100 text-amber-600 rounded-lg"><Clock className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-amber-400 uppercase tracking-widest">Chờ duyệt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.pending}</p>
          </Card>
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-indigo-100 text-indigo-600 rounded-lg"><Box className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-indigo-400 uppercase tracking-widest">Đang mượn</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.borrowing}</p>
          </Card>
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-emerald-100 text-emerald-600 rounded-lg"><CheckCircle2 className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-emerald-400 uppercase tracking-widest">Hoàn thành</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.completed}</p>
          </Card>
       </div>

       {/* Filter Card */}
       <Card className="p-6 md:p-8 overflow-visible border-none shadow-xl rounded-[2.5rem] md:rounded-[3rem] bg-white">
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h3 className="text-[9px] md:text-[11px] font-black text-gray-600 flex items-center gap-2 uppercase tracking-[0.15em]">
                        <SlidersHorizontal className="w-3.5 h-3.5 text-indigo-600" /> Bộ lọc lịch sử
                    </h3>
                    {activeFiltersCount > 0 && (
                        <button onClick={clearFilters} className="text-[9px] text-rose-600 font-black uppercase tracking-widest flex items-center gap-1 hover:underline"><X className="w-3 h-3" /> Xóa lọc</button>
                    )}
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
                    <div className="xl:col-span-4 space-y-4">
                        <label className="block text-[9px] font-black text-gray-600 uppercase tracking-widest ml-1">Chọn nhanh khoảng thời gian</label>
                        <div className="grid grid-cols-3 md:grid-cols-4 gap-2">
                             {[
                               {id: 'today', l: 'H.Nay'}, {id: 'yesterday', l: 'H.Qua'}, {id: 'thisWeek', l: 'Tuần này'}, 
                               {id: '7days', l: '7 ngày'}, {id: '30days', l: '30 ngày'}, {id: '90days', l: '90 ngày'}, {id: 'thisMonth', l: 'Tháng này'}
                             ].map((btn) => (
                                <button key={btn.id} onClick={() => handleQuickDate(btn.id as QuickDateOption)} className={`px-2 py-2.5 text-[8px] font-black uppercase tracking-widest rounded-lg border-2 transition-all shadow-sm active:scale-95 ${quickDate === btn.id ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-100 hover:border-indigo-200'}`}>
                                    {btn.l}
                                </button>
                             ))}
                        </div>
                    </div>

                    <div className="xl:col-span-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div className="space-y-2">
                            <label htmlFor="startDate" className="block text-[9px] font-black text-gray-800 uppercase tracking-widest ml-1">Tùy chỉnh ngày mượn</label>
                            <div className="flex items-center gap-2">
                                <input id="startDate" type="date" value={startDate} onChange={e => handleManualDateChange('start', e.target.value)} className="w-full px-3 py-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-black text-gray-900 focus:ring-2 focus:ring-indigo-600/10 outline-none shadow-inner"/>
                                <span className="text-indigo-600 font-black text-[10px] uppercase">đến</span>
                                <input id="endDate" type="date" value={endDate} onChange={e => handleManualDateChange('end', e.target.value)} className="w-full px-3 py-3 bg-gray-50 border border-gray-100 rounded-xl text-xs font-black text-gray-900 focus:ring-2 focus:ring-indigo-600/10 outline-none shadow-inner"/>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label htmlFor="statusFilter" className="block text-[9px] font-black text-gray-800 uppercase tracking-widest ml-1">Trạng thái xử lý</label>
                            <div className="flex flex-col gap-2">
                                <div className="relative">
                                    <select id="statusFilter" value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-black uppercase text-gray-900 outline-none cursor-pointer appearance-none shadow-inner">
                                        <option value="all">TẤT CẢ TRẠNG THÁI</option>
                                        <option value="pending">CHỜ DUYỆT</option>
                                        <option value="approved">ĐANG MƯỢN</option>
                                        <option value="returned">ĐÃ TRẢ</option>
                                        <option value="rejected">TỪ CHỐI</option>
                                    </select>
                                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                                </div>
                                <div className="relative group">
                                    <ShieldCheck className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-3.5 h-3.5" />
                                    <input type="text" value={handlerFilter} onChange={e => setHandlerFilter(e.target.value)} placeholder="Người xử lý..." className="w-full pl-9 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-xl text-[10px] font-black text-gray-900 outline-none shadow-inner uppercase placeholder:text-gray-400"/>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label htmlFor="searchText" className="block text-[9px] font-black text-gray-800 uppercase tracking-widest ml-1">Tìm nội dung nhanh</label>
                            <div className="relative group h-[calc(100%-24px)]">
                                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                                <input id="searchText" type="text" value={searchText} onChange={e => setSearchText(e.target.value)} placeholder="Tên, mã NV, thiết bị..." className="w-full h-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-2xl text-[11px] font-black text-gray-900 outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all shadow-inner uppercase placeholder:text-gray-400" />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
       </Card>

       {/* History Table */}
       <Card className="p-0 overflow-hidden border-none shadow-xl rounded-[2.5rem] md:rounded-[3rem] bg-white">
            <div className="overflow-x-auto w-full no-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50/80 border-b border-gray-100">
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-500">Thành viên</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-500">Thiết bị</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-500">Thời gian</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-500">Phê duyệt bởi</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-center text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-500">Trạng thái</th>
                            <th className="px-6 md:px-10 py-4 md:py-6 text-right text-[8px] md:text-[10px] font-black uppercase tracking-widest text-gray-500">Hành động</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {loading ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center animate-fade-in"><Loader2 className="w-10 h-10 animate-spin text-indigo-600 mx-auto opacity-20" /></td></tr>
                        ) : currentLogs.length === 0 ? (
                            <tr><td colSpan={6} className="px-10 py-32 text-center text-gray-300 font-black italic uppercase tracking-widest opacity-50 animate-fade-in">Không có kết quả phù hợp</td></tr>
                        ) : (
                            currentLogs.map((item) => (
                                <tr key={item.id} className="hover:bg-indigo-50/20 transition-all duration-300 group">
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 md:w-10 md:h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-xs md:text-sm border-2 border-indigo-400">
                                                {item.user_name?.charAt(0)}
                                            </div>
                                            <div>
                                                <div className="font-black text-gray-900 text-[11px] md:text-[13px] uppercase tracking-tighter">{item.user_name}</div>
                                                <div className="text-[7px] md:text-[9px] text-gray-500 font-black uppercase tracking-widest mt-0.5">{item.employee_id}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <span className="font-black text-gray-900 text-[11px] md:text-[13px] uppercase tracking-tight">{item.tool_name}</span>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="text-gray-900 font-black text-[10px] md:text-xs">M: {new Date(item.borrow_date).toLocaleDateString('vi-VN')}</div>
                                        {item.returned_at && (
                                            <div className="text-indigo-600 font-black text-[10px] md:text-xs mt-1">T: {new Date(item.returned_at).toLocaleDateString('vi-VN')}</div>
                                        )}
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6">
                                        <div className="flex items-center gap-1.5 text-[8px] md:text-[10px] font-black text-gray-800 uppercase">
                                            <ShieldCheck className="w-3 h-3 text-indigo-600" /> {getHandlerName(item)}
                                        </div>
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6 text-center">
                                        {getStatusBadge(item.status)}
                                    </td>
                                    <td className="px-6 md:px-10 py-4 md:py-6 text-right">
                                        {(item.status === 'returned' || item.status === 'rejected') ? (
                                            <button onClick={() => handleReBorrow(item)} disabled={reBorrowingId === item.id} className="inline-flex items-center gap-1.5 px-3 py-2 bg-indigo-50 text-indigo-700 border border-indigo-100 rounded-lg text-[9px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50 active:scale-95">
                                                {reBorrowingId === item.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Undo2 className="w-3.5 h-3.5" />}
                                                Mượn lại
                                            </button>
                                        ) : (
                                            <span className="text-gray-200 font-black text-[9px]">N/A</span>
                                        )}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Pagination Footer */}
            {filteredLogs.length > 0 && (
                <div className="bg-gray-50 border-t border-gray-100 p-6 md:p-10 flex flex-col sm:flex-row items-center justify-between gap-6 rounded-b-[2.5rem] md:rounded-b-[3rem]">
                    <div className="text-[9px] md:text-[11px] text-gray-500 font-black uppercase tracking-widest">
                      Hiển thị <span className="text-gray-900 font-black">{startIndex + 1}-{Math.min(filteredLogs.length, startIndex + ITEMS_PER_PAGE)}</span> trên {filteredLogs.length}
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-2.5 rounded-xl border border-gray-200 bg-white text-gray-800 disabled:opacity-30 hover:bg-indigo-50 transition-all active:scale-95"><ChevronLeft className="w-5 h-5" /></button>
                      <div className="flex items-center gap-1">
                        {Array.from({ length: totalPages }, (_, i) => i + 1).filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1).map((p, idx, arr) => (
                             <React.Fragment key={p}>
                                {idx > 0 && arr[idx-1] !== p - 1 && <span className="text-gray-300 px-1 font-bold">...</span>}
                                <button onClick={() => handlePageChange(p)} className={`w-9 h-9 md:w-11 md:h-11 rounded-xl text-[10px] font-black transition-all border-2 ${currentPage === p ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'}`}>{p}</button>
                             </React.Fragment>
                        ))}
                      </div>
                      <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-2.5 rounded-xl border border-gray-100 bg-white text-gray-800 disabled:opacity-30 hover:bg-indigo-50 transition-all active:scale-95"><ChevronRight className="w-5 h-5" /></button>
                    </div>
                </div>
            )}
       </Card>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import { BorrowRequest, User } from '../../../types';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  History, Search, Calendar, Filter, X, 
  User as UserIcon, ShieldCheck, ChevronDown, 
  SlidersHorizontal, ChevronLeft, ChevronRight, 
  Loader2, RefreshCw, AlertCircle, ChevronsLeft, ChevronsRight,
  Undo2, CheckCircle2, AlertTriangle, FileSpreadsheet,
  Download, ListFilter, CalendarDays, Activity, 
  ArrowUpRight, Clock, Box, LayoutPanelLeft, Timer, PackageCheck, XCircle, RotateCcw, TrendingUp
} from 'lucide-react';

interface HistoryLogProps {
  user: User;
}

interface ExtendedBorrowRequest extends BorrowRequest {
  approved_by?: string;
  rejected_by?: string;
  approved_at?: string;
  rejected_at?: string;
}

type QuickDateOption = 'custom' | 'today' | 'yesterday' | 'thisWeek' | '7days' | '30days' | '90days' | 'thisMonth';

const ITEMS_PER_PAGE = 10;

const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div 
      role="status"
      aria-live="polite"
      className={`fixed bottom-10 right-10 z-[100] ${type === 'success' ? 'bg-emerald-600' : 'bg-rose-600'} text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-fade-in-up border border-white/20 backdrop-blur-md`}
    >
      {type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertTriangle className="w-5 h-5" />}
      <p className="text-xs font-black uppercase tracking-tight">{message}</p>
      <button onClick={onClose} className="ml-2 hover:bg-white/20 p-1 rounded-full active:scale-90" aria-label="Close notification"><X className="w-4 h-4"/></button>
    </div>
  );
};

export const HistoryLog: React.FC<HistoryLogProps> = ({ user }) => {
  const [logs, setLogs] = useState<ExtendedBorrowRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reBorrowingId, setReBorrowingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const [searchText, setSearchText] = useState('');
  const [handlerFilter, setHandlerFilter] = useState(''); 
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [quickDate, setQuickDate] = useState<QuickDateOption>('custom');
  const [currentPage, setCurrentPage] = useState(1);

  const fetchHistory = async (silent = false) => {
    if (!user) return;
    if (!silent) setLoading(true);
    else setIsRefreshing(true);

    setError(null);
    try {
      let query = supabase.from('requests').select('*').order('borrow_date', { ascending: false });
      if (user.role !== 'admin') query = query.eq('user_id', user.id);
      const { data, error: fetchError } = await query;
      if (fetchError) throw fetchError;
      if (data) setLogs(data as ExtendedBorrowRequest[]);
    } catch (err: any) {
      console.error("Fetch history error:", err);
      setError("Không thể tải dữ liệu lịch sử.");
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  useEffect(() => { fetchHistory(); }, [user.id, user.role]);
  useEffect(() => { setCurrentPage(1); }, [searchText, handlerFilter, statusFilter, startDate, endDate]);

  const getHandlerName = (req: ExtendedBorrowRequest) => {
    if (req.status === 'approved' || req.status === 'returned') return req.approved_by || 'Quản lý';
    if (req.status === 'rejected') return req.rejected_by || 'Quản lý';
    return '-';
  };

  // Define getStatusBadge to resolve Error in file src/components/history/HistoryLog.tsx on line 359
  const getStatusBadge = (status: string) => {
    const configs: any = {
      pending: { color: 'bg-amber-50 text-amber-700 border-amber-100', icon: <Timer className="w-3 h-3" />, label: 'CHỜ DUYỆT' },
      approved: { color: 'bg-indigo-50 text-indigo-700 border-indigo-100', icon: <PackageCheck className="w-3 h-3" />, label: 'ĐANG MƯỢN' },
      returned: { color: 'bg-emerald-50 text-emerald-700 border-emerald-100', icon: <RotateCcw className="w-3 h-3" />, label: 'ĐÃ TRẢ' },
      rejected: { color: 'bg-rose-50 text-rose-700 border-rose-100', icon: <XCircle className="w-3 h-3" />, label: 'TỪ CHỐI' }
    };
    const c = configs[status] || configs.pending;
    return (
      <div className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[9px] font-black border shadow-sm ${c.color}`}>
        {c.icon} {c.label}
      </div>
    );
  };

  const handleReBorrow = async (log: ExtendedBorrowRequest) => {
    setReBorrowingId(log.id);
    try {
      const { error } = await supabase.from('requests').insert([{
        user_id: user.id, user_name: user.name, employee_id: user.employeeCode,
        tool_id: log.tool_id, tool_name: log.tool_name, borrow_date: new Date().toISOString(), status: 'pending'
      }]);
      if (error) throw error;
      setToast({ message: "Đã gửi yêu cầu mượn lại thành công!", type: 'success' });
      window.dispatchEvent(new CustomEvent('refresh-counts'));
      fetchHistory(true);
    } catch (err: any) {
      setToast({ message: "Lỗi: " + err.message, type: 'error' });
    } finally {
      setReBorrowingId(null);
    }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const searchLower = searchText.trim().toLowerCase();
      const handlerLower = handlerFilter.trim().toLowerCase();
      const matchesText = !searchLower || (log.user_name?.toLowerCase().includes(searchLower) || log.employee_id?.toLowerCase().includes(searchLower) || log.tool_name?.toLowerCase().includes(searchLower));
      const currentHandler = (getHandlerName(log) || '').toLowerCase();
      const matchesHandler = !handlerFilter || currentHandler.includes(handlerLower);
      const matchesStatus = statusFilter === 'all' || log.status === statusFilter;
      const logBorrowDate = new Date(log.borrow_date.split('T')[0]);
      const filterStartDate = startDate ? new Date(startDate) : null;
      const filterEndDate = endDate ? new Date(endDate) : null;
      const matchesDateRange = (!filterStartDate || logBorrowDate >= filterStartDate) && (!filterEndDate || logBorrowDate <= filterEndDate);
      return matchesText && matchesHandler && matchesStatus && matchesDateRange;
    });
  }, [logs, searchText, handlerFilter, statusFilter, startDate, endDate]);

  const summaryStats = useMemo(() => ({
    total: filteredLogs.length,
    pending: filteredLogs.filter(l => l.status === 'pending').length,
    borrowing: filteredLogs.filter(l => l.status === 'approved').length,
    completed: filteredLogs.filter(l => l.status === 'returned' || l.status === 'rejected').length
  }), [filteredLogs]);

  const handleExportExcel = () => {
    if (filteredLogs.length === 0) return alert("Không có dữ liệu để xuất.");
    const exportData = filteredLogs.map(log => ({
      'Người mượn': log.user_name, 'Mã nhân viên': log.employee_id, 'Thiết bị': log.tool_name,
      'Ngày mượn': new Date(log.borrow_date).toLocaleString('vi-VN'),
      'Ngày trả': log.returned_at ? new Date(log.returned_at).toLocaleString('vi-VN') : 'Chưa trả',
      'Người xử lý': getHandlerName(log),
      'Trạng thái': log.status === 'approved' ? 'Đang mượn' : log.status === 'returned' ? 'Đã trả' : log.status === 'rejected' ? 'Từ chối' : 'Chờ duyệt'
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "LichSuMuonTra");
    XLSX.writeFile(workbook, `Lich_su_muon_tra_${new Date().getTime()}.xlsx`);
  };

  const totalPages = Math.max(1, Math.ceil(filteredLogs.length / ITEMS_PER_PAGE));
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const currentLogs = filteredLogs.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleQuickDate = (option: QuickDateOption) => {
    setQuickDate(option);
    const today = new Date();
    const formatDate = (date: Date) => date.toISOString().split('T')[0];
    let start = new Date(); let end = new Date();
    switch (option) {
        case 'yesterday': start.setDate(today.getDate() - 1); end.setDate(today.getDate() - 1); break;
        case 'thisWeek': const day = today.getDay(); const diff = today.getDate() - day + (day === 0 ? -6 : 1); start = new Date(today.setDate(diff)); end = new Date(); break;
        case '7days': start.setDate(today.getDate() - 7); break;
        case '30days': start.setDate(today.getDate() - 30); break;
        case '90days': start.setDate(today.getDate() - 90); break;
        case 'thisMonth': start = new Date(today.getFullYear(), today.getMonth(), 1); end = new Date(today.getFullYear(), today.getMonth() + 1, 0); break;
        case 'today': default: break; 
    }
    setStartDate(formatDate(start)); setEndDate(formatDate(end));
  };

  // Define handleManualDateChange to resolve Error in file src/components/history/HistoryLog.tsx on line 273 and 275
  const handleManualDateChange = (type: 'start' | 'end', value: string) => {
    setQuickDate('custom');
    if (type === 'start') setStartDate(value);
    else setEndDate(value);
  };

  const clearFilters = () => {
    setSearchText(''); setHandlerFilter(''); setStartDate(''); setEndDate(''); setStatusFilter('all'); setQuickDate('custom'); setCurrentPage(1);
  };

  const activeFiltersCount = [searchText.trim(), handlerFilter.trim(), startDate, endDate, statusFilter !== 'all'].filter(Boolean).length;

  return (
    <div className="space-y-4 md:space-y-6 animate-fade-in pb-10 max-w-7xl mx-auto">
       {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

       {/* Header Panel */}
       <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-gray-100">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-indigo-600 rounded-[1.8rem] shadow-xl shadow-indigo-100 text-white">
                    <History className="w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-xl md:text-2xl font-black text-gray-900 tracking-tight leading-none italic uppercase">Lịch sử hoạt động</h2>
                    <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-1 opacity-70">Hồ sơ tra cứu mượn trả thiết bị</p>
                </div>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={handleExportExcel} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 bg-emerald-50 text-emerald-600 rounded-2xl text-[9px] font-black uppercase tracking-widest transition-all border border-emerald-100 hover:bg-emerald-600 hover:text-white shadow-sm active:scale-95"><FileSpreadsheet className="w-4 h-4"/> Xuất Excel</button>
                <button onClick={() => fetchHistory(true)} className="p-4 bg-gray-50 hover:bg-gray-100 text-gray-400 rounded-2xl transition-all border border-gray-100 shadow-sm active:scale-95">
                  {isRefreshing ? <Loader2 className="w-5 h-5 animate-spin"/> : <RefreshCw className="w-5 h-5"/>}
                </button>
            </div>
       </div>

       {/* Summary Stats Cards */}
       <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
          <Card className="p-5 md:p-6 border-none bg-white shadow-sm rounded-[1.5rem] md:rounded-[2rem] flex flex-col justify-between">
            <div className="flex justify-between items-start mb-2">
              <div className="p-2.5 bg-purple-100 text-purple-600 rounded-lg"><LayoutPanelLeft className="w-5 h-5"/></div>
              <span className="text-[8px] md:text-[10px] font-black text-purple-400 uppercase tracking-widest">Tổng lượt</span>
            </div>
            <p className="text-xl md:text-3xl font-black text-gray-900 tabular-nums">{summaryStats.total}</p>
          </Card>
