                        <div className="grid grid-cols-3 md:grid-cols-4 gap-2">
                             {[
                               {id: 'today', l: 'H.Nay'}, {id: 'yesterday', l: 'H.Qua'}, {id: 'thisWeek', l: 'Tuần này'}, 
                               {id: '7days', l: '7 ngày'}, {id: '30days', l: '30 ngày'}, {id: '90days', l: '90 ngày'}, {id: 'thisMonth', l: 'Tháng này'}
