import React, { useState, useMemo, useContext } from 'react';
import { supabase } from '../../lib/supabase';
import { LucideLoader2, UserCircle, ShieldCheck, Lock, AlertCircle, TreePine, Gift, Sparkles } from 'lucide-react';
