  const [employeeCode, setEmployeeCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isNoel = theme === 'noel';
  const isTet = theme === 'tet';

  const festiveConfig = useMemo(() => {
    if (isNoel) return {
      bg: 'bg-[#fef2f2]',
      accent: 'bg-gradient-to-br from-red-600 to-red-800',
      shadow: 'shadow-red-200',
      button: 'bg-red-600 hover:bg-red-700 shadow-red-300',
      border: 'border-red-100',
      icon: <TreePine className="text-white w-10 h-10" />,
      tag: "Christmas Season 🎄",
      textColor: 'text-red-950',
      labelColor: 'text-gray-700'
    };
    if (isTet) return {
      bg: 'bg-[#fff7ed]',
      accent: 'bg-gradient-to-br from-red-600 via-orange-700 to-amber-800',
      shadow: 'shadow-orange-200',
      button: 'bg-red-600 hover:bg-red-700 shadow-orange-300',
      border: 'border-amber-200',
      icon: <Gift className="text-yellow-400 w-10 h-10 animate-bounce" />,
      tag: "Lunar New Year 🧧 Team V1",
      textColor: 'text-red-950',
      labelColor: 'text-red-900'
    };
    return {
