      <div className={`absolute bottom-[-10%] right-[-5%] w-[40rem] h-[40rem] ${isTet ? 'bg-red-200/40' : 'bg-purple-200/40'} rounded-full blur-[120px] animate-pulse`}></div>

      <div className="max-w-md w-full bg-white/80 backdrop-blur-xl rounded-[3rem] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.15)] border border-white/40 overflow-hidden relative z-10 animate-zoom-in">
        <div className="p-10 pt-14 text-center">
          <div className={`mx-auto ${festiveConfig.accent} w-24 h-24 rounded-[2.5rem] flex items-center justify-center mb-8 shadow-2xl ${festiveConfig.shadow} rotate-3 hover:rotate-0 transition-all duration-500`}>
            {festiveConfig.icon}
          </div>
          <h2 className={`text-4xl font-extrabold ${isTet ? 'text-red-900' : 'text-slate-900'} tracking-tight leading-none`}>Manager V</h2>
          <p className={`text-[10px] font-bold uppercase tracking-[0.3em] mt-4 ${festiveConfig.textColor} opacity-60 flex items-center justify-center gap-3`}>
             <span className="w-4 h-[1px] bg-current opacity-20"></span>
             {festiveConfig.tag}
             <span className="w-4 h-[1px] bg-current opacity-20"></span>
          </p>
        </div>

        <div className="px-10 pb-16">
          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-1.5">
              <label className={`text-[11px] font-bold uppercase tracking-wider ml-1 ${festiveConfig.labelColor} opacity-70`}>Mã định danh</label>
              <div className="relative group">
                <UserCircle className={`absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isTet || isNoel ? 'text-red-400' : 'text-slate-400'} group-focus-within:text-indigo-600`} />
                <input
