            <div className="space-y-1.5">
              <label className={`text-[11px] font-bold uppercase tracking-wider ml-1 ${festiveConfig.labelColor} opacity-70`}>Mật khẩu</label>
              <div className="relative group">
                <Lock className={`absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${isTet || isNoel ? 'text-red-400' : 'text-slate-400'} group-focus-within:text-indigo-600`} />
