import React, { useState, useEffect, useMemo, useContext } from 'react';
import { User, OvertimeRequest, DayConfig, Employee } from '../../../types';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import * as XLSX from 'xlsx';
import { 
  Clock, Calendar as CalendarIcon, X, 
  Timer, Loader2, ChevronLeft, ChevronRight, ChevronDown, Download, BarChart3, Users, User as UserIcon, Settings, Check, Trash2, 
  Activity, Home, Briefcase, FileText, CalendarRange, UserCheck, Search, Filter,
  FileSpreadsheet, FileDown, CalendarDays, Eye, Trophy, Target, Award, Info, Undo2, ArrowRight, Snowflake, Sparkles, UserPlus, UserRoundPen, ChevronUp, Gift, Send, Save
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { ThemeContext } from '../../../App';

interface OvertimeRegistrationProps {
  user: User;
}

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

const timeToNumber = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h + m / 60;
};

const todayStr = new Date().toISOString().split('T')[0];

export const OvertimeRegistration: React.FC<OvertimeRegistrationProps> = ({ user }) => {
  const { theme } = useContext(ThemeContext);
  const [activeTab, setActiveTab] = useState<'calendar' | 'personal' | 'stats'>('calendar');
  const [requests, setRequests] = useState<OvertimeRequest[]>([]);
  const [dayConfigs, setDayConfigs] = useState<Record<string, boolean>>({}); 
  const [allEmployees, setAllEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);

  const [currentDate, setCurrentDate] = useState(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isConfirmCancelOpen, setIsConfirmCancelOpen] = useState(false); 
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isConfigUpdating, setIsConfigUpdating] = useState(false);
  const [isListExpanded, setIsListExpanded] = useState(false); 

  const [selectedDateStr, setSelectedDateStr] = useState('');
  const [targetUserId, setTargetUserId] = useState(user.id);
  const [startTime, setStartTime] = useState('17:30');
  const [endTime, setEndTime] = useState('20:00');
  const [reason, setReason] = useState('');

  const [editingRequestId, setEditingRequestId] = useState<string | null>(null);

  const [exportStartDate, setExportStartDate] = useState(todayStr);
  const [exportEndDate, setExportEndDate] = useState(todayStr);
  const [statsViewDate, setStatsViewDate] = useState(todayStr);

  const isAdmin = user.role === 'admin';
  const isDefault = theme === 'default';
  const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
  const isTet = theme === 'tet';

  useEffect(() => {
    fetchRequests();
    fetchDayConfigs();
    if (isAdmin) fetchEmployees();
  }, [user.id, currentDate]);

  const currentSelectedRequest = useMemo(() => {
    if (!selectedDateStr || !targetUserId) return null;
    return requests.find(r => r.date === selectedDateStr && r.user_id === targetUserId) || null;
  }, [requests, selectedDateStr, targetUserId]);

  const dayRequestsInModal = useMemo(() => {
    const dayReqs = requests.filter(r => r.date === selectedDateStr);
    const uniqueReqs: OvertimeRequest[] = [];
    const seenUsers = new Set();

    dayReqs.forEach(req => {
      if (!seenUsers.has(req.user_id)) {
        seenUsers.add(req.user_id);
        uniqueReqs.push(req);
      }
    });
    return uniqueReqs;
  }, [requests, selectedDateStr]);

  useEffect(() => {
    if (!selectedDateStr) return;

    if (currentSelectedRequest) {
        setStartTime(currentSelectedRequest.start_time);
        setEndTime(currentSelectedRequest.end_time);
        setReason(currentSelectedRequest.reason || '');
        setEditingRequestId(currentSelectedRequest.id);
    } else {
        const dateObj = new Date(selectedDateStr);
        const dayOfWeek = dateObj.getDay(); 
        const defaultIsWorking = dayOfWeek !== 0 && dayOfWeek !== 6;
        const isWorkingDay = dayConfigs[selectedDateStr] ?? defaultIsWorking;

        if (isWorkingDay) {
            setStartTime(dayOfWeek === 6 ? '14:30' : '17:30');
            setEndTime('20:00');
        } else {
            setStartTime('08:00');
            setEndTime('20:00');
        }
        setReason('');
        setEditingRequestId(null);
    }
  }, [selectedDateStr, targetUserId, currentSelectedRequest, dayConfigs]);

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
          .from('ot_requests')
          .select('*, users(employee_id, name)');
      if (error) throw error;
      if (data) setRequests(data as OvertimeRequest[]);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    const { data } = await supabase.from('users').select('*').order('name');
    if (data) setAllEmployees(data as Employee[]);
  };

  const fetchDayConfigs = async () => {
    const startOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-01`;
    const endOfMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}`;
    const { data } = await supabase.from('day_configs').select('*').gte('date', startOfMonth).lte('date', endOfMonth);
    if (data) {
        const configMap: Record<string, boolean> = {};
        (data as DayConfig[]).forEach(cfg => configMap[cfg.date] = cfg.is_working_day);
        setDayConfigs(configMap);
    }
  };

  const updateDayWorkingStatus = async (status: boolean) => {
    if (!isAdmin || !selectedDateStr) return;
    setIsConfigUpdating(true);
    try {
        const { error } = await supabase.from('day_configs').upsert({ date: selectedDateStr, is_working_day: status });
        if (error) throw error;
        setDayConfigs(prev => ({ ...prev, [selectedDateStr]: status }));
    } catch (err: any) {
        alert("Lỗi cập nhật: " + err.message);
    } finally {
        setIsConfigUpdating(false);
    }
  };

  const calculateHours = (start: string, end: string, dateStr: string) => {
    if (!dateStr || !start || !end) return 0;
    const s = timeToNumber(start);
    const e = Math.min(timeToNumber(end), 22.0);
    const diff = e - s;
    if (diff <= 0) return 0;

    const dateObj = new Date(dateStr);
    const defaultIsWorking = dateObj.getDay() !== 0 && dateObj.getDay() !== 6;
    const isWorkDay = dayConfigs[dateStr] ?? defaultIsWorking;

    let ded = 0;
    if (diff >= 8) ded = 1.0;
    else if (diff > 4 && (!isWorkDay || diff > 5)) ded = 0.5;
    return parseFloat(Math.max(0, diff - ded).toFixed(2));
  };

  const calculatedHours = useMemo(() => calculateHours(startTime, endTime, selectedDateStr), [startTime, endTime, selectedDateStr, dayConfigs]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (calculatedHours <= 0) return alert("Giờ làm không hợp lệ.");

    setIsSubmitting(true);
    try {
      const { data: existing } = await supabase
        .from('ot_requests')
        .select('id')
        .eq('user_id', targetUserId)
        .eq('date', selectedDateStr)
        .maybeSingle();

      const finalEditingId = editingRequestId || existing?.id;

      const payload = {
          user_id: targetUserId, 
          date: selectedDateStr, 
          start_time: startTime,
          end_time: endTime, 
          total_hours: calculatedHours, 
          reason: reason.trim(), 
          status: 'approved' 
      };

      const res = finalEditingId 
        ? await supabase.from('ot_requests').update(payload).eq('id', finalEditingId)
        : await supabase.from('ot_requests').insert([payload]);

      if (res.error) throw res.error;

      await fetchRequests();
      setIsModalOpen(false);
    } catch (err: any) {
        alert("Lỗi: " + err.message);
    } finally {
        setIsSubmitting(false);
    }
  };

  const handleCancelRequest = async () => {
    if (!editingRequestId) return;
    setIsDeleting(true);
    try {
        const { error } = await supabase.from('ot_requests').delete().eq('id', editingRequestId);
        if (error) throw error;
        setRequests(prev => prev.filter(r => r.id !== editingRequestId));
        setIsConfirmCancelOpen(false);
        setIsModalOpen(false);
    } catch (err: any) {
        alert(err.message);
    } finally {
        setIsDeleting(false);
    }
  };

  const handleExportExcelPro = (mode: 'today' | 'range') => {
    let dataToExport = [];
    if (mode === 'today') {
      dataToExport = requests.filter(r => r.date === todayStr);
    } else {
      dataToExport = requests.filter(r => r.date >= exportStartDate && r.date <= exportEndDate);
    }

    if (dataToExport.length === 0) return alert("Không có dữ liệu để xuất.");

    const workbook = XLSX.utils.book_new();
    const wscols = [
      {wch: 6},  {wch: 15}, {wch: 25}, {wch: 12}, {wch: 12}, {wch: 12}, {wch: 40}, {wch: 15}
    ];

    const groupedByDate: Record<string, OvertimeRequest[]> = {};
    dataToExport.forEach(req => {
        if (!groupedByDate[req.date]) groupedByDate[req.date] = [];
        groupedByDate[req.date].push(req);
    });

    const sortedDates = Object.keys(groupedByDate).sort();

    sortedDates.forEach(date => {
        const userMap = new Map();
        groupedByDate[date].forEach(r => userMap.set(r.user_id, r));

        const dayRequests = Array.from(userMap.values())
          .sort((a, b) => (a.users?.employee_id || "").localeCompare(b.users?.employee_id || ""));

        const formattedData = dayRequests.map((req, idx) => ({
          'STT': idx + 1,
          'Mã nhân viên': req.users?.employee_id || 'N/A',
          'Họ và tên': req.users?.name || 'Ẩn danh',
          'Giờ bắt đầu': req.start_time,
          'Giờ kết thúc': req.end_time,
          'Tổng giờ': req.total_hours,
          'Nội dung công việc': req.reason,
          'Trạng thái': req.status === 'approved' ? 'Đã duyệt' : 'Đang xử lý'
        }));
        const worksheet = XLSX.utils.json_to_sheet(formattedData);
        worksheet['!cols'] = wscols;
        XLSX.utils.book_append_sheet(workbook, worksheet, date);
    });

    const fileName = `Bao_cao_tang_ca_${mode === 'today' ? todayStr : (exportStartDate + '_den_' + exportEndDate)}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const handleDateClick = (dateStr: string) => {
    setSelectedDateStr(dateStr);
    setTargetUserId(user.id);
    setIsModalOpen(true);
    setIsListExpanded(false); 
  };

  const myStats = useMemo(() => {
    const my = requests.filter(r => r.user_id === user.id && r.date.startsWith(currentMonthStr));
    const total = my.filter(r => r.status === 'approved').reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    const trend = Array.from({length: getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth())}, (_, i) => {
        const d = i + 1;
        const dStr = `${currentMonthStr}-${String(d).padStart(2, '0')}`;
        return { day: d, hours: my.find(r => r.date === dStr)?.total_hours || 0 };
    });
    return { total, count: my.length, pending: my.filter(r => r.status === 'pending').length, trend };
  }, [requests, user.id, currentMonthStr, currentDate]);

  const teamMonthlyStats = useMemo(() => {
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    const uniqueUserIds = new Set(monthlyApproved.map(r => r.user_id));
    const totalHours = monthlyApproved.reduce((sum, r) => sum + Number(r.total_hours || 0), 0);
    return { totalHours, activeMembers: uniqueUserIds.size };
  }, [requests, currentMonthStr]);

  const topRankings = useMemo(() => {
    const employeeMap: Record<string, { name: string; hours: number; count: number }> = {};
    const monthlyApproved = requests.filter(r => r.date.startsWith(currentMonthStr) && r.status === 'approved');
    monthlyApproved.forEach(req => {
        const id = req.user_id;
        if (!employeeMap[id]) employeeMap[id] = { name: req.users?.name || 'Ẩn danh', hours: 0, count: 0 };
        employeeMap[id].hours = Number((employeeMap[id].hours + Number(req.total_hours || 0)).toFixed(2));
        employeeMap[id].count += 1;
    });
    return Object.values(employeeMap).sort((a, b) => b.hours - a.hours).slice(0, 10);
  }, [requests, currentMonthStr]);

  const targetedRegistrations = useMemo(() => {
    const dayReqs = requests.filter(r => r.date === statsViewDate);
    const uniqueMap = new Map();
    dayReqs.forEach(r => uniqueMap.set(r.user_id, r));
    return Array.from(uniqueMap.values()).sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [requests, statsViewDate]);

  const renderCalendarDays = () => {
    const days = [];
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = getFirstDayOfMonth(year, month);
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 
    const totalDays = getDaysInMonth(year, month);

    for (let i = 0; i < startOffset; i++) {
        days.push(<div key={`empty-${i}`} className="h-24 md:h-40 bg-slate-50/40 border border-slate-100/50"></div>);
    }

    for (let d = 1; d <= totalDays; d++) {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        const dayRequestsLocal = requests.filter(r => r.date === dateStr);
        const uniqueUserIds = new Set(dayRequestsLocal.map(r => r.user_id));
        const myRequest = dayRequestsLocal.find(r => r.user_id === user.id);
        const isToday = todayStr === dateStr;
        const isPast = dateStr < todayStr;
        const dateObj = new Date(year, month, d);
        const isActuallyWorking = dayConfigs[dateStr] ?? (dateObj.getDay() !== 0 && dateObj.getDay() !== 6);

        days.push(
            <div 
                key={d} 
                onClick={() => handleDateClick(dateStr)}
                className={`h-24 md:h-40 border border-slate-100 p-2 relative transition-all cursor-pointer group flex flex-col 
                  ${isToday ? 'bg-indigo-50/50 ring-inset ring-2 ring-indigo-500/40 z-10' : 'bg-white hover:bg-slate-50'} 
                  ${isPast ? 'opacity-80' : 'opacity-100'}`}
            >
                <div className="flex justify-between items-start mb-2">
                    <span className={`text-xs font-bold ${isToday ? 'bg-indigo-600 text-white w-6 h-6 rounded-lg flex items-center justify-center shadow-lg' : 'text-slate-600'}`}>
                        {d}
                    </span>
                    {!isActuallyWorking && (
                      <span className="text-[7px] font-extrabold px-1.5 py-0.5 rounded bg-rose-100 text-rose-600 uppercase">Nghỉ</span>
                    )}
                </div>

                <div className="flex-1 flex flex-col justify-start gap-1 overflow-hidden">
                    {myRequest && (
                      <div className="flex items-center gap-1.5 bg-emerald-600 text-white px-2 py-1 rounded-lg shrink-0 shadow-sm border border-white/20">
                        <UserIcon className="w-2.5 h-2.5" />
                        <span className="text-[8px] font-bold truncate uppercase">{myRequest.total_hours}h</span>
                      </div>
                    )}
                    <div className="flex flex-wrap gap-1">
                      {dayRequestsLocal.slice(0, 3).map((req, idx) => (
                        <div key={idx} className="w-5 h-5 rounded-lg bg-indigo-100 text-indigo-700 border border-indigo-200 flex items-center justify-center shrink-0 shadow-sm" title={req.users?.name}>
                           <span className="text-[8px] font-bold uppercase">{req.users?.name?.charAt(0)}</span>
                        </div>
                      ))}
                      {uniqueUserIds.size > 3 && (
                        <div className="w-5 h-5 rounded-lg bg-slate-100 text-slate-400 border border-slate-200 flex items-center justify-center shrink-0">
                           <span className="text-[7px] font-bold">+{uniqueUserIds.size - 3}</span>
                        </div>
                      )}
                    </div>
                </div>

                {uniqueUserIds.size > 0 && (
                    <div className="absolute bottom-2 right-2 bg-slate-900 text-white text-[8px] px-1.5 py-0.5 rounded-md font-bold shadow-lg">
                        {uniqueUserIds.size} NV
                    </div>
                )}
            </div>
        );
    }
    return days;
  };

  return (
    <div className="space-y-8 h-full flex flex-col animate-fade-in max-w-[1400px] mx-auto w-full px-4 md:px-0 pb-32">
        {/* REFINED HEADER */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 glass-card p-6 md:p-8 rounded-[2.5rem] vibrant-shadow">
            <div className="flex items-center gap-5">
                <div className={`p-5 rounded-3xl shadow-2xl text-white transform hover:rotate-3 transition-transform ${isTet ? 'bg-red-600' : 'bg-indigo-600'}`}>
                    <Clock className="w-8 h-8" />
                </div>
                <div>
                    <h2 className="text-2xl md:text-4xl font-extrabold text-slate-900 tracking-tight leading-none">
                        Tăng ca
                        {isTet && <Sparkles className="inline ml-2 w-6 h-6 text-orange-500 animate-pulse" />}
                    </h2>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-2 flex items-center gap-2">
                       <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
                       Hệ thống ghi nhận thời gian
                    </p>
                </div>
            </div>
            <div className="flex bg-slate-100/80 p-1.5 rounded-2xl border border-slate-200 shadow-inner w-full lg:w-auto backdrop-blur-md">
                {['calendar', 'personal', 'stats'].map(t => (
                    <button key={t} onClick={() => setActiveTab(t as any)} className={`flex-1 lg:flex-none px-6 md:px-10 py-3 rounded-xl text-[11px] font-bold transition-all uppercase tracking-widest ${activeTab === t ? (isTet ? 'bg-red-600 text-white shadow-lg' : 'bg-white text-indigo-700 shadow-md') : 'text-slate-500 hover:text-slate-900'}`}>
                        {t === 'calendar' ? 'Lịch' : t === 'personal' ? 'Cá nhân' : 'Thống kê'}
                    </button>
                ))}
            </div>
        </div>

        <div className="flex-1 min-h-0">
            {activeTab === 'calendar' && (
                <div className="vibrant-shadow rounded-[3rem] overflow-hidden bg-white border border-slate-100">
                    <div className="flex items-center justify-between p-6 md:p-10 bg-white border-b border-slate-100">
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()-1, 1))} className="p-3 hover:bg-slate-100 rounded-2xl text-slate-400 hover:text-indigo-600 transition-all"><ChevronLeft className="w-7 h-7"/></button>
                        <h3 className="text-xl md:text-3xl font-extrabold text-slate-900 tracking-tight italic">Tháng {currentDate.getMonth()+1} / {currentDate.getFullYear()}</h3>
                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth()+1, 1))} className="p-3 hover:bg-slate-100 rounded-2xl text-slate-400 hover:text-indigo-600 transition-all"><ChevronRight className="w-7 h-7"/></button>
                    </div>
                    <div className="grid grid-cols-7 bg-slate-50/50 text-[10px] font-bold uppercase text-slate-400 border-b border-slate-100">
                        {['Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7', 'Chủ Nhật'].map((d, i) => (
                            <div key={d} className={`py-6 text-center tracking-widest ${i >= 5 ? 'text-rose-500' : ''}`}>{d}</div>
                        ))}
                    </div>
                    <div className="grid grid-cols-7 auto-rows-fr bg-slate-100 gap-[1px]">
                        {renderCalendarDays()}
                    </div>
                </div>
            )}

            {activeTab === 'personal' && (
                <div className="space-y-8 animate-page-transition">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className={`p-8 rounded-[2.5rem] shadow-2xl border-none text-white relative overflow-hidden ${isTet ? 'bg-gradient-to-br from-red-600 to-red-800' : 'bg-gradient-to-br from-indigo-600 to-purple-800'}`}>
                            <div className="absolute top-[-20%] right-[-10%] w-32 h-32 bg-white/10 rounded-full blur-2xl"></div>
                            <h3 className="text-xs font-bold uppercase opacity-70 tracking-widest mb-4">Tổng giờ T{currentDate.getMonth()+1}</h3>
                            <div className="flex items-baseline gap-2">
                                <span className="text-5xl font-extrabold tabular-nums leading-none">{myStats.total.toFixed(1)}</span>
                                <span className="text-lg font-bold opacity-60">giờ</span>
                            </div>
                        </div>

                        <Card className="p-8 border-none bg-white rounded-[2.5rem] shadow-xl flex items-center gap-6">
                            <div className="p-5 bg-emerald-50 rounded-3xl text-emerald-600"><Check className="w-10 h-10"/></div>
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Ngày đăng ký</p>
                                <p className="text-4xl font-extrabold text-slate-900 tabular-nums">{myStats.count}</p>
                            </div>
                        </Card>

                        <Card className="p-8 border-none bg-white rounded-[2.5rem] shadow-xl flex items-center gap-6">
                            <div className="p-5 bg-amber-50 rounded-3xl text-amber-600"><Timer className="w-10 h-10"/></div>
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Đang chờ duyệt</p>
                                <p className="text-4xl font-extrabold text-slate-900 tabular-nums">{myStats.pending}</p>
                            </div>
                        </Card>
                    </div>

                    <Card className="rounded-[3rem] p-8 md:p-12 shadow-2xl border-none bg-white min-h-[500px]">
                        <div className="flex justify-between items-center mb-10">
                            <h4 className="text-xl font-extrabold text-slate-900 uppercase flex items-center gap-3"><Activity className="text-indigo-600" /> Biểu đồ hoạt động</h4>
                            <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 rounded-xl text-[10px] font-bold text-slate-500 border border-slate-100">Cập nhật lúc {new Date().toLocaleTimeString('vi-VN', {hour:'2-digit', minute:'2-digit'})}</div>
                        </div>
                        <div className="h-80 md:h-[450px] w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={myStats.trend}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                    <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} dy={10} />
                                    <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                                    <Tooltip 
                                        cursor={{fill: '#f8fafc'}}
                                        contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 40px rgba(0,0,0,0.1)' }}
                                    />
                                    <Bar dataKey="hours" fill={isTet ? "#dc2626" : "#4f46e5"} radius={[6, 6, 0, 0]} barSize={16} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </Card>
                </div>
            )}

            {activeTab === 'stats' && (
                <div className="space-y-8 animate-page-transition">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <Card className="bg-white p-8 border-none shadow-xl rounded-[2.5rem] flex items-center gap-6">
                            <div className={`p-5 ${isTet ? 'bg-red-50 text-red-600' : 'bg-indigo-50 text-indigo-600'} rounded-3xl`}><Users className="w-10 h-10"/></div>
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Thành viên OT</p>
                                <p className="text-4xl font-extrabold text-slate-900">{teamMonthlyStats.activeMembers}</p>
                            </div>
                        </Card>
                        <Card className="bg-white p-8 border-none shadow-xl rounded-[2.5rem] flex items-center gap-6">
                            <div className={`p-5 bg-emerald-50 text-emerald-600 rounded-3xl`}><Timer className="w-10 h-10"/></div>
                            <div>
                                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Tổng giờ nhóm</p>
                                <p className="text-4xl font-extrabold text-slate-900">{teamMonthlyStats.totalHours.toFixed(1)}h</p>
                            </div>
                        </Card>
                        <Card className={`${isTet ? 'bg-gradient-to-br from-red-600 to-red-800' : 'bg-gradient-to-br from-slate-800 to-slate-900'} text-white p-8 border-none shadow-2xl rounded-[2.5rem] flex items-center gap-6`}>
                            <div className="p-5 bg-white/10 rounded-3xl"><Target className="w-10 h-10"/></div>
                            <div>
                                <p className="text-xs font-bold text-white/60 uppercase tracking-widest">Hôm nay</p>
                                <p className="text-4xl font-extrabold text-white">{requests.filter(r => r.date === todayStr).length} NV</p>
                            </div>
                        </Card>
                    </div>

                    <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">
                        {/* Chi tiết đăng ký theo ngày */}
                        <div className="xl:col-span-8 space-y-6">
                            <div className="glass-card rounded-[3rem] p-0 overflow-hidden shadow-2xl">
                                <div className="p-8 bg-white/50 border-b border-slate-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                                    <div>
                                        <h4 className="text-2xl font-extrabold text-slate-900 tracking-tight flex items-center gap-3">
                                            Danh sách đăng ký 
                                            <span className="px-3 py-1 bg-indigo-600 text-white text-[10px] rounded-full font-black">
                                                {targetedRegistrations.length} NV
                                            </span>
                                        </h4>
                                        <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Dữ liệu ngày {statsViewDate.split('-').reverse().join('/')}</p>
                                    </div>
                                    <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-slate-100 shadow-sm w-full md:w-auto">
                                        <CalendarIcon className="w-5 h-5 text-slate-400" />
                                        <input type="date" value={statsViewDate} onChange={(e) => setStatsViewDate(e.target.value)} className="bg-transparent text-sm font-bold outline-none cursor-pointer text-slate-900 w-full"/>
                                    </div>
                                </div>
                                <div className="p-8 space-y-4 max-h-[600px] overflow-y-auto no-scrollbar">
                                    {targetedRegistrations.length === 0 ? (
                                        <div className="py-24 text-center flex flex-col items-center gap-4">
                                            <div className="p-6 bg-slate-50 rounded-full"><Info className="w-10 h-10 text-slate-200"/></div>
                                            <p className="font-bold uppercase text-xs tracking-widest text-slate-300">Không tìm thấy dữ liệu đăng ký</p>
                                        </div>
                                    ) : (
                                        targetedRegistrations.map((req, idx) => (
                                            <div key={idx} className="p-6 rounded-[2rem] bg-white border border-slate-100 hover:border-indigo-200 transition-all flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6 group shadow-sm hover:shadow-xl">
                                                <div className="flex items-center gap-5">
                                                    <div className="relative">
                                                        <div className={`w-16 h-16 text-white rounded-3xl flex items-center justify-center font-extrabold text-2xl shadow-xl transition-transform group-hover:rotate-3 ${isTet ? 'bg-red-600' : 'bg-indigo-600'}`}>{req.users?.name?.charAt(0)}</div>
                                                        <div className="absolute -top-2 -left-2 w-7 h-7 bg-slate-900 text-white text-[10px] font-black rounded-xl flex items-center justify-center border-2 border-white shadow-md z-10">{idx + 1}</div>
                                                    </div>
                                                    <div>
                                                        <h5 className="font-extrabold text-slate-900 text-lg tracking-tight uppercase leading-none">{req.users?.name}</h5>
                                                        <div className="flex flex-wrap items-center gap-3 mt-3">
                                                          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-3 py-1 bg-slate-100 rounded-full">{req.users?.employee_id}</span>
                                                          <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-widest px-3 py-1 bg-indigo-50 rounded-full border border-indigo-100">{req.start_time} - {req.end_time}</span>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="text-left sm:text-right w-full sm:w-auto pt-4 sm:pt-0 border-t sm:border-t-0 border-slate-100 flex sm:flex-col justify-between items-center sm:items-end">
                                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1 hidden sm:block">Giờ làm việc</p>
                                                    <div className="flex items-baseline gap-1">
                                                      <span className="text-3xl font-extrabold text-slate-900 tabular-nums">{req.total_hours.toFixed(1)}</span>
                                                      <span className="text-xs font-bold text-slate-400 uppercase">H</span>
                                                    </div>
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="xl:col-span-4 space-y-8">
                            <Card className="rounded-[3rem] p-0 overflow-hidden shadow-2xl border-none bg-white">
                                <div className={`p-8 ${isTet ? 'bg-red-600' : 'bg-indigo-600'} text-white relative overflow-hidden`}>
