import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Wrench, TrendingUp, Loader2, Package, ShoppingBag, BarChart as BarChartIcon, ArrowUpRight, Activity } from 'lucide-react';

const COLORS = ['#6366f1', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981', '#3b82f6'];

interface SafeChartContainerProps {
  children: React.ReactNode;
  height?: number;
  hasData?: boolean;
}

const SafeChartContainer: React.FC<SafeChartContainerProps> = ({ children, height = 300, hasData = true }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    if (!containerRef.current) return;

    const observer = new ResizeObserver((entries) => {
      if (!entries.length) return;
      const { width, height: contentHeight } = entries[0].contentRect;
      if (width > 0) {
        setDimensions({ width, height: contentHeight || height });
      }
    });

    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [height]);

  if (!hasData) {
    return (
      <div style={{ height }} className="w-full flex flex-col items-center justify-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-100">
         <div className="p-5 bg-white rounded-3xl shadow-sm mb-4">
            <BarChartIcon className="w-8 h-8 text-slate-200" />
         </div>
         <span className="text-slate-400 text-xs font-bold uppercase tracking-widest">Chưa có dữ liệu thống kê</span>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef} 
      style={{ 
        height: `${height}px`, 
        width: '100%', 
        position: 'relative',
        minWidth: '0px'
      }} 
      className="overflow-hidden" 
    >
      {isMounted && dimensions.width > 0 ? (
        <ResponsiveContainer width="100%" height="100%">
          {children as React.ReactElement}
        </ResponsiveContainer>
      ) : (
        <div className="w-full h-full flex flex-col items-center justify-center bg-slate-50/30 rounded-3xl">
           <Loader2 className="w-6 h-6 text-indigo-500 animate-spin mb-3" />
           <span className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Loading charts...</span>
        </div>
      )}
    </div>
  );
};

export const DashboardStats: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalToolsQuantity: 0,
    totalToolsAvailable: 0,
    borrowedTools: 0,
    pendingRequests: 0,
  });
  const [barData, setBarData] = useState<any[]>([]);
  const [pieData, setPieData] = useState<any[]>([]);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [toolsRes, requestsRes] = await Promise.all([
        supabase.from('tools').select('quantity, available, status'),
        supabase.from('requests').select('status, borrow_date')
      ]);

      const tools = toolsRes.data || [];
      const requests = requestsRes.data || [];

      const totalToolsQuantity = tools.reduce((sum, tool) => sum + (tool.quantity || 0), 0);
      const totalToolsAvailable = tools.reduce((sum, tool) => sum + (tool.status === 'active' ? (tool.available || 0) : 0), 0);
      const borrowedTools = requests.filter(r => r.status === 'approved').length;
      const pendingRequests = requests.filter(r => r.status === 'pending').length;

      setStats({
        totalToolsQuantity,
        totalToolsAvailable,
        borrowedTools,
        pendingRequests
      });

      const pieChartData = [
        { name: 'Sẵn có', value: totalToolsAvailable },
        { name: 'Đang mượn', value: borrowedTools },
        { name: 'Bảo trì', value: Math.max(0, totalToolsQuantity - totalToolsAvailable - borrowedTools) },
      ];
      setPieData(pieChartData.filter(item => item.value > 0));

      const last7Days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        return {
            dateStr: d.toLocaleDateString('vi-VN'),
            dayName: d.toLocaleDateString('vi-VN', { weekday: 'short' }),
            fullDate: d.toISOString().split('T')[0]
        };
      });

      const chartData = last7Days.map(day => {
        const count = requests.filter(r => r.borrow_date.startsWith(day.fullDate)).length;
        return {
            name: day.dayName,
            requests: count
        };
      });

      setBarData(chartData);

    } catch (error) {
      console.error("Error fetching dashboard data:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
        <div className="flex h-[70vh] items-center justify-center">
            <div className="flex flex-col items-center gap-4">
              <Loader2 className="w-12 h-12 animate-spin text-indigo-600 opacity-20" />
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-300">Synchronizing system data...</p>
            </div>
        </div>
    );
  }

  return (
    <div className="space-y-8 animate-page-transition">
      <div className="flex justify-between items-end">
        <div>
           <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">Xin chào, Team V1! 👋</h1>
           <p className="text-sm font-bold text-slate-400 mt-1">Dưới đây là thống kê tài sản và hoạt động hôm nay.</p>
        </div>
        <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white rounded-2xl border border-slate-100 shadow-sm">
           <Activity className="w-4 h-4 text-emerald-500" />
           <span className="text-[10px] font-bold text-slate-600 uppercase tracking-widest">Hệ thống đang ổn định</span>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card className="vibrant-shadow border-none rounded-[2rem] p-8 group hover:scale-[1.02] transition-all">
          <div className="flex justify-between items-start mb-6">
            <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl group-hover:bg-indigo-600 group-hover:text-white transition-colors">
              <Package className="w-7 h-7" />
            </div>
            <ArrowUpRight className="w-5 h-5 text-slate-300" />
          </div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Tổng tài sản</p>
          <p className="text-4xl font-extrabold text-slate-900 tabular-nums">{stats.totalToolsQuantity}</p>
        </Card>

        <Card className="vibrant-shadow border-none rounded-[2rem] p-8 group hover:scale-[1.02] transition-all">
          <div className="flex justify-between items-start mb-6">
            <div className="p-4 bg-purple-50 text-purple-600 rounded-2xl group-hover:bg-purple-600 group-hover:text-white transition-colors">
              <ShoppingBag className="w-7 h-7" />
            </div>
            <ArrowUpRight className="w-5 h-5 text-slate-300" />
          </div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Đang mượn</p>
