interface HeaderProps {
  user: any;
  onMenuClick?: () => void;
}

interface NotificationItem {
  id: string;
  type: 'borrow' | 'overtime';
  title: string;
  message: string;
  time: string;
  status: 'pending' | 'approved' | 'rejected' | 'returned';
  isRead: boolean;
}

export const Header: React.FC<HeaderProps> = ({ user, onMenuClick }) => {
  const { theme, setTheme } = useContext(ThemeContext);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const isDefault = theme === 'default';

  const getDismissedIds = (): string[] => {
    const stored = localStorage.getItem(`dismissed_notifs_${user?.id}`);
    return stored ? JSON.parse(stored) : [];
  };

  const getSeenIds = (): string[] => {
    const stored = localStorage.getItem(`seen_notifs_${user?.id}`);
    return stored ? JSON.parse(stored) : [];
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchNotifications = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    try {
      const isAdmin = user.role === 'admin';
      const dismissedIds = getDismissedIds();
      const seenIds = getSeenIds();
      const notifs: NotificationItem[] = [];

      let borrowQuery = supabase.from('requests').select('*').order('borrow_date', { ascending: false }).limit(20);

      if (!isAdmin) {
        borrowQuery = borrowQuery.eq('user_id', user.id);
      }

      const { data: borrowData } = await borrowQuery;

      if (borrowData) {
        (borrowData as BorrowRequest[]).forEach(req => {
          let shouldNotify = false; 
          let title = ''; 
          let message = '';
          const uniqueId = `borrow-${req.id}-${req.status}`;

          if (dismissedIds.includes(uniqueId)) return;

          if (isAdmin) {
            if (req.status === 'pending') { 
              shouldNotify = true; 
              title = 'Đơn mượn mới'; 
              message = `${req.user_name} cần mượn ${req.tool_name}`; 
            }
          } else {
            if (req.user_id === user.id && req.status !== 'pending') { 
              shouldNotify = true; 
              title = 'Trạng thái yêu cầu'; 
              const statusText = req.status === 'approved' ? 'đã được DUYỆT' : req.status === 'rejected' ? 'bị TỪ CHỐI' : 'đã HOÀN TRẢ';
              message = `Mượn "${req.tool_name}" ${statusText}`; 
            }
          }

          if (shouldNotify) {
            notifs.push({ 
              id: uniqueId, 
              type: 'borrow', 
              title, 
              message, 
              time: req.status === 'returned' ? (req.returned_at || req.borrow_date) : req.borrow_date, 
              status: req.status, 
              isRead: seenIds.includes(uniqueId)
            });
          }
        });
      }

      const sortedNotifs = notifs.sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());
      setNotifications(sortedNotifs);

      const unread = sortedNotifs.filter(n => !seenIds.includes(n.id)).length;
      setUnreadCount(unread);
    } catch (error) { 
      console.error("Lỗi thông báo:", error); 
    } finally { 
      setLoading(false); 
    }
  }, [user]);

  useEffect(() => { 
    fetchNotifications(); 
    const handleRefresh = () => fetchNotifications();
    window.addEventListener('refresh-counts', handleRefresh);
    const interval = setInterval(fetchNotifications, 30000);
    return () => {
      window.removeEventListener('refresh-counts', handleRefresh);
      clearInterval(interval);
    };
  }, [fetchNotifications]);

  const handleBellClick = () => {
    setIsOpen(!isOpen);
    if (!isOpen) {
      const currentIds = notifications.map(n => n.id);
      const seenIds = Array.from(new Set([...getSeenIds(), ...currentIds]));
      localStorage.setItem(`seen_notifs_${user?.id}`, JSON.stringify(seenIds));
      setUnreadCount(0);
    }
  };

  const deleteNotification = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    const dismissedIds = [...getDismissedIds(), id];
    localStorage.setItem(`dismissed_notifs_${user?.id}`, JSON.stringify(dismissedIds));
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  return (
    <header className="h-20 px-6 md:px-10 flex items-center justify-between sticky top-0 z-30 transition-all duration-300 glass-card mx-6 my-4 rounded-[2rem] shadow-[0_8px_30px_rgb(0,0,0,0.04)]">
      <div className="flex items-center gap-4">
        <button onClick={onMenuClick} className="lg:hidden p-3 hover:bg-slate-100 rounded-2xl transition-colors">
          <Menu className="w-6 h-6 text-slate-600" />
        </button>

        <div className="hidden lg:flex items-center gap-1 bg-slate-100/80 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
           <button onClick={() => setTheme('default')} className={`p-2 rounded-xl transition-all ${theme === 'default' ? 'bg-white text-indigo-600 shadow-md scale-105' : 'text-slate-400 hover:text-slate-600'}`} title="Hiện đại"><Palette className="w-4 h-4" /></button>
           <button onClick={() => setTheme('noel')} className={`p-2 rounded-xl transition-all ${theme === 'noel' ? 'bg-white text-red-600 shadow-md scale-105' : 'text-slate-400 hover:text-slate-600'}`} title="Giáng sinh"><Snowflake className="w-4 h-4" /></button>
           <button onClick={() => setTheme('tet')} className={`p-2 rounded-xl transition-all ${theme === 'tet' ? 'bg-white text-orange-600 shadow-md scale-105' : 'text-slate-400 hover:text-slate-600'}`} title="Tết"><Gift className="w-4 h-4" /></button>
        </div>

        <div className="hidden sm:block ml-4">
          <p className="text-[10px] font-extrabold text-slate-300 uppercase tracking-[0.2em] leading-none mb-1">Thời gian hệ thống</p>
          <p className="text-[11px] font-bold text-slate-500 uppercase tracking-widest">
            {new Date().toLocaleDateString('vi-VN', { weekday: 'long', day: '2-digit', month: '2-digit' })}
          </p>
        </div>
      </div>

      <div className="flex items-center gap-4 md:gap-8">
        <div className="relative group hidden md:block">
           <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 group-focus-within:text-indigo-500 transition-colors" />
           <input type="text" placeholder="Tìm kiếm nhanh..." className="pl-12 pr-6 py-2.5 bg-slate-50/50 border border-slate-200 rounded-full text-xs font-bold focus:bg-white focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all w-64" />
        </div>

        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={handleBellClick} 
            className={`relative p-3 rounded-2xl transition-all duration-300 ${isOpen ? 'bg-indigo-50 text-indigo-600 shadow-inner' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-900'}`}
          >
            <Bell className="w-5 h-5" />
            {unreadCount > 0 && (
              <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-rose-500 rounded-full border-2 border-white animate-pulse"></span>
            )}
          </button>

          {isOpen && (
            <div className="absolute right-0 top-full mt-4 w-80 sm:w-96 bg-white rounded-[2.5rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.2)] border border-slate-100 overflow-hidden animate-zoom-in origin-top-right ring-1 ring-black/5">
              <div className="p-6 border-b border-slate-50 bg-slate-50/50 flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <h3 className="font-extrabold text-xs uppercase tracking-widest text-slate-900">Thông báo</h3>
                  <span className="bg-indigo-600 text-white text-[8px] font-black px-2 py-0.5 rounded-full uppercase">Live</span>
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); fetchNotifications(); }} 
                  className={`p-2 hover:bg-white rounded-xl transition-all ${loading ? 'animate-spin' : ''}`}
                >
                  <RefreshCw className="w-4 h-4 text-slate-400" />
                </button>
              </div>

              <div className="max-h-[450px] overflow-y-auto no-scrollbar bg-white p-2">
                {notifications.length === 0 ? (
                  <div className="py-20 text-center flex flex-col items-center gap-4 opacity-30">
                    <Bell className="w-10 h-10 text-slate-400" />
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Không có tin mới</p>
                  </div>
                ) : (
                  <ul className="space-y-1">
                    {notifications.map((n) => (
                      <li key={n.id} className="relative p-4 hover:bg-slate-50 rounded-[1.5rem] transition-all group">
                        <div className="flex justify-between items-start gap-4">
                          <div className={`w-10 h-10 rounded-xl shrink-0 flex items-center justify-center border ${n.status === 'pending' ? 'bg-amber-50 border-amber-100 text-amber-500' : 'bg-indigo-50 border-indigo-100 text-indigo-500'}`}>
                             {/* Added Timer to the imports to fix line 213 */}
                             {n.status === 'pending' ? <Timer className="w-5 h-5" /> : <Clock className="w-5 h-5" />}
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-xs font-extrabold text-slate-900 uppercase tracking-tight mb-1">{n.title}</p>
                            <p className="text-[11px] text-slate-500 font-medium leading-relaxed truncate">{n.message}</p>
                            <div className="flex items-center gap-2 mt-3 text-[9px] font-bold text-slate-300 uppercase">
                                {new Date(n.time).toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })} • {new Date(n.time).toLocaleDateString('vi-VN')}
                            </div>
                          </div>
                          <button 
                            onClick={(e) => deleteNotification(e, n.id)}
                            className="p-1.5 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all shrink-0"
                          >
                            <X className="w-4 h-4" />
                          </button>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              <div className="p-5 border-t border-slate-50 bg-slate-50/30 text-center">
                 <button 
                  onClick={() => setIsOpen(false)}
                  className="text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-indigo-600 transition-colors"
                 >
                   Đóng
                 </button>
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center gap-4 pl-4 border-l border-slate-100">
          <div className="text-right hidden md:block">
            <p className="text-sm font-extrabold text-slate-900 tracking-tight leading-none uppercase">{user?.name || 'V1 User'}</p>
            <p className="text-[10px] font-bold uppercase tracking-widest mt-1.5 text-indigo-600">{user?.role === 'admin' ? 'Administrator' : 'Personnel'}</p>
