          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-xl border-2 border-white transform hover:rotate-6 transition-transform cursor-pointer overflow-hidden bg-gradient-to-br from-indigo-500 to-purple-600`}>
