import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import { Card } from '../ui/Card';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Wrench, TrendingUp, Loader2, Package, ShoppingBag, BarChart as BarChartIcon, ArrowUpRight, Activity } from 'lucide-react';

const COLORS = ['#6366f1', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981', '#3b82f6'];

interface SafeChartContainerProps {
  children: React.ReactNode;
  height?: number;
  hasData?: boolean;
}

const SafeChartContainer: React.FC<SafeChartContainerProps> = ({ children, height = 300, hasData = true }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    if (!containerRef.current) return;

    const observer = new ResizeObserver((entries) => {
      if (!entries.length) return;
      const { width, height: contentHeight } = entries[0].contentRect;
      if (width > 0) {
        setDimensions({ width, height: contentHeight || height });
      }
    });

    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [height]);

  if (!hasData) {
    return (
      <div style={{ height }} className="w-full flex flex-col items-center justify-center bg-slate-50/50 rounded-[1.5rem] border-2 border-dashed border-slate-100">
         <div className="p-4 bg-white rounded-2xl shadow-sm mb-3">
            <BarChartIcon className="w-6 h-6 text-slate-200" />
         </div>
         <span className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Không có dữ liệu</span>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef} 
      style={{ 
        height: `${height}px`, 
        width: '100%', 
        position: 'relative',
        minWidth: '0px'
      }} 
      className="overflow-hidden" 
    >
      {isMounted && dimensions.width > 0 ? (
        <ResponsiveContainer width="100%" height="100%">
          {children as React.ReactElement}
        </ResponsiveContainer>
      ) : (
        <div className="w-full h-full flex flex-col items-center justify-center bg-slate-50/20 rounded-2xl">
           <Loader2 className="w-5 h-5 text-indigo-500 animate-spin mb-2" />
        </div>
      )}
    </div>
  );
};

export const DashboardStats: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalToolsQuantity: 0,
    totalToolsAvailable: 0,
    borrowedTools: 0,
    pendingRequests: 0,
  });
  const [barData, setBarData] = useState<any[]>([]);
  const [pieData, setPieData] = useState<any[]>([]);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [toolsRes, requestsRes] = await Promise.all([
        supabase.from('tools').select('quantity, available, status'),
        supabase.from('requests').select('status, borrow_date')
      ]);

      const tools = toolsRes.data || [];
      const requests = requestsRes.data || [];

      const totalToolsQuantity = tools.reduce((sum, tool) => sum + (tool.quantity || 0), 0);
      const totalToolsAvailable = tools.reduce((sum, tool) => sum + (tool.status === 'active' ? (tool.available || 0) : 0), 0);
      const borrowedTools = requests.filter(r => r.status === 'approved').length;
      const pendingRequests = requests.filter(r => r.status === 'pending').length;

      setStats({
        totalToolsQuantity,
        totalToolsAvailable,
        borrowedTools,
        pendingRequests
      });

      const pieChartData = [
        { name: 'Sẵn có', value: totalToolsAvailable },
        { name: 'Đang mượn', value: borrowedTools },
        { name: 'Bảo trì', value: Math.max(0, totalToolsQuantity - totalToolsAvailable - borrowedTools) },
      ];
      setPieData(pieChartData.filter(item => item.value > 0));

      const last7Days = Array.from({ length: 7 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() - (6 - i));
        return {
            dateStr: d.toLocaleDateString('vi-VN'),
            dayName: d.toLocaleDateString('vi-VN', { weekday: 'short' }),
            fullDate: d.toISOString().split('T')[0]
        };
      });

      const chartData = last7Days.map(day => {
        const count = requests.filter(r => r.borrow_date.startsWith(day.fullDate)).length;
        return {
            name: day.dayName,
            requests: count
        };
      });

      setBarData(chartData);

    } catch (error) {
      console.error("Error fetching dashboard data:", error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
        <div className="flex h-[60vh] items-center justify-center">
            <Loader2 className="w-10 h-10 animate-spin text-indigo-600 opacity-20" />
        </div>
    );
  }

  return (
    <div className="space-y-6 animate-page-transition">
      <div className="flex justify-between items-end mb-2">
        <div>
           <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">Xin chào, Team V1!</h1>
           <p className="text-xs font-bold text-slate-500 mt-1 uppercase tracking-widest opacity-80">Tổng quan hoạt động hệ thống</p>
        </div>
        <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-white rounded-xl border border-slate-200 shadow-sm">
           <Activity className="w-3.5 h-3.5 text-emerald-500" />
           <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Ổn định</span>
        </div>
      </div>

      {/* Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
        {[
          { label: 'Tổng tài sản', val: stats.totalToolsQuantity, icon: Package, color: 'indigo' },
          { label: 'Đang mượn', val: stats.borrowedTools, icon: ShoppingBag, color: 'purple' },
          { label: 'Khả dụng', val: stats.totalToolsAvailable, icon: Wrench, color: 'emerald' },
          { label: 'Yêu cầu mới', val: stats.pendingRequests, icon: TrendingUp, color: 'amber' }
        ].map((c, i) => (
          <Card key={i} className="vibrant-shadow border-none rounded-[1.5rem] p-6 group hover:translate-y-[-2px] transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className={`p-3 bg-${c.color}-50 text-${c.color}-600 rounded-xl group-hover:bg-${c.color}-600 group-hover:text-white transition-colors`}>
                <c.icon className="w-6 h-6" />
              </div>
              <ArrowUpRight className="w-4 h-4 text-slate-300" />
            </div>
            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5">{c.label}</p>
            <p className="text-2xl font-extrabold text-slate-900 tabular-nums">{c.val}</p>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
