                    <p className={`font-black text-sm md:text-lg uppercase tracking-tighter text-gray-800 leading-tight italic transition-colors ${isTet ? 'group-hover:text-red-700' : 'group-hover:text-indigo-700'}`}>{req.tool_name}</p>
